local function assertEqual(actual, expected, label)
    if actual ~= expected then
        error(label .. " (expected " .. tostring(expected) .. ", got " .. tostring(actual) .. ")")
    end
end

local function assertTrue(value, label)
    if not value then
        error(label)
    end
end

local function hasValue(items, value)
    for _, item in ipairs(items or {}) do
        if item == value then
            return true
        end
    end
    return false
end

function getActionSequencerPopup(action, result, predicate)
    local actionSequencer = require('ui.action_sequencer')
    local sequencer = actionSequencer.createActionSequencer({ eventBus = events.createEventBus() })
    sequencer:queueActionSequence({
        action = action,
        result = result,
    })
    for _, step in ipairs(sequencer.currentSequence or {}) do
        if step.type == actionSequencer.STEP_TYPES.TEXT_POPUP and step.data and
           (not predicate or predicate(step.data)) then
            return step.data
        end
    end
    return nil
end

local function countEventListeners(bus)
    local count = 0
    for _, listeners in pairs(bus.listeners or {}) do
        count = count + #listeners
    end
    return count
end

local function checkEventBusMutationSafeDispatch()
    local bus = events.createEventBus()
    local calls = {}
    local unsubscribeFirst

    unsubscribeFirst = bus:on("mutation_test", function()
        calls[#calls + 1] = "first"
        unsubscribeFirst()
    end)
    bus:on("mutation_test", function()
        calls[#calls + 1] = "second"
    end)

    bus:emit("mutation_test", {})
    assertEqual(table.concat(calls, ","), "first,second",
        "self-unsubscribe during emit should not skip the following listener")

    calls = {}
    bus:emit("mutation_test", {})
    assertEqual(table.concat(calls, ","), "second",
        "unsubscribed listeners should stay removed after mutation-safe emit")

    local onceCalls = 0
    local persistentCalls = 0
    bus:once("once_test", function()
        onceCalls = onceCalls + 1
    end)
    bus:on("once_test", function()
        persistentCalls = persistentCalls + 1
    end)

    bus:emit("once_test", {})
    bus:emit("once_test", {})
    assertEqual(onceCalls, 1, "once listener should fire only once")
    assertEqual(persistentCalls, 2, "once unsubscribe should not skip persistent listeners")

    local clearCalls = {}
    bus:on("clear_test", function()
        clearCalls[#clearCalls + 1] = "clearer"
        bus:clear("clear_test")
    end)
    bus:on("clear_test", function()
        clearCalls[#clearCalls + 1] = "stale"
    end)

    bus:emit("clear_test", {})
    assertEqual(table.concat(clearCalls, ","), "clearer",
        "clearing during emit should deactivate remaining listeners")
    assertEqual(bus:listenerCount("clear_test"), 0, "clear should remove active listeners")
end

local function major(value)
    return {
        name = "Major " .. tostring(value),
        value = value,
        is_major = true,
    }
end

local function checkDoomClassification()
    for _, card in ipairs(constants.MajorArcana) do
        if card.value >= 1 and card.value <= 14 then
            assertEqual(deck.getDoomType(card), "lesser", "Major " .. card.value .. " should be lesser doom")
            assertTrue(deck.isLesserDoom(card), "Major " .. card.value .. " should satisfy isLesserDoom")
            assertTrue(not deck.isGreaterDoom(card), "Major " .. card.value .. " should not satisfy isGreaterDoom")
        elseif card.value >= 15 and card.value <= 21 then
            assertEqual(deck.getDoomType(card), "greater", "Major " .. card.value .. " should be greater doom")
            assertTrue(deck.isGreaterDoom(card), "Major " .. card.value .. " should satisfy isGreaterDoom")
            assertTrue(not deck.isLesserDoom(card), "Major " .. card.value .. " should not satisfy isLesserDoom")
        end
    end

    local fool = nil
    for _, card in ipairs(constants.MinorArcana) do
        if card.name == "The Fool" then
            fool = card
            break
        end
    end

    assertTrue(fool ~= nil, "The Fool must exist in MinorArcana")
    assertEqual(deck.getDoomType(fool), nil, "The Fool should not be classified as doom")

    local shortDeck = deck.createDeck({})
    shortDeck.draw_pile = {
        { name = "Draw Bottom", value = 1, suit = constants.SUITS.SWORDS },
        { name = "Draw Top", value = 2, suit = constants.SUITS.CUPS },
    }
    shortDeck.discard_pile = {
        { name = "Discard Bottom", value = 3, suit = constants.SUITS.PENTACLES },
        { name = "Discard Top", value = 4, suit = constants.SUITS.WANDS },
    }

    local drawn = {}
    for _ = 1, 4 do
        drawn[#drawn + 1] = shortDeck:draw()
    end

    assertEqual(#drawn, 4, "out-of-cards draws should continue after reshuffling the discard pile")
    assertEqual(drawn[1].name, "Draw Top", "draw should consume the current draw pile before reshuffling")
    assertEqual(shortDeck:discardPileCount(), 0, "out-of-cards reshuffle should move discard pile into draw pile")
    assertTrue(shortDeck:draw() == nil, "draw should return nil only after draw and discard piles are exhausted")
end

local function checkGroupTestResolution()
    local great = fate_resolver.resolveTest(4, constants.SUITS.SWORDS, {
        name = "X of Swords",
        value = 10,
        suit = constants.SUITS.SWORDS,
    })
    local success = fate_resolver.resolveTest(4, constants.SUITS.SWORDS, {
        name = "X of Cups",
        value = 10,
        suit = constants.SUITS.CUPS,
    })
    local failure = fate_resolver.resolveTest(2, constants.SUITS.SWORDS, {
        name = "V of Cups",
        value = 5,
        suit = constants.SUITS.CUPS,
    })
    local greatFailure = fate_resolver.resolvePush(failure.total, failure.cards, {
        name = "III of Wands",
        value = 3,
        suit = constants.SUITS.WANDS,
    })

    assertEqual(fate_resolver.getGroupTestHits(great), 2, "group tests should score great success as 2 hits")
    assertEqual(fate_resolver.getGroupTestHits(success), 1, "group tests should score success as 1 hit")
    assertEqual(fate_resolver.getGroupTestHits(failure), 0, "group tests should score failure as 0 hits")
    assertEqual(fate_resolver.getGroupTestHits(greatFailure), -1,
        "group tests should score great failure as -1 hit")

    assertEqual(fate_resolver.resolveGroupTest({ success, success }).result,
        fate_resolver.GROUP_RESULTS.SUCCESS, "2 group-test hits should succeed for the group")
    assertEqual(fate_resolver.resolveGroupTest({ success, failure }).result,
        fate_resolver.GROUP_RESULTS.TIGHT_SPOT, "1 group-test hit should put the group in a tight spot")
    assertEqual(fate_resolver.resolveGroupTest({ failure, failure }).result,
        fate_resolver.GROUP_RESULTS.FAILURE, "0 group-test hits should fail for the group")
    assertEqual(fate_resolver.resolveGroupTest({ greatFailure, failure }).result,
        fate_resolver.GROUP_RESULTS.DISASTER, "negative group-test hits should be a disaster")

    local aided, err = fate_resolver.prepareAidedTest({
        lead = { id = "pc_lock_lead" },
        helper = { id = "pc_lock_helper" },
    })
    assertTrue(aided ~= nil, err or "aided Test Fate setup should succeed")
    assertTrue(aided.favor == true, "meaningful aid should grant favor to the lead test")
    assertTrue(aided.leadChoosesPush == true, "the lead adventurer should decide whether to push fate")
    assertEqual(aided.pushOwnerId, "pc_lock_lead", "aided tests should record the push decision owner")
    assertEqual(aided.affectedActors[2].actorId, "pc_lock_helper",
        "aided tests should record helpers as consequence targets")

    local aidedFailure = fate_resolver.resolveTest(1, constants.SUITS.PENTACLES, {
        name = "III of Wands",
        value = 3,
        suit = constants.SUITS.WANDS,
    }, aided.favor)
    local shared = fate_resolver.sharedAidedConsequences(aided, aidedFailure)
    assertEqual(#shared, 2, "aided Test Fate consequences should apply to lead and helper")
    assertEqual(shared[1].result, fate_resolver.RESULTS.FAILURE,
        "aided Test Fate consequences should preserve the test result")
    assertEqual(shared[2].actorId, "pc_lock_helper",
        "aided Test Fate consequences should affect the helper equally")

    local retreatResolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local function makeRetreatParticipant(id, pentacles)
        return base_entity.createEntity({
            id = id,
            name = id,
            isPC = true,
            pentacles = pentacles or 0,
        })
    end
    local function resolveRetreat(opts)
        opts = opts or {}
        local participants = opts.participants or {
            makeRetreatParticipant("pc_retreat_fast", 4),
            makeRetreatParticipant("pc_retreat_slow", 0),
        }
        local ended = nil
        local controller = {
            pcs = participants,
            endChallenge = function(_, outcome, data)
                ended = {
                    outcome = outcome,
                    data = data,
                }
            end,
        }
        local action = {
            actor = participants[1],
            card = major(5),
            type = action_resolver.ACTION_TYPES.FLEE,
            participants = participants,
            challengeController = opts.challengeController or controller,
            pursuit = opts.pursuit,
            enemyMobility = opts.enemyMobility,
            enemyTiedToLair = opts.enemyTiedToLair,
            enemyWillNotPursue = opts.enemyWillNotPursue,
            pursuitReason = opts.pursuitReason,
            retreatPursuitReason = opts.retreatPursuitReason,
            retreatPursuitSource = opts.retreatPursuitSource,
            retreatAdjudication = opts.retreatAdjudication,
            retreatOption = opts.retreatOption,
            retreatOptionId = opts.retreatOptionId,
            testResults = opts.testResults,
            retreatTestCards = opts.retreatTestCards,
            cleverTactics = opts.cleverTactics,
            retreatFavorTarget = opts.retreatFavorTarget,
            complication = opts.complication,
            retreatComplication = opts.retreatComplication,
            escapeComplication = opts.escapeComplication,
            retreatComplicationTarget = opts.retreatComplicationTarget,
            endChallenge = opts.endChallenge,
        }
        return retreatResolver:resolve(action), participants, ended
    end

    local fastRetreat, fastParticipants = resolveRetreat({
        enemyMobility = "fast",
        pursuitReason = "The dragon is airborne over open fields.",
    })
    assertTrue(not fastRetreat.success, "fast or magical pursuers should block retreat")
    assertTrue(hasValue(fastRetreat.effects, "retreat_impossible"),
        "blocked retreat should report impossible pursuit")
    assertTrue(not fastParticipants[1].retreated, "blocked retreat should not mark PCs fled")
    assertEqual(fastRetreat.retreatPursuit.branch, "impossible",
        "blocked retreat should preserve the impossible-pursuit adjudication branch")
    assertEqual(fastRetreat.retreatPursuit.reason, "The dragon is airborne over open fields.",
        "blocked retreat should preserve scene-specific pursuit adjudication copy")

    local noPursuit, noPursuitParticipants, noPursuitEnd = resolveRetreat({
        enemyTiedToLair = true,
        retreatOption = {
            id = "retreat_no_pursuit",
            name = "No Pursuit",
            description = "The fire elemental is bound to the hearth.",
        },
        retreatOptionId = "retreat_no_pursuit",
    })
    assertTrue(noPursuit.success, "tied-to-lair enemies should allow clean retreat")
    assertTrue(hasValue(noPursuit.effects, "retreat_no_pursuit"), "no-pursuit retreat should be explicit")
    assertTrue(noPursuitParticipants[1].retreated and noPursuitParticipants[2].retreated,
        "clean retreat should mark the guild as fled")
    assertEqual(noPursuitEnd and noPursuitEnd.outcome, "fled",
        "successful retreat should end the Challenge as fled")
    assertEqual(noPursuit.retreatPursuit.branch, "no_pursuit",
        "no-pursuit retreat should preserve the adjudication branch")
    assertEqual(noPursuit.retreatPursuit.reason, "The fire elemental is bound to the hearth.",
        "no-pursuit retreat should preserve Command Board pursuit framing copy")
    assertEqual(noPursuit.retreatPursuit.optionId, "retreat_no_pursuit",
        "no-pursuit retreat should preserve the selected framing option id")

    local pendingRetreat = resolveRetreat({
        pursuit = "equivalent",
        retreatAdjudication = {
            description = "The rubble-strewn hall gives the guild a chance to shake pursuit.",
            source = "scene",
        },
    })
    assertTrue(not pendingRetreat.success and pendingRetreat.needsGroupTest,
        "equivalent pursuit retreat should request the Pentacles group test")
    assertEqual(pendingRetreat.groupTestAttribute, "pentacles",
        "retreat group test should use Pentacles")
    assertEqual(pendingRetreat.retreatPursuit.branch, "equivalent",
        "equivalent pursuit should preserve the group-test adjudication branch")
    assertEqual(pendingRetreat.retreatPursuit.source, "scene",
        "equivalent pursuit should preserve authored adjudication source")
    assertEqual(pendingRetreat.groupTestRequest.testers[1].actorId, "pc_retreat_fast",
        "retreat group test should identify the highest-Pentacles adventurer")
    assertEqual(pendingRetreat.groupTestRequest.testers[2].actorId, "pc_retreat_slow",
        "retreat group test should identify the lowest-Pentacles adventurer")

    local pendingTacticRetreat = resolveRetreat({
        pursuit = "equivalent",
        cleverTactics = { "push over a bookcase" },
    })
    assertTrue(pendingTacticRetreat.groupTestRequest.favorChoiceRequired,
        "clever retreat tactics should require choosing which group test gets favor")
    assertEqual(pendingTacticRetreat.groupTestRequest.cleverTactics[1].description, "push over a bookcase",
        "pending retreat should preserve clever tactic descriptions for the group-test prompt")

    local cleanRetreat, _, cleanEnd = resolveRetreat({
        testResults = { success, success },
    })
    assertTrue(cleanRetreat.success and cleanRetreat.escaped, "2 group-test hits should escape cleanly")
    assertEqual(cleanRetreat.groupTest.hits, 2, "clean retreat should preserve group-test hits")
    assertTrue(hasValue(cleanRetreat.effects, "retreat_clean"), "clean retreat should be reported")
    assertEqual(cleanEnd and cleanEnd.outcome, "fled", "clean group-test retreat should end the Challenge")

    local complicatedRetreat = resolveRetreat({
        testResults = { success, failure },
        endChallenge = false,
    })
    assertTrue(complicatedRetreat.success and complicatedRetreat.complication,
        "1 group-test hit should escape with a GM complication")
    assertTrue(hasValue(complicatedRetreat.effects, "retreat_complication"),
        "complicated retreat should be reported")
    assertEqual(complicatedRetreat.retreatComplication.id, "gm_complication",
        "generic one-hit retreats should preserve a GM complication metadata record")

    local lastInLine = makeRetreatParticipant("pc_retreat_last_in_line", 0)
    lastInLine.marchingOrder = 2
    local firstInLine = makeRetreatParticipant("pc_retreat_first_in_line", 4)
    firstInLine.marchingOrder = 1
    local authoredComplicatedRetreat = resolveRetreat({
        participants = { firstInLine, lastInLine },
        testResults = { success, failure },
        complication = {
            id = "caught_last_marching_order",
        },
        endChallenge = false,
    })
    assertEqual(authoredComplicatedRetreat.retreatComplication.id, "caught_last_marching_order",
        "authored retreat complication should preserve the selected rulebook example")
    assertTrue(authoredComplicatedRetreat.retreatComplication.target == lastInLine,
        "last-rank retreat complication should select the last marching-order adventurer")
    assertEqual(authoredComplicatedRetreat.retreatComplication.targetRole, "last_in_marching_order",
        "last-rank retreat complication should label the target role")

    local routeTrap = { id = "collapsing_stairs", name = "Collapsing Stairs" }
    local routeComplicatedRetreat = resolveRetreat({
        testResults = { success, failure },
        complication = {
            id = "dangerous_escape_route",
            trap = routeTrap,
        },
        endChallenge = false,
    })
    assertTrue(routeComplicatedRetreat.retreatComplication.routeDangerous,
        "dangerous-route retreat complication should flag the escape route as dangerous")
    assertTrue(routeComplicatedRetreat.retreatComplication.trap == routeTrap,
        "dangerous-route retreat complication should preserve the authored trap")

    local cleverRetreat = resolveRetreat({
        retreatTestCards = {
            highest = { name = "VII of Cups", value = 7, suit = constants.SUITS.CUPS },
            lowest = { name = "V of Cups", value = 5, suit = constants.SUITS.CUPS },
        },
        cleverTactics = {
            { description = "push over a bookcase", actorId = "pc_retreat_fast" },
        },
        retreatFavorTarget = "highest",
        endChallenge = false,
    })
    assertTrue(cleverRetreat.success and cleverRetreat.complication,
        "clever-tactic favor should apply to the selected retreat group test")
    assertEqual(cleverRetreat.groupTest.hits, 1,
        "clever-tactic favor should turn the selected retreat test into one group-test hit")
    assertTrue(cleverRetreat.groupTestRequest.testers[1].favor,
        "retreat group-test metadata should mark the favored tester")

    local corneredRetreat, corneredParticipants, corneredEnd = resolveRetreat({
        testResults = { failure, failure },
    })
    assertTrue(not corneredRetreat.success and corneredRetreat.cornered,
        "0 group-test hits should leave the guild cornered")
    assertTrue(hasValue(corneredRetreat.effects, "retreat_cornered"),
        "cornered retreat should be reported")
    assertTrue(not corneredParticipants[1].retreated, "failed retreat should not mark PCs fled")
    assertTrue(corneredEnd == nil, "failed retreat should not end the Challenge")

    local actionSequencer = require('ui.action_sequencer')
    local function getRetreatPopup(result)
        local sequencer = actionSequencer.createActionSequencer({ eventBus = events.createEventBus() })
        sequencer:queueActionSequence({
            action = {
                type = action_resolver.ACTION_TYPES.FLEE,
            },
            result = result,
        })
        for _, step in ipairs(sequencer.currentSequence or {}) do
            if step.type == actionSequencer.STEP_TYPES.TEXT_POPUP and
               step.data and step.data.retreatOutcome then
                return step.data
            end
        end
        return nil
    end

    local impossiblePopup = getRetreatPopup(fastRetreat)
    assertTrue(impossiblePopup ~= nil, "impossible retreat should queue a visible retreat popup")
    assertEqual(impossiblePopup.title, "Retreat Impossible",
        "impossible retreat popup should label the blocked pursuit branch")
    assertTrue(impossiblePopup.gmFacing,
        "impossible retreat popup should be flagged for GM-facing pursuit presentation")

    local noPursuitPopup = getRetreatPopup(noPursuit)
    assertTrue(noPursuitPopup ~= nil, "no-pursuit retreat should queue a visible retreat popup")
    assertEqual(noPursuitPopup.retreatOutcome, "no_pursuit",
        "no-pursuit retreat popup should preserve the clean non-pursuit branch")
    assertEqual(noPursuitPopup.retreatPursuit.reason, "The fire elemental is bound to the hearth.",
        "retreat popup should carry scene-specific pursuit adjudication copy")
    assertTrue(not noPursuitPopup.gmFacing,
        "no-pursuit retreat popup should not require GM complication framing")

    local complicationPopup = getRetreatPopup(complicatedRetreat)
    assertTrue(complicationPopup ~= nil, "complicated retreat should queue a visible retreat popup")
    assertEqual(complicationPopup.title, "Retreat Complication",
        "complicated retreat popup should label the GM complication branch")
    assertEqual(complicationPopup.groupTestHits, 1,
        "complicated retreat popup should carry the one-hit group-test result")
    assertTrue(complicationPopup.gmFacing,
        "complicated retreat popup should be flagged for GM-facing complication presentation")

    local authoredComplicationPopup = getRetreatPopup(authoredComplicatedRetreat)
    assertEqual(authoredComplicationPopup.retreatComplication.id, "caught_last_marching_order",
        "retreat complication popup should carry the authored complication")
    assertEqual(authoredComplicationPopup.complicationTargetId, lastInLine.id,
        "retreat complication popup should identify the authored target")

    local corneredPopup = getRetreatPopup(corneredRetreat)
    assertTrue(corneredPopup ~= nil, "cornered retreat should queue a visible retreat popup")
    assertEqual(corneredPopup.title, "Retreat Cornered",
        "cornered retreat popup should label the failed escape branch")
    assertTrue(corneredPopup.gmFacing,
        "cornered retreat popup should be flagged for GM-facing follow-up presentation")

    local controllerBus = events.createEventBus()
    local controllerResolver = action_resolver.createActionResolver({
        eventBus = controllerBus,
    })
    local controller = challenge_controller.createChallengeController({
        eventBus = controllerBus,
        actionResolver = controllerResolver,
    })
    controllerResolver.challengeController = controller
    local controllerRetreatEnd = nil
    controllerBus:on(events.EVENTS.CHALLENGE_END, function(data)
        controllerRetreatEnd = data
    end)
    local controllerRunner = makeRetreatParticipant("pc_controller_retreat_a", 4)
    local controllerStraggler = makeRetreatParticipant("pc_controller_retreat_b", 0)
    local controllerPursuer = base_entity.createEntity({
        id = "npc_controller_retreat_pursuer",
        name = "Controller Retreat Pursuer",
        isPC = false,
    })
    controller.pcs = { controllerRunner, controllerStraggler }
    controller.npcs = { controllerPursuer }
    controller.allCombatants = { controllerRunner, controllerStraggler, controllerPursuer }
    local controllerSuccess, controllerResult = controller:attemptFlee(controllerRunner, {
        enemyTiedToLair = true,
    })
    assertTrue(controllerSuccess and controllerResult.success,
        "ChallengeController flee helper should delegate no-pursuit retreat to the resolver")
    assertTrue(controllerRunner.retreated and controllerStraggler.retreated,
        "ChallengeController retreat should mark all participants as fled")
    assertEqual(controllerRetreatEnd and controllerRetreatEnd.outcome, "fled",
        "ChallengeController retreat should end the Challenge through the resolver")

    local pendingController = challenge_controller.createChallengeController({
        eventBus = events.createEventBus(),
        actionResolver = controllerResolver,
    })
    local pendingRunner = makeRetreatParticipant("pc_controller_pending_retreat", 3)
    pendingController.pcs = { pendingRunner }
    pendingController.allCombatants = { pendingRunner, controllerPursuer }
    local pendingSuccess, pendingResult = pendingController:attemptFlee(pendingRunner, {
        pursuit = "equivalent",
    })
    assertTrue(not pendingSuccess and pendingResult.needsGroupTest,
        "ChallengeController flee helper should preserve pending group-test retreats")
    assertTrue(pendingController.pendingRetreat ~= nil,
        "pending retreat details should remain available for UI test collection")

    local promptBus = events.createEventBus()
    local promptResolver = action_resolver.createActionResolver({
        eventBus = promptBus,
    })
    local promptController = challenge_controller.createChallengeController({
        eventBus = promptBus,
        actionResolver = promptResolver,
    })
    promptResolver.challengeController = promptController
    local promptHigh = makeRetreatParticipant("pc_retreat_prompt_high", 4)
    promptHigh.name = "Retreat Prompt High"
    local promptLow = makeRetreatParticipant("pc_retreat_prompt_low", 0)
    promptLow.name = "Retreat Prompt Low"
    local promptPursuer = base_entity.createEntity({
        id = "npc_retreat_prompt_pursuer",
        name = "Retreat Prompt Pursuer",
        isPC = false,
    })
    promptController.state = challenge_controller.STATES.AWAITING_ACTION
    promptController.activeEntity = promptHigh
    promptController.currentRound = 1
    promptController.currentCount = 5
    promptController.pcs = { promptHigh, promptLow }
    promptController.npcs = { promptPursuer }
    promptController.allCombatants = { promptHigh, promptLow, promptPursuer }

    local promptDeck = {
        discard = function(self, card)
            self.discarded = self.discarded or {}
            self.discarded[#self.discarded + 1] = card
        end,
    }
    local promptHand = player_hand.createPlayerHand({
        eventBus = promptBus,
        playerDeck = promptDeck,
        guild = { promptHigh, promptLow },
    })
    local highCard = { name = "Ten of Cups", value = 10, suit = constants.SUITS.CUPS }
    local lowCard = { name = "King of Cups", value = 14, suit = constants.SUITS.CUPS }
    promptHand.hands[promptHigh.id] = { cards = { highCard } }
    promptHand.hands[promptLow.id] = { cards = { lowCard } }

    local promptInput = challenge_input_controller.createChallengeInputController({
        eventBus = promptBus,
        gameState = {
            challengeController = promptController,
            playerHand = promptHand,
            guild = { promptHigh, promptLow },
        },
    })
    promptInput:init()
    local promptOverlay = require('ui.challenge_overlay').createChallengeOverlay({
        gameState = {
            challengeController = promptController,
            playerHand = promptHand,
        },
        inputState = promptInput:getState(),
    })

    local promptRetreatResolved = nil
    promptBus:on(events.EVENTS.CHALLENGE_ACTION, function(action)
        local result = promptResolver:resolve(action)
        if result and result.needsGroupTest then
            promptController.pendingRetreat = action
            promptBus:emit(events.EVENTS.REQUEST_RETREAT_GROUP_TEST, {
                actor = action.actor,
                action = action,
                result = result,
                request = result.groupTestRequest,
            })
            return
        end
        promptRetreatResolved = result
    end)
    promptBus:on(events.EVENTS.RETREAT_GROUP_TEST_COMPLETE, function(data)
        local action = promptController.pendingRetreat
        action.retreatTestCards = data.retreatTestCards
        action.groupTestCards = data.retreatTestCards
        action.retreatFavorTarget = data.retreatFavorTarget
        promptRetreatResolved = promptResolver:resolve(action)
        promptController.pendingRetreat = nil
    end)

    local promptAction = {
        actor = promptHigh,
        card = highCard,
        type = action_resolver.ACTION_TYPES.FLEE,
        challengeController = promptController,
        participants = { promptHigh, promptLow },
        pursuit = "equivalent",
        retreatTestCards = {
            [promptHigh.id] = highCard,
        },
    }
    promptController:submitAction(promptAction)
    assertTrue(promptInput:getState().pendingRetreatGroupTest ~= nil,
        "retreat group-test prompt should open when pursuit requires cards")
    assertEqual(promptInput:getState().retreatTestIndex, 2,
        "retreat group-test prompt should skip a tester whose initial Flee card is already recorded")
    local retreatPrompt = promptOverlay:getFooterPrompt(promptController:getState(), promptController:getActiveEntity())
    assertTrue(retreatPrompt and retreatPrompt:find("Retreat", 1, true) and
        retreatPrompt:find("Retreat Prompt Low", 1, true),
        "Challenge HUD should ask the missing retreat tester for a card")
    promptInput:handleChallengeInput("q")
    assertTrue(promptRetreatResolved and promptRetreatResolved.success,
        "retreat prompt should resolve once the missing group-test card is supplied")
    assertEqual(promptRetreatResolved.groupTest.hits, 2,
        "retreat prompt should use both supplied Pentacles cards for the group test")
    assertEqual(#promptHand:getHand(promptLow), 0,
        "retreat prompt should discard the played group-test card")

    promptHand.hands[promptHigh.id] = { cards = { highCard } }
    local favorLowCard = { name = "Queen of Cups", value = 13, suit = constants.SUITS.CUPS }
    promptHand.hands[promptLow.id] = { cards = { favorLowCard } }
    promptRetreatResolved = nil
    promptController.state = challenge_controller.STATES.AWAITING_ACTION
    promptController.activeEntity = promptHigh
    local tacticPromptAction = {
        actor = promptHigh,
        card = highCard,
        type = action_resolver.ACTION_TYPES.FLEE,
        challengeController = promptController,
        participants = { promptHigh, promptLow },
        pursuit = "equivalent",
        cleverTactics = { "slam the gate" },
        retreatTestCards = {
            [promptHigh.id] = highCard,
        },
    }
    promptController:submitAction(tacticPromptAction)
    assertTrue(promptInput:getState().awaitingRetreatFavorChoice,
        "retreat prompt should ask which tester receives clever-tactic favor")
    local favorPrompt = promptOverlay:getFooterPrompt(promptController:getState(), promptController:getActiveEntity())
    assertTrue(favorPrompt and favorPrompt:find("favor", 1, true),
        "Challenge HUD should label the clever-tactic favor choice")
    promptInput:handleChallengeInput("2")
    assertEqual(promptInput:getState().retreatFavorTarget, "lowest",
        "retreat prompt should store the selected tester as the clever-tactic favor target")
    assertEqual(promptInput:getState().retreatTestIndex, 2,
        "retreat prompt should continue to the missing tester after choosing favor")
    promptInput:handleChallengeInput("q")
    assertTrue(promptRetreatResolved and promptRetreatResolved.success,
        "retreat prompt should resolve after favor selection and the missing group-test card")
    assertTrue(promptRetreatResolved.groupTestRequest.testers[2].favor,
        "retreat prompt should apply selected clever-tactic favor to the requested tester")

    local previousLove = love
    love = {
        graphics = {
            getDimensions = function()
                return 1024, 768
            end,
        },
    }
    local boardBus = events.createEventBus()
    local retreatBoard = command_board.createCommandBoard({
        eventBus = boardBus,
        challengeController = promptController,
    })
    retreatBoard:init()
    local emittedRetreatAction = nil
    boardBus:on("action_selected", function(data)
        emittedRetreatAction = data
    end)
    retreatBoard:show({ name = "Five of Swords", value = 5, suit = constants.SUITS.SWORDS }, promptHigh, true)
    local fleeButton = nil
    for _, button in ipairs(retreatBoard.buttons) do
        if button.action and button.action.id == "flee" then
            fleeButton = button
            break
        end
    end
    assertTrue(fleeButton ~= nil, "Command Board should expose Flee as a Challenge action")
    retreatBoard:mousepressed(fleeButton.x + 1, fleeButton.y + 1, 1)
    assertEqual(retreatBoard.mode, "retreat_option",
        "Flee should open the retreat-framing picker before submission")
    local cleverButton = nil
    for _, button in ipairs(retreatBoard.buttons) do
        if button.action and button.action.retreatOptionId == "retreat_clever" then
            cleverButton = button
            break
        end
    end
    assertTrue(cleverButton ~= nil, "retreat picker should offer a clever-tactic branch")
    retreatBoard:mousepressed(cleverButton.x + 1, cleverButton.y + 1, 1)
    assertEqual(retreatBoard.mode, "retreat_text",
        "clever retreat branch should ask for the tactic description")
    retreatBoard:textinput("push over a bookcase")
    retreatBoard:keypressed("return")
    local cleverRetreatAction = emittedRetreatAction
    emittedRetreatAction = nil

    retreatBoard:show({ name = "Six of Swords", value = 6, suit = constants.SUITS.SWORDS }, promptHigh, true)
    fleeButton = nil
    for _, button in ipairs(retreatBoard.buttons) do
        if button.action and button.action.id == "flee" then
            fleeButton = button
            break
        end
    end
    assertTrue(fleeButton ~= nil, "Command Board should keep Flee available after the retreat picker closes")
    retreatBoard:mousepressed(fleeButton.x + 1, fleeButton.y + 1, 1)
    local noPursuitButton = nil
    for _, button in ipairs(retreatBoard.buttons) do
        if button.action and button.action.retreatOptionId == "retreat_no_pursuit" then
            noPursuitButton = button
            break
        end
    end
    assertTrue(noPursuitButton ~= nil, "retreat picker should offer a no-pursuit branch")
    retreatBoard:mousepressed(noPursuitButton.x + 1, noPursuitButton.y + 1, 1)
    local noPursuitRetreatAction = emittedRetreatAction
    love = previousLove
    assertTrue(cleverRetreatAction and cleverRetreatAction.action,
        "retreat picker should emit a selected Flee action")
    assertEqual(cleverRetreatAction.action.pursuit, "equivalent",
        "clever retreat option should preserve equivalent pursuit for the group test")
    assertEqual(cleverRetreatAction.action.cleverTactics[1].description, "push over a bookcase",
        "retreat picker should carry the typed clever tactic into the action")
    assertTrue(noPursuitRetreatAction and noPursuitRetreatAction.action,
        "retreat picker should emit the no-pursuit Flee action directly")
    assertEqual(noPursuitRetreatAction.action.pursuit, "no_pursuit",
        "no-pursuit retreat option should mark the clean-retreat pursuit branch")
    assertTrue(noPursuitRetreatAction.action.enemyTiedToLair and noPursuitRetreatAction.action.enemyWillNotPursue,
        "no-pursuit retreat option should carry the resolver's non-pursuit flags")

    local inputBus = events.createEventBus()
    local inputControllerState = challenge_controller.createChallengeController({
        eventBus = inputBus,
    })
    inputControllerState.state = challenge_controller.STATES.AWAITING_ACTION
    inputControllerState.activeEntity = promptHigh
    inputControllerState.currentRound = 1
    inputControllerState.currentCount = 5
    inputControllerState.pcs = { promptHigh, promptLow }
    inputControllerState.allCombatants = { promptHigh, promptLow, promptPursuer }
    local inputDeck = {
        discard = function() end,
    }
    local inputHand = player_hand.createPlayerHand({
        eventBus = inputBus,
        playerDeck = inputDeck,
        guild = { promptHigh, promptLow },
    })
    local inputFleeCard = { name = "Five of Swords", value = 5, suit = constants.SUITS.SWORDS }
    inputHand.hands[promptHigh.id] = { cards = { inputFleeCard } }
    local submittedRetreat = nil
    inputBus:on(events.EVENTS.CHALLENGE_ACTION, function(action)
        submittedRetreat = action
    end)
    local inputPrompt = challenge_input_controller.createChallengeInputController({
        eventBus = inputBus,
        gameState = {
            challengeController = inputControllerState,
            playerHand = inputHand,
            guild = { promptHigh, promptLow },
        },
    })
    inputPrompt:init()
    local inputState = inputPrompt:getState()
    inputState.selectedEntity = promptHigh
    inputState.selectedCard = inputFleeCard
    inputState.selectedCardIndex = 1
    inputPrompt:handleActionSelected(cleverRetreatAction)
    assertTrue(submittedRetreat ~= nil,
        "Challenge input should submit the framed Flee action from the Command Board")
    assertEqual(submittedRetreat.pursuit, "equivalent",
        "Challenge input should preserve retreat pursuit metadata")
    assertEqual(submittedRetreat.cleverTactics[1].description, "push over a bookcase",
        "Challenge input should preserve clever retreat tactic metadata")
    assertTrue(submittedRetreat.retreatTestCards[promptHigh.id] == inputFleeCard,
        "Challenge input should still record the initially played Flee card as a retreat-test card")
end

local function buildLinearZones()
    return {
        { id = "A", name = "A", adjacent_to = { "B" } },
        { id = "B", name = "B", adjacent_to = { "A", "C" } },
        { id = "C", name = "C", adjacent_to = { "B", "D" } },
        { id = "D", name = "D", adjacent_to = { "C" } },
    }
end

local function checkMovementAdjacency()
    local bus = events.createEventBus()
    local zoneRegistry = zone_system.createZoneRegistry({ eventBus = bus })
    local zones = buildLinearZones()
    zoneRegistry:setRoomZones(zones)

    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
        zoneSystem = zoneRegistry,
    })

    local action = {
        challengeController = {
            zones = zones,
        },
    }

    local ok, err = resolver:canMoveBetweenZones(action, "A", "B")
    assertTrue(ok and err == nil, "A->B should be adjacent")

    ok, err = resolver:canMoveBetweenZones(action, "A", "C")
    assertTrue(not ok and (err == "zones_too_far" or err == "zones_not_adjacent"), "A->C should be rejected for single-step Move")

    ok, err = resolver:canMoveBetweenZones(action, "A", "C", { maxDistance = 2 })
    assertTrue(ok and err == nil, "A->C should be legal for two-step Dash")

    ok, err = resolver:canMoveBetweenZones(action, "A", "D", { maxDistance = 2 })
    assertTrue(not ok and err == "zones_too_far", "A->D should be too far for Dash")

    ok, err = resolver:canMoveBetweenZones(action, "A", "Z")
    assertTrue(not ok and err == "zone_not_found", "A->Z should reject unknown zone")
end

local function checkMovementActionDistances()
    local bus = events.createEventBus()
    local zoneRegistry = zone_system.createZoneRegistry({ eventBus = bus })
    local zones = buildLinearZones()
    zoneRegistry:setRoomZones(zones)

    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
        zoneSystem = zoneRegistry,
    })

    local actor = {
        id = "pc_1",
        name = "Runner",
        isPC = true,
        zone = "A",
        conditions = {},
    }
    zoneRegistry:placeEntity(actor.id, actor.zone)

    local dashAction = {
        actor = actor,
        card = { name = "Pentacles", value = 5, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.DASH,
        destinationZone = "C",
        challengeController = { zones = zones },
    }
    local dashResult = resolver:resolve(dashAction)
    assertTrue(dashResult.success, "Dash should move two zones away")
    assertEqual(actor.zone, "C", "Dash should update actor zone")
    assertEqual(dashResult.oldZone, "A", "successful Dash should record the source zone")
    assertEqual(dashResult.newZone, "C", "successful Dash should record the destination zone")
    assertEqual(dashResult.destinationZone, "C", "successful Dash should preserve destination metadata")
    assertEqual(dashResult.movementType, action_resolver.ACTION_TYPES.DASH,
        "successful Dash should record the movement action type")
    do
        local dashPopup = getActionSequencerPopup(dashAction, dashResult, function(data)
            return data.title == "Dash"
        end)
        assertTrue(dashPopup ~= nil, "successful Dash should queue a visible movement popup")
        assertEqual(dashPopup.oldZone, "A", "Dash popup should preserve the source zone")
        assertEqual(dashPopup.newZone, "C", "Dash popup should preserve the destination zone")
        assertEqual(dashPopup.destinationZone, "C", "Dash popup should preserve destination metadata")
        assertEqual(dashPopup.movementType, action_resolver.ACTION_TYPES.DASH,
            "Dash popup should preserve the movement type")
    end

    actor.zone = "A"
    zoneRegistry:placeEntity(actor.id, actor.zone)
    local moveResult = resolver:resolve({
        actor = actor,
        card = { name = "Move", value = 5, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MOVE,
        destinationZone = "C",
        challengeController = { zones = zones },
    })
    assertTrue(not moveResult.success, "Move should not skip an intermediate zone")
    assertEqual(actor.zone, "A", "Failed Move should not update actor zone")

    local avoidResult = resolver:resolve({
        actor = actor,
        card = { name = "Avoid", value = 5, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.AVOID,
        destinationZone = "C",
        challengeController = { zones = zones },
        allEntities = {},
    })
    assertTrue(not avoidResult.success, "Avoid should only move to an adjacent zone")
    assertEqual(actor.zone, "A", "Failed Avoid should not update actor zone")

    local guard = {
        id = "npc_guarding_path",
        name = "Guarding Path",
        isPC = false,
        zone = "B",
        conditions = {},
    }
    local blockedByGuard = resolver:resolve({
        actor = actor,
        target = guard,
        card = { name = "Guarded Avoid", value = 5, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.AVOID,
        destinationZone = "B",
        targetInitiative = 5,
        challengeController = { zones = zones },
        allEntities = {},
    })
    assertTrue(not blockedByGuard.success, "Avoid against a blocking target should require beating Initiative")
    assertEqual(actor.zone, "A", "blocked target Avoid should not move the actor")
    assertTrue(hasValue(blockedByGuard.effects, "avoid_blocked"),
        "blocked target Avoid should report the guard block")

    local passedGuardAction = {
        actor = actor,
        target = guard,
        card = { name = "Passing Avoid", value = 6, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.AVOID,
        destinationZone = "B",
        targetInitiative = 5,
        challengeController = { zones = zones },
        allEntities = {},
    }
    local passedGuard = resolver:resolve(passedGuardAction)
    assertTrue(passedGuard.success, "Avoid should move past a non-engaged threat when it beats Initiative")
    assertEqual(actor.zone, "B", "successful target Avoid should update actor zone")
    assertEqual(passedGuard.avoidValue, 6, "successful target Avoid should preserve the Avoid value")
    assertEqual(passedGuard.targetInitiative, 5, "successful target Avoid should preserve target Initiative")
    assertEqual(passedGuard.oldZone, "A", "successful Avoid should record the source zone")
    assertEqual(passedGuard.newZone, "B", "successful Avoid should record the destination zone")
    assertEqual(passedGuard.destinationZone, "B", "successful Avoid should preserve destination metadata")
    assertEqual(passedGuard.movementType, action_resolver.ACTION_TYPES.AVOID,
        "successful Avoid should record the movement action type")
    assertTrue(passedGuard.avoidOpponents and passedGuard.avoidOpponents[1].opponent == guard,
        "successful target Avoid should preserve the compared target")
    assertTrue(passedGuard.avoidMovement and passedGuard.avoidMovement.avoidOpponents == passedGuard.avoidOpponents,
        "successful Avoid movement metadata should carry comparison details")
    assertTrue(hasValue(passedGuard.effects, "avoid_target_passed"),
        "successful target Avoid should report passing the blocking target")
    do
        local avoidPopup = getActionSequencerPopup(passedGuardAction, passedGuard, function(data)
            return data.title == "Avoid"
        end)
        assertTrue(avoidPopup ~= nil, "successful Avoid should queue a visible movement popup")
        assertEqual(avoidPopup.oldZone, "A", "Avoid popup should preserve the source zone")
        assertEqual(avoidPopup.newZone, "B", "Avoid popup should preserve the destination zone")
        assertEqual(avoidPopup.avoidValue, 6, "Avoid popup should preserve the Avoid value")
        assertEqual(avoidPopup.targetInitiative, 5, "Avoid popup should preserve target Initiative")
        assertTrue(avoidPopup.targetPassed, "Avoid popup should flag a passed blocking target")
    end

    local partingMover = base_entity.createEntity({
        id = "pc_parting_choice_mover",
        name = "Parting Choice Mover",
        isPC = true,
        zone = "A",
    })
    local permissiveGuard = base_entity.createEntity({
        id = "npc_parting_choice_guard",
        name = "Permissive Guard",
        isPC = false,
        zone = "A",
    })
    zoneRegistry:placeEntity(partingMover.id, partingMover.zone)
    zoneRegistry:placeEntity(permissiveGuard.id, permissiveGuard.zone)
    resolver:formEngagement(partingMover, permissiveGuard)
    local allowedMoveAction = {
        actor = partingMover,
        card = { name = "Move", value = 5, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MOVE,
        destinationZone = "B",
        challengeController = { zones = zones },
        allEntities = { partingMover, permissiveGuard },
        partingBlowChoices = {
            [permissiveGuard.id] = "allow",
        },
    }
    local allowedMove = resolver:resolve(allowedMoveAction)
    assertTrue(allowedMove.success, "Move should allow engaged opponents to decline a parting blow")
    assertEqual(partingMover.zone, "B", "parting-blow decline should still move the actor")
    assertEqual(allowedMove.oldZone, "A", "successful Move should record the source zone")
    assertEqual(allowedMove.newZone, "B", "successful Move should record the destination zone")
    assertEqual(allowedMove.destinationZone, "B", "successful Move should preserve destination metadata")
    assertEqual(allowedMove.movementType, action_resolver.ACTION_TYPES.MOVE,
        "successful Move should record the movement action type")
    assertTrue(hasValue(allowedMove.effects, "parting_blow_declined"),
        "declined parting blows should be reported")
    assertTrue(not hasValue(allowedMove.effects, "parting_blows"),
        "declined parting blows should not wound the mover")
    assertEqual(allowedMove.partingBlows.wounds, 0, "declined parting blows should record zero wounds")
    assertEqual(allowedMove.partingBlowWounds, 0,
        "successful Move metadata should preserve zero parting-blow Wounds")
    assertTrue(allowedMove.partingBlowDeclines and allowedMove.partingBlowDeclines[1] == permissiveGuard,
        "successful Move metadata should preserve parting-blow declines")
    assertTrue(allowedMove.movement and allowedMove.movement.partingBlows == allowedMove.partingBlows,
        "successful Move metadata should carry the parting-blow result")
    assertTrue(not partingMover.conditions.staggered,
        "declined parting blows should not apply a Wound")
    assertTrue(not partingMover.is_engaged and not permissiveGuard.is_engaged,
        "moving away should clear engagement flags on both combatants")
    do
        local movePopup = getActionSequencerPopup(allowedMoveAction, allowedMove, function(data)
            return data.title == "Move"
        end)
        assertTrue(movePopup ~= nil, "successful Move should queue a visible movement popup")
        assertEqual(movePopup.oldZone, "A", "Move popup should preserve the source zone")
        assertEqual(movePopup.newZone, "B", "Move popup should preserve the destination zone")
        assertEqual(movePopup.destinationZone, "B", "Move popup should preserve destination metadata")
        assertEqual(movePopup.partingBlowWounds, 0,
            "Move popup should report zero Wounds for a declined parting blow")
        assertTrue(movePopup.partingBlowDeclined,
            "Move popup should flag declined parting blows")
        assertTrue(movePopup.partingBlowDeclines and movePopup.partingBlowDeclines[1] == permissiveGuard,
            "Move popup should preserve declined parting-blow combatants")
    end

    local avoidMover = base_entity.createEntity({
        id = "pc_failed_avoid_decline",
        name = "Failed Avoid Decline",
        isPC = true,
        pentacles = 0,
        zone = "A",
    })
    local avoidGuard = base_entity.createEntity({
        id = "npc_failed_avoid_decliner",
        name = "Failed Avoid Decliner",
        isPC = false,
        zone = "A",
    })
    zoneRegistry:placeEntity(avoidMover.id, avoidMover.zone)
    zoneRegistry:placeEntity(avoidGuard.id, avoidGuard.zone)
    resolver:formEngagement(avoidMover, avoidGuard)
    local declinedAvoidAction = {
        actor = avoidMover,
        card = { name = "Failed Avoid", value = 4, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.AVOID,
        destinationZone = "B",
        targetInitiative = 10,
        challengeController = { zones = zones },
        allEntities = { avoidMover, avoidGuard },
        avoidWoundDeclinesById = {
            [avoidGuard.id] = true,
        },
    }
    local declinedAvoid = resolver:resolve(declinedAvoidAction)
    assertTrue(not declinedAvoid.success,
        "failed engaged Avoid should still report the failed comparison when the opponent declines the Wound")
    assertEqual(avoidMover.zone, "B", "failed engaged Avoid should still move after consequences resolve")
    assertEqual(declinedAvoid.avoidValue, 4, "failed engaged Avoid should preserve the Avoid value")
    assertEqual(declinedAvoid.oldZone, "A", "failed engaged Avoid should record the source zone")
    assertEqual(declinedAvoid.newZone, "B", "failed engaged Avoid should record the destination zone")
    assertEqual(declinedAvoid.destinationZone, "B", "failed engaged Avoid should preserve destination metadata")
    assertEqual(declinedAvoid.movementType, action_resolver.ACTION_TYPES.AVOID,
        "failed engaged Avoid should record the movement action type")
    assertEqual(declinedAvoid.avoidFailures, 1, "declined Avoid Wounds should preserve the failed-opponent count")
    assertEqual(declinedAvoid.avoidWounds, 0, "declined Avoid Wounds should record zero Wounds")
    assertTrue(declinedAvoid.avoidOpponents and declinedAvoid.avoidOpponents[1].opponent == avoidGuard,
        "failed engaged Avoid should preserve compared opponents")
    assertTrue(declinedAvoid.avoidOpponents[1].woundDeclined,
        "failed engaged Avoid should mark declined Wounds per opponent")
    assertTrue(declinedAvoid.avoidMovement and declinedAvoid.avoidMovement.avoidWoundDeclines == declinedAvoid.avoidWoundDeclines,
        "failed engaged Avoid movement metadata should carry declined Wounds")
    assertTrue(hasValue(declinedAvoid.effects, "avoid_wound_declined"),
        "declined Avoid Wounds should be reported")
    assertTrue(not avoidMover.conditions.staggered,
        "declined Avoid Wounds should not wound the actor")
    assertTrue(not avoidMover.is_engaged and not avoidGuard.is_engaged,
        "Avoid movement should clear engagement flags on both combatants")
    do
        local avoidPopup = getActionSequencerPopup(declinedAvoidAction, declinedAvoid, function(data)
            return data.title == "Avoid"
        end)
        assertTrue(avoidPopup ~= nil, "failed-but-moving Avoid should queue a visible movement popup")
        assertEqual(avoidPopup.oldZone, "A", "failed Avoid popup should preserve the source zone")
        assertEqual(avoidPopup.newZone, "B", "failed Avoid popup should preserve the destination zone")
        assertEqual(avoidPopup.avoidFailures, 1, "failed Avoid popup should preserve failure count")
        assertEqual(avoidPopup.avoidWounds, 0, "failed Avoid popup should preserve zero Wounds")
        assertTrue(avoidPopup.failedButMoved, "failed Avoid popup should flag movement after failed comparison")
        assertTrue(avoidPopup.woundDeclined, "failed Avoid popup should flag declined Wounds")
    end
end

local function checkAcrobatTraversalTalent()
    local bus = events.createEventBus()
    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
    })
    local zones = buildLinearZones()

    local acrobat = base_entity.createEntity({
        id = "pc_acrobat_traversal",
        name = "Acrobat Traversal",
        isPC = true,
        talents = {
            acrobat = { mastered = true, wounded = false },
        },
    })
    acrobat.zone = "A"

    local climb = resolver:resolve({
        actor = acrobat,
        card = { name = "Five of Cups", value = 5, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.MOVE,
        destinationZone = "B",
        traversal = "climb",
        challengeController = { zones = zones },
    })
    assertTrue(climb.success, "Acrobat should move across climb/ledge traversal as a miscellaneous Move")
    assertEqual(acrobat.zone, "B", "Acrobat traversal should update the actor zone")
    assertTrue(hasValue(climb.effects, "acrobat_traversal"), "Acrobat traversal should report the talent")
    assertTrue(hasValue(climb.effects, "traversal_no_test"), "Acrobat traversal should not require Test of Fate")
    assertTrue(climb.acrobatTraversal and climb.acrobatTraversal.noTestFate,
        "Acrobat traversal metadata should mark the fate test as bypassed")
    local actionSequencer = require('ui.action_sequencer')
    local traversalSequencer = actionSequencer.createActionSequencer({ eventBus = events.createEventBus() })
    traversalSequencer:queueActionSequence({
        action = {
            actor = acrobat,
            card = { name = "Five of Cups", value = 5, suit = constants.SUITS.CUPS },
            destinationZone = "B",
            traversal = "climb",
        },
        result = climb,
    })
    local hasAcrobatPopup = false
    for _, step in ipairs(traversalSequencer.currentSequence or {}) do
        if step.type == actionSequencer.STEP_TYPES.TEXT_POPUP and
           step.data and step.data.title == "Acrobat" then
            hasAcrobatPopup = true
            assertEqual(step.data.traversalMode, "climb",
                "Acrobat traversal popup should preserve the traversal mode")
            assertTrue(step.data.noTestFate,
                "Acrobat traversal popup should mark the Test Fate bypass")
            break
        end
    end
    assertTrue(hasAcrobatPopup, "Acrobat traversal should queue a visible movement popup")

    local novice = base_entity.createEntity({
        id = "pc_novice_traversal",
        name = "Novice Traversal",
        isPC = true,
    })
    novice.zone = "A"
    local blocked = resolver:resolve({
        actor = novice,
        card = { name = "Six of Cups", value = 6, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.MOVE,
        destinationZone = "B",
        traversal = "tightrope",
        challengeController = { zones = zones },
    })
    assertTrue(not blocked.success, "non-Acrobat traversal should require a Test of Fate")
    assertEqual(novice.zone, "A", "blocked traversal should not move the actor")
    assertTrue(hasValue(blocked.effects, "traversal_test_required"),
        "non-Acrobat traversal should report that a fate test is required")

    local traversalRequest = nil
    bus:on(events.EVENTS.REQUEST_TEST_OF_FATE, function(data)
        if data and data.traversalTest then
            traversalRequest = data
        end
    end)
    local asyncNovice = base_entity.createEntity({
        id = "pc_async_traversal",
        name = "Async Traversal",
        isPC = true,
    })
    asyncNovice.zone = "A"
    local asyncAction = {
        actor = asyncNovice,
        card = { name = "Six of Cups", value = 6, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.MOVE,
        destinationZone = "B",
        traversal = "tightrope",
        promptTraversalTestOfFate = true,
        challengeController = { zones = zones },
    }
    local pending = resolver:resolve(asyncAction)
    assertTrue(pending.pendingTestOfFate, "prompted non-Acrobat traversal should open the async Test Fate flow")
    assertTrue(pending.pendingTraversalTestOfFate,
        "prompted non-Acrobat traversal should mark the pending test as traversal-specific")
    assertEqual(asyncNovice.zone, "A", "pending traversal test should not move the actor")
    assertTrue(traversalRequest ~= nil, "prompted non-Acrobat traversal should emit a Test Fate request")
    assertEqual(traversalRequest.attribute, "pentacles",
        "non-Acrobat traversal should test the Pentacles attribute")
    assertEqual(traversalRequest.targetSuit, constants.SUITS.PENTACLES,
        "non-Acrobat traversal should target Pentacles")
    assertTrue(traversalRequest.traversalTest, "non-Acrobat traversal Test Fate should be flagged")
    assertEqual(traversalRequest.traversalMode, "tightrope",
        "non-Acrobat traversal Test Fate should preserve traversal mode")

    local completed = resolver:resolveTestOfFateOutcome(asyncAction, { success = true })
    assertTrue(completed.success, "a successful async traversal test should resume and complete movement")
    assertEqual(asyncNovice.zone, "B", "successful async traversal should move the actor")
    assertTrue(hasValue(completed.effects, "traversal_test_passed"),
        "successful async traversal should report the passed test")
    local testSequencer = actionSequencer.createActionSequencer({ eventBus = events.createEventBus() })
    testSequencer:queueActionSequence({
        action = asyncAction,
        result = completed,
    })
    local hasTraversalTestPopup = false
    for _, step in ipairs(testSequencer.currentSequence or {}) do
        if step.type == actionSequencer.STEP_TYPES.TEXT_POPUP and
           step.data and step.data.title == "Traversal Test" then
            hasTraversalTestPopup = true
            assertTrue(step.data.testPassed,
                "passed traversal popup should mark the passed Test Fate")
            assertEqual(step.data.destinationZone, "B",
                "passed traversal popup should preserve the destination zone")
            break
        end
    end
    assertTrue(hasTraversalTestPopup, "passed traversal tests should queue a visible popup")

    local failedNovice = base_entity.createEntity({
        id = "pc_failed_async_traversal",
        name = "Failed Async Traversal",
        isPC = true,
    })
    failedNovice.zone = "A"
    local failedAction = {
        actor = failedNovice,
        card = { name = "Seven of Cups", value = 7, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.MOVE,
        destinationZone = "B",
        traversal = "tightrope",
        promptTraversalTestOfFate = true,
        challengeController = { zones = zones },
    }
    local failedPending = resolver:resolve(failedAction)
    assertTrue(failedPending.pendingTraversalTestOfFate,
        "failed async traversal setup should also wait for a Test Fate result")
    local failed = resolver:resolveTestOfFateOutcome(failedAction, { success = false })
    assertTrue(not failed.success, "a failed async traversal test should keep movement blocked")
    assertEqual(failedNovice.zone, "A", "failed async traversal should not move the actor")
    assertTrue(hasValue(failed.effects, "traversal_test_failed"),
        "failed async traversal should report the failed test")
    local failedSequencer = actionSequencer.createActionSequencer({ eventBus = events.createEventBus() })
    failedSequencer:queueActionSequence({
        action = failedAction,
        result = failed,
    })
    local hasTraversalFailedPopup = false
    for _, step in ipairs(failedSequencer.currentSequence or {}) do
        if step.type == actionSequencer.STEP_TYPES.TEXT_POPUP and
           step.data and step.data.title == "Traversal Failed" then
            hasTraversalFailedPopup = true
            assertTrue(step.data.testFailed,
                "failed traversal popup should mark the failed Test Fate")
            break
        end
    end
    assertTrue(hasTraversalFailedPopup, "failed traversal tests should queue a visible popup")

    local tested = resolver:resolve({
        actor = novice,
        card = { name = "Seven of Cups", value = 7, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.MOVE,
        destinationZone = "B",
        traversal = "tightrope",
        traversalTestResult = { success = true },
        challengeController = { zones = zones },
    })
    assertTrue(tested.success, "a passed traversal test should allow non-Acrobat movement")
    assertEqual(novice.zone, "B", "passed traversal test should move the actor")
    assertTrue(hasValue(tested.effects, "traversal_test_passed"),
        "passed traversal test should be reported")

    local gearClimber = base_entity.createEntity({
        id = "pc_grappling_climber",
        name = "Grappling Climber",
        isPC = true,
    })
    gearClimber.zone = "A"
    gearClimber.inventory = inventory.createInventory()
    gearClimber.inventory:addItem(inventory.createItemFromTemplate("grappling_hook"), inventory.LOCATIONS.PACK)

    local hookOnly = resolver:resolve({
        actor = gearClimber,
        card = { name = "Eight of Cups", value = 8, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.MOVE,
        destinationZone = "B",
        traversal = "sheer_surface",
        challengeController = { zones = zones },
    })
    assertTrue(not hookOnly.success, "a grappling hook without rope should still require a traversal test")
    assertEqual(gearClimber.zone, "A", "blocked hook-only traversal should not move the actor")

    gearClimber.inventory:addItem(inventory.createItemFromTemplate("rope"), inventory.LOCATIONS.PACK)
    local hookedClimb = resolver:resolve({
        actor = gearClimber,
        card = { name = "Nine of Cups", value = 9, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.MOVE,
        destinationZone = "B",
        traversal = "sheer_surface",
        challengeController = { zones = zones },
    })
    assertTrue(hookedClimb.success, "grappling hook plus rope should climb sheer surfaces without a test")
    assertEqual(gearClimber.zone, "B", "grappling hook traversal should move the actor")
    assertTrue(hasValue(hookedClimb.effects, "grappling_hook_traversal"),
        "grappling hook traversal should report the gear bypass")
    assertTrue(hasValue(hookedClimb.effects, "traversal_no_test"),
        "grappling hook traversal should bypass Test of Fate")

    local woundedAcrobat = base_entity.createEntity({
        id = "pc_wounded_acrobat_traversal",
        name = "Wounded Acrobat Traversal",
        isPC = true,
        talents = {
            acrobat = { mastered = true, wounded = true },
        },
    })
    woundedAcrobat.zone = "A"
    local woundedBlocked = resolver:resolve({
        actor = woundedAcrobat,
        card = { name = "Eight of Cups", value = 8, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.MOVE,
        destinationZone = "B",
        traversal = "ledge",
        challengeController = { zones = zones },
    })
    assertTrue(not woundedBlocked.success, "wounded Acrobat talent should not bypass traversal tests")
    assertTrue(hasValue(woundedBlocked.effects, "acrobat_traversal_blocked"),
        "wounded Acrobat traversal should be blocked like ordinary difficult traversal")

    local uiBus = events.createEventBus()
    local uiActor = base_entity.createEntity({
        id = "pc_acrobat_traversal_ui",
        name = "Acrobat Traversal UI",
        isPC = true,
        talents = {
            acrobat = { mastered = true },
        },
    })
    uiActor.zone = "deck"
    local uiCard = { name = "Five of Cups", value = 5, suit = constants.SUITS.CUPS }
    local submittedMove = nil
    local uiZones = {
        { id = "deck", name = "Deck", adjacent_to = { "rigging" } },
        {
            id = "rigging",
            name = "Rigging",
            adjacent_to = { "deck" },
            traversalMode = "climb",
            requiresAcrobatTraversal = true,
        },
    }
    local uiChallenge = {
        zones = uiZones,
        allCombatants = { uiActor },
        isActive = function()
            return true
        end,
        getState = function()
            return "awaiting_action"
        end,
        getActiveEntity = function()
            return uiActor
        end,
        submitAction = function(_, action)
            submittedMove = action
            return true
        end,
    }
    local uiInput = challenge_input_controller.createChallengeInputController({
        eventBus = uiBus,
        gameState = {
            challengeController = uiChallenge,
            actionResolver = action_resolver.createActionResolver({
                eventBus = uiBus,
            }),
            playerHand = {
                discardCard = function()
                    return uiCard, 1, nil
                end,
                getHand = function()
                    return { uiCard }
                end,
            },
            guild = { uiActor },
        },
    })
    uiInput:init()
    local uiState = uiInput:getState()
    uiState.selectedCard = uiCard
    uiState.selectedCardIndex = 1
    uiState.selectedEntity = uiActor
    uiInput:handleActionSelected({
        action = {
            id = "move",
            name = "Move",
        },
    })
    assertTrue(uiState.awaitingZone, "Acrobat traversal UI should open destination selection for Move")
    assertEqual(uiState.availableZones[1].id, "rigging",
        "Acrobat traversal UI should offer the authored traversal zone")
    uiInput:handleZoneSelection("1")
    assertTrue(submittedMove ~= nil, "Acrobat traversal UI should submit the selected Move")
    assertEqual(submittedMove.destinationZone, "rigging",
        "Acrobat traversal UI should preserve the selected traversal destination")
    assertEqual(submittedMove.traversalMode, "climb",
        "Acrobat traversal UI should carry authored traversal mode into the action")
    assertTrue(submittedMove.acrobatTraversal,
        "Acrobat traversal UI should mark selected traversal as an Acrobat-capable movement")
    assertTrue(submittedMove.destinationTraversal and submittedMove.destinationTraversal.requiresAcrobatTraversal,
        "Acrobat traversal UI should preserve the authored Acrobat traversal requirement")
end

local function checkUpMySleeveTalent()
    local bus = events.createEventBus()
    local createdEvent = nil
    bus:on("up_my_sleeve_item_created", function(data)
        createdEvent = data
    end)

    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
    })
    local actor = base_entity.createEntity({
        id = "pc_up_my_sleeve",
        name = "Sleeved Adventurer",
        isPC = true,
        talents = {
            up_my_sleeve = { mastered = true, wounded = false },
        },
    })
    actor.resolve = 3
    actor.inventory = inventory.createInventory()

    local first = resolver:resolveUpMySleeve(actor, "lockpick")
    assertTrue(first.success, "Up My Sleeve should produce a common one-slot item")
    assertEqual(first.templateId, "lockpicks", "Up My Sleeve should normalize lockpick alias")
    assertEqual(first.location, inventory.LOCATIONS.HANDS, "Up My Sleeve should default produced item to hands")
    assertEqual(actor.resolve, 2, "Up My Sleeve should spend one Resolve")
    assertEqual(actor.upMySleeveUses, 1, "Up My Sleeve should track Crawl uses")
    assertTrue(first.item.properties.upMySleeve, "produced item should be marked for audit")
    assertEqual(createdEvent and createdEvent.item, first.item, "Up My Sleeve should emit created item event")
    assertTrue(hasValue(first.effects, "resolve_spent_for_up_my_sleeve"),
        "Up My Sleeve should report Resolve spend")
    assertTrue(hasValue(first.effects, "item_produced"), "Up My Sleeve should report item creation")
    assertEqual(actor.inventory:findItem(first.item.id), first.item, "produced item should be in inventory")
    assertTrue(first.upMySleeveCreation and first.upMySleeveCreation.item == first.item,
        "Up My Sleeve should preserve item creation presentation metadata")
    assertEqual(first.upMySleeveCreation.resolveSpent, 1,
        "Up My Sleeve creation metadata should preserve Resolve spend")
    local firstPopup = getActionSequencerPopup({ actor = actor, type = action_resolver.ACTION_TYPES.UP_MY_SLEEVE },
        first, function(data)
            return data.title == "Up My Sleeve"
        end)
    assertTrue(firstPopup ~= nil, "Up My Sleeve should queue an action-sequencer popup")
    assertEqual(firstPopup.item, first.item, "Up My Sleeve popup should preserve the produced item")
    assertEqual(firstPopup.templateId, "lockpicks", "Up My Sleeve popup should preserve the template id")
    assertEqual(firstPopup.resolveSpent, 1, "Up My Sleeve popup should preserve Resolve spend")

    local second = resolver:resolveUpMySleeve(actor, "dagger", {
        location = inventory.LOCATIONS.BELT,
    })
    assertTrue(second.success, "Up My Sleeve should allow the second sleeve")
    assertEqual(second.location, inventory.LOCATIONS.BELT, "Up My Sleeve should respect requested location")
    assertEqual(actor.resolve, 1, "second Up My Sleeve use should spend another Resolve")
    assertEqual(actor.upMySleeveUses, 2, "second Up My Sleeve use should exhaust both sleeves")
    assertEqual(second.usesRemaining, 0, "Up My Sleeve should report no remaining uses after two uses")

    local third = resolver:resolveUpMySleeve(actor, "hermetic_bottle")
    assertTrue(not third.success, "Up My Sleeve should be limited to twice per Crawl")
    assertEqual(third.reason, "uses_exhausted", "third Up My Sleeve use should fail on use limit")
    assertTrue(hasValue(third.effects, "up_my_sleeve_uses_exhausted"),
        "exhausted Up My Sleeve should report use exhaustion")
    assertEqual(actor.resolve, 1, "failed exhausted Up My Sleeve should not spend Resolve")

    local noResolve = base_entity.createEntity({
        id = "pc_up_my_sleeve_no_resolve",
        name = "No Resolve Sleeve",
        isPC = true,
        talents = {
            up_my_sleeve = { mastered = true, wounded = false },
        },
    })
    noResolve.resolve = 0
    noResolve.inventory = inventory.createInventory()
    local missingResolve = resolver:resolveUpMySleeve(noResolve, "dagger")
    assertTrue(not missingResolve.success, "Up My Sleeve should require Resolve")
    assertEqual(missingResolve.reason, "not_enough_resolve", "Up My Sleeve should preflight Resolve")
    assertTrue(hasValue(missingResolve.effects, "resolve_missing"), "missing Resolve should be reported")
    assertEqual(#noResolve.inventory:getItems(inventory.LOCATIONS.HANDS), 0,
        "failed Resolve preflight should not add an item")
    assertEqual(noResolve.upMySleeveUses or 0, 0, "failed Resolve preflight should not consume a sleeve")

    local wounded = base_entity.createEntity({
        id = "pc_up_my_sleeve_wounded",
        name = "Wounded Sleeve",
        isPC = true,
        talents = {
            up_my_sleeve = { mastered = true, wounded = true },
        },
    })
    wounded.resolve = 1
    local woundedResult = resolver:resolveUpMySleeve(wounded, "dagger")
    assertTrue(not woundedResult.success, "wounded Up My Sleeve should not be usable")
    assertEqual(woundedResult.reason, "requires_up_my_sleeve",
        "wounded Up My Sleeve should fail the talent gate")
    assertTrue(hasValue(woundedResult.effects, "talent_missing_or_wounded"),
        "wounded Up My Sleeve should report wounded talent")

    local oversized = resolver:resolveUpMySleeve(noResolve, {
        name = "Folding Ladder",
        size = 2,
        common = true,
    })
    assertTrue(not oversized.success, "Up My Sleeve should reject items larger than one slot")
    assertEqual(oversized.reason, "not_one_slot", "oversized Up My Sleeve item should fail size gate")

    noResolve.resolve = 1
    local rare = resolver:resolveUpMySleeve(noResolve, {
        name = "Jeweled Key",
        size = 1,
        common = true,
        properties = { rare = true },
    })
    assertTrue(not rare.success, "Up My Sleeve should reject rare items")
    assertEqual(rare.reason, "not_common", "rare Up My Sleeve item should fail common item gate")

    local custom = resolver:resolveUpMySleeve(noResolve, {
        id = "custom_handkerchief",
        name = "Handkerchief",
        size = 1,
        common = true,
    })
    assertTrue(custom.success, "Up My Sleeve should allow GM-approved custom common one-slot items")
    assertEqual(custom.item.name, "Handkerchief", "custom Up My Sleeve item should retain its name")
    assertEqual(custom.item.id, "custom_handkerchief", "custom Up My Sleeve item should retain its instance id")

    local examples = base_entity.createEntity({
        id = "pc_up_my_sleeve_examples",
        name = "Sleeve Example Adventurer",
        isPC = true,
        talents = {
            up_my_sleeve = { mastered = true, wounded = false },
        },
    })
    examples.resolve = 2
    examples.inventory = inventory.createInventory()
    local handkerchief = resolver:resolveUpMySleeve(examples, "handkerchief")
    assertTrue(handkerchief.success, "Up My Sleeve should support the rulebook handkerchief example")
    assertEqual(handkerchief.templateId, "handkerchief", "handkerchief should resolve through a canonical template")
    assertEqual(handkerchief.item.name, "Handkerchief", "handkerchief example should create the named item")

    local wire = resolver:resolveUpMySleeve(examples, "length of wire")
    assertTrue(wire.success, "Up My Sleeve should support the rulebook length-of-wire example")
    assertEqual(wire.templateId, "length_of_wire", "length of wire should resolve through a canonical template")
    assertEqual(wire.item.name, "Length of Wire", "wire example should create the named item")

    local actionActor = base_entity.createEntity({
        id = "pc_up_my_sleeve_action",
        name = "Sleeve Action Adventurer",
        isPC = true,
        talents = {
            up_my_sleeve = { mastered = true, wounded = false },
        },
    })
    actionActor.resolve = 1
    actionActor.inventory = inventory.createInventory()
    local sleeveAction = {
        actor = actionActor,
        card = { name = "Seven of Pentacles", value = 7, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.UP_MY_SLEEVE,
        upMySleeveItem = "length_of_wire",
    }
    local actionResult = resolver:resolve(sleeveAction)
    assertTrue(actionResult.success, "Up My Sleeve should resolve through the normal Challenge action path")
    assertEqual(actionResult.templateId, "length_of_wire", "Challenge action Up My Sleeve should keep selected template")
    assertEqual(actionActor.resolve, 0, "Challenge action Up My Sleeve should spend Resolve")
    assertTrue(hasValue(actionResult.effects, "item_produced"),
        "Challenge action Up My Sleeve should report produced item")
    assertTrue(actionResult.upMySleeveCreation and actionResult.upMySleeveCreation.item == actionResult.item,
        "Challenge action Up My Sleeve should preserve creation metadata")
    local actionPopup = getActionSequencerPopup(sleeveAction, actionResult, function(data)
        return data.title == "Up My Sleeve"
    end)
    assertTrue(actionPopup ~= nil, "Challenge action Up My Sleeve should queue an action-sequencer popup")
    assertEqual(actionPopup.templateId, "length_of_wire",
        "Challenge action Up My Sleeve popup should preserve selected template")
    assertEqual(actionPopup.usesRemaining, 1,
        "Challenge action Up My Sleeve popup should preserve remaining sleeve uses")
end

local function checkQuickInterruptTalent()
    local bus = events.createEventBus()
    local emittedAction = nil
    local foolStart = nil
    bus:on(events.EVENTS.CHALLENGE_ACTION, function(action)
        emittedAction = action
    end)
    bus:on("fool_interrupt_start", function(data)
        foolStart = data
    end)

    local controller = challenge_controller.createChallengeController({
        eventBus = bus,
    })
    controller.state = challenge_controller.STATES.AWAITING_ACTION
    controller.currentRound = 1
    controller.currentCount = 5

    local active = base_entity.createEntity({
        id = "npc_active_quick_target",
        name = "Active Target",
        isPC = false,
    })
    controller.activeEntity = active

    local quick = base_entity.createEntity({
        id = "pc_quick_interrupt",
        name = "Quick Interrupt",
        isPC = true,
        pentacles = 2,
        talents = {
            quick = { mastered = true, wounded = false },
        },
    })
    quick.zone = "A"
    quick.inventory = inventory.createInventory()
    quick.inventory:addItem(inventory.createItemFromTemplate("light_armor"), inventory.LOCATIONS.BELT)

    local card = { name = "Five of Pentacles", value = 5, suit = constants.SUITS.PENTACLES }
    local ok, err = controller:playQuickInterrupt(quick, card, {
        type = action_resolver.ACTION_TYPES.DASH,
        destinationZone = "B",
    })
    assertTrue(ok, "Quick! should allow a Pentacles action interrupt in light armor")
    assertEqual(controller.state, challenge_controller.STATES.RESOLVING, "Quick! should move controller to resolving")
    assertEqual(controller.activeEntity, quick, "Quick! should temporarily set the interrupting actor active")
    assertTrue(emittedAction and emittedAction.isQuickInterrupt, "Quick! should emit a marked interrupt action")
    assertTrue(emittedAction.quickTalentInterrupt, "Quick! should mark talent-specific interrupt context")
    assertTrue(emittedAction.quickInterruptContext and emittedAction.quickInterruptContext.previousActive == active,
        "Quick! interrupt context should preserve the interrupted active entity")
    assertEqual(emittedAction.actor, quick, "Quick! interrupt should use the Quick! actor")
    assertEqual(emittedAction.challengeController, controller, "Quick! interrupt action should carry controller context")

    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
        challengeController = controller,
    })
    local resolved = resolver:resolve(emittedAction)
    assertTrue(resolved.success, "Quick! interrupt Pentacles action should resolve normally")
    assertTrue(resolved.quickInterrupt, "Quick! interrupt result should keep audit metadata")
    assertTrue(hasValue(resolved.effects, "quick_interrupt"), "Quick! interrupt should report its effect")
    assertEqual(quick.zone, "B", "Quick! interrupt Dash should apply the Pentacles action")
    assertTrue(resolved.quickInterruptResolution and resolved.quickInterruptResolution.actionType == action_resolver.ACTION_TYPES.DASH,
        "Quick! interrupt should preserve presentation metadata")
    assertEqual(resolved.quickInterruptResolution.previousActive, active,
        "Quick! presentation metadata should preserve the interrupted active entity")
    local quickPopup = getActionSequencerPopup(emittedAction, resolved, function(data)
        return data.title == "Quick!"
    end)
    assertTrue(quickPopup ~= nil, "Quick! interrupt should queue an action-sequencer popup")
    assertEqual(quickPopup.actionType, action_resolver.ACTION_TYPES.DASH,
        "Quick! popup should preserve the interrupt action type")
    assertEqual(quickPopup.card, card, "Quick! popup should preserve the interrupt card")
    assertEqual(quickPopup.previousActive, active, "Quick! popup should preserve interrupted active entity")

    controller:completeQuickInterrupt()
    assertEqual(controller.state, challenge_controller.STATES.AWAITING_ACTION,
        "Quick! completion should restore the prior Challenge state")
    assertEqual(controller.activeEntity, active, "Quick! completion should restore the prior active entity")

    local uiBus = events.createEventBus()
    local uiController = challenge_controller.createChallengeController({ eventBus = uiBus })
    local uiResolver = action_resolver.createActionResolver({
        eventBus = uiBus,
        challengeController = uiController,
    })
    local uiActive = base_entity.createEntity({
        id = "npc_quick_ui_active",
        name = "Quick UI Active",
        isPC = false,
    })
    local uiQuick = base_entity.createEntity({
        id = "pc_quick_ui",
        name = "Quick UI",
        isPC = true,
        pentacles = 2,
        talents = {
            quick = { mastered = true, wounded = false },
        },
    })
    uiController.state = challenge_controller.STATES.AWAITING_ACTION
    uiController.currentRound = 1
    uiController.currentCount = 4
    uiController.activeEntity = uiActive
    uiController.pcs = { uiQuick }
    uiController.npcs = { uiActive }
    uiController.allCombatants = { uiQuick, uiActive }

    local uiCard = { name = "Seven of Pentacles", value = 7, suit = constants.SUITS.PENTACLES }
    local uiCardsById = {
        [uiQuick.id] = { uiCard },
    }
    local uiHand = {}
    function uiHand:getHand(entity)
        return uiCardsById[entity.id] or {}
    end
    function uiHand:discardCard(entity, opts)
        opts = opts or {}
        local cards = uiCardsById[entity.id] or {}
        local index = opts.index
        if opts.card then
            for i, held in ipairs(cards) do
                if held == opts.card then
                    index = i
                    break
                end
            end
        end
        index = index or 1
        local removed = table.remove(cards, index)
        return removed, index, nil
    end

    local uiInput = challenge_input_controller.createChallengeInputController({
        eventBus = uiBus,
        gameState = {
            challengeController = uiController,
            playerHand = uiHand,
            guild = { uiQuick },
        },
    })
    uiInput:init()

    local uiOverlay = require('ui.challenge_overlay').createChallengeOverlay({
        gameState = {
            challengeController = uiController,
            playerHand = uiHand,
            guild = { uiQuick },
        },
        inputState = uiInput:getState(),
    })

    local uiEmitted = nil
    uiBus:on(events.EVENTS.CHALLENGE_ACTION, function(action)
        uiEmitted = action
        action.result = uiResolver:resolve(action)
        uiController:resolveAction(action)
    end)

    uiInput:handleChallengeInput("k")
    assertEqual(uiInput:getState().quickInterruptActor, uiQuick,
        "Quick! input should select the lone eligible interrupt actor")
    local quickPrompt = uiOverlay:getFooterPrompt(uiController:getState(), uiController:getActiveEntity())
    assertTrue(quickPrompt and quickPrompt:find("Quick!"),
        "Challenge overlay should surface Quick! prompts")
    local previousLove = love
    love = {
        graphics = {
            getDimensions = function()
                return 1280, 720
            end,
        },
    }
    uiInput:handleCombatMousePressed(595, 515, 1)
    love = previousLove
    assertEqual(uiInput:getState().selectedCard, uiCard,
        "Quick! mouse input should select a Pentacles card")
    uiInput:handleActionSelected({ action = action_registry.getAction("dodge") })
    assertTrue(uiEmitted and uiEmitted.isQuickInterrupt,
        "Quick! input should emit a marked interrupt action")
    assertEqual(uiEmitted.actor, uiQuick, "Quick! input interrupt should use the selected actor")
    assertEqual(#uiCardsById[uiQuick.id], 0, "Quick! input should discard the played card")
    assertTrue(uiInput:getState().quickInterruptActor == nil,
        "Quick! input prompt should clear after submission")
    uiController:onVisualComplete({})
    assertEqual(uiController.state, challenge_controller.STATES.AWAITING_ACTION,
        "Quick! input completion should restore the interrupted state")

    emittedAction = nil
    local foolActor = base_entity.createEntity({
        id = "pc_fool_interrupt",
        name = "Fool Interrupt",
        isPC = true,
        pentacles = 2,
    })
    foolActor.zone = "A"
    local foolCard = { name = "The Fool", value = 0, suit = constants.SUITS.MAJOR, is_major = false }
    local followUpCard = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS }
    ok, err = controller:playFoolInterrupt(foolActor, foolCard, followUpCard, {
        type = action_resolver.ACTION_TYPES.DASH,
        destinationZone = "C",
    })
    assertTrue(ok, "The Fool should allow an immediate follow-up action interrupt")
    assertEqual(err, nil, "valid Fool interrupt should not report an error")
    assertEqual(controller.state, challenge_controller.STATES.RESOLVING,
        "Fool interrupt should move controller to resolving")
    assertEqual(controller.activeEntity, foolActor,
        "Fool interrupt should temporarily set the interrupting actor active")
    assertTrue(foolStart and foolStart.action == emittedAction,
        "Fool interrupt start event should expose the wrapped action")
    assertTrue(emittedAction and emittedAction.isFoolInterrupt,
        "Fool interrupt should emit a marked interrupt action")
    assertEqual(emittedAction.card, foolCard,
        "Fool interrupt wrapper should keep The Fool as the trigger card")
    assertEqual(emittedAction.followUpCard, followUpCard,
        "Fool interrupt wrapper should carry the real follow-up card")
    assertEqual(emittedAction.followUpAction, action_resolver.ACTION_TYPES.DASH,
        "Fool interrupt wrapper should carry the real follow-up action")
    assertEqual(emittedAction.challengeController, controller,
        "Fool interrupt action should carry controller context")

    local foolResolved = resolver:resolve(emittedAction)
    assertTrue(foolResolved.success, "Fool interrupt should resolve through the Fool helper")
    assertTrue(foolResolved.foolInterrupt and foolResolved.isFoolInterrupt,
        "Fool interrupt result should retain audit metadata")
    assertTrue(foolResolved.followUpResult and foolResolved.followUpResult.success,
        "Fool interrupt should resolve the follow-up action")
    assertEqual(foolActor.zone, "C", "Fool follow-up Dash should apply the follow-up action")

    controller:resolveAction(emittedAction)
    controller:onVisualComplete({})
    assertEqual(controller.state, challenge_controller.STATES.AWAITING_ACTION,
        "Fool completion should restore the prior Challenge state")
    assertEqual(controller.activeEntity, active,
        "Fool completion should restore the prior active entity")

    ok, err = controller:playFoolInterrupt(foolActor, foolCard, nil, {
        type = action_resolver.ACTION_TYPES.DASH,
        destinationZone = "D",
    })
    assertTrue(not ok, "Fool interrupt with a declared action should require a follow-up card")
    assertEqual(err, "missing_fool_followup_card",
        "missing Fool follow-up card should explain the rule")
    assertEqual(controller.state, challenge_controller.STATES.AWAITING_ACTION,
        "rejected Fool interrupt should not change controller state")
    assertEqual(controller.activeEntity, active,
        "rejected Fool interrupt should not change active entity")

    emittedAction = nil
    local foolVigilanceActor = base_entity.createEntity({
        id = "pc_fool_vigilance",
        name = "Fool Vigilance",
        isPC = true,
    })
    local foolVigilanceCard = { name = "Seven of Swords", value = 7, suit = constants.SUITS.SWORDS }
    ok, err = controller:playFoolInterrupt(foolVigilanceActor, foolCard, foolVigilanceCard, {
        type = action_resolver.ACTION_TYPES.VIGILANCE,
        followUpAction = action_resolver.ACTION_TYPES.TRIVIAL_ACTION,
        trigger = { template = "ally_acts" },
    })
    assertTrue(ok, "The Fool should preserve action-specific metadata for a Vigilance follow-up")
    assertEqual(err, nil, "valid Fool Vigilance interrupt should not report an error")
    assertEqual(emittedAction.foolFollowUpAction, action_resolver.ACTION_TYPES.VIGILANCE,
        "Fool wrapper should store the immediate action separately")
    assertEqual(emittedAction.followUpAction, action_resolver.ACTION_TYPES.TRIVIAL_ACTION,
        "Fool wrapper should preserve the Vigilance follow-up action")
    local foolVigilanceResolved = resolver:resolve(emittedAction)
    assertTrue(foolVigilanceResolved.success,
        "Fool-played Vigilance should resolve through the wrapped follow-up action")
    assertTrue(foolVigilanceActor.pendingVigilance ~= nil,
        "Fool-played Vigilance should prepare pending Vigilance")
    assertEqual(foolVigilanceActor.pendingVigilance.followUpAction, action_resolver.ACTION_TYPES.TRIVIAL_ACTION,
        "prepared Fool Vigilance should keep its declared Trivial Action follow-up")
    controller:completeFoolInterrupt()

    local inputBus = events.createEventBus()
    local inputFoolAction = nil
    local inputDiscards = {}
    inputBus:on(events.EVENTS.CHALLENGE_ACTION, function(action)
        inputFoolAction = action
    end)
    local inputChallenge = challenge_controller.createChallengeController({
        eventBus = inputBus,
    })
    local inputActor = base_entity.createEntity({
        id = "pc_fool_input",
        name = "Fool Input",
        isPC = true,
    })
    inputChallenge.state = challenge_controller.STATES.AWAITING_ACTION
    inputChallenge.activeEntity = inputActor
    inputChallenge.currentRound = 1
    inputChallenge.currentCount = 3
    inputChallenge.pcs = { inputActor }
    inputChallenge.allCombatants = { inputActor }

    local inputFool = { name = "The Fool", value = 0, suit = constants.SUITS.MAJOR, is_major = true }
    local inputFollowUp = { name = "Nine of Swords", value = 9, suit = constants.SUITS.SWORDS }
    local inputHand = player_hand.createPlayerHand({
        eventBus = inputBus,
        playerDeck = {
            discard = function(_, card)
                inputDiscards[#inputDiscards + 1] = card
            end,
        },
        guild = { inputActor },
    })
    inputHand.hands[inputActor.id] = {
        cards = { inputFool, inputFollowUp },
        initiativeCard = nil,
    }
    local inputController = challenge_input_controller.createChallengeInputController({
        eventBus = inputBus,
        gameState = {
            challengeController = inputChallenge,
            playerHand = inputHand,
        },
    })
    inputController:init()

    inputController:handleChallengeInput("q")
    assertTrue(inputController:getState().awaitingFoolFollowUpCard,
        "selecting The Fool should ask for a follow-up card before opening actions")
    assertTrue(inputController:getState().foolCard == inputFool,
        "Fool input flow should retain the triggering Fool card")
    local activeFoolOverlay = require('ui.challenge_overlay').createChallengeOverlay({
        gameState = {
            challengeController = inputChallenge,
            playerHand = inputHand,
            guild = { inputActor },
        },
        inputState = inputController:getState(),
    })
    assertEqual(activeFoolOverlay:getFooterPrompt(challenge_controller.STATES.AWAITING_ACTION, inputActor),
        "Select follow-up card for The Fool (Q/W/E), ESC to cancel",
        "Challenge overlay should prompt for the required Fool follow-up card")

    inputController:handleChallengeInput("q")
    assertTrue(inputController:getState().awaitingFoolFollowUpCard,
        "Fool input flow should reject selecting The Fool as its own follow-up")

    inputController:handleChallengeInput("w")
    assertTrue(not inputController:getState().awaitingFoolFollowUpCard,
        "selecting a non-Fool follow-up card should continue to action selection")
    assertTrue(inputController:getState().foolFollowUpCard == inputFollowUp,
        "Fool input flow should retain the selected follow-up card")

    inputController:handleActionSelected({
        action = action_registry.getAction("trivial_action"),
    })
    assertTrue(inputFoolAction and inputFoolAction.isFoolInterrupt,
        "Fool input flow should submit a marked Fool interrupt")
    assertEqual(inputFoolAction.card, inputFool,
        "Fool input flow should keep The Fool as the wrapper card")
    assertEqual(inputFoolAction.followUpCard, inputFollowUp,
        "Fool input flow should submit the selected follow-up card")
    assertEqual(inputFoolAction.foolFollowUpAction, action_resolver.ACTION_TYPES.TRIVIAL_ACTION,
        "Fool input flow should submit the chosen action as the immediate follow-up")
    assertEqual(#inputHand:getHand(inputActor), 0,
        "Fool input flow should remove both played cards from the hand")
    assertTrue(hasValue(inputDiscards, inputFool),
        "Fool input flow should discard The Fool after it is played")
    assertTrue(hasValue(inputDiscards, inputFollowUp),
        "non-facedown Fool follow-up cards should discard normally")

    local minorFoolAction = nil
    local minorDiscards = {}
    local minorBus = events.createEventBus()
    minorBus:on(events.EVENTS.CHALLENGE_ACTION, function(action)
        minorFoolAction = action
    end)
    local minorActor = base_entity.createEntity({
        id = "pc_minor_fool_input",
        name = "Minor Fool Input",
        isPC = true,
    })
    local minorChallenge = challenge_controller.createChallengeController({
        eventBus = minorBus,
    })
    minorChallenge.state = challenge_controller.STATES.MINOR_WINDOW
    minorChallenge.currentRound = 1
    minorChallenge.currentCount = 4
    minorChallenge.pcs = { minorActor }
    minorChallenge.allCombatants = { minorActor }
    local minorFool = { name = "The Fool", value = 0, suit = constants.SUITS.MAJOR, is_major = true }
    local minorFollowUp = { name = "Two of Cups", value = 2, suit = constants.SUITS.CUPS }
    local minorHand = player_hand.createPlayerHand({
        eventBus = minorBus,
        playerDeck = {
            discard = function(_, card)
                minorDiscards[#minorDiscards + 1] = card
            end,
        },
        guild = { minorActor },
    })
    minorHand.hands[minorActor.id] = {
        cards = { minorFool, minorFollowUp },
        initiativeCard = nil,
    }
    local minorInput = challenge_input_controller.createChallengeInputController({
        eventBus = minorBus,
        gameState = {
            challengeController = minorChallenge,
            playerHand = minorHand,
            guild = { minorActor },
        },
    })
    minorInput:init()

    minorInput:handleChallengeInput("1")
    minorInput:handleChallengeInput("q")
    assertTrue(minorInput:getState().awaitingFoolFollowUpCard,
        "selecting The Fool in the minor window should start the interrupt follow-up flow")
    local minorFoolOverlay = require('ui.challenge_overlay').createChallengeOverlay({
        gameState = {
            challengeController = minorChallenge,
            playerHand = minorHand,
            guild = { minorActor },
        },
        inputState = minorInput:getState(),
    })
    assertEqual(minorFoolOverlay:getFooterPrompt(challenge_controller.STATES.MINOR_WINDOW),
        "Select follow-up card for The Fool (Q/W/E), ESC to cancel",
        "minor-window overlay should prompt for the required Fool follow-up card")
    minorInput:handleChallengeInput("w")
    minorInput:handleActionSelected({
        action = action_registry.getAction("trivial_action"),
    })
    assertTrue(minorFoolAction and minorFoolAction.isFoolInterrupt,
        "minor-window Fool flow should submit a Fool interrupt")
    assertEqual(minorFoolAction.foolFollowUpAction, action_resolver.ACTION_TYPES.TRIVIAL_ACTION,
        "minor-window Fool flow should carry the chosen immediate action")
    assertEqual(minorChallenge.pendingFoolRestore.state, challenge_controller.STATES.MINOR_WINDOW,
        "minor-window Fool flow should restore back to the minor window after resolution")
    assertEqual(#minorHand:getHand(minorActor), 0,
        "minor-window Fool flow should remove both played cards from hand")
    assertTrue(hasValue(minorDiscards, minorFool) and hasValue(minorDiscards, minorFollowUp),
        "minor-window Fool flow should discard ordinary played Fool cards")
    minorChallenge:completeFoolInterrupt()
    assertEqual(minorChallenge.state, challenge_controller.STATES.MINOR_WINDOW,
        "completed minor-window Fool interrupt should restore the minor window")

    local minorDashChallenge = challenge_controller.createChallengeController({
        eventBus = events.createEventBus(),
    })
    local minorDashActor = base_entity.createEntity({
        id = "pc_minor_dash_input",
        name = "Minor Dash Input",
        isPC = true,
        zone = "A",
    })
    minorDashChallenge.state = challenge_controller.STATES.MINOR_WINDOW
    minorDashChallenge.currentRound = 1
    minorDashChallenge.currentCount = 6
    minorDashChallenge.pcs = { minorDashActor }
    minorDashChallenge.allCombatants = { minorDashActor }
    minorDashChallenge.zones = {
        { id = "A", name = "A" },
        { id = "B", name = "B" },
    }
    local minorDashCard = { name = "Four of Pentacles", value = 4, suit = constants.SUITS.PENTACLES }
    local minorDashHand = player_hand.createPlayerHand({
        eventBus = events.createEventBus(),
        guild = { minorDashActor },
    })
    minorDashHand.hands[minorDashActor.id] = {
        cards = { minorDashCard },
        initiativeCard = nil,
    }
    local minorDashInput = challenge_input_controller.createChallengeInputController({
        eventBus = events.createEventBus(),
        gameState = {
            challengeController = minorDashChallenge,
            playerHand = minorDashHand,
            guild = { minorDashActor },
        },
    })
    minorDashInput:init()
    minorDashInput:handleChallengeInput("1")
    minorDashInput:handleChallengeInput("q")
    minorDashInput:handleActionSelected({
        action = action_registry.getAction("dash"),
    })
    assertTrue(minorDashInput:getState().awaitingZone,
        "minor-window movement actions should ask for a destination zone")
    local minorDashOverlay = require('ui.challenge_overlay').createChallengeOverlay({
        gameState = {
            challengeController = minorDashChallenge,
            playerHand = minorDashHand,
            guild = { minorDashActor },
        },
        inputState = minorDashInput:getState(),
    })
    assertEqual(minorDashOverlay:getFooterPrompt(challenge_controller.STATES.MINOR_WINDOW),
        "Select destination zone (1-1) for minor action, ESC to cancel",
        "minor-window overlay should prompt for movement destination selection")
    minorDashInput:handleChallengeInput("1")
    assertEqual(#minorDashChallenge.pendingMinors, 1,
        "minor-window zone selection should declare the pending minor action")
    assertEqual(minorDashChallenge.pendingMinors[1].action.destinationZone, "B",
        "minor-window zone selection should preserve the chosen destination")

    local ironQuick = base_entity.createEntity({
        id = "pc_iron_quick",
        name = "Iron Quick",
        isPC = true,
        talents = {
            quick = { mastered = true, wounded = false },
        },
    })
    ironQuick.inventory = inventory.createInventory()
    ironQuick.inventory:addItem(inventory.createItemFromTemplate("iron_armor"), inventory.LOCATIONS.BELT)
    ok, err = controller:playQuickInterrupt(ironQuick, card, {
        type = action_resolver.ACTION_TYPES.DASH,
        destinationZone = "B",
    })
    assertTrue(not ok, "Quick! should not work in heavier armor")
    assertEqual(err, "requires_light_or_no_armor", "Quick! armor gate should explain the block")

    local woundedQuick = base_entity.createEntity({
        id = "pc_wounded_quick",
        name = "Wounded Quick",
        isPC = true,
        talents = {
            quick = { mastered = true, wounded = true },
        },
    })
    ok, err = controller:playQuickInterrupt(woundedQuick, card, {
        type = action_resolver.ACTION_TYPES.DASH,
        destinationZone = "B",
    })
    assertTrue(not ok, "wounded Quick! should not be usable")
    assertEqual(err, "requires_quick", "wounded Quick! should fail the talent gate")

    ok, err = controller:playQuickInterrupt(quick, card, {
        type = action_resolver.ACTION_TYPES.MELEE,
        target = active,
    })
    assertTrue(not ok, "Quick! should only interrupt with Pentacles actions")
    assertEqual(err, "requires_pentacles_action", "Quick! should reject non-Pentacles actions")

    controller.state = challenge_controller.STATES.RESOLVING
    ok, err = controller:playQuickInterrupt(quick, card, {
        type = action_resolver.ACTION_TYPES.DASH,
        destinationZone = "C",
    })
    assertTrue(not ok, "Quick! should only interrupt during open interrupt windows")
    assertEqual(err, "cannot_interrupt_now", "Quick! should report closed interrupt timing")
end

local function checkCounselTalent()
    local bus = events.createEventBus()
    local counselEvent = nil
    bus:on("counsel_card_given", function(data)
        counselEvent = data
    end)
    local counselSequencer = require('ui.action_sequencer').createActionSequencer({
        eventBus = bus,
    })
    counselSequencer:init()

    local counselor = base_entity.createEntity({
        id = "pc_counselor",
        name = "Counselor",
        isPC = true,
        talents = {
            counsel = { mastered = true, wounded = false },
        },
    })
    counselor.resolve = 1
    local target = base_entity.createEntity({
        id = "pc_counsel_target",
        name = "Counsel Target",
        isPC = true,
    })
    local cupsCard = { name = "Six of Cups", value = 6, suit = constants.SUITS.CUPS }
    local swordCard = { name = "Seven of Swords", value = 7, suit = constants.SUITS.SWORDS }
    local hand = player_hand.createPlayerHand({
        eventBus = bus,
        guild = { counselor, target },
    })
    hand.hands[counselor.id] = { cards = { cupsCard, swordCard } }
    hand.hands[target.id] = { cards = {} }

    local controller = challenge_controller.createChallengeController({
        eventBus = bus,
        playerHand = hand,
    })
    controller.state = challenge_controller.STATES.AWAITING_ACTION
    controller.currentRound = 1

    local ok, detail = controller:resolveCounsel(counselor, target, cupsCard,
        action_resolver.ACTION_TYPES.AID, {
            spendResolve = true,
        })
    assertTrue(ok, "Counsel should transfer a matching-suit card to another adventurer")
    assertEqual(counselor.resolve, 0, "Counsel interrupt should spend one Resolve")
    assertEqual(#hand.hands[counselor.id].cards, 1, "Counsel should remove the card from the counselor hand")
    assertEqual(hand.hands[target.id].cards[1], cupsCard, "Counsel should add the card to the target hand")
    assertTrue(cupsCard.counsel and cupsCard.counsel.interrupt, "Resolve Counsel should mark the card interrupt-capable")
    assertEqual(cupsCard.counsel.actionType, action_resolver.ACTION_TYPES.AID,
        "Counsel should record the advised action")
    assertEqual(counselor.counselUsedRound, 1, "Counsel should record once-per-round use")
    assertEqual(counselEvent and counselEvent.card, cupsCard, "Counsel should emit transfer details")
    assertTrue(detail.interrupt and detail.resolveSpent, "Counsel detail should report Resolve interrupt use")
    assertEqual(detail.actionName, "Aid Another", "Counsel detail should preserve advised action name")
    assertEqual(detail.round, 1, "Counsel detail should preserve the Challenge round")
    assertEqual(detail.sourceHandSize, 1, "Counsel detail should report remaining counselor cards")
    assertEqual(detail.targetHandSize, 1, "Counsel detail should report recipient hand size")
    local counselPopup = nil
    for _, step in ipairs(counselSequencer.currentSequence or {}) do
        if step.type == require('ui.action_sequencer').STEP_TYPES.TEXT_POPUP and step.data and
           step.data.title == "Counsel" then
            counselPopup = step.data
            break
        end
    end
    assertTrue(counselPopup ~= nil, "Counsel should queue an action-sequencer popup")
    assertEqual(counselPopup.card, cupsCard, "Counsel popup should preserve the transferred card")
    assertEqual(counselPopup.actionType, action_resolver.ACTION_TYPES.AID,
        "Counsel popup should preserve the advised action")
    assertTrue(counselPopup.interrupt and counselPopup.resolveSpent,
        "Counsel popup should preserve Resolve-paid interrupt metadata")

    ok, detail = controller:resolveCounsel(counselor, target, swordCard, action_resolver.ACTION_TYPES.MELEE)
    assertTrue(not ok, "Counsel should be limited to once per round")
    assertEqual(detail, "counsel_already_used", "Counsel duplicate use should explain the round limit")
    assertEqual(#hand.hands[counselor.id].cards, 1, "failed duplicate Counsel should not transfer another card")

    controller.currentRound = 2
    ok, detail = controller:resolveCounsel(counselor, target, swordCard, action_resolver.ACTION_TYPES.AID)
    assertTrue(not ok, "Counsel should require the card suit to match the advised action")
    assertEqual(detail, "suit_mismatch", "Counsel suit mismatch should explain the block")
    assertEqual(#hand.hands[counselor.id].cards, 1, "failed suit mismatch should leave counselor hand intact")

    local freeCounselor = base_entity.createEntity({
        id = "pc_free_counselor",
        name = "Free Counselor",
        isPC = true,
        talents = {
            counsel = { mastered = true, wounded = false },
        },
    })
    freeCounselor.resolve = 0
    local freeCard = { name = "Four of Cups", value = 4, suit = constants.SUITS.CUPS }
    hand.hands[freeCounselor.id] = { cards = { freeCard } }
    controller.currentRound = 3
    ok, detail = controller:resolveCounsel(freeCounselor, target, freeCard, action_resolver.ACTION_TYPES.AID)
    assertTrue(ok, "Counsel without Resolve should still transfer matching advice")
    assertEqual(freeCounselor.resolve, 0, "non-interrupt Counsel should not require Resolve")
    assertTrue(freeCard.counsel and not freeCard.counsel.interrupt,
        "non-Resolve Counsel should not mark the card as an interrupt")

    local brokeCounselor = base_entity.createEntity({
        id = "pc_broke_counselor",
        name = "Broke Counselor",
        isPC = true,
        talents = {
            counsel = { mastered = true, wounded = false },
        },
    })
    brokeCounselor.resolve = 0
    local brokeCard = { name = "Three of Cups", value = 3, suit = constants.SUITS.CUPS }
    hand.hands[brokeCounselor.id] = { cards = { brokeCard } }
    controller.currentRound = 4
    ok, detail = controller:resolveCounsel(brokeCounselor, target, brokeCard,
        action_resolver.ACTION_TYPES.AID, {
            spendResolve = true,
        })
    assertTrue(not ok, "Counsel interrupt should require Resolve")
    assertEqual(detail, "not_enough_resolve", "Counsel missing Resolve should explain the block")
    assertEqual(#hand.hands[brokeCounselor.id].cards, 1, "failed Resolve Counsel should not transfer")

    local wounded = base_entity.createEntity({
        id = "pc_wounded_counsel",
        name = "Wounded Counsel",
        isPC = true,
        talents = {
            counsel = { mastered = true, wounded = true },
        },
    })
    local woundedCard = { name = "Two of Cups", value = 2, suit = constants.SUITS.CUPS }
    hand.hands[wounded.id] = { cards = { woundedCard } }
    controller.currentRound = 5
    ok, detail = controller:resolveCounsel(wounded, target, woundedCard, action_resolver.ACTION_TYPES.AID)
    assertTrue(not ok, "wounded Counsel should not be usable")
    assertEqual(detail, "requires_counsel", "wounded Counsel should fail the talent gate")

    local uiBus = events.createEventBus()
    local uiEvent = nil
    uiBus:on("counsel_card_given", function(data)
        uiEvent = data
    end)
    local uiCounselor = base_entity.createEntity({
        id = "pc_counsel_ui",
        name = "Counsel UI",
        isPC = true,
        talents = {
            counsel = { mastered = true, wounded = false },
        },
    })
    uiCounselor.resolve = 1
    local uiTarget = base_entity.createEntity({
        id = "pc_counsel_ui_target",
        name = "Counsel UI Target",
        isPC = true,
    })
    local uiCard = { name = "Five of Cups", value = 5, suit = constants.SUITS.CUPS }
    local uiHand = player_hand.createPlayerHand({
        eventBus = uiBus,
        guild = { uiCounselor, uiTarget },
    })
    uiHand.hands[uiCounselor.id] = { cards = { uiCard } }
    uiHand.hands[uiTarget.id] = { cards = {} }
    local uiController = challenge_controller.createChallengeController({
        eventBus = uiBus,
        playerHand = uiHand,
    })
    uiController.state = challenge_controller.STATES.AWAITING_ACTION
    uiController.currentRound = 9
    uiController.pcs = { uiCounselor, uiTarget }
    uiController.allCombatants = { uiCounselor, uiTarget }
    local uiInput = challenge_input_controller.createChallengeInputController({
        eventBus = uiBus,
        gameState = {
            challengeController = uiController,
            playerHand = uiHand,
            guild = { uiCounselor, uiTarget },
        },
    })
    uiInput:init()
    local uiOverlay = require('ui.challenge_overlay').createChallengeOverlay({
        gameState = {
            challengeController = uiController,
            playerHand = uiHand,
            guild = { uiCounselor, uiTarget },
        },
        inputState = uiInput:getState(),
    })

    uiInput:handleChallengeInput("c")
    assertEqual(uiInput:getState().counselActor, uiCounselor,
        "Counsel input should select the lone eligible counselor")
    assertTrue(uiOverlay:getFooterPrompt(uiController:getState(), nil):find("Counsel"),
        "Challenge overlay should surface Counsel prompts")

    local previousLove = love
    love = {
        graphics = {
            getDimensions = function()
                return 1280, 720
            end,
        },
    }
    uiInput:handleCombatMousePressed(595, 515, 1)
    assertEqual(uiInput:getState().counselCard, uiCard,
        "Counsel mouse input should select the advice card")
    uiInput:handleCombatMousePressed(25, 170, 1)
    love = previousLove
    assertTrue(uiInput:getState().awaitingCounselResolveChoice,
        "Counsel mouse input should ask whether to spend Resolve for interrupt advice")
    uiInput:handleChallengeInput("r")
    assertEqual(uiCounselor.resolve, 0, "Counsel input should spend Resolve when requested")
    assertEqual(#uiHand.hands[uiCounselor.id].cards, 0,
        "Counsel input should remove the advised card from the counselor")
    assertEqual(uiHand.hands[uiTarget.id].cards[1], uiCard,
        "Counsel input should transfer the advised card to the target")
    assertTrue(uiCard.counsel and uiCard.counsel.interrupt,
        "Counsel input should mark Resolve-paid advice as interrupt-capable")
    assertEqual(uiEvent and uiEvent.card, uiCard,
        "Counsel input should emit the counsel transfer event")
    assertTrue(uiInput:getState().counselActive == false,
        "Counsel input prompt should clear after transfer")
end

local function checkCounterSpellTalent()
    local bus = events.createEventBus()
    local resolvedEvent = nil
    local maleficenceEvent = nil
    bus:on("counter_spell_resolved", function(data)
        resolvedEvent = data
    end)
    bus:on(events.EVENTS.MALEFICENCE_TRIGGERED, function(data)
        maleficenceEvent = data
    end)

    local resolver = action_resolver.createActionResolver({ eventBus = bus })
    local caster = base_entity.createEntity({
        id = "enemy_sorcerer",
        name = "Enemy Sorcerer",
        wands = 2,
    })
    local counterer = base_entity.createEntity({
        id = "pc_counter_spell",
        name = "Counter-spell PC",
        isPC = true,
        wands = 3,
        talents = {
            counter_spell = { mastered = true, wounded = false },
        },
    })
    counterer.resolve = 2

    local incoming = {
        actor = caster,
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "sleep",
        card = { name = "Four of Wands", value = 4, suit = constants.SUITS.WANDS },
        result = {
            success = true,
            testValue = 6,
            effects = {},
        },
    }
    local counterAction = {
        actor = counterer,
        target = caster,
        type = action_resolver.ACTION_TYPES.COUNTER_SPELL,
        card = { name = "Four of Wands", value = 4, suit = constants.SUITS.WANDS },
        incomingAction = incoming,
        canPerceiveCasting = true,
    }
    local result = resolver:resolve(counterAction)
    assertTrue(result.success, "Counter-spell should fizzle perceived enemy casting")
    assertTrue(result.counterSpellWon, "higher Counter-spell value should beat the enemy spell total")
    assertTrue(result.counterSpellResolution and result.counterSpellResolution.mode == "incoming",
        "Counter-spell should preserve incoming-spell presentation metadata")
    assertEqual(counterer.resolve, 1, "Counter-spell interrupt should spend one Resolve")
    assertTrue(incoming.countered and incoming.fizzled, "Counter-spell should mark the incoming action fizzled")
    assertTrue(incoming.result and incoming.result.success == false,
        "Counter-spell should mark existing incoming results unsuccessful")
    assertTrue(hasValue(result.effects, "counter_spell_fizzled"), "Counter-spell should report the fizzle")
    local counterPopup = getActionSequencerPopup(counterAction, result, function(data)
        return data.title == "Counter-spell"
    end)
    assertTrue(counterPopup ~= nil, "Counter-spell should queue a visible fizzle popup")
    assertEqual(counterPopup.spellId, "sleep", "Counter-spell popup should preserve incoming spell id")
    assertEqual(counterPopup.enemyValue, 6, "Counter-spell popup should preserve incoming spell value")
    assertEqual(counterPopup.counterValue, 7, "Counter-spell popup should preserve counter value")
    assertTrue(counterPopup.spellFizzled, "Counter-spell popup should preserve fizzle state")
    assertEqual(resolvedEvent, result, "Counter-spell should emit the resolved result")
    assertTrue(maleficenceEvent == nil, "winning Counter-spell should not trigger maleficence")

    local tieCounterer = base_entity.createEntity({
        id = "pc_counter_spell_tie",
        name = "Tie Counter-spell PC",
        isPC = true,
        wands = 2,
        talents = {
            counter_spell = { mastered = true, wounded = false },
        },
    })
    tieCounterer.resolve = 1
    local tieIncoming = {
        actor = caster,
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "sleep",
        card = { name = "Four of Wands", value = 4, suit = constants.SUITS.WANDS },
        result = {
            success = true,
            testValue = 6,
            effects = {},
        },
    }
    local tie = resolver:resolve({
        actor = tieCounterer,
        target = caster,
        type = action_resolver.ACTION_TYPES.COUNTER_SPELL,
        card = { name = "Four of Wands", value = 4, suit = constants.SUITS.WANDS },
        incomingAction = tieIncoming,
        maleficenceValue = 1,
    })
    assertTrue(tie.success, "tied Counter-spell should still fizzle the enemy spell")
    assertTrue(not tie.counterSpellWon, "equal Counter-spell value should count as magical backlash")
    assertTrue(tieIncoming.countered, "equal Counter-spell should still mark the incoming spell countered")
    assertTrue(hasValue(tie.effects, "counter_spell_maleficence"),
        "equal Counter-spell should trigger maleficence")
    assertEqual(tieCounterer.resolve, 0, "maleficence Counter-spell should still spend Resolve")
    assertTrue(tie.maleficence and tie.maleficence.reason == "counter_spell_failed_or_tied",
        "Counter-spell backlash should retain its maleficence reason")
    assertTrue(tie.maleficence.resolution and tie.maleficence.resolution.success,
        "Counter-spell backlash should be able to resolve from an explicit draw")
    assertEqual(tie.maleficence.branch, "weird", "Counter-spell backlash should use the incoming spell branch")
    assertEqual(maleficenceEvent, tie.maleficence, "Counter-spell backlash should emit maleficence")

    local brokeCounterer = base_entity.createEntity({
        id = "pc_counter_spell_broke",
        name = "Broke Counter-spell PC",
        isPC = true,
        wands = 3,
        talents = {
            counter_spell = { mastered = true, wounded = false },
        },
    })
    brokeCounterer.resolve = 0
    local brokeIncoming = {
        actor = caster,
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "sleep",
        card = { name = "Four of Wands", value = 4, suit = constants.SUITS.WANDS },
    }
    local broke = resolver:resolve({
        actor = brokeCounterer,
        target = caster,
        type = action_resolver.ACTION_TYPES.COUNTER_SPELL,
        card = { name = "Six of Wands", value = 6, suit = constants.SUITS.WANDS },
        incomingAction = brokeIncoming,
    })
    assertTrue(not broke.success, "Counter-spell should require Resolve")
    assertTrue(hasValue(broke.effects, "resolve_missing"), "missing Resolve should be reported")
    assertTrue(not brokeIncoming.countered, "failed Resolve gate should not counter the incoming spell")

    local woundedCounterer = base_entity.createEntity({
        id = "pc_counter_spell_wounded",
        name = "Wounded Counter-spell PC",
        isPC = true,
        wands = 3,
        talents = {
            counter_spell = { mastered = true, wounded = true },
        },
    })
    woundedCounterer.resolve = 1
    local wounded = resolver:resolve({
        actor = woundedCounterer,
        target = caster,
        type = action_resolver.ACTION_TYPES.COUNTER_SPELL,
        card = { name = "Six of Wands", value = 6, suit = constants.SUITS.WANDS },
        incomingAction = brokeIncoming,
    })
    assertTrue(not wounded.success, "wounded Counter-spell should not be usable")
    assertTrue(hasValue(wounded.effects, "requires_counter_spell"),
        "wounded Counter-spell should fail the talent gate")
    assertEqual(woundedCounterer.resolve, 1, "failed talent gate should not spend Resolve")

    local ongoingCounterer = base_entity.createEntity({
        id = "pc_counter_spell_ongoing",
        name = "Ongoing Counter-spell PC",
        isPC = true,
        wands = 2,
        talents = {
            counter_spell = { mastered = true, wounded = false },
        },
    })
    ongoingCounterer.resolve = 1
    local ongoingCaster = base_entity.createEntity({
        id = "enemy_shroud_caster",
        name = "Enemy Shroud Caster",
        wands = 3,
    })
    local shrouded = base_entity.createEntity({
        id = "enemy_shrouded",
        name = "Shrouded Enemy",
    })
    shrouded.conditions.shrouded = true
    shrouded.conditions.invisible = true
    shrouded.shroud = { caster = ongoingCaster }
    local activeSpell = {
        spellId = "shroud",
        name = "Shroud",
        branch = "weird",
        caster = ongoingCaster,
        target = shrouded,
        concentration = true,
        resolveCommitted = 2,
    }
    ongoingCaster.activeSpells = { activeSpell }
    ongoingCaster.committedResolve = 2
    local ongoingCounterAction = {
        actor = ongoingCounterer,
        targetCaster = ongoingCaster,
        activeSpell = activeSpell,
        mode = "ongoing",
    }
    local negated = resolver:resolveCounterSpell(ongoingCounterAction)
    assertTrue(negated.success, "Counter-spell should negate an ongoing spell")
    assertTrue(negated.counterSpellResolution and negated.counterSpellResolution.mode == "ongoing",
        "ongoing Counter-spell should preserve negation presentation metadata")
    assertTrue(hasValue(negated.effects, "counter_spell_negated"),
        "ongoing Counter-spell should report negation")
    assertEqual(#ongoingCaster.activeSpells, 0, "negated ongoing spell should leave active spells")
    assertEqual(ongoingCaster.committedResolve, 0, "negated ongoing spell should release committed Resolve")
    assertTrue(shrouded.conditions.shrouded == false and shrouded.shroud == nil,
        "negated ongoing spell should run spell cleanup")
    assertEqual(ongoingCounterer.resolve, 0, "ongoing Counter-spell should spend Resolve")
    local negatedPopup = getActionSequencerPopup(ongoingCounterAction, negated, function(data)
        return data.title == "Counter-spell"
    end)
    assertTrue(negatedPopup ~= nil, "ongoing Counter-spell should queue a visible negation popup")
    assertTrue(negatedPopup.negated, "ongoing Counter-spell popup should preserve negation state")
    assertEqual(negatedPopup.spellId, "shroud", "ongoing Counter-spell popup should preserve active spell id")
    assertEqual(negatedPopup.endedSpell, negated.endedSpell,
        "ongoing Counter-spell popup should preserve ended spell metadata")
end

function checkCounterSpellIncomingInterruptPresentation()
    local bus = events.createEventBus()
    local resolver = action_resolver.createActionResolver({ eventBus = bus })
    local controller = challenge_controller.createChallengeController({ eventBus = bus })

    local caster = base_entity.createEntity({
        id = "npc_counterspell_incoming_caster",
        name = "Incoming Caster",
        isPC = false,
        wands = 2,
        conditions = {},
    })
    local counterer = base_entity.createEntity({
        id = "pc_counterspell_incoming",
        name = "Incoming Counterspeller",
        isPC = true,
        wands = 3,
        conditions = {},
        talents = {
            counter_spell = { mastered = true, wounded = false },
        },
    })
    counterer.resolve = 1

    controller.state = challenge_controller.STATES.AWAITING_ACTION
    controller.currentRound = 1
    controller.currentCount = 6
    controller.activeEntity = caster
    controller.pcs = { counterer }
    controller.npcs = { caster }
    controller.allCombatants = { counterer, caster }

    local incomingCard = { name = "Four of Wands", value = 4, suit = constants.SUITS.WANDS }
    local counterCard = { name = "Six of Wands", value = 6, suit = constants.SUITS.WANDS }
    local wrongCard = { name = "Six of Swords", value = 6, suit = constants.SUITS.SWORDS }
    local incomingAction = {
        actor = caster,
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "sleep",
        card = incomingCard,
    }

    local candidates = controller:getCounterSpellInterruptCandidates(incomingAction)
    assertEqual(#candidates, 1, "incoming spell should expose one Counter-spell candidate")
    assertEqual(candidates[1].actor, counterer, "Counter-spell candidate should be the hostile talent user")

    local ok, reason = controller:canCounterSpellIncoming(counterer, wrongCard, incomingAction)
    assertTrue(not ok, "Counter-spell incoming interrupt should require a Wands card")
    assertEqual(reason, "requires_wands_card", "wrong Counter-spell interrupt card should explain Wands gate")

    local availableEvent = nil
    local startedEvent = nil
    local counterActionSeen = nil
    local incomingSeen = nil
    bus:on("counter_spell_interrupt_available", function(data)
        availableEvent = data
        local played, counterAction = controller:playCounterSpellInterrupt(counterer, counterCard, data.incomingAction)
        assertTrue(played, "Counter-spell interrupt helper should play a valid interrupt")
        assertTrue(counterAction.isCounterSpellInterrupt, "Counter-spell helper should mark interrupt metadata")
    end)
    bus:on("counter_spell_interrupt_start", function(data)
        startedEvent = data
    end)
    bus:on(events.EVENTS.CHALLENGE_ACTION, function(action)
        if action.type == action_resolver.ACTION_TYPES.COUNTER_SPELL then
            counterActionSeen = action
            action.result = resolver:resolve(action)
            controller:resolveAction(action)
        elseif action.type == action_resolver.ACTION_TYPES.SPEAK_INCANTATION then
            incomingSeen = action
            action.result = resolver:resolve(action)
            controller:resolveAction(action)
        end
    end)

    ok, reason = controller:submitAction(incomingAction)
    assertTrue(ok, "incoming spell submission should still enter the normal action flow")
    assertTrue(availableEvent ~= nil, "incoming spell should emit Counter-spell interrupt availability")
    assertEqual(availableEvent.candidates[1].actor, counterer,
        "Counter-spell availability should list the eligible counterspeller")
    assertTrue(startedEvent ~= nil, "playing Counter-spell should emit an interrupt start event")
    assertTrue(incomingSeen == nil, "incoming spell should pause until Counter-spell visual completion")
    assertEqual(counterActionSeen and counterActionSeen.incomingAction, incomingAction,
        "Counter-spell action should carry the incoming spell action")
    assertTrue(counterActionSeen and counterActionSeen.result and counterActionSeen.result.success,
        "Counter-spell interrupt should resolve successfully")
    assertEqual(counterer.resolve, 0, "Counter-spell interrupt should spend Resolve")
    controller:onVisualComplete({})
    assertTrue(incomingSeen ~= nil, "incoming spell should resume after Counter-spell completes")
    assertEqual(startedEvent.incomingAction, incomingSeen,
        "Counter-spell start event should reference the incoming spell action")
    assertTrue(incomingSeen.countered and incomingSeen.fizzled,
        "Counter-spell interrupt should mark the incoming spell fizzled before it resolves")
    assertTrue(incomingSeen.result and incomingSeen.result.success == false,
        "countered incoming spell should not resolve its spell effect afterward")
    assertTrue(hasValue(incomingSeen.result.effects, "counter_spell_fizzled"),
        "countered incoming spell should report the fizzle when normal resolution reaches it")

    local uiBus = events.createEventBus()
    local uiResolver = action_resolver.createActionResolver({ eventBus = uiBus })
    local uiController = challenge_controller.createChallengeController({ eventBus = uiBus })
    local uiCaster = base_entity.createEntity({
        id = "npc_counterspell_ui_caster",
        name = "Prompt Caster",
        isPC = false,
        wands = 2,
        conditions = {},
    })
    local uiCounterer = base_entity.createEntity({
        id = "pc_counterspell_ui",
        name = "Prompt Counterspeller",
        isPC = true,
        wands = 3,
        conditions = {},
        talents = {
            counter_spell = { mastered = true, wounded = false },
        },
    })
    uiCounterer.resolve = 1
    uiController.state = challenge_controller.STATES.AWAITING_ACTION
    uiController.currentRound = 1
    uiController.currentCount = 7
    uiController.activeEntity = uiCaster
    uiController.pcs = { uiCounterer }
    uiController.npcs = { uiCaster }
    uiController.allCombatants = { uiCounterer, uiCaster }

    local uiCounterCard = { name = "Seven of Wands", value = 7, suit = constants.SUITS.WANDS }
    local uiCards = { uiCounterCard }
    local fakeHand = { discarded = {} }
    function fakeHand:getHand(_)
        return uiCards
    end
    function fakeHand:discardCard(_, opts)
        opts = opts or {}
        local index = opts.index
        if opts.card then
            for i, card in ipairs(uiCards) do
                if card == opts.card then
                    index = i
                    break
                end
            end
        end
        index = index or 1
        local removed = table.remove(uiCards, index)
        self.discarded[#self.discarded + 1] = removed
        return removed, index, nil
    end

    local uiInput = challenge_input_controller.createChallengeInputController({
        eventBus = uiBus,
        gameState = {
            challengeController = uiController,
            playerHand = fakeHand,
            guild = { uiCounterer },
        },
    })
    uiInput:init()

    local uiOverlay = require('ui.challenge_overlay').createChallengeOverlay({
        gameState = {
            challengeController = uiController,
            playerHand = fakeHand,
        },
        inputState = uiInput:getState(),
    })

    local uiCounterActionSeen = nil
    local uiIncomingSeen = nil
    uiBus:on(events.EVENTS.CHALLENGE_ACTION, function(action)
        if action.type == action_resolver.ACTION_TYPES.COUNTER_SPELL then
            uiCounterActionSeen = action
            action.result = uiResolver:resolve(action)
            uiController:resolveAction(action)
        elseif action.type == action_resolver.ACTION_TYPES.SPEAK_INCANTATION then
            uiIncomingSeen = action
            action.result = uiResolver:resolve(action)
            uiController:resolveAction(action)
        end
    end)

    local uiIncomingAction = {
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "sleep",
        card = { name = "Five of Wands", value = 5, suit = constants.SUITS.WANDS },
    }
    ok, reason = uiController:submitAction(uiIncomingAction)
    assertTrue(ok, "incoming spell UI prompt submission should pause successfully")
    assertTrue(uiInput:getState().pendingCounterSpellInterrupt ~= nil,
        "input controller should store the pending Counter-spell prompt")
    assertTrue(uiCounterActionSeen == nil and uiIncomingSeen == nil,
        "UI prompt should wait for a player card before resolving either action")
    local prompt = uiOverlay:getFooterPrompt(uiController:getState(), uiController:getActiveEntity())
    assertTrue(prompt and prompt:find("Counter%-spell"),
        "Challenge overlay should surface the Counter-spell prompt")

    uiInput:handleChallengeInput("q")
    assertTrue(uiCounterActionSeen and uiCounterActionSeen.result and uiCounterActionSeen.result.success,
        "Q should play the prompted Wands Counter-spell card")
    assertEqual(#uiCards, 0, "prompted Counter-spell card should be discarded from hand")
    assertTrue(uiInput:getState().pendingCounterSpellInterrupt == nil,
        "Counter-spell prompt should clear after a card is played")
    assertEqual(uiCounterer.resolve, 0, "prompted Counter-spell should spend Resolve")
    assertTrue(uiIncomingSeen == nil,
        "incoming spell should still wait for Counter-spell visual completion")

    uiController:onVisualComplete({})
    assertTrue(uiIncomingSeen and uiIncomingSeen.countered and uiIncomingSeen.fizzled,
        "prompted Counter-spell should resume the incoming spell as fizzled")
    assertTrue(hasValue(uiIncomingSeen.result.effects, "counter_spell_fizzled"),
        "prompted Counter-spell fizzle should be reported by normal spell resolution")
end

local function checkDwimmercraftTalent()
    local bus = events.createEventBus()
    local resolvedEvent = nil
    bus:on("dwimmercraft_resolved", function(data)
        resolvedEvent = data
    end)

    local resolver = action_resolver.createActionResolver({ eventBus = bus })
    local caster = base_entity.createEntity({
        id = "pc_dwimmercraft",
        name = "Dwimmercraft PC",
        isPC = true,
        wands = 2,
        talents = {
            dwimmercraft = { mastered = true, wounded = false },
        },
    })
    caster.resolve = 1
    caster.zone = "north"

    local trinket = {
        id = "brass_key",
        name = "Brass Key",
        zone = "north",
        weightPounds = 1,
        size = 1,
    }
    local levitateAction = {
        actor = caster,
        target = trinket,
        type = action_resolver.ACTION_TYPES.DWIMMERCRAFT,
        card = { name = "Three of Cups", value = 3, suit = constants.SUITS.CUPS },
        mode = "levitate",
        challengeController = { isActive = function() return true end },
    }
    local levitate = resolver:resolve(levitateAction)
    assertTrue(levitate.success, "Dwimmercraft should levitate a small same-zone object")
    assertTrue(trinket.dwimmercraft and trinket.dwimmercraft.noFineControl,
        "Dwimmercraft levitation should record no fine motor control")
    assertTrue(hasValue(levitate.effects, "dwimmercraft_misc_action"),
        "Challenge Dwimmercraft should count as a miscellaneous action")
    assertTrue(levitate.dwimmercraftResolution and levitate.dwimmercraftResolution.mode == "levitate",
        "Dwimmercraft levitation should preserve presentation metadata")
    assertEqual(levitate.dwimmercraftResolution.object, trinket,
        "Dwimmercraft levitation metadata should preserve the object")
    local levitatePopup = getActionSequencerPopup(levitateAction, levitate, function(data)
        return data.title == "Dwimmercraft"
    end)
    assertTrue(levitatePopup ~= nil, "Dwimmercraft levitation should queue an action-sequencer popup")
    assertEqual(levitatePopup.mode, "levitate", "Dwimmercraft levitation popup should preserve mode")
    assertEqual(levitatePopup.object, trinket, "Dwimmercraft levitation popup should preserve the object")
    assertTrue(levitatePopup.noFineControl, "Dwimmercraft levitation popup should preserve no-fine-control metadata")
    assertEqual(resolvedEvent, levitate, "Dwimmercraft should emit resolved details")

    local boulder = {
        id = "boulder",
        name = "Boulder",
        zone = "north",
        weightPounds = 80,
        size = 3,
    }
    local tooHeavy = resolver:resolve({
        actor = caster,
        target = boulder,
        type = action_resolver.ACTION_TYPES.DWIMMERCRAFT,
        card = { name = "Four of Cups", value = 4, suit = constants.SUITS.CUPS },
        mode = "levitate",
    })
    assertTrue(not tooHeavy.success, "Dwimmercraft should not levitate heavy objects")
    assertTrue(hasValue(tooHeavy.effects, "dwimmercraft_object_too_heavy"),
        "heavy Dwimmercraft objects should report the weight gate")

    local simpleIllusionAction = {
        actor = caster,
        type = action_resolver.ACTION_TYPES.DWIMMERCRAFT,
        card = { name = "Five of Cups", value = 5, suit = constants.SUITS.CUPS },
        mode = "simple_illusion",
        image = "a silver apple",
    }
    local simpleIllusion = resolver:resolve(simpleIllusionAction)
    assertTrue(simpleIllusion.success, "Dwimmercraft should create a simple handheld illusion")
    assertTrue(simpleIllusion.illusion and simpleIllusion.illusion.convincingUntilInteracted,
        "simple Dwimmercraft illusions should last until interaction reveals them")
    assertTrue(hasValue(simpleIllusion.effects, "dwimmercraft_simple_illusion"),
        "simple Dwimmercraft illusion should report its effect")
    assertTrue(simpleIllusion.dwimmercraftResolution and simpleIllusion.dwimmercraftResolution.mode == "simple_illusion",
        "Dwimmercraft illusion should preserve presentation metadata")
    local illusionPopup = getActionSequencerPopup(simpleIllusionAction, simpleIllusion, function(data)
        return data.title == "Dwimmercraft"
    end)
    assertTrue(illusionPopup ~= nil, "Dwimmercraft illusion should queue an action-sequencer popup")
    assertEqual(illusionPopup.image, "a silver apple", "Dwimmercraft illusion popup should preserve image text")
    assertTrue(illusionPopup.convincingUntilInteracted,
        "Dwimmercraft illusion popup should preserve interaction-reveal metadata")

    local shrouded = base_entity.createEntity({
        id = "shrouded_subject",
        name = "Shrouded Subject",
    })
    shrouded.conditions.shrouded = true
    shrouded.conditions.invisible = true
    shrouded.shroud = { caster = shrouded }
    local secondSightAction = {
        actor = caster,
        type = action_resolver.ACTION_TYPES.DWIMMERCRAFT,
        card = { name = "Six of Cups", value = 6, suit = constants.SUITS.CUPS },
        mode = "second_sight",
    }
    local secondSight = resolver:resolve(secondSightAction)
    assertTrue(secondSight.success, "Dwimmercraft should focus second sight")
    assertEqual(caster.resolve, 0, "second sight should spend one Resolve")
    assertTrue(caster.secondSight and caster.secondSight.active, "second sight should be stored on the actor")
    assertTrue(caster.conditions.second_sight, "second sight should be a watch-duration condition")
    assertTrue(resolver:canActorSeeShrouded(caster, shrouded, {}),
        "second sight should see invisible or Shrouded subjects")
    assertTrue(secondSight.dwimmercraftResolution and secondSight.dwimmercraftResolution.mode == "second_sight",
        "Dwimmercraft second sight should preserve presentation metadata")
    assertTrue(secondSight.dwimmercraftResolution.seesShrouded,
        "Dwimmercraft second sight metadata should preserve Shrouded sight")
    local secondSightPopup = getActionSequencerPopup(secondSightAction, secondSight, function(data)
        return data.title == "Dwimmercraft"
    end)
    assertTrue(secondSightPopup ~= nil, "Dwimmercraft second sight should queue an action-sequencer popup")
    assertEqual(secondSightPopup.mode, "second_sight", "Dwimmercraft second sight popup should preserve mode")
    assertEqual(secondSightPopup.resolveSpent, 1, "Dwimmercraft second sight popup should preserve Resolve spend")
    assertTrue(secondSightPopup.seesInvisible and secondSightPopup.identifiesSorcerers,
        "Dwimmercraft second sight popup should preserve sight capabilities")

    local inspected = resolver:inspectWithSecondSight(caster, {
        id = "illusory_sorcerer",
        isIllusion = true,
        illusionTrueForm = "empty air",
        properties = { magical = true },
        isSorcerer = true,
    })
    assertTrue(inspected.success, "active second sight should inspect magical subjects")
    assertEqual(inspected.trueForm, "empty air", "second sight should reveal an illusion's true form")
    assertTrue(inspected.magical, "second sight should identify magical subjects")
    assertTrue(inspected.isSorcerer, "second sight should identify sorcerers")

    local watch = watch_manager.createWatchManager({
        eventBus = bus,
        guild = { caster },
    })
    local expired = watch:clearWatchDurationConditions()
    assertEqual(#expired, 1, "second sight should expire with watch-duration conditions")
    assertTrue(caster.secondSight == nil, "expired second sight should clear the stored sight record")
    assertTrue(not caster.canSeeShrouded and not caster.magicSight,
        "expired second sight should restore temporary sight flags")

    local broke = base_entity.createEntity({
        id = "pc_dwimmercraft_broke",
        name = "Broke Dwimmercraft PC",
        isPC = true,
        talents = {
            dwimmercraft = { mastered = true, wounded = false },
        },
    })
    broke.resolve = 0
    local missingResolve = resolver:resolve({
        actor = broke,
        type = action_resolver.ACTION_TYPES.DWIMMERCRAFT,
        card = { name = "Seven of Cups", value = 7, suit = constants.SUITS.CUPS },
        mode = "second_sight",
    })
    assertTrue(not missingResolve.success, "second sight should require Resolve")
    assertTrue(hasValue(missingResolve.effects, "resolve_missing"),
        "missing second sight Resolve should be reported")

    local wounded = base_entity.createEntity({
        id = "pc_dwimmercraft_wounded",
        name = "Wounded Dwimmercraft PC",
        isPC = true,
        talents = {
            dwimmercraft = { mastered = true, wounded = true },
        },
    })
    local woundedResult = resolver:resolve({
        actor = wounded,
        type = action_resolver.ACTION_TYPES.DWIMMERCRAFT,
        card = { name = "Eight of Cups", value = 8, suit = constants.SUITS.CUPS },
        mode = "showy_illusion",
    })
    assertTrue(not woundedResult.success, "wounded Dwimmercraft should not be usable")
    assertTrue(hasValue(woundedResult.effects, "requires_dwimmercraft"),
        "wounded Dwimmercraft should fail the talent gate")
end

local function checkMakePactCampAction()
    local function actionAvailable(actions, id)
        for _, action in ipairs(actions or {}) do
            if action.id == id then
                return true
            end
        end
        return false
    end

    local bus = events.createEventBus()
    local campEvent = nil
    local maleficenceEvent = nil
    bus:on("camp_action_resolved", function(data)
        if data.action == "make_pact" then
            campEvent = data
        end
    end)
    bus:on(events.EVENTS.MALEFICENCE_TRIGGERED, function(data)
        maleficenceEvent = data
    end)

    local actor = base_entity.createEntity({
        id = "pc_make_pact",
        name = "Make Pact PC",
        isPC = true,
        wands = 3,
        talents = {
            gramarye = { mastered = true, wounded = false },
            magic_of_the_weald = { mastered = true, wounded = false },
        },
    })
    actor.resolve = 0
    actor.inventory = inventory.createInventory()
    local component = inventory.createItemFromTemplate("component_speak_to_animal")
    actor.inventory:addItem(component, inventory.LOCATIONS.HANDS)

    local plain = base_entity.createEntity({
        id = "pc_no_make_pact",
        name = "No Pact PC",
        isPC = true,
    })
    assertTrue(actionAvailable(camp_actions.getAvailableActions(actor, { actor }), "make_pact"),
        "Gramarye should grant the Make a Pact Camp Action")
    assertTrue(not actionAvailable(camp_actions.getAvailableActions(plain, { plain }), "make_pact"),
        "Make a Pact should not be available without Gramarye")

    local makePactOptions = camp_actions.getMakePactOptions(actor, {
        pactId = "silence",
        component = component,
    })
    assertEqual(makePactOptions.result, "make_pact_options_ready",
        "Make a Pact options should report readiness")
    assertTrue(not makePactOptions.disabled, "Make a Pact options should be enabled for Gramarye")
    assertTrue(makePactOptions.hasGramarye, "Make a Pact options should report the Gramarye gate")
    assertTrue(not makePactOptions.requiresPacts,
        "Make a Pact options should report selected pact readiness")
    assertEqual(makePactOptions.selectedCount, 1, "Make a Pact options should list the selected pact")
    assertEqual(makePactOptions.selectedPacts[1].pactId, "silence",
        "Make a Pact options should preserve the selected pact id")
    assertEqual(makePactOptions.selectedPacts[1].component.id, component.id,
        "Make a Pact options should preview the selected component")
    assertEqual(makePactOptions.selectedPacts[1].actionDataPreview.componentId, component.id,
        "Make a Pact options should preview resolver action data")
    assertEqual(makePactOptions.selectedPacts[1].resultPreview.result, "pact_made",
        "Make a Pact options should preview pact creation")
    assertEqual(makePactOptions.selectedPacts[1].resultPreview.componentLocation, inventory.LOCATIONS.HANDS,
        "Make a Pact options should preview component location")
    assertTrue(makePactOptions.componentOptions[1].selected,
        "Make a Pact component options should mark selected components")
    assertTrue(component.pactCharge == nil and not component.properties.pactCharged,
        "Make a Pact options should not charge the component")

    local repeatedComponentOptions = camp_actions.getMakePactOptions(actor, {
        pacts = { "silence", "verity" },
        components = { component, component },
    })
    assertTrue(repeatedComponentOptions.disabled,
        "Make a Pact options should reject reusing one component for multiple pacts")
    assertEqual(repeatedComponentOptions.selectedPacts[2].unavailableReason,
        "Each pact needs a different component",
        "Make a Pact options should explain the per-pact component gate")

    local plainOptions = camp_actions.getMakePactOptions(plain, {
        pactId = "silence",
    })
    assertTrue(plainOptions.disabled, "Make a Pact options should be disabled without Gramarye")
    assertTrue(hasValue(plainOptions.unavailableReasons, "Requires Gramarye"),
        "Make a Pact options should report the Gramarye requirement")

    local ok, result, pacts = camp_actions.resolveAction({
        type = "make_pact",
        actor = actor,
        pactId = "silence",
        component = component,
    }, {
        eventBus = bus,
    })
    assertTrue(ok, "Make a Pact should charge a carried spell component")
    assertEqual(result, "pacts_made", "Make a Pact should report pact creation")
    assertEqual(#pacts, 1, "Make a Pact should create one pact record")
    assertEqual(pacts[1].pactId, "silence", "Make a Pact should preserve the chosen pact")
    assertTrue(component.properties.pactCharged and component.pactCharge == pacts[1],
        "Make a Pact should charge the selected component")
    assertEqual(campEvent and campEvent.pacts[1], pacts[1], "Make a Pact should emit charged pact details")

    local duplicateOptions = camp_actions.getMakePactOptions(actor, {
        pactId = "verity",
        component = component,
    })
    assertTrue(duplicateOptions.disabled,
        "Make a Pact options should disable already-charged components")
    assertEqual(duplicateOptions.selectedPacts[1].unavailableReason, "Component already charged",
        "Make a Pact options should explain already-charged components")
    assertTrue(hasValue(duplicateOptions.unavailableReasons, "Component already charged"),
        "Make a Pact options should report charged-component selection failures")

    local duplicate, duplicateReason = camp_actions.resolveAction({
        type = "make_pact",
        actor = actor,
        pactId = "verity",
        component = component,
    }, {
        eventBus = bus,
    })
    assertTrue(not duplicate, "Make a Pact should not charge a component twice")
    assertEqual(duplicateReason, "Component already charged",
        "duplicate pact charge should report the component gate")

    local resolver = action_resolver.createActionResolver({ eventBus = bus })
    local cast = resolver:resolve({
        actor = actor,
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "speak_to_animal",
        card = { name = "Eight of Wands", value = 8, suit = constants.SUITS.WANDS },
        usePactCharge = true,
    })
    assertTrue(cast.success, "pact charge should substitute for the first Resolve when casting")
    assertTrue(cast.pactChargeSpent, "Speak Incantation should report the pact charge spend")
    assertEqual(actor.resolve, 0, "pact charge should allow a base spell with no Resolve remaining")
    assertEqual(actor.committedResolve or 0, 0, "pact-paid concentration should not commit unspent Resolve")
    assertTrue(component.properties.pactCharged == false and component.pactCharge == nil,
        "spent pact charge should clear from the component")
    assertTrue(pacts[1].spent and pacts[1].active == false,
        "spent pact should no longer remain active")

    local breaker = base_entity.createEntity({
        id = "pc_break_pact",
        name = "Break Pact PC",
        isPC = true,
        talents = {
            gramarye = { mastered = true, wounded = false },
        },
    })
    breaker.inventory = inventory.createInventory()
    local flareComponent = inventory.createItemFromTemplate("component_flare")
    breaker.inventory:addItem(flareComponent, inventory.LOCATIONS.HANDS)
    local made = select(3, camp_actions.resolveAction({
        type = "make_pact",
        actor = breaker,
        pactId = "verity",
        component = flareComponent,
    }, {
        eventBus = bus,
    }))
    local breakOk, breakResult, detail = camp_actions.breakPact(breaker, made[1], {
        eventBus = bus,
        actionResolver = resolver,
    })
    assertTrue(breakOk, "breaking a pact should be supported")
    assertEqual(breakResult, "pact_broken", "broken pact should report the pact break")
    assertTrue(made[1].broken and made[1].active == false, "broken pact should be marked inactive")
    assertTrue(flareComponent.properties.pactCharged == false,
        "breaking a pact should clear the component charge")
    assertTrue(detail.maleficence and detail.maleficence.reason == "pact_broken",
        "breaking a pact should trigger maleficence")
    assertEqual(detail.maleficence.branch, "weald",
        "broken pact maleficence should use the component branch")
    assertEqual(maleficenceEvent, detail.maleficence,
        "breaking a pact should emit the maleficence event")

    local function createPactRecoveryActor(id, pactId, eventBus)
        local pc = base_entity.createEntity({
            id = id,
            name = id,
            isPC = true,
            talents = {
                gramarye = { mastered = true, wounded = false },
            },
        })
        pc.inventory = inventory.createInventory()
        local pactComponent = inventory.createItemFromTemplate("component_flare")
        pc.inventory:addItem(pactComponent, inventory.LOCATIONS.HANDS)
        local pactOk, pactResult, madePacts = camp_actions.resolveAction({
            type = "make_pact",
            actor = pc,
            pactId = pactId,
            component = pactComponent,
        }, {
            eventBus = eventBus,
        })
        assertTrue(pactOk, pactId .. " setup should make the pact")
        assertEqual(pactResult, "pacts_made", pactId .. " setup should report pact creation")
        return pc, pactComponent, madePacts[1]
    end

    local mortificationBus = events.createEventBus()
    local mortificationBreaks = 0
    mortificationBus:on(events.EVENTS.MALEFICENCE_TRIGGERED, function(data)
        if data.source and data.source.pactId == "self_mortification" then
            mortificationBreaks = mortificationBreaks + 1
        end
    end)
    local mortified, mortificationComponent, mortificationPact =
        createPactRecoveryActor("pc_self_mortification_recovery", "self_mortification", mortificationBus)
    mortified.bonds = {
        ally = { charged = true },
    }
    assertTrue(mortified.conditions.stressed, "Self-mortification should immediately mark Stressed")
    local mortificationCamp = camp_controller.createCampController({
        eventBus = mortificationBus,
        guild = { mortified },
    })
    mortificationCamp:transitionTo(camp_controller.STATES.RECOVERY)
    ok, result = mortificationCamp:spendBondForRecovery(mortified, "ally", "clear_stress")
    assertTrue(ok, "clearing Self-mortification stress should still resolve the recovery spend")
    assertEqual(result, "stress_cleared", "Self-mortification breach should report the recovery result")
    assertTrue(mortificationPact.broken and mortificationPact.active == false,
        "clearing Self-mortification stress should break the pact")
    assertTrue(mortificationComponent.properties.pactCharged == false,
        "breaking Self-mortification should clear the component charge")
    assertEqual(mortificationBreaks, 1, "clearing Self-mortification stress should trigger maleficence")

    local mutilationBus = events.createEventBus()
    local mutilationBreaks = 0
    mutilationBus:on(events.EVENTS.MALEFICENCE_TRIGGERED, function(data)
        if data.source and data.source.pactId == "self_mutilation" then
            mutilationBreaks = mutilationBreaks + 1
        end
    end)
    local mutilated, mutilationComponent, mutilationPact =
        createPactRecoveryActor("pc_self_mutilation_recovery", "self_mutilation", mutilationBus)
    assertEqual(mutilationPact.immediateEffect, "talent_wounded",
        "Self-mutilation setup should record which wound track the pact used")
    assertEqual(mutilated.woundedTalents, 1, "Self-mutilation should immediately apply its wound")
    mutilated.bonds = {
        ally = { charged = true },
    }
    local mutilationCamp = camp_controller.createCampController({
        eventBus = mutilationBus,
        guild = { mutilated },
    })
    mutilationCamp:transitionTo(camp_controller.STATES.RECOVERY)
    ok, result = mutilationCamp:spendBondForRecovery(mutilated, "ally", "heal_wound")
    assertTrue(ok, "Camp recovery should still heal the Self-mutilation wound")
    assertEqual(result, "talent_healed", "Self-mutilation test wound should heal through talent recovery")
    assertEqual(mutilated.woundedTalents, 0,
        "healing the Self-mutilation wound should clear the wounded talent")
    assertTrue(mutilationPact.broken and mutilationPact.active == false,
        "healing the Self-mutilation wound should break the pact")
    assertTrue(mutilationComponent.properties.pactCharged == false,
        "breaking Self-mutilation should clear the component charge")
    assertEqual(mutilationBreaks, 1, "healing the Self-mutilation wound should trigger maleficence")

    local function createPactItemActor(id, pactId, itemTemplate, itemLocation)
        local pc = base_entity.createEntity({
            id = id,
            name = id,
            isPC = true,
            swords = 3,
            cups = 3,
            talents = {
                gramarye = { mastered = true, wounded = false },
            },
        })
        pc.inventory = inventory.createInventory()
        local pactComponent = inventory.createItemFromTemplate("component_flare")
        local item = inventory.createItemFromTemplate(itemTemplate)
        pc.inventory:addItem(pactComponent, inventory.LOCATIONS.PACK)
        pc.inventory:addItem(item, itemLocation or inventory.LOCATIONS.PACK)
        local pactOk, pactResult, itemPacts = camp_actions.resolveAction({
            type = "make_pact",
            actor = pc,
            pactId = pactId,
            component = pactComponent,
        }, {
            eventBus = bus,
        })
        assertTrue(pactOk, pactId .. " item setup should make the pact")
        assertEqual(pactResult, "pacts_made", pactId .. " item setup should report creation")
        return pc, item, pactComponent, itemPacts[1]
    end

    local weaponActor, dagger, weaponComponent, weaponPact =
        createPactItemActor("pc_forego_weapons_attack", "forego_weapons", "dagger", inventory.LOCATIONS.HANDS)
    local weaponTarget = base_entity.createEntity({
        id = "npc_forego_weapon_target",
        name = "Forego Weapon Target",
        isPC = false,
        health = 2,
        defense = 0,
    })
    local weaponResult = resolver:resolve({
        actor = weaponActor,
        target = weaponTarget,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        weapon = dagger,
    })
    assertTrue(weaponPact.broken and weaponPact.active == false,
        "attacking with a weapon should break Forego Weapons")
    assertTrue(weaponComponent.properties.pactCharged == false,
        "breaking Forego Weapons should clear the component charge")
    assertTrue(hasValue(weaponResult.effects, "pact_broken_forego_weapons"),
        "weapon contact should report the broken Forego Weapons pact")

    local armorActor, shield, armorComponent, armorPact =
        createPactItemActor("pc_forego_armor_shield", "forego_armor", "shield_light", inventory.LOCATIONS.PACK)
    local shieldPull = resolver:resolve({
        actor = armorActor,
        card = { name = "Eight of Cups", value = 8, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.PULL_ITEM,
        item = shield,
    })
    assertTrue(shieldPull.success, "pulling a shield should still resolve")
    assertTrue(armorPact.broken and armorPact.active == false,
        "wielding a shield should break Forego Armor")
    assertTrue(armorComponent.properties.pactCharged == false,
        "breaking Forego Armor should clear the component charge")
    assertTrue(hasValue(shieldPull.effects, "pact_broken_forego_armor"),
        "shield contact should report the broken Forego Armor pact")

    local woodActor, torch, woodComponent, woodPact =
        createPactItemActor("pc_forego_wood_torch", "forego_wood", "torch", inventory.LOCATIONS.PACK)
    local torchPull = resolver:resolve({
        actor = woodActor,
        card = { name = "Eight of Cups", value = 8, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.PULL_ITEM,
        item = torch,
    })
    assertTrue(torchPull.success, "pulling a torch should still resolve")
    assertTrue(woodPact.broken and woodPact.active == false,
        "touching a torch should break Forego Wood")
    assertTrue(woodComponent.properties.pactCharged == false,
        "breaking Forego Wood should clear the component charge")
    assertTrue(hasValue(torchPull.effects, "pact_broken_forego_wood"),
        "wood contact should report the broken Forego Wood pact")

    local wandActor, wand, _, wandPact =
        createPactItemActor("pc_forego_wood_wand", "forego_wood", "wand_archwood", inventory.LOCATIONS.PACK)
    local wandPull = resolver:resolve({
        actor = wandActor,
        card = { name = "Eight of Cups", value = 8, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.PULL_ITEM,
        item = wand,
    })
    assertTrue(wandPull.success, "pulling an archwood wand should still resolve")
    assertTrue(wandPact.active and not wandPact.broken,
        "archwood wands should not break Forego Wood")
    assertTrue(not hasValue(wandPull.effects, "pact_broken_forego_wood"),
        "archwood exemption should avoid Forego Wood breach effects")

    local skinActor, calfskin, skinComponent, skinPact =
        createPactItemActor("pc_forego_skins_calfskin", "forego_skins", "component_portable_hole",
            inventory.LOCATIONS.PACK)
    local calfskinPull = resolver:resolve({
        actor = skinActor,
        card = { name = "Eight of Cups", value = 8, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.PULL_ITEM,
        item = calfskin,
    })
    assertTrue(calfskinPull.success, "pulling a calfskin item should still resolve")
    assertTrue(skinPact.broken and skinPact.active == false,
        "touching calfskin should break Forego Skins")
    assertTrue(skinComponent.properties.pactCharged == false,
        "breaking Forego Skins should clear the component charge")
    assertTrue(hasValue(calfskinPull.effects, "pact_broken_forego_skins"),
        "skin/fur contact should report the broken Forego Skins pact")

    local clothActor, cloth, _, clothPact =
        createPactItemActor("pc_forego_skins_cloth", "forego_skins", "clothes_common",
            inventory.LOCATIONS.PACK)
    local clothPull = resolver:resolve({
        actor = clothActor,
        card = { name = "Eight of Cups", value = 8, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.PULL_ITEM,
        item = cloth,
    })
    assertTrue(clothPull.success, "pulling woven clothing should still resolve")
    assertTrue(clothPact.active and not clothPact.broken,
        "woven clothing should not break Forego Skins")
    assertTrue(not hasValue(clothPull.effects, "pact_broken_forego_skins"),
        "woven clothing should avoid Forego Skins breach effects")
end

local function checkKeyedTalentWoundSlots()
    local pc = base_entity.createEntity({
        id = "pc_keyed_talents",
        name = "Keyed Talent PC",
        isPC = true,
        armorSlots = 0,
        talentWoundSlots = 2,
        talents = {
            aegis = { mastered = true, wounded = false },
            path_lore = { mastered = true, wounded = false },
        },
    })

    assertEqual(pc:getTalentCount(), 2, "keyed talent maps should count as wound slots")
    assertEqual(pc:takeWound("piercing"), "talent_wounded", "first keyed talent should absorb a wound")
    assertEqual(pc.woundedTalents, 1, "first talent wound should increment wound count")
    assertEqual(pc:takeWound("piercing"), "talent_wounded", "second keyed talent should absorb a wound")
    assertEqual(pc.woundedTalents, 2, "second talent wound should increment wound count")
    assertEqual(pc:takeWound("piercing"), "staggered", "wounds should cascade after keyed talents are exhausted")

    local preWounded = base_entity.createEntity({
        id = "pc_pre_wounded_keyed_talents",
        name = "Pre-Wounded Keyed Talent PC",
        isPC = true,
        armorSlots = 0,
        talentWoundSlots = 2,
        talents = {
            aegis = { mastered = true, wounded = true },
            path_lore = { mastered = true, wounded = false },
        },
    })
    assertEqual(preWounded.woundedTalents, 1,
        "entities should initialize woundedTalents from keyed wounded talent flags")
    assertEqual(preWounded:getWoundsTaken(), 1,
        "pre-wounded keyed talents should count toward total wounds")
    assertEqual(preWounded:healWound(), "talent_healed",
        "pre-wounded keyed talents should be healable through the wound track")
    assertEqual(preWounded.woundedTalents, 0,
        "healing a pre-wounded keyed talent should synchronize the wound count")
    assertTrue(not preWounded.talents.aegis.wounded,
        "healing a pre-wounded keyed talent should clear the talent flag")

    local adventurer = entity_factory.createAdventurer({
        id = "adventurer_keyed_talents",
        name = "Keyed Talent Adventurer",
        talentWoundSlots = 2,
        talents = {
            aegis = { mastered = true, wounded = false },
            path_lore = { mastered = true, wounded = false },
            ritualist = { mastered = false, wounded = false },
        },
    })
    assertTrue(adventurer:woundTalent("path_lore"), "direct adventurer talent wounds should resolve")
    assertEqual(adventurer.woundedTalents, 1,
        "direct adventurer talent wounds should increment wound count")
    assertTrue(adventurer.talents.path_lore.wounded,
        "direct adventurer talent wounds should set the keyed talent flag")
    assertTrue(adventurer:woundTalent("path_lore"),
        "re-wounding an already wounded talent should be idempotent")
    assertEqual(adventurer.woundedTalents, 1,
        "re-wounding an already wounded talent should not double-count")
    assertTrue(adventurer:woundTalent("aegis"), "second direct adventurer talent wound should resolve")
    assertEqual(adventurer.woundedTalents, 2,
        "second direct adventurer talent wound should respect keyed counts")
    assertTrue(not adventurer:woundTalent("ritualist"),
        "direct adventurer talent wounds should respect talent wound slot limits")
    assertTrue(adventurer:healTalent("path_lore"), "direct adventurer talent healing should resolve")
    assertEqual(adventurer.woundedTalents, 1,
        "direct adventurer talent healing should decrement wound count")
    assertTrue(not adventurer.talents.path_lore.wounded,
        "direct adventurer talent healing should clear the keyed talent flag")
    assertTrue(adventurer:woundTalent("ritualist"),
        "healed direct adventurer talent slots should become available again")
    assertEqual(adventurer.woundedTalents, 2,
        "direct adventurer talent wound count should stay synchronized after healing")

    local preWoundedAdventurer = entity_factory.createAdventurer({
        id = "adventurer_pre_wounded_keyed_talents",
        name = "Pre-Wounded Keyed Talent Adventurer",
        talentWoundSlots = 2,
        talents = {
            aegis = { mastered = true, wounded = true },
            ritualist = { mastered = false, wounded = false },
        },
    })
    assertEqual(preWoundedAdventurer.woundedTalents, 1,
        "adventurers should initialize woundedTalents after normalizing keyed talents")
    assertTrue(preWoundedAdventurer:healTalent("aegis"),
        "pre-wounded adventurer talents should be healable by id")
    assertEqual(preWoundedAdventurer.woundedTalents, 0,
        "direct healing should synchronize pre-wounded adventurer talent counts")
end

local function checkChosenPCWoundOptions()
    local woundReference = base_entity.getWoundRulesReference()
    assertEqual(woundReference.source, "Core Rules Chapter 7: Wounds, Notching Armor, and Tracking Enemy Damage",
        "Wound rules metadata should cite the Chapter 7 wound section")
    assertTrue(woundReference.playerWounds.anyOrder,
        "Wound rules metadata should preserve player-selected wound order")
    assertTrue(woundReference.playerWounds.stressedIsNotAWound,
        "Wound rules metadata should preserve that Stressed is not a Wound choice")
    assertEqual(woundReference.playerWounds.choices[1].id, "armor",
        "Wound rules metadata should list armor notching as a player wound choice")
    assertEqual(woundReference.playerWounds.choices[2].limit, 2,
        "Wound rules metadata should preserve the normal two-talent wound limit")
    assertEqual(woundReference.playerWounds.choices[5].nextWound, "dead",
        "Wound rules metadata should preserve Death's Door fatal follow-up")
    assertTrue(woundReference.damageTypes.piercing.armorAllowed == false,
        "Wound rules metadata should preserve Piercing armor bypass")
    assertTrue(woundReference.damageTypes.critical.talentAllowed == false,
        "Wound rules metadata should preserve Critical skipping talents")
    assertTrue(woundReference.npcHealthDefense.defenseReducedFirst,
        "Wound rules metadata should preserve NPC Defense-first HD tracking")
    assertTrue(woundReference.npcHealthDefense.piercingBypassesDefense,
        "Wound rules metadata should preserve NPC Piercing HD bypass")
    assertTrue(woundReference.deathsDoor.lingersForOneWatch,
        "Wound rules metadata should preserve Death's Door one-watch timing")
    assertTrue(woundReference.deathsDoor.healedTargetMarksStressed,
        "Wound rules metadata should preserve Healed Death's Door stress")

    local playerTrack = base_entity.getPlayerWoundTrack()
    playerTrack.choices[1].id = "mutated"
    assertEqual(base_entity.getPlayerWoundTrack().choices[1].id, "armor",
        "player wound track getter should return copy-safe metadata")
    local criticalDetails = base_entity.getDamageTypeDetails("critical")
    assertEqual(criticalDetails.conditionTrack[1], "injured",
        "Critical damage metadata should begin at Injured")
    local piercingDetails = base_entity.getDamageTypeDetails(true)
    assertEqual(piercingDetails.id, "piercing",
        "legacy true damage metadata lookup should normalize to Piercing")
    local hdRules = base_entity.getNPCHealthDefenseRules()
    hdRules.format = "mutated"
    assertEqual(base_entity.getNPCHealthDefenseRules().format, "HD: Health/Defense",
        "NPC HD metadata getter should return copy-safe metadata")

    local choicePC = base_entity.createEntity({
        id = "pc_wound_choice",
        name = "Wound Choice PC",
        isPC = true,
        armorSlots = 1,
        talentWoundSlots = 2,
        talents = {
            aegis = { mastered = true, wounded = false },
            path_lore = { mastered = true, wounded = false },
        },
    })

    local choices = choicePC:getAvailableWoundChoices("normal")
    assertTrue(hasValue(choices, "armor"), "normal Wound choices should include armor")
    assertTrue(hasValue(choices, "talent"), "normal Wound choices should include talents")
    assertTrue(hasValue(choices, "injured"), "normal Wound choices should include Injured")
    assertTrue(hasValue(choicePC:getAvailableWoundChoices("critical"), "injured"),
        "Critical Wound choices should expose the forced Injured result first")

    assertEqual(choicePC:takeWound("normal", { choice = "talent", talentId = "path_lore" }), "talent_wounded",
        "explicit Wound choice should allow talent before armor")
    assertEqual(choicePC.armorNotches, 0, "choosing talent should not notch armor first")
    assertTrue(choicePC.talents.path_lore.wounded, "explicit talent wound should wound the requested talent")

    local injuredFirst = base_entity.createEntity({
        id = "pc_injured_first",
        name = "Injured First PC",
        isPC = true,
        armorSlots = 1,
        talentWoundSlots = 1,
        talents = {
            aegis = { mastered = true, wounded = false },
        },
    })
    assertEqual(injuredFirst:takeWound("normal", { choice = "injured" }), "injured",
        "PCs should be able to mark Injured before armor or talents")
    assertEqual(injuredFirst.armorNotches, 0, "marking Injured should leave armor available")
    assertEqual(injuredFirst:takeWound("normal", { choice = "armor" }), "deaths_door",
        "an already Injured PC must mark Death's Door on the next Wound")
    assertEqual(injuredFirst.armorNotches, 0, "Injured gate should prevent later armor selection")

    local piercingPC = base_entity.createEntity({
        id = "pc_piercing_choice",
        name = "Piercing Choice PC",
        isPC = true,
        armorSlots = 1,
        talentWoundSlots = 1,
        talents = {
            aegis = { mastered = true, wounded = false },
        },
    })
    assertEqual(piercingPC:takeWound("piercing", { choice = "armor" }), "talent_wounded",
        "piercing damage should not allow armor selection")
    assertEqual(piercingPC.armorNotches, 0, "piercing damage should leave armor unnotched")

    local deathsDoorFirst = base_entity.createEntity({
        id = "pc_deaths_door_first",
        name = "Death's Door First PC",
        isPC = true,
        armorSlots = 1,
        talentWoundSlots = 0,
    })
    assertEqual(deathsDoorFirst:takeWound("normal", { choice = "deaths_door" }), "deaths_door",
        "PCs should be able to choose Death's Door before other available options")
    assertEqual(deathsDoorFirst:takeWound("critical"), "dead",
        "Critical damage at Death's Door should kill")

    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local attacker = base_entity.createEntity({
        id = "npc_wound_attacker",
        name = "Wound Attacker",
        isPC = false,
        swords = 3,
        health = 2,
        defense = 0,
    })
    local target = base_entity.createEntity({
        id = "pc_action_wound_choice",
        name = "Action Wound Choice PC",
        isPC = true,
        armorSlots = 1,
        talentWoundSlots = 1,
        talents = {
            aegis = { mastered = true, wounded = false },
        },
    })
    local attack = resolver:resolve({
        actor = attacker,
        target = target,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 5,
        targetWoundChoice = "injured",
    })
    assertTrue(attack.success, "setup melee should hit")
    assertTrue(target.conditions.injured, "action-level wound choice should mark Injured")
    assertEqual(target.armorNotches, 0, "action-level wound choice should bypass available armor when chosen")

    local promptBus = events.createEventBus()
    local promptResolver = action_resolver.createActionResolver({
        eventBus = promptBus,
    })
    local promptController = challenge_controller.createChallengeController({
        eventBus = promptBus,
    })
    promptController.state = challenge_controller.STATES.AWAITING_ACTION
    local promptAttacker = base_entity.createEntity({
        id = "npc_wound_prompt_attacker",
        name = "Wound Prompt Attacker",
        isPC = false,
        swords = 3,
        health = 2,
        defense = 0,
    })
    local promptTarget = base_entity.createEntity({
        id = "pc_wound_prompt_target",
        name = "Wound Prompt Target",
        isPC = true,
        armorSlots = 1,
        talentWoundSlots = 1,
        talents = {
            aegis = { mastered = true, wounded = false },
        },
    })
    local promptInput = challenge_input_controller.createChallengeInputController({
        eventBus = promptBus,
        gameState = {
            challengeController = promptController,
            playerHand = {
                getHand = function()
                    return {}
                end,
            },
            guild = { promptTarget },
        },
    })
    promptInput:init()
    local promptOverlay = require('ui.challenge_overlay').createChallengeOverlay({
        gameState = {
            challengeController = promptController,
            playerHand = {
                getHand = function()
                    return {}
                end,
            },
        },
        inputState = promptInput:getState(),
    })

    local promptAction = {
        actor = promptAttacker,
        target = promptTarget,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 5,
        promptWoundChoice = true,
    }
    local woundChoiceResolved = false
    local woundChoiceCompletions = 0
    promptBus:on(events.EVENTS.WOUND_CHOICE_COMPLETE, function(data)
        local ok, resultOrReason = promptResolver:resolvePendingWoundChoice(promptAction, data)
        assertTrue(ok, "Wound prompt completion should resolve the pending Wound choice: " .. tostring(resultOrReason))
        woundChoiceResolved = true
        woundChoiceCompletions = woundChoiceCompletions + 1
    end)
    local promptResult = promptResolver:resolve(promptAction)
    assertTrue(promptResult.pendingWoundChoice ~= nil,
        "ordinary PC Wound should pause for a Challenge Wound-choice prompt")
    assertTrue(promptInput:getState().pendingWoundChoice ~= nil,
        "input controller should retain the pending Wound-choice prompt")
    local woundPrompt = promptOverlay:getFooterPrompt(promptController:getState(), promptController:getActiveEntity())
    assertTrue(woundPrompt and woundPrompt:find("Wound", 1, true),
        "Challenge overlay should surface the Wound-choice prompt")
    assertTrue(not promptTarget.conditions.staggered and promptTarget.armorNotches == 0,
        "pending Wound choices should not apply damage before player election")

    promptInput:handleChallengeInput("3")
    assertTrue(woundChoiceResolved, "number-key Wound prompt choice should emit completion")
    assertTrue(promptTarget.conditions.staggered, "choosing option 3 should mark Staggered")
    assertEqual(promptTarget.armorNotches, 0, "choosing Staggered should leave armor unnotched")
    assertTrue(promptResult.pendingWoundChoice == nil, "resolved Wound prompt should clear the result pending marker")
    assertEqual(promptResult.woundChoice, "staggered", "resolved Wound prompt should record the elected choice")

    local talentPromptTarget = base_entity.createEntity({
        id = "pc_wound_prompt_talent_target",
        name = "Wound Prompt Talent Target",
        isPC = true,
        armorSlots = 1,
        talentWoundSlots = 2,
        talents = {
            aegis = { name = "Aegis", mastered = true, wounded = false },
            path_lore = { name = "Path Lore", mastered = true, wounded = false },
        },
    })
    promptAction = {
        actor = promptAttacker,
        target = talentPromptTarget,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 5,
        promptWoundChoice = true,
    }
    woundChoiceResolved = false
    local talentPromptResult = promptResolver:resolve(promptAction)
    assertTrue(talentPromptResult.pendingWoundChoice ~= nil,
        "Wound prompt should be reusable for later Challenge damage")
    promptInput:handleChallengeInput("t")
    assertTrue(not woundChoiceResolved,
        "choosing Talent with multiple unwounded talents should ask for the specific talent first")
    assertTrue(promptInput:getState().awaitingWoundTalentChoice,
        "input state should track the specific Wound-talent subprompt")
    local talentPrompt = promptOverlay:getFooterPrompt(promptController:getState(), promptController:getActiveEntity())
    assertTrue(talentPrompt and talentPrompt:find("Path Lore", 1, true),
        "Challenge overlay should list specific talents for talent Wound choices")
    promptInput:handleChallengeInput("2")
    assertTrue(woundChoiceResolved, "specific Wound-talent prompt should emit completion")
    assertTrue(talentPromptTarget.talents.path_lore.wounded,
        "specific Wound-talent choice should wound the selected talent")
    assertTrue(not talentPromptTarget.talents.aegis.wounded,
        "specific Wound-talent choice should leave unselected talents intact")
    assertEqual(talentPromptResult.woundChoice, "talent",
        "resolved specific Wound-talent prompt should record the talent Wound choice")

    local calmBerserker = base_entity.createEntity({
        id = "pc_wound_prompt_berserkergang_calm",
        name = "Calm Berserkergang Prompt",
        isPC = true,
        armorSlots = 0,
        talentWoundSlots = 1,
        talents = {
            berserkergang = { name = "Berserkergang", mastered = true, wounded = false },
        },
    })
    promptAction = {
        actor = promptAttacker,
        target = calmBerserker,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 5,
        promptWoundChoice = true,
    }
    woundChoiceResolved = false
    promptResolver:resolve(promptAction)
    promptInput:handleChallengeInput("t")
    assertTrue(not woundChoiceResolved,
        "choosing Berserkergang as the Wounded talent should ask whether to enter rage")
    assertTrue(promptInput:getState().awaitingBerserkergangChoice,
        "input state should track the Berserkergang rage election")
    local berserkPrompt = promptOverlay:getFooterPrompt(promptController:getState(), promptController:getActiveEntity())
    assertTrue(berserkPrompt and berserkPrompt:find("Berserkergang", 1, true),
        "Challenge overlay should surface the Berserkergang rage election")
    promptInput:handleChallengeInput("space")
    assertTrue(woundChoiceResolved, "declining Berserkergang rage should still wound the talent")
    assertTrue(calmBerserker.talents.berserkergang.wounded,
        "declining Berserkergang rage should preserve the selected talent Wound")
    assertTrue(not calmBerserker.conditions.berserkergang,
        "declining Berserkergang rage should not enter the rage state")

    local ragingBerserker = base_entity.createEntity({
        id = "pc_wound_prompt_berserkergang_rage",
        name = "Raging Berserkergang Prompt",
        isPC = true,
        armorSlots = 0,
        talentWoundSlots = 1,
        talents = {
            berserkergang = { name = "Berserkergang", mastered = true, wounded = false },
        },
    })
    promptAction = {
        actor = promptAttacker,
        target = ragingBerserker,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 5,
        promptWoundChoice = true,
    }
    woundChoiceResolved = false
    promptResolver:resolve(promptAction)
    promptInput:handleChallengeInput("t")
    promptInput:handleChallengeInput("r")
    assertTrue(woundChoiceResolved, "accepting Berserkergang rage should complete the Wound prompt")
    assertTrue(ragingBerserker.conditions.berserkergang and ragingBerserker.conditions.berserk,
        "accepting Berserkergang rage should enter the rage state")

    local multiWoundTarget = base_entity.createEntity({
        id = "pc_multi_wound_prompt_target",
        name = "Multi-Wound Prompt Target",
        isPC = true,
        armorSlots = 1,
        talentWoundSlots = 0,
    })
    promptAction = {
        promptWoundChoice = true,
        result = {
            effects = {},
            description = "",
        },
    }
    woundChoiceResolved = false
    woundChoiceCompletions = 0
    local multiPending = promptResolver:applyDamage(multiWoundTarget, 2, promptAction.result.effects,
        nil, nil, nil, {
            source = "attack",
            action = promptAction,
            result = promptAction.result,
            promptWoundChoice = true,
        })
    assertTrue(multiPending and multiPending.pendingWoundChoice,
        "multi-Wound PC damage should pause for the first Wound choice")
    assertEqual(multiPending.amount, 1, "multi-Wound prompt should resolve one Wound at a time")
    assertEqual(multiPending.remainingAmount, 1, "multi-Wound prompt should retain remaining Wounds")
    promptInput:handleChallengeInput("1")
    assertEqual(multiWoundTarget.armorNotches, 1,
        "first multi-Wound choice should apply only the selected first Wound")
    assertTrue(promptAction.pendingWoundChoice ~= nil,
        "multi-Wound damage should request the next Wound choice after the first resolves")
    assertTrue(promptInput:getState().pendingWoundChoice ~= nil,
        "input prompt should remain open for the next Wound in a multi-Wound hit")
    promptInput:handleChallengeInput("1")
    assertTrue(multiWoundTarget.conditions.staggered,
        "second multi-Wound choice should apply separately after the second election")
    assertTrue(promptAction.pendingWoundChoice == nil,
        "multi-Wound prompt should clear after all Wounds are resolved")
    assertEqual(woundChoiceCompletions, 2,
        "multi-Wound damage should complete one prompt per player-elected Wound")
    assertEqual(#(promptAction.result.woundChoices or {}), 2,
        "multi-Wound result should retain each elected Wound choice")

    local piercingPromptTarget = base_entity.createEntity({
        id = "pc_piercing_prompt_target",
        name = "Piercing Prompt Target",
        isPC = true,
        armorSlots = 1,
        talentWoundSlots = 1,
        talents = {
            aegis = { mastered = true, wounded = false },
        },
    })
    local piercingPending = promptResolver:applyDamage(piercingPromptTarget, 1, { "piercing" }, nil, nil, nil, {
        promptWoundChoice = true,
        action = { promptWoundChoice = true },
        result = { effects = {} },
    })
    assertTrue(piercingPending and piercingPending.pendingWoundChoice,
        "Piercing Wounds should still prompt when multiple non-armor choices remain")
    assertTrue(not hasValue(piercingPending.choices, "armor"),
        "Piercing Wound-choice prompt should not offer armor")
end

local function checkDeathsDoorDefeatedInChallengeFlow()
    local controller = challenge_controller.createChallengeController({
        eventBus = events.createEventBus(),
    })

    local pc = base_entity.createEntity({
        id = "pc_deaths_door_flow",
        name = "Death Door PC",
        isPC = true,
    })
    local npc = base_entity.createEntity({
        id = "npc_deaths_door_flow",
        name = "Death Door NPC",
        isPC = false,
        health = 1,
        defense = 0,
    })

    pc.conditions.deaths_door = true
    controller.pcs = { pc }
    controller.npcs = { npc }
    controller:buildCombatantList()
    assertTrue(controller:isDefeated(pc), "Death's Door PC should be defeated for Challenge flow")
    assertEqual(#controller.allCombatants, 1, "Death's Door PC should be excluded from active combatants")
    assertEqual(controller:checkEndConditions(), challenge_controller.OUTCOMES.DEFEAT,
        "all PCs at Death's Door should end the Challenge in defeat")

    pc.conditions.deaths_door = false
    npc.conditions.deaths_door = true
    controller:buildCombatantList()
    assertTrue(controller:isDefeated(npc), "Death's Door NPC should be defeated for Challenge flow")
    assertEqual(#controller.allCombatants, 1, "Death's Door NPC should be excluded from active combatants")
    assertEqual(controller:checkEndConditions(), challenge_controller.OUTCOMES.VICTORY,
        "all NPCs at Death's Door should count as victory")

    local ai = npc_ai.createNPCAI({
        eventBus = events.createEventBus(),
        challengeController = {
            npcs = { npc },
            pcs = { pc },
        },
    })
    assertTrue(ai:isDefeated(npc), "NPC AI should treat Death's Door as defeated")

    local consciousPC = base_entity.createEntity({
        id = "pc_conscious_target",
        name = "Conscious Target",
        isPC = true,
    })
    consciousPC.zone = "far"
    pc.zone = "near"
    pc.conditions.deaths_door = true
    local selected = ai:selectTarget(npc, { pc, consciousPC }, false)
    assertEqual(selected, consciousPC, "NPC AI should not target a PC at Death's Door")

    local dog = {
        id = "npc_hound",
        name = "Hungry Hound",
        zone = "near",
        tags = { "hound" },
        conditions = {},
    }
    local easyTarget = base_entity.createEntity({
        id = "pc_easy_dog_target",
        name = "Easy Dog Target",
        isPC = true,
    })
    easyTarget.zone = "near"
    easyTarget.conditions = {}
    easyTarget.npcDefense = 0
    local cursedTarget = base_entity.createEntity({
        id = "pc_dogs_hate_me",
        name = "Dogs Hate Me",
        isPC = true,
    })
    cursedTarget.zone = "far"
    cursedTarget.conditions = {}
    cursedTarget.malediction = {
        active = true,
        curse = {
            flags = { dogsHateYou = true },
        },
    }
    selected = ai:selectTarget(dog, { easyTarget, cursedTarget }, false)
    assertEqual(selected, cursedTarget, "dog-like NPCs should prioritize Dogs Hate You targets")

    local zombie = {
        id = "npc_targeting_zombie",
        name = "Targeting Zombie",
        zone = "near",
        undead = true,
        conditions = {},
    }
    local ordinaryTarget = base_entity.createEntity({
        id = "pc_ordinary_undead_target",
        name = "Ordinary Undead Target",
        isPC = true,
        pentacles = 4,
    })
    ordinaryTarget.zone = "near"
    ordinaryTarget.conditions = {}
    local corpseLikeTarget = base_entity.createEntity({
        id = "pc_desiccated_undead_target",
        name = "Desiccated Undead Target",
        isPC = true,
        pentacles = -4,
    })
    corpseLikeTarget.zone = "near"
    corpseLikeTarget.conditions = {}
    corpseLikeTarget.malediction = {
        active = true,
        curse = {
            flags = { undeadUsuallyIgnore = true },
        },
    }
    selected = ai:selectTarget(zombie, { corpseLikeTarget, ordinaryTarget }, false)
    assertEqual(selected, ordinaryTarget, "undead NPCs should ignore desiccated-corpse Malediction targets when other targets exist")
    selected = ai:selectTarget(zombie, { corpseLikeTarget }, false)
    assertEqual(selected, corpseLikeTarget, "undead NPCs should still target a desiccated-corpse Malediction target if no other target exists")

    local markedTarget = base_entity.createEntity({
        id = "pc_undead_mark_target",
        name = "Undead Mark Target",
        isPC = true,
        pentacles = 5,
    })
    markedTarget.zone = "far"
    markedTarget.conditions = {}
    local markResolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local markRecord = markResolver:triggerMaleficence(markedTarget, "wastes", "smoke_test", {
        spell = { id = "necromancy", branch = "wastes" },
    })
    local markResult = markResolver:resolvePendingMaleficence(markedTarget, {
        record = markRecord,
        value = 8,
        allEntities = { markedTarget },
    })
    assertTrue(markResult.success, "Wastes VIII Undead Mark should resolve from table data")
    assertTrue(markedTarget.conditions.undead_mark, "Wastes VIII should mark Undead Mark")
    assertEqual(markedTarget.conditionDurations.undead_mark["until"], "cleansed",
        "Wastes VIII Undead Mark should last until cleansed")
    assertTrue(markedTarget.maleficenceConditionMetadata.undead_mark.invisibleForeheadMark,
        "Wastes VIII should preserve the invisible forehead mark")
    assertEqual(markedTarget.maleficenceConditionMetadata.undead_mark.undeadDesires[1], "talk",
        "Wastes VIII should preserve the undead desire list")
    selected = ai:selectTarget(zombie, { ordinaryTarget, markedTarget }, false)
    assertEqual(selected, markedTarget, "undead NPCs should prioritize Undead Mark targets")
    selected = ai:selectTarget(zombie, { ordinaryTarget, markedTarget }, true)
    assertEqual(selected, ordinaryTarget, "undead melee targeting should still require a same-zone marked target")

    local spirit = {
        id = "npc_targeting_spirit",
        name = "Targeting Spirit",
        zone = "near",
        tags = { "spirit" },
        conditions = {},
    }
    local haloTarget = base_entity.createEntity({
        id = "pc_halo_target",
        name = "Halo Target",
        isPC = true,
        pentacles = 5,
    })
    haloTarget.zone = "far"
    haloTarget.conditions = {}
    local haloRecord = markResolver:triggerMaleficence(haloTarget, "welkin", "smoke_test", {
        spell = { id = "heavenfire", branch = "welkin" },
    })
    local haloResult = markResolver:resolvePendingMaleficence(haloTarget, {
        record = haloRecord,
        value = 8,
        allEntities = { haloTarget },
    })
    assertTrue(haloResult.success, "Welkin VIII Halo should resolve from table data")
    assertTrue(haloTarget.conditions.halo, "Welkin VIII should mark Halo")
    assertTrue(haloTarget.maleficenceConditionMetadata.halo.browHalo,
        "Welkin VIII should preserve brow-halo metadata")
    assertTrue(haloTarget.maleficenceConditionMetadata.halo.spiritsReactNegatively,
        "Welkin VIII should preserve negative spirit reaction metadata")
    selected = ai:selectTarget(spirit, { ordinaryTarget, haloTarget }, false)
    assertEqual(selected, haloTarget, "spirit NPCs should prioritize Halo targets")
    selected = ai:selectTarget(zombie, { ordinaryTarget, haloTarget }, false)
    assertEqual(selected, ordinaryTarget, "non-spirit undead should not prioritize Halo by itself")

    local targetingWraith = entity_factory.createEntity("wraith")
    targetingWraith.id = "npc_light_avoiding_wraith"
    targetingWraith.zone = "near"
    local litTarget = base_entity.createEntity({
        id = "pc_lit_wraith_target",
        name = "Lit Wraith Target",
        isPC = true,
        pentacles = -4,
    })
    litTarget.zone = "near"
    litTarget.inventory = inventory.createInventory()
    litTarget.inventory:addItem(inventory.createItemFromTemplate("torch"), inventory.LOCATIONS.HANDS)
    local unlitTarget = base_entity.createEntity({
        id = "pc_unlit_wraith_target",
        name = "Unlit Wraith Target",
        isPC = true,
        pentacles = 4,
    })
    unlitTarget.zone = "near"
    selected = ai:selectTarget(targetingWraith, { litTarget, unlitTarget }, false)
    assertEqual(selected, unlitTarget,
        "Wraith NPCs should avoid adventurers carrying visible light sources when another target exists")
    selected = ai:selectTarget(targetingWraith, { litTarget }, false)
    assertEqual(selected, litTarget,
        "Wraith NPCs should still target a light-bearing adventurer when no other target exists")

    local socialTarget = base_entity.createEntity({
        id = "pc_authored_social_target",
        name = "Authored Social Target",
        isPC = true,
        pentacles = 2,
    })
    socialTarget.zone = "near"
    local socialNpc = {
        id = "npc_authored_social",
        name = "Authored Social NPC",
        zone = "near",
        conditions = {},
        preferredActions = {
            {
                id = "taunting_banter",
                type = action_resolver.ACTION_TYPES.BANTER,
                targetMode = "same_zone_pc",
                banterIntent = "taunt",
            },
        },
    }
    ai.hand = {
        { name = "The Star", value = 17, is_major = true },
        { name = "The Hermit", value = 9, is_major = true },
    }
    local socialDecision = ai:decide(socialNpc, { socialTarget })
    assertEqual(socialDecision.type, action_resolver.ACTION_TYPES.BANTER,
        "NPC AI should choose authored social Challenge actions before melee fallback")
    assertEqual(socialDecision.target, socialTarget,
        "authored NPC social actions should resolve a same-zone target")
    assertEqual(socialDecision.card.value, 9,
        "authored standard Challenge actions should spend a lesser doom")
    assertTrue(socialDecision.npcAIAuthoredAction,
        "authored NPC decisions should be marked for audit")

    local spellTarget = base_entity.createEntity({
        id = "pc_authored_spell_target",
        name = "Authored Spell Target",
        isPC = true,
    })
    spellTarget.zone = "far"
    local spellNpc = {
        id = "npc_authored_spell",
        name = "Authored Spell NPC",
        zone = "near",
        conditions = {},
        aiActions = {
            {
                id = "fear_spell",
                type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
                spellId = "fear",
                targetMode = "any_pc",
                resolveSpent = 1,
            },
        },
    }
    ai.hand = {
        { name = "The High Priestess", value = 2, is_major = true },
    }
    local spellDecision = ai:decide(spellNpc, { spellTarget })
    assertEqual(spellDecision.type, action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        "NPC AI should choose authored spellcasting actions")
    assertEqual(spellDecision.spellId, "fear", "authored NPC spell actions should preserve the spell id")
    assertEqual(spellDecision.target, spellTarget,
        "authored NPC spell actions should target the selected adventurer")

    local itemTarget = base_entity.createEntity({
        id = "pc_authored_item_target",
        name = "Authored Item Target",
        isPC = true,
    })
    itemTarget.zone = "near"
    local itemNpc = {
        id = "npc_authored_item",
        name = "Authored Item NPC",
        zone = "near",
        conditions = {},
        inventory = inventory.createInventory(),
        challengeActions = {
            {
                id = "throw_salt",
                type = action_resolver.ACTION_TYPES.USE_ITEM,
                targetMode = "same_zone_pc",
                itemTemplateId = "salt",
            },
        },
    }
    local salt = inventory.createItemFromTemplate("salt")
    itemNpc.inventory:addItem(salt, inventory.LOCATIONS.HANDS)
    ai.hand = {
        { name = "Temperance", value = 14, is_major = true },
    }
    local itemDecision = ai:decide(itemNpc, { itemTarget })
    assertEqual(itemDecision.type, action_resolver.ACTION_TYPES.USE_ITEM,
        "NPC AI should choose authored item-use actions")
    assertEqual(itemDecision.item, salt,
        "authored NPC item-use actions should attach the carried item")
    assertEqual(itemDecision.target, itemTarget,
        "authored NPC item-use actions should attach the selected target")
end

local function checkChallengeSurpriseAmbushActions()
    local procedure = challenge_controller.getChallengeProcedure()
    assertEqual(procedure.source, "Core Rules Chapter 7: Challenge Phase",
        "Challenge procedure metadata should cite the Chapter 7 source")
    assertEqual(#procedure.steps, 6, "Challenge procedure metadata should expose steps 0 through 5")
    assertEqual(procedure.roundValueRange.max, 14,
        "Challenge procedure metadata should preserve the King-high count-up range")
    assertEqual(procedure.loopSteps[1], 1,
        "Challenge procedure metadata should identify steps 1-5 as the repeated round loop")
    assertEqual(procedure.projectVariants[1].id, "minor_actions_declaration_order",
        "Challenge procedure metadata should document the intentional minor-action ordering variant")

    local sceneStep = challenge_controller.getChallengeStepDetails("set scene")
    assertEqual(sceneStep.index, 0, "set-scene step should be addressable by label alias")
    assertTrue(hasValue(sceneStep.presentationKeys, "sceneHazards"),
        "set-scene metadata should surface hazards for presentation")
    assertTrue(hasValue(sceneStep.responsibilities,
        "Clarify whether either side is surprised or has an ambush advantage."),
        "set-scene metadata should preserve surprise and ambush framing")

    local drawStep = challenge_controller.getChallengeStepDetails(1)
    assertEqual(drawStep.playerCards.count, 4,
        "draw-cards metadata should preserve the four-card player draw")
    assertEqual(drawStep.gmCards.deck, "major_arcana",
        "draw-cards metadata should preserve the GM major-arcana deck")
    assertTrue(hasValue(drawStep.cardsAreSpentOn, "minor actions"),
        "draw-cards metadata should list minor actions as a card use")

    local initiativeStep = challenge_controller.getChallengeStepDetails("initiative")
    assertTrue(initiativeStep.initiative.facedown,
        "Initiative metadata should preserve facedown Initiative")
    assertTrue(initiativeStep.initiative.sameTypeEnemiesShareCard,
        "Initiative metadata should preserve shared enemy Initiative")
    assertTrue(initiativeStep.initiative.significantEnemiesMayUseIndividualCards,
        "Initiative metadata should preserve significant enemy Initiative exceptions")

    local turnStep = challenge_controller.getChallengeStepDetails("count-up")
    assertEqual(turnStep.countRange.max, 14,
        "take-turns metadata should expose the Ace-to-King count range")
    assertTrue(turnStep.turnRules.skippedTurnsDoNotOpenMinorWindow,
        "take-turns metadata should preserve skipped-turn minor-window handling")

    local minorStep = challenge_controller.getChallengeStepDetails({ key = "minor_actions" })
    assertTrue(minorStep.minorRules.playerCardMustMatchSuit,
        "minor-action metadata should preserve player suit matching")
    assertTrue(minorStep.minorRules.valueUsesCardOnly,
        "minor-action metadata should preserve face-value-only minor totals")
    assertEqual(minorStep.projectVariant.id, "declaration_order_resolution",
        "minor-action metadata should expose the declaration-order variant")

    local endRoundStep = challenge_controller.getChallengeStepDetails("round end")
    assertTrue(endRoundStep.cleanup.facedownActionsRemainInPlay,
        "end-round metadata should preserve facedown action lifecycle")
    assertTrue(endRoundStep.cleanup.foolDrawsShuffleBothDecksBeforeNextDeal,
        "end-round metadata should preserve Fool reshuffle timing")

    procedure.steps[1].label = "mutated"
    assertEqual(challenge_controller.getChallengeProcedure().steps[1].label, "Set the scene",
        "Challenge procedure getter should return copy-safe metadata")

    local bus = events.createEventBus()
    local surpriseEvent = nil
    bus:on("challenge_surprise_resolved", function(data)
        surpriseEvent = data
    end)

    local controller = challenge_controller.createChallengeController({
        eventBus = bus,
    })

    local first = base_entity.createEntity({
        id = "pc_surprised_first",
        name = "Surprised First",
        isPC = true,
    })
    local second = base_entity.createEntity({
        id = "pc_surprised_second",
        name = "Surprised Second",
        isPC = true,
    })
    local ambusherA = base_entity.createEntity({
        id = "npc_ambusher_a",
        name = "Ambusher A",
        isPC = false,
        health = 1,
        defense = 0,
    })
    local ambusherB = base_entity.createEntity({
        id = "npc_ambusher_b",
        name = "Ambusher B",
        isPC = false,
        health = 1,
        defense = 0,
    })
    local ambusherC = base_entity.createEntity({
        id = "npc_ambusher_c",
        name = "Ambusher C",
        isPC = false,
        health = 1,
        defense = 0,
    })

    local ok, err = controller:startChallenge({
        pcs = { first, second },
        npcs = { ambusherA, ambusherB, ambusherC },
        surprised = true,
        surpriseActions = {
            { tactic = "shank" },
            { tactic = "shank" },
            { tactic = "shank" },
        },
    })
    assertTrue(ok, "surprised Challenge should start")
    assertTrue(surpriseEvent ~= nil, "surprised Challenge should emit surprise resolution details")
    assertEqual(#controller.surpriseResults, 3, "each GM character should receive one pre-Challenge surprise action")
    assertTrue(first.conditions.staggered, "first adventurer should take one surprise Wound")
    assertTrue(second.conditions.staggered, "second adventurer should take one surprise Wound")
    assertEqual(first:getWoundsTaken(), 1, "an adventurer should only be shanked once before Challenge")
    assertEqual(second:getWoundsTaken(), 1, "each available adventurer can be shanked once")
    assertTrue(hasValue(controller.surpriseResults[3].effects, "ambush_no_target"),
        "extra shank attackers should not wound an adventurer twice")
    assertEqual(controller.state, challenge_controller.STATES.PRE_ROUND,
        "Challenge should proceed to normal initiative after surprise actions")

    local resourceController = challenge_controller.createChallengeController({
        eventBus = events.createEventBus(),
    })
    local deprived = base_entity.createEntity({
        id = "pc_deprived",
        name = "Deprived PC",
        isPC = true,
    })
    local schemer = base_entity.createEntity({
        id = "npc_schemer",
        name = "Schemer",
        isPC = false,
        health = 1,
        defense = 0,
    })
    resourceController.pcs = { deprived }
    resourceController.npcs = { schemer }
    local resourceResults = resourceController:resolveSurpriseActions({
        npcs = { schemer },
        surpriseActions = {
            { tactic = "deprive_resources", target = deprived, resource = "disarm" },
        },
    })
    assertTrue(deprived.conditions.disarmed, "ambush tactic 2 should be able to deprive resources")
    assertTrue(hasValue(resourceResults[1].effects, "ambush_deprive_resources"),
        "resource deprivation should be reported as an ambush effect")

    local advantageResults = resourceController:resolveSurpriseActions({
        npcs = { schemer },
        surpriseActions = {
            { tactic = "create_advantage", advantage = "The bridge is collapsed." },
        },
    })
    assertTrue(hasValue(advantageResults[1].effects, "ambush_advantage"),
        "ambush tactic 1 should record created advantages")
    assertEqual(resourceController.sceneAdvantages[#resourceController.sceneAdvantages].description,
        "The bridge is collapsed.",
        "created ambush advantages should be retained for scene special rules")

    local sceneBus = events.createEventBus()
    local sceneRulesEvent = nil
    sceneBus:on("challenge_scene_rules_resolved", function(data)
        sceneRulesEvent = data
    end)
    local sceneController = challenge_controller.createChallengeController({
        eventBus = sceneBus,
    })
    local archer = base_entity.createEntity({
        id = "pc_scene_archer",
        name = "Scene Archer",
        isPC = true,
        swords = 0,
    })
    archer.zone = "deck"
    archer.ammo = 1
    archer.inventory = inventory.createInventory()
    local bow = inventory.createItemFromTemplate("bow")
    archer.inventory:addItem(bow, inventory.LOCATIONS.HANDS)
    local riggingClimber = base_entity.createEntity({
        id = "pc_scene_rigging_climber",
        name = "Scene Rigging Climber",
        isPC = true,
    })
    riggingClimber.zone = "deck"
    riggingClimber.inventory = inventory.createInventory()
    local climberDagger = inventory.createItemFromTemplate("dagger")
    riggingClimber.inventory:addItem(climberDagger, inventory.LOCATIONS.HANDS)
    local assassin = base_entity.createEntity({
        id = "npc_scene_assassin",
        name = "Scene Assassin",
        isPC = false,
        health = 1,
        defense = 0,
    })
    assassin.zone = "trees"
    local shortBlade = base_entity.createEntity({
        id = "pc_scene_short_blade",
        name = "Scene Short Blade",
        isPC = true,
        swords = 0,
    })
    shortBlade.zone = "idol"
    shortBlade.inventory = inventory.createInventory()
    local dagger = inventory.createItemFromTemplate("dagger")
    shortBlade.inventory:addItem(dagger, inventory.LOCATIONS.HANDS)
    local polearmUser = base_entity.createEntity({
        id = "pc_scene_polearm",
        name = "Scene Polearm",
        isPC = true,
        swords = 0,
    })
    polearmUser.zone = "idol"
    polearmUser.inventory = inventory.createInventory()
    local polearm = {
        id = "scene_test_polearm",
        name = "Scene Test Polearm",
        size = 2,
        weaponType = "polearm",
        isWeapon = true,
        isMelee = true,
        tags = { "polearm", "reach" },
    }
    polearmUser.inventory:addItem(polearm, inventory.LOCATIONS.HANDS)
    local idolImp = base_entity.createEntity({
        id = "npc_scene_idol_imp",
        name = "Scene Idol Imp",
        isPC = false,
        health = 2,
        defense = 0,
    })
    idolImp.tags = { "imp" }
    idolImp.zone = "idol"
    local sceneAuthoring = require('logic.challenge_scene_authoring')
    local authoredSceneConfig = {
        pcs = { archer, riggingClimber, shortBlade, polearmUser },
        npcs = { assassin, idolImp },
        zones = {
            { id = "deck", name = "Main Deck" },
            { id = "trees", name = "Ancient Trees" },
            { id = "idol", name = "Giant Idol" },
            { id = "gangway", name = "Blade Gangway" },
            { id = "chasm", name = "Rope Chasm" },
            { id = "rigging", name = "Ship Rigging" },
        },
        sceneSpecialRules = {
            {
                id = "ancient_tree_cover",
                zoneId = "trees",
                description = "The assassin darts between ancient trees.",
                disfavorActions = { action_resolver.ACTION_TYPES.MISSILE },
            },
            {
                id = "idol_climbers",
                zoneId = "idol",
                description = "Imps hang off the giant idol out of short-weapon reach.",
                actionTypes = { action_resolver.ACTION_TYPES.MELEE },
                targetTags = { "imp" },
                requiredWeaponTags = { "polearm" },
                blockReason = "Only polearms and missile weapons can reach the imps on the idol.",
            },
        },
        sceneHazards = {
            {
                id = "swinging_blades",
                zoneId = "gangway",
                description = "Swinging blades block the gangway.",
                requiredAction = action_resolver.ACTION_TYPES.AVOID,
                blockReason = "Must Avoid the swinging blades to pass.",
            },
            {
                id = "rope_chasm",
                zoneId = "chasm",
                description = "The chasm can only be descended safely by rope.",
                requiredAction = action_resolver.ACTION_TYPES.AVOID,
                requiredItemTags = { "rope" },
                blockReason = "Must use a rope to descend the chasm safely.",
            },
            {
                id = "rigging_climb",
                zoneId = "rigging",
                description = "Climbing into the rigging requires deft movement and empty hands.",
                actionTypes = { action_resolver.ACTION_TYPES.MOVE },
                requiredCardSuit = constants.SUITS.PENTACLES,
                requiresBothHandsFree = true,
                blockReason = "Must spend a Pentacles card and have both hands free to climb into the rigging.",
            },
        },
    }
    local sceneValidation = sceneAuthoring.validateChallengeScene(authoredSceneConfig, {
        requireIds = true,
    })
    assertTrue(sceneValidation.ok, "authored Challenge scene should validate before setup")
    assertEqual(sceneValidation.ruleCount, 2,
        "scene validation should count authored special rules")
    assertEqual(sceneValidation.hazardCount, 3,
        "scene validation should count authored hazards")
    local sceneChecklist = sceneAuthoring.createAuthoringChecklist(authoredSceneConfig, {
        requireIds = true,
    })
    assertTrue(sceneChecklist.complete,
        "authored Challenge scene checklist should pass for complete zone/rule/hazard data")
    local badSceneValidation = sceneAuthoring.validateChallengeScene({
        zones = {
            { id = "floor" },
        },
        sceneHazards = {
            {
                id = "blank_hazard",
                zoneId = "missing_zone",
            },
        },
    }, {
        requireIds = true,
    })
    assertTrue(not badSceneValidation.ok,
        "scene validation should reject hazards without description/effect and with unknown zones")
    assertEqual(badSceneValidation.errors[1].code, "description_missing",
        "scene validation should report missing player-facing hazard text")
    assertEqual(badSceneValidation.errors[2].code, "unknown_zone",
        "scene validation should report unknown zone references")

    ok, err = sceneController:startChallenge(authoredSceneConfig)
    assertTrue(ok, "Challenge setup should accept authored scene special rules")
    assertTrue(sceneRulesEvent ~= nil, "Challenge setup should emit authored scene rule details")
    assertEqual(sceneRulesEvent.sceneSpecialRules[1].id, "ancient_tree_cover",
        "Challenge setup should preserve authored scene rule ids")
    assertEqual(sceneRulesEvent.sceneHazards[1].id, "swinging_blades",
        "Challenge setup should preserve authored scene hazard ids")
    assertEqual(sceneRulesEvent.sceneHazards[2].id, "rope_chasm",
        "Challenge setup should preserve authored item-gated hazard ids")
    assertEqual(sceneRulesEvent.sceneHazards[3].id, "rigging_climb",
        "Challenge setup should preserve authored suit-and-hands hazard ids")
    assertEqual(sceneRulesEvent.zoneSpecialRules.trees[1].id, "ancient_tree_cover",
        "Challenge setup should index scene rules by zone")
    assertEqual(sceneRulesEvent.zoneSpecialRules.idol[1].id, "idol_climbers",
        "Challenge setup should index weapon-gated scene rules by zone")
    assertEqual(sceneRulesEvent.zoneSpecialRules.rigging[1].id, "rigging_climb",
        "Challenge setup should index suit-and-hands scene rules by zone")

    local sceneResolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
        challengeController = sceneController,
    })
    local coveredShot = sceneResolver:resolve({
        actor = archer,
        target = assassin,
        card = { name = "Seven of Swords", value = 7, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MISSILE,
        weapon = bow,
        targetInitiative = 6,
        challengeController = sceneController,
    })
    assertTrue(not coveredShot.success,
        "scene missile disfavor should be able to turn a near hit into a miss")
    assertEqual(coveredShot.favor, false, "scene missile disfavor should set action disfavor")
    assertEqual(coveredShot.favorModifier, -3, "scene missile disfavor should apply the standard -3 modifier")
    assertTrue(hasValue(coveredShot.effects, "scene_special_rule_disfavor"),
        "scene missile disfavor should report the scene rule effect")
    assertEqual(coveredShot.sceneRules[1].id, "ancient_tree_cover",
        "scene missile disfavor should expose the matching rule")

    local blockedMove = sceneResolver:resolve({
        actor = archer,
        card = { name = "Five of Pentacles", value = 5, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.MOVE,
        destinationZone = "gangway",
        challengeController = sceneController,
    })
    assertTrue(not blockedMove.success, "scene hazards should block ordinary movement when authored")
    assertEqual(blockedMove.description, "Must Avoid the swinging blades to pass.",
        "scene hazard movement block should preserve authored reason")
    assertTrue(hasValue(blockedMove.effects, "scene_special_rule_blocked"),
        "scene hazard movement block should report a scene-rule block")
    assertEqual(blockedMove.blockedSceneRule.id, "swinging_blades",
        "scene hazard movement block should expose the blocking rule")
    assertEqual(archer.zone, "deck", "blocked scene-hazard movement should leave the actor in place")

    local avoidedHazard = sceneResolver:resolve({
        actor = archer,
        card = { name = "Eight of Pentacles", value = 8, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.AVOID,
        destinationZone = "gangway",
        challengeController = sceneController,
    })
    assertTrue(avoidedHazard.success, "scene hazards should allow movement when the required action is used")
    assertEqual(archer.zone, "gangway", "required scene-hazard action should move the actor into the destination")
    archer.zone = "deck"

    local noRopeChasm = sceneResolver:resolve({
        actor = archer,
        card = { name = "Eight of Pentacles", value = 8, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.AVOID,
        destinationZone = "chasm",
        challengeController = sceneController,
    })
    assertTrue(not noRopeChasm.success, "scene item gates should block hazards when required gear is missing")
    assertEqual(noRopeChasm.description, "Must use a rope to descend the chasm safely.",
        "scene item gate should preserve authored block text")
    assertEqual(noRopeChasm.blockedSceneRule.id, "rope_chasm",
        "scene item gate should expose the blocking rule")

    local rope = inventory.createItemFromTemplate("rope")
    archer.inventory:addItem(rope, inventory.LOCATIONS.PACK)
    local ropeChasm = sceneResolver:resolve({
        actor = archer,
        card = { name = "Eight of Pentacles", value = 8, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.AVOID,
        destinationZone = "chasm",
        challengeController = sceneController,
    })
    assertTrue(ropeChasm.success, "scene item gates should allow hazards when required gear is carried")
    assertEqual(archer.zone, "chasm", "item-gated scene hazard should move the actor after the required action")
    assertEqual(ropeChasm.sceneRules[1].id, "rope_chasm",
        "scene item gate should report the satisfied scene rule")
    archer.zone = "deck"

    local occupiedHandsRigging = sceneResolver:resolve({
        actor = riggingClimber,
        card = { name = "Eight of Pentacles", value = 8, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.MOVE,
        destinationZone = "rigging",
        challengeController = sceneController,
    })
    assertTrue(not occupiedHandsRigging.success,
        "scene free-hands gates should block movement when hands are occupied")
    assertEqual(occupiedHandsRigging.description,
        "Must spend a Pentacles card and have both hands free to climb into the rigging.",
        "scene free-hands gate should preserve authored block text")
    assertEqual(occupiedHandsRigging.blockedSceneRule.id, "rigging_climb",
        "scene free-hands gate should expose the blocking rule")
    assertEqual(riggingClimber.zone, "deck",
        "blocked free-hands movement should leave the actor in place")

    riggingClimber.inventory:removeItem(climberDagger.id)
    local wrongSuitRigging = sceneResolver:resolve({
        actor = riggingClimber,
        card = { name = "Nine of Swords", value = 9, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MOVE,
        destinationZone = "rigging",
        challengeController = sceneController,
    })
    assertTrue(not wrongSuitRigging.success,
        "scene card-suit gates should block movement when the played card has the wrong suit")
    assertEqual(wrongSuitRigging.description,
        "Must spend a Pentacles card and have both hands free to climb into the rigging.",
        "scene card-suit gate should preserve authored block text")
    assertEqual(wrongSuitRigging.blockedSceneRule.id, "rigging_climb",
        "scene card-suit gate should expose the blocking rule")
    assertEqual(riggingClimber.zone, "deck",
        "blocked card-suit movement should leave the actor in place")

    local riggingMove = sceneResolver:resolve({
        actor = riggingClimber,
        card = { name = "Eight of Pentacles", value = 8, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.MOVE,
        destinationZone = "rigging",
        challengeController = sceneController,
    })
    assertTrue(riggingMove.success,
        "scene card-suit and free-hands gates should allow movement when both requirements are met")
    assertEqual(riggingClimber.zone, "rigging",
        "suit-and-hands-gated scene hazard should move the actor after requirements are met")
    assertEqual(riggingMove.sceneRules[1].id, "rigging_climb",
        "satisfied suit-and-hands scene gate should report the scene rule")
    riggingClimber.zone = "deck"

    local shortMelee = sceneResolver:resolve({
        actor = shortBlade,
        target = idolImp,
        card = { name = "Nine of Swords", value = 9, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        weapon = dagger,
        targetInitiative = 6,
        challengeController = sceneController,
    })
    assertTrue(not shortMelee.success,
        "scene weapon restrictions should block melee attacks without the required weapon tag")
    assertEqual(shortMelee.description, "Only polearms and missile weapons can reach the imps on the idol.",
        "scene weapon restriction should preserve authored block text")
    assertEqual(shortMelee.blockedSceneRule.id, "idol_climbers",
        "scene weapon restriction should expose the blocking rule")
    assertTrue(hasValue(shortMelee.effects, "scene_special_rule_blocked"),
        "scene weapon restriction should report a scene-rule block")

    local polearmMelee = sceneResolver:resolve({
        actor = polearmUser,
        target = idolImp,
        card = { name = "Nine of Swords", value = 9, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        weapon = polearm,
        targetInitiative = 6,
        challengeController = sceneController,
    })
    assertTrue(polearmMelee.success,
        "scene weapon restrictions should allow melee attacks with an authored required weapon tag")
    assertTrue(not hasValue(polearmMelee.effects, "scene_special_rule_blocked"),
        "allowed scene weapon attacks should not report a scene-rule block")

    local resistedBus = events.createEventBus()
    local resistedEvent = nil
    resistedBus:on("ambush_resisted", function(data)
        resistedEvent = data
    end)
    local resistedController = challenge_controller.createChallengeController({
        eventBus = resistedBus,
    })
    local watchful = base_entity.createEntity({
        id = "pc_watchful_ambusher",
        name = "Watchful Ambusher",
        isPC = true,
        talentWoundSlots = 0,
        talents = {
            ambusher = { mastered = true, wounded = false },
        },
    })
    watchful.resolve = 1
    local lurker = base_entity.createEntity({
        id = "npc_lurker",
        name = "Lurker",
        isPC = false,
        health = 1,
        defense = 0,
    })

    ok, err = resistedController:startChallenge({
        pcs = { watchful },
        npcs = { lurker },
        surprised = true,
        resistAmbushWithAmbusher = true,
        surpriseActions = {
            { tactic = "shank", target = watchful },
        },
    })
    assertTrue(ok, "Ambusher resistance challenge should start")
    assertTrue(resistedEvent ~= nil, "successful Ambusher resistance should emit a result")
    assertEqual(watchful.resolve, 0, "Ambusher resistance should spend one Resolve")
    assertTrue(resistedController.ambushResistance and resistedController.ambushResistance.success,
        "Ambusher resistance should be retained on the controller")
    assertTrue(not resistedController.surprised, "successful Ambusher resistance should cancel surprise")
    assertEqual(#resistedController.surpriseResults, 0,
        "successful Ambusher resistance should skip pre-Challenge surprise actions")
    assertEqual(watchful:getWoundsTaken(), 0, "resisted ambush should not wound the warning adventurer")
    assertEqual(resistedController.state, challenge_controller.STATES.PRE_ROUND,
        "Challenge should proceed to initiative after resisting ambush")

    local failedBus = events.createEventBus()
    local failedEvent = nil
    local unresolvedSurpriseEvent = nil
    failedBus:on("ambush_resistance_failed", function(data)
        failedEvent = data
    end)
    failedBus:on("challenge_surprise_resolved", function(data)
        unresolvedSurpriseEvent = data
    end)
    local failedController = challenge_controller.createChallengeController({
        eventBus = failedBus,
    })
    local brokeAmbusher = base_entity.createEntity({
        id = "pc_broke_ambusher",
        name = "Broke Ambusher",
        isPC = true,
        talentWoundSlots = 0,
        talents = {
            ambusher = { mastered = true, wounded = false },
        },
    })
    brokeAmbusher.resolve = 0
    local knife = base_entity.createEntity({
        id = "npc_knife",
        name = "Knife",
        isPC = false,
        health = 1,
        defense = 0,
    })

    ok, err = failedController:startChallenge({
        pcs = { brokeAmbusher },
        npcs = { knife },
        surprised = true,
        resistAmbushWithAmbusher = true,
        surpriseActions = {
            { tactic = "shank", target = brokeAmbusher },
        },
    })
    assertTrue(ok, "failed Ambusher resistance challenge should still start")
    assertTrue(failedEvent ~= nil, "failed Ambusher resistance should emit a failure result")
    assertTrue(hasValue(failedEvent.effects, "resolve_missing"),
        "failed Ambusher resistance should report missing Resolve")
    assertTrue(unresolvedSurpriseEvent ~= nil, "failed Ambusher resistance should leave surprise actions active")
    assertTrue(failedController.surprised, "failed Ambusher resistance should not clear surprise")
    assertEqual(#failedController.surpriseResults, 1,
        "failed Ambusher resistance should still resolve pre-Challenge surprise actions")
    assertTrue(brokeAmbusher.conditions.staggered,
        "failed Ambusher resistance should let the ambush shank wound the target")

    local promptBus = events.createEventBus()
    local promptController = challenge_controller.createChallengeController({
        eventBus = promptBus,
    })
    local promptAmbusher = base_entity.createEntity({
        id = "pc_prompt_ambusher",
        name = "Prompt Ambusher",
        isPC = true,
        talentWoundSlots = 0,
        talents = {
            ambusher = { mastered = true, wounded = false },
        },
    })
    promptAmbusher.resolve = 1
    local promptKnife = base_entity.createEntity({
        id = "npc_prompt_knife",
        name = "Prompt Knife",
        isPC = false,
        health = 1,
        defense = 0,
    })
    local promptInputState = {}
    local promptInput = challenge_input_controller.createChallengeInputController({
        gameState = {
            challengeController = promptController,
            guild = { promptAmbusher },
        },
        eventBus = promptBus,
        inputState = promptInputState,
    })
    promptInput:init()
    local promptOverlay = require('ui.challenge_overlay').createChallengeOverlay({
        gameState = {
            challengeController = promptController,
        },
        inputState = promptInputState,
    })
    local promptEvent = nil
    promptBus:on("ambusher_resistance_available", function(data)
        promptEvent = data
    end)

    ok, err = promptController:startChallenge({
        pcs = { promptAmbusher },
        npcs = { promptKnife },
        surprised = true,
        surpriseActions = {
            { tactic = "shank", target = promptAmbusher },
