    assertTrue(ok, "Ambusher resistance prompt challenge should start")
    assertTrue(promptEvent ~= nil, "eligible Ambusher should emit a start-of-challenge prompt")
    assertEqual(promptController.state, challenge_controller.STATES.AMBUSH_RESISTANCE,
        "eligible Ambusher should pause before surprise actions")
    assertTrue(promptInputState.pendingAmbusherResistance ~= nil,
        "Ambusher input prompt should retain pending candidates")
    local footerPrompt = promptOverlay:getFooterPrompt(promptController:getState())
    assertTrue(footerPrompt and footerPrompt:find("Ambusher", 1, true),
        "Challenge HUD should surface the Ambusher resistance prompt")
    promptInput:handleChallengeInput("r")
    assertEqual(promptAmbusher.resolve, 0,
        "Ambusher prompt should spend Resolve when elected")
    assertTrue(not promptController.surprised,
        "Ambusher prompt election should cancel surprise")
    assertEqual(#promptController.surpriseResults, 0,
        "Ambusher prompt election should skip surprise actions")
    assertEqual(promptController.state, challenge_controller.STATES.PRE_ROUND,
        "Ambusher prompt election should resume Challenge initiative")
    assertTrue(promptInputState.pendingAmbusherResistance == nil,
        "Ambusher prompt should clear after election")

    local skipBus = events.createEventBus()
