        "skipped Ambusher prompt should pause before surprise actions")
    skipInput:handleChallengeInput("space")
    assertTrue(skipController.ambushResistance and skipController.ambushResistance.skipped,
        "skipping Ambusher prompt should record the skipped election")
    assertTrue(skipController.surprised,
        "skipping Ambusher prompt should leave surprise active")
    assertEqual(#skipController.surpriseResults, 1,
        "skipping Ambusher prompt should resolve surprise actions")
    assertTrue(skipAmbusher.conditions.staggered,
        "skipping Ambusher prompt should let the ambush shank wound the target")
    assertEqual(skipController.state, challenge_controller.STATES.PRE_ROUND,
        "skipping Ambusher prompt should resume Challenge initiative")
end

local function checkActingEntityCannotMinor()
    local function hasAction(actions, id)
        for _, action in ipairs(actions or {}) do
            if action.id == id then
                return true
            end
        end
        return false
    end

    local controller = challenge_controller.createChallengeController({
        eventBus = events.createEventBus(),
    })
    local actor = base_entity.createEntity({
        id = "pc_active_minor",
        name = "Active Minor",
        isPC = true,
    })
    local ally = base_entity.createEntity({
        id = "pc_ally_minor",
        name = "Ally Minor",
        isPC = true,
    })
    controller.state = challenge_controller.STATES.MINOR_WINDOW
    controller.activeEntity = actor
    controller.pendingMinors = {}

    local ok, err = controller:declareMinorAction(actor,
        { name = "Five of Pentacles", value = 5, suit = constants.SUITS.PENTACLES },
        { type = action_resolver.ACTION_TYPES.DODGE })
    assertTrue(not ok, "acting entity should not be able to declare a minor action after their turn action")
    assertEqual(err, "acting_entity_cannot_minor", "active minor rejection should explain the rule")
    assertEqual(#controller.pendingMinors, 0, "rejected active-entity minor should not be queued")

    ok, err = controller:declareMinorAction(ally,
        { name = "Six of Pentacles", value = 6, suit = constants.SUITS.PENTACLES },
        { type = action_resolver.ACTION_TYPES.DODGE })
    assertTrue(ok, "other combatants should still be able to declare minor actions")
    assertEqual(err, nil, "accepted ally minor should not report an error")
    assertEqual(#controller.pendingMinors, 1, "accepted ally minor should be queued")

    ok, err = controller:declareMinorAction(ally,
        { name = "Seven of Pentacles", value = 7, suit = constants.SUITS.PENTACLES },
        { type = action_resolver.ACTION_TYPES.DODGE })
    assertTrue(not ok, "a combatant should not declare multiple minor actions in one window")
    assertEqual(err, "minor_action_already_declared",
        "duplicate minor rejection should explain the one-card window limit")
    assertEqual(#controller.pendingMinors, 1, "rejected duplicate minor should not be queued")

    local enemy = base_entity.createEntity({
        id = "npc_gm_major_minor",
        name = "GM Major Minor",
        isPC = false,
        health = 1,
        defense = 0,
    })
    local gmLesserDoom = major(7)
    assertTrue(hasAction(action_registry.getAvailableActions(gmLesserDoom, false, enemy),
        action_resolver.ACTION_TYPES.DODGE),
        "GM lesser dooms should ignore suit matching for ordinary minor Challenge Actions")

    ok, err = controller:declareMinorAction(enemy, gmLesserDoom, {
        type = action_resolver.ACTION_TYPES.DODGE,
    })
    assertTrue(ok, "GM lesser doom minor declarations should bypass suit matching")
    assertEqual(err, nil, "accepted GM lesser doom minor should not report an error")
    assertEqual(#controller.pendingMinors, 2, "accepted GM lesser doom minor should be queued")

    local gmGreaterDoom = major(18)
    assertTrue(not hasAction(action_registry.getAvailableActions(gmGreaterDoom, false, enemy),
        action_resolver.ACTION_TYPES.DODGE),
        "GM greater dooms should not list ordinary minor Challenge Actions")
    local greaterDoomEnemy = base_entity.createEntity({
        id = "npc_gm_greater_minor",
        name = "GM Greater Minor",
        isPC = false,
        health = 1,
        defense = 0,
    })
    ok, err = controller:declareMinorAction(greaterDoomEnemy, gmGreaterDoom, {
        type = action_resolver.ACTION_TYPES.DODGE,
    })
    assertTrue(not ok, "GM greater dooms should not declare ordinary minor Challenge Actions")
    assertEqual(err, "greater_doom_standard_action_blocked",
        "blocked GM greater-doom minor should explain ordinary-action legality")
    assertEqual(#controller.pendingMinors, 2, "rejected GM greater-doom minor should not be queued")

    local miscEnemy = base_entity.createEntity({
        id = "npc_gm_misc_minor",
        name = "GM Misc Minor",
        isPC = false,
        health = 1,
        defense = 0,
    })
    ok, err = controller:declareMinorAction(miscEnemy, major(8), {
        type = action_resolver.ACTION_TYPES.MOVE,
    })
    assertTrue(not ok, "GM major cards should not make miscellaneous actions into minor actions")
    assertEqual(err, "misc_not_allowed", "GM misc minor rejection should preserve the misc rule")
    assertEqual(#controller.pendingMinors, 2, "rejected GM misc minor should not be queued")

    local groupController = challenge_controller.createChallengeController({
        eventBus = events.createEventBus(),
    })
    local groupActive = base_entity.createEntity({
        id = "npc_group_active",
        name = "Group Active",
        isPC = false,
        health = 1,
        defense = 0,
    })
    groupActive.initiativeGroupId = "goblins"
    local groupMate = base_entity.createEntity({
        id = "npc_group_mate",
        name = "Group Mate",
        isPC = false,
        health = 1,
        defense = 0,
    })
    groupMate.initiativeGroupId = "goblins"
    groupController.state = challenge_controller.STATES.MINOR_WINDOW
    groupController.activeEntity = groupActive
    ok, err = groupController:declareMinorAction(groupMate, major(5), {
        type = action_resolver.ACTION_TYPES.DODGE,
    })
    assertTrue(not ok, "enemy groups should not minor after their own shared turn action")
    assertEqual(err, "acting_entity_cannot_minor",
        "active enemy group minor rejection should use the active-entity reason")

    local otherGroup = base_entity.createEntity({
        id = "npc_other_group",
        name = "Other Group",
        isPC = false,
        health = 1,
        defense = 0,
    })
    otherGroup.initiativeGroupId = "orcs"
    local otherGroupMate = base_entity.createEntity({
        id = "npc_other_group_mate",
        name = "Other Group Mate",
        isPC = false,
        health = 1,
        defense = 0,
    })
    otherGroupMate.initiativeGroupId = "orcs"
    ok, err = groupController:declareMinorAction(otherGroup, major(6), {
        type = action_resolver.ACTION_TYPES.DODGE,
    })
    assertTrue(ok, "other enemy groups should be able to declare a GM minor action")
    ok, err = groupController:declareMinorAction(otherGroupMate, major(7), {
        type = action_resolver.ACTION_TYPES.DODGE,
    })
    assertTrue(not ok, "one enemy group should only declare one minor action per window")
    assertEqual(err, "minor_action_already_declared",
        "duplicate enemy group minor rejection should use the duplicate reason")
    assertEqual(#groupController.pendingMinors, 1,
        "rejected duplicate enemy group minor should not be queued")
end

local function checkSkippedTurnBypassesMinorWindow()
    local bus = events.createEventBus()
    local minorWindows = 0
    local skippedTurn = nil
    bus:on(events.EVENTS.MINOR_ACTION_WINDOW, function()
        minorWindows = minorWindows + 1
    end)
    bus:on(events.EVENTS.CHALLENGE_TURN_END, function(data)
        if data.skipped then
            skippedTurn = data
        end
    end)

    local controller = challenge_controller.createChallengeController({
        eventBus = bus,
    })
    local skipper = base_entity.createEntity({
        id = "pc_skip_turn",
        name = "Skip Turn",
        isPC = true,
    })
    local nextActor = base_entity.createEntity({
        id = "pc_next_turn",
        name = "Next Turn",
        isPC = true,
    })

    controller.state = challenge_controller.STATES.AWAITING_ACTION
    controller.currentRound = 1
    controller.currentCount = 5
    controller.activeEntity = skipper
    controller.allCombatants = { skipper, nextActor }
    controller.initiativeSlots = {
        [skipper.id] = { card = { value = 5 }, value = 5, revealed = true },
        [nextActor.id] = { card = { value = 5 }, value = 5, revealed = false },
    }
    controller.actedThisRound = {}

    local ok, err = controller:skipTurn(skipper, "pass")
    assertTrue(ok, "active entity should be able to skip their turn")
    assertEqual(err, nil, "successful skip should not report an error")
    assertTrue(skippedTurn ~= nil, "skip should emit a skipped turn-end event")
    assertEqual(skippedTurn.reason, "pass", "skip event should preserve the reason")
    assertEqual(minorWindows, 0, "skipping should not open a minor-action window")
    assertTrue(controller.actedThisRound[skipper.id], "skipped entity should count as acted")
    assertEqual(controller.activeEntity, nextActor, "count-up should continue to the next same-count actor")
    assertEqual(controller.state, challenge_controller.STATES.AWAITING_ACTION,
        "next same-count actor should receive their turn after a skip")

    local autoBus = events.createEventBus()
    local autoMinorWindows = 0
    local autoSkippedTurn = nil
    autoBus:on(events.EVENTS.MINOR_ACTION_WINDOW, function()
        autoMinorWindows = autoMinorWindows + 1
    end)
    autoBus:on(events.EVENTS.CHALLENGE_TURN_END, function(data)
        if data.skipped then
            autoSkippedTurn = data
        end
    end)

    local emptyHandActor = base_entity.createEntity({
        id = "pc_no_cards_turn",
        name = "No Cards Turn",
        isPC = true,
    })
    local followingActor = base_entity.createEntity({
        id = "pc_after_no_cards",
        name = "After No Cards",
        isPC = true,
    })
    local hand = player_hand.createPlayerHand({
        eventBus = autoBus,
        guild = { emptyHandActor, followingActor },
    })
    hand.hands[emptyHandActor.id] = { cards = {} }
    hand.hands[followingActor.id] = {
        cards = {
            { name = "Six of Cups", value = 6, suit = constants.SUITS.CUPS },
        },
    }

    local autoController = challenge_controller.createChallengeController({
        eventBus = autoBus,
        playerHand = hand,
    })
    autoController.currentRound = 1
    autoController.currentCount = 5
    autoController.allCombatants = { emptyHandActor, followingActor }
    autoController.initiativeSlots = {
        [emptyHandActor.id] = { card = { value = 5 }, value = 5, revealed = false },
        [followingActor.id] = { card = { value = 5 }, value = 5, revealed = false },
    }

    autoController:startEntityTurn(emptyHandActor)
    assertTrue(autoSkippedTurn ~= nil, "active PCs with no Challenge cards should auto-skip")
    assertEqual(autoSkippedTurn.reason, "no_challenge_cards",
        "no-card auto-skip should report the rulebook reason")
    assertEqual(autoMinorWindows, 0, "no-card auto-skip should not open a minor-action window")
    assertTrue(autoController.actedThisRound[emptyHandActor.id],
        "no-card auto-skipped PCs should count as acted")
    assertEqual(autoController.activeEntity, followingActor,
        "no-card auto-skip should continue count-up to the next eligible actor")
    assertEqual(autoController.state, challenge_controller.STATES.AWAITING_ACTION,
        "following same-count actor with cards should still receive a normal turn")
end

function checkInitiativeTieDeclarationOrder()
    local controller = challenge_controller.createChallengeController({
        eventBus = events.createEventBus(),
    })
    local pc = base_entity.createEntity({
        id = "pc_tied_initiative",
        name = "Tied Initiative PC",
        isPC = true,
    })
    local npc = base_entity.createEntity({
        id = "npc_tied_initiative",
        name = "Tied Initiative NPC",
        isPC = false,
        health = 1,
        defense = 0,
    })

    controller.currentRound = 1
    controller.currentCount = 7
    controller.allCombatants = { pc, npc }
    controller.initiativeSlots = {
        [pc.id] = { card = { name = "Seven of Cups", value = 7 }, value = 7, revealed = false },
        [npc.id] = { card = { name = "The Chariot", value = 7 }, value = 7, revealed = false },
    }
    controller.actedThisRound = {}

    local defaultOrder = controller:getEntitiesAtCount(7)
    assertEqual(defaultOrder[1], pc,
        "same-Initiative default should preserve combatant order when no declaration order is supplied")

    local ok, err = controller:setInitiativeTieOrder(7, { npc.id, pc.id })
    assertTrue(ok, "controller should accept explicit tied-Initiative declaration order")
    assertEqual(err, nil, "valid tied-Initiative order should not report an error")

    local ordered = controller:getEntitiesAtCount(7)
    assertEqual(ordered[1], npc,
        "explicit tied-Initiative order should allow GM/NPC declaration before PC")
    assertEqual(ordered[2], pc,
        "explicit tied-Initiative order should retain the remaining tied actor")

    controller.activeEntity = npc
    controller:completeTurn()
    assertTrue(controller.actedThisRound[npc.id], "first tied actor should be marked acted")
    assertEqual(controller.activeEntity, pc,
        "same-count continuation should honor the remaining explicit tied-Initiative order")
    assertTrue(controller.initiativeSlots[pc.id].revealed,
        "continuing to the next tied actor should reveal their Initiative")

    local invalidOk, invalidErr = controller:setInitiativeTieOrder(7, "pc_first")
    assertTrue(not invalidOk, "invalid tied-Initiative order should be rejected")
    assertEqual(invalidErr, "invalid_tie_order",
        "invalid tied-Initiative order should explain the failure")
end

local function checkNPCNoActionSkipsTurn()
    local bus = events.createEventBus()
    local visualCompletes = 0
    bus:on(events.EVENTS.UI_SEQUENCE_COMPLETE, function()
        visualCompletes = visualCompletes + 1
    end)

    local skipped = nil
    local ai = npc_ai.createNPCAI({
        eventBus = bus,
        challengeController = {
            skipTurn = function(_, entity, reason)
                skipped = { entity = entity, reason = reason }
                return true
            end,
        },
    })
    local npc = {
        id = "npc_no_action",
        name = "No Action NPC",
        isPC = false,
        conditions = {},
    }

    ai:handleNPCTurn({ npc = npc, pcs = {} })
    assertTrue(skipped ~= nil, "NPC with no valid action should use the controller skip path")
    assertEqual(skipped.entity, npc, "NPC skip should identify the acting NPC")
    assertEqual(skipped.reason, "no_valid_action", "NPC skip should explain the no-action reason")
    assertEqual(visualCompletes, 0, "NPC no-action skip should not fake a visual-complete event")
end

local function checkDeathsDoorWatchExpiry()
    local bus = events.createEventBus()
    local defeatedEvents = {}
    bus:on(events.EVENTS.ENTITY_DEFEATED, function(payload)
        defeatedEvents[#defeatedEvents + 1] = payload
    end)

    local pc = base_entity.createEntity({
        id = "pc_death_door_watch",
        name = "Death Door Watch PC",
        isPC = true,
    })

    assertEqual(pc:takeWound("normal", { choice = "deaths_door", currentWatch = 0 }), "deaths_door",
        "Death's Door wound should accept the current watch marker")
    assertEqual(pc.deathDoorExpiresAtWatch, 1, "Death's Door should expire after one watch")

    local manager = watch_manager.createWatchManager({
        eventBus = bus,
        guild = { pc },
    })
    local watchResult = manager:incrementWatch()
    assertTrue(pc.conditions.dead, "unhealed Death's Door PC should die when a watch passes")
    assertTrue(not pc:isAlive(), "dead PCs should not report as alive")
    assertTrue(pc.deathDoorExpired, "watch expiry should mark the Death's Door expiry reason")
    assertEqual(#watchResult.deathDoorExpired, 1, "watch result should report expired Death's Door PCs")
    assertEqual(watchResult.deathDoorExpired[1], pc, "watch result should include the expired PC")
    assertEqual(#defeatedEvents, 1, "Death's Door expiry should emit an entity defeated event")
    assertEqual(defeatedEvents[1].reason, "death_door_expired", "defeated event should explain Death's Door expiry")
    assertEqual(pc.undeadRise.riseAtWatch, 2, "Death's Door expiry should schedule zombie rise for the next watch")
    local zombieWatchResult = manager:incrementWatch()
    assertEqual(#zombieWatchResult.undeadRaised, 1, "Death's Door corpse should rise on the following watch")
    assertEqual(zombieWatchResult.undeadRaised[1].blueprintId, "zombie", "Death's Door expiry should raise a zombie")

    local healed = base_entity.createEntity({
        id = "pc_death_door_healed_before_watch",
        name = "Death Door Healed PC",
        isPC = true,
    })
    healed:markDeathsDoor(0)
    local healResult = healed:healWound()
    assertEqual(healResult, "deaths_door_healed", "Heal effects should save Death's Door PCs")
    assertTrue(not healed.conditions.deaths_door, "healing should clear Death's Door")
    assertTrue(healed.conditions.stressed, "healing from Death's Door should mark Stressed")
    assertEqual(healed.deathDoorWatchStarted, nil, "healing should clear the Death's Door watch timer")
    assertEqual(healed.deathDoorExpiresAtWatch, nil, "healing should clear the Death's Door expiry watch")

    local healedManager = watch_manager.createWatchManager({
        eventBus = events.createEventBus(),
        guild = { healed },
    })
    healedManager:incrementWatch()
    assertTrue(not healed.conditions.dead, "healed Death's Door PCs should not expire on the next watch")
end

local function checkWatchDurationConditionExpiry()
    local bus = events.createEventBus()
    local expired = {}
    bus:on(events.EVENTS.CONDITION_EXPIRED, function(payload)
        expired[#expired + 1] = payload
    end)

    local pc = base_entity.createEntity({
        id = "pc_watch_condition",
        name = "Watch Condition PC",
        isPC = true,
    })
    pc.conditions.stunned = true
    pc.stunned = true
    pc.conditions.silenced = true
    pc.conditionDurations = {
        stunned = { duration = "watch" },
        silenced = { ["until"] = "fool_reshuffle" },
    }

    local manager = watch_manager.createWatchManager({
        eventBus = bus,
        guild = { pc },
    })
    local watchResult = manager:incrementWatch()

    assertTrue(not pc.conditions.stunned and not pc.stunned,
        "watch-duration conditions should clear when one watch passes")
    assertTrue(pc.conditions.silenced,
        "non-watch duration conditions should remain when a watch passes")
    assertTrue(pc.conditionDurations and pc.conditionDurations.silenced and not pc.conditionDurations.stunned,
        "watch expiry should remove only watch-duration metadata")
    assertEqual(#watchResult.conditionsExpired, 1,
        "watch result should report expired watch-duration conditions")
    assertEqual(watchResult.conditionsExpired[1].condition, "stunned",
        "watch result should name the expired watch-duration condition")
    assertEqual(#expired, 1, "watch-duration expiry should emit a condition-expired event")
    assertEqual(expired[1].watchNumber, 1, "condition-expired event should carry the watch number")
end

local function checkStartingGuildData()
    local guild = {}
    local byId = {}

    for _, pcData in ipairs(starting_guild.adventurers) do
        local pc = entity_factory.createAdventurer(pcData)
        guild[#guild + 1] = pc
        byId[pc.id] = pc
    end

    for _, bond in ipairs(starting_guild.bonds) do
        local source = byId[bond.from]
        local target = byId[bond.to]
        if source and target then
            source:setBond(target.id, bond.status)
        end
    end

    assertEqual(#guild, 4, "starter guild data should create four adventurers")
    assertEqual(guild[1].id, "grim", "starter guild should use stable data-authored ids")
    assertEqual(guild[1]:getTalentCount(), 1, "starter talents should be keyed data")
    assertTrue(guild[1]:isTalentMastered("aegis"), "Grim should keep mastered Aegis")
    assertTrue(not guild[3]:isTalentMastered("ritualist"), "Ember should keep Ritualist in training")
    assertEqual(guild[4].ammo, 10, "Fern should keep starting ammo")

    local grimWeapon = guild[1].inventory:getItems(inventory.LOCATIONS.HANDS)[1]
    assertEqual(grimWeapon.weaponType, "sword", "starter sword should retain weapon type metadata")
    assertTrue(grimWeapon.isMelee, "starter sword should be a melee weapon")
    local grimShield = guild[1].inventory:getItems(inventory.LOCATIONS.HANDS)[2]
    assertEqual(grimShield.name, "Light Shield", "Aegis starter should carry a shield")
    assertEqual(grimShield.durability, 1, "starter light shield should use rulebook Notch capacity")

    local grimBelt = guild[1].inventory:getItems(inventory.LOCATIONS.BELT)
    assertEqual(grimBelt[1].templateId, "torch", "starter torches should come from item templates")
    assertTrue(grimBelt[1].properties.light_source, "starter torch should keep template light metadata")

    local emberBelt = guild[3].inventory:getItems(inventory.LOCATIONS.BELT)
    assertEqual(emberBelt[1].templateId, "lantern", "starter lantern should come from item templates")
    assertTrue(emberBelt[1].properties.provides_belt_light,
        "starter lantern should keep template belt-light metadata")

    local fernWeapon = guild[4].inventory:getItems(inventory.LOCATIONS.HANDS)[1]
    assertEqual(fernWeapon.weaponType, "bow", "starter bow should retain weapon type metadata")
    assertTrue(fernWeapon.isRanged, "starter bow should be a ranged weapon")
    assertTrue(fernWeapon.uses_ammo, "starter bow should retain ammo metadata")

    local fernBelt = guild[4].inventory:getItems(inventory.LOCATIONS.BELT)
    assertEqual(fernBelt[2].templateId, "rations_3", "starter ration stack should come from item templates")
    assertEqual(fernBelt[2].quantity, 3, "starter ration stack should keep template quantity")

    assertEqual(starting_guild.restock.ammo.default, 10, "city restock ammo should be data-authored")
    assertEqual(starting_guild.restock.supplies[1].templateId, "torch",
        "city restock light source should be data-authored")
    assertEqual(starting_guild.restock.supplies[2].templateId, "rations_3",
        "city restock food should be data-authored")

    local restockPC = base_entity.createEntity({
        id = "pc_restock_data",
        name = "Restock Data",
        isPC = true,
    })
    restockPC.ammo = 0
    restockPC.inventory = inventory.createInventory()
    guild_restock.restockAdventurer(restockPC, starting_guild.restock)
    assertEqual(restockPC.ammo, 10, "city restock should use data-authored ammo defaults")

    local restockedTorch, torchLocation = restockPC.inventory:findItemByPredicate(function(item)
        return item.templateId == "torch"
    end)
    assertTrue(restockedTorch ~= nil, "city restock should add the data-authored light source")
    assertEqual(torchLocation, inventory.LOCATIONS.BELT, "city restock should place light in the data-authored slot")

    local restockedRations, rationLocation = restockPC.inventory:findItemByPredicate(function(item)
        return item.templateId == "rations_3"
    end)
    assertTrue(restockedRations ~= nil, "city restock should add the data-authored ration stack")
    assertEqual(restockedRations.quantity, 3, "city restock should keep ration template quantity")
    assertEqual(rationLocation, inventory.LOCATIONS.PACK, "city restock should place rations in the data-authored slot")

    guild_restock.restockAdventurer(restockPC, starting_guild.restock)
    assertEqual(restockPC.inventory:countItemsByPredicate(function(item)
        return item.properties and item.properties.light_source
    end), 1, "city restock should not duplicate an existing light source")
    assertEqual(restockPC.inventory:countItemsByPredicate(function(item)
        return item.isRation
    end), 3, "city restock should not duplicate existing rations")

    assertEqual(guild[1]:getBond("whisper").status, "rivalry", "starter rivalry bond should be data-authored")
    assertEqual(guild[3]:getBond("fern").status, "friendship", "starter friendship bond should be data-authored")
end

function checkSessionRecapResolveAward()
    local session_flow = require('logic.session_flow')
    local sessionProcedure = session_flow.getSessionFlowProcedure()
    assertEqual(sessionProcedure.beforePlay[1].key, "recap",
        "Session Flow procedure should expose Recap as the first before-play step")
    assertEqual(sessionProcedure.beforePlay[1].award.amount, 1,
        "Session Flow procedure should preserve the exceptional recap Resolve award")
    assertEqual(sessionProcedure.beforePlay[2].missedPhase, "crawl",
        "Session Flow procedure should preserve the returning-player Crawl-only rule")
    assertTrue(hasValue(sessionProcedure.beforePlay[2].assistantRequiredFor, "Train"),
        "Session Flow procedure should preserve returning-player assistant requirements")
    assertEqual(session_flow.getSessionFlowProcedure("endOfPlay").key, "end_of_play",
        "Session Flow procedure helper should return named sections")
    sessionProcedure.beforePlay[1].label = "Changed recap"
    assertEqual(session_flow.getSessionFlowProcedure().beforePlay[1].label, "Recap",
        "Session Flow procedure helper should return copy-safe metadata")

    local duringPlayOptions = session_flow.getDuringPlayOptions({
        campaign = {
            currentPhase = "city",
            currentQuest = "Recover the missing contract seal",
            currentContract = {
                id = "baron_orphic_map",
                title = "Map Baron Orphic's cistern",
            },
        },
        completedSteps = { "pursue_quest", "crawl", "challenge", "camp" },
    })
    assertEqual(duringPlayOptions.currentStep, "city",
        "during-play options should normalize current phase into the rulebook loop")
    assertEqual(duringPlayOptions.selectedOption.label, "Return to the City",
        "during-play options should expose the selected loop step")
    assertEqual(duringPlayOptions.nextStep, "contract",
        "during-play options should preview the next rulebook loop step")
    assertTrue(duringPlayOptions.options[4].completed,
        "during-play options should preserve completed loop-step flags")
    assertTrue(duringPlayOptions.hasCurrentQuest,
        "during-play options should preserve current-quest context")
    assertTrue(duringPlayOptions.hasContract,
        "during-play options should preserve current-contract context")
    assertTrue(not duringPlayOptions.options[7].disabled,
        "during-play options should allow descending while a current quest exists")
    duringPlayOptions.procedure[1].label = "Changed loop"
    assertEqual(session_flow.getSessionFlowProcedure("duringPlay")[1].label,
        "Decide to pursue one adventurer's quest",
        "during-play options should return copy-safe procedure metadata")

    local noQuestLoopOptions = session_flow.getDuringPlayOptions({
        currentStep = "pursue_quest",
    })
    assertTrue(noQuestLoopOptions.options[1].disabled,
        "during-play options should flag missing quest selection context")
    assertEqual(noQuestLoopOptions.options[1].unavailableReason, "Current quest required",
        "during-play options should explain current-quest gates")
    assertTrue(noQuestLoopOptions.options[7].disabled,
        "during-play options should block descent without a current quest")

    local recapper = entity_factory.createAdventurer({
        id = "pc_recap_reader",
        name = "Recap Reader",
    })
    local recipient = entity_factory.createAdventurer({
        id = "pc_recap_recipient",
        name = "Recap Recipient",
    })
    recapper.resolve.current = 2
    recipient.resolve.current = 1

    local campaign = {}
    local beforePlayOptions = session_flow.getBeforePlayOptions({
        campaign = campaign,
        participants = { recapper, recipient },
        recapper = recapper,
        exceptional = true,
        summary = "The guild escaped the cistern shrine and still owes Baron Orphic a map.",
        helpers = { recipient },
        gmCorrections = { "The brass key was lost in the shrine, not recovered." },
        currentPhase = "crawl",
        currentLocation = "cistern shrine",
        currentObjective = "Find the missing contract seal",
    })
    assertEqual(beforePlayOptions.recapOptions.resultPreview, "recap_resolve_awarded",
        "before-play options should preview exceptional recap awards")
    assertEqual(beforePlayOptions.recapOptions.award.projectedResolve, 3,
        "before-play options should preview the capped recap Resolve award")
    assertTrue(beforePlayOptions.recapOptions.hasTableHelp,
        "before-play options should preview table help for recaps")
    assertTrue(beforePlayOptions.recapOptions.hasGmCorrections,
        "before-play options should preview GM recap corrections")
    assertEqual(beforePlayOptions.recapOptions.memoryPreview.location, "cistern shrine",
        "before-play options should preview the refreshed session location")
    assertEqual(recapper.resolve.current, 2,
        "before-play recap options should not mutate Resolve before recording")

    local ok, result, detail = session_flow.resolveRecap({
        campaign = campaign,
        recapper = recapper,
        exceptional = true,
        summary = "The guild escaped the cistern shrine and still owes Baron Orphic a map.",
        helpers = { recipient },
        gmCorrections = { "The brass key was lost in the shrine, not recovered." },
        currentPhase = "crawl",
        currentLocation = "cistern shrine",
        currentObjective = "Find the missing contract seal",
    })
    assertTrue(ok, "exceptional recap should resolve")
    assertEqual(result, "recap_resolve_awarded", "exceptional recap should award Resolve")
    assertEqual(recapper.resolve.current, 3, "exceptional recapper should be able to keep the Resolve")
    assertEqual(detail.resolve.applied, 1, "recap detail should report the applied Resolve")
    assertTrue(detail.hasTableHelp, "recap detail should record help from others at the table")
    assertTrue(detail.hasGmCorrections, "recap detail should record GM corrections")
    assertEqual(campaign.campaignLog.sessionRecaps[1], detail,
        "before-play recap should append to the campaign log")
    assertEqual(campaign.lastSessionRecap, detail,
        "before-play recap should expose the latest recap on campaign state")
    assertEqual(campaign.currentSessionMemory.location, "cistern shrine",
        "before-play recap should refresh the current session location")

    ok, result, detail = session_flow.resolveRecap({
        recapper = recapper,
        recipient = recipient,
        goodRecap = true,
    })
    assertTrue(ok, "exceptional recap should allow giving Resolve away")
    assertEqual(result, "recap_resolve_awarded", "given recap Resolve should report the award")
    assertEqual(recapper.resolve.current, 3, "giving recap Resolve away should not heal the recapper")
    assertEqual(recipient.resolve.current, 2, "recap Resolve should be grantable to another adventurer")
    assertEqual(detail.recipientId, "pc_recap_recipient", "recap detail should record the Resolve recipient")

    ok, result, detail = session_flow.resolveRecap({
        recapper = recapper,
    })
    assertTrue(ok, "ordinary recap should still record")
    assertEqual(result, "recap_recorded", "ordinary recap should not award Resolve")
    assertEqual(recapper.resolve.current, 3, "ordinary recap should leave Resolve unchanged")
    assertTrue(detail.exceptional == false, "ordinary recap detail should record that no award was made")

    local returning = entity_factory.createAdventurer({
        id = "pc_returning_player",
        name = "Returning Player",
    })
    local absentHelper = entity_factory.createAdventurer({
        id = "pc_returning_helper",
        name = "Returning Helper",
    })
    local lonelyReturn = entity_factory.createAdventurer({
        id = "pc_returning_lonely",
        name = "Lonely Returning Player",
    })
    local missingHelperOptions = session_flow.getBeforePlayOptions({
        actor = lonelyReturn,
        phase = "crawl",
        action = "train",
    })
    assertTrue(not missingHelperOptions.returningPlayerOptions.canMarkAbsent,
        "before-play options should preview missing helper blocks for returning players")
    assertEqual(missingHelperOptions.returningPlayerOptions.unavailableReason, "Assistant adventurer required",
        "before-play options should explain returning-player helper requirements")
    assertTrue(missingHelperOptions.returningPlayerOptions.selectedCampAction.requiresAssistant,
        "before-play options should flag Camp Actions that require an absent helper")
    assertTrue(lonelyReturn.absentFromCrawl ~= true,
        "returning-player options should not mutate absence state")

    local missingHelper
    missingHelper, result = session_flow.markAbsentFromCrawl({
        actor = lonelyReturn,
        action = "train",
    })
    assertTrue(not missingHelper,
        "returning-player bookkeeping should reject Camp Actions that need an absent helper")
    assertEqual(result, "Assistant adventurer required",
        "returning-player helper requirements should explain the missing adventurer")
    assertTrue(lonelyReturn.absentFromCrawl ~= true,
        "failed returning-player absence records should not mark the actor absent")

    local cityAbsence = entity_factory.createAdventurer({
        id = "pc_returning_city_absence",
        name = "Returning City Absence",
        path = "Squire",
    })
    local cityAbsenceOptions = session_flow.getBeforePlayOptions({
        actor = cityAbsence,
        phase = "city",
        action = "fletch_arrows",
    })
    assertTrue(not cityAbsenceOptions.returningPlayerOptions.phaseValid,
        "before-play options should preview that returning-player absence only applies to Crawl sessions")
    assertEqual(cityAbsenceOptions.returningPlayerOptions.unavailableReason, "Crawl Phase absence required",
        "before-play options should explain non-Crawl absence previews")
    assertTrue(cityAbsence.absentFromCrawl ~= true,
        "non-Crawl returning-player options should not mutate absence state")

    local cityAbsenceOk
    cityAbsenceOk, result = session_flow.markAbsentFromCrawl({
        actor = cityAbsence,
        phase = "city",
        action = "fletch_arrows",
    })
    assertTrue(not cityAbsenceOk, "returning-player trailing rule should only apply to missed Crawl sessions")
    assertEqual(result, "Crawl Phase absence required",
        "non-Crawl missed sessions should explain the Crawl Phase prerequisite")
    assertTrue(cityAbsence.absentFromCrawl ~= true,
        "non-Crawl missed sessions should not mark the actor trailing behind the guild")

    returning.inventory = inventory.createInventory()
    returning.inventory:addItem(inventory.createItemFromTemplate("bow"), inventory.LOCATIONS.HANDS)
    returning.ammo = 0
    local returningOptions = session_flow.getBeforePlayOptions({
        actor = returning,
        guild = { returning, absentHelper },
        phase = "crawl",
        action = "fletch_arrows",
        helper = absentHelper,
    })
    assertTrue(returningOptions.returningPlayerOptions.canMarkAbsent,
        "before-play options should preview valid missed-Crawl absence records")
    assertEqual(returningOptions.returningPlayerOptions.resultPreview, "adventurer_absent_from_crawl",
        "before-play options should preview the absence bookkeeping result")
    assertEqual(returningOptions.returningPlayerOptions.selectedCampAction.id, "fletch_arrows",
        "before-play options should preserve the selected returning-player Camp Action")
    assertTrue(not returningOptions.returningPlayerOptions.selectedCampAction.disabled,
        "before-play options should mark available returning-player Camp Actions ready")
    assertEqual(returning.ammo, 0,
        "returning-player options should not resolve Camp Action benefits")

    ok, result, detail = session_flow.markAbsentFromCrawl({
        actor = returning,
        phase = "crawl",
        action = "fletch_arrows",
        helper = absentHelper,
    })
    assertTrue(ok, "missed Crawl sessions should record the absent adventurer")
    assertEqual(result, "adventurer_absent_from_crawl", "absence helper should report the trailing state")
    assertEqual(detail.phase, "crawl", "absence helper should record the missed Crawl phase")
    assertEqual(returning.distanceRoomsFromGuild, 1,
        "absent returning players should be about one room behind the guild")
    assertTrue(returning.trailingBehindGuild == true, "absent returning players should trail the main guild")
    assertTrue(absentHelper.absentFromCrawl == true,
        "helper adventurers should be marked absent when they support the missed-session action")

    local rejoinOptions = session_flow.getBeforePlayOptions({
        actor = returning,
        guild = { returning },
    })
    assertTrue(rejoinOptions.returningPlayerOptions.canResolveReturningCampAction,
        "before-play options should preview ready returning-player Camp Action resolution")
    assertEqual(rejoinOptions.returningPlayerOptions.resultPreview, "returning_player_camp_action_resolved",
        "before-play options should preview the returning-player rejoin result")
    assertEqual(returning.ammo, 0,
        "returning-player rejoin options should not apply pending Camp Action benefits")

    ok, result, detail = session_flow.resolveReturningPlayerCampAction({
        actor = returning,
        guild = { returning },
        eventBus = events.createEventBus(),
    })
    assertTrue(ok, "returning players should resolve a Camp Action benefit")
    assertEqual(result, "returning_player_camp_action_resolved",
        "returning player helper should report the rejoin result")
    assertEqual(returning.ammo, 12, "returning player Camp Action should apply its normal benefit")
    assertTrue(returning.absentFromCrawl == false, "returning player should rejoin the Crawl after the action")
    assertTrue(absentHelper.absentFromCrawl == false,
        "helper adventurers should rejoin with the returning player by default")
    assertEqual(detail.campResult, "ammo_refilled",
        "returning player detail should preserve the delegated Camp Action result")

    local fellowshipReturn = base_entity.createEntity({
        id = "pc_returning_fellowship",
        name = "Returning Fellowship",
        isPC = true,
    })
    local fellowshipHelper = base_entity.createEntity({
        id = "pc_returning_fellowship_helper",
        name = "Returning Fellowship Helper",
        isPC = true,
    })
    ok, result = session_flow.markAbsentFromCrawl({
        actor = fellowshipReturn,
        action = "fellowship",
        assistant = fellowshipHelper,
    })
    assertTrue(ok, "returning Fellowship should record the required absent helper")
    ok, result, detail = session_flow.resolveReturningPlayerCampAction({
        actor = fellowshipReturn,
        guild = { fellowshipReturn },
        eventBus = events.createEventBus(),
    })
    assertTrue(ok, "returning Fellowship should resolve through the stored helper")
    assertEqual(result, "returning_player_camp_action_resolved",
        "returning Fellowship should report the rejoin result")
    assertEqual(detail.action.target, fellowshipHelper,
        "returning Fellowship should infer the stored assistant as the action target")
    assertTrue(fellowshipReturn.bonds[fellowshipHelper.id].charged,
        "returning Fellowship should charge the actor's Bond with the helper")
    assertTrue(fellowshipHelper.bonds[fellowshipReturn.id].charged,
        "returning Fellowship should charge the helper's Bond with the actor")
    assertTrue(fellowshipHelper.absentFromCrawl == false,
        "returning Fellowship helper should rejoin with the returning player")

    local trainReturn = base_entity.createEntity({
        id = "pc_returning_train",
        name = "Returning Train",
        isPC = true,
    })
    trainReturn.path = "pentacles"
    trainReturn.xp = 2
    trainReturn.talents = {}
    local trainHelper = base_entity.createEntity({
        id = "pc_returning_train_helper",
        name = "Returning Train Helper",
        isPC = true,
    })
    trainHelper.talents = {
        war_stories = { mastered = true },
    }
    ok, result = session_flow.markAbsentFromCrawl({
        actor = trainReturn,
        action = {
            type = "train",
            talentId = "war_stories",
            xp = 2,
        },
        assistant = trainHelper,
    })
    assertTrue(ok, "returning Train should record the required absent trainer")
    ok, result, detail = session_flow.resolveReturningPlayerCampAction({
        actor = trainReturn,
        guild = { trainReturn },
        eventBus = events.createEventBus(),
    })
    assertTrue(ok, "returning Train should resolve through the stored trainer")
    assertEqual(detail.action.target, trainHelper,
        "returning Train should infer the stored assistant as the trainer")
    assertEqual(trainReturn.xp, 0, "returning Train should spend the trainee's invested XP")
    assertTrue(trainReturn.talents.war_stories ~= nil,
        "returning Train should create the trained talent record")
    assertEqual(trainReturn.talents.war_stories.xp_invested, 2,
        "returning Train should preserve the invested XP amount")
    assertTrue(trainHelper.absentFromCrawl == false,
        "returning Train helper should rejoin with the returning player")
end

function checkSessionEndOfPlayBookkeeping()
    local session_flow = require('logic.session_flow')
    local onboarding = session_flow.getNewAdventurerOnboarding()
    assertTrue(hasValue(onboarding.priorToFirstSession, "Omphalic Market gear chosen"),
        "new adventurer onboarding metadata should preserve the starting gear checklist")
    assertTrue(hasValue(onboarding.firstSession, "select two players with whom the adventurer has Bonds"),
        "new adventurer onboarding metadata should preserve the first-session Bond selection")
    assertTrue(hasValue(onboarding.endOfSecondSession, "join the current quest and gain 3 XP"),
        "new adventurer onboarding metadata should preserve the second-session quest XP branch")
    onboarding.firstSession[1] = "changed"
    assertEqual(session_flow.getNewAdventurerOnboarding().firstSession[1],
        "select two players with whom the adventurer has Bonds",
        "new adventurer onboarding metadata should be copy-safe")

    local campaign = {}
    local endOptions = session_flow.getEndOfPlayOptions({
        campaign = campaign,
        phase = "crawl",
        specifiedTime = "22:00",
        stoppedAtSpecifiedTime = true,
        sceneJustEnded = true,
        nextSceneTeaser = "The brass gate opens onto the drowned chapel.",
        feedback = {
            "Where do you want to go next?",
            "Which loose thread matters most?",
        },
        playerPriorities = { "recover the contract seal", "avoid the drowned chapel patrol" },
        desiredDestinations = { "drowned chapel" },
        nextSession = "2026-05-21 19:00",
        expectedAbsences = { "Whisper" },
    })
    assertEqual(endOptions.resultPreview, "end_of_play_recorded",
        "end-of-play options should preview the closure record result")
    assertTrue(endOptions.closedAtStoppingPoint,
        "end-of-play options should preview rulebook stopping-point guidance")
    assertEqual(endOptions.closeReasonPreview, "specified_time",
        "end-of-play options should preview timed closure reasons")
    assertTrue(endOptions.hasFeedbackPrompt,
        "end-of-play options should preview feedback prompts")
    assertTrue(endOptions.hasNextDirectionFeedback,
        "end-of-play options should preview what players want to do and where they want to go")
    assertTrue(endOptions.hasNextSessionReminder,
        "end-of-play options should preview next-session reminder details")
    assertEqual(endOptions.promptOptions[1].prompt, "what players want to do next",
        "end-of-play options should preserve rulebook feedback prompt metadata")
    assertEqual(endOptions.nextSessionAgendaPreview.destinations[1], "drowned chapel",
        "end-of-play options should preview next-session agenda state")
    assertEqual(endOptions.nextSessionReminderPreview.expectedAbsences[1], "Whisper",
        "end-of-play options should preview expected absences")
    assertTrue(campaign.campaignLog == nil,
        "end-of-play options should not append campaign log state before recording")

    local ok, result, detail = session_flow.recordEndOfPlay({
        campaign = campaign,
        phase = "crawl",
        specifiedTime = "22:00",
        stoppedAtSpecifiedTime = true,
        sceneJustEnded = true,
        nextSceneTeaser = "The brass gate opens onto the drowned chapel.",
        feedback = {
            "Where do you want to go next?",
            "Which loose thread matters most?",
        },
        playerPriorities = { "recover the contract seal", "avoid the drowned chapel patrol" },
        desiredDestinations = { "drowned chapel" },
        nextSession = "2026-05-21 19:00",
        expectedAbsences = { "Whisper" },
    })
    assertTrue(ok, "end-of-play helper should record session closure")
    assertEqual(result, "end_of_play_recorded", "end-of-play helper should report closure result")
    assertTrue(detail.closedAtStoppingPoint,
        "ending after a scene or teaser should count as a good stopping point")
    assertEqual(detail.closeReason, "specified_time", "timed end-of-play closures should record their reason")
    assertTrue(detail.hasFeedbackPrompt, "end-of-play helper should preserve feedback prompts")
    assertTrue(detail.hasNextDirectionFeedback,
        "end-of-play helper should preserve what players want to do or where they want to go next")
    assertTrue(detail.hasNextSessionReminder, "end-of-play helper should preserve next-session reminders")
    assertEqual(campaign.campaignLog.sessionClosures[1], detail,
        "end-of-play helper should append to the campaign log")
    assertEqual(campaign.lastSessionClosure, detail,
        "end-of-play helper should expose the last closure on campaign state")
    assertEqual(campaign.nextSessionReminder.expectedAbsences[1], "Whisper",
        "end-of-play reminders should preserve expected absences")
    assertEqual(campaign.nextSessionAgenda.destinations[1], "drowned chapel",
        "end-of-play agenda should carry desired destinations into next session")

    local readyNewcomer
    readyNewcomer, result = entity_factory.createCallToAdventureAdventurer({
        id = "pc_pre_first_session_ready",
        name = "Pre First Ready",
        kin = "human",
        kith = "human",
        path = "swords",
        fittingInAttribute = "wands",
        failedCareerAttribute = "cups",
        firstAdventureAttribute = "pentacles",
        masteredPathTalent = "aegis",
        motifs = {
            "Veteran Smith",
            "Penitent Grave Robber",
            "Young Explorer",
        },
        quest = "Find the green reliquary",
        appearance = "A careful swordswoman with a green reliquary sketch.",
        languages = { "vulgaris", "cant" },
    })
    assertTrue(readyNewcomer ~= nil, "pre-first-session check should start from a valid new adventurer sheet")
    readyNewcomer.startingGearSelected = true
    readyNewcomer.startingGearSelection = { complete = true }
    local readyOnboardingOptions = session_flow.getNewAdventurerOnboardingOptions({
        actor = readyNewcomer,
    })
    assertTrue(readyOnboardingOptions.priorToFirstSession.readyForFirstSession,
        "new adventurer onboarding options should preview first-session readiness")
    assertEqual(readyOnboardingOptions.priorToFirstSession.resultPreview,
        "new_adventurer_pre_first_session_ready",
        "new adventurer onboarding options should preview complete pre-first-session state")
    assertTrue(readyOnboardingOptions.priorToFirstSession.kinTalentWritten,
        "new adventurer onboarding options should preview written kin talent state")
    assertTrue(readyOnboardingOptions.priorToFirstSession.sevenPathTalentsWritten,
        "new adventurer onboarding options should preview all seven path talents")
    assertEqual(readyOnboardingOptions.priorToFirstSession.masteredPathTalent, "aegis",
        "new adventurer onboarding options should preview the mastered path talent")
    assertTrue(readyNewcomer.newAdventurerPreFirstSession == nil,
        "new adventurer onboarding options should not persist pre-first-session records")

    ok, result, detail = session_flow.recordNewAdventurerPreFirstSession({
        campaign = campaign,
        actor = readyNewcomer,
    })
    assertTrue(ok, "new adventurer pre-first-session helper should record checklist readiness")
    assertEqual(result, "new_adventurer_pre_first_session_recorded",
        "new adventurer pre-first-session helper should report its checklist result")
    assertTrue(detail.nameKnown, "pre-first-session checklist should verify the adventurer knows their name")
    assertTrue(detail.kinTalentWritten, "pre-first-session checklist should verify the kin talent is written")
    assertTrue(detail.sevenPathTalentsWritten,
        "pre-first-session checklist should verify all seven path talents are written")
    assertTrue(detail.masteredOnePathTalent,
        "pre-first-session checklist should verify exactly one path talent is mastered")
    assertTrue(detail.restInTraining,
        "pre-first-session checklist should verify the other path talents remain in training")
    assertTrue(detail.gearReady, "pre-first-session checklist should verify Omphalic Market gear readiness")
    assertTrue(detail.readyForFirstSession,
        "complete pre-first-session checklist records should be ready for first session")
    assertEqual(campaign.campaignLog.newAdventurerPreFirstSessions[1], detail,
        "pre-first-session helper should append to the campaign log")

    local unreadyNewcomer = base_entity.createEntity({
        id = "pc_pre_first_session_unready",
        name = "",
        isPC = true,
        talents = {
            proud_and_ancient = { mastered = true, trainingKind = "kin" },
            aegis = { mastered = true, trainingKind = "path" },
        },
    })
    local unreadyOptions = session_flow.getNewAdventurerOnboardingOptions({
        actor = unreadyNewcomer,
        pathTalents = { "aegis" },
    })
    assertTrue(unreadyOptions.priorToFirstSession.needsFollowup,
        "new adventurer onboarding options should flag incomplete pre-first-session checklists")
    assertTrue(hasValue(unreadyOptions.priorToFirstSession.missing, "name"),
        "new adventurer onboarding options should preview missing names")
    assertTrue(hasValue(unreadyOptions.priorToFirstSession.missing, "seven_path_talents"),
        "new adventurer onboarding options should preview missing path talents")
    assertTrue(hasValue(unreadyOptions.priorToFirstSession.missing, "omphalic_market_gear"),
        "new adventurer onboarding options should preview missing gear")

    ok, result, detail = session_flow.recordNewAdventurerPreFirstSession({
        actor = unreadyNewcomer,
        pathTalents = { "aegis" },
    })
    assertTrue(ok, "partial pre-first-session checklist records should still persist")
    assertTrue(detail.needsFollowup,
        "partial pre-first-session checklist records should flag missing checklist items")
    assertTrue(hasValue(detail.missing, "name"),
        "pre-first-session checklist should flag missing adventurer names")
    assertTrue(hasValue(detail.missing, "seven_path_talents"),
        "pre-first-session checklist should flag missing path talents")
    assertTrue(hasValue(detail.missing, "omphalic_market_gear"),
        "pre-first-session checklist should flag missing starting gear")

    local newcomer = base_entity.createEntity({
        id = "pc_first_session_newcomer",
        name = "First Session Newcomer",
        isPC = true,
    })
    local firstSessionOptions = session_flow.getNewAdventurerOnboardingOptions({
        actor = newcomer,
        appearance = "A mud-spattered candle-maker with a brass mask.",
        bondTargets = { "Whisper", "Marta" },
        gameWorldQuestions = { "Who owns the drowned chapel?" },
        rulesQuestions = { "When do I test fate?" },
        actionHelpQuestions = { "Which card should I play to help the scout?" },
        feedback = { "The map handoff helped." },
        couldImprove = { "I needed the light rules repeated." },
    })
    assertTrue(firstSessionOptions.firstSession.complete,
        "new adventurer onboarding options should preview complete first-session follow-through")
    assertEqual(firstSessionOptions.firstSession.resultPreview, "new_adventurer_first_session_ready",
        "new adventurer onboarding options should preview ready first-session records")
    assertTrue(firstSessionOptions.firstSession.hasTwoBondTargets,
        "new adventurer onboarding options should preview the two first-session Bond targets")
    assertTrue(firstSessionOptions.firstSession.askedQuestions,
        "new adventurer onboarding options should preview first-session questions")
    assertTrue(firstSessionOptions.firstSession.gaveFeedback,
        "new adventurer onboarding options should preview first-session feedback")
    assertTrue(newcomer.appearance == nil,
        "new adventurer onboarding options should not write first-session appearance")

    ok, result, detail = session_flow.recordNewAdventurerFirstSession({
        campaign = campaign,
        actor = newcomer,
        appearance = "A mud-spattered candle-maker with a brass mask.",
        bondTargets = { "Whisper", "Marta" },
        gameWorldQuestions = { "Who owns the drowned chapel?" },
        rulesQuestions = { "When do I test fate?" },
        actionHelpQuestions = { "Which card should I play to help the scout?" },
        feedback = { "The map handoff helped." },
        couldImprove = { "I needed the light rules repeated." },
    })
    assertTrue(ok, "new adventurer first-session helper should record checklist follow-through")
    assertEqual(result, "new_adventurer_first_session_recorded",
        "new adventurer first-session helper should report its checklist result")
    assertEqual(newcomer.appearance, "A mud-spattered candle-maker with a brass mask.",
        "new adventurer first-session helper should record what the adventurer looks like")
    assertTrue(detail.hasTwoBondTargets,
        "new adventurer first-session helper should preserve the two selected Bond targets")
    assertTrue(detail.askedQuestions,
        "new adventurer first-session helper should record world/rules/action questions")
    assertTrue(detail.gaveFeedback,
        "new adventurer first-session helper should record first-session feedback")
    assertTrue(not detail.needsFollowup,
        "complete new adventurer first-session checklist records should not require follow-up")
    assertEqual(campaign.campaignLog.newAdventurerFirstSessions[1], detail,
        "new adventurer first-session helper should append to the campaign log")
    assertEqual(campaign.lastNewAdventurerFirstSession, detail,
        "new adventurer first-session helper should expose the latest onboarding record")

    local quietNewcomer = base_entity.createEntity({
        id = "pc_first_session_quiet",
        name = "Quiet First Session",
        isPC = true,
    })
    ok, result, detail = session_flow.recordNewAdventurerFirstSession({
        actor = quietNewcomer,
        bondTargets = { "Whisper" },
    })
    assertTrue(ok, "partial new adventurer first-session records should still persist")
    assertTrue(detail.needsFollowup,
        "partial new adventurer first-session records should flag missing checklist items")

    local guildmateA = base_entity.createEntity({
        id = "pc_onboarding_guildmate_a",
        name = "Onboarding Guildmate A",
        isPC = true,
    })
    local guildmateB = base_entity.createEntity({
        id = "pc_onboarding_guildmate_b",
        name = "Onboarding Guildmate B",
        isPC = true,
    })
    local secondSessionNewcomer = base_entity.createEntity({
        id = "pc_onboarding_second_session",
        name = "Onboarding Second Session",
        isPC = true,
    })
    local secondSessionOptions = session_flow.getNewAdventurerOnboardingOptions({
        actor = secondSessionNewcomer,
        guild = { guildmateA, guildmateB },
        currentQuest = "Map the white labyrinth",
        role = "scout",
        marchingOrder = 2,
        decision = "join_guild",
    })
    assertTrue(not secondSessionOptions.priorToSecondSession.completeGuildBonds,
        "new adventurer onboarding options should require all-guild Bonds before session two")
    assertEqual(secondSessionOptions.priorToSecondSession.requiredBondCount, 2,
        "new adventurer onboarding options should count required all-guild Bonds")
    assertEqual(secondSessionOptions.endOfSecondSession.decisionOptions[1].unavailableReason,
        "Complete guild Bonds required",
        "new adventurer onboarding options should explain blocked guild joins")
    assertEqual(secondSessionNewcomer.xp or 0, 0,
        "new adventurer onboarding options should not grant second-session quest XP")

    secondSessionNewcomer.bonds = {
        [guildmateA.id] = { status = "friendship" },
        [guildmateB.id] = { status = "rivalry" },
    }
    local completeSecondSessionOptions = session_flow.getNewAdventurerOnboardingOptions({
        actor = secondSessionNewcomer,
        guild = { guildmateA, guildmateB },
        guildRoster = { currentQuest = "Map the white labyrinth" },
        role = "scout",
        marchingOrder = 2,
        decision = "join_guild",
    })
    assertTrue(completeSecondSessionOptions.priorToSecondSession.completeGuildBonds,
        "new adventurer onboarding options should recognize complete all-guild Bonds")
    assertTrue(completeSecondSessionOptions.endOfSecondSession.canJoinGuild,
        "new adventurer onboarding options should preview joining the current guild")
    assertEqual(completeSecondSessionOptions.endOfSecondSession.resultPreview,
        "new_adventurer_joined_guild",
        "new adventurer onboarding options should preview the join-guild branch")
    assertEqual(completeSecondSessionOptions.endOfSecondSession.decisionOptions[1].xpAwarded, 3,
        "new adventurer onboarding options should preview the rulebook join-quest XP")
    assertTrue(completeSecondSessionOptions.endOfSecondSession.canElectReplacement,
        "new adventurer onboarding options should preview the replacement branch after all-guild Bonds")
    assertTrue(not secondSessionNewcomer.joinedGuild,
        "new adventurer onboarding options should not sign the guild roster")
    assertEqual(secondSessionNewcomer.xp or 0, 0,
        "new adventurer onboarding options should not grant XP while previewing")
end

function checkSessionZeroBookkeeping()
    local session_flow = require('logic.session_flow')
    local sessionZeroProcedure = session_flow.getSessionZeroProcedure()
    assertEqual(sessionZeroProcedure.defaultAssumption,
        "megadungeon-based exploration where adventurers pursue their own quests",
        "Session 0 metadata should preserve the default campaign assumption")
    assertTrue(hasValue(sessionZeroProcedure.collaborativeGameCreation[2].prompts, "intra-party conflict"),
        "Session 0 metadata should preserve sources-of-fun prompts")
    assertTrue(hasValue(sessionZeroProcedure.guildCreation.questions, "What are the looting rights?"),
        "Session 0 metadata should preserve guild creation questions")
    assertTrue(hasValue(sessionZeroProcedure.guildCreation.rosterFields,
        "directed Bonds with every other guild member"),
        "Session 0 metadata should preserve directed Bond roster requirements")
    sessionZeroProcedure.guildCreation.questions[1] = "changed"
    assertEqual(session_flow.getSessionZeroProcedure().guildCreation.questions[1],
        "What is the name of your guild?",
        "Session 0 metadata should be copy-safe")

    local campaign = {}
    local sessionZeroOptions = session_flow.getSessionZeroOptions({
        campaign = campaign,
        campaignPremise = "Megadungeon-based exploration with personal quests.",
        funSources = {
            combat = true,
            emergingStory = true,
        },
        sensitiveSubjects = { "undead plague" },
        avoidSubjects = { "slavery" },
        specialPermissions = {
            { request = "Cannibal adventurer", approved = false },
        },
        questReviews = {
            { quest = "Get rich", needsRevision = true },
        },
        guildDecisions = {
            name = "The Bellwardens",
            whyTogether = "Secret Pope's strike force",
            members = { "Phynn", "Dorian" },
