        avoidSubjects = { "slavery" },
        askFirstSubjects = { "intra-party romance" },
        rulesClarifications = {
            { question = "Can two dwarves be kin?", answer = "Yes, discuss relation at the table." },
        },
        specialPermissions = {
            { request = "Cannibal adventurer", approved = false, note = "Not for this game." },
            { request = "Shared mentor", tableApproved = true },
        },
        questReviews = {
            { adventurerId = "pc_grail", quest = "Find the Grail of Mythrys", approved = true },
            { adventurerId = "pc_rich", quest = "Get rich", vetoed = true, suggestion = "Name a concrete treasure." },
