function checkGMResponseAdjudication()
    local adjudication = require('logic.adjudication')
    local procedure = adjudication.getAdjudicationProcedure()
    assertEqual(procedure.stockResponses[1], adjudication.RESPONSES.YES,
        "GM response metadata should expose Yes as the first stock response")
    assertTrue(hasValue(procedure.safeSuccessThreshold, "appropriate tools"),
        "GM response metadata should preserve the safe-success tool threshold")
    assertEqual(procedure.penaltyChoices[1].acceptedDraw.majorArcanaTrigger, "I-V",
        "GM response metadata should expose long-time Meatgrinder draw range")
    assertEqual(procedure.penaltyChoices[2].acceptedDraw.majorArcanaTrigger, "XV-XX",
        "GM response metadata should expose loud-noise Meatgrinder draw range")
    assertTrue(hasValue(procedure.testFateGuidance, "Do not test inconsequential actions."),
        "GM response metadata should preserve Test Fate restraint guidance")
    procedure.stockResponses[1] = "changed"
    assertEqual(adjudication.getAdjudicationProcedure().stockResponses[1], adjudication.RESPONSES.YES,
        "GM response procedure metadata should be copy-safe")

    local responses = adjudication.getResponseDetails()
    assertEqual(responses[adjudication.RESPONSES.SAY_MORE].nextStep,
        "Shift to Yes, Draw, or No after the table reaches clarity.",
        "GM response details should preserve Say More follow-up guidance")
    assertEqual(responses[adjudication.RESPONSES.DRAW].drawType, adjudication.DRAW_TYPES.TEST_FATE,
        "GM response details should preserve Draw as Test Fate")
    responses[adjudication.RESPONSES.NO].label = "changed"
    assertEqual(adjudication.getResponseDetails(adjudication.RESPONSES.NO).label, "No, you can't do that",
        "GM response detail helper should return copy-safe records")

    local safeOptions = adjudication.getAdjudicationOptions({
        action = "open the unlocked door",
        risk = false,
        plentyTime = true,
        hasTools = true,
    })
    assertEqual(safeOptions.selectedResponse, adjudication.RESPONSES.YES,
        "GM response options should preview the selected stock response")
    assertTrue(safeOptions.responseOptions[1].selected,
        "GM response options should flag the selected response choice")
    assertTrue(safeOptions.automaticSuccess,
        "GM response options should preview automatic success")
    assertEqual(safeOptions.resultPreview, "adjudication_options_ready",
        "GM response options should report non-mutating option readiness")
    safeOptions.procedure.stockResponses[1] = "changed"
    assertEqual(adjudication.getAdjudicationOptions({ action = "open the unlocked door" }).procedure.stockResponses[1],
        adjudication.RESPONSES.YES,
        "GM response options should return copy-safe procedure metadata")

    local clarificationOptions = adjudication.getAdjudicationOptions({
        action = "search for traps",
        ambiguous = true,
        question = "How exactly are you searching?",
    })
    assertTrue(clarificationOptions.requiresClarification,
        "GM response options should surface Say More clarification state")
    assertEqual(clarificationOptions.selectedOption.nextStep,
        "Shift to Yes, Draw, or No after the table reaches clarity.",
        "GM response options should preserve Say More follow-up guidance")

    local penaltyChoiceOptions = adjudication.getAdjudicationOptions({
        action = "carefully dismantle the barricade",
        takesLongTime = true,
    })
    assertTrue(penaltyChoiceOptions.requiresPlayerChoice,
        "GM response options should surface unaccepted penalty choices")
    assertTrue(penaltyChoiceOptions.penaltyOptions[1].choiceRequired,
        "GM response options should flag the relevant penalty choice")
    assertEqual(penaltyChoiceOptions.penaltyOptions[1].majorArcanaTrigger, "I-V",
        "GM response options should preserve long-time Meatgrinder trigger ranges")

    local drawOptions = adjudication.getAdjudicationOptions({
        action = "hold the falling portcullis",
        uncertain = true,
        attribute = "swords",
        targetSuit = constants.SUITS.SWORDS,
    })
    assertTrue(drawOptions.requiresTestFate,
        "GM response options should surface Test Fate draw requirements")
    assertEqual(drawOptions.testFateOption.attribute, "swords",
        "GM response options should preserve selected Test Fate attributes")

    local blockedOptions = adjudication.getAdjudicationOptions({
        action = "pick the jail-cell lock",
        requiresTools = true,
        hasTools = false,
    })
    assertTrue(blockedOptions.blocked,
        "GM response options should flag No responses as blocked")
    assertEqual(blockedOptions.selectedOption.reason, "missing_tools",
        "GM response options should preserve concrete No reasons")

    local verdict = adjudication.adjudicateAction({
        action = "open the unlocked door",
        risk = false,
        plentyTime = true,
        hasTools = true,
    })
    assertEqual(verdict.response, adjudication.RESPONSES.YES,
        "ordinary safe actions should receive the Yes response")
    assertEqual(verdict.result, "automatic_success",
        "ordinary safe actions should auto-succeed without Test Fate")

    verdict = adjudication.adjudicateAction({
        action = "climb the handhold-rich tree",
        difficult = true,
        risk = false,
        plentyTime = true,
        hasTools = true,
    })
    assertEqual(verdict.response, adjudication.RESPONSES.YES,
        "difficult actions should still auto-succeed when time/tools/risk are safe")
    assertEqual(verdict.reason, "difficult_but_safe",
        "difficult safe actions should report the rulebook safe-success threshold")

    verdict = adjudication.adjudicateAction({
        action = "balance a mug on your head",
        uncertain = true,
        stakes = "trivial",
    })
    assertEqual(verdict.response, adjudication.RESPONSES.YES,
        "inconsequential uncertain actions should not call for Test Fate")
    assertEqual(verdict.reason, "inconsequential_action",
        "inconsequential actions should report why no Test Fate was called")

    verdict = adjudication.adjudicateAction({
        action = "search for traps",
        ambiguous = true,
        question = "How exactly are you searching?",
    })
    assertEqual(verdict.response, adjudication.RESPONSES.SAY_MORE,
        "ambiguous actions should request clarification")
    assertEqual(verdict.question, "How exactly are you searching?",
        "clarification verdict should preserve the GM question")

    verdict = adjudication.adjudicateAction({
        action = "pick the jail-cell lock",
        requiresTools = true,
        hasTools = false,
    })
    assertEqual(verdict.response, adjudication.RESPONSES.NO,
        "actions without required tools should receive the No response")
    assertEqual(verdict.result, "missing_tools",
        "missing-tool adjudication should report the concrete reason")

    verdict = adjudication.adjudicateAction({
        action = "tame the wild beast with one draw",
        requiresWeeks = true,
        alternative = "try to capture it",
        takesLongTime = true,
    })
    assertEqual(verdict.response, adjudication.RESPONSES.NO,
        "actions requiring weeks should not resolve as an immediate time-cost choice")
    assertEqual(verdict.result, "extended_project_required",
        "long-term project adjudication should report the concrete reason")
    assertEqual(verdict.alternative, "try to capture it",
        "long-term No adjudication should preserve an available alternative")

    verdict = adjudication.adjudicateAction({
        action = "carefully dismantle the barricade",
        takesLongTime = true,
    })
    assertEqual(verdict.response, adjudication.RESPONSES.YES,
        "time-cost actions should first be presented as a player choice")
    assertTrue(verdict.choiceRequired == true,
        "time-cost adjudication should require player acceptance before drawing")
    assertEqual(verdict.penalties[1].majorArcanaTrigger, "I-V",
        "long-time penalties should use the torches-gutter range")

    verdict = adjudication.adjudicateAction({
        action = "hack down the wooden door",
        createsNoise = true,
        acceptNoise = true,
        majorCards = {
            noise = { value = 15, name = "Devil" },
        },
    })
    assertEqual(verdict.response, adjudication.RESPONSES.DRAW,
        "accepted noisy actions should draw on the Meatgrinder")
    assertEqual(verdict.drawType, adjudication.DRAW_TYPES.MEATGRINDER,
        "accepted noisy actions should use the Meatgrinder draw type")
    assertEqual(verdict.draws[1].majorArcanaTrigger, "XV-XX",
        "noise penalties should use the loud-noise encounter range")
    assertTrue(verdict.draws[1].triggered == true,
        "major XV should trigger a loud-noise random encounter")
    assertEqual(verdict.draws[1].triggeredCategory, meatgrinder.CATEGORIES.RANDOM_ENCOUNTER,
        "noise penalties should report a random-encounter trigger")

    verdict = adjudication.adjudicateAction({
        action = "hold the falling portcullis",
        uncertain = true,
        attribute = "swords",
        targetSuit = constants.SUITS.SWORDS,
    })
    assertEqual(verdict.response, adjudication.RESPONSES.DRAW,
        "fraught actions should require a draw")
    assertEqual(verdict.result, "test_fate_required",
        "fraught actions should route to Test Fate")
    assertEqual(verdict.draws[1].attribute, "swords",
        "Test Fate adjudication should preserve the GM-selected attribute")
end

function checkBoundByFateTracker()
    local fate_binding = require('logic.fate_binding')
    local adjudication = require('logic.adjudication')
    local records = {}
    local lockFailure = {
        result = fate_resolver.RESULTS.FAILURE,
        success = false,
        total = 9,
    }

    local entry = fate_binding.record(records, {
        scope = "room_101",
        objective = "brass door lock",
        method = "pick lock",
        actor = { id = "pc_first_picker" },
        helpers = { { id = "pc_lock_advice" } },
        tools = { "lockpicks" },
    }, lockFailure)
    assertEqual(entry.result, lockFailure, "bound-by-fate tracker should preserve the original test result")
    assertEqual(entry.actorIds[1], "pc_first_picker", "bound-by-fate tracker should record the lead actor")
    assertEqual(entry.actorIds[2], "pc_lock_advice", "bound-by-fate tracker should record helpers")

    local status = fate_binding.getStatus(records, {
        scope = "room_101",
        objective = "brass door lock",
        method = "pick lock",
        actor = { id = "pc_second_picker" },
        tools = { "lockpicks" },
    })
    assertTrue(status.allowed == false, "same-method retries should be blocked for fellow guild members")
    assertEqual(status.reason, "result_stands", "blocked retries should report that the old result stands")

    status = fate_binding.getStatus(records, {
        scope = "room_101",
        objective = "brass door lock",
        method = "bash down",
        actor = { id = "pc_warrior" },
        tools = { "warhammer" },
    })
    assertTrue(status.allowed == true, "alternate methods should remain legal after a failed test")
    assertEqual(status.reason, "alternate_method", "alternate methods should be identified distinctly")

    status = fate_binding.getStatus(records, {
        scope = "room_101",
        objective = "brass door lock",
        method = "pick lock",
        actor = { id = "pc_second_picker" },
        tools = { "acid and lockpicks" },
    })
    assertTrue(status.allowed == true, "changed tools or circumstances should allow a new attempt")
    assertEqual(status.reason, "circumstance_changed",
        "changed circumstances should be identified as the retry reason")

    local verdict = adjudication.adjudicateAction({
        action = "pick the brass door lock",
        scope = "room_101",
        objective = "brass door lock",
        method = "pick lock",
        actor = { id = "pc_second_picker" },
        tools = { "lockpicks" },
        uncertain = true,
        boundByFateRecords = records,
    })
    assertEqual(verdict.response, adjudication.RESPONSES.NO,
        "GM adjudication should reject same-method Tests of Fate while bound by fate")
    assertEqual(verdict.result, "bound_by_fate", "bound-by-fate adjudication should report its reason")

    local successRecords = {}
    fate_binding.record(successRecords, {
        scope = "room_102",
        objective = "slick wall",
        method = "climb",
        actor = { id = "pc_climber" },
    }, {
        result = fate_resolver.RESULTS.SUCCESS,
        success = true,
        total = 15,
    })
    status = fate_binding.getStatus(successRecords, {
        scope = "room_102",
        objective = "slick wall",
        method = "climb",
    })
    assertTrue(status.allowed == false,
        "successful Tests of Fate should also bind repeated attempts until circumstances change")
end

function checkCallToAdventureAdventurerCreation()
    local talent_catalog = require('data.talent_catalog')
    local language_catalog = require('data.language_catalog')
    local motif_catalog = require('data.motif_catalog')
    local pc, result, detail = entity_factory.createCallToAdventureAdventurer({
        id = "pc_call_to_adventure",
        name = "Call Adventurer",
        kin = "human",
        kith = "human",
        path = "swords",
        fittingInAttribute = "wands",
        failedCareerAttribute = "cups",
        firstAdventureAttribute = "pentacles",
        masteredPathTalent = "aegis",
        motifs = {
            "Veteran Smith",
            "Penitent Grave Robber",
            "Young Explorer",
        },
        quest = "Find the bell beneath the river",
        appearance = "A scarred knight with a patched cloak",
        languages = { "vulgaris", "cant" },
    })
    assertTrue(pc ~= nil, "Call to Adventure helper should create an adventurer")
    assertEqual(result, "call_to_adventure_created", "Call to Adventure helper should report creation")
    assertEqual(pc.swords, 4, "Call to Adventure path attribute should be rated 4")
    assertEqual(pc.pentacles, 3, "Call to Adventure first-adventure attribute should be rated 3")
    assertEqual(pc.cups, 2, "Call to Adventure failed-career attribute should be rated 2")
    assertEqual(pc.wands, 1, "Call to Adventure fitting-in attribute should be rated 1")
    assertEqual(pc.resolve.current, 4, "fresh adventurers should start with full 4 Resolve")
    assertEqual(pc.resolve.max, 4, "fresh adventurers should have a maximum of 4 Resolve")
    assertTrue(pc:isTalentMastered("proud_and_ancient"), "Call to Adventure should master the kin talent")
    assertEqual(pc.kith, "human", "Call to Adventure should record the resolved kith")
    assertEqual(detail.kith, "human", "Call to Adventure detail should expose the resolved kith")
    assertTrue(pc:isTalentMastered("aegis"), "Call to Adventure should master one chosen path talent")
    assertTrue(pc:hasTalent("war_stories"), "Call to Adventure should write down every path talent")
    assertTrue(not pc:isTalentMastered("war_stories"),
        "unchosen Call to Adventure path talents should remain in training")
    assertEqual(#detail.pathTalents, 7, "Call to Adventure should expose the seven creation path talents")
    assertEqual(pc.quest, "Find the bell beneath the river", "Call to Adventure should record the quest")
    assertEqual(#pc.motifs, 3, "Call to Adventure should record three motifs")
    assertTrue(pc.motifInfo[1].sampleMotif,
        "Call to Adventure should parse rulebook sample descriptor/profession motifs")
    assertEqual(pc.motifInfo[2].profession, "grave_robber",
        "motif metadata should preserve multi-word professions")
    assertEqual(detail.motifInfo[3].descriptor, "young_very",
        "motif metadata should normalize rulebook descriptor aliases")
    assertTrue(hasValue(pc.languages, "cant"), "Call to Adventure should preserve selected languages")
    assertTrue(hasValue(pc.knownLanguages, "vulgaris"), "Call to Adventure should expose known languages")
    assertTrue(pc.languageInfo.vulgaris.commonCity,
        "Call to Adventure should attach rulebook language metadata")
    assertTrue(pc.languageInfo.cant.unintelligibleWithoutProficiency,
        "Cant metadata should preserve its unintelligible-without-proficiency rule")
    assertTrue(detail.languageInfo.vulgaris.derivedFrom[2] == "vetus",
        "language metadata should preserve Vulgaris roots")
    assertEqual(pc.appearance, "A scarred knight with a patched cloak",
        "Call to Adventure should record appearance")
    assertEqual(pc.arete.kith, "human", "Call to Adventure should record kith arete setup")
    assertEqual(pc.arete.talentId, "byname", "human Call to Adventure arete should point to Byname")
    assertEqual(#pc.arete.triggers, 3, "Call to Adventure should record all three arete triggers")
    assertEqual(pc.arete.triggers[1].id, "getting_married",
        "Call to Adventure should preserve the rulebook arete trigger ids")
    assertTrue(not pc:isTalentMastered("byname"), "arete talent should not start mastered")

    local vetusInfo = language_catalog.getLanguage("Cult")
    assertEqual(vetusInfo.id, "vetus", "language catalog should normalize rulebook aliases")
    assertTrue(vetusInfo.onlyWrittenLanguageInCity,
        "Vetus metadata should preserve the City's written-language rule")
    local langOk, langReason, langDetail = language_catalog.validateStartingLanguages({
        "Tylwyth",
        "Vetus",
    }, {
        strictCommonCity = true,
    })
    assertTrue(langOk, "language catalog should validate two distinct common City languages")
    assertEqual(langReason, "languages_selected", "valid starting languages should report selection")
    assertTrue(langDetail.languageInfo.tylwyth.speakers[1] == "fay",
        "Tylwyth metadata should preserve fay speakers")

    local customMotif = motif_catalog.parseMotif("White Worm Survivor")
    assertTrue(customMotif.structured, "motif parser should preserve freeform descriptor/profession shape")
    assertTrue(not customMotif.sampleMotif,
        "motif parser should distinguish custom motifs from sample-list motifs")
    local strictOk, strictReason = motif_catalog.validateMotifs({
        "Veteran Smith",
        "Penitent Grave Robber",
        "White Worm Survivor",
    }, {
        strictSamples = true,
    })
    assertTrue(not strictOk, "strict motif validation should reject non-sample motifs")
    assertEqual(strictReason, "Motif must use a rulebook descriptor and profession",
        "strict motif validation should explain the sample-list requirement")

    local ok, areteDetail = talent_catalog.recordAreteTrigger(pc, "getting_married")
    assertTrue(ok, "arete helper should mark a completed trigger")
    assertEqual(areteDetail.checkCount, 1, "arete helper should count checked triggers")
    assertTrue(not pc:isTalentMastered("byname"), "one arete check should not grant the talent")
    talent_catalog.recordAreteTrigger(pc, "fulfilling_an_oath")
    ok, areteDetail = talent_catalog.recordAreteTrigger(pc, "defeating_rival_house_in_fair_duel")
    assertTrue(ok and areteDetail.completed, "third arete check should complete the checklist")
    assertTrue(pc:isTalentMastered("byname"), "completed human arete should grant Byname")
    assertEqual(pc.talents.byname.trainingKind, "arete", "granted arete talent should be marked as arete")

    local gnomeArete = talent_catalog.getAreteSetup("gnome")
    assertEqual(gnomeArete.kith, "fay", "gnome arete setup should use fay triggers")
    assertEqual(gnomeArete.talentId, "uncanny_knowledge", "gnome arete setup should grant Uncanny Knowledge")
    local kithOk, kithReason, kithDetail = talent_catalog.validateKithKin("gnome", "fey")
    assertTrue(kithOk, "kith/kin validation should accept rulebook aliases")
    assertEqual(kithReason, "kith_kin_valid", "valid kith/kin pairs should report validation")
    assertEqual(kithDetail.kith, "fay", "kith/kin validation should normalize accepted kith")
    kithOk, kithReason = talent_catalog.validateKithKin("dwarf", "fay")
    assertTrue(not kithOk, "kith/kin validation should reject mismatched categories")
    assertEqual(kithReason, "Kith does not match kin",
        "mismatched kith/kin validation should explain the incompatibility")

    local invalidAttributes, reason = entity_factory.createCallToAdventureAdventurer({
        name = "Invalid Attribute Adventurer",
        kin = "human",
        path = "cups",
        attributes = {
            swords = 4,
            pentacles = 3,
            cups = 2,
            wands = 1,
        },
        masteredPathTalent = "chirurgeon",
        motifs = { "one", "two", "three" },
        quest = "Find a cure",
        appearance = "A harried doctor",
    })
    assertTrue(not invalidAttributes, "Call to Adventure should reject attributes that do not match the path")
    assertEqual(reason, "Path attribute must be rated 4",
        "invalid Call to Adventure path attributes should explain the path rating")

    local wrongKith
    wrongKith, reason = entity_factory.createCallToAdventureAdventurer({
        name = "Wrong Kith Adventurer",
        kin = "dwarf",
        kith = "fay",
        path = "swords",
        fittingInAttribute = "wands",
        failedCareerAttribute = "cups",
        firstAdventureAttribute = "pentacles",
        masteredPathTalent = "aegis",
        motifs = { "one", "two", "three" },
        quest = "Find the false beard",
        appearance = "A miner under a glamor",
    })
    assertTrue(not wrongKith, "Call to Adventure should reject incompatible kith/kin pairs")
    assertEqual(reason, "Kith does not match kin",
        "incompatible Call to Adventure kith/kin pairs should explain the category mismatch")

    local wrongKinTalent
    wrongKinTalent, reason = entity_factory.createCallToAdventureAdventurer({
        name = "Wrong Kin Talent Adventurer",
        kin = "human",
        kith = "human",
        kinTalent = "labor_unending",
        path = "swords",
        fittingInAttribute = "wands",
        failedCareerAttribute = "cups",
        firstAdventureAttribute = "pentacles",
        masteredPathTalent = "aegis",
        motifs = { "one", "two", "three" },
        quest = "Claim an impossible inheritance",
        appearance = "A courtier with a forged pedigree",
    })
    assertTrue(not wrongKinTalent, "Call to Adventure should reject kin talents from another kin")
    assertEqual(reason, "Kin talent must match kin",
        "mismatched Call to Adventure kin talents should explain the kin talent rule")

    local badTalent
    badTalent, reason = entity_factory.createCallToAdventureAdventurer({
        name = "Invalid Talent Adventurer",
        kin = "human",
        path = "pentacles",
        fittingInAttribute = "wands",
        failedCareerAttribute = "cups",
        firstAdventureAttribute = "swords",
        masteredPathTalent = "aegis",
        motifs = { "one", "two", "three" },
        quest = "Open the vault",
        appearance = "A careful burglar",
    })
    assertTrue(not badTalent, "Call to Adventure should reject off-path mastered talents")
    assertEqual(reason, "Mastered path talent must belong to the chosen path",
        "off-path mastered talents should explain the chosen-path gate")

    local missingMotifs
    missingMotifs, reason = entity_factory.createCallToAdventureAdventurer({
        name = "Missing Motifs Adventurer",
        kin = "human",
        path = "swords",
        fittingInAttribute = "wands",
        failedCareerAttribute = "cups",
        firstAdventureAttribute = "pentacles",
        masteredPathTalent = "aegis",
        motifs = { "only one", "only two" },
        quest = "Find the lost sword",
        appearance = "A solemn guard",
    })
    assertTrue(not missingMotifs, "Call to Adventure should require three motifs")
    assertEqual(reason, "Exactly three motifs required", "missing Call to Adventure motifs should explain the rule")

    local extraMotifs
    extraMotifs, reason = entity_factory.createCallToAdventureAdventurer({
        name = "Extra Motifs Adventurer",
        kin = "human",
        path = "swords",
        fittingInAttribute = "wands",
        failedCareerAttribute = "cups",
        firstAdventureAttribute = "pentacles",
        masteredPathTalent = "aegis",
        motifs = { "one", "two", "three", "four" },
        quest = "Find the lost sword",
        appearance = "A verbose guard",
    })
    assertTrue(not extraMotifs, "Call to Adventure should reject extra motifs")
    assertEqual(reason, "Exactly three motifs required",
        "extra Call to Adventure motifs should explain the exact rule")

    local badResolve
    badResolve, reason = entity_factory.createCallToAdventureAdventurer({
        name = "Bad Resolve Adventurer",
        kin = "human",
        path = "swords",
        fittingInAttribute = "wands",
        failedCareerAttribute = "cups",
        firstAdventureAttribute = "pentacles",
        masteredPathTalent = "aegis",
        motifs = { "one", "two", "three" },
        quest = "Find the lost sword",
        appearance = "A weary guard",
        resolve = 3,
    })
    assertTrue(not badResolve, "Call to Adventure should reject noncanonical starting Resolve")
    assertEqual(reason, "Call to Adventure Resolve must be 4",
        "invalid Call to Adventure Resolve should explain the fixed value")

    local duplicateLanguages
    duplicateLanguages, reason = entity_factory.createCallToAdventureAdventurer({
        name = "Duplicate Language Adventurer",
        kin = "human",
        path = "swords",
        fittingInAttribute = "wands",
        failedCareerAttribute = "cups",
        firstAdventureAttribute = "pentacles",
        masteredPathTalent = "aegis",
        motifs = { "one", "two", "three" },
        quest = "Find the lost sword",
        appearance = "A wary guard",
        languages = { "Vulgaris", "vulgaris" },
    })
    assertTrue(not duplicateLanguages, "Call to Adventure should reject duplicate language choices")
    assertEqual(reason, "Choose two distinct languages",
        "duplicate Call to Adventure languages should explain the distinct-language gate")

    local strictMotifs
    strictMotifs, reason = entity_factory.createCallToAdventureAdventurer({
        name = "Strict Motif Adventurer",
        kin = "human",
        path = "swords",
        fittingInAttribute = "wands",
        failedCareerAttribute = "cups",
        firstAdventureAttribute = "pentacles",
        masteredPathTalent = "aegis",
        motifs = { "Veteran Smith", "Penitent Grave Robber", "White Worm Survivor" },
        quest = "Find the lost sword",
        appearance = "A formal guard",
        strictRulebookMotifs = true,
    })
    assertTrue(not strictMotifs,
        "Call to Adventure should support strict sample-list motif validation when requested")
    assertEqual(reason, "Motif must use a rulebook descriptor and profession",
        "strict Call to Adventure motifs should explain the sample-list requirement")
end

function checkUltraFastAdventurerCreation()
    local pc, result, detail = entity_factory.createUltraFastAdventurer({
        id = "pc_ultra_fast",
        name = "Fast Replacement",
        kin = "human",
        kith = "human",
        path = "cups",
        masteredPathTalent = "chirurgeon",
        talents = {
            bookworm = { mastered = true },
        },
        motifs = { "not", "yet", "fixed" },
        quest = "Premature quest",
        appearance = "Premature appearance",
        languages = { "vulgaris", "cant" },
    })
    assertTrue(pc ~= nil, "ultra-fast helper should create a replacement adventurer")
    assertEqual(result, "ultra_fast_adventurer_created",
        "ultra-fast helper should report shortcut creation")
    assertTrue(detail.enabled, "ultra-fast detail should mark the shortcut as enabled")
    assertTrue(detail.midSession, "ultra-fast detail should mark the mid-session replacement use")
    assertTrue(pc.callToAdventurePending,
        "ultra-fast adventurers should remain pending full post-session character creation")
    assertEqual(pc.kith, "human", "ultra-fast helper should record the resolved kith")
    assertEqual(detail.kith, "human", "ultra-fast detail should expose the resolved kith")
    assertEqual(pc.cups, 4, "ultra-fast helper should fix the path attribute at 4")
    assertEqual(pc.swords, nil, "ultra-fast helper should leave non-path attributes blank")
    assertEqual(pc:getAttribute(constants.SUITS.SWORDS), 0,
        "blank ultra-fast attributes should read as unresolved instead of defaulting to 1")
    assertEqual(#pc.motifs, 0, "ultra-fast helper should leave motifs blank up front")
    assertEqual(pc.quest, nil, "ultra-fast helper should leave quest blank up front")
    assertEqual(#pc.languages, 0, "ultra-fast helper should leave languages blank up front")
    assertEqual(pc.resolve.current, 4, "ultra-fast adventurers should start with full 4 Resolve")
    assertEqual(pc.resolve.max, 4, "ultra-fast adventurers should have maximum 4 Resolve")
    assertTrue(pc:isTalentMastered("proud_and_ancient"),
        "ultra-fast helper should write down the kin talent")
    assertTrue(pc:isTalentMastered("chirurgeon"),
        "ultra-fast helper should master exactly the selected path talent")
    assertTrue(not pc:hasTalent("bookworm"),
        "ultra-fast helper should not write down every path talent up front")
    assertEqual(#detail.pathTalents, 7,
        "ultra-fast detail should preserve the later full-creation path talent list")
    assertTrue(hasValue(detail.unresolvedAttributes, "swords"),
        "ultra-fast detail should track unresolved attributes")
    assertTrue(hasValue(detail.unresolvedFields, "quest"),
        "ultra-fast detail should track blank sheet fields")

    local ok, reason, record = entity_factory.resolveUltraFastSheetQuestion(pc, {
        field = "attribute",
        attribute = "swords",
        value = 3,
    })
    assertTrue(ok, "ultra-fast sheet questions should resolve attributes during play")
    assertEqual(reason, "ultra_fast_question_resolved",
        "ultra-fast attribute answers should report resolution")
    assertEqual(record.attribute, "swords", "ultra-fast attribute record should name the answer")
    assertEqual(pc.swords, 3, "ultra-fast attribute answers should update the shorthand score")
    assertEqual(pc:getAttribute(constants.SUITS.SWORDS), 3,
        "ultra-fast attribute answers should update the suit score")
    assertTrue(not hasValue(detail.unresolvedAttributes, "swords"),
        "resolved ultra-fast attributes should be removed from the unresolved list")

    local duplicate
    duplicate, reason = entity_factory.resolveUltraFastSheetQuestion(pc, {
        field = "attribute",
        attribute = "pentacles",
        value = 3,
    })
    assertTrue(not duplicate, "ultra-fast attributes should stay distinct once answered")
    assertEqual(reason, "Ultra-fast attributes must stay distinct",
        "duplicate ultra-fast attribute values should explain the distinctness rule")

    local repeated
    repeated, reason = entity_factory.resolveUltraFastSheetQuestion(pc, {
        field = "attribute",
        attribute = "swords",
        value = 2,
    })
    assertTrue(not repeated, "ultra-fast attributes should not be rewritten after answer")
    assertEqual(reason, "Ultra-fast attribute already resolved",
        "rewritten ultra-fast attributes should explain that the answer is fixed")

    local pathRewrite
    pathRewrite, reason = entity_factory.resolveUltraFastSheetQuestion(pc, {
        field = "attribute",
        attribute = "cups",
        value = 2,
    })
    assertTrue(not pathRewrite, "ultra-fast path attributes should remain fixed at 4")
    assertEqual(reason, "Path attribute already fixed",
        "ultra-fast path attribute rewrites should explain the fixed path score")

    ok, reason, record = entity_factory.resolveUltraFastSheetQuestion(pc, {
        field = "gear",
        item = "rope",
        answer = true,
    })
    assertTrue(ok, "ultra-fast sheet questions should record ad-hoc gear answers")
    assertEqual(record.item, "rope", "ultra-fast gear records should preserve the item question")
    assertEqual(pc.ultraFastGearAnswers[1].hasItem, true,
        "ultra-fast gear records should preserve the table answer")
    assertTrue(hasValue(detail.unresolvedFields, "gear"),
        "ultra-fast gear should remain open for more ad-hoc equipment questions")

    local badMotifs
    badMotifs, reason = entity_factory.resolveUltraFastSheetQuestion(pc, {
        field = "motifs",
        motifs = { "only one" },
    })
    assertTrue(not badMotifs, "ultra-fast motif resolution should still enforce full creation shape")
    assertEqual(reason, "Exactly three motifs required",
        "invalid ultra-fast motifs should explain the exact three-motif rule")

    ok, reason, record = entity_factory.resolveUltraFastSheetQuestion(pc, {
        field = "motifs",
        motifs = {
            "hospice ward",
            "failed surgeon",
            "plague survivor",
        },
    })
    assertTrue(ok, "ultra-fast motif answers should resolve when complete")
    assertEqual(#pc.motifs, 3, "ultra-fast motif answers should record three motifs")
    assertTrue(record.motifInfo[1].structured,
        "ultra-fast motif answers should preserve descriptor/profession metadata")
    assertTrue(not hasValue(detail.unresolvedFields, "motifs"),
        "complete ultra-fast motifs should clear their unresolved field")

    ok, reason = entity_factory.resolveUltraFastSheetQuestion(pc, {
        field = "quest",
        quest = "Find the fever saint",
    })
    assertTrue(ok, "ultra-fast quest answers should resolve during play")
    assertEqual(pc.quest, "Find the fever saint", "ultra-fast quest answers should record the quest")
    assertTrue(not hasValue(detail.unresolvedFields, "quest"),
        "ultra-fast quest answers should clear their unresolved field")

    ok, reason = entity_factory.resolveUltraFastSheetQuestion(pc, {
        field = "appearance",
        appearance = "A pale sawbones with a laurel mask",
    })
    assertTrue(ok, "ultra-fast appearance answers should resolve during play")
    assertEqual(pc.appearance, "A pale sawbones with a laurel mask",
        "ultra-fast appearance answers should record the look")
    assertTrue(not hasValue(detail.unresolvedFields, "appearance"),
        "ultra-fast appearance answers should clear their unresolved field")

    ok, reason, record = entity_factory.resolveUltraFastSheetQuestion(pc, {
        field = "languages",
        languages = { "vulgaris", "vetus" },
    })
    assertTrue(ok, "ultra-fast language answers should use starting language validation")
    assertTrue(hasValue(pc.languages, "vetus"), "ultra-fast language answers should record languages")
    assertTrue(record.languageInfo.vetus.onlyWrittenLanguageInCity,
        "ultra-fast language records should include rulebook metadata")
    assertTrue(not hasValue(detail.unresolvedFields, "languages"),
        "ultra-fast language answers should clear their unresolved field")

    local wrongKith
    wrongKith, reason = entity_factory.createUltraFastAdventurer({
        name = "Fast Wrong Kith",
        kin = "dwarf",
        kith = "fay",
        path = "swords",
        masteredPathTalent = "aegis",
    })
    assertTrue(not wrongKith, "ultra-fast helper should reject incompatible kith/kin pairs")
    assertEqual(reason, "Kith does not match kin",
        "ultra-fast incompatible kith/kin pairs should explain the category mismatch")

    local wrongKinTalent
    wrongKinTalent, reason = entity_factory.createUltraFastAdventurer({
        name = "Fast Wrong Kin Talent",
        kin = "human",
        kith = "human",
        kinTalent = "labor_unending",
        path = "swords",
        masteredPathTalent = "aegis",
    })
    assertTrue(not wrongKinTalent, "ultra-fast helper should reject kin talents from another kin")
    assertEqual(reason, "Kin talent must match kin",
        "ultra-fast mismatched kin talents should explain the kin talent rule")
end

function checkCallToAdventureGuildRoster()
    local guild_roster = require('logic.guild_roster')
    local scout = entity_factory.createCallToAdventureAdventurer({
        id = "pc_call_guild_scout",
        name = "Guild Scout",
        kin = "wood_elf",
        path = "pentacles",
        fittingInAttribute = "wands",
        failedCareerAttribute = "cups",
        firstAdventureAttribute = "swords",
        masteredPathTalent = "sneak",
        motifs = { "forest child", "failed courier", "trap survivor" },
        quest = "Find the moon map",
        appearance = "A wary scout with living vine tattoos",
    })
    local guard = entity_factory.createCallToAdventureAdventurer({
        id = "pc_call_guild_guard",
        name = "Guild Guard",
        kin = "dwarf",
        path = "swords",
        fittingInAttribute = "wands",
        failedCareerAttribute = "cups",
        firstAdventureAttribute = "pentacles",
        masteredPathTalent = "aegis",
        motifs = { "forge child", "failed toll keeper", "shield bearer" },
        quest = "Recover the oath stone",
        appearance = "A square-shouldered guard with a braided beard",
    })

    local roster, result, detail = entity_factory.createCallToAdventureGuild({
        name = "The Lantern Compact",
        sigil = "A lantern over crossed keys",
        terms = "Equal shares; the guild pays funeral expenses.",
        adventurers = { scout, guard },
        roles = {
            pc_call_guild_scout = "scout",
            pc_call_guild_guard = "bodyguard",
        },
        marchingOrder = {
            pc_call_guild_scout = "first",
            pc_call_guild_guard = "last",
        },
        bonds = {
            { from = "pc_call_guild_scout", to = "pc_call_guild_guard", status = "friendship" },
            { from = "pc_call_guild_guard", to = "pc_call_guild_scout", status = "guardianship" },
        },
    })
    assertTrue(roster ~= nil, "Call to Adventure guild roster should be created")
    assertEqual(result, "guild_roster_created", "Call to Adventure guild roster should report creation")
    assertEqual(roster.guildName, "The Lantern Compact", "guild roster should record the guild name")
    assertEqual(roster.sigil, "A lantern over crossed keys", "guild roster should record the sigil")
    assertEqual(roster.terms, "Equal shares; the guild pays funeral expenses.",
        "guild roster should record looting-right terms")
    assertEqual(#roster.entries, 2, "guild roster should include all adventurers")
    assertEqual(roster.marchingOrder[1].actorId, "pc_call_guild_scout",
        "guild roster should sort marching order by chosen position")
    assertEqual(guard.guildRole, "bodyguard", "guild roster should assign each adventurer's role")
    assertEqual(scout.marchingOrder, 1, "guild roster should assign marching order to actors")
    assertEqual(guard.marchingOrder, 2, "guild roster should parse last marching-order wording")
    scout.sizeCategory = "small"
    guard.sizeCategory = "human_sized"
    local plateTarget, plateDetail = guild_roster.selectMarchingOrderActor(roster, {
        minSize = "human_sized",
    })
    assertEqual(plateTarget, guard,
        "marching-order helper should choose the first adventurer large enough for a pressure plate")
    assertEqual(plateDetail.skipped[1].actor, scout,
        "marching-order helper should report smaller adventurers skipped by the plate")
    assertEqual(scout:getBond("pc_call_guild_guard").status, "friendship",
        "guild bonding should preserve directed Bond status")
    assertEqual(scout:getBond("pc_call_guild_guard").bondType, "ally",
        "guild bonding should map legacy friendship to the rulebook Ally Bond")
    assertTrue(scout:getBond("pc_call_guild_guard").chargeTrigger ~= nil,
        "guild bonding should preserve the rulebook Bond charge trigger")
    assertEqual(guard:getBond("pc_call_guild_scout").status, "guardianship",
        "guild bonding should require reciprocal directed Bonds")
    assertEqual(guard:getBond("pc_call_guild_scout").bondType, "ward",
        "guild bonding should map legacy guardianship to the rulebook Ward Bond")
    assertEqual(detail.bonds[1].bondType, "ally", "guild roster should report canonical Bond metadata")
    assertEqual(#detail.bonds, 2, "guild roster should report applied Bonds")

    scout.bonds = {}
    guard.bonds = {}
    local incompleteRoster, reason = entity_factory.createCallToAdventureGuild({
        name = "Missing Bonds",
        sigil = "Blank shield",
        adventurers = { scout, guard },
        roles = {
            pc_call_guild_scout = "scout",
            pc_call_guild_guard = "bodyguard",
        },
        marchingOrder = {
            pc_call_guild_scout = 1,
            pc_call_guild_guard = 2,
        },
        bonds = {
            { from = "pc_call_guild_scout", to = "pc_call_guild_guard", status = "friendship" },
        },
    })
    assertTrue(not incompleteRoster, "guild roster should require each member to Bond with every other member")
    assertEqual(reason, "Bond with every other guild member required",
        "incomplete guild Bonds should explain the all-to-all requirement")

    local duplicateRoster
    duplicateRoster, reason = entity_factory.createCallToAdventureGuild({
        name = "Duplicate March",
        sigil = "Two left boots",
        adventurers = { scout, guard },
        roles = {
            pc_call_guild_scout = "scout",
            pc_call_guild_guard = "bodyguard",
        },
        marchingOrder = {
            pc_call_guild_scout = 1,
            pc_call_guild_guard = 1,
        },
        defaultBondStatus = "friendship",
    })
    assertTrue(not duplicateRoster, "guild roster should reject duplicate marching-order positions")
    assertEqual(reason, "Marching order must be unique",
        "duplicate marching order should explain the roster constraint")

    local unknownBondRoster
    unknownBondRoster, reason = entity_factory.createCallToAdventureGuild({
        name = "Unknown Bonds",
        sigil = "Question mark",
        adventurers = { scout, guard },
        roles = {
            pc_call_guild_scout = "scout",
            pc_call_guild_guard = "bodyguard",
        },
        marchingOrder = {
            pc_call_guild_scout = 1,
            pc_call_guild_guard = 2,
        },
        defaultBondStatus = "mysterious affinity",
        strictBondTypes = true,
    })
    assertTrue(not unknownBondRoster, "strict Call to Adventure guild bonding should reject unknown Bond types")
    assertEqual(reason, "Unknown Bond type", "unknown strict Bond types should explain the rulebook gate")
end

local function checkAppendixCDenizenBlueprintData()
    local appendixCBestiaryBlueprints = {
        { id = "animate_statue", name = "Animate Statue" },
        { id = "bloodybones", name = "Bloodybones" },
        { id = "brain_spider", name = "Brain Spider" },
        { id = "cockatrice", name = "Cockatrice" },
        { id = "devil", name = "Devil, Gluttony" },
        { id = "dragon", name = "Dragon" },
        { id = "face_rat", name = "Face Rat" },
        { id = "fungoid", name = "Fungoid" },
        { id = "griffin", name = "Griffin" },
        { id = "harpy", name = "Harpy" },
        { id = "imp", name = "Imp" },
        { id = "jinn", name = "Jinn" },
        { id = "kelpie", name = "Kelpie" },
        { id = "yellow_king_lich", name = "Lich, The Yellow King" },
        { id = "lion", name = "Lion" },
        { id = "mimic", name = "Mimic" },
        { id = "nymph", name = "Nymph" },
        { id = "ogre", name = "Ogre" },
        { id = "questing_beast", name = "Questing Beast" },
        { id = "skeleton_brute", name = "Skeleton" },
        { id = "slime", name = "Slime" },
        { id = "titan_sporehulk", name = "Titan, The Sporehulk" },
        { id = "ungoat", name = "Ungoat" },
        { id = "vampire", name = "Vampire" },
        { id = "wraith", name = "Wraith" },
        { id = "winter_wolf", name = "Winter Wolf" },
        { id = "zombie", name = "Zombie" },
    }

    for _, denizen in ipairs(appendixCBestiaryBlueprints) do
        assertTrue(entity_factory.hasBlueprint(denizen.id),
            "Appendix C bestiary blueprint should be registered: " .. denizen.name)
        assertTrue(entity_factory.createEntity(denizen.id) ~= nil,
            "Appendix C bestiary blueprint should instantiate: " .. denizen.name)
    end

    assertTrue(entity_factory.hasBlueprint("zombie"), "Zombie denizen blueprint should be registered")

    local zombie = entity_factory.createEntity("zombie")
    assertTrue(zombie ~= nil, "Zombie blueprint should instantiate through the entity factory")
    assertEqual(zombie.swords, 0, "Zombie should use canonical Swords")
    assertEqual(zombie.pentacles, 0, "Zombie should use canonical Pentacles")
    assertEqual(zombie.cups, 0, "Zombie should use canonical Cups")
    assertEqual(zombie.wands, 0, "Zombie should use canonical Wands")
    assertEqual(zombie.npcHealth, 1, "Zombie should use canonical Health")
    assertEqual(zombie.npcDefense, 0, "Zombie should use canonical Defense")
    assertTrue(zombie.undead and hasValue(zombie.tags, "zombie") and hasValue(zombie.tags, "minion"),
        "Zombie should be tagged as an undead minion zombie")
    assertTrue(zombie.zombie and zombie.zombie.breathless and zombie.zombie.undreaming,
        "Zombie should preserve Breathless and Undreaming")
    assertTrue(zombie.zombie.rottingBrains.mindManipulationImmune and
        zombie.zombie.rottingBrains.inspireImmune and
        zombie.zombie.rottingBrains.cannotSeeIllusions,
        "Zombie should preserve Rotting Brains immunities")
    assertEqual(zombie.zombie.optionalOldArmorDefense, 1,
        "Zombie should preserve optional old-armor Defense")
    assertEqual(zombie.social.likes[1], "fond_memory_of_life",
        "Zombie should like some fond memory of life")
    assertEqual(zombie.social.hates[1], "living", "Zombie should hate the living")
    assertEqual(zombie.lesserDooms[1].id, "devour_the_living",
        "Zombie should expose Devour the Living lesser doom")
    assertEqual(zombie.lesserDooms[1].effect.healWounds, 2,
        "Zombie Devour the Living should Heal 2 Wounds")
    assertEqual(zombie.lesserDooms[2].id, "fear",
        "Zombie should expose the Undead template Fear lesser doom")
    assertEqual(zombie.lesserDooms[2].effect.type, "undead_fear",
        "Zombie Fear should use the generic undead Fear runtime")
    assertEqual(zombie.greaterDooms[1].id, "last_grasp",
        "Zombie should expose Last Grasp greater doom")
    assertTrue(zombie.greaterDooms[1].effect.severedLimb.sameInitiativeAsZombie and
        zombie.greaterDooms[1].effect.severedLimb.cannotUseLastGrasp,
        "Zombie Last Grasp should preserve severed limb limits")
    assertTrue(zombie.alchemy == nil, "Zombie should not expose reagent data")

    assertTrue(entity_factory.hasBlueprint("skeleton_brute"), "Skeleton denizen blueprint should be registered")

    local skeleton = entity_factory.createEntity("skeleton_brute")
    assertTrue(skeleton ~= nil, "Skeleton blueprint should instantiate through the entity factory")
    assertEqual(skeleton.swords, 6, "Skeleton should use canonical Swords")
    assertEqual(skeleton.pentacles, 1, "Skeleton should use canonical Pentacles")
    assertEqual(skeleton.cups, 1, "Skeleton should use canonical Cups")
    assertEqual(skeleton.wands, 4, "Skeleton should use canonical Wands")
    assertEqual(skeleton.npcHealth, 6, "Skeleton should use canonical Health")
    assertEqual(skeleton.npcDefense, 0, "Skeleton should use canonical Defense")
    assertTrue(skeleton.undead and hasValue(skeleton.tags, "skeleton"),
        "Skeleton should be tagged as an undead skeleton")
    assertTrue(skeleton.skeleton and skeleton.skeleton.breathless and skeleton.skeleton.undreaming,
        "Skeleton should preserve Breathless and Undreaming")
    assertTrue(skeleton.skeleton.inspireImmune and skeleton.skeleton.piercingImmune,
        "Skeleton should preserve Empty Skulls and Fleshless")
    assertTrue(skeleton.skeleton.mustExceedInitiative,
        "Skeleton should preserve its exceed-Initiative targeting rule")
    assertEqual(skeleton.social.likes[1], "almost_nothing", "Skeleton should like almost nothing")
    assertEqual(skeleton.social.hates[1], "life", "Skeleton should hate life")
    assertEqual(skeleton.lesserDooms[1].id, "unearthly_fear",
        "Skeleton should expose Unearthly Fear lesser doom")
    assertEqual(skeleton.greaterDooms[1].id, "absorb_bones",
        "Skeleton should expose Absorb Bones greater doom")

    assertTrue(entity_factory.hasBlueprint("yellow_king_lich"),
        "Yellow King Lich denizen blueprint should be registered")

    local lich = entity_factory.createEntity("yellow_king_lich")
    assertTrue(lich ~= nil, "Yellow King Lich blueprint should instantiate through the entity factory")
    assertEqual(lich.swords, 3, "Yellow King Lich should use canonical Swords")
    assertEqual(lich.pentacles, 3, "Yellow King Lich should use canonical Pentacles")
    assertEqual(lich.cups, 3, "Yellow King Lich should use canonical Cups")
    assertEqual(lich.wands, 6, "Yellow King Lich should use canonical Wands")
    assertEqual(lich.npcHealth, 5, "Yellow King Lich body should use canonical Health")
    assertEqual(lich.npcDefense, 9, "Yellow King Lich body should use canonical Defense")
    assertTrue(lich.undead and hasValue(lich.tags, "dungeon_lord") and hasValue(lich.tags, "lich"),
