function checkCockatriceGazeRuntime()
    local gazeResolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local cockatrice = entity_factory.createEntity("cockatrice")
    local rootedTarget = base_entity.createEntity({
        id = "pc_cockatrice_rooted",
        name = "Cockatrice Rooted Target",
        isPC = true,
        wands = 4,
    })

    local rootResult = gazeResolver:resolve({
        actor = cockatrice,
        target = rootedTarget,
        type = action_resolver.ACTION_TYPES.COCKATRICE_GAZE,
        round = 1,
    })
    assertTrue(rootResult.success, "Cockatrice gaze should resolve without spending a card")
    assertTrue(rootResult.automatic and rootResult.cardValue == 0,
        "Cockatrice gaze should be marked as automatic/cardless")
    assertTrue(rootedTarget.conditions.rooted and rootedTarget.cockatriceGazeRooted,
        "Cockatrice gaze phase 1 should Root the target")
    assertTrue(hasValue(rootResult.effects, "cockatrice_gaze_rooted"),
        "Cockatrice gaze phase 1 should report Rooted")

    local repeatedRound = gazeResolver:resolve({
        actor = cockatrice,
        target = rootedTarget,
        type = action_resolver.ACTION_TYPES.COCKATRICE_GAZE,
        round = 1,
    })
    assertTrue(not repeatedRound.success, "Cockatrice gaze should be limited to once per round")
    assertTrue(hasValue(repeatedRound.effects, "cockatrice_gaze_round_spent"),
        "spent Cockatrice gaze should report the round limit")

    local recoverRooted = gazeResolver:resolve({
        actor = rootedTarget,
        card = { name = "Nine of Wands", value = 9, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.RECOVER,
        recoverEffect = "rooted",
    })
    assertTrue(recoverRooted.success, "Recover should clear Cockatrice gaze phase-1 Rooted")
    assertTrue(not rootedTarget.conditions.rooted and not rootedTarget.cockatriceGazeRooted,
        "Recover should clear Cockatrice gaze Rooted metadata")

    local stoneTarget = base_entity.createEntity({
        id = "pc_cockatrice_stone",
        name = "Cockatrice Stone Target",
        isPC = true,
        wands = 4,
    })
    local firstGaze = gazeResolver:resolve({
        actor = cockatrice,
        target = stoneTarget,
        type = action_resolver.ACTION_TYPES.COCKATRICE_GAZE,
        round = 2,
    })
    assertTrue(firstGaze.success and stoneTarget.conditions.rooted,
        "first Cockatrice gaze in a later round should Root a fresh target")

    local secondGaze = gazeResolver:resolve({
        actor = cockatrice,
        target = stoneTarget,
        type = action_resolver.ACTION_TYPES.COCKATRICE_GAZE,
        round = 3,
        mirrorReflection = true,
    })
    assertTrue(secondGaze.success, "Cockatrice gaze should petrify an already Rooted target")
    assertTrue(hasValue(secondGaze.effects, "cockatrice_gaze_not_reflected_by_mirror"),
        "Cockatrice gaze should explicitly ignore mirror reflection")
    assertTrue(hasValue(secondGaze.effects, "petrification_curse"),
        "Cockatrice gaze phase 2 should report a petrification Curse")
    assertTrue(stoneTarget.conditions.petrified and stoneTarget.conditions.petrification,
        "Cockatrice gaze phase 2 should mark petrification conditions")
    assertEqual(stoneTarget.material, "stone", "Cockatrice petrification should turn the target to stone")
    assertTrue(not stoneTarget.conditions.rooted, "Cockatrice gaze phase 2 should replace gaze Rooted")
    assertEqual(stoneTarget.malediction.curseId, "petrification",
        "Cockatrice petrification should be represented as a Curse")
    assertTrue(stoneTarget.nonRecoverableConditions.petrified == "cockatrice_gaze",
        "Cockatrice petrification should not be recoverable as a normal condition")

    local recoverPetrified = gazeResolver:resolve({
        actor = stoneTarget,
        card = { name = "Nine of Wands", value = 9, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.RECOVER,
        recoverEffect = "petrified",
    })
    assertTrue(not recoverPetrified.success, "Recover should not clear Cockatrice petrification")
    assertTrue(stoneTarget.conditions.petrified and stoneTarget.petrificationCurse,
        "failed Recover should leave Cockatrice petrification intact")

    local combatBus = events.createEventBus()
    local combatZones = zone_system.createZoneRegistry({ eventBus = combatBus })
    combatZones:setRoomZones(buildLinearZones())
    local combatResolver = action_resolver.createActionResolver({
        eventBus = combatBus,
        zoneSystem = combatZones,
    })

    local tailCockatrice = entity_factory.createEntity("cockatrice")
    tailCockatrice.id = "npc_cockatrice_tail_bite"
    tailCockatrice.zone = "A"
    local tailTarget = base_entity.createEntity({
        id = "pc_cockatrice_tail_bite",
        name = "Cockatrice Tail Bite Target",
        isPC = true,
    })
    tailTarget.zone = "A"
    combatZones:placeEntity(tailCockatrice.id, "A")
    combatZones:placeEntity(tailTarget.id, "A")

    local tailBite = combatResolver:resolve({
        actor = tailCockatrice,
        target = tailTarget,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        lesserDoom = tailCockatrice.lesserDooms[1],
        targetInitiative = 8,
        destinationZone = "B",
        allEntities = { tailCockatrice, tailTarget },
    })
    assertTrue(tailBite.success and hasValue(tailBite.effects, "cockatrice_tail_bite"),
        "Cockatrice Tail Bite should ride on a successful Attack")
    assertTrue(tailTarget.conditions.staggered and hasValue(tailBite.effects, "displaced"),
        "Cockatrice Tail Bite should both Wound and Displace the target")
    assertEqual(tailTarget.zone, "B", "Cockatrice Tail Bite should move the target to the chosen zone")

    local flutterCockatrice = entity_factory.createEntity("cockatrice")
    flutterCockatrice.id = "npc_cockatrice_flutter"
    flutterCockatrice.zone = "A"
    local flutterTargetA = base_entity.createEntity({
        id = "pc_cockatrice_flutter_a",
        name = "Cockatrice Flutter Target A",
        isPC = true,
    })
    local flutterTargetB = base_entity.createEntity({
        id = "pc_cockatrice_flutter_b",
        name = "Cockatrice Flutter Target B",
        isPC = true,
    })
    flutterTargetA.zone = "A"
    flutterTargetB.zone = "A"
    combatZones:placeEntity(flutterCockatrice.id, "A")
    combatZones:placeEntity(flutterTargetA.id, "A")
    combatZones:placeEntity(flutterTargetB.id, "A")
    combatResolver:formEngagement(flutterCockatrice, flutterTargetA)
    combatResolver:formEngagement(flutterCockatrice, flutterTargetB)

    local blockedFlutter = combatResolver:resolve({
        actor = flutterCockatrice,
        type = action_resolver.ACTION_TYPES.COCKATRICE_FLUTTER,
        destinationZone = "B",
    })
    assertTrue(not blockedFlutter.success and hasValue(blockedFlutter.effects, "cockatrice_flutter_requires_greater_doom"),
        "Cockatrice Flutter should require a greater doom")

    local flutter = combatResolver:resolve({
        actor = flutterCockatrice,
        type = action_resolver.ACTION_TYPES.COCKATRICE_FLUTTER,
        greaterDoom = flutterCockatrice.greaterDooms[2],
        destinationZone = "B",
        allEntities = { flutterCockatrice, flutterTargetA, flutterTargetB },
    })
    assertTrue(flutter.success and hasValue(flutter.effects, "cockatrice_flutter"),
        "Cockatrice Flutter should automatically disengage and move")
    assertEqual(flutterCockatrice.zone, "B", "Cockatrice Flutter should move one zone away")
    assertTrue(flutterCockatrice.flying and flutterCockatrice.conditions.flying,
        "Cockatrice Flutter should mark the cockatrice as flying")
    assertTrue(not combatResolver:areEngaged(flutterCockatrice, flutterTargetA) and
        not combatResolver:areEngaged(flutterCockatrice, flutterTargetB),
        "Cockatrice Flutter should disengage from all adventurers")
end

function checkGriffinGrabRuntime()
    local grabResolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local griffin = entity_factory.createEntity("griffin")
    griffin.id = "npc_griffin_grab"
    griffin.name = "Runtime Griffin"
    griffin.zone = "nest"
    griffin.flying = true

    local victim = base_entity.createEntity({
        id = "pc_griffin_grab_victim",
        name = "Griffin Grab Victim",
        isPC = true,
        wands = 4,
    })
    victim.zone = "nest"

    local blockedGrab = grabResolver:resolve({
        actor = griffin,
        target = victim,
        card = { name = "Ten of Pentacles", value = 10, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "grab",
        targetInitiative = 8,
    })
    assertTrue(not blockedGrab.success, "Griffin Grab should require a greater doom discard")
    assertTrue(hasValue(blockedGrab.effects, "griffin_grab_requires_greater_doom"),
        "blocked Griffin Grab should report missing greater doom")

    local grab = grabResolver:resolve({
        actor = griffin,
        target = victim,
        card = { name = "Ten of Pentacles", value = 10, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "grab",
        greaterDoom = griffin.greaterDooms[1],
        targetInitiative = 8,
        heightFeet = 20,
        flying = true,
    })
    assertTrue(grab.success, "Griffin greater-doom Roughhouse should Grab on success")
    assertTrue(victim.conditions.rooted and victim.rootedBy == "griffin_grab",
        "Griffin Grab should Root the victim")
    assertTrue(victim.griffinGrabbedBy == griffin and griffin.grabbedVictim == victim,
        "Griffin Grab should link victim and griffin")
    assertTrue(hasValue(grab.effects, "target_moves_with_griffin"),
        "Griffin Grab should report forced movement with the griffin")

    local move = grabResolver:resolve({
        actor = griffin,
        card = { name = "Six of Pentacles", value = 6, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.MOVE,
        destinationZone = "rafters",
    })
    assertTrue(move.success, "Griffin should still be able to Move while carrying a grabbed victim")
    assertEqual(victim.zone, "rafters", "grabbed victim should move with the griffin")
    assertTrue(hasValue(move.effects, "griffin_grab_victim_moved"),
        "movement should report the grabbed victim movement")

    local attacker = base_entity.createEntity({
        id = "pc_misses_griffin",
        name = "Griffin Miss Attacker",
        isPC = true,
        swords = 0,
    })
    attacker.zone = "rafters"

    local missedAttack = grabResolver:resolve({
        actor = attacker,
        target = griffin,
        card = { name = "Two of Swords", value = 2, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 20,
    })
    assertTrue(not missedAttack.success, "low-value Attack should miss the griffin")
    assertTrue(hasValue(missedAttack.effects, "miss_redirected_to_grabbed_victim"),
        "missed Attack against a grabbing griffin should hit the victim")
    assertTrue(victim.conditions.staggered,
        "redirected miss should apply a Wound to the grabbed victim")

    local recoverGrab = grabResolver:resolve({
        actor = victim,
        card = { name = "Nine of Wands", value = 9, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.RECOVER,
        recoverEffect = "rooted",
        heightFeet = 20,
    })
    assertTrue(recoverGrab.success, "Recover should clear Griffin Grab Rooted")
    assertTrue(not victim.conditions.rooted and not victim.griffinGrabbedBy and not griffin.grabbedVictim,
        "Recover should release the Griffin Grab link")
    assertTrue(recoverGrab.griffinGrabFall and recoverGrab.griffinGrabFall.wounds == 2,
        "Recovering from a flying Griffin Grab should cause falling damage")

    local dropVictim = base_entity.createEntity({
        id = "pc_griffin_drop_victim",
        name = "Griffin Drop Victim",
        isPC = true,
    })
    dropVictim.zone = "rafters"
    griffin.zone = "rafters"

    local dropGrab = grabResolver:resolve({
        actor = griffin,
        target = dropVictim,
        card = { name = "Ten of Pentacles", value = 10, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "grab",
        greaterDoom = griffin.greaterDooms[1],
        targetInitiative = 8,
        heightFeet = 10,
        flying = true,
    })
    assertTrue(dropGrab.success, "Griffin should be able to establish a second Grab")

    local drop = grabResolver:resolve({
        actor = griffin,
        type = action_resolver.ACTION_TYPES.GRIFFIN_DROP,
        heightFeet = 10,
        fallSuccess = true,
    })
    assertTrue(drop.success, "Griffin should drop a grabbed victim as a cardless free action")
    assertTrue(hasValue(drop.effects, "griffin_drop") and hasValue(drop.effects, "griffin_grab_released"),
        "Griffin drop should report drop and release")
    assertTrue(not dropVictim.conditions.rooted and not griffin.grabbedVictim,
        "Griffin drop should release the victim")
    assertTrue(drop.griffinGrabFall and drop.griffinGrabFall.wounds == 0,
        "drop fall should run through falling damage resolution")
end

function checkHarpyShriekRuntime()
    local shriekResolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local harpy = entity_factory.createEntity("harpy")
    harpy.id = "npc_harpy_shriek"
    harpy.name = "Runtime Harpy"
    harpy.zone = "roost"

    local nearbyPC = base_entity.createEntity({
        id = "pc_harpy_shriek_target",
        name = "Harpy Shriek Target",
        isPC = true,
    })
    nearbyPC.zone = "roost"
    nearbyPC.challengeHand = {
        { name = "Five of Swords", value = 5, suit = constants.SUITS.SWORDS },
        { name = "Six of Cups", value = 6, suit = constants.SUITS.CUPS },
    }

    local nearbyNPC = base_entity.createEntity({
        id = "npc_harpy_shriek_target",
        name = "Other Shriek Target",
    })
    nearbyNPC.zone = "roost"

    local otherHarpy = entity_factory.createEntity("harpy")
    otherHarpy.id = "npc_harpy_shriek_immune"
    otherHarpy.zone = "roost"

    local farTarget = base_entity.createEntity({
        id = "pc_harpy_shriek_elsewhere",
        name = "Elsewhere Shriek Target",
        isPC = true,
    })
    farTarget.zone = "hall"

    local blockedShriek = shriekResolver:resolve({
        actor = harpy,
        type = action_resolver.ACTION_TYPES.HARPY_SHRIEK,
        allEntities = { harpy, nearbyPC, nearbyNPC, otherHarpy, farTarget },
    })
    assertTrue(not blockedShriek.success, "Harpy Shriek should require a greater doom")
    assertTrue(hasValue(blockedShriek.effects, "harpy_shriek_requires_greater_doom"),
        "blocked Harpy Shriek should report missing greater doom")

    local room = { id = "harpy_roost" }
    local shriek = shriekResolver:resolve({
        actor = harpy,
        type = action_resolver.ACTION_TYPES.HARPY_SHRIEK,
        greaterDoom = harpy.greaterDooms[1],
        allEntities = { harpy, nearbyPC, nearbyNPC, otherHarpy, farTarget },
        room = room,
    })
    assertTrue(shriek.success, "Harpy Shriek should resolve as a cardless greater-doom effect")
    assertEqual(#shriek.affected, 2, "Harpy Shriek should affect same-zone non-harpies")
    assertTrue(nearbyPC.conditions.stunned and nearbyPC.conditions.stunnedInstant,
        "Harpy Shriek should Stun same-zone adventurers")
    assertEqual(#nearbyPC.challengeHand, 1, "Stunned target should discard one challenge card")
    assertTrue(nearbyNPC.conditions.stunned, "Harpy Shriek should Stun same-zone non-harpy NPCs")
    assertTrue(not otherHarpy.conditions.stunned, "Harpy Shriek should not Stun other harpies")
    assertTrue(not farTarget.conditions.stunned, "Harpy Shriek should not Stun creatures in other zones")
    assertTrue(shriek.drawsNearbyCreatures and room.loudNoise and room.loudNoise.drawsNearbyCreatures,
        "Harpy Shriek should record its nearby-creature noise consequence")
    assertTrue(hasValue(shriek.effects, "draws_nearby_creatures"),
        "Harpy Shriek should report nearby creatures being drawn to the sound")

    local flightBus = events.createEventBus()
    local flightZones = zone_system.createZoneRegistry({ eventBus = flightBus })
    flightZones:setRoomZones(buildLinearZones())
    local flightResolver = action_resolver.createActionResolver({
        eventBus = flightBus,
        zoneSystem = flightZones,
    })
    local flyingHarpy = entity_factory.createEntity("harpy")
    flyingHarpy.id = "npc_harpy_flight"
    flyingHarpy.zone = "A"
    local meleeTarget = base_entity.createEntity({
        id = "pc_harpy_flight_target",
        name = "Harpy Flight Target",
        isPC = true,
    })
    meleeTarget.zone = "A"
    flightZones:placeEntity(flyingHarpy.id, "A")
    flightZones:placeEntity(meleeTarget.id, "A")
    flightResolver:formEngagement(flyingHarpy, meleeTarget)

    local blockedFlight = flightResolver:resolve({
        actor = flyingHarpy,
        card = { name = "Five of Pentacles", value = 5, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.MOVE,
        lesserDoom = flyingHarpy.lesserDooms[1],
        destinationZone = "B",
        enoughSpace = false,
        allEntities = { flyingHarpy, meleeTarget },
    })
    assertTrue(not blockedFlight.success and hasValue(blockedFlight.effects, "harpy_flight_requires_space"),
        "Harpy Flight should require enough space")

    local flight = flightResolver:resolve({
        actor = flyingHarpy,
        card = { name = "Seven of Pentacles", value = 7, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.MOVE,
        lesserDoom = flyingHarpy.lesserDooms[1],
        destinationZone = "B",
        allEntities = { flyingHarpy, meleeTarget },
    })
    assertTrue(flight.success, "Harpy Flight should resolve through the Move action")
    assertTrue(flyingHarpy.flying and flyingHarpy.conditions.flying,
        "Harpy Flight should mark the harpy as flying")
    assertTrue(not flyingHarpy.is_engaged and not meleeTarget.is_engaged,
        "Harpy Flight should clear melee engagement")
    assertTrue(hasValue(flight.effects, "harpy_flight"),
        "Harpy Flight should report the flight state")

    meleeTarget.zone = "B"
    flightZones:placeEntity(meleeTarget.id, "B")
    local blockedMelee = flightResolver:resolve({
        actor = meleeTarget,
        target = flyingHarpy,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 5,
    })
    assertTrue(not blockedMelee.success and hasValue(blockedMelee.effects, "only_ranged_attacks_can_hit"),
        "Flying harpies should stay out of ordinary melee reach")

    local flyBy = flightResolver:resolve({
        actor = flyingHarpy,
        target = meleeTarget,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 8,
        flyByAttack = true,
    })
    assertTrue(flyBy.success and hasValue(flyBy.effects, "harpy_fly_by_attack"),
        "Flying harpies should be able to make no-engagement fly-by Attacks")
    assertTrue(flyingHarpy.harpyMeleeTargetableThisTurn and not flyingHarpy.is_engaged,
        "Harpy fly-by Attacks should expose the harpy to melee for the turn without engagement")

    local pelt = flightResolver:resolve({
        actor = flyingHarpy,
        card = { name = "Two of Cups", value = 2, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.HARPY_PELT_WITH_STONES,
        sceneryName = "Loose Roost Stone",
    })
    assertTrue(pelt.success and flyingHarpy.harpyPreparedStone,
        "Harpy Pelt with Stones should prepare scenery as a thrown missile")

    local stoneTarget = base_entity.createEntity({
        id = "pc_harpy_stone_target",
        name = "Harpy Stone Target",
        isPC = true,
    })
    stoneTarget.zone = "B"
    flightZones:placeEntity(stoneTarget.id, "B")
    local stoneAttack = flightResolver:resolve({
        actor = flyingHarpy,
        target = stoneTarget,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MISSILE,
        targetInitiative = 8,
    })
    assertTrue(stoneAttack.success and hasValue(stoneAttack.effects, "harpy_pelt_with_stones"),
        "Prepared Harpy stones should be throwable as missile Attacks while flying")
    assertTrue(stoneTarget.conditions.staggered and flyingHarpy.harpyPreparedStone == nil,
        "Harpy stone missile should wound the target and consume the prepared scenery")

    local flutterHarpy = entity_factory.createEntity("harpy")
    flutterHarpy.id = "npc_harpy_flutter"
    flutterHarpy.zone = "A"
    local blockedFlutter = flightResolver:resolve({
        actor = flutterHarpy,
        type = action_resolver.ACTION_TYPES.HARPY_FLUTTER_MOVE,
        destinationZone = "B",
    })
    assertTrue(not blockedFlutter.success and hasValue(blockedFlutter.effects, "harpy_flutter_requires_turn"),
        "Harpy Flutter should only be available on the harpy's turn")
    local flutter = flightResolver:resolve({
        actor = flutterHarpy,
        type = action_resolver.ACTION_TYPES.HARPY_FLUTTER_MOVE,
        destinationZone = "B",
        onTurn = true,
    })
    assertTrue(flutter.success and flutter.cardless and flutter.countsTowardTurnCard == false,
        "Harpy Flutter should move one zone without spending a card")
    assertEqual(flutterHarpy.zone, "B", "Harpy Flutter should move the harpy to the destination zone")

    local pullHarpy = entity_factory.createEntity("harpy")
    pullHarpy.id = "npc_harpy_pull"
    pullHarpy.zone = "A"
    local pullTarget = base_entity.createEntity({
        id = "pc_harpy_pull_target",
        name = "Harpy Pull Target",
        isPC = true,
    })
    pullTarget.zone = "A"
    flightZones:placeEntity(pullHarpy.id, "A")
    flightZones:placeEntity(pullTarget.id, "A")

    local missedPull = flightResolver:resolve({
        actor = pullHarpy,
        target = pullTarget,
        card = { name = "Six of Pentacles", value = 6, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.HARPY_PULL_INTO_AIR,
        lesserDoom = pullHarpy.lesserDooms[3],
        targetInitiative = 7,
    })
    assertTrue(not missedPull.success and not pullTarget.conditions.staggered,
        "Harpy Pull Into the Air should not add Pentacles off the harpy's turn")

    local pull = flightResolver:resolve({
        actor = pullHarpy,
        target = pullTarget,
        card = { name = "Six of Pentacles", value = 6, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.HARPY_PULL_INTO_AIR,
        lesserDoom = pullHarpy.lesserDooms[3],
        targetInitiative = 7,
        onTurn = true,
    })
    assertTrue(pull.success and hasValue(pull.effects, "harpy_pentacles_added"),
        "Harpy Pull Into the Air should add Pentacles on the harpy's turn")
    assertTrue(hasValue(pull.effects, "piercing") and pullTarget.conditions.staggered,
        "Harpy Pull Into the Air should deal Piercing damage")
    assertTrue(flightResolver:areEngaged(pullHarpy, pullTarget),
        "Harpy Pull Into the Air should engage the harpy")
end

function checkFaceRatGreaterDoomRuntime()
    local faceResolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local faceRat = entity_factory.createEntity("face_rat")
    faceRat.id = "npc_face_rat_runtime"
    faceRat.name = "Runtime Face Rat"

    local diseaseTarget = base_entity.createEntity({
        id = "pc_face_rat_disease",
        name = "Face Rat Disease Target",
        isPC = true,
        wands = 4,
    })
    local diseaseAttack = faceResolver:resolve({
        actor = faceRat,
        target = diseaseTarget,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        greaterDoom = faceRat.greaterDooms[1],
        targetInitiative = 5,
    })
    assertTrue(diseaseAttack.success, "Face Rat Infectious Disease should ride on a successful Attack")
    assertTrue(hasValue(diseaseAttack.effects, "face_rat_disease"),
        "Face Rat Infectious Disease should report the affliction")
    assertTrue(diseaseTarget.afflictions and diseaseTarget.afflictions.face_rat_disease,
        "Face Rat Infectious Disease should add the affliction record")
    assertEqual(diseaseTarget.afflictions.face_rat_disease.stageCosts[3], 2,
        "Face Rat Disease stage 3 should require two cure charges")
    assertTrue(diseaseTarget.conditions.staggered,
        "Face Rat Infectious Disease should still deal the Attack Wound")

    local socialTarget = base_entity.createEntity({
        id = "npc_face_rat_social_target",
        name = "Face Rat Social Target",
    })
    local diseasedInfluence = faceResolver:resolve({
        actor = diseaseTarget,
        target = socialTarget,
        card = { name = "Ten of Wands", value = 10, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.BANTER,
    })
    assertTrue(hasValue(diseasedInfluence.effects, "face_rat_disease_wands_disfavor"),
        "Face Rat Disease stage 1 should give disfavor on Wands influence tests")

    local faceRatDiseaseCamp = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { diseaseTarget },
    })
    faceRatDiseaseCamp.hasShelter = true
    faceRatDiseaseCamp:processEndOfCampEffects(diseaseTarget)
    assertEqual(diseaseTarget.afflictions.face_rat_disease.stage, 2,
        "Face Rat Disease should progress at camp end")
    assertTrue(diseaseTarget.conditions.silenced and diseaseTarget.faceRatDiseaseSilenced,
        "Face Rat Disease stage 2 should Silence the victim")
    assertEqual(diseaseTarget.nonRecoverableConditions.silenced, "face_rat_disease",
        "Face Rat Disease Silence should persist until the affliction is cured")
    faceRatDiseaseCamp:processEndOfCampEffects(diseaseTarget)
    assertEqual(diseaseTarget.afflictions.face_rat_disease.stage, 3,
        "Face Rat Disease should continue progressing through its affliction clock")
    assertTrue(diseaseTarget.conditions.blind and diseaseTarget.conditions.blinded and
        diseaseTarget.faceRatDiseaseBlind,
        "Face Rat Disease stage 3 should Blind the victim")
    assertEqual(diseaseTarget.nonRecoverableConditions.blind, "face_rat_disease",
        "Face Rat Disease Blind should persist until the affliction is cured")
    assertTrue(faceRatDiseaseCamp:applyAfflictionCharges(diseaseTarget, "face_rat_disease", 2, "test"),
        "Face Rat Disease stage 3 should accept its two cure charges")
    assertEqual(diseaseTarget.afflictions.face_rat_disease.stage, 2,
        "Curing Face Rat Disease stage 3 should regress to stage 2")
    assertTrue(not diseaseTarget.conditions.blind and not diseaseTarget.conditions.blinded and
        not diseaseTarget.faceRatDiseaseBlind,
        "Curing Face Rat Disease stage 3 should clear Blind")
    assertTrue(diseaseTarget.conditions.silenced and diseaseTarget.faceRatDiseaseSilenced,
        "Curing Face Rat Disease stage 3 should leave stage 2 Silence in place")
    assertTrue(faceRatDiseaseCamp:applyAfflictionCharges(diseaseTarget, "face_rat_disease", 1, "test"),
        "Face Rat Disease stage 2 should accept its cure charge")
    assertEqual(diseaseTarget.afflictions.face_rat_disease.stage, 1,
        "Curing Face Rat Disease stage 2 should regress to stage 1")
    assertTrue(not diseaseTarget.conditions.silenced and not diseaseTarget.faceRatDiseaseSilenced,
        "Curing Face Rat Disease stage 2 should clear Silence")
    assertTrue(diseaseTarget.conditions.face_rat_featureless_mask and diseaseTarget.faceRatDiseaseWandsDisfavor,
        "Curing Face Rat Disease stage 2 should leave stage 1 effects in place")
    assertTrue(faceRatDiseaseCamp:applyAfflictionCharges(diseaseTarget, "face_rat_disease", 1, "test"),
        "Face Rat Disease stage 1 should accept its cure charge")
    assertTrue(not diseaseTarget.afflictions.face_rat_disease,
        "Curing Face Rat Disease stage 1 should remove the affliction")
    assertTrue(not diseaseTarget.conditions.face_rat_featureless_mask and
        not diseaseTarget.faceRatDiseaseWandsDisfavor,
        "Fully curing Face Rat Disease should clear stage 1 effects")

    local stealTarget = base_entity.createEntity({
        id = "pc_face_rat_steal_face",
        name = "Face Rat Steal Face Target",
        isPC = true,
        wands = 4,
    })
    local stealFace = faceResolver:resolve({
        actor = faceRat,
        target = stealTarget,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        greaterDoom = faceRat.greaterDooms[2],
        targetInitiative = 5,
    })
    assertTrue(stealFace.success, "Face Rat Steal Face should ride on a successful Attack")
    assertEqual(stealFace.damageDealt, 0, "Face Rat Steal Face should replace the Wound")
    assertTrue(not stealTarget.conditions.staggered,
        "Face Rat Steal Face should not apply normal wound-track damage")
    assertTrue(stealTarget.conditions.blind and stealTarget.conditions.blinded and stealTarget.conditions.silenced,
        "Face Rat Steal Face should Blind and Silence the victim")
    assertTrue(faceRat.stolenFaces and faceRat.stolenFaces[1].victim == stealTarget,
        "Face Rat Steal Face should permanently copy the victim's face")

    local recoverBlind = faceResolver:resolve({
        actor = stealTarget,
        card = { name = "Nine of Wands", value = 9, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.RECOVER,
        recoverEffect = "blind",
    })
    assertTrue(recoverBlind.success, "Recover should clear the stolen-face Blind effect")
    assertTrue(not stealTarget.conditions.blind and stealTarget.conditions.silenced,
        "Recovering Blind should leave stolen-face Silence in place")

    local recoverSilence = faceResolver:resolve({
        actor = stealTarget,
        card = { name = "Nine of Wands", value = 9, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.RECOVER,
        recoverEffect = "silence",
    })
    assertTrue(recoverSilence.success, "Recover should separately clear the stolen-face Silence effect")
    assertTrue(not stealTarget.conditions.silenced,
        "Recovering Silence should finish clearing the stolen-face conditions")
end

function checkFaceRatBadLittleHandsRuntime()
    local badHandsResolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local faceRat = entity_factory.createEntity("face_rat")
    faceRat.id = "npc_face_rat_bad_hands"
    faceRat.name = "Bad Hands Face Rat"

    local target = base_entity.createEntity({
        id = "pc_bad_hands_target",
        name = "Bad Hands Target",
        isPC = true,
    })
    target.inventory = inventory.createInventory()
    local torch = inventory.createItemFromTemplate("torch")
    target.inventory:addItem(torch, inventory.LOCATIONS.BELT)

    local steal = badHandsResolver:resolve({
        actor = faceRat,
        target = target,
        card = { name = "Ten of Pentacles", value = 10, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "bad_little_hands",
        lesserDoom = faceRat.lesserDooms[1],
        targetInitiative = 5,
    })
    assertTrue(steal.success, "Face Rat Bad Little Hands should steal a belt item on a successful Roughhouse")
    assertTrue(hasValue(steal.effects, "bad_little_hands") and hasValue(steal.effects, "belt_item_stolen"),
        "Bad Little Hands should report belt item theft")
    local remainingTorch = target.inventory:findItem(torch.id)
    assertTrue(remainingTorch == nil, "stolen belt item should leave the target inventory")
    assertTrue(faceRat.badLittleHands and faceRat.badLittleHands[1] == torch,
        "Face Rat should hold the stolen item in Bad Little Hands")
    assertTrue(faceRat.stolenItems and faceRat.stolenItems[1].from == target,
        "Bad Little Hands should remember the original owner for recovery")
    assertTrue(torch.heldInBadLittleHands and torch.stolenBy == faceRat.id,
        "stolen item should be marked as held by the Face Rat")
    local ratInventoryItem = faceRat.inventory and faceRat.inventory.findItem and faceRat.inventory:findItem(torch.id)
    assertTrue(ratInventoryItem == nil, "Face Rat should not gain usable inventory access to the stolen item")

    local disarmer = base_entity.createEntity({
        id = "pc_bad_hands_disarmer",
        name = "Bad Hands Disarmer",
        isPC = true,
        pentacles = 4,
    })
    disarmer.inventory = inventory.createInventory()
    local recovered = badHandsResolver:resolve({
        actor = disarmer,
        target = faceRat,
        card = { name = "Ten of Pentacles", value = 10, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.DISARM,
        targetInitiative = 2,
    })
    assertTrue(recovered.success, "Disarm should recover an item held in Bad Little Hands")
    assertTrue(hasValue(recovered.effects, "bad_little_hands_item_recovered"),
        "Disarm recovery should report Bad Little Hands recovery")
    local recoveredTorch, recoveredLocation = target.inventory:findItem(torch.id)
    assertTrue(recoveredTorch == torch and recoveredLocation == inventory.LOCATIONS.BELT,
        "Disarm should return the stolen item to its original belt slot")
    assertTrue(#(faceRat.badLittleHands or {}) == 0 and #(faceRat.stolenItems or {}) == 0,
        "Disarm recovery should clear the Face Rat's stolen item state")
    assertTrue(not torch.heldInBadLittleHands and torch.stolenBy == nil,
        "Disarm recovery should clear stolen-item metadata")

    local emptyTarget = base_entity.createEntity({
        id = "pc_bad_hands_empty_belt",
        name = "Empty Belt Target",
        isPC = true,
    })
    emptyTarget.inventory = inventory.createInventory()
    local noBeltItem = badHandsResolver:resolve({
        actor = entity_factory.createEntity("face_rat"),
        target = emptyTarget,
        card = { name = "Ten of Pentacles", value = 10, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "bad_little_hands",
        targetInitiative = 5,
    })
    assertTrue(not noBeltItem.success, "Bad Little Hands should fail cleanly when the target has no belt item")
    assertTrue(hasValue(noBeltItem.effects, "bad_little_hands_no_belt_item"),
        "empty belt failure should be reported explicitly")

    local missedRat = entity_factory.createEntity("face_rat")
    local missedTarget = base_entity.createEntity({
        id = "pc_bad_hands_missed_target",
        name = "Missed Bad Hands Target",
        isPC = true,
    })
    missedTarget.inventory = inventory.createInventory()
    local missedRope = inventory.createItemFromTemplate("rope")
    missedTarget.inventory:addItem(missedRope, inventory.LOCATIONS.BELT)
    local missed = badHandsResolver:resolve({
        actor = missedRat,
        target = missedTarget,
        card = { name = "Two of Pentacles", value = 2, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "bad_little_hands",
        targetInitiative = 9,
    })
    assertTrue(not missed.success, "failed Bad Little Hands contest should not steal an item")
    local unStolenRope, unStolenLocation = missedTarget.inventory:findItem(missedRope.id)
    assertTrue(unStolenRope == missedRope and unStolenLocation == inventory.LOCATIONS.BELT,
        "failed Bad Little Hands contest should leave the belt item in place")

    local killedRat = entity_factory.createEntity("face_rat")
    local killTarget = base_entity.createEntity({
        id = "pc_bad_hands_kill_target",
        name = "Bad Hands Kill Target",
        isPC = true,
    })
    killTarget.inventory = inventory.createInventory()
    local oil = inventory.createItemFromTemplate("oil")
    killTarget.inventory:addItem(oil, inventory.LOCATIONS.BELT)
    local killSteal = badHandsResolver:resolve({
        actor = killedRat,
        target = killTarget,
        card = { name = "Ten of Pentacles", value = 10, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "steal_belt_item",
        targetInitiative = 5,
    })
    assertTrue(killSteal.success, "Bad Little Hands should also normalize steal_belt_item effect text")

    local killEffects = {}
    badHandsResolver:applyDamage(killedRat, 1, killEffects)
    badHandsResolver:applyDamage(killedRat, 1, killEffects)
    assertTrue(killedRat.badLittleHands and #killedRat.badLittleHands == 1,
        "Face Rat should keep the stolen item until it is actually killed")
    badHandsResolver:applyDamage(killedRat, 1, killEffects)
    assertTrue(hasValue(killEffects, "bad_little_hands_items_released_on_defeat"),
        "killing the Face Rat should release Bad Little Hands items")
    local recoveredOil, recoveredOilLocation = killTarget.inventory:findItem(oil.id)
    assertTrue(recoveredOil == oil and recoveredOilLocation == inventory.LOCATIONS.BELT,
        "killing the Face Rat should return the stolen item to its original owner")
end

function checkLionAttackRuntime()
    local lionResolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local lion = entity_factory.createEntity("lion")
    lion.id = "npc_lion_runtime"

    local disarmTarget = base_entity.createEntity({
        id = "pc_lion_bite_disarm",
        name = "Lion Bite Disarm Target",
        isPC = true,
    })
    disarmTarget.inventory = inventory.createInventory()
    local dagger = inventory.createItemFromTemplate("dagger")
    local biteShield = inventory.createItemFromTemplate("shield_light")
    disarmTarget.inventory:addItem(dagger, inventory.LOCATIONS.HANDS)
    disarmTarget.inventory:addItem(biteShield, inventory.LOCATIONS.HANDS)

    local biteDisarm = lionResolver:resolve({
        actor = lion,
        target = disarmTarget,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        lesserDoom = lion.lesserDooms[1],
        lesserDoomChoice = "disarmed",
        disarmItemId = biteShield.id,
        targetInitiative = 8,
    })
    assertTrue(biteDisarm.success, "Lion Bite should ride on a successful Attack")
    assertTrue(hasValue(biteDisarm.effects, "lion_bite") and hasValue(biteDisarm.effects, "disarmed"),
        "Lion Bite should report the chosen Disarm rider")
    assertTrue(disarmTarget.conditions.disarmed and biteDisarm.droppedItem == biteShield,
        "Lion Bite Disarm should drop the chosen held item without a second contest")
    local heldDagger = disarmTarget.inventory:findItem(dagger.id)
    assertTrue(heldDagger == dagger, "Lion Bite Disarm should leave other held items in the target's hands")
    local heldBiteShield = disarmTarget.inventory:findItem(biteShield.id)
    assertTrue(heldBiteShield == nil, "Lion Bite Disarm should remove the chosen item from the target's hands")

    local tripTarget = base_entity.createEntity({
        id = "pc_lion_bite_trip",
        name = "Lion Bite Trip Target",
        isPC = true,
    })
    tripTarget.inventory = inventory.createInventory()
    local biteTrip = lionResolver:resolve({
        actor = lion,
        target = tripTarget,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        lesserDoom = lion.lesserDooms[1],
        lesserDoomChoice = "tripped",
        targetInitiative = 8,
    })
    assertTrue(biteTrip.success, "Lion Bite Trip should ride on a successful Attack")
    assertTrue(tripTarget.conditions.prone and hasValue(biteTrip.effects, "lion_bite_trip"),
        "Lion Bite Trip should make the target prone without a second contest")

    local clawTarget = base_entity.createEntity({
        id = "pc_lion_claw_double",
        name = "Lion Claw Double Target",
        isPC = true,
    })
    clawTarget.inventory = inventory.createInventory()
    local claw = lionResolver:resolve({
        actor = lion,
        target = clawTarget,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        lesserDoom = lion.lesserDooms[2],
        targetInitiative = 8,
    })
    assertTrue(claw.success, "Lion Claw should hit normally before checking the double-Initiative rider")
    assertEqual(claw.damageDealt, 2, "Lion Claw should deal 2 Wounds when attack value doubles Initiative")
    assertTrue(hasValue(claw.effects, "lion_claw_double_initiative"),
        "Lion Claw should report its double-Initiative rider")
    assertTrue(clawTarget.conditions.staggered and clawTarget.conditions.injured,
        "Lion Claw double-Initiative damage should apply two Wounds")

    local ordinaryClawTarget = base_entity.createEntity({
        id = "pc_lion_claw_ordinary",
        name = "Lion Claw Ordinary Target",
        isPC = true,
    })
    ordinaryClawTarget.inventory = inventory.createInventory()
    local ordinaryClaw = lionResolver:resolve({
        actor = lion,
        target = ordinaryClawTarget,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        lesserDoom = lion.lesserDooms[2],
        targetInitiative = 10,
    })
    assertTrue(ordinaryClaw.success, "Lion Claw should still hit when it beats but does not double Initiative")
    assertEqual(ordinaryClaw.damageDealt, 1,
        "Lion Claw should not increase damage when attack value does not double Initiative")
    assertTrue(not hasValue(ordinaryClaw.effects, "lion_claw_double_initiative"),
        "ordinary Lion Claw hit should not report the double-Initiative rider")

    local retreatBus = events.createEventBus()
    local zones = zone_system.createZoneRegistry({ eventBus = retreatBus })
    local retreatResolver = action_resolver.createActionResolver({
        eventBus = retreatBus,
        zoneSystem = zones,
    })
    local retreatLion = entity_factory.createEntity("lion")
    retreatLion.id = "npc_lion_cautious_retreat"
    local firstAdventurer = base_entity.createEntity({
        id = "pc_lion_retreat_first",
        name = "First Lion Retreat Target",
        isPC = true,
    })
    local secondAdventurer = base_entity.createEntity({
        id = "pc_lion_retreat_second",
        name = "Second Lion Retreat Target",
        isPC = true,
    })
    retreatResolver:formEngagement(retreatLion, firstAdventurer)
    retreatResolver:formEngagement(retreatLion, secondAdventurer)

    local blockedRetreat = retreatResolver:resolve({
        actor = retreatLion,
        target = firstAdventurer,
        type = action_resolver.ACTION_TYPES.LION_CAUTIOUS_RETREAT,
    })
    assertTrue(not blockedRetreat.success, "Lion Cautious Retreat should require a greater doom")
    assertTrue(hasValue(blockedRetreat.effects, "lion_cautious_retreat_requires_greater_doom"),
        "blocked Lion Cautious Retreat should report the missing greater doom")

    local retreat = retreatResolver:resolve({
        actor = retreatLion,
        target = firstAdventurer,
        type = action_resolver.ACTION_TYPES.LION_CAUTIOUS_RETREAT,
        greaterDoom = retreatLion.greaterDooms[1],
    })
    assertTrue(retreat.success, "Lion Cautious Retreat should resolve as a cardless greater-doom action")
    assertTrue(retreat.countsTowardTurnCard == false and retreat.cardless,
        "Lion Cautious Retreat should not count toward the lion's one-card turn limit")
    assertTrue(not zones:areEngaged(retreatLion.id, firstAdventurer.id),
        "Lion Cautious Retreat should disengage from the selected adventurer")
    assertTrue(zones:areEngaged(retreatLion.id, secondAdventurer.id),
        "Lion Cautious Retreat should leave other engagements intact")

    local fleetLion = entity_factory.createEntity("lion")
    fleetLion.id = "npc_lion_fleet"
    fleetLion.zone = "A"
    local blockedFleet = lionResolver:resolve({
        actor = fleetLion,
        type = action_resolver.ACTION_TYPES.LION_FLEET_MOVE,
        destinationZone = "B",
    })
    assertTrue(not blockedFleet.success and hasValue(blockedFleet.effects, "lion_fleet_requires_turn"),
        "Lion Fleet should only be available on the lion's turn")

    local fleet = lionResolver:resolve({
        actor = fleetLion,
        type = action_resolver.ACTION_TYPES.LION_FLEET_MOVE,
        destinationZone = "B",
        onTurn = true,
    })
    assertTrue(fleet.success and fleet.countsTowardTurnCard == false and fleet.cardless,
        "Lion Fleet should move one zone without spending the lion's turn card")
    assertEqual(fleetLion.zone, "B", "Lion Fleet should move the lion to the destination zone")
    assertTrue(hasValue(fleet.effects, "lion_fleet"),
        "Lion Fleet should report its rulebook movement rider")

    local untrackableBus = events.createEventBus()
    local untrackableFateRequests = 0
    local untrackableEvent = nil
    untrackableBus:on(events.EVENTS.REQUEST_TEST_OF_FATE, function()
        untrackableFateRequests = untrackableFateRequests + 1
    end)
    untrackableBus:on("lion_untrackable_tracking_prevented", function(data)
        untrackableEvent = data
    end)
    local untrackableResolver = action_resolver.createActionResolver({
        eventBus = untrackableBus,
    })
    local trackerOwner = base_entity.createEntity({
        id = "pc_lion_tracker_owner",
        name = "Lion Tracker",
        isPC = true,
    })
    local trackingHound = {
        id = "hound_lion_tracker",
        name = "Lion Tracker Hound",
        conditions = {},
        knownCommands = { "Track" },
    }
    trackerOwner.companion = trackingHound
    local huntedLion = entity_factory.createEntity("lion")
    huntedLion.id = "npc_lion_untrackable"
    huntedLion.knowsItIsBeingHunted = true

    local blockedTrack = untrackableResolver:resolve({
        actor = trackerOwner,
        companion = trackingHound,
        card = { name = "Three of Cups", value = 3, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.COMMAND,
        commandName = "Track",
        trackSubject = huntedLion,
        contestedCommand = false,
    })
    assertTrue(not blockedTrack.success, "Lion Untrackable should block companion Track")
    assertTrue(hasValue(blockedTrack.effects, "lion_untrackable") and
        hasValue(blockedTrack.effects, "tracking_prevented"),
        "blocked Lion tracking should report the Untrackable rider")
    assertTrue(trackingHound.tracking == nil,
        "blocked Lion tracking should not leave the companion following a trail")
    assertTrue(huntedLion.tracksCoveredByTail and huntedLion.lion.tracksCoveredByTail,
        "a hunted lion should mark its tracks as covered by its tail")
    assertTrue(untrackableEvent and untrackableEvent.lion == huntedLion,
        "Lion Untrackable should emit the blocked tracking event")

    local blockedFate = untrackableResolver:resolve({
        actor = trackerOwner,
        target = huntedLion,
        card = { name = "Five of Pentacles", value = 5, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.TEST_FATE,
        testContext = "tracking the lion through the scrub",
    })
    assertTrue(not blockedFate.success and not blockedFate.pendingTestOfFate,
        "Lion Untrackable should block tracking Test of Fate before a request is emitted")
    assertTrue(hasValue(blockedFate.effects, "tracks_covered_by_tail"),
        "blocked Lion tracking Test of Fate should record tail-covered tracks")
    assertEqual(untrackableFateRequests, 0,
        "Lion Untrackable should not emit a Test of Fate request for impossible tracking")

    local unawareLion = entity_factory.createEntity("lion")
    unawareLion.id = "npc_lion_trackable_unaware"
    local ordinaryTracker = {
        id = "hound_lion_tracker_ordinary",
        name = "Ordinary Lion Tracker Hound",
        conditions = {},
        knownCommands = { "Track" },
    }
    local ordinaryTrack = untrackableResolver:resolve({
        actor = trackerOwner,
        companion = ordinaryTracker,
        card = { name = "Three of Cups", value = 3, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.COMMAND,
        commandName = "Track",
        trackSubject = unawareLion,
        contestedCommand = false,
    })
    assertTrue(ordinaryTrack.success and hasValue(ordinaryTrack.effects, "companion_track"),
        "a lion that does not know it is hunted should remain trackable")
    assertTrue(ordinaryTracker.tracking and ordinaryTracker.tracking.subject == unawareLion,
        "ordinary Lion tracking should still record the followed trail")

    local mercyLion = entity_factory.createEntity("lion")
    mercyLion.id = "npc_lion_noble_mercy"
    local mercyTarget = base_entity.createEntity({
        id = "pc_lion_mercy_supplicant",
        name = "Lion Mercy Supplicant",
        isPC = true,
    })
    mercyTarget.conditions.prostrating = true
    mercyTarget.conditions.askingMercy = true
    local nobleMercy = lionResolver:resolve({
        actor = mercyLion,
        target = mercyTarget,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 1,
    })
    assertTrue(not nobleMercy.success, "Lion Noble Mercy should prevent attacks against mercy supplicants")
    assertTrue(hasValue(nobleMercy.effects, "lion_noble_mercy") and
        hasValue(nobleMercy.effects, "attack_prevented"),
        "Lion Noble Mercy should report the attack refusal")
    assertTrue(mercyTarget.sparedByLionMercy and not mercyTarget.conditions.staggered,
        "Lion Noble Mercy should spare the supplicant without applying a Wound")

    local sinfulDead = base_entity.createEntity({
        id = "pc_lion_roar_sinful",
        name = "Sinful Dead",
        isPC = true,
    })
    sinfulDead.conditions.dead = true
    local blockedRoar = lionResolver:resolve({
        actor = lion,
        target = sinfulDead,
        type = action_resolver.ACTION_TYPES.LION_ROAR_OF_LIFE,
        greaterDoom = lion.greaterDooms[2],
    })
    assertTrue(not blockedRoar.success and sinfulDead.conditions.dead,
        "Lion Roar of Life should require a creature that died without sin")
    assertTrue(hasValue(blockedRoar.effects, "lion_roar_of_life_requires_sinless_dead"),
        "blocked Roar of Life should report the sinless-dead requirement")

    local sinlessDead = base_entity.createEntity({
        id = "pc_lion_roar_sinless",
        name = "Sinless Dead",
        isPC = true,
    })
    sinlessDead.conditions.dead = true
    sinlessDead.conditions.deaths_door = true
    sinlessDead.isChild = true
    local roar = lionResolver:resolve({
        actor = lion,
        target = sinlessDead,
        type = action_resolver.ACTION_TYPES.LION_ROAR_OF_LIFE,
        greaterDoom = lion.greaterDooms[2],
        greaterDoomCard = major(17),
    })
    assertTrue(roar.success and hasValue(roar.effects, "lion_roar_of_life") and
        hasValue(roar.effects, "sinless_dead_revived"),
        "Lion Roar of Life should revive sinless dead creatures")
    assertTrue(not sinlessDead.conditions.dead and not sinlessDead.conditions.deaths_door,
        "Lion Roar of Life should clear dead and Death's Door state")
    assertTrue(sinlessDead.revivedByLionRoar and sinlessDead.revivedByLionRoar.sinless,
        "Lion Roar of Life should preserve revival metadata")
end

function checkDragonRuntime()
    local dragonResolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local dragon = entity_factory.createEntity("dragon")
    dragon.id = "npc_dragon_runtime"
    dragon.zone = "hoard"

    local armoredScalesAttacker = base_entity.createEntity({
        id = "pc_dragon_armored_scales_attacker",
        name = "Dragon Armored Scales Attacker",
        isPC = true,
        swords = 0,
    })
    local armoredScales = dragonResolver:resolve({
        actor = armoredScalesAttacker,
        target = dragon,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetGreaterDoom = dragon.greaterDooms[1],
        targetInitiativeCard = { name = "Greater Doom XVII", value = 17, is_major = true },
    })
    assertTrue(not armoredScales.success, "Dragon Armored Scales should let the dragon use a greater doom as Initiative")
    assertEqual(armoredScales.difficulty, 17, "Dragon Armored Scales should set Initiative from the greater doom")
    assertTrue(hasValue(armoredScales.effects, "dragon_armored_scales"),
        "Dragon Armored Scales should report greater-doom Initiative")

    local clawTarget = base_entity.createEntity({
        id = "pc_dragon_claw",
        name = "Dragon Claw Target",
        isPC = true,
    })
    clawTarget.inventory = inventory.createInventory()
    local claw = dragonResolver:resolve({
        actor = dragon,
        target = clawTarget,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        lesserDoom = dragon.lesserDooms[1],
        targetInitiative = 8,
    })
    assertTrue(claw.success, "Dragon Claw should ride on a successful Attack")
    assertEqual(claw.damageDealt, 2, "Dragon Claw should deal 2 Wounds when the attack doubles Initiative")
    assertTrue(hasValue(claw.effects, "dragon_claw_double_initiative"),
        "Dragon Claw should report its double-Initiative rider")
    assertTrue(clawTarget.conditions.staggered and clawTarget.conditions.injured,
        "Dragon Claw double-Initiative damage should apply two Wounds")

    local tailPrimary = base_entity.createEntity({
        id = "pc_dragon_tail_primary",
        name = "Dragon Tail Primary",
        isPC = true,
    })
    tailPrimary.zone = "hoard"
    tailPrimary.inventory = inventory.createInventory()
    local tailSecondary = base_entity.createEntity({
        id = "pc_dragon_tail_secondary",
        name = "Dragon Tail Secondary",
        isPC = true,
    })
    tailSecondary.zone = "hoard"
    tailSecondary.inventory = inventory.createInventory()
    local farAdventurer = base_entity.createEntity({
        id = "pc_dragon_tail_far",
        name = "Dragon Tail Far",
        isPC = true,
    })
    farAdventurer.zone = "far"
    local bystander = base_entity.createEntity({
        id = "npc_dragon_tail_bystander",
        name = "Dragon Tail Bystander",
        isPC = false,
    })
    bystander.zone = "hoard"

    local tailWhip = dragonResolver:resolve({
        actor = dragon,
        target = tailPrimary,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        lesserDoom = dragon.lesserDooms[3],
        targetInitiative = 8,
        targetInitiatives = {
            pc_dragon_tail_secondary = 8,
        },
        allEntities = { dragon, tailPrimary, tailSecondary, farAdventurer, bystander },
    })
    assertTrue(tailWhip.success, "Dragon Tail Whip primary Attack should resolve normally")
    assertTrue(hasValue(tailWhip.effects, "dragon_tail_whip"),
        "Dragon Tail Whip should report its zone Attack rider")
    assertEqual(#(tailWhip.zoneAttackResults or {}), 1,
        "Dragon Tail Whip should only follow up against same-zone adventurers")
    assertTrue(tailPrimary.conditions.staggered and tailSecondary.conditions.staggered,
        "Dragon Tail Whip should wound primary and same-zone adventurer targets")
    assertTrue(not farAdventurer.conditions.staggered and not bystander.conditions.deaths_door,
        "Dragon Tail Whip should skip far adventurers and non-adventurers")

    local flightBus = events.createEventBus()
    local flightZones = zone_system.createZoneRegistry({ eventBus = flightBus })
    local flightResolver = action_resolver.createActionResolver({
        eventBus = flightBus,
        zoneSystem = flightZones,
    })
    flightZones:setRoomZones({
        zone_system.createZone({ id = "ground" }),
        zone_system.createZone({ id = "air" }),
    })
    local flyingDragon = entity_factory.createEntity("dragon")
    flyingDragon.id = "npc_dragon_flight"
    flyingDragon.zone = "ground"
    local flightTarget = base_entity.createEntity({
        id = "pc_dragon_flight_target",
        name = "Dragon Flight Target",
        isPC = true,
    })
    flightTarget.zone = "ground"
    flightZones:placeEntity(flyingDragon.id, "ground")
    flightZones:placeEntity(flightTarget.id, "ground")
    flightResolver:formEngagement(flyingDragon, flightTarget)
    local flight = flightResolver:resolve({
        actor = flyingDragon,
        card = { name = "Seven of Pentacles", value = 7, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.MOVE,
        lesserDoom = flyingDragon.lesserDooms[2],
        destinationZone = "air",
        allEntities = { flyingDragon, flightTarget },
    })
    assertTrue(flight.success, "Dragon Flight should resolve through the Move action")
    assertTrue(flyingDragon.flying and flyingDragon.conditions.flying,
        "Dragon Flight should mark the dragon as flying")
    assertTrue(not flyingDragon.is_engaged and not flightTarget.is_engaged,
        "Dragon Flight should clear melee engagement")
    assertTrue(hasValue(flight.effects, "dragon_flight"),
        "Dragon Flight should report the flight state")

    local flyBy = flightResolver:resolve({
        actor = flyingDragon,
        target = flightTarget,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 8,
        flyByAttack = true,
    })
    assertTrue(flyBy.success, "Flying dragon should be able to make a fly-by Attack")
    assertTrue(hasValue(flyBy.effects, "dragon_fly_by_attack"),
        "Dragon fly-by Attack should report the no-engagement attack")
    assertTrue(not flyingDragon.is_engaged and not flightTarget.is_engaged,
        "Dragon fly-by Attack should not form melee engagement")

    local breathTarget = base_entity.createEntity({
        id = "pc_dragon_breath_unarmored",
        name = "Dragon Breath Unarmored",
        isPC = true,
    })
    breathTarget.zone = "near"
    breathTarget.inventory = inventory.createInventory()
    local breath = dragonResolver:resolve({
        actor = dragon,
        target = breathTarget,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MISSILE,
        greaterDoom = dragon.greaterDooms[2],
        targetInitiative = 8,
    })
    assertTrue(breath.success, "Dragon Breath of Fire should ride on a successful Attack")
    assertEqual(breath.damageDealt, 3, "Dragon Breath of Fire should deal 3 Wounds to unarmored targets")
    assertTrue(hasValue(breath.effects, "dragon_breath_of_fire") and
        hasValue(breath.effects, "dragon_breath_unarmored"),
        "Dragon Breath of Fire should report unarmored fire damage")
    assertTrue(breathTarget.conditions.staggered and breathTarget.conditions.injured and
        breathTarget.conditions.deaths_door,
        "Dragon Breath of Fire should apply three Wounds to unarmored targets")

    local metalTarget = base_entity.createEntity({
        id = "pc_dragon_breath_metal",
        name = "Dragon Breath Metal Armor",
        isPC = true,
    })
    metalTarget.zone = "near"
    metalTarget.inventory = inventory.createInventory()
    metalTarget.inventory:addItem(inventory.createItemFromTemplate("iron_armor"), inventory.LOCATIONS.BELT)
    local metalBreath = dragonResolver:resolve({
        actor = dragon,
        target = metalTarget,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MISSILE,
        greaterDoom = dragon.greaterDooms[2],
        targetInitiative = 8,
    })
    assertTrue(metalBreath.success, "Dragon Breath of Fire should hit metal-armored targets")
    assertEqual(metalBreath.damageDealt, 1,
        "Dragon Breath of Fire should apply one Critical Wound to metal-armored targets")
    assertTrue(hasValue(metalBreath.effects, "critical") and
        hasValue(metalBreath.effects, "dragon_breath_metal_armor"),
        "Dragon Breath of Fire should report Critical metal-armor damage")
    assertTrue(metalTarget.conditions.injured and not metalTarget.conditions.staggered,
        "Dragon Breath of Fire Critical damage should bypass earlier wound slots")

    local protectedTarget = base_entity.createEntity({
        id = "pc_dragon_breath_protected",
        name = "Dragon Breath Protected",
        isPC = true,
    })
    protectedTarget.zone = "near"
    protectedTarget.elementProtections = {
        fire_ward = {
            active = true,
            elementSet = { fire = true },
        },
    }
    protectedTarget.protectedElements = { fire = true }
    local protectedBreath = dragonResolver:resolve({
        actor = dragon,
        target = protectedTarget,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MISSILE,
        greaterDoom = dragon.greaterDooms[2],
        targetInitiative = 8,
    })
    assertTrue(protectedBreath.success, "Dragon Breath of Fire should still hit fire-protected targets")
    assertEqual(protectedBreath.damageDealt, 0,
        "Protection from the Elements fire should prevent Dragon Breath of Fire damage")
    assertTrue(not protectedTarget.conditions.staggered and not protectedTarget.conditions.injured,
        "fire-protected targets should take no Dragon Breath of Fire wounds")
    assertTrue(hasValue(protectedBreath.effects, "protection_from_elements_fire_block"),
        "Dragon Breath of Fire should report elemental protection blocking the fire")

    local biteTarget = base_entity.createEntity({
        id = "pc_dragon_bite",
        name = "Dragon Bite Target",
        isPC = true,
    })
    biteTarget.inventory = inventory.createInventory()
    local overwhelmingBite = dragonResolver:resolve({
        actor = dragon,
        target = biteTarget,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        greaterDoom = dragon.greaterDooms[3],
        greaterDoomChoice = "tripped",
        targetInitiative = 8,
    })
    assertTrue(overwhelmingBite.success, "Dragon Overwhelming Bite should ride on a successful Attack")
    assertEqual(overwhelmingBite.damageDealt, 1, "Dragon Overwhelming Bite should still deal the base Wound")
    assertTrue(biteTarget.conditions.prone and biteTarget.conditions.staggered,
        "Dragon Overwhelming Bite should wound and Trip the target")
    assertTrue(hasValue(overwhelmingBite.effects, "dragon_overwhelming_bite_trip"),
        "Dragon Overwhelming Bite should report the chosen rider")
end

function checkTitanSporehulkRuntime()
    local titanResolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local titan = entity_factory.createEntity("titan_sporehulk")
    titan.id = "npc_titan_runtime"
    titan.zone = "legs"

    local attacker = base_entity.createEntity({
        id = "pc_titan_attacker",
        name = "Titan Attacker",
        isPC = true,
        swords = 4,
        pentacles = 4,
    })
    attacker.zone = "legs"
    attacker.inventory = inventory.createInventory()
    attacker.inventory:addItem(inventory.createItemFromTemplate("longsword"), inventory.LOCATIONS.HANDS)

    local protectedHit = titanResolver:resolve({
        actor = attacker,
        target = titan,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetSection = "legs",
        targetInitiative = 8,
    })
    assertTrue(protectedHit.success, "Sporehulk protected body hit should win the attack contest")
    assertTrue(hasValue(protectedHit.effects, "titan_rune_protection_immune"),
        "Sporehulk rune should block ordinary section damage before it is destroyed")
    assertEqual((titan.titanSections and titan.titanSections.legs and titan.titanSections.legs.health) or
        titan.titan.sections.legs.health, 4,
        "Sporehulk rune protection should leave Legs Health unchanged")

    local blockedRune = titanResolver:resolve({
        actor = attacker,
        target = titan,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetRune = true,
        targetInitiative = 8,
    })
    assertTrue(not blockedRune.success, "Ground rune melee should be blocked before the attack contest")
    assertTrue(hasValue(blockedRune.effects, "titan_section_melee_requires_climb"),
        "Melee rune attack should require climbing onto the Torso")
    assertTrue(not titan.titanRuneDestroyed, "Blocked rune melee should not destroy the rune")

    local climbLegs = titanResolver:resolve({
        actor = attacker,
        target = titan,
        card = { name = "Seven of Pentacles", value = 7, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.DASH,
        climbSporehulk = true,
        destinationSection = "legs",
    })
    assertTrue(climbLegs.success, "Dash should climb onto the Sporehulk Legs")
    assertEqual(attacker.sporehulkClimbSection, "legs", "first Sporehulk climb should reach Legs")

    local climbTorso = titanResolver:resolve({
        actor = attacker,
        target = titan,
        card = { name = "Seven of Pentacles", value = 7, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.DASH,
        climbSporehulk = true,
        destinationSection = "torso",
    })
    assertTrue(climbTorso.success, "Dash should climb one section from Legs to Torso")
    assertEqual(attacker.sporehulkClimbSection, "torso", "second Sporehulk climb should reach Torso")

    local runeHit = titanResolver:resolve({
        actor = attacker,
        target = titan,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetRune = true,
        targetInitiative = 8,
    })
    assertTrue(runeHit.success, "Torso climber should be able to hit the Sporehulk rune")
    assertTrue(titan.titanRuneDestroyed, "Successful rune hit should end Sporehulk rune protection")
    assertTrue(hasValue(runeHit.effects, "titan_rune_destroyed") and
        hasValue(runeHit.effects, "titan_rune_protection_ended"),
        "Successful rune hit should report rune destruction")
    assertEqual(titan.titanSections.torso.defense, 9,
        "Successful rune hit should deal one Wound to the Torso section")

    local tieTorso = titanResolver:resolve({
        actor = attacker,
        target = titan,
        card = { name = "Three of Swords", value = 3, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetSection = "torso",
        targetInitiative = 10,
    })
    assertTrue(not tieTorso.success, "Sporehulk Torso Tough should make equal-Initiative attacks fail")
    assertTrue(hasValue(tieTorso.effects, "titan_torso_tough_requires_exceed"),
        "Sporehulk Torso Tough should report the exceed-Initiative requirement")

    local rampage = titanResolver:resolve({
        actor = attacker,
        target = titan,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetSection = "legs",
        targetGreaterDoom = titan.greaterDooms[1],
        targetInitiativeCard = { name = "Greater Doom XIX", value = 19, is_major = true },
    })
    assertTrue(not rampage.success, "Sporehulk Rampage should let a greater doom stand as Initiative")
    assertEqual(rampage.difficulty, 19, "Sporehulk Rampage should set Initiative from the greater doom")
    assertTrue(hasValue(rampage.effects, "titan_sporehulk_rampage"),
        "Sporehulk Rampage should report greater-doom Initiative")

    local sectionDamage = titanResolver:applyDamage(titan, 4, {}, nil, nil, nil, {
        action = {
            actor = attacker,
            target = titan,
            targetSection = "legs",
        },
    })
    assertEqual(sectionDamage.titanSection, "legs", "post-rune section damage should target named sections")
    assertTrue(titan.titanSections.legs.defeated and titan.titanLegsDefeated,
        "Defeating Sporehulk Legs should mark the Legs section defeated")
    assertTrue(titan.conditions.crumpled and titan.cannotDash,
        "Defeating Sporehulk Legs should crumple it and block Dash")

    local actionTitan = entity_factory.createEntity("titan_sporehulk")
    actionTitan.id = "npc_titan_actions_runtime"
    actionTitan.zone = "legs"
    actionTitan.titanRuneDestroyed = true
    actionTitan.titan.runeOfProtection.destroyed = true

    local kickPrimary = base_entity.createEntity({
        id = "pc_titan_kick_primary",
        name = "Titan Kick Primary",
        isPC = true,
    })
    kickPrimary.zone = "legs"
    kickPrimary.inventory = inventory.createInventory()
    local kickSecondary = base_entity.createEntity({
        id = "pc_titan_kick_secondary",
        name = "Titan Kick Secondary",
        isPC = true,
    })
    kickSecondary.zone = "legs"
    kickSecondary.inventory = inventory.createInventory()
    local kickFar = base_entity.createEntity({
        id = "pc_titan_kick_far",
        name = "Titan Kick Far",
        isPC = true,
    })
    kickFar.zone = "torso"

    local kick = titanResolver:resolve({
        actor = actionTitan,
        target = kickPrimary,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        lesserDoom = actionTitan.lesserDooms[1],
        targetInitiative = 8,
        targetInitiatives = {
            pc_titan_kick_secondary = 8,
        },
        allEntities = { actionTitan, kickPrimary, kickSecondary, kickFar },
    })
    assertTrue(kick.success, "Sporehulk Kick primary Attack should resolve normally")
    assertTrue(hasValue(kick.effects, "titan_sporehulk_kick"),
        "Sporehulk Kick should report its zone Attack rider")
    assertEqual(#(kick.zoneAttackResults or {}), 1,
        "Sporehulk Kick should only follow up against same-zone adventurers")
    assertTrue(kickPrimary.conditions.staggered and kickSecondary.conditions.staggered,
        "Sporehulk Kick should wound same-zone adventurers")
    assertTrue(not kickFar.conditions.staggered,
        "Sporehulk Kick should skip climbers in other sections")

    actionTitan.zone = "field_a"
    local grabTarget = base_entity.createEntity({
        id = "pc_titan_grabbed",
        name = "Titan Grabbed Adventurer",
        isPC = true,
    })
    grabTarget.zone = "field_a"
    grabTarget.inventory = inventory.createInventory()
    local grab = titanResolver:resolve({
        actor = actionTitan,
        target = grabTarget,
        card = { name = "Ten of Pentacles", value = 10, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        lesserDoom = actionTitan.lesserDooms[2],
        roughhouseEffect = "grab",
        armSection = "left_arm",
        targetInitiative = 8,
        allEntities = { actionTitan, grabTarget },
    })
    assertTrue(grab.success and hasValue(grab.effects, "titan_sporehulk_grab"),
        "Sporehulk Grab should Root and hold a target with an arm")
    assertTrue(grabTarget.conditions.rooted and grabTarget.titanGrabbedBy == actionTitan,
        "Sporehulk Grab should track the grabbed target")

    local titanMove = titanResolver:resolve({
        actor = actionTitan,
        card = { name = "Five of Pentacles", value = 5, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.MOVE,
        destinationZone = "field_b",
        allEntities = { actionTitan, grabTarget },
    })
    assertTrue(titanMove.success and hasValue(titanMove.effects, "titan_grab_victims_moved"),
        "grabbed adventurers should move with the Sporehulk")
    assertEqual(grabTarget.zone, "field_b", "Sporehulk Grab movement should update grabbed targets")

    local missedTitanAttack = titanResolver:resolve({
        actor = attacker,
        target = actionTitan,
        card = { name = "Two of Swords", value = 2, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetSection = "legs",
        targetInitiative = 20,
        allEntities = { actionTitan, grabTarget, attacker },
    })
    assertTrue(not missedTitanAttack.success and
        hasValue(missedTitanAttack.effects, "miss_redirected_to_grabbed_foe"),
        "missed Attacks against the Sporehulk should hit a grabbed adventurer")
    assertTrue(grabTarget.conditions.staggered,
        "Sporehulk missed-attack redirection should Wound the grabbed adventurer")

    local smashTarget = base_entity.createEntity({
        id = "pc_titan_smash_target",
        name = "Titan Smash Target",
        isPC = true,
    })
    local smash = titanResolver:resolve({
        actor = actionTitan,
        target = smashTarget,
        card = { name = "Greater Doom XVIII", value = 18, is_major = true },
        type = action_resolver.ACTION_TYPES.MELEE,
        greaterDoom = actionTitan.greaterDooms[2],
        armSection = "left_arm",
        targetInitiative = 12,
    })
    assertTrue(smash.success and hasValue(smash.effects, "titan_sporehulk_smash"),
        "Sporehulk Smash should allow a greater doom card as an Attack action")

    local squeeze = titanResolver:resolve({
        actor = actionTitan,
        type = action_resolver.ACTION_TYPES.TITAN_SQUEEZE,
        greaterDoom = actionTitan.greaterDooms[3],
        armSection = "left_arm",
        allEntities = { actionTitan, grabTarget },
    })
    assertTrue(squeeze.success and squeeze.cardless and squeeze.countsTowardTurnCard == false,
        "Sporehulk Squeeze should be a cardless greater-doom action")
    assertTrue(hasValue(squeeze.effects, "titan_sporehulk_squeeze") and grabTarget.conditions.injured,
        "Sporehulk Squeeze should Wound grabbed adventurers")

    local throwTarget = base_entity.createEntity({
        id = "pc_titan_throw_target",
        name = "Titan Throw Target",
        isPC = true,
    })
    local throwStones = titanResolver:resolve({
        actor = actionTitan,
        target = throwTarget,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        lesserDoom = actionTitan.lesserDooms[3],
        armSection = "left_arm",
        thrownHeldTarget = grabTarget,
        targetInitiative = 8,
        allEntities = { actionTitan, grabTarget, throwTarget },
    })
    assertTrue(throwStones.success and hasValue(throwStones.effects, "titan_sporehulk_throw_stones"),
        "Sporehulk Throw Stones should resolve from its lesser doom")
    assertTrue(grabTarget.titanGrabbedBy == nil and grabTarget.conditions.deaths_door,
        "throwing a grabbed adventurer should release and automatically Wound them")

    titanResolver:getTitanSectionState(actionTitan, "left_arm").defeated = true
    local blockedSqueeze = titanResolver:resolve({
        actor = actionTitan,
        type = action_resolver.ACTION_TYPES.TITAN_SQUEEZE,
        greaterDoom = actionTitan.greaterDooms[3],
        armSection = "left_arm",
    })
    assertTrue(not blockedSqueeze.success and hasValue(blockedSqueeze.effects, "titan_section_doom_blocked"),
        "defeated Sporehulk sections should block their associated dooms")

    local climberA = base_entity.createEntity({
        id = "pc_titan_shake_a",
        name = "Titan Shake A",
        isPC = true,
    })
    climberA.inventory = inventory.createInventory()
    climberA.climbingSporehulk = titan
    climberA.climbingSporehulkId = titan.id
    climberA.sporehulkClimbSection = "torso"
    local climberB = base_entity.createEntity({
        id = "pc_titan_shake_b",
        name = "Titan Shake B",
        isPC = true,
    })
    climberB.inventory = inventory.createInventory()
    climberB.climbingSporehulk = titan
    climberB.climbingSporehulkId = titan.id
    climberB.sporehulkClimbSection = "left_arm"

    local shake = titanResolver:resolve({
        actor = titan,
        card = { name = "Eight of Pentacles", value = 8, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        lesserDoom = titan.lesserDooms[4],
        roughhouseEffect = "shake",
        targetInitiatives = {
            pc_titan_shake_a = 8,
            pc_titan_shake_b = 8,
        },
        allEntities = { titan, climberA, climberB },
    })
    assertTrue(shake.success, "Sporehulk Shake should resolve against climbers")
    assertEqual(#(shake.shakeResults or {}), 2, "Sporehulk Shake should test all climbers")
    assertTrue(climberA.conditions.prone and climberB.conditions.prone,
        "Sporehulk Shake should Trip climbers it beats")
    assertTrue(climberA.conditions.staggered and climberB.conditions.staggered,
        "Sporehulk Shake should deal Piercing falling damage")
    assertTrue(climberA.sporehulkClimbSection == nil and climberB.sporehulkClimbSection == nil,
        "Sporehulk Shake should drop climbers to the ground")
    assertTrue(hasValue(shake.effects, "titan_sporehulk_shake"),
        "Sporehulk Shake should report its roughhouse-all-climbers rider")
end

function checkFungoidRuntime()
    local fungoidResolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local attacker = base_entity.createEntity({
        id = "pc_fungoid_attacker",
        name = "Fungoid Attacker",
        isPC = true,
        swords = 0,
    })
    attacker.loreBids = 2
    local fungoid = entity_factory.createEntity("fungoid")
    local brainSpores = fungoidResolver:resolve({
        actor = attacker,
        target = fungoid,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        weapon = { name = "Sword", weaponType = "sword" },
        targetInitiative = 5,
    })
    assertTrue(brainSpores.success, "Fungoid Brain Spores should trigger from a successful melee Attack")
    assertEqual(attacker.loreBids, 1, "Fungoid Brain Spores should cost the attacker 1 lore bid")
    assertTrue(hasValue(brainSpores.effects, "fungoid_brain_spores") and
        hasValue(brainSpores.effects, "lore_bid_lost"),
        "Fungoid Brain Spores should report the lore bid loss")

    attacker.inventory = inventory.createInventory()
    local poisonNeedle = inventory.createItem({
        name = "Poison Needle",
        properties = {
            consumable = true,
            useEffect = {
                type = "apply_conditions",
                target = "target",
                conditions = {
                    poisoned = true,
                    poison = true,
                },
            },
        },
    })
    attacker.inventory:addItem(poisonNeedle, inventory.LOCATIONS.HANDS)
    local blockedPoison = fungoidResolver:resolve({
        actor = attacker,
        target = fungoid,
        card = { name = "Seven of Cups", value = 7, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = poisonNeedle.id,
        contestedUseItem = false,
    })
    assertTrue(blockedPoison.success, "Fungoid Poison Immunity should let the item use resolve")
    assertTrue(hasValue(blockedPoison.effects, "poison_blocked") and
        hasValue(blockedPoison.effects, "poison_immunity"),
        "Fungoid Poison Immunity should report blocked poison")
    assertTrue(not fungoid.conditions.poisoned and not fungoid.conditions.poison,
        "Fungoid Poison Immunity should prevent poison conditions")

    local sporeFungoid = entity_factory.createEntity("fungoid")
    sporeFungoid.id = "npc_fungoid_choking_spores"
    sporeFungoid.zone = "mushroom_ring"
    local sameZonePC = base_entity.createEntity({
        id = "pc_fungoid_spores_same",
        name = "Same Zone Fungoid Spores",
        isPC = true,
    })
    sameZonePC.zone = "mushroom_ring"
    local sameZoneMonster = entity_factory.createEntity("zombie")
    sameZoneMonster.id = "npc_fungoid_spores_same"
    sameZoneMonster.zone = "mushroom_ring"
    local farPC = base_entity.createEntity({
        id = "pc_fungoid_spores_far",
        name = "Far Fungoid Spores",
        isPC = true,
    })
    farPC.zone = "hall"
    local spores = fungoidResolver:resolve({
        actor = sporeFungoid,
        type = action_resolver.ACTION_TYPES.FUNGOID_CHOKING_SPORES,
        lesserDoom = sporeFungoid.lesserDooms[1],
        lesserDoomCard = { name = "Six of Wands", value = 6, suit = constants.SUITS.WANDS },
        allEntities = { sporeFungoid, sameZonePC, sameZoneMonster, farPC },
    })
    assertTrue(spores.success, "Fungoid Choking Spores should resolve from a lesser doom")
    assertTrue(sporeFungoid.conditions.silenced and sameZonePC.conditions.silenced and
        sameZoneMonster.conditions.silenced,
        "Fungoid Choking Spores should Silence all same-zone creatures")
    assertTrue(not farPC.conditions.silenced, "Fungoid Choking Spores should not Silence other zones")

    local recoverSilence = fungoidResolver:resolve({
        actor = sameZonePC,
        type = action_resolver.ACTION_TYPES.RECOVER,
        card = { name = "Seven of Pentacles", value = 7, suit = constants.SUITS.PENTACLES },
        recoverEffect = "silence",
    })
    assertTrue(recoverSilence.success, "Recover should clear Fungoid Choking Spores Silence")
    assertTrue(not sameZonePC.conditions.silenced, "Recover should remove the Silenced condition")

    local illusion = fungoidResolver:resolve({
        actor = sporeFungoid,
        type = action_resolver.ACTION_TYPES.FUNGOID_MINOR_ILLUSION,
        lesserDoom = sporeFungoid.lesserDooms[2],
        lesserDoomCard = { name = "Three of Cups", value = 3, suit = constants.SUITS.CUPS },
        illusionKind = "object",
        image = "silver key",
    })
    assertTrue(illusion.success, "Fungoid Minor Illusion should create non-living object images")
    assertTrue(illusion.illusion and illusion.illusion.imageOnly and illusion.illusion.noSubstance,
        "Fungoid Minor Illusion should be image-only and insubstantial")

    local blockedIllusion = fungoidResolver:resolve({
        actor = sporeFungoid,
        type = action_resolver.ACTION_TYPES.FUNGOID_MINOR_ILLUSION,
        lesserDoom = sporeFungoid.lesserDooms[2],
        lesserDoomCard = { name = "Three of Cups", value = 3, suit = constants.SUITS.CUPS },
        illusionKind = "creature",
        image = "adventurer",
    })
    assertTrue(not blockedIllusion.success, "Fungoid Minor Illusion should reject living creature images")
    assertTrue(hasValue(blockedIllusion.effects, "fungoid_minor_illusion_living_target_blocked"),
        "blocked Fungoid Minor Illusion should report the living-image restriction")

    sporeFungoid.npcHealth = sporeFungoid.npcMaxHealth - 2
    local regen = fungoidResolver:resolve({
        actor = sporeFungoid,
        type = action_resolver.ACTION_TYPES.FUNGOID_FUNGAL_REGENERATION,
        greaterDoom = sporeFungoid.greaterDooms[1],
    })
    assertTrue(regen.success and regen.cardless and regen.countsTowardTurnCard == false,
        "Fungoid Fungal Regeneration should be a cardless greater-doom action")
    assertEqual(sporeFungoid.npcHealth, sporeFungoid.npcMaxHealth - 1,
        "Fungoid Fungal Regeneration should Heal 1 Wound")

    local imitator = entity_factory.createEntity("fungoid")
    imitator.id = "npc_fungoid_imitator"
    imitator.zone = "mirror_room"
    local original = base_entity.createEntity({
        id = "pc_fungoid_original",
        name = "Fungoid Original",
        isPC = true,
    })
    original.zone = "mirror_room"
    local imitation = fungoidResolver:resolve({
        actor = imitator,
        type = action_resolver.ACTION_TYPES.FUNGOID_PERFECT_IMITATION,
        greaterDoom = imitator.greaterDooms[2],
        original = original,
    })
    assertTrue(imitation.success, "Fungoid Perfect Imitation should resolve from a greater doom")
    assertTrue(imitator.fungoidPerfectImitation and imitator.fungoidPerfectImitation.active,
        "Fungoid Perfect Imitation should store active imitation state")

    local redirected = fungoidResolver:resolve({
        actor = attacker,
        target = imitator,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        weapon = { name = "Sword", weaponType = "sword" },
        targetInitiative = 5,
        perfectImitationRedirectRoll = 0.25,
    })
    assertTrue(redirected.success, "Fungoid Perfect Imitation redirected target should still resolve")
    assertTrue(hasValue(redirected.effects, "fungoid_perfect_imitation_redirected"),
        "Fungoid Perfect Imitation should report redirected targeting")
    assertTrue(original.conditions.staggered and imitator.npcDefense == imitator.npcMaxDefense,
        "Fungoid Perfect Imitation should redirect the Wound to the original")

    local imitationEndEffects = {}
    fungoidResolver:applyDamage(imitator, 1, imitationEndEffects,
        { name = "Sword", weaponType = "sword" }, nil, nil, { source = "attack" })
    assertTrue(not imitator.fungoidPerfectImitation.active,
        "Fungoid Perfect Imitation should end when the fungoid takes a Wound")
    assertTrue(hasValue(imitationEndEffects, "fungoid_perfect_imitation_ended"),
        "Fungoid Perfect Imitation should report ending on Wound")
end

function checkNymphRuntime()
    local nymphBus = events.createEventBus()
    local nymphWantEvent = nil
    nymphBus:on("nymph_want_revealed", function(data)
        nymphWantEvent = data
    end)
    local zones = zone_system.createZoneRegistry({ eventBus = nymphBus })
    zones:setRoomZones({
        zone_system.createZone({ id = "shore", name = "Shore" }),
        zone_system.createZone({ id = "pool", name = "Moonlit Pool" }),
    })
    local nymphResolver = action_resolver.createActionResolver({
        eventBus = nymphBus,
        zoneSystem = zones,
    })

    local nymph = entity_factory.createEntity("nymph")
    nymph.id = "npc_nymph_runtime"
    nymph.zone = "pool"
    zones:placeEntity(nymph.id, nymph.zone)

    local minorDiscard = deck.createDeck({})
    minorDiscard:discard({ name = "Seven of Cups", value = 7, suit = constants.SUITS.CUPS })
    local want = nymphResolver:resolve({
        actor = nymph,
        type = action_resolver.ACTION_TYPES.NYMPH_WANT,
        minorDeck = minorDiscard,
    })
    assertTrue(want.success, "Nymph wants should resolve from the top minor discard card")
    assertEqual(want.nymphWant.suit, "cups",
        "Nymph wants should read the top discard card's suit")
    assertEqual(want.nymphWant.request, "Bring sweet wine to drink.",
        "Cups-discard nymph wants should ask for sweet wine")
    assertTrue(hasValue(want.effects, "nymph_want_cups"),
        "Nymph wants should report the resolved suit")
    assertTrue(nymph.currentWant == want.nymphWant and nymphWantEvent and nymphWantEvent.request == want.nymphWant.request,
        "Nymph wants should store and emit the current request")

    local lured = base_entity.createEntity({
        id = "pc_nymph_lured",
        name = "Nymph Lured",
        isPC = true,
    })
    lured.zone = "shore"
    zones:placeEntity(lured.id, lured.zone)

    local resister = base_entity.createEntity({
        id = "pc_nymph_resister",
        name = "Nymph Resister",
        isPC = true,
    })
    resister.resolve = { current = 1, max = 4 }
    resister.zone = "shore"
    zones:placeEntity(resister.id, resister.zone)

    local blind = base_entity.createEntity({
        id = "pc_nymph_blind",
        name = "Nymph Blind",
        isPC = true,
    })
    blind.conditions.blind = true
    blind.zone = "shore"
    zones:placeEntity(blind.id, blind.zone)

    local partingGuard = base_entity.createEntity({
        id = "npc_nymph_parting_guard",
        name = "Parting Guard",
        isPC = false,
    })
    partingGuard.zone = "shore"
    zones:placeEntity(partingGuard.id, partingGuard.zone)

    local allEntities = { nymph, lured, resister, blind, partingGuard }
    nymphResolver:formEngagement(lured, partingGuard)

    local beauty = nymphResolver:resolve({
        actor = nymph,
        type = action_resolver.ACTION_TYPES.NYMPH_BEWITCHING_BEAUTY,
        card = { name = "Three of Cups", value = 3, suit = constants.SUITS.CUPS },
        allEntities = allEntities,
        destinationZones = {
            pc_nymph_lured = "pool",
            pc_nymph_resister = "pool",
            pc_nymph_blind = "pool",
        },
        resistResolveById = {
            pc_nymph_resister = true,
        },
    })
    assertTrue(beauty.success, "Nymph Bewitching Beauty should resolve from any discarded card")
    assertEqual(lured.zone, "pool", "Nymph Bewitching Beauty should displace visible adventurers toward the nymph")
    assertTrue(lured.conditions.staggered,
        "Nymph Bewitching Beauty movement should trigger normal parting blow damage")
    assertTrue(not nymphResolver:areEngaged(lured, partingGuard),
        "Nymph Bewitching Beauty should clear old engagements after forced movement")
    assertEqual(resister.zone, "shore", "Resolve resistance should prevent Nymph Bewitching Beauty movement")
    assertEqual(resister.resolve.current, 0, "Nymph Bewitching Beauty resistance should spend 1 Resolve")
    assertEqual(blind.zone, "shore", "Blind adventurers should not be affected by visible Nymph Beauty")
    assertTrue(hasValue(beauty.effects, "nymph_bewitching_beauty") and
        hasValue(beauty.effects, "nymph_bewitching_beauty_resisted"),
        "Nymph Bewitching Beauty should report its effect and resistance")

    nymphResolver:formEngagement(nymph, lured)
    nymphResolver:formEngagement(nymph, resister)
    local blockedRetreat = nymphResolver:resolve({
        actor = nymph,
        type = action_resolver.ACTION_TYPES.NYMPH_EXPEDITIOUS_RETREAT,
        allEntities = allEntities,
    })
    assertTrue(not blockedRetreat.success, "Nymph Expeditious Retreat should require a greater doom")
    assertTrue(hasValue(blockedRetreat.effects, "nymph_expeditious_retreat_requires_greater_doom"),
        "blocked Nymph Expeditious Retreat should report missing greater doom")

    local retreat = nymphResolver:resolve({
        actor = nymph,
        type = action_resolver.ACTION_TYPES.NYMPH_EXPEDITIOUS_RETREAT,
        greaterDoom = nymph.greaterDooms[1],
        allEntities = allEntities,
    })
    assertTrue(retreat.success, "Nymph Expeditious Retreat should resolve as a cardless greater-doom action")
    assertTrue(retreat.countsTowardTurnCard == false and retreat.cardless,
        "Nymph Expeditious Retreat should not spend the nymph's turn card")
    assertTrue(not zones:isEngaged(nymph.id),
        "Nymph Expeditious Retreat should disengage from all adventurers")
    assertTrue(not lured.is_engaged and not resister.is_engaged,
        "Nymph Expeditious Retreat should update former targets' engagement flags")

    local sleepTarget = base_entity.createEntity({
        id = "pc_nymph_sleep_target",
        name = "Nymph Sleep Target",
        isPC = true,
    })
    local blockedSleep = nymphResolver:resolve({
        actor = nymph,
        target = sleepTarget,
        type = action_resolver.ACTION_TYPES.NYMPH_SLEEP_SONG,
        card = { name = "Seven of Wands", value = 7, suit = constants.SUITS.WANDS },
        targetInitiative = 9,
    })
    assertTrue(not blockedSleep.success, "Nymph Sleep Song should require a greater doom")
    assertTrue(hasValue(blockedSleep.effects, "nymph_sleep_song_requires_greater_doom"),
        "blocked Nymph Sleep Song should report missing greater doom")

    local sleep = nymphResolver:resolve({
        actor = nymph,
        target = sleepTarget,
        type = action_resolver.ACTION_TYPES.NYMPH_SLEEP_SONG,
        card = { name = "Seven of Wands", value = 7, suit = constants.SUITS.WANDS },
        greaterDoom = nymph.greaterDooms[2],
        targetInitiative = 9,
    })
    assertTrue(sleep.success, "Nymph Sleep Song should use Speak Incantations against target Initiative")
    assertTrue(sleepTarget.conditions.knocked_out and sleepTarget.conditions.sleeping,
        "Nymph Sleep Song should apply Knockout sleep on success")
    assertEqual(sleepTarget.sleep.wake, "sharp_slap",
        "Nymph Sleep Song should record the sharp-slap wake condition")

    local wakefulTarget = base_entity.createEntity({
        id = "pc_nymph_wakeful_target",
        name = "Nymph Wakeful Target",
        isPC = true,
    })
    local failedSong = nymphResolver:resolve({
        actor = nymph,
        target = wakefulTarget,
        type = action_resolver.ACTION_TYPES.NYMPH_SLEEP_SONG,
        card = { name = "Two of Wands", value = 2, suit = constants.SUITS.WANDS },
        greaterDoom = nymph.greaterDooms[2],
        targetInitiative = 20,
    })
    assertTrue(not failedSong.success, "failed Nymph Sleep Song should not apply Knockout")
    assertTrue(not wakefulTarget.conditions.knocked_out and hasValue(failedSong.effects, "nymph_sleep_song_failed"),
        "failed Nymph Sleep Song should report failure without mutating the target")

    nymph.nymph.chosenElement = "water"
    nymph.nymph.elementalHome = "pool"
    local waterEffects = { "water" }
    local waterBlocked = nymphResolver:applyDamage(nymph, 1, waterEffects, nil, nil, nil, {
        source = "hazard",
        damageElement = "water",
    })
    assertTrue(waterBlocked and waterBlocked.immune and waterBlocked.reason == "elemental_immunity",
        "Nymph elemental immunity should ignore damage from her chosen element")
    assertEqual(nymph.npcHealth, nymph.npcMaxHealth,
        "chosen-element immunity should prevent nymph Wounds")
    assertTrue(hasValue(waterEffects, "elemental_immunity_water"),
        "elemental immunity should report the blocked element")

    nymphResolver:formEngagement(nymph, lured)
    local blockedMeld = nymphResolver:resolve({
        actor = nymph,
        type = action_resolver.ACTION_TYPES.ELEMENTAL_MELD,
        elementalHome = "pool",
        elementalHomePresent = true,
    })
    assertTrue(not blockedMeld.success, "Elemental Meld should require a miscellaneous-action card in Challenges")
    assertTrue(hasValue(blockedMeld.effects, "elemental_meld_requires_card"),
        "blocked Elemental Meld should report the missing card")

    local meld = nymphResolver:resolve({
        actor = nymph,
        type = action_resolver.ACTION_TYPES.ELEMENTAL_MELD,
        card = { name = "Three of Pentacles", value = 3, suit = constants.SUITS.PENTACLES },
        elementalHome = "pool",
        elementalHomePresent = true,
        allEntities = allEntities,
    })
    assertTrue(meld.success and nymph.elementalMelded and nymph.intangible and nymph.inElementalHome,
        "Nymph Elemental Meld should make her immaterial inside her elemental home")
    assertTrue(not zones:isEngaged(nymph.id) and not lured.is_engaged,
        "Elemental Meld should clear engagements as the nymph steps into her home")
    assertTrue(hasValue(meld.effects, "elemental_home_entered"),
        "Elemental Meld should report the home-entry state")

    local emerge = nymphResolver:resolve({
        actor = nymph,
        type = action_resolver.ACTION_TYPES.ELEMENTAL_MELD,
        returnFromMeld = true,
        destinationZone = "pool",
    })
    assertTrue(emerge.success and not nymph.elementalMelded and not nymph.intangible,
        "Nymph Elemental Meld should support emerging from the elemental home")
    assertEqual(nymph.zone, "pool", "emerging should place the nymph back in the chosen zone")
end

function checkWinterWolfRuntime()
    local wolfBus = events.createEventBus()
    local zones = zone_system.createZoneRegistry({ eventBus = wolfBus })
    zones:setRoomZones({
        zone_system.createZone({ id = "snowfield", name = "Snowfield" }),
        zone_system.createZone({ id = "ridge", name = "Ridge" }),
    })
    local wolfResolver = action_resolver.createActionResolver({
        eventBus = wolfBus,
        zoneSystem = zones,
    })

    local wolf = entity_factory.createEntity("winter_wolf")
    wolf.id = "npc_winter_wolf_runtime"
    wolf.zone = "snowfield"
    zones:placeEntity(wolf.id, wolf.zone)

    local rootedPC = base_entity.createEntity({
        id = "pc_winter_wolf_rooted",
        name = "Winter Wolf Rooted",
        isPC = true,
    })
    rootedPC.zone = "snowfield"
    zones:placeEntity(rootedPC.id, rootedPC.zone)

    local bystander = base_entity.createEntity({
        id = "pc_winter_wolf_bystander",
        name = "Winter Wolf Bystander",
        isPC = true,
    })
    bystander.zone = "snowfield"
    zones:placeEntity(bystander.id, bystander.zone)

    local auraEntities = { wolf, rootedPC, bystander }
    wolfResolver:formEngagement(wolf, rootedPC)
    local aura = wolfResolver:resolve({
        actor = wolf,
        type = action_resolver.ACTION_TYPES.WINTER_WOLF_AURA_OF_ICE,
        allEntities = auraEntities,
    })
    assertTrue(aura.success and aura.cardless and aura.countsTowardTurnCard == false,
        "Winter Wolf Aura of Ice should be automatic and cardless")
    assertTrue(rootedPC.conditions.rooted and rootedPC.conditions.winter_wolf_ice_root,
        "Winter Wolf Aura of Ice should Root adventurers who begin engaged")
    assertTrue(not bystander.conditions.rooted,
        "Winter Wolf Aura of Ice should not Root unengaged same-zone adventurers")
    assertTrue(not zones:areEngaged(wolf.id, rootedPC.id),
        "Rooted adventurers should leave the engagement through the normal Rooted path")

    local fireWolf = entity_factory.createEntity("winter_wolf")
    fireWolf.id = "npc_winter_wolf_fire"
    local fireUser = base_entity.createEntity({
        id = "pc_winter_wolf_fire_user",
        name = "Winter Wolf Fire User",
        isPC = true,
    })
    local torch = inventory.createItemFromTemplate("torch")
    local fireEffects = { "fire" }
    wolfResolver:applyDamage(fireWolf, 1, fireEffects, torch, nil, nil, {
        source = "attack",
        action = { actor = fireUser },
    })
    assertEqual(fireWolf.npcHealth, 2,
        "Winter Wolf fire vulnerability should turn fire damage into 2 Wounds")
    assertTrue(torch.destroyed and hasValue(fireEffects, "torch_or_lantern_destroyed"),
        "Torch or lantern fire attacks against winter wolves should Destroy that light source")

    local coldWolf = entity_factory.createEntity("winter_wolf")
    local coldEffects = { "cold" }
    local coldBlocked = wolfResolver:applyDamage(coldWolf, 1, coldEffects, nil, nil, nil, {
        source = "hazard",
        damageElement = "cold",
    })
    assertTrue(coldBlocked and coldBlocked.immune,
        "Winter Wolf elemental nature should ignore cold damage")
    assertEqual(coldWolf.npcHealth, coldWolf.npcMaxHealth,
        "cold elemental immunity should prevent winter wolf Wounds")
    assertTrue(hasValue(coldEffects, "elemental_immunity_cold"),
        "Winter Wolf cold immunity should report its element")

    local blockedMistTravel = wolfResolver:resolve({
        actor = bystander,
        type = action_resolver.ACTION_TYPES.MOVE,
        card = { name = "Five of Pentacles", value = 5, suit = constants.SUITS.PENTACLES },
        destinationZone = "ridge",
        traversalMode = "mist",
        requiresElementalTravel = true,
    })
    assertTrue(not blockedMistTravel.success and blockedMistTravel.traversalRequiresTest,
        "non-winter-wolf mist traversal should require a Test of Fate")
    assertTrue(hasValue(blockedMistTravel.effects, "winter_wolf_elemental_travel_required"),
        "blocked mist traversal should report the missing elemental travel")

    local waterTravel = wolfResolver:resolve({
        actor = wolf,
        type = action_resolver.ACTION_TYPES.MOVE,
        card = { name = "Six of Pentacles", value = 6, suit = constants.SUITS.PENTACLES },
        destinationZone = "ridge",
        traversalMode = "water_surface",
        requiresElementalTravel = true,
    })
    assertTrue(waterTravel.success and hasValue(waterTravel.effects, "winter_wolf_elemental_travel"),
        "Winter Wolf Elemental Travel should cross water without a Test of Fate")
    assertTrue(hasValue(waterTravel.effects, "water_frozen_under_paws") and
        hasValue(waterTravel.effects, "traversal_no_test"),
        "Winter Wolf water traversal should freeze water under its paws")

    local mistTravel = wolfResolver:resolve({
        actor = wolf,
        type = action_resolver.ACTION_TYPES.MOVE,
        card = { name = "Seven of Pentacles", value = 7, suit = constants.SUITS.PENTACLES },
        destinationZone = "snowfield",
        traversalMode = "mist",
        requiresElementalTravel = true,
    })
    assertTrue(mistTravel.success and hasValue(mistTravel.effects, "mists_treated_as_solid"),
        "Winter Wolf Elemental Travel should treat mists as solid footing")

    local breathWolf = entity_factory.createEntity("winter_wolf")
    breathWolf.id = "npc_winter_wolf_breath"
    breathWolf.zone = "snowfield"

    local hitPC = base_entity.createEntity({
        id = "pc_winter_wolf_hit",
        name = "Winter Wolf Hit",
        isPC = true,
    })
    hitPC.zone = "snowfield"
    hitPC.inventory = inventory.createInventory()
    local potion = inventory.createItemFromTemplate("healing_potion")
    local oil = inventory.createItemFromTemplate("oil")
    local packedWater = inventory.createItemFromTemplate("waterskin")
    hitPC.inventory:addItem(potion, inventory.LOCATIONS.BELT)
    hitPC.inventory:addItem(oil, inventory.LOCATIONS.BELT)
    hitPC.inventory:addItem(packedWater, inventory.LOCATIONS.PACK)

    local missedPC = base_entity.createEntity({
        id = "pc_winter_wolf_missed",
        name = "Winter Wolf Missed",
        isPC = true,
    })
    missedPC.zone = "snowfield"
    missedPC.inventory = inventory.createInventory()
    local missedPotion = inventory.createItemFromTemplate("healing_potion")
    missedPC.inventory:addItem(missedPotion, inventory.LOCATIONS.BELT)

    local protectedPC = base_entity.createEntity({
        id = "pc_winter_wolf_protected",
        name = "Winter Wolf Protected",
        isPC = true,
    })
    protectedPC.zone = "snowfield"
    protectedPC.inventory = inventory.createInventory()
    protectedPC.elementProtections = {
        water_ward = {
            active = true,
            elementSet = { water = true },
        },
    }
    protectedPC.protectedElements = { water = true }
    local protectedPotion = inventory.createItemFromTemplate("healing_potion")
    protectedPC.inventory:addItem(protectedPotion, inventory.LOCATIONS.BELT)

    local farPC = base_entity.createEntity({
        id = "pc_winter_wolf_far",
        name = "Winter Wolf Far",
        isPC = true,
    })
    farPC.zone = "ridge"

    local blockedBreath = wolfResolver:resolve({
        actor = breathWolf,
        type = action_resolver.ACTION_TYPES.WINTER_WOLF_BREATH_OF_ICE,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        allEntities = { breathWolf, hitPC },
    })
    assertTrue(not blockedBreath.success, "Winter Wolf Breath of Ice should require a greater doom")
    assertTrue(hasValue(blockedBreath.effects, "winter_wolf_breath_of_ice_requires_greater_doom"),
        "blocked Winter Wolf Breath of Ice should report missing greater doom")

    local breath = wolfResolver:resolve({
        actor = breathWolf,
        type = action_resolver.ACTION_TYPES.WINTER_WOLF_BREATH_OF_ICE,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        greaterDoom = breathWolf.greaterDooms[1],
        allEntities = { breathWolf, hitPC, missedPC, protectedPC, farPC },
        targetInitiatives = {
            pc_winter_wolf_hit = 6,
            pc_winter_wolf_missed = 20,
            pc_winter_wolf_protected = 6,
            pc_winter_wolf_far = 6,
        },
    })
    assertTrue(breath.success, "Winter Wolf Breath of Ice should hit same-zone targets below its Attack value")
    assertTrue(hitPC.conditions.staggered,
        "successful Winter Wolf Breath of Ice should deal a Wound")
    assertTrue(potion.destroyed and oil.destroyed,
        "Winter Wolf Breath of Ice should Destroy all liquid belt items on hit")
    assertTrue(not packedWater.destroyed,
        "Winter Wolf Breath of Ice should not Destroy liquid items outside the belt")
    assertTrue(not missedPC.conditions.staggered and not missedPotion.destroyed,
        "missed Winter Wolf Breath of Ice targets should not take Wounds or lose liquid belt items")
    assertTrue(not protectedPC.conditions.staggered and not protectedPotion.destroyed,
        "water-protected targets should take no ice Wounds or gear damage")
    assertTrue(hasValue(breath.effects, "protection_from_elements_water_block"),
        "Winter Wolf Breath of Ice should report elemental protection blocking cold")
    assertTrue(not farPC.conditions.staggered,
        "Winter Wolf Breath of Ice should not target adventurers outside the wolf's zone")
    assertTrue(hasValue(breath.effects, "winter_wolf_breath_hit"),
        "Winter Wolf Breath of Ice should report hit resolution")
end

function checkWraithRuntime()
    local wraithBus = events.createEventBus()
    local zones = zone_system.createZoneRegistry({ eventBus = wraithBus })
    zones:setRoomZones({
        zone_system.createZone({ id = "crypt", name = "Crypt" }),
        zone_system.createZone({ id = "stair", name = "Stair" }),
        zone_system.createZone({ id = "chapel", name = "Chapel" }),
    })
    local wraithResolver = action_resolver.createActionResolver({
        eventBus = wraithBus,
        zoneSystem = zones,
    })

    local wraith = entity_factory.createEntity("wraith")
    wraith.id = "npc_wraith_runtime"
    wraith.zone = "crypt"
    zones:placeEntity(wraith.id, wraith.zone)

    local lightBearer = base_entity.createEntity({
        id = "pc_wraith_light_bearer",
        name = "Wraith Light Bearer",
        isPC = true,
    })
    lightBearer.zone = "crypt"
    lightBearer.inventory = inventory.createInventory()
    local torch = inventory.createItemFromTemplate("torch")
    lightBearer.inventory:addItem(torch, inventory.LOCATIONS.HANDS)
    zones:placeEntity(lightBearer.id, lightBearer.zone)

    local sword = inventory.createItem({
        name = "Sword",
        weaponType = "sword",
    })
    local shadowEffects = {}
    local shadowBlocked = wraithResolver:applyDamage(wraith, 1, shadowEffects, sword, nil, nil, {
        source = "attack",
    })
    assertTrue(shadowBlocked and shadowBlocked.immune,
        "Wraith Shadow Form should ignore ordinary physical damage while intangible")
    assertEqual(wraith.npcHealth, 4,
        "Wraith Shadow Form should prevent physical Wounds before bright light")
    assertTrue(hasValue(shadowEffects, "wraith_shadow_form_immune"),
        "Wraith Shadow Form immunity should be explicit")

    local reveal = wraithResolver:resolve({
        actor = lightBearer,
        target = wraith,
        type = action_resolver.ACTION_TYPES.WRAITH_SHINE_LIGHT,
        card = { name = "Three of Cups", value = 3, suit = constants.SUITS.CUPS },
        round = 1,
    })
    assertTrue(reveal.success, "Wraith bright-light reveal should resolve with any discarded card")
    assertTrue(wraith.tangible and wraith.conditions.tangible,
        "Wraith bright-light reveal should make the wraith tangible to everyone")

    local tangibleEffects = {}
    wraithResolver:applyDamage(wraith, 1, tangibleEffects, sword, nil, nil, {
        source = "attack",
        action = { round = 1 },
    })
    assertEqual(wraith.npcHealth, 3,
        "Tangible wraiths should take ordinary physical damage")

    local expired = wraithResolver:clearExpiredWraithTangibility(1, { wraith })
    assertEqual(#expired, 1, "Wraith bright-light tangibility should expire at round end")
    assertTrue(wraith.intangible and wraith.conditions.intangible and not wraith.conditions.tangible,
        "Expired Wraith tangibility should restore Shadow Form")

    local conditionItem = inventory.createItem({
        name = "Mind Venom",
        properties = {
            useEffect = {
                type = "apply_conditions",
                target = "target",
                conditions = {
                    poisoned = true,
                    controlled = true,
                },
            },
        },
    })
    lightBearer.inventory:addItem(conditionItem, inventory.LOCATIONS.HANDS)
    local spectral = wraithResolver:resolve({
        actor = lightBearer,
        target = wraith,
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        card = { name = "Four of Cups", value = 4, suit = constants.SUITS.CUPS },
        itemId = conditionItem.id,
        contestedUseItem = false,
    })
    assertTrue(spectral.success, "Wraith Spectral immunity should let the item use resolve")
    assertTrue(not wraith.conditions.poisoned and not wraith.conditions.controlled,
        "Wraith Spectral immunity should block biology and mental-control conditions")
    assertTrue(hasValue(spectral.effects, "wraith_spectral_immunity"),
        "Wraith Spectral immunity should report blocked conditions")

    local afraid = base_entity.createEntity({
        id = "pc_wraith_afraid",
        name = "Wraith Afraid",
        isPC = true,
    })
    afraid.zone = "crypt"
    zones:placeEntity(afraid.id, afraid.zone)
    local steady = base_entity.createEntity({
        id = "pc_wraith_steady",
        name = "Wraith Steady",
        isPC = true,
    })
    steady.zone = "crypt"
    zones:placeEntity(steady.id, steady.zone)
    local far = base_entity.createEntity({
        id = "pc_wraith_far",
        name = "Wraith Far",
        isPC = true,
    })
    far.zone = "chapel"
    zones:placeEntity(far.id, far.zone)

    local blockedFear = wraithResolver:resolve({
        actor = wraith,
        type = action_resolver.ACTION_TYPES.WRAITH_FEAR,
        allEntities = { wraith, afraid },
    })
    assertTrue(not blockedFear.success, "Wraith Fear should require a lesser doom")
    assertTrue(hasValue(blockedFear.effects, "wraith_fear_requires_lesser_doom"),
        "blocked Wraith Fear should report missing lesser doom")

    local fear = wraithResolver:resolve({
        actor = wraith,
        type = action_resolver.ACTION_TYPES.WRAITH_FEAR,
        lesserDoom = wraith.lesserDooms[1],
        lesserDoomCard = { name = "Four of Wands", value = 4, suit = constants.SUITS.WANDS },
        onWraithTurn = true,
        allEntities = { wraith, afraid, steady, far },
        targetInitiatives = {
            pc_wraith_afraid = 6,
            pc_wraith_steady = 12,
            pc_wraith_far = 1,
        },
        destinationZones = {
            pc_wraith_afraid = "stair",
            pc_wraith_steady = "stair",
        },
    })
    assertTrue(fear.success and hasValue(fear.effects, "wands_added"),
        "Wraith Fear should add Wands when used on the wraith's turn")
    assertEqual(afraid.zone, "stair",
        "Wraith Fear should Displace beaten same-zone adventurers to the player's chosen adjacent zone")
    assertEqual(steady.zone, "crypt",
        "Wraith Fear should not Displace adventurers whose Initiative resists it")
    assertEqual(far.zone, "chapel",
        "Wraith Fear should not affect adventurers outside the wraith's zone")

    wraithResolver:formEngagement(wraith, steady)
    local blockedRetreat = wraithResolver:resolve({
        actor = wraith,
        type = action_resolver.ACTION_TYPES.WRAITH_RETREAT_INTO_SHADOWS,
        allEntities = { wraith, steady },
    })
    assertTrue(not blockedRetreat.success, "Wraith Retreat into the Shadows should require any discarded card")
    local retreat = wraithResolver:resolve({
        actor = wraith,
        type = action_resolver.ACTION_TYPES.WRAITH_RETREAT_INTO_SHADOWS,
        card = { name = "Five of Swords", value = 5, suit = constants.SUITS.SWORDS },
        allEntities = { wraith, steady },
    })
    assertTrue(retreat.success and retreat.countsTowardTurnCard == false,
        "Wraith Retreat into the Shadows should not count against the one-card turn limit")
    assertTrue(not zones:areEngaged(wraith.id, steady.id),
        "Wraith Retreat into the Shadows should disengage from all adventurers")

    local kissTarget = base_entity.createEntity({
        id = "pc_wraith_kiss_target",
        name = "Wraith Kiss Target",
        isPC = true,
    })
    kissTarget.xp = 3
    kissTarget.zone = "crypt"
    local kiss = wraithResolver:resolve({
        actor = wraith,
        target = kissTarget,
        type = action_resolver.ACTION_TYPES.MELEE,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        greaterDoom = wraith.greaterDooms[1],
        targetInitiative = 6,
    })
    assertTrue(kiss.success, "Wraith Dolorous Kiss should ride on a successful Attack")
    assertEqual(kissTarget.xp, 2, "Wraith Dolorous Kiss should drain 1 XP")
    assertTrue(kissTarget.conditions.staggered,
        "Wraith Dolorous Kiss should still deal the Attack Wound")
    assertTrue(hasValue(kiss.effects, "wraith_dolorous_kiss") and hasValue(kiss.effects, "xp_drained"),
        "Wraith Dolorous Kiss should report XP drain")

    local destroyEffects = { "magic" }
    wraithResolver:applyDamage(wraith, 4, destroyEffects, nil, nil, nil, {
        source = "spell",
        magic = true,
    })
    assertTrue(wraith.conditions.dead, "Destroying the Wraith should be possible with nonphysical damage")
    assertEqual(kissTarget.xp, 3,
        "Destroying the Wraith should restore XP drained by Dolorous Kiss")
    assertTrue(hasValue(destroyEffects, "wraith_drained_xp_restored"),
        "Wraith XP restoration should be explicit")
end

function checkJinnRuntime()
    local jinnResolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local jinn = entity_factory.createEntity("jinn")
    jinn.id = "npc_jinn_runtime"

    local blockedBody = jinnResolver:resolve({
        actor = jinn,
        type = action_resolver.ACTION_TYPES.JINN_BODY_OF_SMOKELESS_FIRE,
    })
    assertTrue(not blockedBody.success, "Jinn Body of Smokeless Fire should require any discarded card")
    assertTrue(hasValue(blockedBody.effects, "jinn_body_requires_card"),
        "blocked Jinn Body of Smokeless Fire should report missing card")

    local smoke = jinnResolver:resolve({
        actor = jinn,
        type = action_resolver.ACTION_TYPES.JINN_BODY_OF_SMOKELESS_FIRE,
        card = { name = "Two of Cups", value = 2, suit = constants.SUITS.CUPS },
    })
    assertTrue(smoke.success and smoke.countsTowardTurnCard == false,
        "Jinn Body of Smokeless Fire should not count against the one-card turn limit")
    assertTrue(jinn.intangible and jinn.conditions.intangible,
        "Jinn Body of Smokeless Fire should make the jinn intangible")

    local sword = inventory.createItem({
        name = "Sword",
        weaponType = "sword",
    })
    local smokeEffects = {}
    local smokeBlocked = jinnResolver:applyDamage(jinn, 1, smokeEffects, sword, nil, nil, {
        source = "attack",
    })
    assertTrue(smokeBlocked and smokeBlocked.immune,
        "Intangible jinni should ignore ordinary physical weapon damage")
    assertEqual(jinn.npcHealth, 7,
        "Body of Smokeless Fire should prevent physical Wounds")
    assertTrue(hasValue(smokeEffects, "jinn_body_of_smokeless_fire_immune"),
        "Body of Smokeless Fire immunity should be explicit")

    local fireEffects = { "fire" }
    jinnResolver:applyDamage(jinn, 1, fireEffects, nil, nil, nil, {
        source = "fire",
        fire = true,
    })
    assertEqual(jinn.npcHealth, 6,
        "Body of Smokeless Fire should only block physical objects, not non-object fire damage")

    local tangible = jinnResolver:resolve({
        actor = jinn,
        type = action_resolver.ACTION_TYPES.JINN_BODY_OF_SMOKELESS_FIRE,
        card = { name = "Three of Cups", value = 3, suit = constants.SUITS.CUPS },
        becomeTangible = true,
    })
    assertTrue(tangible.success and jinn.tangible and not jinn.conditions.intangible,
        "Jinn Body of Smokeless Fire should toggle the jinn back to tangible")

    local hiddenJinn = entity_factory.createEntity("jinn")
    hiddenJinn.id = "npc_jinn_hidden"
    local watcher = base_entity.createEntity({
        id = "pc_jinn_watcher",
        name = "Jinn Watcher",
        isPC = true,
    })
    local invisible = jinnResolver:resolve({
        actor = hiddenJinn,
        type = action_resolver.ACTION_TYPES.JINN_INVISIBLE,
        card = { name = "Four of Wands", value = 4, suit = constants.SUITS.WANDS },
    })
    assertTrue(invisible.success and hiddenJinn.conditions.shrouded and hiddenJinn.conditions.invisible,
        "Jinn Invisible should make the jinn Shrouded")
    assertTrue(not jinnResolver:canActorSeeShrouded(watcher, hiddenJinn, {}),
        "ordinary creatures should not see a still Shrouded jinn")
    assertTrue(jinnResolver:canActorSeeShrouded(jinn, hiddenJinn, {}),
        "Jinn Second Sight should see Shrouded creatures")

    hiddenJinn.magicEffects = { "curse_of_ash" }
    local secondSight = jinnResolver:getJinnSecondSightMagicalEffects(jinn, { hiddenJinn })
    assertEqual(#secondSight, 1,
        "Jinn Second Sight should identify magical effects on observed subjects")

    local unseenAttack = jinnResolver:resolve({
        actor = watcher,
        target = hiddenJinn,
        type = action_resolver.ACTION_TYPES.MELEE,
        card = { name = "Nine of Swords", value = 9, suit = constants.SUITS.SWORDS },
        targetInitiative = 1,
    })
    assertTrue(not unseenAttack.success and hasValue(unseenAttack.effects, "shrouded_target_unseen"),
        "a still Shrouded jinn should not be deliberately targetable without special senses")

    local doorTarget = base_entity.createEntity({
        id = "pc_jinn_door_target",
        name = "Door Target",
        isPC = true,
    })
    local revealAttack = jinnResolver:resolve({
        actor = hiddenJinn,
        target = doorTarget,
        type = action_resolver.ACTION_TYPES.MELEE,
        card = { name = "Nine of Swords", value = 9, suit = constants.SUITS.SWORDS },
        targetInitiative = 6,
    })
    assertTrue(revealAttack.success and hasValue(revealAttack.effects, "jinn_invisibility_ended"),
        "a jinn should lose Invisible when it interacts with the physical world")
    assertTrue(not hiddenJinn.conditions.shrouded and not hiddenJinn.conditions.invisible,
        "Jinn Invisible should clear after physical interaction")

    local naturalJinn = entity_factory.createEntity("jinn")
    naturalJinn.id = "npc_jinn_natural_sorcery"
    naturalJinn.resolve = 0
    naturalJinn.inventory = inventory.createInventory()
    local missingNaturalDoom = jinnResolver:resolve({
        actor = naturalJinn,
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        card = { name = "Eight of Wands", value = 8, suit = constants.SUITS.WANDS },
        spellId = "illusion",
        image = "A jeweled doorway floating above the floor",
        zoneId = "vault",
    })
    assertTrue(not missingNaturalDoom.success,
        "Spirit Natural Sorcery should require its lesser doom")
    assertTrue(hasValue(missingNaturalDoom.effects, "spirit_natural_sorcery_doom_missing"),
        "blocked Spirit Natural Sorcery should report the missing lesser doom")

    local overdrawnNaturalSorcery = jinnResolver:resolve({
        actor = naturalJinn,
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        card = { name = "Eight of Wands", value = 8, suit = constants.SUITS.WANDS },
        spellId = "illusion",
        lesserDoom = naturalJinn.lesserDooms[3],
        resolveSpent = 2,
        image = "A golden staircase into the ceiling",
        zoneId = "vault",
    })
    assertTrue(not overdrawnNaturalSorcery.success,
        "Spirit Natural Sorcery should not create extra free Resolve")
    assertTrue(hasValue(overdrawnNaturalSorcery.effects, "spirit_natural_sorcery_resolve_limit"),
        "overdrawn Spirit Natural Sorcery should report its Resolve limit")

    local naturalSorcery = jinnResolver:resolve({
        actor = naturalJinn,
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        card = { name = "Eight of Wands", value = 8, suit = constants.SUITS.WANDS },
        spellId = "illusion",
        lesserDoom = naturalJinn.lesserDooms[3],
        image = "A ribald puppet show",
        zoneId = "vault",
    })
    assertTrue(naturalSorcery.success, "Spirit Natural Sorcery should cast an authored spell")
    assertTrue(hasValue(naturalSorcery.effects, "spirit_natural_sorcery") and
        hasValue(naturalSorcery.effects, "componentless_spellcasting") and
        hasValue(naturalSorcery.effects, "no_resolve_spellcasting"),
        "Spirit Natural Sorcery should report componentless no-Resolve casting")
    assertEqual(naturalSorcery.resolveSpent, 0,
        "Spirit Natural Sorcery should spend no ordinary Resolve")
    assertEqual(naturalSorcery.spellResolveValue, 1,
        "Spirit Natural Sorcery should cast at one spell-Resolve of effect")
    assertEqual(naturalJinn.resolve, 0,
        "Spirit Natural Sorcery should not decrement a spirit's Resolve")
    assertEqual(naturalJinn.committedResolve or 0, 0,
        "Spirit Natural Sorcery should not commit Resolve for ongoing spells")
    assertTrue(naturalSorcery.visualIllusion and naturalSorcery.visualIllusion.visualOnly,
        "Spirit Natural Sorcery should still apply the selected spell effect")

    local possessJinn = entity_factory.createEntity("jinn")
    possessJinn.id = "npc_jinn_possess"
    local possessed = base_entity.createEntity({
        id = "pc_jinn_possessed",
        name = "Possessed Adventurer",
        isPC = true,
        swords = 4,
    })
    local commandedVictim = base_entity.createEntity({
        id = "npc_jinn_commanded_victim",
        name = "Commanded Victim",
        isPC = false,
        health = 2,
        defense = 0,
    })
    local possess = jinnResolver:resolve({
        actor = possessJinn,
        target = possessed,
        type = action_resolver.ACTION_TYPES.MELEE,
        card = { name = "Seven of Swords", value = 7, suit = constants.SUITS.SWORDS },
        greaterDoom = possessJinn.greaterDooms[1],
        targetInitiative = 6,
        inChallenge = true,
        allEntities = { possessJinn, possessed, commandedVictim },
        controlledAction = {
            type = action_resolver.ACTION_TYPES.MELEE,
            target = commandedVictim,
            targetInitiative = 6,
        },
    })
    assertTrue(possess.success and hasValue(possess.effects, "jinn_possess"),
        "Jinn Possess should ride on a successful Attack")
    assertTrue(not possessed.conditions.staggered,
        "Jinn Possess should replace the Attack Wound")
    assertTrue(possess.controlledActionResult and possess.controlledActionResult.success,
        "Jinn Possess should immediately resolve the commanded action")
    assertEqual(possess.controlledActionResult.testValue, 7,
        "Jinn Possess controlled action should use the Attack card value only")
    assertEqual(commandedVictim.npcHealth, 1,
        "Jinn Possess commanded action should affect the commanded target")
    assertTrue(not possessed.conditions.controlled and possessed.controlledBy == nil,
        "Jinn Possess should release control after the immediate command resolves")
end

function checkYellowKingRuntime()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local lich = entity_factory.createEntity("yellow_king_lich")
    lich.id = "npc_yellow_king_runtime"
    lich.zone = "throne"

    local shrouded = base_entity.createEntity({
        id = "pc_yellow_king_shrouded",
        name = "Shrouded Adventurer",
        isPC = true,
    })
    shrouded.conditions.shrouded = true
    assertTrue(resolver:canActorSeeShrouded(lich, shrouded, {}),
        "Yellow King Second Sight should see Shrouded creatures")

    local spite = resolver:resolve({
        actor = lich,
        type = action_resolver.ACTION_TYPES.YELLOW_KING_SPITE_ALONE,
        card = { name = "Two of Wands", value = 2, suit = constants.SUITS.WANDS },
    })
    assertTrue(spite.success and lich.conditions.yellow_king_spite_alone,
        "Spite Alone Holds Me Aloft should place the Yellow King in the upper reaches")

    local attacker = base_entity.createEntity({
        id = "pc_yellow_king_attacker",
        name = "Yellow King Attacker",
        isPC = true,
        swords = 8,
    })
    attacker.zone = "throne"
    local unreachable = resolver:resolve({
        actor = attacker,
        target = lich,
        type = action_resolver.ACTION_TYPES.MELEE,
        card = { name = "King of Swords", value = 14, suit = constants.SUITS.SWORDS },
        targetInitiative = 1,
    })
    assertTrue(not unreachable.success and hasValue(unreachable.effects, "only_ranged_attacks_can_hit"),
        "Spite Alone Holds Me Aloft should block melee attacks")

    attacker.inventory = inventory.createInventory()
    attacker.ammo = 1
    local bow = inventory.createItem({
        name = "Bow",
        weaponType = "bow",
        isWeapon = true,
        isRanged = true,
        uses_ammo = false,
    })
    attacker.inventory:addItem(bow, inventory.LOCATIONS.HANDS)
    local ranged = resolver:resolve({
        actor = attacker,
        target = lich,
        type = action_resolver.ACTION_TYPES.MISSILE,
        card = { name = "Nine of Swords", value = 9, suit = constants.SUITS.SWORDS },
        weapon = bow,
        targetInitiative = 1,
    })
    assertTrue(ranged.success,
        "Spite Alone Holds Me Aloft should still allow ranged attacks")

    local disarm = resolver:resolve({
        actor = attacker,
        target = lich,
        type = action_resolver.ACTION_TYPES.DISARM,
        card = { name = "Ten of Pentacles", value = 10, suit = constants.SUITS.PENTACLES },
        targetInitiative = 1,
    })
    assertTrue(disarm.success and lich.conditions.yellow_king_crown_disarmed,
        "Disarm should knock away the Crown of Archwood")
    assertTrue(not resolver:yellowKingHasActiveCrown(lich),
        "a disarmed Crown of Archwood should disable crown powers")

    local blockedSpite = resolver:resolve({
        actor = lich,
        type = action_resolver.ACTION_TYPES.YELLOW_KING_SPITE_ALONE,
        card = { name = "Three of Wands", value = 3, suit = constants.SUITS.WANDS },
    })
    assertTrue(not blockedSpite.success and hasValue(blockedSpite.effects, "yellow_king_crown_required"),
        "Yellow King crown powers should fail while the Crown is disarmed")

    local recoverCrown = resolver:resolve({
        actor = lich,
        type = action_resolver.ACTION_TYPES.RECOVER,
        card = { name = "Four of Wands", value = 4, suit = constants.SUITS.WANDS },
        recoverEffect = "crown",
    })
    assertTrue(recoverCrown.success and resolver:yellowKingHasActiveCrown(lich),
        "Recover should restore the Crown of Archwood")

    local deathDealerTarget = base_entity.createEntity({
        id = "pc_yellow_king_death_dealer_target",
        name = "Death Dealer Target",
        isPC = true,
    })
    deathDealerTarget.zone = "throne"
    lich.conditions.yellow_king_spite_alone = false
    local deathDealer = resolver:resolve({
        actor = lich,
        target = deathDealerTarget,
        type = action_resolver.ACTION_TYPES.MELEE,
        card = major(8),
        lesserDoom = lich.lesserDooms[1],
        targetInitiative = 1,
    })
    assertTrue(deathDealer.success and hasValue(deathDealer.effects, "piercing") and
        hasValue(deathDealer.effects, "yellow_king_death_dealer"),
        "Death Dealer should make the Yellow King's melee Attack Piercing")

    local arcaneTarget = base_entity.createEntity({
        id = "pc_yellow_king_arcane_target",
        name = "Arcane Target",
        isPC = true,
    })
    arcaneTarget.zone = "gallery"
    local arcane = resolver:resolve({
        actor = lich,
        target = arcaneTarget,
        type = action_resolver.ACTION_TYPES.MISSILE,
        card = major(7),
        lesserDoom = lich.lesserDooms[4],
        targetInitiative = 12,
    })
    assertTrue(arcane.success and arcane.testValue == 13 and hasValue(arcane.effects, "magic"),
        "If the Poison Won't Take You should attack with Wands as one-zone arcane energy")
    assertTrue(arcaneTarget.conditions.staggered,
        "Yellow King arcane attacks should wound on a hit")

    local sorrowTarget = base_entity.createEntity({
        id = "pc_yellow_king_sorrow_target",
        name = "Sorrow Target",
        isPC = true,
    })
    local sorrowResister = base_entity.createEntity({
        id = "pc_yellow_king_sorrow_resister",
        name = "Sorrow Resister",
        isPC = true,
    })
    local sorrow = resolver:resolve({
        actor = lich,
        type = action_resolver.ACTION_TYPES.YELLOW_KING_SORROW,
        lesserDoom = lich.lesserDooms[3],
        lesserDoomCard = major(5),
        onTurn = true,
        targets = { sorrowTarget, sorrowResister },
        targetInitiatives = {
            pc_yellow_king_sorrow_target = 10,
            pc_yellow_king_sorrow_resister = 20,
        },
    })
    assertTrue(sorrow.success and sorrowTarget.conditions.stunned and not sorrowResister.conditions.stunned,
        "Sorrow should Stun listeners whose Initiative is beaten")
    assertEqual(sorrow.testValue, 11,
        "Sorrow should add Wands on the Yellow King's turn")

    local controller = {
        npcs = { lich },
        allCombatants = { lich },
    }
    local clone = resolver:resolve({
        actor = lich,
        type = action_resolver.ACTION_TYPES.YELLOW_KING_FAITHFUL_SERVANT,
        greaterDoom = lich.greaterDooms[2],
        greaterDoomCard = major(17),
        cloneName = "Dead Guildmate",
        challengeController = controller,
    })
    assertTrue(clone.success and clone.summonedEntity and clone.summonedEntity.npcHealth == 1 and
        clone.summonedEntity.npcDefense == 0,
        "Faithful Servant should create a temporary HD 1/0 clone")
    assertTrue(clone.summonedEntity.knowsLifeMemories and #controller.npcs == 2,
        "Faithful Servant clones should know the dead person's memories and join the NPC roster")

    local sheetLoss = resolver:resolve({
        actor = lich,
        target = attacker,
        type = action_resolver.ACTION_TYPES.YELLOW_KING_DOUBT_ME_TRAITOR,
        greaterDoom = lich.greaterDooms[1],
        greaterDoomCard = major(18),
        lossType = "talent",
        lossLabel = "Doom Eye",
    })
    assertTrue(sheetLoss.success and attacker.conditions.yellow_king_sheet_loss and
        attacker.temporarySheetLosses[1].restoredAt == "end_next_camp_phase",
        "Do You Doubt Me, Traitor? should cross off a sheet entry until next Camp end")

    local enchanted = base_entity.createEntity({
        id = "pc_yellow_king_enchanted",
        name = "Enchanted Adventurer",
        isPC = true,
        swords = 4,
    })
    local commandedVictim = base_entity.createEntity({
        id = "npc_yellow_king_commanded_victim",
        name = "Yellow King Commanded Victim",
        isPC = false,
        health = 2,
        defense = 0,
    })
    local enchant = resolver:resolve({
        actor = lich,
        target = enchanted,
        type = action_resolver.ACTION_TYPES.MELEE,
        card = major(9),
        greaterDoom = lich.greaterDooms[3],
        targetInitiative = 1,
        inChallenge = true,
        allEntities = { lich, enchanted, commandedVictim },
        controlledAction = {
            type = action_resolver.ACTION_TYPES.MELEE,
            target = commandedVictim,
            targetInitiative = 1,
        },
    })
    assertTrue(enchant.success and hasValue(enchant.effects, "yellow_king_enchant"),
        "Yellow King enchantment should ride on a successful Attack")
    assertTrue(not enchanted.conditions.staggered and enchant.controlledActionResult and
        enchant.controlledActionResult.success,
        "Yellow King enchantment should replace the Wound with an immediate controlled task")

    local spellTarget = entity_factory.createEntity("zombie")
    spellTarget.id = "npc_yellow_king_heavenfire_target"
    local day = resolver:resolve({
        actor = lich,
        target = spellTarget,
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        card = major(6),
        spellId = "heavenfire",
        greaterDoom = lich.greaterDooms[4],
        greaterDoomCard = major(19),
        useYellowKingDayOfTears = true,
    })
    assertTrue(day.success and hasValue(day.effects, "yellow_king_day_of_tears_and_mourning"),
        "Day of Tears and Mourning should cast Appendix A spells without components or Resolve")
    assertEqual(day.resolveSpent, 0,
        "Day of Tears and Mourning should not spend ordinary Resolve")

    local doomedLich = entity_factory.createEntity("yellow_king_lich")
    doomedLich.id = "npc_yellow_king_defeat"
    doomedLich.npcHealth = 1
    doomedLich.npcDefense = 0
    local defeatEffects = {}
    resolver:applyDamage(doomedLich, 1, defeatEffects, nil, nil, nil, {
        source = "attack",
    })
    assertTrue(doomedLich.yellowKingCrystalSkull and hasValue(defeatEffects, "yellow_king_crystal_skull"),
        "defeating the Yellow King's body should leave an invulnerable crystal skull")
    local skullEffects = {}
    local skullHit = resolver:applyDamage(doomedLich, 1, skullEffects, nil, nil, nil, {
        source = "attack",
    })
    assertTrue(skullHit and skullHit.immune and hasValue(skullEffects, "yellow_king_crystal_skull_invulnerable"),
        "the Yellow King's crystal skull should ignore further damage")
end

function checkVampireRuntime()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local vampire = entity_factory.createEntity("vampire")
    vampire.id = "npc_vampire_runtime"

    local sword = inventory.createItem({
        name = "Sword",
        weaponType = "sword",
        isWeapon = true,
    })
    local ordinaryEffects = {}
    local ordinaryBlocked = resolver:applyDamage(vampire, 1, ordinaryEffects, sword, nil, nil, {
        source = "attack",
    })
    assertTrue(ordinaryBlocked and ordinaryBlocked.immune,
        "Vampire Invulnerable should block ordinary weapon damage")
    assertEqual(vampire.npcHealth, 7,
        "ordinary weapon damage should not reduce vampire Health")
    assertEqual(vampire.npcDefense, 2,
        "ordinary weapon damage should not reduce vampire Defense")
    assertTrue(hasValue(ordinaryEffects, "vampire_invulnerable"),
        "Vampire immunity should report Invulnerable")

    local silverSword = inventory.createItem({
        name = "Silver Sword",
        weaponType = "sword",
        isWeapon = true,
    })
    silverSword.material = "silver"
    silverSword.properties = silverSword.properties or {}
    silverSword.properties.material = "silver"
    resolver:applyDamage(vampire, 1, {}, silverSword, nil, nil, {
        source = "attack",
    })
    assertEqual(vampire.npcDefense, 1,
        "silver weapons should bypass Vampire Invulnerable")

    resolver:applyDamage(vampire, 1, {}, sword, nil, nil, {
        source = "attack",
        sunlight = true,
    })
    assertEqual(vampire.npcDefense, 0,
        "sunlight should negate Vampire Invulnerable against ordinary damage")

    local mist = resolver:resolve({
        actor = vampire,
        type = action_resolver.ACTION_TYPES.VAMPIRE_MIST_FORM,
        greaterDoom = vampire.greaterDooms[3],
        greaterDoomCard = major(18),
    })
    assertTrue(mist.success and vampire.conditions.mist_form and vampire.intangible,
        "Vampire Mist Form should make physical objects pass through the vampire")
    local mistEffects = {}
    local mistBlocked = resolver:applyDamage(vampire, 1, mistEffects, silverSword, nil, nil, {
        source = "attack",
    })
    assertTrue(mistBlocked and mistBlocked.immune and hasValue(mistEffects, "vampire_mist_form_immune"),
        "Vampire Mist Form should block physical weapon damage even from silver")

    local batForm = resolver:resolve({
        actor = vampire,
        type = action_resolver.ACTION_TYPES.VAMPIRE_BAT_FORM,
        greaterDoom = vampire.greaterDooms[1],
        greaterDoomCard = major(17),
    })
    assertTrue(batForm.success and vampire.conditions.flying and vampire.vampireBatForm.flyMoveZones == 1,
        "Vampire Bat Form should enable one-zone flying Move actions")

    vampire.zone = "crypt"
    local controller = {
        npcs = { vampire },
        pcs = {},
        allCombatants = { vampire },
    }
    local bats = resolver:resolve({
        actor = vampire,
        type = action_resolver.ACTION_TYPES.VAMPIRE_CALL_BATS,
        lesserDoom = vampire.lesserDooms[1],
        lesserDoomCard = major(6),
        challengeController = controller,
    })
    assertTrue(bats.success and bats.summonedEntity and bats.summonedEntity.npcHealth == 2,
        "Vampire Call Bats should summon a HD 2/0 bat cloud")
    assertEqual(bats.summonedEntity.initiative, 6,
        "Vampire Call Bats should use the doom card as bat Initiative")
    assertEqual(bats.summonedEntity.gmChallengeCardsBonus, 2,
        "active vampire bat clouds should add 2 GM Challenge cards each round")
    assertEqual(#controller.npcs, 2,
        "summoned vampire bats should join the active NPC roster")

    local ai = npc_ai.createNPCAI({
        eventBus = events.createEventBus(),
        challengeController = {
            npcs = { bats.summonedEntity },
            pcs = {
                { id = "pc_vampire_bats_draw", isPC = true, conditions = {} },
            },
        },
    })
    assertEqual(ai:calculateRoundDrawCount(), 6,
        "bat-cloud draw bonus should feed the GM Challenge draw formula")

    local graceVampire = entity_factory.createEntity("vampire")
    graceVampire.id = "npc_vampire_grace"
    graceVampire.cups = 4
    resolver:resolve({
        actor = graceVampire,
        type = action_resolver.ACTION_TYPES.VAMPIRE_SUPERNATURAL_GRACE,
        lesserDoom = graceVampire.lesserDooms[2],
        card = { name = "Two of Cups", value = 2, suit = constants.SUITS.CUPS },
    })
    resolver:resolve({
        actor = graceVampire,
        type = action_resolver.ACTION_TYPES.VAMPIRE_SUPERNATURAL_GRACE,
        lesserDoom = graceVampire.lesserDooms[2],
        card = { name = "Eight of Cups", value = 8, suit = constants.SUITS.CUPS },
    })
    assertEqual(#graceVampire.vampireDodgeCards, 2,
        "Supernatural Grace should allow multiple facedown Dodge cards")
    local graceAttacker = base_entity.createEntity({
        id = "pc_vampire_grace_attacker",
        name = "Vampire Grace Attacker",
        isPC = true,
        swords = 1,
    })
    local graceAttack = resolver:resolve({
        actor = graceAttacker,
        target = graceVampire,
        type = action_resolver.ACTION_TYPES.MELEE,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        targetInitiative = 5,
    })
    assertTrue(not graceAttack.success and hasValue(graceAttack.effects, "dodged"),
        "Supernatural Grace should let the vampire choose a prepared Dodge to counter an Attack")
    assertEqual(#graceVampire.vampireDodgeCards, 1,
        "Supernatural Grace should consume only one Dodge per incoming Attack")

    graceVampire.zone = "balcony"
    local speed = resolver:resolve({
        actor = graceVampire,
        type = action_resolver.ACTION_TYPES.VAMPIRE_SUPERNATURAL_SPEED,
        lesserDoomCards = {
            { name = "Three of Swords", value = 3, suit = constants.SUITS.SWORDS },
            { name = "Four of Wands", value = 4, suit = constants.SUITS.WANDS },
        },
        destinationZone = "crypt",
    })
    assertTrue(speed.success and speed.countsTowardTurnCard == false,
        "Supernatural Speed should move without spending the one-card turn limit")
    assertEqual(graceVampire.zone, "crypt",
        "Supernatural Speed should move one zone per discarded lesser doom")

    local feedVampire = entity_factory.createEntity("vampire")
    feedVampire.id = "npc_vampire_feed"
    feedVampire.npcHealth = 5
    local feedTarget = base_entity.createEntity({
        id = "pc_vampire_feed_target",
        name = "Vampire Feed Target",
        isPC = true,
    })
    local feed = resolver:resolve({
        actor = feedVampire,
        target = feedTarget,
        type = action_resolver.ACTION_TYPES.MELEE,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        targetInitiative = 2,
        useVampireFeed = true,
        vampireFeedCard = { name = "Two of Wands", value = 2, suit = constants.SUITS.WANDS },
    })
    assertTrue(feed.success and feedTarget.conditions.staggered,
        "Vampire Feed setup Attack should Wound a condition")
    assertEqual(feedVampire.npcHealth, 6,
        "Vampire Feed should Heal the vampire after an Attack wounds a condition or talent")
    assertTrue(hasValue(feed.effects, "vampire_feed"),
        "Vampire Feed should report the healing rider")

    local mesmerizer = entity_factory.createEntity("vampire")
    mesmerizer.id = "npc_vampire_mesmerize"
    local mesmerized = base_entity.createEntity({
        id = "pc_vampire_mesmerized",
        name = "Vampire Mesmerized",
        isPC = true,
        swords = 4,
    })
    local commandedVictim = base_entity.createEntity({
        id = "npc_vampire_commanded_victim",
        name = "Vampire Commanded Victim",
        isPC = false,
        health = 2,
        defense = 0,
    })
    local mesmerize = resolver:resolve({
        actor = mesmerizer,
        target = mesmerized,
        type = action_resolver.ACTION_TYPES.MELEE,
        card = { name = "Seven of Swords", value = 7, suit = constants.SUITS.SWORDS },
        greaterDoom = mesmerizer.greaterDooms[2],
        targetInitiative = 6,
        inChallenge = true,
        allEntities = { mesmerizer, mesmerized, commandedVictim },
        controlledAction = {
            type = action_resolver.ACTION_TYPES.MELEE,
            target = commandedVictim,
            targetInitiative = 6,
        },
    })
    assertTrue(mesmerize.success and hasValue(mesmerize.effects, "vampire_mesmerize"),
        "Vampire Mesmerize should ride on a successful Attack")
    assertTrue(not mesmerized.conditions.staggered,
        "Vampire Mesmerize should replace the Attack Wound")
    assertTrue(mesmerize.controlledActionResult and mesmerize.controlledActionResult.success,
        "Vampire Mesmerize should immediately resolve the commanded action")
    assertEqual(commandedVictim.npcHealth, 1,
        "Vampire Mesmerize commanded action should affect the commanded target")

    local waryTarget = base_entity.createEntity({
        id = "pc_vampire_gaze_wary",
        name = "Vampire Gaze Wary",
        isPC = true,
        swords = 0,
    })
    mesmerizer.inventory:addItem(inventory.createItemFromTemplate("shield_light"), inventory.LOCATIONS.HANDS)
    local disfavoredAttack = resolver:resolve({
        actor = waryTarget,
        target = mesmerizer,
        type = action_resolver.ACTION_TYPES.MELEE,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        targetInitiative = 8,
        avoidsVampireGaze = true,
    })
    assertTrue(not disfavoredAttack.success and
        hasValue(disfavoredAttack.effects, "vampire_gaze_avoidance_disfavor"),
        "actions taken while avoiding a vampire's gaze should suffer disfavor")

    local avoidedMesmerize = resolver:resolve({
        actor = mesmerizer,
        target = waryTarget,
        type = action_resolver.ACTION_TYPES.MELEE,
        card = { name = "Seven of Swords", value = 7, suit = constants.SUITS.SWORDS },
        greaterDoom = mesmerizer.greaterDooms[2],
        targetInitiative = 6,
        targetAvoidsGaze = true,
    })
    assertTrue(avoidedMesmerize.success and
        hasValue(avoidedMesmerize.effects, "vampire_mesmerize_gaze_avoided"),
        "avoiding eye contact should block Vampire Mesmerize")
    assertTrue(not waryTarget.conditions.controlled and not waryTarget.conditions.staggered,
        "gaze-avoided Vampire Mesmerize should not Control or Wound the target")
end

function checkImpRuntime()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local imp = entity_factory.createEntity("imp")
    imp.id = "npc_imp_runtime"

    local target = base_entity.createEntity({
        id = "pc_imp_vomit_target",
        name = "Imp Vomit Target",
        isPC = true,
    })
    target.inventory = inventory.createInventory()
    local targetDagger = inventory.createItem({
        name = "Target Dagger",
        weaponType = "dagger",
        isWeapon = true,
        durability = 2,
    })
    target.inventory:addItem(targetDagger, inventory.LOCATIONS.HANDS)

    local vomit = resolver:resolve({
        actor = imp,
        target = target,
        type = action_resolver.ACTION_TYPES.MELEE,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        lesserDoom = imp.lesserDooms[1],
        targetInitiative = 1,
    })
    assertTrue(vomit.success and hasValue(vomit.effects, "imp_vomit"),
        "Imp Vomit should ride on a successful Attack")
    assertTrue(not target.conditions.staggered,
        "Imp Vomit should deal no Wound")
    assertEqual(targetDagger.notches, 1,
        "Imp Vomit should Notch one target item")

    local roughTarget = base_entity.createEntity({
        id = "pc_imp_filth_target",
        name = "Imp Filth Target",
        isPC = true,
    })
    local filth = resolver:resolve({
        actor = imp,
        target = roughTarget,
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "trip",
        card = { name = "Eight of Pentacles", value = 8, suit = constants.SUITS.PENTACLES },
        lesserDoom = imp.lesserDooms[2],
        targetInitiative = 1,
    })
    assertTrue(filth.success and roughTarget.conditions.prone and roughTarget.conditions.stressed,
        "Imp Piss and Shit should add Stressed to a successful Roughhouse")
    assertTrue(hasValue(filth.effects, "imp_piss_and_shit"),
        "Imp Piss and Shit should report the stress rider")

    local bystander = base_entity.createEntity({
        id = "pc_imp_bystander",
        name = "Imp Bystander",
        isPC = true,
    })
    imp.zone = "pit"
    target.zone = "pit"
    bystander.zone = "pit"
    local incoming = {
        actor = target,
        target = imp,
        type = action_resolver.ACTION_TYPES.MELEE,
    }
    local badLuck = resolver:resolve({
        actor = imp,
        target = bystander,
        type = action_resolver.ACTION_TYPES.IMP_BAD_LUCK_MACHINE,
        greaterDoom = imp.greaterDooms[1],
        greaterDoomCard = major(18),
        incomingAction = incoming,
    })
    assertTrue(badLuck.success and incoming.target == bystander,
        "Imp Bad Luck Machine should retarget an incoming action to a same-zone creature")
    assertTrue(incoming.disfavor and hasValue(badLuck.effects, "disfavor"),
        "Imp Bad Luck Machine should add disfavor to the retargeted action")

    local ai = npc_ai.createNPCAI({
        eventBus = events.createEventBus(),
        challengeController = {
            npcs = {},
            pcs = {},
        },
    })
    ai.hand = {
        major(12),
        major(3),
        major(9),
    }
    local chosenIndex = ai:chooseInitiativeCard({
        id = "npc_imp_initiative",
        blueprintId = "imp",
        behavior = "defensive",
        conditions = {},
    })
    assertEqual(chosenIndex, 2,
        "Imps should always choose the lowest Initiative card even with defensive behavior")
end

function checkBloodybonesRuntime()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local bloodybones = entity_factory.createEntity("bloodybones")
    local startingHealth = bloodybones.npcHealth
    local startingDefense = bloodybones.npcDefense

    local sword = inventory.createItem({
        name = "Sword",
        weaponType = "sword",
    })
    local swordEffects = {}
    local swordBlocked = resolver:applyDamage(bloodybones, 1, swordEffects, sword, nil, nil, {
        source = "attack",
    })
    assertTrue(swordBlocked and swordBlocked.immune and swordBlocked.result == "invulnerable",
        "Bloodybones Immune to Damage should block ordinary weapon Wounds")
    assertEqual(bloodybones.npcHealth, startingHealth,
        "Bloodybones weapon immunity should leave infinite Health unchanged")
    assertEqual(bloodybones.npcDefense, startingDefense,
        "Bloodybones weapon immunity should leave Defense unchanged")
    assertTrue(hasValue(swordEffects, "bloodybones_immune_to_damage") and
        hasValue(swordEffects, "never_takes_wounds"),
        "Bloodybones weapon immunity should report never taking Wounds")

    local fireEffects = { "fire" }
    local fireBlocked = resolver:applyDamage(bloodybones, 1, fireEffects, nil, nil, nil, {
        source = "fire",
        fire = true,
    })
    assertTrue(fireBlocked and fireBlocked.immune,
        "Bloodybones Immune to Damage should block fire")
    assertEqual(bloodybones.npcHealth, startingHealth,
        "Bloodybones fire immunity should leave Health unchanged")

    local spellEffects = { "spell", "magic" }
    local spellBlocked = resolver:applyDamage(bloodybones, 2, spellEffects, nil, nil, nil, {
        source = "spell",
        magical = true,
    })
    assertTrue(spellBlocked and spellBlocked.immune and spellBlocked.amountPrevented == 2,
        "Bloodybones Immune to Damage should block spells and all requested Wounds")
    assertEqual(bloodybones.npcHealth, startingHealth,
        "Bloodybones spell immunity should leave Health unchanged")
    assertTrue(not bloodybones.conditions.dead and not bloodybones.conditions.deaths_door,
        "Bloodybones blocked damage should not mark defeat conditions")

    local sorcerer = base_entity.createEntity({
        id = "pc_bloodybones_sorcerer",
        name = "Bloodybones Sorcerer",
        isPC = true,
        talents = {
            magic_of_the_weald = { mastered = true },
        },
    })
    local shrouded = base_entity.createEntity({
        id = "pc_bloodybones_shrouded",
        name = "Bloodybones Shrouded",
        isPC = true,
    })
    shrouded.conditions.shrouded = true
    local mundane = base_entity.createEntity({
        id = "pc_bloodybones_mundane",
        name = "Bloodybones Mundane",
        isPC = true,
    })

    local smelled = resolver:getBloodybonesSmelledMagic(bloodybones, { sorcerer, shrouded, mundane })
    assertEqual(#smelled, 2,
        "Bloodybones Smell Magic should identify sorcerers or magical effects by scent")
    assertTrue(smelled[1].subject == sorcerer and smelled[1].sorcerer and smelled[1].scent,
        "Bloodybones Smell Magic should distinguish sorcerers")
    assertTrue(smelled[2].subject == shrouded and smelled[2].magicalEffect,
        "Bloodybones Smell Magic should distinguish magical effects")

    local notBloodybones = base_entity.createEntity({
        id = "npc_not_bloodybones",
        name = "Not Bloodybones",
        isPC = false,
    })
    assertEqual(#resolver:getBloodybonesSmelledMagic(notBloodybones, { sorcerer }), 0,
        "non-Bloodybones creatures should not use Bloodybones Smell Magic")
end

function checkAnimateStatueRuntime()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local statue = entity_factory.createEntity("animate_statue")
    local statueDefense = statue.npcDefense
    local notcher = base_entity.createEntity({
        id = "pc_animate_statue_notcher",
        name = "Animate Statue Notcher",
        isPC = true,
        pentacles = 4,
        talents = {
            fight_dirty = { mastered = true },
        },
    })
    local notch = resolver:resolve({
        actor = notcher,
        target = statue,
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "notch",
        card = { name = "Ten of Pentacles", value = 10, suit = constants.SUITS.PENTACLES },
        targetInitiative = 5,
    })
    assertTrue(notch.success, "Fight Dirty Notch should work against an Animate Statue construct")
    assertTrue(hasValue(notch.effects, "animate_statue_construct_notch_wounds"),
        "Animate Statue Construct should convert Notches into Wounds")
    assertEqual(statue.npcDefense, statueDefense - 2,
        "Animate Statue should treat one Notch as 2 Wounds")

    local sorcerer = base_entity.createEntity({
        id = "pc_animate_statue_sorcerer",
        name = "Animate Statue Sorcerer",
        isPC = true,
        talents = {
            magic_of_the_wastes = { mastered = true },
        },
    })
    local magicalSubject = base_entity.createEntity({
        id = "pc_animate_statue_magic_effect",
        name = "Animate Statue Magic Effect",
        isPC = true,
    })
    magicalSubject.activeSpells = {
        { spellId = "shroud" },
    }
    local mundane = base_entity.createEntity({
        id = "pc_animate_statue_mundane",
        name = "Animate Statue Mundane",
        isPC = true,
    })
    local sensed = resolver:getAnimateStatueSensedMagic(statue, { sorcerer, magicalSubject, mundane })
    assertEqual(#sensed, 2,
        "Animate Statue Sense Magic should identify sorcerers or magical effects")
    assertTrue(sensed[1].subject == sorcerer and sensed[1].sorcerer and sensed[1].sight,
        "Animate Statue Sense Magic should identify sorcerers by sight")
    assertTrue(sensed[2].subject == magicalSubject and sensed[2].magicalEffect,
        "Animate Statue Sense Magic should identify magical effects")

    local caster = base_entity.createEntity({
        id = "pc_animate_statue_caster",
        name = "Animate Statue Caster",
        isPC = true,
        wands = 4,
        resolve = { current = 4, max = 4 },
        talents = {
            magic_of_the_wastes = { mastered = true },
        },
    })
    caster.resolve = { current = 4, max = 4 }
    caster.inventory = inventory.createInventory()
    caster.inventory:addItem(inventory.createItemFromTemplate("component_withering"), inventory.LOCATIONS.HANDS)

    local nullTarget = entity_factory.createEntity("animate_statue")
    local blocked = resolver:resolve({
        actor = caster,
        target = nullTarget,
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "withering",
        card = { name = "Nine of Wands", value = 9, suit = constants.SUITS.WANDS },
        targetInitiative = 1,
    })
    assertTrue(not blocked.success and hasValue(blocked.effects, "animate_statue_magic_null"),
        "Animate Statue Magically Null should block ordinary magic")
    assertEqual(caster.resolve.current, 4,
        "blocked Animate Statue magic should not spend Resolve")

    local objectMagicTarget = entity_factory.createEntity("animate_statue")
    local objectMagic = resolver:resolve({
        actor = caster,
        target = objectMagicTarget,
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "withering",
        objectTargetingMagic = true,
        card = { name = "Nine of Wands", value = 9, suit = constants.SUITS.WANDS },
        targetInitiative = 1,
    })
    assertTrue(objectMagic.success and not hasValue(objectMagic.effects, "animate_statue_magic_null"),
        "object-targeting magic should be allowed through Animate Statue Magically Null")

    local haymakerStatue = entity_factory.createEntity("animate_statue")
    haymakerStatue.id = "npc_animate_statue_haymaker"
    haymakerStatue.zone = "gallery"
    local firstTarget = base_entity.createEntity({
        id = "pc_animate_statue_haymaker_first",
        name = "First Haymaker Target",
        isPC = true,
    })
    firstTarget.zone = "gallery"
    local secondTarget = base_entity.createEntity({
        id = "pc_animate_statue_haymaker_second",
        name = "Second Haymaker Target",
        isPC = true,
    })
    secondTarget.zone = "gallery"
    local farTarget = base_entity.createEntity({
        id = "pc_animate_statue_haymaker_far",
        name = "Far Haymaker Target",
        isPC = true,
    })
    farTarget.zone = "alcove"
    local sameZoneMonster = entity_factory.createEntity("zombie")
    sameZoneMonster.id = "npc_animate_statue_haymaker_bystander"
    sameZoneMonster.zone = "gallery"
    local haymaker = resolver:resolve({
        actor = haymakerStatue,
        target = firstTarget,
        type = action_resolver.ACTION_TYPES.MELEE,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        lesserDoom = haymakerStatue.lesserDooms[1],
        targetInitiative = 5,
        targetInitiatives = {
            pc_animate_statue_haymaker_second = 5,
            pc_animate_statue_haymaker_far = 5,
        },
        allEntities = { haymakerStatue, firstTarget, secondTarget, farTarget, sameZoneMonster },
    })
    assertTrue(haymaker.success and hasValue(haymaker.effects, "animate_statue_haymaker"),
        "Animate Statue Haymaker should resolve as a same-zone Attack rider")
    assertTrue(haymaker.zoneAttackResults and #haymaker.zoneAttackResults == 1,
        "Animate Statue Haymaker should attack each other same-zone adventurer")
    assertTrue(firstTarget.conditions.staggered and secondTarget.conditions.staggered,
        "Animate Statue Haymaker should wound primary and same-zone adventurer targets")
    assertTrue(not farTarget.conditions.staggered and sameZoneMonster.npcHealth == sameZoneMonster.npcMaxHealth,
        "Animate Statue Haymaker should not hit far targets or non-adventurers")

    local grabBus = events.createEventBus()
    local grabZones = zone_system.createZoneRegistry({ eventBus = grabBus })
    grabZones:setRoomZones(buildLinearZones())
    local grabResolver = action_resolver.createActionResolver({
        eventBus = grabBus,
        zoneSystem = grabZones,
    })
    local grabStatue = entity_factory.createEntity("animate_statue")
    grabStatue.id = "npc_animate_statue_grab"
    grabStatue.zone = "A"
    grabZones:placeEntity(grabStatue.id, grabStatue.zone)
    local grabbed = base_entity.createEntity({
        id = "pc_animate_statue_grabbed",
        name = "Grabbed Adventurer",
        isPC = true,
    })
    grabbed.zone = "A"
    grabZones:placeEntity(grabbed.id, grabbed.zone)
    local grab = grabResolver:resolve({
        actor = grabStatue,
        target = grabbed,
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "grab",
        card = { name = "Ten of Pentacles", value = 10, suit = constants.SUITS.PENTACLES },
        lesserDoom = grabStatue.lesserDooms[2],
        targetInitiative = 5,
    })
    assertTrue(grab.success and grabbed.conditions.rooted and grabbed.animateStatueGrabbedBy == grabStatue,
        "Animate Statue Grab should Root the target and store the grab link")

    local moveGrab = grabResolver:resolve({
        actor = grabStatue,
        type = action_resolver.ACTION_TYPES.MOVE,
        card = { name = "Six of Pentacles", value = 6, suit = constants.SUITS.PENTACLES },
        destinationZone = "B",
        challengeController = { zones = buildLinearZones() },
        allEntities = { grabStatue, grabbed },
    })
    assertTrue(moveGrab.success and grabbed.zone == "B",
        "grabbed adventurers should move with the animate statue")
    assertTrue(hasValue(moveGrab.effects, "animate_statue_grab_victims_moved"),
        "Animate Statue movement should report moved grabbed victims")

    local missAttacker = base_entity.createEntity({
        id = "pc_animate_statue_miss_attacker",
        name = "Miss Attacker",
        isPC = true,
        swords = 0,
    })
    missAttacker.zone = "B"
    local miss = grabResolver:resolve({
        actor = missAttacker,
        target = grabStatue,
        type = action_resolver.ACTION_TYPES.MELEE,
        card = { name = "Two of Swords", value = 2, suit = constants.SUITS.SWORDS },
        targetInitiative = 20,
        allEntities = { grabStatue, grabbed, missAttacker },
    })
    assertTrue(not miss.success and hasValue(miss.effects, "animate_statue_missed_attack_redirected"),
        "missed Attacks against an Animate Statue should hit a grabbed adventurer")
    assertTrue(grabbed.conditions.staggered,
        "Animate Statue missed-attack redirection should Wound the grabbed adventurer")

    local squeeze = grabResolver:resolve({
        actor = grabStatue,
        type = action_resolver.ACTION_TYPES.ANIMATE_STATUE_SQUEEZE,
        greaterDoom = grabStatue.greaterDooms[1],
        allEntities = { grabStatue, grabbed },
    })
    assertTrue(squeeze.success and squeeze.cardless and squeeze.countsTowardTurnCard == false,
        "Animate Statue Squeeze should resolve as a cardless greater doom")
    assertTrue(grabbed.conditions.injured,
        "Animate Statue Squeeze should automatically Wound grabbed adventurers")

    local thrown = base_entity.createEntity({
        id = "pc_animate_statue_thrown",
        name = "Thrown Adventurer",
        isPC = true,
    })
    thrown.zone = "B"
    local throwGrab = grabResolver:resolve({
        actor = grabStatue,
        target = thrown,
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "grab",
        card = { name = "Ten of Pentacles", value = 10, suit = constants.SUITS.PENTACLES },
        lesserDoom = grabStatue.lesserDooms[2],
        targetInitiative = 5,
    })
    assertTrue(throwGrab.success, "test setup should grab a target for Throw Stones")
    local throwTarget = base_entity.createEntity({
        id = "pc_animate_statue_throw_target",
        name = "Throw Stones Target",
        isPC = true,
    })
    throwTarget.zone = "B"
    local throw = grabResolver:resolve({
        actor = grabStatue,
        target = throwTarget,
        type = action_resolver.ACTION_TYPES.MELEE,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        lesserDoom = grabStatue.lesserDooms[3],
        thrownHeldTarget = thrown,
        targetInitiative = 5,
        allEntities = { grabStatue, thrown, throwTarget },
    })
    assertTrue(throw.success and hasValue(throw.effects, "animate_statue_throw_stones"),
        "Animate Statue Throw Stones should resolve as an Attack rider")
    assertTrue(thrown.conditions.staggered and thrown.animateStatueGrabbedBy == nil,
        "Throw Stones should Wound and release the thrown held adventurer")
end

function checkUngoatRuntime()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local attacker = base_entity.createEntity({
        id = "pc_ungoat_attacker",
        name = "Ungoat Attacker",
        isPC = true,
    })
    local ungoat = entity_factory.createEntity("ungoat")
    ungoat.id = "npc_ungoat_runtime"
    local sword = inventory.createItem({
        name = "Sword",
        weaponType = "sword",
    })
    local woundEffects = {}
    resolver:applyDamage(ungoat, 1, woundEffects, sword, nil, nil, {
        source = "attack",
        direct = true,
        action = {
            actor = attacker,
            allEntities = { attacker, ungoat },
        },
        maleficenceBranch = "wastes",
    })
    assertTrue(attacker.pendingMaleficence and
        attacker.pendingMaleficence.reason == "ungoat_maleficent_retribution",
        "direct Wounds to an ungoat should trigger maleficence for the attacker")
    assertTrue(hasValue(woundEffects, "ungoat_maleficent_retribution"),
        "Ungoat Maleficent Retribution should be explicit")

    local saltAttacker = base_entity.createEntity({
        id = "pc_ungoat_salt_attacker",
        name = "Ungoat Salt Attacker",
        isPC = true,
    })
    local saltGoat = entity_factory.createEntity("ungoat")
    saltGoat.id = "npc_ungoat_salt"
    saltAttacker.inventory = inventory.createInventory()
    local salt = inventory.createItemFromTemplate("salt")
    saltAttacker.inventory:addItem(salt, inventory.LOCATIONS.HANDS)
    local saltThrow = resolver:resolve({
        actor = saltAttacker,
        target = saltGoat,
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        itemId = salt.id,
        targetInitiative = 1,
        allEntities = { saltAttacker, saltGoat },
    })
    assertTrue(saltThrow.success and saltGoat.conditions.deaths_door,
        "salt thrown from hand should deal 2 Wounds to an ungoat on a successful Attack")
    assertTrue(not saltAttacker.pendingMaleficence,
        "salt Wounds should not trigger Ungoat Maleficent Retribution")
    assertTrue(hasValue(saltThrow.effects, "salt_reactive"),
        "Ungoat salt vulnerability should use the salt reactive damage path")

    local packTarget = base_entity.createEntity({
        id = "pc_ungoat_pack_target",
        name = "Ungoat Pack Target",
        isPC = true,
    })
    packTarget.inventory = inventory.createInventory()
    local reagent = inventory.createItemFromTemplate("jinn_reagent")
    packTarget.inventory:addItem(reagent, inventory.LOCATIONS.PACK)
    local rummager = entity_factory.createEntity("ungoat")
    rummager.id = "npc_ungoat_rummager"
    local rummage = resolver:resolve({
        actor = rummager,
        target = packTarget,
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "rummage",
        card = { name = "Eight of Pentacles", value = 8, suit = constants.SUITS.PENTACLES },
        lesserDoom = rummager.lesserDooms[1],
        targetInitiative = 1,
    })
    assertTrue(rummage.success and rummage.droppedItem == reagent,
        "Ungoat Rummage should pull an item out of the target's backpack")
    assertTrue(not packTarget.inventory:findItem(reagent.id) and #packTarget.droppedItems == 1,
        "Ungoat Rummage should leave the pack item dropped on the ground")
    assertTrue(hasValue(rummage.effects, "pack_item_dropped"),
        "Ungoat Rummage should report dropped pack items")

    local recovered = resolver:resolve({
        actor = packTarget,
        type = action_resolver.ACTION_TYPES.RECOVER,
        card = { name = "Three of Wands", value = 3, suit = constants.SUITS.WANDS },
        recoverEffect = "dropped_item",
    })
    assertTrue(recovered.success and recovered.recoveredItem == reagent,
        "adventurers should be able to Recover items dropped by Ungoat Rummage")
    assertTrue(packTarget.inventory:findItem(reagent.id),
        "Recover should return a rummaged item to the adventurer's hands")

    local wand = inventory.createItemFromTemplate("wand_archwood")
    packTarget.inventory:addItem(wand, inventory.LOCATIONS.PACK)
    local secondRummage = resolver:resolve({
        actor = rummager,
        target = packTarget,
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "rummage",
        card = { name = "Nine of Pentacles", value = 9, suit = constants.SUITS.PENTACLES },
        lesserDoom = rummager.lesserDooms[1],
        targetInitiative = 1,
    })
    assertTrue(secondRummage.success and #packTarget.droppedItems == 1,
        "test setup should leave another dropped item for ungoat pick-up")
    local pickup = resolver:resolve({
        actor = rummager,
        target = packTarget,
        type = action_resolver.ACTION_TYPES.UNGOAT_PICK_UP_DROPPED_ITEM,
        card = { name = "Any Card", value = 1, suit = constants.SUITS.CUPS },
    })
    assertTrue(pickup.success and pickup.pickedUpItem == wand,
        "ungoats should pick up dropped items with any card")
    assertTrue(rummager.inventory and rummager.inventory:findItem(wand.id),
        "ungoat pick-up should move the dropped item into the ungoat's inventory")

    local sorcerer = base_entity.createEntity({
        id = "pc_ungoat_sorcerer",
        name = "Ungoat Sorcerer",
        isPC = true,
        talents = {
            magic_of_the_wastes = { mastered = true },
        },
    })
    local mundane = base_entity.createEntity({
        id = "pc_ungoat_mundane",
        name = "Ungoat Mundane",
        isPC = true,
    })
    local smelled = resolver:getUngoatSmelledMagic(rummager, { sorcerer, mundane, saltGoat })
    assertEqual(#smelled, 1,
        "Ungoat Smell Magic should identify sorcerers or magical effects by scent")
    assertTrue(smelled[1].subject == sorcerer and smelled[1].sorcerer,
        "Ungoat Smell Magic should distinguish sorcerers")
end

function checkDevilRuntime()
    local devilBus = events.createEventBus()
    local zones = zone_system.createZoneRegistry({ eventBus = devilBus })
    zones:setRoomZones({
        zone_system.createZone({ id = "pit", name = "Pit" }),
        zone_system.createZone({ id = "ledge", name = "Ledge" }),
    })
    local devilResolver = action_resolver.createActionResolver({
        eventBus = devilBus,
        zoneSystem = zones,
    })

    local devil = entity_factory.createEntity("devil")
    devil.id = "npc_devil_runtime"
    devil.zone = "pit"
    zones:placeEntity(devil.id, devil.zone)

    local sword = inventory.createItem({
        name = "Forged Sword",
        weaponType = "sword",
        properties = { forged = true, material = "steel" },
    })
    local ironEffects = {}
    local ironBlocked = devilResolver:applyDamage(devil, 1, ironEffects, sword, nil, nil, {
        source = "attack",
    })
    assertTrue(ironBlocked and ironBlocked.immune,
        "Devil Untouched by Hot Iron should ignore crafted or forged weapons")
    assertEqual(devil.npcHealth, 3,
        "Devil crafted-weapon immunity should prevent Wounds")
    assertTrue(hasValue(ironEffects, "devil_untouched_by_hot_iron"),
        "Devil crafted-weapon immunity should be explicit")

    local branch = inventory.createItem({
        name = "Branch",
        weaponType = "club",
        properties = { natural = true, improvisedNatural = true },
    })
    local branchEffects = {}
    devilResolver:applyDamage(devil, 1, branchEffects, branch, nil, nil, {
        source = "attack",
    })
    assertEqual(devil.npcHealth, 2,
        "Devils should remain vulnerable to improvised natural weapons")

    local poisoner = base_entity.createEntity({
        id = "pc_devil_poisoner",
        name = "Devil Poisoner",
        isPC = true,
    })
    poisoner.inventory = inventory.createInventory()
    local poison = inventory.createItem({
        name = "Poison Blood",
        properties = {
            useEffect = {
                type = "apply_conditions",
                target = "target",
                conditions = {
                    poisoned = true,
                },
            },
        },
    })
    poisoner.inventory:addItem(poison, inventory.LOCATIONS.HANDS)
    local poisonResult = devilResolver:resolve({
        actor = poisoner,
        target = devil,
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        card = { name = "Three of Cups", value = 3, suit = constants.SUITS.CUPS },
        itemId = poison.id,
        contestedUseItem = false,
    })
    assertTrue(poisonResult.success and hasValue(poisonResult.effects, "poison_immunity"),
        "Devil Endless Gullet should block poison effects")
    assertTrue(not devil.conditions.poisoned, "Devil Endless Gullet should prevent poisoned condition")

    local biteTarget = base_entity.createEntity({
        id = "pc_devil_bite_target",
        name = "Devil Bite Target",
        isPC = true,
    })
    biteTarget.zone = "pit"
    zones:placeEntity(biteTarget.id, biteTarget.zone)

    local blockedBite = devilResolver:resolve({
        actor = devil,
        target = biteTarget,
        type = action_resolver.ACTION_TYPES.DEVIL_BITE,
        card = { name = "Eight of Pentacles", value = 8, suit = constants.SUITS.PENTACLES },
        targetInitiative = 6,
    })
    assertTrue(not blockedBite.success, "Devil Bite should require a lesser doom")
    assertTrue(hasValue(blockedBite.effects, "devil_bite_requires_lesser_doom"),
        "blocked Devil Bite should report missing lesser doom")

    local bite = devilResolver:resolve({
        actor = devil,
        target = biteTarget,
        type = action_resolver.ACTION_TYPES.DEVIL_BITE,
        card = { name = "Eight of Pentacles", value = 8, suit = constants.SUITS.PENTACLES },
        lesserDoom = devil.lesserDooms[1],
        targetInitiative = 6,
        allEntities = { devil, biteTarget },
    })
    assertTrue(bite.success, "Devil Bite should resolve as a lesser-doom Roughhouse hold")
    assertTrue(biteTarget.conditions.rooted and biteTarget.conditions.devil_bitten,
        "Devil Bite should Root and mark the held target")
    assertTrue(biteTarget.devilMovesWith == devil,
        "Devil Bite should make the target move with the devil")

    local move = devilResolver:resolve({
        actor = devil,
        type = action_resolver.ACTION_TYPES.MOVE,
        card = { name = "Five of Pentacles", value = 5, suit = constants.SUITS.PENTACLES },
        destinationZone = "ledge",
        allEntities = { devil, biteTarget },
    })
    assertTrue(move.success, "Devil should be able to move while holding a bitten target")
    assertEqual(biteTarget.zone, "ledge",
        "Devil Bite target should move with the devil")

    local attacker = base_entity.createEntity({
        id = "pc_devil_miss_attacker",
        name = "Devil Miss Attacker",
        isPC = true,
        swords = 0,
    })
    attacker.zone = "ledge"
    local missed = devilResolver:resolve({
        actor = attacker,
        target = devil,
        type = action_resolver.ACTION_TYPES.MELEE,
        card = { name = "Two of Swords", value = 2, suit = constants.SUITS.SWORDS },
        weapon = sword,
        targetInitiative = 20,
        allEntities = { devil, biteTarget, attacker },
    })
    assertTrue(not missed.success and biteTarget.conditions.staggered,
        "Missed Attacks against a biting devil should hit a bitten target")
    assertTrue(hasValue(missed.effects, "miss_redirected_to_devil_bitten_target"),
        "Devil Bite missed-attack redirection should be explicit")

    local retreatTarget = base_entity.createEntity({
        id = "pc_devil_retreat_target",
        name = "Devil Retreat Target",
        isPC = true,
    })
    retreatTarget.zone = "ledge"
    zones:placeEntity(retreatTarget.id, retreatTarget.zone)
    devilResolver:formEngagement(devil, retreatTarget)
    local blockedRetreat = devilResolver:resolve({
        actor = devil,
        target = retreatTarget,
        type = action_resolver.ACTION_TYPES.DEVIL_FIENDISH_RETREAT,
        allEntities = { devil, retreatTarget },
    })
    assertTrue(not blockedRetreat.success, "Devil Fiendish Retreat should require a greater doom")
    local retreat = devilResolver:resolve({
        actor = devil,
        target = retreatTarget,
        type = action_resolver.ACTION_TYPES.DEVIL_FIENDISH_RETREAT,
        greaterDoom = devil.greaterDooms[1],
        allEntities = { devil, retreatTarget },
    })
    assertTrue(retreat.success and retreat.cardless and retreat.countsTowardTurnCard == false,
        "Devil Fiendish Retreat should not count toward the one-card turn limit")
    assertTrue(not zones:areEngaged(devil.id, retreatTarget.id),
        "Devil Fiendish Retreat should disengage from one adventurer")

    local breather = base_entity.createEntity({
        id = "pc_devil_cloud_breather",
        name = "Devil Cloud Breather",
        isPC = true,
    })
    breather.zone = "ledge"
    local cloud = devilResolver:resolve({
        actor = devil,
        type = action_resolver.ACTION_TYPES.DEVIL_STINKING_CLOUD,
        greaterDoom = devil.greaterDooms[2],
        targetZone = "ledge",
    })
    assertTrue(cloud.success, "Devil Stinking Cloud should resolve from a greater doom")
    local cloudStart = devilResolver:applyStinkingCloudRoundStart({
        round = 1,
        allEntities = { devil, breather },
    })
    assertEqual(#cloudStart, 1,
        "Devil Stinking Cloud should affect other creatures in the cloud but not the devil")
    assertTrue(breather.conditions.stunned and breather.stinkingCloudDrawPenalty == 1,
        "Devil Stinking Cloud should use the normal Stinking Cloud round-start effect")
    assertTrue(not devil.conditions.stunned,
        "Devil Stinking Cloud should exclude its creator")

    local swallowDevil = entity_factory.createEntity("devil")
    swallowDevil.id = "npc_devil_swallow"
    swallowDevil.zone = "pit"
    zones:placeEntity(swallowDevil.id, swallowDevil.zone)
    local swallowTarget = base_entity.createEntity({
        id = "pc_devil_swallow_target",
        name = "Devil Swallow Target",
        isPC = true,
    })
    swallowTarget.zone = "pit"
    zones:placeEntity(swallowTarget.id, swallowTarget.zone)
    devilResolver:resolve({
        actor = swallowDevil,
        target = swallowTarget,
        type = action_resolver.ACTION_TYPES.DEVIL_BITE,
        card = { name = "Eight of Pentacles", value = 8, suit = constants.SUITS.PENTACLES },
        lesserDoom = swallowDevil.lesserDooms[1],
        targetInitiative = 6,
        allEntities = { swallowDevil, swallowTarget },
    })
    local swallow = devilResolver:resolve({
        actor = swallowDevil,
        target = swallowTarget,
        type = action_resolver.ACTION_TYPES.DEVIL_SWALLOW,
        greaterDoom = swallowDevil.greaterDooms[3],
    })
    assertTrue(swallow.success and swallowTarget.conditions.swallowed,
        "Devil Swallow should move a bitten target into extradimensional danger")
    assertEqual(swallowTarget.devilSwallowEscape.successesToEscape, 3,
        "Devil Swallow should track three Swords successes to escape")

    local greatEscape = devilResolver:resolve({
        actor = swallowTarget,
        devil = swallowDevil,
        type = action_resolver.ACTION_TYPES.DEVIL_SWALLOW_TEST_FATE,
        success = true,
        greatSuccess = true,
    })
    assertTrue(greatEscape.success, "Devil Swallow Test Fate should record great successes")
    assertEqual(swallowTarget.devilSwallowEscape.successes, 2,
        "Great successes should count as two Swallow escape successes")
    local escape = devilResolver:resolve({
        actor = swallowTarget,
        devil = swallowDevil,
        type = action_resolver.ACTION_TYPES.DEVIL_SWALLOW_TEST_FATE,
        success = true,
    })
    assertTrue(escape.released and not swallowTarget.conditions.swallowed,
        "Three Swallow escape successes should make the devil vomit up the victim")

    local releaseDevil = entity_factory.createEntity("devil")
    releaseDevil.id = "npc_devil_release"
    releaseDevil.zone = "pit"
    local releaseTarget = base_entity.createEntity({
        id = "pc_devil_release_target",
        name = "Devil Release Target",
        isPC = true,
    })
    releaseTarget.zone = "pit"
    devilResolver:addDevilBiteHold(releaseDevil, releaseTarget, {})
    devilResolver:resolve({
        actor = releaseDevil,
        target = releaseTarget,
        type = action_resolver.ACTION_TYPES.DEVIL_SWALLOW,
        greaterDoom = releaseDevil.greaterDooms[3],
    })
    local releaseEffects = { "fire" }
    devilResolver:applyDamage(releaseDevil, 3, releaseEffects, nil, nil, nil, {
        source = "fire",
        fire = true,
    })
    assertTrue(releaseDevil.conditions.deaths_door or releaseDevil.conditions.dead,
        "Devil should be defeatable by natural dangers like fire")
    assertTrue(not releaseTarget.conditions.swallowed and releaseTarget.barfedUpByDevil == "devil_defeated",
        "Defeating the devil should make it barf up swallowed creatures")
    assertTrue(hasValue(releaseEffects, "devil_swallowed_creatures_released"),
        "Devil defeat release should be explicit")
end

function checkMimicRuntime()
    local mimicBus = events.createEventBus()
    local camouflageEvents = {}
    mimicBus:on("mimic_camouflage_interaction", function(data)
        camouflageEvents[#camouflageEvents + 1] = data
    end)
    local mimicResolver = action_resolver.createActionResolver({
        eventBus = mimicBus,
    })

    local attacker = base_entity.createEntity({
        id = "pc_mimic_attacker",
        name = "Mimic Attacker",
        isPC = true,
        swords = 3,
    })
    attacker.inventory = inventory.createInventory()
    local sword = inventory.createItemFromTemplate("longsword")
    attacker.inventory:addItem(sword, inventory.LOCATIONS.HANDS)

    local toughMimic = entity_factory.createEntity("mimic")
    toughMimic.inventory:addItem(inventory.createItemFromTemplate("dagger"), inventory.LOCATIONS.HANDS)
    local tieAttack = mimicResolver:resolve({
        actor = attacker,
        target = toughMimic,
        weapon = sword,
        card = { name = "Seven of Swords", value = 7, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 10,
    })
    assertTrue(not tieAttack.success, "Mimic Tough should make equal-Initiative attacks fail")
    assertTrue(hasValue(tieAttack.effects, "mimic_tough_requires_exceed"),
        "Mimic Tough tie failure should be explicit")

    local waryInteractor = base_entity.createEntity({
        id = "pc_mimic_wary_interactor",
        name = "Wary Mimic Interactor",
        isPC = true,
        cups = 2,
    })
    waryInteractor.inventory = inventory.createInventory()
    local sleepingMimic = entity_factory.createEntity("mimic")
    local safeInteraction = mimicResolver:resolve({
        actor = waryInteractor,
        target = sleepingMimic,
        card = { name = "Eight of Cups", value = 8, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.MIMIC_CAMOUFLAGE_INTERACTION,
    })
    assertTrue(safeInteraction.success, "Mimic camouflage interaction should use a Cups test")
    assertTrue(hasValue(safeInteraction.effects, "mimic_camouflage_detected"),
        "successful Mimic camouflage interaction should report the safe pullback")
    assertTrue(not sleepingMimic.awake and sleepingMimic.mimic.camouflagedAsObject,
        "successful Mimic camouflage interaction should not wake the mimic")

    local carelessInteractor = base_entity.createEntity({
        id = "pc_mimic_careless_interactor",
        name = "Careless Mimic Interactor",
        isPC = true,
        cups = 0,
    })
    carelessInteractor.inventory = inventory.createInventory()
    local ambushMimic = entity_factory.createEntity("mimic")
    local ambushInteraction = mimicResolver:resolve({
        actor = carelessInteractor,
        target = ambushMimic,
        card = { name = "Four of Cups", value = 4, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.INTERACT,
    })
    assertTrue(not ambushInteraction.success, "failed Mimic camouflage interaction should fail the Cups test")
    assertTrue(hasValue(ambushInteraction.effects, "mimic_camouflage_ambush") and
        hasValue(ambushInteraction.effects, "piercing"),
        "failed Mimic camouflage interaction should report the Piercing ambush")
    assertTrue(carelessInteractor.conditions.staggered,
        "failed Mimic camouflage interaction should apply a Piercing Wound")
    assertTrue(ambushMimic.awake and not ambushMimic.mimic.camouflagedAsObject,
        "failed Mimic camouflage interaction should wake the mimic")
    assertTrue(ambushInteraction.challengeMayProceed,
        "failed Mimic camouflage interaction should mark that a Challenge can proceed")
    assertTrue(#camouflageEvents == 2 and camouflageEvents[2].ambush,
        "Mimic camouflage interactions should emit safe and ambush events")

    local woundedMimic = entity_factory.createEntity("mimic")
    woundedMimic.inventory:addItem(inventory.createItemFromTemplate("dagger"), inventory.LOCATIONS.HANDS)
    local beforeDefense = woundedMimic.npcDefense
    local wound = mimicResolver:resolve({
        actor = attacker,
        target = woundedMimic,
        weapon = sword,
        card = { name = "Seven of Swords", value = 7, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 9,
    })
    assertTrue(wound.success, "Mimic should be Wounded when the attack exceeds Initiative")
    assertEqual(woundedMimic.npcDefense, beforeDefense - 1,
        "successful weapon attack should reduce Mimic Defense before Harden")
    assertEqual(woundedMimic.lastWoundingWeaponType, "sword",
        "Mimic should remember the last weapon type that Wounded it")

    local freshMimic = entity_factory.createEntity("mimic")
    local blockedHarden = mimicResolver:resolve({
        actor = freshMimic,
        type = action_resolver.ACTION_TYPES.MIMIC_HARDEN,
        greaterDoom = freshMimic.greaterDooms[1],
    })
    assertTrue(not blockedHarden.success, "Mimic Harden should require a prior wounding weapon type")
    assertTrue(hasValue(blockedHarden.effects, "mimic_harden_no_wounding_weapon"),
        "Mimic Harden should report missing prior weapon type")

    local harden = mimicResolver:resolve({
        actor = woundedMimic,
        type = action_resolver.ACTION_TYPES.MIMIC_HARDEN,
        greaterDoom = woundedMimic.greaterDooms[1],
    })
    assertTrue(harden.success, "Mimic Harden should resolve as a cardless greater-doom action")
    assertTrue(harden.countsTowardTurnCard == false and harden.cardless,
        "Mimic Harden should not count toward the mimic's one-card turn limit")
    assertEqual(woundedMimic.mimicWeaponImmunityType, "sword",
        "Mimic Harden should become immune to the last wounding weapon type")

    local hardenedDefense = woundedMimic.npcDefense
    local immuneHit = mimicResolver:resolve({
        actor = attacker,
        target = woundedMimic,
        weapon = sword,
        card = { name = "Seven of Swords", value = 7, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 9,
    })
    assertTrue(immuneHit.success, "Mimic Harden should not prevent the Attack from connecting")
    assertTrue(hasValue(immuneHit.effects, "mimic_harden_immune"),
        "Mimic Harden should report immunity against the hardened weapon type")
    assertEqual(woundedMimic.npcDefense, hardenedDefense,
        "Mimic Harden should prevent damage from the immune weapon type")

    local dagger = inventory.createItemFromTemplate("dagger")
    attacker.inventory:addItem(dagger, inventory.LOCATIONS.HANDS)
    local differentWeaponHit = mimicResolver:resolve({
        actor = attacker,
        target = woundedMimic,
        weapon = dagger,
        card = { name = "Seven of Swords", value = 7, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 9,
    })
    assertTrue(differentWeaponHit.success, "Mimic Harden should not block a different weapon type")
    assertEqual(woundedMimic.npcDefense, hardenedDefense - 1,
        "different weapon type should still damage the hardened mimic")

    local riotMimic = entity_factory.createEntity("mimic")
    local armoredTarget = base_entity.createEntity({
        id = "pc_mimic_riot_target",
        name = "Mimic Riot Target",
        isPC = true,
        armorSlots = 1,
    })
    armoredTarget.inventory = inventory.createInventory()
    local riot = mimicResolver:resolve({
        actor = riotMimic,
        target = armoredTarget,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        greaterDoom = riotMimic.greaterDooms[2],
        targetInitiative = 5,
    })
    assertTrue(riot.success, "Mimic Riot of Teeth should ride on a successful Attack")
    assertTrue(hasValue(riot.effects, "mimic_riot_of_teeth") and hasValue(riot.effects, "piercing"),
        "Mimic Riot of Teeth should make the Attack Piercing")
    assertEqual(armoredTarget.armorNotches, 0,
        "Mimic Riot of Teeth Piercing damage should bypass armor notches")
    assertTrue(armoredTarget.conditions.staggered,
        "Mimic Riot of Teeth should still apply the Wound after bypassing armor")

    local dirtyFighter = base_entity.createEntity({
        id = "pc_mimic_notcher",
        name = "Mimic Notcher",
        isPC = true,
        pentacles = 3,
        talents = {
            fight_dirty = { mastered = true },
        },
    })
    local notchedMimic = entity_factory.createEntity("mimic")
    local notchDefense = notchedMimic.npcDefense
    local notch = mimicResolver:resolve({
        actor = dirtyFighter,
        target = notchedMimic,
        card = { name = "Eight of Pentacles", value = 8, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "notch",
        targetInitiative = 5,
    })
    assertTrue(notch.success, "Fight Dirty Notch should work against a Mimic construct")
    assertTrue(hasValue(notch.effects, "mimic_construct_notch_wounds"),
        "Mimic Construct should convert Notches into Wounds")
    assertEqual(notchedMimic.npcDefense, notchDefense - 2,
        "Mimic Construct should treat one Notch as 2 Wounds")
end

function checkKelpieRuntime()
    local kelpieBus = events.createEventBus()
    local zones = zone_system.createZoneRegistry({ eventBus = kelpieBus })
    local kelpieResolver = action_resolver.createActionResolver({
        eventBus = kelpieBus,
        zoneSystem = zones,
    })

    local kelpie = entity_factory.createEntity("kelpie")
    kelpie.id = "npc_kelpie_trample"
    kelpie.zone = "ford"
    local firstTarget = base_entity.createEntity({
        id = "pc_kelpie_trample_first",
        name = "First Kelpie Trample Target",
        isPC = true,
    })
    firstTarget.zone = "ford"
    local secondTarget = base_entity.createEntity({
        id = "pc_kelpie_trample_second",
        name = "Second Kelpie Trample Target",
        isPC = true,
    })
    secondTarget.zone = "ford"

    local trample = kelpieResolver:resolve({
        actor = kelpie,
        target = firstTarget,
        secondTarget = secondTarget,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        lesserDoom = kelpie.lesserDooms[1],
        targetInitiative = 20,
        secondTargetInitiative = 5,
    })
    assertTrue(not trample.success, "Kelpie Trample starts from an unsuccessful Attack")
    assertTrue(trample.trampleResult and trample.trampleResult.success,
        "Kelpie Trample should attack a second same-zone target after the miss")
    assertTrue(hasValue(trample.effects, "kelpie_trample") and
        hasValue(trample.effects, "second_attack_after_miss"),
        "Kelpie Trample should report its data-driven follow-up attack")
    assertTrue(not firstTarget.conditions.staggered and secondTarget.conditions.staggered,
        "Kelpie Trample should wound the second target, not the missed first target")

    local farTarget = base_entity.createEntity({
        id = "pc_kelpie_trample_far",
        name = "Far Kelpie Trample Target",
        isPC = true,
    })
    farTarget.zone = "bank"
    local blockedTrample = kelpieResolver:resolve({
        actor = kelpie,
        target = firstTarget,
        secondTarget = farTarget,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        lesserDoom = kelpie.lesserDooms[1],
        targetInitiative = 20,
        secondTargetInitiative = 5,
    })
    assertTrue(not blockedTrample.trampleResult,
        "Kelpie Trample should not attack a second target in another zone")
    assertTrue(hasValue(blockedTrample.effects, "kelpie_trample_target_not_same_zone"),
        "Kelpie Trample should report a second target in the wrong zone")

    local thresholdKelpie = entity_factory.createEntity("kelpie")
    local thresholdHealth = thresholdKelpie.npcHealth
    local thresholdEffects = {}
    local thresholdIgnored = kelpieResolver:applyDamage(thresholdKelpie, 1, thresholdEffects,
        { name = "Iron Sword", weaponType = "sword" }, nil, nil, { source = "attack" })
    assertTrue(thresholdIgnored and thresholdIgnored.reason == "kelpie_threshold",
        "Kelpie Threshold should ignore one non-silver Wound")
    assertEqual(thresholdKelpie.npcHealth, thresholdHealth,
        "Kelpie Threshold should preserve Health when damage is below the threshold")
    assertTrue(hasValue(thresholdEffects, "kelpie_threshold_ignored"),
        "Kelpie Threshold should report ignored damage")

    local brokenKelpie = entity_factory.createEntity("kelpie")
    local brokenEffects = {}
    kelpieResolver:applyDamage(brokenKelpie, 2, brokenEffects,
        { name = "Iron Sword", weaponType = "sword" }, nil, nil, { source = "attack" })
    assertTrue(brokenKelpie.kelpieThresholdBroken,
        "Kelpie Threshold should break when dealt 2 Wounds at once")
    assertEqual(brokenKelpie.npcHealth, brokenKelpie.npcMaxHealth - 2,
        "Kelpie Threshold should let a threshold-breaking hit deal damage")
    assertTrue(hasValue(brokenEffects, "kelpie_threshold_broken"),
        "Kelpie Threshold should report the two-Wound break")

    local silverKelpie = entity_factory.createEntity("kelpie")
    local silverEffects = {}
    kelpieResolver:applyDamage(silverKelpie, 1, silverEffects,
        { name = "Silver Longsword", weaponType = "sword", properties = { silver = true } },
        nil, nil, { source = "attack" })
    assertTrue(silverKelpie.kelpieThresholdBroken,
        "Kelpie Threshold should break when damaged by a silver weapon")
    assertEqual(silverKelpie.npcHealth, silverKelpie.npcMaxHealth - 1,
        "Silver weapon damage should apply normally after breaking Kelpie Threshold")
    assertTrue(hasValue(silverEffects, "kelpie_threshold_broken_silver"),
        "Kelpie Threshold should report the silver break")
end

function checkAppendixCExceedInitiativeRuntime()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local attacker = base_entity.createEntity({
        id = "pc_exceed_initiative_attacker",
        name = "Exceed Initiative Attacker",
        isPC = true,
        swords = 0,
        pentacles = 0,
    })

    local ogre = entity_factory.createEntity("ogre")
    local ogreTie = resolver:resolve({
        actor = attacker,
        target = ogre,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        weapon = { name = "Sword", weaponType = "sword" },
        targetInitiative = 10,
    })
    assertTrue(not ogreTie.success, "Ogre Tough should make equal-Initiative melee Attacks fail")
    assertTrue(hasValue(ogreTie.effects, "ogre_tough_requires_exceed"),
        "Ogre Tough tie failure should be explicit")
    assertEqual(ogre.npcDefense, ogre.npcMaxDefense,
        "Ogre Tough tie failure should not damage Defense")

    local ogreHit = resolver:resolve({
        actor = attacker,
        target = ogre,
        card = { name = "Page of Swords", value = 11, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        weapon = { name = "Sword", weaponType = "sword" },
        targetInitiative = 10,
    })
    assertTrue(ogreHit.success, "Ogre Tough should allow Attacks that exceed Initiative")
    assertEqual(ogre.npcDefense, ogre.npcMaxDefense - 1,
        "Ogre Tough should take damage normally after an exceeding hit")

    local skeleton = entity_factory.createEntity("skeleton_brute")
    attacker.is_engaged = false
    attacker.inventory = inventory.createInventory()
    local bow = inventory.createItemFromTemplate("bow")
    attacker.inventory:addItem(bow, inventory.LOCATIONS.HANDS)
    attacker.ammo = 1
    local skeletonTie = resolver:resolve({
        actor = attacker,
        target = skeleton,
        card = { name = "Six of Swords", value = 6, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MISSILE,
        weapon = bow,
        targetInitiative = 9,
    })
    assertTrue(not skeletonTie.success, "Skeleton Fleshless should make equal-Initiative missile Attacks fail")
    assertTrue(hasValue(skeletonTie.effects, "skeleton_fleshless_requires_exceed"),
        "Skeleton Fleshless tie failure should be explicit")
    assertEqual(skeleton.npcHealth, skeleton.npcMaxHealth,
        "Skeleton Fleshless tie failure should not damage Health")
end

function checkSkeletonRuntime()
    local skeletonResolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local skeleton = entity_factory.createEntity("skeleton_brute")
    skeleton.id = "npc_skeleton_unearthly_fear"
    skeleton.zone = "crypt"
    local lowTarget = base_entity.createEntity({
        id = "pc_skeleton_fear_low",
        name = "Low Skeleton Fear Target",
        isPC = true,
    })
    lowTarget.zone = "crypt"
    local highTarget = base_entity.createEntity({
        id = "pc_skeleton_fear_high",
        name = "High Skeleton Fear Target",
        isPC = true,
    })
    highTarget.zone = "crypt"
    local farTarget = base_entity.createEntity({
        id = "pc_skeleton_fear_far",
        name = "Far Skeleton Fear Target",
        isPC = true,
    })
    farTarget.zone = "hall"

    local fear = skeletonResolver:resolve({
        actor = skeleton,
        type = action_resolver.ACTION_TYPES.SKELETON_UNEARTHLY_FEAR,
        lesserDoom = skeleton.lesserDooms[1],
        lesserDoomCard = { name = "The Chariot", value = 7, is_major = true },
        onSkeletonTurn = true,
        targetInitiatives = {
            pc_skeleton_fear_low = 10,
            pc_skeleton_fear_high = 12,
            pc_skeleton_fear_far = 1,
        },
        allEntities = { skeleton, lowTarget, highTarget, farTarget },
    })
    assertTrue(fear.success, "Skeleton Unearthly Fear should resolve from a lesser doom")
    assertEqual(fear.fearValue, 11, "Skeleton Unearthly Fear should add Wands on the skeleton's turn")
    assertTrue(hasValue(fear.effects, "skeleton_unearthly_fear") and
        hasValue(fear.effects, "zone_stun_test"),
        "Skeleton Unearthly Fear should report its zone stun test")
    assertTrue(lowTarget.conditions.stunned and not highTarget.conditions.stunned and
        not farTarget.conditions.stunned,
        "Skeleton Unearthly Fear should stun only same-zone adventurers whose Initiative is beaten")

    local archer = base_entity.createEntity({
        id = "pc_skeleton_piercing_archer",
        name = "Skeleton Piercing Archer",
        isPC = true,
        swords = 0,
        pentacles = 0,
    })
    archer.inventory = inventory.createInventory()
    archer.ammo = 1
    local bow = inventory.createItemFromTemplate("bow")
    archer.inventory:addItem(bow, inventory.LOCATIONS.HANDS)
    local fleshlessSkeleton = entity_factory.createEntity("skeleton_brute")
    local fleshlessHealth = fleshlessSkeleton.npcHealth
    local piercingAttack = skeletonResolver:resolve({
        actor = archer,
        target = fleshlessSkeleton,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MISSILE,
        weapon = bow,
        targetInitiative = 5,
    })
    assertTrue(piercingAttack.success, "Skeleton Fleshless piercing immunity should not prevent the Attack from connecting")
    assertTrue(hasValue(piercingAttack.effects, "skeleton_fleshless_piercing_immune"),
        "Skeleton Fleshless should report piercing weapon immunity")
    assertEqual(fleshlessSkeleton.npcHealth, fleshlessHealth,
        "Skeleton Fleshless should ignore damage from piercing weapons")

    local woundedSkeleton = entity_factory.createEntity("skeleton_brute")
    woundedSkeleton.id = "npc_skeleton_absorb_bones"
    woundedSkeleton.zone = "crypt"
    woundedSkeleton.npcHealth = woundedSkeleton.npcMaxHealth - 2
    local boneSource = entity_factory.createEntity("skeleton_brute")
    boneSource.id = "npc_skeleton_bone_source"
    boneSource.zone = "crypt"
    boneSource.conditions.dead = true

    local absorb = skeletonResolver:resolve({
        actor = woundedSkeleton,
        type = action_resolver.ACTION_TYPES.SKELETON_ABSORB_BONES,
        greaterDoom = woundedSkeleton.greaterDooms[1],
        allEntities = { woundedSkeleton, boneSource },
    })
    assertTrue(absorb.success, "Skeleton Absorb Bones should resolve with same-zone bones")
    assertTrue(hasValue(absorb.effects, "skeleton_absorb_bones") and hasValue(absorb.effects, "healed"),
        "Skeleton Absorb Bones should report its heal")
    assertEqual(woundedSkeleton.npcHealth, woundedSkeleton.npcMaxHealth - 1,
        "Skeleton Absorb Bones should heal one Wound")
    assertTrue(boneSource.consumedByAbsorbBones and boneSource.removed,
        "Skeleton Absorb Bones should consume the bone source")

    local blockedAbsorb = skeletonResolver:resolve({
        actor = woundedSkeleton,
        type = action_resolver.ACTION_TYPES.SKELETON_ABSORB_BONES,
        greaterDoom = woundedSkeleton.greaterDooms[1],
        allEntities = { woundedSkeleton },
    })
    assertTrue(not blockedAbsorb.success, "Skeleton Absorb Bones should require a bone source")
    assertTrue(hasValue(blockedAbsorb.effects, "skeleton_absorb_bones_missing_source"),
        "blocked Skeleton Absorb Bones should report missing bones")
end

function checkZombieRuntime()
    local zombieResolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local zombie = entity_factory.createEntity("zombie")
    zombie.id = "npc_zombie_devour"
    zombie.npcMaxHealth = 3
    zombie.npcHealth = 1
    local deathsDoorTarget = base_entity.createEntity({
        id = "pc_zombie_devour_deaths_door",
        name = "Zombie Devour Death's Door",
        isPC = true,
    })
    deathsDoorTarget:markDeathsDoor(0)

    local devour = zombieResolver:resolve({
        actor = zombie,
        target = deathsDoorTarget,
        type = action_resolver.ACTION_TYPES.ZOMBIE_DEVOUR_THE_LIVING,
        lesserDoom = zombie.lesserDooms[1],
        lesserDoomCard = { name = "Four of Swords", value = 4, suit = constants.SUITS.SWORDS },
    })
    assertTrue(devour.success, "Zombie Devour the Living should resolve against Death's Door living targets")
    assertTrue(hasValue(devour.effects, "zombie_devour_the_living") and hasValue(devour.effects, "devoured_living"),
        "Zombie Devour the Living should report devouring the target")
    assertEqual(zombie.npcHealth, 3, "Zombie Devour the Living should Heal 2 Wounds")
    assertTrue(deathsDoorTarget.conditions.dead and not deathsDoorTarget.conditions.deaths_door,
        "Zombie Devour the Living should kill and consume the Death's Door target")
    assertEqual(deathsDoorTarget.devouredByZombie, zombie.id,
        "Zombie Devour the Living should record the consuming zombie")

    local consciousTarget = base_entity.createEntity({
        id = "pc_zombie_devour_conscious",
        name = "Zombie Devour Conscious",
        isPC = true,
    })
    local blockedDevour = zombieResolver:resolve({
        actor = zombie,
        target = consciousTarget,
        type = action_resolver.ACTION_TYPES.ZOMBIE_DEVOUR_THE_LIVING,
        lesserDoom = zombie.lesserDooms[1],
        lesserDoomCard = { name = "Four of Swords", value = 4, suit = constants.SUITS.SWORDS },
    })
    assertTrue(not blockedDevour.success, "Zombie Devour the Living should require a helpless target")
    assertTrue(hasValue(blockedDevour.effects, "zombie_devour_the_living_invalid_target"),
        "blocked Zombie Devour the Living should report an invalid target")

    local fearZombie = entity_factory.createEntity("zombie")
    fearZombie.id = "npc_zombie_fear"
    fearZombie.zone = "crypt"
    fearZombie.wands = 1
    local lowFearTarget = base_entity.createEntity({
        id = "pc_zombie_fear_low",
        name = "Zombie Fear Low Initiative",
        isPC = true,
        zone = "crypt",
        initiative = 6,
    })
    local highFearTarget = base_entity.createEntity({
        id = "pc_zombie_fear_high",
        name = "Zombie Fear High Initiative",
        isPC = true,
        zone = "crypt",
        initiative = 12,
    })
    local farFearTarget = base_entity.createEntity({
        id = "pc_zombie_fear_far",
        name = "Zombie Fear Far",
        isPC = true,
        zone = "hall",
        initiative = 1,
    })
    local blockedFear = zombieResolver:resolve({
        actor = fearZombie,
        type = action_resolver.ACTION_TYPES.UNDEAD_FEAR,
        lesserDoomCard = { name = "Seven of Cups", value = 7, suit = constants.SUITS.CUPS },
        allEntities = { fearZombie, lowFearTarget },
    })
    assertTrue(not blockedFear.success, "Undead Fear should require a lesser doom")
    assertTrue(hasValue(blockedFear.effects, "undead_fear_requires_lesser_doom"),
        "blocked Undead Fear should report the missing lesser doom")

    local fear = zombieResolver:resolve({
        actor = fearZombie,
        type = action_resolver.ACTION_TYPES.UNDEAD_FEAR,
        lesserDoom = fearZombie.lesserDooms[2],
        lesserDoomCard = { name = "Seven of Cups", value = 7, suit = constants.SUITS.CUPS },
        onUndeadTurn = true,
        targetInitiatives = {
            pc_zombie_fear_low = 6,
            pc_zombie_fear_high = 12,
            pc_zombie_fear_far = 1,
        },
        destinationZones = {
            pc_zombie_fear_low = "hall",
        },
        challengeController = {
            zones = {
                { id = "crypt", adjacent_to = { "hall" } },
                { id = "hall" },
            },
        },
        allEntities = { fearZombie, lowFearTarget, highFearTarget, farFearTarget },
    })
    assertTrue(fear.success, "Undead Fear should resolve from the template lesser doom")
    assertEqual(fear.fearValue, 8, "Undead Fear should add Wands on the undead's turn")
    assertTrue(hasValue(fear.effects, "undead_fear") and hasValue(fear.effects, "fear_displaced"),
        "Undead Fear should report same-zone displacement")
    assertEqual(lowFearTarget.zone, "hall",
        "Undead Fear should Displace beaten same-zone adventurers to the player's chosen adjacent zone")
    assertEqual(highFearTarget.zone, "crypt",
        "Undead Fear should not Displace adventurers whose Initiative resists it")
    assertEqual(farFearTarget.zone, "hall",
        "Undead Fear should not affect adventurers outside the undead's zone")

    local lastGraspZombie = entity_factory.createEntity("zombie")
    lastGraspZombie.id = "npc_zombie_last_grasp"
    lastGraspZombie.zone = "crypt"
    local allEntities = { lastGraspZombie }
    local lastGraspEffects = {}
    local lastGrasp = zombieResolver:applyDamage(lastGraspZombie, 1, lastGraspEffects,
        { name = "Sword", weaponType = "sword" }, allEntities, nil, {
            source = "attack",
            targetGreaterDoom = lastGraspZombie.greaterDooms[1],
            targetInitiative = 6,
        })
    assertTrue(lastGrasp and lastGrasp.result == "zombie_last_grasp",
        "Zombie Last Grasp should prevent an incoming Wound")
    assertTrue(hasValue(lastGraspEffects, "zombie_last_grasp") and
        hasValue(lastGraspEffects, "zombie_severed_limb_spawned"),
        "Zombie Last Grasp should report the severed limb")
    assertEqual(lastGraspZombie.npcHealth, lastGraspZombie.npcMaxHealth,
        "Zombie Last Grasp should leave the zombie unwounded")
    assertTrue(not lastGraspZombie.conditions.dead, "Zombie Last Grasp should prevent destruction")
    assertEqual(#allEntities, 2, "Zombie Last Grasp should add a new enemy to combat")
    local limb = allEntities[2]
    assertTrue(limb.zombieLimb and limb.severedFrom == lastGraspZombie.id,
        "Zombie Last Grasp limb should remember its source zombie")
    assertEqual(limb.zone, "crypt", "Zombie Last Grasp limb should appear in the zombie's zone")
    assertEqual(limb.initiative, 6, "Zombie Last Grasp limb should use the zombie's Initiative")
    assertEqual(limb.npcHealth, 1, "Zombie Last Grasp limb should suffer 1 Wound before stopping")

    local limbEffects = {}
    zombieResolver:applyDamage(limb, 1, limbEffects,
        { name = "Sword", weaponType = "sword" }, allEntities, nil, {
            source = "attack",
            targetGreaterDoom = lastGraspZombie.greaterDooms[1],
            useZombieLastGrasp = true,
        })
    assertTrue(limb.conditions.dead, "Zombie severed limbs should not use Last Grasp")
    assertTrue(not hasValue(limbEffects, "zombie_last_grasp"),
        "Zombie severed limbs should not report Last Grasp")
    assertEqual(#allEntities, 2, "Zombie severed limbs should not spawn more limbs")
end

function checkSlimeRuntime()
    local slimeResolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local attacker = base_entity.createEntity({
        id = "pc_slime_attacker",
        name = "Slime Attacker",
        isPC = true,
        swords = 0,
        pentacles = 0,
    })
    local swordSlime = entity_factory.createEntity("slime")
    local sword = inventory.createItemFromTemplate("longsword")
    local swordHit = slimeResolver:resolve({
        actor = attacker,
        target = swordSlime,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        weapon = sword,
        targetInitiative = 5,
    })
    assertTrue(swordHit.success, "Slime Impermeable Membrane should not prevent the Attack from connecting")
    assertTrue(hasValue(swordHit.effects, "slime_impermeable_membrane_immune"),
        "Slime Impermeable Membrane should report slashing/crushing weapon immunity")
    assertEqual(swordSlime.npcHealth, swordSlime.npcMaxHealth,
        "Slime Impermeable Membrane should prevent sword damage")
    assertEqual(sword.notches or 0, 0,
        "Slime Acidic should not Notch weapons that fail to damage the slime")

    local daggerSlime = entity_factory.createEntity("slime")
    local dagger = inventory.createItemFromTemplate("dagger")
    local daggerHit = slimeResolver:resolve({
        actor = attacker,
        target = daggerSlime,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        weapon = dagger,
        targetInitiative = 5,
    })
    assertTrue(daggerHit.success, "Slime should take damage from sharp piercing weapons")
    assertTrue(hasValue(daggerHit.effects, "slime_acidic_weapon_notched"),
        "Slime Acidic should report Notching a damaging weapon")
    assertEqual(daggerSlime.npcHealth, daggerSlime.npcMaxHealth - 1,
        "Slime should lose Health from a piercing weapon")
    assertEqual(daggerSlime.swords, daggerSlime.npcHealth,
        "Slime Swords should track current Health after damage")
    assertEqual(daggerSlime.pentacles, daggerSlime.npcHealth,
        "Slime Pentacles should track current Health after damage")
    assertEqual(dagger.notches, 1,
        "Slime Acidic should Notch a weapon that damages it")

    local tripSlime = entity_factory.createEntity("slime")
    local trip = slimeResolver:resolve({
        actor = attacker,
        target = tripSlime,
        card = { name = "Ten of Pentacles", value = 10, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.TRIP,
        targetInitiative = 5,
    })
    assertTrue(not trip.success, "Slime Shapeless Body should block Trip")
    assertTrue(hasValue(trip.effects, "slime_trip_immune"),
        "Slime Shapeless Body should report Trip immunity")
    assertTrue(not tripSlime.conditions.prone,
        "Slime Shapeless Body should prevent Prone")

    local root = slimeResolver:resolve({
        actor = attacker,
        target = tripSlime,
        card = { name = "Ten of Pentacles", value = 10, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "root",
        targetInitiative = 5,
    })
    assertTrue(not root.success, "Slime Shapeless Body should block Root")
    assertTrue(hasValue(root.effects, "slime_root_immune"),
        "Slime Shapeless Body should report Root immunity")
    assertTrue(not tripSlime.conditions.rooted,
        "Slime Shapeless Body should prevent Rooted")

    tripSlime.zone = "near"
    local displace = slimeResolver:resolve({
        actor = attacker,
        target = tripSlime,
        card = { name = "Ten of Pentacles", value = 10, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.DISPLACE,
        destinationZone = "far",
        targetInitiative = 5,
    })
    assertTrue(not displace.success, "Slime Shapeless Body should block Displace")
    assertTrue(hasValue(displace.effects, "slime_displace_immune"),
        "Slime Shapeless Body should report Displace immunity")
    assertEqual(tripSlime.zone, "near",
        "Slime Shapeless Body should prevent forced movement")

    local engulfBus = events.createEventBus()
    local engulfZones = zone_system.createZoneRegistry({ eventBus = engulfBus })
    engulfZones:setRoomZones(buildLinearZones())
    local engulfResolver = action_resolver.createActionResolver({
        eventBus = engulfBus,
        zoneSystem = engulfZones,
    })
    local engulfSlime = entity_factory.createEntity("slime")
    engulfSlime.id = "npc_slime_engulf"
    engulfSlime.zone = "A"
    local engulfTarget = base_entity.createEntity({
        id = "pc_slime_engulfed",
        name = "Slime Engulfed Target",
        isPC = true,
    })
    engulfTarget.zone = "A"
    engulfTarget.inventory = inventory.createInventory()
    local beltFlask = inventory.createItem({ name = "Belt Flask", size = 1, durability = 2 })
    local beltArmor = inventory.createItemFromTemplate("light_armor")
    engulfTarget.inventory:addItem(beltFlask, inventory.LOCATIONS.BELT)
    engulfTarget.inventory:addItem(beltArmor, inventory.LOCATIONS.BELT)
    engulfZones:placeEntity(engulfSlime.id, "A")
    engulfZones:placeEntity(engulfTarget.id, "A")

    local engulf = engulfResolver:resolve({
        actor = engulfSlime,
        target = engulfTarget,
        card = { name = "Eight of Pentacles", value = 8, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        lesserDoom = engulfSlime.lesserDooms[1],
        targetInitiative = 10,
        allEntities = { engulfSlime, engulfTarget },
    })
    assertTrue(engulf.success and hasValue(engulf.effects, "slime_engulfed"),
        "Slime Protoplasmic Attack should engulf on a successful Roughhouse")
    assertTrue(engulfTarget.conditions.rooted and engulfTarget.slimeEngulfedBy == engulfSlime,
        "Slime Protoplasmic Attack should Root and track the engulfed target")

    local slimeMove = engulfResolver:resolve({
        actor = engulfSlime,
        card = { name = "Five of Pentacles", value = 5, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.MOVE,
        destinationZone = "B",
        allEntities = { engulfSlime, engulfTarget },
    })
    assertTrue(slimeMove.success and hasValue(slimeMove.effects, "slime_engulfed_targets_moved"),
        "Slime movement should carry engulfed targets with it")
    assertEqual(engulfTarget.zone, "B", "engulfed targets should move with the slime")

    local turnStart = engulfResolver:resolve({
        actor = engulfTarget,
        slime = engulfSlime,
        type = action_resolver.ACTION_TYPES.SLIME_ENGULF_TURN_START,
        allEntities = { engulfSlime, engulfTarget },
    })
    assertTrue(turnStart.success and hasValue(turnStart.effects, "slime_engulfed_wound"),
        "engulfed targets should take a Wound at turn start")
    assertTrue(engulfTarget.conditions.staggered,
        "Slime engulf turn start should wound the target")
    assertEqual(beltFlask.notches, 1, "Slime engulf turn start should Notch belt items")
    assertEqual(beltArmor.notches, 1, "Slime engulf turn start should Notch worn belt armor")

    local grind = engulfResolver:resolve({
        actor = engulfSlime,
        type = action_resolver.ACTION_TYPES.SLIME_GRIND,
        greaterDoom = engulfSlime.greaterDooms[1],
        allEntities = { engulfSlime, engulfTarget },
    })
    assertTrue(grind.success and grind.cardless and grind.countsTowardTurnCard == false,
        "Slime Grind should be a cardless greater-doom action")
    assertTrue(hasValue(grind.effects, "slime_grind") and engulfTarget.conditions.injured,
        "Slime Grind should wound all currently engulfed targets")

    local blockedRecover = engulfResolver:resolve({
        actor = engulfTarget,
        card = { name = "Seven of Wands", value = 7, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.RECOVER,
        recoverEffect = "rooted",
    })
    assertTrue(not blockedRecover.success and
        hasValue(blockedRecover.effects, "slime_engulf_escape_requires_test_fate"),
        "Slime engulf should require a Swords Test Fate instead of ordinary Recover")

    engulfTarget.swords = 0
    local failedEscape = engulfResolver:resolve({
        actor = engulfTarget,
        card = { name = "Nine of Swords", value = 9, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.TEST_FATE,
        escapeSlimeEngulf = true,
    })
    assertTrue(not failedEscape.success and hasValue(failedEscape.effects, "slime_engulf_escape_failed"),
        "failed Slime escape Test Fate should leave the target engulfed")
    assertTrue(engulfTarget.conditions.rooted and engulfTarget.slimeEngulfedBy == engulfSlime,
        "failed Slime escape should preserve Rooted and engulf tracking")

    engulfTarget.swords = 3
    local escape = engulfResolver:resolve({
        actor = engulfTarget,
        card = { name = "Seven of Swords", value = 7, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.TEST_FATE,
        escapeSlimeEngulf = true,
    })
    assertTrue(escape.success and hasValue(escape.effects, "slime_engulf_escape"),
        "successful Slime escape Test Fate should release the target")
    assertEqual(escape.modifier, 3, "Slime escape Test Fate should use Swords")
    assertTrue(not engulfTarget.conditions.rooted and not engulfTarget.slimeEngulfedBy,
        "successful Slime escape should clear Rooted and engulf tracking")
    assertEqual(#engulfResolver:getSlimeEngulfedTargets(engulfSlime), 0,
        "successful Slime escape should remove the target from the slime's engulf list")

    local crackSlime = entity_factory.createEntity("slime")
    crackSlime.id = "npc_slime_crack_traversal"
    crackSlime.zone = "A"
    engulfZones:placeEntity(crackSlime.id, "A")
    local crackMove = engulfResolver:resolve({
        actor = crackSlime,
        card = { name = "Five of Pentacles", value = 5, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.MOVE,
        destinationZone = "B",
        underDoor = true,
    })
    assertTrue(crackMove.success and hasValue(crackMove.effects, "slime_body_squeeze_traversal"),
        "Slime body should pass under doors and through cracks without a Test Fate")
    assertTrue(crackMove.slimeBodyTraversal and crackMove.slimeBodyTraversal.noTestFate,
        "Slime body traversal should record no-Test-Fate squeeze metadata")
    assertEqual(crackSlime.zone, "B", "Slime body traversal should update the slime's zone")

    local saltThrower = base_entity.createEntity({
        id = "pc_slime_salt_thrower",
        name = "Slime Salt Thrower",
        isPC = true,
        swords = 3,
    })
    saltThrower.inventory = inventory.createInventory()
    local salt = inventory.createItemFromTemplate("salt")
    saltThrower.inventory:addItem(salt, inventory.LOCATIONS.HANDS)
    local regenSlime = entity_factory.createEntity("slime")
    regenSlime.id = "npc_slime_regenerate"
    local saltAttack = slimeResolver:resolve({
        actor = saltThrower,
        target = regenSlime,
        card = { name = "Seven of Swords", value = 7, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = salt.id,
        targetInitiative = 5,
    })
    assertTrue(saltAttack.success and regenSlime.slimeSaltedThisTurn,
        "salt thrown onto a slime should mark Regenerate blocked for the turn")
    local blockedRegen = slimeResolver:resolve({
        actor = regenSlime,
        type = action_resolver.ACTION_TYPES.SLIME_REGENERATE,
        greaterDoom = regenSlime.greaterDooms[2],
    })
    assertTrue(not blockedRegen.success and hasValue(blockedRegen.effects, "slime_regenerate_blocked_by_salt"),
        "Slime Regenerate should be blocked by salt spread this turn")

    regenSlime.slimeSaltedThisTurn = false
    regenSlime.saltSpreadThisTurn = false
    local beforeRegenHealth = regenSlime.npcHealth
    local regenerate = slimeResolver:resolve({
        actor = regenSlime,
        type = action_resolver.ACTION_TYPES.SLIME_REGENERATE,
        greaterDoom = regenSlime.greaterDooms[2],
    })
    assertTrue(regenerate.success and regenerate.cardless and hasValue(regenerate.effects, "slime_regenerate"),
        "Slime Regenerate should heal as a cardless greater-doom action")
    assertEqual(regenSlime.npcHealth, math.min(regenSlime.npcMaxHealth, beforeRegenHealth + 1),
        "Slime Regenerate should restore one Health")
    assertEqual(regenSlime.swords, regenSlime.npcHealth,
        "Slime Regenerate should resync Swords to current Health")
    assertEqual(regenSlime.pentacles, regenSlime.npcHealth,
        "Slime Regenerate should resync Pentacles to current Health")
end

function checkOgreRuntime()
    local ogreResolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local ogre = entity_factory.createEntity("ogre")
    ogre.id = "npc_ogre_sweeping_club"
    ogre.zone = "bridge"

    local hungryOgre = entity_factory.createEntity("ogre")
    hungryOgre.id = "npc_ogre_eat_eat_eat"
    hungryOgre.inventory = inventory.createInventory({ handsSlots = 4 })
    local cursedRing = inventory.createItem({ name = "Cursed Iron Ring", size = 1, itemType = "artifact" })
    cursedRing.poisonous = true
    hungryOgre.inventory:addItem(cursedRing, inventory.LOCATIONS.HANDS)
    local eatObject = ogreResolver:resolve({
        actor = hungryOgre,
        type = action_resolver.ACTION_TYPES.OGRE_EAT_OBJECT,
        card = { name = "Two of Cups", value = 2, suit = constants.SUITS.CUPS },
        itemId = cursedRing.id,
    })
    assertTrue(eatObject.success, "Ogre Eat-Eat-Eat should let an ogre play any card to eat a held object")
    assertTrue(cursedRing.destroyed and not hungryOgre.inventory:findItem(cursedRing.id),
        "Ogre Eat-Eat-Eat should destroy and remove the eaten object")
    assertTrue(hasValue(eatObject.effects, "ogre_eat_eat_eat") and
        hasValue(eatObject.effects, "ogre_eating_no_harm"),
        "Ogre Eat-Eat-Eat should report object destruction without harm")

    local portcullis = { id = "ogre_portcullis", name = "Iron Portcullis", obstacleType = "portcullis" }
    local hideousStrength = ogreResolver:resolve({
        actor = hungryOgre,
        target = portcullis,
        type = action_resolver.ACTION_TYPES.OGRE_HIDEOUS_STRENGTH,
        card = { name = "Four of Wands", value = 4, suit = constants.SUITS.WANDS },
        strengthTask = "lift_portcullis",
    })
    assertTrue(hideousStrength.success, "Ogre Hideous Strength should resolve incredible strength feats with any card")
    assertTrue(portcullis.lifted and portcullis.open and portcullis.overcomeByOgreStrength,
        "Ogre Hideous Strength should lift a portcullis obstacle")
    assertTrue(hasValue(hideousStrength.effects, "ogre_hideous_strength") and
        hasValue(hideousStrength.effects, "portcullis_lifted"),
        "Ogre Hideous Strength should report the resolved obstacle feat")

    local firstTarget = base_entity.createEntity({
        id = "pc_ogre_sweep_first",
        name = "First Ogre Sweep Target",
        isPC = true,
    })
    firstTarget.zone = "bridge"
    local secondTarget = base_entity.createEntity({
        id = "pc_ogre_sweep_second",
        name = "Second Ogre Sweep Target",
        isPC = true,
    })
    secondTarget.zone = "bridge"
    local farTarget = base_entity.createEntity({
        id = "pc_ogre_sweep_far",
        name = "Far Ogre Sweep Target",
        isPC = true,
    })
    farTarget.zone = "stairs"
    local sameZoneMonster = entity_factory.createEntity("zombie")
    sameZoneMonster.id = "npc_ogre_sweep_bystander"
    sameZoneMonster.zone = "bridge"

    local sweep = ogreResolver:resolve({
        actor = ogre,
        target = firstTarget,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        weapon = { name = "Tree Trunk", weaponType = "club" },
        lesserDoom = ogre.lesserDooms[1],
        targetInitiative = 5,
        targetInitiatives = {
            pc_ogre_sweep_second = 5,
            pc_ogre_sweep_far = 5,
        },
        allEntities = { ogre, firstTarget, secondTarget, farTarget, sameZoneMonster },
    })
    assertTrue(sweep.success, "Ogre Sweeping Club should still resolve the primary Attack")
    assertTrue(hasValue(sweep.effects, "ogre_sweeping_club") and hasValue(sweep.effects, "zone_attack"),
        "Ogre Sweeping Club should report its zone Attack rider")
    assertTrue(sweep.zoneAttackResults and #sweep.zoneAttackResults == 1,
        "Ogre Sweeping Club should attack one additional same-zone adventurer")
    assertTrue(firstTarget.conditions.staggered and secondTarget.conditions.staggered,
        "Ogre Sweeping Club should wound primary and same-zone adventurer targets")
    assertTrue(not farTarget.conditions.staggered and sameZoneMonster.npcHealth == sameZoneMonster.npcMaxHealth,
        "Ogre Sweeping Club should not hit other-zone targets or non-adventurers")

    local bullyTarget = base_entity.createEntity({
        id = "pc_ogre_bully_target",
        name = "Ogre Bully Target",
        isPC = true,
    })
    bullyTarget.bonds = {
        ally = { status = "friendship", charged = true },
        rival = { status = "rivalry", charged = false },
    }
    local bully = ogreResolver:resolve({
        actor = ogre,
        target = bullyTarget,
        type = action_resolver.ACTION_TYPES.OGRE_BULLY,
        greaterDoom = ogre.greaterDooms[1],
        bondTargetId = "ally",
    })
    assertTrue(bully.success, "Ogre Bully should erase a chosen charged Bond")
    assertTrue(hasValue(bully.effects, "ogre_bully") and hasValue(bully.effects, "charged_bond_erased"),
        "Ogre Bully should report the erased Bond")
    assertTrue(not bullyTarget.bonds.ally.charged and bullyTarget.bonds.rival.charged == false,
        "Ogre Bully should clear only the selected charged Bond")

    local blockedBully = ogreResolver:resolve({
        actor = ogre,
        target = bullyTarget,
        type = action_resolver.ACTION_TYPES.OGRE_BULLY,
        greaterDoom = ogre.greaterDooms[1],
        bondTargetId = "ally",
    })
    assertTrue(not blockedBully.success, "Ogre Bully should fail when the selected Bond is not charged")
    assertTrue(hasValue(blockedBully.effects, "ogre_bully_no_charged_bond"),
        "blocked Ogre Bully should report the missing charged Bond")

    local overwhelmingTarget = base_entity.createEntity({
        id = "pc_ogre_overwhelming_target",
        name = "Ogre Overwhelming Target",
        isPC = true,
    })
    local overwhelming = ogreResolver:resolve({
        actor = ogre,
        target = overwhelmingTarget,
        type = action_resolver.ACTION_TYPES.OGRE_OVERWHELMING_ATTACK,
        weapon = { name = "Tree Trunk", weaponType = "club" },
        greaterDoom = ogre.greaterDooms[2],
        greaterDoomCard = { name = "The Tower", value = 16, is_major = true },
        targetInitiative = 12,
    })
    assertTrue(overwhelming.success, "Ogre Overwhelming Attack should use a greater doom as an Attack")
    assertTrue(hasValue(overwhelming.effects, "ogre_overwhelming_attack") and
        hasValue(overwhelming.effects, "greater_doom_attack"),
        "Ogre Overwhelming Attack should report its greater-doom Attack")
    assertTrue(overwhelmingTarget.conditions.staggered,
        "Ogre Overwhelming Attack should damage the target through normal melee resolution")

    local deadlyTarget = base_entity.createEntity({
        id = "pc_ogre_deadly_target",
        name = "Ogre Deadly Target",
        isPC = true,
    })
    local deadly = ogreResolver:resolve({
        actor = ogre,
        target = deadlyTarget,
        card = { name = "Nine of Swords", value = 9, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        weapon = { name = "Tree Trunk", weaponType = "club" },
        greaterDoom = ogre.greaterDooms[3],
        greaterDoomCard = { name = "The Devil", value = 15, is_major = true },
        targetInitiative = 5,
    })
    assertTrue(deadly.success, "Brute Deadly Attack should resolve on a successful Attack")
    assertTrue(hasValue(deadly.effects, "brute_deadly_attack") and hasValue(deadly.effects, "damage_increased"),
        "Brute Deadly Attack should report the increased damage")
    assertTrue(deadlyTarget.conditions.staggered and deadlyTarget.conditions.injured,
        "Brute Deadly Attack should deal 2 Wounds")

    local corrosiveTarget = base_entity.createEntity({
        id = "pc_ogre_corrosive_target",
        name = "Ogre Corrosive Target",
        isPC = true,
    })
    corrosiveTarget.inventory = inventory.createInventory()
    local corrodedSword = inventory.createItemFromTemplate("longsword")
    corrosiveTarget.inventory:addItem(corrodedSword, inventory.LOCATIONS.HANDS)
    local corrosive = ogreResolver:resolve({
        actor = ogre,
        target = corrosiveTarget,
        card = { name = "Nine of Swords", value = 9, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        weapon = { name = "Tree Trunk", weaponType = "club" },
        greaterDoom = ogre.greaterDooms[4],
        greaterDoomCard = { name = "The Tower", value = 16, is_major = true },
        targetInitiative = 5,
        targetItem = corrodedSword,
    })
    assertTrue(corrosive.success, "Brute Corrosive Attack should resolve on a successful Attack")
    assertTrue(hasValue(corrosive.effects, "brute_corrosive_attack") and
        hasValue(corrosive.effects, "wound_replaced") and hasValue(corrosive.effects, "item_destroyed"),
        "Brute Corrosive Attack should report replacing the Wound with item destruction")
    assertTrue(corrodedSword.destroyed, "Brute Corrosive Attack should destroy the selected item")
    assertTrue(not corrosiveTarget.conditions.staggered,
        "Brute Corrosive Attack should not wound when it destroys an item instead")

    local untouchableAttacker = base_entity.createEntity({
        id = "pc_ogre_untouchable_attacker",
        name = "Ogre Untouchable Attacker",
        isPC = true,
        swords = 0,
    })
    local untouchableOgre = entity_factory.createEntity("ogre")
    local untouchable = ogreResolver:resolve({
        actor = untouchableAttacker,
        target = untouchableOgre,
        card = { name = "Page of Swords", value = 11, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        weapon = { name = "Sword", weaponType = "sword" },
        targetGreaterDoom = untouchableOgre.greaterDooms[5],
        greaterDoomInitiativeCard = { name = "Queen of Wands", value = 12, suit = constants.SUITS.WANDS },
    })
    assertTrue(not untouchable.success, "Brute Untouchable should let a greater doom set Initiative")
    assertEqual(untouchable.difficulty, 12, "Brute Untouchable should use the greater doom card value")
    assertTrue(hasValue(untouchable.effects, "brute_untouchable") and
        hasValue(untouchable.effects, "greater_doom_as_initiative"),
        "Brute Untouchable should report the greater-doom Initiative")
end

function checkQuestingBeastRuntime()
    local retreatBus = events.createEventBus()
    local zones = zone_system.createZoneRegistry({ eventBus = retreatBus })
    local questResolver = action_resolver.createActionResolver({
        eventBus = retreatBus,
        zoneSystem = zones,
    })

    local beast = entity_factory.createEntity("questing_beast")
    beast.id = "npc_questing_beast_retreat"
    local firstHunter = base_entity.createEntity({
        id = "pc_questing_beast_hunter_first",
        name = "First Questing Beast Hunter",
        isPC = true,
    })
    local secondHunter = base_entity.createEntity({
        id = "pc_questing_beast_hunter_second",
        name = "Second Questing Beast Hunter",
        isPC = true,
    })
    local allEntities = { beast, firstHunter, secondHunter }
    questResolver:formEngagement(beast, firstHunter)
    questResolver:formEngagement(beast, secondHunter)

    local slipperyBeast = entity_factory.createEntity("questing_beast")
    slipperyBeast.id = "npc_questing_beast_slippery"
    local pressureTrap = { id = "trap_questing_beast_slippery", name = "Pressure Plate Trap", trap = true }
    local slippery = questResolver:resolve({
        actor = slipperyBeast,
        target = pressureTrap,
        type = action_resolver.ACTION_TYPES.QUESTING_BEAST_SLIPPERY,
        card = { name = "Two of Pentacles", value = 2, suit = constants.SUITS.PENTACLES },
        hazardType = "trap",
    })
    assertTrue(slippery.success, "Questing Beast Slippery should avoid hazards with any discarded card")
    assertTrue(slippery.countsTowardTurnCard == false and slippery.cardless ~= true,
        "Questing Beast Slippery should spend a card without counting toward the turn-card limit")
    assertTrue(pressureTrap.triggered and pressureTrap.evaded and pressureTrap.triggeredByQuestingBeast,
        "Questing Beast Slippery should trigger and evade traps")
    assertTrue(hasValue(slippery.effects, "questing_beast_slippery") and
        hasValue(slippery.effects, "trap_triggered_and_evaded"),
        "Questing Beast Slippery should report the hazard outcome")

    local pit = { id = "pit_questing_beast_slippery", name = "Open Pit", hazardType = "pit" }
    local slipperyPit = questResolver:resolve({
        actor = slipperyBeast,
        target = pit,
        type = action_resolver.ACTION_TYPES.QUESTING_BEAST_SLIPPERY,
        card = { name = "Five of Cups", value = 5, suit = constants.SUITS.CUPS },
    })
    assertTrue(slipperyPit.success and pit.leapt and pit.crossed,
        "Questing Beast Slippery should leap pits as a hazard outcome")

    local blockedRetreat = questResolver:resolve({
        actor = beast,
        type = action_resolver.ACTION_TYPES.QUESTING_BEAST_EXPEDITIOUS_RETREAT,
        allEntities = allEntities,
    })
    assertTrue(not blockedRetreat.success, "Questing Beast Expeditious Retreat should require a greater doom")
    assertTrue(hasValue(blockedRetreat.effects, "questing_beast_expeditious_retreat_requires_greater_doom"),
        "blocked Questing Beast Expeditious Retreat should report the missing greater doom")

    local retreat = questResolver:resolve({
        actor = beast,
        type = action_resolver.ACTION_TYPES.QUESTING_BEAST_EXPEDITIOUS_RETREAT,
        greaterDoom = beast.greaterDooms[2],
        allEntities = allEntities,
    })
    assertTrue(retreat.success, "Questing Beast Expeditious Retreat should resolve as a cardless greater-doom action")
    assertTrue(retreat.countsTowardTurnCard == false and retreat.cardless,
        "Questing Beast Expeditious Retreat should not spend the beast's turn card")
    assertTrue(not zones:isEngaged(beast.id),
        "Questing Beast Expeditious Retreat should disengage from all combatants")
    assertTrue(not firstHunter.is_engaged and not secondHunter.is_engaged,
        "Questing Beast Expeditious Retreat should update former hunters' engagement flags")

    local resilientBeast = entity_factory.createEntity("questing_beast")
    resilientBeast.id = "npc_questing_beast_resilient"
    resilientBeast.conditions.rooted = true
    resilientBeast.conditions.prone = true
    resilientBeast.conditions.blind = true
    resilientBeast.conditions.silenced = true
    resilientBeast.conditions.exhausted = true
    resilientBeast.conditions.burning = true
    resilientBeast.conditions.disarmed = true
    resilientBeast.conditions.webbed = true
    resilientBeast.conditions.stunned = true
    resilientBeast.webbedLimbs = 4
    resilientBeast.silenced = true
    resilientBeast.exhausted = true

    local blockedResilient = questResolver:resolve({
        actor = resilientBeast,
        type = action_resolver.ACTION_TYPES.QUESTING_BEAST_RESILIENT,
    })
    assertTrue(not blockedResilient.success, "Questing Beast Resilient should require a greater doom")
    assertTrue(hasValue(blockedResilient.effects, "questing_beast_resilient_requires_greater_doom"),
        "blocked Questing Beast Resilient should report the missing greater doom")

    local resilient = questResolver:resolve({
        actor = resilientBeast,
        type = action_resolver.ACTION_TYPES.QUESTING_BEAST_RESILIENT,
        greaterDoom = resilientBeast.greaterDooms[3],
    })
    assertTrue(resilient.success, "Questing Beast Resilient should resolve as a cardless greater-doom action")
    assertTrue(resilient.countsTowardTurnCard == false and resilient.cardless,
        "Questing Beast Resilient should not spend the beast's turn card")
    assertTrue(#resilient.clearedEffects >= 8,
        "Questing Beast Resilient should clear all tracked recoverable effects")
    assertTrue(not resilientBeast.conditions.rooted and not resilientBeast.conditions.prone and
        not resilientBeast.conditions.blind and not resilientBeast.conditions.silenced and
        not resilientBeast.conditions.exhausted and not resilientBeast.conditions.burning and
        not resilientBeast.conditions.disarmed and not resilientBeast.conditions.webbed and
        not resilientBeast.conditions.stunned,
        "Questing Beast Resilient should clear the condition flags")
    assertTrue(resilientBeast.webbedLimbs == nil and not resilientBeast.silenced and not resilientBeast.exhausted,
        "Questing Beast Resilient should clear mirrored condition metadata")

    local evasiveBeast = entity_factory.createEntity("questing_beast")
    local blockedEvasive = questResolver:resolve({
        actor = evasiveBeast,
        type = action_resolver.ACTION_TYPES.QUESTING_BEAST_EVASIVE,
    })
    assertTrue(not blockedEvasive.success, "Questing Beast Evasive should require a greater doom")
    assertTrue(hasValue(blockedEvasive.effects, "questing_beast_evasive_requires_greater_doom"),
        "blocked Questing Beast Evasive should report the missing greater doom")

    local evasive = questResolver:resolve({
        actor = evasiveBeast,
        type = action_resolver.ACTION_TYPES.QUESTING_BEAST_EVASIVE,
        greaterDoom = evasiveBeast.greaterDooms[1],
        greaterDoomCard = { name = "The Chariot", value = 7 },
    })
    assertTrue(evasive.success, "Questing Beast Evasive should prepare a greater-doom Dodge")
    assertTrue(evasiveBeast.pendingDefense and evasiveBeast.pendingDefense.type == "dodge",
        "Questing Beast Evasive should store a Dodge defense")
    assertEqual(evasiveBeast.pendingDefense.value, 7,
        "Questing Beast Evasive should use the greater doom card value as the Dodge value")
    assertTrue(evasiveBeast.pendingDefense.questingBeastEvasive,
        "Questing Beast Evasive should mark the pending defense as greater-doom Evasive")

    local nipBeast = entity_factory.createEntity("questing_beast")
    local nipPrepare = questResolver:resolve({
        actor = nipBeast,
        card = { name = "Ten of Cups", value = 10, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.RIPOSTE,
        lesserDoom = nipBeast.lesserDooms[1],
    })
    assertTrue(nipPrepare.success, "Questing Beast should prepare a Nip Riposte")
    assertTrue(nipBeast.pendingDefense and nipBeast.pendingDefense.lesserDoom == nipBeast.lesserDooms[1],
        "Questing Beast Nip should be stored on the pending Riposte defense")

    local nipAttacker = base_entity.createEntity({
        id = "pc_questing_beast_nip_attacker",
        name = "Questing Beast Nip Attacker",
        isPC = true,
        swords = 0,
    })
    nipAttacker.inventory = inventory.createInventory()
    local triggerNip = questResolver:resolve({
        actor = nipAttacker,
        target = nipBeast,
        card = { name = "Two of Swords", value = 2, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 8,
    })
    assertTrue(triggerNip.riposteResult and triggerNip.riposteResult.success,
        "Questing Beast Nip should resolve through the prepared Riposte")
    assertEqual(triggerNip.riposteResult.damageDealt, 2,
        "Questing Beast Nip should make a successful Riposte deal 2 Wounds")
    assertTrue(hasValue(triggerNip.riposteResult.effects, "questing_beast_nip"),
        "Questing Beast Nip should report its Riposte damage rider")
    assertTrue(nipAttacker.conditions.staggered and nipAttacker.conditions.injured,
        "Questing Beast Nip should apply two Wounds to the attacker")

    local trampler = entity_factory.createEntity("questing_beast")
    trampler.id = "npc_questing_beast_trample"
    trampler.zone = "trail"
    local firstTarget = base_entity.createEntity({
        id = "pc_questing_beast_trample_first",
        name = "First Trample Target",
        isPC = true,
    })
    firstTarget.zone = "trail"
    local secondTarget = base_entity.createEntity({
        id = "pc_questing_beast_trample_second",
        name = "Second Trample Target",
        isPC = true,
    })
    secondTarget.zone = "trail"
    local trample = questResolver:resolve({
        actor = trampler,
        target = firstTarget,
        secondTarget = secondTarget,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        lesserDoom = trampler.lesserDooms[2],
        targetInitiative = 20,
        secondTargetInitiative = 5,
    })
    assertTrue(not trample.success, "Questing Beast Trample starts from an unsuccessful Attack")
    assertTrue(trample.trampleResult and trample.trampleResult.success,
        "Questing Beast Trample should attack a second same-zone target after the miss")
    assertTrue(hasValue(trample.effects, "questing_beast_trample"),
        "Questing Beast Trample should report the follow-up attack")
    assertTrue(not firstTarget.conditions.staggered and secondTarget.conditions.staggered,
        "Questing Beast Trample should wound the second target, not the missed first target")

    local farTarget = base_entity.createEntity({
        id = "pc_questing_beast_trample_far",
        name = "Far Trample Target",
        isPC = true,
    })
    farTarget.zone = "elsewhere"
    local blockedTrample = questResolver:resolve({
        actor = trampler,
        target = firstTarget,
        secondTarget = farTarget,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        lesserDoom = trampler.lesserDooms[2],
        targetInitiative = 20,
        secondTargetInitiative = 5,
    })
    assertTrue(not blockedTrample.trampleResult,
        "Questing Beast Trample should not attack a second target in another zone")
    assertTrue(hasValue(blockedTrample.effects, "questing_beast_trample_target_not_same_zone"),
        "Questing Beast Trample should report a second target in the wrong zone")
end

function checkBeastTemplateRuntime()
    local bus = events.createEventBus()
    local zones = zone_system.createZoneRegistry({ eventBus = bus })
    local zoneList = buildLinearZones()
    zones:setRoomZones(zoneList)
    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
        zoneSystem = zones,
    })

    local beast = base_entity.createEntity({
        id = "npc_beast_template",
        name = "Template Beast",
        isPC = false,
        swords = 4,
    })
    beast.tags = { "beast" }
    beast.beast = {
        fleetMoveZones = 2,
        freeMoveOnTurn = true,
    }
    beast.zone = "A"
    zones:placeEntity(beast.id, beast.zone)
    beast.lesserDooms = {
        {
            id = "bite",
            name = "Bite",
            effect = {
                type = "attack_plus_condition_choice",
                choices = { "disarmed", "tripped" },
                chooser = "gm",
            },
        },
        {
            id = "claw",
            name = "Claw",
            effect = {
                type = "attack_double_initiative_bonus",
                wounds = 2,
            },
        },
        {
            id = "trample",
            name = "Trample",
            effect = {
                type = "second_attack_after_miss",
                targetScope = "same_zone",
            },
        },
    }

    local blockedFleet = resolver:resolve({
        actor = beast,
        type = action_resolver.ACTION_TYPES.BEAST_FLEET_MOVE,
        destinationZone = "C",
        challengeController = { zones = zoneList },
    })
    assertTrue(not blockedFleet.success, "Beast Fleet should only be available on the beast's turn")
    assertTrue(hasValue(blockedFleet.effects, "beast_fleet_requires_turn"),
        "blocked Beast Fleet should report the turn gate")

    local fleet = resolver:resolve({
        actor = beast,
        type = action_resolver.ACTION_TYPES.BEAST_FLEET_MOVE,
        destinationZone = "C",
        onTurn = true,
        challengeController = { zones = zoneList },
    })
    assertTrue(fleet.success and fleet.cardless and fleet.countsTowardTurnCard == false,
        "Beast Fleet should move without spending the one-card turn limit")
    assertEqual(beast.zone, "C", "Beast Fleet should use the beast's authored move distance")
    assertTrue(hasValue(fleet.effects, "beast_fleet") and hasValue(fleet.effects, "free_move_on_turn"),
        "Beast Fleet should report the generic template rider")

    local biteTarget = base_entity.createEntity({
        id = "pc_beast_bite_target",
        name = "Beast Bite Target",
        isPC = true,
    })
    biteTarget.zone = beast.zone
    biteTarget.inventory = inventory.createInventory()
    local shield = inventory.createItemFromTemplate("shield_light")
    biteTarget.inventory:addItem(shield, inventory.LOCATIONS.HANDS)
    local bite = resolver:resolve({
        actor = beast,
        target = biteTarget,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        lesserDoom = beast.lesserDooms[1],
        lesserDoomChoice = "disarmed",
        disarmItemId = shield.id,
        targetInitiative = 6,
    })
    assertTrue(bite.success, "Beast Bite should ride on a successful Attack")
    assertTrue(hasValue(bite.effects, "beast_bite") and hasValue(bite.effects, "beast_bite_disarm"),
        "Beast Bite should report the generic Disarm rider")
    assertTrue(bite.droppedItem == shield and biteTarget.conditions.disarmed,
        "Beast Bite should Disarm the GM's chosen item")

    local clawTarget = base_entity.createEntity({
        id = "pc_beast_claw_target",
        name = "Beast Claw Target",
        isPC = true,
    })
    clawTarget.zone = beast.zone
    clawTarget.inventory = inventory.createInventory()
    local claw = resolver:resolve({
        actor = beast,
        target = clawTarget,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        lesserDoom = beast.lesserDooms[2],
        targetInitiative = 5,
    })
    assertTrue(claw.success, "Beast Claw should hit before checking the double-Initiative rider")
    assertEqual(claw.damageDealt, 2, "Beast Claw should deal 2 Wounds when Attack doubles Initiative")
    assertTrue(hasValue(claw.effects, "beast_claw_double_initiative"),
        "Beast Claw should report the generic double-Initiative rider")

    local firstTarget = base_entity.createEntity({
        id = "pc_beast_trample_first",
        name = "First Beast Trample Target",
        isPC = true,
    })
    firstTarget.zone = "C"
    local secondTarget = base_entity.createEntity({
        id = "pc_beast_trample_second",
        name = "Second Beast Trample Target",
        isPC = true,
    })
    secondTarget.zone = "C"
    local trample = resolver:resolve({
        actor = beast,
        target = firstTarget,
        secondTarget = secondTarget,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        lesserDoom = beast.lesserDooms[3],
        targetInitiative = 20,
        secondTargetInitiative = 5,
    })
    assertTrue(not trample.success, "Beast Trample starts from an unsuccessful Attack")
    assertTrue(trample.trampleResult and trample.trampleResult.success,
        "Beast Trample should attack a second same-zone target after the miss")
    assertTrue(hasValue(trample.effects, "second_attack_after_miss_trample") and
        hasValue(trample.effects, "second_attack_after_miss"),
        "Beast Trample should report the data-driven follow-up attack")
    assertTrue(not firstTarget.conditions.staggered and secondTarget.conditions.staggered,
        "Beast Trample should wound the second target, not the missed first target")
end

function checkSorcerousTemplateRuntime()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local tracker = base_entity.createEntity({
        id = "npc_sorcerous_smeller",
        name = "Sorcerous Smeller",
        isPC = false,
    })
    tracker.tags = { "sorcerous" }
    tracker.sorcerous = {
        smellMagic = true,
    }
    local sorcerer = base_entity.createEntity({
        id = "pc_sorcerous_template_sorcerer",
        name = "Sorcerous Template Sorcerer",
        isPC = true,
        talents = {
            magic_of_the_wastes = { mastered = true },
        },
    })
    local shrouded = base_entity.createEntity({
        id = "pc_sorcerous_template_shrouded",
        name = "Sorcerous Template Shrouded",
        isPC = true,
    })
    shrouded.conditions.shrouded = true
    local mundane = base_entity.createEntity({
        id = "pc_sorcerous_template_mundane",
        name = "Sorcerous Template Mundane",
        isPC = true,
    })
    local smelled = resolver:getSorcerousSmelledMagic(tracker, { sorcerer, shrouded, mundane })
    assertEqual(#smelled, 2,
        "Sorcerous Smell Magic should identify sorcerers or magical effects by scent")
    assertTrue(smelled[1].subject == sorcerer and smelled[1].sorcerer and smelled[1].scent,
        "Sorcerous Smell Magic should distinguish sorcerers")
    assertTrue(smelled[2].subject == shrouded and smelled[2].magicalEffect,
        "Sorcerous Smell Magic should distinguish magical effects")

    local notSorcerous = base_entity.createEntity({
        id = "npc_not_sorcerous",
        name = "Not Sorcerous",
        isPC = false,
    })
    assertEqual(#resolver:getSorcerousSmelledMagic(notSorcerous, { sorcerer }), 0,
        "non-sorcerous creatures should not use Sorcerous Smell Magic")

    local strange = base_entity.createEntity({
        id = "npc_sorcerous_strange_body",
        name = "Sorcerous Strange Body",
        isPC = false,
        health = 3,
    })
    strange.tags = { "sorcerous" }
    strange.sorcerous = {
        strangeBody = {
            immuneTo = { "weapons", "blunt_force_trauma" },
            vulnerableTo = { "fire" },
        },
    }

    local hammer = inventory.createItem({
        name = "Hammer",
        weaponType = "hammer",
    })
    local hammerEffects = {}
    local hammerBlocked = resolver:applyDamage(strange, 1, hammerEffects, hammer, nil, nil, {
        source = "attack",
    })
    assertTrue(hammerBlocked and hammerBlocked.immune and
        hammerBlocked.reason == "sorcerous_strange_body",
        "Sorcerous Strange Body should ignore authored immune harm types")
    assertEqual(strange.npcHealth, 3,
        "Sorcerous Strange Body immunity should prevent Wounds")
    assertTrue(hasValue(hammerEffects, "sorcerous_strange_body_immune"),
        "Sorcerous Strange Body immunity should report its template effect")

    local fireEffects = { "fire" }
    resolver:applyDamage(strange, 1, fireEffects, nil, nil, nil, {
        source = "hazard",
        damageElement = "fire",
    })
    assertEqual(strange.npcHealth, 1,
        "Sorcerous Strange Body vulnerability should turn one matching Wound into two")
    assertTrue(hasValue(fireEffects, "sorcerous_strange_body_vulnerable") and
        hasValue(fireEffects, "strange_body_damage_deals_two_wounds"),
        "Sorcerous Strange Body vulnerability should report doubled damage")
end

function checkEliteTemplateRuntime()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local elite = base_entity.createEntity({
        id = "npc_elite_template",
        name = "Template Elite",
        isPC = false,
        health = 3,
    })
    elite.rank = "elite"
    elite.tags = { "elite" }
    elite.greaterDooms = {
        {
            id = "intangible",
            name = "Intangible",
            effect = {
                type = "toggle_intangible",
                countsTowardTurnCard = false,
            },
        },
        {
            id = "regenerate",
            name = "Regenerate",
            effect = {
                type = "heal_self",
                wounds = 1,
                countsTowardTurnCard = false,
            },
        },
        {
            id = "command",
            name = "Command",
            effect = {
                type = "elite_command",
            },
        },
        {
            id = "potence",
            name = "Potence",
            effect = {
                type = "potence",
                effect = "stun",
            },
        },
        {
            id = "shapeshifter",
            name = "Shapeshifter",
            effect = {
                type = "shapeshifter",
                defaultShape = "bat",
                abilities = { "flying", "swimming" },
            },
        },
    }

    local blockedIntangible = resolver:resolve({
        actor = elite,
        type = action_resolver.ACTION_TYPES.ELITE_INTANGIBLE,
    })
    assertTrue(not blockedIntangible.success, "Elite Intangible should require a greater doom")
    assertTrue(hasValue(blockedIntangible.effects, "elite_intangible_requires_greater_doom"),
        "blocked Elite Intangible should report missing greater doom")

    local intangible = resolver:resolve({
        actor = elite,
        type = action_resolver.ACTION_TYPES.ELITE_INTANGIBLE,
        greaterDoom = elite.greaterDooms[1],
        becomeIntangible = true,
    })
    assertTrue(intangible.success and elite.intangible and elite.conditions.intangible,
        "Elite Intangible should make the elite intangible")
    assertTrue(intangible.cardless and intangible.countsTowardTurnCard == false,
        "Elite Intangible should not spend the one-card turn limit")

    local sword = inventory.createItem({
        name = "Sword",
        weaponType = "sword",
    })
    local physicalEffects = {}
    local physicalBlocked = resolver:applyDamage(elite, 1, physicalEffects, sword, nil, nil, {
        source = "attack",
    })
    assertTrue(physicalBlocked and physicalBlocked.immune and physicalBlocked.reason == "elite_intangible",
        "intangible elites should ignore ordinary physical objects")
    assertEqual(elite.npcHealth, 3, "Elite Intangible should prevent physical Wounds")
    assertTrue(hasValue(physicalEffects, "elite_intangible_immune"),
        "Elite Intangible immunity should report the physical pass-through")

    resolver:applyDamage(elite, 1, { "magic" }, nil, nil, nil, {
        source = "spell",
        spell = true,
    })
    assertEqual(elite.npcHealth, 2, "Elite Intangible should not block magic damage")

    local blockedRegenerate = resolver:resolve({
        actor = elite,
        type = action_resolver.ACTION_TYPES.ELITE_REGENERATE,
    })
    assertTrue(not blockedRegenerate.success, "Elite Regenerate should require a greater doom")
    assertTrue(hasValue(blockedRegenerate.effects, "elite_regenerate_requires_greater_doom"),
        "blocked Elite Regenerate should report missing greater doom")

    local regenerate = resolver:resolve({
        actor = elite,
        type = action_resolver.ACTION_TYPES.ELITE_REGENERATE,
        greaterDoom = elite.greaterDooms[2],
    })
    assertTrue(regenerate.success and regenerate.cardless and regenerate.countsTowardTurnCard == false,
        "Elite Regenerate should heal cardlessly through a greater doom")
    assertEqual(regenerate.healed, 1, "Elite Regenerate should Heal 1 Wound")
    assertEqual(elite.npcHealth, 3, "Elite Regenerate should restore one Health")
    assertTrue(hasValue(regenerate.effects, "elite_regenerate") and hasValue(regenerate.effects, "healed"),
        "Elite Regenerate should report its template effect")

    local tangible = resolver:resolve({
        actor = elite,
        type = action_resolver.ACTION_TYPES.ELITE_INTANGIBLE,
        greaterDoom = elite.greaterDooms[1],
        becomeTangible = true,
    })
    assertTrue(tangible.success and not elite.conditions.intangible and elite.tangible,
        "Elite Intangible should also toggle the elite back to tangible")

    local commanded = base_entity.createEntity({
        id = "pc_elite_commanded",
        name = "Elite Commanded Target",
        isPC = true,
    })
    commanded.zone = "A"
    local commandedVictim = base_entity.createEntity({
        id = "npc_elite_commanded_victim",
        name = "Elite Commanded Victim",
        isPC = false,
        health = 2,
    })
    commandedVictim.zone = "A"
    local command = resolver:resolve({
        actor = elite,
        target = commanded,
        card = { name = "Nine of Swords", value = 9, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        greaterDoom = elite.greaterDooms[3],
        inChallenge = true,
        targetInitiative = 1,
        allEntities = { elite, commanded, commandedVictim },
        controlledAction = {
            type = action_resolver.ACTION_TYPES.MELEE,
            target = commandedVictim,
            targetInitiative = 1,
        },
    })
    assertTrue(command.success and command.eliteCommand,
        "Elite Command should replace Attack damage with control")
    assertEqual(command.controlledActionValue, 9,
        "Elite Command should use the lesser doom Attack value for the commanded action")
    assertTrue(command.controlledActionResult and command.controlledActionResult.success,
        "Elite Command should immediately resolve the commanded action")
    assertEqual(commandedVictim.npcHealth, 1,
        "Elite Command's immediate action should use the commanded target as actor")
    assertTrue(hasValue(command.effects, "elite_command_released"),
        "Elite Command should release one-shot control after the immediate action")

    local potenceTarget = base_entity.createEntity({
        id = "pc_elite_potence_target",
        name = "Elite Potence Target",
        isPC = true,
    })
    potenceTarget.zone = "A"
    local otherPotenceTarget = base_entity.createEntity({
        id = "pc_elite_potence_other",
        name = "Other Elite Potence Target",
        isPC = true,
    })
    otherPotenceTarget.zone = "A"
    local outsidePotence = base_entity.createEntity({
        id = "pc_elite_potence_outside",
        name = "Outside Elite Potence",
        isPC = true,
    })
    outsidePotence.zone = "B"
    elite.zone = "A"
    local potence = resolver:resolve({
        actor = elite,
        type = action_resolver.ACTION_TYPES.ELITE_POTENCE,
        greaterDoom = elite.greaterDooms[4],
        allEntities = { elite, potenceTarget, otherPotenceTarget, outsidePotence },
    })
    assertTrue(potence.success and #potence.affectedTargets == 2,
        "Elite Potence should affect all adventurers in the elite's zone")
    assertTrue(potenceTarget.conditions.stunned and otherPotenceTarget.conditions.stunned and
        not outsidePotence.conditions.stunned,
        "Elite Potence should apply its specific effect only in-zone")

    local shape = resolver:resolve({
        actor = elite,
        type = action_resolver.ACTION_TYPES.ELITE_SHAPESHIFTER,
        greaterDoom = elite.greaterDooms[5],
    })
    assertTrue(shape.success and elite.eliteShape and elite.eliteShape.shape == "bat",
        "Elite Shapeshifter should record the new shape")
    assertTrue(elite.flying and elite.conditions.flying and elite.swimming,
        "Elite Shapeshifter should grant shape abilities")

    local invulnerableElite = base_entity.createEntity({
        id = "npc_elite_invulnerable",
        name = "Invulnerable Elite",
        isPC = false,
        health = 2,
    })
    invulnerableElite.rank = "elite"
    invulnerableElite.elite = {
        invulnerable = {
            except = { "silver_weapons" },
        },
    }
    local ordinarySword = inventory.createItem({
        name = "Ordinary Sword",
        weaponType = "sword",
    })
    local silverSword = inventory.createItem({
        name = "Silver Sword",
        weaponType = "sword",
        material = "silver",
    })
    local invulnerableEffects = {}
    local invulnerableBlocked = resolver:applyDamage(invulnerableElite, 1, invulnerableEffects,
        ordinarySword, nil, nil, { source = "attack" })
    assertTrue(invulnerableBlocked and invulnerableBlocked.reason == "elite_invulnerable",
        "Elite Invulnerable should ignore damage outside its exception")
    assertEqual(invulnerableElite.npcHealth, 2,
        "Elite Invulnerable should preserve Health against ordinary damage")
    resolver:applyDamage(invulnerableElite, 1, { "silver_weapon" }, silverSword, nil, nil, {
        source = "attack",
    })
    assertEqual(invulnerableElite.npcHealth, 1,
        "Elite Invulnerable should allow damage from its specific source")

    local thresholdElite = base_entity.createEntity({
        id = "npc_elite_threshold",
        name = "Threshold Elite",
        isPC = false,
        health = 3,
    })
    thresholdElite.rank = "elite"
    thresholdElite.elite = {
        threshold = {
            woundsInSingleTurn = 2,
        },
    }
    local thresholdEffects = {}
    local thresholdIgnored = resolver:applyDamage(thresholdElite, 1, thresholdEffects, ordinarySword, nil, nil, {
        source = "attack",
    })
    assertTrue(thresholdIgnored and thresholdIgnored.reason == "elite_threshold",
        "Elite Threshold should ignore damage below its one-turn threshold")
    assertEqual(thresholdElite.npcHealth, 3,
        "Elite Threshold should preserve Health until broken")
    resolver:applyDamage(thresholdElite, 2, {}, ordinarySword, nil, nil, {
        source = "attack",
    })
    assertTrue(thresholdElite.eliteThresholdBroken,
        "Elite Threshold should break when enough Wounds are dealt in one turn")
    assertEqual(thresholdElite.npcHealth, 1,
        "Elite Threshold should take the threshold-breaking damage normally")

    local retributiveElite = base_entity.createEntity({
        id = "npc_elite_retributive",
        name = "Retributive Elite",
        isPC = false,
        health = 3,
    })
    retributiveElite.rank = "elite"
    retributiveElite.elite = {
        retributive = true,
    }
    retributiveElite.zone = "A"
    local retributiveTarget = base_entity.createEntity({
        id = "pc_elite_retributive_target",
        name = "Retributive Target",
        isPC = true,
    })
    retributiveTarget.zone = "A"
    resolver:formEngagement(retributiveElite, retributiveTarget)
    local retributive = resolver:applyEliteRetributiveStartTurn(retributiveTarget,
        { retributiveElite, retributiveTarget }, { round = 1 })
    assertTrue(#retributive.retributiveHits == 1 and hasValue(retributive.effects, "elite_retributive"),
        "Elite Retributive should wound engaged creatures at the start of their turn")
    assertTrue(retributiveTarget.conditions.staggered,
        "Elite Retributive should apply 1 Wound to the active engaged creature")
end

function checkDungeonLordTemplateRuntime()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local lord = base_entity.createEntity({
        id = "npc_generic_dungeon_lord",
        name = "Generic Dungeon Lord",
        isPC = false,
        health = 4,
        defense = 2,
        swords = 6,
        pentacles = 3,
        cups = 3,
        wands = 3,
    })
    lord.rank = "dungeon_lord"
    lord.tags = { "dungeon_lord" }
    lord.dungeonLord = {
        corePool = "heart",
        defeatMode = "core_pool",
        pools = {
            heart = {
                name = "Heart",
                health = 4,
                defense = 2,
                core = true,
                lesserDooms = { "baleful_gaze" },
            },
            left_arm = {
                name = "Left Arm",
                health = 2,
                defense = 0,
                greaterDooms = { "smash" },
            },
            crown = {
                name = "Crown",
                health = 1,
                defense = 1,
                greaterDooms = { "sorcery" },
            },
        },
    }

    local pools = resolver:ensureDungeonLordPoolState(lord)
    assertTrue(pools and pools.heart and pools.left_arm and pools.crown,
        "Dungeon Lord template should initialize authored HD pools")
    assertEqual(pools.heart.defense, 2,
        "Dungeon Lord core pool should preserve authored Defense")
    assertTrue(resolver:dungeonLordPoolCanUseDoom(lord, { id = "smash" }),
        "undefeated Dungeon Lord pools should make their dooms available")

    local sword = inventory.createItem({
        name = "Sword",
        weaponType = "sword",
    })
    local armDamage = resolver:applyDamage(lord, 2, {}, sword, nil, nil, {
        action = {
            actor = base_entity.createEntity({ id = "pc_lord_arm_attacker", isPC = true }),
            target = lord,
            targetPool = "left_arm",
        },
    })
    assertEqual(armDamage.dungeonLordPool, "left_arm",
        "Dungeon Lord damage should target the named pool")
    assertTrue(lord.dungeonLordPoolState.left_arm.defeated,
        "Dungeon Lord pool damage should defeat depleted pools")
    assertTrue(not lord.conditions.deaths_door,
        "defeating a non-core Dungeon Lord pool should not defeat a core-pool lord")
    assertTrue(not resolver:dungeonLordPoolCanUseDoom(lord, { id = "smash" }),
        "defeated Dungeon Lord pools should disable their associated dooms")

    local blockedDoom = resolver:resolve({
        actor = lord,
        target = base_entity.createEntity({ id = "pc_lord_doom_target", isPC = true }),
        type = action_resolver.ACTION_TYPES.MELEE,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        greaterDoom = { id = "smash", name = "Smash", poolId = "left_arm" },
        targetInitiative = 1,
    })
    assertTrue(not blockedDoom.success,
        "Dungeon Lord defeated pools should block their associated doom actions")
    assertTrue(hasValue(blockedDoom.effects, "dungeon_lord_pool_doom_blocked"),
        "blocked Dungeon Lord doom should report the defeated pool gate")

    local crownDamage = resolver:applyDamage(lord, 1, { "piercing" }, sword, nil, nil, {
        action = {
            target = lord,
            targetPool = "crown",
        },
    })
    assertEqual(crownDamage.dungeonLordPool, "crown",
        "Dungeon Lord pool damage should support separate non-body pools")
    assertEqual(lord.dungeonLordPoolState.crown.health, 0,
        "piercing damage should bypass pool Defense")
    assertTrue(lord.dungeonLordPoolState.crown.defeated,
        "Dungeon Lord separate pools should mark defeated independently")

    local heartDamage = resolver:applyDamage(lord, 6, {}, sword, nil, nil, {
        action = {
            target = lord,
            targetPool = "heart",
        },
    })
    assertEqual(heartDamage.dungeonLordPool, "heart",
        "Dungeon Lord core pool damage should target the authored core")
    assertTrue(lord.dungeonLordDefeated and lord.conditions.deaths_door,
        "defeating the core pool should defeat a core-pool Dungeon Lord")
    assertEqual(lord.npcHealth, 0,
        "Dungeon Lord core pool should mirror Health for presentation")

    local allPoolsLord = base_entity.createEntity({
        id = "npc_all_pool_lord",
        name = "All Pool Lord",
        isPC = false,
    })
    allPoolsLord.rank = "dungeon_lord"
    allPoolsLord.dungeonLord = {
        defeatMode = "all_pools",
        pools = {
            head = { health = 1, defense = 0 },
            body = { health = 1, defense = 0 },
        },
    }
    resolver:applyDamage(allPoolsLord, 1, {}, sword, nil, nil, {
        action = {
            target = allPoolsLord,
            targetPool = "head",
        },
    })
    assertTrue(not allPoolsLord.conditions.deaths_door,
        "all-pool Dungeon Lords should survive until every pool is defeated")
    resolver:applyDamage(allPoolsLord, 1, {}, sword, nil, nil, {
        action = {
            target = allPoolsLord,
            targetPool = "body",
        },
    })
    assertTrue(allPoolsLord.dungeonLordDefeated and allPoolsLord.conditions.deaths_door,
        "all-pool Dungeon Lords should fall once every pool is defeated")
end

function checkStrategistTemplateRuntime()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local tactician = entity_factory.createEntity("questing_beast")
    tactician.id = "npc_strategist_tactics"
    local tacticsTarget = base_entity.createEntity({
        id = "pc_strategist_tactics_target",
        name = "Strategist Tactics Target",
        isPC = true,
    })
    local tactics = resolver:resolve({
        actor = tactician,
        target = tacticsTarget,
        type = action_resolver.ACTION_TYPES.MELEE,
        card = { name = "Seven of Swords", value = 7, suit = constants.SUITS.SWORDS },
        greaterDoom = tactician.greaterDooms[4],
        targetInitiative = 20,
    })
    assertTrue(tactics.quickInterrupt,
        "Strategist Tactics should mark a standard Challenge Action as an interrupt")
    assertTrue(hasValue(tactics.effects, "strategist_tactics") and
        hasValue(tactics.effects, "standard_action_as_interrupt"),
        "Strategist Tactics should report the generic interrupt conversion")

    local retreatBus = events.createEventBus()
    local zones = zone_system.createZoneRegistry({ eventBus = retreatBus })
    local retreatResolver = action_resolver.createActionResolver({
        eventBus = retreatBus,
        zoneSystem = zones,
    })
    local strategist = base_entity.createEntity({
        id = "npc_strategist_retreat",
        name = "Strategist Retreat",
        isPC = false,
    })
    strategist.rank = "strategist"
    strategist.tags = { "strategist" }
    strategist.greaterDooms = {
        {
            id = "cautious_retreat",
            name = "Cautious Retreat",
            effect = {
                type = "disengage_one",
                countsTowardTurnCard = false,
            },
        },
    }
    local adventurer = base_entity.createEntity({
        id = "pc_strategist_retreat",
        name = "Strategist Retreat Target",
        isPC = true,
    })
    retreatResolver:formEngagement(strategist, adventurer)

    local blockedRetreat = retreatResolver:resolve({
        actor = strategist,
        target = adventurer,
        type = action_resolver.ACTION_TYPES.STRATEGIST_CAUTIOUS_RETREAT,
    })
    assertTrue(not blockedRetreat.success, "Strategist Cautious Retreat should require a greater doom")
    assertTrue(hasValue(blockedRetreat.effects, "strategist_cautious_retreat_requires_greater_doom"),
        "blocked Strategist Cautious Retreat should report the missing greater doom")
    assertTrue(zones:areEngaged(strategist.id, adventurer.id),
        "blocked Strategist Cautious Retreat should leave the engagement intact")

    local retreat = retreatResolver:resolve({
        actor = strategist,
        target = adventurer,
        type = action_resolver.ACTION_TYPES.STRATEGIST_CAUTIOUS_RETREAT,
        greaterDoom = strategist.greaterDooms[1],
    })
    assertTrue(retreat.success, "Strategist Cautious Retreat should disengage from one adventurer")
    assertTrue(retreat.cardless and retreat.countsTowardTurnCard == false,
        "Strategist Cautious Retreat should not spend the one-card turn limit")
    assertTrue(hasValue(retreat.effects, "strategist_cautious_retreat") and
        hasValue(retreat.effects, "disengaged"),
        "Strategist Cautious Retreat should report the disengagement")
    assertTrue(not zones:areEngaged(strategist.id, adventurer.id),
        "Strategist Cautious Retreat should break the selected engagement")

    local sorcerer = base_entity.createEntity({
        id = "npc_strategist_sorcery",
        name = "Strategist Sorcerer",
        isPC = false,
    })
    sorcerer.rank = "strategist"
    sorcerer.tags = { "strategist" }
    sorcerer.knownSpells = {
        illusion = true,
    }
    sorcerer.strategist = {
        sorcery = {
            spellIds = { "illusion" },
            componentTemplateIds = { "component_illusion" },
            greaterDoomSubstitutesResolve = true,
            extraGreaterDoomAddsResolve = 1,
        },
    }
    sorcerer.resolve = 0
    sorcerer.inventory = inventory.createInventory()
    sorcerer.inventory:addItem(inventory.createItemFromTemplate("component_illusion"), inventory.LOCATIONS.HANDS)
    sorcerer.greaterDooms = {
        {
            id = "sorcery",
            name = "Sorcery",
            effect = {
                type = "spellcasting_resolve_substitute",
                spellIds = { "illusion" },
            },
        },
    }

    local missingDoom = resolver:resolve({
        actor = sorcerer,
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        card = { name = "Eight of Wands", value = 8, suit = constants.SUITS.WANDS },
        spellId = "illusion",
        image = "A jeweled doorway floating above the floor",
        zoneId = "vault",
    })
    assertTrue(not missingDoom.success, "Strategist Sorcery should require a discarded greater doom")
    assertTrue(hasValue(missingDoom.effects, "strategist_sorcery_doom_missing"),
        "blocked Strategist Sorcery should report the missing greater doom payment")

    local sorcery = resolver:resolve({
        actor = sorcerer,
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        card = { name = "Eight of Wands", value = 8, suit = constants.SUITS.WANDS },
        spellId = "illusion",
        greaterDoom = sorcerer.greaterDooms[1],
        image = "A ribald puppet show",
        zoneId = "vault",
    })
    assertTrue(sorcery.success, "Strategist Sorcery should cast an authored spell with a greater doom")
    assertTrue(hasValue(sorcery.effects, "strategist_sorcery") and
        hasValue(sorcery.effects, "greater_doom_instead_of_resolve"),
        "Strategist Sorcery should report greater-doom spell payment")
    assertEqual(sorcery.resolveSpent, 0, "Strategist Sorcery should spend no ordinary Resolve")
    assertEqual(sorcery.spellResolveValue, 1,
        "Strategist Sorcery should count one greater doom as one Resolve")
    assertEqual(sorcerer.resolve, 0, "Strategist Sorcery should not decrement the caster's Resolve")
    assertEqual(sorcerer.committedResolve or 0, 0,
        "Strategist Sorcery should not commit Resolve for ongoing Illusion")
    assertTrue(sorcery.component and sorcery.component.templateId == "component_illusion",
        "Strategist Sorcery should still require and use a held spell component")
    assertTrue(sorcery.visualIllusion and sorcery.visualIllusion.visualOnly,
        "Strategist Sorcery should still apply the Illusion spell effect")
end

local function checkLightSourceVisibility()
    local candleHolder = base_entity.createEntity({
        id = "pc_candle_holder",
        name = "Candle Holder",
        isPC = true,
    })
    candleHolder.inventory = inventory.createInventory()
    local candleBystander = base_entity.createEntity({
        id = "pc_candle_bystander",
        name = "Candle Bystander",
        isPC = true,
    })
    candleBystander.inventory = inventory.createInventory()

    local candle = inventory.createItemFromTemplate("candles")
    candle.properties.isLit = true
    candle.properties.is_lit = true
    candle.properties.extinguished = false
    candleHolder.inventory:addItem(candle, inventory.LOCATIONS.HANDS)

    local candleLights = light_system.createLightSystem({
        eventBus = events.createEventBus(),
        guild = { candleHolder, candleBystander },
    })
    candleLights:init()

    assertEqual(candleLights:getLightLevelForEntity(candleHolder), light_system.LIGHT_LEVELS.BRIGHT,
        "candle carriers should get bright light")
    assertEqual(candleLights:getLightLevelForEntity(candleBystander), light_system.LIGHT_LEVELS.DARK,
        "candles should not provide dim light to nearby guildmates")

    local torchHolder = base_entity.createEntity({
        id = "pc_torch_holder",
        name = "Torch Holder",
        isPC = true,
    })
    torchHolder.inventory = inventory.createInventory()
    local torchBystander = base_entity.createEntity({
        id = "pc_torch_bystander",
        name = "Torch Bystander",
        isPC = true,
    })
    torchBystander.inventory = inventory.createInventory()

    local torch = inventory.createItemFromTemplate("torch")
    torchHolder.inventory:addItem(torch, inventory.LOCATIONS.HANDS)

    local torchLights = light_system.createLightSystem({
        eventBus = events.createEventBus(),
        guild = { torchHolder, torchBystander },
    })
    torchLights:init()

    assertEqual(torchLights:getLightLevelForEntity(torchHolder), light_system.LIGHT_LEVELS.BRIGHT,
        "torch carriers should get bright light")
    assertEqual(torchLights:getLightLevelForEntity(torchBystander), light_system.LIGHT_LEVELS.DIM,
        "torches should provide dim light to nearby guildmates")

    local labRoomData = nil
    for _, roomData in ipairs(tomb_data.data.rooms or {}) do
        if roomData.id == "114_laboratory" then
            labRoomData = roomData
            break
        end
    end
    local labRooms = room_manager.createRoomManager({
        eventBus = events.createEventBus(),
    })
    labRooms:registerRoom(room_manager.createRoomInstance(labRoomData, labRoomData.id))
    local labExplorer = base_entity.createEntity({
        id = "pc_lab_environmental_light",
        name = "Lab Environmental Light",
        isPC = true,
    })
    labExplorer.inventory = inventory.createInventory()
    labExplorer.location = "114_laboratory"
    local labBus = events.createEventBus()
    local darknessDoom = nil
    labBus:on(events.EVENTS.DARKNESS_DOOMED, function(data)
        darknessDoom = data
    end)
    local labLights = light_system.createLightSystem({
        eventBus = labBus,
        guild = { labExplorer },
        roomManager = labRooms,
    })
    labLights:init()
    assertEqual(labLights:getLightLevelForEntity(labExplorer), light_system.LIGHT_LEVELS.DIM,
        "the Tomb laboratory star-child should provide environmental dim light")
    assertEqual(labLights:getLightLevel(), light_system.LIGHT_LEVELS.DIM,
        "environmental light should lift the party out of darkness")
    assertTrue(darknessDoom == nil,
        "environmental light should prevent the out-of-light doom procedure")

    local personalLightHolder = base_entity.createEntity({
        id = "pc_personal_candle_holder",
        name = "Personal Candle Holder",
        isPC = true,
    })
    personalLightHolder.inventory = inventory.createInventory()
    local stillDarkBystander = base_entity.createEntity({
        id = "pc_still_dark_bystander",
        name = "Still Dark Bystander",
        isPC = true,
    })
    stillDarkBystander.inventory = inventory.createInventory()
    local personalLights = light_system.createLightSystem({
        eventBus = events.createEventBus(),
        guild = { personalLightHolder, stillDarkBystander },
    })
    personalLights:init()
    assertTrue(personalLightHolder.conditions.blind_from_darkness and stillDarkBystander.conditions.blind_from_darkness,
        "darkness should mark each dark adventurer Blind")

    local personalCandle = inventory.createItemFromTemplate("candles")
    personalCandle.properties.isLit = true
    personalCandle.properties.is_lit = true
    personalCandle.properties.extinguished = false
    personalLightHolder.inventory:addItem(personalCandle, inventory.LOCATIONS.HANDS)
    personalLights:recalculateLightLevels()

    assertEqual(personalLights:getLightLevelForEntity(personalLightHolder), light_system.LIGHT_LEVELS.BRIGHT,
        "a lit candle should restore bright light for its holder")
    assertEqual(personalLights:getLightLevelForEntity(stillDarkBystander), light_system.LIGHT_LEVELS.DARK,
        "a personal candle should still leave other adventurers dark")
    assertTrue(not personalLightHolder.conditions.blind and not personalLightHolder.conditions.blind_from_darkness,
        "personal light should clear only the holder's darkness Blind even while party light remains dark")
    assertTrue(stillDarkBystander.conditions.blind and stillDarkBystander.conditions.blind_from_darkness,
        "remaining dark adventurers should keep darkness Blind")

    local dimWorker = base_entity.createEntity({
        id = "pc_dim_light_worker",
        name = "Dim Light Worker",
        isPC = true,
    })
    dimWorker.inventory = inventory.createInventory()
    local dimTorchHolder = base_entity.createEntity({
        id = "pc_dim_torch_holder",
        name = "Dim Torch Holder",
        isPC = true,
    })
    dimTorchHolder.inventory = inventory.createInventory()
    local dimTorch = inventory.createItemFromTemplate("torch")
    dimTorchHolder.inventory:addItem(dimTorch, inventory.LOCATIONS.HANDS)
    local dimBus = events.createEventBus()
    local dimTestRequest = nil
    dimBus:on(events.EVENTS.REQUEST_TEST_OF_FATE, function(data)
        dimTestRequest = data
    end)
    local dimLights = light_system.createLightSystem({
        eventBus = dimBus,
        guild = { dimWorker, dimTorchHolder },
    })
    dimLights:init()
    local dimResolver = action_resolver.createActionResolver({
        eventBus = dimBus,
        lightSystem = dimLights,
    })

    local dimLockpick = dimResolver:resolve({
        actor = dimWorker,
        card = { name = "Three of Pentacles", value = 3, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.TEST_FATE,
        context = "picking locks",
        challengeController = {
            isActive = function()
                return true
            end,
        },
    })
    assertTrue(dimLockpick.pendingTestOfFate, "dim-light lockpicking should still request a Test of Fate")
    assertEqual(dimTestRequest.favor, false,
        "complex visually-dependent work in dim light should suffer disfavor")
    assertTrue(hasValue(dimLockpick.effects, "dim_light_test_fate_disfavor"),
        "dim-light Test Fate disfavor should be reported")

    dimTestRequest = nil
    local illuminatedLockpick = dimResolver:resolve({
        actor = dimWorker,
        card = { name = "Four of Pentacles", value = 4, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.TEST_FATE,
        context = "picking locks",
        activeIllumination = true,
        challengeController = {
            isActive = function()
                return true
            end,
        },
    })
    assertTrue(illuminatedLockpick.pendingTestOfFate,
        "actively illuminated dim-light work should still request a Test of Fate")
    assertEqual(dimTestRequest.favor, nil,
        "active illumination should prevent dim-light disfavor")
    assertTrue(not hasValue(illuminatedLockpick.effects, "dim_light_test_fate_disfavor"),
        "actively illuminated work should not report dim-light disfavor")
end

local function checkDroppedLightSourceRules()
    local candleCarrier = base_entity.createEntity({
        id = "pc_drop_candle",
        name = "Candle Dropper",
        isPC = true,
        pentacles = 4,
    })
    candleCarrier.inventory = inventory.createInventory()
    local candle = inventory.createItemFromTemplate("candles")
    candle.properties.isLit = true
    candle.properties.is_lit = true
    candle.properties.extinguished = false
    candleCarrier.inventory:addItem(candle, inventory.LOCATIONS.HANDS)

    local candleBus = events.createEventBus()
    local candleLights = light_system.createLightSystem({
        eventBus = candleBus,
        guild = { candleCarrier },
    })
    candleLights:init()
    candleBus:emit(events.EVENTS.LIGHT_SOURCE_DROPPED, {
        entity = candleCarrier,
        item = candle,
    })
    assertTrue(not candle.properties.isLit, "dropped candles should go out")
    assertTrue(candle.properties.extinguished, "dropped candles should be marked extinguished")
    assertTrue(not candle.destroyed, "dropped candles should be relightable")
    assertTrue(candleLights:lightItem(candle), "dropped candles should be relightable")
    assertTrue(candle.properties.isLit, "relit candles should become active again")

    local lanternCarrier = base_entity.createEntity({
        id = "pc_drop_lantern",
        name = "Lantern Dropper",
        isPC = true,
    })
    lanternCarrier.inventory = inventory.createInventory()
    local lantern = inventory.createItemFromTemplate("lantern")
    lanternCarrier.inventory:addItem(lantern, inventory.LOCATIONS.HANDS)
    local lanternBroken = nil
    local lanternBus = events.createEventBus()
    lanternBus:on(events.EVENTS.LANTERN_BROKEN, function(data)
        lanternBroken = data
    end)
    local lanternLights = light_system.createLightSystem({
        eventBus = lanternBus,
        guild = { lanternCarrier },
    })
    lanternLights:init()
    lanternBus:emit(events.EVENTS.LIGHT_SOURCE_DROPPED, {
        entity = lanternCarrier,
        item = lantern,
    })
    assertTrue(lantern.destroyed and lantern.properties.broken, "dropped lanterns should shatter")
    assertTrue(lanternBroken and lanternBroken.reason == "dropped", "dropped lanterns should emit break reason")
    assertTrue(not lanternCarrier.conditions.covered_in_oil,
        "dropped hand lanterns should not apply the belt-wound oil spill rider")

    local beltLanternCarrier = base_entity.createEntity({
        id = "pc_belt_lantern_wound",
        name = "Belt Lantern Wound",
        isPC = true,
    })
    beltLanternCarrier.inventory = inventory.createInventory()
    local beltLantern = inventory.createItemFromTemplate("lantern")
    beltLanternCarrier.inventory:addItem(beltLantern, inventory.LOCATIONS.BELT)
    local beltLanternBroken = nil
    local beltLanternBus = events.createEventBus()
    beltLanternBus:on(events.EVENTS.LANTERN_BROKEN, function(data)
        beltLanternBroken = data
    end)
    local beltLanternLights = light_system.createLightSystem({
        eventBus = beltLanternBus,
        guild = { beltLanternCarrier },
    })
    beltLanternLights:init()
    beltLanternBus:emit(events.EVENTS.WOUND_TAKEN, {
        entity = beltLanternCarrier,
        result = "injured",
        damageType = "normal",
    })
    assertTrue(beltLantern.destroyed and beltLantern.properties.broken,
        "belt lanterns should shatter when the bearer takes a Wound")
    assertTrue(beltLanternBroken and beltLanternBroken.reason == "wound_taken",
        "belt lantern Wound shatter should report the wound reason")
    assertTrue(beltLanternCarrier.conditions.covered_in_oil and beltLanternCarrier.coveredInOil,
        "belt lantern Wound shatter should cover the bearer in oil")

    local torchCarrier = base_entity.createEntity({
        id = "pc_drop_torch",
        name = "Torch Dropper",
        isPC = true,
    })
    torchCarrier.inventory = inventory.createInventory()
    local quenchedTorch = inventory.createItemFromTemplate("torch")
    local stayingTorch = inventory.createItemFromTemplate("torch")
    torchCarrier.inventory:addItem(quenchedTorch, inventory.LOCATIONS.HANDS)
    torchCarrier.inventory:addItem(stayingTorch, inventory.LOCATIONS.HANDS)
    local torchBus = events.createEventBus()
    local torchLights = light_system.createLightSystem({
        eventBus = torchBus,
        guild = { torchCarrier },
    })
    torchLights:init()
    torchBus:emit(events.EVENTS.LIGHT_SOURCE_DROPPED, {
        entity = torchCarrier,
        item = quenchedTorch,
        torchStaysLit = false,
    })
    assertTrue(quenchedTorch.destroyed and quenchedTorch.properties.extinguished,
        "dropped torches can be extinguished and cannot be relit")
    torchBus:emit(events.EVENTS.LIGHT_SOURCE_DROPPED, {
        entity = torchCarrier,
        item = stayingTorch,
        torchStaysLit = true,
    })
    assertTrue(not stayingTorch.destroyed and stayingTorch.properties.isLit,
        "dropped torches can stay lit")

    local disarmBus = events.createEventBus()
    local disarmLights = light_system.createLightSystem({
        eventBus = disarmBus,
        guild = { candleCarrier },
    })
    disarmLights:init()
    local resolver = action_resolver.createActionResolver({
        eventBus = disarmBus,
    })

    candle.properties.isLit = true
    candle.properties.is_lit = true
    candle.properties.extinguished = false
    if not candleCarrier.inventory:findItem(candle.id) then
        candleCarrier.inventory:addItem(candle, inventory.LOCATIONS.HANDS)
    end

    local failedDisarm = resolver:resolve({
        actor = base_entity.createEntity({ id = "pc_bad_disarm", name = "Bad Disarmer", isPC = true, pentacles = 0 }),
        card = { name = "Pentacles", value = 1, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.DISARM,
        target = candleCarrier,
        targetInitiative = 20,
    })
    assertTrue(not failedDisarm.success, "failed disarm should fail the contest")
    assertTrue(candleCarrier.inventory:findItem(candle.id), "failed disarm should not drop held light sources")
    assertTrue(candle.properties.isLit, "failed disarm should not extinguish held light sources")

    local successfulDisarm = resolver:resolve({
        actor = base_entity.createEntity({ id = "pc_good_disarm", name = "Good Disarmer", isPC = true, pentacles = 4 }),
        card = { name = "Pentacles", value = 8, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.DISARM,
        target = candleCarrier,
        targetInitiative = 5,
    })
    assertTrue(successfulDisarm.success, "successful disarm should beat Initiative")
    assertTrue(successfulDisarm.droppedItem == candle, "successful disarm should drop the held light source")
    assertTrue(not candleCarrier.inventory:findItem(candle.id), "successful disarm should remove the dropped light source")
    assertTrue(not candle.properties.isLit and candle.properties.extinguished,
        "successfully disarmed candles should use dropped-light consequences")

    local torchFighter = base_entity.createEntity({
        id = "pc_torch_weapon",
        name = "Torch Fighter",
        isPC = true,
        swords = 4,
    })
    torchFighter.inventory = inventory.createInventory()
    local weaponTorch = inventory.createItemFromTemplate("torch")
    torchFighter.inventory:addItem(weaponTorch, inventory.LOCATIONS.HANDS)
    local torchTarget = base_entity.createEntity({
        id = "npc_torch_target",
        name = "Torch Target",
        isPC = false,
        health = 2,
        defense = 0,
    })
    local weaponBus = events.createEventBus()
    local weaponLights = light_system.createLightSystem({
        eventBus = weaponBus,
        guild = { torchFighter },
    })
    weaponLights:init()
    local weaponResolver = action_resolver.createActionResolver({
        eventBus = weaponBus,
    })
    local torchAttack = weaponResolver:resolve({
        actor = torchFighter,
        card = { name = "Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        weapon = weaponTorch,
        target = torchTarget,
        targetInitiative = 5,
    })
    assertTrue(torchAttack.success, "torch weapon attack should still resolve")
    assertTrue(weaponTorch.destroyed and weaponTorch.properties.broken,
        "light sources used as weapons should break")
    assertTrue(not weaponTorch.properties.isLit and weaponTorch.properties.extinguished,
        "light sources used as weapons should be extinguished")
    assertTrue(hasValue(torchAttack.effects, "light_source_broken"),
        "light-source weapon break should be reported")
    assertEqual(weaponLights:getLightLevelForEntity(torchFighter), light_system.LIGHT_LEVELS.DARK,
        "broken torch weapon should no longer provide light")

    local hitInCombatDestroyed = nil
    weaponBus:on(events.EVENTS.LIGHT_DESTROYED, function(data)
        hitInCombatDestroyed = data
    end)
    local lightTarget = base_entity.createEntity({
        id = "npc_light_source_target",
        name = "Light Source Target",
        isPC = false,
        health = 2,
        defense = 0,
    })
    lightTarget.inventory = inventory.createInventory()
    local struckLantern = inventory.createItemFromTemplate("lantern")
    lightTarget.inventory:addItem(struckLantern, inventory.LOCATIONS.HANDS)
    local itemStrike = weaponResolver:resolve({
        actor = torchFighter,
        card = { name = "Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        weapon = { name = "Shortsword", weaponType = "sword" },
        target = lightTarget,
        targetItem = struckLantern,
        targetInitiative = 5,
    })
    assertTrue(itemStrike.success, "combat hits against targeted light sources should resolve")
    assertTrue(struckLantern.destroyed and struckLantern.properties.broken,
        "light sources hit in combat should break")
    assertTrue(not struckLantern.properties.isLit and struckLantern.properties.extinguished,
        "light sources hit in combat should be extinguished")
    assertTrue(hasValue(itemStrike.effects, "light_source_hit_in_combat"),
        "light source combat hits should report the hit-in-combat rule")
    assertEqual(itemStrike.damageDealt, 0,
        "targeting the light source should not also wound the bearer")
    assertTrue(not (lightTarget.conditions and lightTarget.conditions.injured),
        "targeting the light source should leave the bearer unwounded")
    assertTrue(hitInCombatDestroyed and hitInCombatDestroyed.reason == "hit_in_combat",
        "light source combat hits should emit the hit-in-combat destruction reason")
end

local function checkOutOfLightDoom()
    local doomSystem = light_system.createLightSystem({
        eventBus = events.createEventBus(),
        guild = {},
    })

    local grueVictim = base_entity.createEntity({ id = "pc_grue", name = "Grue Victim", isPC = true })
    local grue = doomSystem:resolveDarknessDoom(grueVictim, { value = 7 })
    assertEqual(grue.doom, light_system.DARKNESS_DOOMS.GRUE, "I-VII darkness doom should be grue")
    assertTrue(grueVictim.conditions.dead and grueVictim.defeated, "grue darkness doom should defeat the adventurer")

    local monsterCaptive = base_entity.createEntity({ id = "pc_captured", name = "Captured", isPC = true })
    local captured = doomSystem:resolveDarknessDoom(monsterCaptive, { value = 8 })
    assertEqual(captured.doom, light_system.DARKNESS_DOOMS.CAPTURED_BY_MONSTERS,
        "VIII darkness doom should capture the adventurer")
    assertTrue(monsterCaptive.conditions.captured and monsterCaptive.capturedByMonsters,
        "monster capture doom should mark captured")

    local ransomCaptive = base_entity.createEntity({ id = "pc_ransom", name = "Ransom", isPC = true })
    local ransom = doomSystem:resolveDarknessDoom(ransomCaptive, { value = 9 })
    assertEqual(ransom.doom, light_system.DARKNESS_DOOMS.OLU_GANG_RANSOM,
        "IX darkness doom should be Olu Gang ransom")
    assertEqual(ransomCaptive.heldForRansom.costPerFame, 1000, "Olu Gang ransom should use 1000 gold per Fame")

    local lostAdventurer = base_entity.createEntity({ id = "pc_lost", name = "Lost", isPC = true })
    local lost = doomSystem:resolveDarknessDoom(lostAdventurer, { value = 10 })
    assertEqual(lost.doom, light_system.DARKNESS_DOOMS.LOST_IN_UNDERWORLD,
        "X darkness doom should lose the adventurer in the Underworld")
    assertTrue(lostAdventurer.conditions.lost and lostAdventurer.lostInUnderworld,
        "lost darkness doom should mark the adventurer lost")

    local retiree = base_entity.createEntity({ id = "pc_retired", name = "Retired", isPC = true })
    local retired = doomSystem:resolveDarknessDoom(retiree, { value = constants.FACE_VALUES.PAGE })
    assertEqual(retired.doom, light_system.DARKNESS_DOOMS.RETIRED, "Page darkness doom should retire")
    assertTrue(retiree.retired and retiree.controlledByGM, "retired darkness doom should remove PC control")

    local stripped = base_entity.createEntity({ id = "pc_stripped", name = "Stripped", isPC = true })
    stripped.inventory = inventory.createInventory()
    local strippedTorch = inventory.createItemFromTemplate("torch")
    local strippedRope = inventory.createItemFromTemplate("rope")
    stripped.inventory:addItem(strippedTorch, inventory.LOCATIONS.BELT)
    stripped.inventory:addItem(strippedRope, inventory.LOCATIONS.PACK)
    local strippedDoom = doomSystem:resolveDarknessDoom(stripped, { value = constants.FACE_VALUES.KNIGHT })
    assertEqual(strippedDoom.doom, light_system.DARKNESS_DOOMS.LOST_ALL_EQUIPMENT,
        "Knight darkness doom should lose all equipment")
    assertEqual(#strippedDoom.lostItems, 2, "Knight darkness doom should remove all carried equipment")
    assertEqual(#stripped.inventory:getAllItems(), 0, "Knight darkness doom inventory should be empty")

    local scattered = base_entity.createEntity({ id = "pc_scattered", name = "Scattered", isPC = true })
    scattered.inventory = inventory.createInventory()
    local keptItem = inventory.createItemFromTemplate("torch")
    local lostItem = inventory.createItemFromTemplate("rope")
    scattered.inventory:addItem(keptItem, inventory.LOCATIONS.BELT)
    scattered.inventory:addItem(lostItem, inventory.LOCATIONS.PACK)
    local queenDoom = doomSystem:resolveDarknessDoom(scattered, { value = constants.FACE_VALUES.QUEEN }, {
        loseItem = {
            [lostItem.id] = true,
        },
    })
    assertEqual(queenDoom.doom, light_system.DARKNESS_DOOMS.RISK_EQUIPMENT_LOSS,
        "Queen darkness doom should risk each item")
    assertEqual(#queenDoom.lostItems, 1, "Queen darkness doom should remove selected lost equipment")
    assertTrue(scattered.inventory:findItem(keptItem.id) ~= nil, "Queen darkness doom should keep unselected gear")
    assertTrue(scattered.inventory:findItem(lostItem.id) == nil, "Queen darkness doom should remove selected gear")

    local raving = base_entity.createEntity({ id = "pc_raving", name = "Raving", isPC = true })
    local kingDoom = doomSystem:resolveDarknessDoom(raving, { value = constants.FACE_VALUES.KING })
    assertEqual(kingDoom.doom, light_system.DARKNESS_DOOMS.RAVING_DARKNESS,
        "King darkness doom should return raving")
    assertTrue(raving.conditions.stressed and raving.ravingAboutDarkness,
        "King darkness doom should mark stressed raving")

    local candleCarrier = base_entity.createEntity({
        id = "pc_extinguished_candle",
        name = "Extinguished Candle",
        isPC = true,
    })
    candleCarrier.inventory = inventory.createInventory()
    local candle = inventory.createItemFromTemplate("candles")
    candle.properties.isLit = false
    candle.properties.is_lit = false
    candle.properties.extinguished = true
    candleCarrier.inventory:addItem(candle, inventory.LOCATIONS.HANDS)
    local candleBus = events.createEventBus()
    local candleDoom = nil
    candleBus:on(events.EVENTS.DARKNESS_DOOMED, function(data)
        candleDoom = data
    end)
    local candleSystem = light_system.createLightSystem({
        eventBus = candleBus,
        guild = { candleCarrier },
    })
    candleSystem:init()
    assertTrue(candleDoom == nil, "relightable candles should prevent out-of-light doom")

    local doomedCarrier = base_entity.createEntity({
        id = "pc_no_light",
        name = "No Light",
        isPC = true,
    })
    doomedCarrier.inventory = inventory.createInventory()
    local spentTorch = inventory.createItemFromTemplate("torch")
    spentTorch.destroyed = true
    spentTorch.properties.extinguished = true
    doomedCarrier.inventory:addItem(spentTorch, inventory.LOCATIONS.PACK)
    local doomBus = events.createEventBus()
    local doomEvent = nil
    doomBus:on(events.EVENTS.DARKNESS_DOOMED, function(data)
        doomEvent = data
    end)
    local noLightSystem = light_system.createLightSystem({
        eventBus = doomBus,
        guild = { doomedCarrier },
    })
    noLightSystem:init()
    assertTrue(doomEvent and doomEvent.needsDraw, "no remaining light sources should request darkness doom draws")
end

local function checkFallingProcedure()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local greatSuccessFaller = base_entity.createEntity({
        id = "pc_fall_great_success",
        name = "Great Success Faller",
        isPC = true,
        pentacles = 4,
        armorSlots = 2,
    })
    local greatSuccess = resolver:resolveFall(greatSuccessFaller, 25, {
        card = { name = "Ten of Pentacles", value = 10, suit = constants.SUITS.PENTACLES },
    })
    assertEqual(greatSuccess.baseWounds, 2, "25-foot fall should start at two Wounds")
    assertEqual(greatSuccess.heightReductionFeet, 20, "great success fall test should reduce height by 20 feet")
    assertEqual(greatSuccess.wounds, 0, "great success should avoid 25-foot fall damage")
    assertTrue(not greatSuccessFaller.conditions.staggered, "great success fall should not wound the faller")

    local successFaller = base_entity.createEntity({
        id = "pc_fall_success",
        name = "Success Faller",
        isPC = true,
        pentacles = 4,
        armorSlots = 2,
    })
    local success = resolver:resolveFall(successFaller, 25, {
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
    })
    assertEqual(success.heightReductionFeet, 10, "successful fall test should reduce height by 10 feet")
    assertEqual(success.wounds, 1, "successful 25-foot fall should deal one Wound")
    assertEqual(successFaller.armorNotches, 0, "falling Wounds should be piercing and skip armor")
    assertTrue(successFaller.conditions.staggered, "successful 25-foot fall should still wound the faller")

    local greatFailureFaller = base_entity.createEntity({
        id = "pc_fall_great_failure",
        name = "Great Failure Faller",
        isPC = true,
        pentacles = 1,
        armorSlots = 2,
    })
    greatFailureFaller.inventory = inventory.createInventory()
    local beltBottle = inventory.createItemFromTemplate("hermetic_bottle")
    local packGlass = inventory.createItem({ name = "Glass Vial", size = 1, durability = 1 })
    local handBottle = inventory.createItemFromTemplate("hermetic_bottle")
    local sturdyRope = inventory.createItem({ name = "Sturdy Rope", size = 1, durability = 2 })
    greatFailureFaller.inventory:addItem(beltBottle, inventory.LOCATIONS.BELT)
    greatFailureFaller.inventory:addItem(packGlass, inventory.LOCATIONS.PACK)
    greatFailureFaller.inventory:addItem(handBottle, inventory.LOCATIONS.HANDS)
    greatFailureFaller.inventory:addItem(sturdyRope, inventory.LOCATIONS.PACK)

    local greatFailure = resolver:resolveFall(greatFailureFaller, 25, {
        testResult = { success = false, isGreat = true },
    })
    assertEqual(greatFailure.heightReductionFeet, 0, "great failure should not reduce falling height")
    assertEqual(greatFailure.wounds, 2, "great failure should take normal falling damage")
    assertEqual(greatFailureFaller.armorNotches, 0, "great failure falling damage should still be piercing")
    assertTrue(greatFailureFaller.conditions.staggered and greatFailureFaller.conditions.injured,
        "two piercing fall Wounds should advance the wound track")
    assertEqual(#greatFailure.fragileItemsDestroyed, 2,
        "great failure should destroy fragile belt and pack items")
    assertTrue(beltBottle.destroyed and packGlass.destroyed, "great failure should break fragile carried gear")
    assertTrue(not handBottle.destroyed, "great failure should not break fragile items held in hands")
    assertTrue(not sturdyRope.destroyed, "great failure should not break durable pack gear")

    local preparedAcrobat = base_entity.createEntity({
        id = "pc_prepared_acrobat",
        name = "Prepared Acrobat",
        isPC = true,
        talents = {
            acrobat = { mastered = true },
        },
    })
    local acrobatPrepared = resolver:resolveFall(preparedAcrobat, 25, {
        acrobatPrepared = true,
    })
    assertEqual(acrobatPrepared.heightReductionFeet, 20,
        "prepared Acrobat should treat the fall as 20 feet shorter")
    assertEqual(acrobatPrepared.wounds, 0, "prepared Acrobat should avoid 25-foot fall damage")
    assertTrue(hasValue(acrobatPrepared.effects, "acrobat_fall_reduction"),
        "prepared Acrobat fall reduction should be reported")

    local unpreparedAcrobat = base_entity.createEntity({
        id = "pc_unprepared_acrobat",
        name = "Unprepared Acrobat",
        isPC = true,
        talents = {
            acrobat = { mastered = true },
        },
    })
    unpreparedAcrobat.resolve = 1
    local acrobatResolve = resolver:resolveFall(unpreparedAcrobat, 25, {
        spendResolveForAcrobat = true,
    })
    assertEqual(acrobatResolve.heightReductionFeet, 20,
        "unprepared Acrobat should spend Resolve to treat the fall as 20 feet shorter")
    assertEqual(unpreparedAcrobat.resolve, 0, "unprepared Acrobat fall reduction should spend one Resolve")
    assertTrue(hasValue(acrobatResolve.effects, "resolve_spent_for_acrobat"),
        "unprepared Acrobat should report Resolve spending")

    local promptBus = events.createEventBus()
    local acrobatPrompt = nil
    local acrobatChoiceResolved = false
    local acrobatPromptAction = {}
    promptBus:on(events.EVENTS.REQUEST_ACROBAT_FALL_CHOICE, function(data)
        acrobatPrompt = data
    end)
    local promptResolver = action_resolver.createActionResolver({
        eventBus = promptBus,
    })
    promptBus:on(events.EVENTS.ACROBAT_FALL_CHOICE_COMPLETE, function(data)
        local ok, resultOrReason = promptResolver:resolvePendingAcrobatFallChoice(acrobatPromptAction, data)
        assertTrue(ok, "Acrobat fall prompt completion should resolve the pending fall: " .. tostring(resultOrReason))
        acrobatChoiceResolved = true
    end)
    local promptedAcrobat = base_entity.createEntity({
        id = "pc_prompted_acrobat",
        name = "Prompted Acrobat",
        isPC = true,
        talents = {
            acrobat = { mastered = true },
        },
    })
    promptedAcrobat.resolve = 1
    local acrobatPromptController = {
        isActive = function()
            return true
        end,
        getState = function()
            return "awaiting_action"
        end,
        getActiveEntity = function()
            return promptedAcrobat
        end,
    }
    local acrobatPromptInput = challenge_input_controller.createChallengeInputController({
        eventBus = promptBus,
        gameState = {
            challengeController = acrobatPromptController,
            playerHand = {
                getHand = function()
                    return {}
                end,
            },
            guild = { promptedAcrobat },
        },
    })
    acrobatPromptInput:init()
    local acrobatPromptOverlay = require('ui.challenge_overlay').createChallengeOverlay({
        gameState = {
            challengeController = acrobatPromptController,
            playerHand = {
                getHand = function()
                    return {}
                end,
            },
        },
        inputState = acrobatPromptInput:getState(),
    })
    local promptedFall = promptResolver:resolveFall(promptedAcrobat, 25, {
        promptAcrobatFallChoice = true,
        fallContext = { source = "fall_smoke" },
    })
    acrobatPromptAction.result = promptedFall
    acrobatPromptAction.pendingAcrobatFallChoice = promptedFall.acrobatFallChoice
    assertTrue(promptedFall.pendingAcrobatFallChoice,
        "unprepared Acrobat falls should be able to pause for a Resolve-spend choice")
    assertTrue(hasValue(promptedFall.effects, "acrobat_fall_choice_required"),
        "Acrobat fall choice prompts should be reported")
    assertEqual(promptedAcrobat.resolve, 1,
        "pending Acrobat fall choice should not spend Resolve before the player elects it")
    assertTrue(not promptedAcrobat.conditions.staggered,
        "pending Acrobat fall choice should not apply falling damage yet")
    assertEqual(promptedFall.acrobatFallChoice.woundsWithoutAcrobat, 2,
        "Acrobat fall choice should report Wounds without spending Resolve")
    assertEqual(promptedFall.acrobatFallChoice.woundsWithAcrobat, 0,
        "Acrobat fall choice should report Wounds after the 20-foot reduction")
    assertTrue(acrobatPrompt and acrobatPrompt.entity == promptedAcrobat,
        "Acrobat fall choice should emit the prompt request")
    assertEqual(acrobatPrompt.fallContext.source, "fall_smoke",
        "Acrobat fall choice prompt should preserve fall context")
    assertTrue(acrobatPromptInput:getState().pendingAcrobatFallChoice ~= nil,
        "input controller should retain the pending Acrobat fall prompt")
    local acrobatFooterPrompt = acrobatPromptOverlay:getFooterPrompt("awaiting_action", promptedAcrobat)
    assertTrue(acrobatFooterPrompt and acrobatFooterPrompt:find("Acrobat", 1, true),
        "Challenge overlay should surface the Acrobat fall prompt")

    acrobatPromptInput:handleChallengeInput("r")
    assertTrue(acrobatChoiceResolved, "Resolve key should complete the Acrobat fall prompt")
    assertEqual(promptedAcrobat.resolve, 0,
        "accepting the Acrobat fall prompt should spend one Resolve")
    assertTrue(not promptedAcrobat.conditions.staggered,
        "accepted Acrobat fall prompt should apply the reduced fall instead of normal damage")
    assertTrue(not promptedFall.pendingAcrobatFallChoice,
        "resolved Acrobat fall prompt should clear the result pending marker")
    assertTrue(promptedFall.acrobatFallChoiceResolved and promptedFall.acrobatFallChoiceResolved.spendResolve,
        "resolved Acrobat fall prompt should record the spend election")

    local decliningAcrobat = base_entity.createEntity({
        id = "pc_declining_acrobat",
        name = "Declining Acrobat",
        isPC = true,
        talents = {
            acrobat = { mastered = true },
        },
    })
    decliningAcrobat.resolve = 1
    local declinedFall = promptResolver:resolveFall(decliningAcrobat, 25, {
        promptAcrobatFallChoice = true,
        declineAcrobatFallReduction = true,
    })
    assertTrue(not declinedFall.pendingAcrobatFallChoice,
        "declining Acrobat fall reduction should resume the fall instead of prompting again")
    assertTrue(hasValue(declinedFall.effects, "acrobat_fall_declined"),
        "declining Acrobat fall reduction should be recorded")
    assertEqual(decliningAcrobat.resolve, 1,
        "declining Acrobat fall reduction should not spend Resolve")
    assertTrue(decliningAcrobat.conditions.staggered,
        "declining Acrobat fall reduction should apply falling damage normally")

    local brokeAcrobat = base_entity.createEntity({
        id = "pc_broke_acrobat",
        name = "Broke Acrobat",
        isPC = true,
        talents = {
            acrobat = { mastered = true },
        },
    })
    brokeAcrobat.resolve = 0
    local noResolve = resolver:resolveFall(brokeAcrobat, 25, {
        spendResolveForAcrobat = true,
    })
    assertEqual(noResolve.heightReductionFeet, 0,
        "unprepared Acrobat without Resolve should not reduce fall height")
    assertTrue(hasValue(noResolve.effects, "acrobat_resolve_missing"),
        "missing Acrobat Resolve should be reported")

    local slimeFaller = base_entity.createEntity({
        id = "pc_no_fall_damage",
        name = "No Fall Damage",
        isPC = true,
        armorSlots = 2,
    })
    slimeFaller.conditions.no_fall_damage = true
    local prevented = resolver:resolveFall(slimeFaller, 50, {})
    assertTrue(prevented.prevented, "no-fall-damage conditions should prevent falling damage")
    assertEqual(prevented.wounds, 0, "prevented falls should deal no Wounds")
end

local function checkCrawlScreenListenerLifecycle()
    local bus = events.createEventBus()
    local screen = crawl_screen.createCrawlScreen({
        eventBus = bus,
        roomManager = {
            getFeature = function()
                return nil
            end,
        },
        watchManager = {},
        gameState = {},
    })

    screen:subscribeEvents()
    local firstCount = countEventListeners(bus)
    assertTrue(firstCount > 0, "crawl screen should register event listeners")

    screen:subscribeEvents()
    assertEqual(countEventListeners(bus), firstCount, "crawl screen resubscribe should not duplicate listeners")

    screen:destroy()
    assertEqual(countEventListeners(bus), 0, "crawl screen destroy should unsubscribe listeners")

    local initBus = events.createEventBus()
    local initScreen = crawl_screen.createCrawlScreen({
        eventBus = initBus,
        roomManager = {
            getFeature = function()
                return nil
            end,
        },
        watchManager = {},
        gameState = {},
    })

    initScreen:init()
    local firstInitCount = countEventListeners(initBus)
    assertTrue(firstInitCount > 0, "crawl screen init should register event listeners")

    initScreen:init()
    assertEqual(countEventListeners(initBus), firstInitCount,
        "crawl screen repeated init should not leak replaced component listeners")

    initScreen:destroy()
    assertEqual(countEventListeners(initBus), 0,
        "crawl screen destroy after repeated init should unsubscribe all listeners")

    local oldGameState = _G.gameState
    local ok, err = pcall(function()
        local guild = {
            base_entity.createEntity({
                id = "pc_lifecycle",
                name = "Lifecycle PC",
                isPC = true,
            }),
        }
        local fakeGameState = {
            activePCIndex = 1,
            guild = guild,
        }
        local roomManagerStub = {
            getFeature = function()
                return nil
            end,
        }
        _G.gameState = fakeGameState

        local transitionBus = events.createEventBus()
        local function makeCrawlScreen()
            local nextScreen = crawl_screen.createCrawlScreen({
                eventBus = transitionBus,
                roomManager = roomManagerStub,
                watchManager = {},
                gameState = fakeGameState,
            })
            fakeGameState.currentScreen = nextScreen
            return nextScreen
        end

        local firstScreen = makeCrawlScreen()
        firstScreen:init()
        firstScreen:setGuild(guild)
        local transitionCount = countEventListeners(transitionBus)
        assertTrue(transitionCount > firstInitCount,
            "crawl screen with guild plates should register component listeners")

        local secondScreen = makeCrawlScreen()
        firstScreen:destroy()
        secondScreen:init()
        secondScreen:setGuild(guild)
        assertEqual(countEventListeners(transitionBus), transitionCount,
            "crawl screen transition should not accumulate old listeners")

        secondScreen:destroy()
        assertEqual(countEventListeners(transitionBus), 0,
            "crawl screen transition cleanup should leave no listeners behind")

        local campScreenModule = require('ui.screens.camp_screen')
        local campBus = events.createEventBus()
        local campScreen = campScreenModule.createCampScreen({
            eventBus = campBus,
            campController = {},
            guild = guild,
        })
        campScreen:init()
        local campCount = countEventListeners(campBus)
        assertTrue(campCount > 0, "camp screen should register UI listeners during init")

        campScreen:subscribeEvents()
        assertEqual(countEventListeners(campBus), campCount,
            "camp screen resubscribe should replace, not duplicate, screen listeners")

        local campScreenNext = campScreenModule.createCampScreen({
            eventBus = campBus,
            campController = {},
            guild = guild,
        })
        campScreen:destroy()
        campScreenNext:init()
        assertEqual(countEventListeners(campBus), campCount,
            "camp screen transition should not accumulate old listeners")

        campScreenNext:destroy()
        assertEqual(countEventListeners(campBus), 0,
            "destroyed camp screen should unsubscribe screen and plate listeners")
    end)
    _G.gameState = oldGameState
    if not ok then
        error(err)
    end
end

