            return camp_controller.STATES.ACTIONS
        end,
        submitAction = function(_, pc, actionData)
            submitted = {
                pc = pc,
                actionData = actionData,
            }
            return true, "submitted"
        end,
    }
    local talentScreen = campScreenModule.createCampScreen({
        eventBus = events.createEventBus(),
        campController = talentController,
        guild = { talentActor, patient },
    })
    local function pickerIndexByTalent(pickerScreen, talentId)
        for i, item in ipairs(pickerScreen.targetPickerItems or {}) do
            if item.campTalentId == talentId then
                return i
            end
        end
        return nil
    end
    local function pickerIndexByHighChantAction(pickerScreen)
        for i, item in ipairs(pickerScreen.targetPickerItems or {}) do
            if item.actionData and item.actionData.talentId == "high_chant" then
                return i
            end
        end
        return nil
    end
    local function pickerIndexByWarStoriesAction(pickerScreen)
        for i, item in ipairs(pickerScreen.targetPickerItems or {}) do
            if item.actionData and item.actionData.talentId == "war_stories" then
                return i
            end
        end
        return nil
    end
    local function pickerIndexByWarStoriesBenefit(pickerScreen, participant, benefit, bondTargetId)
        for i, item in ipairs(pickerScreen.targetPickerItems or {}) do
            if item.warStoriesParticipant == participant and item.warStoriesBenefit == benefit and
               (bondTargetId == nil or item.warStoriesBondTargetId == bondTargetId) then
                return i
            end
        end
        return nil
    end
    local useTalentAction = camp_actions.getAction("use_talent")
    local function optionById(items, id)
        for _, item in ipairs(items or {}) do
            if item.id == id then
                return item
            end
        end
        return nil
    end
    local function hasCommandOption(companionOption, commandName)
        for _, command in ipairs(companionOption and companionOption.commandOptions or {}) do
            if command.command == commandName then
                return true
            end
        end
        return false
    end

    local useTalentOptions = camp_actions.getUseTalentOptions(talentActor, {
        talentId = "high_chant",
        cards = { secondChantCard },
        recipients = { patient },
        discardPile = { chantCard, secondChantCard },
    }, {
        guild = { talentActor, patient },
        actionsCompleted = talentController.actionsCompleted,
        playerDeck = talentController.playerDeck,
        roomManager = campRooms,
        currentRoomId = knownRoom.id,
        currentDungeonLevel = 1,
        knownLocations = { knownRoom.id },
    })
    assertEqual(useTalentOptions.result, "use_talent_options_ready",
        "Use a Talent options should report readiness")
    assertTrue(not useTalentOptions.disabled, "Use a Talent options should be enabled for usable Camp talents")
    assertEqual(useTalentOptions.selectedTalent.id, "high_chant",
        "Use a Talent options should preserve the selected talent")
    assertEqual(#useTalentOptions.talentOptions, 7,
        "Use a Talent options should list supported usable Camp talents")
    assertEqual(useTalentOptions.selectedBranch.talentId, "high_chant",
        "Use a Talent options should expose selected branch data")
    assertEqual(useTalentOptions.selectedBranch.maxCards, 2,
        "High Chant options should preview the Cups card limit")
    assertEqual(useTalentOptions.selectedBranch.cardOptions[1].name, "Three of Wands",
        "High Chant options should list discard cards from the top")
    assertTrue(useTalentOptions.selectedBranch.cardOptions[1].selected,
        "High Chant options should mark selected discard cards")
    assertEqual(useTalentOptions.selectedBranch.selectedRecipients[1].id, patient.id,
        "High Chant options should preview selected recipients")
    assertEqual(useTalentOptions.branches.bookworm.bookOptions[1].id, talentBook.id,
        "Use a Talent options should expose Bookworm readable books")
    assertEqual(useTalentOptions.branches.chirurgery.patientOptions[1].id, patient.id,
        "Use a Talent options should expose resting Chirurgery patients")
    assertTrue(useTalentOptions.branches.chirurgery.patientOptions[1].healingPreview.injured,
        "Chirurgery options should preview wound healing")
    assertTrue(hasCommandOption(useTalentOptions.branches.beastMaster.companionOptions[1], "Guard"),
        "Beast Master options should expose teachable companion commands")
    assertEqual(useTalentOptions.branches.loremaster.textOptions[1].id, inscription.id,
        "Loremaster options should expose short ancient texts")
    assertEqual(useTalentOptions.branches.sneak.locationOptions[1].id, knownRoom.id,
        "Sneak options should include known Infiltrate locations")
    assertTrue(optionById(useTalentOptions.branches.warStories.participantOptions, patient.id) ~= nil,
        "War Stories options should expose guild participants")
    assertEqual(#talentController.playerDeck.discard_pile, 2,
        "Use a Talent options should not consume discard cards")
    assertTrue(patient.inspirationCard == nil,
        "Use a Talent options should not grant inspiration")

    submitted = nil
    talentScreen:submitCampAction(talentActor, useTalentAction, 120, 140)
    assertTrue(talentScreen.targetPickerOpen, "Camp screen Use a Talent should open a talent picker")
    local warStoriesIndex = pickerIndexByTalent(talentScreen, "war_stories")
    assertTrue(warStoriesIndex ~= nil, "Use a Talent picker should list War Stories")
    talentScreen:selectTargetPickerItem(warStoriesIndex)
    assertTrue(submitted == nil, "War Stories talent selection should open the benefit picker first")
    local storytellerResolveIndex = pickerIndexByWarStoriesBenefit(talentScreen, talentActor, "resolve")
    assertTrue(storytellerResolveIndex ~= nil, "War Stories picker should list the storyteller's Resolve benefit")
    talentScreen:selectTargetPickerItem(storytellerResolveIndex)
    assertTrue(submitted == nil, "War Stories storyteller benefit should return to benefit choices")
    local listenerBondIndex = pickerIndexByWarStoriesBenefit(talentScreen, patient, "charge_bond", talentActor.id)
    assertTrue(listenerBondIndex ~= nil, "War Stories picker should list listener Bond benefits")
    talentScreen:selectTargetPickerItem(listenerBondIndex)
    assertTrue(submitted == nil, "War Stories listener benefit should require the finish choice")
    local finishWarStoriesIndex = pickerIndexByWarStoriesAction(talentScreen)
    assertTrue(finishWarStoriesIndex ~= nil, "War Stories picker should offer a finish choice")
    talentScreen:selectTargetPickerItem(finishWarStoriesIndex)
    assertEqual(submitted.actionData.type, "use_talent", "War Stories picker should submit use_talent")
    assertEqual(submitted.actionData.talentId, "war_stories",
        "War Stories picker should submit the selected talent")
    assertEqual(submitted.actionData.participants[1], talentActor,
        "War Stories picker should submit the storyteller participant")
    assertEqual(submitted.actionData.benefits[talentActor.id].type, "resolve",
        "War Stories picker should submit the storyteller Resolve benefit")
    assertEqual(submitted.actionData.participants[2], patient,
        "War Stories picker should submit the listener participant")
    assertEqual(submitted.actionData.benefits[patient.id].type, "charge_bond",
        "War Stories picker should submit the listener Bond benefit")
    assertEqual(submitted.actionData.benefits[patient.id].bondTargetId, talentActor.id,
        "War Stories picker should submit the selected Bond target")

    submitted = nil
    talentScreen:submitCampAction(talentActor, useTalentAction, 120, 140)
    local bookwormIndex = pickerIndexByTalent(talentScreen, "bookworm")
    assertTrue(bookwormIndex ~= nil, "Use a Talent picker should list Bookworm")
    talentScreen:selectTargetPickerItem(bookwormIndex)
    assertTrue(submitted == nil, "Bookworm talent selection should open the book picker first")
    assertEqual(talentScreen.targetPickerItems[1].target, talentBook,
        "Bookworm picker should list readable carried books")
    talentScreen:selectTargetPickerItem(1)
    assertEqual(submitted.actionData.talentId, "bookworm",
        "Bookworm picker should submit the selected talent")
    assertEqual(submitted.actionData.target, talentBook,
        "Bookworm picker should submit the selected book")

    submitted = nil
    talentScreen:submitCampAction(talentActor, useTalentAction, 120, 140)
    local chirurgeonIndex = pickerIndexByTalent(talentScreen, "chirurgeon")
    assertTrue(chirurgeonIndex ~= nil, "Use a Talent picker should list Chirurgery")
    talentScreen:selectTargetPickerItem(chirurgeonIndex)
    assertTrue(submitted == nil, "Chirurgery selection should open the patient picker first")
    assertEqual(talentScreen.targetPickerItems[1].target, patient,
        "Chirurgery picker should list resting non-Stressed guild-mates")
    talentScreen:selectTargetPickerItem(1)
    assertEqual(submitted.actionData.talentId, "chirurgeon",
        "Chirurgery picker should submit the selected talent")
    assertEqual(submitted.actionData.target, patient,
        "Chirurgery picker should submit the selected patient")

    submitted = nil
    talentScreen:submitCampAction(talentActor, useTalentAction, 120, 140)
    local beastMasterIndex = pickerIndexByTalent(talentScreen, "beast_master")
    assertTrue(beastMasterIndex ~= nil, "Use a Talent picker should list Beast Master")
    talentScreen:selectTargetPickerItem(beastMasterIndex)
    assertTrue(submitted == nil, "Beast Master selection should open the companion picker first")
    assertEqual(talentScreen.targetPickerItems[1].target, talentHound,
        "Beast Master picker should list animal companions")
    talentScreen:selectTargetPickerItem(1)
    assertTrue(submitted == nil, "Beast Master companion selection should open the command picker first")
    local guardIndex = nil
    for i, item in ipairs(talentScreen.targetPickerItems) do
        if item.actionData and item.actionData.command == "Guard" then
            guardIndex = i
            break
        end
    end
    assertTrue(guardIndex ~= nil, "Beast Master command picker should list teachable commands")
    talentScreen:selectTargetPickerItem(guardIndex)
    assertEqual(submitted.actionData.talentId, "beast_master",
        "Beast Master picker should submit the selected talent")
    assertEqual(submitted.actionData.companionId, talentHound.id,
        "Beast Master picker should submit the selected companion")
    assertEqual(submitted.actionData.command, "Guard",
        "Beast Master picker should submit the selected command")

    submitted = nil
    talentScreen:submitCampAction(talentActor, useTalentAction, 120, 140)
    local highChantIndex = pickerIndexByTalent(talentScreen, "high_chant")
    assertTrue(highChantIndex ~= nil, "Use a Talent picker should list High Chant")
    talentScreen:selectTargetPickerItem(highChantIndex)
    assertTrue(submitted == nil, "High Chant talent selection should open the discard-card picker first")
    assertEqual(talentScreen.targetPickerItems[1].target, secondChantCard,
        "High Chant picker should list minor discard cards")
    talentScreen:selectTargetPickerItem(1)
    assertTrue(submitted == nil, "High Chant card selection should open the recipient picker first")
    local patientInspirationIndex = nil
    for i, item in ipairs(talentScreen.targetPickerItems) do
        if item.target == patient then
            patientInspirationIndex = i
            break
        end
    end
    assertTrue(patientInspirationIndex ~= nil, "High Chant recipient picker should list uninspired guild-mates")
    talentScreen:selectTargetPickerItem(patientInspirationIndex)
    assertTrue(submitted == nil, "High Chant first recipient selection should return to card choices")
    local remainingCardIndex = pickerIndexByTarget(talentScreen, chantCard)
    assertTrue(remainingCardIndex ~= nil, "High Chant picker should list remaining discard cards")
    talentScreen:selectTargetPickerItem(remainingCardIndex)
    assertTrue(submitted == nil, "High Chant second card selection should open a second recipient picker")
    assertTrue(pickerIndexByTarget(talentScreen, patient) == nil,
        "High Chant recipient picker should not reuse a recipient in the same batch")
    local performerInspirationIndex = pickerIndexByTarget(talentScreen, talentActor)
    assertTrue(performerInspirationIndex ~= nil, "High Chant recipient picker should allow the performer to keep a card")
    talentScreen:selectTargetPickerItem(performerInspirationIndex)
    assertTrue(submitted == nil, "High Chant batch selection should require the finish choice")
    local finishHighChantIndex = pickerIndexByHighChantAction(talentScreen)
    assertTrue(finishHighChantIndex ~= nil, "High Chant picker should offer a finish choice")
    talentScreen:selectTargetPickerItem(finishHighChantIndex)
    assertEqual(submitted.actionData.talentId, "high_chant",
        "High Chant picker should submit the selected talent")
    assertEqual(submitted.actionData.cards[1], secondChantCard,
        "High Chant picker should submit the first selected discard card")
    assertEqual(submitted.actionData.recipients[1], patient,
        "High Chant picker should submit the first selected inspiration recipient")
    assertEqual(submitted.actionData.cards[2], chantCard,
        "High Chant picker should submit the second selected discard card")
    assertEqual(submitted.actionData.recipients[2], talentActor,
        "High Chant picker should submit the second selected inspiration recipient")

    submitted = nil
    talentScreen:submitCampAction(talentActor, useTalentAction, 120, 140)
    local loremasterIndex = pickerIndexByTalent(talentScreen, "loremaster")
    assertTrue(loremasterIndex ~= nil, "Use a Talent picker should list Loremaster")
    talentScreen:selectTargetPickerItem(loremasterIndex)
    assertTrue(submitted == nil, "Loremaster selection should open the text picker first")
    assertEqual(talentScreen.targetPickerItems[1].target, inscription,
        "Loremaster picker should list short ancient carried texts")
    talentScreen:selectTargetPickerItem(1)
    assertEqual(submitted.actionData.talentId, "loremaster",
        "Loremaster picker should submit the selected talent")
    assertEqual(submitted.actionData.target, inscription,
        "Loremaster picker should submit the selected text")

    submitted = nil
    talentScreen:submitCampAction(talentActor, useTalentAction, 120, 140)
    local sneakIndex = pickerIndexByTalent(talentScreen, "sneak")
    assertTrue(sneakIndex ~= nil, "Use a Talent picker should list Sneak")
    talentScreen:selectTargetPickerItem(sneakIndex)
    assertTrue(submitted == nil, "Sneak talent selection should open the location picker first")
    assertEqual(talentScreen.targetPickerItems[1].actionData.roomId, knownRoom.id,
        "Sneak picker should list known infiltration locations")
    talentScreen:selectTargetPickerItem(1)
    assertEqual(submitted.actionData.type, "use_talent",
        "Sneak picker should submit use_talent")
    assertEqual(submitted.actionData.talentId, "sneak",
        "Sneak picker should submit the selected talent")
    assertEqual(submitted.actionData.roomId, knownRoom.id,
        "Sneak picker should submit the selected known location")
end

function checkCampScreenRecoveryBondPicker()
    local campScreenModule = require('ui.screens.camp_screen')
    local actor = base_entity.createEntity({
        id = "pc_camp_screen_recovery",
        name = "Camp Screen Recovery",
        isPC = true,
    })
    actor.conditions.injured = true
    actor.resolve = { current = 2, max = 4 }
    function actor:regainResolve(amount)
        amount = amount or 1
        self.resolve.current = math.min(self.resolve.current + amount, self.resolve.max)
    end
    actor.bonds = {
        ally = { charged = true },
    }
    actor.afflictions = {
        red_welts = { stage = 1, maxStage = 2 },
    }
    actor.animalCompanions = {
        {
            id = "companion_camp_screen_recovery_hound",
            name = "Recovery Hound",
            conditions = { injured = true },
        },
    }

    local captured = nil
    local controller = {
        actionsCompleted = {
            [actor.id] = { type = "rest" },
        },
        getState = function()
            return camp_controller.STATES.RECOVERY
        end,
        spendBondForRecovery = function(_, pc, bondTargetId, spendType, opts)
            captured = {
                pc = pc,
                bondTargetId = bondTargetId,
                spendType = spendType,
                opts = opts,
            }
            return true, spendType .. "_ok"
        end,
    }
    local screen = campScreenModule.createCampScreen({
        eventBus = events.createEventBus(),
        campController = controller,
        guild = { actor },
    })

    local function pickerIndexBySpendType(pickerScreen, spendType)
        for i, item in ipairs(pickerScreen.targetPickerItems or {}) do
            if item.actionData and item.actionData.spendType == spendType then
                return i
            end
        end
        return nil
    end

    screen.hoveredBond = {
        pcIndex = 1,
        targetId = "ally",
        bond = actor.bonds.ally,
    }
    screen:handleRecoveryClick(1, 120, 140)
    assertTrue(screen.targetPickerOpen, "Recovery charged Bond click should open a benefit picker")
    assertTrue(pickerIndexBySpendType(screen, "heal_wound") ~= nil,
        "Recovery Bond picker should offer wound healing")
    local regainResolveIndex = pickerIndexBySpendType(screen, "regain_resolve")
    assertTrue(regainResolveIndex ~= nil,
        "Recovery Bond picker should offer Resolve recovery when Resolve is below max")
    assertTrue(pickerIndexBySpendType(screen, "cure_affliction") ~= nil,
        "Recovery Bond picker should offer affliction cure charges after Rest and Recover")
    assertTrue(pickerIndexBySpendType(screen, "heal_companion") ~= nil,
        "Recovery Bond picker should offer injured animal companion healing")

    screen:selectTargetPickerItem(regainResolveIndex)
    assertTrue(captured ~= nil, "Recovery Bond picker should submit a selected benefit")
    assertEqual(captured.pc, actor, "Recovery Bond picker should submit the recovery actor")
    assertEqual(captured.bondTargetId, "ally",
        "Recovery Bond picker should submit the clicked Bond target")
    assertEqual(captured.spendType, "regain_resolve",
        "Recovery Bond picker should submit the selected spend type")
    assertTrue(not screen.targetPickerOpen,
        "Recovery Bond picker should close after submitting a benefit")

    actor.conditions.stressed = true
    captured = nil
    screen.hoveredBond = {
        pcIndex = 1,
        targetId = "ally",
        bond = actor.bonds.ally,
    }
    screen:handleRecoveryClick(1, 120, 140)
    assertTrue(not screen.targetPickerOpen,
        "Stressed Recovery Bond clicks should use the stress gate directly")
    assertEqual(captured.spendType, "clear_stress",
        "Stressed Recovery Bond clicks should submit clear_stress")

    local helperActor = base_entity.createEntity({
        id = "pc_camp_screen_recovery_helper_options",
        name = "Camp Screen Recovery Helper Options",
        isPC = true,
    })
    helperActor.bonds = {
        helper_ally = { charged = true },
    }
    local helperRequestedOptions = nil
    local helperCaptured = nil
    local helperController = {
        getRecoveryOptions = function(_, opts)
            helperRequestedOptions = opts
            return {
                result = "recovery_options_ready",
                selectedActor = {
                    entity = helperActor,
                    entityId = helperActor.id,
                },
                selectedBond = {
                    targetId = "helper_ally",
                    benefitOptions = {
                        {
                            label = "Controller Resolve",
                            detail = "From Recovery options",
                            spendType = "regain_resolve",
                            actionDataPreview = {
                                bondTargetId = "helper_ally",
                                spendType = "regain_resolve",
                                fromRecoveryOptions = true,
                            },
                        },
                    },
                },
            }
        end,
        spendBondForRecovery = function(_, pc, bondTargetId, spendType, opts)
            helperCaptured = {
                pc = pc,
                bondTargetId = bondTargetId,
                spendType = spendType,
                opts = opts,
            }
            return true, "resolve_regained"
        end,
    }
    local helperScreen = campScreenModule.createCampScreen({
        eventBus = events.createEventBus(),
        campController = helperController,
        guild = { helperActor },
    })
    helperScreen.hoveredBond = {
        pcIndex = 1,
        targetId = "helper_ally",
        bond = helperActor.bonds.helper_ally,
    }
    helperScreen:handleRecoveryClick(1, 120, 140)
    assertEqual(helperRequestedOptions.actorId, helperActor.id,
        "Recovery Bond picker should request backend Recovery options for the actor")
    assertEqual(helperScreen.targetPickerItems[1].label, "Controller Resolve",
        "Recovery Bond picker should use backend Recovery option labels")
    helperScreen:selectTargetPickerItem(1)
    assertEqual(helperCaptured.opts.fromRecoveryOptions, true,
        "Recovery Bond picker should submit backend Recovery option action data")

    local aidActor = base_entity.createEntity({
        id = "pc_camp_screen_recovery_aid",
        name = "Camp Screen Recovery Aid",
        isPC = true,
    })
    aidActor.xp = 1
    aidActor.inventory = inventory.createInventory()
    local recoveryBezoar = inventory.createItemFromTemplate("bezoar")
    local recoveryLeeches = inventory.createItemFromTemplate("leeches")
    aidActor.inventory:addItem(recoveryBezoar, inventory.LOCATIONS.PACK)
    aidActor.inventory:addItem(recoveryLeeches, inventory.LOCATIONS.PACK)
    aidActor.afflictions = {
        basilisk_bile = {
            stage = 2,
            maxStage = 2,
            chargesRequired = {
                [1] = 2,
                [2] = 3,
            },
        },
        ghost_lotus = {
            stage = 1,
            maxStage = 3,
            stageRecovery = {
                [1] = { xp = 1, charges = 0 },
                [2] = { charges = 2 },
                [3] = { charges = 1 },
            },
        },
    }
    local aidCaptured = nil
    local aidController = {
        actionsCompleted = {
            [aidActor.id] = { type = "rest", actor = aidActor },
        },
        getState = function()
            return camp_controller.STATES.RECOVERY
        end,
        getAfflictionRecoveryState = function(_, pc, afflictionName)
            local affliction = pc.afflictions[afflictionName]
            local stage = affliction and affliction.stage or 1
            local xpStageCosts = {}
            local spec = affliction and affliction.stageRecovery and affliction.stageRecovery[stage]
            if type(spec) == "table" and spec.xp then
                xpStageCosts[stage] = spec.xp
            end
            return {
                stage = stage,
                xpStageCosts = xpStageCosts,
            }
        end,
        spendHealthfulItemForRecovery = function(_, pc, itemId, opts)
            aidCaptured = {
                kind = "healthful_item",
                pc = pc,
                itemId = itemId,
                opts = opts,
            }
            return true, "affliction_charged", { charges = 8 }
        end,
        spendXPForAfflictionRecovery = function(_, pc, afflictionName, opts)
            aidCaptured = {
                kind = "xp_affliction",
                pc = pc,
                affliction = afflictionName,
                opts = opts,
            }
            return true, "affliction_cured", { xpSpent = opts and opts.xp }
        end,
    }
    local aidScreen = campScreenModule.createCampScreen({
        eventBus = events.createEventBus(),
        campController = aidController,
        guild = { aidActor },
    })
    local function recoveryAidIndex(pickerScreen, spendType, affliction)
        for i, item in ipairs(pickerScreen.targetPickerItems or {}) do
            if item.actionData and item.actionData.spendType == spendType and
               item.actionData.affliction == affliction then
                return i
            end
        end
        return nil
    end

    aidScreen.hoveredBond = nil
    aidScreen:handleRecoveryClick(1, 160, 180)
    assertTrue(aidScreen.targetPickerOpen,
        "plain Recovery plate click should open a non-Bond aid picker when aids are available")
    local bezoarIndex = recoveryAidIndex(aidScreen, "healthful_item", "basilisk_bile")
    assertTrue(bezoarIndex ~= nil,
        "Recovery aid picker should offer carried healthful affliction items")
    local leechRecoveryIndex = nil
    for i, item in ipairs(aidScreen.targetPickerItems or {}) do
        if item.actionData and item.actionData.itemId == recoveryLeeches.id then
            leechRecoveryIndex = i
            break
        end
    end
    assertTrue(leechRecoveryIndex == nil,
        "Recovery aid picker should leave leeches on their Camp Use an Item card-draw path")
    local xpIndex = recoveryAidIndex(aidScreen, "xp_affliction", "ghost_lotus")
    assertTrue(xpIndex ~= nil,
        "Recovery aid picker should offer stage-specific XP affliction recovery")

    aidScreen:selectTargetPickerItem(bezoarIndex)
    assertEqual(aidCaptured.kind, "healthful_item",
        "Recovery aid picker should submit healthful item recovery")
    assertEqual(aidCaptured.itemId, recoveryBezoar.id,
        "Recovery aid picker should submit the selected healthful item")
    assertEqual(aidCaptured.opts.affliction, "basilisk_bile",
        "Recovery aid picker should submit the selected item affliction")

    aidCaptured = nil
    aidScreen:handleRecoveryClick(1, 160, 180)
    aidScreen:selectTargetPickerItem(recoveryAidIndex(aidScreen, "xp_affliction", "ghost_lotus"))
    assertEqual(aidCaptured.kind, "xp_affliction",
        "Recovery aid picker should submit XP affliction recovery")
    assertEqual(aidCaptured.affliction, "ghost_lotus",
        "Recovery aid picker should submit the selected XP affliction")
    assertEqual(aidCaptured.opts.xp, 1,
        "Recovery aid picker should submit the current-stage XP cost")

    local helperAidActor = base_entity.createEntity({
        id = "pc_camp_screen_recovery_aid_options",
        name = "Camp Screen Recovery Aid Options",
        isPC = true,
    })
    local helperAidRequestedOptions = nil
    local helperAidCaptured = nil
    local helperAidController = {
        getRecoveryOptions = function(_, opts)
            helperAidRequestedOptions = opts
            return {
                result = "recovery_options_ready",
                selectedActor = {
                    entity = helperAidActor,
                    entityId = helperAidActor.id,
                    aidOptions = {
                        {
                            label = "Controller Bezoar",
                            detail = "From Recovery options",
                            spendType = "healthful_item",
                            itemId = "bezoar_helper",
                            affliction = "red_welts",
                            actionDataPreview = {
                                spendType = "healthful_item",
                                itemId = "bezoar_helper",
                                affliction = "red_welts",
                                fromRecoveryOptions = true,
                            },
                        },
                    },
                },
            }
        end,
        spendHealthfulItemForRecovery = function(_, pc, itemId, opts)
            helperAidCaptured = {
                pc = pc,
                itemId = itemId,
                opts = opts,
            }
            return true, "affliction_charged", {}
        end,
    }
    local helperAidScreen = campScreenModule.createCampScreen({
        eventBus = events.createEventBus(),
        campController = helperAidController,
        guild = { helperAidActor },
    })
    helperAidScreen:handleRecoveryClick(1, 160, 180)
    assertEqual(helperAidRequestedOptions.actorId, helperAidActor.id,
        "Recovery aid picker should request backend Recovery options for the actor")
    assertEqual(helperAidScreen.targetPickerItems[1].label, "Controller Bezoar",
        "Recovery aid picker should use backend Recovery option labels")
    helperAidScreen:selectTargetPickerItem(1)
    assertEqual(helperAidCaptured.opts.fromRecoveryOptions, true,
        "Recovery aid picker should submit backend Recovery option action data")
end

function checkCampScreenBreakBreadPicker()
    local campScreenModule = require('ui.screens.camp_screen')
    local eater = base_entity.createEntity({
        id = "pc_camp_screen_hale",
        name = "Camp Screen Hale",
        isPC = true,
        talents = {
            hale_and_hearty = { mastered = true },
        },
    })
    eater.inventory = inventory.createInventory()
    local rations = inventory.createItemFromTemplate("rations_3")
    eater.inventory:addItem(rations, inventory.LOCATIONS.PACK)
    eater.bonds = {
        ally = { charged = false, name = "Ally" },
    }

    local captured = nil
    local controller = {
        rationsConsumed = {},
        getState = function()
            return camp_controller.STATES.BREAK_BREAD
        end,
        consumeRation = function(_, pc, opts)
            captured = {
                pc = pc,
                opts = opts or {},
            }
            return true, opts and opts.chargeBondTargetId and
                "ration_consumed_bond_charged" or "ration_consumed"
        end,
    }
    local screen = campScreenModule.createCampScreen({
        eventBus = events.createEventBus(),
        campController = controller,
        guild = { eater },
    })

    screen:handleBreakBreadClick(1, 130, 150)
    assertTrue(screen.targetPickerOpen,
        "Hale and Hearty Break Bread should open a ration choice picker")
    assertEqual(screen.targetPickerAction.id, "break_bread",
        "Break Bread picker should use the break_bread action id")
    assertTrue(#screen.targetPickerItems >= 2,
        "Hale and Hearty picker should offer ordinary eating plus second-ration options")

    local chargeIndex = nil
    for i, item in ipairs(screen.targetPickerItems or {}) do
        if item.actionData and item.actionData.chargeBondTargetId == "ally" then
            chargeIndex = i
            break
        end
    end
    assertTrue(chargeIndex ~= nil,
        "Hale and Hearty picker should offer charging an uncharged Bond")
    screen:selectTargetPickerItem(chargeIndex)
    assertEqual(captured.pc, eater, "Break Bread picker should submit the selected eater")
    assertEqual(captured.opts.chargeBondTargetId, "ally",
        "Hale and Hearty picker should submit the selected Bond target")

    local plain = base_entity.createEntity({
        id = "pc_camp_screen_plain_break_bread",
        name = "Plain Break Bread",
        isPC = true,
    })
    plain.inventory = inventory.createInventory()
    plain.inventory:addItem(inventory.createItemFromTemplate("ration"), inventory.LOCATIONS.PACK)
    local plainCaptured = nil
    local plainController = {
        rationsConsumed = {},
        getState = function()
            return camp_controller.STATES.BREAK_BREAD
        end,
        consumeRation = function(_, pc, opts)
            plainCaptured = {
                pc = pc,
                opts = opts,
            }
            return true, "ration_consumed"
        end,
    }
    local plainScreen = campScreenModule.createCampScreen({
        eventBus = events.createEventBus(),
        campController = plainController,
        guild = { plain },
    })
    plainScreen:handleBreakBreadClick(1, 130, 150)
    assertTrue(not plainScreen.targetPickerOpen,
        "ordinary Break Bread clicks should keep the direct ration-consumption path")
    assertEqual(plainCaptured.pc, plain,
        "ordinary Break Bread click should still submit ration consumption")

    local companionOwner = base_entity.createEntity({
        id = "pc_camp_screen_companion_feed",
        name = "Camp Screen Companion Feed",
        isPC = true,
    })
    companionOwner.inventory = inventory.createInventory()
    companionOwner.inventory:addItem(inventory.createItemFromTemplate("ration"), inventory.LOCATIONS.PACK)
    local houndFeed = inventory.createItemFromTemplate("animal_feed", {
        properties = {
            isAnimalFeed = true,
            feedFor = "hound",
        },
    })
    companionOwner.inventory:addItem(houndFeed, inventory.LOCATIONS.PACK)
    companionOwner.animalCompanions = {
        {
            id = "camp_screen_feed_hound",
            name = "Screen Hound",
            species = "hound",
            conditions = {},
        },
        {
            id = "camp_screen_feed_moth",
            name = "Screen Moth",
            feedType = "dire moth",
            conditions = {},
        },
    }
    local companionCaptured = nil
    local companionController = {
        rationsConsumed = {},
        animalFeedConsumed = {},
        getState = function()
            return camp_controller.STATES.BREAK_BREAD
        end,
        consumeRation = function(_, pc, opts)
            companionCaptured = {
                pc = pc,
                opts = opts,
            }
            return true, "ration_consumed"
        end,
    }
    local companionScreen = campScreenModule.createCampScreen({
        eventBus = events.createEventBus(),
        campController = companionController,
        guild = { companionOwner },
    })
    companionScreen:handleBreakBreadClick(1, 130, 150)
    assertTrue(companionScreen.targetPickerOpen,
        "Break Bread should open a presentation picker for owners with animal companions")
    local companionDetail = companionScreen.targetPickerItems[1].detail or ""
    assertTrue(companionDetail:find("Screen Hound", 1, true) ~= nil and
        companionDetail:find("Animal Feed", 1, true) ~= nil,
        "animal companion feed picker should preview matching feed")
    assertTrue(companionDetail:find("Screen Moth: no feed", 1, true) ~= nil,
        "animal companion feed picker should preview missing species-specific feed")
    companionScreen:selectTargetPickerItem(1)
    assertEqual(companionCaptured.pc, companionOwner,
        "animal companion feed picker should still submit owner ration consumption")
end

function checkCampControllerPromptActionsDoNotComplete()
    local promptedActions = {}
    local bus = events.createEventBus()
    bus:on(camp_controller.EVENTS.CAMP_ACTION_TAKEN, function(data)
        promptedActions[#promptedActions + 1] = data
    end)

    local reader = base_entity.createEntity({
        id = "pc_prompt_reader",
        name = "Prompt Reader",
        isPC = true,
    })
    reader.inventory = inventory.createInventory()
    local book = inventory.createItemFromTemplate("tomb_lore_book")
    reader.inventory:addItem(book, inventory.LOCATIONS.PACK)
    local readController = camp_controller.createCampController({
        eventBus = bus,
        guild = { reader },
    })
    readController:transitionTo(camp_controller.STATES.ACTIONS)
    local ok, result = readController:submitAction(reader, {
        type = "read_book",
        target = book,
    })
    assertTrue(ok, "Read a Book prompt should return success")
    assertEqual(result, "book_question_required", "Read a Book without a question should prompt")
    assertTrue(readController.actionsCompleted[reader.id] == nil,
        "Read a Book prompt should not consume the Camp Action")
    assertEqual(#promptedActions, 0, "prompt-only Camp Actions should not emit action-taken events")

    ok, result = readController:submitAction(reader, {
        type = "read_book",
        target = book,
        request = {
            questionType = "identity_or_origin",
        },
    })
    assertTrue(ok, "Read a Book with a question should resolve")
    assertEqual(result, "book_answered", "Read a Book with a question should answer")
    assertEqual(readController.actionsCompleted[reader.id].type, "read_book",
        "resolved Read a Book should consume the Camp Action")

    local alchemist = base_entity.createEntity({
        id = "pc_prompt_alchemist",
        name = "Prompt Alchemist",
        isPC = true,
        talents = {
            alchemy = { mastered = true },
        },
    })
    alchemist.inventory = inventory.createInventory()
    alchemist.inventory:addItem(inventory.createItemFromTemplate("alchemy_kit"), inventory.LOCATIONS.PACK)
    local reagent = inventory.createItemFromTemplate("brain_spider_reagent")
    alchemist.inventory:addItem(reagent, inventory.LOCATIONS.PACK)
    local brewController = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { alchemist },
    })
    brewController:transitionTo(camp_controller.STATES.ACTIONS)
    ok, result = brewController:submitAction(alchemist, {
        type = "brew_alchemy",
    })
    assertTrue(ok, "Brew Alchemy prompt should return success")
    assertEqual(result, "alchemy_choices_required", "Brew Alchemy without selections should prompt")
    assertTrue(brewController.actionsCompleted[alchemist.id] == nil,
        "Brew Alchemy prompt should not consume the Camp Action")

    ok, result = brewController:submitAction(alchemist, {
        type = "brew_alchemy",
        transforms = {
            {
                reagentId = reagent.id,
                form = "bomb",
            },
        },
    })
    assertTrue(ok, "Brew Alchemy with a reagent/form selection should resolve")
    assertEqual(result, "alchemy_brewed", "Brew Alchemy with selections should brew")
    assertEqual(brewController.actionsCompleted[alchemist.id].type, "brew_alchemy",
        "resolved Brew Alchemy should consume the Camp Action")

    local devourer = base_entity.createEntity({
        id = "pc_prompt_devourer",
        name = "Prompt Devourer",
        isPC = true,
    })
    devourer.activePacts = {
        {
            id = "devour_living",
            active = true,
        },
    }
    local devourController = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { devourer },
    })
    devourController:transitionTo(camp_controller.STATES.ACTIONS)
    ok, result = devourController:submitAction(devourer, {
        type = "devour_living",
    })
    assertTrue(ok, "Devour the Living prompt should return success")
    assertEqual(result, "devour_living_test_required", "Devour the Living without outcome should prompt")
    assertTrue(devourController.actionsCompleted[devourer.id] == nil,
        "Devour the Living prompt should not consume the Camp Action")

    ok, result = devourController:submitAction(devourer, {
        type = "devour_living",
        outcome = "success",
    })
    assertTrue(ok, "Devour the Living with a test outcome should resolve")
    assertEqual(result, "living_food_found", "successful Devour the Living should find food")
    assertEqual(devourController.actionsCompleted[devourer.id].type, "devour_living",
        "resolved Devour the Living should consume the Camp Action")
end

local function checkStunDiscardsChallengeCard()
    local bus = events.createEventBus()
    local discarded = {}
    local pc = base_entity.createEntity({
        id = "pc_stunned_card",
        name = "Stunned Card PC",
        isPC = true,
    })
    local firstCard = { name = "First Challenge", value = 3, suit = constants.SUITS.SWORDS }
    local secondCard = { name = "Second Challenge", value = 8, suit = constants.SUITS.CUPS }
    local hand = player_hand.createPlayerHand({
        eventBus = bus,
        playerDeck = {
            discard = function(_, card)
                discarded[#discarded + 1] = card
            end,
        },
        guild = { pc },
    })
    hand.hands[pc.id] = {
        cards = { firstCard, secondCard },
    }

    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
        playerHand = hand,
    })
    local stun = resolver:applyStun(pc, {
        stunDiscardIndex = 2,
    })

    assertTrue(pc.conditions.stunned and pc.conditions.stunnedInstant,
        "Stun should mark the instantaneous Stunned effect")
    assertTrue(stun.card == secondCard, "Stun should discard the chosen Challenge card")
    assertEqual(#hand.hands[pc.id].cards, 1, "Stun should remove one card from the PC hand")
    assertTrue(hand.hands[pc.id].cards[1] == firstCard,
        "Stun should leave unchosen Challenge cards in hand")
    assertTrue(discarded[1] == secondCard, "Stun should discard the chosen card to the player deck")
end

local function checkChallengeActionFavorAndResolve()
    local actionReference = action_registry.getChallengeActionReference()
    assertEqual(actionReference.source, "Core Rules Chapter 7: Challenge Actions",
        "Challenge action reference should cite the Chapter 7 action section")
    assertTrue(not actionReference.freeActions.requireCard,
        "Challenge action reference should preserve cardless free actions")
    assertTrue(actionReference.valueRules.primaryTurn.addAttribute,
        "Challenge action reference should preserve primary-turn attribute addition")
    assertTrue(not actionReference.valueRules.minorAction.addAttribute,
        "Challenge action reference should preserve face-value-only minor actions")
    assertEqual(actionReference.suitGroups[1].suit, action_registry.SUITS.SWORDS,
        "Challenge action reference should start with Swords actions")
    assertTrue(hasValue(actionReference.coreActionIds, "vigilance"),
        "Challenge action reference should list Vigilance as a core action")
    assertTrue(hasValue(actionReference.extensionActionIds, "heavy_metal_machine"),
        "Challenge action reference should separate talent/extension actions")

    local challengeActionDetails = action_registry.getChallengeActionDetails()
    assertTrue(#challengeActionDetails >= 22,
        "Challenge action details should expose the core Chapter 7 action catalog")

    local attackDetails = action_registry.getChallengeActionDetails("attack")
    assertEqual(attackDetails.rulebookId, "attack",
        "Attack action details should be reachable by rulebook alias")
    assertEqual(attackDetails.tieRule, "attacker wins unless defender has a shield",
        "Attack details should preserve shield tie handling")
    assertTrue(hasValue(attackDetails.effects, "Reveal target Initiative."),
        "Attack details should preserve Initiative reveal")

    local avoidDetails = action_registry.getChallengeActionDetails("avoid")
    assertEqual(avoidDetails.successTest,
        "equal or exceed engaged opponent Initiative, otherwise exceed non-engaged threat Initiative",
        "Avoid details should preserve the engaged tie threshold")

    local aidDetails = action_registry.getChallengeActionDetails("Aid Another")
    assertTrue(aidDetails.facedown, "Aid Another details should preserve facedown preparation")
    assertEqual(aidDetails.primaryValue, "card value + Cups",
        "Aid Another details should preserve Cups primary-turn value")

    local testFateDetails = action_registry.getChallengeActionDetails("test of fate")
    assertEqual(testFateDetails.primaryValue, "spend any card, then draw a separate minor-arcana test card",
        "Test Fate details should preserve the separate test-card draw")

    local vigilanceDetails = action_registry.getChallengeActionDetails("vigilance")
    assertEqual(vigilanceDetails.cardSuitRule, "same_suit_as_follow_up_action",
        "Vigilance details should preserve its same-suit exception")
    assertTrue(vigilanceDetails.facedown, "Vigilance details should preserve facedown play")

    actionReference.suitGroups[1].label = "mutated"
    assertEqual(action_registry.getChallengeActionReference().suitGroups[1].label, "Swords",
        "Challenge action reference getter should return copy-safe metadata")

    local aidDiscards = {}
    local bus = events.createEventBus()
    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
        playerDeck = {
            discard = function(_, card)
                aidDiscards[#aidDiscards + 1] = card
            end,
        },
    })

    local actor = base_entity.createEntity({
        id = "pc_favor",
        name = "Favor Tester",
        isPC = true,
        swords = 1,
        armorSlots = 0,
    })
    actor.resolve = 2

    local target = base_entity.createEntity({
        id = "npc_favor",
        name = "Favor Target",
        isPC = false,
        health = 3,
        defense = 0,
    })

    local revealTarget = base_entity.createEntity({
        id = "npc_explicit_initiative_reveal",
        name = "Explicit Initiative Reveal",
        isPC = false,
        health = 2,
        defense = 0,
    })
    local revealSlot = {
        card = { name = "Seven of Pentacles", value = 7, suit = constants.SUITS.PENTACLES },
        value = 7,
        revealed = false,
    }
    local revealedPayload = nil
    bus:on(events.EVENTS.INITIATIVE_REVEALED, function(data)
        if data.entity == revealTarget then
            revealedPayload = data
        end
    end)
    local explicitInitiativeAttack = resolver:resolve({
        actor = actor,
        target = revealTarget,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 7,
        challengeController = {
            getInitiativeSlot = function(_, entityId)
                if entityId == revealTarget.id then
                    return revealSlot
                end
                return nil
            end,
        },
    })
    assertTrue(explicitInitiativeAttack.success, "explicit target Initiative should still resolve the Attack")
    assertTrue(revealSlot.revealed,
        "opposed actions should reveal the target Initiative slot even when the value is supplied directly")
    assertTrue(revealedPayload and revealedPayload.explicitTargetInitiative,
        "explicit target Initiative reveal should emit an Initiative reveal event")

    local favored = resolver:resolve({
        actor = actor,
        target = target,
        card = { name = "Five of Swords", value = 5, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 9,
        spendResolveForFavor = true,
    })
    assertTrue(favored.success, "Resolve-spent favor should turn a melee miss into a hit")
    assertEqual(actor.resolve, 1, "Challenge Action favor should spend one Resolve")
    assertEqual(favored.baseTestValue, 6, "Challenge Action favor should retain base test value")
    assertEqual(favored.favor, true, "Resolve spend should grant action favor")
    assertEqual(favored.favorModifier, 3, "action favor should add +3")
    assertEqual(favored.testValue, 9, "action favor should modify test value")
    assertTrue(hasValue(favored.effects, "resolve_spent_for_favor"), "Resolve favor spend should be recorded")
    assertTrue(hasValue(favored.effects, "action_favor"), "action favor should be recorded")

    local faceActor = base_entity.createEntity({
        id = "pc_face_card_attack",
        name = "Face Card Attack",
        isPC = true,
        swords = 4,
    })
    local faceTarget = base_entity.createEntity({
        id = "npc_face_card_attack",
        name = "Face Card Target",
        isPC = false,
        health = 3,
        defense = 0,
    })
    local faceAttack = resolver:resolve({
        actor = faceActor,
        target = faceTarget,
        card = { name = "King of Swords", value = 14, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 10,
        weapon = { name = "Longsword", weaponType = "sword" },
    })
    assertTrue(faceAttack.success, "face-card Attack should still resolve normally")
    assertTrue(not faceAttack.isGreat, "ordinary Challenge Actions should not use Test Fate Great Success")
    assertEqual(faceAttack.damageDealt, 1, "face-card Attack should not add a legacy Great Success wound")

    local disfavored = resolver:resolve({
        actor = actor,
        target = target,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 9,
        disfavor = true,
    })
    assertTrue(not disfavored.success, "disfavor should turn a melee tie into a miss")
    assertEqual(disfavored.favor, false, "disfavor should be tracked as false favor state")
    assertEqual(disfavored.favorModifier, -3, "disfavor should subtract 3")
    assertEqual(disfavored.testValue, 6, "disfavor should modify test value")
    assertTrue(hasValue(disfavored.effects, "action_disfavor"), "action disfavor should be recorded")

    local greaterDoomFavorTarget = base_entity.createEntity({
        id = "npc_greater_doom_favor",
        name = "Greater Doom Favor Target",
        isPC = false,
        health = 3,
        defense = 0,
    })
    local greaterDoomFavor = resolver:resolve({
        actor = actor,
        target = greaterDoomFavorTarget,
        card = { name = "Five of Swords", value = 5, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 9,
        greaterDoomFavorCard = { name = "The Devil", value = 15, is_major = true },
    })
    assertTrue(greaterDoomFavor.success, "discarded greater doom favor should turn a melee miss into a hit")
    assertEqual(greaterDoomFavor.favor, true, "greater doom favor should be tracked as favor")
    assertEqual(greaterDoomFavor.favorModifier, 3, "greater doom favor should add +3")
    assertEqual(greaterDoomFavor.testValue, 9, "greater doom favor should modify test value")
    assertTrue(hasValue(greaterDoomFavor.effects, "greater_doom_favor"),
        "greater doom favor should report its source")
    assertTrue(hasValue(greaterDoomFavor.effects, "action_favor"),
        "greater doom favor should flow through the central favor effect")

    local canceledDisfavor = resolver:resolve({
        actor = actor,
        target = greaterDoomFavorTarget,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 9,
        disfavor = true,
        greaterDoomFavorCard = { name = "The Tower", value = 16, is_major = true },
    })
    assertTrue(canceledDisfavor.success, "greater doom favor should cancel one source of disfavor")
    assertEqual(canceledDisfavor.favor, nil, "canceled favor/disfavor should leave neutral favor state")
    assertEqual(canceledDisfavor.favorModifier, 0, "canceled favor/disfavor should not modify the action")
    assertTrue(hasValue(canceledDisfavor.effects, "greater_doom_favor"),
        "neutralized greater doom favor should still report the discarded doom")

    local invalidDoomFavor = resolver:resolve({
        actor = actor,
        target = greaterDoomFavorTarget,
        card = { name = "Five of Swords", value = 5, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 9,
        greaterDoomFavorCard = { name = "Temperance", value = 14, is_major = true },
    })
    assertTrue(not invalidDoomFavor.success, "lesser doom cards should not grant greater doom favor")
    assertTrue(hasValue(invalidDoomFavor.effects, "greater_doom_favor_requires_greater_doom"),
        "invalid greater doom favor should report the card gate")

    local aider = base_entity.createEntity({
        id = "pc_aid_trigger_aider",
        name = "Aid Trigger Aider",
        isPC = true,
        cups = 1,
    })
    local aided = base_entity.createEntity({
        id = "pc_aid_trigger_aided",
        name = "Aid Trigger Aided",
        isPC = true,
    })
    local intendedTarget = base_entity.createEntity({
        id = "npc_aid_trigger_target",
        name = "Aid Trigger Target",
        isPC = false,
        health = 3,
        defense = 0,
    })
    local wrongTarget = base_entity.createEntity({
        id = "npc_aid_wrong_target",
        name = "Aid Wrong Target",
        isPC = false,
        health = 3,
        defense = 0,
    })
    local aidCard = { name = "Four of Cups", value = 4, suit = constants.SUITS.CUPS }
    local selfAid = resolver:resolve({
        actor = aider,
        target = aider,
        card = { name = "Two of Cups", value = 2, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.AID,
    })
    assertTrue(not selfAid.success, "Aid Another should reject self-targeting")
    assertTrue(hasValue(selfAid.effects, "aid_self_blocked"),
        "self-targeted Aid Another should report the rulebook target gate")
    assertEqual(resolver.activeAids[aider.id], nil,
        "self-targeted Aid Another should not bank a facedown aid")

    local enemyAider = base_entity.createEntity({
        id = "npc_enemy_aid_trigger_aider",
        name = "Enemy Aid Trigger Aider",
        isPC = false,
        cups = 1,
    })
    local enemyAid = resolver:resolve({
        actor = enemyAider,
        target = aided,
        card = { name = "Three of Cups", value = 3, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.AID,
    })
    assertTrue(not enemyAid.success, "Aid Another should reject opposing-side targets")
    assertTrue(hasValue(enemyAid.effects, "aid_ally_required"),
        "opposing-side Aid Another should report the ally target gate")
    assertEqual(resolver.activeAids[aided.id], nil,
        "opposing-side Aid Another should not bank a facedown aid")

    local aid = resolver:resolve({
        actor = aider,
        target = aided,
        card = aidCard,
        type = action_resolver.ACTION_TYPES.AID,
        trigger = {
            type = action_resolver.ACTION_TYPES.MELEE,
            target = intendedTarget,
            objective = "Set up the melee strike against the marked foe.",
        },
    })
    assertTrue(aid.success, "Aid Another should bank a declared trigger action")
    assertEqual(aid.aid.triggerAction, action_resolver.ACTION_TYPES.MELEE,
        "Aid Another should record the declared trigger action")
    assertEqual(aid.aid.triggerTargetId, intendedTarget.id,
        "Aid Another should record the declared trigger target")
    assertEqual(resolver.activeAids[aided.id].val, 5, "Aid Another should bank card value plus Cups")
    assertEqual(resolver.activeAids[aided.id].card, aidCard, "Aid Another should keep the facedown card in play")
    assertEqual(#aidDiscards, 0, "Aid Another should not discard its facedown card when banked")

    local actionSequencer = require('ui.action_sequencer')
    local function getAidPopup(action, result, field)
        local sequencer = actionSequencer.createActionSequencer({ eventBus = events.createEventBus() })
        sequencer:queueActionSequence({
            action = action,
            result = result,
        })
        for _, step in ipairs(sequencer.currentSequence or {}) do
            if step.type == actionSequencer.STEP_TYPES.TEXT_POPUP and
               step.data and step.data.title == "Aid Another" and
               (field == nil or step.data[field]) then
                return step.data
            end
        end
        return nil
    end

    local bankedAidPopup = getAidPopup({
        actor = aider,
        target = aided,
        type = action_resolver.ACTION_TYPES.AID,
