    blindedArcher.inventory = inventory.createInventory()
    local blindBow = inventory.createItemFromTemplate("bow")
    blindedArcher.inventory:addItem(blindBow, inventory.LOCATIONS.HANDS)
    blindedArcher.ammo = 1
    local blindShot = resolver:resolve({
        actor = blindedArcher,
        target = target,
        weapon = blindBow,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MISSILE,
        targetInitiative = 1,
    })
    assertTrue(not blindShot.success, "Blind creatures should be unable to make missile attacks")
    assertTrue(hasValue(blindShot.effects, "action_blocked"), "blind missile attacks should be blocked")
    assertEqual(blindedArcher.ammo, 1, "blocked blind missile attacks should not spend ammo")

    local engagedArcher = base_entity.createEntity({
        id = "pc_engaged_missile",
        name = "Engaged Missile",
        isPC = true,
        swords = 3,
    })
    engagedArcher.is_engaged = true
    engagedArcher.inventory = inventory.createInventory()
    local engagedBow = inventory.createItemFromTemplate("bow")
    engagedArcher.inventory:addItem(engagedBow, inventory.LOCATIONS.HANDS)
    engagedArcher.ammo = 1
    local engagedShot = resolver:resolve({
        actor = engagedArcher,
        target = target,
        weapon = engagedBow,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MISSILE,
        targetInitiative = 1,
    })
    assertTrue(not engagedShot.success, "Engaged creatures should be unable to make missile attacks")
    assertTrue(hasValue(engagedShot.effects, "action_blocked"),
        "engaged missile attacks should be blocked before missile resolution")
    assertEqual(engagedArcher.ammo, 1, "blocked engaged missile attacks should not spend ammo")

    local knockedOutActor = base_entity.createEntity({
        id = "pc_knocked_out_action",
        name = "Knocked Out Action",
        isPC = true,
        swords = 3,
    })
    knockedOutActor.conditions.knocked_out = true
    local knockedOutAttack = resolver:resolve({
        actor = knockedOutActor,
        target = target,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 1,
    })
    assertTrue(not knockedOutAttack.success, "Knocked-out creatures should not take actions")
    assertTrue(hasValue(knockedOutAttack.effects, "action_blocked"),
        "knocked-out action attempts should be blocked")

    local deathsDoorActor = base_entity.createEntity({
        id = "pc_deaths_door_action",
        name = "Death's Door Action",
        isPC = true,
        swords = 3,
    })
    deathsDoorActor.conditions.deaths_door = true
    local deathsDoorAttack = resolver:resolve({
        actor = deathsDoorActor,
        target = target,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 1,
    })
    assertTrue(not deathsDoorAttack.success, "Death's Door creatures should not take actions")
    assertTrue(hasValue(deathsDoorAttack.effects, "action_blocked"),
        "Death's Door action attempts should be blocked")

    local deadActor = base_entity.createEntity({
        id = "pc_dead_action",
        name = "Dead Action",
        isPC = true,
        swords = 3,
    })
    deadActor.conditions.dead = true
    local deadAttack = resolver:resolve({
        actor = deadActor,
        target = target,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 1,
    })
    assertTrue(not deadAttack.success, "dead creatures should not take actions")
    assertTrue(hasValue(deadAttack.effects, "action_blocked"),
        "dead action attempts should be blocked")

    local rootedDodger = base_entity.createEntity({
        id = "pc_rooted_dodge",
        name = "Rooted Dodge",
        isPC = true,
        cups = 3,
    })
    rootedDodger.conditions.rooted = true
    local rootedDodge = resolver:resolve({
        actor = rootedDodger,
        card = { name = "Eight of Cups", value = 8, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.DODGE,
    })
    assertTrue(not rootedDodge.success, "Rooted creatures should be unable to Dodge")
    assertTrue(hasValue(rootedDodge.effects, "action_blocked"),
        "Rooted Dodge attempts should be blocked before preparing a defense")
    assertTrue(not rootedDodger.pendingDefense,
        "blocked Rooted Dodge should not prepare a facedown defense")

    local proneMover = base_entity.createEntity({
        id = "pc_prone_mover",
        name = "Prone Mover",
        isPC = true,
        pentacles = 3,
        zone = "near",
    })
    proneMover.conditions.prone = true
    for _, actionType in ipairs({
        action_resolver.ACTION_TYPES.AVOID,
        action_resolver.ACTION_TYPES.DASH,
        action_resolver.ACTION_TYPES.DODGE,
        action_resolver.ACTION_TYPES.MOVE,
    }) do
        local proneBlockedAction = resolver:resolve({
            actor = proneMover,
            card = { name = "Eight of Pentacles", value = 8, suit = constants.SUITS.PENTACLES },
            type = actionType,
            destinationZone = "far",
        })
        assertTrue(not proneBlockedAction.success,
            "Prone creatures should be unable to " .. tostring(actionType))
        assertTrue(hasValue(proneBlockedAction.effects, "action_blocked"),
            "Prone restricted actions should be blocked before resolution")
        assertEqual(proneMover.zone, "near",
            "blocked Prone movement should not change the actor's zone")
    end
    assertTrue(not proneMover.pendingDefense, "blocked Prone Dodge should not prepare a facedown defense")

    actor.resolve = 1
    local cancelled = resolver:resolve({
        actor = actor,
        target = target,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 9,
        disfavor = true,
        spendResolveForFavor = true,
    })
    assertTrue(cancelled.success, "Resolve favor should cancel disfavor back to the base melee tie")
    assertEqual(actor.resolve, 0, "canceling disfavor should still spend Resolve")
    assertEqual(cancelled.favor, nil, "favor and disfavor should cancel to neutral")
    assertEqual(cancelled.favorModifier, 0, "neutral favor state should not modify the test")
    assertEqual(cancelled.testValue, 9, "neutralized favor/disfavor should leave base test value")
    assertTrue(hasValue(cancelled.effects, "resolve_spent_for_favor"), "neutralizing disfavor should record Resolve spend")
    assertTrue(not hasValue(cancelled.effects, "action_favor"), "neutralized disfavor should not record action favor")
    assertTrue(not hasValue(cancelled.effects, "action_disfavor"), "neutralized disfavor should not record action disfavor")

    local houseActor = base_entity.createEntity({
        id = "pc_proud_house",
        name = "Proud House",
        isPC = true,
        wands = 2,
        talents = {
            proud_and_ancient = { mastered = true },
        },
    })
    houseActor.resolve = 1
    houseActor.house = "Crowell"
    houseActor.motto = "Crowell keeps the gate"
    local houseAlly = base_entity.createEntity({
        id = "pc_proud_house_ally",
        name = "Proud House Ally",
        isPC = true,
        swords = 1,
    })
    houseAlly.house = "Crowell"
    local otherHouse = base_entity.createEntity({
        id = "pc_other_house",
        name = "Other House",
        isPC = true,
    })
    otherHouse.house = "Mourn"
    local deafHouse = base_entity.createEntity({
        id = "pc_deaf_house",
        name = "Deaf House",
        isPC = true,
    })
    deafHouse.house = "Crowell"
    deafHouse.conditions.deafened = true

    local activeChallenge = { isActive = function() return true end }
    local warCryAction = {
        actor = houseActor,
        card = { name = "Six of Wands", value = 6, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        proudAndAncientWarCry = true,
        allEntities = { houseActor, houseAlly, otherHouse, deafHouse },
        challengeController = activeChallenge,
    }
    local warCry = resolver:resolve(warCryAction)
    assertTrue(warCry.success, "Proud and Ancient should cry the house motto during Challenges")
    assertEqual(houseActor.resolve, 0, "Proud and Ancient war cry should spend one Resolve")
    assertEqual(warCry.affectedCount, 2, "Proud and Ancient should affect the actor and same-house listeners")
    assertTrue(houseActor.nextActionFavor and houseAlly.nextActionFavor,
        "Proud and Ancient should grant next-action favor to same-house listeners")
    assertTrue(not otherHouse.nextActionFavor, "Proud and Ancient should not favor other houses")
    assertTrue(not deafHouse.nextActionFavor, "Proud and Ancient should not favor listeners who cannot hear")
    assertTrue(warCry.proudAndAncientWarCry ~= nil,
        "Proud and Ancient war cry should preserve presentation metadata")
    assertEqual(warCry.proudAndAncientWarCry.motto, "Crowell keeps the gate",
        "Proud and Ancient presentation metadata should preserve the motto")
    assertEqual(warCry.proudAndAncientWarCry.affectedCount, 2,
        "Proud and Ancient presentation metadata should preserve affected listeners")

    local warCryPopup = getActionSequencerPopup(warCryAction, warCry, function(data)
        return data.title == "Proud and Ancient"
    end)
    assertTrue(warCryPopup ~= nil, "Proud and Ancient war cry should queue an action-sequencer popup")
    assertEqual(warCryPopup.motto, "Crowell keeps the gate",
        "Proud and Ancient popup should preserve the cried motto")
    assertEqual(warCryPopup.affectedCount, 2,
        "Proud and Ancient popup should preserve the inspired listener count")

    local warCryTarget = base_entity.createEntity({
        id = "npc_war_cry_target",
        name = "War Cry Target",
        isPC = false,
        health = 2,
        defense = 0,
    })
    local allyAttack = resolver:resolve({
        actor = houseAlly,
        target = warCryTarget,
        card = { name = "Five of Swords", value = 5, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 9,
    })
    assertTrue(allyAttack.success, "Proud and Ancient next-action favor should turn a miss into a hit")
    assertTrue(hasValue(allyAttack.effects, "proud_and_ancient_favor"),
        "Proud and Ancient next-action favor should be recorded")
    assertTrue(not houseAlly.nextActionFavor, "Proud and Ancient favor should be consumed by the next action")

    local quietHouse = base_entity.createEntity({
        id = "pc_quiet_house",
        name = "Quiet House",
        isPC = true,
        talents = {
            proud_and_ancient = { mastered = true },
        },
    })
    quietHouse.resolve = 1
    local noChallengeCry = resolver:resolve({
        actor = quietHouse,
        card = { name = "Six of Wands", value = 6, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        proudAndAncientWarCry = true,
    })
    assertTrue(not noChallengeCry.success, "Proud and Ancient war cry should require an active Challenge")
    assertEqual(quietHouse.resolve, 1, "failed Proud and Ancient challenge gate should not spend Resolve")

    local woundedHouse = base_entity.createEntity({
        id = "pc_wounded_house",
        name = "Wounded House",
        isPC = true,
        talents = {
            proud_and_ancient = { mastered = true, wounded = true },
        },
    })
    woundedHouse.resolve = 1
    local woundedCry = resolver:resolve({
        actor = woundedHouse,
        card = { name = "Six of Wands", value = 6, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        proudAndAncientWarCry = true,
        challengeController = activeChallenge,
    })
    assertTrue(not woundedCry.success, "Wounded Proud and Ancient should block the war cry")
    assertEqual(woundedHouse.resolve, 1, "wounded Proud and Ancient should not spend Resolve")

    local emptyActor = base_entity.createEntity({
        id = "pc_empty_resolve",
        name = "Empty Resolve",
        isPC = true,
        swords = 1,
    })
    emptyActor.resolve = 0
    local blocked = resolver:resolve({
        actor = emptyActor,
        target = target,
        card = { name = "Five of Swords", value = 5, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 9,
        spendResolveForFavor = true,
    })
    assertTrue(not blocked.success, "Resolve favor should block if Resolve is missing")
    assertTrue(hasValue(blocked.effects, "resolve_missing"), "missing Resolve should be recorded")
end

local function checkTrivialActionExamples()
    local resolver = action_resolver.createActionResolver({ eventBus = events.createEventBus() })
    local actor = base_entity.createEntity({
        id = "pc_trivial_actor",
        name = "Trivial Actor",
        isPC = true,
        zone = "near",
    })
    actor.inventory = inventory.createInventory()

    local controller = challenge_controller.createChallengeController({
        eventBus = events.createEventBus(),
    })
    controller.state = challenge_controller.STATES.AWAITING_ACTION
    controller.currentRound = 1
    controller.currentCount = 4
    controller.activeEntity = actor
    controller.actedThisRound = {}
    local freeMove = resolver:resolve({
        actor = actor,
        type = action_resolver.ACTION_TYPES.FREE_ACTION,
        freeAction = "move_within_zone",
        position = "behind the toppled table",
        challengeController = controller,
    })
    assertTrue(freeMove.success, "free actions should not require a Challenge card")
    assertTrue(hasValue(freeMove.effects, "free_within_zone_move"),
        "within-zone free movement should report its rulebook effect")
    assertEqual(actor.zone, "near", "free movement should keep the actor in the same zone")
    assertEqual(actor.positionInZone, "behind the toppled table",
        "within-zone free movement should preserve position detail")
    assertTrue(not controller.actedThisRound[actor.id],
        "free actions should not spend the actor's Challenge turn")
    assertEqual(controller.state, challenge_controller.STATES.AWAITING_ACTION,
        "free actions should leave the active turn waiting for a real action")

    local freeTalk = resolver:resolve({
        actor = actor,
        type = action_resolver.ACTION_TYPES.FREE_ACTION,
        freeAction = "talk",
        speech = "Hold the line!",
        challengeController = controller,
    })
    assertTrue(freeTalk.success, "talking in character should resolve as a cardless free action")
    assertEqual(freeTalk.speech, "Hold the line!", "free speech should preserve declared speech text")
    assertTrue(hasValue(freeTalk.effects, "free_talk"), "free speech should report its rulebook effect")

    actor.conditions.restrained = true
    local restrainedMove = resolver:resolve({
        actor = actor,
        type = action_resolver.ACTION_TYPES.FREE_ACTION,
        freeAction = "reposition",
        position = "near the door",
        challengeController = controller,
    })
    assertTrue(not restrainedMove.success, "restrained actors should not move freely within a zone")
    assertTrue(hasValue(restrainedMove.effects, "free_movement_restrained"),
        "restrained free movement should report the restraint")
    assertEqual(actor.positionInZone, "behind the toppled table",
        "blocked free movement should not update position detail")
    actor.conditions.restrained = false

    actor.conditions.silenced = true
    local silencedTalk = resolver:resolve({
        actor = actor,
        type = action_resolver.ACTION_TYPES.FREE_ACTION,
        freeAction = "talk",
        speech = "No sound",
        challengeController = controller,
    })
    assertTrue(not silencedTalk.success, "Silenced actors should not speak as a free action")
    assertTrue(hasValue(silencedTalk.effects, "free_speech_blocked"),
        "blocked free speech should report Silence")
    actor.conditions.silenced = false

    local dropped = resolver:resolve({
        actor = actor,
        card = { name = "Two of Wands", value = 2, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.TRIVIAL_ACTION,
        trivialAction = "drop_prone",
    })
    assertTrue(dropped.success, "Trivial Action should allow dropping prone with any card")
    assertTrue(actor.conditions.prone, "dropping prone should mark the actor Prone")
    assertTrue(hasValue(dropped.effects, "dropped_prone"), "dropping prone should report a concrete trivial effect")

    local actionSequencer = require('ui.action_sequencer')
    local function getTrivialActionPopup(action, result)
        local sequencer = actionSequencer.createActionSequencer({ eventBus = events.createEventBus() })
        sequencer:queueActionSequence({
            action = action,
            result = result,
        })
        for _, step in ipairs(sequencer.currentSequence or {}) do
            if step.type == actionSequencer.STEP_TYPES.TEXT_POPUP and
               step.data and step.data.title == "Trivial Action" then
                return step.data
            end
        end
        return nil
    end

    local droppedPopup = getTrivialActionPopup({
        actor = actor,
        type = action_resolver.ACTION_TYPES.TRIVIAL_ACTION,
        trivialAction = "drop_prone",
    }, dropped)
    assertTrue(droppedPopup ~= nil, "dropping prone should queue a visible Trivial Action popup")
    assertTrue(droppedPopup.droppedProne, "drop-prone popup should preserve the concrete trivial effect")
    assertEqual(droppedPopup.target, actor, "drop-prone popup should point at the prone actor")

    local blockedMove = resolver:resolve({
        actor = actor,
        card = { name = "Three of Pentacles", value = 3, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.MOVE,
        destinationZone = "far",
    })
    assertTrue(not blockedMove.success, "actor who dropped prone should obey Prone movement restrictions")

    actor.conditions.prone = false
    local door = { id = "iron_door", state = "closed" }
    local opened = resolver:resolve({
        actor = actor,
        target = door,
        card = { name = "Four of Cups", value = 4, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.TRIVIAL_ACTION,
        trivialAction = "open_door",
    })
    assertTrue(opened.success, "Trivial Action should handle opening a simple door")
    assertTrue(door.isOpen and door.open and door.state == "open", "opening a door should update target state")
    assertTrue(hasValue(opened.effects, "opened"), "opening a door should report a concrete trivial effect")
    local openedPopup = getTrivialActionPopup({
        actor = actor,
        target = door,
        type = action_resolver.ACTION_TYPES.TRIVIAL_ACTION,
        trivialAction = "open_door",
    }, opened)
    assertTrue(openedPopup ~= nil, "opening a door should queue a visible Trivial Action popup")
    assertTrue(openedPopup.opened, "opened popup should preserve the concrete trivial effect")
    assertEqual(openedPopup.target, door, "opened popup should preserve the opened target")

    local lever = { id = "moon_lever", state = "idle" }
    local activated = resolver:resolve({
        actor = actor,
        target = lever,
        card = { name = "Five of Swords", value = 5, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.TRIVIAL_ACTION,
        trivialAction = "throw_lever",
    })
    assertTrue(activated.success, "Trivial Action should handle throwing a simple lever")
    assertTrue(lever.activated and lever.state == "activated", "throwing a lever should update target state")
    assertTrue(hasValue(activated.effects, "activated"), "throwing a lever should report a concrete trivial effect")
    local activatedPopup = getTrivialActionPopup({
        actor = actor,
        target = lever,
        type = action_resolver.ACTION_TYPES.TRIVIAL_ACTION,
        trivialAction = "throw_lever",
    }, activated)
    assertTrue(activatedPopup ~= nil, "throwing a lever should queue a visible Trivial Action popup")
    assertTrue(activatedPopup.activated, "activated popup should preserve the concrete trivial effect")
    assertEqual(activatedPopup.target, lever, "activated popup should preserve the activated target")

    local floor = { id = "trivial_floor", groundItems = {} }
    local fallenTorch = inventory.createItemFromTemplate("torch")
    fallenTorch.onGround = true
    fallenTorch.location = "ground"
    floor.groundItems[#floor.groundItems + 1] = fallenTorch
    local pickedUp = resolver:resolve({
        actor = actor,
        target = floor,
        card = { name = "Six of Pentacles", value = 6, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.TRIVIAL_ACTION,
        trivialAction = "pick_up_item",
        itemId = fallenTorch.id,
    })
    assertTrue(pickedUp.success, "Trivial Action should handle picking up an item from the ground")
    assertEqual(pickedUp.pickedUpItem, fallenTorch, "ground pickup should report the picked-up item")
    assertEqual(#floor.groundItems, 0, "ground pickup should remove the item from the ground-item list")
    assertEqual(select(2, actor.inventory:findItem(fallenTorch.id)), inventory.LOCATIONS.HANDS,
        "ground pickup should place the item in hand by default")
    assertTrue(not fallenTorch.dropped and not fallenTorch.onGround and not fallenTorch.location,
        "ground pickup should clear ground markers")
    assertTrue(hasValue(pickedUp.effects, "ground_item_picked_up"),
        "ground pickup should report a concrete trivial effect")
    local pickupPopup = getTrivialActionPopup({
        actor = actor,
        target = floor,
        type = action_resolver.ACTION_TYPES.TRIVIAL_ACTION,
        trivialAction = "pick_up_item",
        item = fallenTorch,
    }, pickedUp)
    assertTrue(pickupPopup ~= nil, "ground pickup should queue a visible Trivial Action popup")
    assertTrue(pickupPopup.pickedUp, "pickup popup should preserve the concrete trivial effect")
    assertEqual(pickupPopup.item, fallenTorch, "pickup popup should preserve the picked-up item")
    assertEqual(pickupPopup.pickupLocation, inventory.LOCATIONS.HANDS,
        "pickup popup should preserve the inventory destination")

    local droppedSword = inventory.createItemFromTemplate("longsword")
    droppedSword.dropped = true
    actor.droppedItems = { droppedSword }
    local blockedDroppedPickup = resolver:resolve({
        actor = actor,
        card = { name = "Seven of Cups", value = 7, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.TRIVIAL_ACTION,
        trivialAction = "pick_up_item",
        droppedItem = droppedSword,
    })
    assertTrue(not blockedDroppedPickup.success,
        "Trivial Action should not retrieve items dropped by Disarm-style effects")
    assertTrue(hasValue(blockedDroppedPickup.effects, "trivial_pickup_requires_recover"),
        "dropped-item pickup should report the Recover requirement")

    local opposedTarget = base_entity.createEntity({
        id = "npc_trivial_opponent",
        name = "Trivial Opponent",
        isPC = false,
        zone = "near",
    })
    local contestedTrivial = resolver:resolve({
        actor = actor,
        target = opposedTarget,
        card = { name = "Eight of Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.TRIVIAL_ACTION,
        trivialAction = "snatch_badge",
    })
    assertTrue(not contestedTrivial.success,
        "Trivial Action should reject actions aimed at opposing combatants")
    assertTrue(hasValue(contestedTrivial.effects, "trivial_action_contested"),
        "contested Trivial Action should report the uncontested-only rule")

    local contestedDoor = resolver:resolve({
        actor = actor,
        target = door,
        card = { name = "Nine of Cups", value = 9, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.TRIVIAL_ACTION,
        trivialAction = "open_door",
        contested = true,
    })
    assertTrue(not contestedDoor.success,
        "Trivial Action should reject explicitly contested room interactions")
    assertTrue(hasValue(contestedDoor.effects, "trivial_action_contested"),
        "explicitly contested Trivial Action should report the uncontested-only rule")
end

local function checkBanterSocialIntentAndPreferences()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local actor = base_entity.createEntity({
        id = "pc_banter",
        name = "Banterer",
        isPC = true,
        wands = 3,
    })

    local target = base_entity.createEntity({
        id = "npc_social",
        name = "Social Target",
        isPC = false,
        baseMorale = 10,
        health = 2,
        defense = 0,
        disposition = "trust",
    })
    target.social = {
        likes = { "respect" },
        dislikes = { "lies" },
    }

    local neutralMoraleTarget = base_entity.createEntity({
        id = "npc_neutral_morale_banter",
        name = "Neutral Morale Target",
        isPC = false,
        baseMorale = 10,
        health = 2,
        defense = 0,
        disposition = "distaste",
    })
    local neutralMorale = resolver:resolve({
        actor = actor,
        target = neutralMoraleTarget,
        card = { name = "King of Wands", value = 14, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.BANTER,
        banterIntent = "frighten",
        moraleSituation = "neutral",
    })
    assertTrue(not neutralMorale.success,
        "neutral Morale band should use the rulebook Morale 18 score")
    assertEqual(neutralMorale.targetMorale, 18,
        "neutral Morale band should override lower authored base Morale")
    assertEqual(neutralMorale.difficulty, 18,
        "neutral Morale band should set Banter difficulty before disposition modifiers")
    assertTrue(hasValue(neutralMorale.effects, "morale_neutral"),
        "neutral Morale band should be reported")
    assertEqual(neutralMorale.banter.targetMorale, 18,
        "Banter result metadata should preserve the target Morale")
    do
        local popup = getActionSequencerPopup({
            actor = actor,
            target = neutralMoraleTarget,
            type = action_resolver.ACTION_TYPES.BANTER,
