        id = "npc_desiccated_parley_living",
        name = "Living Parley Target",
        isPC = false,
        baseMorale = 8,
        health = 2,
        defense = 0,
        disposition = "distaste",
        dispositionSeverity = 2,
    })
    local corpseParley = resolver:resolve({
        actor = corpseSpeaker,
        target = livingParleyTarget,
        card = { name = "Eight of Cups", value = 8, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.PARLEY,
    })
    assertTrue(not corpseParley.success,
        "desiccated-corpse Malediction should make living GM characters hostile to Parley")
    assertEqual(corpseParley.socialModifier, -3,
        "desiccated-corpse Parley should apply social disfavor")
    assertTrue(hasValue(corpseParley.effects, "desiccated_corpse_hostility"),
        "desiccated-corpse Parley disfavor should be reported")

    local undeadParleyTarget = base_entity.createEntity({
        id = "npc_desiccated_parley_undead",
        name = "Undead Parley Target",
        isPC = false,
        baseMorale = 8,
        health = 2,
        defense = 0,
        disposition = "distaste",
        dispositionSeverity = 2,
    })
    undeadParleyTarget.tags = { "undead" }
    local undeadParley = resolver:resolve({
        actor = corpseSpeaker,
        target = undeadParleyTarget,
        card = { name = "Eight of Cups", value = 8, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.PARLEY,
    })
    assertTrue(undeadParley.success,
        "desiccated-corpse Parley hostility should not apply against undead targets")
    assertTrue(not hasValue(undeadParley.effects, "desiccated_corpse_hostility"),
        "undead Parley targets should not record desiccated-corpse hostility")

    local tylwythSpeaker = base_entity.createEntity({
        id = "pc_tylwyth_parley",
        name = "Tylwyth Parley Speaker",
        isPC = true,
        cups = 3,
    })
    tylwythSpeaker.languageLocked = "tylwyth"
    tylwythSpeaker.speaksGibberishToNonTylwyth = true
    local uncomprehendingTarget = base_entity.createEntity({
        id = "npc_no_tylwyth_parley",
        name = "No Tylwyth Parley Target",
        isPC = false,
        baseMorale = 8,
        health = 2,
        defense = 0,
        disposition = "distaste",
        dispositionSeverity = 2,
    })
    local gibberishParley = resolver:resolve({
        actor = tylwythSpeaker,
        target = uncomprehendingTarget,
        card = { name = "Eight of Cups", value = 8, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.PARLEY,
    })
    assertTrue(not gibberishParley.success,
        "Tylwyth-only Malediction should block Parley when the target lacks the language")
    assertTrue(hasValue(gibberishParley.effects, "language_locked_gibberish"),
        "Tylwyth-only Parley block should report gibberish")
    assertEqual(uncomprehendingTarget.disposition, "distaste",
        "gibberish Parley should not shift Disposition")

    local tylwythTarget = base_entity.createEntity({
        id = "npc_tylwyth_parley",
        name = "Tylwyth Parley Target",
        isPC = false,
        baseMorale = 8,
        health = 2,
        defense = 0,
        disposition = "distaste",
        dispositionSeverity = 2,
    })
    tylwythTarget.understandsLanguages = { tylwyth = true }
    local translatedParley = resolver:resolve({
        actor = tylwythSpeaker,
        target = tylwythTarget,
        card = { name = "Eight of Cups", value = 8, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.PARLEY,
    })
    assertTrue(translatedParley.success,
        "Tylwyth-only Parley should work when the target understands Tylwyth")
    assertTrue(not hasValue(translatedParley.effects, "language_locked_gibberish"),
        "shared Tylwyth should avoid the Parley gibberish block")

    local rhymeSpeaker = base_entity.createEntity({
        id = "pc_rhyme_parley",
        name = "Rhyming Parley Speaker",
        isPC = true,
        cups = 3,
    })
    rhymeSpeaker.malediction = {
        active = true,
        curse = {
            flags = {
                mustSpeakInRhymes = true,
            },
        },
    }
    local rhymeTarget = base_entity.createEntity({
        id = "npc_rhyme_parley",
        name = "Rhyme Parley Target",
        isPC = false,
        baseMorale = 8,
        health = 2,
        defense = 0,
        disposition = "distaste",
        dispositionSeverity = 2,
    })
    local unrhymedParley = resolver:resolve({
        actor = rhymeSpeaker,
        target = rhymeTarget,
        card = { name = "Eight of Cups", value = 8, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.PARLEY,
    })
    assertTrue(not unrhymedParley.success,
        "Speak-in-rhymes Malediction should block Parley until the speech rhymes")
    assertTrue(hasValue(unrhymedParley.effects, "rhymed_speech_required"),
        "unrhymed Parley should request rhymed speech")
    assertTrue(hasValue(unrhymedParley.effects, "speak_in_rhymes"),
        "unrhymed Parley should report the Malediction source")
    assertEqual(rhymeTarget.disposition, "distaste",
        "unrhymed Parley should not shift Disposition")

    local rhymedParley = resolver:resolve({
        actor = rhymeSpeaker,
        target = rhymeTarget,
        card = { name = "Eight of Cups", value = 8, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.PARLEY,
        rhymingCouplets = true,
    })
    assertTrue(rhymedParley.success,
        "Speak-in-rhymes Malediction should allow Parley once the speech rhymes")
    assertTrue(not hasValue(rhymedParley.effects, "rhymed_speech_required"),
        "rhymed Parley should not report the rhyme block")
end

local function checkGuardianRoomSocialEncounterOutcomes()
    local guardianBlueprint = nil
    for _, room in ipairs(tomb_data.data.rooms) do
        if room.id == "118_chamber_of_vigilant" then
            guardianBlueprint = room
            break
        end
    end
    assertTrue(guardianBlueprint ~= nil, "Tomb Guardian room blueprint should be present")

    local function createFixture()
        local bus = events.createEventBus()
        local resolvedEvents = {}
        bus:on(events.EVENTS.ROOM_SOCIAL_ENCOUNTER_RESOLVED, function(data)
            resolvedEvents[#resolvedEvents + 1] = data
        end)

        local manager = room_manager.createRoomManager({ eventBus = bus })
        local room = room_manager.createRoomInstance(guardianBlueprint, guardianBlueprint.id)
        manager:registerRoom(room)

        local resolver = action_resolver.createActionResolver({
            eventBus = bus,
            roomManager = manager,
        })

        local actor = base_entity.createEntity({
            id = "pc_guardian_speaker",
            name = "Guardian Speaker",
            isPC = true,
            wands = 6,
            cups = 6,
            location = room.id,
        })
        actor.inventory = inventory.createInventory()

        local guardian = entity_factory.createEntity("tomb_guardian_spirit", {
            location = room.id,
        })
        guardian.id = "tomb_guardian"
        guardian.location = room.id

        return resolver, room, actor, guardian, resolvedEvents, manager
    end

    local roomInstance = room_manager.createRoomInstance(guardianBlueprint, guardianBlueprint.id)
    assertEqual(#roomInstance.zones, 3, "room instances should preserve authored room zones")
    assertTrue(roomInstance.socialEncounter ~= nil, "room instances should preserve social encounter procedures")
    assertTrue(roomInstance.socialEncounter.outcomes.trust_success ~= nil,
        "Guardian social outcomes should be available at runtime")
    roomInstance.features[1].encounter.count = 99
    assertEqual(guardianBlueprint.features[1].encounter.count, 1,
        "room feature procedure data should be deep-copied per instance")

    local offeringResolver, offeringRoom, offeringActor, offeringGuardian, _, offeringManager = createFixture()
    offeringGuardian.disposition = "distaste"
    offeringGuardian.dispositionSeverity = 2
    local offering = offeringManager:resolveSocialFeatureProcedure(
        offeringRoom.id,
        "ancient_altar",
        "make_offering",
        offeringActor
    )
    assertTrue(offering.success, "Guardian altar should accept an offering as a social procedure")
    assertTrue(hasValue(offering.effects, "room_social_offering_prepared"),
        "offering should prepare a room social disposition effect")
    assertEqual(#offeringManager:getSocialPreparedEffects(offeringRoom.id), 1,
        "offering should persist a prepared social effect on the room")
    local offeringBanter = offeringResolver:resolve({
        actor = offeringActor,
        target = offeringGuardian,
        card = { name = "King of Wands", value = 14, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.BANTER,
        socialApproach = "respect",
        banterIntent = "trust",
        roomId = offeringRoom.id,
    })
    assertTrue(hasValue(offeringBanter.effects, "room_social_feature_disposition"),
        "prepared offerings should shift Guardian Disposition during social resolution")
    assertEqual(offeringGuardian.disposition, "trust",
        "Guardian offering should create the authored positive Disposition")

    local loreResolver, loreRoom, loreActor, loreGuardian, _, loreManager = createFixture()
    local lore = loreManager:resolveSocialFeatureProcedure(
        loreRoom.id,
        "inscribed_tablets",
        "study_lore",
        loreActor
    )
    assertTrue(lore.success, "Guardian tablets should support a study-lore social procedure")
    assertTrue(hasValue(lore.effects, "room_social_lore_prepared"),
        "tablet study should prepare a social favor record")
    assertTrue(loreActor.discoveredLore and loreActor.discoveredLore.tomb_history,
        "tablet study should mark the actor's tomb-history lore")
    local loreBanter = loreResolver:resolve({
        actor = loreActor,
        target = loreGuardian,
        card = { name = "King of Wands", value = 14, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.BANTER,
        banterIntent = "trust",
        roomId = loreRoom.id,
    })
    assertTrue(loreBanter.success, "prepared tablet lore should turn the edge Banter into a success")
    assertEqual(loreBanter.roomSocialModifier, 2,
        "tablet lore should apply the authored social modifier")
    assertTrue(hasValue(loreBanter.effects, "room_social_feature_favor"),
        "tablet lore should report social feature favor")

    local resolver, room, actor, guardian, resolvedEvents = createFixture()
    local trust = resolver:resolve({
        actor = actor,
        target = guardian,
        card = { name = "King of Wands", value = 14, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.BANTER,
        socialApproach = "respect",
        banterIntent = "trust",
        roomId = room.id,
    })
    assertTrue(trust.success, "respectful Guardian Banter should resolve")
    assertEqual(guardian.disposition, "trust", "trust-directed Guardian Banter should keep Trust")
    assertEqual(guardian.dispositionSeverity, 3, "trust-directed Guardian Banter should intensify Trust")
    assertTrue(hasValue(trust.effects, "room_social_trust_success"),
        "intense positive Guardian outcome should resolve the authored trust success")
    assertTrue(hasValue(trust.effects, "room_social_secret_revealed"),
        "Guardian trust success should reveal the authored secret passage")
    assertTrue(room.secretPassageRevealed, "Guardian trust success should mark the room secret passage revealed")
    assertTrue(trust.rewardGranted, "Guardian trust success should grant the authored blessing")
    local blessing = actor.inventory:findItemByPredicate(function(item)
        return item.templateId == "guardian_blessing"
    end)
    assertTrue(blessing ~= nil, "Guardian blessing should be placed in the actor inventory")
    assertEqual(#resolvedEvents, 1, "Guardian trust success should emit one room social event")
    assertEqual(resolvedEvents[1].outcome, "trust_success",
        "room social event should report the trust_success outcome")

    local fearResolver, fearRoom, fearActor, fearGuardian = createFixture()
    local fear = fearResolver:resolve({
        actor = fearActor,
        target = fearGuardian,
        card = { name = "King of Wands", value = 14, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.BANTER,
        socialApproach = "respect",
        banterIntent = "frighten",
        roomId = fearRoom.id,
    })
    assertTrue(fear.success, "fear-directed Guardian Banter should resolve")
    assertEqual(fear.roomSocialEncounter.outcome, "fear_success",
        "Guardian fear outcome should use the authored retreat path")
    assertTrue(fear.guardianRetreats, "Guardian fear outcome should mark retreat")
    assertTrue(fearGuardian.retreated, "Guardian fear outcome should mark the target retreated")

    local angerResolver, angerRoom, angerActor, angerGuardian = createFixture()
    angerGuardian.disposition = "distaste"
    angerGuardian.dispositionSeverity = 2
    local anger = angerResolver:resolve({
        actor = angerActor,
        target = angerGuardian,
        card = { name = "Ace of Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.PARLEY,
        roomId = angerRoom.id,
    })
    assertTrue(not anger.success, "failed Guardian Parley should fail the social test")
    assertEqual(anger.roomSocialEncounter.outcome, "anger_combat",
        "Guardian anger outcome should use the authored combat escalation path")
    assertTrue(anger.triggersCombat, "Guardian anger outcome should flag combat transition")
    assertTrue(angerGuardian.socialCombatTriggered, "Guardian anger outcome should mark the target hostile")
end

local function checkStartingDispositionFromMinorDiscard()
    local mapping = {
        { value = 2, expected = "anger" },
        { value = 4, expected = "distaste" },
        { value = 6, expected = "sadness" },
        { value = 8, expected = "joy" },
        { value = 10, expected = "surprise" },
        { value = 12, expected = "trust" },
        { value = 14, expected = "fear" },
    }

    for _, item in ipairs(mapping) do
        local result, severity = disposition.dispositionFromMinorDiscard({
            name = "Disposition Test",
            value = item.value,
            suit = constants.SUITS.CUPS,
        })
        assertEqual(result, item.expected,
            "minor discard value " .. tostring(item.value) .. " should map to rulebook starting Disposition")
        assertEqual(severity, 2, "random starting Disposition should start at basic severity")
    end

    local randomNPC = entity_factory.createEntity("small_ooze", {
        playerDeck = {
            peekDiscard = function()
                return { name = "Queen of Cups", value = 13, suit = constants.SUITS.CUPS }
            end,
        },
        minorDiscardCard = { name = "Two of Wands", value = 2, suit = constants.SUITS.WANDS },
    })
    assertEqual(randomNPC.disposition, "fear", "NPCs without authored Disposition should use the discard-card table")
    assertEqual(randomNPC.dispositionSeverity, 2, "discard-card Disposition should use basic severity")

    local authoredNPC = entity_factory.createEntity("tomb_guardian_spirit", {
        minorDiscardCard = { name = "Queen of Cups", value = 13, suit = constants.SUITS.CUPS },
    })
    assertEqual(authoredNPC.disposition, "trust", "authored starting Disposition should override random discard mapping")
end

local function checkRoughhouseFacade()
    local roughhouseDef = action_registry.getAction("roughhouse")
    assertTrue(roughhouseDef ~= nil, "canonical Roughhouse action should exist")
    assertTrue(roughhouseDef.roughhouseEffects ~= nil, "Roughhouse should advertise effect choices")

    local bus = events.createEventBus()
    local zoneRegistry = zone_system.createZoneRegistry({ eventBus = bus })
    zoneRegistry:setRoomZones(buildLinearZones())

    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
        zoneSystem = zoneRegistry,
    })

    local actor = base_entity.createEntity({
        id = "pc_roughhouse",
        name = "Roughhouser",
        isPC = true,
        pentacles = 3,
    })
    actor.zone = "A"

    local target = base_entity.createEntity({
        id = "npc_roughhouse",
        name = "Target",
        isPC = false,
        health = 2,
        defense = 0,
    })
    target.zone = "A"
    zoneRegistry:placeEntity(actor.id, actor.zone)
    zoneRegistry:placeEntity(target.id, target.zone)
    resolver:formEngagement(actor, target)
    assertTrue(resolver:areEngaged(actor, target), "setup should engage Roughhouse participants")

    local tripAction = {
        actor = actor,
        card = { name = "Pentacles", value = 7, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "trip",
        target = target,
        targetInitiative = 5,
        allEntities = { actor, target },
    }
    local trip = resolver:resolve(tripAction)
    assertTrue(trip.success, "Roughhouse trip should beat Initiative")
    assertEqual(trip.roughhouseEffect, "trip", "Roughhouse should record chosen trip effect")
    assertTrue(trip.roughhouse and trip.roughhouse.effect == "trip",
        "Roughhouse trip should preserve effect metadata")
    assertEqual(trip.roughhouse.actionValue, 10,
        "Roughhouse trip metadata should preserve the action value")
    assertEqual(trip.roughhouse.targetInitiative, 5,
        "Roughhouse trip metadata should preserve target Initiative")
    assertTrue(target.conditions.prone, "Roughhouse trip should make target prone")
    assertTrue(not resolver:areEngaged(actor, target), "Trip should immediately disengage target")
    do
        local roughhousePopup = getActionSequencerPopup(tripAction, trip, function(data)
            return data.title == "Roughhouse"
        end)
        assertTrue(roughhousePopup ~= nil, "Roughhouse trip should queue a visible popup")
        assertEqual(roughhousePopup.roughhouseEffect, "trip",
            "Roughhouse trip popup should preserve the effect")
        assertEqual(roughhousePopup.actionValue, 10,
            "Roughhouse trip popup should preserve the action value")
        assertEqual(roughhousePopup.targetInitiative, 5,
            "Roughhouse trip popup should preserve target Initiative")
        assertTrue(roughhousePopup.prone,
            "Roughhouse trip popup should report the prone outcome")
    end

    target.conditions.prone = false
    resolver:formEngagement(actor, target)
    local rootAction = {
        actor = actor,
        card = { name = "Pentacles", value = 7, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "root",
        target = target,
        targetInitiative = 5,
        allEntities = { actor, target },
    }
    local root = resolver:resolve(rootAction)
    assertTrue(root.success, "Roughhouse root should beat Initiative")
    assertEqual(root.roughhouseEffect, "root", "Roughhouse should record chosen root effect")
    assertTrue(root.roughhouse and root.roughhouse.effect == "root",
        "Roughhouse root should preserve effect metadata")
    assertTrue(target.conditions.rooted, "Roughhouse root should root target")
    assertTrue(not resolver:areEngaged(actor, target), "Root should immediately disengage target")
    do
        local roughhousePopup = getActionSequencerPopup(rootAction, root, function(data)
            return data.title == "Roughhouse"
        end)
        assertTrue(roughhousePopup ~= nil, "Roughhouse root should queue a visible popup")
        assertEqual(roughhousePopup.roughhouseEffect, "root",
            "Roughhouse root popup should preserve the effect")
        assertTrue(roughhousePopup.rooted,
            "Roughhouse root popup should report the rooted outcome")
    end

    local tieTarget = base_entity.createEntity({
        id = "npc_roughhouse_tie",
        name = "Tie Target",
        isPC = false,
        health = 2,
        defense = 0,
    })
    local tieTrip = resolver:resolve({
        actor = actor,
        card = { name = "Seven of Pentacles", value = 7, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "trip",
        target = tieTarget,
        targetInitiative = 10,
        allEntities = { actor, tieTarget },
    })
    assertTrue(tieTrip.success, "Roughhouse ties should succeed against unshielded targets")
    assertTrue(tieTarget.conditions.prone,
        "successful tied Roughhouse should apply the chosen effect")

    local shieldTieTarget = base_entity.createEntity({
        id = "npc_roughhouse_shield_tie",
        name = "Shield Tie Target",
        isPC = false,
        health = 2,
        defense = 0,
    })
    shieldTieTarget.inventory = inventory.createInventory()
    shieldTieTarget.inventory:addItem(inventory.createItemFromTemplate("shield_light"), inventory.LOCATIONS.HANDS)
    local blockedTieTrip = resolver:resolve({
        actor = actor,
        card = { name = "Seven of Pentacles", value = 7, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "trip",
        target = shieldTieTarget,
        targetInitiative = 10,
        allEntities = { actor, shieldTieTarget },
    })
    assertTrue(not blockedTieTrip.success,
        "wielded shields should make tied Roughhouse actions fail")
    assertTrue(not shieldTieTarget.conditions.prone,
        "failed shield tie should not apply the Roughhouse effect")

    resolver:formEngagement(actor, target)
    local displaceAction = {
        actor = actor,
        card = { name = "Pentacles", value = 7, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "displace",
        target = target,
        targetInitiative = 5,
        destinationZone = "B",
        allEntities = { actor, target },
    }
    local displace = resolver:resolve(displaceAction)
    assertTrue(displace.success, "Roughhouse displace should beat Initiative")
    assertEqual(target.zone, "B", "Roughhouse displace should move target")
    assertEqual(displace.roughhouse.oldZone, "A",
        "Roughhouse displace metadata should preserve the target source zone")
    assertEqual(displace.roughhouse.newZone, "B",
        "Roughhouse displace metadata should preserve the target destination zone")
    assertEqual(displace.roughhouse.destinationZone, "B",
        "Roughhouse displace metadata should preserve selected destination")
    assertTrue(not resolver:areEngaged(actor, target), "Displace should clear old engagement")
    do
        local roughhousePopup = getActionSequencerPopup(displaceAction, displace, function(data)
            return data.title == "Roughhouse"
        end)
        assertTrue(roughhousePopup ~= nil, "Roughhouse displace should queue a visible popup")
        assertEqual(roughhousePopup.roughhouseEffect, "displace",
            "Roughhouse displace popup should preserve the effect")
        assertEqual(roughhousePopup.oldZone, "A",
            "Roughhouse displace popup should preserve the target source zone")
        assertEqual(roughhousePopup.newZone, "B",
            "Roughhouse displace popup should preserve the target destination zone")
        assertTrue(roughhousePopup.displaced,
            "Roughhouse displace popup should report the displaced outcome")
    end

    target.zone = "A"
    zoneRegistry:placeEntity(target.id, target.zone)
    target.inventory = inventory.createInventory()
    local targetSword = inventory.createItemFromTemplate("longsword")
    target.inventory:addItem(targetSword, inventory.LOCATIONS.HANDS)
    local disarmAction = {
        actor = actor,
        card = { name = "Pentacles", value = 7, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "disarm",
        target = target,
        targetInitiative = 5,
        allEntities = { actor, target },
    }
    local disarm = resolver:resolve(disarmAction)
    assertTrue(disarm.success, "Roughhouse disarm should beat Initiative")
    assertTrue(disarm.droppedItem == targetSword, "Roughhouse disarm should drop a held item")
    assertTrue(disarm.roughhouse and disarm.roughhouse.droppedItem == targetSword,
        "Roughhouse disarm metadata should preserve the dropped item")
    assertTrue(target.conditions.disarmed, "Roughhouse disarm should apply disarmed condition for Recover")
    assertTrue(target.inventory:findItem(targetSword.id) == nil,
        "Roughhouse disarm should remove the dropped item from inventory")
    do
        local roughhousePopup = getActionSequencerPopup(disarmAction, disarm, function(data)
            return data.title == "Roughhouse"
        end)
        assertTrue(roughhousePopup ~= nil, "Roughhouse disarm should queue a visible popup")
        assertEqual(roughhousePopup.roughhouseEffect, "disarm",
            "Roughhouse disarm popup should preserve the effect")
        assertTrue(roughhousePopup.droppedItem == targetSword,
            "Roughhouse disarm popup should preserve the dropped item")
        assertTrue(roughhousePopup.disarmed,
            "Roughhouse disarm popup should report the disarmed outcome")
    end

    local unarmedAttack = resolver:resolve({
        actor = actor,
        card = { name = "Five of Swords", value = 5, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        target = target,
        targetInitiative = 9,
        allEntities = { actor, target },
    })
    assertTrue(unarmedAttack.success, "attacks against targets with no melee weapon or shield should gain favor")
    assertTrue(hasValue(unarmedAttack.effects, "unarmed_target_favor"),
        "unarmed target favor should be recorded")

    target.conditions.rooted = false
    target.conditions.prone = false
    local recoverAction = {
        actor = target,
        card = { name = "Ten of Wands", value = 10, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.RECOVER,
    }
    local recover = resolver:resolve(recoverAction)
    assertTrue(recover.success, "Recover should retrieve a dropped disarmed item")
    assertEqual(recover.recoveredEffect, "disarmed", "Recover should preserve the cleared Disarmed effect")
    assertEqual(recover.recoveredItem, targetSword, "Recover should report the retrieved item")
    assertTrue(recover.recover and recover.recover.recoveredItem == targetSword,
        "Recover metadata should preserve the retrieved item")
    assertTrue(target.inventory:findItem(targetSword.id) == targetSword,
        "Recover should return the dropped item to the actor's hands")
    assertTrue(not target.conditions.disarmed, "Recover should clear the disarmed condition")
    do
        local recoverPopup = getActionSequencerPopup(recoverAction, recover, function(data)
            return data.title == "Recover"
        end)
        assertTrue(recoverPopup ~= nil, "Recovering a disarmed item should queue a visible popup")
        assertEqual(recoverPopup.recoveredEffect, "disarmed",
            "Recover item popup should preserve the cleared effect")
        assertTrue(recoverPopup.recoveredItem == targetSword,
            "Recover item popup should preserve the retrieved item")
        assertTrue(recoverPopup.recovered,
            "Recover item popup should flag success")
    end

    local choiceTarget = base_entity.createEntity({
        id = "npc_disarm_choice",
        name = "Disarm Choice Target",
        isPC = false,
        health = 2,
        defense = 0,
    })
    choiceTarget.inventory = inventory.createInventory()
    local choiceSword = inventory.createItemFromTemplate("longsword")
    local choiceShield = inventory.createItemFromTemplate("shield_light")
    choiceTarget.inventory:addItem(choiceSword, inventory.LOCATIONS.HANDS)
    choiceTarget.inventory:addItem(choiceShield, inventory.LOCATIONS.HANDS)
    local choiceDisarm = resolver:resolve({
        actor = actor,
        card = { name = "Pentacles", value = 7, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "disarm",
        target = choiceTarget,
        targetInitiative = 5,
        disarmItemId = choiceShield.id,
    })
    assertTrue(choiceDisarm.success, "Roughhouse disarm should honor an explicit held-item choice")
    assertEqual(choiceDisarm.droppedItem, choiceShield,
        "Roughhouse disarm should drop the chosen held item")
    assertTrue(choiceTarget.inventory:findItem(choiceSword.id) == choiceSword,
        "Roughhouse disarm should leave other held items in place")
    assertTrue(choiceTarget.inventory:findItem(choiceShield.id) == nil,
        "Roughhouse disarm should remove the chosen item from inventory")

    target.conditions.rooted = true
    target.conditions.prone = true
    local recoverProneAction = {
        actor = target,
        card = { name = "Eight of Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.RECOVER,
        recoverEffect = "prone",
    }
    local recoverProne = resolver:resolve(recoverProneAction)
    assertTrue(recoverProne.success, "Recover should allow the GM/player to choose a recoverable effect")
    assertEqual(recoverProne.recoverRequestedEffect, "prone",
        "chosen Recover should preserve the requested effect")
    assertEqual(recoverProne.recoveredEffect, "prone",
        "chosen Recover should preserve the cleared effect")
    assertTrue(not target.conditions.prone, "chosen Recover should clear the requested Prone effect")
    assertTrue(target.conditions.rooted, "chosen Recover should not clear a different recoverable effect")
    do
        local recoverPopup = getActionSequencerPopup(recoverProneAction, recoverProne, function(data)
            return data.title == "Recover"
        end)
        assertTrue(recoverPopup ~= nil, "Recovering a chosen effect should queue a visible popup")
        assertEqual(recoverPopup.requestedEffect, "prone",
            "Recover effect popup should preserve the requested effect")
        assertEqual(recoverPopup.recoveredEffect, "prone",
            "Recover effect popup should preserve the cleared effect")
        assertTrue(recoverPopup.recovered,
            "Recover effect popup should flag success")
    end

    target.conditions.prone = true
    target.conditions.bindingRooted = true
    local recoverBinding = resolver:resolve({
        actor = target,
        card = { name = "Eight of Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.RECOVER,
        recoverEffect = "rooted",
    })
    assertTrue(not recoverBinding.success, "Recover should not fall through when the requested effect is nonrecoverable")
    assertTrue(target.conditions.rooted and target.conditions.prone,
        "failed chosen Recover should leave other effects untouched")
    assertTrue(hasValue(recoverBinding.effects, "binding_rooted"),
        "nonrecoverable Binding-rooted Recover should report the block")
    target.conditions.bindingRooted = nil
    target.conditions.rooted = false
    target.conditions.prone = false

    local nonrecoverableBlind = base_entity.createEntity({
        id = "npc_nonrecoverable_blind",
        name = "Nonrecoverable Blind Target",
        isPC = false,
        health = 2,
        defense = 0,
    })
    nonrecoverableBlind.conditions.blind = true
    nonrecoverableBlind.nonRecoverableConditions = { blind = true }
    local blockedBlindRecoverAction = {
        actor = nonrecoverableBlind,
        card = { name = "Nine of Wands", value = 9, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.RECOVER,
        recoverEffect = "blind",
    }
    local blockedBlindRecover = resolver:resolve(blockedBlindRecoverAction)
    assertTrue(not blockedBlindRecover.success,
        "Recover should honor GM-authored nonrecoverable markers beyond Rooted")
    assertEqual(blockedBlindRecover.recoverRequestedEffect, "blind",
        "blocked Recover should preserve the requested effect")
    assertEqual(blockedBlindRecover.recoverBlockedEffect, "blind",
        "blocked Recover should preserve the blocked effect")
    assertTrue(nonrecoverableBlind.conditions.blind,
        "nonrecoverable Blind should remain after a blocked Recover")
    assertTrue(hasValue(blockedBlindRecover.effects, "recover_effect_nonrecoverable"),
        "generic nonrecoverable Recover should report the GM marker")
    do
        local recoverPopup = getActionSequencerPopup(blockedBlindRecoverAction, blockedBlindRecover, function(data)
            return data.title == "Recover"
        end)
        assertTrue(recoverPopup ~= nil, "blocked Recover should queue a visible popup")
        assertEqual(recoverPopup.requestedEffect, "blind",
            "blocked Recover popup should preserve the requested effect")
        assertEqual(recoverPopup.blockedEffect, "blind",
            "blocked Recover popup should preserve the blocked effect")
        assertTrue(recoverPopup.blocked,
            "blocked Recover popup should flag the block")
    end

    local nonrecoverableRoot = base_entity.createEntity({
        id = "npc_nonrecoverable_root",
        name = "Nonrecoverable Root Target",
        isPC = false,
        health = 2,
        defense = 0,
    })
    nonrecoverableRoot.conditions.rooted = true
    nonrecoverableRoot.nonRecoverableConditions = { rooted = "scene_hazard" }
    local blockedRootRecover = resolver:resolve({
        actor = nonrecoverableRoot,
        card = { name = "Nine of Wands", value = 9, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.RECOVER,
        recoverEffect = "rooted",
    })
    assertTrue(not blockedRootRecover.success,
        "Recover should honor GM-authored nonrecoverable Rooted markers")
    assertTrue(nonrecoverableRoot.conditions.rooted,
        "nonrecoverable Rooted should remain after a blocked Recover")
    assertTrue(hasValue(blockedRootRecover.effects, "recover_effect_nonrecoverable"),
        "generic nonrecoverable Rooted should report the GM marker")
    assertTrue(not hasValue(blockedRootRecover.effects, "binding_rooted"),
        "generic nonrecoverable Rooted should not be mislabeled as Binding")

    local mixedRecover = base_entity.createEntity({
        id = "npc_mixed_recover",
        name = "Mixed Recover Target",
        isPC = false,
        health = 2,
        defense = 0,
    })
    mixedRecover.conditions.blind = true
    mixedRecover.conditions.deaf = true
    mixedRecover.nonRecoverableConditions = { blind = true }
    local skippedBlindRecover = resolver:resolve({
        actor = mixedRecover,
        card = { name = "Ten of Wands", value = 10, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.RECOVER,
    })
    assertTrue(skippedBlindRecover.success,
        "Recover should still clear a later recoverable effect when an earlier one is nonrecoverable")
    assertTrue(mixedRecover.conditions.blind and not mixedRecover.conditions.deaf,
        "automatic Recover should skip nonrecoverable Blind and clear recoverable Deaf")

    local tangledTarget = base_entity.createEntity({
        id = "npc_chosen_disarm_recover",
        name = "Chosen Disarm Target",
        isPC = false,
        health = 2,
        defense = 0,
    })
    tangledTarget.inventory = inventory.createInventory()
    tangledTarget.conditions.rooted = true
    tangledTarget.conditions.disarmed = true
    local chosenSword = inventory.createItemFromTemplate("longsword")
    tangledTarget.droppedItems = { chosenSword }
    local recoverDisarmed = resolver:resolve({
        actor = tangledTarget,
        card = { name = "Eight of Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.RECOVER,
        recoverEffect = "disarmed",
    })
    assertTrue(recoverDisarmed.success, "chosen Recover should retrieve a dropped item even if another effect is present")
    assertEqual(recoverDisarmed.recoveredItem, chosenSword, "chosen disarm Recover should report the recovered item")
    assertTrue(not tangledTarget.conditions.disarmed, "chosen disarm Recover should clear Disarmed")
    assertTrue(tangledTarget.conditions.rooted, "chosen disarm Recover should leave Rooted in place")

    local shieldedTarget = base_entity.createEntity({
        id = "npc_shielded_disarm_rule",
        name = "Shielded Target",
        isPC = false,
        health = 2,
        defense = 0,
    })
    shieldedTarget.zone = "A"
    shieldedTarget.inventory = inventory.createInventory()
    shieldedTarget.inventory:addItem(inventory.createItemFromTemplate("shield_light"), inventory.LOCATIONS.HANDS)
    local shieldedAttack = resolver:resolve({
        actor = actor,
        card = { name = "Five of Swords", value = 5, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        target = shieldedTarget,
        targetInitiative = 9,
    })
    assertTrue(not shieldedAttack.success, "a shield should prevent the unarmed-target favor rider")
    assertTrue(not hasValue(shieldedAttack.effects, "unarmed_target_favor"),
        "shielded targets should not report unarmed-target favor")

    local bareFistActor = base_entity.createEntity({
        id = "pc_bare_fists",
        name = "Bare Fists",
        isPC = true,
    })
    bareFistActor.inventory = inventory.createInventory()
    local armedOpponent = base_entity.createEntity({
        id = "npc_armed_opponent",
        name = "Armed Opponent",
        isPC = false,
        health = 2,
        defense = 0,
    })
    armedOpponent.inventory = inventory.createInventory()
    armedOpponent.inventory:addItem(inventory.createItemFromTemplate("longsword"), inventory.LOCATIONS.HANDS)
    local bareFistDisfavor = resolver:resolve({
        actor = bareFistActor,
        card = { name = "Queen of Swords", value = 13, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        weapon = { name = "Fists", isMelee = true, unarmed = true },
        target = armedOpponent,
        targetInitiative = 13,
    })
    assertTrue(not bareFistDisfavor.success,
        "bare-fist Attacks against armed opponents should suffer disfavor")
    assertEqual(bareFistDisfavor.favorModifier, -3,
        "bare-fist armed-target disfavor should subtract the standard amount")
    assertTrue(hasValue(bareFistDisfavor.effects, "unarmed_attack_disfavor"),
        "bare-fist armed-target disfavor should be reported")

    local largeTarget = base_entity.createEntity({
        id = "npc_large_bare_fist_target",
        name = "Large Bare-Fist Target",
        isPC = false,
        health = 2,
        defense = 0,
    })
    largeTarget.sizeCategory = "large"
    local largePunch = resolver:resolve({
        actor = bareFistActor,
        card = { name = "King of Swords", value = 14, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        weapon = { name = "Bare Fists", isMelee = true, unarmed = true },
        target = largeTarget,
        targetInitiative = 5,
    })
    assertTrue(largePunch.success,
        "bare-fist Attacks can still beat a larger creature's Initiative")
    assertEqual(largePunch.damageDealt, 0,
        "unarmed adventurers should deal no Wounds to larger creatures")
    assertEqual(largeTarget.npcHealth, 2,
        "larger creatures should not lose Health from an adventurer's bare fists")
    assertTrue(hasValue(largePunch.effects, "unarmed_no_damage_larger_target"),
        "larger-target bare-fist damage prevention should be reported")
end

local function checkGiantsStrengthContestTalent()
    local bus = events.createEventBus()
    local emitted = nil
    bus:on("giants_strength_contest_won", function(data)
        emitted = data
    end)

    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
    })

    local troll = base_entity.createEntity({
        id = "pc_giants_strength",
        name = "Giant Strength Troll",
        isPC = true,
        kin = "troll",
        pentacles = 0,
        talents = {
            giants_strength = { mastered = true },
        },
    })
    local dwarf = base_entity.createEntity({
        id = "pc_strength_dwarf",
        name = "Strength Dwarf",
        isPC = true,
        kin = "dwarf",
    })
    dwarf.zone = "A"

    local rawStrength = resolver:resolve({
        actor = troll,
        target = dwarf,
        card = { name = "Two of Pentacles", value = 2, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "displace",
        destinationZone = "B",
        targetInitiative = 14,
        rawStrengthContest = true,
    })
    assertTrue(rawStrength.success, "Giant's Strength should auto-win raw-strength contests")
    assertTrue(rawStrength.giantsStrengthAutoWin, "Giant's Strength should mark the auto-win")
    assertTrue(hasValue(rawStrength.effects, "giants_strength_auto_win"),
        "Giant's Strength should report the auto-win effect")
    assertEqual(dwarf.zone, "B", "auto-winning the contest should still apply the chosen Roughhouse result")
    assertTrue(emitted and emitted.actor == troll and emitted.target == dwarf,
        "Giant's Strength should emit contest details")

    local trollTarget = base_entity.createEntity({
        id = "pc_target_troll",
        name = "Target Troll",
        isPC = true,
        kin = "troll",
    })
    trollTarget.zone = "A"
    local versusTroll = resolver:resolve({
        actor = troll,
        target = trollTarget,
        card = { name = "Two of Pentacles", value = 2, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "displace",
        destinationZone = "B",
        targetInitiative = 14,
        rawStrengthContest = true,
    })
    assertTrue(not versusTroll.success, "Giant's Strength should not auto-win against troll kin")
    assertTrue(not hasValue(versusTroll.effects, "giants_strength_auto_win"),
        "blocked troll-kin contests should not report Giant's Strength")
    assertEqual(trollTarget.zone, "A", "failed non-applicable contest should not move the target")

    local subtleContest = resolver:resolve({
        actor = troll,
        target = dwarf,
        card = { name = "Two of Pentacles", value = 2, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "trip",
        targetInitiative = 14,
        context = "subtle footwork",
    })
    assertTrue(not subtleContest.success, "Giant's Strength should require a raw-strength contest")
    assertTrue(not hasValue(subtleContest.effects, "giants_strength_auto_win"),
        "non-strength contests should not report Giant's Strength")
end

function checkHumanFayTestFateTalents()
    local bus = events.createEventBus()
    local request = nil
    bus:on(events.EVENTS.REQUEST_TEST_OF_FATE, function(data)
        request = data
    end)
    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
    })
    local activeChallenge = {
        isActive = function()
            return true
        end,
    }

    local bynameActor = base_entity.createEntity({
        id = "pc_byname",
        name = "Byname",
        isPC = true,
        talents = {
            byname = { mastered = true },
        },
    })
    bynameActor.byname = "the Blackhearted"
    local bynameTest = resolver:resolve({
        actor = bynameActor,
        card = { name = "Two of Cups", value = 2, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.TEST_FATE,
        useBynameFavor = true,
        bynameRelevant = true,
        testContext = "intimidate someone who fears the Blackhearted name",
        challengeController = activeChallenge,
    })
    assertTrue(bynameTest.pendingTestOfFate, "Byname should still use the normal Test Fate flow")
    assertTrue(hasValue(bynameTest.effects, "byname_test_fate_favor"),
        "Byname should report Test Fate favor")
    assertEqual(request.favor, true, "Byname should grant favor to relevant Tests of Fate")
    assertEqual(bynameTest.kinTalentFavor.detail, "the Blackhearted",
        "Byname favor should preserve the actor's byname")

    request = nil
    local turncloak = base_entity.createEntity({
        id = "pc_turncloak",
        name = "Turncloak",
        isPC = true,
        talents = {
            turncloak = { mastered = true },
        },
    })
    local turncloakTest = resolver:resolve({
        actor = turncloak,
        card = { name = "Three of Cups", value = 3, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.TEST_FATE,
        useTurncloakFavor = true,
        againstHouse = true,
        testContext = "play up a legacy of deceit against house interests",
        challengeController = activeChallenge,
    })
    assertTrue(turncloakTest.pendingTestOfFate, "Turncloak should still use the normal Test Fate flow")
    assertTrue(hasValue(turncloakTest.effects, "turncloak_test_fate_favor"),
        "Turncloak should report Test Fate favor")
    assertEqual(request.favor, true,
        "Turncloak should grant favor when working against house or humankind")

    request = nil
    local blockedTurncloak = resolver:resolve({
        actor = turncloak,
        card = { name = "Four of Cups", value = 4, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.TEST_FATE,
        useTurncloakFavor = true,
        testContext = "help the family repair their honor",
        challengeController = activeChallenge,
    })
    assertTrue(blockedTurncloak.pendingTestOfFate,
        "mismatched Turncloak context should still allow the underlying Test Fate")
    assertTrue(hasValue(blockedTurncloak.effects, "turncloak_test_fate_favor_unavailable"),
        "mismatched Turncloak context should report unavailable favor")
    assertEqual(request.favor, nil, "mismatched Turncloak context should not grant favor")

    request = nil
    local proud = base_entity.createEntity({
        id = "pc_proud_test_fate",
        name = "Proud Test Fate",
        isPC = true,
        talents = {
            proud_and_ancient = { mastered = true },
        },
    })
    proud.house = "Crowell"
    proud.houseMotto = "Crowell keeps the gate"
    proud.houseSigil = "a brass bell over a barred door"
    local proudTest = resolver:resolve({
        actor = proud,
        card = { name = "Five of Cups", value = 5, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.TEST_FATE,
        useProudAndAncientFavor = true,
        houseMottoRelevant = true,
        testContext = "holding the gate while allies escape",
        challengeController = activeChallenge,
    })
    assertTrue(proudTest.pendingTestOfFate, "Proud and Ancient should use the normal Test Fate flow")
    assertTrue(hasValue(proudTest.effects, "proud_and_ancient_test_fate_favor"),
        "Proud and Ancient should report sigil/motto Test Fate favor")
    assertEqual(request.favor, true,
        "dramatically appropriate house motto should grant Test Fate favor")
    assertEqual(proudTest.proudAndAncientTestFate.motto, "Crowell keeps the gate",
        "Proud and Ancient should preserve the relevant house motto")
    assertEqual(request.proudAndAncientTestFate.symbol, "motto",
        "Proud and Ancient Test Fate request should identify the relevant house symbol")

    request = nil
    local missingSigilTest = resolver:resolve({
        actor = proud,
        card = { name = "Six of Cups", value = 6, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.TEST_FATE,
        houseSigilRelevant = true,
        houseSigil = "",
        testContext = "brandishing an unrecorded house sigil",
        challengeController = activeChallenge,
    })
    assertTrue(missingSigilTest.pendingTestOfFate,
        "missing Proud and Ancient sigil should not block the underlying Test Fate")
    assertTrue(hasValue(missingSigilTest.effects, "proud_and_ancient_test_fate_favor_unavailable"),
        "missing Proud and Ancient sigil should report unavailable favor")
    assertEqual(request.favor, nil, "missing Proud and Ancient sigil should not grant favor")
    assertEqual(request.proudAndAncientTestFateUnavailable, "missing_house_sigil",
        "missing Proud and Ancient sigil should preserve the unavailable reason")

    request = nil
    local woundedProud = base_entity.createEntity({
        id = "pc_wounded_proud_test_fate",
        name = "Wounded Proud Test Fate",
        isPC = true,
        talents = {
            proud_and_ancient = { mastered = true, wounded = true },
        },
    })
    woundedProud.houseMotto = "Crowell keeps the gate"
    local woundedProudTest = resolver:resolve({
        actor = woundedProud,
        card = { name = "Seven of Cups", value = 7, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.TEST_FATE,
        houseMottoRelevant = true,
        challengeController = activeChallenge,
    })
    assertTrue(woundedProudTest.pendingTestOfFate,
        "wounded Proud and Ancient should still allow the underlying Test Fate")
    assertTrue(hasValue(woundedProudTest.effects, "proud_and_ancient_test_fate_favor_unavailable"),
        "wounded Proud and Ancient should report unavailable favor")
    assertEqual(request.favor, nil, "wounded Proud and Ancient should not grant Test Fate favor")
end

function checkOrcBloodlineWoundedTalents()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local storm = base_entity.createEntity({
        id = "pc_blur_blood",
        name = "Blur Blood",
        isPC = true,
        armorSlots = 0,
        talents = {
            blur = { mastered = true },
        },
    })
    local blurWound = storm:takeWound("normal", {
        choice = "talent",
        talentId = "blur",
    })
    assertEqual(blurWound, "talent_wounded", "Blur should trigger when its talent is Wounded")
    assertTrue(storm.conditions.shrouded and storm.conditions.invisible,
        "Wounded Blur should make the orc Shrouded")
    assertEqual(storm.shroud.source, "blur", "Blur should record its Shrouded source")

    local blurTarget = base_entity.createEntity({
        id = "pc_blur_blood_resolver",
        name = "Resolver Blur",
        isPC = true,
        armorSlots = 0,
        talents = {
            blur = { mastered = true },
        },
    })
    local blurAttacker = base_entity.createEntity({
        id = "npc_blur_attacker",
        name = "Blur Attacker",
        isPC = false,
        swords = 5,
        health = 2,
        defense = 0,
    })
    local blurAction = {
        actor = blurAttacker,
        target = blurTarget,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 1,
        targetWoundChoice = "talent",
        targetWoundTalentId = "blur",
    }
    local blurHit = resolver:resolve(blurAction)
    assertTrue(blurHit.success, "setup Wounding Blur hit should succeed")
    assertTrue(hasValue(blurHit.effects, "blur_shrouded"),
        "Wounding Blur resolver hit should report the shroud")
    local blurPopup = getActionSequencerPopup(blurAction, blurHit, function(data)
        return data.title == "Wounding Blur"
    end)
    assertTrue(blurPopup ~= nil, "Wounding Blur should queue an action-sequencer popup")
    assertEqual(blurPopup.actor, blurTarget, "Wounding Blur popup should preserve the shrouded orc")

    local fireblood = base_entity.createEntity({
        id = "pc_berserkergang",
        name = "Berserkergang",
        isPC = true,
        swords = 0,
        armorSlots = 0,
        talents = {
            berserkergang = { mastered = true },
        },
    })
    fireblood.resolve = 1
    local rageWound = fireblood:takeWound("normal", {
        choice = "talent",
        talentId = "berserkergang",
        enterBerserkergang = true,
    })
    assertEqual(rageWound, "talent_wounded", "Berserkergang should start from the Wounded talent")
    assertTrue(fireblood.conditions.berserkergang and fireblood.conditions.berserk,
        "Berserkergang should mark the berserk state")

    local rageTarget = base_entity.createEntity({
        id = "npc_berserk_target",
        name = "Berserk Target",
        isPC = false,
        health = 2,
        defense = 0,
    })
    local rageAttack = resolver:resolve({
        actor = fireblood,
        target = rageTarget,
        card = { name = "Five of Swords", value = 5, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 8,
    })
    assertTrue(rageAttack.success, "Berserkergang should grant favor to Attacks")
    assertEqual(rageAttack.favorModifier, 3, "Berserkergang favor should use the standard +3")
    assertTrue(hasValue(rageAttack.effects, "berserkergang_attack_favor"),
        "Berserkergang Attack favor should be reported")
    local ragePopup = getActionSequencerPopup({
        actor = fireblood,
        target = rageTarget,
        card = { name = "Five of Swords", value = 5, suit = constants.SUITS.SWORDS },
    }, rageAttack, function(data)
        return data.title == "Berserkergang" and data.attackFavor == true
    end)
    assertTrue(ragePopup ~= nil, "Berserkergang Attack favor should queue an action-sequencer popup")
    assertEqual(ragePopup.actor, fireblood, "Berserkergang Attack popup should preserve the raging actor")

    local blockedDodge = resolver:resolve({
        actor = fireblood,
        target = rageTarget,
        card = { name = "Five of Pentacles", value = 5, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.DODGE,
    })
    assertTrue(not blockedDodge.success, "Berserkergang should block Dodge")
    assertEqual(blockedDodge.description, "Cannot use that action while berserk",
        "Berserkergang blocked actions should explain the rage limit")

    local ended = resolver:endBerserkergang(fireblood, { spendResolve = true })
    assertTrue(ended.success, "Berserkergang should be endable early by spending Resolve")
    assertEqual(fireblood.resolve, 0, "ending Berserkergang early should spend one Resolve")
    assertTrue(not fireblood.conditions.berserkergang,
        "ending Berserkergang should clear the berserk state")

    local finishingFireblood = base_entity.createEntity({
        id = "pc_berserkergang_finish",
        name = "Berserkergang Finish",
        isPC = true,
        swords = 3,
        armorSlots = 0,
        talents = {
            berserkergang = { mastered = true },
        },
    })
    finishingFireblood:takeWound("normal", {
        choice = "talent",
        talentId = "berserkergang",
        enterBerserkergang = true,
    })
    local lastEnemy = base_entity.createEntity({
        id = "npc_last_berserk_enemy",
        name = "Last Berserk Enemy",
        isPC = false,
        health = 1,
        defense = 0,
    })
    local finishingAttack = resolver:resolve({
        actor = finishingFireblood,
        target = lastEnemy,
        card = { name = "Five of Swords", value = 5, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 3,
        allEntities = { finishingFireblood, lastEnemy },
    })
    assertTrue(finishingAttack.success, "Berserkergang finishing attack setup should hit")
    assertTrue(not finishingFireblood.conditions.berserkergang,
        "Berserkergang should end when every enemy is defeated")
    assertTrue(hasValue(finishingAttack.effects, "berserkergang_ended"),
        "defeating the last enemy should report Berserkergang ending")
    local endingPopup = getActionSequencerPopup({
        actor = finishingFireblood,
        target = lastEnemy,
        card = { name = "Five of Swords", value = 5, suit = constants.SUITS.SWORDS },
    }, finishingAttack, function(data)
        return data.title == "Berserkergang" and data.ended == true
    end)
    assertTrue(endingPopup ~= nil, "ending Berserkergang should queue an action-sequencer popup")

    local earth = base_entity.createEntity({
        id = "pc_quicksilver_blood",
        name = "Quicksilver Blood",
        isPC = true,
        armorSlots = 0,
        talents = {
            quicksilver_blood = { mastered = true },
        },
    })
    local metalAttacker = base_entity.createEntity({
        id = "npc_metal_attacker",
        name = "Metal Attacker",
        isPC = false,
        swords = 5,
        health = 2,
        defense = 0,
    })
    local ironSword = inventory.createItem({
        name = "Iron Sword",
        weaponType = "sword",
        material = "iron",
        isWeapon = true,
        isMelee = true,
        durability = 2,
    })
    local quicksilverAction = {
        actor = metalAttacker,
        target = earth,
        weapon = ironSword,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 1,
        targetWoundChoice = "talent",
        targetWoundTalentId = "quicksilver_blood",
    }
    local quicksilverHit = resolver:resolve(quicksilverAction)
    assertTrue(quicksilverHit.success, "setup Quicksilver Blood hit should succeed")
    assertTrue(ironSword.destroyed, "Wounded Quicksilver Blood should destroy a metal weapon")
    assertTrue(hasValue(quicksilverHit.effects, "quicksilver_blood_weapon_destroyed"),
        "Quicksilver Blood weapon destruction should be reported")
    local quicksilverPopup = getActionSequencerPopup(quicksilverAction, quicksilverHit, function(data)
        return data.title == "Quicksilver Blood"
    end)
    assertTrue(quicksilverPopup ~= nil, "Quicksilver Blood should queue an action-sequencer popup")
    assertEqual(quicksilverPopup.weapon, ironSword,
        "Quicksilver Blood popup should preserve the destroyed weapon")

    local sea = base_entity.createEntity({
        id = "pc_poison_blood",
        name = "Poison Blood",
        isPC = true,
        armorSlots = 0,
        talents = {
            poison_blood = { mastered = true },
        },
    })
    local biter = base_entity.createEntity({
        id = "npc_bite_attacker",
        name = "Bite Attacker",
        isPC = false,
        swords = 5,
        health = 2,
        defense = 2,
    })
    local bite = inventory.createItem({
        name = "Bite",
        weaponType = "bite",
        isWeapon = true,
        isMelee = true,
    })
    local poisonAction = {
        actor = biter,
        target = sea,
        weapon = bite,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 1,
        targetWoundChoice = "talent",
        targetWoundTalentId = "poison_blood",
    }
    local poisonHit = resolver:resolve(poisonAction)
    assertTrue(poisonHit.success, "setup Poison Blood bite should succeed")
    assertEqual(biter.npcDefense, 2, "Poison Blood Critical damage should bypass Defense")
    assertEqual(biter.npcHealth, 1, "Poison Blood should critically Wound the biter")
    assertTrue(hasValue(poisonHit.effects, "poison_blood_critical"),
        "Poison Blood critical damage should be reported")
    local poisonPopup = getActionSequencerPopup(poisonAction, poisonHit, function(data)
        return data.title == "Poison Blood"
    end)
    assertTrue(poisonPopup ~= nil, "Poison Blood should queue an action-sequencer popup")
    assertEqual(poisonPopup.attacker, biter, "Poison Blood popup should preserve the poisoned biter")
end

local function checkFightDirtyRoughhouseTalent()
    local function hasAction(actions, id)
        for _, action in ipairs(actions or {}) do
            if action.id == id then
                return true
            end
        end
        return false
    end

    local swordCard = { name = "Seven of Swords", value = 7, suit = constants.SUITS.SWORDS }
    local dirtyFighter = base_entity.createEntity({
        id = "pc_fight_dirty",
        name = "Fight Dirty",
        isPC = true,
        pentacles = 3,
        talents = {
            fight_dirty = { mastered = true },
        },
    })
    local plainFighter = base_entity.createEntity({
        id = "pc_no_fight_dirty",
        name = "No Fight Dirty",
        isPC = true,
        pentacles = 3,
    })

    assertTrue(hasAction(action_registry.getAvailableActions(swordCard, false, dirtyFighter), "roughhouse"),
        "Fight Dirty should allow Roughhouse as a Swords-card minor action")
    assertTrue(not hasAction(action_registry.getAvailableActions(swordCard, false, plainFighter), "roughhouse"),
        "Roughhouse with a Swords-card minor should require Fight Dirty")

    local controller = challenge_controller.createChallengeController({
        eventBus = events.createEventBus(),
    })
    controller.state = challenge_controller.STATES.MINOR_WINDOW
    controller.activeEntity = base_entity.createEntity({ id = "active_fighter", isPC = true })
    local ok, err = controller:declareMinorAction(dirtyFighter, swordCard, {
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "trip",
    })
    assertTrue(ok, "Fight Dirty should pass the minor declaration suit gate")

    local blockedController = challenge_controller.createChallengeController({
        eventBus = events.createEventBus(),
    })
    blockedController.state = challenge_controller.STATES.MINOR_WINDOW
    blockedController.activeEntity = controller.activeEntity
    ok, err = blockedController:declareMinorAction(plainFighter, swordCard, {
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "trip",
    })
    assertTrue(not ok, "Swords-card Roughhouse minors should be rejected without Fight Dirty")
    assertEqual(err, "suit_mismatch", "missing Fight Dirty should preserve the suit-mismatch reason")

    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local target = base_entity.createEntity({
        id = "npc_fight_dirty_target",
        name = "Fight Dirty Target",
        isPC = false,
        health = 2,
        defense = 0,
    })
    target.inventory = inventory.createInventory()
    local dagger = inventory.createItemFromTemplate("dagger")
    target.inventory:addItem(dagger, inventory.LOCATIONS.HANDS)

    local exhaust = resolver:resolve({
        actor = dirtyFighter,
        target = target,
        card = { name = "Eight of Pentacles", value = 8, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "exhaust",
        targetInitiative = 5,
    })
    assertTrue(exhaust.success, "Fight Dirty Exhaust should resolve as Roughhouse")
    assertTrue(target.conditions.exhausted, "Fight Dirty Exhaust should mark the target Exhausted")
    assertTrue(hasValue(exhaust.effects, "exhausted"), "Fight Dirty Exhaust should report the condition")

    local silence = resolver:resolve({
        actor = dirtyFighter,
        target = target,
        card = { name = "Eight of Pentacles", value = 8, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "silence",
        targetInitiative = 5,
    })
    assertTrue(silence.success, "Fight Dirty Silence should resolve as Roughhouse")
    assertTrue(target.conditions.silenced, "Fight Dirty Silence should mark the target Silenced")
    assertTrue(hasValue(silence.effects, "silenced"), "Fight Dirty Silence should report the condition")

    local notch = resolver:resolve({
        actor = dirtyFighter,
        target = target,
        card = { name = "Eight of Pentacles", value = 8, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "notch",
        targetInitiative = 5,
        targetItemId = dagger.id,
    })
    assertTrue(notch.success, "Fight Dirty Notch should resolve as Roughhouse")
    assertEqual(dagger.notches, 1, "Fight Dirty Notch should damage the selected item")
    assertEqual(notch.notchedItem, dagger, "Fight Dirty Notch should report the damaged item")

    local blockedEffect = resolver:resolve({
        actor = plainFighter,
        target = target,
        card = { name = "Eight of Pentacles", value = 8, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "exhaust",
        targetInitiative = 5,
    })
    assertTrue(not blockedEffect.success, "Fight Dirty-only Roughhouse effects should reject ordinary actors")
    assertTrue(hasValue(blockedEffect.effects, "fight_dirty_required"),
        "blocked Fight Dirty effects should explain the missing talent")
end

local function checkAmbusherFirstRoundDamageTalent()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local function controllerForRound(round)
        return {
            currentRound = round,
            isActive = function()
                return true
            end,
        }
    end
    local function makeAmbusher(id, talents)
        local actor = base_entity.createEntity({
            id = id,
            name = id,
            isPC = true,
            swords = 2,
            talents = talents,
        })
        actor.inventory = inventory.createInventory()
        return actor
    end
    local function makeTarget(id)
        return base_entity.createEntity({
            id = id,
            name = id,
            isPC = false,
            health = 3,
            defense = 0,
        })
    end

    local ambusher = makeAmbusher("pc_ambusher", {
        ambusher = { mastered = true },
    })
    local sword = inventory.createItemFromTemplate("longsword")
    ambusher.inventory:addItem(sword, inventory.LOCATIONS.HANDS)
    local target = makeTarget("npc_ambusher_target")
    local firstRound = resolver:resolve({
        actor = ambusher,
        target = target,
        weapon = sword,
        card = { name = "Five of Swords", value = 5, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 5,
        challengeController = controllerForRound(1),
    })
    assertTrue(firstRound.success, "Ambusher setup Attack should hit")
    assertEqual(firstRound.damageDealt, 2, "Ambusher should deal two Wounds in the first round")
    assertEqual(target.npcHealth, 1, "Ambusher first-round melee should apply two Wounds")
    assertTrue(hasValue(firstRound.effects, "ambusher_first_round_damage"),
        "Ambusher first-round damage should be reported")
    local actionSequencer = require('ui.action_sequencer')
    local sequencer = actionSequencer.createActionSequencer({ eventBus = events.createEventBus() })
    sequencer:queueActionSequence({
        action = {
            actor = ambusher,
            target = target,
            card = { name = "Five of Swords", value = 5, suit = constants.SUITS.SWORDS },
        },
        result = firstRound,
    })
    local hasAmbusherPopup = false
    for _, step in ipairs(sequencer.currentSequence or {}) do
        if step.type == actionSequencer.STEP_TYPES.TEXT_POPUP and
           step.data and step.data.title == "Ambusher" then
            hasAmbusherPopup = true
            assertEqual(step.data.previousDamage, 1,
                "Ambusher popup should include the original damage")
            assertEqual(step.data.damageDealt, 2,
                "Ambusher popup should include the boosted damage")
            break
        end
    end
    assertTrue(hasAmbusherPopup, "Ambusher first-round damage should queue a visible popup")

    local laterTarget = makeTarget("npc_ambusher_later_target")
    local laterRound = resolver:resolve({
        actor = ambusher,
        target = laterTarget,
        weapon = sword,
        card = { name = "Five of Swords", value = 5, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 5,
        challengeController = controllerForRound(2),
    })
    assertTrue(laterRound.success, "Ambusher later-round setup Attack should hit")
    assertEqual(laterRound.damageDealt, 1, "Ambusher should not add damage after the first round")
    assertEqual(laterTarget.npcHealth, 2, "later-round Ambusher attacks should apply one Wound")

    local woundedAmbusher = makeAmbusher("pc_wounded_ambusher", {
        ambusher = { mastered = true, wounded = true },
    })
    local woundedSword = inventory.createItemFromTemplate("longsword")
    woundedAmbusher.inventory:addItem(woundedSword, inventory.LOCATIONS.HANDS)
    local woundedTarget = makeTarget("npc_wounded_ambusher_target")
    local woundedAttack = resolver:resolve({
        actor = woundedAmbusher,
        target = woundedTarget,
        weapon = woundedSword,
        card = { name = "Five of Swords", value = 5, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 5,
        challengeController = controllerForRound(1),
    })
    assertTrue(woundedAttack.success, "wounded Ambusher setup Attack should still hit")
    assertEqual(woundedAttack.damageDealt, 1, "wounded Ambusher should not add first-round damage")

    local archer = makeAmbusher("pc_ambusher_archer", {
        ambusher = { mastered = true },
    })
    local bow = inventory.createItemFromTemplate("bow")
    archer.inventory:addItem(bow, inventory.LOCATIONS.HANDS)
    archer.ammo = 1
    local missileTarget = makeTarget("npc_ambusher_missile_target")
    local missile = resolver:resolve({
        actor = archer,
        target = missileTarget,
        weapon = bow,
        card = { name = "Five of Swords", value = 5, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MISSILE,
        targetInitiative = 5,
        challengeController = controllerForRound(1),
    })
    assertTrue(missile.success, "Ambusher missile setup Attack should hit")
    assertEqual(missile.damageDealt, 2, "Ambusher should also double first-round missile Attack damage")
    assertEqual(missileTarget.npcHealth, 1, "Ambusher first-round missile should apply two Wounds")
end

local function checkAegisTalentDamageSubstitution()
    local bus = events.createEventBus()
    local absorbed = nil
    bus:on(events.EVENTS.ITEM_DAMAGE_ABSORBED, function(data)
        absorbed = data
    end)
    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
    })

    local attacker = base_entity.createEntity({
        id = "npc_aegis_attacker",
        name = "Aegis Attacker",
        isPC = false,
        swords = 4,
        health = 2,
        defense = 0,
    })
    local aegisBearer = base_entity.createEntity({
        id = "pc_aegis_bearer",
        name = "Aegis Bearer",
        isPC = true,
        armorSlots = 0,
        talentWoundSlots = 1,
        talents = {
            aegis = { mastered = true },
        },
    })
    aegisBearer.inventory = inventory.createInventory()
    local heavyShield = inventory.createItemFromTemplate("shield_heavy")
    aegisBearer.inventory:addItem(heavyShield, inventory.LOCATIONS.PACK)

    local attack = resolver:resolve({
        actor = attacker,
        target = aegisBearer,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 3,
        useAegis = true,
    })
    assertTrue(attack.success, "setup Aegis attack should hit")
    assertEqual(heavyShield.notches, 1, "Aegis should Notch a carried intact shield")
    assertTrue(not aegisBearer.talents.aegis.wounded, "Aegis should prevent the physical attack effect")
    assertTrue(hasValue(attack.effects, "aegis_effect_prevented"), "Aegis should report prevented effect")
    assertTrue(absorbed and absorbed.item == heavyShield and absorbed.talent == "aegis",
        "Aegis should emit item damage absorption details")
    assertTrue(attack.aegisResult and attack.aegisResult.shield == heavyShield,
        "Aegis attack results should retain shield Notch details for presentation")
    local actionSequencer = require('ui.action_sequencer')
    local sequencer = actionSequencer.createActionSequencer({ eventBus = events.createEventBus() })
    sequencer:queueActionSequence({
        action = {
            actor = attacker,
            target = aegisBearer,
            card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        },
        result = attack,
    })
    local hasAegisPopup = false
    local visualDamageDealt = nil
    for _, step in ipairs(sequencer.currentSequence or {}) do
        if step.type == actionSequencer.STEP_TYPES.TEXT_POPUP and
           step.data and step.data.title == "Aegis" then
            hasAegisPopup = true
            assertEqual(step.data.shield, heavyShield,
                "Aegis popup should include the shield that was Notched")
            assertEqual(step.data.notchResult, "notched",
                "Aegis popup should include the shield Notch result")
        elseif step.type == actionSequencer.STEP_TYPES.DAMAGE_RESULT then
            visualDamageDealt = step.data and step.data.damageDealt
        end
    end
    assertTrue(hasAegisPopup, "Aegis shield protection should queue a visible popup")
    assertEqual(visualDamageDealt, 0,
        "Aegis-prevented attack visuals should not show a Wound count")

    local promptBus = events.createEventBus()
    local promptResolver = action_resolver.createActionResolver({ eventBus = promptBus })
    local promptAttacker = base_entity.createEntity({
        id = "npc_aegis_prompt_attacker",
        name = "Aegis Prompt Attacker",
        isPC = false,
        swords = 4,
        health = 2,
        defense = 0,
    })
    local promptBearer = base_entity.createEntity({
        id = "pc_aegis_prompt_bearer",
        name = "Aegis Prompt Bearer",
        isPC = true,
        armorSlots = 0,
        talentWoundSlots = 1,
        talents = {
            aegis = { mastered = true },
        },
    })
    promptBearer.inventory = inventory.createInventory()
    local promptShield = inventory.createItemFromTemplate("shield_light")
    promptBearer.inventory:addItem(promptShield, inventory.LOCATIONS.HANDS)
    local promptController = challenge_controller.createChallengeController({
        eventBus = promptBus,
    })
    promptController.state = challenge_controller.STATES.AWAITING_ACTION
    promptController.currentRound = 1
    promptController.currentCount = 4
    promptController.activeEntity = promptAttacker
    promptController.pcs = { promptBearer }
    promptController.npcs = { promptAttacker }
    promptController.allCombatants = { promptBearer, promptAttacker }

    local promptInput = challenge_input_controller.createChallengeInputController({
        eventBus = promptBus,
        gameState = {
            challengeController = promptController,
            playerHand = {
                getHand = function()
                    return {}
                end,
            },
            guild = { promptBearer },
        },
    })
    promptInput:init()

    local promptOverlay = require('ui.challenge_overlay').createChallengeOverlay({
        gameState = {
            challengeController = promptController,
            playerHand = {
                getHand = function()
                    return {}
                end,
            },
        },
        inputState = promptInput:getState(),
    })

    local promptedAction = nil
    promptBus:on(events.EVENTS.CHALLENGE_ACTION, function(action)
        promptedAction = action
        action.result = promptResolver:resolve(action)
        promptController:resolveAction(action)
    end)

    local promptAttack = {
        target = promptBearer,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 3,
    }
    local promptOk, promptReason = promptController:submitAction(promptAttack)
    assertTrue(promptOk, "incoming Aegis prompt action should pause successfully")
    assertTrue(promptInput:getState().pendingAegisElection ~= nil,
        "input controller should store the pending Aegis prompt")
    assertTrue(promptedAction == nil,
        "Aegis prompt should wait for player election before resolving the incoming action")
    local aegisPrompt = promptOverlay:getFooterPrompt(promptController:getState(), promptController:getActiveEntity())
    assertTrue(aegisPrompt and aegisPrompt:find("Aegis"),
        "Challenge overlay should surface the Aegis prompt")

    promptInput:handleChallengeInput("a")
    assertTrue(promptedAction and promptedAction.useAegis,
        "A should elect Aegis on the incoming action")
    assertTrue(promptedAction.result and promptedAction.result.success,
        "prompted Aegis attack should still count as a landed attack")
    assertEqual(promptShield.notches, 1,
        "prompted Aegis should Notch the carried shield when the effect lands")
    assertTrue(not promptBearer.talents.aegis.wounded,
        "prompted Aegis should prevent the physical attack effect")
    assertTrue(promptInput:getState().pendingAegisElection == nil,
        "Aegis prompt should clear after election")

    local multiBus = events.createEventBus()
    local multiController = challenge_controller.createChallengeController({
        eventBus = multiBus,
    })
    local function makePromptAegisTarget(id, name)
        local entity = base_entity.createEntity({
            id = id,
            name = name,
            isPC = true,
            armorSlots = 0,
            talentWoundSlots = 1,
            talents = {
                aegis = { mastered = true },
            },
        })
        entity.inventory = inventory.createInventory()
        local shield = inventory.createItemFromTemplate("shield_light")
        entity.inventory:addItem(shield, inventory.LOCATIONS.HANDS)
        return entity, shield
    end
    local multiFirst, multiFirstShield = makePromptAegisTarget(
        "pc_aegis_multi_first", "Aegis Multi First")
    local multiSecond, multiSecondShield = makePromptAegisTarget(
        "pc_aegis_multi_second", "Aegis Multi Second")
    local multiSkipped, multiSkippedShield = makePromptAegisTarget(
        "pc_aegis_multi_skipped", "Aegis Multi Skipped")
    local multiAttacker = base_entity.createEntity({
        id = "npc_aegis_multi_attacker",
        name = "Aegis Multi Attacker",
        isPC = false,
        swords = 4,
        health = 2,
        defense = 0,
    })
    multiController.state = challenge_controller.STATES.RESOLVING
    multiController.currentRound = 1
    multiController.currentCount = 4
    multiController.pcs = { multiFirst, multiSecond, multiSkipped }
    multiController.npcs = { multiAttacker }
    multiController.allCombatants = { multiFirst, multiSecond, multiSkipped, multiAttacker }

    local multiInput = challenge_input_controller.createChallengeInputController({
        eventBus = multiBus,
        gameState = {
            challengeController = multiController,
            playerHand = {
                getHand = function()
                    return {}
                end,
            },
            guild = { multiFirst, multiSecond, multiSkipped },
        },
    })
    multiInput:init()
    local multiEmitted = 0
    multiBus:on(events.EVENTS.CHALLENGE_ACTION, function()
        multiEmitted = multiEmitted + 1
    end)
    local multiAction = {
        actor = multiAttacker,
        targets = { multiFirst, multiSecond, multiSkipped },
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 3,
        aegisPhysical = true,
    }
    assertTrue(multiController:beginAegisElectionWindow(multiAction),
        "multi-target physical action should pause for Aegis elections")
    assertEqual(#multiInput:getState().pendingAegisElection.candidates, 3,
        "multi-target Aegis prompt should expose every eligible shield bearer")
    multiInput:handleChallengeInput("a")
    assertEqual(multiEmitted, 0,
        "multi-target Aegis should keep the incoming action paused after one election")
    assertTrue(multiAction.aegisActors and multiAction.aegisActors[multiFirst.id],
        "first multi-target Aegis election should be target-scoped")
    assertEqual(#multiInput:getState().pendingAegisElection.candidates, 2,
        "multi-target Aegis prompt should continue with remaining targets")
    multiInput:handleChallengeInput("a")
    assertEqual(multiEmitted, 0,
        "multi-target Aegis should allow a second election before action emission")
    assertTrue(multiAction.aegisActors and multiAction.aegisActors[multiSecond.id],
        "second multi-target Aegis election should be target-scoped")
    assertEqual(#multiInput:getState().pendingAegisElection.candidates, 1,
        "multi-target Aegis prompt should retain skipped eligible targets")
    multiInput:handleChallengeInput("space")
    assertEqual(multiEmitted, 1,
        "multi-target Aegis should emit the incoming action after remaining elections are skipped")
    assertTrue(multiInput:getState().pendingAegisElection == nil,
        "multi-target Aegis prompt should clear after final resolution")

    local multiResult = { effects = {}, success = true }
    resolver:applyDamage(multiFirst, 1, multiResult.effects, nil, nil, nil, {
        source = "attack",
        physical = true,
        action = multiAction,
        result = multiResult,
        useAegis = multiAction.useAegis,
    })
    resolver:applyDamage(multiSecond, 1, multiResult.effects, nil, nil, nil, {
        source = "attack",
        physical = true,
        action = multiAction,
        result = multiResult,
        useAegis = multiAction.useAegis,
    })
    resolver:applyDamage(multiSkipped, 1, multiResult.effects, nil, nil, nil, {
        source = "attack",
        physical = true,
        action = multiAction,
        result = multiResult,
        useAegis = multiAction.useAegis,
    })
    assertEqual(multiFirstShield.notches, 1,
        "first elected multi-target Aegis shield should be Notched")
    assertEqual(multiSecondShield.notches, 1,
        "second elected multi-target Aegis shield should be Notched")
    assertEqual(multiSkippedShield.notches, 0,
        "skipped multi-target Aegis shield should not be Notched by another target's election")
    assertTrue(not multiFirst.talents.aegis.wounded and not multiSecond.talents.aegis.wounded,
        "elected multi-target Aegis bearers should prevent their Wounds")
    assertTrue(multiSkipped.talents.aegis.wounded,
        "skipped multi-target Aegis bearer should take the normal Wound")
    assertEqual(#(multiResult.aegisResults or {}), 2,
        "multi-target Aegis should retain presentation details for each elected shield")
    local multiSequencer = actionSequencer.createActionSequencer({ eventBus = events.createEventBus() })
    multiSequencer:queueActionSequence({
        action = multiAction,
        result = multiResult,
    })
    local multiAegisPopups = 0
    for _, step in ipairs(multiSequencer.currentSequence or {}) do
        if step.type == actionSequencer.STEP_TYPES.TEXT_POPUP and
           step.data and step.data.title == "Aegis" then
            multiAegisPopups = multiAegisPopups + 1
        end
    end
    assertEqual(multiAegisPopups, 2,
        "multi-target Aegis should queue one popup for each elected shield")

    local noElection = base_entity.createEntity({
        id = "pc_aegis_no_election",
        name = "Aegis No Election",
        isPC = true,
        armorSlots = 0,
        talentWoundSlots = 1,
        talents = {
            aegis = { mastered = true },
        },
    })
    noElection.inventory = inventory.createInventory()
    local lightShield = inventory.createItemFromTemplate("shield_light")
    noElection.inventory:addItem(lightShield, inventory.LOCATIONS.HANDS)
    local ordinaryHit = resolver:resolve({
        actor = attacker,
        target = noElection,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 3,
    })
    assertTrue(ordinaryHit.success, "setup non-Aegis attack should hit")
    assertEqual(lightShield.notches, 0, "Aegis should require an explicit election")
    assertTrue(noElection.talents.aegis.wounded, "without election, the normal wound track should apply")

    local spentShieldBearer = base_entity.createEntity({
        id = "pc_aegis_spent_shield",
        name = "Aegis Spent Shield",
        isPC = true,
        armorSlots = 0,
        talentWoundSlots = 1,
        talents = {
            aegis = { mastered = true },
        },
    })
    spentShieldBearer.inventory = inventory.createInventory()
    local spentShield = inventory.createItemFromTemplate("shield_light")
    spentShield.destroyed = true
    spentShieldBearer.inventory:addItem(spentShield, inventory.LOCATIONS.HANDS)
    local spentShieldHit = resolver:resolve({
        actor = attacker,
        target = spentShieldBearer,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 3,
        useAegis = true,
    })
    assertTrue(spentShieldHit.success, "setup spent-shield attack should hit")
    assertTrue(spentShieldBearer.talents.aegis.wounded, "Aegis should require an intact shield")
    assertTrue(not hasValue(spentShieldHit.effects, "aegis_effect_prevented"),
        "spent shields should not report Aegis prevention")

    local magicTarget = base_entity.createEntity({
        id = "pc_aegis_magic",
        name = "Aegis Magic",
        isPC = true,
        armorSlots = 0,
        talentWoundSlots = 1,
        talents = {
            aegis = { mastered = true },
        },
    })
    magicTarget.inventory = inventory.createInventory()
    local magicShield = inventory.createItemFromTemplate("shield_heavy")
    magicTarget.inventory:addItem(magicShield, inventory.LOCATIONS.HANDS)
    resolver:applyDamage(magicTarget, 1, { "magic" }, nil, nil, { useAegis = true }, {
        source = "spell",
    })
    assertEqual(magicShield.notches, 0, "Aegis should not block non-physical damage sources")
    assertTrue(magicTarget.talents.aegis.wounded, "non-physical damage should use the normal wound track")

    local trapTarget = base_entity.createEntity({
        id = "pc_aegis_trap",
        name = "Aegis Trap",
        isPC = true,
        armorSlots = 0,
        talentWoundSlots = 1,
        talents = {
            aegis = { mastered = true },
        },
    })
    trapTarget.inventory = inventory.createInventory()
    local trapShield = inventory.createItemFromTemplate("shield_heavy")
    trapTarget.inventory:addItem(trapShield, inventory.LOCATIONS.HANDS)
    resolver:applyDamage(trapTarget, 1, { "trap" }, nil, nil, { useAegis = true }, {
        source = "trap",
    })
    assertEqual(trapShield.notches, 1, "Aegis should also cover elected physical trap damage")
    assertTrue(not trapTarget.talents.aegis.wounded, "Aegis should prevent the elected trap effect")

    local flailTarget = base_entity.createEntity({
        id = "pc_aegis_flail",
        name = "Aegis Flail",
        isPC = true,
        armorSlots = 0,
        talentWoundSlots = 1,
        talents = {
            aegis = { mastered = true },
        },
    })
    flailTarget.inventory = inventory.createInventory()
    local flailShield = inventory.createItemFromTemplate("shield_heavy")
    flailTarget.inventory:addItem(flailShield, inventory.LOCATIONS.HANDS)
    local flail = inventory.createItem({
        name = "Morning Star",
        weaponType = "flail",
        isWeapon = true,
        isMelee = true,
    })
    local flailHit = resolver:resolve({
        actor = attacker,
        target = flailTarget,
        weapon = flail,
        card = { name = "Ace of Swords", value = 1, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 5,
        useAegis = true,
    })
    assertTrue(flailHit.success, "Flail Attacks should win Initiative ties even against shield users")
    assertTrue(hasValue(flailHit.effects, "flail_tie"), "flail tie-breaker should be reported")
    assertTrue(hasValue(flailHit.effects, "flail_shield_bypass"),
        "Flail Attacks should report bypassing elected shield absorption")
    assertEqual(flailShield.notches, 0, "Aegis should not Notch a shield against a flail Attack")
    assertTrue(flailTarget.talents.aegis.wounded,
        "Flail Attacks should use the normal wound track instead of Aegis prevention")
    assertTrue(not hasValue(flailHit.effects, "aegis_effect_prevented"),
        "Flail Attacks should not report Aegis prevention")

    local hammerTarget = base_entity.createEntity({
        id = "pc_hammer_crush_target",
        name = "Hammer Crush Target",
        isPC = true,
        armorSlots = 0,
        talentWoundSlots = 0,
        health = 3,
        defense = 0,
    })
    local hammerHit = resolver:resolve({
        actor = attacker,
        target = hammerTarget,
        weapon = inventory.createItem({
            name = "Warhammer",
            weaponType = "hammer",
            isWeapon = true,
            isMelee = true,
        }),
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 6,
    })
    assertTrue(hammerHit.success, "hammer Attacks should hit normally before checking the double-Initiative rider")
    assertEqual(hammerHit.damageDealt, 2, "hammer Attacks should deal 2 Wounds when Attack doubles Initiative")
    assertTrue(hasValue(hammerHit.effects, "hammer_crush"),
        "hammer double-Initiative damage should be recorded")

    local bladeRiposter = base_entity.createEntity({
        id = "pc_blade_riposter",
        name = "Blade Riposter",
        isPC = true,
    })
    bladeRiposter.inventory = inventory.createInventory()
    bladeRiposter.inventory:addItem(inventory.createItemFromTemplate("longsword"), inventory.LOCATIONS.HANDS)
    local bladeAttacker = base_entity.createEntity({
        id = "npc_blade_riposte_attacker",
        name = "Blade Riposte Attacker",
        isPC = false,
        health = 3,
        defense = 0,
    })
    local bladeRiposte = resolver:resolveRiposte(bladeRiposter, bladeAttacker, {
        type = "riposte",
        card = { name = "Eight of Cups", value = 8, suit = constants.SUITS.CUPS },
        value = 8,
        defender = bladeRiposter,
    }, 5)
    assertTrue(bladeRiposte.success, "blade Riposte setup should hit")
    assertEqual(bladeRiposte.damageDealt, 2, "blade Ripostes should deal 2 Wounds")
    assertTrue(hasValue(bladeRiposte.effects, "blade_riposte"),
        "blade Riposte damage should be recorded")
end

local function checkDoomEyePerfectShotTalent()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local activeChallenge = {
        isActive = function()
            return true
        end,
    }
    local function makeArcher(id, talents)
        local actor = base_entity.createEntity({
            id = id,
            name = id,
            isPC = true,
            swords = 0,
            talents = talents,
        })
        actor.inventory = inventory.createInventory()
        actor.inventory:addItem(inventory.createItemFromTemplate("bow"), inventory.LOCATIONS.HANDS)
        actor.ammo = 2
        return actor
    end

    local doomArcher = makeArcher("pc_doom_eye", {
        doom_eye = { mastered = true },
    })
    local target = base_entity.createEntity({
        id = "npc_doom_eye_target",
        name = "Doom Eye Target",
        isPC = false,
        health = 2,
        defense = 0,
    })
    local shot = resolver:resolve({
        actor = doomArcher,
        target = target,
        card = { name = "Two of Swords", value = 2, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MISSILE,
        targetInitiative = 20,
        useDoomEye = true,
        challengeController = activeChallenge,
    })
    assertTrue(shot.success, "Doom Eye should auto-hit regardless of target Initiative")
    assertTrue(shot.doomEyeAutoHit, "Doom Eye should mark auto-hit metadata")
    assertTrue(hasValue(shot.effects, "doom_eye_auto_hit"), "Doom Eye should report auto-hit")
    assertTrue(hasValue(shot.effects, "doom_eye_ignores_initiative"),
        "Doom Eye should report that Initiative was ignored")
    assertEqual(target.npcHealth, 1, "Doom Eye hit should still apply missile damage")
    assertEqual(doomArcher.ammo, 1, "Doom Eye should still spend ammunition")
    local actionSequencer = require('ui.action_sequencer')
    local sequencer = actionSequencer.createActionSequencer({ eventBus = events.createEventBus() })
    sequencer:queueActionSequence({
        action = {
            actor = doomArcher,
            target = target,
            card = { name = "Two of Swords", value = 2, suit = constants.SUITS.SWORDS },
        },
        result = shot,
    })
    local hasDoomEyePopup = false
    for _, step in ipairs(sequencer.currentSequence or {}) do
        if step.type == actionSequencer.STEP_TYPES.TEXT_POPUP and
           step.data and step.data.title == "Doom Eye" then
            hasDoomEyePopup = true
            assertEqual(step.data.target, target,
                "Doom Eye popup should include the target whose Initiative was ignored")
            assertTrue(step.data.autoHit,
                "Doom Eye popup should mark the automatic hit")
            break
        end
    end
    assertTrue(hasDoomEyePopup, "Doom Eye perfect shots should queue a visible popup")

    local dodgeTarget = base_entity.createEntity({
        id = "npc_doom_eye_dodge",
        name = "Doom Eye Dodge Target",
        isPC = false,
        health = 2,
        defense = 0,
    })
    dodgeTarget:prepareDefense("dodge", { name = "King of Cups", value = 14, suit = constants.SUITS.CUPS }, 20)
    local dodgedShot = resolver:resolve({
        actor = doomArcher,
        target = dodgeTarget,
        card = { name = "Two of Swords", value = 2, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MISSILE,
        targetInitiative = 20,
        useDoomEye = true,
        challengeController = activeChallenge,
    })
    assertTrue(dodgedShot.success, "Doom Eye should ignore Dodge-boosted Initiative")
    assertTrue(hasValue(dodgedShot.effects, "doom_eye_ignores_dodge"),
        "Doom Eye should report ignored Dodge")
    assertTrue(not dodgeTarget:hasDefense(), "Doom Eye shot should still consume the prepared defense")

    local ordinaryShot = resolver:resolve({
        actor = makeArcher("pc_doom_eye_no_election", {
            doom_eye = { mastered = true },
        }),
        target = base_entity.createEntity({
            id = "npc_doom_eye_ordinary",
            name = "Doom Eye Ordinary Target",
            isPC = false,
            health = 2,
            defense = 0,
        }),
        card = { name = "Two of Swords", value = 2, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MISSILE,
        targetInitiative = 20,
        challengeController = activeChallenge,
    })
    assertTrue(not ordinaryShot.success, "Doom Eye should require explicit election")
    assertTrue(not hasValue(ordinaryShot.effects, "doom_eye_auto_hit"),
        "ordinary missile shots should not report Doom Eye")

    local wrongCard = resolver:resolve({
        actor = makeArcher("pc_doom_eye_wrong_card", {
            doom_eye = { mastered = true },
        }),
        target = target,
        card = { name = "Two of Cups", value = 2, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.MISSILE,
        targetInitiative = 20,
        useDoomEye = true,
        challengeController = activeChallenge,
    })
    assertTrue(not wrongCard.success, "Doom Eye should reject non-Sword cards")
    assertEqual(wrongCard.description, "Doom Eye requires a Sword card",
        "Doom Eye should explain the card-suit requirement")
    assertTrue(hasValue(wrongCard.effects, "doom_eye_blocked"), "blocked Doom Eye should report a block")

    local noTalent = resolver:resolve({
        actor = makeArcher("pc_no_doom_eye", {}),
        target = target,
        card = { name = "Two of Swords", value = 2, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MISSILE,
        targetInitiative = 20,
        useDoomEye = true,
        challengeController = activeChallenge,
    })
    assertTrue(not noTalent.success, "Doom Eye should require the talent")
    assertEqual(noTalent.description, "Requires Doom Eye", "missing Doom Eye should explain the requirement")

    local previousLove = love
    love = {
        graphics = {
            getDimensions = function()
                return 1280, 720
            end,
        },
    }

    local uiBus = events.createEventBus()
    local emitted = nil
    uiBus:on("action_selected", function(data)
        emitted = data
    end)

    local board = command_board.createCommandBoard({ eventBus = uiBus })
    local uiArcher = makeArcher("pc_doom_eye_ui", {
        doom_eye = { mastered = true },
    })
    local uiCard = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS }
    board:show(uiCard, uiArcher, true)
    local missileButton = nil
    for _, button in ipairs(board.buttons) do
        if button.action and button.action.id == "missile" then
            missileButton = button
            break
        end
    end
    assertTrue(missileButton ~= nil, "Doom Eye Command Board setup should expose missile Attack")
    board:mousepressed(missileButton.x + 1, missileButton.y + 1, 1)
    assertEqual(board.mode, "doom_eye_option", "Doom Eye missile selection should prompt for normal shot or Doom Eye")
    assertTrue(emitted == nil, "Doom Eye shot approach picker should wait for an approach selection")

    local doomEyeButton = nil
    for _, button in ipairs(board.buttons) do
        if button.action and button.action.useDoomEye then
            doomEyeButton = button
            break
        end
    end
    assertTrue(doomEyeButton ~= nil, "Doom Eye shot approach picker should include Doom Eye Shot")
    board:mousepressed(doomEyeButton.x + 1, doomEyeButton.y + 1, 1)
    assertTrue(emitted ~= nil, "Doom Eye shot approach selection should emit action_selected")
    assertEqual(emitted.action.id, "missile", "Doom Eye approach should preserve missile Attack action type")
    assertTrue(emitted.action.useDoomEye, "Doom Eye approach should mark the action as a perfect shot")

    local submitted = nil
    local uiTarget = base_entity.createEntity({
        id = "npc_doom_eye_ui_target",
        name = "Doom Eye UI Target",
        isPC = false,
        health = 2,
        defense = 0,
        conditions = {},
    })
    local inputController = challenge_input_controller.createChallengeInputController({
        eventBus = events.createEventBus(),
        inputState = {
            selectedCard = uiCard,
            selectedCardIndex = 1,
            selectedEntity = uiArcher,
        },
        gameState = {
            challengeController = {
                npcs = { uiTarget },
                pcs = { uiArcher },
                allCombatants = { uiArcher, uiTarget },
                getState = function()
                    return "awaiting_action"
                end,
                submitAction = function(_, action)
                    submitted = action
                    return true
                end,
            },
            playerHand = {
                getHand = function()
                    return { uiCard }
                end,
                discardCard = function()
                    return uiCard, 1, nil
                end,
            },
        },
    })
    inputController:handleActionSelected(emitted)
    assertTrue(inputController:getState().awaitingTarget,
        "Doom Eye missile action should continue into target selection")
    inputController:handleTargetSelection("1")
    assertTrue(submitted ~= nil, "Doom Eye target selection should submit the missile action")
    assertEqual(submitted.target, uiTarget, "Doom Eye target picker should keep the selected target")
    assertTrue(submitted.useDoomEye, "Doom Eye target selection should preserve the perfect-shot election")

    love = previousLove
end

local function checkGramaryeArchwoodWandAttacks()
    local wandCard = { name = "Seven of Wands", value = 7, suit = constants.SUITS.WANDS }
    local function makeWandBearer(id, talents)
        local actor = base_entity.createEntity({
            id = id,
            name = id,
            isPC = true,
            swords = 0,
            wands = 3,
            talents = talents,
        })
        actor.inventory = inventory.createInventory()
        actor.inventory:addItem(inventory.createItemFromTemplate("wand_archwood"), inventory.LOCATIONS.HANDS)
        return actor
    end
    local function hasAction(actions, id)
        for _, action in ipairs(actions or {}) do
            if action.id == id then
                return true
            end
        end
        return false
    end

    local gramarye = makeWandBearer("pc_gramarye", {
        gramarye = { mastered = true },
    })
    local plain = makeWandBearer("pc_no_gramarye", {})

    assertTrue(hasAction(action_registry.getAvailableActions(wandCard, false, gramarye), "missile"),
        "Gramarye should allow an archwood wand Attack with a Wands minor card")
    assertTrue(not hasAction(action_registry.getAvailableActions(wandCard, false, plain), "missile"),
        "archwood wand missile Attacks should require Gramarye")

    local controller = challenge_controller.createChallengeController({
        eventBus = events.createEventBus(),
    })
    controller.state = challenge_controller.STATES.MINOR_WINDOW
    controller.activeEntity = base_entity.createEntity({ id = "active_gramarye_turn", isPC = true })
    local ok, err = controller:declareMinorAction(gramarye, wandCard, {
        type = action_resolver.ACTION_TYPES.MISSILE,
    })
    assertTrue(ok, "Gramarye should pass the Wands-card minor declaration suit gate")

    local blockedController = challenge_controller.createChallengeController({
        eventBus = events.createEventBus(),
    })
    blockedController.state = challenge_controller.STATES.MINOR_WINDOW
    blockedController.activeEntity = controller.activeEntity
    ok, err = blockedController:declareMinorAction(plain, wandCard, {
        type = action_resolver.ACTION_TYPES.MISSILE,
    })
    assertTrue(not ok, "Wands-card missile minors should be rejected without Gramarye")
    assertEqual(err, "suit_mismatch", "missing Gramarye should preserve the suit-mismatch reason")

    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local activeChallenge = {
        isActive = function()
            return true
        end,
    }
    local target = base_entity.createEntity({
        id = "npc_gramarye_target",
        name = "Gramarye Target",
        isPC = false,
        health = 2,
        defense = 0,
    })
    local blast = resolver:resolve({
        actor = gramarye,
        target = target,
        card = wandCard,
        type = action_resolver.ACTION_TYPES.MISSILE,
        targetInitiative = 9,
        challengeController = activeChallenge,
    })
    assertTrue(blast.success, "Gramarye wand Attack should use Wands value during Challenges")
    assertEqual(blast.testValue, 10, "Gramarye wand Attack should add Wands instead of Swords")
    assertTrue(hasValue(blast.effects, "gramary_wand_attack"), "Gramarye should report wand attack")
    assertTrue(hasValue(blast.effects, "gramary_wands_action"), "Gramarye should report Wands-action routing")
    assertEqual(target.npcHealth, 1, "Gramarye wand Attack should damage as a weapon")

    local blocked = resolver:resolve({
        actor = plain,
        target = target,
        card = wandCard,
        type = action_resolver.ACTION_TYPES.MISSILE,
        targetInitiative = 9,
        challengeController = activeChallenge,
    })
    assertTrue(not blocked.success, "non-Gramarye archwood wand missile Attack should be blocked")
    assertEqual(blocked.description, "Requires ranged weapon in hands",
        "blocked archwood wand Attack should explain the missing missile-weapon permission")
end

local function checkHeavyMetalMachineInterruptTalent()
    local bus = events.createEventBus()
    local hmmAppliedEvent = nil
    bus:on("heavy_metal_machine_interrupt_applied", function(data)
        hmmAppliedEvent = data
    end)
    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
    })
    local defender = base_entity.createEntity({
        id = "pc_heavy_metal_machine",
        name = "Heavy Metal Machine",
        isPC = true,
        swords = 3,
        talents = {
            heavy_metal_machine = { mastered = true },
        },
    })
    defender.inventory = inventory.createInventory()
    defender.inventory:addItem(inventory.createItemFromTemplate("iron_armor"), inventory.LOCATIONS.BELT)

    local slot = {
        card = { name = "Five of Pentacles", value = 5, suit = constants.SUITS.PENTACLES },
        value = 5,
        revealed = false,
    }
    local controller = {
        currentRound = 4,
        isActive = function()
            return true
        end,
        getInitiativeSlot = function(_, entityId)
            if entityId == defender.id then
                return slot
            end
            return nil
        end,
    }

    local readied = resolver:resolve({
        actor = defender,
        card = { name = "Two of Cups", value = 2, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.HEAVY_METAL_MACHINE,
        challengeController = controller,
        againstActorId = "npc_hmm_attacker",
    })
    assertTrue(readied.success, "Heavy Metal Machine should ready as a miscellaneous interrupt")
    assertTrue(hasValue(readied.effects, "heavy_metal_machine_readied"),
        "Heavy Metal Machine should report the readied interrupt")
    assertEqual(readied.heavyMetalMachine.bonus, 3, "Heavy Metal Machine should add Swords to Initiative")

    local attacker = base_entity.createEntity({
        id = "npc_hmm_attacker",
        name = "HMM Attacker",
        isPC = false,
        swords = 0,
        health = 2,
        defense = 0,
    })
    local attack = resolver:resolve({
        actor = attacker,
        target = defender,
        card = { name = "Four of Swords", value = 4, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        challengeController = controller,
    })
    assertTrue(not attack.success, "Heavy Metal Machine should boost Initiative against the chosen action")
    assertEqual(attack.difficulty, 8, "Heavy Metal Machine should add Swords to the base Initiative")
    assertTrue(hasValue(attack.effects, "heavy_metal_machine_interrupt"),
        "the defended action should report Heavy Metal Machine")
    assertEqual(hmmAppliedEvent and hmmAppliedEvent.actor, defender,
        "Heavy Metal Machine should emit presentation details when consumed")
    assertEqual(hmmAppliedEvent and hmmAppliedEvent.value, 8,
        "Heavy Metal Machine presentation event should report boosted Initiative")
    local actionSequencer = require('ui.action_sequencer')
    local sequencer = actionSequencer.createActionSequencer({ eventBus = events.createEventBus() })
    sequencer:queueActionSequence({
        action = {
            actor = attacker,
            target = defender,
            card = { name = "Four of Swords", value = 4, suit = constants.SUITS.SWORDS },
        },
        result = attack,
    })
    local hasPopup = false
    for _, step in ipairs(sequencer.currentSequence or {}) do
        if step.type == actionSequencer.STEP_TYPES.TEXT_POPUP and
           step.data and step.data.title == "Heavy Metal Machine" then
            hasPopup = true
            assertEqual(step.data.value, 8,
                "Heavy Metal Machine popup should include boosted Initiative")
            break
        end
    end
    assertTrue(hasPopup, "Heavy Metal Machine should queue a visible interrupt popup")
    assertTrue(defender.heavyMetalMachineInterrupt == nil, "Heavy Metal Machine should be consumed after one action")
    assertEqual(slot.value, 5, "Heavy Metal Machine should not permanently replace Initiative")

    local spent = resolver:resolve({
        actor = defender,
        card = { name = "Three of Wands", value = 3, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.HEAVY_METAL_MACHINE,
        challengeController = controller,
    })
    assertTrue(not spent.success, "Heavy Metal Machine should be once per round")
    assertTrue(hasValue(spent.effects, "heavy_metal_machine_spent"),
        "spent Heavy Metal Machine should report the round limit")

    controller.currentRound = 5
    local nextRound = resolver:resolve({
        actor = defender,
        card = { name = "Four of Pentacles", value = 4, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.HEAVY_METAL_MACHINE,
        challengeController = controller,
    })
    assertTrue(nextRound.success, "Heavy Metal Machine should reset on a new round")

    local lightArmor = base_entity.createEntity({
        id = "pc_hmm_light_armor",
        name = "HMM Light Armor",
        isPC = true,
        swords = 3,
        talents = {
            heavy_metal_machine = { mastered = true },
        },
    })
    lightArmor.inventory = inventory.createInventory()
    lightArmor.inventory:addItem(inventory.createItemFromTemplate("light_armor"), inventory.LOCATIONS.BELT)
    local blockedArmor = resolver:resolve({
        actor = lightArmor,
        card = { name = "Two of Cups", value = 2, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.HEAVY_METAL_MACHINE,
        challengeController = {
            currentRound = 1,
            isActive = function()
                return true
            end,
            getInitiativeSlot = function()
                return { value = 5 }
            end,
        },
    })
    assertTrue(not blockedArmor.success, "Heavy Metal Machine should require iron or steel armor")
    assertEqual(blockedArmor.description, "Requires worn iron or steel armor.",
        "wrong armor should explain the Heavy Metal Machine requirement")

    local previousLove = love
    love = {
        graphics = {
            getDimensions = function()
                return 1280, 720
            end,
        },
    }

    local emitted = nil
    local bus = events.createEventBus()
    bus:on("action_selected", function(data)
        emitted = data
    end)

    local board = command_board.createCommandBoard({ eventBus = bus })
    local boardCard = { name = "Two of Cups", value = 2, suit = constants.SUITS.CUPS }
    board:show(boardCard, defender, true)
    local hmmButton = nil
    for _, button in ipairs(board.buttons) do
        if button.action and button.action.id == "heavy_metal_machine" then
            hmmButton = button
            break
        end
    end
    assertTrue(hmmButton ~= nil, "Command Board should expose Heavy Metal Machine")
    assertTrue(hmmButton.enabled, "Heavy Metal Machine should be enabled for iron-armored talent users")
    board:mousepressed(hmmButton.x + 1, hmmButton.y + 1, 1)
    assertTrue(emitted ~= nil, "Heavy Metal Machine button should emit action_selected")
    assertEqual(emitted.action.id, "heavy_metal_machine",
        "Heavy Metal Machine emission should carry the resolver action id")

    local submitted = nil
    local fakeChallenge = {
        allCombatants = { defender },
        getState = function()
            return "awaiting_action"
        end,
        submitAction = function(_, action)
            submitted = action
            return true
        end,
    }
    local fakeHand = {
        getHand = function()
            return { boardCard }
        end,
        discardCard = function()
            return boardCard, 1, nil
        end,
    }
    local inputController = challenge_input_controller.createChallengeInputController({
        gameState = {
            challengeController = fakeChallenge,
            playerHand = fakeHand,
        },
        eventBus = events.createEventBus(),
        inputState = {
            selectedCard = boardCard,
            selectedCardIndex = 1,
            selectedEntity = defender,
        },
    })
    inputController:handleActionSelected(emitted)
    assertTrue(submitted ~= nil, "Heavy Metal Machine should submit without target selection")
    assertEqual(submitted.type, action_resolver.ACTION_TYPES.HEAVY_METAL_MACHINE,
        "Heavy Metal Machine submitted action should keep resolver action type")
    assertEqual(submitted.card, boardCard, "Heavy Metal Machine submitted action should keep selected card")
    assertEqual(submitted.allEntities, fakeChallenge.allCombatants,
        "Heavy Metal Machine submitted action should carry challenge combatants")

    board:show(boardCard, lightArmor, true)
    local blockedButton = nil
    for _, button in ipairs(board.buttons) do
        if button.action and button.action.id == "heavy_metal_machine" then
            blockedButton = button
            break
        end
    end
    assertTrue(blockedButton ~= nil, "Command Board should still show blocked Heavy Metal Machine")
    assertTrue(not blockedButton.enabled, "Heavy Metal Machine should be disabled without iron or steel armor")
    assertEqual(blockedButton.disabledReason, "Requires worn iron or steel armor.",
        "blocked Heavy Metal Machine should explain the armor gate")

    local promptBus = events.createEventBus()
    local promptResolver = action_resolver.createActionResolver({ eventBus = promptBus })
    local promptDefender = base_entity.createEntity({
        id = "pc_hmm_prompt_defender",
        name = "HMM Prompt Defender",
        isPC = true,
        swords = 3,
        talents = {
            heavy_metal_machine = { mastered = true },
        },
    })
    promptDefender.inventory = inventory.createInventory()
    promptDefender.inventory:addItem(inventory.createItemFromTemplate("steel_armor"), inventory.LOCATIONS.BELT)
    local promptAttacker = base_entity.createEntity({
        id = "npc_hmm_prompt_attacker",
        name = "HMM Prompt Attacker",
        isPC = false,
        swords = 0,
        health = 2,
        defense = 0,
    })
    local promptCard = { name = "Two of Cups", value = 2, suit = constants.SUITS.CUPS }
    local promptCards = { promptCard }
    local promptHand = { discarded = {} }
    function promptHand:getHand(entity)
        if entity and entity.id == promptDefender.id then
            return promptCards
        end
        return {}
    end
    function promptHand:discardCard(_, opts)
        opts = opts or {}
        local index = opts.index
        if opts.card then
            for i, card in ipairs(promptCards) do
                if card == opts.card then
                    index = i
                    break
                end
            end
        end
        index = index or 1
        local removed = table.remove(promptCards, index)
        self.discarded[#self.discarded + 1] = removed
        return removed, index, nil
    end

    local promptController = challenge_controller.createChallengeController({
        eventBus = promptBus,
        playerHand = promptHand,
    })
    promptController.state = challenge_controller.STATES.AWAITING_ACTION
    promptController.currentRound = 6
    promptController.currentCount = 4
    promptController.activeEntity = promptAttacker
    promptController.pcs = { promptDefender }
    promptController.npcs = { promptAttacker }
    promptController.allCombatants = { promptDefender, promptAttacker }
    promptController.initiativeSlots[promptDefender.id] = {
        card = { name = "Five of Pentacles", value = 5, suit = constants.SUITS.PENTACLES },
        value = 5,
        revealed = false,
    }

    local promptInput = challenge_input_controller.createChallengeInputController({
        eventBus = promptBus,
        gameState = {
            challengeController = promptController,
            playerHand = promptHand,
            guild = { promptDefender },
        },
    })
    promptInput:init()

    local promptOverlay = require('ui.challenge_overlay').createChallengeOverlay({
        gameState = {
            challengeController = promptController,
            playerHand = promptHand,
        },
        inputState = promptInput:getState(),
    })

    local promptIncomingSeen = nil
    promptBus:on(events.EVENTS.CHALLENGE_ACTION, function(action)
        promptIncomingSeen = action
        action.result = promptResolver:resolve(action)
        promptController:resolveAction(action)
    end)

    local promptAttack = {
        target = promptDefender,
        type = action_resolver.ACTION_TYPES.MELEE,
        card = { name = "Four of Swords", value = 4, suit = constants.SUITS.SWORDS },
    }
    local promptOk, promptReason = promptController:submitAction(promptAttack)
    assertTrue(promptOk, "incoming Heavy Metal Machine prompt action should pause successfully")
    assertTrue(promptInput:getState().pendingHeavyMetalMachineInterrupt ~= nil,
        "input controller should store the pending Heavy Metal Machine prompt")
    assertTrue(promptIncomingSeen == nil,
        "Heavy Metal Machine prompt should wait for a player card before resolving the incoming action")
    local hmmPrompt = promptOverlay:getFooterPrompt(promptController:getState(), promptController:getActiveEntity())
    assertTrue(hmmPrompt and hmmPrompt:find("Heavy Metal Machine"),
        "Challenge overlay should surface the Heavy Metal Machine prompt")

    promptInput:handleChallengeInput("q")
    assertTrue(promptIncomingSeen ~= nil, "Q should play the prompted Heavy Metal Machine card")
    assertEqual(#promptCards, 0, "prompted Heavy Metal Machine card should be discarded")
    assertTrue(promptInput:getState().pendingHeavyMetalMachineInterrupt == nil,
        "Heavy Metal Machine prompt should clear after a card is played")
    assertTrue(promptIncomingSeen.result and not promptIncomingSeen.result.success,
        "prompted Heavy Metal Machine should make the incoming low Attack miss")
    assertEqual(promptIncomingSeen.result.difficulty, 8,
        "prompted Heavy Metal Machine should add Swords to target Initiative")
    assertTrue(hasValue(promptIncomingSeen.result.effects, "heavy_metal_machine_interrupt"),
        "prompted Heavy Metal Machine result should report the interrupt")
    assertTrue(promptDefender.heavyMetalMachineInterrupt == nil,
        "prompted Heavy Metal Machine should be consumed by the incoming action")
    assertEqual(promptDefender.heavyMetalMachineUsedRound, 6,
        "prompted Heavy Metal Machine should spend the round use")

    love = previousLove
end

local function checkMonsterHunterAttackFavorTalent()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local activeChallenge = {
        isActive = function()
            return true
        end,
    }

    local function makeHunter(id, talents)
        local actor = base_entity.createEntity({
            id = id,
            name = id,
            isPC = true,
            swords = 1,
            talents = talents,
        })
        actor.inventory = inventory.createInventory()
        actor.inventory:addItem(inventory.createItemFromTemplate("longsword"), inventory.LOCATIONS.HANDS)
        return actor
    end

    local function makeTarget(id, tags)
        local target = base_entity.createEntity({
            id = id,
            name = id,
            isPC = false,
            health = 3,
            defense = 0,
        })
        target.tags = tags
        return target
    end

    local beastHunter = makeHunter("pc_beast_hunter", {
        monster_hunter = {
            mastered = true,
            foe = "Beast",
            specialization = "cockatrice",
            specializationTags = { "cockatrice" },
        },
    })
    local cockatrice = makeTarget("npc_cockatrice", { "beast", "cockatrice" })
    local favoredAction = {
        actor = beastHunter,
        target = cockatrice,
        card = { name = "Five of Swords", value = 5, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 9,
        challengeController = activeChallenge,
    }
    local favored = resolver:resolve(favoredAction)
    assertTrue(favored.success, "Monster Hunter should grant attack favor against the chosen specialization")
    assertEqual(favored.favorModifier, 3, "Monster Hunter favor should add the standard +3")
    assertEqual(favored.testValue, 9, "Monster Hunter favor should modify the Attack value")
    assertTrue(hasValue(favored.effects, "monster_hunter_attack_favor"),
        "Monster Hunter favor should be reported")
    assertEqual(favored.monsterHunter.foe, "Beast", "Monster Hunter metadata should preserve the hated foe")
    assertEqual(favored.monsterHunter.target, cockatrice,
        "Monster Hunter attack metadata should preserve the hunted target")
    assertEqual(favored.monsterHunter.specialization, "cockatrice",
        "Monster Hunter attack metadata should preserve the matched specialization")
    local hunterPopup = getActionSequencerPopup(favoredAction, favored, function(data)
        return data.title == "Monster Hunter"
    end)
    assertTrue(hunterPopup ~= nil, "Monster Hunter attack favor should queue an action-sequencer popup")
    assertEqual(hunterPopup.target, cockatrice,
        "Monster Hunter popup should preserve the hunted target")
    assertEqual(hunterPopup.specialization, "cockatrice",
        "Monster Hunter popup should preserve the matched specialization")

    local wrongTarget = resolver:resolve({
        actor = beastHunter,
        target = makeTarget("npc_wrong_hunter_target", { "beast", "wolf" }),
        card = { name = "Five of Swords", value = 5, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 9,
        challengeController = activeChallenge,
    })
    assertTrue(not wrongTarget.success, "Monster Hunter should not favor non-specialization targets")
    assertTrue(not hasValue(wrongTarget.effects, "monster_hunter_attack_favor"),
        "non-specialization targets should not report Hunter favor")

    local fateRequest = nil
    local fateBus = events.createEventBus()
    fateBus:on(events.EVENTS.REQUEST_TEST_OF_FATE, function(data)
        fateRequest = data
    end)
    local fateResolver = action_resolver.createActionResolver({
        eventBus = fateBus,
    })
    local hunterFate = fateResolver:resolve({
        actor = beastHunter,
        target = cockatrice,
        card = { name = "Three of Pentacles", value = 3, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.TEST_FATE,
        testAttribute = "pentacles",
        testMotif = "Beast Hunter",
        testContext = "tracking the cockatrice",
        challengeController = activeChallenge,
    })
    assertTrue(hunterFate.pendingTestOfFate,
        "Monster Hunter motif should route related tests through Test Fate")
    assertTrue(fateRequest and fateRequest.favor == true,
        "Monster Hunter motif should grant favor on related Tests of Fate")
    assertEqual(fateRequest.motif, "Beast Hunter",
        "Monster Hunter Test Fate should report the generated Hunter motif")
    assertTrue(hasValue(hunterFate.effects, "monster_hunter_test_fate_motif_favor"),
        "Monster Hunter Test Fate motif favor should be auditable")

    fateRequest = nil
    local wrongHunterFate = fateResolver:resolve({
        actor = beastHunter,
        target = makeTarget("npc_hunter_fate_wolf", { "beast", "wolf" }),
        card = { name = "Three of Pentacles", value = 3, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.TEST_FATE,
        testAttribute = "pentacles",
        testMotif = "Beast Hunter",
        testContext = "tracking a wolf",
        challengeController = activeChallenge,
    })
    assertTrue(wrongHunterFate.pendingTestOfFate,
        "non-specialization Hunter motif tests should still request ordinary Test Fate adjudication")
    assertTrue(fateRequest and fateRequest.favor == nil,
        "non-specialization Hunter motif tests should not grant favor")
    assertTrue(hasValue(wrongHunterFate.effects, "test_fate_motif_unavailable"),
        "non-specialization Hunter motif tests should report unavailable motif favor")

    local cityHunter = makeHunter("pc_city_monster_hunter", {
        monster_hunter = {
            mastered = true,
        },
    })
    local hunterCityController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { cityHunter },
    })
    local ok, result, detail = hunterCityController:resolveAction(cityHunter, {
        type = "change_monster_hunter_foe",
        foe = "Beast",
        specialization = "cockatrice",
        reason = "The last cockatrice made this personal.",
    })
    assertTrue(ok, "Monster Hunter should be able to change hated foe as a City Action")
    assertEqual(result, "monster_hunter_foe_chosen",
        "Monster Hunter City Action should report chosen foe")
    assertEqual(cityHunter.talents.monster_hunter.foe, "Beast",
        "Monster Hunter City Action should store the hated foe")
    assertEqual(cityHunter.talents.monster_hunter.specialization, "cockatrice",
        "Monster Hunter City Action should store the specialization")
    assertEqual(cityHunter.talents.monster_hunter.motif, "Beast Hunter",
        "Monster Hunter City Action should expose the generated Hunter motif")
    assertTrue(hunterCityController:hasActed(cityHunter),
        "Monster Hunter foe change should consume the actor's City Action")

    local cityHunterFavored = resolver:resolve({
        actor = cityHunter,
        target = makeTarget("npc_city_hunter_cockatrice", { "beast", "cockatrice" }),
        card = { name = "Five of Swords", value = 5, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 9,
        challengeController = activeChallenge,
    })
    assertTrue(cityHunterFavored.success,
        "changed Monster Hunter specialization should feed Attack favor")
    assertTrue(hasValue(cityHunterFavored.effects, "monster_hunter_attack_favor"),
        "changed Monster Hunter specialization should report Hunter favor")

    local woundedCityHunter = makeHunter("pc_city_wounded_monster_hunter", {
        monster_hunter = {
            mastered = true,
            wounded = true,
        },
    })
    local woundedHunterCityController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { woundedCityHunter },
    })
    ok, result = woundedHunterCityController:resolveAction(woundedCityHunter, {
        type = "change_monster_hunter_foe",
        foe = "Beast",
        specialization = "cockatrice",
    })
    assertTrue(not ok, "wounded Monster Hunter should not change hated foe")
    assertEqual(result, "Monster Hunter talent is wounded",
        "wounded Monster Hunter City Action should explain the wounded talent")
    assertTrue(not woundedHunterCityController:hasActed(woundedCityHunter),
        "failed Monster Hunter foe change should not consume the City Action")

    local woundedHunter = makeHunter("pc_wounded_hunter", {
        monster_hunter = {
            mastered = true,
            wounded = true,
            foe = "Beast",
            specialization = "cockatrice",
        },
    })
    local woundedAttack = resolver:resolve({
        actor = woundedHunter,
        target = makeTarget("npc_wounded_hunter_target", { "beast", "cockatrice" }),
        card = { name = "Five of Swords", value = 5, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 9,
        challengeController = activeChallenge,
    })
    assertTrue(not woundedAttack.success, "wounded Monster Hunter should not grant attack favor")

    fateRequest = nil
    local woundedFate = fateResolver:resolve({
        actor = woundedHunter,
        target = cockatrice,
        card = { name = "Three of Pentacles", value = 3, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.TEST_FATE,
        testAttribute = "pentacles",
        testMotif = "Beast Hunter",
        testContext = "tracking the cockatrice",
        challengeController = activeChallenge,
    })
    assertTrue(woundedFate.pendingTestOfFate,
        "wounded Hunter motif tests should still request ordinary Test Fate adjudication")
    assertTrue(fateRequest and fateRequest.favor == nil,
        "wounded Monster Hunter should not grant Test Fate motif favor")
    assertTrue(not hasValue(woundedFate.effects, "monster_hunter_test_fate_motif_favor"),
        "wounded Monster Hunter should not report Hunter Test Fate favor")

    local undeadHunter = makeHunter("pc_undead_hunter", {
        undead_hunter = {
            mastered = true,
            specialization = "skeleton",
        },
    })
    local skeleton = makeTarget("npc_skeleton_hunter_target", { "undead", "skeleton" })
    skeleton.undead = true
    local undeadFavored = resolver:resolve({
        actor = undeadHunter,
        target = skeleton,
        card = { name = "Five of Swords", value = 5, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 9,
        challengeController = activeChallenge,
    })
    assertTrue(undeadFavored.success, "specific Hunter talents should also grant specialization favor")
    assertEqual(undeadFavored.monsterHunter.talentId, "undead_hunter",
        "Hunter metadata should preserve the specific Hunter talent")
end

local function checkTwoHandedFocusMinorAttackTalent()
    local pentaclesCard = { name = "Seven of Pentacles", value = 7, suit = constants.SUITS.PENTACLES }
    local swordsCard = { name = "Seven of Swords", value = 7, suit = constants.SUITS.SWORDS }

    local function hasAction(actions, id)
        for _, action in ipairs(actions or {}) do
            if action.id == id then
                return true
            end
        end
        return false
    end

    local function makeActor(id, talents, itemIds)
        local actor = base_entity.createEntity({
            id = id,
            name = id,
            isPC = true,
            talents = talents,
        })
        actor.inventory = inventory.createInventory()
        for _, itemId in ipairs(itemIds or {}) do
            actor.inventory:addItem(inventory.createItemFromTemplate(itemId), inventory.LOCATIONS.HANDS)
        end
        return actor
    end

    local focus = makeActor("pc_two_handed_focus", {
        two_handed_focus = { mastered = true },
    }, { "longsword" })
    assertTrue(hasAction(action_registry.getAvailableActions(pentaclesCard, false, focus), "melee"),
        "Two-handed Focus should allow Pentacles-card minor melee Attacks")
    assertTrue(hasAction(action_registry.getAvailableActions(swordsCard, false, focus), "melee"),
        "Two-handed Focus should preserve Swords-card minor melee Attacks")

    local plain = makeActor("pc_no_two_handed_focus", {}, { "longsword" })
    assertTrue(not hasAction(action_registry.getAvailableActions(pentaclesCard, false, plain), "melee"),
        "Pentacles-card minor melee Attacks should require Two-handed Focus")

    local daggerFocus = makeActor("pc_dagger_focus", {
        two_handed_focus = { mastered = true },
    }, { "dagger" })
    assertTrue(not hasAction(action_registry.getAvailableActions(pentaclesCard, false, daggerFocus), "melee"),
        "Two-handed Focus should not work with daggers")

    local shieldFocus = makeActor("pc_shield_focus", {
        two_handed_focus = { mastered = true },
    }, { "longsword", "shield_light" })
    assertTrue(not hasAction(action_registry.getAvailableActions(pentaclesCard, false, shieldFocus), "melee"),
        "Two-handed Focus should require a free second hand for one-slot weapons")

    local controller = challenge_controller.createChallengeController({
        eventBus = events.createEventBus(),
    })
    controller.state = challenge_controller.STATES.MINOR_WINDOW
    controller.activeEntity = base_entity.createEntity({ id = "active_two_handed_focus_turn", isPC = true })
    local ok, err = controller:declareMinorAction(focus, pentaclesCard, {
        type = action_resolver.ACTION_TYPES.MELEE,
    })
    assertTrue(ok, "Two-handed Focus should pass the Pentacles-card minor declaration suit gate")

    local blockedController = challenge_controller.createChallengeController({
        eventBus = events.createEventBus(),
    })
    blockedController.state = challenge_controller.STATES.MINOR_WINDOW
    blockedController.activeEntity = controller.activeEntity
    ok, err = blockedController:declareMinorAction(plain, pentaclesCard, {
        type = action_resolver.ACTION_TYPES.MELEE,
    })
    assertTrue(not ok, "Pentacles-card melee minors should be rejected without Two-handed Focus")
    assertEqual(err, "suit_mismatch", "missing Two-handed Focus should preserve the suit-mismatch reason")

    focus.swords = 4
    local target = base_entity.createEntity({
        id = "npc_two_handed_focus_target",
        name = "Training Target",
        isPC = false,
        health = 2,
        defense = 0,
    })
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local focusAction = {
        actor = focus,
        target = target,
        card = pentaclesCard,
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 6,
        isMinorAction = true,
    }
    local focusResult = resolver:resolve(focusAction)
    assertTrue(focusResult.success, "Two-handed Focus minor melee Attack should resolve normally")
    assertEqual(focusResult.modifier, 0, "Two-handed Focus minor Attack should still use card value only")
    assertTrue(hasValue(focusResult.effects, "two_handed_focus_minor_attack"),
        "Two-handed Focus minor Attack should report its talent use")
    assertTrue(focusResult.twoHandedFocusMinorAttack ~= nil,
        "Two-handed Focus minor Attack should preserve presentation metadata")
    assertEqual(focusResult.twoHandedFocusMinorAttack.weaponName, "Longsword",
        "Two-handed Focus metadata should preserve the qualifying weapon")
    assertEqual(focusResult.twoHandedFocusMinorAttack.cardName, "Seven of Pentacles",
        "Two-handed Focus metadata should preserve the Pentacles card")

    local focusPopup = getActionSequencerPopup(focusAction, focusResult, function(data)
        return data.title == "Two-handed Focus"
    end)
    assertTrue(focusPopup ~= nil, "Two-handed Focus minor Attack should queue an action-sequencer popup")
    assertEqual(focusPopup.weaponName, "Longsword",
        "Two-handed Focus popup should name the qualifying weapon")
    assertEqual(focusPopup.cardName, "Seven of Pentacles",
        "Two-handed Focus popup should name the off-suit minor card")

    local previousLove = love
    love = {
        graphics = {
            getDimensions = function()
                return 1280, 720
            end,
        },
    }

    local uiBus = events.createEventBus()
    local emitted = nil
    uiBus:on("action_selected", function(data)
        emitted = data
    end)

    local board = command_board.createCommandBoard({ eventBus = uiBus })
    board:show(pentaclesCard, focus, false)
    local focusMeleeButton = nil
    for _, button in ipairs(board.buttons) do
        if button.action and button.action.id == "melee" then
            focusMeleeButton = button
            break
        end
    end
    assertTrue(focusMeleeButton ~= nil, "Command Board should show melee Attack during minor windows")
    assertTrue(focusMeleeButton.enabled,
        "Command Board should enable Pentacles-card minor melee Attacks for Two-handed Focus")
    board:mousepressed(focusMeleeButton.x + 1, focusMeleeButton.y + 1, 1)
    assertTrue(emitted ~= nil, "Two-handed Focus Command Board melee selection should emit action_selected")
    assertEqual(emitted.action.id, "melee",
        "Two-handed Focus Command Board emission should preserve melee Attack")

    local plainBoard = command_board.createCommandBoard({ eventBus = events.createEventBus() })
    plainBoard:show(pentaclesCard, plain, false)
    local plainMeleeButton = nil
    for _, button in ipairs(plainBoard.buttons) do
        if button.action and button.action.id == "melee" then
            plainMeleeButton = button
            break
        end
    end
    assertTrue(plainMeleeButton ~= nil, "Command Board should still render the melee Attack button")
    assertTrue(not plainMeleeButton.enabled,
        "Command Board should keep Pentacles-card minor melee disabled without Two-handed Focus")

    love = previousLove
end

local function checkReaverChargeAttackTalent()
    local bus = events.createEventBus()
    local zones = zone_system.createZoneRegistry({ eventBus = bus })
    zones:setRoomZones({
        zone_system.createZone({ id = "near", adjacent_to = { "far" } }),
        zone_system.createZone({ id = "far", adjacent_to = { "near" } }),
        zone_system.createZone({ id = "balcony", adjacent_to = {} }),
    })

    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
        zoneSystem = zones,
    })
    local activeChallenge = {
        isActive = function()
            return true
        end,
    }

    local function makeAttacker(id, talents)
        local actor = base_entity.createEntity({
            id = id,
            name = id,
            isPC = true,
            swords = 2,
            talents = talents,
            zone = "near",
        })
        actor.inventory = inventory.createInventory()
        actor.inventory:addItem(inventory.createItemFromTemplate("longsword"), inventory.LOCATIONS.HANDS)
        zones:placeEntity(actor.id, actor.zone)
        return actor
    end

    local function makeTarget(id, zone)
        local target = base_entity.createEntity({
            id = id,
            name = id,
            isPC = false,
            health = 3,
            defense = 0,
            zone = zone,
        })
        zones:placeEntity(target.id, target.zone)
        return target
    end

    local target = makeTarget("npc_reaver_target", "far")
    local ordinary = resolver:resolve({
        actor = makeAttacker("pc_no_reaver_move", {}),
        target = target,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 6,
        challengeController = activeChallenge,
    })
    assertTrue(not ordinary.success, "ordinary melee Attacks should not reach a different zone")
    assertTrue(hasValue(ordinary.effects, "not_engaged"), "ordinary out-of-zone melee should report not engaged")

    local reaver = makeAttacker("pc_reaver_charge", {
        reaver = { mastered = true },
    })
    local chargeTarget = makeTarget("npc_reaver_charge_target", "far")
    local charged = resolver:resolve({
        actor = reaver,
        target = chargeTarget,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 6,
        useReaver = true,
        challengeController = activeChallenge,
    })
    assertTrue(charged.success, "Reaver should move one zone and then resolve the melee Attack")
    assertEqual(reaver.zone, "far", "Reaver charge should update the actor zone")
    assertTrue(hasValue(charged.effects, "reaver_charge"), "Reaver charge should be reported")
    assertEqual(charged.reaverCharge.oldZone, "near", "Reaver metadata should record the old zone")
    assertEqual(charged.reaverCharge.newZone, "far", "Reaver metadata should record the new zone")
    local actionSequencer = require('ui.action_sequencer')
    local sequencer = actionSequencer.createActionSequencer({ eventBus = events.createEventBus() })
    sequencer:queueActionSequence({
        action = {
            actor = reaver,
            target = chargeTarget,
            card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        },
        result = charged,
    })
    local hasReaverPopup = false
    for _, step in ipairs(sequencer.currentSequence or {}) do
        if step.type == actionSequencer.STEP_TYPES.TEXT_POPUP and
           step.data and step.data.title == "Reaver" then
            hasReaverPopup = true
            assertEqual(step.data.oldZone, "near",
                "Reaver popup should include the starting zone")
            assertEqual(step.data.newZone, "far",
                "Reaver popup should include the charged-to zone")
            break
        end
    end
    assertTrue(hasReaverPopup, "Reaver charge should queue a visible movement popup")

    local missingTalent = makeAttacker("pc_reaver_missing_talent", {})
    local blocked = resolver:resolve({
        actor = missingTalent,
        target = makeTarget("npc_reaver_missing_talent_target", "far"),
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 6,
        useReaver = true,
        challengeController = activeChallenge,
    })
    assertTrue(not blocked.success, "Reaver charge should require the talent")
    assertEqual(blocked.description, "Requires Reaver", "missing Reaver should explain the requirement")
    assertTrue(hasValue(blocked.effects, "reaver_blocked"), "blocked Reaver should report a block")

    local rooted = makeAttacker("pc_reaver_rooted", {
        reaver = { mastered = true },
    })
    rooted.conditions.rooted = true
    local rootedCharge = resolver:resolve({
        actor = rooted,
        target = makeTarget("npc_reaver_rooted_target", "far"),
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 6,
        useReaver = true,
        challengeController = activeChallenge,
    })
    assertTrue(not rootedCharge.success, "Rooted Reavers should not charge")
    assertEqual(rooted.zone, "near", "Rooted Reaver charge should not move the actor")

    local previousLove = love
    love = {
        graphics = {
            getDimensions = function()
                return 1280, 720
            end,
        },
    }

    local uiBus = events.createEventBus()
    local emitted = nil
    uiBus:on("action_selected", function(data)
        emitted = data
    end)

    local uiReaver = makeAttacker("pc_reaver_ui", {
        reaver = { mastered = true },
    })
    local uiTarget = makeTarget("npc_reaver_ui_target", "far")
    local board = command_board.createCommandBoard({ eventBus = uiBus })
    board:show({ name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS }, uiReaver, true)
    local meleeButton = nil
    for _, button in ipairs(board.buttons) do
        if button.action and button.action.id == "melee" then
            meleeButton = button
            break
        end
    end
    assertTrue(meleeButton ~= nil, "Reaver Command Board setup should expose melee Attack")
    board:mousepressed(meleeButton.x + 1, meleeButton.y + 1, 1)
    assertEqual(board.mode, "reaver_option", "Reaver melee selection should prompt for normal Attack or charge")
    assertTrue(emitted == nil, "Reaver attack approach picker should wait for an approach selection")

    local reaverButton = nil
    for _, button in ipairs(board.buttons) do
        if button.action and button.action.useReaver then
            reaverButton = button
            break
        end
    end
    assertTrue(reaverButton ~= nil, "Reaver attack approach picker should include Reaver Charge")
    board:mousepressed(reaverButton.x + 1, reaverButton.y + 1, 1)
    assertTrue(emitted ~= nil, "Reaver attack approach selection should emit action_selected")
    assertEqual(emitted.action.id, "melee", "Reaver approach should preserve melee Attack action type")
    assertTrue(emitted.action.useReaver, "Reaver approach should mark the action as a Reaver charge")

    local uiCard = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS }
    local submitted = nil
    local inputController = challenge_input_controller.createChallengeInputController({
        eventBus = events.createEventBus(),
        inputState = {
            selectedCard = uiCard,
            selectedCardIndex = 1,
            selectedEntity = uiReaver,
        },
        gameState = {
            challengeController = {
                zoneSystem = zones,
                npcs = { uiTarget },
                pcs = { uiReaver },
                allCombatants = { uiReaver, uiTarget },
                getState = function()
                    return "awaiting_action"
                end,
                submitAction = function(_, action)
                    submitted = action
                    return true
                end,
            },
            zoneRegistry = zones,
            playerHand = {
                getHand = function()
                    return { uiCard }
                end,
                discardCard = function()
                    return uiCard, 1, nil
                end,
            },
        },
    })
    inputController:handleActionSelected(emitted)
    assertTrue(inputController:getState().awaitingTarget,
        "Reaver melee action should allow target selection before submitting")
    inputController:handleTargetSelection("1")
    assertTrue(submitted ~= nil, "Reaver target selection should submit the melee action")
    assertEqual(submitted.target, uiTarget, "Reaver target picker should allow adjacent-zone melee targets")
    assertTrue(submitted.useReaver, "Reaver target selection should preserve the charge election")

    love = previousLove
end

local function checkNPCDrawFormula()
    local gmReference = npc_ai.getGMChallengeReference()
    assertEqual(gmReference.source, "Core Rules Chapter 7: GMing the Challenge",
        "GM Challenge metadata should cite the Chapter 7 GMing section")
    assertEqual(gmReference.roundDrawFormula.base, 3,
        "GM Challenge metadata should preserve the base three-card draw")
    assertTrue(gmReference.roundDrawFormula.recalculatedEachRound,
        "GM Challenge metadata should preserve round-by-round draw recalculation")
    assertEqual(gmReference.roundDrawFormula.modifiers[1].id, "enemy_type",
        "GM Challenge metadata should preserve enemy-type draw modifiers")
    assertEqual(gmReference.roundDrawFormula.examples[1].total, 6,
        "GM Challenge metadata should preserve the twelve-imps draw example")
    assertTrue(gmReference.mulligan.optional,
        "GM Challenge metadata should preserve optional mulligans")
    assertEqual(gmReference.initiative.oneCardForEach, "significant enemy or enemy group",
        "GM Challenge metadata should preserve significant enemy/group Initiative")
    assertTrue(gmReference.initiative.sameEnemyTypeSharesCard,
        "GM Challenge metadata should preserve shared same-type Initiative")
    assertEqual(gmReference.doomCards.lesser.values.max, 14,
        "GM Challenge metadata should preserve lesser-doom values")
    assertEqual(gmReference.doomCards.greater.values.min, 15,
        "GM Challenge metadata should preserve greater-doom values")
    assertTrue(hasValue(gmReference.doomCards.greater.use,
        "targeted greater doom riders paired with a lesser-doom Attack"),
        "GM Challenge metadata should preserve targeted greater-doom riders")
    assertTrue(gmReference.minorActions.majorArcanaHaveNoSuits,
        "GM Challenge metadata should preserve suitless major-arcana minor actions")
    assertEqual(gmReference.mobRule.thresholds[1].attackers, 2,
        "GM Challenge metadata should preserve the first mob-rule threshold")
    assertTrue(gmReference.mobRule.thresholds[2].piercing,
        "GM Challenge metadata should preserve the four-attacker Piercing threshold")
    assertTrue(gmReference.mobRule.thresholds[3].critical,
        "GM Challenge metadata should preserve the eight-attacker Critical threshold")

    local drawFormula = npc_ai.getGMRoundDrawFormula()
    drawFormula.modifiers[1].id = "mutated"
    assertEqual(npc_ai.getGMRoundDrawFormula().modifiers[1].id, "enemy_type",
        "GM round draw metadata getter should return copy-safe data")
    local mobRule = npc_ai.getGMMobRule()
    mobRule.thresholds[1].attackers = 99
    assertEqual(npc_ai.getGMMobRule().thresholds[1].attackers, 2,
        "GM mob-rule metadata getter should return copy-safe data")

    local bus = events.createEventBus()
    local ai = npc_ai.createNPCAI({
        eventBus = bus,
        challengeController = {
            npcs = {},
            pcs = {},
        },
    })

    local function makeNPC(id, blueprintId, extra)
        local npc = {
            id = id,
            blueprintId = blueprintId or "imp",
            isPC = false,
            rank = "soldier",
            conditions = {},
        }
        for key, value in pairs(extra or {}) do
            npc[key] = value
        end
        return npc
    end

    local function makePC(id)
        return {
            id = id,
            isPC = true,
            conditions = {},
        }
    end

    for i = 1, 12 do
        ai.challengeController.npcs[i] = makeNPC("n" .. i, "imp")
    end
    for i = 1, 4 do
        ai.challengeController.pcs[i] = makePC("p" .. i)
    end

    assertEqual(ai:calculateRoundDrawCount(), 6, "12 imps vs 4 adventurers should draw 6 GM cards")

    ai.challengeController.npcs = {}
    for i = 1, 7 do
        ai.challengeController.npcs[i] = makeNPC("n" .. i, "imp")
    end
    assertEqual(ai:calculateRoundDrawCount(), 5, "7 imps vs 4 adventurers should draw 5 GM cards")

    ai.challengeController.npcs = {
        makeNPC("n1", "imp"),
        makeNPC("n2", "ogre", { size = "large" }),
        makeNPC("n3", "boss", { rank = "elite" }),
        makeNPC("n4", "lord", { rank = "lord" }),
    }
    assertEqual(ai:calculateRoundDrawCount(), 13, "mixed enemies should apply type, size, elite, and lord bonuses")

    ai.challengeController.npcs[1].stinkingCloudDrawPenalty = 2
    ai.challengeController.npcs[2].stinkingCloudDrawPenalty = 1
    assertEqual(ai:calculateRoundDrawCount(), 10, "Stinking Cloud penalties should reduce the GM round draw")

    local draws = {
        major(15),
        major(16),
        major(4),
        major(1),
        major(2),
        major(3),
    }
    local drawIndex = 0
    local discarded = {}
    local mulliganAI = npc_ai.createNPCAI({
        eventBus = events.createEventBus(),
        challengeController = {
            npcs = {},
            pcs = {},
        },
        gmDeck = {
            draw = function()
                drawIndex = drawIndex + 1
                return draws[drawIndex]
            end,
            discard = function(_, card)
                discarded[#discarded + 1] = card
            end,
        },
    })
    mulliganAI:refreshRoundHand(1)
    assertEqual(drawIndex, 6, "GM hand that is mostly greater dooms should mulligan once")
    assertEqual(#discarded, 3, "mostly-greater-doom mulligan should discard the first hand")
    assertEqual(mulliganAI.hand[1], draws[4], "mulligan should keep the replacement hand")
end

local function checkStartRoundSpellEffectsHook()
    local pc = {
        id = "pc_round_effect",
        name = "Round Effect PC",
        isPC = true,
        conditions = {},
    }
    local npc = {
        id = "npc_round_effect",
        name = "Round Effect NPC",
        isPC = false,
        conditions = {},
    }
