local function checkMaledictionChickenDoomChallengeStart()
    local bus = events.createEventBus()
    local chickenEvent = nil
    local clearedEvent = nil
    bus:on(events.EVENTS.MALEDICTION_CHICKEN_DOOM, function(data)
        chickenEvent = data
    end)
    bus:on(events.EVENTS.MALEDICTION_CHICKEN_CLEARED, function(data)
        clearedEvent = data
    end)

    local cursed = base_entity.createEntity({
        id = "pc_chicken_doom",
        name = "Chicken Doom Adventurer",
        isPC = true,
        wands = 0,
        health = 2,
        defense = 0,
    })
    cursed.malediction = {
        active = true,
        curse = {
            flags = { stressChickenTest = true },
        },
    }
    local npc = base_entity.createEntity({
        id = "npc_chicken_stressor",
        name = "Chicken Stressor",
        isPC = false,
        health = 2,
        defense = 0,
    })

    local controller = challenge_controller.createChallengeController({
        eventBus = bus,
        guild = { cursed },
    })
    local ok = controller:startChallenge({
        pcs = { cursed },
        npcs = { npc },
        chickenDoomTests = {
            [cursed.id] = { success = false, total = 5, isGreat = false },
        },
    })
    assertTrue(ok, "challenge should start with a chicken-doom cursed adventurer")
    assertTrue(cursed.conditions.chicken and cursed.conditions.chickenDoom,
        "failed Chicken Doom stress test should transform the target into a chicken")
    assertTrue(chickenEvent and chickenEvent.entity == cursed and chickenEvent.result == "chicken",
        "Chicken Doom stress test should emit a failed transformation event")
    assertEqual(cursed.chickenDoom.expiresAfterRound, 1, "Chicken Doom should last for one round")

    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local blocked = resolver:resolve({
        actor = cursed,
        card = { name = "Three of Pentacles", value = 3, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.MOVE,
    })
    assertTrue(not blocked.success, "Chicken Doom should block normal Challenge actions")
    assertEqual(blocked.description, "Cannot act while transformed into a chicken",
        "Chicken Doom action block should explain the transformation")

    local cleared = controller:clearExpiredChickenDoom(1)
    assertEqual(#cleared, 1, "Chicken Doom should clear after the failed round expires")
    assertTrue(not cursed.conditions.chicken and not cursed.conditions.chickenDoom and cursed.chickenDoom == nil,
        "clearing Chicken Doom should restore the adventurer's normal form flags")
    assertTrue(clearedEvent and clearedEvent.entity == cursed,
        "Chicken Doom clearing should emit an event")

    local steady = base_entity.createEntity({
        id = "pc_chicken_steady",
        name = "Steady Chicken Doom Adventurer",
        isPC = true,
        wands = 3,
        health = 2,
        defense = 0,
    })
    steady.stressChickenTest = true
    local steadyNPC = base_entity.createEntity({
        id = "npc_chicken_steady_stressor",
        name = "Steady Stressor",
        isPC = false,
        health = 2,
        defense = 0,
    })
    local steadyController = challenge_controller.createChallengeController({
        eventBus = events.createEventBus(),
        guild = { steady },
    })
    assertTrue(steadyController:startChallenge({
        pcs = { steady },
        npcs = { steadyNPC },
        chickenDoomTests = {
            [steady.id] = { success = true, total = 12, isGreat = false },
        },
    }), "challenge should start when Chicken Doom stress test succeeds")
    assertTrue(not (steady.conditions and steady.conditions.chicken),
        "successful Chicken Doom stress test should not transform the target")
end

local function checkNPCSharedInitiativeGroups()
    local submissions = {}
    local discarded = {}
    local ai = npc_ai.createNPCAI({
        eventBus = events.createEventBus(),
        gmDeck = {
            discard = function(_, card)
                discarded[#discarded + 1] = card
            end,
        },
        challengeController = {
            submitInitiative = function(_, npc, card)
                submissions[#submissions + 1] = { npc = npc, card = card }
            end,
        },
    })

    ai.hand = { major(7) }

    local first = { id = "n1", name = "Imp A", blueprintId = "imp", conditions = {} }
    local second = { id = "n2", name = "Imp B", blueprintId = "imp", conditions = {} }

    ai:handleNPCInitiative({ npc = first, round = 1 })
    ai:handleNPCInitiative({ npc = second, round = 1 })

    assertEqual(#submissions, 2, "both grouped NPCs should submit initiative")
    assertTrue(submissions[1].card == submissions[2].card, "same enemy type should share one initiative card")
    assertEqual(#ai.hand, 0, "shared initiative should spend only one GM card")
    assertEqual(#discarded, 0, "GM Initiative cards should remain in play until round end")

    ai:discardRoundInitiativeCards()
    assertEqual(#discarded, 1, "shared GM Initiative card should discard once at round end")
    assertTrue(discarded[1] == submissions[1].card,
        "round-end GM Initiative discard should use the submitted Initiative card")
end

local function checkNPCRoundEndDiscardBeforeReshuffle()
    local bus = events.createEventBus()
    local discarded = {}
    local discardCountWhenClockWouldReshuffle = nil
    local ai = npc_ai.createNPCAI({
        eventBus = bus,
        gmDeck = {
            discard = function(_, card)
                discarded[#discarded + 1] = card
            end,
        },
    })
    ai:init()
    ai.hand = { major(8), major(19) }
    local sharedInitiative = major(3)
    ai.roundInitiativeCards = { goblins = sharedInitiative, goblin_archers = sharedInitiative }

    bus:on(events.EVENTS.CHALLENGE_ROUND_END, function()
        discardCountWhenClockWouldReshuffle = #discarded
    end)

    bus:emit(events.EVENTS.CHALLENGE_ROUND_END, { round = 1 })

    assertEqual(#discarded, 3, "GM should discard unused and Initiative Challenge cards at round end")
    assertTrue(discarded[1] == sharedInitiative,
        "GM current Initiative card should discard before unused hand cards")
    assertEqual(discardCountWhenClockWouldReshuffle, 3,
        "unused and Initiative GM cards should be discarded before the controller's Fool reshuffle step")
    assertEqual(#ai.hand, 0, "GM hand should be empty after round-end discard")
    assertTrue(next(ai.roundInitiativeCards) == nil, "shared initiative cache should clear at round end")
end

local function checkFoolReshuffleConditionExpiry()
    local bus = events.createEventBus()
    local expired = {}
    bus:on(events.EVENTS.CONDITION_EXPIRED, function(payload)
        expired[#expired + 1] = payload
    end)

    local pc = base_entity.createEntity({
        id = "pc_fool_condition",
        name = "Fool Condition PC",
        isPC = true,
    })
    pc.conditions.silenced = true
    pc.silenced = true
    pc.conditions.rhymebound = true
    local healingBlock = {
        ["until"] = "fool_reshuffle",
        woundTypes = { "talent", "injured" },
        active = true,
    }
    pc.conditionDurations = {
        silenced = { ["until"] = "fool_reshuffle" },
        rhymebound = { ["until"] = "next_camp_complete" },
    }
    pc.healingBlocks = {
        healingBlock,
        { ["until"] = "city_prayer", woundTypes = { "injured" }, active = true },
    }
    pc.healingBlock = healingBlock
    local npc = base_entity.createEntity({
        id = "npc_fool_condition",
        name = "Fool Condition NPC",
        isPC = false,
        health = 2,
        defense = 0,
    })

    local controller = challenge_controller.createChallengeController({
        eventBus = bus,
        guild = { pc },
        gameClock = {
            endRound = function()
                return true
            end,
        },
    })
    controller.pcs = { pc }
    controller.npcs = { npc }
    controller.allCombatants = { pc, npc }
    controller.currentRound = 1
    controller.currentCount = 14
    controller.state = challenge_controller.STATES.COUNT_UP

    controller:advanceCount()

    assertTrue(not pc.conditions.silenced and not pc.silenced,
        "Fool reshuffle should clear conditions marked until fool_reshuffle")
    assertTrue(pc.conditions.rhymebound,
        "Fool reshuffle should not clear next-camp-complete conditions")
    assertTrue(pc.conditionDurations and pc.conditionDurations.rhymebound and not pc.conditionDurations.silenced,
        "Fool reshuffle should remove only fool_reshuffle duration metadata")
    assertTrue(pc.healingBlock == nil and pc.healingBlocks and #pc.healingBlocks == 1,
        "Fool reshuffle should clear matching healing blocks and preserve other healing blocks")
    assertEqual(#expired, 2, "Fool reshuffle should emit condition-expired events")
    assertEqual(expired[1].condition, "silenced", "Fool expiry event should name the condition")
    assertEqual(expired[1].timing, "fool_reshuffle", "Fool expiry event should carry the timing")
    assertEqual(expired[1].round, 1, "Fool expiry event should use the completed round")
    assertEqual(expired[2].condition, "healing_block", "Fool expiry event should report healing block expiry")

    local game_clock = require('logic.game_clock')
    local playerResets = 0
    local gmResets = 0
    local playerDeck = {
        reset = function()
            playerResets = playerResets + 1
        end,
    }
    local gmDeck = {
        reset = function()
            gmResets = gmResets + 1
        end,
    }
    local clock = game_clock.createGameClock(playerDeck, gmDeck)
    local foolCard = { name = "The Fool", value = 0, suit = constants.SUITS.MAJOR }

    clock:setPhase(game_clock.PHASES.CRAWL)
    clock:onCardDrawn(foolCard)
    assertTrue(not clock:isReshufflePending(),
        "Fool draws outside a Challenge round should not schedule a Challenge reshuffle")
    assertTrue(not clock:endRound(),
        "out-of-Challenge Fool draws should not reshuffle decks at Challenge round end")
    assertEqual(playerResets, 0, "out-of-Challenge Fool draws should not reset the player deck")
    assertEqual(gmResets, 0, "out-of-Challenge Fool draws should not reset the GM deck")

    clock:setPhase(game_clock.PHASES.CHALLENGE)
    clock:onCardDrawn(foolCard)
    assertTrue(clock:isReshufflePending(),
        "Fool draws during a Challenge round should schedule the end-round reshuffle")
    assertTrue(clock:endRound(), "Challenge Fool draws should reshuffle both decks at round end")
    assertEqual(playerResets, 1, "Challenge Fool reshuffle should reset the player deck")
    assertEqual(gmResets, 1, "Challenge Fool reshuffle should reset the GM deck")

    local pc = base_entity.createEntity({
        id = "pc_clock_phase",
        name = "Clock Phase PC",
        isPC = true,
    })
    local npc = base_entity.createEntity({
        id = "npc_clock_phase",
        name = "Clock Phase NPC",
        isPC = false,
        health = 1,
        defense = 0,
    })
    local controllerClock = game_clock.createGameClock(playerDeck, gmDeck)
    controllerClock:setPhase(game_clock.PHASES.CRAWL)
    local controller = challenge_controller.createChallengeController({
        eventBus = events.createEventBus(),
        guild = { pc },
        gameClock = controllerClock,
    })
    local ok, err = controller:startChallenge({
        pcs = { pc },
        npcs = { npc },
    })
    assertTrue(ok, "challenge setup should succeed for clock phase coverage")
    assertEqual(err, nil, "challenge setup should not report a clock phase error")
    assertEqual(controllerClock:getPhase(), game_clock.PHASES.CHALLENGE,
        "Challenge start should put the game clock into Challenge phase")
    controller:endChallenge(challenge_controller.OUTCOMES.VICTORY)
    assertEqual(controllerClock:getPhase(), game_clock.PHASES.CRAWL,
        "Challenge end should restore the prior game clock phase")
end

local function checkGreaterDoomAttackPairing()
    local ai = npc_ai.createNPCAI({
        eventBus = events.createEventBus(),
        challengeController = {
            allCombatants = {},
        },
    })

    local npc = entity_factory.createEntity("brain_spider")
    npc.id = "brain_spider_1"
    npc.zone = "near"
    npc.preferredActions = nil
    local pc = {
        id = "pc_1",
        name = "Target",
        zone = "near",
        isPC = true,
        conditions = {},
    }

    ai.hand = { major(17), major(12) }

    local action = ai:decide(npc, { pc })
    assertTrue(action ~= nil, "NPC should choose an attack when target is in zone")
    assertEqual(action.card.value, 12, "greater doom attack should use lesser doom as the Attack card")
    assertEqual(action.greaterDoomCard.value, 17, "greater doom card should be attached as rider")
    assertEqual(action.greaterDoom.id, "web", "attack rider should carry the selected doom")
    assertEqual(#ai.hand, 0, "paired doom attack should spend both cards")

    local sorceryResolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local sorcerer = entity_factory.createEntity("brain_spider_queen")
    sorcerer.id = "brain_spider_queen_ai"
    sorcerer.zone = "crypt"
    sorcerer.resolve = 0
    pc.zone = "crypt"
    ai.actionResolver = sorceryResolver
    ai.hand = { major(16), major(8) }
    local sorceryAction = ai:decide(sorcerer, { pc })
    assertTrue(sorceryAction ~= nil, "authored Brain Spider Sorcery should produce an AI action")
    assertEqual(sorceryAction.type, action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        "Brain Spider authored AI should choose Speak Incantation")
    assertEqual(sorceryAction.spellId, "illusion",
        "Brain Spider authored AI should preserve the Illusion spell id")
    assertEqual(sorceryAction.card.value, 8,
        "Brain Spider authored Sorcery should spend a lesser doom for Speak Incantation")
    assertEqual(sorceryAction.greaterDoom.id, "sorcery",
        "Brain Spider authored Sorcery should attach the Sorcery greater doom")
    assertEqual(sorceryAction.greaterDoomCard.value, 16,
        "Brain Spider authored Sorcery should discard a greater doom for Resolve")
    assertEqual(#ai.hand, 0, "Brain Spider authored Sorcery should spend both doom cards")
    local sorceryResult = sorceryResolver:resolve(sorceryAction)
    assertTrue(sorceryResult.success, "Brain Spider authored AI Sorcery should resolve through spellcasting")
    assertTrue(hasValue(sorceryResult.effects, "brain_spider_sorcery") and
        hasValue(sorceryResult.effects, "visual_illusion"),
        "Brain Spider authored AI Sorcery should apply Illusion with greater-doom payment")
    assertEqual(sorceryResult.resolveSpent, 0,
        "Brain Spider authored AI Sorcery should spend no ordinary Resolve")

    local function makeMob(id)
        return {
            id = id,
            name = id,
            zone = "near",
            isPC = false,
            swords = 0,
            conditions = {},
        }
    end

    ai.hand = { major(17), major(12) }
    local genericNPC = makeMob("npc_generic_doom_favor")
    local genericTarget = {
        id = "pc_greater_doom_favor_target",
        name = "Greater Doom Favor Target",
        zone = "near",
        isPC = true,
        defense = 0,
        conditions = {},
    }
    local favoredAction = ai:decide(genericNPC, { genericTarget })
    assertTrue(favoredAction ~= nil, "generic NPC should choose an attack when a target is in zone")
    assertEqual(favoredAction.card.value, 12, "greater doom favor attack should still use a lesser doom action card")
    assertEqual(favoredAction.greaterDoomFavorCard.value, 17,
        "generic NPC should discard a greater doom for favor on a standard attack")
    assertTrue(favoredAction.greaterDoomFavor, "generic NPC action should mark greater doom favor")
    assertEqual(#ai.hand, 0, "greater doom favor attack should spend both cards")

    ai.challengeController.zones = {
        { id = "near", adjacent_to = { "far" } },
        { id = "far", adjacent_to = { "near" } },
    }
    local farTarget = {
        id = "pc_far_target",
        name = "Far Target",
        zone = "far",
        isPC = true,
        conditions = {},
    }
    local mover = makeMob("npc_lesser_doom_mover")
    ai.hand = { major(18) }
    local greaterDoomMove = ai:decide(mover, { farTarget })
    assertTrue(greaterDoomMove ~= nil, "NPC Move should allow greater dooms as miscellaneous actions")
    assertEqual(greaterDoomMove.type, action_resolver.ACTION_TYPES.MOVE,
        "greater-doom distant-target decision should be a Move action")
    assertEqual(greaterDoomMove.card.value, 18, "NPC Move may spend a greater doom when no lesser doom is available")
    assertEqual(#ai.hand, 0, "greater-doom Move should spend the movement card")

    ai.hand = { major(18), major(13) }
    local legalMove = ai:decide(mover, { farTarget })
    assertTrue(legalMove ~= nil, "NPC Move should use a lesser doom when one is available")
    assertEqual(legalMove.type, action_resolver.ACTION_TYPES.MOVE,
        "legal distant-target decision should be a Move action")
    assertEqual(legalMove.card.value, 13, "NPC Move should spend the lesser doom card")
    assertEqual(#ai.hand, 1, "NPC Move should leave unrelated greater dooms in hand")
    assertEqual(ai.hand[1].value, 18, "NPC Move should not spend the greater doom")

    local legalityResolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local directNPC = makeMob("npc_direct_greater_doom_attack")
    local directTarget = {
        id = "pc_direct_greater_doom_target",
        name = "Direct Greater Doom Target",
        zone = "near",
        isPC = true,
        defense = 0,
        conditions = {},
    }
    local illegalAttack = legalityResolver:resolve({
        actor = directNPC,
        target = directTarget,
        card = major(18),
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 10,
    })
    assertTrue(not illegalAttack.success,
        "direct resolver should reject greater dooms for ordinary GM Challenge Actions")
    assertTrue(hasValue(illegalAttack.effects, "greater_doom_standard_action_blocked"),
        "illegal greater-doom Challenge Action should report the doom legality gate")

    local directMover = makeMob("npc_direct_greater_doom_move")
    directMover.zone = "near"
    local legalMiscMove = legalityResolver:resolve({
        actor = directMover,
        card = major(18),
        type = action_resolver.ACTION_TYPES.MOVE,
        destinationZone = "far",
    })
    assertTrue(legalMiscMove.success, "direct resolver should allow greater dooms for miscellaneous Move")
    assertEqual(directMover.zone, "far", "greater-doom miscellaneous Move should still move the NPC")

    local mobTarget = {
        id = "pc_mob_rule_target",
        name = "Mob Rule Target",
        zone = "near",
        isPC = true,
        defense = 5,
        conditions = {},
    }
    local mobs = {}
    for i = 1, 8 do
        mobs[i] = makeMob("npc_mob_rule_" .. i)
    end
    local mobAI = npc_ai.createNPCAI({
        eventBus = events.createEventBus(),
        challengeController = {
            npcs = { mobs[1] },
            allCombatants = { mobs[1], mobTarget },
        },
    })
    assertTrue(mobAI:checkMobRule(mobs[1], mobTarget) == nil,
        "one attacker should not trigger mob rule")

    mobAI.challengeController.npcs = { mobs[1], mobs[2] }
    local twoAttackers = mobAI:checkMobRule(mobs[1], mobTarget)
    assertTrue(twoAttackers and twoAttackers.favor, "two attackers should gain mob-rule favor")
    assertTrue(not twoAttackers.piercing and not twoAttackers.critical,
        "two attackers should not gain Piercing or Critical")
    assertTrue(twoAttackers.attackBonus == nil, "mob rule should not add a numeric attack bonus")

    mobAI.challengeController.npcs = { mobs[1], mobs[2], mobs[3] }
    local threeAttackers = mobAI:checkMobRule(mobs[1], mobTarget)
    assertTrue(threeAttackers and threeAttackers.favor and not threeAttackers.piercing,
        "three attackers should still only have mob-rule favor")

    mobAI.challengeController.npcs = { mobs[1], mobs[2], mobs[3], mobs[4] }
    local fourAttackers = mobAI:checkMobRule(mobs[1], mobTarget)
    assertTrue(fourAttackers and fourAttackers.piercing and not fourAttackers.critical,
        "four attackers should add Piercing damage")
    local mobAction = mobAI:createAttackAction(mobs[1], mobTarget, major(3))
    assertTrue(mobAction.favor, "mob-rule attacks should enter the resolver with favor")
    assertTrue(mobAction.mobRuleBonus and mobAction.mobRuleBonus.piercing,
        "created mob-rule actions should preserve Piercing metadata")

    mobAI.challengeController.npcs = {
        mobs[1], mobs[2], mobs[3], mobs[4], mobs[5], mobs[6], mobs[7], mobs[8],
    }
    local eightAttackers = mobAI:checkMobRule(mobs[1], mobTarget)
    assertTrue(eightAttackers and eightAttackers.critical,
        "eight attackers should escalate mob-rule damage to Critical")

    local damageType = nil
    mobTarget.takeWound = function(_, incomingType)
        damageType = incomingType
        return "injured"
    end
    local mobResolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local criticalAction = mobAI:createAttackAction(mobs[1], mobTarget, major(3))
    criticalAction.targetInitiative = 5
    local criticalResult = mobResolver:resolve(criticalAction)
    assertTrue(criticalResult.success, "mob-rule favor should make the low card hit")
    assertTrue(hasValue(criticalResult.effects, "action_favor"),
        "mob-rule favor should flow through the central favor pipeline")
    assertTrue(hasValue(criticalResult.effects, "mob_critical"),
        "eight-attacker mob rule should report Critical damage")
    assertEqual(damageType, "critical", "eight-attacker mob rule should apply Critical Wounds")
end

local function checkWebGreaterDoomResolution()
    local bus = events.createEventBus()
    local zones = zone_system.createZoneRegistry({
        eventBus = bus,
    })
    zones:setRoomZones({
        zone_system.createZone({ id = "near", name = "Near" }),
    })
    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
        zoneSystem = zones,
    })

    local npc = entity_factory.createEntity("brain_spider")
    npc.id = "brain_spider_1"
    npc.zone = "near"
    local webDoom = nil
    for _, doom in ipairs(npc.greaterDooms or {}) do
        if doom.id == "web" then
            webDoom = doom
        end
    end
    assertTrue(webDoom ~= nil, "Brain Spider blueprint should provide the Web greater doom")
    local pc = {
        id = "pc_1",
        name = "Target",
        isPC = true,
        zone = "near",
        pentacles = 1,
        conditions = {},
        takeWound = function()
            error("web greater doom should suppress Attack damage")
        end,
    }

    local action = {
        actor = npc,
        target = pc,
        card = major(12),
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 10,
        allEntities = { npc, pc },
        greaterDoom = webDoom,
        greaterDoomCard = major(17),
    }

    resolver:formEngagement(npc, pc)
    assertTrue(npc.is_engaged and pc.is_engaged, "test setup should start with engagement")

    local result = resolver:resolve(action)
    assertTrue(result.success, "web attack should hit")
    assertTrue(pc.conditions.webbed, "web should mark target webbed")
    assertTrue(pc.conditions.rooted, "web should root target")
    assertTrue(not npc.is_engaged and not pc.is_engaged,
        "Rooted effects should immediately disengage everyone engaged with the target")
    assertTrue(not resolver:hasAnyEngagement(npc) and not resolver:hasAnyEngagement(pc),
        "Rooted disengagement should clear the zone engagement registry")
    assertEqual(pc.webbedLimbs, 4, "web should track limbs to recover from the Brain Spider blueprint")
    assertEqual(result.damageDealt, 0, "web should suppress normal Attack damage")

    local recover = resolver:resolve({
        actor = pc,
        card = { name = "Any", value = 1, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.RECOVER,
    })
    assertTrue(recover.success, "first Recover should free one limb")
    assertEqual(pc.webbedLimbs, 3, "first Recover should decrement webbed limbs")
    assertTrue(pc.conditions.rooted, "target remains rooted until all limbs are free")

    for expectedRemaining = 2, 1, -1 do
        recover = resolver:resolve({
            actor = pc,
            card = { name = "Any", value = 1, suit = constants.SUITS.WANDS },
            type = action_resolver.ACTION_TYPES.RECOVER,
        })
        assertTrue(recover.success, "Recover should continue freeing webbed limbs")
        assertEqual(pc.webbedLimbs, expectedRemaining, "Recover should decrement webbed limbs one at a time")
        assertTrue(pc.conditions.rooted, "target remains rooted while any webbed limb remains")
    end

    recover = resolver:resolve({
        actor = pc,
        card = { name = "Any", value = 1, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.RECOVER,
    })
    assertTrue(recover.success, "final Recover should clear web")
    assertEqual(pc.webbedLimbs, 0, "final Recover should clear webbed limb count")
    assertTrue(not pc.conditions.webbed, "final Recover should clear webbed")
    assertTrue(not pc.conditions.rooted, "final Recover should clear rooted")
end

function checkBrainSpiderRuntime()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local spider = entity_factory.createEntity("brain_spider")
    spider.id = "npc_brain_spider_runtime"
    local hammer = inventory.createItem({
        name = "Hammer",
        weaponType = "hammer",
    })
    local hammerEffects = {}
    local hammerBlocked = resolver:applyDamage(spider, 1, hammerEffects, hammer, nil, nil, {
        source = "attack",
    })
    assertTrue(hammerBlocked and hammerBlocked.immune,
        "Brain Spider Squishy should ignore bludgeoning and smashing weapons")
    assertEqual(spider.npcDefense, 3,
        "Brain Spider Squishy should prevent hammer Wounds")
    assertTrue(hasValue(hammerEffects, "brain_spider_squishy_immune"),
        "Brain Spider Squishy immunity should be explicit")

    local sword = inventory.createItem({
        name = "Sword",
        weaponType = "sword",
    })
    resolver:applyDamage(spider, 1, {}, sword, nil, nil, {
        source = "attack",
    })
    assertEqual(spider.npcDefense, 2,
        "Brain Spider Squishy should not block ordinary blade damage")

    local bus = events.createEventBus()
    local zoneRegistry = zone_system.createZoneRegistry({ eventBus = bus })
    local zones = buildLinearZones()
    zoneRegistry:setRoomZones(zones)
    local moveResolver = action_resolver.createActionResolver({
        eventBus = bus,
        zoneSystem = zoneRegistry,
    })
    local leaper = entity_factory.createEntity("brain_spider")
    leaper.id = "npc_brain_spider_leaper"
    leaper.zone = "A"
    zoneRegistry:placeEntity(leaper.id, leaper.zone)
    local leap = moveResolver:resolve({
        actor = leaper,
        type = action_resolver.ACTION_TYPES.DASH,
        card = { name = "Five of Pentacles", value = 5, suit = constants.SUITS.PENTACLES },
        destinationZone = "C",
        challengeController = { zones = zones },
        lesserDoom = leaper.lesserDooms[1],
        interveningObstacles = { "pit", "blocking_adventurer" },
    })
    assertTrue(leap.success and leaper.zone == "C",
        "Brain Spider Great Leap should Dash two zones")
    assertTrue(hasValue(leap.effects, "brain_spider_great_leap") and
        hasValue(leap.effects, "clears_intervening_obstacles"),
        "Brain Spider Great Leap should record obstacle-clearing movement")

    local wallCrawler = entity_factory.createEntity("brain_spider")
    wallCrawler.id = "npc_brain_spider_wall"
    wallCrawler.zone = "A"
    zoneRegistry:placeEntity(wallCrawler.id, wallCrawler.zone)
    local wall = moveResolver:resolve({
        actor = wallCrawler,
        type = action_resolver.ACTION_TYPES.MOVE,
        card = { name = "Six of Pentacles", value = 6, suit = constants.SUITS.PENTACLES },
        destinationZone = "B",
        challengeController = { zones = zones },
        lesserDoom = wallCrawler.lesserDooms[2],
        allEntities = { wallCrawler },
    })
    assertTrue(wall.success and wallCrawler.conditions.wall_crawling,
        "Brain Spider Wall Crawling should mark effortless wall movement")
    assertTrue(wall.escaped and wallCrawler.escapedByWallCrawling,
        "Brain Spider Wall Crawling should let the spider leave unless adventurers can keep up")

    local tactician = entity_factory.createEntity("brain_spider")
    tactician.id = "npc_brain_spider_tactics"
    local tacticsTarget = base_entity.createEntity({
        id = "pc_brain_spider_tactics_target",
        name = "Tactics Target",
        isPC = true,
    })
    local tactics = resolver:resolve({
        actor = tactician,
        target = tacticsTarget,
        type = action_resolver.ACTION_TYPES.MELEE,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        greaterDoom = tactician.greaterDooms[1],
        targetInitiative = 20,
    })
    assertTrue(tactics.quickInterrupt and tactician ~= nil,
        "Brain Spider Tactics should mark the standard action as an interrupt")
    assertTrue(hasValue(tactics.effects, "brain_spider_tactics") and
        hasValue(tactics.effects, "standard_action_as_interrupt"),
        "Brain Spider Tactics should report the interrupt conversion")

    local sorcerer = entity_factory.createEntity("brain_spider_queen")
    sorcerer.id = "npc_brain_spider_sorcery"
    sorcerer.resolve = 0
    local missingDoom = resolver:resolve({
        actor = sorcerer,
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        card = { name = "Eight of Wands", value = 8, suit = constants.SUITS.WANDS },
        spellId = "illusion",
        image = "A priest vanishing behind a curtain",
        zoneId = "crypt",
    })
    assertTrue(not missingDoom.success,
        "Brain Spider Sorcery should require discarded greater doom cards instead of free Resolve")
    assertTrue(hasValue(missingDoom.effects, "brain_spider_sorcery_doom_missing"),
        "Brain Spider Sorcery should report missing greater doom payment")

    local sorcery = resolver:resolve({
        actor = sorcerer,
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        card = { name = "Eight of Wands", value = 8, suit = constants.SUITS.WANDS },
        spellId = "illusion",
        greaterDoom = sorcerer.greaterDooms[3],
        image = "A ribald puppet show",
        zoneId = "crypt",
    })
    assertTrue(sorcery.success, "Brain Spider Sorcery should cast Illusion with a greater doom card")
    assertTrue(hasValue(sorcery.effects, "brain_spider_sorcery") and
        hasValue(sorcery.effects, "greater_doom_instead_of_resolve"),
        "Brain Spider Sorcery should report greater-doom spell payment")
    assertEqual(sorcery.resolveSpent, 0,
        "Brain Spider Sorcery should spend no Resolve")
    assertEqual(sorcery.spellResolveValue, 1,
        "Brain Spider Sorcery should count one greater doom as one Resolve")
    assertEqual(sorcerer.resolve, 0,
        "Brain Spider Sorcery should not decrement the caster's Resolve")
    assertEqual(sorcerer.committedResolve or 0, 0,
        "Brain Spider Sorcery should not commit Resolve for ongoing Illusion")
    assertTrue(sorcery.visualIllusion and sorcery.visualIllusion.visualOnly,
        "Brain Spider Sorcery should still apply the Illusion spell effect")
end

function checkKodiWebSackLootRuntime(kodiRoom)
    local sackBus = events.createEventBus()
    local sackEvents = {}
    sackBus:on(events.EVENTS.FEATURE_LOOT_CLAIMED, function(data)
        sackEvents[#sackEvents + 1] = data
    end)
    local sackManager = room_manager.createRoomManager({ eventBus = sackBus })
    sackManager:registerRoom(room_manager.createRoomInstance(kodiRoom, kodiRoom.id))
    local sackBearer = base_entity.createEntity({
        id = "pc_kodi_sack_bearer",
        name = "Kodi Sack Bearer",
        isPC = true,
    })
    sackBearer.inventory = inventory.createInventory()
    local sackLoot = sackManager:resolveFeatureLootClaim(kodiRoom.id, "web_sacks", sackBearer)
    assertTrue(sackLoot.success and #sackLoot.items == 6,
        "Kodi web sacks should claim all six authored loot entries")
    assertTrue(hasValue(sackLoot.effects, "feature_loot_claimed") and
        hasValue(sackLoot.effects, "treasure_claimed"),
        "Kodi web-sack claim should report loot and treasure effects")
    assertTrue(sackBearer.inventory:findItemByPredicate(function(item)
        return item.templateId == "chest_111_key" and item.keyId == "111_spiders_treasure_chest"
    end) ~= nil, "Kodi web sacks should add the room 111 chest key to inventory")
    assertTrue(sackBearer.inventory:findItemByPredicate(function(item)
        return item.templateId == "golden_death_mask" and item.properties.appeasesGoldenGhosts
    end) ~= nil, "Kodi web sacks should add the seventh golden death mask to inventory")
    local runtimeSacks = sackManager:getFeature(kodiRoom.id, "web_sacks")
    assertTrue(runtimeSacks.lootTaken and runtimeSacks.state == "looted",
        "Kodi web sacks should persist their looted state")
    local repeatSackLoot = sackManager:resolveFeatureLootClaim(kodiRoom.id, "web_sacks", sackBearer)
    assertTrue(repeatSackLoot.alreadyClaimed and
        hasValue(repeatSackLoot.effects, "feature_loot_already_claimed"),
        "Kodi web sacks should not produce duplicate loot")
    assertEqual(#sackEvents, 1,
        "Kodi web-sack loot should emit one loot-claimed event")
end

function checkScriptoriumScrollRuntime(scriptorium)
    local function findRuntimeFeature(room, featureId)
        for _, feature in ipairs(room.features or {}) do
            if feature.id == featureId then
                return feature
            end
        end
        return nil
    end

    local actionSystem = interaction.createInteractionSystem({})
    local shelfActions = actionSystem:getValidActions(findRuntimeFeature(scriptorium, "bookshelves"))
    local caseActions = actionSystem:getValidActions(findRuntimeFeature(scriptorium, "sealed_scroll_case"))
    local hasPreserveAction = false
    local hasChronicleAction = false
    for _, actionData in ipairs(shelfActions or {}) do
        if actionData.action == "preserve_fragile_scrolls" then
            hasPreserveAction = true
        end
    end
    for _, actionData in ipairs(caseActions or {}) do
        if actionData.action == "open_chronicle_scroll" then
            hasChronicleAction = true
        end
    end
    assertTrue(hasPreserveAction, "Scriptorium shelves should expose a preserve-scrolls focus action")
    assertTrue(hasChronicleAction, "Sealed scroll case should expose an open-chronicle focus action")

    local preserveBus = events.createEventBus()
    local scrollEvents = {}
    local lootEvents = {}
    preserveBus:on(events.EVENTS.FEATURE_SCROLL_HANDLED, function(data)
        scrollEvents[#scrollEvents + 1] = data
    end)
    preserveBus:on(events.EVENTS.FEATURE_LOOT_CLAIMED, function(data)
        lootEvents[#lootEvents + 1] = data
    end)
    local preserveManager = room_manager.createRoomManager({ eventBus = preserveBus })
    preserveManager:registerRoom(room_manager.createRoomInstance(scriptorium, scriptorium.id))
    local scholar = base_entity.createEntity({
        id = "pc_scroll_scholar",
        name = "Scroll Scholar",
        isPC = true,
    })
    scholar.inventory = inventory.createInventory()

    local preserved = preserveManager:resolveSocialFeatureProcedure(
        scriptorium.id,
        "bookshelves",
        "preserve_fragile_scrolls",
        scholar,
        {}
    )
    assertTrue(preserved.success and preserved.preserved and
        hasValue(preserved.effects, "fragile_scrolls_preserved"),
        "Careful Scriptorium scroll handling should preserve the royal scrolls")
    assertTrue(scholar.inventory:findItemByPredicate(function(item)
        return item.templateId == "fragile_royal_scroll" and item.properties.openedCarefully
    end) ~= nil, "Preserved Scriptorium scrolls should enter inventory as carefully opened records")
    assertEqual(preserved.antiquarianValueRange.min, 10,
        "Preserved Scriptorium scrolls should retain the 10g antiquarian minimum")
    assertEqual(preserveManager:getFeature(scriptorium.id, "bookshelves").state, "preserved",
        "Preserved Scriptorium shelves should persist their handled state")
    local repeatPreserved = preserveManager:resolveFragileScrollHandling(
        scriptorium.id,
        "bookshelves",
        scholar,
        { careful = true, rightEnvironment = true }
    )
    assertTrue(repeatPreserved.alreadyHandled,
        "Preserved Scriptorium scrolls should not duplicate loot")

    local chronicle = preserveManager:resolveSocialFeatureProcedure(
        scriptorium.id,
        "sealed_scroll_case",
        "open_chronicle_scroll",
        scholar,
        {}
    )
    assertTrue(chronicle.success and hasValue(chronicle.effects, "opener_chronicle_started"),
        "Opening the sealed Vetus case should start the opener chronicle")
    assertTrue(chronicle.item.properties.activeChronicle and
        chronicle.item.properties.minuteByMinuteChronicle and
        chronicle.item.properties.growsUntilDestroyed,
        "Opened Vetus chronicle item should record minute-by-minute growth until destroyed")
    assertEqual(chronicle.item.properties.openerId, scholar.id,
        "Opened Vetus chronicle should record the opener")
    assertEqual(preserveManager:getFeature(scriptorium.id, "sealed_scroll_case").state, "chronicling",
        "Opened Vetus chronicle case should persist its chronicling state")
    local repeatChronicle = preserveManager:resolveSealedChronicleOpening(
        scriptorium.id,
        "sealed_scroll_case",
        scholar
    )
    assertTrue(repeatChronicle.alreadyOpened,
        "Opened Vetus chronicle should not duplicate its item")
    assertEqual(#scrollEvents, 2,
        "Preserved scrolls and opened chronicle should emit scroll-handled events")
    assertEqual(#lootEvents, 2,
        "Preserved scrolls and opened chronicle should each emit a loot-claimed event")

    local mishandleBus = events.createEventBus()
    local mishandleEvents = {}
    mishandleBus:on(events.EVENTS.FEATURE_SCROLL_HANDLED, function(data)
        mishandleEvents[#mishandleEvents + 1] = data
    end)
    local mishandleManager = room_manager.createRoomManager({ eventBus = mishandleBus })
    mishandleManager:registerRoom(room_manager.createRoomInstance(scriptorium, scriptorium.id))
    local careless = mishandleManager:resolveFragileScrollHandling(
        scriptorium.id,
        "bookshelves",
        scholar,
        { careful = false, rightEnvironment = true }
    )
    assertTrue(careless.success and careless.destroyed and
        hasValue(careless.effects, "scrolls_cracked_to_dust"),
        "Mishandled Scriptorium scrolls should crack and fall to dust")
    assertEqual(mishandleManager:getFeature(scriptorium.id, "bookshelves").state, "destroyed",
        "Mishandled Scriptorium scrolls should persist their destroyed state")
    assertEqual(#mishandleEvents, 1,
        "Mishandled Scriptorium scrolls should emit one scroll-handled event")
end

function checkTornPackLootRuntime(corpseRoom, tornPack)
    local packActions = interaction.createInteractionSystem({}):getValidActions(tornPack)
    local hasClaimAction = false
    for _, actionData in ipairs(packActions) do
        if actionData.action == "claim_loot" then
            hasClaimAction = true
        end
    end
    assertTrue(hasClaimAction, "Torn pack should expose a claim-loot focus action")

    local packBus = events.createEventBus()
    local packLootEvents = {}
    packBus:on(events.EVENTS.FEATURE_LOOT_CLAIMED, function(data)
        packLootEvents[#packLootEvents + 1] = data
    end)
    local packManager = room_manager.createRoomManager({ eventBus = packBus })
    packManager:registerRoom(room_manager.createRoomInstance(corpseRoom, corpseRoom.id))
    local packSearcher = base_entity.createEntity({
        id = "pc_torn_pack_searcher",
        name = "Torn Pack Searcher",
        isPC = true,
    })
    packSearcher.inventory = inventory.createInventory()
    local packLoot = packManager:resolveSocialFeatureProcedure(
        corpseRoom.id,
        "torn_pack",
        "claim_loot",
        packSearcher,
        {}
    )
    assertTrue(packLoot.success and #packLoot.items == 1 and
        packLoot.items[1].templateId == "alchemical_treatise_francis_stewbrew",
        "Torn pack claim should add Francis Stewbrew's treatise and no invented loot")
    assertTrue(packSearcher.inventory:findItemByPredicate(function(item)
        return item.templateId == "alchemical_treatise_francis_stewbrew" and
            item.properties.alchemicalTreatise
    end) ~= nil, "Torn pack claim should place the alchemical treatise in inventory")
    assertEqual(packManager:getFeature(corpseRoom.id, "torn_pack").state, "looted",
        "Torn pack should persist its looted state")
    local repeatPackLoot = packManager:resolveSocialFeatureProcedure(
        corpseRoom.id,
        "torn_pack",
        "claim_loot",
        packSearcher,
        {}
    )
    assertTrue(repeatPackLoot.alreadyClaimed and
        hasValue(repeatPackLoot.effects, "feature_loot_already_claimed"),
        "Torn pack should not duplicate the alchemical treatise")
    assertEqual(#packLootEvents, 1,
        "Torn pack claim should emit one loot-claimed event")
end

function checkTombOfGoldenGhostsBrainSpiderMapData()
    local function findRoom(roomId)
        for _, room in ipairs(tomb_data.data.rooms or {}) do
            if room.id == roomId then
                return room
            end
        end
        return nil
    end

    local function findFeature(room, featureId)
        for _, feature in ipairs(room.features or {}) do
            if feature.id == featureId then
                return feature
            end
        end
        return nil
    end

    local function findConnection(from, to)
        for _, connection in ipairs(tomb_data.data.connections or {}) do
            if connection.from == from and connection.to == to then
                return connection
            end
        end
        return nil
    end

    assertTrue(tomb_data.data.environment.defaultCorridors.dark and
        tomb_data.data.environment.defaultCorridors.material == "natural_limestone_caverns",
        "Tomb map should preserve dark natural limestone corridor defaults")
    assertTrue(tomb_data.data.environment.sensory.riverChurningToNorth and
        tomb_data.data.environment.sensory.smellsOfDampEarth,
        "Tomb map should preserve the river-to-north and damp-earth sensory frame")

    local scriptorium = findRoom("102_scriptorium")
    assertTrue(scriptorium ~= nil, "Scriptorium should be present")
    local shelves = findFeature(scriptorium, "bookshelves")
    assertTrue(shelves.fragileScrolls.requiresCarefulOpening and
        shelves.fragileScrolls.requiresRightEnvironment,
        "Scriptorium scrolls should require careful opening in the right environment")
    assertEqual(shelves.fragileScrolls.mishandledOutcome, "crack_and_fall_to_dust",
        "Mishandled Scriptorium scrolls should crack and fall to dust")
    assertEqual(shelves.fragileScrolls.antiquarianValueRange.min, 10,
        "Scriptorium scrolls should preserve the 10g minimum antiquarian value")
    assertEqual(shelves.fragileScrolls.antiquarianValueRange.max, 100,
        "Scriptorium scrolls should preserve the 100g maximum antiquarian value")
    assertTrue(shelves.fragileScrolls.specialCareToTransport,
        "Scriptorium scrolls should require special transport care")
    assertEqual(shelves.loot[1], "fragile_royal_scroll",
        "Scriptorium shelves should expose fragile royal scroll loot")
    local royalScroll = item_templates.getTemplate("fragile_royal_scroll")
    assertTrue(royalScroll.properties.readableBook and royalScroll.properties.fragile,
        "Fragile royal scroll should be a readable but fragile record")
    assertEqual(royalScroll.properties.loreSubjectId, "tomb_royal_records",
        "Fragile royal scroll should expose royal-record lore")
    assertEqual(royalScroll.properties.antiquarianValueRange.max, 100,
        "Fragile royal scroll template should preserve antiquarian value range")
    local scrollCase = findFeature(scriptorium, "sealed_scroll_case")
    assertEqual(scrollCase.vetusInscription, "Do not open unless special occasion",
        "Scriptorium sealed scroll case should preserve the Vetus warning")
    assertTrue(scrollCase.chronicle.minuteByMinute and scrollCase.chronicle.becomesInfinitelyLong,
        "Sealed chronicle scroll should record minute-by-minute infinite growth")
    assertTrue(scrollCase.chronicle.growsUntilDestroyed,
        "Sealed chronicle scroll should continue growing until destroyed")
    assertEqual(scrollCase.loot[1], "sealed_vetus_chronicle_scroll",
        "Scriptorium sealed case should expose the chronicle scroll item")
    local chronicleScroll = item_templates.getTemplate("sealed_vetus_chronicle_scroll")
    assertTrue(chronicleScroll.properties.vetus and chronicleScroll.properties.openerChronicle,
        "Sealed chronicle scroll template should preserve Vetus opener chronicle metadata")
    assertTrue(chronicleScroll.properties.becomesInfinitelyLong and
        chronicleScroll.properties.growsUntilDestroyed,
        "Sealed chronicle scroll template should preserve infinite growth until destroyed")
    local moldySmell = findFeature(scriptorium, "moldy_smell")
    assertEqual(moldySmell.type, "atmosphere",
        "Scriptorium moldy smell should remain atmospheric rather than an invented hazard")
    checkScriptoriumScrollRuntime(scriptorium)

    local centipedeRoom = findRoom("103_antechamber")
    assertTrue(centipedeRoom ~= nil, "Centipede antechamber should be present")
    local churnedGround = findFeature(centipedeRoom, "churned_ground")
    assertTrue(churnedGround.centipedesEmergeOnEntry and churnedGround.trap == nil,
        "Centipede antechamber ground should point to the encounter rather than an invented trap")
    local centipedeEncounter = findFeature(centipedeRoom, "dire_centipedes")
    assertTrue(centipedeEncounter.encounter.blueprint_id == "giant_centipede",
        "Centipede antechamber should use the Dire Centipede blueprint")
    assertEqual(centipedeEncounter.encounter.count, 3,
        "Centipede antechamber should contain three dire centipedes")
    assertTrue(centipedeEncounter.encounter.emergesOnEnter and centipedeEncounter.encounter.blocksPassage,
        "Centipede antechamber should have centipedes emerge and block passage")
    assertTrue(centipedeEncounter.encounter.pursuesOnlyIfAntagonized,
        "Centipede antechamber centipedes should not pursue unless antagonized")

    local centipedeEvents = {}
    local centipedeBus = events.createEventBus()
    centipedeBus:on(events.EVENTS.FEATURE_ENCOUNTER_TRIGGERED, function(data)
        centipedeEvents[#centipedeEvents + 1] = data
    end)
    local centipedeManager = room_manager.createRoomManager({ eventBus = centipedeBus })
    centipedeManager:registerRoom(room_manager.createRoomInstance(centipedeRoom, centipedeRoom.id))
    local entryResult = centipedeManager:resolveRoomEntryTriggers(centipedeRoom.id, {
        reason = "room_entry",
        watch = 2,
    })
    assertTrue(entryResult.triggers[1] and entryResult.spawns[1].blueprint_id == "giant_centipede",
        "entering Room 103 should trigger the dire centipede encounter")
    assertEqual(entryResult.spawns[1].count, 3,
        "Room 103 entry trigger should spawn all three dire centipedes")
    assertTrue(entryResult.spawns[1].pursuesOnlyIfAntagonized,
        "Room 103 entry spawns should preserve the no-pursuit-unless-antagonized rule")
    assertTrue(entryResult.blockedPassage and entryResult.blockingFeatureIds[1] == "dire_centipedes",
        "Room 103 entry trigger should report the centipedes blocking passage")
    assertTrue(hasValue(entryResult.effects, "room_entry_encounter_triggered"),
        "Room 103 entry trigger should report an entry encounter effect")
    assertTrue(hasValue(entryResult.effects, "room_entry_passage_blocked"),
        "Room 103 entry trigger should report blocked passage")
    local runtimeCentipedes = centipedeManager:getFeature(centipedeRoom.id, "dire_centipedes")
    assertTrue(runtimeCentipedes.encounterTriggered and runtimeCentipedes.entryTriggered and
        runtimeCentipedes.state == "active",
        "Room 103 runtime centipedes should be active after the entry trigger")
    assertEqual(runtimeCentipedes.triggerCount, 1,
        "Room 103 entry trigger should fire the encounter once")
    assertEqual(#centipedeEvents, 1,
        "Room 103 entry trigger should emit one encounter-trigger event")
    local repeatEntry = centipedeManager:resolveRoomEntryTriggers(centipedeRoom.id, {
        reason = "room_entry",
        watch = 3,
    })
    assertEqual(#repeatEntry.triggers, 0,
        "re-entering Room 103 after the entry trigger should not respawn centipedes")
    assertEqual(#repeatEntry.spawns, 0,
        "re-entering Room 103 after the entry trigger should not add new spawns")
    assertTrue(repeatEntry.alreadyResolved and repeatEntry.blockedPassage,
        "re-entering Room 103 should remember the resolved trigger while the active centipedes block passage")
    assertEqual(#centipedeEvents, 1,
        "re-entering Room 103 should not emit another encounter-trigger event")

    local movementEvents = {}
    local movementBus = events.createEventBus()
    movementBus:on(events.EVENTS.ROOM_ENTERED, function(data)
        movementEvents.roomEntered = data
    end)
    movementBus:on(events.EVENTS.PARTY_MOVED, function(data)
        movementEvents.partyMoved = data
    end)
    local movementCentipedeManager = room_manager.createRoomManager({ eventBus = movementBus })
    for _, roomData in ipairs(tomb_data.data.rooms) do
        movementCentipedeManager:registerRoom(room_manager.createRoomInstance(roomData, roomData.id))
    end
    local movementWatch = watch_manager.createWatchManager({
        dungeon = dungeon_graph.loadFromData(tomb_data.data),
        eventBus = movementBus,
        startingRoom = "101_entrance",
        roomManager = movementCentipedeManager,
    })
    local movedToCentipedes, moveResult = movementWatch:moveParty(centipedeRoom.id)
    assertTrue(movedToCentipedes, "movement into Room 103 should be allowed before the centipedes emerge")
    assertTrue(moveResult.entryTriggers and moveResult.entryTriggers.spawns[1] and
        moveResult.entryTriggers.spawns[1].blueprint_id == "giant_centipede",
        "WatchManager movement into Room 103 should resolve the entry centipede trigger")
    assertTrue(moveResult.entryTriggers.blockedPassage,
        "WatchManager movement into Room 103 should carry the blocked-passage entry result")
    assertTrue(movementEvents.roomEntered and movementEvents.roomEntered.entryTriggers == moveResult.entryTriggers,
        "Room-entered events should carry Room 103 entry-trigger results")
    assertTrue(movementEvents.partyMoved and movementEvents.partyMoved.entryTriggers == moveResult.entryTriggers,
        "Party-moved events should carry Room 103 entry-trigger results")

    local corpseRoom = findRoom("104_corpse")
    assertTrue(corpseRoom ~= nil, "Corpse room should be present")
    local tornPack = findFeature(corpseRoom, "torn_pack")
    assertEqual(tornPack.loot[1], "alchemical_treatise_francis_stewbrew",
        "Corpse room torn pack should contain Francis Stewbrew's alchemical treatise")
    assertEqual(tornPack.loot[2], nil,
        "Corpse room torn pack should not add non-rulebook key loot")
    assertEqual(findFeature(corpseRoom, "silver_key"), nil,
        "Corpse room should not preserve the obsolete laboratory key feature")
    local treatise = item_templates.getTemplate("alchemical_treatise_francis_stewbrew")
    assertTrue(treatise.properties.readableBook and treatise.properties.alchemicalTreatise,
        "Francis Stewbrew treatise should be a readable alchemy book")
    assertEqual(treatise.properties.loreSubjectId, "underworld_alchemical_reagents",
        "Francis Stewbrew treatise should expose reagent lore")
    checkTornPackLootRuntime(corpseRoom, tornPack)

    local hall = findRoom("105_hall_of_solemnity")
    assertTrue(hall ~= nil, "Hall of Solemnity should be present")
    local ghostWebs = findFeature(hall, "silvery_webs")
    assertEqual(ghostWebs.stretchFeet, 30,
        "Hall silvery webs should cover a thirty-foot stretch")
    assertTrue(ghostWebs.trap == nil,
        "Hall silvery webs should not invent an extra entangle trap")
    assertTrue(ghostWebs.brainSpiderWebs.solidToTangible and ghostWebs.brainSpiderWebs.solidToIntangible,
        "Hall silvery webs should block tangible and intangible creatures")
    assertTrue(ghostWebs.brainSpiderWebs.blocksGhosts and ghostWebs.brainSpiderWebs.destroyFreesGhosts,
        "Hall silvery webs should contain ghosts until destroyed")
    assertTrue(hasValue(ghostWebs.brainSpiderWebs.containedRooms, "108_tripartite_statue"),
        "Hall silvery webs should contain the whole burial-chamber ghost area")
    local webActions = interaction.createInteractionSystem({}):getValidActions(ghostWebs)
    local sawClearWebsAction = false
    for _, action in ipairs(webActions) do
        if action.action == "clear_webbing" then
            sawClearWebsAction = true
            assertEqual(action.level_required, interaction.LEVELS.GLANCE,
                "Silvery web clearing should be available as a focus action")
        end
    end
    assertTrue(sawClearWebsAction,
        "Hall silvery webs should expose a runtime clear-webbing action")
    local burialConnection = findConnection("105_hall_of_solemnity", "106_burial_chambers")
    assertTrue(burialConnection.properties.blocks_ghosts and burialConnection.properties.blocks_intangible,
        "Hall-to-burial connection should preserve ghost containment metadata")

    local burialChambers = findRoom("106_burial_chambers")
    assertTrue(burialChambers ~= nil, "Burial chambers should be present")
    assertTrue(burialChambers.goldenGhostActivity.hinderExplorersTheyHear,
        "Burial chambers should record that roaming ghosts hinder explorers they hear")
    assertTrue(hasValue(burialChambers.goldenGhostActivity.freeToMoveThroughRooms, "108_tripartite_statue"),
        "Burial chambers should preserve the full 106-108 golden ghost roaming range")
    local webDungeon = dungeon_graph.loadFromData(tomb_data.data)
    local runtimeWebConnection = webDungeon:getConnection("105_hall_of_solemnity", "106_burial_chambers")
    assertTrue(runtimeWebConnection.blocks_ghosts and runtimeWebConnection.blocks_intangible,
        "runtime Tomb graph should preserve web ghost-containment metadata")
    local freedEvents = {}
    local webBus = events.createEventBus()
    webBus:on(events.EVENTS.FEATURE_GHOST_CONTAINMENT_CLEARED, function(data)
        freedEvents[#freedEvents + 1] = data
    end)
    local webManager = room_manager.createRoomManager({
        dungeon = webDungeon,
        eventBus = webBus,
    })
    webManager:registerRoom(room_manager.createRoomInstance(hall, hall.id))
    webManager:registerRoom(room_manager.createRoomInstance(burialChambers, burialChambers.id))
    local runtimeLootedTomb = findRoom("107_looted_tomb")
    local runtimeStatueRoom = findRoom("108_tripartite_statue")
    webManager:registerRoom(room_manager.createRoomInstance(runtimeLootedTomb, runtimeLootedTomb.id))
    webManager:registerRoom(room_manager.createRoomInstance(runtimeStatueRoom, runtimeStatueRoom.id))
    local clearWebs = webManager:resolveBrainSpiderWebDestruction(hall.id, "silvery_webs", {
        dungeon = webDungeon,
    })
    assertTrue(clearWebs.success and hasValue(clearWebs.effects, "ghost_containment_cleared"),
        "destroying the Hall webs should clear ghost containment at runtime")
    assertTrue(hasValue(clearWebs.effects, "golden_ghosts_freed_unappeased") and
        clearWebs.outcome == "natural_disaster",
        "destroying webs before appeasement should free unappeased ghosts as a disaster")
    assertTrue(webManager:getFeature(hall.id, "silvery_webs").destroyed,
        "destroyed silvery webs should persist their cleared state")
    assertTrue(not runtimeWebConnection.blocks_ghosts and not runtimeWebConnection.blocks_intangible,
        "destroyed silvery webs should stop the runtime connection blocking ghosts")
    assertTrue(not runtimeWebConnection.properties.blocks_ghosts and
        runtimeWebConnection.properties.ghost_block_cleared,
        "destroyed silvery webs should update connection property metadata")
    assertTrue(webManager:getFeature(runtimeLootedTomb.id, "golden_ghosts").haunting.disasterPending,
        "unappeased golden ghosts should record disaster pending after webs are destroyed")
    assertTrue(webManager:getRoom(burialChambers.id).goldenGhostActivity.disasterPending,
        "burial chamber ghost activity should record the freed unappeased disaster")
    assertEqual(#freedEvents, 1,
        "destroying the silvery webs should emit one ghost-containment event")
    local astronomerMural = findFeature(burialChambers, "astronomer_mural")
    assertEqual(astronomerMural.reveal_connection.to, "116_glaura_nest",
        "Burial chamber astronomer mural should reveal the secret door to 116")
    assertTrue(astronomerMural.cannotOpenFromThisSide and
        astronomerMural.opensFromOtherSide == "116_glaura_nest",
        "Burial chamber secret door should only open from Glaura's side")

    local lootedTomb = findRoom("107_looted_tomb")
    assertTrue(lootedTomb ~= nil, "Looted tomb should be present")
    local goldenGhosts = findFeature(lootedTomb, "golden_ghosts")
    assertTrue(goldenGhosts.haunting.mute and goldenGhosts.haunting.communicatesByCharades,
        "Golden ghosts should be mute and communicate by gesture")
    assertEqual(goldenGhosts.haunting.demands.total, 7,
        "Golden ghosts should demand seven death masks")
    assertEqual(goldenGhosts.haunting.demands.locations[1].roomId, "111_spiders_treasure",
        "Golden ghosts should point to the six masks in room 111")
    assertEqual(goldenGhosts.haunting.demands.locations[2].roomId, "117_kodi_nest",
        "Golden ghosts should point to the one mask in Kodi's nest")
    assertEqual(goldenGhosts.haunting.appeasedOutcome, "return_to_sleep_of_death",
        "Appeased golden ghosts should return to the sleep of death")
    assertEqual(goldenGhosts.haunting.freedUnappeasedOutcome, "natural_disaster",
        "Freed unappeased golden ghosts should be treated as a disaster")
    local goldenGhostActions = interaction.createInteractionSystem({}):getValidActions(goldenGhosts)
    local sawReturnMasksAction = false
    for _, action in ipairs(goldenGhostActions) do
        if action.action == "return_death_masks" then
            sawReturnMasksAction = true
            assertEqual(action.level_required, interaction.LEVELS.GLANCE,
                "Golden ghosts should expose mask return as a focus action")
        end
    end
    assertTrue(sawReturnMasksAction,
        "Golden ghosts should allow the guild to return demanded death masks")
    local sarcophagi = findFeature(lootedTomb, "sarcophagi")
    assertEqual(sarcophagi.secrets, "The sarcophagi are empty.",
        "Looted tomb sarcophagi should not hide placeholder treasure")

    local statueRoom = findRoom("108_tripartite_statue")
    assertTrue(statueRoom ~= nil, "Tripartite statue room should be present")
    local statueFeature = findFeature(statueRoom, "tripartite_statue")
    assertTrue(statueFeature.ghostInterference.activeUntilDeathMasksReturned,
        "Golden ghosts should block statue tampering until their masks are returned")
    assertEqual(statueFeature.ghostInterference.deathMasksRequired, 7,
        "Tripartite statue ghost gate should require all seven masks")
    local ghostEvents = {}
    local puzzleEvents = {}
    local treasureEvents = {}
    local ghostBus = events.createEventBus()
    ghostBus:on(events.EVENTS.ROOM_HAUNTING_APPEASED, function(data)
        ghostEvents[#ghostEvents + 1] = data
    end)
