        "Tomb Meatgrinder X should preserve the cold unquiet-dead wind")
    local travelEvents = tomb_data.meatgrinder.travel_event
    assertEqual(travelEvents[1].effect, "quicksand",
        "Tomb Meatgrinder XI should be the centipede-churned quicksand event")
    assertEqual(travelEvents[1].target, "first_human_orc_troll_stature_adventurer",
        "Tomb Meatgrinder XI should target the first qualifying stature adventurer")
    assertTrue(travelEvents[2].excludesEntryExit,
        "Tomb Meatgrinder XII should spare only the entry exit from illusory walls")
    assertEqual(travelEvents[3].torchFlickersConsumed, 3,
        "Tomb Meatgrinder XIII should consume three torch flickers when clearing webs by torch")
    assertEqual(travelEvents[4].failure, "pulled_feet_first_20_feet_into_air",
        "Tomb Meatgrinder XIV should preserve the twenty-foot trap-web hoist")
    assertEqual(travelEvents[5].target, "each_player",
        "Tomb Meatgrinder XV should test every player against the earthquake")
    local randomEncounter = tomb_data.meatgrinder.random_encounter
    assertEqual(randomEncounter[1].controller_blueprint_id, "brain_spider_kodi",
        "Puppet-mummy Meatgrinder encounter should record Kodi as controller")
    assertTrue(randomEncounter[1].controllerHiddenByIllusion and randomEncounter[1].revealedBySecondSight,
        "Puppet-mummy Meatgrinder encounter should preserve Kodi's illusion reveal")
    assertEqual(randomEncounter[2].blueprint_id, "brain_spider_queen",
        "Glaura Meatgrinder encounter should use the named Glaura blueprint")
    assertTrue(randomEncounter[2].telepathicWarning and randomEncounter[2].usesWallCrawlingToEscape,
        "Glaura Meatgrinder encounter should warn and escape by Wall Crawling")
    assertTrue(randomEncounter[3].mute and randomEncounter[3].communicatesByCharades,
        "Golden ghost Meatgrinder encounter should preserve mute charades")
    assertEqual(randomEncounter[4].rivals[1].name, "Finch",
        "Rival adventurer Meatgrinder encounter should name Finch")
    assertEqual(randomEncounter[4].rivals[2].name, "Justin Pepperoni",
        "Rival adventurer Meatgrinder encounter should name Justin Pepperoni")
    assertEqual(randomEncounter[4].chasedBy.count, "discard",
        "Rival adventurer Meatgrinder encounter should be chased by discard-count centipedes")
    assertEqual(randomEncounter[4].rescueRewards[1], "signet_ring_20",
        "Rival adventurer rescue reward should include the 20g signet ring")
    assertEqual(item_templates.getTemplate("signet_ring_20").properties.value, 20,
        "Rival adventurer signet ring should be worth 20g")
    assertTrue(randomEncounter[4].slimeBombInHermeticBottle and
        randomEncounter[4].rescueRewards[2] == "slime_bomb",
        "Rival adventurer rescue reward should include a slime bomb in a hermetic bottle")
    assertEqual(randomEncounter[5].blueprint_id, "giant_centipede",
        "Dire centipede Meatgrinder encounter should keep the centipede blueprint id")
    assertTrue(randomEncounter[5].blocksEntry and randomEncounter[5].willNotPursueFleeingGuild,
        "Dire centipede Meatgrinder encounter should block entry but not pursue fleeing guild")
    assertTrue(tomb_data.meatgrinder.quest_rumor.description:find("next step") ~= nil,
        "Tomb Meatgrinder XXI should stay a context-delivered quest clue")
end

function checkTombOfGoldenGhostsDenizenRuntime()
    local bus = events.createEventBus()
    local zoneRegistry = zone_system.createZoneRegistry({ eventBus = bus })
    local zones = buildLinearZones()
    zoneRegistry:setRoomZones(zones)
    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
        zoneSystem = zoneRegistry,
    })

    local centipede = entity_factory.createEntity("giant_centipede")
    centipede.id = "npc_dire_centipede_fleet"
    centipede.zone = "A"
    zoneRegistry:placeEntity(centipede.id, centipede.zone)
    local blockedFleet = resolver:resolve({
        actor = centipede,
        type = action_resolver.ACTION_TYPES.CENTIPEDE_FLEET_MOVE,
        destinationZone = "B",
    })
    assertTrue(not blockedFleet.success and hasValue(blockedFleet.effects, "dire_centipede_fleet_requires_turn"),
        "Dire Centipede Fleet should only be available on the centipede's turn")

    local fleet = resolver:resolve({
        actor = centipede,
        type = action_resolver.ACTION_TYPES.CENTIPEDE_FLEET_MOVE,
        destinationZone = "B",
        onTurn = true,
        challengeController = { zones = zones },
    })
    assertTrue(fleet.success and fleet.countsTowardTurnCard == false and fleet.cardless,
        "Dire Centipede Fleet should move one zone without spending the centipede's turn card")
    assertEqual(centipede.zone, "B", "Dire Centipede Fleet should move to the destination zone")
    assertTrue(hasValue(fleet.effects, "dire_centipede_fleet"),
        "Dire Centipede Fleet should report its rulebook movement rider")

    local firstTarget = base_entity.createEntity({
        id = "pc_dire_centipede_trample_first",
        name = "First Dire Centipede Trample Target",
        isPC = true,
    })
    firstTarget.zone = "B"
    local secondTarget = base_entity.createEntity({
        id = "pc_dire_centipede_trample_second",
        name = "Second Dire Centipede Trample Target",
        isPC = true,
    })
    secondTarget.zone = "B"
    local trample = resolver:resolve({
        actor = centipede,
        target = firstTarget,
        secondTarget = secondTarget,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        lesserDoom = centipede.lesserDooms[1],
        targetInitiative = 20,
        secondTargetInitiative = 5,
    })
    assertTrue(not trample.success, "Dire Centipede Trample starts from an unsuccessful Attack")
    assertTrue(trample.trampleResult and trample.trampleResult.success,
        "Dire Centipede Trample should attack a second same-zone target after the miss")
    assertTrue(hasValue(trample.effects, "second_attack_after_miss_trample") and
        hasValue(trample.effects, "second_attack_after_miss"),
        "Dire Centipede Trample should report its data-driven follow-up attack")
    assertTrue(not firstTarget.conditions.staggered and secondTarget.conditions.staggered,
        "Dire Centipede Trample should wound the second target, not the missed first target")

    local puppet = entity_factory.createEntity("puppet_mummy")
    puppet.id = "npc_puppet_mummy_last_grasp"
    puppet.zone = "crypt"
    puppet.initiative = 7
    local allEntities = { puppet }
    local lastGraspEffects = {}
    local lastGrasp = resolver:applyDamage(puppet, 1, lastGraspEffects,
        { name = "Sword", weaponType = "sword" }, allEntities, nil, {
            source = "attack",
            targetGreaterDoom = puppet.greaterDooms[1],
            targetInitiative = 7,
        })
    assertTrue(lastGrasp and lastGrasp.result == "puppet_mummy_last_grasp",
        "Puppet-Mummy Last Grasp should prevent an incoming Wound")
    assertTrue(hasValue(lastGraspEffects, "puppet_mummy_last_grasp") and
        hasValue(lastGraspEffects, "puppet_mummy_severed_limb_spawned"),
        "Puppet-Mummy Last Grasp should report the severed limb")
    assertEqual(puppet.npcHealth, puppet.npcMaxHealth,
        "Puppet-Mummy Last Grasp should leave the puppet-mummy unwounded")
    assertTrue(not puppet.conditions.dead, "Puppet-Mummy Last Grasp should prevent destruction")
    assertEqual(#allEntities, 2, "Puppet-Mummy Last Grasp should add a new enemy to combat")
    local limb = allEntities[2]
    assertTrue(limb.puppetMummyLimb and limb.severedFrom == puppet.id,
        "Puppet-Mummy Last Grasp limb should remember its source")
    assertTrue(not limb.undead, "Puppet-Mummy severed limbs should remain non-undead")
    assertEqual(limb.zone, "crypt", "Puppet-Mummy Last Grasp limb should appear in the source zone")
    assertEqual(limb.initiative, 7, "Puppet-Mummy Last Grasp limb should use the source Initiative")
    assertEqual(limb.npcHealth, 1, "Puppet-Mummy Last Grasp limb should suffer 1 Wound before stopping")

    local limbEffects = {}
    resolver:applyDamage(limb, 1, limbEffects,
        { name = "Sword", weaponType = "sword" }, allEntities, nil, {
            source = "attack",
            targetGreaterDoom = puppet.greaterDooms[1],
        })
    assertTrue(limb.conditions.dead, "Puppet-Mummy severed limbs should not use Last Grasp")
    assertTrue(not hasValue(limbEffects, "puppet_mummy_last_grasp"),
        "Puppet-Mummy severed limbs should not report Last Grasp")
    assertEqual(#allEntities, 2, "Puppet-Mummy severed limbs should not spawn more limbs")

    local function tombRoom(roomId)
        for _, room in ipairs(tomb_data.data.rooms or {}) do
            if room.id == roomId then
                return room
            end
        end
        return nil
    end

    local manager = room_manager.createRoomManager({
        eventBus = events.createEventBus(),
        playerDeck = {
            peekDiscard = function()
                return { name = "Queen of Cups", value = constants.FACE_VALUES.QUEEN, suit = constants.SUITS.CUPS }
            end,
        },
    })
    manager:registerRoom(room_manager.createRoomInstance(tombRoom("116_glaura_nest"), "116_glaura_nest"))
    local ok, encounter = manager:resolveEncounterFeature("116_glaura_nest", "glaura_boss", {
        minorDiscardCard = { name = "Seven of Cups", value = 7, suit = constants.SUITS.CUPS },
    })
    assertTrue(ok, "Glaura nest encounter should resolve through the room manager")
    assertEqual(encounter.minorDiscardCard.value, constants.FACE_VALUES.QUEEN,
        "conditional Tomb allies should inspect the top minor discard before fallback inputs")
    assertEqual(#encounter.spawns, 2, "face-card minor discard should add the conditional Tomb ally")
    assertEqual(encounter.spawns[1].blueprint_id, "brain_spider_queen",
        "Glaura encounter should keep the primary brain spider queen spawn")
    assertEqual(encounter.spawns[2].blueprint_id, "brain_spider_kodi",
        "Glaura encounter should add Kodi when the top minor discard is a face card")
    assertEqual(encounter.activeConditionalAllies[1].conditionReason, "minor_discard_face_card",
        "resolved conditional ally should record why it was included")
    do
        local absentBus = events.createEventBus()
        local absentEvents = {}
        absentBus:on(events.EVENTS.FEATURE_ENCOUNTER_TRIGGERED, function(data)
            absentEvents[#absentEvents + 1] = data
        end)
        local absentManager = room_manager.createRoomManager({
            eventBus = absentBus,
            encounteredBlueprintIds = { brain_spider_queen = true },
        })
        absentManager:registerRoom(room_manager.createRoomInstance(tombRoom("116_glaura_nest"), "116_glaura_nest"))
        local absentOk, absentEncounter = absentManager:resolveEncounterFeature("116_glaura_nest", "glaura_boss")
        assertTrue(absentOk and absentEncounter.alreadyEncountered and #absentEncounter.spawns == 0,
            "Glaura nest should skip Glaura when she was already encountered elsewhere")
        assertTrue(hasValue(absentEncounter.effects, "encounter_already_encountered"),
            "unless-already-encountered resolution should report the skipped encounter")
        local absentTrigger = absentManager:triggerEncounterFeature("116_glaura_nest", "glaura_boss", {
            reason = "room_explored",
        })
        assertTrue(absentTrigger.success and absentTrigger.skipped and #absentTrigger.spawns == 0,
            "triggering an already encountered Glaura should not spawn a duplicate")
        assertEqual(absentManager:getFeature("116_glaura_nest", "glaura_boss").state, "absent",
            "already encountered Glaura should persist as absent in her nest")
        assertEqual(#absentEvents, 0,
            "skipped already-encountered features should not emit encounter-triggered events")
    end

    local noFaceManager = room_manager.createRoomManager({
        eventBus = events.createEventBus(),
    })
    noFaceManager:registerRoom(room_manager.createRoomInstance(tombRoom("117_kodi_nest"), "117_kodi_nest"))
    ok, encounter = noFaceManager:resolveEncounterFeature("117_kodi_nest", "kodi_dove_devourer", {
        minorDiscardCard = { name = "Seven of Cups", value = 7, suit = constants.SUITS.CUPS },
    })
    assertTrue(ok, "Kodi nest encounter should resolve through the room manager")
    assertEqual(#encounter.spawns, 1, "non-face minor discard should not add the conditional Tomb ally")
    assertEqual(encounter.spawns[1].blueprint_id, "brain_spider_kodi",
        "Kodi encounter should keep the primary named brain spider")
    assertEqual(encounter.inactiveConditionalAllies[1].blueprint_id, "brain_spider_queen",
        "Kodi encounter should retain inactive Glaura ally diagnostics")
    assertEqual(encounter.inactiveConditionalAllies[1].conditionReason, "minor_discard_not_face_card",
        "inactive conditional ally should record the non-face discard reason")
end

local function checkRecoverClearsBurningDuration()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local actor = base_entity.createEntity({
        id = "pc_weald_recover_burning",
        name = "Weald Burning Recover",
        isPC = true,
        wands = 3,
        armorSlots = 0,
        talents = {
            magic_of_the_weald = { mastered = true },
        },
    })

    local record = resolver:triggerMaleficence(actor, "weald", "smoke_test", {
        spell = { id = "control_animal", branch = "weald" },
    })
    local resolved = resolver:resolvePendingMaleficence(actor, {
        record = record,
        value = 10,
        allEntities = { actor },
    })

    assertTrue(resolved.success, "Weald X Self-Ignition should resolve from table data")
    assertTrue(hasValue(resolved.effects, "maleficence_damage"), "Weald X should wound the sorcerer")
    assertTrue(hasValue(resolved.effects, "maleficence_condition_burning"), "Weald X should apply Burning")
    assertTrue(actor.conditions.burning, "Weald X should mark the sorcerer Burning")
    assertTrue(actor.conditions.onFire, "Weald X should sync the legacy onFire condition")
    assertTrue(actor.onFire, "Weald X should sync actor.onFire")
    assertTrue(actor.burningGear and actor.burningGear.clothesOnFire and actor.burningGear.gearOnFire,
        "Weald X should record the sorcerer's clothes and gear catching fire")
    assertTrue(actor.burningGear.recoverActionRequired,
        "Weald X gear fire should record that Recover is required during Challenges")
    assertTrue(actor.burningGear.gmArbitratedConsequences,
        "Weald X gear fire should retain GM-arbitrated consequence metadata")
    assertEqual(actor.conditionDurations.burning["until"], "recover",
        "Weald X Burning should last until Recover")
    local hadStaggered = actor.conditions.staggered == true
    local hadInjured = actor.conditions.injured == true
    local woundedTalents = actor.woundedTalents or 0
    assertTrue(hadStaggered or hadInjured or woundedTalents > 0,
        "Weald X wound should still leave normal wound state")

    local recover = resolver:resolve({
        actor = actor,
        card = { name = "Any", value = 7, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.RECOVER,
    })
    assertTrue(recover.success, "Recover should clear Weald X Burning")
    assertTrue(hasValue(recover.effects, "recovered_burning"), "Recover should report Burning cleared")
    assertTrue(hasValue(recover.effects, "burning_gear_extinguished"),
        "Recover should report extinguishing the burning clothes and gear")
    assertTrue(hasValue(recover.effects, "recovered_duration_cleared"),
        "Recover should consume the recover-duration marker")
    assertTrue(not actor.conditions.burning, "Recover should clear Burning")
    assertTrue(not actor.conditions.onFire, "Recover should clear legacy onFire condition")
    assertTrue(not actor.onFire, "Recover should clear actor.onFire")
    assertTrue(actor.burningGear == nil and actor.maleficenceBurningGear == nil,
        "Recover should clear the active burning gear record")
    assertTrue(actor.extinguishedBurningGear and actor.extinguishedBurningGear.extinguished,
        "Recover should retain an extinguished burning gear audit record")
    assertTrue(actor.conditionDurations == nil or actor.conditionDurations.burning == nil,
        "Recover should remove the Burning duration marker")
    assertEqual(actor.conditions.staggered == true, hadStaggered,
        "Recover should not change Staggered from Self-Ignition")
    assertEqual(actor.conditions.injured == true, hadInjured,
        "Recover should not change Injured from Self-Ignition")
    assertEqual(actor.woundedTalents or 0, woundedTalents,
        "Recover should not heal the Self-Ignition talent wound")
end

function checkGMAdjudicatedMaleficenceDurationMilestones()
    local bus = events.createEventBus()
    local expired = {}
    local milestone = nil
    bus:on(events.EVENTS.CONDITION_EXPIRED, function(data)
        expired[#expired + 1] = data
    end)
    bus:on("maleficence_condition_milestone_resolved", function(data)
        milestone = data
    end)

    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
    })
    local actor = base_entity.createEntity({
        id = "pc_gm_maleficence_durations",
        name = "GM Maleficence Durations",
        isPC = true,
    })
    actor.conditions.shadowless = true
    actor.conditions.undead_mark = true
    actor.conditions.fungal_growth = true
    actor.conditions.silenced = true
    actor.conditionDurations = {
        shadowless = { ["until"] = "shadow_returns" },
        undead_mark = { ["until"] = "cleansed" },
        fungal_growth = { ["until"] = "cured" },
        silenced = { ["until"] = "fool_reshuffle" },
    }

    local shadow = resolver:resolveMaleficenceConditionMilestone(actor, "shadow_returns", {
        condition = "shadowless",
        trouble = "stole the magistrate's wig",
    })
    assertTrue(shadow.success, "Wayward Shadow should clear when the GM says the shadow returns")
    assertTrue(not actor.conditions.shadowless, "shadow return should clear Shadowless")
    assertTrue(actor.conditionDurations and not actor.conditionDurations.shadowless,
        "shadow return should remove only the matching duration marker")
    assertEqual(actor.waywardShadowReturned.trouble, "stole the magistrate's wig",
        "shadow return should record the GM-adjudicated trouble")
    assertTrue(hasValue(shadow.effects, "wayward_shadow_returned"),
        "shadow return should report its specific milestone")

    local cleansed = resolver:resolveMaleficenceConditionMilestone(actor, "cleansed", {
        condition = "undead_mark",
        method = "saintly absolution",
    })
    assertTrue(cleansed.success, "Undead Mark should clear through a GM-adjudicated cleansing")
    assertTrue(not actor.conditions.undead_mark, "cleansing should clear Undead Mark")
    assertTrue(hasValue(cleansed.effects, "maleficence_cleansed"),
        "cleansing should report its milestone")

    local cured = resolver:resolveMaleficenceConditionMilestone(actor, "cured", {
        condition = "fungal_growth",
        cure = "surgical cure",
    })
    assertTrue(cured.success, "Fungal Growth should clear through a GM-adjudicated cure")
    assertTrue(not actor.conditions.fungal_growth, "cure should clear Fungal Growth")
    assertTrue(hasValue(cured.effects, "maleficence_cured"), "cure should report its milestone")
    assertTrue(actor.conditions.silenced and actor.conditionDurations and actor.conditionDurations.silenced,
        "GM milestone clears should leave unrelated duration conditions alone")
    assertEqual(#expired, 3, "each GM milestone clear should emit a condition-expired event")
    assertEqual(expired[1].timing, "shadow_returns", "shadow expiry should carry its milestone timing")
    assertEqual(expired[2].timing, "cleansed", "cleansing expiry should carry its milestone timing")
    assertEqual(expired[3].timing, "cured", "cure expiry should carry its milestone timing")
    assertEqual(milestone, cured, "last successful milestone should emit the resolved milestone result")

    local noMatch = resolver:resolveMaleficenceConditionMilestone(actor, "cleansed", {
        condition = "silenced",
    })
    assertTrue(not noMatch.success, "wrong milestone should not clear unrelated maleficence durations")
    assertTrue(actor.conditions.silenced and actor.conditionDurations.silenced,
        "failed milestone clear should preserve the condition and duration")
end

local function checkBloodyTearsMaleficenceDisfavor()
    local bus = events.createEventBus()
    local testRequest = nil
    bus:on(events.EVENTS.REQUEST_TEST_OF_FATE, function(data)
        testRequest = data
    end)

    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
    })
    local actor = base_entity.createEntity({
        id = "pc_wastes_bloody_tears",
        name = "Wastes Bloody Tears",
        isPC = true,
        swords = 1,
        wands = 3,
        talents = {
            magic_of_the_wastes = { mastered = true },
        },
    })

    local record = resolver:triggerMaleficence(actor, "wastes", "smoke_test", {
        spell = { id = "necromancy", branch = "wastes" },
    })
    local resolved = resolver:resolvePendingMaleficence(actor, {
        record = record,
        value = 7,
        allEntities = { actor },
    })

    assertTrue(resolved.success, "Wastes VII Bloody Tears should resolve from table data")
    assertTrue(hasValue(resolved.effects, "maleficence_condition_bloody_tears"),
        "Wastes VII should report the Bloody Tears condition")
    assertTrue(actor.conditions.bloody_tears, "Wastes VII should mark Bloody Tears")
    assertEqual(actor.conditionDurations.bloody_tears["until"], "fool_reshuffle",
        "Wastes VII Bloody Tears should last until the next Fool reshuffle")
    assertTrue(actor.maleficenceConditionMetadata.bloody_tears.ruinsRobes,
        "Wastes VII should preserve the ruined-robes detail")
    assertTrue(actor.maleficenceConditionMetadata.bloody_tears.visionObscured,
        "Wastes VII should preserve bloody-tear vision obstruction metadata")

    local target = base_entity.createEntity({
        id = "npc_bloody_tears_target",
        name = "Bloody Tears Target",
        isPC = false,
        health = 2,
        defense = 0,
    })
    local attack = resolver:resolve({
        actor = actor,
        target = target,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        targetInitiative = 9,
    })
    assertTrue(not attack.success, "Bloody Tears should impose disfavor in combat")
    assertEqual(attack.favorModifier, -3, "Bloody Tears combat disfavor should subtract 3")
    assertTrue(hasValue(attack.effects, "bloody_tears_vision_disfavor"),
        "Bloody Tears combat disfavor should be reported")
    assertTrue(hasValue(attack.effects, "action_disfavor"),
        "Bloody Tears should use the Challenge Action disfavor channel")

    local pending = resolver:resolve({
        actor = actor,
        card = { name = "Three of Cups", value = 3, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.TEST_FATE,
        visionBased = true,
        challengeController = {
            isActive = function()
                return true
            end,
        },
    })
    assertTrue(pending.pendingTestOfFate, "vision-based Test Fate should still open the async test flow")
    assertTrue(testRequest ~= nil, "vision-based Test Fate should emit a request")
    assertEqual(testRequest.favor, false, "Bloody Tears should pass disfavor to vision-based Tests of Fate")
    assertTrue(hasValue(pending.effects, "bloody_tears_vision_disfavor"),
        "Bloody Tears Test Fate disfavor should be reported")
end

local function checkAngelicChantBlocksStealth()
    local bus = events.createEventBus()
    local testRequests = 0
    bus:on(events.EVENTS.REQUEST_TEST_OF_FATE, function()
        testRequests = testRequests + 1
    end)

    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
    })
    local actor = base_entity.createEntity({
        id = "pc_welkin_angelic_chant",
        name = "Welkin Angelic Chant",
        isPC = true,
        pentacles = 3,
        talents = {
            magic_of_the_welkin = { mastered = true },
        },
    })

    local record = resolver:triggerMaleficence(actor, "welkin", "smoke_test", {
        spell = { id = "heavenfire", branch = "welkin" },
    })
    local resolved = resolver:resolvePendingMaleficence(actor, {
        record = record,
        value = 5,
        allEntities = { actor },
    })

    assertTrue(resolved.success, "Welkin V Angelic Chant should resolve from table data")
    assertTrue(hasValue(resolved.effects, "maleficence_condition_angelic_chant"),
        "Welkin V should report the Angelic Chant condition")
    assertTrue(actor.conditions.angelic_chant, "Welkin V should mark Angelic Chant")
    assertEqual(actor.conditionDurations.angelic_chant["until"], "fool_reshuffle",
        "Welkin V Angelic Chant should last until the next Fool reshuffle")
    assertTrue(actor.maleficenceConditionMetadata.angelic_chant.musicBeautiful,
        "Welkin V should preserve the beautiful chanting detail")
    assertTrue(actor.maleficenceConditionMetadata.angelic_chant.musicLoud,
        "Welkin V should preserve the loud chanting detail")
    assertTrue(actor.maleficenceConditionMetadata.angelic_chant.stealthImpossible,
        "Welkin V should preserve stealth-impossible metadata")

    local stealth = resolver:resolve({
        actor = actor,
        card = { name = "Three of Pentacles", value = 3, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.TEST_FATE,
        stealth = true,
        challengeController = {
            isActive = function()
                return true
            end,
        },
    })

    assertTrue(not stealth.pendingTestOfFate, "Angelic Chant should block stealth before the async test flow")
    assertTrue(not stealth.success, "Angelic Chant should make stealth impossible")
    assertTrue(hasValue(stealth.effects, "stealth_impossible"), "blocked stealth should report stealth impossible")
    assertTrue(hasValue(stealth.effects, "angelic_chant_stealth_blocked"),
        "blocked stealth should report Angelic Chant")
    assertEqual(testRequests, 0, "blocked Angelic Chant stealth should not emit a Test Fate request")
end

function checkIronSteelArmorBlocksSwimSneak()
    local bus = events.createEventBus()
    local testRequests = 0
    bus:on(events.EVENTS.REQUEST_TEST_OF_FATE, function()
        testRequests = testRequests + 1
    end)

    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
    })
    local function activeChallenge()
        return {
            isActive = function()
                return true
            end,
        }
    end

    local ironSneak = base_entity.createEntity({
        id = "pc_iron_armor_stealth",
        name = "Iron Armor Stealth",
        isPC = true,
        pentacles = 3,
    })
    ironSneak.inventory = inventory.createInventory()
    ironSneak.inventory:addItem(inventory.createItemFromTemplate("iron_armor"), inventory.LOCATIONS.BELT)

    local blockedStealth = resolver:resolve({
        actor = ironSneak,
        card = { name = "Three of Pentacles", value = 3, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.TEST_FATE,
        stealth = true,
        challengeController = activeChallenge(),
    })
    assertTrue(not blockedStealth.success, "iron armor should make stealth Tests of Fate impossible")
    assertTrue(not blockedStealth.pendingTestOfFate, "blocked iron-armor stealth should not open async fate")
    assertTrue(hasValue(blockedStealth.effects, "heavy_armor_stealth_blocked"),
        "blocked iron-armor stealth should report the armor reason")

    local steelSwimmer = base_entity.createEntity({
        id = "pc_steel_armor_swimmer",
        name = "Steel Armor Swimmer",
        isPC = true,
        pentacles = 2,
    })
    steelSwimmer.inventory = inventory.createInventory()
    steelSwimmer.inventory:addItem(inventory.createItemFromTemplate("steel_armor"), inventory.LOCATIONS.BELT)

    local blockedSwim = resolver:resolve({
        actor = steelSwimmer,
        card = { name = "Four of Pentacles", value = 4, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.TEST_FATE,
        context = "swim through floodwater",
        challengeController = activeChallenge(),
    })
    assertTrue(not blockedSwim.success, "steel armor should make swimming Tests of Fate impossible")
    assertTrue(not blockedSwim.pendingTestOfFate, "blocked steel-armor swimming should not open async fate")
    assertTrue(hasValue(blockedSwim.effects, "heavy_armor_swim_blocked"),
        "blocked steel-armor swimming should report the armor reason")

    local lightSneak = base_entity.createEntity({
        id = "pc_light_armor_stealth",
        name = "Light Armor Stealth",
        isPC = true,
        pentacles = 2,
    })
    lightSneak.inventory = inventory.createInventory()
    lightSneak.inventory:addItem(inventory.createItemFromTemplate("light_armor"), inventory.LOCATIONS.BELT)

    local allowedLightArmor = resolver:resolve({
        actor = lightSneak,
        card = { name = "Five of Pentacles", value = 5, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.TEST_FATE,
        stealth = true,
        challengeController = activeChallenge(),
    })
    assertTrue(allowedLightArmor.pendingTestOfFate, "light armor should not block stealth Tests of Fate")

    local sneakActor = base_entity.createEntity({
        id = "pc_iron_sneak_talent",
        name = "Iron Sneak Talent",
        isPC = true,
        talents = {
            sneak = { mastered = true },
        },
    })
    sneakActor.inventory = inventory.createInventory()
    sneakActor.inventory:addItem(inventory.createItemFromTemplate("iron_armor"), inventory.LOCATIONS.BELT)
    local blockedSneakTalent = resolver:resolve({
        actor = sneakActor,
        type = action_resolver.ACTION_TYPES.SNEAK,
        mode = "go_sneaking",
    })
    assertTrue(not blockedSneakTalent.success, "iron armor should block the Sneak talent's go-sneaking procedure")
    assertTrue(not sneakActor.sneaking and not sneakActor.offStage,
        "blocked heavy-armor Sneak should not put the actor off-stage")
    assertEqual(testRequests, 1, "only the allowed light-armor Test Fate should emit a request")
end

