        wands = 3,
        zone = "dais",
        location = "sleep_chamber",
        talents = {
            magic_of_the_weird = { mastered = true },
        },
    })
    local ally = base_entity.createEntity({
        id = "pc_weird_sleep_test_ally",
        name = "Sleep Test Ally",
        isPC = true,
        wands = 1,
        zone = "alcove",
        location = "sleep_chamber",
    })
    local distant = base_entity.createEntity({
        id = "pc_weird_sleep_test_distant",
        name = "Distant Awake",
        isPC = true,
        wands = 0,
        zone = "dais",
        location = "outer_hall",
    })

    local record = resolver:triggerMaleficence(actor, "weird", "smoke_test", {
        spell = { id = "illusion", branch = "weird" },
    })
    local resolved = resolver:resolvePendingMaleficence(actor, {
        record = record,
        value = 3,
        allEntities = { actor, ally, distant },
        roomTestCards = {
            [actor.id] = { name = "Knight of Wands", value = 12, suit = constants.SUITS.WANDS },
            [ally.id] = { name = "Five of Cups", value = 5, suit = constants.SUITS.CUPS },
            [distant.id] = { name = "Ace of Cups", value = 1, suit = constants.SUITS.CUPS },
        },
    })

    assertTrue(resolved.success, "Weird III Sleep Test should resolve from table data")
    assertTrue(hasValue(resolved.effects, "maleficence_room_test_wands"),
        "Weird III should report the Wands room test")
    assertTrue(hasValue(resolved.effects, "maleficence_room_test_knocked_out"),
        "Weird III should report Knockout failures")
    assertEqual(#resolved.roomTests, 2, "Weird III should test everyone in the sorcerer's room")
    assertEqual(#resolved.roomTestFailures, 1, "Weird III should record failed Wands tests")
    assertTrue(not actor.conditions.knocked_out and not actor.conditions.sleeping,
        "successful Wands tests should avoid Knockout")
    assertTrue(ally.conditions.knocked_out and ally.conditions.knockout and ally.conditions.sleeping,
        "failed Wands tests should apply Knockout and deep sleep")
    assertTrue(ally.maleficenceSleep and ally.maleficenceSleep.deep,
        "Weird III Knockout should record maleficence sleep metadata")
    assertTrue(not distant.conditions.knocked_out and not distant.conditions.sleeping,
        "Weird III should not test creatures outside the sorcerer's room")
    assertTrue(not resolved.unappliedEffects, "room-test maleficence should not be left unapplied")
end

function checkWeirdLivingIllusionMaleficence()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local sorcerer = base_entity.createEntity({
        id = "pc_weird_living_illusion",
        name = "Living Illusion Sorcerer",
        isPC = true,
        wands = 3,
        talents = {
            magic_of_the_weird = { mastered = true },
        },
    })
    sorcerer.resolve = 2
    sorcerer.inventory = inventory.createInventory()
    sorcerer.inventory:addItem(inventory.createItemFromTemplate("component_illusion"), inventory.LOCATIONS.HANDS)

    local record = resolver:triggerMaleficence(sorcerer, "weird", "smoke_test", {
        spell = { id = "illusion", branch = "weird" },
    })
    local resolved = resolver:resolvePendingMaleficence(sorcerer, {
        record = record,
        value = 8,
    })

    assertTrue(resolved.success, "Weird VIII Living Illusion should resolve from table data")
    assertTrue(sorcerer.conditions.living_illusion and sorcerer.living_illusion,
        "Weird VIII should mark the sorcerer as a living illusion")
    assertTrue(sorcerer.conditions.cannot_cast_spells and sorcerer.cannot_cast_spells,
        "Weird VIII should block spellcasting while the illusion persists")
    assertTrue(sorcerer.conditions.cannot_interact_with_flesh and sorcerer.cannot_interact_with_flesh,
        "Weird VIII should block interaction with the plane of Flesh")
    assertTrue(resolved.livingIllusion and resolved.livingIllusion.visualOnly and
        resolved.livingIllusion.canInteractWithFlesh == false,
        "Weird VIII should retain the visual-only no-substance illusion metadata")
    assertEqual(sorcerer.conditionDurations.living_illusion["until"], "fool_reshuffle",
        "Weird VIII living illusion should last until the Fool reshuffle")
    assertEqual(sorcerer.conditionDurations.cannot_cast_spells["until"], "fool_reshuffle",
        "Weird VIII spellcasting block should expire with the living illusion")

    local cast = resolver:resolve({
        actor = sorcerer,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "illusion",
        illusionKind = "object",
        image = "glass flower",
        zoneId = "hall",
    })
    assertTrue(not cast.success, "living illusions should be unable to cast spells")
    assertTrue(hasValue(cast.effects, "spellcasting_blocked"),
        "living illusion spellcasting should report the concrete casting block")
    assertEqual(sorcerer.resolve, 2, "blocked living illusion spellcasting should not spend Resolve")
    assertTrue(not resolved.unappliedEffects, "living-illusion maleficence should not be left unapplied")
end

function checkConditionSpecificMaleficenceMetadata()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local weirdSorcerer = base_entity.createEntity({
        id = "pc_weird_condition_metadata",
        name = "Weird Metadata Sorcerer",
        isPC = true,
        talents = {
            magic_of_the_weird = { mastered = true },
        },
    })

    local mouthRecord = resolver:triggerMaleficence(weirdSorcerer, "weird", "smoke_test", {
        spell = { id = "illusion", branch = "weird" },
