    assertEqual(weirdSorcerer.maleficenceConditionMetadata.rhymebound.speechForm, "rhyming_couplets",
        "Weird IX should preserve the rhyming-couplets speech form")
    assertTrue(weirdSorcerer.maleficenceConditionMetadata.rhymebound.inCharacterSpeechOnly,
        "Weird IX should preserve the in-character speech limit")

