        "Wastes IX should record the departed shadow's mischief")
    assertEqual(wastesSorcerer.conditionDurations.shadowless["until"], "shadow_returns",
        "Wastes IX shadowless state should persist until the shadow returns")
    local shadowReturned = resolver:resolveMaleficenceConditionMilestone(wastesSorcerer, "shadow_returns", {
        condition = "shadowless",
        trouble = "painted lies on the chapel door",
    })
    assertTrue(shadowReturned.success, "Wastes IX shadow should clear through its return milestone")
    assertTrue(wastesSorcerer.waywardShadow and wastesSorcerer.waywardShadow.active == false and
        wastesSorcerer.waywardShadow.returned,
