    assertEqual(wastesSorcerer.conditionDurations.stunned.duration, "watch",
        "Wastes X Stunned state should last for a watch")
    assertTrue(twin.parasiticTwin.canDoVeryLittle,
        "Wastes X should preserve that the sorcerer can do very little")
    assertEqual(twin.parasiticTwin.chunks[1], "hands",
        "Wastes X should preserve the parasitic twin body-chunk details")

    local wealdSorcerer = base_entity.createEntity({
        id = "pc_weald_condition_metadata",
