        "Weald Queen should mark Lycanthropy and Cursed")
    assertTrue(lycanthropy.lycanthropy.moonTriggered and lycanthropy.lycanthropy.uncontrolled and
        lycanthropy.lycanthropy.violent,
        "Weald Queen should preserve the moon-triggered uncontrolled violent transformation")
    assertEqual(wealdSorcerer.conditionDurations.lycanthropy["until"], "cured",
        "Weald Queen Lycanthropy should persist until cured")
    assertEqual(wealdSorcerer.conditionDurations.cursed["until"], "cured",
        "Weald Queen Curse should share the lycanthropy cure milestone")
    assertTrue(not mouth.unappliedEffects and not interior.unappliedEffects and
        not lostVoice.unappliedEffects and not rhyme.unappliedEffects and
        not shadow.unappliedEffects and not twin.unappliedEffects and
        not fungus.unappliedEffects and not lycanthropy.unappliedEffects,
        "condition-specific maleficence metadata should not leave unapplied effects")
end

function checkWorldDelayedMaleficenceMetadata()
    local worldState = {}
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
        worldState = worldState,
    })
    local actor = base_entity.createEntity({
        id = "pc_world_delayed_maleficence_metadata",
        name = "World Metadata Sorcerer",
        isPC = true,
        talents = {
            magic_of_the_wastes = { mastered = true },
            magic_of_the_weald = { mastered = true },
            magic_of_the_weird = { mastered = true },
            magic_of_the_welkin = { mastered = true },
        },
    })

    local blightRecord = resolver:triggerMaleficence(actor, "wastes", "smoke_test", {
        spell = { id = "necromancy", branch = "wastes" },
    })
    local blight = resolver:resolvePendingMaleficence(actor, {
        record = blightRecord,
        value = 14,
    })
    assertTrue(blight.success, "Wastes King Regional Blight should resolve from table data")
    assertEqual(blight.worldConsequences[1].plantLife, "wither_and_die",
        "Wastes King should record regional plant death")
    assertTrue(blight.worldConsequences[1].stillbirths and blight.worldConsequences[1].civilizationConsequences,
        "Wastes King should preserve stillbirth and civilization fallout")

    local huntRecord = resolver:triggerMaleficence(actor, "weald", "smoke_test", {
        spell = { id = "control_animal", branch = "weald" },
    })
    local hunt = resolver:resolvePendingMaleficence(actor, {
        record = huntRecord,
        value = 14,
    })
    assertTrue(hunt.success, "Weald King Wild Hunt should resolve from table data")
    assertEqual(hunt.worldConsequences[1].tag, "wild_hunt",
        "Weald King should tag the Wild Hunt consequence")
    assertEqual(hunt.worldConsequences[1].headStartDays, 1,
        "Weald King should preserve the one-day head start")
    assertEqual(hunt.worldConsequences[1].messenger, "gnome",
        "Weald King should preserve the gnome messenger")
    assertEqual(hunt.worldConsequences[1].hunters, "wood_elves",
        "Weald King should preserve the wood-elf hunters")

    local nightmareRecord = resolver:triggerMaleficence(actor, "weird", "smoke_test", {
        spell = { id = "illusion", branch = "weird" },
    })
    local nightmare = resolver:resolvePendingMaleficence(actor, {
        record = nightmareRecord,
        value = 10,
    })
    assertTrue(nightmare.success, "Weird X Embodied Nightmare should resolve from table data")
    assertEqual(nightmare.delayedConsequences[1].timing, "next_camp_phase",
        "Weird X should remain tied to the next Camp phase")
    assertEqual(nightmare.delayedConsequences[1].step, 3,
        "Weird X should preserve the rulebook Camp step")
    assertEqual(nightmare.delayedConsequences[1].manifestation, "worst_nightmare",
        "Weird X should preserve the worst-nightmare manifestation")
    assertTrue(nightmare.delayedConsequences[1].requiresPlayerGMDiscussion,
        "Weird X should preserve the GM/player discussion requirement")

    local firstbornRecord = resolver:triggerMaleficence(actor, "welkin", "smoke_test", {
        spell = { id = "heavenfire", branch = "welkin" },
    })
    local firstborn = resolver:resolvePendingMaleficence(actor, {
        record = firstbornRecord,
        value = 10,
    })
    assertTrue(firstborn.success, "Welkin X Firstborn Doom should resolve from table data")
    assertEqual(firstborn.delayedConsequences[1].timing, "return_to_city",
        "Welkin X should trigger on return to the City")
    assertEqual(firstborn.delayedConsequences[1].target, "guild_parent_firstborns",
        "Welkin X should target guild members who are parents")
    assertTrue(firstborn.delayedConsequences[1].death,
        "Welkin X should record the firstborn death")
    assertEqual(firstborn.delayedConsequences[1].runeName, "sorcerer",
        "Welkin X should preserve that the sorcerer's name is written in runes")

    local meteorRecord = resolver:triggerMaleficence(actor, "welkin", "smoke_test", {
        spell = { id = "heavenfire", branch = "welkin" },
    })
    local meteor = resolver:resolvePendingMaleficence(actor, {
        record = meteorRecord,
        value = 14,
    })
    assertTrue(meteor.success, "Welkin King Meteor Star should resolve from table data")
    assertEqual(meteor.delayedConsequences[1].timing, "third_night",
        "Welkin King meteor should arrive at the end of the third night")
    assertEqual(meteor.delayedConsequences[1].starColor, "discharge_brown",
        "Welkin King should preserve the star color")
    assertTrue(meteor.worldConsequences[1].randomDistrict and meteor.worldConsequences[1].cityUninhabitableWeeks,
        "Welkin King should preserve random district destruction and city uninhabitability")
    assertEqual(#worldState.worldConsequences, 3,
        "world-state metadata smoke should retain all world consequences")
    assertEqual(#worldState.delayedConsequences, 3,
        "world-state metadata smoke should retain all delayed consequences")
    assertTrue(not blight.unappliedEffects and not hunt.unappliedEffects and
        not nightmare.unappliedEffects and not firstborn.unappliedEffects and not meteor.unappliedEffects,
        "world and delayed maleficence metadata should not leave unapplied effects")
end

function checkWeirdPermanentSilenceAllowsSpellcasting()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local sorcerer = base_entity.createEntity({
        id = "pc_weird_permanent_silence",
        name = "Silent Weird Sorcerer",
        isPC = true,
        wands = 3,
        talents = {
            magic_of_the_weird = { mastered = true },
        },
    })
    sorcerer.resolve = 2
    sorcerer.inventory = inventory.createInventory()
    sorcerer.inventory:addItem(inventory.createItemFromTemplate("component_illusion"), inventory.LOCATIONS.HANDS)

    local record = resolver:triggerMaleficence(sorcerer, "weird", "smoke_test", {
        spell = { id = "illusion", branch = "weird" },
    })
    local resolved = resolver:resolvePendingMaleficence(sorcerer, {
        record = record,
        value = 14,
    })

    assertTrue(resolved.success, "Weird King Permanent Silence Curse should resolve from table data")
    assertTrue(sorcerer.conditions.silenced and sorcerer.conditions.cursed,
        "Weird King should mark the sorcerer Silenced and Cursed")
    assertTrue(resolved.silenceCurse and resolved.silenceCurse.canCastSpells,
        "Weird King should record the rulebook spellcasting exception")
    assertTrue(sorcerer.conditionDurations.silenced.permanent and
        sorcerer.conditionDurations.silenced.canCastSpells,
        "Weird King Silence should be permanent but spellcasting-capable")
    assertTrue(sorcerer.conditionDurations.silenced.illusoryTextSpeech,
        "Weird King should preserve the illusory text speech-balloon detail")

    local cast = resolver:resolve({
        actor = sorcerer,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "illusion",
        illusionKind = "object",
        image = "floating words",
        zoneId = "hall",
    })

    assertTrue(cast.success, "Weird King permanent Silence should still allow spellcasting")
    assertTrue(not hasValue(cast.effects, "spell_speech_blocked"),
        "Weird King spellcasting should bypass the generic Silenced speech block")
    assertEqual(sorcerer.resolve, 1,
        "successful spellcasting through Weird King silence should spend Resolve normally")
    assertTrue(not resolved.unappliedEffects, "Weird King should not be left unapplied")
end

local function checkPermanentBodyChangeMaleficence()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
