        assertTrue(actor.bodyChanges[3].affectsReflections, "Decaying Reflection should target reflections")
        assertTrue(actor.bodyChanges[3].decaysOverTime, "Decaying Reflection should decay over time")
        assertEqual(actor.bodyChanges[3].finalReflection, "bleached_white_skull",
