        assertEqual(actor.bodyChanges[5].hairColor, "milky_white", "Milky Pallor should preserve hair color")
        assertEqual(actor.bodyChanges[5].skinColor, "milky_white", "Milky Pallor should preserve skin color")
        assertEqual(actor.bodyChanges[5].irisColor, "milky_white", "Milky Pallor should preserve iris color")
        assertTrue(actor.conditions.milky_pallor, "Milky Pallor should expose a condition flag")
