local function checkChallengeItemActions()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local actor = base_entity.createEntity({
        id = "pc_1",
        name = "Item User",
        isPC = true,
        cups = 3,
        armorSlots = 0,
        talents = { nimble = { wounded = false } },
    })
    actor.inventory = inventory.createInventory()

    local sword = inventory.createItem({ name = "Sword", size = 1 })
    local potion = inventory.createItemFromTemplate("healing_potion")
    local torch = inventory.createItem({ name = "Torch", size = 1 })

    actor.inventory:addItem(sword, inventory.LOCATIONS.HANDS)
    actor.inventory:addItem(potion, inventory.LOCATIONS.PACK)
    actor.inventory:addItem(torch, inventory.LOCATIONS.BELT)

    local pullPack = resolver:resolve({
        actor = actor,
        card = { name = "Cups", value = 2, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.PULL_ITEM,
        itemId = potion.id,
        swapWithItemId = sword.id,
    })
    assertTrue(pullPack.success, "Pull Item from Pack should succeed with a swappable held item")
    local potionLoc = select(2, actor.inventory:findItem(potion.id))
    local swordLoc = select(2, actor.inventory:findItem(sword.id))
    assertEqual(potionLoc, inventory.LOCATIONS.HANDS, "pulled pack item should move to hands")
    assertEqual(swordLoc, inventory.LOCATIONS.PACK, "held item should swap back to pack")
    assertEqual(pullPack.sourceLocation, inventory.LOCATIONS.PACK,
        "Pull Item from Pack should report the source location")
    assertEqual(pullPack.destinationLocation, inventory.LOCATIONS.HANDS,
        "Pull Item from Pack should report the destination location")

    do
        local packPullPopup = getActionSequencerPopup({
            actor = actor,
            type = action_resolver.ACTION_TYPES.PULL_ITEM,
            item = potion,
        }, pullPack, function(data)
            return data.fromPack or data.fromBelt
        end)
        assertTrue(packPullPopup ~= nil, "Pull Item from Pack should queue a visible item popup")
        assertTrue(packPullPopup.fromPack, "Pull Item popup should mark the pack source")
        assertEqual(packPullPopup.pulledItem, potion, "Pull Item popup should preserve the pulled pack item")
        assertEqual(packPullPopup.swappedItem, sword, "Pull Item popup should preserve the swapped held item")
        assertEqual(packPullPopup.destinationLocation, inventory.LOCATIONS.HANDS,
            "Pull Item popup should preserve the destination location")
    end

    do
        local invalidSwapActor = base_entity.createEntity({
            id = "pc_invalid_pack_swap",
            name = "Invalid Pack Swap",
            isPC = true,
            cups = 1,
        })
        invalidSwapActor.inventory = inventory.createInventory()
        local handA = inventory.createItem({ name = "Held Knife", size = 1 })
        local handB = inventory.createItem({ name = "Held Cup", size = 1 })
        local packItem = inventory.createItem({ name = "Pack Flask", size = 1 })
        invalidSwapActor.inventory:addItem(handA, inventory.LOCATIONS.HANDS)
        invalidSwapActor.inventory:addItem(handB, inventory.LOCATIONS.HANDS)
        invalidSwapActor.inventory:addItem(packItem, inventory.LOCATIONS.PACK)
        local invalidSwap = resolver:resolve({
            actor = invalidSwapActor,
            card = { name = "Cups", value = 2, suit = constants.SUITS.CUPS },
            type = action_resolver.ACTION_TYPES.PULL_ITEM,
            itemId = packItem.id,
            swapWithItemId = "not-held",
        })
        assertTrue(not invalidSwap.success,
            "Pull Item from Pack should reject an explicit swap item that is not held")
        assertTrue(hasValue(invalidSwap.effects, "swap_item_not_held"),
            "invalid Pull Item swap should report the selected held-item gate")
        assertEqual(select(2, invalidSwapActor.inventory:findItem(packItem.id)), inventory.LOCATIONS.PACK,
            "invalid Pull Item swap should leave the pack item in the pack")
        assertEqual(select(2, invalidSwapActor.inventory:findItem(handA.id)), inventory.LOCATIONS.HANDS,
            "invalid Pull Item swap should not choose a fallback held item")
    end

    actor.conditions.injured = true
    usePotionAction = {
        actor = actor,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = potion.id,
        item = potion,
    }
    local usePotion = resolver:resolve(usePotionAction)
    assertTrue(usePotion.success, "Use Item should allow a held item")
    assertTrue(usePotion.itemUse and usePotion.itemUse.item == potion,
        "Use Item should preserve structured item-use metadata")
    assertTrue(usePotion.itemUse.itemConsumed and usePotion.itemUse.consumedItem == potion,
        "Use Item metadata should preserve consumed item state")
    assertEqual(usePotion.itemUse.itemEffectType, "heal_wound",
        "Use Item metadata should preserve the item effect type")
    do
        useItemPopup = getActionSequencerPopup(usePotionAction, usePotion, function(data)
            return data.title == "Use Item"
        end)
        assertTrue(useItemPopup ~= nil, "Use Item should queue a visible item-effect popup")
        assertEqual(useItemPopup.item, potion, "Use Item popup should preserve the item")
        assertEqual(useItemPopup.itemEffectType, "heal_wound",
            "Use Item popup should preserve the item effect type")
        assertTrue(useItemPopup.itemConsumed, "Use Item popup should preserve consumed item state")
    end
    assertTrue(not actor.conditions.injured, "healing potion should clear a wound through healWound")
    assertTrue(not actor.inventory:findItem(potion.id), "consumable potion should leave inventory after use")

    local deathDoorActor = base_entity.createEntity({
        id = "pc_death_door_heal",
