        assertTrue(beltPullPopup.fromBelt, "Pull Item popup should mark the belt source")
        assertEqual(beltPullPopup.pulledItem, torch, "Pull Item popup should preserve the pulled belt item")
        assertEqual(beltPullPopup.swappedItem, nil,
            "Pull Item popup should omit swap metadata when nothing was swapped")
