        local bathOil = inventory.createItemFromTemplate("griffin_oil")
        local stinkingAdventurer = base_entity.createEntity({
            id = "pc_griffin_bath",
            name = "Stinking Adventurer",
            isPC = true,
        })
        stinkingAdventurer.inventory = inventory.createInventory()
        stinkingAdventurer.conditions.stressed = true
        stinkingAdventurer.conditions.imp_stink = true
        stinkingAdventurer.conditions.choking_stink = true
        stinkingAdventurer.impStink = { stressedUntilWashed = true }
        stinkingAdventurer.conditionDurations = {
            imp_stink = { ["until"] = "washed" },
            choking_stink = { ["until"] = "washed" },
            stressed = { ["until"] = "washed" },
        }
        stinkingAdventurer.inventory:addItem(bathOil, inventory.LOCATIONS.HANDS)
        local bathUse = resolver:resolve({
            actor = stinkingAdventurer,
            card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
            type = action_resolver.ACTION_TYPES.USE_ITEM,
            itemId = bathOil.id,
            target = stinkingAdventurer,
            dungeonBath = true,
        })
        assertTrue(bathUse.success, "griffin oil should support an impromptu dungeon bath")
        assertTrue(not stinkingAdventurer.conditions.imp_stink and not stinkingAdventurer.impStink,
            "griffin oil bath should wash off Imp stink")
        assertTrue(not stinkingAdventurer.conditions.stressed,
            "washing off Imp stink should clear its stress rider")
        assertTrue(not stinkingAdventurer.conditionDurations.imp_stink and
            not stinkingAdventurer.conditionDurations.choking_stink and
            not stinkingAdventurer.conditionDurations.stressed,
            "washing off Imp stink should clear wash-off duration metadata")
        assertTrue(stinkingAdventurer.griffinOilBath, "griffin oil should record the dungeon bath")
    end

    local questOil = inventory.createItemFromTemplate("questing_beast_oil")
    local barkingDoor = inventory.createItem({ name = "Barking Door", size = 2, properties = {} })
    local meatgrinderDraws = {
        { category = watch_manager.MEATGRINDER.RANDOM_ENCOUNTER, description = "A monster finds the sound." },
        { category = watch_manager.MEATGRINDER.CURIOSITY, description = "A strange noise answers." },
    }
    local meatgrinderDrawCount = 0
    local questWatch = {
        drawMeatgrinder = function()
            meatgrinderDrawCount = meatgrinderDrawCount + 1
            return meatgrinderDraws[meatgrinderDrawCount]
        end,
    }
    actor.inventory:addItem(questOil, inventory.LOCATIONS.HANDS)
    local questOilUse = resolver:resolve({
        actor = actor,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = questOil.id,
        target = barkingDoor,
        watchManager = questWatch,
    })
    assertTrue(questOilUse.success, "questing beast oil should be usable on an object")
    assertEqual(meatgrinderDrawCount, 2,
        "questing beast oil should draw twice on the Meatgrinder table")
    assertTrue(barkingDoor.properties.barkingLure and barkingDoor.properties.questingBeastBark,
        "questing beast oil should mark a barking lure")
    assertEqual(barkingDoor.properties.effectDurations.barkingLure.duration, "watch",
        "questing beast oil should last for a watch")
    assertEqual(#questOilUse.questingBeastEncounters, 1,
        "questing beast oil should flag encounters drawn to the lure")
    assertTrue(meatgrinderDraws[1].questingBeastLure,
        "questing beast oil should annotate drawn encounter records")
    assertTrue(not actor.inventory:findItem(questOil.id), "questing beast oil should be consumed")

    local ungoatOil = inventory.createItemFromTemplate("ungoat_oil")
    local spellCaster = base_entity.createEntity({
        id = "pc_ungoat_oil_caster",
        name = "Ungoat Oil Caster",
        isPC = true,
        conditions = {},
    })
    local spellTarget = base_entity.createEntity({
        id = "pc_ungoat_oil_target",
        name = "Ungoat Oil Target",
        isPC = true,
        conditions = {},
    })
    local activeSizeSpell = {
        spellId = "change_size",
        target = spellTarget,
        resolveCommitted = 1,
        concentration = true,
    }
    spellCaster.activeSpells = { activeSizeSpell }
    spellCaster.committedResolve = 1
    spellTarget.conditions.sizeChanged = true
    spellTarget.conditions.sizeGrown = true
    spellTarget.changeSize = { caster = spellCaster, active = true, mode = "grow" }
    spellTarget.sizeMultiplier = 2
    actor.inventory:addItem(ungoatOil, inventory.LOCATIONS.HANDS)
    local ungoatOilUse = resolver:resolve({
        actor = actor,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = ungoatOil.id,
        target = spellTarget,
        allEntities = { spellCaster },
    })
    assertTrue(ungoatOilUse.success, "ungoat oil should be usable on a spell-affected target")
    assertEqual(#spellCaster.activeSpells, 0,
        "ungoat oil should end active concentration spells affecting the target")
    assertEqual(spellCaster.committedResolve, 0,
        "ungoat oil should release committed Resolve from ended concentration spells")
    assertTrue(spellTarget.changeSize == nil and not spellTarget.conditions.sizeChanged,
        "ungoat oil should run active spell cleanup")
    assertTrue(spellTarget.properties.magicSuppressed,
        "ungoat oil should suppress target magic for a watch")
    assertEqual(spellTarget.properties.effectDurations.magicSuppressed.duration, "watch",
        "ungoat oil suppression should record its watch duration")
    assertTrue(not actor.inventory:findItem(ungoatOil.id), "ungoat oil should be consumed")

    local slimeOil = inventory.createItemFromTemplate("slime_oil")
    local woodenDoor = inventory.createItem({
        name = "Wooden Door",
        size = 2,
        durability = 2,
        properties = { material = "wood" },
    })
    actor.inventory:addItem(slimeOil, inventory.LOCATIONS.HANDS)
    local slimeOilUse = resolver:resolve({
        actor = actor,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = slimeOil.id,
        target = woodenDoor,
    })
    assertTrue(slimeOilUse.success, "slime oil should be usable on an object")
    assertTrue(woodenDoor.destroyed, "slime oil should destroy non-magical objects it touches")
    assertTrue(not actor.inventory:findItem(slimeOil.id), "slime oil should be consumed")

    local undeadActor = base_entity.createEntity({
        id = "undead_potion_user",
        name = "Undead",
        isPC = false,
        health = 2,
        defense = 0,
        undead = true,
    })
    undeadActor.undead = true
    undeadActor.inventory = inventory.createInventory()
    local undeadPotion = inventory.createItemFromTemplate("slime_potion")
    undeadActor.inventory:addItem(undeadPotion, inventory.LOCATIONS.HANDS)
    local undeadPotionUse = resolver:resolve({
        actor = undeadActor,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = undeadPotion.id,
    })
    assertTrue(undeadPotionUse.success, "potion use on undead should still spend the item")
    assertTrue(not undeadActor.conditions.shapeless_body, "potions should not affect undead")
    assertTrue(not undeadActor.inventory:findItem(undeadPotion.id), "ineffective potion should still be consumed")
end

function checkVampireBombExposureRuntime()
    local bus = events.createEventBus()
    local exposureEvents = {}
    bus:on(events.EVENTS.VAMPIRE_WEAKNESS_EXPOSURE, function(payload)
        exposureEvents[#exposureEvents + 1] = payload
    end)

    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
    })
    local actor = base_entity.createEntity({
        id = "pc_vampire_bomb_exposure_user",
        name = "Vampire Bomb Exposure User",
        isPC = true,
        cups = 3,
    })
    actor.inventory = inventory.createInventory()
    local target = base_entity.createEntity({
        id = "npc_vampire_bomb_exposure_target",
        name = "Vampire Bomb Exposure Target",
        isPC = false,
        health = 2,
        defense = 0,
    })
    local vampireBomb = inventory.createItemFromTemplate("vampire_bomb")
    actor.inventory:addItem(vampireBomb, inventory.LOCATIONS.HANDS)

    local use = resolver:resolve({
        actor = actor,
        card = { name = "Cups", value = 8, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = vampireBomb.id,
        target = target,
        targetInitiative = 7,
    })
    assertTrue(use.success, "vampire bomb should land before later exposure is checked")
    assertTrue(target.conditions.vampire_weaknesses and target.conditions.sunlight_stuns,
        "vampire bomb should apply a watch-long weakness package")
    assertTrue(not target.conditions.stunned,
        "vampire bomb should not Stun until a weakness trigger is present")

    local ignored = resolver:resolveVampireWeaknessExposure(target, "cold iron")
    assertTrue(not ignored.success and ignored.reason == "not_vampire_weakness_trigger",
        "unlisted exposure should not trigger vampire-bomb weakness")

    local silverExposure = resolver:resolveVampireWeaknessExposure(target, { silver = true })
    assertTrue(silverExposure.success and target.conditions.stunned and target.conditions.stunnedInstant,
        "later silver exposure should Stun a vampire-bombed target")
    assertEqual(target.vampireWeaknesses.lastExposure, "silver",
        "later weakness exposure should record the trigger")
    assertEqual(#exposureEvents, 1, "later weakness exposure should emit one presentation event")
    assertEqual(exposureEvents[1].exposure, "silver",
        "weakness exposure event should name the trigger")

    target.conditions.stunned = false
    target.conditions.stunnedInstant = false
    local herbExposure = resolver:resolveVampireWeaknessExposure(target, "wild rose")
    assertTrue(herbExposure.success and target.conditions.stunned,
        "wholesome herb examples should trigger vampire-bomb weakness")
    assertEqual(target.vampireWeaknesses.lastExposure, "wild_rose",
        "herb example exposure should be normalized")

    local manager = watch_manager.createWatchManager({
        eventBus = bus,
        guild = { target },
    })
    manager:clearWatchDurationConditions()
    assertTrue(not target.conditions.vampire_weaknesses and not target.conditions.sunlight_stuns,
        "watch expiry should clear vampire-bomb weakness flags")
    assertTrue(target.vampireWeaknesses == nil,
        "watch expiry should clear the stored vampire-bomb weakness record")

    local expiredExposure = resolver:resolveVampireWeaknessExposure(target, "sunlight")
    assertTrue(not expiredExposure.success and expiredExposure.reason == "no_vampire_weaknesses",
        "expired vampire-bomb weakness should no longer Stun on exposure")
end

function checkAlchemicalObjectPropertyWatchExpiry()
    local bus = events.createEventBus()
    local propertyEvents = {}
    bus:on(events.EVENTS.PROPERTY_EXPIRED, function(payload)
        propertyEvents[#propertyEvents + 1] = payload
    end)

    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
    })
    local actor = base_entity.createEntity({
        id = "pc_alchemical_property_expiry",
        name = "Alchemical Property Expiry",
        isPC = true,
        cups = 3,
    })
    actor.inventory = inventory.createInventory()

    local glue = inventory.createItemFromTemplate("brain_spider_oil")
    local door = inventory.createItem({ name = "Glue Door", size = 2, properties = { object = true } })
    local bar = inventory.createItem({ name = "Glue Bar", size = 1, properties = { object = true } })
    actor.inventory:addItem(glue, inventory.LOCATIONS.HANDS)
    local glueUse = resolver:resolve({
        actor = actor,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = glue.id,
        target = door,
        secondaryTarget = bar,
        contestedUseItem = false,
    })
    assertTrue(glueUse.success and door.adheredTo == bar and bar.adheredTo == door,
        "brain spider oil should create a watch-long reciprocal adhesion bond")

    local questOil = inventory.createItemFromTemplate("questing_beast_oil")
    local statue = inventory.createItem({ name = "Barking Statue", size = 2, properties = { object = true } })
    actor.inventory:addItem(questOil, inventory.LOCATIONS.HANDS)
    local questUse = resolver:resolve({
        actor = actor,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = questOil.id,
        target = statue,
        contestedUseItem = false,
    })
    assertTrue(questUse.success and statue.properties.barkingLure and statue.properties.questingBeastBark,
        "questing beast oil should create a watch-long barking lure")
    assertEqual(statue.properties.pendingMeatgrinderDraws, 2,
        "questing beast oil should queue two Meatgrinder draws when no WatchManager is present")

    local ungoatOil = inventory.createItemFromTemplate("ungoat_oil")
    local enchantedBlade = inventory.createItem({
        name = "Enchanted Blade",
        size = 1,
        properties = {
            object = true,
            enchanted = true,
            magical = true,
        },
    })
    enchantedBlade.activeEnchantments = {
        {
            id = "flaming_blade",
            active = true,
        },
    }
    actor.inventory:addItem(ungoatOil, inventory.LOCATIONS.HANDS)
    local suppressUse = resolver:resolve({
        actor = actor,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = ungoatOil.id,
        target = enchantedBlade,
        contestedUseItem = false,
    })
    assertTrue(suppressUse.success and enchantedBlade.properties.magicSuppressed,
        "ungoat oil should suppress an object's magic for a watch")
    assertTrue(enchantedBlade.activeEnchantments[1].paused,
        "ungoat oil should pause active object enchantments")

    local lureDeck = {
        cards = {
            { name = "Passing Watch", value = 2 },
            { name = "Random Encounter", value = 16 },
            { name = "Curiosity", value = 9 },
        },
        discarded = {},
        draw = function(self)
            local card = self.cards[1]
            table.remove(self.cards, 1)
            return card
        end,
        discard = function(self, card)
            self.discarded[#self.discarded + 1] = card
        end,
    }
    local manager = watch_manager.createWatchManager({
        eventBus = bus,
        gmDeck = lureDeck,
        trackedObjects = { door, bar, statue, enchantedBlade },
    })
    local watchResult = manager:incrementWatch()
    local lureDetails = watchResult.barkingLureDraws or {}
    assertEqual(#lureDetails, 1,
        "watch passage should resolve the pending questing-beast lure draws")
    assertTrue(lureDetails[1].target == statue,
        "pending questing-beast lure draw detail should keep the lure target")
    assertEqual(lureDetails[1].resolvedDrawCount, 2,
        "pending questing-beast lure should draw twice")
    assertEqual(#lureDetails[1].draws, 2,
        "pending questing-beast lure should report both draws")
    assertEqual(#lureDetails[1].encounters, 1,
        "pending questing-beast lure should surface random encounters drawn to the lure")
    assertTrue(lureDetails[1].draws[1].questingBeastLure and lureDetails[1].draws[1].lureTarget == statue,
        "pending questing-beast lure draws should be annotated with the target")
    assertTrue(statue.properties.pendingMeatgrinderDraws == nil,
        "resolved questing-beast lure draws should clear their pending counter")
    assertEqual(#lureDeck.discarded, 3,
        "watch passage should discard the normal and questing-beast lure Meatgrinder cards")

    local expired = watchResult.propertiesExpired
    assertTrue(#expired >= 2, "watch object-property expiry should report tracked alchemical effects")
    assertTrue(door.adheredTo == nil and bar.adheredTo == nil,
        "watch expiry should clear reciprocal brain spider oil adhesion")
    assertTrue(not door.properties.adhered and not bar.properties.adhered,
        "watch expiry should clear adhered object properties")
    assertTrue(not statue.properties.barkingLure and not statue.properties.questingBeastBark,
        "watch expiry should clear questing beast oil barking properties")
    assertTrue(statue.properties.effectDurations == nil,
        "watch expiry should remove empty object effect-duration tables")
    assertTrue(not enchantedBlade.properties.magicSuppressed and not enchantedBlade.properties.spellsNegated,
        "watch expiry should clear ungoat oil magic suppression")
    assertTrue(not enchantedBlade.activeEnchantments[1].paused and
        enchantedBlade.activeEnchantments[1].resumedAfterSuppression,
        "watch expiry should resume enchantments paused by ungoat oil")
    assertTrue(#propertyEvents >= 2,
        "watch object-property expiry should emit presentation events")
end

function checkJinnOilCityPortalRuntime()
    local bus = events.createEventBus()
    local phaseEvents = {}
    bus:on(events.EVENTS.PHASE_CHANGED, function(payload)
        phaseEvents[#phaseEvents + 1] = payload
    end)

    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
    })
    local actor = base_entity.createEntity({
        id = "pc_jinn_portal_opener",
        name = "Jinn Portal Opener",
        isPC = true,
        cups = 3,
    })
    actor.inventory = inventory.createInventory()
    local floor = inventory.createItem({
        name = "Portal Floor",
        type = "floor",
        properties = { floor = true },
    })
    local oil = inventory.createItemFromTemplate("jinn_oil")
    actor.inventory:addItem(oil, inventory.LOCATIONS.HANDS)
    local opened = resolver:resolve({
        actor = actor,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = oil.id,
        target = floor,
        contestedUseItem = false,
    })
    assertTrue(opened.success and floor.cityPortal and floor.properties.portalOpen,
        "jinn oil should leave an active City portal on the ground")
    assertTrue(not actor.teleportedToCity,
        "opening a jinn oil portal should not force the item user through it")
    local stillOpen = resolver:expireJinnOilCityPortal(floor, { elapsedSeconds = 59 })
    assertTrue(not stillOpen.success and floor.properties.portalOpen,
        "jinn oil portals should remain open before their one-minute duration elapses")

    local traveler = base_entity.createEntity({
        id = "pc_jinn_portal_traveler",
        name = "Jinn Portal Traveler",
        isPC = true,
    })
    local entry = resolver:enterJinnOilCityPortal(traveler, floor, {
        phase = "crawl",
    })
    assertTrue(entry.success and traveler.teleportedToCity and traveler.location == "city",
        "any later creature entering a jinn oil portal should teleport to the City")
    assertEqual(traveler.cityPortalArrival.arrival, "manhole",
        "jinn oil portal entry should preserve the manhole arrival")
    assertTrue(entry.phaseChange and entry.phaseChange.newPhase == "city",
        "later jinn oil portal entry should begin a City Phase")
    assertEqual(#phaseEvents, 1,
        "later jinn oil portal entry should emit a phase-change event")

    floor.properties.portalOpen = false
    floor.cityPortal.active = false
    local lateTraveler = base_entity.createEntity({
        id = "pc_jinn_portal_late",
        name = "Late Portal Traveler",
        isPC = true,
    })
    local rejected = resolver:enterJinnOilCityPortal(lateTraveler, floor)
    assertTrue(not rejected.success and rejected.reason == "city_portal_closed",
        "closed jinn oil portals should reject later entry")
    assertTrue(not lateTraveler.teleportedToCity,
        "closed jinn oil portal entry should not move the actor")

    local expiredFloor = inventory.createItem({
        name = "Expired Portal Floor",
        type = "floor",
        properties = { floor = true },
    })
    local expiredOil = inventory.createItemFromTemplate("jinn_oil")
    actor.inventory:addItem(expiredOil, inventory.LOCATIONS.HANDS)
    local expiredOpen = resolver:resolve({
        actor = actor,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = expiredOil.id,
        target = expiredFloor,
        contestedUseItem = false,
    })
    assertTrue(expiredOpen.success and expiredFloor.properties.portalOpen,
        "second jinn oil portal should open for expiry coverage")
    local expiredTraveler = base_entity.createEntity({
        id = "pc_jinn_portal_expired_late",
        name = "Expired Portal Late Traveler",
        isPC = true,
    })
    local expiredEntry = resolver:enterJinnOilCityPortal(expiredTraveler, expiredFloor, {
        elapsedSeconds = 61,
    })
    assertTrue(not expiredEntry.success and expiredEntry.reason == "city_portal_closed",
        "jinn oil portals should close after about one minute")
    assertTrue(expiredFloor.cityPortal.closed and expiredFloor.properties.portalClosed,
        "expired jinn oil portals should record closed state")
end

function checkMimicPotionObjectSpeechTimerRuntime()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local actor = base_entity.createEntity({
        id = "pc_mimic_timer_user",
        name = "Mimic Timer User",
        isPC = true,
        cups = 3,
    })
    actor.inventory = inventory.createInventory()
    local potion = inventory.createItemFromTemplate("mimic_potion")
    actor.inventory:addItem(potion, inventory.LOCATIONS.HANDS)
    local use = resolver:resolve({
        actor = actor,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = potion.id,
    })
    assertTrue(use.success and actor.objectSpeech and actor.objectSpeech.active,
        "mimic potion should start active object speech")

    local mug = inventory.createItem({
        name = "Talkative Mug",
        size = 1,
        properties = {
            object = true,
            purpose = "hold ale",
        },
    })
    local withinTimer = resolver:askObjectWithMimicPotion(actor, mug, {
        topic = "purpose",
        elapsedRealTimeMinutes = 3,
    })
    assertTrue(withinTimer.success and withinTimer.answerType == "created_purpose",
        "mimic potion should allow object speech through the three-minute timer")

    local expired = resolver:askObjectWithMimicPotion(actor, mug, {
        topic = "purpose",
        elapsedRealTimeMinutes = 4,
    })
    assertTrue(not expired.success and expired.reason == "object_speech_expired",
        "mimic potion object speech should expire after three real-time minutes")
    assertTrue(actor.objectSpeech == nil and not actor.conditions.object_speech and not actor.canTalkToObjects,
        "mimic potion expiry should clear object speech state")

    local secondActor = base_entity.createEntity({
        id = "pc_mimic_beer_user",
        name = "Mimic Beer User",
        isPC = true,
        cups = 3,
    })
    secondActor.inventory = inventory.createInventory()
    local secondPotion = inventory.createItemFromTemplate("mimic_potion")
    secondActor.inventory:addItem(secondPotion, inventory.LOCATIONS.HANDS)
    resolver:resolve({
        actor = secondActor,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = secondPotion.id,
    })
    local extended = resolver:askObjectWithMimicPotion(secondActor, mug, {
        topic = "purpose",
        elapsedRealTimeMinutes = 10,
        gmBeer = true,
    })
    assertTrue(extended.success and extended.gmBeerExtended,
        "GM beer should extend mimic potion object speech past the normal timer")
    assertTrue(secondActor.objectSpeech and secondActor.objectSpeech.gmBeerExtended,
        "GM beer extension should persist on the active object speech record")
end

function checkDevilOilInvisibleFireExtinguishRuntime()
    local resolver = action_resolver.createActionResolver({
