    local sword = inventory.createItem({
        name = "Invisible Fire Sword",
        size = 1,
        durability = 2,
        weaponType = "sword",
        properties = { material = "metal" },
    })
    actor.inventory:addItem(oil, inventory.LOCATIONS.HANDS)
