    assertTrue(hasValue(incorporealBombUse.effects, "incorporeal_affected"),
        "brain spider bomb should report its incorporeal exception")
    assertTrue(incorporealTarget.alchemyAffectedIncorporeal ~= nil,
        "brain spider bomb should audit the incorporeal alchemy hit")
    assertTrue(not thrower.inventory:findItem(incorporealBomb.id),
        "incorporeal brain spider bomb should be consumed")

    local speaker = base_entity.createEntity({
        id = "pc_brain_spider_potion_speaker",
        name = "Brain Spider Potion Speaker",
        isPC = true,
        wands = 3,
    })
    speaker.malediction = {
        active = true,
        curse = {
            flags = {
                languageLocked = "tylwyth",
                speaksGibberishToNonTylwyth = true,
            },
        },
    }
    speaker.inventory = inventory.createInventory()
    local brainPotion = inventory.createItemFromTemplate("brain_spider_potion")
    speaker.inventory:addItem(brainPotion, inventory.LOCATIONS.HANDS)
    local brainPotionUse = resolver:resolve({
        actor = speaker,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = brainPotion.id,
    })
    assertTrue(brainPotionUse.success, "brain spider potion should be usable on self without contest")
    assertTrue(speaker.conditions.universal_speech and speaker.conditions.psionic_voice,
        "brain spider potion should make speech psionically understandable")
    assertEqual(speaker.conditionDurations.universal_speech.duration, "watch",
        "brain spider potion speech should last for a watch")

    local listener = base_entity.createEntity({
        id = "npc_brain_spider_potion_listener",
        name = "No Shared Language Listener",
        isPC = false,
        baseMorale = 8,
        health = 2,
        defense = 0,
        disposition = "distaste",
        dispositionSeverity = 2,
    })
    local psionicBanter = resolver:resolve({
        actor = speaker,
        target = listener,
        card = { name = "Eight of Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.BANTER,
        banterIntent = "frighten",
    })
    assertTrue(psionicBanter.success,
        "brain spider potion should bypass language-locked gibberish during Banter")
    assertTrue(hasValue(psionicBanter.effects, "psionic_voice_translation"),
        "brain spider potion language bypass should be auditable")
    assertTrue(not hasValue(psionicBanter.effects, "language_locked_gibberish"),
        "brain spider potion should prevent missing-language social failure")
end

function checkFaceRatAlchemyRuntime()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local drinker = base_entity.createEntity({
        id = "pc_face_rat_potion_drinker",
        name = "Face Rat Potion Drinker",
        isPC = true,
    })
    drinker.inventory = inventory.createInventory()
    local firstSeen = base_entity.createEntity({
        id = "npc_face_rat_first_seen",
        name = "First Seen Guard",
        isPC = false,
        health = 2,
        defense = 0,
    })
    local illusionSighted = base_entity.createEntity({
        id = "npc_illusion_sighted",
        name = "Illusion-Sighted Witness",
        isPC = false,
        health = 2,
        defense = 0,
    })
    illusionSighted.conditions.cannot_see_illusions = true

    local facePotion = inventory.createItemFromTemplate("face_rat_potion")
    drinker.inventory:addItem(facePotion, inventory.LOCATIONS.HANDS)
    local facePotionUse = resolver:resolve({
        actor = drinker,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = facePotion.id,
        firstSeenCreature = firstSeen,
        observers = { firstSeen, illusionSighted },
    })
    assertTrue(facePotionUse.success, "face rat potion should resolve with the first seen creature")
    assertTrue(drinker.faceRatIllusion and drinker.faceRatIllusion.active,
        "face rat potion should create a live duplicate illusion")
    assertEqual(drinker.faceRatIllusion.duplicateOf, firstSeen,
        "face rat potion should duplicate the first creature seen after drinking")
    assertTrue(drinker.faceRatIllusion.visualOnly and drinker.faceRatIllusion.hologram,
        "face rat potion duplicate should be purely visual like a hologram")
    assertTrue(drinker.conditions.illusion_duplicate_active and not drinker.conditions.illusion_duplicate_pending,
        "face rat potion should replace the pending duplicate marker with an active duplicate")
    assertEqual(#drinker.faceRatIllusion.seeThroughObservers, 1,
        "creatures not affected by illusions should see through the face rat disguise")
    assertTrue(hasValue(facePotionUse.effects, "illusion_seen_through"),
        "face rat potion should report observers who see through the illusion")

    local faceWatch = watch_manager.createWatchManager({
        eventBus = events.createEventBus(),
        guild = { drinker },
    })
    faceWatch:incrementWatch()
    assertTrue(drinker.faceRatIllusion == nil and drinker.apparentDuplicateOf == nil,
        "watch expiration should clear face rat duplicate state")
    assertTrue(not drinker.conditions.face_rat_duplicate and not drinker.conditions.illusion_duplicate_active,
        "watch expiration should clear active face rat illusion conditions")
end

function checkAlchemicalPotionDamageImmunity()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local devilDrinker = base_entity.createEntity({
        id = "npc_devil_potion_fireproof",
        name = "Devil Potion Fireproof",
        isPC = false,
        health = 2,
        defense = 0,
