function checkSlimeOilAcidHoleRuntime()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local actor = base_entity.createEntity({
        id = "pc_slime_oil_hole_user",
        name = "Slime Oil Hole User",
        isPC = true,
        cups = 1,
    })
    actor.inventory = inventory.createInventory()

    local slimeOil = inventory.createItemFromTemplate("slime_oil")
    local stoneFloor = inventory.createItem({
        name = "Stone Floor",
        type = "floor",
        size = 0,
        properties = { material = "stone", floor = true },
    })
    actor.inventory:addItem(slimeOil, inventory.LOCATIONS.HANDS)
    local floorUse = resolver:resolve({
        actor = actor,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = slimeOil.id,
        target = stoneFloor,
    })
    assertTrue(floorUse.success and stoneFloor.destroyed,
        "slime oil should dissolve non-magical floor material")
    assertTrue(stoneFloor.acidHole and stoneFloor.acidHole.diameterFeet == 5,
        "slime oil should create the canonical five-foot acid hole")
    assertTrue(stoneFloor.floorEatenThrough and stoneFloor.properties.floorEatenThrough,
        "slime oil should eat through floors")
    assertTrue(hasValue(floorUse.effects, "acid_hole") and hasValue(floorUse.effects, "floor_eaten_through"),
        "slime oil floor holes should be auditable")
    assertTrue(not actor.inventory:findItem(slimeOil.id),
        "slime oil should be consumed after dissolving a floor")

    local glassOil = inventory.createItemFromTemplate("slime_oil")
    local glassPane = inventory.createItem({
        name = "Glass Pane",
        size = 1,
        properties = { material = "glass" },
    })
    actor.inventory:addItem(glassOil, inventory.LOCATIONS.HANDS)
    local glassUse = resolver:resolve({
        actor = actor,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = glassOil.id,
        target = glassPane,
    })
    assertTrue(glassUse.success, "slime oil should still be spent on glass")
    assertTrue(not glassPane.destroyed and not glassPane.acidHole,
        "slime oil should not dissolve glass or create a hole through it")
    assertTrue(hasValue(glassUse.effects, "material_resisted"),
        "slime oil glass resistance should be auditable")
    assertTrue(not actor.inventory:findItem(glassOil.id),
        "glass-resisted slime oil should still be consumed")
end

