function checkSlimePotionSqueezeRuntime()
    local bus = events.createEventBus()
    local zoneRegistry = zone_system.createZoneRegistry({ eventBus = bus })
    local zones = buildLinearZones()
    zoneRegistry:setRoomZones(zones)

    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
        zoneSystem = zoneRegistry,
    })

    local actor = base_entity.createEntity({
        id = "pc_slime_potion_squeezer",
        name = "Slime Potion Squeezer",
        isPC = true,
        zone = "A",
    })
    actor.inventory = inventory.createInventory()
    zoneRegistry:placeEntity(actor.id, actor.zone)

    local blockedMove = resolver:resolve({
        actor = actor,
        card = { name = "Move", value = 5, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MOVE,
        destinationZone = "B",
        traversalMode = "hand_sized_gap",
        handSizedGap = true,
        challengeController = { zones = zones },
    })
    assertTrue(not blockedMove.success, "hand-sized gap movement should require slime potion shaping")
    assertEqual(actor.zone, "A", "blocked gap movement should not move the actor")
    assertTrue(hasValue(blockedMove.effects, "slime_squeeze_required"),
        "blocked gap movement should report the missing slime condition")

    local slimePotion = inventory.createItemFromTemplate("slime_potion")
    actor.inventory:addItem(slimePotion, inventory.LOCATIONS.HANDS)
    local potionUse = resolver:resolve({
        actor = actor,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = slimePotion.id,
    })
    assertTrue(potionUse.success and actor.conditions.squeeze_through_gaps,
        "slime potion should grant the squeeze-through-gaps condition")

    local squeezeMove = resolver:resolve({
        actor = actor,
        card = { name = "Move", value = 5, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MOVE,
        destinationZone = "B",
        traversalMode = "hand_sized_gap",
        handSizedGap = true,
        challengeController = { zones = zones },
    })
    assertTrue(squeezeMove.success, "slime potion should allow hand-sized gap movement")
    assertEqual(actor.zone, "B", "slime squeeze movement should update actor zone")
    assertTrue(squeezeMove.slimeSqueezeTraversal and squeezeMove.slimeSqueezeTraversal.handSizedGap,
        "slime squeeze movement should record hand-sized gap traversal metadata")
    assertTrue(hasValue(squeezeMove.effects, "slime_squeeze_traversal") and
        hasValue(squeezeMove.effects, "hand_sized_gap_passed"),
        "slime squeeze movement should report auditable traversal effects")
end

