    assertTrue(mistMove.success, "vampire mist should move through keyholes")
    assertEqual(actor.zone, "B", "vampire mist keyhole movement should update actor zone")
    assertTrue(mistMove.vampireMistTraversal and mistMove.vampireMistTraversal.mode == "keyhole",
        "vampire mist movement should record keyhole traversal metadata")
    assertTrue(hasValue(mistMove.effects, "vampire_mist_crack_traversal") and
        hasValue(mistMove.effects, "mist_pass_cracks"),
        "vampire mist crack movement should report auditable traversal effects")

    local hazardEffects = { "hazard" }
    local hazardDamage = resolver:applyDamage(actor, 1, hazardEffects, nil, nil, nil, {
        source = "hazard",
    })
    assertTrue(hazardDamage and hazardDamage.immune,
        "vampire potion mist form should block ordinary environmental hazards")
    assertTrue(hasValue(hazardEffects, "vampire_mist_form_immune"),
        "vampire potion hazard immunity should be auditable")
end

function checkOgreOilSolventRuntime()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local actor = base_entity.createEntity({
        id = "pc_ogre_oil_solvent_user",
        name = "Ogre Oil Solvent User",
        isPC = true,
        cups = 1,
    })
    actor.inventory = inventory.createInventory()

    local brainOil = inventory.createItemFromTemplate("brain_spider_oil")
    local woodenDoor = inventory.createItem({
        name = "Glued Wooden Door",
        size = 2,
        durability = 2,
        properties = { material = "wood" },
    })
    local woodenFrame = inventory.createItem({
        name = "Glued Wooden Frame",
        size = 2,
        durability = 2,
        properties = { material = "wood" },
    })
    actor.inventory:addItem(brainOil, inventory.LOCATIONS.HANDS)
    local glueUse = resolver:resolve({
        actor = actor,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = brainOil.id,
        target = woodenDoor,
        secondaryTarget = woodenFrame,
    })
    assertTrue(glueUse.success and woodenDoor.adheredTo == woodenFrame and woodenFrame.adheredTo == woodenDoor,
        "brain spider oil fixture should create a reciprocal adhesion bond")

    local solventOil = inventory.createItemFromTemplate("ogre_oil")
    actor.inventory:addItem(solventOil, inventory.LOCATIONS.HANDS)
    local solventUse = resolver:resolve({
        actor = actor,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = solventOil.id,
        target = woodenDoor,
    })
    assertTrue(solventUse.success, "ogre oil should resolve on glued wood")
    assertTrue(not woodenDoor.adheredTo and not woodenFrame.adheredTo and
        not woodenDoor.properties.adhered and not woodenFrame.properties.adhered,
        "ogre oil should dissolve reciprocal adhesive bonds")
    assertTrue(woodenDoor.properties.material == "paper" and
        woodenDoor.ogreSolventTransformation.result == "wood_to_paper",
        "ogre oil should turn wood into paper")
    assertTrue(hasValue(solventUse.effects, "ogre_solvent_adhesive_broken") and
        hasValue(solventUse.effects, "wood_to_paper"),
        "ogre oil adhesive and wood transformations should be auditable")
    assertTrue(not actor.inventory:findItem(solventOil.id),
        "ogre oil should be consumed after dissolving adhesive")

    local stoneOil = inventory.createItemFromTemplate("ogre_oil")
    local stoneBlock = inventory.createItem({
        name = "Stone Block",
        size = 3,
        durability = 3,
        properties = { material = "stone" },
    })
    actor.inventory:addItem(stoneOil, inventory.LOCATIONS.HANDS)
    local stoneUse = resolver:resolve({
        actor = actor,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = stoneOil.id,
        target = stoneBlock,
    })
    assertTrue(stoneUse.success and stoneBlock.properties.material == "mud",
        "ogre oil should turn stone into mud")
    assertTrue(hasValue(stoneUse.effects, "stone_to_mud"),
        "ogre oil stone transformation should be auditable")

    local metalOil = inventory.createItemFromTemplate("ogre_oil")
    local ironGate = inventory.createItem({
        name = "Iron Gate",
        size = 3,
        durability = 3,
        properties = { material = "iron" },
    })
    actor.inventory:addItem(metalOil, inventory.LOCATIONS.HANDS)
    local metalUse = resolver:resolve({
        actor = actor,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = metalOil.id,
        target = ironGate,
    })
    assertTrue(metalUse.success and ironGate.properties.materialState == "bendable",
        "ogre oil should make metal bendable")
    assertTrue(hasValue(metalUse.effects, "metal_bendable"),
        "ogre oil metal transformation should be auditable")
end

function checkTitanPotionGrowthTestOfFateRuntime()
    local bus = events.createEventBus()
    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
    })

    local actor = base_entity.createEntity({
        id = "pc_titan_potion_growth_tests",
        name = "Titan Potion Growth Tests",
        isPC = true,
        pentacles = 0,
    })
    actor.inventory = inventory.createInventory()
    local titanPotion = inventory.createItemFromTemplate("titan_potion")
    actor.inventory:addItem(titanPotion, inventory.LOCATIONS.HANDS)
    local potionUse = resolver:resolve({
        actor = actor,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = titanPotion.id,
    })
    assertTrue(potionUse.success and actor.conditions.titan_growth and actor.changeSize.testOfFateOnly,
        "titan potion should grant Growth limited to Tests of Fate")

    local testRequest = nil
    bus:on(events.EVENTS.REQUEST_TEST_OF_FATE, function(data)
        testRequest = data
    end)

    local strengthTest = resolver:resolve({
        actor = actor,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.TEST_FATE,
        testAttribute = "pentacles",
        sizeContext = "strength",
        challengeController = {
            isActive = function()
                return true
            end,
        },
    })
    assertTrue(strengthTest.pendingTestOfFate,
        "titan potion Growth should still route advantageous checks through Test Fate")
    assertTrue(testRequest and testRequest.favor == true,
        "titan potion Growth should favor Tests of Fate where size helps")
    assertTrue(hasValue(strengthTest.effects, "change_size_action_favor"),
        "titan potion favorable size tests should be auditable")

    testRequest = nil
    local squeezeTest = resolver:resolve({
        actor = actor,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.TEST_FATE,
        testAttribute = "pentacles",
        sizeContext = "squeeze",
        challengeController = {
            isActive = function()
                return true
            end,
        },
    })
    assertTrue(squeezeTest.pendingTestOfFate,
        "titan potion Growth should still route disadvantageous checks through Test Fate")
    assertTrue(testRequest and testRequest.favor == false,
        "titan potion Growth should disfavor Tests of Fate where size hurts")
    assertTrue(hasValue(squeezeTest.effects, "change_size_action_disfavor"),
        "titan potion unfavorable size tests should be auditable")

    local target = base_entity.createEntity({
        id = "npc_titan_potion_challenge_action",
        name = "Titan Potion Challenge Action",
        isPC = false,
        health = 2,
        defense = 0,
        conditions = {},
    })
    local roughhouse = resolver:resolve({
        actor = actor,
        target = target,
        card = { name = "Pentacles", value = 7, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "trip",
        targetInitiative = 9,
    })
    assertTrue(not hasValue(roughhouse.effects, "change_size_action_favor") and
        not hasValue(roughhouse.effects, "change_size_action_disfavor"),
        "titan potion Growth should not modify Challenge Actions")
end

function checkTitanOilStructuralStressRuntime()
    local bus = events.createEventBus()
    local environment = environment_manager.createEnvironmentManager({ eventBus = bus })
    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
        environmentManager = environment,
    })

    local actor = base_entity.createEntity({
        id = "pc_titan_oil_structural_user",
        name = "Titan Oil Structural User",
        isPC = true,
    })
    actor.inventory = inventory.createInventory()

    local titanOil = inventory.createItemFromTemplate("titan_oil")
    local statue = inventory.createItem({
        id = "small_statue_titan_oil",
        name = "Small Statue",
        size = 2,
        durability = 2,
        properties = {},
    })
    local balcony = {
        id = "rotting_balcony",
        name = "Rotting Balcony",
        properties = {
            support = true,
        },
    }
    actor.inventory:addItem(titanOil, inventory.LOCATIONS.HANDS)
    local oilUse = resolver:resolve({
        actor = actor,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = titanOil.id,
        target = statue,
        supportingSurface = balcony,
        structuralStressResult = "cracked",
    })
    assertTrue(oilUse.success, "titan oil should resolve on objects resting on vulnerable supports")
    assertEqual(statue.titanOilWeight.multiplier, 10,
        "titan oil should record the object as ten times as heavy")
    assertTrue(statue.titanOilWeight.structurallyIntact and not statue.structureDamaged,
        "titan oil should preserve the object's own structure")
    assertTrue(balcony.properties.titanOilStructuralStress and balcony.properties.structuralStress,
        "titan oil should place the structural stress on the surrounding support")
    assertEqual(balcony.properties.structuralStressResult, "cracked",
        "titan oil should preserve adjudicated environmental stress results")
    assertEqual(#environment.environmentShifts, 1,
        "titan oil structural stress should persist an environment shift")
    assertEqual(environment.environmentShifts[1].support, balcony,
        "titan oil environment shift should reference the stressed support")
    assertTrue(hasValue(oilUse.effects, "titan_oil_environment_stress") and
        hasValue(oilUse.effects, "titan_oil_support_stressed"),
        "titan oil structural stress should be auditable")
end

function checkImpOilSlipperyPuddleRuntime()
    local bus = events.createEventBus()
    local zoneRegistry = zone_system.createZoneRegistry({ eventBus = bus })
    local zones = buildLinearZones()
    zoneRegistry:setRoomZones(zones)
    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
        zoneSystem = zoneRegistry,
    })

    local actor = base_entity.createEntity({
        id = "pc_imp_oil_puddle_user",
        name = "Imp Oil Puddle User",
        isPC = true,
        zone = "A",
    })
    actor.inventory = inventory.createInventory()
    zoneRegistry:placeEntity(actor.id, actor.zone)

    local impOil = inventory.createItemFromTemplate("imp_oil")
    actor.inventory:addItem(impOil, inventory.LOCATIONS.HANDS)
    local targetZone = zoneRegistry:getZone("B")
    local oilUse = resolver:resolve({
        actor = actor,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = impOil.id,
        target = targetZone,
        pouredOut = true,
    })
    assertTrue(oilUse.success, "imp oil should pour out onto a zone")
    assertTrue(targetZone.properties.slipperyPuddle and targetZone.slipperyPuddle.diameterFeet == 10,
        "imp oil should record a ten-foot slippery puddle")
    assertTrue(#(targetZone.hazards or {}) == 1 and targetZone.hazards[1].type == "slippery_puddle",
        "imp oil puddles should register as movement hazards")

    local slipMove = resolver:resolve({
        actor = actor,
        card = { name = "Move", value = 5, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MOVE,
        destinationZone = "B",
        slipperyPuddleTestResult = { success = false },
    })
    assertTrue(slipMove.success, "walking into an imp oil puddle should still enter the zone")
    assertEqual(actor.zone, "B", "imp oil slips should happen after zone entry")
    assertTrue(actor.conditions.prone, "failed imp oil puddle traversal should leave the mover prone")
    assertTrue(slipMove.frictionlessPuddle and slipMove.frictionlessPuddle.slipped,
        "imp oil puddle movement should record the slip")
    assertTrue(hasValue(slipMove.effects, "slippery_puddle_entered") and
        hasValue(slipMove.effects, "slippery_puddle_slip"),
        "imp oil puddle slip should be auditable")

    local cautious = base_entity.createEntity({
        id = "pc_imp_oil_cautious_walker",
        name = "Imp Oil Cautious Walker",
        isPC = true,
        zone = "A",
    })
    cautious.inventory = inventory.createInventory()
    zoneRegistry:placeEntity(cautious.id, cautious.zone)
    local pendingMove = resolver:resolve({
        actor = cautious,
        card = { name = "Move", value = 5, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MOVE,
        destinationZone = "B",
    })
    assertTrue(pendingMove.success and pendingMove.frictionlessPuddle.requiresTest,
        "imp oil puddles should request adjudication when no traversal result is supplied")
    assertTrue(not cautious.conditions.prone and hasValue(pendingMove.effects, "slippery_puddle_test_required"),
        "pending imp oil puddle traversal should not apply a slip before adjudication")
end

