function checkBeltHotbarPotionUse()
    local belt_hotbar = require('ui.belt_hotbar')
    local bus = events.createEventBus()
    local consumedEvent = nil
    bus:on("potion_consumed", function(data)
        consumedEvent = data
    end)

    local pc = base_entity.createEntity({
        id = "pc_belt_hotbar_potion",
        name = "Belt Potion User",
        isPC = true,
    })
    pc.inventory = inventory.createInventory()
    pc.conditions.injured = true

    local potion = inventory.createItemFromTemplate("healing_potion")
    pc.inventory:addItem(potion, inventory.LOCATIONS.BELT)

    local hotbar = belt_hotbar.createBeltHotbar({
        eventBus = bus,
        guild = { pc },
    })

    local ok = hotbar:useItem(1)
    assertTrue(ok, "belt hotbar should route potion use through the item resolver")
    assertTrue(not pc.conditions.injured, "belt hotbar potion should apply healing effects")
    assertTrue(not pc.inventory:findItem(potion.id), "successful belt hotbar potion use should consume the potion")
    assertTrue(consumedEvent and consumedEvent.consumed,
        "belt hotbar potion event should report resolver-backed consumption")

    consumedEvent = nil
    pc.conditions.injured = true
    pc.conditions.stressed = true
    local blockedPotion = inventory.createItemFromTemplate("healing_potion")
    pc.inventory:addItem(blockedPotion, inventory.LOCATIONS.BELT)
    ok = hotbar:useItem(1)
    assertTrue(not ok, "belt hotbar should report blocked potion effects")
    assertTrue(pc.inventory:findItem(blockedPotion.id) ~= nil,
        "blocked belt hotbar potion use should not remove the potion")
    assertTrue(consumedEvent and consumedEvent.consumed == false,
        "belt hotbar potion event should report when nothing was consumed")
end

function checkWolfsbaneWardItemUse()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local wardActor = base_entity.createEntity({
        id = "pc_wolfsbane_ward",
        name = "Wolfsbane Warder",
        isPC = true,
        cups = 0,
        wands = 3,
    })
    wardActor.inventory = inventory.createInventory()
    local wolfsbane = inventory.createItemFromTemplate("wolfsbane")
    wardActor.inventory:addItem(wolfsbane, inventory.LOCATIONS.HANDS)

    local winterWolf = entity_factory.createEntity("winter_wolf", { name = "Wolfsbane Target" })
    winterWolf.zone = "near"
    local wolfsbaneWard = resolver:resolve({
        actor = wardActor,
        target = winterWolf,
        card = { name = "Eight of Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = wolfsbane.id,
        targetInitiative = 10,
        destinationZone = "far",
    })
    assertTrue(wolfsbaneWard.success, "brandished wolfsbane should use Wands to affect wolves")
    assertEqual(wolfsbaneWard.itemUseAttribute, "wands", "wolfsbane ward should be a Wands item action")
    assertEqual(winterWolf.zone, "far", "successful wolfsbane ward should displace the affected wolf")
    assertTrue(wardActor.inventory:findItem(wolfsbane.id), "wolfsbane should not be consumed by brandishing")

    local undeadUnaffected = entity_factory.createEntity("zombie", { name = "Wolfsbane Zombie" })
    undeadUnaffected.zone = "near"
    local wolfsbaneNoEffect = resolver:resolve({
        actor = wardActor,
        target = undeadUnaffected,
