end

function checkTenFootPoleHazardProbe()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local actor = base_entity.createEntity({
        id = "pc_pole_probe",
        name = "Pole Probe",
        isPC = true,
        cups = 2,
    })
    actor.inventory = inventory.createInventory()
    local pole = inventory.createItemFromTemplate("pole_10ft")
    local poleAdded = actor.inventory:addItem(pole, inventory.LOCATIONS.BELT)
    assertTrue(poleAdded, "oversized 10-foot pole should be carried in belt slots")

    local trappedFloor = {
        id = "needle_floor",
        name = "Needle Floor",
        type = "hazard",
        properties = {
            hiddenTrap = true,
        },
        trap = {
            damage = 1,
            hidden = true,
        },
        hazards = {
            {
                type = "pit",
                hidden = true,
            },
        },
    }
    local probe = resolver:resolve({
        actor = actor,
        target = trappedFloor,
        card = { name = "Five of Cups", value = 5, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = pole.id,
    })
    assertTrue(probe.success, "10-foot pole should probe trap and hazard targets")
    assertTrue(hasValue(probe.effects, "hazard_probed"), "pole probing should report hazard probing")
    assertTrue(hasValue(probe.effects, "trap_detected"), "pole probing should mark traps detected")
    assertTrue(hasValue(probe.effects, "hazard_detected"), "pole probing should mark hazards detected")
    assertTrue(trappedFloor.probedByPole and trappedFloor.properties.probedByPole,
        "pole probing should mark the target as safely probed")
    assertTrue(trappedFloor.trap.detected and trappedFloor.trap.probedByPole,
        "pole probing should mark embedded traps detected")
    assertTrue(trappedFloor.hazards[1].detected and trappedFloor.hazards[1].probedByPole,
        "pole probing should mark embedded hazards detected")
    assertEqual(probe.itemEffect.reach, "10ft", "pole probing should preserve the ten-foot reach")
    assertTrue(actor.inventory:findItem(pole.id), "10-foot pole should not be consumed by probing")

    local plainFloor = {
        id = "plain_floor",
        name = "Plain Floor",
        type = "floor",
        properties = {},
    }
    local noEffect = resolver:resolve({
        actor = actor,
        target = plainFloor,
        card = { name = "Six of Cups", value = 6, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = pole.id,
    })
    assertTrue(not noEffect.success, "10-foot pole should report no effect without a trap or hazard target")
    assertTrue(hasValue(noEffect.effects, "pole_probe_no_effect"),
        "failed pole probing should explain the missing trap or hazard")
    assertTrue(actor.inventory:findItem(pole.id), "failed pole probing should not consume the pole")
end

function checkMirrorGazeReflectionItemUse()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local mirrorBearer = base_entity.createEntity({
        id = "pc_mirror_bearer",
        name = "Mirror Bearer",
        isPC = true,
        cups = 4,
    })
    mirrorBearer.inventory = inventory.createInventory()
    local mirror = inventory.createItemFromTemplate("mirror")
    mirrorBearer.inventory:addItem(mirror, inventory.LOCATIONS.HANDS)

    local vampire = entity_factory.createEntity("vampire")
    vampire.id = "npc_mirror_vampire"
    local prepared = resolver:resolve({
        actor = mirrorBearer,
        target = vampire,
        card = { name = "Ten of Cups", value = 10, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = mirror.id,
        targetInitiative = 8,
    })
    assertTrue(prepared.success, "mirror should prepare reflection against a monster dread gaze")
    assertTrue(hasValue(prepared.effects, "mirror_gaze_reflection_prepared"),
        "mirror reflection should report prepared gaze reflection")
    assertTrue(vampire.mirrorGazeReflection and vampire.conditions.mirror_gaze_reflected,
        "mirror reflection should mark the monster's next gaze as reflected")
    assertTrue(mirrorBearer.inventory:findItem(mirror.id), "mirror should not be consumed by reflecting a gaze")

    local mesmerized = base_entity.createEntity({
        id = "pc_mirror_mesmerized",
        name = "Mirror Mesmerized",
        isPC = true,
        swords = 4,
    })
    local reflectedMesmerize = resolver:resolve({
        actor = vampire,
        target = mesmerized,
        type = action_resolver.ACTION_TYPES.MELEE,
        card = { name = "Seven of Swords", value = 7, suit = constants.SUITS.SWORDS },
        greaterDoom = vampire.greaterDooms[2],
        targetInitiative = 6,
        inChallenge = true,
        allEntities = { vampire, mesmerized },
    })
    assertTrue(reflectedMesmerize.success, "reflected Vampire Mesmerize should still ride on a landed Attack")
    assertTrue(hasValue(reflectedMesmerize.effects, "vampire_mesmerize_mirror_reflected"),
        "Vampire Mesmerize should report mirror reflection")
    assertTrue(not mesmerized.conditions.staggered and not mesmerized.conditions.controlled,
        "reflected Mesmerize should not Wound or Control the mirror-defended target")
    assertTrue(vampire.conditions.controlled and vampire.conditions.mesmerized,
        "reflected Mesmerize should turn the vampire's gaze back on itself")
    assertTrue(not vampire.mirrorGazeReflection and vampire.lastMirrorGazeReflection,
        "mirror reflection should be consumed by the next gaze")

    local cockatrice = entity_factory.createEntity("cockatrice")
    local cockatriceReflection = resolver:resolve({
        actor = mirrorBearer,
        target = cockatrice,
        card = { name = "Nine of Cups", value = 9, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = mirror.id,
        targetInitiative = 0,
    })
    assertTrue(not cockatriceReflection.success, "cockatrice gaze should remain immune to mirror reflection")
    assertTrue(hasValue(cockatriceReflection.effects, "mirror_gaze_not_reflected"),
        "cockatrice mirror immunity should be reported")
    assertTrue(not cockatrice.mirrorGazeReflection,
        "cockatrice should not receive a pending mirror reflection state")
end

function checkFirewoodCampfireItemUse()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local actor = base_entity.createEntity({
