function checkChalkAndChainItemUse()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local actor = base_entity.createEntity({
        id = "pc_chalk_chain_user",
        name = "Chalk and Chain User",
        isPC = true,
        cups = 2,
    })
    actor.inventory = inventory.createInventory()

    local chalk = inventory.createItemFromTemplate("chalk")
    actor.inventory:addItem(chalk, inventory.LOCATIONS.HANDS)
    local trappedPassage = {
        id = "chalk_trapped_passage",
        name = "Trapped Passage",
        type = "passage",
        properties = {
            hiddenTrap = true,
        },
        trap = {
            hidden = true,
        },
    }
    local marked = resolver:resolve({
        actor = actor,
        target = trappedPassage,
        card = { name = "Three of Cups", value = 3, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = chalk.id,
        intent = "trap_warning",
        warning = "pit",
    })
    assertTrue(marked.success, "chalk should mark surfaces, routes, and hazard warnings")
    assertTrue(hasValue(marked.effects, "chalk_marked"), "chalk use should report a surface mark")
    assertTrue(trappedPassage.chalkMarked and trappedPassage.trapWarningMarked,
        "chalk should mark trap-warning state on the target")
    assertEqual(chalk.quantity, 4, "marking with chalk should consume one chalk from the stack")
    assertTrue(not chalk.destroyed, "a remaining chalk stack should not be marked destroyed")

    local chain = inventory.createItemFromTemplate("chain_10ft")
    actor.inventory:addItem(chain, inventory.LOCATIONS.HANDS)
    local fallenGate = {
        id = "fallen_iron_gate",
        name = "Fallen Iron Gate",
        type = "gate",
        properties = {
            movable = true,
        },
    }
    local secured = resolver:resolve({
        actor = actor,
        target = fallenGate,
        card = { name = "Four of Cups", value = 4, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = chain.id,
    })
    assertTrue(secured.success, "10-foot chain should secure haulable objects")
    assertTrue(fallenGate.chainSecured and fallenGate.haulableByChain and fallenGate.properties.chainSecured,
        "chain should mark objects secured for hauling")
    assertTrue(chain.inUseAsBinding and chain.bindingTargetId == fallenGate.id,
        "chain should be committed while securing an object")
    assertTrue(actor.inventory:findItem(chain.id), "chain should not be consumed by securing a target")

    local secondGate = {
        id = "second_gate",
        name = "Second Gate",
        type = "gate",
        properties = {
            movable = true,
        },
    }
    local reused = resolver:resolve({
        actor = actor,
        target = secondGate,
        card = { name = "Five of Cups", value = 5, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = chain.id,
    })
    assertTrue(not reused.success, "chain already securing one target should not secure another")
    assertTrue(not secondGate.chainSecured, "failed chain reuse should leave the second object unsecured")

    local binder = base_entity.createEntity({
        id = "pc_chain_binder",
        name = "Chain Binder",
        isPC = true,
        cups = 2,
    })
    binder.inventory = inventory.createInventory()
    local spareChain = inventory.createItemFromTemplate("chain_10ft")
    binder.inventory:addItem(spareChain, inventory.LOCATIONS.HANDS)
    local captive = base_entity.createEntity({
        id = "npc_chain_captive",
        name = "Chain Captive",
        isPC = false,
        health = 1,
        defense = 0,
    })
    captive.kith = true
    local bound = resolver:resolve({
        actor = binder,
        target = captive,
        card = { name = "Nine of Cups", value = 9, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = spareChain.id,
        targetInitiative = 4,
    })
    assertTrue(bound.success, "chain should bind a subdued or beaten person target")
    assertTrue(captive.conditions.restrained and captive.conditions.chain_bound and captive.conditions.rooted,
        "chain should mark bound people restrained, chain-bound, and rooted")

    local activeTarget = {
        id = "active_unbeaten_target",
        name = "Active Unbeaten Target",
        conditions = {},
        kith = true,
    }
    local failedBinder = base_entity.createEntity({
        id = "pc_failed_chain_binder",
        name = "Failed Chain Binder",
        isPC = true,
        cups = 2,
    })
    failedBinder.inventory = inventory.createInventory()
    local anotherChain = inventory.createItemFromTemplate("chain_10ft")
    failedBinder.inventory:addItem(anotherChain, inventory.LOCATIONS.HANDS)
    local failedBind = resolver:resolve({
        actor = failedBinder,
        target = activeTarget,
        card = { name = "Six of Cups", value = 6, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = anotherChain.id,
    })
    assertTrue(not failedBind.success, "chain should not bind an active target without a won contest")
    assertTrue(not activeTarget.conditions.chain_bound, "failed chain binding should not mark the target")
end

