function checkAttackLikeUseItemRules()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local blindThrower = base_entity.createEntity({
        id = "pc_blind_item_thrower",
        name = "Blind Target Item Thrower",
        isPC = true,
        cups = 0,
    })
    blindThrower.inventory = inventory.createInventory()
    local blindBomb = inventory.createItemFromTemplate("brain_spider_bomb")
    blindThrower.inventory:addItem(blindBomb, inventory.LOCATIONS.HANDS)
    local blindTarget = base_entity.createEntity({
        id = "npc_blind_item_target",
        name = "Blind Item Target",
        isPC = false,
        health = 2,
        defense = 0,
    })
    blindTarget.conditions.blind = true
    blindTarget.inventory = inventory.createInventory()
    blindTarget.inventory:addItem(inventory.createItem({ name = "Guard Sword", weaponType = "sword" }),
        inventory.LOCATIONS.HANDS)
    local blindBombUse = resolver:resolve({
        actor = blindThrower,
        target = blindTarget,
        card = { name = "Six of Cups", value = 6, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = blindBomb.id,
        targetInitiative = 8,
    })
    assertTrue(blindBombUse.success, "Attack-like Use Item should gain favor against Blind targets")
    assertTrue(hasValue(blindBombUse.effects, "blind_target_favor"),
        "Attack-like Use Item should report Blind target favor")
    assertTrue(blindTarget.conditions.rooted, "favored bomb should apply its condition on hit")

    local shroudThrower = base_entity.createEntity({
        id = "pc_shrouded_item_thrower",
        name = "Shrouded Target Item Thrower",
        isPC = true,
        cups = 4,
    })
    shroudThrower.inventory = inventory.createInventory()
    local shroudedBomb = inventory.createItemFromTemplate("brain_spider_bomb")
    shroudThrower.inventory:addItem(shroudedBomb, inventory.LOCATIONS.HANDS)
    local shroudedTarget = base_entity.createEntity({
        id = "npc_shrouded_item_target",
        name = "Shrouded Item Target",
        isPC = false,
        health = 2,
        defense = 0,
    })
    shroudedTarget.conditions.shrouded = true
    local shroudedBombUse = resolver:resolve({
        actor = shroudThrower,
        target = shroudedTarget,
        card = { name = "Queen of Cups", value = 13, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = shroudedBomb.id,
        targetInitiative = 1,
    })
    assertTrue(not shroudedBombUse.success,
        "Attack-like Use Item should not deliberately target a still Shrouded creature")
    assertTrue(hasValue(shroudedBombUse.effects, "shrouded_target_unseen"),
        "blocked Attack-like Use Item should report the Shrouded targeting rule")
    assertTrue(shroudThrower.inventory:findItem(shroudedBomb.id),
        "blocked Shrouded item use should not consume the bomb before it is thrown")

    local aegisThrower = base_entity.createEntity({
        id = "pc_aegis_item_thrower",
        name = "Aegis Item Thrower",
        isPC = true,
        cups = 3,
    })
    aegisThrower.inventory = inventory.createInventory()
    local aegisBomb = inventory.createItemFromTemplate("brain_spider_bomb")
    aegisThrower.inventory:addItem(aegisBomb, inventory.LOCATIONS.HANDS)
    local aegisTarget = base_entity.createEntity({
        id = "pc_aegis_item_target",
        name = "Aegis Item Target",
        isPC = true,
        health = 2,
        defense = 0,
        talents = {
            aegis = { mastered = true },
        },
    })
    aegisTarget.inventory = inventory.createInventory()
    local aegisShield = inventory.createItemFromTemplate("shield_light")
    aegisTarget.inventory:addItem(aegisShield, inventory.LOCATIONS.HANDS)
    local aegisBombUse = resolver:resolve({
        actor = aegisThrower,
        target = aegisTarget,
        card = { name = "Eight of Cups", value = 8, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = aegisBomb.id,
        targetInitiative = 7,
        useAegis = true,
    })
    assertTrue(aegisBombUse.success, "Aegis-prevented bomb should still count as a landed item attack")
    assertTrue(hasValue(aegisBombUse.effects, "aegis_effect_prevented"),
        "Aegis should prevent physical Attack-like item effects")
    assertTrue(hasValue(aegisBombUse.effects, "item_attack_like_aegis_prevented"),
        "Aegis item prevention should be reported")
    assertTrue(aegisShield.destroyed, "Aegis should Notch and destroy a fragile light shield")
    assertTrue(not aegisTarget.conditions.rooted, "Aegis should prevent the bomb condition")
    assertTrue(not aegisThrower.inventory:findItem(aegisBomb.id),
        "Aegis-prevented thrown bomb should still be consumed on attempt")
end

local function checkCampTinkersKitRepair()
    local campSteps = camp_controller.getStepDetails()
    assertEqual(campSteps[2].state, camp_controller.STATES.ACTIONS,
        "Camp Phase step metadata should preserve Camp Actions as rulebook step 1")
    assertEqual(campSteps[3].label, "Break bread",
        "Camp Phase step metadata should preserve Break Bread as rulebook step 2")
    assertEqual(campSteps[4].label, "No rest for the wicked",
        "Camp Phase step metadata should preserve the Meatgrinder watch step")
    assertEqual(campSteps[6].label, "End of Camp Phase",
        "Camp Phase step metadata should preserve the end-camp comfort step")
    campSteps[2].label = "Invented camp step"
    assertEqual(camp_controller.getStepDetails()[2].label, "Camp Actions",
        "Camp Phase step metadata should return copy-safe records")
    local actor = base_entity.createEntity({
        id = "pc_tinker",
        name = "Tinker",
        isPC = true,
    })
    actor.inventory = inventory.createInventory()

    local kit = inventory.createItemFromTemplate("tinkers_kit")
    assertEqual(kit.size, 2, "tinker's kit should take two slots")
    actor.inventory:addItem(kit, inventory.LOCATIONS.PACK)

    local sword = inventory.createItem({
        name = "Notched Sword",
        size = 1,
        durability = 2,
    })
    sword.notches = 1
    actor.inventory:addItem(sword, inventory.LOCATIONS.HANDS)

    local repairOptions = camp_actions.getRepairOptions(actor, { targetItem = sword })
    assertEqual(repairOptions.result, "repair_options_ready",
        "tinker's kit repair options should report readiness")
    assertTrue(repairOptions.hasTinkersKit,
        "tinker's kit repair options should detect carried kits")
    assertEqual(repairOptions.kitOptions[1].size, 2,
        "tinker's kit repair options should expose the kit's two-slot size")
    assertTrue(not repairOptions.disabled,
        "tinker's kit repair options should enable repair with a kit and notched gear")
    assertEqual(#repairOptions.repairTargets, 1,
        "tinker's kit repair options should list carried notched gear")
    assertEqual(repairOptions.repairTargets[1].id, sword.id,
        "tinker's kit repair options should identify the repair target")
    assertEqual(repairOptions.repairTargets[1].notchesAfterRepair, 0,
        "tinker's kit repair options should preview one removed Notch")
    assertEqual(repairOptions.selectedTarget.id, sword.id,
        "tinker's kit repair options should mark the selected target")
    repairOptions.repairTargets[1].notches = 99
    assertEqual(camp_actions.getRepairOptions(actor).repairTargets[1].notches, 1,
        "mutating repair options should not alter carried gear")

    local ok, result = camp_actions.resolveRepair(actor, sword, events.createEventBus())
    assertTrue(ok, "tinker's kit camp action should repair a notched item")
    assertEqual(result, "repaired", "repair action should report repaired")
    assertEqual(sword.notches, 0, "tinker's kit should remove one notch")

    local hasUseItem = false
    for _, action in ipairs(camp_actions.getAvailableActions(actor, { actor })) do
        if action.id == "use_item" then
            hasUseItem = true
        end
    end
    assertTrue(hasUseItem, "tinker's kit should make Use an Item available during Camp")

    local armor = inventory.createItem({
        name = "Notched Armor",
        size = 1,
        durability = 2,
    })
    armor.notches = 1
    local useItemRepairEvent = nil
    local repairBus = events.createEventBus()
    repairBus:on("camp_action_resolved", function(data)
        if data.action == "use_item" and data.itemId == kit.id then
            useItemRepairEvent = data
        end
    end)
    local repairController = camp_controller.createCampController({
        eventBus = repairBus,
        guild = { actor },
    })
    repairController:startCamp({ hasShelter = true })
    ok, result = repairController:submitAction(actor, {
        type = "use_item",
        itemId = kit.id,
        targetItem = armor,
    })
    assertTrue(ok, "Use an Item with a tinker's kit should repair a notched item")
    assertEqual(result, "repaired", "tinker's kit Use an Item should report repaired")
    assertEqual(armor.notches, 0, "tinker's kit Use an Item should remove one notch")
    assertTrue(actor.inventory:findItem(kit.id), "tinker's kit should not be consumed by repair")
    assertTrue(useItemRepairEvent and useItemRepairEvent.target == armor,
        "tinker's kit Use an Item should emit canonical use-item repair details")

    local destroyedShield = inventory.createItem({
        name = "Destroyed Shield",
        size = 1,
        durability = 1,
    })
    destroyedShield.notches = 1
    destroyedShield.destroyed = true
    actor.inventory:addItem(destroyedShield, inventory.LOCATIONS.PACK)
    local destroyedRepairOptions = camp_actions.getRepairOptions(actor, { targetItem = destroyedShield })
    assertTrue(destroyedRepairOptions.disabled,
        "tinker's kit repair options should disable destroyed selected targets")
    assertEqual(destroyedRepairOptions.blockedTargets[1].id, destroyedShield.id,
        "tinker's kit repair options should expose destroyed blocked targets")
    assertTrue(hasValue(destroyedRepairOptions.unavailableReasons, "selected_item_not_repairable"),
        "tinker's kit repair options should explain destroyed selected targets")
    ok, result = camp_actions.resolveRepair(actor, destroyedShield, events.createEventBus())
    assertTrue(not ok, "tinker's kit should not salvage destroyed equipment")
    assertEqual(destroyedShield.notches, 1, "failed repair should leave destroyed item notches unchanged")
    assertTrue(destroyedShield.destroyed, "failed repair should leave destroyed item destroyed")
end

function checkCampUseItemResultPrompts()
    local campScreenModule = require('ui.screens.camp_screen')

    local function makeScreen(guild)
        local bus = events.createEventBus()
        local controller = camp_controller.createCampController({
            eventBus = bus,
            guild = guild,
        })
