local function checkCampFletchArrowsAction()
    local actor = base_entity.createEntity({
        id = "pc_fletcher",
        name = "Fletcher",
        isPC = true,
    })
    actor.inventory = inventory.createInventory()
    actor.inventory:addItem(inventory.createItemFromTemplate("bow"), inventory.LOCATIONS.PACK)
    actor.ammo = 2

    local available = camp_actions.getAvailableActions(actor, { actor })
    local sawFletch = false
    for _, action in ipairs(available) do
        if action.id == "fletch_arrows" then
            sawFletch = true
            break
        end
    end
    assertTrue(sawFletch, "Fletch Arrows should be available to a PC carrying a missile weapon")

    local function fletchAmmoOptionByType(options, ammoType)
        for _, option in ipairs(options or {}) do
            if option.type == ammoType then
                return option
            end
        end
        return nil
    end
    local fletchOptions = camp_actions.getFletchArrowsOptions(actor)
    assertEqual(fletchOptions.result, "fletch_arrows_options_ready",
        "Fletch Arrows helper should return structured option data")
    assertTrue(fletchOptions.hasMissileWeapon,
        "Fletch Arrows helper should report carried missile weapons")
    assertEqual(fletchOptions.weaponOptions[1].ammoType, "arrow",
        "Fletch Arrows helper should classify bow ammunition")
    assertEqual(fletchAmmoOptionByType(fletchOptions.ammoOptions, "arrow").previousAmmo, 2,
        "Fletch Arrows helper should preview the previous arrow count")
    assertEqual(fletchAmmoOptionByType(fletchOptions.ammoOptions, "arrow").ammoAfterFletch, 12,
        "Fletch Arrows helper should preview the refilled arrow count")
    fletchOptions.weaponOptions[1].name = "Mutated Bow"
    fletchOptions.ammoOptions[1].ammoAfterFletch = 99
    local refreshedFletchOptions = camp_actions.getFletchArrowsOptions(actor)
    assertEqual(refreshedFletchOptions.weaponOptions[1].name, "Bow",
        "Fletch Arrows helper should return copy-safe weapon option data")
    assertEqual(fletchAmmoOptionByType(refreshedFletchOptions.ammoOptions, "arrow").ammoAfterFletch, 12,
        "Fletch Arrows helper should return copy-safe ammo option data")

    local ok, result = camp_actions.resolveFletchArrows(actor, events.createEventBus())
    assertTrue(ok, "Fletch Arrows should resolve for a missile-weapon user")
    assertEqual(result, "ammo_refilled", "Fletch Arrows should report ammo refill")
    assertEqual(actor.ammo, 12, "Fletch Arrows should refill ammunition to twelve")
    assertEqual(actor.ammunition.arrow, 12, "Fletch Arrows should refill a bow user's arrow quiver")

    local campScreenModule = require('ui.screens.camp_screen')
    local screenFletcher = base_entity.createEntity({
        id = "pc_screen_fletcher",
        name = "Screen Fletcher",
        isPC = true,
    })
    screenFletcher.inventory = inventory.createInventory()
    screenFletcher.inventory:addItem(inventory.createItemFromTemplate("bow"), inventory.LOCATIONS.PACK)
    screenFletcher.ammo = 2
    local screenBus = events.createEventBus()
    local screenController = camp_controller.createCampController({
        eventBus = screenBus,
        guild = { screenFletcher },
    })
    local campScreen = campScreenModule.createCampScreen({
        eventBus = screenBus,
        campController = screenController,
        guild = { screenFletcher },
    })
    campScreen:subscribeEvents()
    screenController:transitionTo(camp_controller.STATES.ACTIONS)
    ok, result = screenController:submitAction(screenFletcher, {
        type = "fletch_arrows",
    })
    assertTrue(ok, "Camp Screen Fletch Arrows submission should resolve")
    assertEqual(result, "ammo_refilled", "Camp Screen Fletch Arrows submission should report refill")
    assertTrue(campScreen.promptOverlay ~= nil,
        "Camp Screen should show a Fletch Arrows result prompt")
    assertEqual(campScreen.promptOverlay.title, "FLETCH ARROWS",
        "Fletch Arrows prompt should use the action title")
    assertTrue((campScreen.promptOverlay.text or ""):find("Arrows: 2 to 12", 1, true) ~= nil,
        "Fletch Arrows prompt should preserve previous and refilled arrow counts")
    campScreen:destroy()

    actor.ammo = 14
    actor.ammunition.arrow = 14
    ok = camp_actions.resolveFletchArrows(actor, events.createEventBus())
    assertTrue(ok, "Fletch Arrows should allow already-full quivers")
    assertEqual(actor.ammo, 14, "Fletch Arrows should not reduce ammo above twelve")
    assertEqual(actor.ammunition.arrow, 14, "Fletch Arrows should not reduce a full arrow quiver")

    local crossbowUser = base_entity.createEntity({
        id = "pc_crossbow_fletcher",
        name = "Crossbow Fletcher",
        isPC = true,
    })
    crossbowUser.inventory = inventory.createInventory()
    crossbowUser.inventory:addItem(inventory.createItemFromTemplate("crossbow"), inventory.LOCATIONS.PACK)
    crossbowUser.ammunition = { arrow = 5, bolt = 2 }
    crossbowUser.ammo = 2
    ok = camp_actions.resolveFletchArrows(crossbowUser, events.createEventBus())
    assertTrue(ok, "Fletch Arrows should resolve for a crossbow user")
    assertEqual(crossbowUser.ammunition.bolt, 12, "Fletch Arrows should refill a crossbow user's bolt quiver")
    assertEqual(crossbowUser.ammunition.arrow, 5, "Fletch Arrows should not refill unrelated arrows")

    local arrowStack = inventory.createItemFromTemplate("arrows")
    assertEqual(arrowStack.stackSize, 12, "Arrows should stack twelve per slot")
    assertEqual(arrowStack.quantity, 12, "An arrows stack should start as a full quiver")
    assertEqual(arrowStack.ammoType, "arrow", "Arrows should retain ammo type metadata")

    local boltStack = inventory.createItemFromTemplate("bolts")
    assertEqual(boltStack.stackSize, 12, "Bolts should stack twelve per slot")
    assertEqual(boltStack.quantity, 12, "A bolts stack should start as a full quiver")
    assertEqual(boltStack.ammoType, "bolt", "Bolts should retain ammo type metadata")

    local fisher = base_entity.createEntity({
        id = "pc_fletch_fisher",
        name = "Fletch Fisher",
        isPC = true,
    })
    fisher.inventory = inventory.createInventory()
    fisher.inventory:addItem(inventory.createItemFromTemplate("fishing_gear"), inventory.LOCATIONS.PACK)
    available = camp_actions.getAvailableActions(fisher, { fisher }, { hasWater = true })
    local sawFisherFletch = false
    local sawFisherHunt = false
    for _, action in ipairs(available) do
        if action.id == "fletch_arrows" then
            sawFisherFletch = true
        elseif action.id == "hunt" then
            sawFisherHunt = true
        end
    end
    assertTrue(not sawFisherFletch, "Fletch Arrows should not be available for fishing gear alone")
    assertTrue(sawFisherHunt, "Fishing gear at water should still satisfy Hunt availability")

    local noBow = base_entity.createEntity({
        id = "pc_no_missile_weapon",
        name = "No Missile Weapon",
        isPC = true,
    })
    noBow.inventory = inventory.createInventory()
    ok, result = camp_actions.resolveFletchArrows(noBow, events.createEventBus())
    assertTrue(not ok, "Fletch Arrows should require a bow or crossbow")
    assertEqual(result, "Requires a bow or crossbow", "missing missile weapon should explain Fletch failure")
end

local function checkCampFellowshipAction()
    local actor = base_entity.createEntity({
        id = "pc_fellowship_actor",
        name = "Fellowship Actor",
        isPC = true,
    })
    local target = base_entity.createEntity({
        id = "pc_fellowship_target",
        name = "Fellowship Target",
        isPC = true,
    })
    local nonAdventurer = base_entity.createEntity({
        id = "npc_fellowship_bystander",
        name = "Fellowship Bystander",
        isPC = false,
    })
    local function fellowshipTargetById(list, id)
        for _, option in ipairs(list or {}) do
            if option.id == id then
                return option
            end
        end
        return nil
    end

    local noTargetOptions = camp_actions.getFellowshipOptions(actor, { actor })
    assertEqual(noTargetOptions.result, "fellowship_options_ready",
        "Fellowship helper should return structured option data")
    assertTrue(noTargetOptions.disabled, "Fellowship helper should disable without another adventurer")
    assertEqual(noTargetOptions.unavailableReasons[1], "no_fellowship_targets",
        "Fellowship helper should explain missing guild-mate targets")

    local fellowshipOptions = camp_actions.getFellowshipOptions(actor, { actor, target, nonAdventurer }, {
        targetId = target.id,
    })
    assertTrue(fellowshipOptions.hasTargets, "Fellowship helper should list guild-mate targets")
    local targetOption = fellowshipTargetById(fellowshipOptions.targetOptions, target.id)
    assertTrue(targetOption ~= nil, "Fellowship helper should include the selected adventurer")
    assertEqual(targetOption.resultPreview, "bonds_charged",
        "Fellowship helper should preview reciprocal Bond charging")
    assertEqual(fellowshipOptions.selectedTarget.id, target.id,
        "Fellowship helper should expose the selected target")
    assertTrue(#fellowshipOptions.roleplayPrompts >= 3,
        "Fellowship helper should expose role-play prompt beats")
    local blockedBystander = fellowshipTargetById(fellowshipOptions.blockedTargets, nonAdventurer.id)
    assertEqual(blockedBystander.unavailableReason, "target_must_be_adventurer",
        "Fellowship helper should report blocked non-adventurer guild members")

    targetOption.name = "Mutated Fellowship Target"
    fellowshipOptions.roleplayPrompts[1].label = "Mutated prompt"
    local refreshedFellowshipOptions = camp_actions.getFellowshipOptions(actor, { actor, target })
    assertEqual(fellowshipTargetById(refreshedFellowshipOptions.targetOptions, target.id).name, target.name,
        "Fellowship helper should return copy-safe target option data")
    assertEqual(refreshedFellowshipOptions.roleplayPrompts[1].label, "Share a memory",
        "Fellowship helper should return copy-safe role-play prompt data")

    local available = camp_actions.getAvailableActions(actor, { actor })
    local sawFellowship = false
    for _, action in ipairs(available) do
        if action.id == "fellowship" then
            sawFellowship = true
            break
        end
    end
    assertTrue(not sawFellowship, "Fellowship should require another adventurer")

    available = camp_actions.getAvailableActions(actor, { actor, target })
    sawFellowship = false
    for _, action in ipairs(available) do
        if action.id == "fellowship" then
            sawFellowship = true
            break
        end
    end
    assertTrue(sawFellowship, "Fellowship should be available with another adventurer")

    available = camp_actions.getAvailableActions(actor, { actor, nonAdventurer })
    sawFellowship = false
    for _, action in ipairs(available) do
        if action.id == "fellowship" then
            sawFellowship = true
            break
        end
    end
    assertTrue(not sawFellowship, "Fellowship should not be available for non-adventurer targets")

    local ok, result = camp_actions.resolveFellowship(actor, actor, events.createEventBus())
    assertTrue(not ok, "Fellowship should not target yourself")
    assertEqual(result, "Cannot fellowship with yourself", "self-fellowship should explain failure")

    ok, result = camp_actions.resolveFellowship(actor, nonAdventurer, events.createEventBus())
    assertTrue(not ok, "Fellowship should reject non-adventurer targets")
    assertEqual(result, "Fellowship target must be an adventurer",
        "non-adventurer fellowship target should explain failure")

    ok, result = camp_actions.resolveAction({
        type = "fellowship",
        actor = actor,
        target = target,
    }, {
        eventBus = events.createEventBus(),
        guild = { actor },
    })
    assertTrue(not ok, "Fellowship should require the target to be in the guild")
    assertEqual(result, "Fellowship requires a guild-mate",
        "non-guild-mate fellowship target should explain failure")

    ok, result = camp_actions.resolveFellowship(actor, target, events.createEventBus())
    assertTrue(ok, "Fellowship should resolve with another adventurer")
    assertEqual(result, "fellowship_complete", "Fellowship should report completion")
    assertTrue(actor.bonds[target.id].charged, "Fellowship should charge actor's bond with target")
    assertTrue(target.bonds[actor.id].charged, "Fellowship should charge target's bond with actor")
end

local function checkCampTrainAction()
    local trainee = base_entity.createEntity({
        id = "pc_train_trainee",
        name = "Train Trainee",
        isPC = true,
    })
    trainee.xp = 3
    trainee.path = "pentacles"
    trainee.talents = {}

    local trainer = base_entity.createEntity({
        id = "pc_train_trainer",
        name = "Train Trainer",
        isPC = true,
        talents = {
            war_stories = { mastered = true },
        },
    })

    local available = camp_actions.getAvailableActions(trainee, { trainee, trainer })
    local sawTrain = false
    for _, action in ipairs(available) do
        if action.id == "train" and action.name == "Train" then
            sawTrain = true
            break
        end
    end
    assertTrue(sawTrain, "Train should be available with another adventurer")

    local trainOptions = camp_actions.getTrainOptions(trainee, { trainee, trainer }, {
        trainerId = trainer.id,
        talentId = "war_stories",
        xp = 2,
    })
    assertEqual(trainOptions.result, "train_options_ready",
        "Camp Train helper should report ready option data")
    assertTrue(not trainOptions.disabled,
        "Camp Train helper should allow a valid trainer, talent, and XP selection")
    assertEqual(trainOptions.selectedTrainer.id, trainer.id,
        "Camp Train helper should expose the selected trainer")
    assertEqual(trainOptions.selectedTalent.id, "war_stories",
        "Camp Train helper should expose the selected mastered trainer talent")
    assertTrue(trainOptions.selectedTalent.mentored,
        "Camp Train helper should preview cross-path mentored training")
    assertTrue(not trainOptions.selectedTalent.ownPath,
        "Camp Train helper should not mark cross-path training as own-path")
    assertEqual(#trainOptions.xpOptions, 3,
        "Camp Train helper should offer positive whole XP choices up to available XP")
    assertEqual(trainOptions.selectedXP.xp, 2,
        "Camp Train helper should expose the selected XP investment")
    assertEqual(trainOptions.selectedXP.totalXPInvestedAfter, 2,
        "Camp Train helper should preview total invested XP")
    assertEqual(trainOptions.selectedXP.availableXPAfter, 1,
        "Camp Train helper should preview remaining available XP")
    assertTrue(not trainOptions.selectedXP.masteredAfter,
        "Camp Train helper should preview incomplete mastery below seven XP")
    assertEqual(trainOptions.selectedXP.actionDataPreview.request.talentId, "war_stories",
        "Camp Train helper should expose resolver-ready action data")
    assertEqual(trainee.xp, 3,
        "Camp Train helper should not spend trainee XP while previewing")
    assertTrue(trainee.talents.war_stories == nil,
        "Camp Train helper should not create the trained talent while previewing")

    trainOptions.selectedTrainer.name = "Mutated Trainer"
    local refreshedTrainOptions = camp_actions.getTrainOptions(trainee, { trainee, trainer }, {
        trainerId = trainer.id,
    })
    assertEqual(refreshedTrainOptions.selectedTrainer.name, trainer.name,
        "Camp Train helper should return copy-safe trainer option data")

    local spentTrainerOptions = camp_actions.getTrainOptions(trainee, { trainee, trainer }, {
        trainerId = trainer.id,
        talentId = "war_stories",
        xp = 1,
        actionsCompleted = {
            [trainer.id] = true,
        },
    })
    assertTrue(spentTrainerOptions.disabled,
        "Camp Train helper should disable trainers who already spent their Camp Action")
    assertEqual(spentTrainerOptions.selectedTrainer.unavailableReason,
        "Trainer has already taken a Camp Action",
        "Camp Train helper should explain spent trainer actions")

    local controller = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { trainee, trainer },
    })
    controller:transitionTo(camp_controller.STATES.ACTIONS)

    local ok, result = controller:submitAction(trainee, {
        type = "train",
        target = trainer,
        talentId = "war_stories",
        xp = 2,
    })
    assertTrue(ok, "Train should resolve with a mastered trainer talent and enough XP")
    assertEqual(result, "training_complete", "Train should report completion")
    assertEqual(trainee.xp, 1, "Train should spend invested XP")
    assertTrue(trainee.talents.war_stories ~= nil, "Train should create the mentored talent")
    assertTrue(trainee.talents.war_stories.mentored, "cross-path Train should mark the talent as mentored")
    assertTrue(not trainee.talents.war_stories.mastered, "two invested XP should not master the talent")
    assertEqual(trainee.talents.war_stories.xp_invested, 2, "Train should record invested XP")
    assertEqual(trainee.talents.war_stories.uses_remaining, 2, "Train should prepare uses equal to XP invested")
    assertTrue(controller.actionsCompleted[trainer.id] ~= nil, "Train should consume the trainer's Camp Action")
    assertTrue(controller:canAdvanceFromActions(), "Train should count as both adventurers' Camp Actions")

    ok, result = controller:submitAction(trainer, { type = "rest" })
    assertTrue(not ok, "trainer should not take a second Camp Action after training")
    assertEqual(result, "Action already taken", "spent trainer action should explain duplicate action failure")

    local poorTrainee = base_entity.createEntity({
        id = "pc_poor_trainee",
        name = "Poor Trainee",
        isPC = true,
    })
    poorTrainee.xp = 0
    poorTrainee.talents = {}
    local poorTrainOptions = camp_actions.getTrainOptions(poorTrainee, { poorTrainee, trainer }, {
        trainerId = trainer.id,
        talentId = "war_stories",
        xp = 1,
    })
    assertTrue(poorTrainOptions.disabled,
        "Camp Train helper should disable training when the trainee lacks XP")
    assertTrue(hasValue(poorTrainOptions.unavailableReasons, "Not enough XP"),
        "Camp Train helper should explain missing XP")
    ok, result = camp_actions.resolveTrain(poorTrainee, trainer, {
        talentId = "war_stories",
        xp = 1,
    }, {}, events.createEventBus())
    assertTrue(not ok, "Train should require XP to invest")
    assertEqual(result, "Not enough XP", "missing XP should explain Train failure")

    local fractionalTrainee = base_entity.createEntity({
        id = "pc_fractional_train_student",
        name = "Fractional Train Student",
        isPC = true,
    })
    fractionalTrainee.xp = 2
    fractionalTrainee.talents = {}
    local fractionalTrainOptions = camp_actions.getTrainOptions(fractionalTrainee, { fractionalTrainee, trainer }, {
        trainerId = trainer.id,
        talentId = "war_stories",
        xp = 1.5,
    })
    assertTrue(fractionalTrainOptions.disabled,
        "Camp Train helper should disable fractional XP training")
    assertTrue(hasValue(fractionalTrainOptions.unavailableReasons,
            "Training XP must be a positive whole number"),
        "Camp Train helper should explain the whole-XP rule")
    ok, result = camp_actions.resolveTrain(fractionalTrainee, trainer, {
        talentId = "war_stories",
        xp = 1.5,
    }, {}, events.createEventBus())
    assertTrue(not ok, "Train should reject fractional XP investment")
    assertEqual(result, "Training XP must be a positive whole number",
        "fractional Camp Train XP should explain the whole-XP rule")
    assertEqual(fractionalTrainee.xp, 2, "fractional Camp Train XP should not be spent")

    local kinTeacher = base_entity.createEntity({
        id = "pc_kin_train_teacher",
        name = "Kin Train Teacher",
        isPC = true,
        talents = {
            proud_and_ancient = { mastered = true },
        },
    })
    local kinStudent = base_entity.createEntity({
        id = "pc_kin_train_student",
        name = "Kin Train Student",
        isPC = true,
    })
    kinStudent.path = "swords"
    kinStudent.kin = "human"
    kinStudent.xp = 3
    kinStudent.talents = {}
    ok, result = camp_actions.resolveTrain(kinStudent, kinTeacher, {
        talentId = "proud_and_ancient",
        xp = 1,
    }, {}, events.createEventBus())
    assertTrue(not ok, "Train should reject kin talents")
    assertEqual(result, "Kin talents cannot be trained", "kin talent training should explain the rulebook restriction")
    assertEqual(kinStudent.xp, 3, "rejected kin talent training should not spend XP")
    assertTrue(kinStudent.talents.proud_and_ancient == nil, "rejected kin talent training should not create the talent")

    local pathStudent = base_entity.createEntity({
        id = "pc_path_train_student",
        name = "Path Train Student",
        isPC = true,
    })
    pathStudent.path = "swords"
    pathStudent.xp = 1
    pathStudent.talents = {}
    local pathTeacher = base_entity.createEntity({
        id = "pc_path_train_teacher",
        name = "Path Train Teacher",
        isPC = true,
        talents = {
            aegis = { mastered = true },
        },
    })
    local ownPathOptions = camp_actions.getTrainOptions(pathStudent, { pathStudent, pathTeacher }, {
        trainerId = pathTeacher.id,
        talentId = "aegis",
        xp = 1,
    })
    assertTrue(ownPathOptions.selectedTalent.ownPath,
        "Camp Train helper should preview own-path talent training")
    assertTrue(not ownPathOptions.selectedTalent.mentored,
        "Camp Train helper should not mark own-path talent training as mentored")
    ok, result = camp_actions.resolveTrain(pathStudent, pathTeacher, {
        talentId = "aegis",
        xp = 1,
    }, {}, events.createEventBus())
    assertTrue(ok, "Train should allow an adventurer to invest in their own path talent")
    assertTrue(pathStudent.talents.aegis.pathTrained, "own-path Train should record path training")
    assertTrue(not pathStudent.talents.aegis.mentored, "own-path Train should not mark the talent as mentored")

    local masteredStudent = base_entity.createEntity({
        id = "pc_mastered_train_student",
        name = "Mastered Train Student",
        isPC = true,
        talents = {
            aegis = { mastered = true },
        },
    })
    masteredStudent.path = "swords"
    masteredStudent.xp = 1
    local masteredTrainOptions = camp_actions.getTrainOptions(masteredStudent, { masteredStudent, pathTeacher }, {
        trainerId = pathTeacher.id,
        talentId = "aegis",
        xp = 1,
    })
    assertTrue(masteredTrainOptions.disabled,
        "Camp Train helper should disable already mastered talent training")
    assertTrue(hasValue(masteredTrainOptions.unavailableReasons, "Talent already mastered"),
        "Camp Train helper should explain already mastered talent training")
    ok, result = camp_actions.resolveTrain(masteredStudent, pathTeacher, {
        talentId = "aegis",
        xp = 1,
    }, {}, events.createEventBus())
    assertTrue(not ok, "Train should reject already mastered talents")
    assertEqual(result, "Talent already mastered", "mastered Camp Train should explain no-op")
    assertEqual(masteredStudent.xp, 1, "rejected mastered Camp Train should not spend XP")

    trainee.xp = 5
    ok, result = camp_actions.resolveTrain(trainee, trainer, {
        talentId = "war_stories",
        xp = 5,
    }, {}, events.createEventBus())
    assertTrue(ok, "additional training should resolve")
    assertTrue(trainee.talents.war_stories.mastered, "seven total invested XP should master the talent")
end

local function checkCampUseTalentAction()
    local beastMaster = base_entity.createEntity({
        id = "pc_camp_beast_master",
        name = "Camp Beast Master",
        isPC = true,
        talents = {
            beast_master = { mastered = true },
        },
    })
    local hound = {
        id = "hound_camp",
        name = "Camp Hound",
        knownCommands = { { command = "Fetch" }, "Stay" },
        conditions = {},
    }
    beastMaster.animalCompanions = { hound }

    local available = camp_actions.getAvailableActions(beastMaster, { beastMaster })
    local sawUseTalent = false
    for _, action in ipairs(available) do
        if action.id == "use_talent" and action.name == "Use a Talent" then
            sawUseTalent = true
            break
        end
    end
    assertTrue(sawUseTalent, "Use a Talent should be available for usable Camp talents")

    local commandCountBeforeDuplicate = #hound.knownCommands
    local duplicateOk, duplicateResult = camp_actions.resolveUseTalent(beastMaster, {
        talentId = "beast_master",
        companionId = "hound_camp",
        command = "Fetch",
    }, {}, events.createEventBus())
    assertTrue(duplicateOk,
        "Beast Master camp talent should accept an already-known command as a no-op")
    assertEqual(duplicateResult, "companion_command_taught",
        "duplicate Beast Master command should report the existing no-op result")
    assertEqual(#hound.knownCommands, commandCountBeforeDuplicate,
        "duplicate Beast Master command should not append a second command-field entry")

    local ok, result = camp_actions.resolveUseTalent(beastMaster, {
        talentId = "beast_master",
        companionId = "hound_camp",
        command = "Guard",
    }, {}, events.createEventBus())
    assertTrue(ok, "Beast Master camp talent should teach a command")
    assertEqual(result, "companion_command_taught", "Beast Master should report command teaching")
    assertTrue(hasValue(hound.knownCommands, "Guard"), "Beast Master should add the taught command")

    ok, result = camp_actions.resolveUseTalent(beastMaster, {
        talentId = "beast_master",
        companionId = "hound_camp",
        command = "Track",
    }, {}, events.createEventBus())
    assertTrue(not ok, "ordinary animal companions should cap at three commands")
    assertEqual(result, "Companion already knows three commands", "command cap should explain Beast Master failure")

    ok, result = camp_actions.resolveUseTalent(beastMaster, {
        talentId = "beast_master",
        companionId = "hound_camp",
        command = "Track",
        replaceCommand = "Stay",
    }, {}, events.createEventBus())
    assertTrue(ok, "Beast Master should retrain a known command")
    assertTrue(hasValue(hound.knownCommands, "Track"), "replacement command should be learned")
    assertTrue(not hasValue(hound.knownCommands, "Stay"), "replaced command should be removed")

    ok, result = camp_actions.resolveUseTalent(beastMaster, {
        talentId = "beast_master",
        companionId = "hound_camp",
        command = "Hunt",
        makeFamiliar = true,
    }, {}, events.createEventBus())
    assertTrue(ok, "mastered Beast Master should be able to designate a familiar while training")
    assertTrue(hound.isFamiliar and hound.familiar, "familiar designation should mark the companion")
    assertTrue(hasValue(hound.knownCommands, "Hunt"), "familiar should learn a fourth command")

    ok, result = camp_actions.resolveUseTalent(beastMaster, {
        talentId = "beast_master",
        companionId = "hound_camp",
        command = "Get Help",
    }, {}, events.createEventBus())
    assertTrue(ok, "familiar should be able to learn a fifth command")
    assertTrue(hasValue(hound.knownCommands, "Get Help"), "familiar fifth command should be recorded")

    ok, result = camp_actions.resolveUseTalent(beastMaster, {
        talentId = "beast_master",
        companionId = "hound_camp",
        command = "Do a Trick",
    }, {}, events.createEventBus())
    assertTrue(not ok, "familiar should cap at five commands")
    assertEqual(result, "Familiar already knows five commands", "familiar command cap should explain Beast Master failure")

    local storyteller = base_entity.createEntity({
        id = "pc_war_stories",
        name = "Storyteller",
        isPC = true,
        talents = {
            war_stories = { mastered = true },
        },
    })
    storyteller.resolve = { current = 4, max = 4 }
    local listener = base_entity.createEntity({
        id = "pc_story_listener",
        name = "Story Listener",
        isPC = true,
    })
    listener.bonds = {
        pc_war_stories = { charged = false },
    }
    ok, result = camp_actions.resolveUseTalent(storyteller, {
        talentId = "war_stories",
        participants = { storyteller, listener },
        benefits = {
            pc_war_stories = { type = "resolve" },
            pc_story_listener = { type = "charge_bond", bondTargetId = "pc_war_stories" },
        },
    }, {}, events.createEventBus())
    assertTrue(ok, "War Stories should resolve as a Camp talent")
    assertEqual(result, "war_stories_shared", "War Stories should report shared story")
    assertEqual(storyteller.resolve.current, 5, "War Stories should raise Resolve to five")
    assertEqual(storyteller.resolve.max, 5, "War Stories should allow Resolve maximum five")
    assertTrue(listener.bonds.pc_war_stories.charged, "War Stories should charge selected uncharged Bonds")

    local chantEvent = nil
    local chantBus = events.createEventBus()
    chantBus:on("camp_action_resolved", function(data)
        if data.talentId == "high_chant" then
            chantEvent = data
        end
    end)
    local chanter = base_entity.createEntity({
        id = "pc_high_chant",
        name = "High Chant",
        isPC = true,
        cups = 2,
        talents = {
            high_chant = { mastered = true },
        },
    })
    local chantAlly = base_entity.createEntity({
        id = "pc_high_chant_ally",
        name = "High Chant Ally",
        isPC = true,
    })
    local chantSword = { name = "Three of Swords", value = 3, suit = constants.SUITS.SWORDS }
    local chantCups = { name = "Four of Cups", value = 4, suit = constants.SUITS.CUPS }
    local chantWands = { name = "Five of Wands", value = 5, suit = constants.SUITS.WANDS }
    local discardPile = { chantSword, chantCups, chantWands }
    local detail = nil
    ok, result, detail = camp_actions.resolveUseTalent(chanter, {
        talentId = "high_chant",
        cards = { chantSword, chantCups },
        recipients = { chanter, chantAlly },
        discardPile = discardPile,
    }, {
        guild = { chanter, chantAlly },
    }, chantBus)
    assertTrue(ok, "High Chant should resolve as a Camp talent")
    assertEqual(result, "high_chant_performed", "High Chant should report performance")
    assertEqual(#detail, 2, "High Chant should grant up to Cups inspiration cards")
    assertEqual(#discardPile, 1, "High Chant should remove selected cards from the minor discard pile")
    assertEqual(discardPile[1], chantWands, "High Chant should leave unselected discard cards")
    assertEqual(chanter.inspirationCard, chantSword, "High Chant performer may keep one inspiration card")
    assertEqual(chantAlly.inspirationCard, chantCups, "High Chant should distribute inspiration to another player")
    assertEqual(chantCups.inspiration.source, "high_chant", "High Chant cards should carry inspiration metadata")
    assertEqual(chantCups.inspiration.expires, "session_end", "High Chant inspiration should last until session end")
    assertTrue(chantEvent and #chantEvent.inspirationCards == 2, "High Chant should emit granted cards")

    local spentEvent = nil
    local spentBus = events.createEventBus()
    spentBus:on("inspiration_card_spent", function(data)
        spentEvent = data
    end)
    local inspirationDiscard = {
        discarded = {},
        discard = function(self, card)
            self.discarded[#self.discarded + 1] = card
        end,
    }
    chanter.zone = "A"
    chanter.pentacles = 7
    local inspiredResolver = action_resolver.createActionResolver({
        eventBus = spentBus,
        playerDeck = inspirationDiscard,
    })
    local inspiredAction = inspiredResolver:resolve({
        actor = chanter,
        card = chantSword,
        type = action_resolver.ACTION_TYPES.DASH,
        destinationZone = "B",
    })
    assertTrue(inspiredAction.success, "inspiration cards should be usable as Challenge action cards")
    assertTrue(hasValue(inspiredAction.effects, "inspiration_spent"),
        "using an inspiration action card should report the spend")
    assertTrue(chanter.inspirationCard == nil, "spent inspiration action card should clear from actor")
    assertTrue(chantSword.inspiration.spent, "spent inspiration action card should be marked spent")
    assertEqual(inspirationDiscard.discarded[1], chantSword, "spent inspiration action card should be discarded")
    assertEqual(spentEvent and spentEvent.card, chantSword, "spent inspiration action card should emit an event")

    local tooMany = base_entity.createEntity({
        id = "pc_high_chant_too_many",
        name = "High Chant Too Many",
        isPC = true,
        cups = 1,
        talents = {
            high_chant = { mastered = true },
        },
    })
    local excessDiscard = {
        { name = "Six of Cups", value = 6, suit = constants.SUITS.CUPS },
        { name = "Seven of Cups", value = 7, suit = constants.SUITS.CUPS },
    }
    ok, result = camp_actions.resolveUseTalent(tooMany, {
        talentId = "high_chant",
        cards = excessDiscard,
        recipients = { tooMany, chanter },
        discardPile = excessDiscard,
    }, {}, events.createEventBus())
    assertTrue(not ok, "High Chant should not select more cards than Cups")
    assertEqual(result, "Too many inspiration cards", "High Chant Cups limit should explain failure")
    assertEqual(#excessDiscard, 2, "failed High Chant should not remove discard cards")

    local blockedCard = { name = "Eight of Cups", value = 8, suit = constants.SUITS.CUPS }
