    local function makeSneakActor(id, talentEntry, resolveAmount)
        local actor = base_entity.createEntity({
            id = id,
            name = id,
            isPC = true,
            talents = {
                sneak = talentEntry or { mastered = true },
            },
        })
        actor.resolve = { current = resolveAmount or 2, max = 2 }
        return actor
    end

