local function checkAlchemyHarvestReagents()
    local harvester = base_entity.createEntity({
        id = "pc_reagent_harvester",
        name = "Reagent Harvester",
        isPC = true,
        talents = {
            alchemy = { mastered = true },
        },
    })
    harvester.inventory = inventory.createInventory()
    harvester.inventory:addItem(inventory.createItemFromTemplate("hermetic_bottle"), inventory.LOCATIONS.PACK)

    local spider = entity_factory.createEntity("brain_spider")
    spider.id = "fresh_brain_spider"
    spider.conditions.dead = true
    spider.defeatedAtWatch = 0

    local bus = events.createEventBus()
    local emitted = nil
    bus:on(events.EVENTS.ALCHEMY_REAGENT_HARVESTED, function(data)
        emitted = data
    end)
    local manager = watch_manager.createWatchManager({
        eventBus = bus,
        guild = { harvester },
    })

    local harvestOptions = alchemy.getHarvestReagentOptions(harvester, { spider }, {
        watchManager = manager,
        selectedSourceId = spider.id,
    })
    assertEqual(harvestOptions.result, "harvest_reagent_options_ready",
        "harvest options should report readiness")
    assertTrue(not harvestOptions.disabled, "fresh monster corpse harvest options should be enabled")
    assertTrue(harvestOptions.hasAlchemyTalent, "harvest options should report usable Alchemy")
    assertTrue(harvestOptions.hasEmptyHermeticBottle,
        "harvest options should report the empty bottle gate")
    assertEqual(harvestOptions.bottle.templateId, "hermetic_bottle",
        "harvest options should expose the empty hermetic bottle")
    assertEqual(harvestOptions.bottle.location, inventory.LOCATIONS.PACK,
        "harvest options should expose the empty bottle location")
    assertEqual(#harvestOptions.sourceOptions, 1,
        "harvest options should list candidate corpse sources")
    assertEqual(harvestOptions.selectedSource.reagentTemplateId, "brain_spider_reagent",
        "harvest options should preview the selected corpse reagent")
    assertTrue(harvestOptions.selectedSource.resultPreview.watchSpent,
        "harvest options should preview the watch spend")
    assertEqual(harvestOptions.selectedSource.resultPreview.remainingYieldAfterHarvest, 0,
        "harvest options should preview one-yield source depletion")
    assertEqual(harvestOptions.selectedSource.resultPreview.sourceState.state, "harvested",
        "harvest options should preview harvested remains state")
    assertTrue(harvestOptions.selectedSource.resultPreview.sourceState.depleted,
        "harvest options should preview harvested corpse cleanup")
    assertEqual(manager:getWatchCount(), 0,
        "harvest options should not spend a watch")
    assertTrue(harvester.inventory:findItemByPredicate(function(item)
        return item.templateId == "hermetic_bottle"
    end) ~= nil, "harvest options should not consume the empty bottle")

    local ok, result, harvest = alchemy.resolveHarvestReagent(harvester, spider, {
        watchManager = manager,
        eventBus = bus,
    })
    assertTrue(ok, "Alchemy users should harvest fresh monster corpses")
    assertEqual(result, "reagent_harvested", "harvest should report reagent collection")
    assertEqual(manager:getWatchCount(), 1, "harvesting reagents should spend a watch")
    assertTrue(harvest.reagent.templateId == "brain_spider_reagent", "brain spiders should yield brain spider reagents")
    assertTrue(harvest.reagent.properties.hermeticBottle, "harvested reagents should be stored in hermetic bottles")
    assertTrue(harvest.reagent.properties.harvestedFrom == "Brain Spider", "harvest should record its source creature")
    assertTrue(harvester.inventory:findItemByPredicate(function(item)
        return item.templateId == "brain_spider_reagent"
    end) ~= nil, "harvested reagent should replace an empty bottle in inventory")
    assertTrue(harvester.inventory:findItemByPredicate(function(item)
        return item.templateId == "hermetic_bottle"
    end) == nil, "empty hermetic bottle should be consumed by harvest")
    assertTrue(spider.alchemy.depleted, "one-yield monsters should be depleted after harvest")
    assertTrue(spider.reagentsHarvested and spider.reagentsDepleted,
        "depleted reagent sources should record that their reagents were harvested")
    assertEqual(harvest.sourceState.state, "harvested",
        "depleted reagent source state should report harvested remains")
    assertTrue(emitted and emitted.reagent == harvest.reagent, "harvest should emit reagent details")

    harvester.inventory:addItem(inventory.createItemFromTemplate("hermetic_bottle"), inventory.LOCATIONS.PACK)
    local depletedOptions = alchemy.getHarvestReagentOptions(harvester, { spider }, {
        watchManager = manager,
        selectedSourceId = spider.id,
    })
    assertTrue(depletedOptions.disabled, "depleted corpse harvest options should be disabled")
    assertTrue(depletedOptions.selectedSource.disabled,
        "depleted corpse source option should be disabled")
    assertTrue(hasValue(depletedOptions.unavailableReasons, "No viable alchemical reagents remain"),
        "depleted corpse selected options should report the blocked selection")
    assertTrue(hasValue(depletedOptions.selectedSource.unavailableReasons, "No viable alchemical reagents remain"),
        "depleted corpse harvest options should explain depletion")
    assertTrue(depletedOptions.selectedSource.resultPreview == nil,
        "depleted corpse harvest options should not preview a successful harvest")
    assertEqual(manager:getWatchCount(), 1,
        "depleted harvest options should not spend a watch")
    ok, result = alchemy.resolveHarvestReagent(harvester, spider, {
        watchManager = manager,
        eventBus = bus,
    })
    assertTrue(not ok, "depleted corpses should not produce more reagents")
    assertEqual(result, "No viable alchemical reagents remain", "depleted corpse should explain harvest failure")
    assertEqual(manager:getWatchCount(), 1, "failed depleted harvest should not spend a watch")

    local staleHarvester = base_entity.createEntity({
        id = "pc_stale_reagent_harvester",
        name = "Stale Reagent Harvester",
        isPC = true,
        talents = {
            alchemy = { mastered = true },
        },
    })
    staleHarvester.inventory = inventory.createInventory()
    staleHarvester.inventory:addItem(inventory.createItemFromTemplate("hermetic_bottle"), inventory.LOCATIONS.PACK)
    local staleSpider = entity_factory.createEntity("brain_spider")
    staleSpider.conditions.dead = true
    staleSpider.defeatedAtWatch = 0
    local staleManager = watch_manager.createWatchManager({ eventBus = events.createEventBus() })
    staleManager.watchCount = 1
    local staleOptions = alchemy.getHarvestReagentOptions(staleHarvester, { staleSpider }, {
        watchManager = staleManager,
    })
    assertTrue(staleOptions.disabled, "stale corpse harvest options should be disabled")
    assertEqual(staleOptions.sourceOptions[1].unavailableReasons[1], "Reagents have spoiled",
        "stale corpse harvest options should explain spoilage")
    ok, result = alchemy.resolveHarvestReagent(staleHarvester, staleSpider, {
        watchManager = staleManager,
    })
    assertTrue(not ok, "corpses left for a watch should lose alchemical potency")
    assertEqual(result, "Reagents have spoiled", "stale corpse should explain harvest failure")
    assertEqual(staleManager:getWatchCount(), 1, "spoiled harvest should not spend another watch")

    local untrained = base_entity.createEntity({
        id = "pc_untrained_alchemy",
        name = "Untrained Alchemy",
        isPC = true,
    })
    untrained.inventory = inventory.createInventory()
    untrained.inventory:addItem(inventory.createItemFromTemplate("hermetic_bottle"), inventory.LOCATIONS.PACK)
    local ooze = entity_factory.createEntity("small_ooze")
    ooze.conditions.dead = true
    local untrainedOptions = alchemy.getHarvestReagentOptions(untrained, { ooze }, {
        watchManager = watch_manager.createWatchManager({ eventBus = events.createEventBus() }),
    })
    assertTrue(untrainedOptions.disabled, "untrained harvest options should be disabled")
    assertEqual(untrainedOptions.unavailableReasons[1], "Requires Alchemy talent",
        "untrained harvest options should report the Alchemy gate")
    ok, result = alchemy.resolveHarvestReagent(untrained, ooze, {
        watchManager = watch_manager.createWatchManager({ eventBus = events.createEventBus() }),
    })
    assertTrue(not ok, "reagent harvesting should require Alchemy")
    assertEqual(result, "Requires Alchemy talent", "missing Alchemy should explain harvest failure")

    local humanoidHarvester = base_entity.createEntity({
        id = "pc_humanoid_reagent_harvester",
        name = "Humanoid Reagent Harvester",
        isPC = true,
        talents = {
            alchemy = { mastered = true },
        },
    })
    humanoidHarvester.inventory = inventory.createInventory()
    humanoidHarvester.inventory:addItem(inventory.createItemFromTemplate("hermetic_bottle"), inventory.LOCATIONS.PACK)
    local humanoidCorpse = {
        id = "fallen_human_sorcerer",
        name = "Fallen Human Sorcerer",
        type = "corpse",
        species = "human",
        conditions = { dead = true },
        alchemy = {
            reagentTemplateId = "brain_spider_reagent",
            yield = 1,
        },
    }
    local humanoidWatch = watch_manager.createWatchManager({ eventBus = events.createEventBus() })
    local humanoidOptions = alchemy.getHarvestReagentOptions(humanoidHarvester, { humanoidCorpse }, {
        watchManager = humanoidWatch,
    })
    assertTrue(humanoidOptions.disabled, "sentient humanoid harvest options should be disabled")
    assertEqual(humanoidOptions.sourceOptions[1].unavailableReasons[1], "Sentient humanoids yield no reagents",
        "humanoid harvest options should explain the rulebook exclusion")
    ok, result = alchemy.resolveHarvestReagent(humanoidHarvester, humanoidCorpse, {
        watchManager = humanoidWatch,
    })
    assertTrue(not ok, "sentient humanoids should not yield alchemical reagents")
    assertEqual(result, "Sentient humanoids yield no reagents",
        "humanoid harvest rejection should explain the rulebook exclusion")
    assertEqual(humanoidWatch:getWatchCount(), 0,
        "rejected humanoid harvest should not spend a watch")

    local system = interaction.createInteractionSystem({})
    local actions = system:getValidActions({
        id = "fresh_spider_corpse",
        type = "corpse",
        alchemy = {
            reagentTemplateId = "brain_spider_reagent",
            yield = 1,
        },
    })
    local sawHarvest = false
    for _, action in ipairs(actions) do
        if action.action == "harvest_reagent" then
            sawHarvest = true
            break
        end
    end
    assertTrue(sawHarvest, "alchemy-bearing corpses should expose a harvest interaction")
end

function checkCaltropsItemHazard()
    local bus = events.createEventBus()
    local zones = zone_system.createZoneRegistry({ eventBus = bus })
    zones:setRoomZones({
        { id = "near", adjacent_to = { "far" } },
        { id = "far", adjacent_to = { "near" } },
    })

    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
        zoneSystem = zones,
    })

    local actor = base_entity.createEntity({
        id = "pc_caltrop_scatterer",
        name = "Caltrop Scatterer",
        isPC = true,
        zone = "near",
    })
    actor.inventory = inventory.createInventory()
    zones:placeEntity(actor.id, "near")

    local caltrops = inventory.createItemFromTemplate("caltrops")
    actor.inventory:addItem(caltrops, inventory.LOCATIONS.HANDS)
    local scatterAction = {
        actor = actor,
        card = { name = "Two of Cups", value = 2, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = caltrops.id,
        item = caltrops,
        targetZone = "far",
    }
    local scatter = resolver:resolve(scatterAction)
    local farZone = zones:getZone("far")
    assertTrue(scatter.success, "Use Item should scatter held caltrops into a zone")
    assertTrue(scatter.itemUse and scatter.itemUse.itemEffectType == "scatter_caltrops",
        "Use Item should preserve zone item-effect metadata")
    assertTrue(farZone.properties.caltrops and farZone.properties.areaDenied,
        "scattered caltrops should mark the target zone as area denied")
    assertEqual(#farZone.caltrops, 1, "scattered caltrops should create one zone hazard")
    assertTrue(hasValue(scatter.effects, "caltrops_scattered"),
        "scattering caltrops should report the authored item effect")
    do
        local caltropPopup = getActionSequencerPopup(scatterAction, scatter, function(data)
            return data.title == "Use Item"
        end)
        assertTrue(caltropPopup ~= nil, "zone Use Item should queue a visible item-effect popup")
        assertEqual(caltropPopup.item, caltrops, "zone Use Item popup should preserve the item")
        assertEqual(caltropPopup.itemEffectType, "scatter_caltrops",
            "zone Use Item popup should preserve the item effect type")
        assertEqual(caltropPopup.targetZone, "far", "zone Use Item popup should preserve the selected zone")
        assertTrue(caltropPopup.itemConsumed, "zone Use Item popup should preserve consumed item state")
    end
    assertTrue(not actor.inventory:findItem(caltrops.id),
        "scattered caltrops should leave the actor's inventory")

    local unshod = base_entity.createEntity({
        id = "npc_unshod_caltrop_walker",
        name = "Unshod Walker",
        isPC = false,
        health = 2,
        defense = 0,
        zone = "near",
    })
    unshod.unshod = true
    zones:placeEntity(unshod.id, "near")
    local stepOnCaltrops = resolver:resolve({
        actor = unshod,
        card = { name = "Two of Pentacles", value = 2, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.MOVE,
        destinationZone = "far",
        allEntities = { actor, unshod },
    })
    assertTrue(stepOnCaltrops.success, "unshod creature should still enter the caltrop zone")
    assertEqual(unshod.zone, "far", "caltrops should wound after movement enters the zone")
    assertEqual(unshod.npcHealth, 1, "unshod walking through caltrops should take one Wound")
    assertTrue(stepOnCaltrops.caltrops and stepOnCaltrops.caltrops.triggered,
        "movement result should record the triggered caltrops")
    assertTrue(hasValue(stepOnCaltrops.effects, "caltrops_wound"),
        "movement through caltrops should report the wound")

    local aegisWalker = base_entity.createEntity({
        id = "pc_aegis_caltrop_walker",
        name = "Aegis Caltrop Walker",
        isPC = true,
        armorSlots = 0,
        talentWoundSlots = 1,
        talents = {
            aegis = { mastered = true },
        },
        zone = "near",
    })
    aegisWalker.unshod = true
    aegisWalker.inventory = inventory.createInventory()
    local aegisShield = inventory.createItemFromTemplate("shield_light")
    aegisWalker.inventory:addItem(aegisShield, inventory.LOCATIONS.HANDS)
    zones:placeEntity(aegisWalker.id, "near")
    local aegisCaltrops = resolver:resolve({
        actor = aegisWalker,
        card = { name = "Two of Pentacles", value = 2, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.MOVE,
        destinationZone = "far",
        allEntities = { actor, unshod, aegisWalker },
        useAegis = true,
    })
    assertTrue(aegisCaltrops.success, "Aegis caltrop movement should still enter the hazard zone")
    assertEqual(aegisWalker.zone, "far", "Aegis caltrop movement should update the actor zone")
    assertEqual(aegisShield.notches, 1, "Aegis should Notch a shield against elected caltrop hazard damage")
    assertTrue(not aegisWalker.talents.aegis.wounded,
        "Aegis should prevent the caltrops Wound effect")
    assertTrue(aegisCaltrops.aegisResult and aegisCaltrops.aegisResult.shield == aegisShield,
        "caltrop movement should retain Aegis shield details for presentation")
    assertEqual(aegisCaltrops.caltropWounds, 0,
        "Aegis-prevented caltrops should not count as applied caltrop Wounds")
    assertTrue(hasValue(aegisCaltrops.effects, "caltrops_wound_prevented"),
        "Aegis-prevented caltrops should report wound prevention")
    local actionSequencer = require('ui.action_sequencer')
    local sequencer = actionSequencer.createActionSequencer({ eventBus = events.createEventBus() })
    sequencer:queueActionSequence({
        action = {
            actor = aegisWalker,
            card = { name = "Two of Pentacles", value = 2, suit = constants.SUITS.PENTACLES },
        },
        result = aegisCaltrops,
    })
    local hasAegisPopup = false
    for _, step in ipairs(sequencer.currentSequence or {}) do
        if step.type == actionSequencer.STEP_TYPES.TEXT_POPUP and
           step.data and step.data.title == "Aegis" then
            hasAegisPopup = true
            assertEqual(step.data.shield, aegisShield,
                "Aegis caltrop popup should include the Notched shield")
            break
        end
    end
    assertTrue(hasAegisPopup, "Aegis-prevented caltrops should queue a visible popup")

    local shod = base_entity.createEntity({
        id = "npc_shod_caltrop_walker",
        name = "Shod Walker",
        isPC = false,
        health = 2,
        defense = 0,
        zone = "near",
    })
    shod.shod = true
    zones:placeEntity(shod.id, "near")
    local shodMove = resolver:resolve({
        actor = shod,
        card = { name = "Two of Pentacles", value = 2, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.MOVE,
        destinationZone = "far",
        allEntities = { actor, shod },
    })
    assertTrue(shodMove.success, "shod movement should still resolve through caltrops")
    assertEqual(shod.npcHealth, 2, "shod creatures should not be wounded by caltrops")
    assertTrue(hasValue(shodMove.effects, "caltrops_shod_ignored"),
        "shod caltrop movement should report why no Wound was applied")

    local flyer = base_entity.createEntity({
        id = "npc_flying_caltrop_walker",
        name = "Flying Walker",
        isPC = false,
        health = 2,
        defense = 0,
        zone = "near",
    })
    flyer.unshod = true
    flyer.flying = true
    zones:placeEntity(flyer.id, "near")
    local flyMove = resolver:resolve({
        actor = flyer,
        card = { name = "Two of Pentacles", value = 2, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.MOVE,
        destinationZone = "far",
        allEntities = { actor, flyer },
    })
    assertTrue(flyMove.success, "flying movement should still cross a caltrop zone")
    assertEqual(flyer.npcHealth, 2, "flying unshod creatures should not walk into caltrops")
    assertTrue(hasValue(flyMove.effects, "caltrops_bypassed"),
        "non-walking caltrop movement should report bypass")
end

function checkCrowbarItemInteraction()
    local itemInteraction = require('logic.item_interaction')
    local system = itemInteraction.createItemInteractionSystem({
        eventBus = events.createEventBus(),
    })
    local crowbar = inventory.createItemFromTemplate("crowbar")
    local lockedDoor = {
        id = "locked_oak_door",
        name = "Locked Oak Door",
        type = "door",
        state = "locked",
        lock = { difficulty = 13 },
    }

    local request = system:useItemOnPOI(crowbar, lockedDoor, itemInteraction.INTERACTION_TYPES.BREAK, {})
    assertTrue(request.requiresTest, "crowbars should request a test to pry a locked door")
    assertEqual(request.testConfig.attribute, "swords", "crowbar pry tests should use Swords")
    assertEqual(request.testConfig.difficulty, 13, "crowbar pry tests should reuse lock difficulty")
    assertTrue(not lockedDoor.broken, "requesting a crowbar test should not break the door yet")

    local failed = system:useItemOnPOI(crowbar, lockedDoor, itemInteraction.INTERACTION_TYPES.BREAK, {
        testResult = { success = false },
    })
    assertTrue(not failed.success, "failed crowbar pry test should fail")
    assertEqual(lockedDoor.state, "locked", "failed crowbar pry should leave the door locked")
    assertTrue(not lockedDoor.broken, "failed crowbar pry should not break the door")

    local forced = system:useItemOnPOI(crowbar, lockedDoor, itemInteraction.INTERACTION_TYPES.BREAK, {
        testResult = { success = true },
    })
    assertTrue(forced.success, "successful crowbar pry should succeed")
    assertEqual(lockedDoor.state, "broken", "successful crowbar pry should break the door")
    assertTrue(lockedDoor.broken and lockedDoor.forcedOpen and lockedDoor.priedOpen,
        "successful crowbar pry should mark forced-open state")
    assertTrue(lockedDoor.lock.broken and lockedDoor.lock.disabled,
        "successful crowbar pry should break the lock")
    assertEqual(crowbar.notches, 0, "forcing a door with a crowbar should break the door, not the crowbar")

    local lockpicks = inventory.createItemFromTemplate("lockpicks")
    local lockedChest = {
        id = "locked_travel_chest",
        name = "Locked Travel Chest",
        type = "chest",
        state = "locked",
        lock = { difficulty = 12 },
    }
    assertTrue(lockpicks.stackable, "Lockpicks should be modeled as a stack")
    assertEqual(lockpicks.stackSize, 6, "Lockpicks should stack six per slot")
    assertEqual(lockpicks.quantity, 6, "A lockpick stack should start with six picks")

    local lockpickAttempt = system:useItemOnPOI(lockpicks, lockedChest, itemInteraction.INTERACTION_TYPES.UNLOCK, {})
    assertTrue(lockpickAttempt.requiresTest, "template lockpicks should request a lock-picking test")
    assertEqual(lockpickAttempt.testConfig.attribute, "pentacles", "lockpicks should still test Pentacles")
    assertEqual(lockpickAttempt.testConfig.difficulty, 12, "lockpick tests should reuse lock difficulty")

    local failedPick = system:useItemOnPOI(lockpicks, lockedChest, itemInteraction.INTERACTION_TYPES.UNLOCK, {
        testResult = { success = false },
    })
    assertTrue(not failedPick.success, "failed lockpicking should fail")
    assertTrue(failedPick.lockpickBroken, "failed lockpicking should break one lockpick")
    assertEqual(lockpicks.quantity, 5, "failed lockpicking should consume one pick from the stack")
    assertEqual(lockedChest.state, "locked", "failed lockpicking should leave the chest locked")

    local picked = system:useItemOnPOI(lockpicks, lockedChest, itemInteraction.INTERACTION_TYPES.UNLOCK, {
        testResult = { success = true },
    })
    assertTrue(picked.success, "successful lockpicking should succeed")
    assertEqual(lockedChest.state, "unlocked", "successful lockpicking should unlock the chest")
    assertTrue(lockedChest.lock.picked and not lockedChest.lock.broken,
        "successful lockpicking should pick the lock without breaking it")
    assertEqual(lockpicks.quantity, 5, "successful lockpicking should not consume another lockpick")

    local hatchet = inventory.createItemFromTemplate("hatchet")
    assertTrue(system:canPerform(hatchet, itemInteraction.INTERACTION_TYPES.BREAK),
        "template hatchets should be usable to smash open breakable doors")
    local barredDoor = {
        id = "barred_door",
        name = "Barred Door",
        type = "door",
        breakable = true,
    }
    local hatchetBreak = system:useItemOnPOI(hatchet, barredDoor, itemInteraction.INTERACTION_TYPES.BREAK, {})
    assertTrue(hatchetBreak.success, "hatchets should break open authored breakable doors")
    assertEqual(hatchetBreak.poiStateChange, "destroyed", "hatchet smashing should destroy the obstacle")

    local sword = inventory.createItemFromTemplate("rusty_sword")
    assertTrue(system:canPerform(sword, itemInteraction.INTERACTION_TYPES.BREAK),
        "weapons should be selectable for smashing objects open")
    local weaponBreak = system:useItemOnPOI(sword, {
        id = "stuck_crate",
        name = "Stuck Crate",
        breakable = true,
    }, itemInteraction.INTERACTION_TYPES.BREAK, {})
    assertTrue(weaponBreak.success, "weapon smashing should break an authored breakable object")
    assertTrue(weaponBreak.itemDamaged, "weapon smashing should Notch the weapon")
    assertEqual(sword.notches, 1, "weapon smashing should add one Notch")

    local brittleWeapon = inventory.createItem({ name = "Brittle Knife", weaponType = "dagger", durability = 1 })
    local destroyedWeapon = system:useItemOnPOI(brittleWeapon, {
        id = "jammed_box",
        name = "Jammed Box",
        breakable = true,
    }, itemInteraction.INTERACTION_TYPES.BREAK, {})
    assertTrue(destroyedWeapon.itemDestroyed and brittleWeapon.destroyed,
        "weapon smashing should Destroy a weapon with no durability left")
end

function checkManaclesItemRestraint()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local actor = base_entity.createEntity({
        id = "pc_manacles_user",
        name = "Manacles User",
        isPC = true,
        cups = 0,
    })
    actor.inventory = inventory.createInventory()
    local manacles = inventory.createItemFromTemplate("manacles")
    actor.inventory:addItem(manacles, inventory.LOCATIONS.HANDS)

    local captive = base_entity.createEntity({
        id = "npc_manacles_captive",
        name = "Captured Brigand",
        isPC = false,
        health = 1,
        defense = 0,
    })
    captive.kith = true
    local restrained = resolver:resolve({
        actor = actor,
        target = captive,
        card = { name = "Ten of Cups", value = 10, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = manacles.id,
        targetInitiative = 5,
    })
    assertTrue(restrained.success, "manacles should restrain a beaten person target")
    assertTrue(captive.conditions.restrained and captive.conditions.manacled and captive.conditions.rooted,
        "manacles should mark the target restrained, manacled, and rooted")
    assertTrue(captive.readyForCityReward and captive.canTurnInForReward,
        "manacled targets should be marked as haulable to the City for rewards")
    assertTrue(manacles.inUseAsRestraint and manacles.restrainingTargetId == captive.id,
        "used manacles should be committed to the restrained target")
    assertTrue(actor.inventory:findItem(manacles.id) ~= nil, "manacles should not be consumed like a thrown item")

    local secondCaptive = base_entity.createEntity({
        id = "npc_second_manacles_captive",
        name = "Second Brigand",
        isPC = false,
        health = 1,
        defense = 0,
    })
    secondCaptive.kith = true
    local reused = resolver:resolve({
        actor = actor,
        target = secondCaptive,
        card = { name = "King of Cups", value = 14, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = manacles.id,
        targetInitiative = 1,
    })
    assertTrue(not reused.success, "manacles already holding a captive should not restrain a second target")
    assertTrue(not secondCaptive.conditions.restrained, "failed manacle reuse should not restrain the second target")

    local spareManacles = inventory.createItemFromTemplate("manacles")
    actor.inventory:addItem(spareManacles, inventory.LOCATIONS.HANDS)
    local chest = {
        id = "chest_not_person",
        name = "Chest",
        properties = { object = true },
    }
    local noEffect = resolver:resolve({
        actor = actor,
        target = chest,
        card = { name = "Nine of Cups", value = 9, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = spareManacles.id,
        targetInitiative = 1,
    })
    assertTrue(not noEffect.success, "manacles should not restrain object targets")
    assertTrue(hasValue(noEffect.effects, "manacles_no_effect"),
        "object manacle attempts should report the no-effect path")
end

function checkIronSpikesGearUse()
    local itemInteraction = require('logic.item_interaction')
    local system = itemInteraction.createItemInteractionSystem({
        eventBus = events.createEventBus(),
    })
    local spikes = inventory.createItemFromTemplate("iron_spikes")
    assertTrue(system:canPerform(spikes, itemInteraction.INTERACTION_TYPES.WEDGE),
        "iron spikes should be selectable for wedging doors")
    assertTrue(system:canPerform(spikes, itemInteraction.INTERACTION_TYPES.PITON),
        "iron spikes should be selectable as climbing pitons")

    local closedDoor = {
        id = "oaken_sally_door",
        name = "Oaken Sally Door",
        type = "door",
        state = "closed",
    }
    local wedged = system:useItemOnPOI(spikes, closedDoor, itemInteraction.INTERACTION_TYPES.WEDGE, {})
    assertTrue(wedged.success, "iron spikes should wedge a closed door")
    assertTrue(closedDoor.wedgedClosed and closedDoor.openBlocked and closedDoor.properties.spikedClosed,
        "wedged doors should record blocked-open state")
    assertEqual(closedDoor.state, "wedged", "wedged doors should expose a wedged state")
    assertEqual(spikes.quantity, 5, "wedging should spend one spike from the stack")
    assertTrue(not spikes.destroyed, "spending one spike should not destroy a nonempty spike stack")

    local openDoor = {
        id = "open_gallery_gate",
        name = "Open Gallery Gate",
        type = "gate",
        state = "open",
        open = true,
    }
    local blockedWedge = system:useItemOnPOI(spikes, openDoor, itemInteraction.INTERACTION_TYPES.WEDGE, {})
    assertTrue(not blockedWedge.success, "open doors should need to be closed before wedging")
    assertEqual(spikes.quantity, 5, "failed wedging should not spend a spike")

    local cliff = {
        id = "slick_chimney_wall",
        name = "Slick Chimney Wall",
        type = "wall",
        sheer = true,
        properties = {},
    }
    local pitoned = system:useItemOnPOI(spikes, cliff, itemInteraction.INTERACTION_TYPES.PITON, {})
    assertTrue(pitoned.success, "iron spikes should serve as climbing pitons")
    assertTrue(cliff.climbingAnchor and cliff.climbAssisted and cliff.properties.climbingAnchor,
        "pitoned climb surfaces should record climbing anchor state")
    assertEqual(spikes.quantity, 4, "setting a piton should spend one spike from the stack")

    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local actor = base_entity.createEntity({
        id = "pc_spike_user",
        name = "Spike User",
        isPC = true,
    })
    actor.inventory = inventory.createInventory()
    local heldSpikes = inventory.createItemFromTemplate("iron_spikes")
    actor.inventory:addItem(heldSpikes, inventory.LOCATIONS.HANDS)

    local challengeDoor = {
        id = "challenge_oak_door",
        name = "Challenge Oak Door",
        type = "door",
        state = "closed",
    }
    local challengeWedge = resolver:resolve({
        actor = actor,
        target = challengeDoor,
        card = { name = "Three of Cups", value = 3, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = heldSpikes.id,
        intent = "wedge",
    })
    assertTrue(challengeWedge.success, "Use Item should wedge doors with held iron spikes")
    assertTrue(hasValue(challengeWedge.effects, "iron_spike_wedged"),
        "resolver iron spike wedge should report its effect")
    assertTrue(challengeDoor.wedgedClosed and challengeDoor.openBlocked,
        "resolver wedge should block the door from opening")
    assertEqual(heldSpikes.quantity, 5, "resolver wedge should spend one held spike")
    assertTrue(actor.inventory:findItem(heldSpikes.id) ~= nil,
        "a nonempty spike stack should remain in inventory after one use")

    local challengeWall = {
        id = "challenge_cliff_wall",
        name = "Challenge Cliff Wall",
        type = "wall",
        vertical = true,
        properties = {},
    }
    local challengePiton = resolver:resolve({
        actor = actor,
        target = challengeWall,
        card = { name = "Four of Cups", value = 4, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = heldSpikes.id,
        intent = "piton",
    })
    assertTrue(challengePiton.success, "Use Item should set climbing pitons with held iron spikes")
    assertTrue(hasValue(challengePiton.effects, "iron_spike_piton"),
        "resolver piton use should report its effect")
    assertTrue(challengeWall.climbingAnchor and challengeWall.properties.climbAssisted,
        "resolver piton should mark the target surface as assisted")
    assertEqual(heldSpikes.quantity, 4, "resolver piton should spend one held spike")

    actor.swords = 4
    local undead = base_entity.createEntity({
        id = "npc_spike_staked_zombie",
        name = "Spike Staked Zombie",
        isPC = false,
        tags = { "undead", "zombie" },
        conditions = {},
    })
    undead.undead = true
    local staked = resolver:resolve({
        actor = actor,
        target = undead,
        card = { name = "Seven of Swords", value = 7, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = heldSpikes.id,
        intent = "stake_undead",
        targetInitiative = 5,
    })
    assertTrue(staked.success, "Use Item should drive iron spikes through undead hearts")
    assertEqual(staked.itemUseAttribute, "swords", "staking undead with iron spikes should use Swords")
    assertTrue(hasValue(staked.effects, "iron_spike_undead_heart") and hasValue(staked.effects, "undead_staked"),
        "undead staking should report the iron spike heart effect")
    assertTrue(undead.staked and undead.undeadHeartStaked and undead.conditions.rooted,
        "staked undead should be marked as pinned and heart-staked")
    assertTrue(undead.preventUndeadRise and undead.cannotRiseAsUndead,
        "staked undead should prevent later undead rising")
    assertEqual(heldSpikes.quantity, 3, "staking undead should spend one held spike")

    local livingTarget = base_entity.createEntity({
        id = "npc_spike_living_target",
        name = "Living Spike Target",
        isPC = false,
        conditions = {},
    })
    local nonUndead = resolver:resolve({
        actor = actor,
        target = livingTarget,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = heldSpikes.id,
        intent = "stake_undead",
        targetInitiative = 1,
    })
    assertTrue(not nonUndead.success, "iron spike heart-staking should reject living targets")
    assertTrue(hasValue(nonUndead.effects, "iron_spike_no_effect"),
        "living target spike attempts should report no effect")
    assertEqual(heldSpikes.quantity, 3, "failed undead staking should not spend a spike")

    local preventedEvents = {}
    local preventBus = events.createEventBus()
    preventBus:on(events.EVENTS.UNDEAD_RAISED, function(payload)
        preventedEvents[#preventedEvents + 1] = payload
    end)
    local preventedCorpse = base_entity.createEntity({
        id = "pc_spiked_corpse",
        name = "Spiked Corpse",
        isPC = true,
        conditions = { dead = true },
    })
    preventedCorpse:scheduleUndeadRise("zombie", 0, {
        reason = "iron_spike_heart",
        bodyDestroyed = true,
    })
    local preventManager = watch_manager.createWatchManager({
        eventBus = preventBus,
        guild = { preventedCorpse },
    })
    local raised = preventManager:raiseScheduledUndead()
    assertEqual(#raised, 0, "body-destroyed undead schedules should not raise a zombie")
    assertEqual(#preventedEvents, 0, "prevented undead schedules should not emit an undead-raised event")
    assertTrue(preventedCorpse.undeadRise.raised and preventedCorpse.undeadRise.prevented,
        "prevented undead schedules should be closed out after the watch manager sees them")
end

function checkFlintAndTinderFireStarting()
    local itemInteraction = require('logic.item_interaction')
    local system = itemInteraction.createItemInteractionSystem({
        eventBus = events.createEventBus(),
    })
    local flint = inventory.createItemFromTemplate("flint_and_tinder")
    assertTrue(system:canPerform(flint, itemInteraction.INTERACTION_TYPES.LIGHT),
        "flint and tinder should be selectable for lighting fires")

    local brazier = {
        id = "cold_brazier",
        name = "Cold Brazier",
        type = "brazier",
        state = "unlit",
        properties = {
            flammable = true,
        },
    }
    local litBrazier = system:useItemOnPOI(flint, brazier, itemInteraction.INTERACTION_TYPES.LIGHT, {})
    assertTrue(litBrazier.success, "flint and tinder should start an unlit brazier")
    assertEqual(brazier.state, "lit", "lit fire targets should expose lit state")
    assertTrue(brazier.properties.isLit and brazier.properties.fireStarted,
        "fire-started POIs should record lit metadata")
    assertTrue(not flint.destroyed, "flint and tinder should not be consumed by starting a fire")

    local firewoodPile = {
        id = "dry_firewood_pile",
        name = "Dry Firewood Pile",
        type = "campfire",
        state = "unlit",
        properties = {
            firewood = true,
        },
    }
    local campfire = system:useItemOnPOI(flint, firewoodPile, itemInteraction.INTERACTION_TYPES.LIGHT, {})
    assertTrue(campfire.success, "flint and tinder should start firewood as a campfire")
    assertTrue(firewoodPile.campfire and firewoodPile.properties.campfire,
        "started firewood should be marked as a campfire")

    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local actor = base_entity.createEntity({
        id = "pc_flint_user",
        name = "Flint User",
        isPC = true,
    })
    actor.inventory = inventory.createInventory()
    local heldFlint = inventory.createItemFromTemplate("flint_and_tinder")
    actor.inventory:addItem(heldFlint, inventory.LOCATIONS.HANDS)
    local unlitTorch = inventory.createItemFromTemplate("torch")
    unlitTorch.properties.isLit = false
    unlitTorch.properties.extinguished = true

    local started = resolver:resolve({
        actor = actor,
        target = unlitTorch,
        card = { name = "Two of Cups", value = 2, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = heldFlint.id,
    })
    assertTrue(started.success, "Use Item should start fires with held flint and tinder")
    assertTrue(hasValue(started.effects, "fire_started"), "fire-starting should report its effect")
    assertTrue(unlitTorch.properties.isLit and not unlitTorch.properties.extinguished,
        "resolver fire-starting should relight the target")
    assertTrue(actor.inventory:findItem(heldFlint.id) ~= nil,
        "held flint and tinder should remain available after use")
end

local function checkHarvestableCorpseFeatures()
    local manager = room_manager.createRoomManager({ eventBus = events.createEventBus() })
    manager:registerRoom(room_manager.createRoomInstance({
        id = "alchemy_lab",
        name = "Alchemy Lab",
        description = "A room prepared for reagent tests.",
        features = {},
    }, "alchemy_lab"))

    local spider = entity_factory.createEntity("brain_spider")
    spider.id = "dead_spider_for_corpse"
    spider.conditions.dead = true
    manager:addMob("alchemy_lab", spider.id)

    local corpse = manager:addCorpseForEntity("alchemy_lab", spider, {
        currentWatch = 2,
    })
    assertTrue(corpse ~= nil, "dead alchemy-bearing monsters should create corpse POIs")
    assertEqual(corpse.type, "corpse", "corpse feature should use corpse type")
    assertTrue(corpse.freshCorpse, "generated corpse should start fresh")
    assertEqual(corpse.defeatedEntityId, spider.id, "corpse should remember defeated entity id")
    assertEqual(corpse.defeatedAtWatch, 2, "corpse should record defeat watch for spoilage")
    assertEqual(corpse.alchemy.reagentTemplateId, "brain_spider_reagent", "corpse should carry reagent yield data")
    assertEqual(#manager:getMobs("alchemy_lab"), 0, "defeated mob should be removed from room mob list")
    assertEqual(manager:getFeature("alchemy_lab", corpse.id), corpse, "generated corpse should be registered as a room feature")

    local duplicate = manager:addCorpseForEntity("alchemy_lab", spider, {
        currentWatch = 2,
    })
    assertEqual(duplicate, corpse, "repeated defeat events should not duplicate corpse POIs")
    assertEqual(#manager:getFeaturesByType("alchemy_lab", "corpse"), 1, "room should keep one corpse feature per defeated entity")

    corpse.alchemy.harvestedCount = 0
    assertTrue(spider.alchemy.harvestedCount == nil, "corpse alchemy data should not mutate the source blueprint copy")

    local system = interaction.createInteractionSystem({})
    local actions = system:getValidActions(corpse)
    local sawHarvest = false
    for _, action in ipairs(actions) do
        if action.action == "harvest_reagent" then
            sawHarvest = true
            break
        end
    end
    assertTrue(sawHarvest, "generated monster corpses should expose harvest interaction")

    local corpseHarvester = base_entity.createEntity({
        id = "pc_corpse_harvester",
        name = "Corpse Harvester",
        isPC = true,
        talents = {
            alchemy = { mastered = true },
        },
    })
    corpseHarvester.inventory = inventory.createInventory()
    corpseHarvester.inventory:addItem(inventory.createItemFromTemplate("hermetic_bottle"), inventory.LOCATIONS.PACK)
    local harvestedOk, harvestResult, corpseHarvest = alchemy.resolveHarvestReagent(corpseHarvester, corpse, {
        watchSpent = true,
        currentWatch = 2,
        eventBus = events.createEventBus(),
    })
    assertTrue(harvestedOk, "generated corpse POIs should be harvestable")
    assertEqual(harvestResult, "reagent_harvested", "generated corpse POI harvest should report success")
    assertEqual(corpse.state, "harvested", "harvested corpse POIs should persist harvested state")
    assertTrue(corpse.reagentsHarvested and corpse.reagentsDepleted and corpse.freshCorpse == false,
        "harvested corpse POIs should no longer present as fresh reagent sources")
    assertEqual(corpseHarvest.sourceState.sourceId, corpse.id,
        "harvested corpse POI result should report source cleanup state")

    local zombie = entity_factory.createEntity("zombie")
    zombie.id = "dead_zombie_no_reagent"
    zombie.conditions.dead = true
    local noCorpse, reason = manager:addCorpseForEntity("alchemy_lab", zombie, {
        currentWatch = 2,
    })
    assertTrue(noCorpse == nil, "non-reagent creatures should not create harvestable corpse POIs")
    assertEqual(reason, "no_harvestable_reagents", "missing reagent data should explain skipped corpse POI")

    local wraith = entity_factory.createEntity("wraith")
    wraith.id = "dead_wraith_no_reagent"
    wraith.conditions.dead = true
    noCorpse, reason = manager:addCorpseForEntity("alchemy_lab", wraith, {
        currentWatch = 2,
    })
    assertTrue(noCorpse == nil, "explicit no-reagent creatures should not create harvestable corpse POIs")
    assertEqual(reason, "no_harvestable_reagents", "no-reagent alchemy data should explain skipped corpse POI")

    local noReagentActions = system:getValidActions({
        id = "wraith_remnant",
        type = "corpse",
        alchemy = {
            noReagent = true,
            reason = "no_guts",
        },
    })
    for _, action in ipairs(noReagentActions) do
        assertTrue(action.action ~= "harvest_reagent",
            "explicit no-reagent corpses should not expose harvest interaction")
    end

    local livingSpider = entity_factory.createEntity("brain_spider")
    livingSpider.id = "living_spider_no_corpse"
    noCorpse, reason = manager:addCorpseForEntity("alchemy_lab", livingSpider, {
        currentWatch = 2,
    })
    assertTrue(noCorpse == nil, "living monsters should not create corpse POIs")
    assertEqual(reason, "entity_not_dead", "living source should explain skipped corpse POI")
end

local function checkAlchemyMenagerieReagentPurchase()
    local buyer = base_entity.createEntity({
        id = "pc_menagerie_buyer",
        name = "Menagerie Buyer",
        isPC = true,
    })
    buyer.gold = 50
    buyer.inventory = inventory.createInventory()

    local bus = events.createEventBus()
    local emitted = nil
    bus:on(events.EVENTS.ALCHEMY_REAGENT_PURCHASED, function(data)
        emitted = data
    end)

    local ok, result, purchase = alchemy.resolveMenagerieReagentPurchase(buyer, {
        source = "brain_spider",
        quantity = 2,
    }, { eventBus = bus })
    assertTrue(ok, "menagerie purchase should buy authored reagent templates")
    assertEqual(result, "reagent_purchased", "menagerie purchase should report success")
    assertEqual(purchase.cost, 50, "menagerie reagents should cost 25g each")
    assertEqual(buyer.gold, 0, "menagerie purchase should spend PC gold")
    assertEqual(#purchase.reagents, 2, "menagerie purchase should create one reagent per purchase")
    assertTrue(emitted and emitted.quantity == 2, "menagerie purchase should emit purchase details")
    local purchasedCount = buyer.inventory:countItemsByPredicate(function(item)
        return item.templateId == "brain_spider_reagent" and
            item.properties.cityPurchased == true and
            item.properties.purchasedAt == "Master Underhill's Menagerie"
    end)
    assertEqual(purchasedCount, 2, "menagerie purchase should add bottled reagents to inventory")

    local stockBuyer = base_entity.createEntity({
        id = "pc_stock_menagerie_buyer",
        name = "Stock Menagerie Buyer",
        isPC = true,
    })
    stockBuyer.gold = 60
    stockBuyer.inventory = inventory.createInventory()
    local menagerieStock = {
        lamprey_gland = {
            id = "lamprey_gland",
            name = "Lamprey Gland",
            reagentTemplateId = "slime_reagent",
            costPerReagent = 30,
            quantityAvailable = 2,
            locationName = "Underhill's wet cabinet",
            properties = {
                menagerieShelf = "wet cabinet",
            },
        },
    }
    ok, result, purchase = alchemy.resolveMenagerieReagentPurchase(stockBuyer, {
        stockId = "lamprey_gland",
        quantity = 2,
    }, {
        stock = menagerieStock,
        eventBus = events.createEventBus(),
    })
    assertTrue(ok, "menagerie purchase should support authored stock entries")
    assertEqual(purchase.cost, 60, "authored menagerie stock should set custom reagent prices")
    assertEqual(purchase.stockId, "lamprey_gland", "menagerie purchase should report stock id")
    assertEqual(purchase.stockRemaining, 0, "menagerie purchase should decrement finite stock")
    assertEqual(menagerieStock.lamprey_gland.quantityAvailable, 0,
        "menagerie purchase should update the mutable stock table")
    assertTrue(stockBuyer.inventory:findItemByPredicate(function(item)
        return item.templateId == "slime_reagent" and
            item.properties.menagerieStockId == "lamprey_gland" and
            item.properties.purchaseCost == 30 and
            item.properties.menagerieShelf == "wet cabinet" and
            item.properties.purchasedAt == "Underhill's wet cabinet"
    end) ~= nil, "authored stock reagents should preserve stock metadata")

    local emptyStockBuyer = base_entity.createEntity({
        id = "pc_empty_stock_menagerie_buyer",
        name = "Empty Stock Menagerie Buyer",
        isPC = true,
    })
    emptyStockBuyer.gold = 30
    emptyStockBuyer.inventory = inventory.createInventory()
    ok, result = alchemy.resolveMenagerieReagentPurchase(emptyStockBuyer, {
        stockId = "lamprey_gland",
    }, {
        stock = menagerieStock,
        eventBus = events.createEventBus(),
    })
    assertTrue(not ok, "menagerie purchase should reject depleted authored stock")
    assertEqual(result, "Reagent stock unavailable", "depleted menagerie stock should explain failure")
    assertEqual(emptyStockBuyer.gold, 30, "depleted stock purchase should not spend gold")

    local coinBuyer = base_entity.createEntity({
        id = "pc_coin_menagerie_buyer",
        name = "Coin Menagerie Buyer",
        isPC = true,
    })
    coinBuyer.gold = 10
    coinBuyer.inventory = inventory.createInventory()
    coinBuyer.inventory:addItem(inventory.createItemFromTemplate("gold_coins_15"), inventory.LOCATIONS.PACK)
    ok, result, purchase = alchemy.resolveMenagerieReagentPurchase(coinBuyer, {
        reagentTemplateId = "slime_reagent",
    }, { eventBus = events.createEventBus() })
    assertTrue(ok, "menagerie purchase should combine PC gold and carried coin stacks")
    assertEqual(coinBuyer.gold, 0, "menagerie purchase should empty numeric gold first")
    assertEqual(alchemy.getGold(coinBuyer), 0, "menagerie purchase should spend carried coin stack remainder")
    assertTrue(coinBuyer.inventory:findItemByPredicate(function(item)
        return item.templateId == "slime_reagent"
    end) ~= nil, "menagerie purchase should add selected reagent")

    local poorBuyer = base_entity.createEntity({
        id = "pc_poor_menagerie_buyer",
        name = "Poor Menagerie Buyer",
        isPC = true,
    })
    poorBuyer.gold = 24
    poorBuyer.inventory = inventory.createInventory()
    ok, result = alchemy.resolveMenagerieReagentPurchase(poorBuyer, {
        source = "brain_spider",
    }, { eventBus = events.createEventBus() })
    assertTrue(not ok, "menagerie purchase should require 25g per reagent")
    assertEqual(result, "Not enough gold", "insufficient gold should explain menagerie purchase failure")
    assertEqual(poorBuyer.gold, 24, "failed menagerie purchase should not spend gold")
    assertEqual(#poorBuyer.inventory.pack, 0, "failed menagerie purchase should not add reagents")

    local crampedBuyer = base_entity.createEntity({
        id = "pc_cramped_menagerie_buyer",
        name = "Cramped Menagerie Buyer",
        isPC = true,
    })
    crampedBuyer.gold = 25
    crampedBuyer.inventory = inventory.createInventory({ packSlots = 0 })
    ok, result = alchemy.resolveMenagerieReagentPurchase(crampedBuyer, {
        source = "brain_spider",
    }, { eventBus = events.createEventBus() })
    assertTrue(not ok, "menagerie purchase should need inventory room")
    assertEqual(result, "insufficient_slots", "full pack should explain menagerie purchase failure")
    assertEqual(crampedBuyer.gold, 25, "failed slot check should not spend gold")

    ok, result = alchemy.resolveMenagerieReagentPurchase(buyer, {
        source = "wraith",
    }, { eventBus = events.createEventBus() })
    assertTrue(not ok, "menagerie purchase should reject unknown reagent sources")
    assertEqual(result, "Unknown alchemical reagent", "unknown menagerie source should explain failure")
end

local function checkAlchemyReagentSale()
    local seller = base_entity.createEntity({
        id = "pc_reagent_seller",
        name = "Reagent Seller",
        isPC = true,
    })
    seller.gold = 0
    seller.inventory = inventory.createInventory()
    local spiderReagent = inventory.createItemFromTemplate("brain_spider_reagent")
    seller.inventory:addItem(spiderReagent, inventory.LOCATIONS.PACK)

    local bus = events.createEventBus()
    local emitted = nil
    bus:on(events.EVENTS.ALCHEMY_REAGENT_SOLD, function(data)
        emitted = data
    end)

    local ok, result, sale = alchemy.resolveReagentSale(seller, {
        itemId = spiderReagent.id,
    }, { eventBus = bus })
    assertTrue(ok, "Alchemists' Hall should buy bottled reagents")
    assertEqual(result, "reagent_sold", "reagent sale should report success")
    assertEqual(sale.value, 20, "brain spider reagent should use 5g x total HD sale value")
    assertEqual(seller.gold, 20, "reagent sale should add gold to seller")
    assertTrue(not seller.inventory:findItem(spiderReagent.id), "sold reagent should leave inventory")
    assertTrue(emitted and emitted.reagent == spiderReagent, "reagent sale should emit sold reagent details")

    local gmPricedSeller = base_entity.createEntity({
        id = "pc_gm_priced_reagent_seller",
        name = "GM Priced Reagent Seller",
        isPC = true,
    })
    gmPricedSeller.gold = 5
    gmPricedSeller.inventory = inventory.createInventory()
    local slimeReagent = inventory.createItemFromTemplate("slime_reagent")
    gmPricedSeller.inventory:addItem(slimeReagent, inventory.LOCATIONS.PACK)
    ok, result, sale = alchemy.resolveReagentSale(gmPricedSeller, {
        source = "slime",
        price = 37,
    }, { eventBus = events.createEventBus() })
    assertTrue(ok, "reagent sale should accept GM-adjudicated value")
    assertEqual(sale.value, 37, "explicit GM value should override fallback HD value")
    assertEqual(gmPricedSeller.gold, 42, "explicit-value reagent sale should pay the seller")

    local harvestedSeller = base_entity.createEntity({
        id = "pc_harvested_reagent_seller",
        name = "Harvested Reagent Seller",
        isPC = true,
        talents = {
            alchemy = { mastered = true },
        },
    })
    harvestedSeller.gold = 0
    harvestedSeller.inventory = inventory.createInventory()
    harvestedSeller.inventory:addItem(inventory.createItemFromTemplate("hermetic_bottle"), inventory.LOCATIONS.PACK)
    local queen = entity_factory.createEntity("brain_spider_queen")
    queen.conditions.dead = true
    local harvestOk, _, harvest = alchemy.resolveHarvestReagent(harvestedSeller, queen, {
        watchSpent = true,
        currentWatch = 0,
        eventBus = events.createEventBus(),
    })
    assertTrue(harvestOk, "queen reagent should be harvestable before sale")
    assertEqual(harvest.reagent.properties.sourceTotalHD, 6, "harvest should record source total HD")
    ok, result, sale = alchemy.resolveReagentSale(harvestedSeller, {
        itemId = harvest.reagent.id,
    }, { eventBus = events.createEventBus() })
    assertTrue(ok, "harvested reagent should be saleable")
    assertEqual(sale.value, 30, "harvested reagent should sell for 5g x source total HD")
    assertEqual(harvestedSeller.gold, 30, "harvested reagent sale should pay fallback value")

    local unknownValueSeller = base_entity.createEntity({
        id = "pc_unknown_value_reagent_seller",
        name = "Unknown Value Reagent Seller",
        isPC = true,
    })
    unknownValueSeller.gold = 0
    unknownValueSeller.inventory = inventory.createInventory()
    local unknown = inventory.createItem({
        name = "Hermetic Bottle: Nameless Reagent",
        type = "reagent",
        properties = {
            reagent = true,
            hermeticBottle = true,
        },
    })
    unknownValueSeller.inventory:addItem(unknown, inventory.LOCATIONS.PACK)
    ok, result = alchemy.resolveReagentSale(unknownValueSeller, {
        itemId = unknown.id,
    }, { eventBus = events.createEventBus() })
    assertTrue(not ok, "reagent sale should require a known value or GM price")
    assertEqual(result, "Reagent value unknown", "unknown reagent value should explain sale failure")
    assertTrue(unknownValueSeller.inventory:findItem(unknown.id) ~= nil, "failed reagent sale should not remove item")

    local looseSeller = base_entity.createEntity({
        id = "pc_loose_reagent_seller",
        name = "Loose Reagent Seller",
        isPC = true,
    })
    looseSeller.inventory = inventory.createInventory()
    local loose = inventory.createItem({
        name = "Loose Monster Guts",
        type = "reagent",
        properties = {
            reagent = true,
            saleValue = 5,
        },
    })
    looseSeller.inventory:addItem(loose, inventory.LOCATIONS.PACK)
    ok, result = alchemy.resolveReagentSale(looseSeller, {
        itemId = loose.id,
    }, { eventBus = events.createEventBus() })
    assertTrue(not ok, "reagent sale should require hermetic preservation")
    assertEqual(result, "Requires bottled reagent", "unbottled reagent should explain sale failure")
end

local function checkCityPhaseDeathAndTaxes()
    local purseAndCoins = base_entity.createEntity({
        id = "pc_city_tax_purse",
        name = "City Tax Purse",
        isPC = true,
    })
    purseAndCoins.gold = 101
    purseAndCoins.inventory = inventory.createInventory()
    local coinStack = inventory.createItemFromTemplate("gold_coins_15")
    local jewel = inventory.createItemFromTemplate("ruby_ring")
    purseAndCoins.inventory:addItem(coinStack, inventory.LOCATIONS.PACK)
    purseAndCoins.inventory:addItem(jewel, inventory.LOCATIONS.PACK)

    local coinOnly = base_entity.createEntity({
        id = "pc_city_tax_coins",
        name = "City Tax Coins",
        isPC = true,
    })
    coinOnly.inventory = inventory.createInventory()
    local coinOnlyStack = inventory.createItemFromTemplate("gold_coins_15")
    coinOnly.inventory:addItem(coinOnlyStack, inventory.LOCATIONS.PACK)

    local broke = base_entity.createEntity({
        id = "pc_city_tax_broke",
        name = "City Tax Broke",
        isPC = true,
    })
    broke.gold = 0
    broke.inventory = inventory.createInventory()

    local bus = events.createEventBus()
    local emitted = nil
    bus:on(events.EVENTS.CITY_DEATH_AND_TAXES_RESOLVED, function(data)
        emitted = data
    end)

    local controller = city_phase.createCityPhaseController({
        eventBus = bus,
        guild = { purseAndCoins, coinOnly, broke },
    })

    local taxOptions = controller:getDeathAndTaxesOptions({ taxRate = 0.01 })
    assertEqual(taxOptions.rate, 0.5, "Death and taxes options should expose the fixed tax rate")
    assertEqual(taxOptions.totalTax, 65, "Death and taxes options should preview guild tax totals")
    assertEqual(taxOptions.details[1].startingGold, 116,
        "Death and taxes options should count purse gold plus carried coin stacks")
    assertEqual(taxOptions.details[1].taxPaid, 58,
        "Death and taxes options should preview half of carried liquid gold")
    assertEqual(taxOptions.details[1].projectedRemainingGold, 58,
        "Death and taxes options should preview remaining liquid gold")
    assertEqual(taxOptions.details[1].liquidItemOptions[1].totalGold, 15,
        "Death and taxes options should expose carried liquid coin stacks")
    assertEqual(taxOptions.details[1].exemptTreasureOptions[1].itemId, jewel.id,
        "Death and taxes options should expose non-liquid treasure exemptions")
    assertEqual(currency.getGold(purseAndCoins), 116,
        "Death and taxes options should not spend gold during preview")

    local ok, result, detail = controller:resolveDeathAndTaxes({ taxRate = 0.01 })
    assertTrue(ok, "City Phase should resolve Death and taxes")
    assertEqual(result, "death_and_taxes_resolved", "Death and taxes should report completion")
    assertEqual(detail.rate, 0.5, "Death and taxes should ignore caller-supplied tax rates")
    assertEqual(detail.totalTax, 65, "Death and taxes should collect 50% of liquid gold from the guild")
    assertEqual(detail.details[1].startingGold, 116, "Death and taxes should count purse gold plus carried coins")
    assertEqual(detail.details[1].taxPaid, 58, "Death and taxes should tax half of carried liquid gold")
    assertEqual(currency.getGold(purseAndCoins), 58, "Death and taxes should leave the untaxed half")
    assertEqual(purseAndCoins.gold, 43, "Death and taxes should spend numeric purse gold before carried coin stacks")
    assertTrue(purseAndCoins.inventory:findItem(jewel.id) ~= nil, "Death and taxes should not tax non-liquid treasure")
    assertEqual(detail.details[2].taxPaid, 7, "Death and taxes should round odd half-coin taxes down")
    assertEqual(currency.getGold(coinOnly), 8, "Death and taxes should update carried coin stacks")
    assertEqual(coinOnlyStack.quantity, 8, "Death and taxes should decrement stack quantity for carried coins")
    assertEqual(detail.details[3].taxPaid, 0, "Death and taxes should tolerate penniless adventurers")
    assertTrue(emitted and emitted.totalTax == 65, "Death and taxes should emit city tax details")

    ok, result = controller:resolveDeathAndTaxes()
    assertTrue(not ok, "Death and taxes should only resolve once per City Phase controller")
    assertEqual(result, "Death and taxes already resolved", "repeat Death and taxes should explain existing resolution")
    taxOptions = controller:getDeathAndTaxesOptions()
    assertTrue(taxOptions.disabled, "Death and taxes options should disable already-resolved controllers")
    assertEqual(taxOptions.unavailableReason, "Death and taxes already resolved",
        "Death and taxes options should explain repeat tax collection")

    local smuggler = base_entity.createEntity({
        id = "pc_city_tax_smuggler",
        name = "City Tax Smuggler",
        isPC = true,
    })
    smuggler.gold = 100
    smuggler.inventory = inventory.createInventory()
    local caught = base_entity.createEntity({
        id = "pc_city_tax_caught",
        name = "City Tax Caught",
        isPC = true,
    })
    caught.gold = 100
    caught.inventory = inventory.createInventory()
    local evasionController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { smuggler, caught },
    })
    taxOptions = evasionController:getDeathAndTaxesOptions({
        taxEvasion = {
            pc_city_tax_smuggler = {
                hiddenGold = 40,
                bribeGold = 10,
                method = "false-bottom chest",
                success = true,
            },
            pc_city_tax_caught = {
                hiddenGold = 40,
                bribeGold = 10,
                bribeAccepted = false,
                detected = true,
                method = "boot coins",
            },
        },
    })
    assertEqual(taxOptions.totalTax, 80, "Death and taxes options should preview smuggling-adjusted tax totals")
    assertEqual(taxOptions.totalBribes, 10, "Death and taxes options should preview accepted bribes")
    assertEqual(taxOptions.details[1].taxableGold, 60,
        "Death and taxes options should preview successfully hidden gold")
    assertEqual(taxOptions.details[1].consequencePreview.id, "tax_evasion_success",
        "Death and taxes options should preview successful evasion audit records")
    assertEqual(taxOptions.details[2].taxableGold, 100,
        "Death and taxes options should preview detected smuggling as fully taxable")
    assertEqual(taxOptions.details[2].consequencePreview.id, "tax_evasion_detected",
        "Death and taxes options should preview detected evasion legal trouble")
    ok, result, detail = evasionController:resolveDeathAndTaxes({
        taxEvasion = {
            pc_city_tax_smuggler = {
                hiddenGold = 40,
                bribeGold = 10,
                method = "false-bottom chest",
                success = true,
            },
            pc_city_tax_caught = {
                hiddenGold = 40,
                bribeGold = 10,
                bribeAccepted = false,
                detected = true,
                method = "boot coins",
            },
        },
    })
    assertTrue(ok, "Death and taxes should resolve GM-adjudicated smuggling")
    assertEqual(detail.totalTax, 80, "tax evasion should reduce only successful smuggler's taxable gold")
    assertEqual(detail.totalBribes, 10, "accepted All-Watch bribes should be reported separately")
    assertEqual(detail.details[1].taxableGold, 60, "successful smuggling should hide declared liquid gold")
    assertEqual(detail.details[1].taxPaid, 30, "successful smuggling should tax only visible liquid gold")
    assertEqual(detail.details[1].bribePaid, 10, "accepted smuggling bribe should be spent")
    assertEqual(currency.getGold(smuggler), 60, "smuggler should keep hidden half after tax and bribe")
    assertEqual(smuggler.taxEvasions[1].id, "tax_evasion_success",
        "successful smuggling should leave an audit record")
    assertEqual(detail.details[2].taxableGold, 100, "detected smuggling should not reduce taxable gold")
    assertEqual(detail.details[2].taxPaid, 50, "detected smuggling should pay the full tax")
    assertEqual(detail.details[2].bribePaid, 0, "rejected bribes should not be spent")
    assertEqual(currency.getGold(caught), 50, "caught smuggler should lose only the full tax")
    assertEqual(caught.legalTroubles[1].id, "tax_evasion_detected",
        "detected smuggling should create an All-Watch legal trouble record")
end

local function checkCityPhaseNoteworthyDeeds()
    local roster = {
        noteworthyDeeds = {
            { id = "first_lord", description = "First dungeon lord slain" },
            { id = "hidden_path", description = "New path through the Underworld forged" },
        },
        fame = 2,
    }
    local bus = events.createEventBus()
    local emitted = nil
    bus:on(events.EVENTS.CITY_NOTEWORTHY_DEEDS_RESOLVED, function(data)
        emitted = data
    end)

    local controller = city_phase.createCityPhaseController({
        eventBus = bus,
        guildRoster = roster,
    })

    local proposedDeeds = {
        { id = "golden_ghost", description = "Tomb of Golden Ghosts sealed", approved = true },
        { id = "ancient_gossip", description = "Learned strange old lore", approved = false },
    }
    local deedOptions = controller:getNoteworthyDeedsOptions({
        deeds = proposedDeeds,
    })
    assertEqual(deedOptions.step, city_phase.STEPS.NOTEWORTHY_DEEDS,
        "Noteworthy deed options should identify the City Phase step")
    assertEqual(deedOptions.previousFame, 2, "Noteworthy deed options should preview previous Fame")
    assertEqual(deedOptions.erased.id, "first_lord", "Noteworthy deed options should preview oldest deed erasure")
    assertEqual(#deedOptions.added, 1, "Noteworthy deed options should preview approved deeds")
    assertEqual(#deedOptions.rejected, 1, "Noteworthy deed options should preview rejected suggestions")
    assertEqual(deedOptions.proposedDeedOptions[2].unavailableReason, "Deed not approved",
        "Noteworthy deed options should explain rejected suggestions")
    assertEqual(deedOptions.projectedFame, 2, "Noteworthy deed options should preview projected Fame")
    assertEqual(deedOptions.activeDeeds[1].id, "hidden_path",
        "Noteworthy deed options should keep remaining old deeds active")
    assertEqual(deedOptions.activeDeeds[2].id, "golden_ghost",
        "Noteworthy deed options should preview approved new active deeds")
    assertEqual(roster.noteworthyDeeds[1].id, "first_lord",
        "Noteworthy deed options should not mutate the roster")

    local ok, result, detail = controller:resolveNoteworthyDeeds({
        deeds = proposedDeeds,
    })
    assertTrue(ok, "Noteworthy deeds should resolve as a City Phase step")
    assertEqual(result, "noteworthy_deeds_recorded", "approved new deeds should report roster update")
    assertEqual(detail.previousFame, 2, "Noteworthy deeds should record previous Fame")
    assertEqual(detail.erased.id, "first_lord", "Noteworthy deeds should erase the oldest active deed")
    assertEqual(#detail.added, 1, "Noteworthy deeds should add only GM-approved deeds")
    assertEqual(#detail.rejected, 1, "Noteworthy deeds should report rejected suggestions")
    assertEqual(roster.fame, 2, "Fame should equal active noteworthy deeds after aging and additions")
    assertEqual(roster.Fame, 2, "Noteworthy deeds should update roster Fame alias")
    assertEqual(roster.noteworthyDeeds[1].id, "hidden_path", "remaining old deeds should stay active")
    assertEqual(roster.noteworthyDeeds[2].id, "golden_ghost", "approved new deeds should be active")
    assertEqual(detail.fameReaction.id, "known_underworld",
        "Noteworthy deeds should frame Fame 2 as generally known in the Underworld")
    assertEqual(detail.fameReaction.dispositionFrame.bias, "recognition_only",
        "ordinary Fame should not force a starting Disposition bias")
    assertTrue(emitted and emitted.fame == 2, "Noteworthy deeds should emit roster details")

    ok, result = controller:resolveNoteworthyDeeds({
        deeds = { "Another praiseworthy deed" },
    })
    assertTrue(not ok, "Noteworthy deeds should only resolve once per City Phase controller")
    assertEqual(result, "Noteworthy deeds already resolved", "repeat Noteworthy deeds should explain existing resolution")
    deedOptions = controller:getNoteworthyDeedsOptions({
        deeds = { "Another praiseworthy deed" },
    })
    assertTrue(deedOptions.disabled, "Noteworthy deed options should disable after resolution")
    assertEqual(deedOptions.unavailableReason, "Noteworthy deeds already resolved",
        "Noteworthy deed options should explain repeat resolution")

    local quietRoster = {
        noteworthyDeeds = {
            { id = "old_glory", description = "Old glory" },
            { id = "older_glory", description = "Older glory" },
        },
        fame = 2,
    }
    local quietController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guildRoster = quietRoster,
    })
    deedOptions = quietController:getNoteworthyDeedsOptions()
    assertEqual(deedOptions.resultPreview, "noteworthy_deeds_aged",
        "Noteworthy deed options should preview no-accomplishment aging")
    assertEqual(deedOptions.erased.id, "old_glory",
        "Noteworthy deed options should preview old deed loss without new deeds")
    assertEqual(deedOptions.projectedFame, 1,
        "Noteworthy deed options should preview Fame loss when no deed replaces the oldest")
    ok, result, detail = quietController:resolveNoteworthyDeeds()
    assertTrue(ok, "Noteworthy deeds should resolve even with no new accomplishments")
    assertEqual(result, "noteworthy_deeds_aged", "no new deeds should report aging")
    assertEqual(detail.erased.id, "old_glory", "no-accomplishment return should still erase the oldest deed")
    assertEqual(quietRoster.fame, 1, "no-accomplishment return should lose 1 Fame when possible")

    local famousRoster = {
        noteworthyDeeds = {
            { id = "old_1", description = "Old deed one" },
            { id = "old_2", description = "Old deed two" },
            { id = "old_3", description = "Old deed three" },
            { id = "old_4", description = "Old deed four" },
            { id = "old_5", description = "Old deed five" },
        },
    }
    local famousController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guildRoster = famousRoster,
    })
    local famousDeeds = {
        { id = "dragon_slayer", description = "Dungeon lord dragon slain" },
        { id = "relic_reclaimed", description = "Potent relic reclaimed" },
    }
    local selectedDeedIds = { "old_2", "old_3", "old_4", "dragon_slayer", "relic_reclaimed" }
    deedOptions = famousController:getNoteworthyDeedsOptions({
        deeds = famousDeeds,
        selectedDeedIds = selectedDeedIds,
        fameTone = "heroic",
    })
    assertTrue(deedOptions.curationRequired,
        "Noteworthy deed options should flag curation when more than five deeds qualify")
    assertEqual(deedOptions.projectedFame, 5, "Noteworthy deed options should cap projected Fame at five")
    assertEqual(#deedOptions.activeDeeds, 5, "Noteworthy deed options should preview five kept deeds")
    assertEqual(deedOptions.dropped[1].id, "old_5",
        "Noteworthy deed options should preview selected-deed cap drops")
    assertEqual(deedOptions.fameReaction.dispositionFrame.bias, "more_favorable",
        "Noteworthy deed options should preview high-Fame Disposition framing")
    ok, result, detail = famousController:resolveNoteworthyDeeds({
        deeds = famousDeeds,
        selectedDeedIds = selectedDeedIds,
        fameTone = "heroic",
    })
    assertTrue(ok, "Noteworthy deeds should allow curation when more than five deeds qualify")
    assertEqual(famousRoster.fame, 5, "Fame should be capped at five active deeds")
    assertEqual(#famousRoster.noteworthyDeeds, 5, "noteworthy roster should keep only five active deeds")
    assertEqual(#detail.dropped, 1, "Noteworthy deeds should report deeds dropped by the five-deed cap")
    assertEqual(detail.dropped[1].id, "old_5", "selected deeds should determine which over-cap deed is dropped")
    assertEqual(detail.fameReaction.id, "famous_city", "Fame 5 should frame the guild as famous within the City")
    assertEqual(detail.fameReaction.dispositionFrame.bias, "more_favorable",
        "heroic high Fame should suggest more favorable starting Dispositions")
    assertEqual(detail.fameReaction.dispositionFrame.suggestedDisposition, disposition.DISPOSITIONS.TRUST,
        "heroic high Fame should bias starting Disposition toward Trust")

    local infamousReaction = disposition.getFameReaction(5, { deedTone = "dastardly" })
    assertEqual(infamousReaction.dispositionFrame.bias, "less_favorable",
        "dastardly high Fame should suggest less favorable starting Dispositions")
    assertEqual(infamousReaction.dispositionFrame.suggestedDisposition, disposition.DISPOSITIONS.DISTASTE,
        "dastardly high Fame should bias starting Disposition toward Distaste")
end

local function checkCityPhaseCityEvents()
    local rumorCard = {
        name = "The Hanged Man",
        value = 12,
        suit = constants.SUITS.MAJOR,
        is_major = true,
    }
    local discardedMajor = nil
    local fakeGMDeck = {
        draw = function()
            return rumorCard
        end,
        discard = function(_, card)
            discardedMajor = card
        end,
    }
    local bus = events.createEventBus()
    local emitted = nil
    bus:on(events.EVENTS.CITY_EVENT_RESOLVED, function(data)
        emitted = data
    end)

    local controller = city_phase.createCityPhaseController({
        eventBus = bus,
        gmDeck = fakeGMDeck,
    })

    local eventOptions = controller:getCityEventOptions()
    assertTrue(eventOptions.autoDrawAvailable,
        "City Event options should report automatic GM-deck draw availability")
    assertTrue(not eventOptions.disabled,
        "City Event options should allow resolution when a GM deck can draw")
    eventOptions = controller:getCityEventOptions({ majorCard = rumorCard })
    assertEqual(eventOptions.step, city_phase.STEPS.CITY_EVENTS,
        "City Event options should identify the City Phase step")
    assertTrue(eventOptions.cardValid, "City Event options should validate numbered major arcana")
    assertEqual(eventOptions.category, "rumor", "City Event options should preview event category")
    assertEqual(eventOptions.event.title, "The Star's Daughter",
        "City Event options should preview the table entry")
    assertEqual(eventOptions.consumedEntryPreviews[1].table, "city_events",
        "City Event options should preview Restock consumed markers")
    assertTrue(discardedMajor == nil, "City Event options should not draw or discard cards during preview")

    local ok, result, detail = controller:resolveCityEvent()
    assertTrue(ok, "City Events should resolve as a City Phase step")
    assertEqual(result, "city_event_resolved", "City Events should report completion")
    assertEqual(detail.card, rumorCard, "City Events should use the drawn major arcana")
    assertEqual(detail.category, "rumor", "major XI-XV City Events should be rumors")
    assertEqual(detail.event.title, "The Star's Daughter", "City Events should consult the drawn card table entry")
    assertEqual(discardedMajor, rumorCard, "City Events should discard automatically drawn major cards")
    assertTrue(controller.lastCityEvent == detail, "City Events should store the last event on the controller")
    assertTrue(emitted and emitted.event.title == "The Star's Daughter", "City Events should emit event details")

    ok, result = controller:resolveCityEvent()
    assertTrue(not ok, "City Events should resolve only once per City Phase controller")
    assertEqual(result, "City Event already resolved", "repeat City Events should explain existing resolution")
    eventOptions = controller:getCityEventOptions({ majorCard = rumorCard })
    assertTrue(eventOptions.disabled, "City Event options should disable after resolution")
    assertEqual(eventOptions.unavailableReason, "City Event already resolved",
        "City Event options should explain repeat resolution")

    local swordsWitness = base_entity.createEntity({
        id = "pc_city_event_swords_witness",
        name = "City Event Swords Witness",
        isPC = true,
        path = "swords",
    })
    local cupsLeft = base_entity.createEntity({
        id = "pc_city_event_cups_left",
        name = "City Event Cups Left",
        isPC = true,
        path = "cups",
    })
    local cupsRight = base_entity.createEntity({
        id = "pc_city_event_cups_right",
        name = "City Event Cups Right",
        isPC = true,
        path = "cups",
    })
    local grossMinorDiscard = { name = "Four of Cups", value = 4, suit = constants.SUITS.CUPS }
    local grossController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { swordsWitness, cupsLeft, cupsRight },
        playerDeck = {
            peekDiscard = function()
                return grossMinorDiscard
            end,
        },
    })
    eventOptions = grossController:getCityEventOptions({
        majorCard = {
            name = "The Magician",
            value = 1,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
        minorDiscardCard = { name = "Three of Swords", value = 3, suit = constants.SUITS.SWORDS },
    })
    assertEqual(eventOptions.effectPreview.randomAdventurer.target, cupsRight,
        "City Event options should preview random adventurers from the top minor discard")
    assertEqual(eventOptions.effectPreview.randomAdventurer.minorDiscard, grossMinorDiscard,
        "City Event options should prefer the real top discard for random target previews")
    ok, result, detail = grossController:resolveCityEvent({
        majorCard = {
            name = "The Magician",
            value = 1,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
        minorDiscardCard = { name = "Three of Swords", value = 3, suit = constants.SUITS.SWORDS },
    })
    assertTrue(ok, "Gross City Event should resolve")
    assertEqual(detail.randomTargetEffects.target, cupsRight,
        "Gross City Event should choose the random adventurer from the top minor discard suit and parity")
    assertEqual(detail.randomTargetEffects.minorDiscard, grossMinorDiscard,
        "Gross City Event should prefer the actual minor discard over fallback target cards")
    assertEqual(cupsRight.cityEventCuriosities[1].id, "night_soil",
        "Gross City Event should record the night-soil fallout on the selected adventurer")
    assertTrue(cupsLeft.cityEventCuriosities == nil and swordsWitness.cityEventCuriosities == nil,
        "Gross City Event should not record night-soil fallout on unselected adventurers")

    local dogWitness = base_entity.createEntity({
        id = "pc_city_event_dog_witness",
        name = "City Event Dog Witness",
        isPC = true,
    })
    local doggyPendingController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { dogWitness },
    })
    ok, result, detail = doggyPendingController:resolveCityEvent({
        majorCard = {
            name = "The High Priestess",
            value = 2,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
    })
    assertTrue(ok, "Doggy City Event should resolve even when the guild does not feed the dog")
    assertTrue(detail.animalCompanionEffects and detail.animalCompanionEffects.pending,
        "Doggy City Event should present a pending animal-companion opportunity before feeding")
    assertEqual(detail.animalCompanionEffects.result, "city_event_animal_companion_opportunity",
        "Doggy City Event should not add a companion unless the dog is fed")
    assertTrue(dogWitness.animalCompanions == nil or #dogWitness.animalCompanions == 0,
        "Doggy City Event should not add the dog before feeding")

    local dogAdopter = base_entity.createEntity({
        id = "pc_city_event_dog_adopter",
        name = "City Event Dog Adopter",
        isPC = true,
    })
    dogAdopter.inventory = inventory.createInventory()
    local dogRations = inventory.createItemFromTemplate("rations_3")
    dogAdopter.inventory:addItem(dogRations, inventory.LOCATIONS.PACK)
    local doggyFedController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { dogAdopter },
    })
    ok, result, detail = doggyFedController:resolveCityEvent({
        majorCard = {
            name = "The High Priestess",
            value = 2,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
        feedDog = true,
        dogOwner = dogAdopter,
    })
    assertTrue(ok, "feeding the Doggy City Event dog should resolve")
    assertEqual(detail.animalCompanionEffects.result, "city_event_animal_companion_joined",
        "feeding the Doggy City Event dog should add it as a companion")
    assertEqual(#dogAdopter.animalCompanions, 1, "feeding the Doggy City Event dog should add one companion")
    assertEqual(dogAdopter.animalCompanions[1].templateId, "hound",
        "Doggy City Event should use the hound companion template")
    assertEqual(dogAdopter.animalCompanions[1].source, "city_event_doggy",
        "Doggy City Event should record the rulebook event source on the companion")
    assertEqual(#dogAdopter.animalCompanions[1].knownCommands, 0,
        "Doggy City Event dog should start as an untrained follower")
    local remainingDogRations = dogAdopter.inventory:findItem(dogRations.id)
    assertTrue(remainingDogRations ~= nil, "feeding the Doggy City Event dog should consume one ration only")
    assertEqual(remainingDogRations.quantity, 2, "feeding the Doggy City Event dog should decrement ration stacks")
    assertEqual(dogAdopter.cityEventAnimalCompanions[1].id, "doggy",
        "Doggy City Event should record the adopted dog on the owner")

    local falconFeedOwner = base_entity.createEntity({
        id = "pc_city_event_falcon_feed",
        name = "City Event Falcon Feed",
        isPC = true,
    })
    falconFeedOwner.inventory = inventory.createInventory()
    local falconFeed = inventory.createItemFromTemplate("animal_feed", {
        properties = {
            isAnimalFeed = true,
            feedFor = "falcon",
        },
    })
    falconFeedOwner.inventory:addItem(falconFeed, inventory.LOCATIONS.PACK)
    local doggyWrongFeedController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { falconFeedOwner },
    })
    ok, result, detail = doggyWrongFeedController:resolveCityEvent({
        majorCard = {
            name = "The High Priestess",
            value = 2,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
        feedDog = true,
        dogOwner = falconFeedOwner,
    })
    assertTrue(ok, "Doggy City Event should remain resolved when no matching feed is available")
    assertTrue(detail.animalCompanionEffects and detail.animalCompanionEffects.pending,
        "Doggy City Event should stay pending when only wrong animal feed is offered")
    assertEqual(detail.animalCompanionEffects.reason, "requires_matching_food",
        "Doggy City Event should require rations or dog-compatible animal feed")
    assertTrue(falconFeedOwner.animalCompanions == nil or #falconFeedOwner.animalCompanions == 0,
        "Doggy City Event should not add the dog for wrong animal feed")
    assertTrue(falconFeedOwner.inventory:findItem(falconFeed.id) ~= nil,
        "Doggy City Event should not consume wrong animal feed")

    local styliteLowWands = base_entity.createEntity({
        id = "pc_city_event_stylite_low_wands",
        name = "City Event Stylite Low Wands",
        isPC = true,
        wands = 1,
    })
    local styliteHighWands = base_entity.createEntity({
        id = "pc_city_event_stylite_high_wands",
        name = "City Event Stylite High Wands",
        isPC = true,
        wands = 5,
    })
    local styliteController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { styliteLowWands, styliteHighWands },
    })
    eventOptions = styliteController:getCityEventOptions({
        majorCard = {
            name = "The Emperor",
            value = 4,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
    })
    assertEqual(eventOptions.effectPreview.targetedAdventurer.target, styliteHighWands,
        "City Event options should preview highest-suit targeted adventurers")
    assertEqual(eventOptions.effectPreview.targetedAdventurer.suitValue, 5,
        "City Event options should preview targeted adventurer suit scores")
    ok, result, detail = styliteController:resolveCityEvent({
        majorCard = {
            name = "The Emperor",
            value = 4,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
    })
    assertTrue(ok, "Stylite City Event should resolve")
    assertTrue(detail.targetedAdventurerEffects.target == styliteHighWands,
        "Stylite City Event should target the adventurer with the highest Wands")
    assertEqual(detail.targetedAdventurerEffects.suitValue, 5,
        "Stylite City Event should report the selected adventurer's Wands score")
    assertEqual(styliteHighWands.cityEventCuriosities[1].id, "stylite_denunciation",
        "Stylite City Event should record the public denunciation on the target")
    assertTrue(styliteLowWands.cityEventCuriosities == nil,
        "Stylite City Event should not record the denunciation on lower-Wands adventurers")

    local successionState = {
        currentRuler = {
            id = "old_ruler",
            name = "The Old Sovereign",
        },
    }
    local successionController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        cityState = successionState,
    })
    ok, result, detail = successionController:resolveCityEvent({
        majorCard = {
            name = "The Wheel of Fortune",
            value = 10,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
        goneReason = "assassinated_or_exiled",
    })
    assertTrue(ok, "King is Dead City Event should resolve")
    assertTrue(detail.successionEffects and detail.successionEffects.pending,
        "King is Dead should mark the City succession as pending")
    assertEqual(successionState.pendingSuccession.oldRuler.name, "The Old Sovereign",
        "King is Dead should remember the previous ruler before succession")
    ok, result, detail = successionController:resolveCityEventConsequences()
    assertTrue(ok, "King is Dead should expose a pending succession consequence")
    assertEqual(result, "city_event_succession_pending",
        "King is Dead should require the GM to determine the new ruler")
    ok, result, detail = successionController:resolveCityEventConsequences({
        newRuler = {
            id = "crow_regent",
            name = "The Crow Regent",
            faction = "court_of_wands",
        },
        regimeNotes = "Expect stricter bird-law edicts.",
    })
    assertTrue(ok, "King is Dead should resolve when the GM supplies a new ruler")
    assertEqual(result, "city_event_succession_resolved",
        "King is Dead should report completed succession")
    assertEqual(successionState.currentRuler.name, "The Crow Regent",
        "King is Dead should update the City ruler")
    assertEqual(successionState.previousRuler.name, "The Old Sovereign",
        "King is Dead should preserve the previous ruler")
    assertEqual(successionState.citySuccessions[1].newRuler.faction, "court_of_wands",
        "King is Dead should preserve authored regime details")
    assertTrue(successionState.pendingSuccession == nil,
        "King is Dead should clear pending succession after the new ruler is recorded")

    local customCityEventsTable = {
        glass_rain = {
            value = 12,
            category = "Rumor",
            title = "Glass Rain Over the Well",
            description = "Needle-bright rain leaves a marriage contract etched in the market stones.",
            author_notes = "Foreshadow the well spirit's dowry.",
            effects = {
                cityOmen = {
                    id = "glass_rain",
                    kind = "rumor_weather",
                    flag = "glassRainRumor",
                },
            },
        },
        ["21"] = "A custom Strange Days table hook",
    }
    local customController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        cityEventsTable = customCityEventsTable,
        cityEventsTableSource = "glass_calendar",
    })
    eventOptions = customController:getCityEventOptions({
        majorCard = rumorCard,
    })
    assertEqual(eventOptions.event.title, "Glass Rain Over the Well",
        "City Event options should preview authored custom table entries")
    assertEqual(eventOptions.cityEventsTableSource, "glass_calendar",
        "City Event options should report custom table sources")
    assertEqual(eventOptions.cityEventsTable.count, 2,
        "City Event options should preview custom table metadata")
    assertEqual(#eventOptions.cityEventsTable.missing, 19,
        "City Event options should preview missing custom table slots")
    assertEqual(eventOptions.effectPreview.cityOmen.id, "glass_rain",
        "City Event options should preview authored event effects")
    ok, result, detail = customController:resolveCityEvent({
        majorCard = rumorCard,
    })
    assertTrue(ok, "City Events should resolve authored custom table entries")
    assertEqual(detail.event.title, "Glass Rain Over the Well",
        "custom City Events should use keyed authored entries by card value")
    assertEqual(detail.event.summary,
        "Needle-bright rain leaves a marriage contract etched in the market stones.",
        "custom City Events should normalize descriptions into summaries")
    assertEqual(detail.event.category, "rumor", "custom City Events should normalize category aliases")
    assertEqual(detail.event.authorNotes, "Foreshadow the well spirit's dowry.",
        "custom City Events should preserve GM author notes")
    assertEqual(detail.event.tableSource, "glass_calendar", "custom City Events should preserve table source")
    assertEqual(detail.cityEventsTableSource, "glass_calendar", "City Event detail should report table source")
    assertEqual(detail.cityEventsTable.count, 2, "custom City Event metadata should count normalized authored slots")
    assertEqual(#detail.cityEventsTable.missing, 19, "custom City Event metadata should report missing slots")
    assertEqual(customCityEventsTable.glass_rain, customCityEventsTable[12],
        "custom City Event normalizer should alias keyed entries to their card value")
    assertEqual(customCityEventsTable[21].category, "signs_and_portents",
        "custom string City Event entries should infer category from card value")
    assertEqual(customController.consumedCityEvents[1].tableSource, "glass_calendar",
        "consumed City Event markers should preserve authored table source")

    local incompleteController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        cityEventsTable = {
            [12] = "Only the Hanged Man has been authored",
        },
        requireCompleteCityEventsTable = true,
    })
    eventOptions = incompleteController:getCityEventOptions({
        majorCard = rumorCard,
    })
    assertTrue(eventOptions.disabled, "City Event options should disable incomplete strict tables")
    assertEqual(eventOptions.unavailableReason, "City Event table incomplete",
        "City Event options should explain incomplete strict tables")
    assertTrue(#eventOptions.cityEventsTable.missing > 0,
        "City Event options should report missing strict table entries")
    ok, result, detail = incompleteController:resolveCityEvent({
        majorCard = rumorCard,
    })
    assertTrue(not ok, "strict custom City Event tables should reject incomplete authoring")
    assertEqual(result, "City Event table incomplete", "incomplete custom City Event tables should explain failure")
    assertEqual(detail.tableName, "city_events", "incomplete custom table detail should identify the table")
    assertTrue(#detail.missing > 0, "incomplete custom table detail should report missing entries")
    assertTrue(not incompleteController.cityEventResolved,
        "incomplete custom City Event tables should not mark the step resolved")

    local signCard = {
        name = "The World",
        value = 21,
        suit = constants.SUITS.MAJOR,
        is_major = true,
    }
    local minorDiscard = {
        name = "Eight of Cups",
        value = 8,
        suit = constants.SUITS.CUPS,
    }
    local fakeMinorDeck = {
        peekDiscard = function()
            return minorDiscard
        end,
    }
    local signsController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        playerDeck = fakeMinorDeck,
    })
    eventOptions = signsController:getCityEventOptions({
        majorCard = signCard,
        minorDiscardCard = {
            name = "Two of Wands",
            value = 2,
            suit = constants.SUITS.WANDS,
        },
    })
    assertEqual(eventOptions.category, "signs_and_portents",
        "City Event options should preview major XXI as Signs and Portents")
    assertEqual(eventOptions.signCard, minorDiscard,
        "City Event options should inspect the real top minor discard")
    assertEqual(eventOptions.sign.title, "The Mushroom Forest",
        "City Event options should preview Signs and Portents entries")
    assertEqual(eventOptions.consumedEntryPreviews[2].table, "signs_and_portents",
        "City Event options should preview consumed Signs entries")
    ok, result, detail = signsController:resolveCityEvent({
        majorCard = signCard,
        minorDiscardCard = {
            name = "Two of Wands",
            value = 2,
            suit = constants.SUITS.WANDS,
        },
    })
    assertTrue(ok, "City Events should resolve Signs and Portents when a minor discard exists")
    assertEqual(detail.category, "signs_and_portents", "major XXI should use Signs and Portents")
    assertEqual(detail.signCard, minorDiscard, "Signs and Portents should inspect the top minor discard")
    assertEqual(detail.sign.title, "The Mushroom Forest", "Signs and Portents should consult the minor discard value")
    assertTrue(signsController.cityEventResolved, "successful Signs and Portents should mark City Events resolved")

    local animalCompanions = require('data.animal_companions')
    local dogSuicideOwner = base_entity.createEntity({
        id = "pc_city_event_dog_suicide_owner",
        name = "City Event Dog Suicide Owner",
        isPC = true,
    })
    local doomedDog = animalCompanions.createCompanion("hound", {
        id = "city_event_doomed_dog",
        name = "Doomed Dog",
    })
    local sparedFalcon = animalCompanions.createCompanion("falcon", {
        id = "city_event_spared_falcon",
        name = "Spared Falcon",
    })
    dogSuicideOwner.animalCompanions = { doomedDog, sparedFalcon }
    local dogSuicideController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { dogSuicideOwner },
    })
    ok, result, detail = dogSuicideController:resolveCityEvent({
        majorCard = signCard,
        minorDiscardCard = {
            name = "Ten of Cups",
            value = 10,
            suit = constants.SUITS.CUPS,
        },
    })
    assertTrue(ok, "Dog Suicide Signs and Portents should resolve")
    assertEqual(detail.sign.title, "Dog Suicide", "Dog Suicide should consult the minor discard value")
    assertTrue(dogSuicideController.cityState.cityDogsDead,
        "Dog Suicide should preserve the City-state dog catastrophe flag")
    assertEqual(detail.animalCompanionCatastropheEffects.casualtyCount, 1,
        "Dog Suicide should affect dog animal companions")
    assertTrue(doomedDog.conditions.dead and doomedDog.dead,
        "Dog Suicide should kill hound/dog companions in the City")
    assertTrue(not (sparedFalcon.conditions and sparedFalcon.conditions.dead),
        "Dog Suicide should not kill non-dog companions")
    assertEqual(dogSuicideOwner.cityEventAnimalCompanionCasualties[1].companionId, "city_event_doomed_dog",
        "Dog Suicide should record companion casualties on the owner")

    local customSignsTable = {
        dream_market = {
            value = 8,
            title = "The Dream Market Opens",
            description = "Every sleeper wakes owing a favor to a mask seller.",
        },
    }
    local customSignsController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        cityEventsTable = {
            [21] = { value = 21, title = "Custom Strange Days", category = "signs" },
        },
        signsAndPortentsTable = customSignsTable,
        signsAndPortentsTableSource = "omen_notebook",
    })
    ok, result, detail = customSignsController:resolveCityEvent({
        majorCard = signCard,
        minorDiscardCard = minorDiscard,
    })
    assertTrue(ok, "City Events should resolve custom Signs and Portents entries")
    assertEqual(detail.sign.title, "The Dream Market Opens",
        "custom Signs and Portents should use keyed authored entries by minor discard value")
    assertEqual(detail.sign.summary, "Every sleeper wakes owing a favor to a mask seller.",
        "custom Signs and Portents should normalize descriptions into summaries")
    assertEqual(detail.sign.category, "signs_and_portents",
        "custom Signs and Portents should default to the signs category")
    assertEqual(detail.sign.tableSource, "omen_notebook", "custom Signs should preserve table source")
    assertEqual(detail.signsAndPortentsTableSource, "omen_notebook",
        "City Event detail should report custom Signs table source")
    assertEqual(customSignsTable.dream_market, customSignsTable[8],
        "custom Signs normalizer should alias keyed entries to their card value")

    local noDiscardController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
    })
    eventOptions = noDiscardController:getCityEventOptions({
        majorCard = signCard,
    })
    assertTrue(eventOptions.disabled, "City Event options should disable Signs without a minor discard")
    assertEqual(eventOptions.unavailableReason, "Requires minor discard for Signs and Portents",
        "City Event options should explain missing Signs discard")
    ok, result = noDiscardController:resolveCityEvent({
        majorCard = signCard,
    })
    assertTrue(not ok, "Signs and Portents should require a minor discard card")
    assertEqual(result, "Requires minor discard for Signs and Portents", "missing Signs discard should explain failure")
    assertTrue(not noDiscardController.cityEventResolved, "failed Signs and Portents should not mark City Events resolved")

    local majorDiscardController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
    })
    ok, result = majorDiscardController:resolveCityEvent({
        majorCard = signCard,
        minorDiscardCard = {
            name = "The Magician",
            value = 1,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
    })
    assertTrue(not ok, "Signs and Portents should reject non-Fool major discard cards")
    assertEqual(result, "Requires minor discard for Signs and Portents",
        "major Signs discard should explain minor-discard requirement")
    assertTrue(not majorDiscardController.cityEventResolved,
        "major Signs discard should not mark City Events resolved")

    local noDeckController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
    })
    ok, result = noDeckController:resolveCityEvent()
    assertTrue(not ok, "City Events should require a major draw or explicit card")
    assertEqual(result, "Requires major arcana draw", "missing City Event draw should explain failure")

    local foolEventController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
    })
    eventOptions = foolEventController:getCityEventOptions({
        majorCard = {
            name = "The Fool",
            value = 0,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
    })
    assertTrue(eventOptions.disabled, "City Event options should disable The Fool as a City Event")
    assertEqual(eventOptions.unavailableReason, "Requires major arcana draw",
        "City Event options should explain Fool rejection")
    ok, result = foolEventController:resolveCityEvent({
        majorCard = {
            name = "The Fool",
            value = 0,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
    })
    assertTrue(not ok, "City Events should reject The Fool as a GM major draw")
    assertEqual(result, "Requires major arcana draw", "Fool City Event draw should explain GM-deck requirement")
    assertTrue(not foolEventController.cityEventResolved, "Fool City Event draw should not mark the step resolved")
end

local function checkCityPhaseCityEventEffects()
    local commonActor = base_entity.createEntity({
        id = "pc_city_event_common",
        name = "City Event Common",
        isPC = true,
    })
    commonActor.gold = 25
    commonActor.inventory = inventory.createInventory()
    local upkeepController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { commonActor },
    })
    local ok, result, detail = upkeepController:resolveCityEvent({
        majorCard = {
            name = "Justice",
            value = 8,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
    })
    assertTrue(ok, "Coronation City Event should resolve")
    assertTrue(detail.effects.upkeepCosts.common == 25, "Coronation should install reduced upkeep costs")
    local upkeepOptions = upkeepController:getUpkeepOptions(commonActor, { tier = "common" })
    assertEqual(upkeepOptions.selectedTier.cost, 25,
        "Upkeep options should preview City Event modified upkeep costs")
    assertEqual(upkeepOptions.selectedTier.baseCost, 50,
        "Upkeep options should preserve the base upkeep tier cost")
    assertTrue(upkeepOptions.selectedTier.costModified,
        "Upkeep options should flag City Event cost modifications")
    assertEqual(upkeepOptions.projectedGold, 0,
        "Upkeep options should preview remaining gold after modified upkeep")
    ok, result, detail = upkeepController:resolveUpkeep(commonActor, {
        tier = "common",
    })
    assertTrue(ok, "reduced City Event upkeep should allow common lodging at event price")
    assertEqual(detail.cost, 25, "Coronation should reduce common upkeep to 25g")
    assertEqual(detail.baseCost, 50, "reduced upkeep should preserve the base tier cost")
    assertEqual(commonActor.gold, 0, "reduced upkeep should spend only the event cost")

    local busker = base_entity.createEntity({
        id = "pc_city_event_busker",
        name = "City Event Busker",
        isPC = true,
        wands = 2,
    })
    busker.gold = 0
    busker.inventory = inventory.createInventory()
    local carouser = base_entity.createEntity({
        id = "pc_city_event_carouser",
        name = "City Event Carouser",
        isPC = true,
    })
    carouser.gold = 50
    carouser.xp = 0
    carouser.inventory = inventory.createInventory()
    local carouseOnlyController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { busker, carouser },
    })
    ok = carouseOnlyController:resolveCityEvent({
        majorCard = {
            name = "The Chariot",
            value = 7,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
    })
    assertTrue(ok, "Ecstasy of St. Naos City Event should resolve")
    ok, result = carouseOnlyController:resolveAction(busker, {
        type = "beg_and_busk",
        card = {
            name = "Five of Wands",
            value = 5,
            suit = constants.SUITS.WANDS,
        },
    })
    assertTrue(not ok, "only-Carouse City Event should reject other City Actions")
    assertEqual(result, "City Action not available during this City Event", "only-Carouse rejection should explain event limit")
    assertTrue(not carouseOnlyController:hasActed(busker), "event-rejected City Action should not consume action")
    ok, result = carouseOnlyController:resolveAction(carouser, {
        type = "carouse",
        spend = "all",
        hangoverCard = {
            name = "The Hermit",
            value = 9,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
    })
    assertTrue(ok, "only-Carouse City Event should still allow Carouse")
    assertEqual(result, "carouse_resolved", "allowed event Carouse should resolve normally")

    local dryCarouser = base_entity.createEntity({
        id = "pc_city_event_dry_carouser",
        name = "City Event Dry Carouser",
        isPC = true,
    })
    dryCarouser.gold = 50
    dryCarouser.inventory = inventory.createInventory()
    local dryController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { dryCarouser },
    })
    ok = dryController:resolveCityEvent({
        majorCard = {
            name = "The Hermit",
            value = 9,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
    })
    assertTrue(ok, "Feast of the Constellations City Event should resolve")
    ok, result = dryController:resolveAction(dryCarouser, {
        type = "carouse",
        spend = "half",
        hangoverCard = {
            name = "The Magician",
            value = 1,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
    })
    assertTrue(not ok, "Carouse-ban City Event should reject Carouse")
    assertEqual(result, "City Action blocked by City Event", "blocked Carouse should explain event limit")
    assertEqual(dryCarouser.gold, 50, "blocked Carouse should not spend gold")
    assertTrue(not dryController:hasActed(dryCarouser), "blocked Carouse should not consume action")

    local hauntedBusker = base_entity.createEntity({
        id = "pc_city_event_haunted_busker",
        name = "City Event Haunted Busker",
        isPC = true,
        wands = 1,
    })
    hauntedBusker.gold = 0
    hauntedBusker.inventory = inventory.createInventory()
    local hauntedState = {}
    local hauntedController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { hauntedBusker },
        cityState = hauntedState,
    })
    ok = hauntedController:resolveCityEvent({
        majorCard = {
            name = "The World",
            value = 21,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
        minorDiscardCard = {
            name = "King of Cups",
            value = 14,
            suit = constants.SUITS.CUPS,
        },
    })
    assertTrue(ok, "What Is Dead May Never Die portent should resolve")
    assertTrue(hauntedState.cityActionsBlockedByUndead and hauntedState.undeadPlague.active,
        "What Is Dead May Never Die should persist the undead City Action block in City state")
    ok, result = hauntedController:resolveAction(hauntedBusker, {
        type = "beg_and_busk",
        card = {
            name = "Two of Wands",
            value = 2,
            suit = constants.SUITS.WANDS,
        },
    })
    assertTrue(not ok, "all-blocking City Event should reject every City Action")
    assertEqual(result, "City Actions blocked by City Event", "all-blocking City Event should explain lockout")
    assertEqual(hauntedBusker.gold, 0, "all-blocked City Action should not apply effects")
    assertTrue(not hauntedController:hasActed(hauntedBusker), "all-blocked City Action should not consume action")

    local hauntedFutureController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { hauntedBusker },
        cityState = hauntedState,
    })
    ok, result = hauntedFutureController:resolveAction(hauntedBusker, {
        type = "beg_and_busk",
        card = {
            name = "Three of Wands",
            value = 3,
            suit = constants.SUITS.WANDS,
        },
    })
    assertTrue(not ok, "undead-haunted City Actions should remain blocked in later City phases")
    assertEqual(result, "City Actions blocked by undead plague",
        "persistent undead City Action blocks should explain the active plague")
    ok, result = hauntedFutureController:resolveCityUndeadPlague({
        source = "Bone-Choked Cistern",
    })
    assertTrue(not ok, "undead plague should not clear until the source is quelled")
    assertEqual(result, "Undead source not quelled",
        "undead plague clear attempts should require quelling the source")
    ok, result, detail = hauntedFutureController:resolveCityUndeadPlague({
        source = "Bone-Choked Cistern",
        quelled = true,
        notes = "The necromantic well was sealed.",
    })
    assertTrue(ok, "undead plague should clear after its source is found and quelled")
    assertEqual(result, "city_undead_plague_quelled", "undead plague clear should report success")
    assertTrue(not hauntedState.cityActionsBlockedByUndead and hauntedState.undeadPlague.active == false,
        "quelling the undead source should unblock future City Actions")
    ok, result = hauntedFutureController:resolveAction(hauntedBusker, {
        type = "beg_and_busk",
        card = {
            name = "Four of Wands",
            value = 4,
            suit = constants.SUITS.WANDS,
        },
    })
    assertTrue(ok, "City Actions should resume after the undead source is quelled")

    local ancientLayout = {
        districts = {},
        constants = {},
        specialCityActions = {},
        counts = {},
    }
    local ancientController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        cityLayout = ancientLayout,
    })
    ok, result, detail = ancientController:resolveCityEvent({
        majorCard = {
            name = "The World",
            value = 21,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
        minorDiscardCard = {
            name = "Four of Cups",
            value = 4,
            suit = constants.SUITS.CUPS,
        },
        additionalDistrictCard = {
            name = "Ace of Swords",
            value = 1,
            suit = constants.SUITS.SWORDS,
        },
    })
    assertTrue(ok, "Ancient Quarter Signs and Portents should resolve")
    assertTrue(detail.layoutEffects and detail.layoutEffects.addedDistrict,
        "Ancient Quarter should add a district layout effect")
    assertEqual(#ancientLayout.districts, 1, "Ancient Quarter should add one district to the City")
    assertEqual(ancientLayout.districts[1].district.id,
        city_districts.getDistrict(constants.SUITS.SWORDS, 1).id,
        "Ancient Quarter should use the provided Appendix D district card")

    local slimeLayout = {
        districts = {
            { district = { id = "slime_target", name = "Slime Target" } },
            { district = { id = "surviving_district", name = "Surviving District" } },
        },
        constants = {},
        specialCityActions = {
            { districtId = "slime_target", districtName = "Slime Target", action = { id = "fight" } },
            { districtId = "surviving_district", districtName = "Surviving District", action = { id = "study_language" } },
        },
        counts = {},
    }
    local slimeController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
