            is_major = true,
        },
        minorDiscardCard = {
            name = "Seven of Cups",
            value = 7,
            suit = constants.SUITS.CUPS,
        },
        removedDistrictId = "slime_target",
    })
    assertTrue(ok, "Slime Catastrophe Signs and Portents should resolve")
    assertEqual(detail.layoutEffects.removedDistrict.districtId, "slime_target",
        "Slime Catastrophe should report the devoured district")
    assertEqual(#slimeLayout.districts, 1, "Slime Catastrophe should remove one district")
    assertEqual(slimeLayout.specialCityActions[1].districtId, "surviving_district",
        "Slime Catastrophe should remove special City Actions from the devoured district")

    local mushroomActor = base_entity.createEntity({
        id = "pc_city_event_mushroom_actor",
        name = "City Event Mushroom Actor",
        isPC = true,
    })
    local mushroomLayout = {
        districts = {
            { district = { id = "mushroom_target", name = "Mushroom Target" } },
        },
        constants = {},
        specialCityActions = {
            { districtId = "mushroom_target", districtName = "Mushroom Target", action = { id = "fight" } },
        },
        counts = {},
    }
    local mushroomController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { mushroomActor },
        cityLayout = mushroomLayout,
    })
    ok, result, detail = mushroomController:resolveCityEvent({
        majorCard = {
            name = "The World",
            value = 21,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
        minorDiscardCard = {
            name = "Eight of Cups",
            value = 8,
            suit = constants.SUITS.CUPS,
        },
        blockedDistrictId = "mushroom_target",
    })
    assertTrue(ok, "Mushroom Forest Signs and Portents should resolve")
    assertEqual(detail.layoutEffects.blockedDistrictAction.districtId, "mushroom_target",
        "Mushroom Forest should report the blocked district action")
    ok, result = mushroomController:resolveDistrictAction(mushroomActor, "fight", {
        bet = 10,
        outcome = "win",
    })
    assertTrue(not ok, "Mushroom Forest should block the selected district action")
    assertEqual(result, "District City Action blocked by City Event",
        "blocked Mushroom Forest district action should explain the event limit")

    local narrativeSigns = {
        { value = 1, id = "rip_van_winkle", yearsElapsed = 100 },
        { value = 3, id = "mists", flag = "unnaturalNight" },
        { value = 5, id = "blood_rain", flag = "bloodRain" },
        { value = 6, id = "wandering_dreams", pendingDreamSecrets = 2 },
        { value = 9, id = "thing_in_the_water", flag = "greyEnnuiSong" },
        { value = 10, id = "dog_suicide", flag = "cityDogsDead" },
        { value = 11, id = "black_miracle_of_the_statues", flag = "iconoclasm" },
        { value = 12, id = "honey_cult", flag = "nascentHordeAnxiety" },
        { value = 13, id = "child_of_silence", flag = "childOfSilenceHuntsGuild" },
    }
    for _, signCase in ipairs(narrativeSigns) do
        local omenState = {}
        local dreamerA = base_entity.createEntity({
            id = "pc_city_event_dreamer_a",
            name = "City Event Dreamer A",
            isPC = true,
        })
        local dreamerB = base_entity.createEntity({
            id = "pc_city_event_dreamer_b",
            name = "City Event Dreamer B",
            isPC = true,
        })
        local omenController = city_phase.createCityPhaseController({
            eventBus = events.createEventBus(),
            guild = { dreamerA, dreamerB },
            cityState = omenState,
        })
        ok, result, detail = omenController:resolveCityEvent({
            majorCard = {
                name = "The World",
                value = 21,
                suit = constants.SUITS.MAJOR,
                is_major = true,
            },
            minorDiscardCard = {
                name = "Narrative Sign",
                value = signCase.value,
                suit = constants.SUITS.CUPS,
            },
        })
        assertTrue(ok, "narrative Signs and Portents should resolve")
        assertTrue(detail.omenEffects and detail.omenEffects.result == "city_omen_recorded",
            "narrative Signs and Portents should record a City omen")
        assertEqual(omenState.cityOmens[1].id, signCase.id,
            "narrative Signs and Portents should preserve the omen id")
        if signCase.flag then
            assertTrue(omenState[signCase.flag], "narrative Signs and Portents should set its City-state flag")
        end
        if signCase.yearsElapsed then
            assertEqual(omenState.yearsElapsed, signCase.yearsElapsed,
                "Rip Van Winkle should advance the City timeline")
        end
        if signCase.pendingDreamSecrets then
            assertEqual(omenState.pendingDreamSecrets, signCase.pendingDreamSecrets,
                "Dreams should ask for one secret per active guild member")
        end
    end

    local secretDreamerA = base_entity.createEntity({
        id = "pc_city_event_secret_dreamer_a",
        name = "City Event Secret Dreamer A",
        isPC = true,
    })
    local secretDreamerB = base_entity.createEntity({
