        cityState = dreamSecretState,
    })
    ok, result, detail = dreamSecretController:resolveCityEvent({
        majorCard = {
            name = "The World",
            value = 21,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
        minorDiscardCard = {
            name = "Six of Cups",
            value = 6,
            suit = constants.SUITS.CUPS,
        },
    })
    assertTrue(ok, "Dreams Signs and Portents should resolve")
    ok, result, detail = dreamSecretController:resolveCityEventConsequences()
    assertTrue(ok, "Dreams should expose pending secret consequences")
    assertEqual(result, "city_event_dream_secrets_pending",
        "Dreams should remain pending until each active adventurer contributes a secret")
    assertEqual(#detail.pendingActors, 2, "Dreams should require one secret from each active adventurer")
    ok, result, detail = dreamSecretController:resolveCityEventConsequences({
        dreamSecrets = {
            {
                teller = secretDreamerA.id,
                dreamer = secretDreamerB.id,
                secret = "I hid the silver reliquary under the old stairs.",
            },
            {
                teller = secretDreamerB,
                dreamer = secretDreamerA,
                secret = "I made a pact with the blind bellringer.",
            },
        },
    })
    assertTrue(ok, "Dreams should resolve after all player secrets are provided")
    assertEqual(result, "city_event_dream_secrets_resolved",
        "Dreams should report completed secret exchanges")
    assertEqual(dreamSecretState.pendingDreamSecrets, 0,
        "Dreams should clear the pending secret count after all exchanges resolve")
    assertEqual(#dreamSecretState.dreamSecrets, 2,
        "Dreams should record the resolved secret exchanges in City state")
    assertEqual(secretDreamerA.cityDreamSecrets[1].secret, "I made a pact with the blind bellringer.",
        "Dreams should record the secret the adventurer dreamed about")
    assertEqual(secretDreamerA.cityDreamSecretsTold[1].dreamerId, secretDreamerB.id,
        "Dreams should record which other adventurer received the told secret")
    assertEqual(secretDreamerB.cityDreamSecrets[1].tellerId, secretDreamerA.id,
        "Dreams should record the teller for dreamed secrets")

    local frontRank = base_entity.createEntity({
        id = "pc_city_event_front_rank",
