    assertTrue(detail.target == backRank, "A Theft should target the back-rank adventurer")
    assertEqual(backRank.cityTravelEvents[1].id, "stolen_gear_spotted",
        "A Theft should record the stolen-gear market-stall prompt")
    assertTrue(frontRank.cityTravelEvents == nil, "A Theft should not record against front-rank adventurers")

    local lowPentacles = base_entity.createEntity({
        id = "pc_city_event_low_pentacles",
        name = "City Event Low Pentacles",
        isPC = true,
        pentacles = 1,
    })
