    assertTrue(detail.target == highPentacles, "A Challenge should target highest Pentacles")
    assertEqual(detail.suitValue, 5, "A Challenge should report the target's Pentacles score")
    assertEqual(highPentacles.cityTravelEvents[1].id, "bravos_challenge",
        "A Challenge should record the bravos fight prompt")

    local lowWands = base_entity.createEntity({
        id = "pc_city_event_low_wands",
        name = "City Event Low Wands",
        isPC = true,
        wands = 0,
    })
    local highWands = base_entity.createEntity({
        id = "pc_city_event_high_wands",
        name = "City Event High Wands",
        isPC = true,
        wands = 4,
    })
    local propositionController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { lowWands, highWands },
    })
    ok = propositionController:resolveCityEvent({
        majorCard = {
            name = "The Moon",
            value = 18,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
    })
    assertTrue(ok, "A Proposition City Event should resolve")
    ok, result, detail = propositionController:resolveCityEventConsequences()
    assertTrue(ok, "A Proposition should resolve its highest-Wands target")
    assertTrue(detail.target == highWands, "A Proposition should target highest Wands")
    assertEqual(highWands.cityTravelEvents[1].id, "discounted_proposition",
        "A Proposition should record the proposition prompt")

    local lowCups = base_entity.createEntity({
        id = "pc_city_event_low_cups",
        name = "City Event Low Cups",
        isPC = true,
        cups = 0,
    })
    local highCups = base_entity.createEntity({
        id = "pc_city_event_high_cups",
        name = "City Event High Cups",
        isPC = true,
        cups = 3,
    })
    local inheritanceController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { highCups, lowCups },
    })
    ok = inheritanceController:resolveCityEvent({
        majorCard = {
            name = "The Sun",
            value = 19,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
    })
    assertTrue(ok, "An Inheritance City Event should resolve")
    ok, result, detail = inheritanceController:resolveCityEventConsequences()
    assertTrue(ok, "An Inheritance should resolve its lowest-Cups target")
    assertTrue(detail.target == lowCups, "An Inheritance should target lowest Cups")
    assertEqual(detail.property.id, "grey_river_townhouse", "An Inheritance should create the townhouse property")
    assertEqual(lowCups.cityProperties.grey_river_townhouse.butler, "Aethelred",
        "An Inheritance should preserve the snooty butler detail")

    local starWatcher = base_entity.createEntity({
        id = "pc_city_event_blood_star_watcher",
        name = "City Event Blood Star Watcher",
        isPC = true,
    })
    starWatcher.conditions = {}
    local starSleeper = base_entity.createEntity({
        id = "pc_city_event_blood_star_sleeper",
        name = "City Event Blood Star Sleeper",
        isPC = true,
    })
    starSleeper.conditions = {}
    local bloodStarController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { starWatcher, starSleeper },
    })
    ok = bloodStarController:resolveCityEvent({
        majorCard = {
            name = "The World",
            value = 21,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
        minorDiscardCard = {
            name = "Two of Cups",
            value = 2,
            suit = constants.SUITS.CUPS,
        },
    })
    assertTrue(ok, "Blood-Red Star Signs and Portents should resolve")
    ok, result, detail = bloodStarController:resolveEndOfCityPhase()
    assertTrue(ok, "City Phase end should resolve Blood-Red Star consequences")
    assertEqual(detail.cityEventConsequences.result, "city_event_next_crawl_condition_resolved",
        "Blood-Red Star should report next-Crawl condition consequences")
    assertEqual(detail.cityEventConsequences.condition, "stressed",
        "Blood-Red Star should queue the Stressed condition")
    assertEqual(#detail.cityEventConsequences.affectedActors, 2,
        "Blood-Red Star should affect every active guild member")
    assertTrue(starWatcher.nextCrawlConditions and starWatcher.nextCrawlConditions.stressed,
        "Blood-Red Star should queue Stressed for the next Crawl")
    assertTrue(starSleeper.conditions.stressed,
        "Blood-Red Star should mark Stressed for the next Crawl transition")

    local trapped = base_entity.createEntity({
        id = "pc_city_event_fire_trapped",
        name = "City Event Fire Trapped",
        isPC = true,
    })
    trapped.conditions = {}
    trapped.inventory = inventory.createInventory()
    trapped.inventory:addItem(inventory.createItem({ name = "Satchel Top" }), inventory.LOCATIONS.PACK)
    trapped.inventory:addItem(inventory.createItem({ name = "Satchel Middle" }), inventory.LOCATIONS.PACK)
    trapped.inventory:addItem(inventory.createItem({ name = "Satchel Bottom" }), inventory.LOCATIONS.PACK)
    local swift = base_entity.createEntity({
        id = "pc_city_event_fire_swift",
        name = "City Event Fire Swift",
        isPC = true,
    })
    swift.conditions = {}
    swift.inventory = inventory.createInventory()
    swift.inventory:addItem(inventory.createItem({ name = "Lucky Cup" }), inventory.LOCATIONS.PACK)
    local fireController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { trapped, swift },
    })
    ok = fireController:resolveCityEvent({
        majorCard = {
            name = "Judgement",
            value = 20,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
    })
    assertTrue(ok, "A Disaster: Fire City Event should resolve")
    ok, result, detail = fireController:resolveCityEventConsequences({
        fireEscapeResults = {
            pc_city_event_fire_trapped = false,
            pc_city_event_fire_swift = true,
        },
    })
    assertTrue(ok, "A Disaster: Fire should resolve explicit Pentacles outcomes")
    assertEqual(result, "city_event_fire_resolved", "fire consequences should report resolution")
    assertEqual(#detail.failedActors, 1, "fire should record failed adventurers")
    assertEqual(#detail.successfulActors, 1, "fire should record successful adventurers")
    assertEqual(#detail.lostItems, 2, "failed fire escape should lose two bottom pack items")
    assertEqual(detail.lostItems[1].item.name, "Satchel Bottom", "fire should lose the deepest pack item first")
    assertEqual(detail.lostItems[2].item.name, "Satchel Middle", "fire should lose the second-deepest pack item")
    assertTrue(trapped.conditions.stressed, "failed fire escape should immediately mark Stressed")
    assertTrue(trapped.nextCrawlConditions and trapped.nextCrawlConditions.stressed,
        "failed fire escape should queue Stressed for the next Crawl")
    assertTrue(not swift.conditions.stressed, "successful fire escape should not become Stressed")
    assertEqual(#trapped.inventory:getItems(inventory.LOCATIONS.PACK), 1,
        "failed fire escape should leave remaining pack items intact")
    assertEqual(trapped.inventory:getItems(inventory.LOCATIONS.PACK)[1].name, "Satchel Top",
        "fire should leave items above the bottom of the pack")
    assertEqual(#swift.inventory:getItems(inventory.LOCATIONS.PACK), 1,
        "successful fire escape should keep pack contents")

    ok, result, detail = fireController:resolveEndOfCityPhase()
    assertTrue(ok, "City Phase end should still resolve after fire consequences")
    assertEqual(detail.cityEventConsequences.result, "city_event_fire_resolved",
        "City Phase end should carry already-resolved fire consequences")
    assertEqual(#trapped.inventory:getItems(inventory.LOCATIONS.PACK), 1,
        "City Phase end should not re-apply already-resolved fire item loss")
end

local function checkCityPhaseEndMaledictionConsequences()
    local cursed = base_entity.createEntity({
        id = "pc_city_dogs_hate",
        name = "City Dogs Hate",
        isPC = true,
    })
    cursed.conditions = {}
    cursed.malediction = {
        active = true,
        curse = {
            flags = { cityPhaseDogCurse = true, dogsHateYou = true },
            metadata = {
                cityPhaseConditionChance = {
                    staggered = 0.5,
                    stressed = 0.5,
                },
            },
        },
    }

    local calm = base_entity.createEntity({
        id = "pc_city_no_dog_curse",
        name = "City No Dog Curse",
        isPC = true,
    })
    calm.conditions = {}

    local emitted = nil
    local phaseChanged = nil
    local bus = events.createEventBus()
    bus:on(events.EVENTS.CITY_PHASE_ENDED, function(data)
        emitted = data
    end)
    bus:on(events.EVENTS.PHASE_CHANGED, function(data)
        phaseChanged = data
    end)
    local controller = city_phase.createCityPhaseController({
        eventBus = bus,
        guild = { cursed, calm },
    })

    local ok, result, detail = controller:resolveEndOfCityPhase({
        dogCurseCondition = {
            pc_city_dogs_hate = "staggered",
        },
    })
    assertTrue(ok, "City Phase end should resolve")
    assertEqual(result, "city_phase_ended", "City Phase end should report completion")
    assertTrue(cursed.conditions.staggered, "Dogs Hate You should mark a City-end Staggered outcome")
    assertTrue(not cursed.conditions.stressed, "explicit Staggered dog-curse outcome should not also stress")
    assertTrue(not calm.conditions.staggered and not calm.conditions.stressed,
        "uncursed City Phase members should not receive dog-curse consequences")
    assertEqual(#detail.dogCurseConsequences, 1, "City Phase end should record one dog-curse consequence")
    assertEqual(detail.dogCurseConsequences[1].condition, "staggered",
        "City Phase end should record the selected dog-curse condition")
    assertTrue(emitted == detail, "City Phase end should emit its detail")
    assertTrue(phaseChanged and phaseChanged.oldPhase == "city" and phaseChanged.newPhase == "crawl",
        "City Phase end should emit a phase transition")

    ok, result = controller:resolveEndOfCityPhase()
    assertTrue(not ok, "City Phase end should resolve only once")
    assertEqual(result, "City Phase already ended", "repeat City Phase end should explain existing resolution")

    local stressedCursed = base_entity.createEntity({
        id = "pc_city_dogs_stressed",
        name = "City Dogs Stressed",
        isPC = true,
    })
    stressedCursed.conditions = {}
    stressedCursed.cityPhaseDogCurse = true
    local stressedController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { stressedCursed },
    })
    ok, result = stressedController:resolveEndOfCityPhase({
        dogCurseCondition = "stressed",
    })
    assertTrue(ok, "City Phase end should accept explicit Stressed dog-curse outcome")
    assertTrue(stressedCursed.conditions.stressed,
        "Dogs Hate You should mark a City-end Stressed outcome")

    do
        local prayerBus = events.createEventBus()
        local expired = {}
        local cityResolved = nil
        prayerBus:on(events.EVENTS.CONDITION_EXPIRED, function(data)
            expired[#expired + 1] = data
        end)
        prayerBus:on(events.EVENTS.CITY_ACTION_RESOLVED, function(data)
            cityResolved = data
        end)

        local sorcerer = base_entity.createEntity({
            id = "pc_city_prayer_welkin",
            name = "City Prayer Welkin",
            isPC = true,
            talents = {
                magic_of_the_welkin = { mastered = true },
            },
        })
        local resolver = action_resolver.createActionResolver({
            eventBus = prayerBus,
        })

        local exhaustedRecord = resolver:triggerMaleficence(sorcerer, "welkin", "smoke_test", {
            spell = { id = "heavenfire", branch = "welkin" },
        })
        local exhausted = resolver:resolvePendingMaleficence(sorcerer, {
            record = exhaustedRecord,
            value = 6,
            allEntities = { sorcerer },
        })
        assertTrue(exhausted.success, "Welkin VI Piteous Stigmata should resolve from table data")
        assertTrue(sorcerer.conditions.exhausted, "Welkin VI should mark Exhausted")
        assertEqual(sorcerer.conditionDurations.exhausted["until"], "city_prayer",
            "Welkin VI Exhausted should last until City prayer")
        assertEqual(sorcerer.maleficenceConditionMetadata.exhausted.stigmataOf, "Mythrys",
            "Welkin VI should preserve the piteous stigmata source")
        assertEqual(sorcerer.maleficenceConditionMetadata.exhausted.prayerLocation, "mythraeum",
            "Welkin VI should preserve the Mythraeum prayer location")

        local haloRecord = resolver:triggerMaleficence(sorcerer, "welkin", "smoke_test", {
            spell = { id = "heavenfire", branch = "welkin" },
        })
        local halo = resolver:resolvePendingMaleficence(sorcerer, {
            record = haloRecord,
            value = 8,
            allEntities = { sorcerer },
        })
        assertTrue(halo.success, "Welkin VIII Halo should resolve from table data")
        assertTrue(sorcerer.conditions.halo, "Welkin VIII should mark Halo")
        assertEqual(sorcerer.conditionDurations.halo["until"], "city_prayer",
            "Welkin VIII Halo should last until City prayer")
        assertTrue(sorcerer.maleficenceConditionMetadata.halo.suitablyImpressive,
            "Welkin VIII should preserve suitably-impressed metadata")
        assertTrue(sorcerer.maleficenceConditionMetadata.halo.spiritCombatPriority,
            "Welkin VIII should preserve spirit combat-priority metadata")

        sorcerer.conditions.silenced = true
        sorcerer.conditionDurations.silenced = { ["until"] = "fool_reshuffle" }

        local prayerController = city_phase.createCityPhaseController({
            eventBus = prayerBus,
            guild = { sorcerer },
        })
        ok, result, detail = prayerController:resolveAction(sorcerer, {
            type = "pray_at_mythraeum",
        })
        assertTrue(ok, "City prayer should resolve through the City Action facade")
        assertEqual(result, "city_prayer_complete", "City prayer should report completion")
        assertTrue(not sorcerer.conditions.exhausted, "City prayer should clear Welkin VI Exhausted")
        assertTrue(not sorcerer.conditions.halo, "City prayer should clear Welkin VIII Halo")
        assertTrue(sorcerer.conditions.silenced, "City prayer should leave non-city-prayer conditions")
        assertTrue(sorcerer.conditionDurations and sorcerer.conditionDurations.silenced and
            not sorcerer.conditionDurations.exhausted and not sorcerer.conditionDurations.halo,
            "City prayer should remove only city-prayer duration metadata")
        assertEqual(#detail.conditionsCleared, 2, "City prayer should report both cleared conditions")
        assertTrue(hasValue(detail.conditionsCleared, "exhausted"),
            "City prayer detail should include Exhausted")
        assertTrue(hasValue(detail.conditionsCleared, "halo"), "City prayer detail should include Halo")
        assertEqual(#expired, 2, "City prayer should emit condition-expired events")
        assertEqual(expired[1].timing, "city_prayer", "City prayer expiry event should carry timing")
        assertTrue(cityResolved and cityResolved.action == city_phase.ACTIONS.PRAY_AT_MYTHRAEUM,
            "City prayer should emit normalized City Action details")
        assertTrue(prayerController:hasActed(sorcerer), "City prayer should consume a successful City Action")
    end
end

local function checkCityPhaseTurnInContracts()
    local weela = base_entity.createEntity({
        id = "pc_city_contract_weela",
        name = "City Contract Weela",
        isPC = true,
    })
    weela.gold = 0
    weela.xp = 0
    weela.inventory = inventory.createInventory()
    local alisander = base_entity.createEntity({
        id = "pc_city_contract_alisander",
        name = "City Contract Alisander",
        isPC = true,
    })
    alisander.gold = 0
    alisander.xp = 2
    alisander.inventory = inventory.createInventory()
    local lucind = base_entity.createEntity({
        id = "pc_city_contract_lucind",
        name = "City Contract Lucind",
        isPC = true,
    })
    lucind.gold = 10
    lucind.xp = 1
    lucind.inventory = inventory.createInventory()

    local contracts = {
        {
            id = "basilisk_eggs",
            name = "Basilisk Eggs for Master Underhill",
            completed = true,
            quantity = 6,
            rewardPerItem = 50,
        },
        {
            id = "unopened_contract",
            name = "Find the Fallen Star",
            completed = false,
            rewardGold = 500,
        },
    }
    local treasury = { gold = 0 }
    local bus = events.createEventBus()
    local emitted = nil
    bus:on(events.EVENTS.CITY_CONTRACTS_TURNED_IN, function(data)
        emitted = data
    end)

    local controller = city_phase.createCityPhaseController({
        eventBus = bus,
        guild = { weela, alisander, lucind },
        contracts = contracts,
        guildTreasury = treasury,
    })

    local contractOptions = controller:getTurnInContractsOptions()
    assertEqual(contractOptions.step, city_phase.STEPS.TURN_IN_CONTRACTS,
        "Turn-in contract options should identify the City Phase step")
    assertEqual(contractOptions.completedCount, 1,
        "Turn-in contract options should count completed unturned contracts")
    assertEqual(contractOptions.totalGold, 300,
        "Turn-in contract options should preview per-item rewards")
    assertEqual(contractOptions.turnInContracts[1].distribution.perRecipient, 100,
        "Turn-in contract options should preview guild reward splits")
    assertEqual(contractOptions.xpAwarded, 1,
        "Turn-in contract options should preview rulebook XP per completed contract")
    assertEqual(contractOptions.xpRecipients[2].projectedXP, 3,
        "Turn-in contract options should preview recipient XP totals")
    assertEqual(contractOptions.contracts[2].unavailableReason, "Selected contract incomplete",
        "Turn-in contract options should explain incomplete contract choices")
    assertEqual(weela.gold, 0, "Turn-in contract options should not pay gold during preview")

    local ok, result, detail = controller:resolveTurnInContracts()
    assertTrue(ok, "Turn in contracts should resolve as a City Phase step")
    assertEqual(result, "contracts_turned_in", "completed contracts should report turned in")
    assertEqual(detail.completedCount, 1, "Turn in contracts should count only completed contracts")
    assertEqual(detail.totalGold, 300, "Turn in contracts should pay per-item rewards")
    assertEqual(detail.contracts[1].distribution.perRecipient, 100, "Turn in contracts should split rewards across the guild")
    assertEqual(weela.gold, 100, "Turn in contracts should pay each guild member")
    assertEqual(alisander.gold, 100, "Turn in contracts should pay the second guild member")
    assertEqual(lucind.gold, 110, "Turn in contracts should add rewards to existing gold")
    assertEqual(treasury.gold, 0, "even contract split should leave no treasury remainder")
    assertEqual(weela.xp, 1, "Turn in contracts should grant 1XP per fulfilled contract")
    assertEqual(alisander.xp, 3, "Turn in contracts should add XP to existing totals")
    assertEqual(lucind.xp, 2, "Turn in contracts should grant each member XP")
    assertTrue(contracts[1].turnedIn, "Turn in contracts should mark completed contracts turned in")
    assertTrue(not contracts[2].turnedIn, "Turn in contracts should not turn in incomplete contracts")
    assertTrue(emitted and emitted.completedCount == 1, "Turn in contracts should emit step details")

    ok, result = controller:resolveTurnInContracts()
    assertTrue(not ok, "Turn in contracts should only resolve once per City Phase controller")
    assertEqual(result, "Contracts already turned in", "repeat Turn in contracts should explain existing resolution")
    contractOptions = controller:getTurnInContractsOptions()
    assertTrue(contractOptions.disabled, "Turn-in contract options should disable after the step resolves")
    assertEqual(contractOptions.unavailableReason, "Contracts already turned in",
        "Turn-in contract options should explain repeat turn-ins")

    local selectedActor = base_entity.createEntity({
        id = "pc_city_contract_selector",
        name = "City Contract Selector",
        isPC = true,
    })
    selectedActor.gold = 0
    selectedActor.xp = 0
    selectedActor.inventory = inventory.createInventory()
    local selectedPatron = {
        id = "patron_underhill",
        name = "Master Underhill",
    }
    local selectedContracts = {
        {
            id = "completed_unselected",
            name = "Completed but Unselected",
            completed = true,
            rewardGold = 20,
        },
        {
            id = "relic_return",
            name = "Return the Brass Reliquary",
            completed = true,
            rewardGold = 75,
            patron = selectedPatron,
        },
    }
    local selectedRoster = {}
    local selectedController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { selectedActor },
        contracts = selectedContracts,
        guildRoster = selectedRoster,
    })
    local selectedPatronInteractions = {
        relic_return = {
            scene = "The patron counts the relic's teeth before paying.",
            reaction = "pleased",
            disposition = "trust",
            notes = "Offer a future reliquary commission.",
        },
    }
    contractOptions = selectedController:getTurnInContractsOptions({
        selectedContractIds = { "relic_return" },
        patronInteractions = selectedPatronInteractions,
    })
    assertTrue(not contractOptions.disabled, "Turn-in options should accept selected completed contracts")
    assertTrue(contractOptions.selected, "Turn-in options should report selected-only previews")
    assertEqual(contractOptions.selectedContractIds[1], "relic_return",
        "Turn-in options should preserve selected IDs")
    assertEqual(contractOptions.turnInContracts[1].distribution.perRecipient, 75,
        "Turn-in options should preview selected contract payout")
    assertEqual(contractOptions.patronInteractions[1].scene,
        "The patron counts the relic's teeth before paying.",
        "Turn-in options should preview patron role-play scenes")
    assertTrue(selectedPatron.disposition == nil, "Turn-in options should not mutate patron Disposition")
    ok, result, detail = selectedController:resolveTurnInContracts({
        selectedContractIds = { "relic_return" },
        patronInteractions = selectedPatronInteractions,
    })
    assertTrue(ok, "Turn in contracts should resolve explicitly selected completed contracts")
    assertEqual(result, "contracts_turned_in", "selected completed contracts should report turned in")
    assertTrue(detail.selected, "Turn in contracts should report when selection was used")
    assertEqual(detail.selectedContractIds[1], "relic_return", "Turn in contracts should report selected IDs")
    assertEqual(detail.completedCount, 1, "selected turn-in should count only selected contracts")
    assertEqual(selectedActor.gold, 75, "selected turn-in should pay the selected contract reward")
    assertEqual(selectedActor.xp, 1, "selected turn-in should grant XP for the selected contract only")
    assertTrue(not selectedContracts[1].turnedIn, "selected turn-in should leave unselected completed contracts open")
    assertTrue(selectedContracts[2].turnedIn, "selected turn-in should mark the selected contract")
    assertEqual(detail.contracts[1].patronInteraction.scene,
        "The patron counts the relic's teeth before paying.",
        "selected turn-in should preserve patron role-play scene text")
    assertEqual(detail.patronInteractions[1].patronName, "Master Underhill",
        "patron interaction should preserve patron identity")
    assertEqual(selectedPatron.disposition, "trust", "patron interaction should update patron disposition")
    assertEqual(selectedPatron.lastContractReaction, "pleased",
        "patron interaction should record patron reaction on the patron")
    assertEqual(selectedContracts[2].patronHistory[1], detail.patronInteractions[1],
        "selected contract should retain patron interaction history")
    assertEqual(selectedRoster.contractPatronInteractions[1], detail.patronInteractions[1],
        "guild roster should retain patron interaction history")

    local incompleteSelectedController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        contracts = {
            { id = "open_selected_contract", completed = false, rewardGold = 50 },
        },
    })
    contractOptions = incompleteSelectedController:getTurnInContractsOptions({
        selectedContractIds = { "open_selected_contract" },
    })
    assertTrue(contractOptions.disabled, "Turn-in options should disable selected incomplete contracts")
    assertEqual(contractOptions.unavailableReason, "Selected contract incomplete",
        "Turn-in options should explain selected incomplete contracts")
    assertEqual(contractOptions.invalidSelectedContracts[1].reason, "Selected contract incomplete",
        "Turn-in options should preserve invalid selected contract details")
    ok, result = incompleteSelectedController:resolveTurnInContracts({
        selectedContractIds = { "open_selected_contract" },
    })
    assertTrue(not ok, "selected turn-in should reject incomplete contracts")
    assertEqual(result, "Selected contract incomplete",
        "selected incomplete contract should explain why turn-in failed")
    assertTrue(not incompleteSelectedController.contractsResolved,
        "failed selected turn-in should not mark contracts resolved")

    local noContractController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { weela },
        contracts = {
            { id = "still_open", completed = false, rewardGold = 100 },
        },
    })
    contractOptions = noContractController:getTurnInContractsOptions()
    assertTrue(not contractOptions.disabled, "Turn-in options should allow no-completed-contract resolution")
    assertEqual(contractOptions.resultPreview, "no_completed_contracts",
        "Turn-in options should preview the no-completed-contract result")
    ok, result, detail = noContractController:resolveTurnInContracts()
    assertTrue(ok, "Turn in contracts should gracefully skip when no contracts are complete")
    assertEqual(result, "no_completed_contracts", "no completed contracts should report skip state")
    assertEqual(detail.completedCount, 0, "no completed contracts should not count open contracts")

    local remainderA = base_entity.createEntity({
        id = "pc_city_contract_remainder_a",
        name = "City Contract Remainder A",
        isPC = true,
    })
    remainderA.gold = 0
    remainderA.inventory = inventory.createInventory()
    local remainderB = base_entity.createEntity({
        id = "pc_city_contract_remainder_b",
        name = "City Contract Remainder B",
        isPC = true,
    })
    remainderB.gold = 0
    remainderB.inventory = inventory.createInventory()
    local remainderTreasury = { gold = 0 }
    local remainderController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { remainderA, remainderB },
        contracts = {
            { id = "odd_reward", completed = true, rewardGold = 5 },
        },
        guildTreasury = remainderTreasury,
    })
    contractOptions = remainderController:getTurnInContractsOptions()
    assertEqual(contractOptions.turnInContracts[1].distribution.remainder, 1,
        "Turn-in options should preview treasury remainders")
    assertEqual(contractOptions.turnInContracts[1].distribution.projectedTreasuryGold, 1,
        "Turn-in options should preview projected treasury gold")
    ok, result, detail = remainderController:resolveTurnInContracts()
    assertTrue(ok, "Turn in contracts should resolve uneven reward splits")
    assertEqual(remainderA.gold, 2, "uneven contract reward should pay floor split")
    assertEqual(remainderB.gold, 2, "uneven contract reward should pay every recipient")
    assertEqual(remainderTreasury.gold, 1, "uneven contract reward should retain remainder in guild treasury")
    assertEqual(detail.contracts[1].distribution.remainder, 1, "uneven contract reward should report treasury remainder")
end

local function checkCityPhaseSellTreasure()
    local seller = base_entity.createEntity({
        id = "pc_city_treasure_seller",
        name = "City Treasure Seller",
        isPC = true,
    })
    seller.gold = 5
    seller.inventory = inventory.createInventory()
    local ring = inventory.createItemFromTemplate("ruby_ring")
    local amulet = inventory.createItemFromTemplate("golden_amulet")
    ring.properties.provenance = {
        source = "Tomb of Golden Ghosts",
        roomId = "golden_idol_shrine",
    }
    seller.inventory:addItem(ring, inventory.LOCATIONS.PACK)
    seller.inventory:addItem(amulet, inventory.LOCATIONS.PACK)

    local bus = events.createEventBus()
    local emitted = nil
    bus:on(events.EVENTS.CITY_TREASURE_SOLD, function(data)
        emitted = data
    end)
    local controller = city_phase.createCityPhaseController({
        eventBus = bus,
        guild = { seller },
    })

    local treasureOptions = controller:getSellTreasureOptions(seller, {
        itemIds = {
            ring.id,
            {
                id = amulet.id,
                value = 80,
                appraisal = "A merchant will give you 80 gold for it.",
                buyer = "Omphalic Goldsmith",
            },
        },
        values = {
            [amulet.id] = 80,
        },
        appraisals = {
            [ring.id] = "Ruby is cleanly cut and fashionable this season.",
        },
        buyer = "Omphalic Market",
        appraiser = "Master Volant",
    })
    assertTrue(not treasureOptions.disabled, "Treasure sale options should allow selected non-liquid treasure")
    assertEqual(treasureOptions.selectedCount, 2, "Treasure sale options should preview selected treasure items")
    assertEqual(treasureOptions.totalGold, 130, "Treasure sale options should preview fixed and GM-adjudicated values")
    assertEqual(treasureOptions.projectedGold, 135, "Treasure sale options should preview seller gold after sale")
    assertEqual(treasureOptions.selectedItems[1].appraisal, "Ruby is cleanly cut and fashionable this season.",
        "Treasure sale options should preview appraisal notes")
    assertEqual(treasureOptions.selectedItems[2].buyer, "Omphalic Goldsmith",
        "Treasure sale options should preview item-specific buyers")
    assertTrue(seller.inventory:findItem(ring.id) ~= nil,
        "Treasure sale options should not remove items during preview")

    local ok, result, detail = controller:resolveSellTreasure(seller, {
        itemIds = {
            ring.id,
            {
                id = amulet.id,
                value = 80,
                appraisal = "A merchant will give you 80 gold for it.",
                buyer = "Omphalic Goldsmith",
            },
        },
        values = {
            [amulet.id] = 80,
        },
        appraisals = {
            [ring.id] = "Ruby is cleanly cut and fashionable this season.",
        },
        buyer = "Omphalic Market",
        appraiser = "Master Volant",
    })
    assertTrue(ok, "City Phase should sell non-liquid treasure before Upkeep")
    assertEqual(result, "treasure_sold", "treasure sale should report completion")
    assertEqual(detail.totalGold, 130, "treasure sale should use item value or explicit GM value")
    assertEqual(seller.gold, 135, "treasure sale should pay the seller before Upkeep")
    assertTrue(seller.inventory:findItem(ring.id) == nil, "sold treasure should leave inventory")
    assertTrue(seller.inventory:findItem(amulet.id) == nil, "explicit-value sold treasure should leave inventory")
    assertEqual(detail.items[1].provenance.roomId, "golden_idol_shrine",
        "treasure sale should preserve item provenance")
    assertEqual(detail.items[1].appraisal, "Ruby is cleanly cut and fashionable this season.",
        "treasure sale should preserve item appraisal notes")
    assertEqual(detail.items[2].buyer, "Omphalic Goldsmith",
        "treasure sale should preserve item-specific buyers")
    assertEqual(seller.treasureSales[1].items[2].appraisal, "A merchant will give you 80 gold for it.",
        "treasure sale should persist sale provenance in the seller history")
    assertTrue(emitted and emitted.totalGold == 130, "treasure sale should emit sale details")

    local coinSeller = base_entity.createEntity({
        id = "pc_city_coin_seller",
        name = "City Coin Seller",
        isPC = true,
    })
    coinSeller.gold = 0
    coinSeller.inventory = inventory.createInventory()
    local coins = inventory.createItemFromTemplate("gold_coins_15")
    coinSeller.inventory:addItem(coins, inventory.LOCATIONS.PACK)
    local coinController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { coinSeller },
    })
    treasureOptions = coinController:getSellTreasureOptions(coinSeller, {
        itemIds = { coins.id },
    })
    assertTrue(treasureOptions.disabled, "Treasure sale options should disable liquid coin sales")
    assertEqual(treasureOptions.unavailableReason, "Item is not non-liquid treasure",
        "Treasure sale options should explain liquid coin rejection")
    ok, result = coinController:resolveSellTreasure(coinSeller, {
        itemIds = { coins.id },
    })
    assertTrue(not ok, "treasure sale should not treat liquid coin as non-liquid treasure")
    assertEqual(result, "Item is not non-liquid treasure", "liquid coin sale should explain rejection")
    assertTrue(coinSeller.inventory:findItem(coins.id) ~= nil, "rejected coin sale should leave coin stack carried")

    local junkSeller = base_entity.createEntity({
        id = "pc_city_junk_seller",
        name = "City Junk Seller",
        isPC = true,
    })
    junkSeller.gold = 0
    junkSeller.inventory = inventory.createInventory()
    local junk = inventory.createItem({ name = "Rusty Pot" })
    junkSeller.inventory:addItem(junk, inventory.LOCATIONS.PACK)
    local junkController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { junkSeller },
    })
    ok, result = junkController:resolveSellTreasure(junkSeller, {
        itemIds = { junk.id },
    })
    assertTrue(not ok, "treasure sale should reject ordinary gear without treasure value")
    assertEqual(result, "Item is not non-liquid treasure", "ordinary gear sale should explain rejection")
    assertEqual(junkSeller.gold, 0, "failed treasure sale should not pay gold")
    assertTrue(junkSeller.inventory:findItem(junk.id) ~= nil, "failed treasure sale should leave item carried")
end

local function checkCityPhasePlanNextCrawl()
    local offers = {
        { id = "rat_cellar", name = "Rat Cellar Cleanup", rewardGold = 50 },
        { id = "sepulcher_titans", name = "Sepulcher of Titans Survey", rewardGold = 120 },
        { id = "star_daughter", name = "Star Daughter Dowry", rewardGold = 200 },
        { id = "mushroom_forest", name = "Mushroom Forest Samples", rewardGold = 75 },
        { id = "missing_butler", name = "Missing Butler Aethelred", rewardGold = 30 },
    }
    local existing = {
        { id = "old_contract", name = "Old Open Contract", status = "active" },
    }
    local roster = {}
    local bus = events.createEventBus()
    local emitted = nil
    bus:on(events.EVENTS.CITY_NEXT_CRAWL_PLANNED, function(data)
        emitted = data
    end)

    local controller = city_phase.createCityPhaseController({
        eventBus = bus,
        contracts = existing,
        jobBoard = offers,
        guildRoster = roster,
    })

    local planOptions = controller:getPlanNextCrawlOptions({
        selectedContractIds = { "rat_cellar", "star_daughter" },
        destination = "Rat Cellar",
        notes = "Seal two jobs, then return below.",
    })
    assertEqual(planOptions.offeredCount, 5, "Plan the next Crawl options should expose the tavern job board")
    assertEqual(planOptions.currentContractCount, 1,
        "Plan the next Crawl options should expose current guild contracts")
    assertEqual(planOptions.selectedCount, 2, "Plan the next Crawl options should preview selected contracts")
    assertTrue(planOptions.jobBoardOptions[1].selected,
        "Plan the next Crawl options should mark selected board contracts")
    assertTrue(not planOptions.jobBoardOptions[1].disabled,
        "Plan the next Crawl options should leave fresh offered contracts selectable")
    assertEqual(planOptions.destination, "Rat Cellar",
        "Plan the next Crawl options should preview the chosen destination")

    local ok, result, detail = controller:resolvePlanNextCrawl({
        selectedContractIds = { "rat_cellar", "star_daughter" },
        destination = "Rat Cellar",
        notes = "Seal two jobs, then return below.",
    })
    assertTrue(ok, "Plan the next Crawl should resolve as a City Phase step")
    assertEqual(result, "next_crawl_planned", "Plan the next Crawl should report completion")
    assertEqual(detail.offeredCount, 5, "Plan the next Crawl should present the job-board contracts")
    assertEqual(detail.signedCount, 2, "Plan the next Crawl should sign selected offered contracts")
    assertTrue(offers[1].signed and offers[1].sealed, "selected contracts should be sealed by the guild")
    assertTrue(offers[3].signed and offers[3].sealed, "multiple selected contracts should be sealed")
    assertEqual(#existing, 3, "signed contracts should join current guild contracts")
    assertEqual(existing[2].id, "rat_cellar", "first signed contract should be appended to current contracts")
    assertEqual(existing[3].id, "star_daughter", "second signed contract should be appended to current contracts")
    assertEqual(roster.currentContracts, existing, "Plan the next Crawl should update the guild roster contract list")
    assertEqual(roster.nextDestination, "Rat Cellar", "Plan the next Crawl should record the chosen destination")
    assertEqual(roster.nextCrawlNotes, "Seal two jobs, then return below.", "Plan the next Crawl should record guild discussion notes")
    assertTrue(emitted and emitted.signedCount == 2, "Plan the next Crawl should emit planning details")

    ok, result = controller:resolvePlanNextCrawl({
        selectedContractIds = { "sepulcher_titans" },
    })
    assertTrue(not ok, "Plan the next Crawl should resolve only once per City Phase controller")
    assertEqual(result, "Next Crawl already planned", "repeat Plan the next Crawl should explain existing resolution")
    planOptions = controller:getPlanNextCrawlOptions({
        selectedContractIds = { "sepulcher_titans" },
    })
    assertTrue(planOptions.disabled, "Plan the next Crawl options should disable already-planned controllers")
    assertEqual(planOptions.unavailableReason, "Next Crawl already planned",
        "Plan the next Crawl options should report repeat-planning reasons")

    local questRoster = {}
    local questController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        jobBoard = offers,
        guildRoster = questRoster,
        contracts = {},
    })
    planOptions = questController:getPlanNextCrawlOptions({
        currentQuest = "Alisander's necromantic errand",
        destination = "Sepulcher of Titans",
    })
    assertTrue(planOptions.continuationPlanned,
        "Plan the next Crawl options should expose continuing a quest without signing a contract")
    assertTrue(planOptions.continueCurrentQuestOption.selected,
        "Plan the next Crawl options should select the continue-current-quest branch")
    assertEqual(planOptions.continueCurrentQuestOption.destination, "Sepulcher of Titans",
        "Plan the next Crawl options should preview quest destination choices")
    ok, result, detail = questController:resolvePlanNextCrawl({
        currentQuest = "Alisander's necromantic errand",
        destination = "Sepulcher of Titans",
    })
    assertTrue(ok, "Plan the next Crawl should allow continuing a quest without sealing a new contract")
    assertEqual(detail.signedCount, 0, "continuing a quest should not require a new contract")
    assertEqual(questRoster.currentQuest, "Alisander's necromantic errand", "Plan the next Crawl should record current quest direction")
    assertEqual(questRoster.nextDestination, "Sepulcher of Titans", "Plan the next Crawl should record the next destination")

    local shortBoardController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        jobBoard = {
            { id = "a" },
            { id = "b" },
            { id = "c" },
        },
    })
    planOptions = shortBoardController:getPlanNextCrawlOptions()
    assertTrue(planOptions.disabled, "Plan the next Crawl options should disable short job boards")
    assertEqual(planOptions.unavailableReason, "Job board should offer four to six contracts",
        "Plan the next Crawl options should explain short job boards")
    ok, result = shortBoardController:resolvePlanNextCrawl()
    assertTrue(not ok, "Plan the next Crawl should require the rulebook four-to-six contract job board")
    assertEqual(result, "Job board should offer four to six contracts", "short job board should explain requirement")
    assertTrue(not shortBoardController.nextCrawlPlanned, "failed job board validation should not mark the step planned")

    local unofferedController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        jobBoard = offers,
        contracts = {},
    })
    planOptions = unofferedController:getPlanNextCrawlOptions({
        selectedContractIds = { "not_on_board" },
    })
    assertTrue(planOptions.disabled, "Plan the next Crawl options should disable unoffered selected contracts")
    assertEqual(planOptions.unavailableReason, "Selected contract not on job board",
        "Plan the next Crawl options should explain unoffered selected contracts")
    assertEqual(planOptions.invalidSelectedContracts[1].contractId, "not_on_board",
        "Plan the next Crawl options should report the invalid selected contract")
    ok, result = unofferedController:resolvePlanNextCrawl({
        selectedContractIds = { "not_on_board" },
    })
    assertTrue(not ok, "Plan the next Crawl should reject contracts not offered on the job board")
    assertEqual(result, "Selected contract not on job board", "unoffered contract should explain rejection")
    assertEqual(#unofferedController.contracts, 0, "failed contract selection should not add contracts")

    local completedController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        jobBoard = {
            { id = "fresh_1" },
            { id = "fresh_2" },
            { id = "fresh_3" },
            { id = "fresh_4" },
            { id = "done_already", completed = true },
        },
        contracts = {},
    })
    planOptions = completedController:getPlanNextCrawlOptions({
        selectedContractIds = { "done_already" },
    })
    assertTrue(planOptions.disabled, "Plan the next Crawl options should disable completed selected contracts")
    assertEqual(planOptions.unavailableReason, "Selected contract already completed",
        "Plan the next Crawl options should explain completed selected contracts")
    assertTrue(planOptions.jobBoardOptions[5].disabled,
        "Plan the next Crawl options should mark completed board contracts unavailable")
    ok, result = completedController:resolvePlanNextCrawl({
        selectedContractIds = { "done_already" },
    })
    assertTrue(not ok, "Plan the next Crawl should reject completed contracts")
    assertEqual(result, "Selected contract already completed", "completed job-board contract should explain rejection")
    assertEqual(#completedController.contracts, 0, "failed completed contract selection should not add contracts")

    local jobBoardCards = {
        { name = "Ace of Swords", value = 1, suit = constants.SUITS.SWORDS },
        { name = "Two of Pentacles", value = 2, suit = constants.SUITS.PENTACLES },
        { name = "Three of Cups", value = 3, suit = constants.SUITS.CUPS },
        { name = "Four of Wands", value = 4, suit = constants.SUITS.WANDS },
        { name = "Five of Swords", value = 5, suit = constants.SUITS.SWORDS },
    }
    local generated, generationDetail = city_phase.generateJobBoard({
        jobBoardCards = jobBoardCards,
        idPrefix = "rat_milk",
    })
    assertEqual(#generated, 5, "card-generated job board should create one offer per card")
    assertEqual(generationDetail.cardCount, 5, "card-generated job board should report drawn card count")
    assertEqual(generated[1].templateId, "tricky_woo", "value I should map to the Tricky Woo contract")
    assertEqual(generated[1].cardRank, "I", "generated contracts should preserve the card-table rank")
    assertEqual(generated[5].templateId, "onion_jack", "value V should map to the Onion Jack bounty")
    assertEqual(generated[1].id, "rat_milk_01_tricky_woo_swords", "generated contract ids should be stable")

    local generatedController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        contracts = {},
    })
    planOptions = generatedController:getPlanNextCrawlOptions({
        generateJobBoard = true,
        jobBoardCards = jobBoardCards,
        idPrefix = "rat_milk",
        selectedContractIds = { "rat_milk_01_tricky_woo_swords" },
        destination = "Mouth of the Underworld",
    })
    assertEqual(planOptions.generatedJobBoard.cardCount, 5,
        "Plan the next Crawl options should preview card-generated job boards")
    assertEqual(planOptions.jobBoardOptions[1].templateId, "tricky_woo",
        "Plan the next Crawl options should expose generated contract metadata")
    assertTrue(planOptions.jobBoardOptions[1].selected,
        "Plan the next Crawl options should select generated contract offers")
    ok, result, detail = generatedController:resolvePlanNextCrawl({
        generateJobBoard = true,
        jobBoardCards = jobBoardCards,
        idPrefix = "rat_milk",
        selectedContractIds = { "rat_milk_01_tricky_woo_swords" },
        destination = "Mouth of the Underworld",
    })
    assertTrue(ok, "Plan the next Crawl should generate a job board from cards when requested")
    assertEqual(result, "next_crawl_planned", "generated job-board planning should report completion")
    assertEqual(detail.generatedJobBoard.cardCount, 5, "Plan the next Crawl should report generated board details")
    assertEqual(detail.signedContracts[1].templateId, "tricky_woo", "generated offers should be selectable contracts")
    assertEqual(#generatedController.contracts, 1, "selected generated contract should join current contracts")
    assertEqual(generatedController.jobBoard[5].templateId, "onion_jack", "generated board should be retained on the controller")

    local customContractTable = {
        [1] = {
            id = "amber_eye",
            title = "Recover the Amber Eye",
            patron = "The Glasswrights",
            objective = "Bring back the Amber Eye from the third lock.",
            rewardGold = 80,
            contractType = "recover",
        },
        [2] = {
            id = "bell_weather",
            title = "Chart the Bell Weather",
            patron = "Matron Holtz",
            objective = "Record three bell peals below the Old Choir.",
            rewardNote = "A warm bed and future gratitude.",
            contractType = "survey",
        },
        [3] = { id = "blue_wine", title = "Find Blue Wine", contractType = "gather" },
        [4] = { id = "salt_crown", title = "Salt the Crown", contractType = "ritual" },
    }
    local customCards = {
        { name = "Ace of Swords", value = 1, suit = constants.SUITS.SWORDS },
        { name = "Two of Cups", value = 2, suit = constants.SUITS.CUPS },
        { name = "Three of Wands", value = 3, suit = constants.SUITS.WANDS },
        { name = "Four of Pentacles", value = 4, suit = constants.SUITS.PENTACLES },
    }
    local customGenerated, customDetail = city_phase.generateJobBoard({
        jobBoardCards = customCards,
        contractTable = customContractTable,
        contractTableSource = "glass_tavern_contracts",
        idPrefix = "glass_tavern",
    })
    assertEqual(#customGenerated, 4, "custom contract tables should generate four-to-six job boards")
    assertEqual(customDetail.contractTableSource, "glass_tavern_contracts",
        "custom job-board generation should report the authored table source")
    assertEqual(customGenerated[1].templateId, "amber_eye", "custom value I should use the authored contract")
    assertEqual(customGenerated[1].source, "glass_tavern_contracts",
        "custom generated contracts should preserve table source")
    assertEqual(customGenerated[2].patron, "Matron Holtz", "custom generated contracts should preserve authored fields")
    local customController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        contracts = {},
        contractTable = customContractTable,
    })
    ok, result, detail = customController:resolvePlanNextCrawl({
        generateJobBoard = true,
        jobBoardCards = customCards,
        contractTableSource = "glass_tavern_contracts",
        idPrefix = "glass_tavern",
        selectedContractIds = { "glass_tavern_02_bell_weather_cups" },
        destination = "Old Choir",
    })
    assertTrue(ok, "Plan the next Crawl should generate boards from custom contract tables")
    assertEqual(detail.generatedJobBoard.contractTableSource, "glass_tavern_contracts",
        "Plan the next Crawl should report the custom contract table source")
    assertEqual(detail.signedContracts[1].templateId, "bell_weather",
        "custom generated offers should be selectable contracts")
    assertEqual(customController.contracts[1].patron, "Matron Holtz",
        "selected custom generated contracts should join current contracts with authored fields")

    local deckCards = {
        { name = "Five of Swords", value = 5, suit = constants.SUITS.SWORDS },
        { name = "Four of Wands", value = 4, suit = constants.SUITS.WANDS },
        { name = "Three of Cups", value = 3, suit = constants.SUITS.CUPS },
        { name = "Two of Pentacles", value = 2, suit = constants.SUITS.PENTACLES },
        { name = "Ace of Swords", value = 1, suit = constants.SUITS.SWORDS },
        { name = "The Fool", value = 0, suit = constants.SUITS.MAJOR, is_major = true },
    }
    local generatedDeck = {
        discarded = {},
        cards = deckCards,
        draw = function(self)
            return table.remove(self.cards)
        end,
        discard = function(self, card)
            self.discarded[#self.discarded + 1] = card
        end,
    }
    planOptions = city_phase.getPlanNextCrawlOptions({
        generateJobBoard = true,
        deck = generatedDeck,
        requireJobBoard = false,
    })
    assertTrue(planOptions.requiresJobBoardDraw,
        "Plan the next Crawl options should report when a generated board still needs a draw")
    assertTrue(planOptions.autoDrawAvailable,
        "Plan the next Crawl options should report available deck draws without mutating the deck")
    assertEqual(#generatedDeck.cards, 6,
        "Plan the next Crawl options should not draw deck-generated job boards during preview")
    generated, generationDetail = city_phase.generateJobBoard({
        deck = generatedDeck,
        idPrefix = "drawn_board",
    })
    assertEqual(#generated, 5, "job board generation should draw five cards by default")
    assertTrue(generationDetail.drawnFromDeck, "deck-generated job board should report deck drawing")
    assertEqual(#generationDetail.skippedCards, 1, "deck-generated job board should skip non-table cards")
    assertEqual(#generatedDeck.discarded, 6, "deck-generated job board should discard automatic draws and skipped cards")

    local shortGeneratedController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        contracts = {},
    })
    ok, result = shortGeneratedController:resolvePlanNextCrawl({
        generateJobBoard = true,
        jobBoardCards = {
            { name = "Ace of Swords", value = 1, suit = constants.SUITS.SWORDS },
            { name = "Two of Swords", value = 2, suit = constants.SUITS.SWORDS },
            { name = "Three of Swords", value = 3, suit = constants.SUITS.SWORDS },
        },
    })
    assertTrue(not ok, "generated job boards should still require four to six cards")
    assertEqual(result, "Job board should offer four to six contracts", "short generated job board should explain requirement")

    local invalidCardController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        contracts = {},
    })
    ok, result = invalidCardController:resolvePlanNextCrawl({
        generateJobBoard = true,
        jobBoardCards = {
            { name = "Ace of Swords", value = 1, suit = constants.SUITS.SWORDS },
            { name = "Two of Swords", value = 2, suit = constants.SUITS.SWORDS },
            { name = "Three of Swords", value = 3, suit = constants.SUITS.SWORDS },
            { name = "The Fool", value = 0, suit = constants.SUITS.MAJOR, is_major = true },
        },
    })
    assertTrue(not ok, "generated job boards should reject cards outside the example contract table")
    assertEqual(result, "Job board cards must map to contracts I through King", "invalid job-board card should explain contract-table range")
end

function checkCityPhaseQuestLifecycle()
    local delver = base_entity.createEntity({
        id = "pc_city_quest_delver",
        name = "City Quest Delver",
        isPC = true,
    })
    delver.xp = 0
    delver.inventory = inventory.createInventory()
    local scout = base_entity.createEntity({
        id = "pc_city_quest_scout",
        name = "City Quest Scout",
        isPC = true,
    })
    scout.xp = 1
    scout.inventory = inventory.createInventory()

    local roster = {}
    local questDeclarations = {}
    local questCompletions = {}
    local bus = events.createEventBus()
    local declaredEvent = nil
    local completedEvent = nil
    bus:on(events.EVENTS.CITY_QUEST_DECLARED, function(data)
        declaredEvent = data
    end)
    bus:on(events.EVENTS.CITY_QUEST_COMPLETED, function(data)
        completedEvent = data
    end)
    local controller = city_phase.createCityPhaseController({
        eventBus = bus,
        guild = { delver, scout },
        guildRoster = roster,
        questDeclarations = questDeclarations,
        questCompletions = questCompletions,
    })

    local ok, result, detail = controller:resolveDeclareGuildQuest({
        quest = "Recover the star-child's bell",
        guildAgrees = true,
        declaredBy = delver,
    })
    assertTrue(ok, "declaring a guild quest should resolve when everyone agrees")
    assertEqual(result, "guild_quest_declared", "declaring a guild quest should report completion")
    assertEqual(delver.xp, 3, "declaring an agreed quest should grant the declaring adventurer 3 XP")
    assertEqual(scout.xp, 4, "declaring an agreed quest should grant every guild member 3 XP")
    assertEqual(roster.currentQuest, "Recover the star-child's bell", "declaring a guild quest should set the current quest")
    assertEqual(#questDeclarations, 1, "declaring a guild quest should persist a declaration record")
    assertEqual(detail.xpAwarded, 3, "declaring a guild quest should report the rulebook XP award")
    assertTrue(declaredEvent and declaredEvent.quest == "Recover the star-child's bell",
        "declaring a guild quest should emit quest details")

    ok, result = controller:resolveDeclareGuildQuest({
        quest = "Open a second quest at the same time",
        guildAgrees = true,
    })
    assertTrue(not ok, "a guild should not pursue a second simultaneous quest")
    assertEqual(result, "Guild already pursuing a quest", "simultaneous quest declaration should explain the limit")
    assertEqual(delver.xp, 3, "failed simultaneous quest declaration should not grant XP")

    ok, result, detail = controller:resolveCompleteGuildQuest({
        notes = "The bell was carried back intact.",
    })
    assertTrue(ok, "completing the current guild quest should resolve")
    assertEqual(result, "guild_quest_completed", "completed guild quest should report completion")
    assertEqual(delver.xp, 6, "quest completion should grant every player 3 XP")
    assertEqual(scout.xp, 7, "quest completion should grant all active guild members 3 XP")
    assertEqual(delver.completedQuest, "Recover the star-child's bell",
        "quest completion should mark the quest completed on participants")
    assertEqual(delver.questCompleted, true, "quest completion should set the participant completion flag")
    assertEqual(roster.lastCompletedQuest, "Recover the star-child's bell",
        "quest completion should record the last completed guild quest")
    assertTrue(roster.currentQuest == nil, "quest completion should clear the current quest for the next declaration")
    assertEqual(#questCompletions, 1, "quest completion should persist a completion record")
    assertTrue(completedEvent and completedEvent.result == "guild_quest_completed",
        "quest completion should emit quest details")
    assertEqual(detail.xpAwarded, 3, "quest completion should report the rulebook XP award")

    local noAgreement = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { delver },
        guildRoster = {},
    })
    ok, result = noAgreement:resolveDeclareGuildQuest({
        quest = "Nobody agreed to this",
    })
    assertTrue(not ok, "declaring a quest should require guild agreement")
    assertEqual(result, "Guild agreement required", "missing agreement should explain the declaration gate")

    local newcomer = base_entity.createEntity({
        id = "pc_city_newcomer",
        name = "City Newcomer",
        isPC = true,
    })
    newcomer.xp = 0
    newcomer.inventory = inventory.createInventory()
    local joinRoster = {
        currentQuest = "Map the white labyrinth",
        adventurers = {},
        rumorMill = {
            {
                id = "hidden_switches",
                text = "The west mural hides the switch for the golden door.",
                secret = true,
            },
            {
                id = "mother_maggot_bane",
                text = "Mother Maggot recoils from bell-metal filings.",
            },
            {
                id = "withheld_rival_cache",
                text = "The guild hid a rival's cache under the stairs.",
                keptSecret = true,
            },
        },
        commonKnowledge = {
            invisible_bridge = "The invisible bridge is safe if crossed single-file.",
        },
    }
    local guildJoins = {}
    local joinEvent = nil
    local joinBus = events.createEventBus()
    joinBus:on(events.EVENTS.CITY_GUILD_JOINED, function(data)
        joinEvent = data
    end)
    local joinController = city_phase.createCityPhaseController({
        eventBus = joinBus,
        guild = {},
        guildRoster = joinRoster,
        guildJoins = guildJoins,
    })
    ok, result = joinController:resolveNewAdventurerJoinGuild({
        adventurer = newcomer,
        role = "scout",
        marchingOrder = 2,
    })
    assertTrue(not ok, "new adventurers should complete all-guild Bonds before joining at second-session end")
    assertEqual(result, "Complete guild Bonds required",
        "new adventurer join should explain the all-guild Bond prerequisite")
    assertEqual(newcomer.xp or 0, 0, "failed second-session join should not grant quest XP")
    assertTrue(not hasValue(joinController.guild, newcomer),
        "failed second-session join should not add the adventurer to the active guild")

    newcomer.newAdventurerBondComplete = true
    ok, result = joinController:resolveNewAdventurerJoinGuild({
        adventurer = newcomer,
        marchingOrder = 2,
    })
    assertTrue(not ok, "new adventurer guild joins should require the stated guild role")
    assertEqual(result, "Guild role required", "missing guild role should explain the roster prerequisite")
    assertEqual(newcomer.xp or 0, 0, "failed role-less join should not grant quest XP")
    assertTrue(not hasValue(joinController.guild, newcomer),
        "failed role-less join should not add the adventurer to the active guild")

    ok, result = joinController:resolveNewAdventurerJoinGuild({
        adventurer = newcomer,
        role = "scout",
    })
    assertTrue(not ok, "new adventurer guild joins should require the stated marching order")
    assertEqual(result, "Marching order required",
        "missing marching order should explain the roster prerequisite")
    assertEqual(newcomer.xp or 0, 0, "failed marching-order-less join should not grant quest XP")
    assertTrue(not hasValue(joinController.guild, newcomer),
        "failed marching-order-less join should not add the adventurer to the active guild")

    ok, result, detail = joinController:resolveNewAdventurerJoinGuild({
        adventurer = newcomer,
        role = "scout",
        marchingOrder = 2,
    })
    assertTrue(ok, "bond-complete new adventurers should be able to sign onto the current guild quest")
    assertEqual(result, "new_adventurer_joined_guild", "new adventurer join should report completion")
    assertEqual(newcomer.xp, 3, "joining the current guild quest should grant the new adventurer 3 XP")
    assertEqual(newcomer.guildQuest, "Map the white labyrinth",
        "joining the guild should attach the current quest to the new adventurer")
    assertEqual(newcomer.guildRole, "scout", "joining the guild should record the stated role")
    assertEqual(newcomer.marchingOrder, 2, "joining the guild should record marching order")
    assertTrue(hasValue(joinController.guild, newcomer), "joining the guild should add the adventurer to the active guild")
    assertTrue(hasValue(joinRoster.adventurers, newcomer), "joining the guild should sign the roster")
    assertEqual(#guildJoins, 1, "joining the guild should persist a join record")
    assertEqual(detail.xpAwarded, 3, "joining the guild should report the rulebook XP award")
    assertEqual(detail.rumorMillDiscoveryCount, 3,
        "joining later should inherit public discoveries from the rumor mill")
    assertEqual(newcomer.rumorMillDiscoveries[1].id, "hidden_switches",
        "rumor mill should pass along discovered secret switches by default")
    assertEqual(newcomer.rumorMillDiscoveries[1].secret, true,
        "secret discovery records should remain marked as secret lore")
    assertEqual(newcomer.rumorMillDiscoveries[3].id, "invisible_bridge",
        "rumor mill should include common-knowledge map discoveries")
    local foundWithheld = false
    for _, discovery in ipairs(newcomer.rumorMillDiscoveries) do
        if discovery.id == "withheld_rival_cache" then
            foundWithheld = true
        end
    end
    assertTrue(not foundWithheld, "rumor mill should omit discoveries the guild deliberately keeps secret")
    assertTrue(joinEvent and joinEvent.adventurer == newcomer, "joining the guild should emit join details")

    local noQuestController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = {},
        guildRoster = {},
    })
    local latecomer = base_entity.createEntity({
        id = "pc_city_latecomer",
        name = "City Latecomer",
        isPC = true,
    })
    latecomer.inventory = inventory.createInventory()
    ok, result = noQuestController:resolveNewAdventurerJoinGuild({
        adventurer = latecomer,
    })
    assertTrue(not ok, "new adventurer quest XP should require a current guild quest")
    assertEqual(result, "Current quest required", "joining without a current quest should explain the prerequisite")
    assertEqual(latecomer.xp or 0, 0, "failed current-quest join should not grant XP")
end

function checkRulebookQuestShapeAndPrep()
    local quest_rules = require('logic.quest_rules')
    local ok, result, detail = quest_rules.reviewQuest({
        quest = "Find the Grail of Mythrys",
    })
    assertTrue(ok, "specific object quests should pass the rulebook quest shape")
    assertEqual(result, quest_rules.RESULTS.ACCEPTED, "accepted quests should report the accepted result")
    assertTrue(not detail.needsRevision, "accepted quests should not require revision")

    ok, result, detail = quest_rules.reviewQuest({
        quest = "Get rich",
    })
    assertTrue(not ok, "broad wealth goals should fail the rulebook quest shape")
    assertEqual(result, quest_rules.RESULTS.NEEDS_REVISION,
        "broad quests should report that revision is needed")
    assertTrue(hasValue(detail.issues, "quest_too_broad"),
        "broad quests should identify the too-broad issue")

    ok, result, detail = quest_rules.reviewQuest({
        quest = "Find another reason to descend",
        afterCompletion = true,
        relatedToPreviousAdventure = false,
    })
    assertTrue(not ok, "new quests after completion should be related to prior adventures")
    assertTrue(hasValue(detail.issues, "new_quest_not_contextual"),
        "replacement quest review should flag unrelated new quests")

    ok, result, detail = quest_rules.prepareQuest({
        quest = "Capture a cockatrice alive",
        objectivePlacement = {
            location = "The basilisk aviary",
        },
        hints = {
            "Shed feathers turn stone-dust grey.",
        },
        rumors = {
            {
                text = "A mirror seller claims the bird cannot see polished silver.",
                correct = false,
            },
        },
        associatedCharacters = {
            "Order of Alchemists factor",
        },
        challenges = {
            "The quarry must be transported without being killed.",
        },
        pathsToVictory = {
            "Use a covered cage and a route through the service lifts.",
        },
    })
    assertTrue(ok, "quest prep helper should record GM prep")
    assertEqual(result, quest_rules.RESULTS.PREP_RECORDED, "quest prep should report recording")
    assertTrue(detail.readyForPlay, "placed quests with hints and open-ended challenges should be ready")
    assertTrue(detail.hasFalseRumors, "quest prep should preserve that rumors may be false")

    local campaign = {
        currentQuest = "Recover the moon-bell",
    }
    ok, result, detail = quest_rules.recordQuestRumor(campaign, {
        rumor = "The bell rings whenever the drowned chapel floods.",
    })
    assertTrue(ok, "quest rumor helper should record a rumor for the current quest")
    assertEqual(result, quest_rules.RESULTS.RUMOR_RECORDED, "quest rumors should report recording")
    assertTrue(detail.leadsOneStepCloser, "quest rumors should lead one step closer by default")
    assertTrue(detail.mayBeFalse, "quest rumors should preserve the rulebook uncertainty")
    assertEqual(#campaign.questRumors, 1, "quest rumors should be appended to campaign state")

    local controller = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = {},
        guildRoster = {},
    })
    ok, result = controller:resolveDeclareGuildQuest({
        quest = "Get rich",
        guildAgrees = true,
    })
    assertTrue(not ok, "City quest declaration should reject broad quests")
    assertEqual(result, "Quest should be discrete and achievable",
        "broad quest declarations should explain the rulebook shape")

    local delver = base_entity.createEntity({
        id = "pc_quest_shape_delver",
        name = "Quest Shape Delver",
        isPC = true,
    })
    delver.xp = 0
    local roster = {}
    controller = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { delver },
        guildRoster = roster,
    })
    ok, result, detail = controller:resolveDeclareGuildQuest({
        quest = "Recover the oath-stone",
        guildAgrees = true,
        objectivePlacement = {
            roomId = "forgotten_chapel",
        },
        hints = {
            "The chapel floor has a fresh drag mark.",
        },
        rumors = {
            "A rival guild was seen carrying stone-prayer tools.",
        },
        challenges = {
            "The stone is built into a load-bearing altar.",
        },
        pathsToVictory = {
            "Brace the arch before prying it loose.",
        },
    })
    assertTrue(ok, "valid quest declarations should still resolve through City Phase")
    assertEqual(result, "guild_quest_declared", "valid quest declarations should report normal completion")
    assertTrue(detail.declaration.questReview.valid, "City quest declarations should store quest review")
    assertTrue(detail.declaration.questPrep.readyForPlay,
        "City quest declarations should store GM quest prep when provided")
    assertEqual(roster.currentQuestPrep.objectivePlacement.roomId, "forgotten_chapel",
        "quest prep should be retained on the guild roster")
    assertEqual(delver.xp, 3, "quest validation should preserve the normal declaration XP award")
end

function checkNewAdventurerChecklistBonds()
    local newcomer = base_entity.createEntity({
        id = "pc_new_bond_newcomer",
        name = "New Bond Newcomer",
        isPC = true,
    })
    local scout = base_entity.createEntity({
        id = "pc_new_bond_scout",
        name = "New Bond Scout",
        isPC = true,
    })
    local guard = base_entity.createEntity({
        id = "pc_new_bond_guard",
        name = "New Bond Guard",
        isPC = true,
    })
    local cook = base_entity.createEntity({
        id = "pc_new_bond_cook",
        name = "New Bond Cook",
        isPC = true,
    })
    local bondRecords = {}
    local replacementRecords = {}
    local roster = {}
    local emitted = nil
    local replacementEmitted = nil
    local bus = events.createEventBus()
    bus:on(events.EVENTS.CITY_NEW_ADVENTURER_BONDS_SELECTED, function(data)
        emitted = data
    end)
    bus:on(events.EVENTS.CITY_GUILD_JOIN_DECLINED, function(data)
        replacementEmitted = data
    end)
    local controller = city_phase.createCityPhaseController({
        eventBus = bus,
        guild = { scout, guard, cook },
        guildRoster = roster,
        newAdventurerBondRecords = bondRecords,
        newAdventurerReplacementRecords = replacementRecords,
    })

    local ok, result, detail = controller:resolveNewAdventurerBonds(newcomer, {
        targets = {
            { target = scout, status = "friendship" },
            { target = guard, status = "rivalry" },
        },
    })
    assertTrue(ok, "new adventurers should choose two first-session Bond targets")
    assertEqual(result, "new_adventurer_bonds_selected", "new adventurer Bonds should report completion")
    assertEqual(detail.stage, "first_session", "two-Bond onboarding should be recorded as first-session setup")
    assertEqual(newcomer.bonds.pc_new_bond_scout.status, "friendship",
        "new adventurer first-session Bond should preserve selected status")
    assertEqual(newcomer.bonds.pc_new_bond_scout.bondType, "ally",
        "new adventurer first-session Bond should map legacy friendship to Ally")
    assertEqual(newcomer.bonds.pc_new_bond_guard.status, "rivalry",
        "new adventurer first-session Bond should preserve the second selected status")
    assertEqual(newcomer.bonds.pc_new_bond_guard.bondType, "rival",
        "new adventurer first-session Bond should map legacy rivalry to Rival")
    assertTrue(detail.bonds[1].chargeTrigger ~= nil,
        "new adventurer Bond records should include rulebook charge prompts")
    assertTrue(newcomer.bonds.pc_new_bond_cook == nil,
        "first-session new adventurer Bonds should not silently fill the whole guild")
    assertEqual(#bondRecords, 1, "new adventurer Bonds should persist controller records")
    assertEqual(#roster.newAdventurerBonds, 1, "new adventurer Bonds should persist roster records")
    assertTrue(emitted and emitted.result == "new_adventurer_bonds_selected",
        "new adventurer Bonds should emit onboarding details")

    local tooFew = base_entity.createEntity({
        id = "pc_new_bond_too_few",
        name = "New Bond Too Few",
        isPC = true,
    })
    ok, result = controller:resolveNewAdventurerBonds(tooFew, {
        targets = { scout },
    })
    assertTrue(not ok, "first-session new adventurer Bonds should require two targets")
    assertEqual(result, "Choose two Bond targets", "too few first-session Bonds should explain the rule")

    local tooMany = base_entity.createEntity({
        id = "pc_new_bond_too_many",
        name = "New Bond Too Many",
        isPC = true,
    })
    ok, result = controller:resolveNewAdventurerBonds(tooMany, {
        targets = { scout, guard, cook },
    })
    assertTrue(not ok, "first-session new adventurer Bonds should reject extra targets by default")
    assertEqual(result, "Choose exactly two Bond targets",
        "too many first-session Bonds should explain the exact count")

    local secondSession = base_entity.createEntity({
        id = "pc_new_bond_second_session",
        name = "New Bond Second Session",
        isPC = true,
    })
    ok, result, detail = controller:resolveNewAdventurerBonds(secondSession, {
        completeGuildBonds = true,
        defaultStatus = "friendship",
    })
    assertTrue(ok, "second-session new adventurer Bonds should fill every active guild member")
    assertEqual(detail.stage, "second_session", "complete-guild Bonds should be recorded as second-session setup")
    assertEqual(secondSession.bonds.pc_new_bond_scout.status, "friendship",
        "second-session Bonds should include the first guild member")
    assertEqual(secondSession.bonds.pc_new_bond_guard.status, "friendship",
        "second-session Bonds should include the second guild member")
    assertEqual(secondSession.bonds.pc_new_bond_cook.status, "friendship",
        "second-session Bonds should include every active guild member")
    assertTrue(secondSession.newAdventurerBondComplete,
        "second-session Bonds should mark the new adventurer's guild Bonds complete")

    local incompleteSecond = base_entity.createEntity({
        id = "pc_new_bond_incomplete_second",
        name = "New Bond Incomplete Second",
        isPC = true,
    })
    ok, result = controller:resolveNewAdventurerBonds(incompleteSecond, {
        completeGuildBonds = true,
        targets = { scout, guard },
    })
    assertTrue(not ok, "second-session new adventurer Bonds should require every guild member")
    assertEqual(result, "Bond with every guild member required",
        "incomplete second-session Bonds should explain the all-guild requirement")

    local unknownBond = base_entity.createEntity({
        id = "pc_new_bond_unknown",
        name = "New Bond Unknown",
        isPC = true,
    })
    ok, result = controller:resolveNewAdventurerBonds(unknownBond, {
        strictBondTypes = true,
        targets = {
            { target = scout, status = "mysterious affinity" },
            { target = guard, status = "friendship" },
        },
    })
    assertTrue(not ok, "strict new adventurer Bonds should reject unknown Bond types")
    assertEqual(result, "Unknown Bond type", "unknown strict onboarding Bond types should explain the rule")

    controller.guild[#controller.guild + 1] = secondSession
    roster.adventurers = { secondSession, scout, guard, cook }
    ok, result, detail = controller:resolveNewAdventurerDeclineGuild({
        adventurer = secondSession,
        reason = "The character did not mesh with the guild",
        replacementName = "New Better Fit",
    })
    assertTrue(ok, "second-session new adventurer should be able to elect a replacement")
    assertEqual(result, "new_adventurer_replacement_elected",
        "declining the guild should report the replacement branch")
    assertTrue(secondSession.newAdventurerDeclinedGuild,
        "declining the guild should mark the trial adventurer")
    assertTrue(not hasValue(controller.guild, secondSession),
        "declining the guild should remove trial adventurers from the active guild")
    assertTrue(not hasValue(roster.adventurers, secondSession),
        "declining the guild should remove trial adventurers from roster adventurers")
    assertEqual(#replacementRecords, 1, "declining the guild should persist controller records")
    assertEqual(#roster.newAdventurerReplacements, 1,
        "declining the guild should persist roster replacement records")
    assertTrue(replacementEmitted and replacementEmitted.result == "new_adventurer_replacement_elected",
        "declining the guild should emit onboarding replacement details")

    local undecided = base_entity.createEntity({
        id = "pc_new_bond_undecided",
        name = "New Bond Undecided",
        isPC = true,
    })
    ok, result = controller:resolveNewAdventurerDeclineGuild({
        adventurer = undecided,
    })
    assertTrue(not ok, "replacement election should require completed guild Bonds by default")
    assertEqual(result, "Complete guild Bonds required",
        "replacement election should explain the second-session Bond prerequisite")
end

function checkRulebookBondChargeTriggers()
    local bond_rules = require('logic.bond_rules')
    local sequence = 0
    local records = {}
    local emitted = nil
    local bus = events.createEventBus()
    bus:on(bond_rules.RESULTS.CHARGED, function(data)
        emitted = data
    end)

    local function pair(status)
        sequence = sequence + 1
        local actor = entity_factory.createAdventurer({
            id = "pc_bond_actor_" .. tostring(sequence),
            name = "Bond Actor " .. tostring(sequence),
        })
        local target = entity_factory.createAdventurer({
            id = "pc_bond_target_" .. tostring(sequence),
            name = "Bond Target " .. tostring(sequence),
        })
        actor:setBond(target.id, status)
        target:setBond(actor.id, status)
        return actor, target
    end

    local function assertCharges(status, trigger, opts, reciprocal, label)
        local actor, target = pair(status)
        opts = opts or {}
        opts.actor = actor
        opts.target = target
        opts.records = records
        opts.eventBus = bus
        local ok, result, detail = bond_rules.resolveCharge(opts)
        assertTrue(ok, label .. " should charge the Bond")
        assertEqual(result, bond_rules.RESULTS.CHARGED, label .. " should report a charged Bond")
        assertTrue(actor:isBondCharged(target.id), label .. " should charge the acting adventurer")
        assertEqual(detail.bondType, actor:getBond(target.id).bondType,
            label .. " should report canonical Bond metadata")
        assertTrue(actor.bondChargeLog and actor.bondChargeLog[1].trigger == trigger,
            label .. " should record an actor charge log")
        if reciprocal then
            assertTrue(target:isBondCharged(actor.id), label .. " should charge the reciprocal Bond")
            assertTrue(detail.reciprocalCharged, label .. " should report reciprocal charging")
        end
    end

    assertCharges("friendship", bond_rules.TRIGGERS.PLAY_TO_HILT, {
        trigger = bond_rules.TRIGGERS.PLAY_TO_HILT,
    }, false, "playing a Bond to the hilt")
    assertCharges("friendship", bond_rules.TRIGGERS.DANGER, {
        trigger = bond_rules.TRIGGERS.DANGER,
    }, false, "putting a Bond in danger")
    assertCharges("friendship", bond_rules.TRIGGERS.ALLY_LAUGH, {
        trigger = bond_rules.TRIGGERS.ALLY_LAUGH,
        inCharacter = true,
        outOfCharacter = true,
    }, false, "Ally laughter")
    assertCharges("adversary", bond_rules.TRIGGERS.ADVERSARY_WITNESS_FAIL_TEST, {
        trigger = bond_rules.TRIGGERS.ADVERSARY_WITNESS_FAIL_TEST,
        consent = true,
        witnessed = true,
        testResult = "failure",
    }, false, "Adversary failed Test of Fate")
    assertCharges("big_little", bond_rules.TRIGGERS.BIG_LITTLE_AIDS_WEAK_ATTRIBUTE, {
        trigger = bond_rules.TRIGGERS.BIG_LITTLE_AIDS_WEAK_ATTRIBUTE,
        aided = true,
        testOfFate = true,
        weakestAttribute = true,
    }, true, "Big/Little weak-attribute aid")
    assertCharges("best_friend", bond_rules.TRIGGERS.BEST_FRIEND_REVEAL_SECRET, {
        trigger = bond_rules.TRIGGERS.BEST_FRIEND_REVEAL_SECRET,
        secretRevealed = true,
    }, true, "Best Friend secret reveal")
    assertCharges("love", bond_rules.TRIGGERS.LOVE_ROMANTIC_GESTURE, {
        trigger = bond_rules.TRIGGERS.LOVE_ROMANTIC_GESTURE,
        romanticGesture = true,
    }, false, "Love romantic gesture")
    assertCharges("master_henchman", bond_rules.TRIGGERS.MASTER_PAYMENT, {
        trigger = bond_rules.TRIGGERS.MASTER_PAYMENT,
        role = "master",
        compensated = true,
    }, false, "Master payment")
    assertCharges("master_henchman", bond_rules.TRIGGERS.HENCHMAN_CAMP_ACTION_BENEFITS_MASTER, {
        trigger = bond_rules.TRIGGERS.HENCHMAN_CAMP_ACTION_BENEFITS_MASTER,
        role = "henchman",
        campAction = true,
        benefitedMaster = true,
        benefitedSelf = false,
    }, false, "Henchman master-only Camp Action")
    assertCharges("mentor_mentee", bond_rules.TRIGGERS.MENTEE_ASKS_ADVICE, {
        trigger = bond_rules.TRIGGERS.MENTEE_ASKS_ADVICE,
        role = "mentee",
        askedAdvice = true,
        adviceGiven = true,
    }, false, "Mentee advice request")
    assertCharges("mentor_mentee", bond_rules.TRIGGERS.MENTOR_ADVICE_FOLLOWED, {
        trigger = bond_rules.TRIGGERS.MENTOR_ADVICE_FOLLOWED,
        role = "mentor",
        adviceFollowed = true,
    }, false, "Mentor advice followed")
    assertCharges("rivalry", bond_rules.TRIGGERS.RIVAL_WITNESS_SUCCESS_TEST, {
        trigger = bond_rules.TRIGGERS.RIVAL_WITNESS_SUCCESS_TEST,
        consent = true,
        witnessed = true,
        testResult = "success",
    }, false, "Rival successful Test of Fate")
    assertCharges("sibling", bond_rules.TRIGGERS.SIBLING_AIDS_TEST, {
        trigger = bond_rules.TRIGGERS.SIBLING_AIDS_TEST,
        aided = true,
        testOfFate = true,
    }, false, "Sibling Test of Fate aid")
    assertCharges("unrequited_love", bond_rules.TRIGGERS.UNREQUITED_KINDNESS_REBUFFED, {
        trigger = bond_rules.TRIGGERS.UNREQUITED_KINDNESS_REBUFFED,
        consent = true,
        kindAct = true,
        rebuffed = true,
    }, false, "Unrequited Love kindness rebuffed")
    assertCharges("guardianship", bond_rules.TRIGGERS.WARD_SURVIVES_CHALLENGE_UNWOUNDED, {
        trigger = bond_rules.TRIGGERS.WARD_SURVIVES_CHALLENGE_UNWOUNDED,
        challengeCompleted = true,
        woundsTaken = 0,
    }, false, "Ward survives a Challenge unwounded")

    assertTrue(#records >= 15, "Bond charge helper should append charge records")
    assertTrue(emitted and emitted.result == bond_rules.RESULTS.CHARGED,
        "Bond charge helper should emit charged-Bond details")

    local actor, target = pair("rivalry")
    local ok, result = bond_rules.resolveCharge({
        actor = actor,
        target = target,
        trigger = bond_rules.TRIGGERS.RIVAL_WITNESS_SUCCESS_TEST,
        requireConsent = true,
        witnessed = true,
        testSucceeded = true,
    })
    assertTrue(not ok, "negative Bonds should be blockable until table consent is recorded")
    assertEqual(result, bond_rules.RESULTS.CONSENT_REQUIRED,
        "negative Bond consent gate should explain the missing consent")
    assertTrue(not actor:isBondCharged(target.id), "missing consent should not charge a negative Bond")

    local unfunActor, unfunTarget = pair("unrequited")
    ok, result = bond_rules.resolveCharge({
        actor = unfunActor,
        target = unfunTarget,
        trigger = bond_rules.TRIGGERS.UNREQUITED_KINDNESS_REBUFFED,
        kindAct = true,
        rebuffed = true,
        fun = false,
    })
    assertTrue(ok, "unfun negative Bonds should resolve through the consent fallback")
    assertEqual(result, bond_rules.RESULTS.SWAPPED_TO_ALLY,
        "unfun negative Bonds should be swapped to Ally")
    assertEqual(unfunActor:getBond(unfunTarget.id).bondType, "ally",
        "negative Bond consent fallback should rewrite the canonical Bond type")
    assertTrue(not unfunActor:isBondCharged(unfunTarget.id),
        "swapping an unfun negative Bond should not also charge it")

    actor, target = pair("friendship")
    ok, result = bond_rules.resolveCharge({
        actor = actor,
        target = target,
        trigger = bond_rules.TRIGGERS.ALLY_LAUGH,
        inCharacter = true,
        outOfCharacter = false,
    })
    assertTrue(not ok, "partial Ally laugh trigger should not charge the Bond")
    assertEqual(result, bond_rules.RESULTS.NOT_QUALIFIED,
        "unmet Bond examples should report a non-qualifying trigger")
end

function checkNewAdventurerStartingGearChecklist()
    local rookie = base_entity.createEntity({
        id = "pc_starting_gear_rookie",
        name = "Starting Gear Rookie",
        isPC = true,
    })
    local startingGearSelections = {}
    local selectedEvent = nil
    local bus = events.createEventBus()
    bus:on(events.EVENTS.CITY_STARTING_GEAR_SELECTED, function(data)
        selectedEvent = data
    end)
    local controller = city_phase.createCityPhaseController({
        eventBus = bus,
        startingGearSelections = startingGearSelections,
    })

    local startingGearItems = {
        "iron_armor",
        "lockpicks",
        "mirror",
        "crowbar",
        "torch",
        "garlic",
        "rope",
        "ration",
        "chalk",
    }
    local gearOptions = controller:getNewAdventurerStartingGearOptions(rookie, {
        items = startingGearItems,
    })
    assertTrue(not gearOptions.disabled,
        "starting gear options should allow a valid Call to Adventure checklist")
    assertEqual(gearOptions.resultPreview, "starting_gear_selected",
        "starting gear options should preview successful selection")
    assertEqual(gearOptions.tierCounts.luxurious, 1,
        "starting gear options should count the selected luxurious item")
    assertEqual(gearOptions.counts.common, 5,
        "starting gear options should count the selected common items")
    assertEqual(gearOptions.tierCounts.impoverished, 3,
        "starting gear options should count the selected impoverished items")
    assertEqual(#gearOptions.selectedItems, #startingGearItems,
        "starting gear options should expose every selected item")
    assertTrue(gearOptions.capacityPreview.usesDefaultInventory,
        "starting gear options should preview default inventory without mutating the actor")
    assertTrue(rookie.inventory == nil,
        "starting gear options should not create the actor inventory")
    local armorOption = nil
    for _, option in ipairs(gearOptions.selectedItems) do
        if option.templateId == "iron_armor" then
            armorOption = option
        end
    end
    assertTrue(armorOption ~= nil, "starting gear options should include selected luxurious armor")
    assertEqual(armorOption.location, inventory.LOCATIONS.BELT,
        "starting gear options should route armor previews to belt slots")

    local ok, result, detail = controller:resolveNewAdventurerStartingGear(rookie, {
        items = startingGearItems,
    })
    assertTrue(ok, "new adventurers should be able to select the starting gear checklist")
    assertEqual(result, "starting_gear_selected", "starting gear should report completion")
    assertEqual(detail.tierCounts.luxurious, 1, "starting gear should allow exactly one luxurious item")
    assertEqual(detail.counts.common, 5, "starting gear should allow five common items")
    assertEqual(detail.tierCounts.impoverished, 3, "starting gear should allow unlimited impoverished items")
    assertTrue(rookie.startingGearSelected, "starting gear should mark the adventurer as equipped")
    assertEqual(#startingGearSelections, 1, "starting gear should persist a controller selection record")
    assertEqual(#rookie.startingGearSelections, 1, "starting gear should persist an actor selection record")
    assertTrue(selectedEvent and selectedEvent.result == "starting_gear_selected",
        "starting gear should emit selection details")

    local armorPlan = nil
    for _, plan in ipairs(detail.items) do
        if plan.templateId == "iron_armor" then
            armorPlan = plan
        end
    end
    assertTrue(armorPlan ~= nil, "starting gear should include selected luxurious armor")
    assertEqual(select(2, rookie.inventory:findItem(armorPlan.item.id)), inventory.LOCATIONS.BELT,
        "starting armor should be placed in belt slots instead of the pack")

    local talentRookie = base_entity.createEntity({
        id = "pc_starting_gear_alchemist",
        name = "Starting Gear Alchemist",
        isPC = true,
    })
    local talentGearItems = {
        { templateId = "alchemy_kit", requiredForTalent = true },
        "lantern",
        "lockpicks",
        "mirror",
        "crowbar",
        "torch",
        "garlic",
    }
    local talentGearOptions = controller:getNewAdventurerStartingGearOptions(talentRookie, {
        items = talentGearItems,
    })
    assertTrue(not talentGearOptions.disabled,
        "starting gear options should allow talent-required checklist gear")
    assertEqual(talentGearOptions.tierCounts.luxurious, 1,
        "starting gear options should leave the luxurious slot available for non-talent gear")
    assertEqual(talentGearOptions.tierCounts.common, 5,
        "starting gear options should preserve common item counts with talent gear")
    assertEqual(talentGearOptions.tierCounts.impoverished, 1,
        "starting gear options should count talent-required market gear as impoverished")
    local alchemyOption = nil
    for _, option in ipairs(talentGearOptions.selectedItems) do
        if option.templateId == "alchemy_kit" then
            alchemyOption = option
        end
    end
    assertTrue(alchemyOption and alchemyOption.talentRequired,
        "starting gear options should tag talent-required market gear")
    assertEqual(alchemyOption.tierReason, "talent_required_gear",
        "starting gear options should explain the talent-required tier downgrade")
    assertTrue(talentRookie.inventory == nil,
        "talent gear options should not create the actor inventory")
    ok, result, detail = controller:resolveNewAdventurerStartingGear(talentRookie, {
        items = talentGearItems,
    })
    assertTrue(ok, "talent-required starting gear should count as impoverished")
    assertEqual(detail.tierCounts.luxurious, 1,
        "talent-required luxurious gear should not consume the one luxurious item slot")
    assertEqual(detail.tierCounts.common, 5, "talent-required gear should preserve the five common item slots")
    assertEqual(detail.tierCounts.impoverished, 1,
        "talent-required luxurious gear should be counted as impoverished")
    local alchemyPlan = nil
    for _, plan in ipairs(detail.items) do
        if plan.templateId == "alchemy_kit" then
            alchemyPlan = plan
        end
    end
    assertTrue(alchemyPlan and alchemyPlan.talentRequired,
        "starting gear should tag market items made impoverished by talent need")

    local overCommon = base_entity.createEntity({
        id = "pc_starting_gear_over_common",
        name = "Starting Gear Over Common",
        isPC = true,
    })
    local overCommonItems = {
        "lantern",
        "lockpicks",
        "mirror",
        "crowbar",
        "torch",
        "garlic",
        "chain_10ft",
    }
    local overCommonOptions = controller:getNewAdventurerStartingGearOptions(overCommon, {
        items = overCommonItems,
    })
    assertTrue(overCommonOptions.disabled,
        "starting gear options should reject more than five common items")
    assertEqual(overCommonOptions.unavailableReason, "Starting gear allows five common items",
        "starting gear options should explain the common item limit")
    assertTrue(overCommon.inventory == nil,
        "failed starting gear options should not create an actor inventory")
    ok, result = controller:resolveNewAdventurerStartingGear(overCommon, {
        items = overCommonItems,
    })
    assertTrue(not ok, "starting gear should reject more than five common items")
    assertEqual(result, "Starting gear allows five common items",
        "too many common starting items should explain the checklist limit")
    assertTrue(not overCommon.startingGearSelected, "failed starting gear should not mark the adventurer equipped")
    assertEqual(#overCommon.inventory.pack, 0, "failed starting gear should not add partial pack items")

    local missingLuxurious = base_entity.createEntity({
        id = "pc_starting_gear_missing_luxury",
        name = "Starting Gear Missing Luxury",
        isPC = true,
    })
    local missingLuxuriousItems = {
        "lockpicks",
        "mirror",
        "crowbar",
        "torch",
        "garlic",
    }
    local missingLuxuriousOptions = controller:getNewAdventurerStartingGearOptions(missingLuxurious, {
        items = missingLuxuriousItems,
    })
    assertTrue(missingLuxuriousOptions.disabled,
        "starting gear options should require one luxurious item")
    assertEqual(missingLuxuriousOptions.unavailableReason, "Starting gear requires one luxurious item",
        "starting gear options should explain a missing luxurious item")
    ok, result = controller:resolveNewAdventurerStartingGear(missingLuxurious, {
        items = missingLuxuriousItems,
    })
    assertTrue(not ok, "complete starting gear should require one luxurious item")
    assertEqual(result, "Starting gear requires one luxurious item",
        "missing luxurious starting item should explain the checklist requirement")

    local cramped = base_entity.createEntity({
        id = "pc_starting_gear_cramped",
        name = "Starting Gear Cramped",
        isPC = true,
    })
    cramped.inventory = inventory.createInventory({ packSlots = 1 })
    local crampedItems = {
        "lantern",
        "lockpicks",
        "mirror",
        "crowbar",
        "torch",
        "garlic",
    }
    local crampedOptions = controller:getNewAdventurerStartingGearOptions(cramped, {
        items = crampedItems,
    })
    assertTrue(crampedOptions.disabled,
        "starting gear options should preflight carried inventory capacity")
    assertEqual(crampedOptions.unavailableReason, "insufficient_slots",
        "starting gear options should report insufficient inventory slots")
    assertTrue(not crampedOptions.capacityPreview.fits,
        "starting gear options should mark the capacity preview as not fitting")
    ok, result = controller:resolveNewAdventurerStartingGear(cramped, {
        items = crampedItems,
    })
    assertTrue(not ok, "starting gear should preflight carried inventory capacity")
    assertEqual(result, "insufficient_slots", "failed starting gear should report insufficient inventory slots")
    assertTrue(not cramped.startingGearSelected, "failed capacity preflight should not mark starting gear selected")
end

local function checkCityPhaseRestockUnderworld()
    local cityEventsTable = {
        [12] = { value = 12, title = "Old Star-Daughter Rumor" },
    }
    local signsTable = {
        [8] = { value = 8, title = "Old Mushroom Forest" },
    }
    local meatgrinderTable = {
        [16] = { value = 16, description = "Old ogre encounter" },
    }
    local resetCalled = false
    local fakeMeatgrinder = {
        consumed = { "global:random_encounter", "111_spiders_treasure:quest_rumor" },
        getConsumedEvents = function(self)
            return self.consumed
        end,
        resetConsumed = function(self)
            resetCalled = true
            self.consumed = {}
        end,
    }
    local roster = {}
    local underworldState = {}
    local bus = events.createEventBus()
    local emitted = nil
    bus:on(events.EVENTS.CITY_UNDERWORLD_RESTOCKED, function(data)
        emitted = data
    end)

    local controller = city_phase.createCityPhaseController({
        eventBus = bus,
        guildRoster = roster,
        cityEventsTable = cityEventsTable,
        signsAndPortentsTable = signsTable,
        meatgrinder = fakeMeatgrinder,
        meatgrinderTable = meatgrinderTable,
        underworldState = underworldState,
    })

    local restockOptions = controller:getRestockUnderworldOptions({
        cityEventReplacements = {
            [12] = { value = 12, title = "New Star-Daughter Consequence" },
        },
        signsAndPortentsReplacements = {
            { value = 8, title = "New Mushroom District Trouble" },
        },
        meatgrinderReplacements = {
            [16] = { value = 16, description = "A rival guild loots the old ogre post" },
        },
        mapUpdates = {
            { roomId = "111_spiders_treasure", state = "looted" },
        },
        factionUpdates = {
            { faction = "tomb_spiders", response = "retreat deeper", status = "withdrawn", strengthDelta = -1 },
        },
        notes = "Replace used random-table entries based on guild consequences.",
    })
    assertEqual(restockOptions.consumedMeatgrinder[1], "global:random_encounter",
        "Restock options should expose consumed Meatgrinder entries")
    assertEqual(restockOptions.cityEventReplacementOptions[1].oldEntry.title, "Old Star-Daughter Rumor",
        "Restock options should preview City Event replacement targets without mutating them")
    assertEqual(restockOptions.signsAndPortentsReplacementOptions[1].key, 8,
        "Restock options should preview Signs and Portents replacement slots")
    assertEqual(restockOptions.meatgrinderReplacementOptions[1].oldEntry.description, "Old ogre encounter",
        "Restock options should preview Meatgrinder replacement targets")
    assertEqual(restockOptions.mapUpdateOptions[1].roomId, "111_spiders_treasure",
        "Restock options should expose map update records")
    assertEqual(restockOptions.factionUpdateOptions[1].factionId, "tomb_spiders",
        "Restock options should normalize faction update ids")
    assertEqual(restockOptions.factionUpdateOptions[1].projectedStrength, -1,
        "Restock options should preview faction strength deltas")
    assertEqual(cityEventsTable[12].title, "Old Star-Daughter Rumor",
        "Restock options should not apply City Event replacements during preview")

    local ok, result, detail = controller:resolveRestockUnderworld({
        cityEventReplacements = {
            [12] = { value = 12, title = "New Star-Daughter Consequence" },
        },
        signsAndPortentsReplacements = {
            { value = 8, title = "New Mushroom District Trouble" },
        },
        meatgrinderReplacements = {
            [16] = { value = 16, description = "A rival guild loots the old ogre post" },
        },
        mapUpdates = {
            { roomId = "111_spiders_treasure", state = "looted" },
        },
        factionUpdates = {
            { faction = "tomb_spiders", response = "retreat deeper", status = "withdrawn", strengthDelta = -1 },
        },
        notes = "Replace used random-table entries based on guild consequences.",
    })
    assertTrue(ok, "Restock the Underworld should resolve as a City Phase step")
    assertEqual(result, "underworld_restocked", "Restock the Underworld should report completion")
    assertEqual(detail.consumedMeatgrinder[1], "global:random_encounter", "Restock should report consumed Meatgrinder entries")
    assertTrue(resetCalled, "Restock should clear consumed Meatgrinder markers after replacement")
    assertEqual(#fakeMeatgrinder.consumed, 0, "Restock should reset Meatgrinder consumed state")
    assertEqual(cityEventsTable[12].title, "New Star-Daughter Consequence", "Restock should replace used City Event entries")
    assertEqual(signsTable[8].title, "New Mushroom District Trouble", "Restock should replace used Signs and Portents entries when provided")
    assertEqual(meatgrinderTable[16].description, "A rival guild loots the old ogre post", "Restock should replace used Meatgrinder entries")
    assertEqual(#detail.cityEventReplacements, 1, "Restock should report City Event replacements")
    assertEqual(#detail.meatgrinderReplacements, 1, "Restock should report Meatgrinder replacements")
    assertEqual(roster.mapsReviewed, true, "Restock should record that maps were reviewed")
    assertEqual(roster.restockNotes[1].mapUpdates[1].roomId, "111_spiders_treasure", "Restock should record map updates")
    assertEqual(roster.restockNotes[1].factionUpdates[1].faction, "tomb_spiders", "Restock should record faction updates")
    assertEqual(underworldState.rooms["111_spiders_treasure"].state, "looted",
        "Restock should persist room state updates for the next Crawl")
    assertEqual(underworldState.factions.tomb_spiders.status, "withdrawn",
        "Restock should persist faction response state")
    assertEqual(underworldState.factions.tomb_spiders.strength, -1,
        "Restock should apply faction strength deltas")
    assertEqual(detail.stateUpdates.factionStateUpdates[1].factionId, "tomb_spiders",
        "Restock detail should report applied faction state updates")
    assertTrue(emitted and emitted.result == "underworld_restocked", "Restock should emit step details")

    ok, result = controller:resolveRestockUnderworld()
    assertTrue(not ok, "Restock the Underworld should resolve only once per City Phase controller")
    assertEqual(result, "Underworld already restocked", "repeat Restock should explain existing resolution")
    restockOptions = controller:getRestockUnderworldOptions()
    assertTrue(restockOptions.disabled, "Restock options should disable already-restocked controllers")
    assertEqual(restockOptions.unavailableReason, "Underworld already restocked",
        "Restock options should explain repeat Restock attempts")

    local consumedCityEventsTable = {
        [21] = { value = 21, title = "Old Strange Days" },
    }
    local consumedSignsTable = {
        [8] = { value = 8, title = "Old Mushroom Forest" },
    }
    local consumedController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        cityEventsTable = consumedCityEventsTable,
        signsAndPortentsTable = consumedSignsTable,
        guildRoster = {},
    })
    ok, result = consumedController:resolveCityEvent({
        majorCard = {
            name = "The World",
            value = 21,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
        minorDiscardCard = {
            name = "Eight of Cups",
            value = 8,
            suit = constants.SUITS.CUPS,
        },
    })
    assertTrue(ok, "City Events should mark consumed entries before Restock")
    assertEqual(consumedController.consumedCityEvents[1].value, 21,
        "resolved City Event should remember its consumed table value")
    assertEqual(consumedController.consumedSignsAndPortents[1].value, 8,
        "resolved Signs and Portents should remember its consumed table value")
    restockOptions = consumedController:getRestockUnderworldOptions({
        cityEventReplacements = {
            { entry = { value = 21, title = "Restocked Strange Days" } },
        },
        signsAndPortentsReplacements = {
            { entry = { value = 8, title = "Restocked Mushroom Forest" } },
        },
    })
    assertEqual(restockOptions.cityEventReplacementOptions[1].key, 21,
        "Restock options should use consumed City Event markers for unkeyed replacements")
    assertEqual(restockOptions.signsAndPortentsReplacementOptions[1].key, 8,
        "Restock options should use consumed Signs markers for unkeyed replacements")
    ok, result, detail = consumedController:resolveRestockUnderworld({
        cityEventReplacements = {
            { entry = { value = 21, title = "Restocked Strange Days" } },
        },
        signsAndPortentsReplacements = {
            { entry = { value = 8, title = "Restocked Mushroom Forest" } },
        },
    })
    assertTrue(ok, "Restock should use consumed City Event markers for unkeyed replacements")
    assertEqual(consumedCityEventsTable[21].title, "Restocked Strange Days",
        "Restock should replace the consumed City Event slot without an explicit key")
    assertEqual(consumedSignsTable[8].title, "Restocked Mushroom Forest",
        "Restock should replace the consumed Signs and Portents slot without an explicit key")
    assertEqual(detail.consumedCityEvents[1].value, 21, "Restock should report consumed City Event entries")
    assertEqual(detail.consumedSignsAndPortents[1].value, 8,
        "Restock should report consumed Signs and Portents entries")
    assertEqual(#consumedController.consumedCityEvents, 0, "Restock should clear consumed City Event markers")
    assertEqual(#consumedController.consumedSignsAndPortents, 0,
        "Restock should clear consumed Signs and Portents markers")

    local nestedMeatgrinderTable = {
        random_encounter = {
            [1] = { value = 16, description = "Old puppet-mummy consequence" },
        },
        quest_rumor = {
            value = 21,
            description = "Old quest rumor",
        },
    }
    local autoCityEventsTable = {
        [12] = { value = 12, category = "rumor", title = "Old Star-Daughter Rumor" },
    }
    local autoResetCalled = false
    local autoMeatgrinder = {
        consumed = {
            "105_hall_of_solemnity:random_encounter:16",
            "111_spiders_treasure:quest_rumor:21",
        },
        getConsumedEvents = function(self)
            return self.consumed
        end,
        resetConsumed = function(self)
            autoResetCalled = true
            self.consumed = {}
        end,
    }
    local autoController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        meatgrinder = autoMeatgrinder,
        meatgrinderTable = nestedMeatgrinderTable,
        cityEventsTable = autoCityEventsTable,
    })
    autoController.lastCityEvent = {
        card = { value = 12 },
        event = autoCityEventsTable[12],
        category = "rumor",
    }

    restockOptions = autoController:getRestockUnderworldOptions({
        autoGenerateReplacements = true,
        mapUpdates = {
            { roomId = "105_hall_of_solemnity", state = "webs destroyed" },
        },
        factionUpdates = {
            { faction = "golden_ghosts", response = "wrath spreads" },
        },
        notes = "The guild freed ghosts before returning the masks.",
    })
    assertEqual(#restockOptions.generatedReplacements.meatgrinder, 2,
        "Restock options should preview generated Meatgrinder drafts")
    assertEqual(restockOptions.meatgrinderReplacementOptions[1].tableKey, "random_encounter",
        "Restock options should preview nested generated Meatgrinder slots")
    assertEqual(restockOptions.meatgrinderReplacementOptions[2].tableKey, "quest_rumor",
        "Restock options should preview singleton generated Meatgrinder slots")
    assertTrue(restockOptions.generatedReplacements.cityEvents[1].entry.summary:find("guild freed ghosts") ~= nil,
        "Restock options should include consequence notes in generated City Event drafts")
    assertEqual(restockOptions.factionUpdateOptions[1].factionId, "golden_ghosts",
        "Restock options should expose generated-restock faction update ids")

    ok, result, detail = autoController:resolveRestockUnderworld({
        autoGenerateReplacements = true,
        mapUpdates = {
            { roomId = "105_hall_of_solemnity", state = "webs destroyed" },
        },
        factionUpdates = {
            { faction = "golden_ghosts", response = "wrath spreads" },
        },
        notes = "The guild freed ghosts before returning the masks.",
    })
    assertTrue(ok, "Restock should generate replacement entries when requested")
    assertTrue(autoResetCalled, "Generated Restock should still reset consumed Meatgrinder markers")
    assertTrue(nestedMeatgrinderTable.random_encounter[1].generated,
        "Generated Restock should replace nested random-encounter Meatgrinder slots")
    assertEqual(nestedMeatgrinderTable.random_encounter[1].replacesConsumedKey,
        "105_hall_of_solemnity:random_encounter:16",
        "Generated nested Meatgrinder replacement should remember the consumed slot")
    assertTrue(nestedMeatgrinderTable.random_encounter[1].description:find("guild freed ghosts") ~= nil,
        "Generated nested Meatgrinder replacement should include consequence notes")
    assertTrue(nestedMeatgrinderTable.quest_rumor.generated,
        "Generated Restock should replace the singleton quest-rumor Meatgrinder slot")
    assertTrue(autoCityEventsTable[12].generated,
        "Generated Restock should replace the last City Event entry")
    assertEqual(autoCityEventsTable[12].category, "rumor",
        "Generated City Event replacement should preserve the old event category")
    assertEqual(#detail.generatedReplacements.meatgrinder, 2,
        "Generated Restock should report generated Meatgrinder drafts")
    assertEqual(#detail.meatgrinderReplacements, 2,
        "Generated Restock should apply generated Meatgrinder drafts")
    assertEqual(detail.meatgrinderReplacements[1].tableKey, "random_encounter",
        "Generated Restock should report nested Meatgrinder table keys")
    assertEqual(#detail.cityEventReplacements, 1,
        "Generated Restock should apply a generated City Event draft")

    local noteOnlyRoster = {}
    local noteOnlyController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guildRoster = noteOnlyRoster,
    })
    restockOptions = noteOnlyController:getRestockUnderworldOptions({
        mapsReviewed = false,
        notes = "No used entries this time.",
    })
    assertTrue(not restockOptions.disabled, "Restock options should allow note-only maintenance")
    assertEqual(restockOptions.mapsReviewed, false, "Restock options should preserve map-review state")
    assertEqual(restockOptions.notes, "No used entries this time.", "Restock options should expose restock notes")
    ok, result, detail = noteOnlyController:resolveRestockUnderworld({
        mapsReviewed = false,
        notes = "No used entries this time.",
    })
    assertTrue(ok, "Restock should allow notes even when no random-table entries were consumed")
    assertEqual(detail.mapsReviewed, false, "Restock should preserve explicit map-review state")
    assertEqual(noteOnlyRoster.restockNotes[1].notes, "No used entries this time.", "Restock should record note-only maintenance")

    local cityProcedure = city_phase.getCityPhaseProcedure()
    assertEqual(cityProcedure.steps[1].key, city_phase.STEPS.DEATH_AND_TAXES,
        "City Phase procedure should expose Death and taxes as the first step")
    assertEqual(cityProcedure.steps[8].key, city_phase.STEPS.RESTOCK_UNDERWORLD,
        "City Phase procedure should expose Restock the Underworld as the final step")
    assertEqual(city_phase.getCityPhaseProcedure().steps[1].label, "Death and taxes",
        "City Phase procedure helper should return copy-safe metadata")
    cityProcedure.steps[1].label = "changed"
    assertEqual(city_phase.getCityPhaseProcedure().steps[1].label, "Death and taxes",
        "City Phase procedure mutation should not leak into module metadata")

    local cityStepDetails = city_phase.getCityPhaseStepDetails()
    assertEqual(#cityStepDetails, #city_phase.CITY_PHASE_STEP_ORDER,
        "City Phase step detail helper should cover every ordered step")
    assertEqual(city_phase.getCityPhaseStepDetails("City Actions").rules.actionsPerAdventurer, 1,
        "City Phase step detail helper should preserve action turn accounting")
    assertEqual(city_phase.getCityPhaseStepDetails(city_phase.STEPS.CITY_EVENTS).rules.signsAndPortents,
        "XXI consults the top minor arcana discard",
        "City Phase step detail helper should expose Signs and Portents draw rules")

    local cityActions = city_phase.getCityActionDetails()
    assertEqual(cityActions[city_phase.ACTIONS.BANKING].returnRate, city_phase.BANKING_RETURN_RATE,
        "City Action details should expose Banking return rate")
    assertEqual(cityActions[city_phase.ACTIONS.BEG_AND_BUSK].deck, "minor_arcana",
        "City Action details should expose Beg and Busk's minor-deck draw")
    assertEqual(city_phase.getCityActionDetails("research").costGold, city_phase.RESEARCH_COST,
        "City Action detail helper should resolve aliases for Research")
    assertEqual(city_phase.getCityActionDetails({ type = "commission" }).costs[2].goldPerSyllable, 5,
        "City Action detail helper should normalize table requests")
    cityActions[city_phase.ACTIONS.BANKING].returnRate = 1
    assertEqual(city_phase.getCityActionDetails(city_phase.ACTIONS.BANKING).returnRate, city_phase.BANKING_RETURN_RATE,
        "City Action detail helper should return copy-safe records")

    local actor = base_entity.createEntity({
        id = "pc_city_flow",
        name = "City Flow",
        isPC = true,
        wands = 2,
    })
    actor.gold = 200
    actor.inventory = inventory.createInventory()

    local controller = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { actor },
        guildRoster = {},
        contracts = {},
        strictCityPhaseOrder = true,
    })

    local status = controller:getCityPhaseFlowStatus()
    assertEqual(#status.steps, #city_phase.CITY_PHASE_STEP_ORDER, "City Phase status should expose every ordered step")
    assertEqual(status.nextStep, city_phase.STEPS.DEATH_AND_TAXES, "City Phase should start with Death and taxes")
    assertTrue(status.steps[1].current, "first unresolved step should be marked current")
    assertTrue(not status.complete, "fresh City Phase flow should not be complete")

    local turnOptions = controller:getCityActionTurnOptions({
        actor = actor,
        action = { type = "beg_and_busk" },
    })
    assertEqual(turnOptions.step, city_phase.STEPS.CITY_ACTIONS,
        "City Action turn options should identify the City Actions step")
    assertTrue(not turnOptions.stepGate.available,
        "City Action turn options should respect strict step ordering")
    assertEqual(turnOptions.stepGate.detail.blockedBy, city_phase.STEPS.DEATH_AND_TAXES,
        "City Action turn options should report the incomplete prior step")
    assertEqual(turnOptions.pendingCount, 1,
        "City Action turn options should count pending active adventurers")
    assertEqual(turnOptions.completedCount, 0,
        "City Action turn options should start with no completed adventurers")
    assertEqual(turnOptions.selectedAction.unavailableReason, "Previous City Phase steps incomplete",
        "City Action turn options should gate selected actions behind strict ordering")

    local ok, result, detail = controller:resolveCityPhaseStep(city_phase.STEPS.CITY_EVENTS, {
        majorCard = {
            name = "The Magician",
            value = 1,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
    })
    assertTrue(not ok, "strict City Phase flow should block later steps before earlier ones")
    assertEqual(result, "Previous City Phase steps incomplete", "strict flow should explain order violations")
    assertEqual(detail.blockedBy, city_phase.STEPS.DEATH_AND_TAXES, "strict flow should identify the missing prior step")

    ok, result = controller:resolveCityPhaseStep("death and taxes")
    assertTrue(ok, "flow dispatcher should resolve Death and taxes")
    assertEqual(result, "death_and_taxes_resolved", "flow dispatcher should return the underlying Death and taxes result")
    status = controller:getCityPhaseFlowStatus()
    assertEqual(status.nextStep, city_phase.STEPS.NOTEWORTHY_DEEDS, "flow status should advance after taxes")

    ok, result = controller:resolveCityPhaseStep("noteworthy deeds")
    assertTrue(ok, "flow dispatcher should resolve Noteworthy deeds")
    assertEqual(result, "noteworthy_deeds_aged", "empty Noteworthy deeds step should still complete")

    ok, result = controller:resolveCityPhaseStep("city events", {
        majorCard = {
            name = "The Magician",
            value = 1,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
    })
    assertTrue(ok, "flow dispatcher should resolve City Events")
    assertEqual(result, "city_event_resolved", "flow dispatcher should return City Event resolution")

    ok, result = controller:resolveCityPhaseStep("turn in contracts")
    assertTrue(ok, "flow dispatcher should resolve Turn in contracts")
    assertEqual(result, "no_completed_contracts", "empty contract turn-in should still complete")

    ok, result = controller:resolveCityPhaseStep("upkeep", {
        actor = actor,
        tier = "common",
    })
    assertTrue(ok, "flow dispatcher should resolve actor Upkeep")
    assertEqual(result, "upkeep_resolved", "flow dispatcher should return the underlying Upkeep result")

    turnOptions = controller:getCityActionTurnOptions({
        actor = actor,
        action = { type = "beg_and_busk" },
    })
    assertTrue(turnOptions.stepGate.available,
        "City Action turn options should unlock after previous ordered steps")
    assertEqual(turnOptions.actionsPerAdventurer, 1,
        "City Action turn options should expose rulebook one-action accounting")
    assertEqual(turnOptions.requiredCount, 1,
        "City Action turn options should require every active adventurer")
    assertEqual(turnOptions.pendingActors[1].actor, actor,
        "City Action turn options should list pending active adventurers")
    assertTrue(turnOptions.selectedAction.available,
        "City Action turn options should allow an unused selected actor")
    assertTrue(turnOptions.commonActionChoices[city_phase.ACTIONS.BEG_AND_BUSK].allowed,
        "City Action turn options should expose allowed common actions")

    ok, result = controller:resolveCityPhaseStep("city actions", {
        actor = actor,
        action = {
            type = "beg_and_busk",
            card = {
                name = "Three of Wands",
                value = 3,
                suit = constants.SUITS.WANDS,
            },
        },
    })
    assertTrue(ok, "flow dispatcher should resolve an actor City Action")
    assertEqual(result, "beg_and_busk_resolved", "flow dispatcher should return the underlying City Action result")
    assertTrue(controller:canAdvance(), "flow dispatcher City Action should count toward phase advancement")
    turnOptions = controller:getCityActionTurnOptions({
        actor = actor,
        action = { type = "beg_and_busk" },
    })
    assertEqual(turnOptions.completedCount, 1,
        "City Action turn options should count completed adventurers")
    assertEqual(turnOptions.pendingCount, 0,
        "City Action turn options should clear pending actors after completion")
    assertEqual(turnOptions.completedActors[1].action, city_phase.ACTIONS.BEG_AND_BUSK,
        "City Action turn options should report completed action ids")
    assertEqual(turnOptions.selectedAction.unavailableReason, "City Action already taken",
        "City Action turn options should explain repeat actor actions")
    assertEqual(turnOptions.resultPreview, "city_actions_complete",
        "City Action turn options should preview completed turn accounting")

    ok, result = controller:resolveCityPhaseStep("plan next crawl", {
        requireJobBoard = false,
        currentQuest = "Return to the Underworld",
        destination = "Tomb of Golden Ghosts",
    })
    assertTrue(ok, "flow dispatcher should resolve Plan the next Crawl")
    assertEqual(result, "next_crawl_planned", "flow dispatcher should return planning completion")

    ok, result = controller:resolveCityPhaseStep("restock underworld", {
        notes = "No table entries were consumed during the flow smoke test.",
    })
    assertTrue(ok, "flow dispatcher should resolve Restock the Underworld")
    assertEqual(result, "underworld_restocked", "flow dispatcher should return restock completion")

    status = controller:getCityPhaseFlowStatus()
    assertTrue(status.complete, "City Phase flow status should report completion after every ordered step")
    assertEqual(status.nextStep, nil, "completed City Phase flow should have no next step")
    assertTrue(status.readyToEnd, "completed City Phase flow should be ready for the end hook")

    local openOrderController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { actor },
    })
    ok, result = openOrderController:resolveCityPhaseStep(city_phase.STEPS.CITY_EVENTS, {
        strictOrder = false,
        majorCard = {
            name = "The Magician",
            value = 1,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
    })
    assertTrue(ok, "non-strict flow dispatcher should preserve direct resolver flexibility")
    assertEqual(result, "city_event_resolved", "non-strict dispatch should still resolve the requested step")

    local restrictedController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { actor },
        cityEventEffects = {
            allowedCityActions = {
                [city_phase.ACTIONS.CAROUSE] = true,
            },
        },
    })
    turnOptions = restrictedController:getCityActionTurnOptions({
        actor = actor,
        action = { type = "beg_and_busk" },
    })
    assertTrue(turnOptions.commonActionChoices[city_phase.ACTIONS.CAROUSE].allowed,
        "City Action turn options should preserve City Event allowed action choices")
    assertTrue(turnOptions.commonActionChoices[city_phase.ACTIONS.BEG_AND_BUSK].disabled,
        "City Action turn options should disable actions outside City Event restrictions")
    assertEqual(turnOptions.selectedAction.unavailableReason, "City Action not available during this City Event",
        "City Action turn options should explain City Event action restrictions")
end

function checkAppendixEUnderworldOrigins()
    local underworld_creation = require('logic.underworld_creation')
    local procedure = underworld_creation.getProcedureSteps()
    assertEqual(procedure.steps[1].key, "origins",
        "Appendix E procedure helper should expose the first Underworld-wide step")
    assertEqual(procedure.steps[3].scope, "dungeon_level",
        "Appendix E procedure helper should mark map creation as a per-level step")
    assertTrue(hasValue(procedure.cadence.underworldWideSteps, "generate_layout"),
        "Appendix E procedure helper should preserve the steps 1-2 cadence")
    assertTrue(hasValue(procedure.cadence.repeatedPerLevelSteps, "create_meatgrinder"),
        "Appendix E procedure helper should preserve repeated level steps")
    procedure.steps[1].label = "Invented step"
    assertEqual(underworld_creation.getProcedureSteps().steps[1].label, "Origins of the Underworld",
        "Appendix E procedure helper should return copy-safe records")
    local origins, result, detail = underworld_creation.recordOrigins({
        truth = "The Underworld is a stolen heaven below the City.",
        originalPurpose = "Guide the dead through rebirth.",
        currentOccupiers = {
            "brain spiders",
            "golden ghosts",
        },
        occupationContradiction = "The occupiers hoard souls instead of releasing them.",
        openQuestions = {
            "Who stole the first dawn?",
            "What happens if a ghost remembers its name?",
        },
        loreHooks = {
            traps = {
                "Prayer traps still enforce the old celestial law.",
            },
            treasure = {
                {
                    id = "coin_faces",
                    clue = "Ancient coins show deposed goddesses.",
                },
            },
        },
    })
    assertTrue(origins ~= nil, "Appendix E origins helper should record complete Underworld origins")
    assertEqual(result, "underworld_origins_recorded", "Underworld origins should report completion")
    assertEqual(origins.truth, "The Underworld is a stolen heaven below the City.",
        "origins should preserve the foundational Underworld truth")
    assertEqual(origins.originalPurpose, "Guide the dead through rebirth.",
        "origins should preserve the Underworld's intended purpose")
    assertEqual(origins.currentOccupiers[1], "brain spiders",
        "origins should preserve current usurping occupiers")
    assertTrue(origins.currentOccupiersContradictOriginalPurpose,
        "origins should mark current occupation as contradictory to original use")
    assertEqual(origins.openQuestions[2], "What happens if a ghost remembers its name?",
        "origins should preserve open-ended questions")
    assertEqual(origins.loreHooks.traps[1], "Prayer traps still enforce the old celestial law.",
        "origins should preserve trap lore hooks")
    assertEqual(origins.loreHooks.treasure[1].id, "coin_faces",
        "origins should preserve structured treasure lore hooks")
    assertTrue(origins.gmSecret and origins.requiresSecrecy,
        "origins should default to GM-facing secret planning material")
    assertTrue(detail.readyForLayout, "complete origins should be ready for layout generation")
    assertEqual(origins.dungeonLoreGuidance.languages,
        "Use unknown or forgotten languages as discoverable lore.",
        "origins should carry Appendix E dungeon-lore guidance")

    local ok, validation = underworld_creation.validateOrigins({
        nature = "The Underworld is the first kingdom of humanity.",
        intendedUse = "Preserve the first oaths between humans and dragons.",
        currentOccupation = "dragons are chained below their old throne room",
        questions = {
            "Who broke the old oaths?",
        },
    })
    assertTrue(ok, "validateOrigins should accept all required Appendix E prompts")
    assertEqual(validation, "underworld_origins_valid", "validateOrigins should report a validation result")

    local layout = underworld_creation.generateLayout({
        cards = { 1, 2, 3 },
        requireOrigins = true,
        origins = {
            truth = "The Underworld is the corpse of the World Giant.",
            originalPurpose = "Hold up the living world.",
            currentOccupiers = "miners hollow out its bones",
            openQuestions = {
                "What wakes when the last rib breaks?",
            },
        },
    })
    assertTrue(layout ~= nil, "layout generation should accept complete required origins")
    assertEqual(layout.origins.openQuestions[1], "What wakes when the last rib breaks?",
        "layout generation should normalize and preserve required origins")

    local invalid, reason = underworld_creation.recordOrigins({
        originalPurpose = "Hold the dead.",
        currentOccupiers = "grave robbers",
        openQuestions = {
            "Who profits?",
        },
    })
    assertTrue(not invalid, "origins should reject missing Underworld truth")
    assertEqual(reason, "Underworld truth required",
        "missing-truth rejection should explain the required Appendix E prompt")

    invalid, reason = underworld_creation.recordOrigins({
        truth = "The Underworld is Hell itself.",
        currentOccupiers = "tourists",
        openQuestions = {
            "Who opened the gates?",
        },
    })
    assertTrue(not invalid, "origins should reject missing original purpose")
    assertEqual(reason, "Original purpose required",
        "missing-purpose rejection should explain the required Appendix E prompt")

    invalid, reason = underworld_creation.recordOrigins({
        truth = "The Underworld is a prison for wicked souls.",
        originalPurpose = "Contain eternal punishments.",
        openQuestions = {
            "Who deserves release?",
        },
    })
    assertTrue(not invalid, "origins should reject missing current occupation contradiction")
    assertEqual(reason, "Current occupation contradiction required",
        "missing-occupation rejection should explain the required Appendix E prompt")

    invalid, reason = underworld_creation.recordOrigins({
        truth = "The Underworld is the Garden of Eden.",
        originalPurpose = "Keep the Trees of Knowledge and Life unreachable.",
        currentOccupiers = "pious gardeners",
    })
    assertTrue(not invalid, "origins should reject missing open-ended questions")
    assertEqual(reason, "Open-ended questions required",
        "missing-question rejection should explain the required Appendix E prompt")

    invalid, reason = underworld_creation.generateLayout({
        cards = { 1, 2, 3 },
        requireOrigins = true,
        origins = {
            truth = "The Underworld is a tomb.",
        },
    })
    assertTrue(not invalid, "layout generation should enforce complete origins when requested")
    assertEqual(reason, "Original purpose required",
        "required-origin layout rejection should surface origin validation errors")
end

function checkAppendixEUnderworldLayoutGeneration()
    local underworld_creation = require('logic.underworld_creation')
    local magicianSeed = underworld_creation.getDungeonSeed(1)
    assertEqual(magicianSeed.name, "The Spires",
        "Appendix E dungeon seed helper should expose seed names")
    assertEqual(magicianSeed.lighting, "Dim mushroom half-light like moonlight.",
        "Appendix E dungeon seed helper should expose lighting guidance")
    assertTrue(hasValue(magicianSeed.commonMonsters, "Forest Imps"),
        "Appendix E dungeon seed helper should expose common monster prompts")

    local forgeSeed = underworld_creation.getDungeonSeed({
        value = 18,
    })
    assertEqual(forgeSeed.dungeonLord, "The Truesilver Golem",
        "Appendix E dungeon seed helper should expose dungeon-lord prompts")
    assertEqual(forgeSeed.sensory.smellTaste, "Chemical ozone.",
        "Appendix E dungeon seed helper should expose sensory defaults")
    forgeSeed.commonMonsters[1] = "Mutated Test Monster"
    assertEqual(underworld_creation.getDungeonSeed(18).commonMonsters[1], "Hallucination Imps",
        "Appendix E dungeon seed helper should return copy-safe seed records")
    assertEqual(underworld_creation.getDungeonSeed(0), nil,
        "Appendix E dungeon seed helper should reject The Fool")

    local layout, result, detail = underworld_creation.generateLayout({
        cards = {
            { name = "The High Priestess", value = 2, suit = constants.SUITS.MAJOR, is_major = true },
            { name = "The Emperor", value = 4, suit = constants.SUITS.MAJOR, is_major = true },
            { name = "The Hierophant", value = 5, suit = constants.SUITS.MAJOR, is_major = true },
            { name = "The Hanged Man", value = 12, suit = constants.SUITS.MAJOR, is_major = true },
            { name = "The Moon", value = 18, suit = constants.SUITS.MAJOR, is_major = true },
        },
        entrances = {
            [4] = {
                known = false,
                traversable = false,
                sealed = true,
                secret = true,
                notes = "A drowned stair sealed below the harbor.",
            },
            [5] = {
                known = true,
                traversable = true,
                sealed = false,
                notes = "A public stair inside a ruined shrine.",
            },
        },
        connectionDefinitions = {
            ["2:4"] = {
                type = "drowned stair",
                description = "A flooded stair drops from the Boundless Moat to the sealed Emperor gate.",
            },
            ["2:5"] = {
                type = "processional hall",
                description = "A public shrine hall slopes from the main entrance toward the ruined city.",
            },
            ["2:12"] = {
                type = "well shaft",
                description = "A rope-and-bucket shaft descends from the moat into Xania's upper cistern.",
            },
            ["2:18"] = {
                type = "mirror gate",
                description = "A truesilver mirror opens only when moonlight touches the moat.",
            },
            ["4:5"] = {
                type = "collapsed avenue",
                description = "A buried imperial road links the inverted castle to the City of Ruin.",
            },
            ["4:12"] = {
                type = "river lock",
                description = "A drained lock chamber can lower travelers from the Emperor's vaults to Xania.",
            },
            ["12:18"] = {
                type = "moon elevator",
                description = "A silent elevator rises and falls with the reflected moon.",
            },
        },
        origins = {
            truth = "The Underworld is a stolen kingdom of the dead.",
            currentOccupiersContradictOriginalPurpose = true,
        },
    })
    assertTrue(layout ~= nil, "Appendix E helper should generate an Underworld layout")
    assertEqual(result, "underworld_layout_generated", "Underworld layout generation should report completion")
    assertEqual(layout.counts.levels, 5, "Underworld layout should keep every drawn dungeon card")
    assertEqual(layout.mainEntrance.value, 2, "lowest drawn card should contain the main entrance")
    assertEqual(layout.mainEntrance.seedName, "The Boundless Moat",
        "layout levels should attach the matching Appendix E dungeon seed")
    assertEqual(layout.mainEntrance.seedLighting, "Dim blue light from bioluminescent waters.",
        "layout levels should attach dungeon-seed lighting guidance")
    assertTrue(hasValue(layout.mainEntrance.commonMonsters, "Kelpies"),
        "layout levels should attach dungeon-seed common monster prompts")
    assertEqual(layout.deepest.value, 18, "highest drawn card should become the deepest dungeon")
    assertEqual(layout.deepest.seedName, "The Truesilver Forge",
        "deepest level should preserve its dungeon-seed identity")
    assertEqual(layout.deepest.dungeonSeed.summary,
        "A mithril mining colony and forge where truesilver sickness distorts minds and magic.",
        "deepest level should preserve the full dungeon-seed detail record")
    assertEqual(layout.counts.depthProfiles, 5,
        "Underworld layout should expose depth guidance for every dungeon level")
    assertEqual(layout.deepest.depthProfile.verticalDepth, 2,
        "deepest level should preserve its cross-section depth")
    assertEqual(layout.deepest.depthProfile.resourcePressure, "deepest",
        "deepest level should carry special resource-pressure guidance")
    assertTrue(layout.deepest.depthProfile.requiresMoreTorchesAndRations,
        "deeper dungeon levels should flag additional torch and ration pressure")
    assertEqual(detail.depthProfiles[5].deepestQuestion,
        "What lurks inside the deepest dungeon, farthest from egress?",
        "layout detail should preserve the deepest-dungeon prompt")
    assertEqual(layout.counts.entrances, 3,
        "main entrance plus all I-V cards should be marked as surface entrances")
    assertEqual(detail.entrances[2].value, 4,
        "additional I-V entrance records should preserve card values")
    assertTrue(detail.entrances[2].sealed and detail.entrances[2].secret,
        "extra entrances should preserve the GM's known/traversable/secret decision")
    assertTrue(not detail.entrances[2].requiresDecision,
        "decided extra entrances should not remain flagged for GM choice")

    local mainToFourth = underworld_creation.findConnection(layout, 2, 4)
    assertTrue(mainToFourth ~= nil, "physically next/divisible levels should be connected")
    assertTrue(mainToFourth.rulebookRules.physically_next,
        "physically next Underworld cards should create a connection")
    assertTrue(mainToFourth.rulebookRules.divisible,
        "evenly divisible Underworld card values should create a connection")
    assertEqual(mainToFourth.connectionType, "drowned stair",
        "layout generation should preserve explicit connection type authoring")
    assertEqual(mainToFourth.description,
        "A flooded stair drops from the Boundless Moat to the sealed Emperor gate.",
        "layout generation should preserve how connected levels are connected")

    local fourthToFifth = underworld_creation.findConnection(layout, 4, 5)
    assertTrue(fourthToFifth ~= nil, "sequential Underworld cards should be connected")
    assertTrue(fourthToFifth.rulebookRules.sequential,
        "sequential card values should create a connection")

    local twelfthToEighteenth = underworld_creation.findConnection(layout, 12, 18)
    assertTrue(twelfthToEighteenth ~= nil,
        "levels physically adjacent in the generated cross-section should be connected")
    assertTrue(twelfthToEighteenth.rulebookRules.physically_next,
        "generated depth ordering should expose physical adjacency connections")
    assertTrue(not twelfthToEighteenth.rulebookRules.sequential,
        "non-sequential adjacent levels should not invent a sequential rule")

    local validLayout, validationResult, validationDetail = underworld_creation.validateLayout(layout, {
        requireConnectionDefinitions = true,
    })
    assertTrue(validLayout, "saved Underworld layouts should validate after generation")
    assertEqual(validationResult, "underworld_layout_valid",
        "saved Underworld layout validation should report completion")
    assertEqual(validationDetail.depthProfiles[5].resourcePressure, "deepest",
        "saved layout validation should expose depth pressure profiles")
    assertEqual(#validationDetail.undefinedConnections, 0,
        "strict saved-layout validation should accept defined inter-level connections")

    local looseLayout = underworld_creation.generateLayout({
        cards = { 1, 6, 12 },
    })
    local invalid, reason, invalidDetail = underworld_creation.validateLayout(looseLayout, {
        requireConnectionDefinitions = true,
    })
    assertTrue(not invalid, "strict saved-layout validation should reject undefined inter-level connections")
    assertEqual(reason, "Underworld layout incomplete",
        "undefined connection rejection should report layout incompleteness")
    assertTrue(hasValue(invalidDetail.missing, "connection_definitions"),
        "undefined connection rejection should expose the missing connection-definition checklist item")

    invalid, reason = underworld_creation.generateLayout({
        cards = {
            { name = "The Fool", value = 0, suit = constants.SUITS.MAJOR, is_major = true },
            { name = "The Magician", value = 1, suit = constants.SUITS.MAJOR, is_major = true },
            { name = "The High Priestess", value = 2, suit = constants.SUITS.MAJOR, is_major = true },
        },
    })
    assertTrue(not invalid, "Underworld layout should reject The Fool")
    assertEqual(reason, "The Fool is not used for Underworld layout",
        "The Fool rejection should explain the Appendix E Major Arcana range")

    invalid, reason = underworld_creation.generateLayout({
        cards = {
            { name = "Two of Cups", value = 2, suit = constants.SUITS.CUPS, is_major = false },
            { name = "The Magician", value = 1, suit = constants.SUITS.MAJOR, is_major = true },
            { name = "The High Priestess", value = 2, suit = constants.SUITS.MAJOR, is_major = true },
        },
    })
    assertTrue(not invalid, "Underworld layout should reject suited minor arcana")
    assertEqual(reason, "Major Arcana card required",
        "minor-card layout rejection should explain the Major Arcana requirement")

    invalid, reason = underworld_creation.generateLayout({
        cards = {
            2,
            4,
            4,
        },
    })
    assertTrue(not invalid, "Underworld layout should reject duplicate Major Arcana values")
    assertEqual(reason, "Duplicate dungeon card",
        "duplicate Underworld layout cards should explain the uniqueness requirement")
end

function checkAppendixERoomDescriptionChecklist()
    local underworld_creation = require('logic.underworld_creation')
    local ok, result, detail = underworld_creation.validateRoomDescriptions({
        {
            id = "101_scriptorium",
            description = "A small room of crumbling scrolls and apparently blank books.",
            reasons = {
                "reason to explore",
                {
                    key = "be surprised",
                    note = "Some books reveal text only under a moon-phase light.",
                },
            },
            lighting = "low torchlight",
            sensory = {
                smell = "mold",
            },
        },
        {
            id = "102_ghost_hall",
            description = "Golden ghosts hover near a warded alcove.",
            reasonToTalk = "The ghosts know the old royal debts.",
            reasonToFight = true,
            reasonToBreatheEasy = "The alcove is warded against centipedes.",
            reasonToReturn = "A gargoyle elsewhere needs its ears brought back here.",
        },
        {
            id = "103_world_machine",
            description = "A dragon sleeps beside a huge hydraulic press.",
            checklist = {
                flee = "The sleeping dragon is too much for an honest fight.",
                experiment = "The hydraulic press can reshape dungeon objects.",
            },
        },
    }, {
        strictLevelDefaults = true,
        defaultLighting = "pitch dark",
        defaultSensory = {
            sound = "distant river",
        },
    })
    assertTrue(ok, "room description checklist should accept rooms with Appendix E reasons")
    assertEqual(result, "room_descriptions_valid", "room checklist validation should report completion")
    assertEqual(detail.count, 3, "room checklist validation should preserve every checked room")
    assertTrue(detail.rooms[1].reasonFlags.explore,
        "room checklist should normalize reason-to-explore wording")
    assertTrue(detail.rooms[1].reasonFlags.surprise,
        "room checklist should normalize reason-to-be-surprised wording")
    assertEqual(detail.rooms[1].standardLighting, "low torchlight",
        "room checklist should preserve room-specific lighting")
    assertEqual(detail.rooms[2].reasonDetails.talk.note, "The ghosts know the old royal debts.",
        "room checklist should preserve reason notes from direct fields")
    assertTrue(detail.rooms[2].reasonFlags.fight and detail.rooms[2].reasonFlags.breathe_easy,
        "room checklist should accept fight and breathe-easy direct fields")
    assertTrue(detail.rooms[2].reasonFlags["return"],
        "room checklist should accept return hooks")
    assertTrue(detail.rooms[3].reasonFlags.flee and detail.rooms[3].reasonFlags.experiment,
        "room checklist should accept keyed checklist entries")
    assertTrue(not detail.rooms[3].warningFlags.lighting_missing,
        "level defaults should satisfy strict lighting checks")

    ok, result, detail = underworld_creation.validateRoomDescriptions({
        {
            id = "104_secret_hearth",
            description = "A hidden hearth cut into the wall.",
            safe = true,
            reasonToBreatheEasy = "The hearth is hidden from centipede patrols.",
            safeRoomNote = "warm hidden hearth",
        },
        {
            id = "105_warded_alcove",
            description = "An alcove under a gold ward.",
            reasonToBreatheEasy = "The gold ward keeps restless ghosts outside.",
            lookAndFeel = "quiet gold alcove",
        },
        {
            id = "106_treasure_pit",
            description = "A collapsed pit glitters with coins.",
            reasonToExplore = "A broken crown is visible below the rubble.",
        },
    }, {
        requireSafeRooms = true,
        requireSafeRoomNotes = true,
    })
    assertTrue(ok, "safe-room authoring should accept a handful of marked safe rooms")
    assertEqual(result, "room_descriptions_valid",
        "safe-room authoring should report room description completion")
    assertEqual(detail.safeRooms.count, 2,
        "safe-room authoring should count marked safe rooms")
    assertEqual(detail.safeRooms.safeRooms[1].note, "warm hidden hearth",
        "safe-room authoring should preserve terse look-and-feel notes")

    ok, result, detail = underworld_creation.validateRoomDescriptions({
        {
            id = "116_idol_vault",
            description = "An idol with emerald eyes watches the flooded chamber.",
            reasonToExplore = "The emerald eyes are worth carrying back to the City.",
            treasures = {
                {
                    id = "emerald_idol_eyes",
                    type = "treasure",
                    description = "Two fist-sized emeralds set into a fish-god idol.",
                    gold = 80,
                    questHook = "The finfolk want the eyes for a treaty gift.",
                },
            },
        },
