            name = "Dire Spiders",
            goals = {
                "fine art",
                "interesting stories",
            },
            avoids = {
                "harpies finding the nest",
                "open flames near the tapestries",
            },
        },
    })
    assertTrue(ok, "Appendix E faction authoring should accept wants and don't-wants")
    assertEqual(result, "dungeon_level_factions_valid",
        "level faction validation should report completion")
    assertEqual(detail.factions[1].wants[1], "their tomb treasure returned",
        "faction authoring should preserve what the faction wants")
    assertEqual(detail.factions[1].doesNotWant[1], "soul thieves carrying open flame",
        "faction authoring should preserve what the faction does not want")
    assertEqual(detail.factions[1].languageContext[1],
        "Vetus names reveal which ghosts still remember the royal debt.",
        "faction authoring should preserve language-specific social clues")
    assertTrue(detail.factions[2].warningFlags.languages_missing,
        "faction authoring should warn when language planning is absent")

    invalid, reason, invalidDetail = underworld_creation.validateFaction({
        name = "Hungry Centipedes",
        wants = {
            "meat and warmth",
        },
    })
    assertTrue(not invalid, "faction authoring should reject missing don't-wants")
    assertEqual(reason, "Faction incomplete",
        "incomplete faction rejection should explain the faction checklist")
    assertTrue(hasValue(invalidDetail.missing, "faction_does_not_want"),
        "incomplete faction details should expose the missing don't-want prompt")

    invalid, reason, invalidDetail = underworld_creation.validateFaction({
        name = "Silent Masks",
        wants = {
            "ancient greetings in the correct tongue",
        },
        doesNotWant = {
            "surface slang spoken in their sanctuary",
        },
        languages = {
            "Vetus",
        },
    }, {
        requireLanguageContext = true,
    })
    assertTrue(not invalid, "strict faction language authoring should reject missing language hooks")
    assertEqual(reason, "Faction incomplete",
        "missing language-hook rejection should explain the faction checklist")
    assertTrue(hasValue(invalidDetail.missing, "faction_language_context"),
        "strict faction details should expose missing language-specific hooks")
    assertTrue(invalidDetail.warningFlags.language_context_missing,
        "strict faction details should warn about missing language context")
end

