function checkAppendixEMapAuthoringChecklist()
    local underworld_creation = require('logic.underworld_creation')
    local ok, result, detail = underworld_creation.validateDungeonMap({
        levelNumber = 1,
        leaveSpaceBetweenAreas = true,
        rooms = {
            { id = "101_entrance", name = "Entrance", shape = "square room" },
            { id = "102_scriptorium", name = "Scriptorium", shape = "rectangular room" },
            { id = "103_antechamber", name = "Antechamber", shape = "circle tower" },
            { id = "104_ghost_hall", name = "Ghost Hall", shape = "long hall" },
            { id = "105_hidden_sanctum", name = "Hidden Sanctum", shape = "small hidden room" },
        },
        connections = {
            { from = "101_entrance", to = "102_scriptorium", properties = { direction = "east", pathwayType = "hall" } },
            { from = "101_entrance", to = "103_antechamber", properties = { direction = "north", pathwayType = "stairs" } },
            { from = "102_scriptorium", to = "104_ghost_hall", properties = { direction = "east", pathwayType = "bridge" } },
            { from = "103_antechamber", to = "104_ghost_hall", properties = { direction = "east", pathwayType = "arched hall" } },
            {
                from = "102_scriptorium",
                to = "105_hidden_sanctum",
                properties = {
                    direction = "south",
                    is_secret = true,
                    shortcut = true,
                    pathwayType = "secret crawlspace",
                },
            },
        },
        playerMap = {
            rooms = {
                { id = "101_entrance", number = "101" },
                { id = "102_scriptorium", number = "102" },
                { id = "103_antechamber", number = "103" },
            },
            blankSpaceForNotes = true,
        },
    }, {
        requireTopologyChecklist = true,
        requireMapDrawingDetails = true,
    })
    assertTrue(ok, "Appendix E map checklist should accept a keyed non-linear dungeon map")
    assertEqual(result, "dungeon_map_valid", "map checklist should report validation")
    assertEqual(detail.roomCount, 5, "map checklist should preserve room count")
    assertEqual(detail.connectionCount, 5, "map checklist should preserve valid pathway count")
    assertTrue(detail.topology.connected, "map checklist should require connected pathways")
    assertTrue(detail.topology.hasCycle, "map checklist should detect feedback-loop paths")
    assertTrue(#detail.topology.choiceNodes >= 1, "map checklist should detect choice points")
    assertEqual(detail.topology.shortcutCount, 1, "map checklist should count authored shortcuts")
    assertEqual(detail.topology.bridgeCount, 1, "map checklist should count choke-point pathways")
    assertTrue(detail.topology.checklist.shortcuts and detail.topology.checklist.chokePoints and
        detail.topology.checklist.feedbackLoops,
        "strict map topology checklist should require shortcuts, choke points, and feedback loops")
    assertEqual(detail.drawing.rooms[3].shape, "circle tower",
        "map drawing checklist should preserve authored area shapes")
    assertEqual(detail.drawing.pathways[5].pathwayType, "secret crawlspace",
        "map drawing checklist should preserve authored pathway types")
    assertTrue(detail.drawing.areaSpacing,
        "map drawing checklist should preserve the leave-space-between-areas signal")
    assertTrue(detail.playerMap.majorityRoomsShown,
        "player-facing map should show a majority of known room numbers")
    assertTrue(detail.playerMap.noContents,
        "player-facing map should omit room contents")
    assertTrue(detail.playerMap.blankSpaceForNotes,
        "player-facing map should reserve space for player discoveries")

    ok, result, detail = underworld_creation.validateDungeonMaps({
        maps = {
            {
                levelNumber = 2,
                rooms = {
                    { id = "201_gate" },
                    { id = "202_loop_a" },
                    { id = "203_loop_b" },
                },
                connections = {
                    { from = "201_gate", to = "202_loop_a" },
                    { from = "202_loop_a", to = "203_loop_b" },
                    { from = "203_loop_b", to = "201_gate" },
                },
                playerMap = {
                    rooms = {
                        "201_gate",
                        "202_loop_a",
                    },
                    openSpace = true,
                },
            },
        },
    })
    assertTrue(ok, "batch map checklist should accept valid level maps")
    assertEqual(result, "dungeon_maps_valid", "batch map checklist should report validation")
    assertEqual(detail.count, 1, "batch map checklist should preserve map count")

    local invalid, reason, invalidDetail = underworld_creation.validateDungeonMap({
        levelNumber = 1,
        rooms = {
            { id = "101_entrance" },
            { id = "205_wrong_level" },
        },
        connections = {
            { from = "101_entrance", to = "999_missing" },
        },
        playerMap = {
            rooms = {
                { id = "101_entrance", number = "101", contents = "hidden idol" },
            },
            blankSpaceForNotes = true,
        },
    })
    assertTrue(not invalid, "map checklist should reject wrong-level and invalid pathway maps")
    assertEqual(reason, "Dungeon map incomplete",
        "map checklist rejection should explain incomplete map authoring")
    assertTrue(hasValue(invalidDetail.missing, "level_keyed_room_numbers"),
        "map checklist should report room numbers keyed to the wrong level")
    assertTrue(hasValue(invalidDetail.missing, "valid_pathways"),
        "map checklist should report pathways that reference missing rooms")
    assertTrue(hasValue(invalidDetail.missing, "player_map_without_contents"),
        "map checklist should reject player maps that reveal room contents")

    invalid, reason, invalidDetail = underworld_creation.validateDungeonMap({
        levelNumber = 1,
        rooms = {
            { id = "101_a" },
            { id = "102_b" },
            { id = "103_c" },
        },
        connections = {
            { from = "101_a", to = "102_b" },
            { from = "102_b", to = "103_c" },
        },
        playerMap = {
            rooms = {
                "101_a",
                "102_b",
            },
            blankSpaceForNotes = true,
        },
    })
    assertTrue(not invalid, "map checklist should reject strictly linear dungeon maps")
    assertTrue(hasValue(invalidDetail.missing, "non_linear_paths"),
        "linear-map rejection should report the missing non-linear pathway structure")

    invalid, reason, invalidDetail = underworld_creation.validateDungeonMap({
        levelNumber = 1,
        rooms = {
            { id = "101_a" },
            { id = "102_b" },
            { id = "103_c" },
        },
        connections = {
            { from = "101_a", to = "102_b" },
            { from = "102_b", to = "103_c" },
            { from = "103_c", to = "101_a" },
        },
        playerMap = {
            rooms = {
                "101_a",
                "102_b",
            },
            blankSpaceForNotes = true,
        },
    }, {
        requireTopologyChecklist = true,
    })
    assertTrue(not invalid, "strict map topology should reject maps without shortcuts and choke points")
    assertEqual(reason, "Dungeon map incomplete",
        "strict topology rejection should report map incompleteness")
    assertTrue(hasValue(invalidDetail.missing, "shortcut_paths"),
        "strict topology rejection should report missing shortcuts")
    assertTrue(hasValue(invalidDetail.missing, "choke_points"),
        "strict topology rejection should report missing choke points")
    assertTrue(not hasValue(invalidDetail.missing, "feedback_loops"),
        "strict topology rejection should not reject an authored feedback loop")

    invalid, reason, invalidDetail = underworld_creation.validateDungeonMap({
        levelNumber = 1,
        rooms = {
            { id = "101_a" },
            { id = "102_b" },
            { id = "103_c" },
        },
        connections = {
            { from = "101_a", to = "102_b" },
            { from = "102_b", to = "103_c" },
            { from = "103_c", to = "101_a" },
        },
        playerMap = {
            rooms = {
                "101_a",
                "102_b",
            },
            blankSpaceForNotes = true,
        },
    }, {
        requireMapDrawingDetails = true,
    })
    assertTrue(not invalid, "strict map drawing should reject missing area and pathway drawing details")
    assertEqual(reason, "Dungeon map incomplete",
        "strict drawing rejection should report map incompleteness")
    assertTrue(hasValue(invalidDetail.missing, "area_shapes"),
        "strict drawing rejection should report missing area shapes")
    assertTrue(hasValue(invalidDetail.missing, "pathway_types"),
        "strict drawing rejection should report missing pathway types")
    assertTrue(hasValue(invalidDetail.missing, "area_spacing"),
        "strict drawing rejection should report missing spacing between areas")

    invalid, reason = underworld_creation.validateDungeonMap(nil)
    assertTrue(not invalid, "map checklist should reject missing map input")
    assertEqual(reason, "Dungeon map required", "missing map input should explain the required map")
end

function checkAppendixERoomFeatureTrapAuthoring()
    local underworld_creation = require('logic.underworld_creation')
    local prompt = underworld_creation.getRoomFeaturePrompt(10)
    assertEqual(prompt.name, "Machine", "Appendix E feature prompt X should be Machine")
    assertEqual(prompt.summary, "An ancient mechanism with unknown purpose, broken logic, or imperfect output.",
        "Appendix E feature prompts should expose rulebook authoring summaries")
    assertTrue(hasValue(prompt.exampleHooks, "missing part or power source"),
        "Appendix E feature prompts should expose example authoring hooks")
    assertEqual(underworld_creation.getRoomFeaturePrompt(21).name, "Well",
        "Appendix E feature prompt XXI should be Well")
    assertTrue(hasValue(underworld_creation.getRoomFeaturePrompt(21).exampleHooks, "resident or guardian"),
        "Appendix E well prompt should preserve resident or guardian guidance")
    assertEqual(underworld_creation.getRoomFeaturePrompt(0), nil,
        "Appendix E feature prompts should not use The Fool")
    local acidLakeTrap = underworld_creation.getTrapExample(1)
    assertEqual(acidLakeTrap.name, "Mysterious tower, acid lake",
        "Appendix E trap examples should expose named trap patterns")
    assertTrue(hasValue(acidLakeTrap.telegraphChannels, "sight"),
        "Appendix E trap examples should expose sensory telegraph channels")
    assertTrue(hasValue(acidLakeTrap.solutions, "cross with magic such as Gust of Wind or Defy Depths"),
        "Appendix E trap examples should expose solution prompts")
    local mushroomTrap = underworld_creation.getTrapExample({
        index = 9,
    })
    assertEqual(mushroomTrap.id, "pyrotechnic_mushrooms",
        "Appendix E trap examples should accept structured example references")
    assertTrue(hasValue(mushroomTrap.consequences, "active flames trigger an explosion"),
        "Appendix E trap examples should expose consequence prompts")
    mushroomTrap.solutions[1] = "ignore the rulebook"
    assertEqual(underworld_creation.getTrapExample(9).solutions[1], "extinguish flames before passing",
        "Appendix E trap examples should return copy-safe records")
    assertEqual(underworld_creation.getTrapExample(10), nil,
        "Appendix E trap examples should reject out-of-range examples")
    local tutorial = underworld_creation.getTutorialDungeonExample()
    assertEqual(tutorial.name, "The Tomb of Golden Ghosts",
        "Appendix E tutorial dungeon helper should expose the named example")
    assertTrue(hasValue(tutorial.scope.focusedSteps, "create_maps"),
        "Appendix E tutorial dungeon helper should preserve the focused creation steps")
    assertEqual(tutorial.scope.tutorialQuest, "Find the Tripartite's crown",
        "Appendix E tutorial dungeon helper should preserve the tutorial quest framing")
    assertTrue(hasValue(tutorial.mapPlan.playerMapOmissions, "secret doors"),
        "Appendix E tutorial dungeon helper should preserve GM/player map differences")
    assertEqual(tutorial.roomDefaults.structure, "natural limestone caverns unless otherwise noted",
        "Appendix E tutorial dungeon helper should preserve room default descriptions")
    assertTrue(hasValue(tutorial.brainstorm.supportingElements, "Book Worm, a sentient centipede who speaks Vetus"),
        "Appendix E tutorial dungeon helper should preserve brainstorming results")
    assertTrue(hasValue(tutorial.checklistReasons.flee,
        "unappeased freed golden ghosts are treated as a natural disaster, not fair enemies"),
        "Appendix E tutorial dungeon helper should preserve checklist reason coverage")
    assertTrue(hasValue(tutorial.meatgrinderProcess.randomEncounters,
        "puppet-mummies controlled by Kodi from behind an illusory wall"),
        "Appendix E tutorial dungeon helper should preserve Meatgrinder design process")
    assertTrue(hasValue(tutorial.meatgrinderProcess.commentary,
        "good solutions simply work while risky solutions call for tests and consequences"),
        "Appendix E tutorial dungeon helper should expose designer commentary")
    assertTrue(hasValue(tutorial.statPlan.tombChoices,
        "dire centipedes combine the beast theme with the minion threat"),
        "Appendix E tutorial dungeon helper should preserve stat-writing choices")
    tutorial.mapPlan.roomKeyPattern = "2xx"
    assertEqual(underworld_creation.getTutorialDungeonExample("Tomb").mapPlan.roomKeyPattern, "1xx",
        "Appendix E tutorial dungeon helper should return copy-safe records")
    assertEqual(underworld_creation.getTutorialDungeonExample("not the tomb"), nil,
        "Appendix E tutorial dungeon helper should reject unknown examples")

    local ok, result, detail = underworld_creation.validateRoomFeatureAuthoring({
        id = "104_world_machine",
        features = {
            {
                id = "unmaking_machine",
                name = "Unmaking Machine",
                promptValue = 10,
                description = "A cube-shaped machine with two square apertures.",
                interactions = {
                    "insert missing cube",
                    "place an item in the upper aperture",
                },
                stateChange = {
                    repaired = "The machine disassembles items into component materials.",
                },
                clue = "A six-inch cube is missing from the left side.",
            },
            {
                id = "owl_throne",
                name = "Owl Throne",
                promptValue = 4,
                description = "A colossal throne whose arms depict closed eyes.",
                risk = "Sitting with a light source can Blind the sitter.",
                reward = "A patient sitter hears a distant dungeon rumor.",
                interactions = {
                    "sit",
                    "listen",
                },
            },
        },
        traps = {
            {
                id = "arrow_plate",
                name = "Arrow trap",
                description = "A ten-foot hallway stretch with wall holes and a pressure plate.",
                guards = "the treasure room beyond",
                sensoryClues = {
                    sight = "small holes dot both walls",
                    sound = "the floor plate clicks under weight",
                },
                trigger = "stepping on the pressure plate",
                consequence = "arrows fire; failure to react deals a Wound",
                solutions = {
                    "drop flat or leap back when the click sounds",
                    "throw something heavy onto the plate",
                    "plug the holes with alchemical glue",
                },
            },
        },
        treasures = {
            {
                id = "aurumius_death_mask",
                name = "Aurumius Death Mask",
                description = "A gold death mask with tears hammered into the cheeks.",
                form = "personalized funerary jewelry",
                value = 50,
                provenance = "The mask depicts an Aurumius prince betrayed during the first tomb breach.",
                guardedBy = "arrow_plate",
                pricingNote = "A City collector will pay 50g if the ghost claim is ignored.",
            },
        },
        denizens = {
            {
                id = "kodi_dove_devourer",
                name = "Kodi Dove-devourer",
                roomId = "104_world_machine",
                blueprintId = "kodi_dove_devourer",
                wants = {
                    "to cover the Underworld in his net",
                },
                likes = {
                    "goats",
                    "drugs",
                    "banjo music",
                },
                dislikes = {
                    "goblins",
                    "being looked down on",
                },
                tactics = {
                    "use Tactics to Avoid or Move as an interrupt action",
                },
                disposition = "greedy but not particularly competent",
            },
        },
    }, {
        strictPrompt = true,
        requireFeaturePlacement = true,
        requireTrapPlacement = true,
        requireTrapSensoryTelegraphs = true,
        requireTreasurePlacement = true,
    })
    assertTrue(ok, "room feature authoring should accept interactive Appendix E features and traps")
    assertEqual(result, "room_feature_authoring_valid",
        "room feature authoring should report validation")
    assertEqual(detail.counts.features, 2, "room feature authoring should preserve valid features")
    assertEqual(detail.features[1].location, "104_world_machine",
        "room feature authoring should preserve feature room placement")
    assertEqual(detail.features[1].prompt.name, "Machine",
        "room feature authoring should attach the selected Appendix E prompt")
    assertTrue(hasValue(detail.features[1].prompt.exampleHooks, "component output"),
        "room feature authoring should attach the selected prompt's example hooks")
    assertTrue(hasValue(detail.features[1].hooks, "state_change"),
        "room feature authoring should detect state-change hooks")
    assertTrue(hasValue(detail.features[2].hooks, "reward") and hasValue(detail.features[2].hooks, "risk"),
        "room feature authoring should detect reward and risk hooks")
    assertEqual(detail.counts.traps, 1, "room feature authoring should preserve valid traps")
    assertEqual(detail.traps[1].location, "104_world_machine",
        "trap authoring should preserve room placement from the room key")
    assertEqual(detail.traps[1].guarded, "the treasure room beyond",
        "trap authoring should preserve the guarded reward")
    assertTrue(hasValue(detail.traps[1].telegraphs, "small holes dot both walls"),
        "trap authoring should preserve sensory telegraphs")
    assertTrue(hasValue(detail.traps[1].sensoryChannels, "sight") and
        hasValue(detail.traps[1].sensoryChannels, "sound"),
        "trap authoring should preserve typed sensory telegraph channels")
    assertEqual(detail.traps[1].solutions[3], "plug the holes with alchemical glue",
        "trap authoring should preserve non-talent disarm options")
    assertEqual(detail.counts.treasures, 1, "room feature authoring should preserve authored treasures")
    assertEqual(detail.treasures[1].location, "104_world_machine",
        "treasure authoring should preserve room placement from the room key")
    assertEqual(detail.treasures[1].value, 50, "treasure authoring should preserve guessed sale value")
    assertEqual(detail.treasures[1].lore[1],
        "The mask depicts an Aurumius prince betrayed during the first tomb breach.",
        "treasure authoring should preserve lore and provenance")
    assertEqual(detail.treasures[1].guardedBy[1], "arrow_plate",
        "treasure authoring should preserve the guarding trap or gate")
    assertEqual(detail.counts.denizens, 1, "room feature authoring should preserve permanent denizens")
    assertEqual(detail.denizens[1].statReference, "kodi_dove_devourer",
        "denizen authoring should preserve stat block references")
    assertEqual(detail.denizens[1].motivations[1], "to cover the Underworld in his net",
        "denizen authoring should preserve motivations")
    assertEqual(detail.denizens[1].tactics[1], "use Tactics to Avoid or Move as an interrupt action",
        "denizen authoring should preserve tactics")
    assertEqual(detail.denizens[1].likes[1], "goats",
        "denizen authoring should preserve likes")

    ok, result, detail = underworld_creation.validateTreasure({
        id = "tripartite_crown",
        name = "Tripartite Crown",
        description = "A thorn-antlered silver crown made for the Aurumius dynasty.",
        form = "ancestral silver regalia",
        valueNote = "Priced by GM judgment; 100g luxurious upkeep makes this feel like a major haul.",
        history = "The crown grounds the tomb quest in the dynasty's broken succession.",
        guardedBy = "six-eye aging statue",
    }, {
        requireTreasureLore = true,
        requireTreasureValue = true,
        requireGuardedTreasure = true,
        requireInterestingTreasure = true,
    })
    assertTrue(ok, "strict treasure authoring should accept priced, guarded, lore-bearing treasure")
    assertEqual(result, "treasure_valid", "treasure authoring should report validation")
    assertTrue(detail.interestingAuthored,
        "treasure authoring should recognize non-coin treasure forms")

    ok, result, detail = underworld_creation.validateDenizen({
        id = "glaura_glossolalia",
        name = "Glaura Glossolalia",
        roomId = "116_star_child",
        statBlockId = "glaura_glossolalia",
        motivation = "ascend into godhood by placing the star-child into one of her eggs",
        likes = {
            "crude jokes",
            "ribald songs",
        },
        dislikes = {
            "Mythric priests",
        },
        tactics = {
            "rush to Kodi's aid at any sound of commotion",
        },
    }, {
        requireDenizenStatBlock = true,
        requireDenizenMotivation = true,
        requireDenizenTactics = true,
        requireDenizenSocialPreferences = true,
    })
    assertTrue(ok, "strict denizen authoring should accept placed statted denizens")
    assertEqual(result, "denizen_valid", "denizen authoring should report validation")
    assertEqual(detail.dislikes[1], "Mythric priests",
        "denizen authoring should preserve dislikes")

    ok, result, detail = underworld_creation.validateTrap({
        id = "rolling_boulder",
        name = "Rolling boulder",
        description = "A devil statue holds a boulder behind a sarcophagus.",
        guards = "Jarl Ninebones's grave goods",
        telegraph = "The statue is posed like a bowler about to throw.",
        trigger = "opening the sarcophagus",
        consequence = "the boulder rolls down the hall for Critical damage",
        solutions = {
            "jump into the sarcophagus",
            "raise a Wall of Elements to block the boulder",
        },
        testFateRequired = true,
    })
    assertTrue(ok, "trap authoring should allow tests only after safe handling fails")
    assertEqual(result, "trap_valid", "trap authoring should validate a complete trap")
    assertEqual(detail.warnings[1], "test_fate_should_follow_failed_safe_handling",
        "trap authoring should warn when tests of fate are part of trap resolution")

    local invalid, reason, invalidDetail = underworld_creation.validateTrap({
        id = "flat_plate",
        name = "Flat pressure plate",
        description = "A pressure plate is somewhere in the hall.",
        guards = "a jewel",
        telegraph = "The hallway feels suspicious.",
        trigger = "stepping on the plate",
        consequence = "spears fire from the wall",
        solutions = {
            "throw a heavy pack onto the plate",
        },
    }, {
        requireTrapSensoryTelegraphs = true,
    })
    assertTrue(not invalid, "strict trap authoring should reject untyped sensory clues")
    assertEqual(reason, "Trap incomplete",
        "strict sensory trap rejection should report trap incompleteness")
    assertTrue(hasValue(invalidDetail.missing, "sensory_telegraph_channels"),
        "strict trap authoring should require typed sensory telegraph channels")

    invalid, reason, invalidDetail = underworld_creation.validateRoomFeature({
        id = "blank_statue",
        name = "Blank Statue",
        description = "A statue with no authored interaction.",
    }, {
        strictPrompt = true,
        requireFeaturePlacement = true,
    })
    assertTrue(not invalid, "feature authoring should reject inert features in strict prompt mode")
    assertEqual(reason, "Room feature incomplete",
        "inert feature rejection should explain incomplete feature authoring")
    assertTrue(hasValue(invalidDetail.missing, "appendix_e_feature_prompt"),
        "feature authoring should require an Appendix E prompt when strict")
    assertTrue(hasValue(invalidDetail.missing, "interactive_hook"),
        "feature authoring should require an interaction, clue, reward, risk, or state change")
    assertTrue(hasValue(invalidDetail.missing, "feature_room_placement"),
        "feature authoring should require map placement when strict")

    invalid, reason, invalidDetail = underworld_creation.validateTreasure({
        description = "1260 loose gold coins",
        type = "coins",
        gold = 1260,
    }, {
        requireTreasureLore = true,
        requireGuardedTreasure = true,
        requireInterestingTreasure = true,
        requireTreasurePlacement = true,
    })
    assertTrue(not invalid, "strict treasure authoring should reject coin-only treasure without lore or guarding")
    assertEqual(reason, "Treasure incomplete", "incomplete treasure rejection should explain the problem")
    assertTrue(hasValue(invalidDetail.missing, "treasure_lore_or_provenance"),
        "treasure authoring should require lore or provenance when strict")
    assertTrue(hasValue(invalidDetail.missing, "treasure_guard_or_gate"),
        "treasure authoring should require guarded or gated placement when strict")
    assertTrue(hasValue(invalidDetail.missing, "interesting_non_coin_treasure"),
        "treasure authoring should require interesting non-coin detail when strict")
    assertTrue(hasValue(invalidDetail.missing, "treasure_room_placement"),
        "treasure authoring should require map placement when strict")
    assertTrue(invalidDetail.warningFlags.treasure_coin_only,
        "coin-only treasure should be flagged for GM authoring review")

    invalid, reason, invalidDetail = underworld_creation.validateDenizen({
        name = "Nameless watcher",
        roomId = "105_watch_post",
    }, {
        requireDenizenStatBlock = true,
        requireDenizenMotivation = true,
        requireDenizenTactics = true,
        requireDenizenSocialPreferences = true,
    })
    assertTrue(not invalid, "strict denizen authoring should reject inert denizens")
    assertEqual(reason, "Denizen incomplete", "incomplete denizen rejection should explain the problem")
    assertTrue(hasValue(invalidDetail.missing, "denizen_stat_block"),
        "denizen authoring should require stat references when strict")
    assertTrue(hasValue(invalidDetail.missing, "denizen_motivation"),
        "denizen authoring should require motivations when strict")
    assertTrue(hasValue(invalidDetail.missing, "denizen_tactics"),
        "denizen authoring should require tactics when strict")
    assertTrue(hasValue(invalidDetail.missing, "denizen_likes_or_dislikes"),
        "denizen authoring should require social preferences when strict")

    invalid, reason, invalidDetail = underworld_creation.validateTrap({
        id = "locked_trap",
        name = "Locked trap",
        description = "Only a master thief can find the tiny wire.",
        guards = "a jewel",
        telegraph = "a faint wire glints in the torchlight",
        trigger = "opening the box",
        consequence = "poison needles fire",
        solutions = {
            "pick the lock",
        },
        requiredTalent = "master_thief",
    }, {
        requireTrapPlacement = true,
    })
    assertTrue(not invalid, "trap authoring should reject special-talent gates")
    assertEqual(reason, "Trap incomplete", "talent-gated trap rejection should explain the trap problem")
    assertTrue(hasValue(invalidDetail.missing, "no_special_talent_gate"),
        "trap authoring should preserve the rulebook no-special-talent trap principle")
    assertTrue(hasValue(invalidDetail.missing, "trap_room_placement"),
        "trap authoring should require map placement when strict")

    invalid, reason, invalidDetail = underworld_creation.validateRoomFeatureAuthoring({
        id = "empty_room",
        features = {},
    })
    assertTrue(not invalid, "room feature authoring should reject rooms with no feature by default")
    assertEqual(reason, "Room feature required",
        "missing room feature rejection should explain the required feature")
    assertTrue(hasValue(invalidDetail.missing, "room_feature"),
        "missing room feature detail should preserve the missing checklist item")
end

function checkAppendixEUnderworldDraftChecklist()
    local underworld_creation = require('logic.underworld_creation')
    local draft = {
        origins = {
            truth = "The Underworld is a stolen heaven beneath the City.",
            originalPurpose = "Guide the dead through rebirth.",
