        },
        rooms = {
            {
                id = "101_gate",
                description = "A circle of cold starlight marks the first gate.",
                reasons = {
                    "explore",
                    "surprise",
                },
                features = {
                    {
                        id = "star_circle",
                        name = "Star Circle",
                        promptValue = 1,
                        description = "A circle of power burns with stolen constellations.",
                        clue = "The constellations are one season ahead of the sky above.",
                        interactions = {
                            "align the missing star",
                        },
                    },
                },
            },
            {
                id = "102_market",
                description = "A ghost merchant weighs silver against forgotten names.",
                reasonToTalk = "The merchant remembers old entrance passwords.",
                reasonToFight = "Its guards attack name thieves.",
                features = {
                    {
                        id = "name_merchant",
                        name = "Name Merchant",
                        promptValue = 9,
                        description = "A merchant sells memories from a velvet ledger.",
                        reward = "A bought name opens a sealed stair.",
                        interactions = {
                            "trade a rumor",
                            "buy a name",
                        },
                    },
                },
            },
            {
                id = "103_statue",
                description = "A statue aims a stone bow at a treasure alcove.",
                checklist = {
                    flee = "The bow cracks when the treasure is touched.",
                    experiment = "The statue turns if its plinth is rotated.",
                },
                features = {
                    {
                        id = "bow_statue",
                        name = "Bow Statue",
                        promptValue = 15,
                        description = "A crowned statue tracks footsteps with stone eyes.",
                        risk = "Its bow fires on anyone who rushes the alcove.",
                        interactions = {
                            "rotate the plinth",
                            "cover the eyes",
                        },
                    },
                },
                traps = {
                    {
                        id = "statue_arrow",
                        name = "Statue arrow trap",
                        description = "The bowstring tightens when the alcove floor sinks.",
                        guards = "a silver death mask",
                        telegraph = "Grooves in the floor point back to the statue.",
                        trigger = "lifting the death mask",
                        consequence = "a stone arrow punches through the alcove",
                        solutions = {
                            "wedge the alcove floor",
                            "rotate the statue away",
                        },
                    },
                },
            },
            {
                id = "104_hearth",
                description = "A low hearth burns without fuel beside chalk bedroll marks.",
                reasonToBreatheEasy = "The fire keeps hunting ghosts outside the threshold.",
                reasonToReturn = "The ashes reveal different maps after each deeper level is found.",
                features = {
                    {
                        id = "memory_hearth",
                        name = "Memory Hearth",
                        promptValue = 8,
                        description = "The hearth shows warm rooms that no longer exist.",
                        reward = "Resting here reveals one safe route back to the entrance.",
                        stateChange = {
                            after_deeper_level = "The ash map redraws itself.",
