        },
        meatgrinder = {
            hunger = "The torchlight gutters and every ration smells of grave wax.",
            curiosities = {
                "A harmless crown rolls uphill.",
                "Cold bells ring from behind the wall.",
                "A ghost drops a shopping list for impossible fruit.",
                "Old chalk points toward a sealed stair.",
                "A velvet mask whispers the wrong name.",
            },
            travelEvents = {
                "A stair folds back on itself.",
                "The floor tilts toward a river of ash.",
                "A pack strap breaks on a hungry nail.",
                "False walls hide every exit but the last one used.",
                "A webbed arch must be cut or burned away.",
            },
            randomEncounters = {
                "A polite ghost tax collector.",
                "Centipedes wearing saint masks.",
                "A rival guild with one lantern left.",
                "A lost pilgrim who remembers tomorrow.",
                "A hungry angel chained to a cart.",
            },
            questRumor = "The deepest stair opens only for the name that was first stolen.",
        },
    }

    local ok, result, detail = underworld_creation.validateUnderworldDraft(draft)
    assertTrue(ok, "Underworld draft checklist should accept a complete Appendix E draft")
    assertEqual(result, "underworld_draft_valid", "complete Underworld drafts should report validation")
    assertTrue(detail.readyForAuthoringUI, "complete Underworld draft should be ready for UI authoring flow")
    assertTrue(detail.readyForPlay, "complete Underworld draft should be ready for play")
    assertEqual(detail.stepsByKey.origins.status, "complete", "origins step should be complete")
    assertEqual(detail.stepsByKey.generate_layout.status, "complete", "layout step should be complete")
    assertEqual(detail.stepsByKey.create_maps.status, "complete", "map step should be complete")
    assertEqual(detail.stepsByKey.write_room_descriptions.status, "complete",
        "room-description step should include feature and trap authoring")
    assertEqual(detail.stepsByKey.write_room_descriptions.detail.factions.count, 2,
        "room-description step should include Appendix E faction wants and don't-wants")
    assertEqual(detail.stepsByKey.create_meatgrinder.status, "complete",
        "Meatgrinder step should be complete")
    assertEqual(detail.counts.levels, 3, "draft checklist should report generated Underworld levels")
    assertEqual(detail.counts.maps, 1, "draft checklist should report checked dungeon maps")
    assertEqual(detail.counts.rooms, 4, "draft checklist should report checked room descriptions")
    assertEqual(detail.counts.factions, 2, "draft checklist should report checked faction authoring")
    assertEqual(detail.counts.meatgrinders, 1, "draft checklist should report checked Meatgrinder tables")

    ok, result, detail = underworld_creation.validateUnderworldDraft(draft, {
        roomDescriptionOptions = {
            requireLevelDefaults = true,
            defaultLighting = "cold starlight and guild torches",
            defaultSensory = {
                smell = "grave wax",
                sound = "distant tax bells",
            },
        },
    })
    assertTrue(ok, "Underworld draft checklist should accept shared room lighting and sensory defaults")
    assertEqual(result, "underworld_draft_valid",
        "drafts with complete level defaults should still report validation")
    assertEqual(#detail.stepsByKey.write_room_descriptions.detail.descriptions.levelDefaults.missingLightingRooms, 0,
        "draft checklist should expose complete lighting defaults through room authoring details")
    assertEqual(#detail.stepsByKey.write_room_descriptions.detail.descriptions.levelDefaults.missingSensoryRooms, 0,
        "draft checklist should expose complete sensory defaults through room authoring details")

    local defaultsInvalid, defaultsReason, defaultsDetail = underworld_creation.validateUnderworldDraft(draft, {
        roomDescriptionOptions = {
            requireLevelDefaults = true,
        },
    })
    assertTrue(not defaultsInvalid,
        "Underworld draft checklist should reject missing level defaults when strict room options require them")
    assertEqual(defaultsReason, "Underworld draft incomplete",
        "missing level defaults should block the combined draft checklist")
    assertEqual(defaultsDetail.stepsByKey.write_room_descriptions.status, "blocked",
        "missing level defaults should block the room-description step")
    assertTrue(hasValue(defaultsDetail.stepsByKey.write_room_descriptions.detail.descriptions.missing,
        "level_lighting_defaults"),
        "draft checklist should expose missing level lighting defaults")
    assertTrue(hasValue(defaultsDetail.stepsByKey.write_room_descriptions.detail.descriptions.missing,
        "level_sensory_defaults"),
        "draft checklist should expose missing level sensory defaults")

    local checklist, checklistResult = underworld_creation.createAuthoringChecklist(draft)
    assertEqual(checklistResult, "underworld_authoring_checklist_ready",
        "authoring checklist wrapper should report a ready draft")
    assertTrue(checklist.valid, "authoring checklist wrapper should preserve draft validity")
    assertEqual(checklist.stepsByKey.write_room_descriptions.detail.featureAuthoring.count, 4,
        "authoring checklist should expose room feature coverage for UI panels")

    local invalid, reason, invalidDetail = underworld_creation.validateUnderworldDraft({
        cards = { 1, 2 },
        maps = {
            {
                levelNumber = 1,
                rooms = {
                    { id = "101_a" },
                    { id = "102_b" },
                },
                connections = {
                    { from = "101_a", to = "102_b" },
                },
                playerMap = {
                    rooms = {
                        "101_a",
                    },
                    blankSpaceForNotes = true,
                },
            },
        },
        rooms = {
            {
                id = "101_a",
                description = "A room with no player-facing reason to care.",
            },
        },
        meatgrinder = {
            hunger = "The torches gutter.",
            curiosities = {
                "Curiosity one.",
                "Curiosity two.",
                "Curiosity three.",
                "Curiosity four.",
                "Curiosity five.",
            },
            travelEvents = {
                "Travel one.",
                "Travel two.",
                "Travel three.",
                "Travel four.",
                "Travel five.",
            },
            randomEncounters = {
                "Encounter one.",
            },
            questRumor = "Quest clue.",
        },
    })
    assertTrue(not invalid, "Underworld draft checklist should reject incomplete authoring")
    assertEqual(reason, "Underworld draft incomplete",
        "incomplete Underworld drafts should report checklist failure")
    assertEqual(invalidDetail.stepsByKey.origins.reason, "Underworld truth required",
        "draft checklist should expose the missing origins prompt")
    assertEqual(invalidDetail.stepsByKey.generate_layout.reason, "At least three dungeons required",
        "draft checklist should expose layout generation blockers")
    assertEqual(invalidDetail.stepsByKey.create_maps.reason, "Dungeon maps incomplete",
        "draft checklist should expose map authoring blockers")
    assertEqual(invalidDetail.stepsByKey.write_room_descriptions.detail.descriptionReason,
        "Room descriptions incomplete",
        "draft checklist should expose room description blockers")
    assertEqual(invalidDetail.stepsByKey.write_room_descriptions.detail.featureReason,
        "Room feature authoring incomplete",
        "draft checklist should expose room feature blockers")
    assertEqual(invalidDetail.stepsByKey.create_meatgrinder.reason, "Meatgrinder tables incomplete",
        "draft checklist should expose Meatgrinder blockers")
    assertTrue(not invalidDetail.readyForAuthoringUI,
        "missing origins and layout should keep authoring flow gated")
    assertTrue(not invalidDetail.readyForPlay,
        "incomplete Underworld draft should not be ready for play")
end

local function checkOmphalicMarketCatalog()
    local expected = {
        animal_feed = "impoverished",
        bedroll = "impoverished",
        candles = "impoverished",
        chalk = "impoverished",
        clothes_rags = "impoverished",
        firewood = "impoverished",
