    assertTrue(ok, "City Phase should allow approved motif changes")
    assertEqual(result, "motif_changed", "approved City motif changes should report completion")
    assertEqual(motifChanger.motifs[1], "Jinxed Smith",
        "descriptor-only City motif changes should preserve the old profession")
