    local communionDeck = {
        draw_pile = { communionDeckBottom, communionDeckTop },
        discard_pile = { communionDiscardBottom, communionDiscardTop },
        draw = function(self)
            return table.remove(self.draw_pile)
        end,
        drawDiscard = function(self)
            return table.remove(self.discard_pile)
        end,
    }
    local communionHand = player_hand.createPlayerHand({
        eventBus = events.createEventBus(),
        playerDeck = communionDeck,
        guild = { communicant },
    })
    communionHand:drawHand(communicant)
    local communionCards = communionHand:getHand(communicant)
    assertEqual(communionCards[1], communionDiscardTop,
        "Strange communions should draw selected Challenge cards from the top minor discard")
    assertEqual(communionCards[2], communionDeckTop,
        "Strange communions should still allow top-of-deck Challenge draws")
    assertEqual(communionCards[3], communionDiscardBottom,
        "Strange communions should allow a deck/discard source combination")
    assertEqual(communionCards[4], communionDeckBottom,
        "Strange communions should preserve the selected draw source order")
    assertTrue(communicant.nextExpeditionChallengeDrawChoice == nil,
        "Strange communions Challenge draw choice should be consumed after one use")

