local function checkCityPhaseUpkeepTiers()
    local poor = base_entity.createEntity({
        id = "pc_city_poor_upkeep",
        name = "City Poor Upkeep",
        isPC = true,
    })
    poor.gold = 24
    poor.inventory = inventory.createInventory()

    local common = base_entity.createEntity({
        id = "pc_city_common_upkeep",
        name = "City Common Upkeep",
        isPC = true,
    })
    common.gold = 50
    common.inventory = inventory.createInventory()
    common.conditions.injured = true

    local luxurious = base_entity.createEntity({
        id = "pc_city_luxurious_upkeep",
        name = "City Luxurious Upkeep",
        isPC = true,
        talents = {
            path_lore = { mastered = true, wounded = true },
        },
    })
    luxurious.gold = 100
    luxurious.inventory = inventory.createInventory()
    luxurious.armorNotches = 2
    luxurious.woundedTalents = 1
    luxurious.conditions.staggered = true
    luxurious.conditions.injured = true
    luxurious.conditions.deaths_door = true
    luxurious.resolve = { current = 1, max = 5 }

    local bus = events.createEventBus()
    local emitted = {}
    bus:on(events.EVENTS.CITY_UPKEEP_RESOLVED, function(data)
        emitted[#emitted + 1] = data
    end)

    local controller = city_phase.createCityPhaseController({
        eventBus = bus,
        guild = { poor, common, luxurious },
    })

    local upkeepOptions = controller:getUpkeepOptions(poor, { tier = "impoverished" })
    assertEqual(upkeepOptions.step, city_phase.STEPS.UPKEEP, "Upkeep options should identify the City Phase step")
    assertEqual(upkeepOptions.gold, 24, "Upkeep options should expose current liquid gold")
    assertEqual(upkeepOptions.selectedTier.cost, 25, "Upkeep options should preview selected tier cost")
    assertEqual(upkeepOptions.selectedTier.refillTier, "impoverished",
        "Upkeep options should expose the selected refill tier")
    assertTrue(upkeepOptions.disabled, "unaffordable Upkeep options should disable resolution")
    assertEqual(upkeepOptions.unavailableReason, "Not enough gold",
        "unaffordable Upkeep options should explain the cost gate")
    assertEqual(upkeepOptions.tierOptions[1].id, "destitute", "Upkeep options should list destitute first")
    assertEqual(upkeepOptions.tierOptions[1].consequencePreview.nextCrawlCondition, "stressed",
        "Upkeep options should preview destitute next-Crawl stress")
    upkeepOptions = controller:getUpkeepOptions(poor, { tier = "destitute" })
    assertTrue(not upkeepOptions.disabled, "destitute Upkeep options should be available without gold")
    assertEqual(upkeepOptions.projectedGold, 24, "destitute Upkeep options should not spend preview gold")

    local ok, result = controller:resolveUpkeep(poor, { tier = "impoverished" })
    assertTrue(not ok, "Upkeep should require the selected tier cost")
    assertEqual(result, "Not enough gold", "failed upkeep should explain insufficient funds")
    assertTrue(not controller:hasUpkeep(poor), "failed upkeep should not mark actor upkeep complete")

    ok, result = controller:resolveUpkeep(poor, { tier = "destitute" })
    assertTrue(ok, "destitute upkeep should cost nothing")
    assertEqual(result, "upkeep_resolved", "destitute upkeep should report completion")
    assertEqual(poor.gold, 24, "destitute upkeep should not spend gold")
    assertEqual(poor.cityUpkeep.tier, "destitute", "destitute upkeep should record the selected tier")
    assertTrue(poor.cityUpkeep.refillTier == nil, "destitute upkeep should not refill the pack")
    assertTrue(poor.conditions.stressed, "destitute upkeep should immediately mark the adventurer Stressed")
    assertTrue(poor.nextCrawlConditions and poor.nextCrawlConditions.stressed,
        "destitute upkeep should queue Stressed for the next Crawl")
    assertEqual(poor.cityUpkeep.consequences[1].source, "destitute_upkeep",
        "destitute upkeep detail should report the stress consequence")
    assertEqual(poor.cityUpkeep.consequences[1].nextCrawlCondition, "stressed",
        "destitute upkeep detail should report the next-Crawl condition")

    local detail
    local commonRefills = {
        { templateId = "ration", quantity = 3 },
        "torch",
        { templateId = "light_armor", location = inventory.LOCATIONS.BELT },
    }
    upkeepOptions = controller:getUpkeepOptions(common, {
        tier = "common",
        refillItems = commonRefills,
    })
    assertTrue(not upkeepOptions.disabled, "common Upkeep options should accept common-or-lower refills")
    assertEqual(#upkeepOptions.selectedRefillItems, 3,
        "Upkeep options should preview every selected refill item")
    assertEqual(upkeepOptions.selectedRefillItems[1].quantity, 3,
        "Upkeep options should preserve selected refill quantities")
    assertEqual(upkeepOptions.selectedRefillItems[3].location, inventory.LOCATIONS.BELT,
        "Upkeep options should preserve refill placement")
    assertTrue(upkeepOptions.recoveryPreview.recoveryAllowed,
        "common Upkeep options should preview Recovery-style bond burns")
    assertEqual(upkeepOptions.recoveryPreview.nextWoundResult, "injured_healed",
        "common Upkeep options should preview the next recoverable Wound")
    assertEqual(upkeepOptions.projectedGold, 0, "common Upkeep options should preview remaining gold")
    assertEqual(common.gold, 50, "Upkeep options should not spend gold during preview")
    ok, result, detail = controller:resolveUpkeep(common, {
        tier = "common",
        refillItems = commonRefills,
    })
    assertTrue(ok, "common upkeep should resolve with 50g")
    assertEqual(common.gold, 0, "common upkeep should spend 50g")
    assertEqual(detail.refillTier, "common", "common upkeep should allow common-or-lower gear refills")
    assertEqual(#detail.refilledGear, 3, "common upkeep should refill selected common-or-lower gear")
    assertEqual(detail.refilledGear[1].item.quantity, 3, "upkeep gear refill should preserve requested stack quantities")
    assertTrue(common.inventory:findItem(detail.refilledGear[1].item.id) ~= nil, "refilled ration stack should enter inventory")
    assertTrue(common.inventory:findItem(detail.refilledGear[2].item.id) ~= nil, "refilled torch should enter inventory")
    assertEqual(common.inventory:findItem(detail.refilledGear[3].item.id), detail.refilledGear[3].item,
        "refilled light armor should enter inventory")
    local _, armorLocation = common.inventory:findItem(detail.refilledGear[3].item.id)
    assertEqual(armorLocation, inventory.LOCATIONS.BELT, "refilled light armor should respect belt-slot placement")
    assertTrue(detail.recoveryAllowed, "common upkeep should allow Recovery-style bond burns")
    assertTrue(common.conditions.injured, "common upkeep should not automatically heal wounds")

    local customBuyer = base_entity.createEntity({
        id = "pc_city_custom_upkeep",
        name = "City Custom Upkeep",
        isPC = true,
    })
    customBuyer.gold = 50
    customBuyer.inventory = inventory.createInventory()
    local customController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { customBuyer },
    })
    ok, result, detail = customController:resolveUpkeep(customBuyer, {
        tier = "common",
        refillItems = {
            {
                id = "button_hook",
                name = "Button Hook",
                tier = "common",
                everyday = true,
                properties = { use = "dress tiny buttons" },
            },
        },
    })
    assertTrue(ok, "common upkeep should allow GM-approved custom everyday gear")
    assertEqual(detail.refilledGear[1].custom, true, "custom upkeep gear should be marked in detail")
    assertEqual(detail.refilledGear[1].tier, "common", "custom upkeep gear should preserve GM price tier")
    assertEqual(detail.refilledGear[1].item.name, "Button Hook", "custom upkeep gear should preserve item name")
    assertEqual(detail.refilledGear[1].item.properties.upkeepCustom, true,
        "custom upkeep gear should mark its source")
    assertTrue(customBuyer.inventory:findItem(detail.refilledGear[1].item.id) ~= nil,
        "custom upkeep gear should enter inventory")

    local luxuriousRefills = {
        { templateId = "steel_armor", location = inventory.LOCATIONS.BELT },
        "bezoar",
    }
    upkeepOptions = controller:getUpkeepOptions(luxurious, {
        tier = "luxurious",
        refillItems = luxuriousRefills,
    })
    assertTrue(not upkeepOptions.disabled, "luxurious Upkeep options should accept luxurious refills")
    assertEqual(upkeepOptions.selectedTier.refillTier, "luxurious",
        "luxurious Upkeep options should expose the full market refill tier")
    assertEqual(upkeepOptions.luxuriousHealingPreview.armorNotches, 2,
        "luxurious Upkeep options should preview healed armor notches")
    assertEqual(upkeepOptions.luxuriousHealingPreview.woundedTalents, 1,
        "luxurious Upkeep options should preview healed talent wounds")
    assertEqual(upkeepOptions.luxuriousHealingPreview.resolveRefreshed, 5,
        "luxurious Upkeep options should preview Resolve refresh")
    ok, result, detail = controller:resolveUpkeep(luxurious, {
        tier = "luxurious",
        refillItems = luxuriousRefills,
    })
    assertTrue(ok, "luxurious upkeep should resolve with 100g")
    assertEqual(luxurious.gold, 0, "luxurious upkeep should spend 100g")
    assertEqual(detail.refillTier, "luxurious", "luxurious upkeep should allow any market gear refill")
    assertEqual(#detail.refilledGear, 2, "luxurious upkeep should refill selected luxurious-or-lower gear")
    assertEqual(luxurious.armorNotches, 0, "luxurious upkeep should heal armor wound slots in the current wound model")
    assertEqual(luxurious.woundedTalents, 0, "luxurious upkeep should heal talent wounds")
    assertTrue(not luxurious.talents.path_lore.wounded, "luxurious upkeep should clear wounded talent flags")
