local function checkCityPhaseBegAndBuskAction()
    local busker = base_entity.createEntity({
        id = "pc_city_busker",
        name = "City Busker",
        isPC = true,
        wands = 3,
    })
    busker.gold = 1
    busker.inventory = inventory.createInventory()

    local foolBusker = base_entity.createEntity({
        id = "pc_city_fool_busker",
        name = "City Fool Busker",
        isPC = true,
        wands = 4,
    })
    foolBusker.gold = 0
    foolBusker.inventory = inventory.createInventory()

    local drawnCard = {
        name = "Seven of Cups",
        value = 7,
        suit = constants.SUITS.CUPS,
    }
    local discardedCard = nil
    local fakeDeck = {
        draw = function()
            return drawnCard
        end,
        discard = function(_, card)
            discardedCard = card
        end,
    }

    local bus = events.createEventBus()
    local resolved = {}
    bus:on(events.EVENTS.CITY_ACTION_RESOLVED, function(data)
        resolved[#resolved + 1] = data
    end)

    local controller = city_phase.createCityPhaseController({
        eventBus = bus,
        playerDeck = fakeDeck,
        guild = { busker, foolBusker },
    })

    local drawOptions = controller:getBegAndBuskOptions(busker)
    assertTrue(not drawOptions.disabled, "Beg and Busk options should enable an available minor-deck draw")
    assertTrue(drawOptions.autoDrawAvailable, "Beg and Busk options should report automatic draw availability")
    assertEqual(drawOptions.wands, 3, "Beg and Busk options should expose the actor's Wands bonus")
    assertEqual(drawOptions.formula, "card_value_plus_wands",
        "Beg and Busk options should expose the rulebook payout formula")

    local ok, result, detail = controller:resolveAction(busker, {
        type = "beg_and_busk",
    })
    assertTrue(ok, "Beg and Busk should resolve through the City Action facade")
    assertEqual(result, "beg_and_busk_resolved", "Beg and Busk should report its canonical action result")
    assertEqual(detail.gold, 10, "Beg and Busk should earn draw value plus Wands")
    assertEqual(busker.gold, 11, "Beg and Busk should add earned gold to the actor")
    assertEqual(discardedCard, drawnCard, "Beg and Busk should discard an automatically drawn card")
    assertTrue(controller:hasActed(busker), "Beg and Busk should consume a successful City Action")
    assertEqual(#resolved, 1, "Beg and Busk should emit a city action event")
    assertEqual(resolved[1].action, city_phase.ACTIONS.BEG_AND_BUSK, "Beg and Busk should emit normalized action id")

    local foolOptions = controller:getBegAndBuskOptions(foolBusker, {
        card = {
            name = "The Fool",
            value = 0,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
    })
    assertTrue(not foolOptions.disabled, "Beg and Busk options should accept The Fool as a minor-deck draw")
    assertEqual(foolOptions.projectedGold, 4,
        "Beg and Busk options should preview Fool payout as zero plus Wands")

    ok, result, detail = controller:resolveAction(foolBusker, {
        type = "beg",
        card = {
            name = "The Fool",
            value = 0,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
    })
    assertTrue(ok, "Beg and Busk should accept an explicitly drawn minor-deck card")
    assertEqual(detail.gold, 4, "Beg and Busk should treat the Fool's numerical value as zero plus Wands")
    assertEqual(foolBusker.gold, 4, "Beg and Busk should pay actor Wands on a zero-value draw")
    assertTrue(controller:canAdvance(), "Beg and Busk should count toward all actors taking City Actions")

    local majorBusker = base_entity.createEntity({
        id = "pc_city_major_busker",
        name = "City Major Busker",
        isPC = true,
        wands = 2,
    })
    majorBusker.gold = 0
    majorBusker.inventory = inventory.createInventory()
    local majorController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { majorBusker },
    })
    local majorOptions = majorController:getBegAndBuskOptions(majorBusker, {
        card = {
            name = "The Magician",
            value = 1,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
    })
    assertTrue(majorOptions.disabled, "Beg and Busk options should reject non-Fool major cards")
    assertEqual(majorOptions.unavailableReason, "Requires minor arcana draw",
        "Beg and Busk options should explain invalid major cards")
    ok, result = majorController:resolveAction(majorBusker, {
        type = "beg_and_busk",
        card = {
            name = "The Magician",
            value = 1,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
    })
    assertTrue(not ok, "Beg and Busk should reject non-Fool major cards")
    assertEqual(result, "Requires minor arcana draw", "major Beg and Busk draw should explain minor-deck requirement")
    assertEqual(majorBusker.gold, 0, "major Beg and Busk draw should not pay gold")
    assertTrue(not majorController:hasActed(majorBusker), "major Beg and Busk draw should not consume City Action")

    local noDeckBusker = base_entity.createEntity({
        id = "pc_city_no_deck_busker",
        name = "City No Deck Busker",
        isPC = true,
        wands = 2,
    })
    noDeckBusker.gold = 0
    noDeckBusker.inventory = inventory.createInventory()
    local noDeckController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { noDeckBusker },
    })
    local noDeckOptions = noDeckController:getBegAndBuskOptions(noDeckBusker)
    assertTrue(noDeckOptions.disabled, "Beg and Busk options should require either a deck or explicit draw")
    assertEqual(noDeckOptions.unavailableReason, "Requires minor arcana draw",
        "Beg and Busk options should explain missing draw source")
    ok, result = noDeckController:resolveAction(noDeckBusker, {
        type = "beg_and_busk",
    })
    assertTrue(not ok, "Beg and Busk should require a card draw")
    assertEqual(result, "Requires minor arcana draw", "missing Beg and Busk draw should explain failure")
    assertEqual(noDeckBusker.gold, 0, "failed Beg and Busk should not pay gold")
    assertTrue(not noDeckController:hasActed(noDeckBusker), "failed Beg and Busk should not consume the City Action")
end

local function checkCityPhaseBankingAction()
    local function findBankingItemOption(options, id)
        for _, option in ipairs(options or {}) do
            if option.id == id then
                return option
            end
        end
        return nil
    end

    local banker = base_entity.createEntity({
        id = "pc_city_banker",
        name = "City Banker",
        isPC = true,
    })
    banker.gold = 100
    banker.inventory = inventory.createInventory()
    local amulet = inventory.createItemFromTemplate("golden_amulet")
    banker.inventory:addItem(amulet, inventory.LOCATIONS.PACK)

    local bus = events.createEventBus()
    local resolved = nil
    bus:on(events.EVENTS.CITY_ACTION_RESOLVED, function(data)
        resolved = data
    end)

    local controller = city_phase.createCityPhaseController({
        eventBus = bus,
        guild = { banker },
    })

    local bankingOptions = controller:getBankingOptions(banker, {
        depositGold = 50,
        itemIds = { amulet.id },
    })
    assertTrue(not bankingOptions.disabled, "Banking option helper should enable valid deposits")
    assertEqual(bankingOptions.carriedGold, 100, "Banking option helper should expose carried gold")
    assertEqual(bankingOptions.bankedGold, 0, "Banking option helper should expose banked gold")
    assertEqual(bankingOptions.depositGold, 50, "Banking option helper should preserve selected deposit gold")
    assertEqual(bankingOptions.returnRate, city_phase.BANKING_RETURN_RATE,
        "Banking option helper should expose the fixed bank return rate")
    assertTrue(findBankingItemOption(bankingOptions.carriedItemOptions, amulet.id).selected,
        "Banking option helper should mark selected carried deposit items")

    local ok, result, detail = controller:resolveAction(banker, {
        type = "banking",
        depositGold = 50,
        itemIds = { amulet.id },
    })
    assertTrue(ok, "Banking should resolve through the City Action facade")
    assertEqual(result, "banking_complete", "Banking should report completion")
    assertEqual(banker.gold, 50, "Banking should remove deposited gold from carried liquid assets")
    assertEqual(detail.bankedGold, 50, "Banking should store deposited gold")
    assertEqual(#detail.itemsDeposited, 1, "Banking should store deposited items")
    assertTrue(banker.inventory:findItem(amulet.id) == nil, "Banked gear should leave carried inventory")
    assertEqual(banker.bank.items[1], amulet, "Banked gear should be held in safe bank storage")
    assertTrue(controller:hasActed(banker), "Banking should consume a successful City Action")
    assertTrue(resolved and resolved.action == city_phase.ACTIONS.BANKING, "Banking should emit city action details")

    ok, result, detail = controller:applyBankingReturns(banker)
    assertTrue(ok, "Banking returns should apply during a City Phase")
    assertEqual(result, "banking_returns_applied", "Banking returns should report application")
    assertEqual(detail[1].interest, 1, "Banking returns should add 2% rounded down")
    assertEqual(banker.bank.gold, 51, "Banking returns should increase banked gold")

    ok, result, detail = controller:applyBankingReturns(banker)
    assertTrue(ok, "Banking returns should tolerate duplicate calls")
    assertEqual(detail[1].interest, 0, "Banking returns should apply only once per controller phase")
    assertEqual(banker.bank.gold, 51, "duplicate Banking returns should not add more gold")

    local fixedReturn = base_entity.createEntity({
        id = "pc_city_fixed_return_banker",
        name = "City Fixed Return Banker",
        isPC = true,
    })
    fixedReturn.bank = { gold = 100, items = {} }
    local fixedReturnController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { fixedReturn },
    })
    ok, result, detail = fixedReturnController:applyBankingReturns(fixedReturn, { rate = 1 })
    assertTrue(ok, "Banking returns should resolve for a banked actor")
    assertEqual(detail[1].interest, 2, "Banking returns should ignore caller-provided rates")
    assertEqual(fixedReturn.bank.gold, 102, "Banking returns should use the rulebook 2% rate")

    local withdrawer = base_entity.createEntity({
        id = "pc_city_bank_withdrawer",
        name = "City Bank Withdrawer",
        isPC = true,
    })
    withdrawer.gold = 0
    withdrawer.inventory = inventory.createInventory()
    local bankedSword = inventory.createItem({
        id = "banked_sword",
        name = "Banked Sword",
        weaponType = "sword",
    })
    withdrawer.bank = {
        gold = 75,
        items = { bankedSword },
    }
    local withdrawController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { withdrawer },
    })
    local withdrawOptions = withdrawController:getBankingOptions(withdrawer, {
        operation = "withdraw",
        gold = 25,
        itemIds = { bankedSword.id },
    })
    assertTrue(not withdrawOptions.disabled, "Banking option helper should enable valid withdrawals")
    assertEqual(withdrawOptions.bankedGold, 75, "Banking option helper should expose withdrawable banked gold")
    assertEqual(withdrawOptions.projectedInterest, 1, "Banking option helper should preview 2% returns")
    assertTrue(findBankingItemOption(withdrawOptions.bankedItemOptions, bankedSword.id).selected,
        "Banking option helper should mark selected banked withdrawal items")
    ok, result, detail = withdrawController:resolveAction(withdrawer, {
        type = "banking",
        operation = "withdraw",
        gold = 25,
        itemIds = { bankedSword.id },
    })
    assertTrue(ok, "Banking should withdraw banked coin and gear through the City Action facade")
    assertEqual(result, "banking_complete", "Banking withdrawal should report completion")
    assertEqual(withdrawer.gold, 25, "Banking withdrawal should move banked gold to carried liquid assets")
    assertEqual(withdrawer.bank.gold, 50, "Banking withdrawal should reduce banked gold")
    assertEqual(#detail.itemsWithdrawn, 1, "Banking should report withdrawn gear")
    assertTrue(withdrawer.inventory:findItem(bankedSword.id) == bankedSword, "withdrawn gear should return to carried inventory")
    assertEqual(#withdrawer.bank.items, 0, "withdrawn gear should leave bank storage")
    assertTrue(withdrawController:hasActed(withdrawer), "successful Banking withdrawal should consume the City Action")

    local overdrawn = base_entity.createEntity({
        id = "pc_city_bank_overdrawn",
        name = "City Bank Overdrawn",
        isPC = true,
    })
    overdrawn.inventory = inventory.createInventory()
    overdrawn.bank = { gold = 5, items = {} }
    local overdrawnController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { overdrawn },
    })
    local overdrawnOptions = overdrawnController:getBankingOptions(overdrawn, {
        operation = "withdraw",
        gold = 6,
    })
    assertTrue(overdrawnOptions.disabled, "Banking option helper should disable overdrawn withdrawals")
    assertEqual(overdrawnOptions.unavailableReason, "Not enough banked gold",
        "Banking option helper should explain overdrawn withdrawals")
    ok, result = overdrawnController:resolveAction(overdrawn, {
        type = "banking",
        operation = "withdraw",
        gold = 6,
    })
    assertTrue(not ok, "Banking should require enough banked gold to withdraw")
    assertEqual(result, "Not enough banked gold", "insufficient banked gold should explain failure")
    assertEqual(overdrawn.bank.gold, 5, "failed withdrawal should not alter banked gold")
    assertTrue(not overdrawnController:hasActed(overdrawn), "failed withdrawal should not consume the City Action")

    local fullPack = base_entity.createEntity({
        id = "pc_city_full_pack_bank",
        name = "City Full Pack Bank",
        isPC = true,
    })
    fullPack.inventory = inventory.createInventory()
    for i = 1, 21 do
        fullPack.inventory:addItem(inventory.createItem({
            id = "pack_filler_" .. tostring(i),
            name = "Pack Filler " .. tostring(i),
        }), inventory.LOCATIONS.PACK)
    end
    local bankedGem = inventory.createItem({
        id = "banked_gem",
        name = "Banked Gem",
    })
    fullPack.bank = { gold = 0, items = { bankedGem } }
    local fullPackController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { fullPack },
    })
    local fullPackBankOptions = fullPackController:getBankingOptions(fullPack, {
        operation = "withdraw",
        itemIds = { bankedGem.id },
    })
    assertTrue(fullPackBankOptions.disabled,
        "Banking option helper should disable withdrawals that exceed inventory capacity")
    assertEqual(fullPackBankOptions.unavailableReason, "insufficient_slots",
        "Banking option helper should explain capacity-blocked withdrawals")
    ok, result = fullPackController:resolveAction(fullPack, {
        type = "banking",
        operation = "withdraw",
        itemIds = { bankedGem.id },
    })
    assertTrue(not ok, "Banking should preflight inventory capacity before withdrawing gear")
    assertEqual(result, "insufficient_slots", "full carried inventory should explain failed bank withdrawal")
    assertEqual(fullPack.bank.items[1], bankedGem, "failed withdrawal should leave gear in safe bank storage")
    assertTrue(not fullPackController:hasActed(fullPack), "failed bank item withdrawal should not consume the City Action")

    local poor = base_entity.createEntity({
        id = "pc_city_poor_banker",
        name = "City Poor Banker",
        isPC = true,
    })
    poor.gold = 10
    poor.inventory = inventory.createInventory()
    local poorController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { poor },
    })
    local poorBankOptions = poorController:getBankingOptions(poor, {
        depositGold = 11,
    })
    assertTrue(poorBankOptions.disabled, "Banking option helper should disable unaffordable deposits")
    assertEqual(poorBankOptions.unavailableReason, "Not enough gold",
        "Banking option helper should explain unaffordable deposits")
    ok, result = poorController:resolveAction(poor, {
        type = "bank",
        depositGold = 11,
    })
    assertTrue(not ok, "Banking should require enough gold to deposit")
    assertEqual(result, "Not enough gold", "insufficient Banking gold should explain failure")
    assertEqual(poor.gold, 10, "failed Banking should not spend gold")
    assertTrue(not poorController:hasActed(poor), "failed Banking should not consume City Action")

    local missingItem = base_entity.createEntity({
        id = "pc_city_missing_item_banker",
        name = "City Missing Item Banker",
        isPC = true,
    })
    missingItem.gold = 20
    missingItem.inventory = inventory.createInventory()
    local missingController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { missingItem },
    })
    ok, result = missingController:resolveAction(missingItem, {
        type = "banking",
        depositGold = 10,
        itemIds = { "not_carried" },
    })
    assertTrue(not ok, "Banking should preflight carried items")
    assertEqual(result, "Banking item not found", "missing Banking item should explain failure")
    assertEqual(missingItem.gold, 20, "failed Banking item preflight should not spend gold")
    assertTrue(not missingController:hasActed(missingItem), "failed Banking item preflight should not consume City Action")

    local empty = base_entity.createEntity({
        id = "pc_city_empty_banker",
        name = "City Empty Banker",
        isPC = true,
    })
    empty.gold = 20
    empty.inventory = inventory.createInventory()
    local emptyController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { empty },
    })
    local emptyBankOptions = emptyController:getBankingOptions(empty, {})
    assertTrue(emptyBankOptions.disabled, "Banking option helper should disable empty bank requests")
    assertEqual(emptyBankOptions.unavailableReason, "Nothing to bank",
        "Banking option helper should explain empty bank requests")
    ok, result = emptyController:resolveAction(empty, {
        type = "banking",
    })
    assertTrue(not ok, "Banking should require something to store")
    assertEqual(result, "Nothing to bank", "empty Banking should explain missing deposit")
    assertTrue(not emptyController:hasActed(empty), "empty Banking should not consume City Action")
end

local function checkCityPhaseBuildAction()
    local builder = base_entity.createEntity({
        id = "pc_city_builder",
        name = "City Builder",
        isPC = true,
    })
    builder.gold = 400
    builder.inventory = inventory.createInventory()

    local buildings = {}
    local cityLayout = {
        districts = {
            {
                districtId = "mason_square",
                district = {
                    id = "mason_square",
                    name = "Mason Square",
                },
            },
        },
        specialCityActions = {},
    }
    local bus = events.createEventBus()
    local resolved = nil
    bus:on(events.EVENTS.CITY_ACTION_RESOLVED, function(data)
        resolved = data
    end)

    local controller = city_phase.createCityPhaseController({
        eventBus = bus,
        guild = { builder },
        buildings = buildings,
        cityLayout = cityLayout,
    })

    local buildOption = controller:getBuildProjectOption(builder, {
        description = "statue in a busy square",
        artisan = {
            id = "rook_mason",
            name = "Rook Mason",
            districtId = "mason_square",
        },
        districtId = "mason_square",
    })
    assertTrue(not buildOption.disabled, "Build option helper should enable an affordable approved project")
    assertEqual(buildOption.syllables, 7, "Build option helper should estimate project syllables")
    assertEqual(buildOption.cost, 350, "Build option helper should price 50g per syllable")
    assertEqual(buildOption.districtName, "Mason Square", "Build option helper should resolve selected City districts")
    assertEqual(buildOption.districtOptions[1].name, "Mason Square",
        "Build option helper should expose discovered district choices")

    local ok, result, detail = controller:resolveAction(builder, {
        type = "build",
        description = "statue in a busy square",
        artisan = {
            id = "rook_mason",
            name = "Rook Mason",
            districtId = "mason_square",
        },
        districtId = "mason_square",
    })
    assertTrue(ok, "Build should resolve through the City Action facade")
    assertEqual(result, "building_complete", "Build should report completion")
    assertEqual(detail.syllables, 7, "Build should count syllables in the project description")
    assertEqual(detail.cost, 350, "Build should cost 50g per syllable")
    assertEqual(builder.gold, 50, "Build should spend the project gold")
    assertTrue(buildings.statue_in_a_busy_square ~= nil, "Build should persist the completed building record")
    assertEqual(buildings.statue_in_a_busy_square.artisan, "Rook Mason", "Build should record the artisan/designer")
    assertEqual(buildings.statue_in_a_busy_square.districtId, "mason_square",
        "Build should record the City district for the project")
    assertEqual(cityLayout.buildings[1].buildingId, "statue_in_a_busy_square",
        "Build should attach completed projects to the City layout")
    assertEqual(cityLayout.districts[1].buildings[1].buildingId, "statue_in_a_busy_square",
        "Build should attach completed projects to the selected district")
    assertTrue(controller:hasActed(builder), "Build should consume a successful City Action")
    assertTrue(resolved and resolved.action == city_phase.ACTIONS.BUILD, "Build should emit city action details")

    local duplicateOption = controller:getBuildProjectOption(builder, {
        description = "statue in a busy square",
    })
    assertTrue(duplicateOption.disabled, "Build option helper should disable duplicate project ids")
    assertEqual(duplicateOption.unavailableReason, "Building project already exists",
        "Build option helper should explain duplicate project ids")

    local missingDistrict = base_entity.createEntity({
        id = "pc_city_build_missing_district",
        name = "City Build Missing District",
        isPC = true,
    })
    missingDistrict.gold = 500
    missingDistrict.inventory = inventory.createInventory()
    local missingDistrictController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { missingDistrict },
        buildings = {},
        cityLayout = cityLayout,
    })
    local missingDistrictOption = missingDistrictController:getBuildProjectOption(missingDistrict, {
        description = "church bell",
        districtId = "not_discovered",
    })
    assertTrue(missingDistrictOption.disabled, "Build option helper should disable unknown City districts")
    assertEqual(missingDistrictOption.unavailableReason, "City district not found",
        "Build option helper should explain unknown City districts")
    ok, result = missingDistrictController:resolveAction(missingDistrict, {
        type = "build",
        description = "church bell",
        districtId = "not_discovered",
    })
    assertTrue(not ok, "Build should reject unknown City districts when a layout is provided")
    assertEqual(result, "City district not found", "unknown Build district should explain failure")
    assertEqual(missingDistrict.gold, 500, "failed district Build should not spend gold")
    assertTrue(not missingDistrictController:hasActed(missingDistrict),
        "failed district Build should not consume City Action")

    local fractionalBuilder = base_entity.createEntity({
        id = "pc_city_build_fractional_syllables",
        name = "City Build Fractional Syllables",
        isPC = true,
    })
    fractionalBuilder.gold = 500
    fractionalBuilder.inventory = inventory.createInventory()
    local fractionalBuildController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { fractionalBuilder },
        buildings = {},
    })
    ok, result = fractionalBuildController:resolveAction(fractionalBuilder, {
        type = "build",
        description = "painted plaza shrine",
        syllables = 2.5,
    })
    assertTrue(not ok, "Build should reject fractional explicit syllable counts")
    assertEqual(result, "Syllable count must be a whole number",
        "fractional Build syllables should explain the syllable-count rule")
    assertEqual(fractionalBuilder.gold, 500, "fractional Build syllables should not spend gold")
    assertTrue(not fractionalBuildController:hasActed(fractionalBuilder),
        "fractional Build syllables should not consume City Action")

    local poor = base_entity.createEntity({
        id = "pc_city_build_poor",
        name = "City Build Poor",
        isPC = true,
    })
    poor.gold = 99
    poor.inventory = inventory.createInventory()
    local poorController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { poor },
        buildings = {},
    })
    local poorBuildOption = poorController:getBuildProjectOption(poor, {
        description = "church bell",
    })
    assertTrue(poorBuildOption.disabled, "Build option helper should disable unaffordable projects")
    assertEqual(poorBuildOption.cost, 100, "Build option helper should expose unaffordable project cost")
    assertEqual(poorBuildOption.unavailableReason, "Not enough gold",
        "Build option helper should explain unaffordable projects")
    ok, result = poorController:resolveAction(poor, {
        type = "build",
        description = "church bell",
    })
    assertTrue(not ok, "Build should require enough gold for the syllable price")
    assertEqual(result, "Not enough gold", "insufficient Build gold should explain failure")
    assertEqual(poor.gold, 99, "failed Build should not spend gold")
    assertTrue(not poorController:hasActed(poor), "failed Build should not consume City Action")

    local rejected = base_entity.createEntity({
        id = "pc_city_build_rejected",
        name = "City Build Rejected",
        isPC = true,
    })
    rejected.gold = 500
    rejected.inventory = inventory.createInventory()
    local rejectedController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { rejected },
        buildings = {},
    })
    ok, result = rejectedController:resolveAction(rejected, {
        type = "build",
        description = "impossible brass tower",
        approved = false,
    })
    assertTrue(not ok, "Build should allow GM reasonableness rejection")
    assertEqual(result, "Building project not approved", "rejected Build should explain GM approval failure")
    assertEqual(rejected.gold, 500, "rejected Build should not spend gold")
    assertTrue(not rejectedController:hasActed(rejected), "rejected Build should not consume City Action")
end

local function checkCityPhaseCommissionCraftAction()
    local function findScaleOption(options, scale)
        for _, option in ipairs(options or {}) do
            if option.scale == scale then
                return option
            end
        end
        return nil
    end

    local patron = base_entity.createEntity({
        id = "pc_city_commission_patron",
        name = "City Commission Patron",
        isPC = true,
    })
    patron.gold = 50
    patron.inventory = inventory.createInventory()

    local commissions = {}
    local bus = events.createEventBus()
    local resolved = nil
    bus:on(events.EVENTS.CITY_ACTION_RESOLVED, function(data)
        resolved = data
    end)

    local controller = city_phase.createCityPhaseController({
        eventBus = bus,
        guild = { patron },
        commissions = commissions,
    })

    local commissionOptions = controller:getCommissionCraftOptions(patron, {
        description = "imp trap",
        scale = "adventurer",
        merchant = "Pawnbroker Jassa",
        deliver = true,
    })
    assertTrue(not commissionOptions.disabled, "Commission Craft option helper should enable affordable commissions")
    assertEqual(commissionOptions.syllables, 2, "Commission Craft option helper should estimate syllables")
    assertEqual(commissionOptions.cost, 10, "Commission Craft option helper should price the selected scale")
    assertEqual(commissionOptions.ratePerSyllable, 5,
        "Commission Craft option helper should expose selected rate per syllable")
    assertTrue(commissionOptions.deliveryRequested,
        "Commission Craft option helper should preserve delivery requests for UI preflight")
    assertEqual(findScaleOption(commissionOptions.scaleOptions, "novel").cost, 50,
        "Commission Craft option helper should expose alternate scale costs")

    local ok, result, detail = controller:resolveAction(patron, {
        type = "commission_craft",
        description = "imp trap",
        scale = "adventurer",
        merchant = "Pawnbroker Jassa",
        deliver = true,
    })
    assertTrue(ok, "Commission Craft should resolve through the City Action facade")
    assertEqual(result, "commission_complete", "Commission Craft should report completion")
    assertEqual(detail.syllables, 2, "Commission Craft should count syllables in the commissioned item")
    assertEqual(detail.ratePerSyllable, 5, "adventurer-scale Commission Craft should cost 5g per syllable")
    assertEqual(detail.cost, 10, "Commission Craft should multiply syllables by the selected rate")
    assertEqual(patron.gold, 40, "Commission Craft should spend gold")
    assertTrue(commissions.imp_trap ~= nil, "Commission Craft should persist the commissioned craft record")
    assertEqual(commissions.imp_trap.merchant, "Pawnbroker Jassa", "Commission Craft should record the merchant/crafter")
    assertTrue(detail.deliveredItem ~= nil, "Commission Craft should deliver requested bespoke gear")
    assertEqual(detail.deliveredItem.name, "imp trap", "Commission Craft should name delivered bespoke gear")
    assertTrue(patron.inventory:findItem(detail.deliveredItem.id) ~= nil,
        "delivered Commission Craft gear should be carried by the patron")
    assertEqual(commissions.imp_trap.deliveredItemId, detail.deliveredItem.id,
        "Commission Craft record should point to delivered gear")
    assertTrue(controller:hasActed(patron), "Commission Craft should consume a successful City Action")
    assertTrue(resolved and resolved.action == city_phase.ACTIONS.COMMISSION_CRAFT, "Commission Craft should emit city action details")

    local merchantPatron = base_entity.createEntity({
        id = "pc_city_commission_registry_patron",
        name = "City Commission Registry Patron",
        isPC = true,
    })
    merchantPatron.gold = 100
    merchantPatron.inventory = inventory.createInventory()
    local merchantCommissions = {}
    local merchants = {
        brass_snail = {
            id = "brass_snail",
            name = "Brass Snail Foundry",
            districtId = "foundry_lane",
            districtName = "Foundry Lane",
            specialties = { "traps", "clockwork" },
        },
    }
    local merchantController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { merchantPatron },
        commissions = merchantCommissions,
        merchants = merchants,
    })
    local merchantOptions = merchantController:getCommissionCraftOptions(merchantPatron, {
        description = "clockwork trap",
        scale = "adventurer",
        merchantId = "brass_snail",
        requireMerchant = true,
    })
    assertTrue(merchantOptions.merchantFound, "Commission Craft option helper should resolve authored merchants")
    assertEqual(merchantOptions.merchant, "Brass Snail Foundry",
        "Commission Craft option helper should expose merchant display names")
    assertEqual(merchantOptions.merchantOptions[1].districtName, "Foundry Lane",
        "Commission Craft option helper should expose merchant districts")
    assertEqual(merchantOptions.merchantOptions[1].specialties[1], "traps",
        "Commission Craft option helper should expose merchant specialties")
    ok, result, detail = merchantController:resolveAction(merchantPatron, {
        type = "commission_craft",
        description = "clockwork trap",
        scale = "adventurer",
        merchantId = "brass_snail",
        requireMerchant = true,
        deliver = true,
    })
    assertTrue(ok, "Commission Craft should resolve authored merchant records")
    assertEqual(result, "commission_complete", "merchant-backed Commission Craft should report completion")
    assertEqual(merchantCommissions.clockwork_trap.merchant, "Brass Snail Foundry",
        "Commission Craft should use the authored merchant name")
    assertEqual(merchantCommissions.clockwork_trap.merchantId, "brass_snail",
        "Commission Craft should preserve the authored merchant id")
    assertEqual(merchantCommissions.clockwork_trap.merchantDistrictId, "foundry_lane",
        "Commission Craft should preserve the merchant district")
    assertEqual(merchantCommissions.clockwork_trap.merchantSpecialties[1], "traps",
        "Commission Craft should preserve merchant specialties")
    assertEqual(merchants.brass_snail.commissions[1], "clockwork_trap",
        "Commission Craft should link completed commissions back to the merchant registry")
    assertEqual(detail.deliveredItem.properties.commissionMerchantId, "brass_snail",
        "delivered Commission Craft gear should preserve the merchant id")
    assertEqual(detail.merchantRecord.name, "Brass Snail Foundry",
        "Commission Craft detail should expose the authored merchant record")

    local missingMerchant = base_entity.createEntity({
        id = "pc_city_commission_missing_merchant",
        name = "City Commission Missing Merchant",
        isPC = true,
    })
    missingMerchant.gold = 50
    missingMerchant.inventory = inventory.createInventory()
    local missingMerchantCommissions = {}
    local missingMerchantController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { missingMerchant },
        commissions = missingMerchantCommissions,
        merchants = merchants,
    })
    local missingMerchantOptions = missingMerchantController:getCommissionCraftOptions(missingMerchant, {
        description = "scrimshaw pipe",
        scale = "farmer",
        merchantId = "missing_foundry",
        requireMerchant = true,
    })
    assertTrue(missingMerchantOptions.disabled,
        "Commission Craft option helper should disable missing required merchants")
    assertEqual(missingMerchantOptions.unavailableReason, "Commission merchant not found",
        "Commission Craft option helper should explain missing required merchants")
    ok, result = missingMerchantController:resolveAction(missingMerchant, {
        type = "commission_craft",
        description = "scrimshaw pipe",
        scale = "farmer",
        merchantId = "missing_foundry",
        requireMerchant = true,
        deliver = true,
    })
    assertTrue(not ok, "Commission Craft should reject missing required merchants")
    assertEqual(result, "Commission merchant not found", "missing Commission Craft merchant should explain failure")
    assertEqual(missingMerchant.gold, 50, "missing merchant Commission Craft should not spend gold")
    assertTrue(missingMerchantCommissions.scrimshaw_pipe == nil,
        "missing merchant Commission Craft should not persist a commission")
    assertTrue(not missingMerchantController:hasActed(missingMerchant),
        "missing merchant Commission Craft should not consume the City Action")

    local fullPack = base_entity.createEntity({
        id = "pc_city_commission_full_pack",
        name = "City Commission Full Pack",
        isPC = true,
    })
    fullPack.gold = 100
    fullPack.inventory = inventory.createInventory()
    for i = 1, 21 do
        fullPack.inventory:addItem(inventory.createItem({
            id = "commission_pack_filler_" .. tostring(i),
            name = "Commission Pack Filler " .. tostring(i),
        }), inventory.LOCATIONS.PACK)
    end
    local fullPackCommissions = {}
    local fullPackController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { fullPack },
        commissions = fullPackCommissions,
    })
    local fullPackOptions = fullPackController:getCommissionCraftOptions(fullPack, {
        description = "pan flute",
        scale = "farmer",
        deliver = true,
    })
    assertTrue(fullPackOptions.deliveryRequested,
        "Commission Craft option helper should mark requested delivered gear")
    assertEqual(fullPackOptions.availableDeliverySlots, 0,
        "Commission Craft option helper should expose available delivery slots")
    ok, result = fullPackController:resolveAction(fullPack, {
        type = "commission_craft",
        description = "pan flute",
        scale = "farmer",
        deliver = true,
    })
    assertTrue(not ok, "Commission Craft should preflight delivery capacity")
    assertEqual(result, "insufficient_slots", "full pack should explain failed Commission Craft delivery")
    assertEqual(fullPack.gold, 100, "failed Commission Craft delivery should not spend gold")
    assertTrue(fullPackCommissions.pan_flute == nil, "failed Commission Craft delivery should not persist a commission")
    assertTrue(not fullPackController:hasActed(fullPack),
        "failed Commission Craft delivery should not consume the City Action")

    local fractional = base_entity.createEntity({
        id = "pc_city_commission_fractional_syllables",
        name = "City Commission Fractional Syllables",
        isPC = true,
    })
    fractional.gold = 100
    fractional.inventory = inventory.createInventory()
    local fractionalController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { fractional },
        commissions = {},
    })
    ok, result = fractionalController:resolveAction(fractional, {
        type = "commission_craft",
        description = "silver snare",
        scale = "adventurer",
        syllables = 1.5,
    })
    assertTrue(not ok, "Commission Craft should reject fractional explicit syllable counts")
    assertEqual(result, "Syllable count must be a whole number",
        "fractional Commission Craft syllables should explain the syllable-count rule")
    assertEqual(fractional.gold, 100, "fractional Commission Craft syllables should not spend gold")
    assertTrue(not fractionalController:hasActed(fractional),
        "fractional Commission Craft syllables should not consume City Action")

    local noble = base_entity.createEntity({
        id = "pc_city_commission_noble",
        name = "City Commission Noble",
        isPC = true,
    })
    noble.gold = 59
    noble.inventory = inventory.createInventory()
    local nobleController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { noble },
        commissions = {},
    })
    local nobleOptions = nobleController:getCommissionCraftOptions(noble, {
        description = "mirror masquerade mask",
        scale = "noble",
    })
    assertTrue(nobleOptions.disabled, "Commission Craft option helper should disable unaffordable scales")
    assertEqual(nobleOptions.unavailableReason, "Not enough gold",
        "Commission Craft option helper should explain unaffordable selected scales")
    assertTrue(findScaleOption(nobleOptions.scaleOptions, "farmer").affordable,
        "Commission Craft option helper should leave cheaper scale alternatives selectable")
    ok, result = nobleController:resolveAction(noble, {
        type = "commission",
        description = "mirror masquerade mask",
        scale = "noble",
    })
    assertTrue(not ok, "Commission Craft should require enough gold for the syllable band")
    assertEqual(result, "Not enough gold", "insufficient Commission Craft gold should explain failure")
    assertEqual(noble.gold, 59, "failed Commission Craft should not spend gold")
    assertTrue(not nobleController:hasActed(noble), "failed Commission Craft should not consume City Action")

    local missingScale = base_entity.createEntity({
        id = "pc_city_commission_missing_scale",
        name = "City Commission Missing Scale",
        isPC = true,
    })
    missingScale.gold = 100
    missingScale.inventory = inventory.createInventory()
    local missingScaleController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { missingScale },
        commissions = {},
    })
    ok, result = missingScaleController:resolveAction(missingScale, {
        type = "commission_craft",
        description = "silver thread bug net",
    })
    assertTrue(not ok, "Commission Craft should require the rulebook price band")
    assertEqual(result, "Commission scale required", "missing Commission Craft scale should explain failure")
    assertEqual(missingScale.gold, 100, "missing Commission Craft scale should not spend gold")
    assertTrue(not missingScaleController:hasActed(missingScale), "missing Commission Craft scale should not consume City Action")
end

local function checkCityPhaseHoldFuneralAction()
    local function findFuneralCandidate(options, id)
        for _, option in ipairs(options or {}) do
            if option.id == id then
                return option
            end
        end
        return nil
    end

    local function findFuneralXPOption(options, xp)
        for _, option in ipairs(options or {}) do
            if option.xp == xp then
                return option
            end
        end
        return nil
    end

    local heir = base_entity.createEntity({
        id = "pc_city_funeral_heir",
        name = "City Funeral Heir",
        isPC = true,
    })
    heir.gold = 300
    heir.xp = 0
    heir.inventory = inventory.createInventory()

    local deceased = base_entity.createEntity({
        id = "pc_city_funeral_deceased",
        name = "City Funeral Deceased",
        isPC = true,
    })
    deceased.xp = 5
    deceased.conditions.dead = true

    local bus = events.createEventBus()
    local resolved = nil
    bus:on(events.EVENTS.CITY_ACTION_RESOLVED, function(data)
        resolved = data
    end)

    local funerals = {}
    local controller = city_phase.createCityPhaseController({
        eventBus = bus,
        guild = { heir },
        funerals = funerals,
    })

    local funeralOptions = controller:getFuneralOptions(heir, {
        deceased = deceased,
        xpReclaimed = 2,
    })
    assertTrue(not funeralOptions.disabled, "Hold a Funeral option helper should enable affordable XP reclamation")
    assertEqual(funeralOptions.cost, 200, "Hold a Funeral option helper should price 100g per XP")
    assertEqual(funeralOptions.previousXP, 5, "Hold a Funeral option helper should expose deceased XP")
    assertEqual(findFuneralXPOption(funeralOptions.xpOptions, 2).cost, 200,
        "Hold a Funeral option helper should expose reclaimable XP choices")
    assertTrue(findFuneralCandidate(funeralOptions.deceasedOptions, "pc_city_funeral_deceased").dead,
        "Hold a Funeral option helper should expose dead adventurer candidates")

    local ok, result, detail = controller:resolveAction(heir, {
        type = "hold_funeral",
        deceased = deceased,
        xpReclaimed = 2,
    })
    assertTrue(ok, "Hold a Funeral should resolve through the City Action facade")
    assertEqual(result, "funeral_held", "Hold a Funeral should report completion")
    assertEqual(detail.cost, 200, "Hold a Funeral should cost 100g per reclaimed XP")
    assertEqual(heir.gold, 100, "Hold a Funeral should spend funeral expenses")
    assertEqual(heir.xp, 2, "Hold a Funeral should grant reclaimed XP to the new adventurer")
    assertEqual(heir.inheritedXP, 2, "Hold a Funeral should record inherited XP separately")
    assertEqual(#funerals, 1, "Hold a Funeral should persist a funeral record")
    assertEqual(funerals[1].deceasedId, "pc_city_funeral_deceased", "Hold a Funeral should record the deceased adventurer")
    assertEqual(heir.replacesAdventurerId, "pc_city_funeral_deceased",
        "Hold a Funeral should link the new adventurer to the deceased one")
    assertTrue(controller:hasActed(heir), "Hold a Funeral should consume a successful City Action")
    assertTrue(resolved and resolved.action == city_phase.ACTIONS.HOLD_FUNERAL, "Hold a Funeral should emit city action details")

    local sponsor = base_entity.createEntity({
        id = "pc_city_funeral_sponsor",
        name = "City Funeral Sponsor",
        isPC = true,
    })
    sponsor.gold = 100
    sponsor.inventory = inventory.createInventory()
    local rosterDead = base_entity.createEntity({
        id = "pc_city_funeral_roster_dead",
        name = "City Funeral Roster Dead",
        isPC = true,
    })
    rosterDead.xp = 4
    rosterDead.conditions.dead = true
    local replacement = base_entity.createEntity({
        id = "pc_city_funeral_replacement",
        name = "City Funeral Replacement",
        isPC = true,
    })
    replacement.xp = 0
    local activeGuild = { sponsor, rosterDead }
    local roster = { adventurers = { sponsor, rosterDead } }
    local rosterController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = activeGuild,
        guildRoster = roster,
        funerals = {},
    })
    local rosterOptions = rosterController:getFuneralOptions(sponsor, {
        deceasedId = "pc_city_funeral_roster_dead",
        newAdventurer = replacement,
        xpReclaimed = 1,
    })
    assertTrue(not rosterOptions.disabled, "Hold a Funeral option helper should resolve roster dead by id")
    assertEqual(rosterOptions.deceasedName, "City Funeral Roster Dead",
        "Hold a Funeral option helper should expose selected roster dead names")
    assertTrue(findFuneralCandidate(rosterOptions.deceasedOptions, "pc_city_funeral_sponsor").disabled,
        "Hold a Funeral option helper should disable living roster candidates")
    ok, result, detail = rosterController:resolveAction(sponsor, {
        type = "hold_funeral",
        deceased = rosterDead,
        newAdventurer = replacement,
        xpReclaimed = 1,
    })
    assertTrue(ok, "Hold a Funeral should accept a replacement adventurer")
    assertEqual(result, "funeral_held", "replacement funeral should report completion")
    assertEqual(replacement.xp, 1, "replacement adventurer should receive reclaimed XP")
    assertTrue(not hasValue(activeGuild, rosterDead), "funeral should remove the deceased from the active guild")
    assertTrue(hasValue(activeGuild, replacement), "funeral should add the replacement to the active guild")
    assertTrue(not hasValue(roster.adventurers, rosterDead), "funeral should remove the deceased from the roster")
    assertTrue(hasValue(roster.adventurers, replacement), "funeral should add the replacement to the roster")
    assertEqual(rosterDead.funeralHeld, true, "funeral should mark the deceased as honored")
    assertEqual(rosterDead.replacedById, "pc_city_funeral_replacement",
        "funeral should link the deceased to the replacement")
    assertEqual(detail.rosterChange.addedHeirToGuild, true,
        "funeral details should report replacement guild insertion")

    local fractional = base_entity.createEntity({
        id = "pc_city_funeral_fractional",
        name = "City Funeral Fractional",
        isPC = true,
    })
    fractional.gold = 500
    fractional.inventory = inventory.createInventory()
    local fractionalController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { fractional },
        funerals = {},
    })
    ok, result = fractionalController:resolveAction(fractional, {
        type = "hold_funeral",
        previousXP = 3,
        xp = 1.5,
    })
    assertTrue(not ok, "Hold a Funeral should reject fractional reclaimed XP")
    assertEqual(result, "Funeral XP must be a positive whole number",
        "fractional funeral XP should explain the whole-XP rule")
    assertEqual(fractional.xp or 0, 0, "fractional funeral XP should not be granted")
    assertEqual(fractional.gold, 500, "fractional funeral XP should not spend gold")
    assertTrue(not fractionalController:hasActed(fractional),
        "fractional funeral XP should not consume City Action")

    local poor = base_entity.createEntity({
        id = "pc_city_funeral_poor",
        name = "City Funeral Poor",
        isPC = true,
    })
    poor.gold = 99
    poor.xp = 0
    poor.inventory = inventory.createInventory()
    local poorController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { poor },
        funerals = {},
    })
    local poorFuneralOptions = poorController:getFuneralOptions(poor, {
        previousXP = 1,
        xp = 1,
    })
    assertTrue(poorFuneralOptions.disabled, "Hold a Funeral option helper should disable unaffordable rites")
    assertEqual(poorFuneralOptions.cost, 100, "Hold a Funeral option helper should expose funeral cost")
    assertEqual(poorFuneralOptions.unavailableReason, "Not enough gold",
        "Hold a Funeral option helper should explain unaffordable rites")
    ok, result = poorController:resolveAction(poor, {
        type = "funeral",
        previousXP = 1,
        xp = 1,
    })
    assertTrue(not ok, "Hold a Funeral should require enough gold per reclaimed XP")
    assertEqual(result, "Not enough gold", "insufficient funeral gold should explain failure")
    assertEqual(poor.xp, 0, "failed Hold a Funeral should not grant XP")
    assertEqual(poor.gold, 99, "failed Hold a Funeral should not spend gold")
    assertTrue(not poorController:hasActed(poor), "failed Hold a Funeral should not consume City Action")

    local overreach = base_entity.createEntity({
        id = "pc_city_funeral_overreach",
        name = "City Funeral Overreach",
        isPC = true,
    })
    overreach.gold = 500
    overreach.xp = 0
    overreach.inventory = inventory.createInventory()
    local overreachController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { overreach },
        funerals = {},
    })
    local overreachOptions = overreachController:getFuneralOptions(overreach, {
        previousXP = 1,
        xpReclaimed = 2,
    })
    assertTrue(overreachOptions.disabled, "Hold a Funeral option helper should disable over-reclaimed XP")
    assertEqual(overreachOptions.unavailableReason, "Cannot reclaim more XP than the deceased had",
        "Hold a Funeral option helper should explain XP cap")
    ok, result = overreachController:resolveAction(overreach, {
        type = "hold_funeral",
        previousXP = 1,
        xpReclaimed = 2,
    })
    assertTrue(not ok, "Hold a Funeral should cap reclaimed XP at the deceased adventurer's XP")
    assertEqual(result, "Cannot reclaim more XP than the deceased had", "over-reclaimed funeral XP should explain failure")
    assertEqual(overreach.xp, 0, "over-reclaimed funeral XP should not be granted")
    assertEqual(overreach.gold, 500, "over-reclaimed funeral XP should not spend gold")
    assertTrue(not overreachController:hasActed(overreach), "over-reclaimed funeral XP should not consume City Action")

    local livingSponsor = base_entity.createEntity({
        id = "pc_city_funeral_living_sponsor",
        name = "City Funeral Living Sponsor",
        isPC = true,
    })
    livingSponsor.gold = 200
    livingSponsor.inventory = inventory.createInventory()
    local livingAdventurer = base_entity.createEntity({
        id = "pc_city_funeral_living",
        name = "City Funeral Living",
        isPC = true,
    })
    livingAdventurer.xp = 2
    local livingController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { livingSponsor, livingAdventurer },
        funerals = {},
    })
    local livingOptions = livingController:getFuneralOptions(livingSponsor, {
        deceased = livingAdventurer,
        xpReclaimed = 1,
    })
    assertTrue(livingOptions.disabled, "Hold a Funeral option helper should disable living honorees")
    assertEqual(livingOptions.unavailableReason, "Adventurer must be dead",
        "Hold a Funeral option helper should explain living honorees")
    ok, result = livingController:resolveAction(livingSponsor, {
        type = "hold_funeral",
        deceased = livingAdventurer,
        xpReclaimed = 1,
    })
    assertTrue(not ok, "Hold a Funeral should require the honored adventurer to be dead")
    assertEqual(result, "Adventurer must be dead", "living funeral targets should explain the death requirement")
    assertEqual(livingSponsor.gold, 200, "living-target funeral should not spend gold")
    assertTrue(not livingController:hasActed(livingSponsor), "living-target funeral should not consume City Action")
end

function checkCityPhaseRetirementAction()
    local talent_catalog = require('data.talent_catalog')
    local retiree = base_entity.createEntity({
        id = "pc_city_retirement_veteran",
        name = "City Retirement Veteran",
        isPC = true,
    })
    retiree.xp = 25
    retiree.quest = "Recover the cracked bell"
    retiree.completedQuest = "Recover the cracked bell"
    retiree.inventory = inventory.createInventory()

    local successor = base_entity.createEntity({
        id = "pc_city_retirement_successor",
        name = "City Retirement Successor",
        isPC = true,
    })
    successor.talents = {}
    successor.inventory = inventory.createInventory()
    successor.kin = "human"
    successor.kith = "human"
    successor.arete = talent_catalog.getAreteSetup(successor.kin, successor.kith)

    local activeGuild = { retiree }
    local roster = { adventurers = { retiree } }
    local retirements = {}
    local bus = events.createEventBus()
    local resolved = nil
    bus:on(events.EVENTS.CITY_ACTION_RESOLVED, function(data)
        resolved = data
    end)

    local controller = city_phase.createCityPhaseController({
        eventBus = bus,
        guild = activeGuild,
        guildRoster = roster,
        retirements = retirements,
    })

    local retirementOptions = controller:getRetirementChoiceOptions(retiree, {
        newAdventurer = successor,
        benefits = {
            { type = "talent", talentId = "war_stories" },
            { type = "arete_check", triggerId = "getting_married" },
        },
    })
    assertTrue(not retirementOptions.retirement.disabled,
        "Retirement options should allow completed-quest adventurers to retire")
    assertEqual(retirementOptions.benefitSlots, 2,
        "Retirement options should preview one benefit slot per 10 retired XP")
    assertEqual(retirementOptions.selectedBenefitCount, 2,
        "Retirement options should count selected benefits")
    assertEqual(retirementOptions.retirement.unspentBenefitSlots, 0,
        "Retirement options should preview unspent benefit slots")
    assertTrue(retirementOptions.rosterPreview.removeRetireeFromGuild,
        "Retirement options should preview removing the retiree from the guild")
    assertTrue(retirementOptions.rosterPreview.addSuccessorToGuild,
        "Retirement options should preview adding the successor to the guild")
    assertEqual(retirementOptions.retirement.resultPreview, "adventurer_retired",
        "Retirement options should preview successful retirement")
    assertEqual(retirementOptions.newQuest.unavailableReason, "New quest required",
        "Retirement choice options should explain missing new-quest text")
    assertTrue(not (retiree.retired or successor.talents.war_stories),
        "Retirement options should not mutate retiree or successor")

    local ok, result, detail = controller:resolveAction(retiree, {
        type = "retire_adventurer",
        newAdventurer = successor,
        benefits = {
            { type = "talent", talentId = "war_stories" },
            { type = "arete_check", triggerId = "getting_married" },
        },
    })
    assertTrue(ok, "Retire Adventurer should resolve after a completed quest")
    assertEqual(result, "adventurer_retired", "Retire Adventurer should report retirement")
    assertEqual(detail.benefitSlots, 2, "Retire Adventurer should grant one benefit per 10 XP")
    assertEqual(#retirements, 1, "Retire Adventurer should persist a retirement record")
    assertEqual(retiree.retired, true, "Retire Adventurer should mark the old adventurer retired")
    assertEqual(retiree.controlledByGM, true, "retired adventurers should be under GM command")
    assertEqual(retiree.livesInCity, true, "retired adventurers should live in the City")
    assertTrue(not hasValue(activeGuild, retiree), "retirement should remove the old adventurer from the guild")
    assertTrue(hasValue(activeGuild, successor), "retirement should add the successor to the guild")
    assertTrue(not hasValue(roster.adventurers, retiree), "retirement should remove the old adventurer from the roster")
    assertTrue(hasValue(roster.adventurers, successor), "retirement should add the successor to the roster")
    assertTrue(successor.talents.war_stories and successor.talents.war_stories.mastered == true,
        "retirement should master the chosen successor talent")
    assertEqual(successor.areteCheckMarks, 1, "retirement should apply successor arete check marks")
    assertEqual(successor.arete.checkCount, 1, "retirement arete benefit should update checklist progress")
    assertTrue(successor.arete.checks.getting_married == true,
        "retirement arete benefit should mark the selected trigger")
    assertEqual(detail.benefits[2].triggerId, "getting_married",
        "retirement should report the selected arete trigger")
    assertTrue(not (successor.talents.byname and successor.talents.byname.mastered),
        "one retirement arete check should not complete the arete talent")
    assertEqual(successor.replacesAdventurerId, "pc_city_retirement_veteran",
        "retirement should link the successor to the retiree")
    assertTrue(controller:hasActed(retiree), "retirement should consume the retiree's City Action")
    assertTrue(controller:hasActed(successor), "retirement successor arrival should not create a free City Action")
    assertTrue(controller:canAdvance(), "retirement should not leave the City Action step waiting on the successor")
    assertTrue(resolved and resolved.action == city_phase.ACTIONS.RETIRE_ADVENTURER,
        "Retire Adventurer should emit city action details")
    retirementOptions = controller:getRetirementChoiceOptions(retiree, {
        newAdventurer = successor,
    })
    assertTrue(retirementOptions.retirement.disabled,
        "Retirement options should disable after the retiree used a City Action")
    assertEqual(retirementOptions.retirement.unavailableReason, "City Action already taken",
        "Retirement options should explain repeat City Actions")

    local overAllocated = base_entity.createEntity({
        id = "pc_city_retirement_overallocated",
        name = "City Retirement Overallocated",
        isPC = true,
    })
    overAllocated.xp = 9
    overAllocated.questCompleted = true
    overAllocated.inventory = inventory.createInventory()
    local overController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { overAllocated },
        retirements = {},
    })
    retirementOptions = overController:getRetirementChoiceOptions(overAllocated, {
        newAdventurer = successor,
        benefits = {
            { type = "talent", talentId = "aegis" },
        },
    })
    assertTrue(retirementOptions.retirement.disabled,
        "Retirement options should disable overallocated benefits")
    assertEqual(retirementOptions.retirement.unavailableReason, "Retirement benefits exceed available slots",
        "Retirement options should explain benefit slot caps")
    ok, result = overController:resolveAction(overAllocated, {
        type = "retire",
        newAdventurer = successor,
        benefits = {
            { type = "talent", talentId = "aegis" },
        },
    })
    assertTrue(not ok, "Retire Adventurer should cap benefits by retired XP")
    assertEqual(result, "Retirement benefits exceed available slots",
        "overallocated retirement benefits should explain the slot cap")
    assertTrue(overAllocated.retired ~= true, "failed retirement should not mark the adventurer retired")
    assertTrue(not overController:hasActed(overAllocated), "failed retirement should not consume City Action")

    local sponsor = base_entity.createEntity({
        id = "pc_city_retirement_sponsor",
        name = "City Retirement Sponsor",
        isPC = true,
    })
    sponsor.inventory = inventory.createInventory()
    local deadRetiree = base_entity.createEntity({
        id = "pc_city_retirement_dead",
        name = "City Retirement Dead",
        isPC = true,
    })
    deadRetiree.xp = 20
    deadRetiree.questCompleted = true
    deadRetiree.conditions.dead = true
    local deadController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { sponsor, deadRetiree },
        retirements = {},
    })
    retirementOptions = deadController:getRetirementChoiceOptions(sponsor, {
        retiree = deadRetiree,
        newAdventurer = successor,
        benefits = {
            { type = "talent", talentId = "aegis" },
        },
    })
    assertTrue(retirementOptions.retirement.disabled,
        "Retirement options should disable dead retiree transfers")
    assertEqual(retirementOptions.retirement.unavailableReason, "Retirement requires a living adventurer",
        "Retirement options should explain living-retiree requirement")
    ok, result = deadController:resolveAction(sponsor, {
        type = "retirement",
        retiree = deadRetiree,
        newAdventurer = successor,
        benefits = {
            { type = "talent", talentId = "aegis" },
        },
    })
    assertTrue(not ok, "Retire Adventurer should not transfer benefits from dead adventurers")
    assertEqual(result, "Retirement requires a living adventurer",
        "dead retirements should explain that Hold a Funeral is the XP-transfer path")
    assertTrue(deadRetiree.retired ~= true, "failed dead retirement should not mark the adventurer retired")
    assertTrue(not deadController:hasActed(sponsor), "failed dead retirement should not consume sponsor City Action")

    local quester = base_entity.createEntity({
        id = "pc_city_new_quest",
        name = "City New Quest",
        isPC = true,
    })
    quester.xp = 4
    quester.quest = "Recover the cracked bell"
    quester.questCompleted = true
    quester.inventory = inventory.createInventory()
    local questDeclarations = {}
    local questController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { quester },
        questDeclarations = questDeclarations,
    })
    retirementOptions = questController:getDeclareNewQuestOptions(quester, {
        newQuest = "Carry the cracked bell to Mythrys",
    })
    assertTrue(not retirementOptions.newQuest.disabled,
        "Declare New Quest options should allow completed-quest adventurers to continue")
    assertEqual(retirementOptions.newQuest.xpGained, 3,
        "Declare New Quest options should preview the 3XP award")
    assertEqual(retirementOptions.newQuest.projectedXP, 7,
        "Declare New Quest options should preview projected XP")
    assertEqual(retirementOptions.newQuest.resultPreview, "new_quest_declared",
        "Declare New Quest options should preview successful declaration")
    ok, result, detail = questController:resolveAction(quester, {
        type = "declare_new_quest",
        newQuest = "Carry the cracked bell to Mythrys",
    })
    assertTrue(ok, "Declare New Quest should resolve after a completed quest")
    assertEqual(result, "new_quest_declared", "Declare New Quest should report the new quest")
    assertEqual(quester.xp, 7, "Declare New Quest should award 3 XP for the completed quest")
    assertEqual(quester.quest, "Carry the cracked bell to Mythrys", "Declare New Quest should store the next quest")
    assertEqual(quester.questCompleted, false, "Declare New Quest should clear the completed-quest flag")
    assertEqual(quester.retired, false, "Declare New Quest should keep the adventurer active")
    assertEqual(#questDeclarations, 1, "Declare New Quest should persist a declaration record")
    assertEqual(detail.xpGained, 3, "Declare New Quest details should record the XP award")
    assertTrue(questController:hasActed(quester), "Declare New Quest should consume a City Action")

    local incomplete = base_entity.createEntity({
        id = "pc_city_retirement_incomplete",
        name = "City Retirement Incomplete",
        isPC = true,
    })
    incomplete.xp = 20
    incomplete.inventory = inventory.createInventory()
    local incompleteController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { incomplete },
    })
    retirementOptions = incompleteController:getRetirementChoiceOptions(incomplete, {
        newQuest = "Pretend the last job is done",
    })
    assertTrue(retirementOptions.retirement.disabled and retirementOptions.newQuest.disabled,
        "Retirement choice options should disable both branches without a completed quest")
    assertEqual(retirementOptions.retirement.unavailableReason, "Quest must be complete",
        "Retirement options should explain incomplete quests")
    ok, result = incompleteController:resolveAction(incomplete, {
        type = "new_quest",
        newQuest = "Pretend the last job is done",
    })
    assertTrue(not ok, "Retirement/new quest choices should require a completed quest")
    assertEqual(result, "Quest must be complete", "incomplete quest choices should explain the prerequisite")
    assertTrue(not incompleteController:hasActed(incomplete),
        "failed incomplete-quest choice should not consume City Action")
end

local function checkCityPhaseCampActionFacade()
    local function findCityCampActionOption(options, id)
        for _, option in ipairs(options or {}) do
            if option.campAction == id then
                return option
            end
        end
        return nil
    end

    local fletcher = base_entity.createEntity({
        id = "pc_city_camp_fletcher",
        name = "City Camp Fletcher",
        isPC = true,
    })
    fletcher.inventory = inventory.createInventory()
    fletcher.inventory:addItem(inventory.createItemFromTemplate("bow"), inventory.LOCATIONS.PACK)
    fletcher.ammo = 3

    local bus = events.createEventBus()
    local cityResolved = nil
    local campResolved = nil
    bus:on(events.EVENTS.CITY_ACTION_RESOLVED, function(data)
        cityResolved = data
    end)
    bus:on("camp_action_resolved", function(data)
        campResolved = data
    end)

    local controller = city_phase.createCityPhaseController({
        eventBus = bus,
        guild = { fletcher },
    })

    local fletcherOptions = controller:getCityCampActionOptions(fletcher, {
        campAction = "fletch_arrows",
    })
    assertTrue(not fletcherOptions.disabled,
        "City Camp Action options should enable selected available Camp Actions")
    assertEqual(fletcherOptions.selectedCampAction, "fletch_arrows",
        "City Camp Action options should normalize selected Camp Action ids")
    assertTrue(findCityCampActionOption(fletcherOptions.options, "fletch_arrows").selected,
        "City Camp Action options should mark the selected action")
    assertTrue(not findCityCampActionOption(fletcherOptions.options, "fletch_arrows").disabled,
        "City Camp Action options should expose available delegated actions")

    local ok, result, detail = controller:resolveAction(fletcher, {
        type = "camp_action",
        campAction = "fletch_arrows",
    })
    assertTrue(ok, "City Camp Action should resolve through the City Action facade")
    assertEqual(result, "camp_action_complete", "City Camp Action should report facade completion")
    assertEqual(detail.campAction, "fletch_arrows", "City Camp Action should record the delegated Camp Action")
    assertEqual(detail.campResult, "ammo_refilled", "City Camp Action should preserve the Camp Action result")
    assertEqual(fletcher.ammo, 12, "City Camp Action should apply Camp Action effects")
    assertTrue(controller:hasActed(fletcher), "City Camp Action should consume the actor's City Action")
    assertTrue(cityResolved and cityResolved.action == city_phase.ACTIONS.CAMP_ACTION, "City Camp Action should emit city action details")
    assertTrue(campResolved and campResolved.action == "fletch_arrows", "City Camp Action should reuse camp action event emission")

    local tinker = base_entity.createEntity({
        id = "pc_city_camp_tinker",
        name = "City Camp Tinker",
        isPC = true,
    })
    tinker.inventory = inventory.createInventory()
    local kit = inventory.createItemFromTemplate("tinkers_kit")
    tinker.inventory:addItem(kit, inventory.LOCATIONS.PACK)
    local notchedArmor = inventory.createItem({
        name = "City Notched Armor",
        size = 1,
        durability = 2,
    })
    notchedArmor.notches = 1
    local tinkerBus = events.createEventBus()
    local tinkerCityResolved = nil
    local tinkerCampResolved = nil
    tinkerBus:on(events.EVENTS.CITY_ACTION_RESOLVED, function(data)
        tinkerCityResolved = data
    end)
    tinkerBus:on("camp_action_resolved", function(data)
        if data.action == "use_item" then
            tinkerCampResolved = data
        end
    end)
    local tinkerController = city_phase.createCityPhaseController({
        eventBus = tinkerBus,
        guild = { tinker },
    })
    local tinkerOptions = tinkerController:getCityCampActionOptions(tinker, {
        campAction = "use_item",
    })
    assertTrue(not tinkerOptions.disabled,
        "City Camp Action options should enable available Use an Item delegation")
    assertEqual(findCityCampActionOption(tinkerOptions.options, "use_item").name, "Use an Item",
        "City Camp Action options should expose delegated Camp Action display metadata")
    ok, result, detail = tinkerController:resolveAction(tinker, {
        type = "camp_action",
        campAction = "use_item",
        itemId = kit.id,
        targetItem = notchedArmor,
    })
    assertTrue(ok, "City Camp Action should allow Use an Item through the facade")
    assertEqual(result, "camp_action_complete", "City Use Item facade should report completion")
    assertEqual(detail.campAction, "use_item", "City Use Item should record the delegated Camp Action")
    assertEqual(detail.campResult, "repaired", "City Use Item should preserve tinker repair result")
    assertEqual(notchedArmor.notches, 0, "City Use Item should apply tinker kit repair effects")
    assertTrue(tinker.inventory:findItem(kit.id), "City Use Item tinker repair should not consume the kit")
    assertTrue(tinkerController:hasActed(tinker), "successful City Use Item should consume the actor's City Action")
    assertTrue(tinkerCityResolved and tinkerCityResolved.action == city_phase.ACTIONS.CAMP_ACTION,
        "City Use Item should emit city action details")
    assertTrue(tinkerCampResolved and tinkerCampResolved.itemId == kit.id,
        "City Use Item should preserve Camp Use Item event emission")

    local trainee = base_entity.createEntity({
        id = "pc_city_camp_trainee",
        name = "City Camp Trainee",
        isPC = true,
    })
    trainee.xp = 2
    trainee.talents = {}
    trainee.inventory = inventory.createInventory()
    local trainer = base_entity.createEntity({
        id = "pc_city_camp_trainer",
        name = "City Camp Trainer",
        isPC = true,
        talents = {
            war_stories = { mastered = true },
        },
    })
    trainer.inventory = inventory.createInventory()

    local trainController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { trainee, trainer },
    })
    ok, result, detail = trainController:resolveAction(trainee, {
        type = "camp",
        campAction = "train",
        target = trainer,
        talentId = "war_stories",
        xp = 1,
    })
    assertTrue(ok, "City Camp Action should allow guild-mate Train as a Camp Action")
    assertEqual(result, "camp_action_complete", "guild-mate City Camp Train should report facade completion")
    assertEqual(detail.campResult, "training_complete", "guild-mate City Camp Train should preserve training result")
    assertEqual(trainee.xp, 1, "guild-mate City Camp Train should spend trainee XP")
    assertTrue(trainee.talents.war_stories ~= nil, "guild-mate City Camp Train should create the mentored talent")
    assertTrue(trainController:hasActed(trainee), "guild-mate City Camp Train should consume trainee City Action")
    assertTrue(trainController:hasActed(trainer), "guild-mate City Camp Train should consume trainer City Action")
    assertTrue(trainController:canAdvance(), "guild-mate City Camp Train should count both actors toward City Action completion")

    ok, result = trainController:resolveAction(trainer, {
        type = "camp_action",
        campAction = "rest",
    })
    assertTrue(not ok, "mentor should not take a second City Action after guild-mate Camp Train")
    assertEqual(result, "City Action already taken", "spent mentor City Action should explain duplicate action failure")

    local noBow = base_entity.createEntity({
        id = "pc_city_camp_no_bow",
        name = "City Camp No Bow",
        isPC = true,
    })
    noBow.inventory = inventory.createInventory()
    local noBowController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { noBow },
    })
    local noBowOptions = noBowController:getCityCampActionOptions(noBow, {
        campAction = "fletch_arrows",
    })
    assertTrue(noBowOptions.disabled,
        "City Camp Action options should disable selected unavailable Camp Actions")
    assertEqual(noBowOptions.unavailableReason, "Requires a bow or crossbow",
        "City Camp Action options should explain missing fletching gear")
    ok, result = noBowController:resolveAction(noBow, {
        type = "camp_action",
        campAction = "fletch_arrows",
    })
    assertTrue(not ok, "failed City Camp Action should preserve Camp Action validation")
    assertEqual(result, "Requires a bow or crossbow", "failed City Camp Action should return Camp Action failure reason")
    assertTrue(not noBowController:hasActed(noBow), "failed City Camp Action should not consume City Action")

    local unknown = base_entity.createEntity({
        id = "pc_city_camp_unknown",
        name = "City Camp Unknown",
        isPC = true,
    })
    unknown.inventory = inventory.createInventory()
    local unknownController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { unknown },
    })
    local unknownOptions = unknownController:getCityCampActionOptions(unknown, {
        campAction = "invent_new_camp_action",
    })
    assertTrue(unknownOptions.disabled, "City Camp Action options should disable unknown delegated actions")
    assertEqual(unknownOptions.unavailableReason, "Unknown Camp Action",
        "City Camp Action options should explain unknown delegated actions")
    ok, result = unknownController:resolveAction(unknown, {
        type = "camp_action",
        campAction = "invent_new_camp_action",
    })
    assertTrue(not ok, "City Camp Action should reject unknown Camp Actions")
    assertEqual(result, "Unknown Camp Action", "unknown City Camp Action should explain failure")
    assertTrue(not unknownController:hasActed(unknown), "unknown City Camp Action should not consume City Action")
end

local function checkCityPhaseCarouseAction()
    local carouser = base_entity.createEntity({
        id = "pc_city_carouser",
        name = "City Carouser",
        isPC = true,
    })
    carouser.gold = 100
    carouser.xp = 0
    carouser.inventory = inventory.createInventory()

    local hangoverCard = {
        name = "The Hermit",
        value = 9,
        suit = constants.SUITS.MAJOR,
        is_major = true,
    }
    local discardedMajor = nil
    local fakeGMDeck = {
        draw = function()
            return hangoverCard
        end,
        discard = function(_, card)
            discardedMajor = card
        end,
    }
    local bracketCard = {
        name = "Six of Cups",
        value = 6,
        suit = constants.SUITS.CUPS,
    }
    local fakeMinorDeck = {
        peekDiscard = function()
            return bracketCard
        end,
    }

    local bus = events.createEventBus()
    local resolved = nil
    bus:on(events.EVENTS.CITY_ACTION_RESOLVED, function(data)
        resolved = data
    end)

    local controller = city_phase.createCityPhaseController({
        eventBus = bus,
        guild = { carouser },
        gmDeck = fakeGMDeck,
        playerDeck = fakeMinorDeck,
    })

    local carouseOptions = controller:getCarouseOptions(carouser, {
        spend = "half",
        hangoverCard = hangoverCard,
    })
    assertTrue(not carouseOptions.disabled, "Carouse options should enable an affordable selected spend")
    assertEqual(carouseOptions.goldSpent, 50, "Carouse options should preview half-spend gold")
    assertEqual(carouseOptions.xpGained, 1, "Carouse options should preview half-spend XP")
    assertEqual(carouseOptions.spendOptions[2].goldSpent, 100,
        "Carouse options should expose all-in spend choices")
    assertEqual(carouseOptions.hangover.id, "new_tattoo",
        "Carouse options should map explicit major cards to hangovers")
    assertEqual(carouseOptions.minorDiscard, bracketCard,
        "Carouse options should preview the usable top minor discard")
    assertEqual(carouseOptions.hangoverOutcomePreview.location, "backside",
        "Carouse options should preview bracketed hangover details without resolving")
    assertEqual(carouseOptions.hangoverOutcomePreview.quality, "cringe_misspelled",
        "Carouse options should preview tattoo quality from the minor discard")

    local ok, result, detail = controller:resolveAction(carouser, {
        type = "carouse",
        spend = "half",
        minorDiscardCard = {
            name = "Two of Wands",
            value = 2,
            suit = constants.SUITS.WANDS,
        },
    })
    assertTrue(ok, "Carouse should resolve through the City Action facade")
    assertEqual(result, "carouse_resolved", "Carouse should report completion")
    assertEqual(detail.goldSpent, 50, "half Carouse should spend 50% of brought-back gold")
    assertEqual(carouser.gold, 50, "Carouse should spend the selected gold")
    assertEqual(carouser.xp, 1, "half Carouse should grant 1XP")
    assertEqual(detail.hangover.id, "new_tattoo", "Carouse should map the major card to a hangover entry")
    assertEqual(detail.minorDiscard, bracketCard, "Carouse should expose the current minor discard for bracketed hangover results")
    assertEqual(detail.hangoverOutcome.location, "backside", "Carouse should resolve tattoo location from the minor discard suit")
    assertEqual(detail.hangoverOutcome.quality, "cringe_misspelled", "Carouse should resolve tattoo quality from the minor discard value")
    assertEqual(carouser.tattoos[1].location, "backside", "Carouse should record applied tattoo consequences on the actor")
    assertEqual(discardedMajor, hangoverCard, "Carouse should discard an automatically drawn hangover card")
    assertTrue(controller:hasActed(carouser), "Carouse should consume a successful City Action")
    assertTrue(resolved and resolved.action == city_phase.ACTIONS.CAROUSE, "Carouse should emit city action details")

    local allIn = base_entity.createEntity({
        id = "pc_city_all_in_carouser",
        name = "City All-In Carouser",
        isPC = true,
    })
    allIn.gold = 80
    allIn.xp = 2
    allIn.inventory = inventory.createInventory()
    local allInController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { allIn },
    })
    local allInOptions = allInController:getCarouseOptions(allIn, {
        spend = "all",
        goldBroughtBack = 80,
        hangoverCard = {
            name = "Death",
            value = 13,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
    })
    assertTrue(not allInOptions.disabled, "Carouse options should enable all-in explicit hangovers")
    assertEqual(allInOptions.goldSpent, 80, "Carouse options should preview all-in spending")
    assertEqual(allInOptions.xpGained, 2, "Carouse options should preview all-in XP")
    assertTrue(allInOptions.hangoverOutcomePreview.requiresMinorDiscard,
        "Carouse options should flag bracketed hangovers missing minor discard context")
    ok, result, detail = allInController:resolveAction(allIn, {
        type = "carouse",
        spend = "all",
        goldBroughtBack = 80,
        hangoverCard = {
            name = "Death",
            value = 13,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
    })
    assertTrue(ok, "all-in Carouse should accept an explicit major hangover card")
    assertEqual(detail.goldSpent, 80, "all-in Carouse should spend all brought-back gold")
    assertEqual(allIn.gold, 0, "all-in Carouse should empty available gold")
    assertEqual(allIn.xp, 4, "all-in Carouse should grant 2XP")
    assertEqual(detail.hangover.id, "wanted_poster", "all-in Carouse should record hangover table entry")
    assertTrue(detail.hangoverOutcome.requiresMinorDiscard, "bracketed Carouse hangovers should mark missing minor discard context")

    local saver = base_entity.createEntity({
        id = "pc_city_savings_carouser",
        name = "City Savings Carouser",
        isPC = true,
    })
    saver.gold = 120
    saver.xp = 0
    saver.inventory = inventory.createInventory()
    local saverController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { saver },
    })
    ok, result, detail = saverController:resolveAction(saver, {
        type = "carouse",
        spend = "half",
        goldBroughtBack = 80,
        hangoverCard = {
            name = "Temperance",
            value = 14,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
    })
    assertTrue(ok, "Carouse should base its spend on brought-back gold when provided")
    assertEqual(detail.baseGold, 80, "Carouse should record the brought-back gold basis")
    assertEqual(detail.goldSpent, 40, "half Carouse should spend half of brought-back gold")
    assertEqual(saver.gold, 80, "Carouse should leave pre-existing saved gold unspent")
    assertEqual(saver.xp, 1, "brought-back half Carouse should still grant 1XP")

    local windfall = base_entity.createEntity({
        id = "pc_city_windfall_carouser",
        name = "City Windfall Carouser",
        isPC = true,
    })
    windfall.gold = 100
    windfall.inventory = inventory.createInventory()
    local windfallController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { windfall },
    })
    ok, result, detail = windfallController:resolveAction(windfall, {
        type = "carouse",
        spend = "half",
        hangoverCard = {
            name = "The Magician",
            value = 1,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
        minorDiscardCard = {
            name = "Seven of Swords",
            value = 7,
            suit = constants.SUITS.SWORDS,
        },
    })
    assertTrue(ok, "Carouse windfall should resolve through the City Action facade")
    assertEqual(detail.hangoverOutcome.goldGained, 7, "Carouse windfall should gain gold equal to the minor discard value")
    assertEqual(windfall.gold, 57, "Carouse windfall should add found gold after spending")

    do
        local invalidMinor = base_entity.createEntity({
            id = "pc_city_invalid_minor_discard_carouser",
            name = "City Invalid Minor Discard Carouser",
            isPC = true,
        })
        invalidMinor.gold = 100
        invalidMinor.inventory = inventory.createInventory()
        ok, result, detail = city_phase.createCityPhaseController({
            eventBus = events.createEventBus(),
            guild = { invalidMinor },
        }):resolveAction(invalidMinor, {
            type = "carouse",
            spend = "half",
            hangoverCard = {
                name = "The Magician",
                value = 1,
                suit = constants.SUITS.MAJOR,
                is_major = true,
            },
            minorDiscardCard = {
                name = "The World",
                value = 21,
                suit = constants.SUITS.MAJOR,
                is_major = true,
            },
        })
        assertTrue(ok, "Carouse should still resolve when a non-minor fallback discard is ignored")
        assertTrue(detail.hangoverOutcome.requiresMinorDiscard,
            "Carouse should not resolve bracketed outcomes from a non-minor discard fallback")
        assertEqual(detail.hangoverOutcome.goldGained, 0,
            "Carouse should not award bracketed windfall gold from a major discard fallback")
        assertTrue(detail.minorDiscard == nil, "Carouse should expose no usable minor discard for invalid fallback cards")
        assertEqual(detail.invalidMinorDiscard.name, "The World",
            "Carouse should retain invalid fallback discard details for caller diagnostics")
        assertEqual(invalidMinor.gold, 50, "Carouse should only spend the selected gold when fallback discard is invalid")
    end

    local firebug = base_entity.createEntity({
        id = "pc_city_firebug_carouser",
        name = "City Firebug Carouser",
        isPC = true,
    })
