    assertEqual(pact.infernalContracts[1].price, "one_soul", "Carouse soul-invoice hangover should record the infernal contract")

    local minorHangover = base_entity.createEntity({
        id = "pc_city_minor_hangover_carouser",
        name = "City Minor Hangover Carouser",
        isPC = true,
    })
    minorHangover.gold = 100
    minorHangover.inventory = inventory.createInventory()
