        spend = "half",
        hangoverCard = {
            name = "Seven of Cups",
            value = 7,
            suit = constants.SUITS.CUPS,
        },
    })
    assertTrue(minorHangoverOptions.disabled, "Carouse options should reject minor hangover cards")
    assertEqual(minorHangoverOptions.unavailableReason, "Requires major arcana draw",
        "Carouse options should explain invalid hangover draws")
    ok, result = minorHangoverController:resolveAction(minorHangover, {
        type = "carouse",
        spend = "half",
        hangoverCard = {
            name = "Seven of Cups",
            value = 7,
            suit = constants.SUITS.CUPS,
        },
    })
    assertTrue(not ok, "Carouse should reject minor cards as hangover draws")
    assertEqual(result, "Requires major arcana draw", "minor Carouse hangover draw should explain GM-deck requirement")
    assertEqual(minorHangover.gold, 100, "minor Carouse hangover draw should not spend gold")
    assertTrue(not minorHangoverController:hasActed(minorHangover),
        "minor Carouse hangover draw should not consume City Action")

    local invalidSpend = base_entity.createEntity({
        id = "pc_city_invalid_carouser",
        name = "City Invalid Carouser",
        isPC = true,
    })
    invalidSpend.gold = 100
    invalidSpend.inventory = inventory.createInventory()
