local function checkCityPhasePrepareComponentsAction()
    local sorcerer = base_entity.createEntity({
        id = "pc_city_component_prepper",
        name = "City Component Prepper",
        isPC = true,
    })
    sorcerer.inventory = inventory.createInventory({ packSlots = 2 })

    local bus = events.createEventBus()
    local resolved = nil
    bus:on(events.EVENTS.CITY_ACTION_RESOLVED, function(data)
        resolved = data
    end)

    local controller = city_phase.createCityPhaseController({
        eventBus = bus,
        guild = { sorcerer },
    })

    local function findComponentOption(options, spellId)
        for _, option in ipairs(options or {}) do
            if option.spellId == spellId then
                return option
            end
        end
        return nil
    end

    local options = city_phase.getPrepareComponentOptions()
    local flareOption = findComponentOption(options, "flare")
    assertTrue(flareOption ~= nil, "Prepare Components should expose Flare as a selectable option")
    assertEqual(flareOption.componentId, "component_flare",
        "Prepare Components option should map spells to component templates")
    assertEqual(flareOption.componentName, "Guano of a Dire Bat",
        "Prepare Components option should preserve the component display name")
    assertTrue((flareOption.label or ""):find("Flare", 1, true) ~= nil and
        (flareOption.label or ""):find("Guano of a Dire Bat", 1, true) ~= nil,
        "Prepare Components option label should name the spell and component")

    local noPackActor = base_entity.createEntity({
        id = "pc_city_no_pack_component_options",
        name = "City No Pack Component Options",
        isPC = true,
    })
    noPackActor.inventory = inventory.createInventory({ packSlots = 0 })
    local disabledFlare = findComponentOption(controller:getPrepareComponentOptions(noPackActor), "flare")
    assertTrue(disabledFlare and disabledFlare.disabled,
        "Prepare Components option list should mark components unavailable without pack space")
    assertEqual(disabledFlare.unavailableReason, "insufficient_pack_slots",
        "Prepare Components unavailable option should explain the pack-space gate")

    local ok, result, detail = controller:resolveAction(sorcerer, {
        type = "prepare_components",
        componentIds = { "component_flare", "withering" },
    })
    assertTrue(ok, "Prepare Components should resolve through the City Action facade")
    assertEqual(result, "components_prepared", "Prepare Components should report prepared components")
    assertEqual(detail.count, 2, "Prepare Components should add every requested component")
    assertTrue(sorcerer.inventory:findItemByPredicate(function(item)
        return item.templateId == "component_flare"
    end) ~= nil, "Prepare Components should add explicit component templates")
    assertTrue(sorcerer.inventory:findItemByPredicate(function(item)
        return item.templateId == "component_withering"
    end) ~= nil, "Prepare Components should resolve spell ids to their components")
    assertTrue(controller:hasActed(sorcerer), "Prepare Components should consume a successful City Action")
    assertTrue(resolved and resolved.action == city_phase.ACTIONS.PREPARE_COMPONENTS, "Prepare Components should emit city action details")

    local cramped = base_entity.createEntity({
        id = "pc_city_cramped_component_prepper",
        name = "City Cramped Component Prepper",
        isPC = true,
    })
    cramped.inventory = inventory.createInventory({ packSlots = 1 })
    local crampedController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { cramped },
    })
    ok, result = crampedController:resolveAction(cramped, {
        type = "prepare_spell_components",
        componentIds = { "component_flare", "component_withering" },
    })
    assertTrue(not ok, "Prepare Components should require enough pack space")
    assertEqual(result, "insufficient_slots", "full pack should explain Prepare Components failure")
    assertEqual(#cramped.inventory.pack, 0, "failed Prepare Components should not add partial components")
    assertTrue(not crampedController:hasActed(cramped), "failed Prepare Components should not consume City Action")

    local beltPrepper = base_entity.createEntity({
        id = "pc_city_belt_component_prepper",
        name = "City Belt Component Prepper",
        isPC = true,
    })
    beltPrepper.inventory = inventory.createInventory()
    local beltController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { beltPrepper },
    })
    ok, result = beltController:resolveAction(beltPrepper, {
        type = "prepare_components",
        componentIds = { "component_flare" },
        location = inventory.LOCATIONS.BELT,
    })
    assertTrue(not ok, "Prepare Components should use pack slots, not belt or hand slots")
    assertEqual(result, "components_pack_only", "non-pack Prepare Components should explain the pack-slot rule")
    assertTrue(not beltController:hasActed(beltPrepper), "non-pack Prepare Components should not consume City Action")

    local unknown = base_entity.createEntity({
        id = "pc_city_unknown_component_prepper",
        name = "City Unknown Component Prepper",
        isPC = true,
    })
    unknown.inventory = inventory.createInventory()
    local unknownController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { unknown },
    })
    ok, result = unknownController:resolveAction(unknown, {
        type = "prepare_components",
        componentIds = { "component_nonexistent" },
    })
    assertTrue(not ok, "Prepare Components should reject unknown component requests")
    assertEqual(result, "Unknown spell component", "unknown component should explain Prepare Components failure")
    assertTrue(not unknownController:hasActed(unknown), "unknown component should not consume City Action")
end

local function checkCityPhaseTrainAction()
    local trainee = base_entity.createEntity({
        id = "pc_city_train_trainee",
        name = "City Train Trainee",
        isPC = true,
    })
    trainee.gold = 100
    trainee.path = "pentacles"
    trainee.inventory = inventory.createInventory()
    trainee.talents = {}

    local bus = events.createEventBus()
    local resolved = nil
    bus:on(events.EVENTS.CITY_ACTION_RESOLVED, function(data)
        resolved = data
    end)

    local controller = city_phase.createCityPhaseController({
        eventBus = bus,
        guild = { trainee },
    })

    local function findTrainingOption(options, talentId)
        for _, option in ipairs(options or {}) do
            if option.talentId == talentId then
                return option
            end
        end
        return nil
    end

    local trainingOptions = controller:getCityTrainingOptions(trainee)
    local warStoriesOption = findTrainingOption(trainingOptions, "war_stories")
    assertTrue(warStoriesOption ~= nil, "City Train should expose War Stories as a selectable training option")
    assertTrue(warStoriesOption.mentored and warStoriesOption.cityExpert,
        "cross-path City Train option should require a City expert")
    assertEqual(warStoriesOption.maxInvestableXP, 2,
        "City Train option should cap XP choices by available gold")
    assertEqual(warStoriesOption.xpOptions[2].cost, 100,
        "City Train option should price each XP at the fixed City rate")

    local acrobatOption = findTrainingOption(trainingOptions, "acrobat")
    assertTrue(acrobatOption and acrobatOption.ownPath,
        "City Train option should identify own-path talents")
    assertTrue(not acrobatOption.mentored,
        "own-path City Train option should not require mentoring")

    local blockedWarStories = findTrainingOption(city_phase.getCityTrainingOptions({
        actor = trainee,
        availableExperts = { war_stories = false },
    }), "war_stories")
    assertTrue(blockedWarStories and blockedWarStories.disabled,
        "City Train option should mark unavailable cross-path experts")
    assertEqual(blockedWarStories.unavailableReason, "Trainer unavailable",
        "unavailable City Train option should preserve the resolver reason")

    local ok, result, detail = controller:resolveAction(trainee, {
        type = "train",
        talentId = "War Stories",
        xp = 2,
        trainerName = "Master Salia",
    })
    assertTrue(ok, "City Train should resolve through the City Action facade")
    assertEqual(result, "training_complete", "City Train should report training completion")
    assertEqual(detail.cost, 100, "City Train should cost 50g per XP invested")
    assertEqual(trainee.gold, 0, "City Train should spend gold")
    assertTrue(trainee.talents.war_stories ~= nil, "City Train should create the trained talent")
    assertTrue(trainee.talents.war_stories.mentored, "City Train should mark outside-path training as mentored")
    assertTrue(not trainee.talents.war_stories.pathTrained, "cross-path City Train should not mark path training")
    assertTrue(trainee.talents.war_stories.cityTrained, "City Train should record city expert training")
    assertEqual(trainee.talents.war_stories.xp_invested, 2, "City Train should record invested XP")
    assertEqual(trainee.talents.war_stories.uses_remaining, 2, "City Train should prepare uses equal to XP invested")
    assertTrue(not trainee.talents.war_stories.mastered, "two City Train XP should not master the talent")
    assertTrue(controller:hasActed(trainee), "City Train should consume a successful City Action")
    assertTrue(resolved and resolved.action == city_phase.ACTIONS.TRAIN, "City Train should emit city action details")

    local nearlyMastered = base_entity.createEntity({
        id = "pc_city_train_mastery",
        name = "City Train Mastery",
        isPC = true,
        talents = {
            aegis = {
                mastered = false,
                wounded = false,
                xp_invested = 6,
                uses_remaining = 1,
            },
        },
    })
    nearlyMastered.gold = 50
    nearlyMastered.inventory = inventory.createInventory()
    local masteryController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { nearlyMastered },
    })
    ok, result, detail = masteryController:resolveAction(nearlyMastered, {
        type = "city_train",
        talentId = "aegis",
        xp = 1,
    })
    assertTrue(ok, "City Train should allow continued training on an unmastered talent")
    assertTrue(nearlyMastered.talents.aegis.mastered, "seven total invested XP should master a City-trained talent")
    assertEqual(detail.totalXPInvested, 7, "City Train mastery detail should report total invested XP")

    local pathStudent = base_entity.createEntity({
        id = "pc_city_train_path_student",
        name = "City Train Path Student",
        isPC = true,
    })
    pathStudent.gold = 50
    pathStudent.path = "swords"
    pathStudent.inventory = inventory.createInventory()
    pathStudent.talents = {}
    local pathController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { pathStudent },
    })
    ok, result = pathController:resolveAction(pathStudent, {
        type = "train",
        talentId = "aegis",
        xp = 1,
    })
    assertTrue(ok, "City Train should allow own-path talent investment")
    assertTrue(pathStudent.talents.aegis.pathTrained, "own-path City Train should record path training")
    assertTrue(not pathStudent.talents.aegis.mentored, "own-path City Train should not mark the talent as mentored")

    local unavailable = base_entity.createEntity({
        id = "pc_city_train_unavailable",
        name = "City Train Unavailable",
        isPC = true,
    })
    unavailable.gold = 50
    unavailable.path = "pentacles"
    unavailable.inventory = inventory.createInventory()
    unavailable.talents = {}
    local unavailableController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { unavailable },
    })
    ok, result = unavailableController:resolveAction(unavailable, {
        type = "train",
        talentId = "war_stories",
        xp = 1,
        trainerAvailable = false,
    })
    assertTrue(not ok, "City Train should respect unavailable cross-path experts")
    assertEqual(result, "Trainer unavailable", "unavailable expert should explain City Train failure")
    assertEqual(unavailable.gold, 50, "unavailable expert should not spend gold")
    assertTrue(not unavailableController:hasActed(unavailable), "unavailable expert should not consume City Action")

    local kinStudent = base_entity.createEntity({
        id = "pc_city_train_kin_student",
        name = "City Train Kin Student",
        isPC = true,
    })
    kinStudent.gold = 100
    kinStudent.path = "swords"
    kinStudent.kin = "human"
    kinStudent.inventory = inventory.createInventory()
    kinStudent.talents = {}
    local kinController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { kinStudent },
    })
    ok, result = kinController:resolveAction(kinStudent, {
        type = "train",
        talentId = "proud_and_ancient",
        xp = 1,
    })
    assertTrue(not ok, "City Train should reject kin talents")
    assertEqual(result, "Kin talents cannot be trained", "City Train kin talent rejection should explain the rule")
    assertEqual(kinStudent.gold, 100, "City Train kin rejection should not spend gold")
    assertTrue(kinStudent.talents.proud_and_ancient == nil, "City Train kin rejection should not create a talent")
    assertTrue(not kinController:hasActed(kinStudent), "City Train kin rejection should not consume City Action")

    local poor = base_entity.createEntity({
        id = "pc_city_train_poor",
        name = "City Train Poor",
        isPC = true,
    })
    poor.gold = 49
    poor.inventory = inventory.createInventory()
    poor.talents = {}
    local poorController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { poor },
    })
    ok, result = poorController:resolveAction(poor, {
        type = "train",
        talentId = "aegis",
        xp = 1,
        costPerXP = 1,
    })
    assertTrue(not ok, "City Train should require the fixed 50g per XP")
    assertEqual(result, "Not enough gold", "underpriced City Train gold should explain failure")
    assertEqual(poor.gold, 49, "underpriced City Train should not spend gold")
    assertTrue(poor.talents.aegis == nil, "failed City Train should not create a talent")
    assertTrue(not poorController:hasActed(poor), "failed City Train should not consume City Action")

    local fractional = base_entity.createEntity({
        id = "pc_city_train_fractional",
        name = "City Train Fractional",
        isPC = true,
    })
    fractional.gold = 100
    fractional.inventory = inventory.createInventory()
    fractional.talents = {}
    local fractionalController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { fractional },
    })
    ok, result = fractionalController:resolveAction(fractional, {
        type = "train",
        talentId = "aegis",
        xp = 1.5,
    })
    assertTrue(not ok, "City Train should reject fractional XP investment")
    assertEqual(result, "Training XP must be a positive whole number",
        "fractional City Train XP should explain the whole-XP rule")
    assertEqual(fractional.gold, 100, "fractional City Train should not spend gold")
    assertTrue(fractional.talents.aegis == nil, "fractional City Train should not create a talent")
    assertTrue(not fractionalController:hasActed(fractional), "fractional City Train should not consume City Action")

    local mastered = base_entity.createEntity({
        id = "pc_city_train_mastered",
        name = "City Train Mastered",
        isPC = true,
        talents = {
            aegis = { mastered = true },
        },
    })
    mastered.gold = 100
    mastered.inventory = inventory.createInventory()
    local masteredController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { mastered },
    })
    ok, result = masteredController:resolveAction(mastered, {
        type = "train",
        talentId = "aegis",
        xp = 1,
    })
    assertTrue(not ok, "City Train should reject already mastered talents")
    assertEqual(result, "Talent already mastered", "mastered City Train should explain no-op")
    assertEqual(mastered.gold, 100, "rejected mastered City Train should not spend gold")

    local noTalent = base_entity.createEntity({
        id = "pc_city_train_no_talent",
        name = "City Train No Talent",
        isPC = true,
    })
    noTalent.gold = 100
    noTalent.inventory = inventory.createInventory()
    local noTalentController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { noTalent },
    })
    ok, result = noTalentController:resolveAction(noTalent, {
        type = "train",
    })
    assertTrue(not ok, "City Train should require a talent choice")
    assertEqual(result, "Choose a talent to train", "missing City Train talent should explain failure")
    assertTrue(not noTalentController:hasActed(noTalent), "missing City Train talent should not consume City Action")
end

local function checkCityPhaseJarlGoblinHordeAction()
    local jarl = base_entity.createEntity({
        id = "pc_city_jarl",
        name = "City Jarl",
        isPC = true,
        talents = {
            jarl = { mastered = true },
        },
    })
    jarl.xp = 3
    jarl.inventory = inventory.createInventory()

    local controller = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { jarl },
    })

    local hordeOptions = controller:getGoblinHordeOptions(jarl, {
        xp = 2,
    })
    assertTrue(not hordeOptions.disabled, "Jarl options should allow a usable Jarl to gather goblins")
    assertEqual(hordeOptions.action, city_phase.ACTIONS.ASSEMBLE_GOBLIN_HORDE,
        "Jarl options should identify the goblin horde City Action")
    assertEqual(#hordeOptions.xpOptions, 4, "Jarl options should include zero through current whole XP")
    assertEqual(hordeOptions.xpOptions[1].recruited, 2,
        "Jarl options should preview the base two goblins for zero XP")
    assertEqual(hordeOptions.selectedPreview.requestedGoblins, 4,
        "Jarl options should preview 2 + XP goblin recruitment")
    assertEqual(hordeOptions.selectedPreview.projectedGoblinCount, 4,
        "Jarl options should preview projected horde size")
    assertEqual(hordeOptions.selectedPreview.xpAfter, 1,
        "Jarl options should preview XP after recruitment")
    assertTrue(hordeOptions.countsAsAnimalCompanion and hordeOptions.countsAsOneCreature,
        "Jarl options should expose horde creature accounting")
    assertTrue(hordeOptions.suppliesOwnFood and hordeOptions.oneWordCommandsOnly,
        "Jarl options should expose horde food and command rules")
    assertEqual(#(jarl.animalCompanions or {}), 0,
        "Jarl options should not assemble a horde during preview")
    assertEqual(jarl.xp, 3, "Jarl options should not spend XP during preview")

    local ok, result, detail = controller:resolveAction(jarl, {
        type = "jarl",
        xp = 2,
    })
    assertTrue(ok, "Jarl City Action should assemble a goblin horde")
    assertEqual(result, "goblin_horde_assembled", "Jarl City Action should report horde assembly")
    assertEqual(jarl.xp, 1, "Jarl City Action should spend chosen XP")
    assertEqual(#jarl.animalCompanions, 1, "Goblin horde should count as an animal companion")
    assertTrue(controller:hasActed(jarl), "Jarl City Action should consume a City Action")

    local horde = jarl.animalCompanions[1]
    assertTrue(horde.goblinHorde, "assembled companion should be marked as a goblin horde")
    assertEqual(horde.goblinCount, 4, "Jarl should attract 2 + XP spent goblins")
    assertEqual(detail.goblinCount, 4, "Jarl detail should report current horde count")
    assertEqual(horde.porterSlots, 4, "goblin horde should carry one slot per goblin")
    assertTrue(horde.countsAsOneCreature, "goblin horde should count as one creature")
    assertTrue(horde.suppliesOwnFood, "goblin horde should supply its own food")
    assertTrue(horde.commandsAny and horde.oneWordCommandsOnly, "goblin horde should follow any one-word command")

    local woundResult = horde:takeWound("normal")
    assertEqual(woundResult, "goblin_killed", "each goblin horde Wound should kill one goblin")
    assertEqual(horde.goblinCount, 3, "goblin horde Wound should reduce horde size")
    assertEqual(horde.porterSlots, 3, "goblin porter slots should track surviving goblins")

    local feedController = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { jarl },
    })
    feedController:transitionTo(camp_controller.STATES.BREAK_BREAD)
    horde.conditions.weak = true
    horde.weak = true
    ok, result = feedController:feedAnimalCompanion(jarl, horde)
    assertTrue(ok, "goblin horde should self-supply food during Break Bread")
    assertEqual(result, "animal_feed_self_supplied", "self-supplied horde feed should report distinct result")
    assertTrue(not horde.conditions.weak and not horde.weak, "self-supplied horde feed should clear Weak")

    local target = base_entity.createEntity({
        id = "npc_horde_target",
        name = "Horde Target",
        isPC = false,
        health = 2,
    })
    local resolver = action_resolver.createActionResolver({ eventBus = events.createEventBus() })
    local commandResult = resolver:resolve({
        actor = jarl,
        card = { name = "Cups", value = 8, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.COMMAND,
        companionId = horde.id,
        commandName = "attack",
        target = target,
        contestedCommand = false,
    })
    assertTrue(commandResult.success, "goblin horde should obey a one-word command")
    assertEqual(commandResult.commandName, "sic_em", "one-word attack should normalize to Sic 'Em")

    local complexCommand = resolver:resolve({
        actor = jarl,
        card = { name = "Cups", value = 8, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.COMMAND,
        companionId = horde.id,
        commandName = "Get Help",
        contestedCommand = false,
    })
    assertTrue(not complexCommand.success, "goblin horde should reject multi-word commands")
    assertTrue(hasValue(complexCommand.effects, "command_too_complex"),
        "multi-word goblin command should report complexity block")

    jarl.xp = 10
    local capController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { jarl },
    })
    hordeOptions = capController:getGoblinHordeOptions(jarl, {
        xp = 10,
    })
    assertEqual(hordeOptions.existingGoblinCount, 3,
        "Jarl options should inspect an existing horde")
    assertEqual(hordeOptions.selectedPreview.recruited, 5,
        "Jarl options should preview recruitment capped by remaining slots")
    assertEqual(hordeOptions.selectedPreview.projectedGoblinCount, 8,
        "Jarl options should preview the eight-goblin cap")
    assertTrue(hordeOptions.selectedPreview.capped,
        "Jarl options should flag capped recruitment")
    ok, result, detail = capController:resolveAction(jarl, {
        type = "assemble_goblin_horde",
        xp = 10,
    })
    assertTrue(ok, "Jarl City Action should add goblins up to the rulebook cap")
    assertEqual(horde.goblinCount, 8, "goblin horde should cap at eight goblins")
    assertTrue(detail.capped, "Jarl detail should report recruitment capped by the eight-goblin maximum")

    local fullController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { jarl },
    })
    hordeOptions = fullController:getGoblinHordeOptions(jarl, {
        xp = 0,
    })
    assertTrue(hordeOptions.disabled, "Jarl options should disable a full horde")
    assertEqual(hordeOptions.unavailableReason, "Goblin horde at capacity",
        "Jarl options should explain full-horde capacity")
    ok, result = fullController:resolveAction(jarl, {
        type = "hatch_goblin_horde",
        xp = 0,
    })
    assertTrue(not ok, "Jarl City Action should reject already-full hordes")
    assertEqual(result, "Goblin horde at capacity", "full horde should explain Jarl failure")
    assertTrue(not fullController:hasActed(jarl), "failed full-horde Jarl action should not consume City Action")

    local fractionalJarl = base_entity.createEntity({
        id = "pc_fractional_jarl",
        name = "Fractional Jarl",
        isPC = true,
        talents = {
            jarl = { mastered = true },
        },
    })
    fractionalJarl.xp = 2
    local fractionalController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { fractionalJarl },
    })
    hordeOptions = fractionalController:getGoblinHordeOptions(fractionalJarl, {
        xp = 1.5,
    })
    assertTrue(hordeOptions.disabled, "Jarl options should disable fractional XP spend")
    assertEqual(hordeOptions.unavailableReason, "Jarl XP must be a whole number",
        "Jarl options should explain whole-XP selection")
    ok, result = fractionalController:resolveAction(fractionalJarl, {
        type = "jarl",
        xp = 1.5,
    })
    assertTrue(not ok, "Jarl City Action should reject fractional XP spend")
    assertEqual(result, "Jarl XP must be a whole number",
        "fractional Jarl XP should explain the whole-XP rule")
    assertEqual(fractionalJarl.xp, 2, "fractional Jarl XP should not be spent")
    assertEqual(#(fractionalJarl.animalCompanions or {}), 0,
        "fractional Jarl XP should not assemble a horde")
    assertTrue(not fractionalController:hasActed(fractionalJarl),
        "fractional Jarl XP should not consume City Action")

    local noJarl = base_entity.createEntity({
        id = "pc_no_jarl",
        name = "No Jarl",
        isPC = true,
        talents = {},
    })
    noJarl.xp = 3
    local noJarlController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { noJarl },
    })
    hordeOptions = noJarlController:getGoblinHordeOptions(noJarl, {
        xp = 1,
    })
    assertTrue(hordeOptions.disabled, "Jarl options should disable actors without Jarl")
    assertEqual(hordeOptions.unavailableReason, "Requires Jarl talent",
        "Jarl options should explain missing Jarl talent")
    ok, result = noJarlController:resolveAction(noJarl, {
        type = "jarl",
        xp = 1,
    })
    assertTrue(not ok, "Jarl City Action should require the Jarl talent")
    assertEqual(result, "Requires Jarl talent", "missing Jarl should explain City Action failure")
    assertTrue(not noJarlController:hasActed(noJarl), "missing Jarl should not consume City Action")

    local woundedJarl = base_entity.createEntity({
        id = "pc_wounded_jarl",
        name = "Wounded Jarl",
        isPC = true,
        talents = {
            jarl = { mastered = true, wounded = true },
        },
    })
    woundedJarl.xp = 3
    local woundedController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { woundedJarl },
    })
    ok, result = woundedController:resolveAction(woundedJarl, {
        type = "gather_goblins",
        xp = 1,
    })
    assertTrue(not ok, "Wounded Jarl talent should block horde assembly")
    assertEqual(result, "Requires Jarl talent", "wounded Jarl should explain City Action failure")
    assertEqual(woundedJarl.xp, 3, "wounded Jarl failure should not spend XP")

    local poorJarl = base_entity.createEntity({
        id = "pc_poor_jarl",
        name = "Poor Jarl",
        isPC = true,
        talents = {
            jarl = { mastered = true },
        },
    })
    poorJarl.xp = 1
    local poorController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { poorJarl },
    })
    hordeOptions = poorController:getGoblinHordeOptions(poorJarl, {
        xp = 2,
    })
    assertTrue(hordeOptions.disabled, "Jarl options should disable unaffordable XP spend")
    assertEqual(hordeOptions.unavailableReason, "Not enough XP",
        "Jarl options should explain insufficient XP")
    ok, result = poorController:resolveAction(poorJarl, {
        type = "jarl",
        xp = 2,
    })
    assertTrue(not ok, "Jarl City Action should require the chosen XP")
    assertEqual(result, "Not enough XP", "insufficient Jarl XP should explain failure")
    assertEqual(poorJarl.xp, 1, "insufficient Jarl XP should not be spent")
end

local function checkCityPhaseSupportAction()
    assertEqual(city_phase.classifySupportContributionImpact(25).id, "small",
        "Support should expose the 25g small-impact contribution band")
    assertEqual(city_phase.classifySupportContributionImpact(50).id, "humble_meaningful",
        "Support should expose the 50g humble-but-meaningful contribution band")
    assertEqual(city_phase.classifySupportContributionImpact(100).id, "significant",
        "Support should expose the 100g significant contribution band")
    assertEqual(city_phase.classifySupportContributionImpact(1000).id, "dramatic",
        "Support should expose the 1000g dramatic contribution band")

    local patron = base_entity.createEntity({
        id = "pc_city_support_patron",
        name = "City Support Patron",
        isPC = true,
    })
    patron.gold = 100
    patron.inventory = inventory.createInventory()

    local bus = events.createEventBus()
    local resolved = nil
    bus:on(events.EVENTS.CITY_ACTION_RESOLVED, function(data)
        resolved = data
    end)

    local projects = {}
    local controller = city_phase.createCityPhaseController({
        eventBus = bus,
        guild = { patron },
        projects = projects,
    })

    local function findContributionOption(options, id)
        for _, option in ipairs(options or {}) do
            if option.id == id then
                return option
            end
        end
        return nil
    end

    local function findSupportProjectOption(options, projectId)
        for _, option in ipairs(options or {}) do
            if option.projectId == projectId then
                return option
            end
        end
        return nil
    end

    local contributionOptions = controller:getSupportContributionOptions(patron)
    assertEqual(contributionOptions[1].id, "small",
        "Support contribution options should start at the smallest rulebook band")
    assertTrue(not findContributionOption(contributionOptions, "significant").disabled,
        "Support contribution options should allow affordable bands")
    assertTrue(findContributionOption(contributionOptions, "dramatic").disabled,
        "Support contribution options should disable unaffordable bands")

    local ok, result, detail = controller:resolveAction(patron, {
        type = "support",
        name = "Patch the orphanage roof",
        complexity = 2,
        contribution = 50,
        description = "Buy shingles and pay roofers.",
        completionEffects = {
            outcome = "The orphanage is dry enough to sleep through storms.",
            flags = { "orphanage_roof_repaired" },
            projectFlags = { "civic_good" },
            cityState = {
                orphanage = {
                    roof = "patched",
                },
            },
            guildRoster = {
                contacts = {
                    { id = "orphanage_matron", name = "Matron Holtz" },
                },
                assets = {
                    { id = "orphanage_gratitude", name = "Orphanage gratitude" },
                },
            },
        },
    })
    assertTrue(ok, "Support should resolve through the City Action facade")
    assertEqual(result, "project_supported", "Support should report project progress")
    assertEqual(patron.gold, 50, "Support should spend the GM-approved contribution")
    assertEqual(detail.projectId, "patch_the_orphanage_roof", "Support should normalize a project id from the project name")
    assertEqual(detail.progress, 1, "Support should advance exactly one project step")
    assertEqual(detail.complexity, 2, "Support should preserve project complexity")
    assertTrue(not detail.complete, "Support should not complete before reaching project complexity")
    assertEqual(detail.contributionImpact.id, "humble_meaningful",
        "Support should classify a 50g contribution as humble but meaningful")
    assertEqual(projects.patch_the_orphanage_roof.contributions[1].impactId, "humble_meaningful",
        "Support should record the contribution impact band in project history")
    assertTrue(controller:hasActed(patron), "Support should consume a successful City Action")
    assertTrue(resolved and resolved.action == city_phase.ACTIONS.SUPPORT, "Support should emit city action details")
    assertEqual(resolved.detail.contributionImpact.id, "humble_meaningful",
        "Support event detail should include the contribution impact band")

    local projectOption = findSupportProjectOption(controller:getSupportProjectOptions(patron),
        "patch_the_orphanage_roof")
    assertTrue(projectOption ~= nil, "Support project options should expose existing projects")
    assertEqual(projectOption.progress, 1, "Support project option should report current progress")
    assertEqual(projectOption.remainingSteps, 1, "Support project option should report remaining project steps")
    assertEqual(projectOption.contributionCount, 1, "Support project option should report contribution history")
    assertTrue(not findContributionOption(projectOption.contributionOptions, "humble_meaningful").disabled,
        "Support project option should preserve affordable contribution choices")
    assertTrue(findContributionOption(projectOption.contributionOptions, "significant").disabled,
        "Support project option should disable unaffordable contribution choices")

    local followup = base_entity.createEntity({
        id = "pc_city_support_followup",
        name = "City Support Followup",
        isPC = true,
    })
    followup.gold = 25
    followup.inventory = inventory.createInventory()
    local supportState = {}
    local supportRoster = {}
    local followupController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { followup },
        cityState = supportState,
        guildRoster = supportRoster,
        projects = projects,
    })
    ok, result, detail = followupController:resolveAction(followup, {
        type = "support_project",
        projectId = "patch_the_orphanage_roof",
        contribution = 25,
        description = "Patch the remaining leak.",
    })
    assertTrue(ok, "Support should continue existing projects across City Phases")
    assertTrue(detail.complete, "Support should complete a project when progress reaches complexity")
    assertEqual(projects.patch_the_orphanage_roof.progress, 2, "Support should persist completed progress in the project store")
    assertEqual(#projects.patch_the_orphanage_roof.contributions, 2, "Support should record each contribution step")
    assertEqual(detail.contributionImpact.id, "small", "Support should classify a 25g contribution as small impact")
    assertEqual(projects.patch_the_orphanage_roof.contributions[2].impact.minimumGold, 25,
        "Support project history should preserve the impact threshold")
    assertEqual(projects.patch_the_orphanage_roof.outcome,
        "The orphanage is dry enough to sleep through storms.",
        "completed Support projects should preserve authored outcomes")
    assertEqual(projects.patch_the_orphanage_roof.flags.civic_good, true,
        "Support completion should apply authored project flags")
    assertEqual(supportState.flags.orphanage_roof_repaired, true,
        "Support completion should apply authored City state flags")
    assertEqual(supportState.orphanage.roof, "patched",
        "Support completion should merge authored City state")
    assertEqual(supportRoster.contacts[1].id, "orphanage_matron",
        "Support completion should append authored roster contacts")
    assertEqual(supportRoster.assets[1].id, "orphanage_gratitude",
        "Support completion should append authored roster assets")
    assertEqual(detail.completionDetail.outcome, projects.patch_the_orphanage_roof.outcome,
        "Support detail should report the applied completion outcome")

    local alreadyComplete = base_entity.createEntity({
        id = "pc_city_support_complete",
        name = "City Support Complete",
        isPC = true,
    })
    alreadyComplete.gold = 100
    alreadyComplete.inventory = inventory.createInventory()
    local completeController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { alreadyComplete },
        projects = projects,
    })
    ok, result = completeController:resolveAction(alreadyComplete, {
        type = "support",
        projectId = "patch_the_orphanage_roof",
        contribution = 25,
    })
    assertTrue(not ok, "Support should reject already complete projects")
    assertEqual(result, "Project already complete", "completed Support project should explain no-op")
    assertEqual(alreadyComplete.gold, 100, "completed Support project should not spend gold")
    assertTrue(not completeController:hasActed(alreadyComplete), "completed Support project should not consume City Action")
    local completeOption = findSupportProjectOption(completeController:getSupportProjectOptions(alreadyComplete),
        "patch_the_orphanage_roof")
    assertTrue(completeOption and completeOption.disabled,
        "Support project options should disable completed projects")
    assertEqual(completeOption.unavailableReason, "Project already complete",
        "completed Support project option should explain the no-op")

    local poor = base_entity.createEntity({
        id = "pc_city_support_poor",
        name = "City Support Poor",
        isPC = true,
    })
    poor.gold = 24
    poor.inventory = inventory.createInventory()
    local poorController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { poor },
        projects = {},
    })
    ok, result = poorController:resolveAction(poor, {
        type = "support",
        name = "Soup kitchen",
        complexity = 2,
        contribution = 25,
    })
    assertTrue(not ok, "Support should require the contribution gold")
    assertEqual(result, "Not enough gold", "insufficient Support gold should explain failure")
    assertTrue(not poorController:hasActed(poor), "failed Support should not consume City Action")

    local missingComplexity = base_entity.createEntity({
        id = "pc_city_support_missing_complexity",
        name = "City Support Missing Complexity",
        isPC = true,
    })
    missingComplexity.gold = 100
    missingComplexity.inventory = inventory.createInventory()
    local missingController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { missingComplexity },
        projects = {},
    })
    ok, result = missingController:resolveAction(missingComplexity, {
        type = "support",
        projectId = "unknown_clock",
        contribution = 25,
    })
    assertTrue(not ok, "new Support projects should require complexity")
    assertEqual(result, "Project complexity required", "missing Support complexity should explain setup requirement")
    assertTrue(not missingController:hasActed(missingComplexity), "invalid Support setup should not consume City Action")

    local invalidComplexity = base_entity.createEntity({
        id = "pc_city_support_invalid_complexity",
        name = "City Support Invalid Complexity",
        isPC = true,
    })
    invalidComplexity.gold = 100
    invalidComplexity.inventory = inventory.createInventory()
    local invalidController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { invalidComplexity },
        projects = {},
    })
    ok, result = invalidController:resolveAction(invalidComplexity, {
        type = "support",
        name = "Too large",
        complexity = 9,
        contribution = 25,
    })
    assertTrue(not ok, "Support should keep project complexity in the rulebook range")
    assertEqual(result, "Project complexity must be 2-8", "invalid Support complexity should explain rulebook range")

    local fractionalComplexity = base_entity.createEntity({
        id = "pc_city_support_fractional_complexity",
        name = "City Support Fractional Complexity",
        isPC = true,
    })
    fractionalComplexity.gold = 100
    fractionalComplexity.inventory = inventory.createInventory()
    local fractionalController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { fractionalComplexity },
        projects = {},
    })
    ok, result = fractionalController:resolveAction(fractionalComplexity, {
        type = "support",
        name = "Half step project",
        complexity = 2.5,
        contribution = 25,
    })
    assertTrue(not ok, "Support should reject fractional project complexity")
    assertEqual(result, "Project complexity must be a whole number",
        "fractional Support complexity should explain the whole-step rule")
    assertEqual(fractionalComplexity.gold, 100, "fractional Support complexity should not spend gold")
    assertTrue(not fractionalController:hasActed(fractionalComplexity),
        "fractional Support complexity should not consume City Action")

    local rejected = base_entity.createEntity({
        id = "pc_city_support_rejected",
        name = "City Support Rejected",
        isPC = true,
    })
    rejected.gold = 100
    rejected.inventory = inventory.createInventory()
    local rejectedController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { rejected },
        projects = {},
    })
    ok, result = rejectedController:resolveAction(rejected, {
        type = "support",
        name = "Impossible clock",
        complexity = 2,
        contribution = 25,
        description = "Buy gears for the impossible clock.",
        approved = false,
    })
    assertTrue(not ok, "Support should allow GM reasonableness rejection")
    assertEqual(result, "Support project not approved", "rejected Support should explain GM approval failure")
    assertEqual(rejected.gold, 100, "rejected Support should not spend gold")
    assertTrue(not rejectedController:hasActed(rejected), "rejected Support should not consume City Action")
end

local function checkCityPhaseResearchAction()
    local researcher = base_entity.createEntity({
        id = "pc_city_researcher",
        name = "City Researcher",
        isPC = true,
        cups = 4,
    })
    researcher.gold = 50
    researcher.inventory = inventory.createInventory()

    local successCard = {
        name = "Ten of Swords",
        value = 10,
        suit = constants.SUITS.SWORDS,
    }
    local discardedCard = nil
    local fakeDeck = {
        draw = function()
            return successCard
        end,
        discard = function(_, card)
            discardedCard = card
        end,
    }

    local bus = events.createEventBus()
    local resolved = nil
    bus:on(events.EVENTS.CITY_ACTION_RESOLVED, function(data)
        resolved = data
    end)

    local controller = city_phase.createCityPhaseController({
        eventBus = bus,
        guild = { researcher },
        playerDeck = fakeDeck,
    })

    local function findResearchQuestionOption(options, questionType)
        for _, option in ipairs(options or {}) do
            if option.questionType == questionType then
                return option
            end
        end
        return nil
    end

    local researchOptions = controller:getResearchQuestionOptions(researcher, {
        topic = "The star-daughter beneath the tomb",
        subjectId = "monster_brain_spider",
    })
    assertTrue(not researchOptions.disabled, "Research options should be available to a funded researcher")
    assertEqual(researchOptions.cost, city_phase.RESEARCH_COST,
        "Research options should expose the fixed City Research cost")
    assertEqual(researchOptions.subjectName, "Brain Spider",
        "Research options should expose catalog subject names when available")
    local vulnerabilityOption = findResearchQuestionOption(researchOptions.questionOptions, "vulnerability")
    assertTrue(vulnerabilityOption and vulnerabilityOption.answerAvailable,
        "Research options should flag catalog-backed question answers")

    local ok, result, detail = controller:resolveAction(researcher, {
        type = "research",
        topic = "The star-daughter beneath the tomb",
        subjectId = "monster_brain_spider",
        questionType = "vulnerability",
    })
    assertTrue(ok, "Research should resolve through the City Action facade")
    assertEqual(result, "research_complete", "Research should report completion")
    assertEqual(researcher.gold, 0, "Research should spend 50g")
    assertEqual(detail.questions, 1, "successful Research should allow one question")
    assertEqual(#detail.answers, 1, "successful Research should answer one supplied question")
    assertEqual(detail.answers[1].source, "lore_catalog", "Research should answer authored lore questions")
    assertTrue(detail.answers[1].response.summary:find("Flame") ~= nil,
        "Research should surface the catalog lore answer")
    assertEqual(detail.answers[1].loreSpend, false, "Research answers should not spend lore bid uses")
    assertEqual(detail.testResult.result, "success", "Research should run a Cups test")
    assertEqual(discardedCard, successCard, "Research should discard an automatically drawn test card")
    assertTrue(controller:hasActed(researcher), "Research should consume a successful City Action")
    assertTrue(resolved and resolved.action == city_phase.ACTIONS.RESEARCH, "Research should emit city action details")
    assertEqual(controller.researchLog[1], detail, "Research should append the answer record to the City log")
    local researchSummary = controller:summarizeResearchResult(detail)
    assertEqual(researchSummary.answeredCount, 1,
        "Research summary should report answered questions")
    assertTrue(researchSummary.answers[1].summary:find("Flame") ~= nil,
        "Research summary should preserve answer text")

    local greatResearcher = base_entity.createEntity({
        id = "pc_city_great_researcher",
        name = "City Great Researcher",
        isPC = true,
        cups = 4,
    })
    greatResearcher.gold = 50
    greatResearcher.inventory = inventory.createInventory()
    local greatController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { greatResearcher },
    })
    ok, result, detail = greatController:resolveAction(greatResearcher, {
        type = "research",
        topic = "Lost routes through the Underworld",
        card = {
            name = "Ten of Cups",
            value = 10,
            suit = constants.SUITS.CUPS,
        },
        questionsToAsk = {
            { subjectId = "hazard_silvery_webs", questionType = "environmental_risk" },
            { question = "Who has the passphrase?", answer = "The bellfounder's apprentice." },
            { question = "Where is the green gate?" },
            { question = "What was too much to ask?", answer = "Overflow" },
        },
    })
    assertTrue(ok, "Research should accept an explicit Cups test card")
    assertEqual(detail.testResult.result, "great_success", "matching-suit Research success should be great")
    assertEqual(detail.questions, 3, "great-success Research should allow three questions")
    assertEqual(#detail.answers, 2, "great-success Research should attach catalog and GM answers")
    assertEqual(detail.answers[2].response.summary, "The bellfounder's apprentice.",
        "Research should preserve GM-authored answers")
    assertEqual(#detail.pendingQuestions, 1, "unanswered Research questions should stay pending")
    assertEqual(detail.pendingQuestions[1].question, "Where is the green gate?",
        "pending Research questions should preserve their prompt")
    assertEqual(#detail.overflowQuestions, 1, "Research should track requests beyond the allowed question count")
    local greatSummary = city_phase.summarizeResearchResult(detail)
    assertEqual(greatSummary.pendingCount, 1,
        "Research summary should report pending unanswered questions")
    assertEqual(greatSummary.overflowCount, 1,
        "Research summary should report overflow questions")

    local failedResearcher = base_entity.createEntity({
        id = "pc_city_failed_researcher",
        name = "City Failed Researcher",
        isPC = true,
        cups = 1,
    })
    failedResearcher.gold = 50
    failedResearcher.inventory = inventory.createInventory()
    local failedController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { failedResearcher },
    })
    ok, result, detail = failedController:resolveAction(failedResearcher, {
        type = "research",
        topic = "Unreliable tavern gossip",
        card = {
            name = "Five of Wands",
            value = 5,
            suit = constants.SUITS.WANDS,
        },
    })
    assertTrue(ok, "failed Research test should still resolve the City Action")
    assertEqual(detail.testResult.result, "failure", "low Research test should fail")
    assertEqual(detail.questions, 0, "failed Research should allow no questions")
    assertEqual(failedResearcher.gold, 0, "failed Research should still spend its bribe money")
    assertTrue(failedController:hasActed(failedResearcher), "failed Research test should still consume City Action")

    local poor = base_entity.createEntity({
        id = "pc_city_poor_researcher",
        name = "City Poor Researcher",
        isPC = true,
        cups = 4,
    })
    poor.gold = 49
    poor.inventory = inventory.createInventory()
    local poorController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { poor },
    })
    local poorResearchOptions = poorController:getResearchQuestionOptions(poor, {
        topic = "An expensive rumor",
        subjectId = "monster_brain_spider",
    })
    assertTrue(poorResearchOptions.disabled,
        "Research options should disable unaffordable Research")
    assertEqual(poorResearchOptions.unavailableReason, "Not enough gold",
        "unaffordable Research options should explain the gold gate")
    ok, result = poorController:resolveAction(poor, {
        type = "research",
        topic = "An expensive rumor",
        card = {
            name = "Ten of Cups",
            value = 10,
            suit = constants.SUITS.CUPS,
        },
    })
    assertTrue(not ok, "Research should require 50g")
    assertEqual(result, "Not enough gold", "insufficient Research gold should explain failure")
    assertEqual(poor.gold, 49, "failed Research setup should not spend gold")
    assertTrue(not poorController:hasActed(poor), "failed Research setup should not consume City Action")

    local discounted = base_entity.createEntity({
        id = "pc_city_discounted_researcher",
        name = "City Discounted Researcher",
        isPC = true,
        cups = 4,
    })
    discounted.gold = 49
    discounted.inventory = inventory.createInventory()
    local discountedController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { discounted },
    })
    ok, result = discountedController:resolveAction(discounted, {
        type = "research",
        topic = "Suspiciously cheap rumor",
        cost = 1,
        card = {
            name = "Ten of Cups",
            value = 10,
            suit = constants.SUITS.CUPS,
        },
    })
    assertTrue(not ok, "Research should ignore caller-provided discounts below the rulebook cost")
    assertEqual(result, "Not enough gold", "discounted Research should still require 50g")
    assertEqual(discounted.gold, 49, "discounted failed Research should not spend gold")
    assertTrue(not discountedController:hasActed(discounted),
        "discounted failed Research should not consume City Action")

    local majorResearcher = base_entity.createEntity({
        id = "pc_city_major_researcher",
        name = "City Major Researcher",
        isPC = true,
        cups = 4,
    })
    majorResearcher.gold = 50
    majorResearcher.inventory = inventory.createInventory()
    local majorController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { majorResearcher },
    })
    ok, result = majorController:resolveAction(majorResearcher, {
        type = "research",
        topic = "A major misunderstanding",
        card = {
            name = "The Magician",
            value = 1,
            suit = constants.SUITS.MAJOR,
            is_major = true,
        },
    })
    assertTrue(not ok, "Research should reject non-Fool major cards")
    assertEqual(result, "Requires minor arcana draw", "major Research draw should explain minor-deck requirement")
    assertEqual(majorResearcher.gold, 50, "major Research draw should not spend gold")
    assertTrue(not majorController:hasActed(majorResearcher), "major Research draw should not consume City Action")

    local noTopic = base_entity.createEntity({
        id = "pc_city_no_topic_researcher",
        name = "City No Topic Researcher",
        isPC = true,
    })
    noTopic.gold = 50
    noTopic.inventory = inventory.createInventory()
    local noTopicController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { noTopic },
    })
    ok, result = noTopicController:resolveAction(noTopic, {
        type = "research",
        card = {
            name = "Ten of Cups",
            value = 10,
            suit = constants.SUITS.CUPS,
        },
    })
    assertTrue(not ok, "Research should require a topic")
    assertEqual(result, "Research topic required", "missing Research topic should explain failure")
    assertTrue(not noTopicController:hasActed(noTopic), "missing Research topic should not consume City Action")

    local noDeck = base_entity.createEntity({
        id = "pc_city_no_deck_researcher",
        name = "City No Deck Researcher",
        isPC = true,
    })
    noDeck.gold = 50
    noDeck.inventory = inventory.createInventory()
    local noDeckController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { noDeck },
    })
    ok, result = noDeckController:resolveAction(noDeck, {
        type = "research",
        topic = "A topic with no draw",
    })
    assertTrue(not ok, "Research should require a card draw")
    assertEqual(result, "Requires minor arcana draw", "missing Research draw should explain failure")
    assertEqual(noDeck.gold, 50, "missing Research draw should not spend gold")
    assertTrue(not noDeckController:hasActed(noDeck), "missing Research draw should not consume City Action")
end

local function checkCityPhaseAlchemyActionFacade()
    local buyer = base_entity.createEntity({
        id = "pc_city_menagerie_buyer",
        name = "City Menagerie Buyer",
        isPC = true,
    })
    buyer.gold = 25
    buyer.inventory = inventory.createInventory()

    local seller = base_entity.createEntity({
        id = "pc_city_reagent_seller",
        name = "City Reagent Seller",
        isPC = true,
    })
    seller.gold = 0
    seller.inventory = inventory.createInventory()
    local reagent = inventory.createItemFromTemplate("slime_reagent")
    seller.inventory:addItem(reagent, inventory.LOCATIONS.PACK)

    local bus = events.createEventBus()
    local resolved = {}
    bus:on(events.EVENTS.CITY_ACTION_RESOLVED, function(data)
        resolved[#resolved + 1] = data
    end)

    local controller = city_phase.createCityPhaseController({
        eventBus = bus,
        guild = { buyer, seller },
    })

    local reagentOptions = controller:getMenagerieReagentPurchaseOptions(buyer, {
        source = "brain_spider",
    })
    assertEqual(reagentOptions.selectedTemplateId, "brain_spider_reagent",
        "City Phase Menagerie options should resolve selected reagent sources")
    assertEqual(reagentOptions.cost, 25, "City Phase Menagerie options should preview the fixed reagent cost")
    assertTrue(not reagentOptions.disabled, "City Phase Menagerie options should allow affordable reagent purchases")
    assertEqual(buyer.gold, 25, "City Phase Menagerie options should not spend gold during preview")

    local ok, result, detail = controller:resolveAction(buyer, {
        type = "harvest_alchemical_reagents",
        source = "brain_spider",
    })
    assertTrue(ok, "City Phase should dispatch Menagerie reagent purchases")
    assertEqual(result, "reagent_purchased", "City Phase Menagerie action should report reagent purchase")
    assertEqual(detail.cost, 25, "City Phase Menagerie action should spend one reagent cost")
    assertEqual(buyer.gold, 0, "City Phase Menagerie action should spend actor gold")
    assertTrue(controller:hasActed(buyer), "successful City Action should mark actor as acted")
    assertTrue(not controller:canAdvance(), "City Phase should wait for every active adventurer")
    assertEqual(#resolved, 1, "successful City Action should emit a city resolution event")
    assertEqual(resolved[1].action, city_phase.ACTIONS.MENAGERIE_REAGENT_PURCHASE, "Menagerie alias should emit normalized City Action")
    assertTrue(not resolved[1].canAdvance, "city event should report incomplete City Phase while actors remain")
    assertTrue(buyer.inventory:findItemByPredicate(function(item)
        return item.templateId == "brain_spider_reagent"
    end) ~= nil, "City Phase Menagerie action should add the selected reagent")

    local stockCityBuyer = base_entity.createEntity({
        id = "pc_city_stock_menagerie_buyer",
        name = "City Stock Menagerie Buyer",
        isPC = true,
    })
    stockCityBuyer.gold = 30
    stockCityBuyer.inventory = inventory.createInventory()
    local cityMenagerieStock = {
        pickled_slime = {
            id = "pickled_slime",
            reagentTemplateId = "slime_reagent",
            costPerReagent = 30,
            quantityAvailable = 1,
        },
    }
    local stockController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { stockCityBuyer },
        menagerieStock = cityMenagerieStock,
    })
    reagentOptions = stockController:getMenagerieReagentPurchaseOptions(stockCityBuyer, {
        stockId = "pickled_slime",
    })
    assertEqual(reagentOptions.selectedStockId, "pickled_slime",
        "City Phase Menagerie options should select configured stock")
    assertEqual(reagentOptions.cost, 30, "City Phase Menagerie options should preview authored stock prices")
    assertEqual(reagentOptions.stockRemainingAfterPurchase, 0,
        "City Phase Menagerie options should preview finite stock after purchase")
    ok, result, detail = stockController:resolveAction(stockCityBuyer, {
        type = "harvest_alchemical_reagents",
        stockId = "pickled_slime",
    })
    assertTrue(ok, "City Phase should dispatch authored Menagerie stock purchases")
    assertEqual(result, "reagent_purchased", "City Phase stock purchase should report reagent purchase")
    assertEqual(detail.cost, 30, "City Phase stock purchase should use authored stock price")
    assertEqual(cityMenagerieStock.pickled_slime.quantityAvailable, 0,
        "City Phase stock purchase should decrement configured stock")
    assertTrue(stockCityBuyer.inventory:findItemByPredicate(function(item)
        return item.templateId == "slime_reagent" and item.properties.menagerieStockId == "pickled_slime"
    end) ~= nil, "City Phase stock purchase should preserve stock metadata")

    ok, result = controller:resolveAction(buyer, {
        type = "sell_reagents",
        source = "brain_spider",
    })
    assertTrue(not ok, "City Phase should reject a second action by the same adventurer")
    assertEqual(result, "City Action already taken", "repeat City Action should explain turn accounting")
    assertEqual(#resolved, 1, "rejected repeat City Action should not emit a city event")

    local saleOptions = controller:getReagentSaleOptions(seller, {
        source = "slime",
        price = 37,
    })
    assertEqual(saleOptions.selectedItemId, reagent.id,
        "City Phase reagent sale options should select carried matching reagents")
    assertEqual(saleOptions.saleValue, 37, "City Phase reagent sale options should preview GM-adjudicated prices")
    assertTrue(not saleOptions.disabled, "City Phase reagent sale options should allow bottled reagents")
    assertTrue(seller.inventory:findItem(reagent.id) ~= nil,
        "City Phase reagent sale options should not remove reagents during preview")

    ok, result, detail = controller:resolveAction(seller, {
        type = "sell_reagents",
        source = "slime",
        price = 37,
    })
    assertTrue(ok, "City Phase should dispatch Alchemists' Hall reagent sales")
    assertEqual(result, "reagent_sold", "City Phase sale action should report reagent sale")
    assertEqual(detail.value, 37, "City Phase sale should pass through GM-adjudicated price")
    assertEqual(seller.gold, 37, "City Phase sale should pay the seller")
    assertTrue(seller.inventory:findItem(reagent.id) == nil, "City Phase sale should remove sold reagent")
    assertTrue(controller:canAdvance(), "City Phase should advance after all active adventurers act")
    assertEqual(#resolved, 2, "second successful City Action should emit a city event")
    assertEqual(resolved[2].action, city_phase.ACTIONS.SELL_REAGENT, "sale alias should emit normalized City Action")
    assertTrue(resolved[2].canAdvance, "city event should report when all active actors have acted")

    local poor = base_entity.createEntity({
        id = "pc_city_poor_buyer",
        name = "City Poor Buyer",
        isPC = true,
    })
    poor.gold = 0
    poor.inventory = inventory.createInventory()
    local retryController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { poor },
    })
    reagentOptions = retryController:getMenagerieReagentPurchaseOptions(poor, {
        source = "slime",
    })
    assertTrue(reagentOptions.disabled, "City Phase Menagerie options should disable unaffordable purchases")
    assertEqual(reagentOptions.unavailableReason, "Not enough gold",
        "City Phase Menagerie options should explain insufficient funds")
    ok, result = retryController:resolveAction(poor, {
        type = "harvest_alchemical_reagents",
        source = "slime",
    })
    assertTrue(not ok, "failed City Action should bubble up action failure")
    assertEqual(result, "Not enough gold", "failed Menagerie City Action should explain insufficient funds")
    assertTrue(not retryController:hasActed(poor), "failed City Action should not consume the actor action")

    poor.gold = 25
    ok, result = retryController:resolveAction(poor, {
        type = "harvest_alchemical_reagents",
        source = "slime",
    })
    assertTrue(ok, "actor should be able to retry after a failed City Action")
    assertEqual(result, "reagent_purchased", "retried City Action should resolve normally")
    assertTrue(retryController:canAdvance(), "single-actor City Phase should advance after successful retry")

    local dead = base_entity.createEntity({
        id = "pc_city_dead",
        name = "City Dead",
        isPC = true,
    })
    dead.conditions.dead = true
    dead.inventory = inventory.createInventory()
    local deadController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { dead },
    })
    ok, result = deadController:resolveAction(dead, {
        type = "harvest_alchemical_reagents",
        source = "slime",
    })
    assertTrue(not ok, "dead adventurers should not perform City Actions")
    assertEqual(result, "No active adventurer", "dead adventurer City Action should explain inactive actor")
    assertTrue(deadController:canAdvance(), "dead adventurers should not block City Phase advancement")

    local unknown = base_entity.createEntity({
        id = "pc_city_unknown",
        name = "City Unknown",
        isPC = true,
    })
    unknown.inventory = inventory.createInventory()
    local unknownController = city_phase.createCityPhaseController({
        eventBus = events.createEventBus(),
        guild = { unknown },
    })
    ok, result = unknownController:resolveAction(unknown, {
        type = "hold_a_parade",
    })
    assertTrue(not ok, "unknown City Action should fail")
    assertEqual(result, "Unknown City Action", "unknown City Action should explain unsupported action")
    assertTrue(not unknownController:hasActed(unknown), "unknown City Action should not consume the actor action")
end

local function checkCampReadBookAction()
    local actor = base_entity.createEntity({
        id = "pc_reader",
        name = "Reader",
        isPC = true,
    })
    actor.loreBids = 2
    actor.inventory = inventory.createInventory()

    local available = camp_actions.getAvailableActions(actor, { actor })
    local sawReadBook = false
    for _, action in ipairs(available) do
        if action.id == "read_book" then
            sawReadBook = true
            break
        end
    end
    assertTrue(not sawReadBook, "Read a Book should require a readable carried book")

    local blank = inventory.createItemFromTemplate("blank_book")
    actor.inventory:addItem(blank, inventory.LOCATIONS.PACK)
    assertTrue(not camp_actions.hasReadableBook(actor), "blank books should not satisfy Read a Book")

    local book = inventory.createItemFromTemplate("tomb_lore_book")
    actor.inventory:addItem(book, inventory.LOCATIONS.PACK)
    assertTrue(camp_actions.hasReadableBook(actor), "authored lore books should satisfy Read a Book")

    local function readBookQuestionById(list, id)
        for _, option in ipairs(list or {}) do
            if option.id == id then
                return option
            end
        end
        return nil
    end
    local readBookOptions = camp_actions.getReadBookOptions(actor, {
        bookId = book.id,
        questionType = "identity_or_origin",
    })
    assertEqual(readBookOptions.result, "read_book_options_ready",
        "Read a Book helper should return structured option data")
    assertTrue(readBookOptions.hasReadableBooks,
        "Read a Book helper should report carried readable books")
    assertEqual(readBookOptions.selectedBook.id, book.id,
        "Read a Book helper should expose the selected carried book")
    assertEqual(readBookOptions.selectedQuestion.id, "identity_or_origin",
        "Read a Book helper should expose the selected question")
    assertTrue(readBookQuestionById(readBookOptions.selectedBook.questionOptions, "identity_or_origin") ~= nil,
        "Read a Book helper should list supported book-scoped questions")
    readBookOptions.selectedBook.name = "Mutated Book"
    readBookOptions.selectedBook.questionOptions[1].name = "Mutated Question"
    local refreshedReadBookOptions = camp_actions.getReadBookOptions(actor, {
        bookId = book.id,
        questionType = "identity_or_origin",
    })
    assertEqual(refreshedReadBookOptions.selectedBook.name, book.name,
        "Read a Book helper should return copy-safe book option data")
    assertTrue(refreshedReadBookOptions.selectedBook.questionOptions[1].name ~= "Mutated Question",
        "Read a Book helper should return copy-safe question option data")

    available = camp_actions.getAvailableActions(actor, { actor })
    sawReadBook = false
    for _, action in ipairs(available) do
        if action.id == "read_book" and action.name == "Read a Book" then
            sawReadBook = true
            break
        end
    end
    assertTrue(sawReadBook, "Read a Book should be available when a readable book is carried")

    local bus = events.createEventBus()
    local prompted = nil
    bus:on("camp_action_resolved", function(data)
        if data.action == "read_book" then
            prompted = data
        end
    end)

    local ok, result = camp_actions.resolveReadBook(actor, book, nil, {}, bus)
    assertTrue(ok, "Read a Book without a question should open the question prompt")
    assertEqual(result, "book_question_required", "Read a Book should request one question")
    assertTrue(prompted and prompted.requiresQuestion, "Read a Book prompt should advertise question requirement")
    assertEqual(prompted.subjectId, "location_guardian_shrine", "Read a Book prompt should expose book subject")

    local response
    ok, result, response = camp_actions.resolveAction({
        type = "read_book",
        actor = actor,
        target = book,
        request = {
            questionType = "identity_or_origin",
        },
    }, { eventBus = events.createEventBus() })
    assertTrue(ok, "Read a Book should answer an available book-scoped question")
    assertEqual(result, "book_answered", "Read a Book should report an answered question")
    assertTrue(response.summary:find("astronomer") ~= nil, "Read a Book should return the authored lore answer")
    assertEqual(actor.loreBids, 2, "Read a Book should not spend ordinary lore bid uses")
    assertEqual(actor.lastBookLoreResult.loreSpend, false, "Read a Book should record no lore spend")

    local screenReader = base_entity.createEntity({
        id = "pc_screen_reader",
        name = "Screen Reader",
        isPC = true,
    })
    screenReader.inventory = inventory.createInventory()
    local screenBook = inventory.createItemFromTemplate("tomb_lore_book")
    screenReader.inventory:addItem(screenBook, inventory.LOCATIONS.PACK)
    local screenBus = events.createEventBus()
    local screenController = camp_controller.createCampController({
        eventBus = screenBus,
        guild = { screenReader },
    })
    local campScreenModule = require('ui.screens.camp_screen')
    local campScreen = campScreenModule.createCampScreen({
        eventBus = screenBus,
        campController = screenController,
        guild = { screenReader },
    })
    campScreen:subscribeEvents()
    screenController:transitionTo(camp_controller.STATES.ACTIONS)
    ok, result = screenController:submitAction(screenReader, {
        type = "read_book",
        target = screenBook,
        request = {
            questionType = "identity_or_origin",
        },
    })
    assertTrue(ok, "Camp Screen Read a Book submission should resolve")
    assertEqual(result, "book_answered", "Camp Screen Read a Book should preserve answered result")
    assertTrue(campScreen.promptOverlay ~= nil,
        "Camp Screen should show a Read a Book answer prompt")
    assertEqual(campScreen.promptOverlay.title, "READ A BOOK",
        "Read a Book prompt should use the action title")
    assertTrue((campScreen.promptOverlay.text or ""):find("astronomer", 1, true) ~= nil,
        "Read a Book prompt should present the lore answer summary")
    assertTrue((campScreen.promptOverlay.text or ""):find("Moldering Tomb Astronomies", 1, true) ~= nil,
        "Read a Book prompt should name the selected book")
    campScreen:destroy()

    ok, result = camp_actions.resolveReadBook(actor, book, {
        questionType = "vulnerability",
    }, {}, events.createEventBus())
    assertTrue(not ok, "Read a Book should reject unsupported questions for the book subject")
    assertEqual(result, "book_rephrase_needed", "unsupported book questions should request a rephrase")
    assertEqual(actor.loreBids, 2, "rephrased book questions should not spend lore bid uses")

    local outsideBook = inventory.createItemFromTemplate("tomb_lore_book")
    ok, result = camp_actions.resolveReadBook(actor, outsideBook, {
        questionType = "identity_or_origin",
    }, {}, events.createEventBus())
    assertTrue(not ok, "Read a Book should require the target book to be carried")
    assertEqual(result, "Book must be carried", "uncarried book should explain Read a Book failure")

    actor.afflictions = {
        ghost_lotus = { stage = 2 },
    }
    local blockedReadOptions = camp_actions.getReadBookOptions(actor, {
        bookId = book.id,
    })
    assertTrue(blockedReadOptions.disabled,
        "Read a Book helper should disable reading when the actor cannot read")
    assertEqual(blockedReadOptions.unavailableReasons[1], "cannot_read",
        "Read a Book helper should explain blocked reading")
    assertTrue(not camp_actions.hasReadableBook(actor),
        "ghost lotus stage 2 should block Read a Book availability")
    ok, result = camp_actions.resolveReadBook(actor, book, {
        questionType = "identity_or_origin",
    }, {}, events.createEventBus())
    assertTrue(not ok, "ghost lotus stage 2 should block reading")
    assertEqual(result, "Cannot read", "ghost lotus blocked reading should explain the rulebook rider")
    actor.afflictions = nil
end

local function checkCampScoutAheadAction()
    local actor = base_entity.createEntity({
        id = "pc_scout",
        name = "Scout",
        isPC = true,
    })

    local available = camp_actions.getAvailableActions(actor, { actor })
    local sawScoutAhead = false
    for _, action in ipairs(available) do
        if action.id == "scout" and action.name == "Scout Ahead" then
            sawScoutAhead = true
            break
        end
    end
    assertTrue(sawScoutAhead, "Scout Ahead should be available as the canonical Scout camp action")
    local function campOutcomeById(list, outcome)
        for _, option in ipairs(list or {}) do
            if option.outcome == outcome then
                return option
            end
        end
        return nil
    end

    local bus = events.createEventBus()
    local initiated = nil
    bus:on("camp_action_resolved", function(data)
        if data.action == "scout" and data.result == "scout_initiated" then
            initiated = data
        end
    end)

    local ok, result = camp_actions.resolveScout(actor, {}, bus)
    assertTrue(ok, "Scout Ahead should initiate cleanly")
    assertEqual(result, "scout_initiated", "Scout Ahead should report test initiation")
    assertTrue(initiated and initiated.requiresTest, "Scout Ahead should request a test")
    assertEqual(initiated.testSuit, "pentacles", "Scout Ahead should test Pentacles")

    local scoutInfo = {
        "Goblin tracks cross the eastern threshold.",
        "A warm draft carries incense from the stairs.",
    }
    local outcomeBus = events.createEventBus()
    local emitted = nil
    outcomeBus:on("camp_action_resolved", function(data)
        if data.action == "scout" then
            emitted = data
        end
    end)

    local information
    ok, result, information = camp_actions.resolveScoutOutcome(actor, "success", {
        scoutInfo = scoutInfo,
    }, outcomeBus)
    assertTrue(ok, "successful Scout Ahead should reveal a hint")
    assertEqual(result, "scout_hint", "successful Scout Ahead should report a hint")
    assertEqual(information, scoutInfo[1], "successful Scout Ahead should reveal one nearby hint")
    assertEqual(actor.lastScoutResult.outcome, "success", "Scout Ahead should record normalized success")
    assertEqual(emitted.information, scoutInfo[1], "Scout Ahead should emit the revealed hint")

    local fullInfo = {
        rooms = { "Collapsed shrine", "Ghoul nest" },
        creatures = "Hungry dead and tomb mites",
    }
    local scoutOutcomeOptions = camp_actions.getScoutOutcomeOptions(actor, {
        scoutInfo = scoutInfo,
        greatSuccessInfo = fullInfo,
    }, {
        outcome = "great_success",
    })
    assertEqual(scoutOutcomeOptions.result, "scout_outcome_options_ready",
        "Scout Ahead helper should return structured outcome option data")
    assertEqual(scoutOutcomeOptions.testSuit, "pentacles",
        "Scout Ahead helper should expose the Pentacles test")
    assertEqual(scoutOutcomeOptions.selectedOutcome.outcome, "great_success",
        "Scout Ahead helper should expose the selected outcome")
    assertEqual(campOutcomeById(scoutOutcomeOptions.outcomeOptions, "success").informationPreview, scoutInfo[1],
        "Scout Ahead helper should preview the success hint")
    assertEqual(campOutcomeById(scoutOutcomeOptions.outcomeOptions, "great_success").informationPreview.rooms[1],
        "Collapsed shrine", "Scout Ahead helper should preview the full report")
    campOutcomeById(scoutOutcomeOptions.outcomeOptions, "great_success").informationPreview.rooms[1] = "Mutated room"
    local refreshedScoutOptions = camp_actions.getScoutOutcomeOptions(actor, {
        scoutInfo = scoutInfo,
        greatSuccessInfo = fullInfo,
    }, {
        outcome = "great_success",
    })
    assertEqual(campOutcomeById(refreshedScoutOptions.outcomeOptions, "great_success").informationPreview.rooms[1],
        "Collapsed shrine", "Scout Ahead helper should return copy-safe full-report data")

    ok, result, information = camp_actions.resolveScoutOutcome(actor, { degree = "great success" }, {
        greatSuccessInfo = fullInfo,
    }, events.createEventBus())
    assertTrue(ok, "great-success Scout Ahead should reveal a full report")
    assertEqual(result, "full_scout_report", "great-success Scout Ahead should report full information")
    assertEqual(information, fullInfo, "great-success Scout Ahead should preserve structured nearby info")
    assertEqual(actor.lastScoutResult.information, fullInfo, "great-success Scout Ahead should cache the full report")

    local dungeon = dungeon_graph.loadFromData(tomb_data.data)
    local scoutRoomManager = room_manager.createRoomManager({ eventBus = events.createEventBus() })
    for _, roomData in ipairs(tomb_data.data.rooms or {}) do
        scoutRoomManager:registerRoom(room_manager.createRoomInstance(roomData, roomData.id))
    end

    ok, result, information = camp_actions.resolveScoutOutcome(actor, "success", {
        currentRoomId = "101_entrance",
        dungeon = dungeon,
        roomManager = scoutRoomManager,
    }, events.createEventBus())
    assertTrue(ok, "successful Scout Ahead should derive adjacent-room hints from map data")
    assertEqual(result, "scout_hint", "derived Scout Ahead should still report a hint")
    assertEqual(information.roomId, "102_scriptorium",
        "derived Scout Ahead success should reveal one adjacent room")
    assertTrue(information.summary:find("Scriptorium") ~= nil,
        "derived Scout Ahead hint should identify the nearby room")
    assertEqual(information.secret, nil,
        "derived Scout Ahead hints should omit undiscovered secret exits by default")

    ok, result, information = camp_actions.resolveScoutOutcome(actor, "great_success", {
        currentRoomId = "101_entrance",
        dungeon = dungeon,
        roomManager = scoutRoomManager,
    }, events.createEventBus())
    assertTrue(ok, "great-success Scout Ahead should derive a full adjacent-room report")
    assertEqual(result, "full_scout_report", "derived great-success Scout Ahead should report full information")
    assertEqual(#information, 2,
        "derived great-success Scout Ahead should report each non-secret adjacent room")
    assertEqual(information[1].roomId, "102_scriptorium",
        "derived Scout Ahead report should preserve connection order")
    assertTrue(information[2].features[1] ~= nil,
        "derived Scout Ahead report should include visible notable nearby features")

    ok, result = camp_actions.resolveScoutOutcome(actor, "failure", {}, events.createEventBus())
    assertTrue(not ok, "failed Scout Ahead should not reveal information")
    assertEqual(result, "nothing_learned", "failed Scout Ahead should report no new information")
    assertEqual(actor.lastScoutResult.result, "nothing_learned", "failed Scout Ahead should cache the failure")

    local context = {}
    ok, result = camp_actions.resolveScoutOutcome(actor, "great_failure", context, events.createEventBus())
    assertTrue(not ok, "great-failure Scout Ahead should fail the camp action")
    assertEqual(result, "challenge_triggered", "great-failure Scout Ahead should trigger a Challenge")
    assertTrue(context.challengeTriggered, "great-failure Scout Ahead should mark Challenge trigger context")

    local controllerScout = base_entity.createEntity({
        id = "pc_controller_scout_outcome",
        name = "Controller Scout Outcome",
        isPC = true,
    })
    local scoutController = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { controllerScout },
    })
    scoutController:transitionTo(camp_controller.STATES.ACTIONS)
    ok, result = scoutController:submitAction(controllerScout, {
        type = "scout",
        outcome = "failure",
    })
    assertTrue(ok, "adjudicated failed Scout Ahead should be accepted by the Camp Controller")
    assertEqual(result, "nothing_learned", "failed Scout Ahead should preserve its outcome result")
    assertEqual(scoutController.actionsCompleted[controllerScout.id].outcome, "failure",
        "failed Scout Ahead should still consume the Camp Action")

    local screenScout = base_entity.createEntity({
        id = "pc_screen_scout",
        name = "Screen Scout",
        isPC = true,
    })
    local screenBus = events.createEventBus()
    local screenController = camp_controller.createCampController({
        eventBus = screenBus,
        guild = { screenScout },
    })
    local campScreenModule = require('ui.screens.camp_screen')
    local campScreen = campScreenModule.createCampScreen({
        eventBus = screenBus,
        campController = screenController,
        guild = { screenScout },
    })
    campScreen:subscribeEvents()
    screenController:transitionTo(camp_controller.STATES.ACTIONS)
    ok, result = screenController:submitAction(screenScout, {
        type = "scout",
        outcome = "success",
        scoutInfo = {
            "Bootprints vanish beside a cracked idol.",
        },
    })
    assertTrue(ok, "Camp Screen Scout Ahead submission should resolve")
    assertEqual(result, "scout_hint", "Camp Screen Scout Ahead submission should report the hint")
    assertTrue(campScreen.promptOverlay ~= nil,
        "Camp Screen should show a Scout Ahead result prompt")
    assertEqual(campScreen.promptOverlay.title, "SCOUT AHEAD",
        "Scout Ahead prompt should use the action title")
    assertTrue((campScreen.promptOverlay.text or ""):find("Bootprints vanish", 1, true) ~= nil,
        "Scout Ahead prompt should preserve the revealed hint")
    campScreen:destroy()
end

local function checkCampUpdateMapsAction()
    local actor = base_entity.createEntity({
        id = "pc_mapper",
        name = "Mapper",
        isPC = true,
    })

    local available = camp_actions.getAvailableActions(actor, { actor })
    local sawUpdateMaps = false
    for _, action in ipairs(available) do
        if action.id == "update_maps" and action.name == "Update Maps" then
            sawUpdateMaps = true
            break
        end
    end
    assertTrue(sawUpdateMaps, "Update Maps should be available as a Camp Action")

    local graph = dungeon_graph.createGraph()
    graph:createRoom({ id = "A", name = "Entry" })
    graph:createRoom({ id = "B", name = "Hall", description = "A vaulted hall runs east." })
    graph:createRoom({ id = "C", name = "Shrine", description = "A forgotten shrine waits in the dark." })
    graph:addConnection("A", "B", { direction = "east" })
    graph:addConnection("B", "C", { direction = "east" })

    local movementBus = events.createEventBus()
    local crawlScenes = {}
    movementBus:on(events.EVENTS.CRAWL_SCENE_SET, function(data)
        crawlScenes[#crawlScenes + 1] = data
    end)
    local mappedDeck = {
        draw_pile = {
            { name = "VI Curiosity", value = 6, is_major = true },
        },
        discarded = {},
        draw = function(self)
            return table.remove(self.draw_pile)
        end,
        discard = function(self, card)
            self.discarded[#self.discarded + 1] = card
        end,
    }
    local manager = watch_manager.createWatchManager({
        dungeon = graph,
        startingRoom = "A",
        guild = { actor },
        eventBus = movementBus,
        gmDeck = mappedDeck,
        meatgrinder = meatgrinder.createMeatgrinder({ eventBus = movementBus }),
    })
    local mapState = {}
    local bus = events.createEventBus()
    local emitted = nil
    bus:on("camp_action_resolved", function(data)
        if data.action == "update_maps" then
            emitted = data
        end
    end)

    local mapOptions = camp_actions.getUpdateMapsOptions(actor, {
        watchManager = manager,
        guildMap = mapState,
        traveledRooms = { "A", "B", "C" },
    }, {
        rooms = { "A", "B", "C" },
    })
    assertEqual(mapOptions.result, "update_maps_options_ready",
        "Update Maps helper should return structured option data")
    assertTrue(mapOptions.hasRoomsToMap,
        "Update Maps helper should report travelled rooms to map")
    assertEqual(mapOptions.selectedRoute.roomCount, 3,
        "Update Maps helper should expose the selected route room count")
    assertEqual(mapOptions.selectedRoute.rooms[1].name, "Entry",
        "Update Maps helper should resolve room names from the dungeon graph")
    assertEqual(mapOptions.selectedRoute.mappedRoomTravelPerWatch, 2,
        "Update Maps helper should preview the mapped-route travel pace")
    mapOptions.selectedRoute.rooms[1].name = "Mutated Entry"
    mapOptions.selectedRoute.actionDataPreview.rooms[1] = "mutated"
    local refreshedMapOptions = camp_actions.getUpdateMapsOptions(actor, {
        watchManager = manager,
        guildMap = mapState,
        traveledRooms = { "A", "B", "C" },
    }, {
        rooms = { "A", "B", "C" },
    })
    assertEqual(refreshedMapOptions.selectedRoute.rooms[1].name, "Entry",
        "Update Maps helper should return copy-safe room option data")
    assertEqual(refreshedMapOptions.selectedRoute.actionDataPreview.rooms[1], "A",
        "Update Maps helper should return copy-safe action data")

    local emptyMapOptions = camp_actions.getUpdateMapsOptions(actor, {})
    assertTrue(emptyMapOptions.disabled,
        "Update Maps helper should disable when no travelled rooms are available")
    assertEqual(emptyMapOptions.unavailableReasons[1], "no_rooms_to_map",
        "Update Maps helper should explain missing rooms")

    local ok, result, rooms = camp_actions.resolveUpdateMaps(actor, {
        watchManager = manager,
        guildMap = mapState,
        traveledRooms = { "A", "B", "C" },
    }, bus)
    assertTrue(ok, "Update Maps should resolve with travelled rooms")
    assertEqual(result, "maps_updated", "Update Maps should report map update")
    assertEqual(#rooms, 3, "Update Maps should record travelled rooms")
    assertTrue(emitted and emitted.mappedRoomTravelPerWatch == 2, "Update Maps should emit mapped travel pace")
    assertTrue(mapState.mappedRooms.A and mapState.mappedRooms.B and mapState.mappedRooms.C,
        "Update Maps should record rooms in guild map state")
    assertTrue(manager:isMappedRoom("A") and manager:isMappedRoom("B") and manager:isMappedRoom("C"),
        "Update Maps should push mapped rooms into WatchManager")
    assertEqual(manager.mappedRoomTravelPerWatch, 2, "Update Maps should set mapped travel to two rooms per watch")

    local controllerMapState = {}
    local controllerMapper = base_entity.createEntity({
        id = "pc_controller_mapper",
        name = "Controller Mapper",
        isPC = true,
    })
    local mapController = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { controllerMapper },
        guildMap = controllerMapState,
        traveledRooms = { "A", "B" },
    })
    mapController:transitionTo(camp_controller.STATES.ACTIONS)
    ok, result = mapController:submitAction(controllerMapper, { type = "update_maps" })
    assertTrue(ok, "Camp controller should pass map state to Update Maps")
    assertEqual(result, "maps_updated", "Camp controller Update Maps should resolve")
    assertTrue(controllerMapState.mappedRooms.A and controllerMapState.mappedRooms.B,
        "Camp controller Update Maps should record travelled rooms")

    local screenMapper = base_entity.createEntity({
        id = "pc_screen_mapper",
        name = "Screen Mapper",
        isPC = true,
    })
    local screenBus = events.createEventBus()
    local screenController = camp_controller.createCampController({
        eventBus = screenBus,
        guild = { screenMapper },
        guildMap = {},
        traveledRooms = { "A", "B" },
    })
    local campScreenModule = require('ui.screens.camp_screen')
    local campScreen = campScreenModule.createCampScreen({
        eventBus = screenBus,
        campController = screenController,
        guild = { screenMapper },
    })
    campScreen:subscribeEvents()
    screenController:transitionTo(camp_controller.STATES.ACTIONS)
    ok, result = screenController:submitAction(screenMapper, {
        type = "update_maps",
    })
    assertTrue(ok, "Camp Screen Update Maps submission should resolve")
    assertEqual(result, "maps_updated", "Camp Screen Update Maps should report the map update")
    assertTrue(campScreen.promptOverlay ~= nil,
        "Camp Screen should show an Update Maps result prompt")
    assertEqual(campScreen.promptOverlay.title, "UPDATE MAPS",
        "Update Maps prompt should use the action title")
    assertTrue((campScreen.promptOverlay.text or ""):find("2 rooms", 1, true) ~= nil,
        "Update Maps prompt should preserve the mapped room count")
    assertTrue((campScreen.promptOverlay.text or ""):find("2 rooms per watch", 1, true) ~= nil,
        "Update Maps prompt should preserve the mapped travel pace")
    campScreen:destroy()

    ok, result = manager:moveParty("B")
    assertTrue(ok, "first mapped-room move should succeed")
    assertTrue(not result.watchSpent, "first mapped-room transition should not spend a watch")
    assertEqual(manager:getWatchCount(), 0, "first mapped transition should not trigger Meatgrinder")
    assertEqual(crawlScenes[1].roomId, "B", "Crawl scene frames should use the entered room")
    assertEqual(crawlScenes[1].prompts.light, "What light do you have?",
        "Crawl scene frames should preserve the rulebook light prompt")
    assertEqual(crawlScenes[1].prompts.hands, "What do you have in your hands?",
        "Crawl scene frames should preserve the rulebook hands prompt")

    ok, result = manager:moveParty("C")
    assertTrue(ok, "second mapped-room move should succeed")
    assertTrue(result.watchSpent, "second mapped-room transition should spend a watch")
    assertEqual(manager:getWatchCount(), 1, "two mapped-room transitions should cost one watch")
    assertEqual(crawlScenes[2].roomId, "C", "watch-spending moves should emit a Crawl scene frame")
    assertEqual(crawlScenes[2].meatgrinderResults[1].category, watch_manager.MEATGRINDER.CURIOSITY,
        "Crawl scene frames should include the room-entry Meatgrinder result")
    assertTrue(crawlScenes[2].description:find("forgotten shrine", 1, true) ~= nil,
        "Crawl scene frames should include room description context")
    assertTrue(crawlScenes[2].description:find("distant echoes", 1, true) ~= nil,
        "Crawl scene frames should include Meatgrinder presentation context")
    assertEqual(result.crawlScene, crawlScenes[2],
        "moveParty should return the emitted Crawl scene frame for UI presentation")

    local function watchDeck(values)
        local index = 0
        return {
            draw = function()
                index = index + 1
                local value = values[index]
                if not value then
                    return nil
                end
                return {
                    name = "Major " .. tostring(value),
                    value = value,
                    is_major = true,
                }
            end,
            discard = function() end,
        }
    end

    local reasonBus = events.createEventBus()
    local watchEvents = {}
    reasonBus:on(events.EVENTS.WATCH_PASSED, function(data)
        watchEvents[#watchEvents + 1] = data
    end)
    local reasonManager = watch_manager.createWatchManager({
        eventBus = reasonBus,
        gmDeck = watchDeck({ 6, 11 }),
    })
    local longTaskWatch = reasonManager:spendWatchForLongTask("take a door off its hinges")
    assertEqual(longTaskWatch.reason, "long_task",
        "long tasks should record the rulebook reason a watch passed")
    assertEqual(longTaskWatch.longTask, "take a door off its hinges",
        "long-task watches should preserve the task description")
    assertEqual(watchEvents[1].longTask, "take a door off its hinges",
        "WATCH_PASSED should expose long-task metadata")

    local phaseWatch = reasonManager:spendWatchForPhase("challenge")
    assertEqual(phaseWatch.reason, "phase", "phase changes should record the rulebook watch reason")
    assertEqual(phaseWatch.phase, "challenge", "phase watches should preserve the phase name")
    assertEqual(watchEvents[2].phase, "challenge", "WATCH_PASSED should expose phase metadata")

    local overland_travel = require('logic.overland_travel')
    local overlandProcedure = overland_travel.getProcedure()
    assertEqual(overlandProcedure.watchesPerDay, 3,
        "Overland procedure metadata should preserve three watches per day")
    assertEqual(overlandProcedure.steps[1].key, "choose_action",
        "Overland procedure metadata should preserve the choose-action step")
    assertEqual(overlandProcedure.steps[2].key, "meatgrinder",
        "Overland procedure metadata should preserve the Meatgrinder draw step")
    assertEqual(overlandProcedure.steps[3].key, "set_scene",
        "Overland procedure metadata should preserve the set-scene step")
    assertEqual(overlandProcedure.exhaustion.effect, "Guild members become Exhausted until they Encamp again.",
        "Overland procedure metadata should preserve the no-Encamp exhaustion rule")
    overlandProcedure.steps[1].key = "invented_step"
    assertEqual(overland_travel.getProcedure().steps[1].key, "choose_action",
        "Overland procedure metadata should be copy-safe")
    local overlandActions = overland_travel.getActionDetails()
    assertEqual(overlandActions.travel.clearRoadBonusHexes, 1,
        "Overland action metadata should preserve clear-road travel bonus")
    assertEqual(overlandActions.travel.allRidingBonusHexes, 1,
        "Overland action metadata should preserve all-riding travel bonus")
    assertTrue(overlandActions.encamp.satisfiesDailyEncamp,
        "Overland action metadata should mark Encamp as satisfying daily rest")
    assertEqual(overland_travel.getActionDetails({ type = "scout_hex" }).key, "explore",
        "Overland action metadata should accept action aliases")
    local traveler = base_entity.createEntity({
        id = "pc_overland_traveler",
        name = "Overland Traveler",
        isPC = true,
    })
    traveler.inventory = inventory.createInventory()
    traveler.inventory:addItem(inventory.createItemFromTemplate("bow"), inventory.LOCATIONS.HANDS)
    local overlandBus = events.createEventBus()
    local daysEnded = {}
    local meatgrinderDraws = {}
    local sceneFrames = {}
    local encampReady = nil
    local overlandCampAction = nil
    local exhaustionEvents = 0
    overlandBus:on(overland_travel.EVENTS.DAY_ENDED, function(data)
        daysEnded[#daysEnded + 1] = data
    end)
    overlandBus:on(overland_travel.EVENTS.MEATGRINDER_DRAWN, function(data)
        meatgrinderDraws[#meatgrinderDraws + 1] = data
    end)
    overlandBus:on(overland_travel.EVENTS.SCENE_SET, function(data)
        sceneFrames[#sceneFrames + 1] = data
    end)
    overlandBus:on(overland_travel.EVENTS.ENCAMP_READY, function(data)
        encampReady = data
    end)
    overlandBus:on("camp_action_resolved", function(data)
        if data.action == "hunt" then
            overlandCampAction = data
        end
    end)
    overlandBus:on(overland_travel.EVENTS.EXHAUSTION_APPLIED, function(data)
        exhaustionEvents = exhaustionEvents + 1
        assertEqual(data.actors[1], traveler, "overland exhaustion should report affected guild members")
    end)

    local routedOverland = overland_travel.createOverlandTravelController({
        eventBus = events.createEventBus(),
        guild = { traveler },
        currentHex = "A",
        hexMap = {
            A = { roads = { B = true } },
            B = { roads = { C = true } },
            C = { neighbors = { D = true } },
            D = { neighbors = { E = true } },
            E = {},
        },
    })
    local routedOptions = routedOverland:getActionOptions({
        type = "travel",
        destinationHex = "C",
    })
    assertEqual(routedOptions.resultPreview, "overland_action_options_ready",
        "Overland action options should report non-mutating option readiness")
    assertEqual(routedOptions.options[5].key, overland_travel.ACTIONS.TRAVEL,
        "Overland action options should expose Travel as a canonical watch action")
    assertTrue(routedOptions.options[5].selected and not routedOptions.options[5].disabled,
        "Overland action options should flag selected valid Travel")
    assertEqual(routedOptions.travelOptions.distance, 2,
        "Overland action options should preview inferred clear-road route distance")
    assertTrue(routedOptions.travelOptions.clearRoad,
        "Overland action options should infer clear-road travel bonuses")
    assertTrue(routedOptions.travelOptions.route and routedOptions.travelOptions.route[1] == "A" and
        routedOptions.travelOptions.route[3] == "C",
        "Overland action options should preserve route previews")
    routedOptions.procedure.steps[1].key = "changed"
    assertEqual(routedOverland:getActionOptions({ type = "encamp" }).procedure.steps[1].key, "choose_action",
        "Overland action options should return copy-safe procedure metadata")
    local blockedRouteOptions = routedOverland:getActionOptions({
        type = "travel",
        destinationHex = "D",
    })
    assertTrue(blockedRouteOptions.selectedOption.disabled,
        "Overland action options should flag travel destinations beyond current range")
    assertEqual(blockedRouteOptions.travelOptions.unavailableReason, "Destination too far",
        "Overland action options should explain travel range gates")
    local mountedRouteOptions = routedOverland:getActionOptions({
        type = "travel",
        destinationHex = "D",
        clearRoad = true,
        allRiding = true,
    })
    assertTrue(not mountedRouteOptions.selectedOption.disabled,
        "Overland action options should preview clear-road plus mounted range bonuses")
    assertEqual(mountedRouteOptions.travelOptions.maxDistance, 3,
        "Overland action options should preserve the +1 road and +1 riding bonuses")

    local routeDetail = nil
    local ok, result = routedOverland:resolveAction({
        type = "travel",
        destinationHex = "C",
    })
    assertTrue(ok, "authored clear-road routes should infer two-hex Overland Travel")
    assertEqual(result, "overland_action_resolved", "routed Overland Travel should resolve")
    assertEqual(routedOverland.currentHex, "C", "routed Overland Travel should update current hex")
    ok, result, routeDetail = routedOverland:resolveAction({
        type = "travel",
        destinationHex = "E",
    })
    assertTrue(not ok, "non-road two-hex Overland Travel should require riding or explicit road")
    assertEqual(result, "Destination too far", "non-road routed Overland Travel should explain the distance gate")
    assertEqual(routedOverland.currentHex, "C", "failed routed Overland Travel should leave current hex unchanged")
    ok, result, routeDetail = routedOverland:resolveAction({
        type = "travel",
        destinationHex = "E",
        allRiding = true,
    })
    assertTrue(ok, "all-riding guilds should be able to travel two non-road hexes")
    assertEqual(routeDetail.distance, 2, "routed Overland Travel should report inferred route distance")
    assertTrue(routeDetail.route and routeDetail.route[1] == "C" and routeDetail.route[3] == "E",
        "routed Overland Travel should report the inferred hex path")

    local overlandDeck = {
        draw_pile = {
            { name = "XV Travel", value = 15, is_major = true },
            { name = "XXI Quest Rumor", value = 21, is_major = true },
            { name = "I Torches Gutter", value = 1, is_major = true },
            { name = "VI Curiosity", value = 6, is_major = true },
            { name = "XVI Random Encounter", value = 16, is_major = true },
            { name = "XI Travel Event", value = 11, is_major = true },
        },
        discarded = {},
        draw = function(self)
            return table.remove(self.draw_pile)
        end,
        discard = function(self, card)
            self.discarded[#self.discarded + 1] = card
        end,
    }

    local overland = overland_travel.createOverlandTravelController({
        eventBus = overlandBus,
        guild = { traveler },
        currentHex = "A",
        hexMap = {
            C = {
                terrain = "misty moor",
                notableFeatures = {
                    { id = "wayside_shrine", name = "Wayside Shrine", type = "feature" },
                },
                lairs = { "wolf den" },
                spoor = { "ogre tracks" },
            },
        },
        gmDeck = overlandDeck,
        meatgrinder = meatgrinder.createMeatgrinder({ eventBus = overlandBus }),
    })
    ok, result = overland:resolveAction({
        type = "travel",
        destinationHex = "C",
        distance = 2,
    })
    assertTrue(not ok, "Overland Travel should not move two hexes without roads or mounts")
    assertEqual(result, "Destination too far", "failed Overland Travel should explain the distance gate")
    assertEqual(overland.currentHex, "A", "failed Overland Travel should leave the guild in place")

    ok, result = overland:resolveAction({
        type = "travel",
        destinationHex = "C",
        distance = 2,
        clearRoad = true,
    })
    assertTrue(ok, "clear roads should allow an extra overland hex")
    assertEqual(result, "overland_action_resolved", "successful overland actions should report resolution")
    assertEqual(overland.currentHex, "C", "successful Overland Travel should update the current hex")
    assertEqual(overland.currentWatch, 1, "one overland action should spend one watch")
    assertEqual(meatgrinderDraws[1].draw.category, meatgrinder.CATEGORIES.TRAVEL_EVENT,
        "each overland watch should draw and categorize a Meatgrinder card")
    assertEqual(sceneFrames[1].hex, "C",
        "overland scene frames should use the post-action hex context")
    assertTrue(sceneFrames[1].description and sceneFrames[1].description ~= "",
        "overland scene frames should carry Meatgrinder presentation text")
    local exploreOptions = overland:getActionOptions({ type = "explore" })
    assertEqual(exploreOptions.currentHex, "C",
        "Overland action options should preserve current hex state")
    assertEqual(exploreOptions.exploreOptions.terrain, "misty moor",
        "Overland action options should preview authored hex terrain")
    assertEqual(exploreOptions.exploreOptions.features[1].id, "wayside_shrine",
        "Overland action options should preview discoverable hex features")

    local overlandDetail
    ok, result, overlandDetail = overland:resolveAction({ type = "explore" })
    assertTrue(ok, "Explore should resolve as an overland watch action")
    assertEqual(overlandDetail.terrain, "misty moor",
        "Explore should expose authored terrain from the current hex")
    assertEqual(overlandDetail.features[1].id, "wayside_shrine",
        "Explore should expose authored notable features from the current hex")
    assertEqual(overlandDetail.spoor[1], "ogre tracks",
        "Explore should expose authored spoor from the current hex")
    local interactOptions = overland:getActionOptions({
        type = "interact",
        featureId = "wayside_shrine",
        mode = "pray",
    })
    assertTrue(interactOptions.dayWillEndAfterAction,
        "Overland action options should preview day-end timing before the third watch")
    assertTrue(interactOptions.missingEncampWouldExhaust,
        "Overland action options should preview the missing-Encamp exhaustion risk")
    assertEqual(interactOptions.interactOptions.selectedFeature.name, "Wayside Shrine",
        "Overland action options should preview selected Interact features")
    assertEqual(interactOptions.interactOptions.mode, "pray",
        "Overland action options should preserve selected interaction modes")
    local staticOptions = overland_travel.getActionOptions({
        currentHex = "A",
        type = "camp_action",
        actor = traveler,
        campAction = "hunt",
    })
    assertTrue(staticOptions.campActionOptions.actions[1] ~= nil,
        "Overland action options should expose Camp Action choices")
    assertTrue(not staticOptions.selectedOption.disabled,
        "Overland action options should preview configured Camp Action readiness")
    ok, result, overlandDetail = overland:resolveAction({
        type = "interact",
        featureId = "wayside_shrine",
        mode = "pray",
    })
    assertTrue(ok, "Interact should resolve as an overland watch action")
    assertEqual(overlandDetail.feature.name, "Wayside Shrine",
        "Interact should resolve selected authored hex features")
    assertEqual(overlandDetail.interaction.mode, "pray",
        "Interact should preserve the selected interaction mode")
    assertEqual(#daysEnded, 1, "three overland watches should end the day")
    assertTrue(daysEnded[1].encamped == false, "day-end audit should record missing Encamp")
    assertTrue(traveler.conditions.exhausted and traveler.overlandExhausted,
        "failing to Encamp once per day should mark guild members Exhausted")
    assertEqual(exhaustionEvents, 1, "missing daily Encamp should emit one exhaustion event")

    ok, result = overland:resolveAction({
        type = "encamp",
        campController = {
            getState = function()
                return camp_controller.STATES.INACTIVE
            end,
            startCamp = function()
                return false, "camp_unavailable"
            end,
        },
    })
    assertTrue(not ok, "failed Encamp CampController handoff should reject the overland action")
    assertEqual(result, "camp_unavailable", "failed Encamp should report the CampController failure")
    assertTrue(not overland.didEncampToday, "failed Encamp should not satisfy the daily overland Encamp requirement")
    assertTrue(traveler.conditions.exhausted and traveler.overlandExhausted,
        "failed Encamp should not clear overland Exhausted")
    assertEqual(overland.currentWatch, 0, "failed Encamp should not spend an overland watch")
    assertEqual(encampReady, nil, "failed Encamp should not emit the Camp handoff event")

    local encampDetail
    ok, result, encampDetail = overland:resolveAction({ type = "encamp" })
    assertTrue(ok, "Encamp should resolve as an overland action")
    assertTrue(not traveler.conditions.exhausted and not traveler.overlandExhausted,
        "Encamp should clear overland-sourced Exhausted")
    assertEqual(overland.currentWatch, 1, "Encamp should still spend one overland watch")
    assertEqual(encampDetail.campState, camp_controller.STATES.BREAK_BREAD,
        "Encamp should hand off to Camp Phase step 2 after overland Camp Actions are separated")
    assertTrue(encampReady and encampReady.steps[1] == "break_bread",
        "Encamp should emit the Camp steps 2-5 handoff for UI/controller integration")

    ok = overland:resolveAction({
        type = "travel",
        destinationHex = "F",
        distance = 3,
        clearRoad = true,
        allRiding = true,
    })
    assertTrue(ok, "clear roads plus an all-mounted guild should allow three-hex overland travel")
    ok, result = overland:resolveAction({
        type = "camp_action",
        campActions = {
            { actor = traveler, campAction = "hunt" },
            { actor = traveler, campAction = "hunt" },
        },
    })
    assertTrue(not ok, "duplicate Overland Camp Action actors should be rejected before resolution")
    assertEqual(result, "Action already taken",
        "duplicate Overland Camp Action actors should use the Camp Action accounting failure")
    assertEqual(overland.currentWatch, 2, "failed Overland Camp Action batches should not spend a watch")
    assertEqual(overlandCampAction, nil,
        "failed Overland Camp Action preflight should not emit delegated Camp Action events")
    ok, result, encampDetail = overland:resolveAction({
        type = "camp_action",
        actor = traveler,
        campAction = "hunt",
    })
    assertTrue(ok, "Camp Action should resolve in the optional overland watch loop")
    assertEqual(encampDetail.campActionResults[1].campResult, "hunt_initiated",
        "Overland Camp Action should delegate to the concrete Camp Action resolver")
    assertTrue(overlandCampAction and overlandCampAction.action == "hunt",
        "Overland Camp Action should preserve Camp Action event emission")
    assertEqual(#daysEnded, 2, "the second overland day should end after three more watches")
    assertTrue(daysEnded[2].encamped, "Encamp should satisfy the once-per-day overland requirement")
    assertTrue(not traveler.conditions.exhausted, "an overland day with Encamp should not Exhaust the guild")
    assertEqual(#meatgrinderDraws, 6,
        "each successful overland watch action should produce one Meatgrinder draw")
    assertEqual(#overlandDeck.discarded, 6,
        "overland Meatgrinder draws should discard the drawn major cards")
end

local function checkLoudNoiseMeatgrinderThreshold()
    local function deckFor(values)
        local index = 0
        local discarded = {}
        return {
            discarded = discarded,
            draw = function()
                index = index + 1
                local value = values[index]
                if not value then
                    return nil
                end
                return {
                    name = "Major " .. tostring(value),
                    value = value,
                    is_major = true,
                }
            end,
            discard = function(_, card)
                discarded[#discarded + 1] = card
            end,
        }
    end

    local function checkValue(value)
        local bus = events.createEventBus()
        local randomEncounters = 0
        local meatgrinderRolls = 0
        local travelEvents = 0
        local torchesGutter = 0
        bus:on(events.EVENTS.MEATGRINDER_ROLL, function()
            meatgrinderRolls = meatgrinderRolls + 1
        end)
        bus:on(events.EVENTS.RANDOM_ENCOUNTER, function(data)
            randomEncounters = randomEncounters + 1
            assertEqual(data.category, watch_manager.MEATGRINDER.RANDOM_ENCOUNTER,
                "loud-noise random encounter event should report random_encounter")
        end)
        bus:on(events.EVENTS.TRAVEL_EVENT, function()
            travelEvents = travelEvents + 1
        end)
        bus:on(events.EVENTS.TORCHES_GUTTER, function()
            torchesGutter = torchesGutter + 1
        end)

        local gmDeck = deckFor({ value })
        local manager = watch_manager.createWatchManager({
            gmDeck = gmDeck,
            eventBus = bus,
        })

        local result = manager:checkLoudNoise()
        return result, {
            randomEncounters = randomEncounters,
            meatgrinderRolls = meatgrinderRolls,
            travelEvents = travelEvents,
            torchesGutter = torchesGutter,
            discarded = gmDeck.discarded,
        }
    end

    local fifteenth, fifteenthEvents = checkValue(15)
    assertTrue(fifteenth.triggered, "loud noise should trigger an encounter on XV")
    assertEqual(fifteenth.result.category, watch_manager.MEATGRINDER.RANDOM_ENCOUNTER,
        "loud noise should treat XV as a random encounter")
    assertEqual(fifteenth.result.normalCategory, watch_manager.MEATGRINDER.TRAVEL_EVENT,
        "loud noise should preserve the normal XV Meatgrinder category")
    assertEqual(fifteenthEvents.randomEncounters, 1, "loud noise XV should emit a random encounter")
    assertEqual(fifteenthEvents.meatgrinderRolls, 1, "triggered loud-noise draws should emit one Meatgrinder roll")
    assertEqual(fifteenthEvents.travelEvents, 0, "loud noise XV should not emit its normal travel event")
    assertEqual(#fifteenthEvents.discarded, 1, "loud noise draws should still discard the major card")

    local fourteenth, fourteenthEvents = checkValue(14)
    assertTrue(not fourteenth.triggered, "loud noise should not trigger an encounter on XIV")
    assertEqual(fourteenth.result.category, watch_manager.MEATGRINDER.TRAVEL_EVENT,
        "ordinary XIV loud-noise draws should retain the travel-event category")
    assertTrue(fourteenth.result.ignoredByLoudNoise,
        "non-triggering loud-noise draws should be auditable as ignored")
    assertEqual(fourteenthEvents.randomEncounters, 0, "loud noise XIV should not emit a random encounter")
    assertEqual(fourteenthEvents.meatgrinderRolls, 0, "ignored loud-noise draws should not emit Meatgrinder rolls")
    assertEqual(fourteenthEvents.travelEvents, 0, "ignored loud-noise draws should not emit travel events")

    local gutter, gutterEvents = checkValue(5)
    assertTrue(not gutter.triggered, "loud noise should ignore torches-gutter draws")
    assertTrue(gutter.result.ignoredByLoudNoise,
        "ignored torches-gutter loud-noise draws should remain auditable")
    assertEqual(gutterEvents.torchesGutter, 0,
        "ignored loud-noise torches-gutter draws should not flicker lights")

    local twentieth, twentiethEvents = checkValue(20)
    assertTrue(twentieth.triggered, "loud noise should trigger an encounter on XX")
    assertEqual(twentieth.result.category, watch_manager.MEATGRINDER.RANDOM_ENCOUNTER,
        "loud noise XX should remain a random encounter")
    assertEqual(twentiethEvents.randomEncounters, 1, "loud noise XX should emit one random encounter")
    assertEqual(twentiethEvents.meatgrinderRolls, 1, "loud noise XX should emit one Meatgrinder roll")
end

local function checkMeatgrinderTorchesGutterNotConsumed()
    local room = { id = "torch_test_room", name = "Torch Test Room" }
    local grinder = meatgrinder.createMeatgrinder({
        eventBus = events.createEventBus(),
    })

    local firstGutter = grinder:resolveByValue(1, room, {})
    local secondGutter = grinder:resolveByValue(1, room, {})
    assertEqual(firstGutter.category, meatgrinder.CATEGORIES.TORCHES_GUTTER,
        "I should resolve as torches gutter")
    assertEqual(secondGutter.category, meatgrinder.CATEGORIES.TORCHES_GUTTER,
        "repeated torches gutter should still resolve as torches gutter")
    assertTrue(not firstGutter.consumed and not secondGutter.consumed,
        "torches gutter results should not be marked consumed")
    assertTrue(not grinder:isConsumed(meatgrinder.CATEGORIES.TORCHES_GUTTER, room.id),
        "torches gutter should not be marked off on the Meatgrinder")
    assertEqual(#grinder:getConsumedEvents(), 0,
        "torches gutter should not appear in consumed Meatgrinder events")
    assertTrue(not hasValue((secondGutter.effects or {}), "respite"),
        "repeated torches gutter should not turn into respite")

    local curiosity = grinder:resolveByValue(6, room, {})
    local differentCuriosity = grinder:resolveByValue(7, room, {})
    local repeatedCuriosity = grinder:resolveByValue(6, room, {})
    assertTrue(curiosity.consumed, "non-gutter Meatgrinder entries should be marked consumed")
    assertTrue(grinder:isConsumed(meatgrinder.CATEGORIES.CURIOSITY, room.id),
        "curiosity should be marked off on the Meatgrinder")
    assertTrue(grinder:isConsumed(meatgrinder.CATEGORIES.CURIOSITY, room.id, 6),
        "specific curiosity entries should be marked off by card value")
    assertTrue(not grinder:isConsumed(meatgrinder.CATEGORIES.CURIOSITY, room.id, 8),
        "other curiosity entries should remain available until their own card is drawn")
    assertTrue(differentCuriosity.consumed,
        "a different card in the same category should resolve as its own Meatgrinder entry")
    assertEqual(differentCuriosity.category, meatgrinder.CATEGORIES.CURIOSITY,
        "different same-category cards should not be converted to respite")
    assertTrue(differentCuriosity.effects[1] == nil or differentCuriosity.effects[1].type ~= "respite",
        "different same-category cards should not produce respite")
    assertTrue(repeatedCuriosity.consumed, "repeated non-gutter entries should report consumed respite")
    assertEqual(repeatedCuriosity.effects[1].type, "respite",
        "repeated non-gutter entries should produce a watch of respite")

    local droppings = grinder:resolveByValue(11, room, {})
    assertEqual(droppings.effects[1].type, "droppings",
        "default Meatgrinder XI should preserve the Droppings travel event")
    assertEqual(droppings.effects[1].target, "first_in_marching_order",
        "Droppings should target the first marcher")
    assertTrue(droppings.effects[1].stressIfUnclean,
        "Droppings should record the cleanup-or-Stress consequence")
    assertEqual(droppings.effects[1].sourceCreature, "ogre",
        "Droppings investigation should reveal fresh ogre spoor")

    local river = grinder:resolveByValue(12, room, {})
    assertEqual(river.effects[1].type, "rushing_river",
        "default Meatgrinder XII should preserve the Rushing River travel event")
    assertEqual(river.effects[1].attribute, "swords",
        "Rushing River crossing should call for a Swords test")
    assertEqual(river.effects[1].stressTarget, "crossers",
        "Rushing River should stress adventurers who brave the cold water")
    assertTrue(river.effects[1].destroysFragilePackItems,
        "Rushing River should record fragile pack item destruction")

    local hole = grinder:resolveByValue(13, room, {})
    assertEqual(hole.effects[1].type, "hole_in_pack",
        "default Meatgrinder XIII should preserve the Hole in Pack travel event")
    assertEqual(hole.effects[1].lostItem, "last_listed_pack_item",
        "Hole in Pack should lose the last listed pack item")
    assertTrue(hole.effects[1].backtrackingCostsWatches,
        "Hole in Pack should record the extra-watch backtracking cost")

    local badScene = grinder:resolveByValue(14, room, {})
    assertEqual(badScene.effects[1].type, "bad_scene",
        "default Meatgrinder XIV should preserve the Bad Scene travel event")
    assertTrue(badScene.effects[1].poisonousMushrooms and badScene.effects[1].chestHazard,
        "Bad Scene should preserve mushroom and chest hazards")
    assertEqual(badScene.effects[1].corpseHazard, "zombie",
        "Bad Scene should preserve the zombie corpse hazard")

    local webs = grinder:resolveByValue(15, room, {})
    assertEqual(webs.effects[1].type, "webs",
        "default Meatgrinder XV should preserve the Webs travel event")
    assertTrue(webs.effects[1].blocksPath and webs.effects[1].visibleHangingSacks,
        "Webs should record the blocked path and visible hanging sacks")

    local traveler = base_entity.createEntity({
        id = "pc_travel_stress",
        name = "Travel Stress",
        isPC = true,
    })
    local travelBus = events.createEventBus()
    local travelHook = nil
    travelBus:on("travel_event_check", function(data)
        travelHook = data
    end)
    local environment = environment_manager.createEnvironmentManager({
        eventBus = travelBus,
        guild = { traveler },
    })
    environment:init()
    travelBus:emit(events.EVENTS.TRAVEL_EVENT, {
        value = 14,
        effects = {
            {
                type = "stress_all",
                stressReason = environment_manager.STRESS_REASONS.TERRIFYING,
            },
        },
    })
    assertTrue(traveler.conditions.stressed, "structured travel events should apply explicit party Stress")
    assertEqual(travelHook.stressApplications[1].count, 1,
        "travel-event Stress hook should report newly Stressed adventurers")
    assertEqual(travelHook.stressChance, nil,
        "travel-event Stress should come from structured effects instead of card-value probability")

    local defaultEncounter = grinder:resolveByValue(16, { id = "default_random_room" }, {})
    assertEqual(defaultEncounter.category, meatgrinder.CATEGORIES.RANDOM_ENCOUNTER,
        "XVI should still resolve as a random encounter")
    assertEqual(#defaultEncounter.spawns, 0,
        "default Meatgrinder random encounters should not spawn a non-authored generic monster")
    assertEqual(defaultEncounter.effects[2].type, "gm_authored_random_encounter_required",
        "default Meatgrinder random encounters should ask for authored local scenario content")

    local configuredEncounter = grinder:resolveByValue(17, {
        id = "configured_random_room",
        randomEncounter = {
            blueprint_id = "slime",
            count = 2,
            description = "Two slimes bubble out of the garbage pit.",
        },
    }, {})
    assertEqual(configuredEncounter.spawns[1].blueprint_id, "slime",
        "configured default random encounters should normalize blueprint spawns")
    assertEqual(configuredEncounter.spawns[1].count, 2,
        "configured default random encounters should preserve authored counts")

    local function watchDeck(values)
        local index = 0
        local discarded = {}
        return {
            discarded = discarded,
            draw = function()
                index = index + 1
                local value = values[index]
                if not value then
                    return nil
                end
                return {
                    name = "Major " .. tostring(value),
                    value = value,
                    is_major = true,
                }
            end,
            discard = function(_, card)
                discarded[#discarded + 1] = card
            end,
        }
    end

    local ignoredCarefulBus = events.createEventBus()
    local ignoredEncounterEvents = 0
    local ignoredMeatgrinderEvents = 0
    ignoredCarefulBus:on(events.EVENTS.RANDOM_ENCOUNTER, function()
        ignoredEncounterEvents = ignoredEncounterEvents + 1
    end)
    ignoredCarefulBus:on(events.EVENTS.MEATGRINDER_ROLL, function()
        ignoredMeatgrinderEvents = ignoredMeatgrinderEvents + 1
    end)
    local ignoredDeck = watchDeck({ 6, 16 })
    local ignoredManager = watch_manager.createWatchManager({
        gmDeck = ignoredDeck,
        eventBus = ignoredCarefulBus,
    })
    local ignoredCareful = ignoredManager:incrementWatch({ careful = true })
    assertEqual(#ignoredCareful.meatgrinderResults, 1,
        "moving carefully should keep only the first draw when the second draw is not torches gutter")
    assertTrue(ignoredCareful.carefulIgnoredDraw.ignoredByMovingCarefully,
        "moving carefully should audit ignored non-gutter second draws")
    assertEqual(ignoredCareful.carefulIgnoredDraw.category, watch_manager.MEATGRINDER.RANDOM_ENCOUNTER,
        "moving carefully should preserve the ignored second draw category")
    assertEqual(ignoredEncounterEvents, 0,
        "ignored moving-carefully random encounters should not emit encounter events")
    assertEqual(ignoredMeatgrinderEvents, 1,
        "ignored moving-carefully draws should not emit general Meatgrinder events")
    assertEqual(#ignoredDeck.discarded, 2,
        "moving carefully should still draw and discard the ignored second card")

    local keptCarefulBus = events.createEventBus()
    local keptTorchEvents = 0
    keptCarefulBus:on(events.EVENTS.TORCHES_GUTTER, function()
        keptTorchEvents = keptTorchEvents + 1
    end)
    local keptDeck = watchDeck({ 6, 5 })
    local keptManager = watch_manager.createWatchManager({
        gmDeck = keptDeck,
        eventBus = keptCarefulBus,
    })
    local keptCareful = keptManager:incrementWatch({ careful = true })
    assertEqual(#keptCareful.meatgrinderResults, 2,
        "moving carefully should keep a second torches-gutter draw")
    assertTrue(keptCareful.carefulTorchesGutter,
        "moving carefully should mark when the second draw keeps torches guttering")
    assertEqual(keptTorchEvents, 1,
        "kept moving-carefully torches-gutter draws should emit torches-gutter events")
end

function checkAuthoredTombMeatgrinderRuntime()
    local grinder = meatgrinder.createMeatgrinder({
        eventBus = events.createEventBus(),
    })
    grinder:registerTable(tomb_data.meatgrinder)

    local room = { id = "tomb_runtime_room", name = "Runtime Tomb Room" }
    local fewmets = grinder:resolveByValue(8, room, {})
    assertEqual(fewmets.category, meatgrinder.CATEGORIES.CURIOSITY,
        "Tomb VIII should resolve as a curiosity")
    assertEqual(fewmets.raw.loreReveal, "centipede_scat",
        "Tomb VIII should retain authored fewmets lore metadata")

    local trapWebs = grinder:resolveByValue(14, room, {})
    assertEqual(trapWebs.category, meatgrinder.CATEGORIES.TRAVEL_EVENT,
        "Tomb XIV should resolve as a travel event")
    assertEqual(trapWebs.effects[1].type, "trap_webs",
        "Tomb XIV should normalize authored effect metadata")
    assertEqual(trapWebs.raw.failure, "pulled_feet_first_20_feet_into_air",
        "Tomb XIV should retain trap-web failure metadata")

    local repeatedTrapWebs = grinder:resolveByValue(14, room, {})
    assertEqual(repeatedTrapWebs.effects[1].type, "respite",
        "repeated authored non-gutter entries should use Meatgrinder respite")

    local puppetMummies = grinder:resolveByValue(16, { id = "tomb_runtime_puppet_room" }, {})
    assertEqual(puppetMummies.spawns[1].blueprint_id, "puppet_mummy",
        "Tomb XVI should expose puppet-mummy spawn metadata")
    assertEqual(puppetMummies.raw.controller_blueprint_id, "brain_spider_kodi",
        "Tomb XVI should retain Kodi controller metadata")

    local rivals = grinder:resolveByValue(19, { id = "tomb_runtime_rivals_room" }, {})
    assertEqual(rivals.raw.rivals[1].name, "Finch",
        "Tomb XIX should retain named rival adventurers")
    assertEqual(rivals.raw.rescueRewards[1], "signet_ring_20",
        "Tomb XIX should retain rescue reward metadata")

    local rumor = grinder:resolveByValue(21, { id = "tomb_runtime_quest_room" }, {})
    assertTrue(rumor.description:find("next step") ~= nil,
        "Tomb XXI should resolve the authored quest-rumor clue")

    local function deckFor(values)
        local index = 0
        local discarded = {}
        return {
            discarded = discarded,
            draw = function()
                index = index + 1
                local value = values[index]
                if not value then
                    return nil
                end
                return {
                    name = "Major " .. tostring(value),
                    value = value,
                    is_major = true,
                }
            end,
            discard = function(_, card)
                discarded[#discarded + 1] = card
            end,
        }
    end

    local bus = events.createEventBus()
    local meatgrinderRolls = {}
    local randomEncounters = {}
    bus:on(events.EVENTS.MEATGRINDER_ROLL, function(data)
        meatgrinderRolls[#meatgrinderRolls + 1] = data
    end)
    bus:on(events.EVENTS.RANDOM_ENCOUNTER, function(data)
        randomEncounters[#randomEncounters + 1] = data
    end)

    local gmDeck = deckFor({ 8, 8, 16 })
    local manager = watch_manager.createWatchManager({
        gmDeck = gmDeck,
        eventBus = bus,
        startingRoom = "105_hall_of_webs",
        meatgrinderTable = tomb_data.meatgrinder,
    })

    local firstFewmets = manager:drawMeatgrinder()
    assertEqual(firstFewmets.description, "The ground here is strewn with gross black fewmets.",
        "WatchManager should surface authored Tomb Meatgrinder descriptions")
    assertEqual(firstFewmets.raw.loreReveal, "centipede_scat",
        "WatchManager should carry authored raw Meatgrinder metadata")
    assertEqual(#meatgrinderRolls, 1,
        "WatchManager should emit one Meatgrinder roll for an authored draw")

    local secondFewmets = manager:drawMeatgrinder()
    assertEqual(secondFewmets.effects[1].type, "respite",
        "WatchManager should route repeated authored entries through Meatgrinder consumption")
    assertEqual(#meatgrinderRolls, 2,
        "adapted Meatgrinder resolution should not double-emit roll events")

    local puppetDraw = manager:drawMeatgrinder()
    assertEqual(puppetDraw.spawns[1].blueprint_id, "puppet_mummy",
        "WatchManager should expose authored random-encounter spawns")
    assertEqual(puppetDraw.raw.controllerHiddenByIllusion, true,
        "WatchManager should preserve authored random-encounter metadata")
    assertEqual(#randomEncounters, 1,
        "WatchManager should emit random-encounter events for authored random encounters")
    assertEqual(randomEncounters[1].description, puppetDraw.description,
        "random-encounter event should use the enriched authored draw")
    assertEqual(#gmDeck.discarded, 3,
        "authored Meatgrinder draws should still discard GM deck cards")
end

local function checkCampHuntAction()
    local actor = base_entity.createEntity({
        id = "pc_hunter",
        name = "Hunter",
        isPC = true,
    })
    actor.inventory = inventory.createInventory()
    actor.inventory:addItem(inventory.createItemFromTemplate("bow"), inventory.LOCATIONS.PACK)

    local available = camp_actions.getAvailableActions(actor, { actor })
    local sawHunt = false
    for _, action in ipairs(available) do
        if action.id == "hunt" then
            sawHunt = true
            break
        end
    end
    assertTrue(sawHunt, "Hunt should be available to a PC carrying a missile weapon")
    local function campOutcomeById(list, outcome)
        for _, option in ipairs(list or {}) do
            if option.outcome == outcome then
                return option
            end
        end
        return nil
    end
    local huntOutcomeOptions = camp_actions.getHuntOutcomeOptions(actor, {}, {
        outcome = "great_success",
    })
    assertEqual(huntOutcomeOptions.result, "hunt_outcome_options_ready",
        "Hunt helper should return structured outcome option data")
    assertEqual(huntOutcomeOptions.method, "missile",
        "Hunt helper should expose the missile hunting method")
    assertEqual(huntOutcomeOptions.testSuit, "swords",
        "Hunt helper should expose the Swords test")
    assertEqual(huntOutcomeOptions.selectedOutcome.resultPreview, "large_game_found",
        "Hunt helper should expose the selected outcome preview")
    assertEqual(campOutcomeById(huntOutcomeOptions.outcomeOptions, "success").itemPreview.templateId, "fresh_game",
        "Hunt helper should preview ordinary fresh game")
    assertEqual(campOutcomeById(huntOutcomeOptions.outcomeOptions, "great_success").itemPreview.templateId,
        "fresh_game_feast", "Hunt helper should preview large fresh game")
    campOutcomeById(huntOutcomeOptions.outcomeOptions, "success").itemPreview.name = "Mutated Game"
    local refreshedHuntOptions = camp_actions.getHuntOutcomeOptions(actor, {}, {
        outcome = "success",
    })
    assertEqual(campOutcomeById(refreshedHuntOptions.outcomeOptions, "success").itemPreview.name, "Fresh Game",
        "Hunt helper should return copy-safe item preview data")

    local bus = events.createEventBus()
    local initiated = nil
    bus:on("camp_action_resolved", function(data)
        if data.action == "hunt" and data.result == "hunt_initiated" then
            initiated = data
        end
    end)

    local ok, result = camp_actions.resolveHunt(actor, {}, bus)
    assertTrue(ok, "Hunt should start for a missile-weapon user")
    assertEqual(result, "hunt_initiated", "Hunt should report test initiation")
    assertTrue(initiated and initiated.requiresTest, "Hunt should request a test")
    assertEqual(initiated.testSuit, "swords", "Hunt should test Swords")

    local fisher = base_entity.createEntity({
        id = "pc_fisher",
        name = "Fisher",
        isPC = true,
    })
    fisher.inventory = inventory.createInventory()
    fisher.inventory:addItem(inventory.createItemFromTemplate("fishing_gear"), inventory.LOCATIONS.PACK)
    local waterContext = {
        currentRoom = {
            id = "boundless_moat_bank",
            name = "Boundless Moat Bank",
            properties = { bodyOfWater = true },
        },
    }
    local fishingAvailable = camp_actions.getAvailableActions(fisher, { fisher }, waterContext)
    local sawFishingHunt = false
    for _, action in ipairs(fishingAvailable) do
        if action.id == "hunt" then
            sawFishingHunt = true
            break
        end
    end
    assertTrue(sawFishingHunt, "Hunt should be available to a PC carrying fishing gear at water")
    local fishingOptions = camp_actions.getHuntOutcomeOptions(fisher, waterContext)
    assertEqual(fishingOptions.method, "fishing",
        "Hunt helper should expose the fishing method at water")
    assertTrue(not fishingOptions.disabled,
        "Hunt helper should allow fishing gear at water")

    local fishingInitiated = nil
    local fishBus = events.createEventBus()
    fishBus:on("camp_action_resolved", function(data)
        if data.action == "hunt" and data.result == "hunt_initiated" then
            fishingInitiated = data
        end
    end)
    ok, result = camp_actions.resolveHunt(fisher, waterContext, fishBus)
    assertTrue(ok, "Fishing gear at water should start the Hunt food-gathering action")
    assertEqual(result, "hunt_initiated", "fishing Hunt should report test initiation")
    assertEqual(fishingInitiated.method, "fishing", "fishing Hunt should record its method")

    ok, result = camp_actions.resolveHuntOutcome(fisher, "success", waterContext, events.createEventBus())
    assertTrue(ok, "successful fishing should produce fresh food")
    assertEqual(result, "fresh_game_found", "successful fishing should share the fresh-game result")
    local fishGame = fisher.inventory:findItemByPredicate(function(item)
        return item.properties and item.properties.gatheredByFishing
    end)
    assertTrue(fishGame ~= nil, "fishing should mark the gathered fresh food")

    local dryFisher = base_entity.createEntity({
        id = "pc_dry_fisher",
        name = "Dry Fisher",
        isPC = true,
    })
    dryFisher.inventory = inventory.createInventory()
    dryFisher.inventory:addItem(inventory.createItemFromTemplate("fishing_gear"), inventory.LOCATIONS.PACK)
    local dryFishingOptions = camp_actions.getHuntOutcomeOptions(dryFisher, {
        currentRoom = { id = "dry_corridor" },
    })
    assertTrue(dryFishingOptions.disabled,
        "Hunt helper should disable fishing gear away from water")
    assertEqual(dryFishingOptions.unavailableReasons[1], "Requires a body of water",
        "Hunt helper should explain dry fishing")
    ok, result = camp_actions.resolveHunt(dryFisher, { currentRoom = { id = "dry_corridor" } }, events.createEventBus())
    assertTrue(not ok, "fishing gear should not hunt without a body of water")
    assertEqual(result, "Requires a body of water", "dry fishing should explain the water requirement")

    ok, result = camp_actions.resolveHuntOutcome(actor, "success", {}, events.createEventBus())
    assertTrue(ok, "successful Hunt should produce fresh game")
    assertEqual(result, "fresh_game_found", "successful Hunt should report fresh game")
    local freshGame = actor.inventory:findItemByPredicate(function(item)
        return item.properties and item.properties.freshGame
    end)
    assertTrue(freshGame ~= nil, "successful Hunt should add fresh game to inventory")
    assertTrue(not freshGame.isRation, "fresh game should not be treated as an automatic ration")
    assertTrue(freshGame.properties.requiresCookingGear, "fresh game should require cooking gear to eat")
    assertTrue(freshGame.properties.preservableWithSalt, "fresh game should record salt preservation requirement")

    local salt = inventory.createItemFromTemplate("salt", { quantity = 2 })
    actor.inventory:addItem(salt, inventory.LOCATIONS.PACK)
    ok, result = camp_actions.resolvePreserveHuntedGame(actor, freshGame, {}, events.createEventBus())
    assertTrue(ok, "salt should preserve fresh game into rations")
    assertEqual(result, "game_preserved", "preserving hunted game should report preserved result")
    assertEqual(salt.quantity, 1, "preserving hunted game should consume one salt")
    assertTrue(actor.inventory:findItem(freshGame.id) == nil, "preserved fresh game should be removed")
    local preservedRation = actor.inventory:findItemByPredicate(function(item)
        return item.isRation
    end)
    assertTrue(preservedRation ~= nil, "preserved fresh game should add rations")
    assertEqual(preservedRation.quantity, 1, "ordinary fresh game should preserve into one ration")

    local rawGamePC = base_entity.createEntity({
        id = "pc_raw_game",
        name = "Raw Game",
        isPC = true,
    })
    rawGamePC.inventory = inventory.createInventory()
    local rawGame = inventory.createItemFromTemplate("fresh_game")
    rawGamePC.inventory:addItem(rawGame, inventory.LOCATIONS.PACK)
    local rawGameCamp = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { rawGamePC },
    })
    rawGameCamp:transitionTo(camp_controller.STATES.BREAK_BREAD)
    ok, result = rawGameCamp:consumeRation(rawGamePC)
    assertTrue(not ok, "uncooked fresh game should not satisfy Break Bread")
    assertEqual(result, "no_ration", "uncooked fresh game should not count as a meal")
    assertTrue(rawGamePC.inventory:findItem(rawGame.id) ~= nil, "uncooked fresh game should remain after failed meal")

    local cookActor = base_entity.createEntity({
        id = "pc_cook_hunter",
        name = "Cook Hunter",
        isPC = true,
    })
    cookActor.inventory = inventory.createInventory()
    local cookGame = inventory.createItemFromTemplate("fresh_game")
    cookActor.inventory:addItem(cookGame, inventory.LOCATIONS.PACK)
    ok, result = camp_actions.resolveCookHuntedGame(cookActor, cookGame, {}, events.createEventBus())
    assertTrue(not ok, "cooking hunted game should require cooking gear")
    assertEqual(result, "Requires cooking gear", "missing cooking gear should explain cooking failure")
    cookActor.inventory:addItem(inventory.createItemFromTemplate("cooking_gear"), inventory.LOCATIONS.PACK)
    ok, result = camp_actions.resolveCookHuntedGame(cookActor, cookGame, {}, events.createEventBus())
    assertTrue(ok, "cooking gear should prepare hunted game for Break Bread")
    assertEqual(result, "game_cooked", "cooking hunted game should report cooked result")
    assertTrue(cookActor.inventory:findItem(cookGame.id) == nil, "cooked fresh game should be removed")
    local cookedMeal = cookActor.inventory:findItemByPredicate(function(item)
        return item.properties and item.properties.isCampMeal
    end)
    assertTrue(cookedMeal ~= nil, "cooked hunted game should add a camp meal")
    assertTrue(not cookedMeal.isRation, "cooked hunted game should not become preserved rations")

    local cookedCamp = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { cookActor },
    })
    cookedCamp:transitionTo(camp_controller.STATES.BREAK_BREAD)
    ok = cookedCamp:consumeRation(cookActor)
    assertTrue(ok, "cooked hunted game should satisfy Break Bread")
    assertTrue(cookActor.inventory:findItem(cookedMeal.id) == nil, "eaten cooked game meal should be consumed")
    assertTrue(not cookActor.conditions.stressed, "cooked game meal should prevent missed-meal stress")

    local useItemCook = base_entity.createEntity({
        id = "pc_use_item_cook_game",
        name = "Use Item Cook Game",
        isPC = true,
    })
    useItemCook.inventory = inventory.createInventory()
    local useItemCookGame = inventory.createItemFromTemplate("fresh_game")
    useItemCook.inventory:addItem(useItemCookGame, inventory.LOCATIONS.PACK)
    useItemCook.inventory:addItem(inventory.createItemFromTemplate("cooking_gear"), inventory.LOCATIONS.PACK)
    local useItemCookAvailable = false
    for _, action in ipairs(camp_actions.getAvailableActions(useItemCook, { useItemCook })) do
        if action.id == "use_item" then
            useItemCookAvailable = true
            break
        end
    end
    assertTrue(useItemCookAvailable,
        "cookable hunted game should make Use an Item available during Camp")
    local useItemCookController = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { useItemCook },
    })
    useItemCookController:transitionTo(camp_controller.STATES.ACTIONS)
    ok, result = useItemCookController:submitAction(useItemCook, {
        type = "use_item",
        itemId = useItemCookGame.id,
        preparation = "cook",
    })
    assertTrue(ok, "Use an Item should cook hunted game with cooking gear")
    assertEqual(result, "game_cooked", "cooked hunted game Use an Item should report cooked result")
    assertTrue(useItemCook.inventory:findItem(useItemCookGame.id) == nil,
        "cooked hunted game Use an Item should remove the fresh game")
    assertTrue(useItemCook.inventory:findItemByPredicate(function(item)
        return item.properties and item.properties.isCampMeal
    end) ~= nil, "cooked hunted game Use an Item should add a cooked meal")
    assertEqual(useItemCookController.actionsCompleted[useItemCook.id].type, "use_item",
        "cooked hunted game Use an Item should consume the Camp Action")

    local useItemPreserve = base_entity.createEntity({
        id = "pc_use_item_preserve_game",
        name = "Use Item Preserve Game",
        isPC = true,
    })
    useItemPreserve.inventory = inventory.createInventory()
    local useItemPreserveGame = inventory.createItemFromTemplate("fresh_game")
    local useItemSalt = inventory.createItemFromTemplate("salt", { quantity = 2 })
    useItemPreserve.inventory:addItem(useItemPreserveGame, inventory.LOCATIONS.PACK)
    useItemPreserve.inventory:addItem(useItemSalt, inventory.LOCATIONS.PACK)
    local useItemPreserveController = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { useItemPreserve },
    })
    useItemPreserveController:transitionTo(camp_controller.STATES.ACTIONS)
    ok, result = useItemPreserveController:submitAction(useItemPreserve, {
        type = "use_item",
        itemId = useItemPreserveGame.id,
        preparation = "preserve",
    })
    assertTrue(ok, "Use an Item should preserve hunted game with salt")
    assertEqual(result, "game_preserved", "preserved hunted game Use an Item should report preserved result")
    assertEqual(useItemSalt.quantity, 1, "preserved hunted game Use an Item should consume one salt")
    assertTrue(useItemPreserve.inventory:findItem(useItemPreserveGame.id) == nil,
        "preserved hunted game Use an Item should remove the fresh game")
    assertTrue(useItemPreserve.inventory:findItemByPredicate(function(item)
        return item.isRation
    end) ~= nil, "preserved hunted game Use an Item should add rations")

    local feastActor = base_entity.createEntity({
        id = "pc_feast_hunter",
        name = "Feast Hunter",
        isPC = true,
    })
    feastActor.inventory = inventory.createInventory()
    feastActor.inventory:addItem(inventory.createItemFromTemplate("crossbow"), inventory.LOCATIONS.HANDS)
    ok, result = camp_actions.resolveHuntOutcome(feastActor, "great_success", {}, events.createEventBus())
    assertTrue(ok, "great-success Hunt should produce large game")
    assertEqual(result, "large_game_found", "great-success Hunt should report large game")
    local largeGame = feastActor.inventory:findItemByPredicate(function(item)
        return item.properties and item.properties.greatSuccess
    end)
    assertTrue(largeGame ~= nil, "great-success Hunt should add large fresh game")
    assertEqual(largeGame.properties.meals, "guild", "large game should feed the guild once prepared")

    local feastCookActor = base_entity.createEntity({
        id = "pc_feast_cook",
        name = "Feast Cook",
        isPC = true,
    })
    feastCookActor.inventory = inventory.createInventory()
    local cookFeast = inventory.createItemFromTemplate("fresh_game_feast")
    feastCookActor.inventory:addItem(cookFeast, inventory.LOCATIONS.PACK)
    feastCookActor.inventory:addItem(inventory.createItemFromTemplate("cooking_gear"), inventory.LOCATIONS.PACK)
    ok, result = camp_actions.resolveCookHuntedGame(feastCookActor, cookFeast, {
        guild = { feastCookActor, actor, cookActor },
    }, events.createEventBus())
    assertTrue(ok, "large fresh game should cook into guild meals")
    assertEqual(result, "game_cooked", "large game cooking should report cooked result")
    local feastMeal = feastCookActor.inventory:findItemByPredicate(function(item)
        return item.properties and item.properties.isCampMeal
    end)
    assertTrue(feastMeal ~= nil, "large fresh game should add cooked meal stack")
    assertEqual(feastMeal.quantity, 3, "large cooked game should produce one meal per guild member")

    feastActor.inventory:addItem(inventory.createItemFromTemplate("salt"), inventory.LOCATIONS.PACK)
    ok, result = camp_actions.resolvePreserveHuntedGame(feastActor, largeGame, {
        guild = { actor, feastActor, { id = "ally_1" }, { id = "ally_2" } },
    }, events.createEventBus())
    assertTrue(ok, "large fresh game should be preservable with salt")
    assertEqual(result, "game_preserved", "large game preservation should report preserved result")
    local feastRations = feastActor.inventory:findItemByPredicate(function(item)
        return item.isRation
    end)
    assertTrue(feastRations ~= nil, "large game preservation should add ration stack")
    assertEqual(feastRations.quantity, 4, "large game should preserve into one ration per guild member")

    local failedActor = base_entity.createEntity({
        id = "pc_failed_hunter",
        name = "Failed Hunter",
        isPC = true,
    })
    failedActor.inventory = inventory.createInventory()
    failedActor.inventory:addItem(inventory.createItemFromTemplate("bow"), inventory.LOCATIONS.HANDS)
    ok, result = camp_actions.resolveHuntOutcome(failedActor, "failure", {}, events.createEventBus())
    assertTrue(not ok, "failed Hunt should not produce game")
    assertEqual(result, "no_game", "failed Hunt should report no game")

    local huntController = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { failedActor },
    })
    huntController:transitionTo(camp_controller.STATES.ACTIONS)
    ok, result = huntController:submitAction(failedActor, {
        type = "hunt",
        outcome = "failure",
    })
    assertTrue(ok, "adjudicated failed Hunt should be accepted by the Camp Controller")
    assertEqual(result, "no_game", "failed Hunt should preserve its outcome result")
    assertEqual(huntController.actionsCompleted[failedActor.id].outcome, "failure",
        "failed Hunt should still consume the Camp Action")

    local screenHunter = base_entity.createEntity({
        id = "pc_screen_hunter",
        name = "Screen Hunter",
        isPC = true,
    })
    screenHunter.inventory = inventory.createInventory()
    screenHunter.inventory:addItem(inventory.createItemFromTemplate("bow"), inventory.LOCATIONS.HANDS)
    local screenBus = events.createEventBus()
    local screenController = camp_controller.createCampController({
        eventBus = screenBus,
        guild = { screenHunter },
    })
    local campScreenModule = require('ui.screens.camp_screen')
    local campScreen = campScreenModule.createCampScreen({
        eventBus = screenBus,
        campController = screenController,
        guild = { screenHunter },
    })
    campScreen:subscribeEvents()
    screenController:transitionTo(camp_controller.STATES.ACTIONS)
    ok, result = screenController:submitAction(screenHunter, {
        type = "hunt",
        outcome = "success",
    })
    assertTrue(ok, "Camp Screen Hunt submission should resolve")
    assertEqual(result, "fresh_game_found", "Camp Screen Hunt submission should report fresh game")
    assertTrue(campScreen.promptOverlay ~= nil,
        "Camp Screen should show a Hunt result prompt")
    assertEqual(campScreen.promptOverlay.title, "HUNT",
        "Hunt prompt should use the action title")
    assertTrue((campScreen.promptOverlay.text or ""):find("Fresh Game", 1, true) ~= nil,
        "Hunt prompt should preserve the found game item")
    campScreen:destroy()

    local unpreservedGame = inventory.createItemFromTemplate("fresh_game")
    failedActor.inventory:addItem(unpreservedGame, inventory.LOCATIONS.PACK)
    ok, result = camp_actions.resolvePreserveHuntedGame(failedActor, unpreservedGame, {}, events.createEventBus())
    assertTrue(not ok, "preserving hunted game should require salt")
    assertEqual(result, "Requires salt", "missing salt should explain preservation failure")

    local context = {}
    ok, result = camp_actions.resolveHuntOutcome(failedActor, "great_failure", context, events.createEventBus())
    assertTrue(not ok, "great-failure Hunt should fail the camp action")
    assertEqual(result, "challenge_triggered", "great-failure Hunt should trigger a Challenge")
    assertTrue(context.challengeTriggered, "great-failure Hunt should mark Challenge trigger context")

    local noBow = base_entity.createEntity({
        id = "pc_no_hunt_weapon",
        name = "No Hunt Weapon",
        isPC = true,
    })
    noBow.inventory = inventory.createInventory()
    ok, result = camp_actions.resolveHunt(noBow, {}, events.createEventBus())
    assertTrue(not ok, "Hunt should require a missile weapon")
    assertEqual(result, "Requires a missile weapon", "missing missile weapon should explain Hunt failure")
end

local function checkCampPatrolMeatgrinderChoice()
    local function fakeMeatgrinder(draws)
        local index = 0
        return {
            draw = function()
                index = index + 1
                return draws[index]
            end,
        }
    end

    local function makeController(draws)
        local bus = events.createEventBus()
        local emitted = {}
        bus:on("meatgrinder_result", function(data)
            emitted[#emitted + 1] = data
        end)

        local controller = camp_controller.createCampController({
            eventBus = bus,
            guild = {},
            meatgrinder = fakeMeatgrinder(draws),
        })
        controller:transitionTo(camp_controller.STATES.WATCH)
        return controller, emitted
    end

    local encounter = {
        category = "random_encounter",
        description = "A monster finds the camp.",
    }
    local curiosity = {
        category = "curiosity",
        description = "A strange noise passes by.",
    }
    local travel = {
        category = "travel_event",
        description = "Loose stones shift nearby.",
    }

    local controller, emitted = makeController({ encounter, curiosity })
    local ok, watchResult = controller:resolveWatch(true)
    assertTrue(ok, "Patrol watch should resolve")
    assertEqual(#watchResult.draws, 2, "Patrol should draw twice from the Meatgrinder")
    assertEqual(watchResult.selected, curiosity, "Patrol should choose a non-encounter when available")
    assertTrue(not watchResult.challengeTriggered, "Patrol should avoid Challenge when a non-encounter is drawn")
    assertEqual(#emitted, 1, "Patrol should emit only the selected Meatgrinder result")
    assertEqual(emitted[1], curiosity, "Patrol should emit the selected non-encounter")

    controller, emitted = makeController({ encounter, { category = "random_encounter", description = "Second encounter" } })
    ok, watchResult = controller:resolveWatch(true)
    assertTrue(ok, "Patrol watch should resolve when both draws are encounters")
    assertTrue(watchResult.challengeTriggered, "Patrol should trigger Challenge only if both draws are encounters")
    assertEqual(watchResult.selected, encounter, "Patrol should select one encounter when both draws are encounters")
    assertEqual(#emitted, 1, "Patrol double-encounter should still emit one effective result")
    assertEqual(emitted[1], encounter, "Patrol double-encounter should emit the selected encounter")

    controller, emitted = makeController({ travel, encounter })
    ok, watchResult = controller:resolveWatch(false)
    assertTrue(ok, "Non-patrol watch should resolve")
    assertEqual(#watchResult.draws, 1, "Non-patrol watch should draw once")
    assertEqual(watchResult.selected, travel, "Non-patrol watch should use the only draw")
    assertEqual(#emitted, 1, "Non-patrol watch should emit the only draw")
    assertEqual(emitted[1], travel, "Non-patrol watch should emit the selected draw")

    local campScreenModule = require('ui.screens.camp_screen')
    local screenPatroller = base_entity.createEntity({
        id = "pc_screen_patroller",
        name = "Screen Patroller",
        isPC = true,
    })
    local screenBus = events.createEventBus()
    local screenController = camp_controller.createCampController({
        eventBus = screenBus,
        guild = { screenPatroller },
        meatgrinder = fakeMeatgrinder({ encounter, curiosity }),
    })
    local campScreen = campScreenModule.createCampScreen({
        eventBus = screenBus,
        campController = screenController,
        guild = { screenPatroller },
    })
    campScreen:subscribeEvents()
    screenController:transitionTo(camp_controller.STATES.ACTIONS)
    ok, result = screenController:submitAction(screenPatroller, {
        type = "patrol",
    })
    assertTrue(ok, "Camp Screen Patrol submission should resolve")
    assertEqual(result, "patrol_active", "Camp Screen Patrol should report the active patrol")
    assertTrue(screenController.patrolActive, "Patrol submission should mark the Watch for a double draw")
    assertTrue(campScreen.promptOverlay ~= nil,
        "Camp Screen should show a Patrol result prompt")
    assertEqual(campScreen.promptOverlay.title, "PATROL",
        "Patrol prompt should use the action title")
    assertTrue((campScreen.promptOverlay.text or ""):find("draw twice", 1, true) ~= nil,
        "Patrol prompt should explain the double Meatgrinder draw")
    campScreen:dismissPromptOverlay()
    screenController:transitionTo(camp_controller.STATES.WATCH)
    campScreen:handleMeatgrinderClick()
    assertTrue(screenController.watchResolved, "Camp Screen Watch button should resolve the Watch")
    assertTrue(campScreen.promptOverlay ~= nil,
        "Camp Screen should show a Watch result prompt")
    assertEqual(campScreen.promptOverlay.title, "THE WATCH",
        "Watch prompt should use the Watch title")
    assertTrue((campScreen.promptOverlay.text or ""):find("Patrol drew 2", 1, true) ~= nil,
        "Watch prompt should summarize Patrol's two draws")
    assertTrue((campScreen.promptOverlay.text or ""):find("A strange noise passes by.", 1, true) ~= nil,
        "Watch prompt should preserve the selected Meatgrinder result")
    assertTrue((campScreen.promptOverlay.text or ""):find("avoids a Challenge", 1, true) ~= nil,
        "Watch prompt should report the avoided Challenge")
    campScreen:destroy()

    local cupsLeft = base_entity.createEntity({
        id = "pc_cups_left",
        name = "Cups Left",
        isPC = true,
        cups = 4,
    })
    cupsLeft.pathSuit = constants.SUITS.CUPS
    local cupsRight = base_entity.createEntity({
        id = "pc_cups_right",
        name = "Cups Right",
        isPC = true,
        cups = 1,
    })
    cupsRight.pathSuit = constants.SUITS.CUPS

    local bus = events.createEventBus()
    local guardEvent = nil
    bus:on("camp_watch_guard", function(data)
        guardEvent = data
    end)
    controller = camp_controller.createCampController({
        eventBus = bus,
        guild = { cupsLeft, cupsRight },
        meatgrinder = fakeMeatgrinder({ encounter }),
    })
    controller:transitionTo(camp_controller.STATES.WATCH)
    ok, watchResult = controller:resolveWatch(false, {
        guardCard = { name = "Three of Cups", value = 3, suit = constants.SUITS.CUPS },
        guardTestCard = { name = "Ten of Cups", value = 10, suit = constants.SUITS.CUPS },
    })
    assertTrue(ok, "random encounter watch should resolve guard test")
    assertEqual(watchResult.guard, cupsLeft, "odd discard should choose first matching path guard")
    assertTrue(watchResult.alarmRaised, "successful Cups guard test should raise the alarm")
    assertTrue(not watchResult.surprised, "successful Cups guard test should avoid surprise")
    assertTrue(guardEvent and guardEvent.guard == cupsLeft, "watch should emit guard test result")

    controller = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { cupsLeft, cupsRight },
        meatgrinder = fakeMeatgrinder({ encounter }),
        playerDeck = {
            peekDiscard = function()
                return { name = "Four of Cups", value = 4, suit = constants.SUITS.CUPS }
            end,
        },
    })
    controller:transitionTo(camp_controller.STATES.WATCH)
    ok, watchResult = controller:resolveWatch(false, {
        guardCard = { name = "Three of Cups", value = 3, suit = constants.SUITS.CUPS },
        guardTestCard = { name = "Ten of Cups", value = 10, suit = constants.SUITS.CUPS },
    })
    assertTrue(ok, "random encounter watch should use the top minor discard when a deck is present")
    assertEqual(watchResult.guardCard.value, 4,
        "watch guard selection should prefer the player deck discard over fallback guard cards")
    assertEqual(watchResult.guard, cupsRight, "even top discard should choose last matching path guard")

    controller = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { cupsLeft, cupsRight },
        meatgrinder = fakeMeatgrinder({ encounter }),
    })
    controller:transitionTo(camp_controller.STATES.WATCH)
    ok, watchResult = controller:resolveWatch(false, {
        guardCard = { name = "Four of Cups", value = 4, suit = constants.SUITS.CUPS },
        guardTestCard = { name = "Two of Swords", value = 2, suit = constants.SUITS.SWORDS },
    })
    assertTrue(ok, "random encounter watch should resolve failed guard test")
    assertEqual(watchResult.guard, cupsRight, "even discard should choose last matching path guard")
    assertTrue(watchResult.surprised, "failed Cups guard test should mark the guild surprised")
    assertTrue(not watchResult.alarmRaised, "failed Cups guard test should not raise the alarm")
    assertTrue(watchResult.sleepingVulnerable,
        "failed watch guard should mark the sleeping guild as vulnerable")
    assertTrue(watchResult.surpriseEquipmentInactive and watchResult.armorInactive and watchResult.weaponsInactive,
        "failed watch guard should mark armor and wielded weapons inactive")
    assertTrue(watchResult.challengeConfig and watchResult.challengeConfig.sleepingVulnerable,
        "failed watch guard should prepare sleeping-vulnerable Challenge metadata")

    local sleepingBus = events.createEventBus()
    local sleepingSurpriseEvent = nil
    sleepingBus:on("challenge_surprise_resolved", function(data)
        sleepingSurpriseEvent = data
    end)
    local sleepingChallenge = challenge_controller.createChallengeController({
        eventBus = sleepingBus,
    })
    local armoredSleeper = base_entity.createEntity({
        id = "pc_armored_sleeper",
        name = "Armored Sleeper",
        isPC = true,
        armorSlots = 1,
    })
    local nightStalker = base_entity.createEntity({
        id = "npc_night_stalker",
        name = "Night Stalker",
        isPC = false,
        health = 1,
        defense = 0,
    })
    ok = sleepingChallenge:startChallenge({
        pcs = { armoredSleeper },
        npcs = { nightStalker },
        surprised = true,
        sleepingVulnerable = true,
        surpriseActions = {
            { tactic = "shank", target = armoredSleeper },
        },
    })
    assertTrue(ok, "sleeping-vulnerable Challenge should start")
    assertEqual(armoredSleeper.armorNotches, 0,
        "sleeping surprise wounds should ignore armor instead of notching it")
    assertTrue(armoredSleeper.conditions.staggered,
        "sleeping surprise wounds should hit the normal wound track")
    assertTrue(hasValue(sleepingChallenge.surpriseResults[1].effects, "sleeping_armor_inactive"),
        "sleeping surprise result should report inactive armor")
    assertTrue(hasValue(sleepingChallenge.surpriseResults[1].effects, "sleeping_weapons_inactive"),
        "sleeping surprise result should report inactive weapons")
    assertTrue(sleepingSurpriseEvent and sleepingSurpriseEvent.sleepingVulnerable,
        "sleeping surprise event should expose sleeping vulnerability")

    local alertChallenge = challenge_controller.createChallengeController({
        eventBus = events.createEventBus(),
    })
    local armoredAlert = base_entity.createEntity({
        id = "pc_armored_alert",
        name = "Armored Alert",
        isPC = true,
        armorSlots = 1,
    })
    ok = alertChallenge:startChallenge({
        pcs = { armoredAlert },
        npcs = { nightStalker },
        surprised = true,
        surpriseActions = {
            { tactic = "shank", target = armoredAlert },
        },
    })
    assertTrue(ok, "ordinary surprised Challenge should still start")
    assertEqual(armoredAlert.armorNotches, 1,
        "ordinary surprise wounds should keep existing armor behavior")
    assertTrue(not armoredAlert.conditions.staggered,
        "ordinary surprise wounds should not bypass armor without sleeping metadata")
end

local function checkCampComfortRequirements()
    local bedrollOnlyPC = base_entity.createEntity({
        id = "pc_bedroll_only",
        name = "Bedroll Only",
        isPC = true,
    })
    local bedrollOnlyCamp = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { bedrollOnlyPC },
    })
    assertTrue(bedrollOnlyCamp:startCamp({ hasBedrolls = true }), "camp should start with bedroll config")
    bedrollOnlyCamp:endCamp()
    assertTrue(bedrollOnlyPC.conditions.stressed, "bedroll alone should not satisfy camp comfort")

    local bedrollFirePC = base_entity.createEntity({
        id = "pc_bedroll_fire",
        name = "Bedroll Fire",
        isPC = true,
    })
    local bedrollFireCamp = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { bedrollFirePC },
    })
    assertTrue(bedrollFireCamp:startCamp({ hasBedrolls = true, hasFire = true }),
        "camp should start with bedroll and fire config")
    local bedrollFireOptions = bedrollFireCamp:getEndCampComfortOptions({ selectedActor = bedrollFirePC })
    assertEqual(bedrollFireOptions.result, "end_camp_comfort_options_ready",
        "end-camp comfort options should report readiness")
    assertTrue(bedrollFireOptions.resources.hasBedrolls and bedrollFireOptions.resources.hasFire,
        "end-camp comfort options should expose current comfort resources")
    assertTrue(bedrollFireOptions.rules.shelterSatisfiesComfort,
        "end-camp comfort options should expose shelter as a complete comfort rule")
    assertEqual(#bedrollFireOptions.actors, 1,
        "end-camp comfort options should include each guild member")
    assertTrue(bedrollFireOptions.actors[1].selected,
        "end-camp comfort options should mark the selected sleeper")
    assertEqual(bedrollFireOptions.actors[1].comfortCount, 2,
        "bedroll plus fire should preview two comfort elements")
    assertTrue(bedrollFireOptions.actors[1].benefits.bedroll and
        bedrollFireOptions.actors[1].benefits.fire,
        "bedroll plus fire options should preview both benefits")
    assertTrue(bedrollFireOptions.actors[1].comfortable,
