    assertTrue(not bedrollFireOptions.actors[1].wouldWakeStressed,
        "comfortable sleepers should not preview wake-up stress")
    bedrollFireCamp:endCamp()
    assertTrue(not bedrollFirePC.conditions.stressed, "two comfort elements should prevent end-camp stress")

    local bedrollSleeper = base_entity.createEntity({
