    assertEqual(assignedBedrollOptions.resources.bedrollCapacity, 1,
        "bedroll option resources should expose one-person capacity")
    assertEqual(assignedBedrollOptions.resources.bedrollOccupants[1].id, bedrollSleeper.id,
