    assertTrue(assignedBedrollOptions.actors[1].benefits.bedroll,
        "assigned bedroll options should count the assigned sleeper")
    assertTrue(not assignedBedrollOptions.actors[2].benefits.bedroll,
        "assigned bedroll options should not count unassigned sleepers")
    assertEqual(assignedBedrollOptions.actors[2].comfortCount, 1,
