    })
    assertTrue(woodComfortCamp:startCamp(), "Forego Wood comfort camp should derive carried firewood")
    assertTrue(woodComfortCamp.hasFire and woodComfortCamp.fireViolatesForegoWood,
        "carried market firewood should be marked as pact-violating fire")
    local woodComfortOptions = woodComfortCamp:getEndCampComfortOptions()
    assertTrue(woodComfortOptions.resources.fireViolatesForegoWood,
        "Forego Wood options should expose pact-violating fire")
    assertTrue(woodComfortOptions.actors[1].fireBlockedByForegoWood,
        "Forego Wood options should report fire blocked for pact-bound sleepers")
    assertTrue(not woodComfortOptions.actors[1].benefits.fire,
        "Forego Wood options should not count violating fire for pact-bound sleepers")
    assertEqual(woodComfortOptions.actors[1].comfortCount, 1,
        "Forego Wood options should leave only bedroll comfort for pact-bound sleepers")
    assertTrue(woodComfortOptions.actors[1].wouldWakeStressed,
        "Forego Wood options should preview wake-up stress when fire cannot count")
    assertTrue(hasValue(woodComfortOptions.actors[1].unavailableReasons, "fire_violates_forego_wood"),
        "Forego Wood options should expose the fire violation reason")
    assertTrue(woodComfortOptions.actors[2].benefits.fire and
        not woodComfortOptions.actors[2].wouldWakeStressed,
        "Forego Wood options should still count the same fire for unbound sleepers")
    woodComfortCamp:endCamp()
    assertTrue(woodPactPC.conditions.stressed,
        "Forego Wood should prevent bought/felled fire from counting for camp comfort")
    assertTrue(not fireBearer.conditions.stressed,
        "non-pact guild members should still benefit from the same fire")
    assertTrue(woodComfortPact.active and not woodComfortPact.broken,
        "sitting outside the fire's benefit should not break Forego Wood")

