    assertTrue(sparedPC.inventory:findItem(sparedItem.id) ~= nil,
        "vermin curse should not steal from the pack when the nightly chance does not hit")
end

local function checkCampRationConsumption()
    local rationedPC = base_entity.createEntity({
        id = "pc_ration_stack",
        name = "Ration Stack",
        isPC = true,
    })
    rationedPC.inventory = inventory.createInventory()
    local rationStack = inventory.createItemFromTemplate("rations_3")
    rationedPC.inventory:addItem(rationStack, inventory.LOCATIONS.PACK)

    local controller = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { rationedPC },
    })
    controller:transitionTo(camp_controller.STATES.BREAK_BREAD)

    local rationOptions = controller:getBreakBreadOptions({ selectedActor = rationedPC })
    assertEqual(rationOptions.result, "break_bread_options_ready",
        "Break Bread options should report readiness")
    assertTrue(rationOptions.inBreakBreadPhase,
        "Break Bread options should expose the active phase")
    assertTrue(rationOptions.rules.oneRationPerAdventurer and
        rationOptions.rules.lardIsEmergencyRationSubstitute,
        "Break Bread options should expose ration and lard rules")
    assertEqual(#rationOptions.pendingActors, 1,
        "unfed adventurer should appear in Break Bread pending actors")
    assertEqual(rationOptions.actors[1].rationCount, 3,
        "Break Bread options should count stacked rations")
    assertEqual(rationOptions.actors[1].requestedRations, 1,
        "ordinary Break Bread options should request one ration")
    assertEqual(rationOptions.actors[1].resultPreview, "ration_consumed",
        "ordinary Break Bread options should preview ration consumption")
    assertTrue(rationOptions.actors[1].selected,
        "Break Bread options should mark the selected eater")
    rationOptions.actors[1].rationChoices[1].quantity = 99
    local rationOptionsAgain = controller:getBreakBreadOptions()
    assertEqual(rationOptionsAgain.actors[1].rationChoices[1].quantity, 3,
        "mutating Break Bread option choices should not alter carried rations")

    local ok, result = controller:consumeRation(rationedPC)
    assertTrue(ok, "Break Bread should consume a ration from a stack")
    assertEqual(result, "ration_consumed", "ration consumption should report the canonical result")
    assertEqual(rationStack.quantity, 2, "stacked rations should decrement by one")
    assertTrue(not rationedPC.conditions.stressed, "eating a ration should not mark Stressed")

    ok = controller:consumeRation(rationedPC)
    assertTrue(ok, "second ration should be consumable from the same stack")
    assertEqual(rationStack.quantity, 1, "second ration should leave one ration in the stack")

    ok = controller:consumeRation(rationedPC)
    assertTrue(ok, "final ration in a stack should be consumable")
    assertTrue(rationedPC.inventory:findItem(rationStack.id) == nil, "empty ration stack should be removed")

    ok, result = controller:consumeRation(rationedPC)
    assertTrue(not ok, "missing ration should fail Break Bread consumption")
    assertEqual(result, "no_ration", "missing ration should report no_ration")
    assertTrue(rationedPC.conditions.stressed, "missing ration should mark Stressed")
    assertEqual(rationedPC.starvationCount, 1, "first missed meal should increment starvation count")

    ok = controller:consumeRation(rationedPC)
    assertTrue(not ok, "second missed ration should still fail consumption")
    assertTrue(rationedPC.conditions.starving, "second consecutive missed meal should mark Starving")
    assertEqual(rationedPC.starvationCount, 2, "second missed meal should increment starvation count again")

    local singlePC = base_entity.createEntity({
        id = "pc_single_ration",
        name = "Single Ration",
        isPC = true,
    })
    singlePC.inventory = inventory.createInventory()
    local singleRation = inventory.createItemFromTemplate("ration")
    singlePC.inventory:addItem(singleRation, inventory.LOCATIONS.PACK)
    local singleController = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { singlePC },
    })
    singleController:transitionTo(camp_controller.STATES.BREAK_BREAD)

    ok = singleController:consumeRation(singlePC)
    assertTrue(ok, "single ration item should be consumed")
    assertTrue(singlePC.inventory:findItem(singleRation.id) == nil, "single ration should be removed after consumption")

    local skipPC = base_entity.createEntity({
        id = "pc_skip_ration",
        name = "Skip Ration",
        isPC = true,
    })
    skipPC.inventory = inventory.createInventory()
    local skippedRations = inventory.createItemFromTemplate("rations_3")
    skipPC.inventory:addItem(skippedRations, inventory.LOCATIONS.PACK)
    local skipController = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { skipPC },
    })
    skipController:transitionTo(camp_controller.STATES.BREAK_BREAD)

    ok, result = skipController:skipRation(skipPC)
    assertTrue(not ok, "explicitly skipping rations should count as a missed meal")
    assertEqual(result, "no_ration", "skipping rations should report no_ration")
    assertEqual(skippedRations.quantity, 3, "skipping rations should not consume carried food")
    assertTrue(skipPC.conditions.stressed, "skipping rations should mark Stressed")
    assertTrue(skipController:canAdvanceFromBreakBread(), "skipped ration should resolve Break Bread")

    local ashedPC = base_entity.createEntity({
        id = "pc_ash_food_curse",
        name = "Ash Food Curse",
        isPC = true,
    })
    ashedPC.foodMayTurnToAsh = true
    ashedPC.rationAshChance = 0.5
    ashedPC.inventory = inventory.createInventory()
    local ashedRation = inventory.createItemFromTemplate("ration")
    ashedPC.inventory:addItem(ashedRation, inventory.LOCATIONS.PACK)
    local ashedEvents = 0
    local ashBus = events.createEventBus()
    ashBus:on(camp_controller.EVENTS.RATION_ASHED, function(data)
        ashedEvents = ashedEvents + 1
        assertEqual(data.entity, ashedPC, "ash curse event should identify the cursed eater")
        assertEqual(data.count, 1, "one ashed ration should be reported")
    end)
    local ashedController = camp_controller.createCampController({
        eventBus = ashBus,
        guild = { ashedPC },
    })
    ashedController:transitionTo(camp_controller.STATES.BREAK_BREAD)
    ok, result = ashedController:consumeRation(ashedPC, { rationAsh = true })
    assertTrue(not ok, "Malediction ash-food curse should waste the ration instead of feeding")
    assertEqual(result, "ration_ashed", "ashed food should report the Malediction rider")
    assertTrue(ashedPC.inventory:findItem(ashedRation.id) == nil, "ashed ration should be consumed")
    assertTrue(ashedPC.conditions.stressed, "ashed-only meal should leave the adventurer hungry")
    assertEqual(ashedPC.starvationCount, 1, "ashed-only meal should increment starvation")
    assertEqual(ashedEvents, 1, "ashed ration should emit exactly one ash event")
    assertTrue(ashedController:canAdvanceFromBreakBread(), "ashed ration should resolve Break Bread")

    local retryPC = base_entity.createEntity({
        id = "pc_ash_food_retry",
        name = "Ash Food Retry",
        isPC = true,
    })
    retryPC.foodMayTurnToAsh = true
    retryPC.inventory = inventory.createInventory()
    local retryRations = inventory.createItemFromTemplate("rations_3")
    retryPC.inventory:addItem(retryRations, inventory.LOCATIONS.PACK)
    local retryController = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { retryPC },
    })
    retryController:transitionTo(camp_controller.STATES.BREAK_BREAD)
    ok, result = retryController:consumeRation(retryPC, { rationAsh = { true, false } })
    assertTrue(ok, "ash-food curse should allow another ration to feed the adventurer")
    assertEqual(result, "ration_consumed", "eventual nourishment should report ration consumption")
    assertEqual(retryRations.quantity, 1, "one ashed ration and one eaten ration should both leave the stack")
    assertTrue(not retryPC.conditions.stressed, "eventual nourishment should prevent missed-meal stress")

    local halePC = base_entity.createEntity({
        id = "pc_hale_and_hearty",
        name = "Hale and Hearty",
        isPC = true,
        talents = {
            hale_and_hearty = { mastered = true },
        },
    })
    halePC.inventory = inventory.createInventory()
    local haleRations = inventory.createItemFromTemplate("rations_3")
    halePC.inventory:addItem(haleRations, inventory.LOCATIONS.PACK)
    halePC.bonds = {
        ally = { charged = false },
    }
    local haleController = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { halePC },
    })
    haleController:transitionTo(camp_controller.STATES.BREAK_BREAD)
    local haleOptions = haleController:getBreakBreadOptions({
        selectedActor = halePC,
        chargeBondTargetId = "ally",
    })
    assertTrue(haleOptions.actors[1].canUseHaleAndHearty,
        "Break Bread options should preview Hale and Hearty eligibility")
    assertEqual(haleOptions.actors[1].requestedRations, 2,
        "Hale and Hearty options should preview eating a second ration")
    assertEqual(haleOptions.actors[1].resultPreview, "ration_consumed_bond_charged",
        "Hale and Hearty options should preview bond charging")
    assertEqual(haleOptions.actors[1].chargeableBonds[1].targetId, "ally",
        "Hale and Hearty options should expose chargeable Bonds")

    ok, result = haleController:consumeRation(halePC, { chargeBondTargetId = "ally" })
    assertTrue(ok, "Hale and Hearty should be able to eat a second ration")
    assertEqual(result, "ration_consumed_bond_charged", "Hale and Hearty should report bond charging")
    assertEqual(haleRations.quantity, 1, "Hale and Hearty should consume two rations")
    assertTrue(halePC.bonds.ally.charged, "Hale and Hearty should charge the selected uncharged bond")

    local function createGluttonyConsumer(id, rationTemplate, eventBus)
        local pc = base_entity.createEntity({
            id = id,
            name = id,
            isPC = true,
            talents = {
                gramarye = { mastered = true, wounded = false },
            },
        })
        pc.inventory = inventory.createInventory()
        local rations = inventory.createItemFromTemplate(rationTemplate)
        local component = inventory.createItemFromTemplate("component_flare")
        pc.inventory:addItem(rations, inventory.LOCATIONS.PACK)
        pc.inventory:addItem(component, inventory.LOCATIONS.HANDS)
        local pactOk, pactResult, pacts = camp_actions.resolveAction({
            type = "make_pact",
            actor = pc,
            pactId = "gluttony",
            component = component,
        }, {
            eventBus = eventBus,
        })
        assertTrue(pactOk, "Gluttony test setup should be able to make a pact")
        assertEqual(pactResult, "pacts_made", "Gluttony setup should report pact creation")
        return pc, rations, component, pacts[1]
    end

    local gluttonyBus = events.createEventBus()
    local gluttonyPC, gluttonyRations, gluttonyComponent, gluttonyPact =
        createGluttonyConsumer("pc_gluttony_double", "rations_3", gluttonyBus)
    local gluttonyController = camp_controller.createCampController({
        eventBus = gluttonyBus,
        guild = { gluttonyPC },
    })
    gluttonyController:transitionTo(camp_controller.STATES.BREAK_BREAD)
    local gluttonyOptions = gluttonyController:getBreakBreadOptions()
    assertTrue(gluttonyOptions.actors[1].gluttonyPactActive,
        "Break Bread options should detect active Gluttony")
    assertEqual(gluttonyOptions.actors[1].requestedRations, 2,
        "Gluttony options should default to two rations")
    assertEqual(gluttonyOptions.actors[1].requiredRations, 2,
        "Gluttony options should expose its required ration count")
    assertEqual(gluttonyOptions.actors[1].resultPreview, "ration_consumed",
        "Gluttony options should preview success when two rations are available")
    ok, result = gluttonyController:consumeRation(gluttonyPC)
    assertTrue(ok, "Gluttony should still satisfy Break Bread when enough food is available")
    assertEqual(result, "ration_consumed", "Gluttony should report ordinary consumption after eating double")
    assertEqual(gluttonyRations.quantity, 1, "Gluttony should consume two rations by default")
    assertTrue(gluttonyPact.active and not gluttonyPact.broken,
        "Gluttony pact should remain active after double portions")
    assertTrue(gluttonyComponent.properties.pactCharged,
        "kept Gluttony pact should preserve the spell component charge")

    local shortBus = events.createEventBus()
    local maleficenceEvents = 0
    shortBus:on(events.EVENTS.MALEFICENCE_TRIGGERED, function(data)
        maleficenceEvents = maleficenceEvents + 1
        assertEqual(data.reason, "pact_broken", "Gluttony breach should trigger pact maleficence")
    end)
    local shortPC, shortRation, shortComponent, shortPact =
        createGluttonyConsumer("pc_gluttony_short", "ration", shortBus)
    local shortController = camp_controller.createCampController({
        eventBus = shortBus,
        guild = { shortPC },
    })
    shortController:transitionTo(camp_controller.STATES.BREAK_BREAD)
    local shortOptions = shortController:getBreakBreadOptions()
    assertEqual(shortOptions.actors[1].totalFoodCount, 1,
        "Break Bread options should count the single available Gluttony ration")
    assertEqual(shortOptions.actors[1].resultPreview, "ration_consumed_pact_broken",
        "Break Bread options should preview Gluttony breaking when underfed")
    assertTrue(hasValue(shortOptions.actors[1].pactBreaks, "gluttony"),
        "Break Bread options should identify the Gluttony pact break")
    ok, result = shortController:consumeRation(shortPC)
    assertTrue(ok, "Gluttony with one ration should still eat what is available")
    assertEqual(result, "ration_consumed_pact_broken",
        "Gluttony should report a pact break when fewer than two rations are eaten")
    assertTrue(shortPC.inventory:findItem(shortRation.id) == nil,
        "the available ration should be consumed before the Gluttony breach")
    assertTrue(shortPact.broken and shortPact.active == false,
        "underfeeding Gluttony should mark the pact broken")
    assertTrue(shortComponent.properties.pactCharged == false and shortComponent.pactCharge == nil,
        "breaking Gluttony should clear the component charge")
    assertTrue(shortPC.pendingMaleficence and shortPC.pendingMaleficence.reason == "pact_broken",
        "breaking Gluttony should queue maleficence when no action resolver is attached")
    assertEqual(maleficenceEvents, 1, "breaking Gluttony should emit one maleficence event")

    local explicitBus = events.createEventBus()
    local explicitPC, explicitRations, _, explicitPact =
        createGluttonyConsumer("pc_gluttony_explicit", "rations_3", explicitBus)
    local explicitController = camp_controller.createCampController({
        eventBus = explicitBus,
        guild = { explicitPC },
    })
    explicitController:transitionTo(camp_controller.STATES.BREAK_BREAD)
    ok, result = explicitController:consumeRation(explicitPC, { rationCount = 1 })
    assertTrue(ok, "explicitly underfeeding Gluttony should still consume a ration")
    assertEqual(result, "ration_consumed_pact_broken",
        "explicitly eating only one ration should break Gluttony")
    assertEqual(explicitRations.quantity, 2,
        "explicitly eating one ration should consume only the requested ration")
    assertTrue(explicitPact.broken and explicitPact.active == false,
        "explicit Gluttony underfeeding should mark the pact broken")

    local function actionAvailable(actions, id)
        for _, action in ipairs(actions or {}) do
            if action.id == id then
                return true
            end
        end
        return false
    end

    local function createDevourConsumer(id, rationTemplate, eventBus)
        local pc = base_entity.createEntity({
            id = id,
            name = id,
            isPC = true,
            talents = {
                gramarye = { mastered = true, wounded = false },
            },
        })
        pc.inventory = inventory.createInventory()
        local rations = inventory.createItemFromTemplate(rationTemplate)
        local component = inventory.createItemFromTemplate("component_flare")
        pc.inventory:addItem(rations, inventory.LOCATIONS.PACK)
        pc.inventory:addItem(component, inventory.LOCATIONS.HANDS)
        local pactOk, pactResult, pacts = camp_actions.resolveAction({
            type = "make_pact",
            actor = pc,
            pactId = "devour_living",
            component = component,
        }, {
            eventBus = eventBus,
        })
        assertTrue(pactOk, "Devour the Living setup should be able to make a pact")
        assertEqual(pactResult, "pacts_made", "Devour the Living setup should report pact creation")
        return pc, rations, component, pacts[1]
    end

    local noDevour = base_entity.createEntity({
        id = "pc_no_devour_action",
        name = "No Devour Action",
        isPC = true,
    })
    assertTrue(not actionAvailable(camp_actions.getAvailableActions(noDevour, { noDevour }), "devour_living"),
        "Devour the Living Camp Action should require the active pact")

    local devourBus = events.createEventBus()
    local devourCampEvents = {}
    devourBus:on("camp_action_resolved", function(data)
        if data.action == "devour_living" then
            devourCampEvents[#devourCampEvents + 1] = data
        end
    end)
    local devourPC, devourRations, devourComponent, devourPact =
        createDevourConsumer("pc_devour_living_success", "rations_3", devourBus)
    assertTrue(actionAvailable(camp_actions.getAvailableActions(devourPC, { devourPC }), "devour_living"),
        "active Devour the Living pact should unlock its Camp Action")

    ok, result = camp_actions.resolveAction({
        type = "devour_living",
        actor = devourPC,
    }, {
        eventBus = devourBus,
    })
    assertTrue(ok, "Devour the Living should request its fate test when no result is supplied")
    assertEqual(result, "devour_living_test_required",
        "Devour the Living should report the required test")
    assertTrue(devourCampEvents[#devourCampEvents].requiresTest,
        "Devour the Living should emit a test-required camp action event")
    assertEqual(devourCampEvents[#devourCampEvents].testSuit, "cups",
        "Devour the Living forage test should use Cups")

    ok, result = camp_actions.resolveAction({
        type = "devour_living",
        actor = devourPC,
        outcome = "success",
    }, {
        eventBus = devourBus,
    })
    assertTrue(ok, "successful Devour the Living forage should resolve")
    assertEqual(result, "living_food_found", "successful Devour the Living should find living food")
    assertTrue(devourPC.devourLivingMealAvailable, "successful Devour the Living should stage a living meal")
    local devourController = camp_controller.createCampController({
        eventBus = devourBus,
        guild = { devourPC },
    })
    devourController:transitionTo(camp_controller.STATES.BREAK_BREAD)
    local devourOptions = devourController:getBreakBreadOptions()
    assertTrue(devourOptions.actors[1].devourLivingPactActive and
        devourOptions.actors[1].devourLivingMealAvailable,
        "Break Bread options should preview found living food for Devour the Living")
    assertEqual(devourOptions.actors[1].resultPreview, "living_food_consumed",
        "Break Bread options should preview living food consumption")
    ok, result = devourController:consumeRation(devourPC)
    assertTrue(ok, "Devour the Living should satisfy Break Bread from found living food")
    assertEqual(result, "living_food_consumed", "living food should report a distinct Break Bread result")
    assertEqual(devourRations.quantity, 3, "Devour the Living should not consume ordinary rations on success")
    assertTrue(devourPact.active and not devourPact.broken,
        "eating living food should preserve the Devour the Living pact")
    assertTrue(devourComponent.properties.pactCharged,
        "kept Devour the Living pact should preserve the component charge")

    local screenDevourBus = events.createEventBus()
    local screenDevourPC = createDevourConsumer("pc_screen_devour_living", "rations_3", screenDevourBus)
    local screenDevourController = camp_controller.createCampController({
        eventBus = screenDevourBus,
        guild = { screenDevourPC },
    })
    local campScreenModule = require('ui.screens.camp_screen')
    local campScreen = campScreenModule.createCampScreen({
        eventBus = screenDevourBus,
        campController = screenDevourController,
        guild = { screenDevourPC },
    })
    campScreen:subscribeEvents()
    screenDevourController:transitionTo(camp_controller.STATES.ACTIONS)
    ok, result = screenDevourController:submitAction(screenDevourPC, {
        type = "devour_living",
        outcome = "success",
    })
    assertTrue(ok, "Camp Screen Devour the Living submission should resolve")
    assertEqual(result, "living_food_found", "Camp Screen Devour the Living should report living food")
    assertTrue(campScreen.promptOverlay ~= nil,
        "Camp Screen should show a Devour the Living result prompt")
    assertEqual(campScreen.promptOverlay.title, "DEVOUR THE LIVING",
        "Devour the Living prompt should use the action title")
    assertTrue((campScreen.promptOverlay.text or ""):find("living vermin", 1, true) ~= nil,
        "Devour the Living prompt should preserve the found-living-food result")
    campScreen:destroy()

    local failedDevourBus = events.createEventBus()
    local failedDevourPC, failedDevourRations, _, failedDevourPact =
        createDevourConsumer("pc_devour_living_failure", "rations_3", failedDevourBus)
    ok, result = camp_actions.resolveAction({
        type = "devour_living",
        actor = failedDevourPC,
        outcome = "failure",
    }, {
        eventBus = failedDevourBus,
    })
    assertTrue(not ok, "failed Devour the Living forage should not find food")
    assertEqual(result, "no_living_food", "failed Devour the Living forage should report no food")
    local failedDevourController = camp_controller.createCampController({
        eventBus = failedDevourBus,
        guild = { failedDevourPC },
    })
    failedDevourController:transitionTo(camp_controller.STATES.BREAK_BREAD)
    local failedDevourOptions = failedDevourController:getBreakBreadOptions()
    assertEqual(failedDevourOptions.actors[1].resultPreview, "devour_living_starving",
        "Break Bread options should preview Devour the Living starvation after failed forage")
    assertTrue(failedDevourOptions.actors[1].wouldMarkStressed,
        "failed Devour the Living options should preview missed-meal stress")
    ok, result = failedDevourController:consumeRation(failedDevourPC)
    assertTrue(not ok, "failed Devour the Living should make the adventurer go hungry")
    assertEqual(result, "devour_living_starving",
        "failed Devour the Living forage should use the pact starvation result")
    assertEqual(failedDevourRations.quantity, 3,
        "Devour the Living failure should not consume ordinary rations")
    assertTrue(failedDevourPC.conditions.stressed,
        "Devour the Living failure should apply missed-meal stress")
    assertTrue(failedDevourPact.active and not failedDevourPact.broken,
        "starving under Devour the Living should not itself break the pact")

    local forbiddenDevourBus = events.createEventBus()
    local forbiddenBreaks = 0
    forbiddenDevourBus:on(events.EVENTS.MALEFICENCE_TRIGGERED, function(data)
        if data.source and data.source.pactId == "devour_living" then
            forbiddenBreaks = forbiddenBreaks + 1
        end
    end)
    local forbiddenDevourPC, forbiddenDevourRations, forbiddenDevourComponent, forbiddenDevourPact =
        createDevourConsumer("pc_devour_living_forbidden", "rations_3", forbiddenDevourBus)
    local forbiddenDevourController = camp_controller.createCampController({
        eventBus = forbiddenDevourBus,
        guild = { forbiddenDevourPC },
    })
    forbiddenDevourController:transitionTo(camp_controller.STATES.BREAK_BREAD)
    local forbiddenDevourOptions = forbiddenDevourController:getBreakBreadOptions({
        consumeForbiddenRation = true,
    })
    assertTrue(forbiddenDevourOptions.actors[1].forbiddenRationWouldBreakDevourLiving,
        "Break Bread options should expose forbidden ordinary food for Devour the Living")
    assertEqual(forbiddenDevourOptions.actors[1].resultPreview, "ration_consumed_pact_broken",
        "Break Bread options should preview Devour the Living pact break from ordinary food")
    assertTrue(hasValue(forbiddenDevourOptions.actors[1].pactBreaks, "devour_living"),
        "Break Bread options should identify the Devour the Living pact break")
    ok, result = forbiddenDevourController:consumeRation(forbiddenDevourPC, { consumeForbiddenRation = true })
    assertTrue(ok, "explicitly eating ordinary rations under Devour the Living should still feed")
    assertEqual(result, "ration_consumed_pact_broken",
        "ordinary food should break Devour the Living when explicitly consumed")
    assertEqual(forbiddenDevourRations.quantity, 2,
        "explicit Devour the Living breach should consume one ordinary ration")
    assertTrue(forbiddenDevourPact.broken and forbiddenDevourPact.active == false,
        "forbidden ordinary food should mark Devour the Living broken")
    assertTrue(forbiddenDevourComponent.properties.pactCharged == false and
        forbiddenDevourComponent.pactCharge == nil,
        "breaking Devour the Living should clear the component charge")
    assertEqual(forbiddenBreaks, 1, "breaking Devour the Living should trigger maleficence")
end

function checkLardBreakBreadSubstitute()
    local lardTemplate = item_templates.getTemplate("lard")
    assertTrue(lardTemplate.properties.emergencyRation and lardTemplate.properties.rationSubstitute,
        "Lard should be marked as an emergency ration substitute")
    assertTrue(lardTemplate.properties.grease and lardTemplate.properties.soap,
        "Lard should retain its grease and soap utility tags")

    local lardOnlyPC = base_entity.createEntity({
        id = "pc_lard_only_break_bread",
        name = "Lard Only",
        isPC = true,
    })
    lardOnlyPC.inventory = inventory.createInventory()
    local lard = inventory.createItemFromTemplate("lard")
    lardOnlyPC.inventory:addItem(lard, inventory.LOCATIONS.PACK)
    local lardController = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { lardOnlyPC },
    })
    lardController:transitionTo(camp_controller.STATES.BREAK_BREAD)

    local lardOptions = lardController:getBreakBreadOptions()
    assertEqual(lardOptions.actors[1].rationCount, 0,
        "lard-only Break Bread options should show no ordinary rations")
    assertEqual(lardOptions.actors[1].emergencySubstituteCount, 1,
        "lard-only Break Bread options should count lard as emergency food")
    assertEqual(lardOptions.actors[1].resultPreview, "ration_consumed",
        "lard-only Break Bread options should preview successful feeding")

    local ok, result = lardController:consumeRation(lardOnlyPC)
    assertTrue(ok, "lard should feed an adventurer when no ration is available")
    assertEqual(result, "ration_consumed", "lard emergency feeding should satisfy Break Bread")
    assertTrue(lardOnlyPC.inventory:findItem(lard.id) == nil, "eaten lard should be consumed")
    assertTrue(not lardOnlyPC.conditions.stressed and not lardOnlyPC.conditions.starving,
        "eating lard should prevent missed-meal conditions")
    assertEqual(lardOnlyPC.starvationCount, 0, "eating lard should reset starvation pressure")

    local rationFirstPC = base_entity.createEntity({
        id = "pc_ration_before_lard",
        name = "Ration Before Lard",
        isPC = true,
    })
    rationFirstPC.inventory = inventory.createInventory()
    local reserveLard = inventory.createItemFromTemplate("lard")
    local ration = inventory.createItemFromTemplate("ration")
    rationFirstPC.inventory:addItem(reserveLard, inventory.LOCATIONS.PACK)
    rationFirstPC.inventory:addItem(ration, inventory.LOCATIONS.PACK)
    local rationFirstController = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { rationFirstPC },
    })
    rationFirstController:transitionTo(camp_controller.STATES.BREAK_BREAD)

    local rationFirstOptions = rationFirstController:getBreakBreadOptions()
    assertEqual(rationFirstOptions.actors[1].rationCount, 1,
        "Break Bread options should count ordinary rations separately from lard")
    assertEqual(rationFirstOptions.actors[1].emergencySubstituteCount, 1,
        "Break Bread options should keep emergency lard visible in reserve")
    assertEqual(rationFirstOptions.actors[1].rationChoices[1].id, ration.id,
        "Break Bread options should list the ordinary ration before emergency lard")

    ok, result = rationFirstController:consumeRation(rationFirstPC)
    assertTrue(ok, "ordinary rations should still feed before emergency lard")
    assertEqual(result, "ration_consumed", "ordinary ration feeding should report the canonical result")
    assertTrue(rationFirstPC.inventory:findItem(ration.id) == nil, "ordinary ration should be consumed first")
    assertTrue(rationFirstPC.inventory:findItem(reserveLard.id) ~= nil,
        "lard should remain in reserve while ordinary rations are available")
end

local function checkCampAnimalFeedConsumption()
    local animalCompanions = require('data.animal_companions')
    local owner = base_entity.createEntity({
        id = "pc_companion_owner",
        name = "Companion Owner",
        isPC = true,
    })
    owner.inventory = inventory.createInventory()
    owner.inventory:addItem(inventory.createItemFromTemplate("ration"), inventory.LOCATIONS.PACK)
    local feed = inventory.createItemFromTemplate("animal_feed", { quantity = 2 })
    owner.inventory:addItem(feed, inventory.LOCATIONS.PACK)
    local hound = {
        id = "hound_feed",
        name = "Hound",
        species = "hound",
        conditions = {
            staggered = true,
            weak = true,
            starving = true,
        },
        weak = true,
        starving = true,
        starvationCount = 1,
    }
    owner.animalCompanions = { hound }

    local controller = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { owner },
    })
    controller:transitionTo(camp_controller.STATES.BREAK_BREAD)
    local feedOptions = controller:getBreakBreadOptions()
    assertEqual(#feedOptions.pendingAnimalFeeds, 1,
        "Break Bread options should include unresolved animal feeds")
    assertEqual(feedOptions.actors[1].animalFeeds[1].matchingFeedCount, 2,
        "Break Bread options should count matching animal feed stacks")
    assertEqual(feedOptions.actors[1].animalFeeds[1].resultPreview, "animal_feed_consumed",
        "Break Bread options should preview animal feed consumption")
    assertTrue(feedOptions.actors[1].animalFeeds[1].wouldClearStaggered and
        feedOptions.actors[1].animalFeeds[1].wouldClearWeak and
        feedOptions.actors[1].animalFeeds[1].wouldClearStarving,
        "Break Bread options should preview cleared companion conditions")
    feedOptions.actors[1].animalFeeds[1].matchingFeedChoices[1].quantity = 99
    local feedOptionsAgain = controller:getBreakBreadOptions()
    assertEqual(feedOptionsAgain.actors[1].animalFeeds[1].matchingFeedChoices[1].quantity, 2,
        "mutating Break Bread animal feed options should not alter carried feed")
    controller.rationsConsumed[owner.id] = true
    assertTrue(not controller:canAdvanceFromBreakBread(),
        "Break Bread should wait for unresolved animal companion feed")
    controller.rationsConsumed[owner.id] = nil

    local ok, result = controller:consumeRation(owner)
    assertTrue(ok, "owner should consume their ration while feeding companions")
    assertEqual(feed.quantity, 1, "animal feed stack should decrement by one")
    assertTrue(not hound.conditions.staggered, "fed animal companion should clear Staggered")
    assertTrue(not hound.conditions.weak and not hound.weak, "fed animal companion should clear Weak")
    assertTrue(not hound.conditions.starving and not hound.starving, "fed animal companion should clear Starving")
    assertEqual(hound.starvationCount, 0, "fed animal companion should reset starvation count")
    assertTrue(controller:canAdvanceFromBreakBread(), "fed animal companion should allow Break Bread to advance")

    do
        local mothOwner = base_entity.createEntity({
            id = "pc_moth_feed_owner",
            name = "Moth Feed Owner",
            isPC = true,
        })
        mothOwner.inventory = inventory.createInventory()
        mothOwner.inventory:addItem(inventory.createItemFromTemplate("ration"), inventory.LOCATIONS.PACK)
        local mothFeed = inventory.createItemFromTemplate("animal_feed", {
            properties = {
                isAnimalFeed = true,
                feedFor = "dire_moth",
            },
        })
        mothOwner.inventory:addItem(mothFeed, inventory.LOCATIONS.PACK)
        local moth = animalCompanions.createCompanion("trained dire moths", {
            id = "moth_specific_feed",
            conditions = { weak = true, starving = true, staggered = true },
            weak = true,
            starving = true,
            starvationCount = 1,
        })
        mothOwner.animalCompanions = { moth }
        local mothController = camp_controller.createCampController({
            eventBus = events.createEventBus(),
            guild = { mothOwner },
        })
        mothController:transitionTo(camp_controller.STATES.BREAK_BREAD)
        ok, result = mothController:consumeRation(mothOwner)
        assertTrue(ok, "specific dire moth feed should satisfy Break Bread")
        assertTrue(not moth.conditions.weak and not moth.weak,
            "specific dire moth feed should clear Weak")
        assertTrue(not moth.conditions.starving and not moth.starving,
            "specific dire moth feed should clear Starving")
        assertTrue(not moth.conditions.staggered, "specific dire moth feed should clear Staggered")
        assertTrue(not mothOwner.inventory:findItem(mothFeed.id),
            "specific dire moth feed should be consumed")
    end

    do
        local wrongFeedOwner = base_entity.createEntity({
            id = "pc_wrong_companion_feed_owner",
            name = "Wrong Companion Feed Owner",
            isPC = true,
        })
        wrongFeedOwner.inventory = inventory.createInventory()
        wrongFeedOwner.inventory:addItem(inventory.createItemFromTemplate("ration"), inventory.LOCATIONS.PACK)
        local falconFeed = inventory.createItemFromTemplate("animal_feed", {
            properties = {
                isAnimalFeed = true,
                feedFor = "falcon",
            },
        })
        wrongFeedOwner.inventory:addItem(falconFeed, inventory.LOCATIONS.PACK)
        local hungryHound = animalCompanions.createCompanion("small but vicious dogs", {
            id = "hound_wrong_feed",
            conditions = {},
        })
        wrongFeedOwner.animalCompanions = { hungryHound }
        local wrongFeedController = camp_controller.createCampController({
            eventBus = events.createEventBus(),
            guild = { wrongFeedOwner },
        })
        wrongFeedController:transitionTo(camp_controller.STATES.BREAK_BREAD)
        ok, result = wrongFeedController:consumeRation(wrongFeedOwner)
        assertTrue(ok, "owner ration should still resolve when companion feed type is wrong")
        assertTrue(hungryHound.conditions.weak and hungryHound.weak,
            "wrong species-specific feed should not satisfy the companion")
        assertTrue(wrongFeedOwner.inventory:findItem(falconFeed.id) ~= nil,
            "wrong species-specific feed should remain unused")
    end

    local unfedOwner = base_entity.createEntity({
        id = "pc_unfed_companion_owner",
        name = "Unfed Companion Owner",
        isPC = true,
    })
    unfedOwner.inventory = inventory.createInventory()
    unfedOwner.inventory:addItem(inventory.createItemFromTemplate("ration"), inventory.LOCATIONS.PACK)
    local unfedHound = {
        id = "hound_unfed",
        name = "Unfed Hound",
        conditions = {},
    }
    unfedOwner.animalCompanions = { unfedHound }
    local unfedController = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { unfedOwner },
    })
    unfedController:transitionTo(camp_controller.STATES.BREAK_BREAD)
    local unfedOptions = unfedController:getBreakBreadOptions()
    assertEqual(unfedOptions.actors[1].animalFeeds[1].resultPreview, "no_animal_feed",
        "Break Bread options should preview missing animal feed")
    assertTrue(unfedOptions.actors[1].animalFeeds[1].wouldBecomeWeak,
        "Break Bread options should preview Weak for unfed companions")

    ok = unfedController:consumeRation(unfedOwner)
    assertTrue(ok, "owner ration consumption should still resolve when animal feed is missing")
    assertTrue(unfedHound.conditions.weak and unfedHound.weak,
        "unfed animal companion should become Weak")
    assertEqual(unfedHound.starvationCount, 1, "unfed animal companion should track missed feed")
    assertTrue(unfedController:canAdvanceFromBreakBread(),
        "unfed animal companion should be marked resolved for Break Bread")

    local starvingOwner = base_entity.createEntity({
        id = "pc_starving_companion_owner",
        name = "Starving Companion Owner",
        isPC = true,
    })
    starvingOwner.inventory = inventory.createInventory()
    starvingOwner.inventory:addItem(inventory.createItemFromTemplate("ration"), inventory.LOCATIONS.PACK)
    local starvingHound = {
        id = "hound_starving",
        name = "Starving Hound",
        conditions = { weak = true },
        weak = true,
        starvationCount = 1,
    }
    starvingOwner.animalCompanions = { starvingHound }
    local starvingController = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { starvingOwner },
    })
    starvingController:transitionTo(camp_controller.STATES.BREAK_BREAD)

    ok = starvingController:consumeRation(starvingOwner)
    assertTrue(ok, "second missed companion feed should still resolve owner ration")
    assertTrue(starvingHound.conditions.starving and starvingHound.starving,
        "second missed animal feed should mark Starving")
    assertEqual(starvingHound.starvationCount, 2, "second missed animal feed should increment starvation")

    local abandonOwner = base_entity.createEntity({
        id = "pc_abandoned_companion_owner",
        name = "Abandoned Companion Owner",
        isPC = true,
    })
    abandonOwner.inventory = inventory.createInventory()
    abandonOwner.inventory:addItem(inventory.createItemFromTemplate("ration"), inventory.LOCATIONS.PACK)
    local abandonedHound = {
        id = "hound_abandon",
        name = "Abandoning Hound",
        conditions = { weak = true, starving = true },
        weak = true,
        starving = true,
        starvationCount = 2,
    }
    abandonOwner.animalCompanions = { abandonedHound }
    abandonOwner.companion = abandonedHound
    abandonOwner.companions = { hound = abandonedHound }
    local abandonBus = events.createEventBus()
    local abandonment = nil
    abandonBus:on(camp_controller.EVENTS.ANIMAL_COMPANION_ABANDONED, function(data)
        abandonment = data
    end)
    local abandonController = camp_controller.createCampController({
        eventBus = abandonBus,
        guild = { abandonOwner },
    })
    abandonController:transitionTo(camp_controller.STATES.BREAK_BREAD)
    local abandonOptions = abandonController:getBreakBreadOptions()
    assertEqual(abandonOptions.actors[1].animalFeeds[1].resultPreview, "animal_companion_abandoned",
        "Break Bread options should preview abandonment for repeatedly unfed companions")
    assertTrue(abandonOptions.actors[1].animalFeeds[1].wouldAbandon,
        "Break Bread options should mark the abandonment preview")

    ok = abandonController:consumeRation(abandonOwner)
    assertTrue(ok, "owner ration consumption should still resolve when starving companion abandons")
    assertTrue(abandonedHound.abandoned and abandonedHound.conditions.abandoned,
        "already-starving animal companion should abandon after another missed feed")
    assertEqual(#abandonOwner.animalCompanions, 0,
        "abandoned animal companion should be removed from the owner's animal companion roster")
    assertTrue(abandonOwner.companion == nil and abandonOwner.companions.hound == nil,
        "abandoned animal companion should be removed from direct companion references")
    assertTrue(abandonment and abandonment.companion == abandonedHound and abandonment.owner == abandonOwner,
        "abandonment should emit an animal companion abandonment event")
    assertTrue(abandonController:canAdvanceFromBreakBread(),
        "abandoned animal companion should count as resolved for Break Bread")

    local woundResolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local injuredCompanion = animalCompanions.createCompanion("hound", {
        id = "hound_wound_track",
        name = "Wound Track Hound",
    })
    local woundEffects = {}
    woundResolver:applyDamage(injuredCompanion, 1, woundEffects, nil, nil, nil, {
        source = "attack",
    })
    assertTrue(injuredCompanion.conditions.staggered,
        "first animal companion Wound should mark Staggered")
    woundResolver:applyDamage(injuredCompanion, 1, woundEffects, nil, nil, nil, {
        source = "attack",
    })
    assertTrue(injuredCompanion.conditions.injured,
        "second animal companion Wound should mark Injured")
    woundResolver:applyDamage(injuredCompanion, 1, woundEffects, nil, nil, nil, {
        source = "attack",
    })
    assertTrue(injuredCompanion.conditions.dead,
        "third animal companion Wound should kill a non-familiar")

    local familiarOwner = base_entity.createEntity({
        id = "pc_familiar_owner",
        name = "Familiar Owner",
        isPC = true,
        cups = 3,
    })
    familiarOwner.resolve = { current = 1, max = 4 }
    local familiar = animalCompanions.createCompanion("hound", {
        id = "hound_familiar",
        name = "Familiar Hound",
        isFamiliar = true,
        familiar = true,
        owner = familiarOwner,
        conditions = { injured = true },
    })
    local familiarEffects = {}
    woundResolver:applyDamage(familiar, 1, familiarEffects, nil, nil, nil, {
        source = "attack",
        companionOwner = familiarOwner,
    })
    assertTrue(familiar.conditions.deaths_door and not familiar.conditions.dead,
        "familiar owner should spend Resolve to avert a killing Wound")
    assertEqual(familiarOwner.resolve.current, 0,
        "familiar killing-blow mitigation should spend owner Resolve")
    assertTrue(hasValue(familiarEffects, "familiar_resolve_spent"),
        "familiar killing-blow mitigation should report Resolve spend")

    local healResult = woundResolver:resolve({
        actor = familiarOwner,
        target = familiar,
        card = { name = "Queen of Cups", value = 13, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.HEAL,
    })
    assertTrue(healResult.success, "Heal effect should work on animal companions")
    assertTrue(not familiar.conditions.deaths_door and not familiar.outOfAction,
        "Heal effect should restore a familiar from out-of-action state")

    familiar.conditions.injured = true
    familiarOwner.bonds = {
        ally = { charged = true },
    }
    familiarOwner.animalCompanions = { familiar }
    local recoveryController = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { familiarOwner },
    })
    recoveryController:transitionTo(camp_controller.STATES.RECOVERY)
    ok, result = recoveryController:spendBondForRecovery(familiarOwner, "ally", "heal_companion", {
        companionId = "hound_familiar",
    })
    assertTrue(ok, "Recovery should allow a charged Bond to heal an Injured animal companion")
    assertEqual(result, "injured_healed", "companion Recovery should report Injured healing")
    assertTrue(not familiar.conditions.injured,
        "companion Recovery should clear Injured")
    assertTrue(not familiarOwner.bonds.ally.charged,
        "companion Recovery should spend the owner's charged Bond")
end

local function checkCampRecoveryEndClearsStaggered()
    local pc = base_entity.createEntity({
        id = "pc_recovery_staggered",
        name = "Recovery Staggered",
        isPC = true,
    })
    pc.conditions.stressed = true
    pc.conditions.staggered = true
    pc.loreBids = 0
    pc.bonds = {
        ally = { charged = true },
    }

    local controller = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { pc },
    })
    controller:transitionTo(camp_controller.STATES.RECOVERY)
    assertEqual(pc.loreBids, 4, "recovery should refill lore bids")
    assertTrue(pc.conditions.staggered, "Stressed PC should not clear Staggered at recovery start")

    local ok = controller:spendBondForRecovery(pc, "ally", "clear_stress")
    assertTrue(ok, "bond spend should clear Stressed during recovery")
    assertTrue(not pc.conditions.stressed, "clear_stress recovery spend should remove Stressed")
    assertTrue(pc.conditions.staggered, "Staggered should remain until recovery step ends")

    assertTrue(controller:advanceStep(), "advancing from recovery should finalize recovery")
    assertTrue(not pc.conditions.staggered, "non-Stressed PC should clear Staggered at recovery end")
end

local function checkCampCompleteConditionDurations()
    local pc = base_entity.createEntity({
        id = "pc_next_camp_condition",
        name = "Next Camp Condition",
        isPC = true,
    })
    pc.conditions.rhymebound = true
    pc.conditions.silenced = true
    pc.conditionDurations = {
        rhymebound = { ["until"] = "next_camp_complete" },
        silenced = { ["until"] = "fool_reshuffle" },
    }

    local expired = {}
    local bus = events.createEventBus()
    bus:on(camp_controller.EVENTS.CONDITION_EXPIRED, function(data)
        expired[#expired + 1] = data
    end)
    local controller = camp_controller.createCampController({
        eventBus = bus,
        guild = { pc },
    })
    controller.hasShelter = true

    controller:endCamp()

    assertTrue(not pc.conditions.rhymebound,
        "next-camp-complete maleficence conditions should clear at Camp end")
    assertTrue(pc.conditions.silenced,
        "other duration conditions should remain after Camp end")
    assertTrue(pc.conditionDurations and pc.conditionDurations.silenced and not pc.conditionDurations.rhymebound,
        "Camp end should remove only next-camp-complete duration metadata")
    assertEqual(#expired, 1, "Camp end should emit one condition-expired event")
    assertEqual(expired[1].condition, "rhymebound", "condition-expired event should name the cleared condition")
end

local function checkMaledictionExtraBondRecoveryCost()
    local campPC = base_entity.createEntity({
        id = "pc_malediction_extra_bond_camp",
        name = "Camp Infirm Curse",
        isPC = true,
    })
    campPC.conditions.injured = true
    campPC.malediction = {
        active = true,
        curse = {
            flags = { maledictionExtraBondRecoveryCost = true },
        },
    }
    campPC.bonds = {
        ally_a = { charged = true },
    }
    local campEvent = nil
    local campBus = events.createEventBus()
    campBus:on(camp_controller.EVENTS.BOND_SPENT, function(data)
        campEvent = data
    end)
    local camp = camp_controller.createCampController({
        eventBus = campBus,
        guild = { campPC },
    })
    camp:transitionTo(camp_controller.STATES.RECOVERY)

    local extraCostOptions = camp:getRecoveryOptions({
        actorId = campPC.id,
        bondTargetId = "ally_a",
        spendType = "heal_wound",
    })
    assertTrue(extraCostOptions.selectedBenefit.requiresExtraBond,
        "Recovery helper should flag Malediction Page's two-Bond recovery cost")
    assertTrue(extraCostOptions.selectedBenefit.disabled,
        "Recovery helper should disable extra-cost wound healing without a second Bond")
    assertEqual(extraCostOptions.selectedBenefit.unavailableReason, "Requires two charged Bonds",
        "Recovery helper should explain missing second recovery Bond")

    local ok, result = camp:spendBondForRecovery(campPC, "ally_a", "heal_wound")
    assertTrue(not ok, "Malediction Page should require two charged Bonds to clear Injured at Camp")
    assertEqual(result, "Requires two charged Bonds", "missing second Bond should explain Malediction recovery cost")
    assertTrue(campPC.conditions.injured, "failed extra-cost recovery should not clear Injured")
    assertTrue(campPC.bonds.ally_a.charged, "failed extra-cost recovery should not spend the first Bond")

    campPC.bonds.ally_b = { charged = true }
    local extraReadyOptions = camp:getRecoveryOptions({
        actorId = campPC.id,
        bondTargetId = "ally_a",
        spendType = "heal_wound",
        extraBondTargetId = "ally_b",
    })
    assertEqual(extraReadyOptions.selectedBenefit.extraBondOptions[1].targetId, "ally_b",
        "Recovery helper should list the available second Bond")
    assertTrue(extraReadyOptions.selectedBenefit.extraBondOptions[1].selected,
        "Recovery helper should expose the selected second Bond")
    ok, result = camp:spendBondForRecovery(campPC, "ally_a", "heal_wound", {
        extraBondTargetId = "ally_b",
    })
    assertTrue(ok, "Malediction Page should clear Injured when two charged Bonds are burned")
    assertEqual(result, "injured_healed", "extra-cost Camp recovery should still report the healed wound")
    assertTrue(not campPC.conditions.injured, "two-Bond Camp recovery should clear Injured")
    assertTrue(not campPC.bonds.ally_a.charged and not campPC.bonds.ally_b.charged,
        "two-Bond Camp recovery should burn both charged Bonds")
    assertTrue(campEvent and campEvent.bondCost == 2 and campEvent.extraBondTargetId == "ally_b",
        "Camp recovery event should report the second Malediction recovery Bond")

    local cityPC = base_entity.createEntity({
        id = "pc_malediction_extra_bond_city",
        name = "City Infirm Curse",
        isPC = true,
        talents = {
            path_lore = { mastered = true, wounded = true },
        },
    })
    cityPC.gold = 50
    cityPC.inventory = inventory.createInventory()
    cityPC.woundedTalents = 1
    cityPC.maledictionExtraBondRecoveryCost = true
    cityPC.bonds = {
        ally_a = { charged = true },
    }
    local cityBus = events.createEventBus()
    local cityEvent = nil
    cityBus:on(events.EVENTS.CITY_UPKEEP_RECOVERY_BOND_SPENT, function(data)
        cityEvent = data
    end)
    local city = city_phase.createCityPhaseController({
        eventBus = cityBus,
        guild = { cityPC },
    })
    assertTrue(city:resolveUpkeep(cityPC, { tier = "common" }),
        "common City upkeep should enable Recovery-style bond burns")

    ok, result = city:spendBondForUpkeepRecovery(cityPC, "ally_a", "heal_wound")
    assertTrue(not ok, "Malediction Page should require two charged Bonds to clear wounded talents in City")
    assertEqual(result, "Requires two charged Bonds", "City missing second Bond should explain Malediction recovery cost")
    assertTrue(cityPC.talents.path_lore.wounded, "failed City extra-cost recovery should not heal the talent")
    assertTrue(cityPC.bonds.ally_a.charged, "failed City extra-cost recovery should not spend the first Bond")

    cityPC.bonds.ally_b = { charged = true }
    ok, result = city:spendBondForUpkeepRecovery(cityPC, "ally_a", "heal_wound", {
        extraBondTargetId = "ally_b",
    })
    assertTrue(ok, "Malediction Page should heal a wounded talent when two charged Bonds are burned in City")
    assertEqual(result, "talent_healed", "extra-cost City recovery should report the healed talent")
    assertTrue(not cityPC.talents.path_lore.wounded, "two-Bond City recovery should clear the wounded talent")
    assertTrue(not cityPC.bonds.ally_a.charged and not cityPC.bonds.ally_b.charged,
        "two-Bond City recovery should burn both charged Bonds")
    assertTrue(cityEvent and cityEvent.bondCost == 2 and cityEvent.extraBondTargetId == "ally_b",
        "City recovery event should report the second Malediction recovery Bond")
end

local function checkCampStarvingSkipsRecovery()
    local pc = base_entity.createEntity({
        id = "pc_starving_recovery",
        name = "Starving Recovery",
        isPC = true,
    })
    pc.conditions.stressed = true
    pc.conditions.staggered = true
    pc.conditions.starving = true
    pc.loreBids = 1
    pc.bonds = {
        ally = { charged = true },
    }

    local controller = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { pc },
    })
    controller:transitionTo(camp_controller.STATES.RECOVERY)
    assertEqual(pc.loreBids, 1, "Starving PC should not refill lore bids during Recovery")
    assertTrue(pc.conditions.staggered, "Starving PC should not clear Staggered during Recovery")
    local starvingRecoveryOptions = controller:getRecoveryOptions({
        actorId = pc.id,
        bondTargetId = "ally",
        spendType = "clear_stress",
    })
    assertTrue(starvingRecoveryOptions.selectedActor.disabled,
        "Recovery helper should disable Starving adventurers")
    assertTrue(starvingRecoveryOptions.selectedActor.starving,
        "Recovery helper should expose Starving recovery state")
    assertTrue(hasValue(starvingRecoveryOptions.selectedActor.unavailableReasons,
            "Starving adventurers cannot recover"),
        "Recovery helper should explain Starving recovery skip")

    local ok, result = controller:spendBondForRecovery(pc, "ally", "clear_stress")
    assertTrue(not ok, "Starving PC should not burn Bonds during Recovery")
    assertEqual(result, "Starving adventurers cannot recover", "starving recovery block should be explicit")
    assertTrue(pc.bonds.ally.charged, "blocked Starving recovery should not spend the Bond")
    assertTrue(pc.conditions.stressed, "blocked Starving recovery should not clear Stressed")

    assertTrue(controller:advanceStep(), "advancing from Recovery should tolerate a Starving PC")
    assertTrue(pc.conditions.staggered, "Starving PC should still not clear Staggered at Recovery end")

    local comfortPC = base_entity.createEntity({
        id = "pc_starving_comfort",
        name = "Starving Comfort",
        isPC = true,
    })
    comfortPC.conditions.starving = true
    comfortPC.conditions.stressed = false
    local comfortController = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { comfortPC },
    })
    comfortController:processEndOfCampEffects(comfortPC)
    assertTrue(not comfortPC.conditions.stressed,
        "Starving PC should skip end-of-camp comfort stress checks")
end

local function checkCampAfflictionRecoveryCharges()
    local restAction = camp_actions.getAction("rest")
    assertEqual(restAction.name, "Rest and Recover", "Rest action should use the canonical camp action name")
    assertTrue(camp_actions.getAction("tend_affliction") == nil,
        "legacy Tend Affliction should not be offered as a separate Camp Action")

    local legacyTendActor = base_entity.createEntity({
        id = "pc_legacy_tend_affliction",
        name = "Legacy Tend Affliction",
        isPC = true,
    })
    legacyTendActor.afflictions = {
        red_welts = { stage = 1 },
    }
    local ok, result = camp_actions.resolveAction({
        type = "tend_affliction",
        actor = legacyTendActor,
    }, { eventBus = events.createEventBus() })
    assertTrue(not ok, "legacy Tend Affliction resolver should reject direct use")
    assertEqual(result, "Unknown action: tend_affliction",
        "legacy Tend Affliction should be unavailable through the Camp Action dispatcher")

    local pc = base_entity.createEntity({
        id = "pc_afflicted_recovery",
        name = "Afflicted Recovery",
        isPC = true,
    })
    pc.conditions.stressed = true
    pc.bonds = {
        ally_a = { charged = true, name = "Ally A" },
        ally_b = { charged = true, name = "Ally B" },
        ally_c = { charged = true, name = "Ally C" },
        ally_d = { charged = true, name = "Ally D" },
    }
    pc.afflictions = {
        goblin_rot = {
            stage = 2,
            maxStage = 3,
            chargesRequired = {
                [1] = 1,
                [2] = 1,
                [3] = 2,
            },
        },
    }

    local controller = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { pc },
    })
    controller:transitionTo(camp_controller.STATES.RECOVERY)

    local stressedRecoveryOptions = controller:getRecoveryOptions({
        actorId = pc.id,
        bondTargetId = "ally_a",
        spendType = "cure_affliction",
        affliction = "goblin_rot",
    })
    assertEqual(stressedRecoveryOptions.result, "recovery_options_ready",
        "Recovery helper should report ready option data")
    assertTrue(stressedRecoveryOptions.selectedActor.stressed,
        "Recovery helper should expose the selected actor's Stressed gate")
    assertTrue(hasValue(stressedRecoveryOptions.selectedActor.unavailableReasons, "Must clear stress first"),
        "Recovery helper should explain the Stressed-first recovery gate")
    assertEqual(stressedRecoveryOptions.selectedBond.benefitOptions[1].spendType, "clear_stress",
        "Recovery helper should offer only stress clearing while Stressed")

    ok, result = controller:spendBondForRecovery(pc, "ally_a", "cure_affliction", {
        affliction = "goblin_rot",
    })
    assertTrue(not ok, "Stressed adventurers should clear stress before curing afflictions")
    assertEqual(result, "Must clear stress first", "affliction cure should obey recovery stress gate")
    assertTrue(pc.bonds.ally_a.charged, "blocked affliction cure should not spend the Bond")

    pc.conditions.stressed = false
    local noRestRecoveryOptions = controller:getRecoveryOptions({
        actorId = pc.id,
        bondTargetId = "ally_a",
        spendType = "cure_affliction",
        affliction = "goblin_rot",
    })
    assertTrue(hasValue(noRestRecoveryOptions.selectedActor.unavailableReasons,
            "Requires Rest and Recover action"),
        "Recovery helper should explain missing Rest and Recover for affliction recovery")
    assertTrue(noRestRecoveryOptions.selectedAffliction.disabled,
        "Recovery helper should disable affliction options before Rest and Recover")
    ok, result = controller:spendBondForRecovery(pc, "ally_a", "cure_affliction", {
        affliction = "goblin_rot",
    })
    assertTrue(not ok, "affliction bond recovery should require the Rest and Recover action")
    assertEqual(result, "Requires Rest and Recover action",
        "missing Rest and Recover action should explain blocked affliction recovery")
    assertTrue(pc.bonds.ally_a.charged,
        "blocked no-rest affliction recovery should not spend the Bond")

    controller.actionsCompleted[pc.id] = { type = "rest", actor = pc }
    local readyRecoveryOptions = controller:getRecoveryOptions({
        actorId = pc.id,
        bondTargetId = "ally_a",
        spendType = "cure_affliction",
        affliction = "goblin_rot",
    })
    assertTrue(not readyRecoveryOptions.selectedActor.disabled,
        "Recovery helper should enable valid post-Rest affliction recovery")
    assertEqual(readyRecoveryOptions.selectedBond.name, "Ally A",
        "Recovery helper should expose selected charged Bond option data")
    assertEqual(readyRecoveryOptions.selectedBenefit.spendType, "cure_affliction",
        "Recovery helper should expose the selected Bond benefit")
    assertEqual(readyRecoveryOptions.selectedBenefit.actionDataPreview.affliction, "goblin_rot",
        "Recovery helper should expose resolver-ready affliction action data")
    assertEqual(readyRecoveryOptions.selectedAffliction.stage, 2,
        "Recovery helper should expose selected affliction stage state")

    readyRecoveryOptions.selectedBond.name = "Mutated Bond"
    local refreshedRecoveryOptions = controller:getRecoveryOptions({
        actorId = pc.id,
        bondTargetId = "ally_a",
        spendType = "cure_affliction",
        affliction = "goblin_rot",
    })
    assertEqual(refreshedRecoveryOptions.selectedBond.name, "Ally A",
        "Recovery helper should return copy-safe Bond option data")

    ok, result = controller:spendBondForRecovery(pc, "ally_a", "cure_affliction", {
        affliction = "goblin_rot",
    })
    assertTrue(ok, "first affliction charge should be accepted")
    assertEqual(result, "affliction_charged", "partial affliction charges should be recorded")
    assertEqual(pc.afflictions.goblin_rot.cureCharges, 1, "partial charge should accumulate")
    assertTrue(not pc.afflictions.goblin_rot.curedStages[3], "insufficient charges should not cure final stage")

    ok, result = controller:spendBondForRecovery(pc, "ally_b", "cure_affliction", {
        affliction = "goblin_rot",
    })
    assertTrue(ok, "second affliction charge should be accepted")
    assertEqual(result, "affliction_charged", "curing a future stage should keep affliction active")
    assertTrue(pc.afflictions.goblin_rot.curedStages[3], "charges should cure the most severe stage first")
    assertEqual(pc.afflictions.goblin_rot.stage, 2, "curing a future stage should not regress current stage")

    ok, result = controller:spendBondForRecovery(pc, "ally_c", "cure_affliction", {
        affliction = "goblin_rot",
    })
    assertTrue(ok, "current-stage affliction charge should be accepted")
    assertEqual(result, "affliction_charged", "current-stage cure should keep affliction active if lower stages remain")
    assertTrue(pc.afflictions.goblin_rot.curedStages[2], "current stage should be cured")
    assertEqual(pc.afflictions.goblin_rot.stage, 1, "curing the current stage should regress the affliction")

    ok, result = controller:spendBondForRecovery(pc, "ally_d", "cure_affliction", {
        affliction = "goblin_rot",
    })
    assertTrue(ok, "last affliction charge should be accepted")
    assertEqual(result, "affliction_cured", "all cured stages should fully heal the affliction")
    assertTrue(pc.afflictions.goblin_rot == nil, "fully cured affliction should be removed")

    local held = base_entity.createEntity({
        id = "pc_affliction_held",
        name = "Affliction Held",
        isPC = true,
    })
    held.afflictions = {
        red_welts = {
            stage = 1,
            maxStage = 3,
            curedStages = { [2] = true },
        },
    }
    local heldController = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { held },
    })
    heldController.hasShelter = true
    heldController:processEndOfCampEffects(held)
    assertEqual(held.afflictions.red_welts.stage, 1,
        "afflictions should not advance into an already-cured next stage")

    local hiddenPatient = base_entity.createEntity({
        id = "pc_hidden_affliction_thresholds",
        name = "Hidden Affliction Thresholds",
        isPC = true,
    })
    hiddenPatient.afflictions = {
        ghost_lotus = {
            stage = 2,
            maxStage = 2,
            stageCosts = {
                [1] = 99,
                [2] = 99,
            },
            hiddenStageCosts = {
                [1] = 5,
                [2] = 1,
            },
        },
    }
    local hiddenEvents = {}
    local hiddenBus = events.createEventBus()
    hiddenBus:on("affliction_charges_spent", function(data)
        hiddenEvents[#hiddenEvents + 1] = data
    end)
    local hiddenController = camp_controller.createCampController({
        eventBus = hiddenBus,
        guild = { hiddenPatient },
    })
    local hiddenState = hiddenController:getAfflictionRecoveryState(hiddenPatient, "ghost_lotus")
    assertTrue(hiddenState.thresholdsHidden, "hidden affliction thresholds should be flagged for presentation")
    assertTrue(hiddenState.stageCosts == nil, "hidden affliction thresholds should not expose up-front stage costs")
    assertTrue(hiddenState.knownStageCosts[1] == nil and hiddenState.knownStageCosts[2] == nil,
        "hidden affliction thresholds should begin with no known costs")

    ok, detail = hiddenController:applyAfflictionCharges(hiddenPatient, "ghost_lotus", 1, "bond")
    assertTrue(ok, "hidden affliction thresholds should accept cure charges")
    assertEqual(detail.curedStages[1], 2, "hidden threshold mechanics should use GM-only stage costs")
    assertEqual(hiddenPatient.afflictions.ghost_lotus.stage, 1,
        "curing the current hidden-threshold stage should regress the affliction")
    assertEqual(detail.knownStageCosts[2], 1,
        "cured hidden affliction stages should reveal their spent threshold")
    assertTrue(detail.knownStageCosts[1] == nil,
        "uncured hidden affliction stages should keep their threshold hidden")
    assertTrue(hiddenEvents[1].thresholdsHidden,
        "hidden affliction recovery events should mark cure thresholds as hidden")

    ok, detail = hiddenController:applyAfflictionCharges(hiddenPatient, "ghost_lotus", 4, "bond")
    assertTrue(ok, "partial hidden-threshold charges should accumulate")
    assertEqual(#detail.curedStages, 0, "insufficient hidden-threshold charges should not reveal a stage")
    assertEqual(detail.cureChargesRemaining, 4, "partial hidden-threshold charges should remain banked")
    hiddenState = hiddenController:getAfflictionRecoveryState(hiddenPatient, "ghost_lotus")
    assertTrue(hiddenState.knownStageCosts[1] == nil,
        "partial hidden-threshold progress should not reveal the unknown threshold")

    ok, detail = hiddenController:applyAfflictionCharges(hiddenPatient, "ghost_lotus", 1, "bond")
    assertTrue(ok, "final hidden-threshold charge should resolve")
    assertEqual(detail.result, "affliction_cured", "all hidden-threshold stages should cure the affliction")
    assertEqual(detail.knownStageCosts[1], 5,
        "fully cured hidden afflictions should report revealed spent thresholds")
    assertTrue(hiddenPatient.afflictions.ghost_lotus == nil,
        "fully cured hidden-threshold afflictions should be removed")

    hiddenPatient.xp = 1
    hiddenPatient.conditions = { ghost_lotus_euphoria = true }
    hiddenPatient.ghostLotusEuphoria = true
    hiddenPatient.afflictions = {
        ghost_lotus = {
            stage = 1,
            maxStage = 3,
            stageRecovery = {
                [1] = { xp = 1, charges = 0 },
                [2] = { charges = 2 },
                [3] = { charges = 1 },
            },
        },
    }
    hiddenController:transitionTo(camp_controller.STATES.RECOVERY)
    hiddenController.actionsCompleted[hiddenPatient.id] = { type = "rest", actor = hiddenPatient }
    hiddenState = hiddenController:getAfflictionRecoveryState(hiddenPatient, "ghost_lotus")
    assertEqual(hiddenState.stageCosts[1], 0,
        "ghost lotus stage 1 should not require affliction recovery charges")
    assertEqual(hiddenState.xpStageCosts[1], 1,
        "ghost lotus stage 1 should expose its XP recovery requirement")
    ok, result, detail = hiddenController:spendXPForAfflictionRecovery(hiddenPatient, "ghost_lotus")
    assertTrue(ok, "ghost lotus stage 1 should be recoverable by spending XP")
    assertEqual(result, "affliction_cured", "XP recovery should cure first-stage ghost lotus")
    assertEqual(detail.xpSpent, 1, "ghost lotus stage 1 should spend exactly 1 XP")
    assertEqual(hiddenPatient.xp, 0, "ghost lotus XP recovery should deduct the spent XP")
    assertTrue(hiddenPatient.afflictions.ghost_lotus == nil,
        "ghost lotus stage 1 XP recovery should remove the affliction")
    assertTrue(not hiddenPatient.ghostLotusEuphoria and not hiddenPatient.conditions.ghost_lotus_euphoria,
        "curing ghost lotus should clear its euphoria rider")

    local bezoarPatient = base_entity.createEntity({
        id = "pc_bezoar_patient",
        name = "Bezoar Patient",
        isPC = true,
    })
    bezoarPatient.inventory = inventory.createInventory()
    local bezoar = inventory.createItemFromTemplate("bezoar")
    bezoarPatient.inventory:addItem(bezoar, inventory.LOCATIONS.PACK)
    bezoarPatient.afflictions = {
        basilisk_bile = {
            stage = 3,
            maxStage = 3,
            chargesRequired = {
                [1] = 2,
                [2] = 3,
                [3] = 3,
            },
        },
    }
    local bezoarController = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { bezoarPatient },
    })
    bezoarController:transitionTo(camp_controller.STATES.RECOVERY)
    bezoarController.actionsCompleted[bezoarPatient.id] = { type = "rest", actor = bezoarPatient }
    local bezoarOptions = bezoarController:getRecoveryOptions({
        actorId = bezoarPatient.id,
        itemId = bezoar.id,
        spendType = "healthful_item",
        affliction = "basilisk_bile",
    })
    assertTrue(not bezoarOptions.selectedActor.disabled,
        "Recovery helper should enable healthful-item affliction recovery after Rest and Recover")
    assertEqual(bezoarOptions.selectedAid.itemId, bezoar.id,
        "Recovery helper should expose the selected healthful recovery item")
    assertEqual(bezoarOptions.selectedAid.charges, 8,
        "Recovery helper should preview bezoar affliction recovery charges")
    assertEqual(bezoarOptions.selectedAid.actionDataPreview.affliction, "basilisk_bile",
        "Recovery helper should expose healthful-item recovery action data")

    bezoarOptions.selectedAid.itemName = "Mutated Bezoar"
    local refreshedBezoarOptions = bezoarController:getRecoveryOptions({
        actorId = bezoarPatient.id,
        itemId = bezoar.id,
        spendType = "healthful_item",
        affliction = "basilisk_bile",
    })
    assertEqual(refreshedBezoarOptions.selectedAid.itemName, bezoar.name,
        "Recovery helper should return copy-safe healthful item option data")

    ok, result, detail = bezoarController:spendHealthfulItemForRecovery(bezoarPatient, bezoar.id, {
        affliction = "basilisk_bile",
    })
    assertTrue(ok, "bezoar should provide healthful affliction recovery charges")
    assertEqual(result, "affliction_cured", "bezoar's 8 charges should be able to cure a full affliction clock")
    assertEqual(detail.charges, 8, "bezoar should count as 8 burned charges")
    assertTrue(bezoarPatient.afflictions.basilisk_bile == nil, "fully cured affliction should be removed after bezoar")
    assertTrue(not bezoarPatient.inventory:findItem(bezoar.id), "bezoar should be consumed when swallowed")

    local stressedPatient = base_entity.createEntity({
        id = "pc_stressed_bezoar",
        name = "Stressed Bezoar Patient",
        isPC = true,
    })
    stressedPatient.conditions.stressed = true
    stressedPatient.inventory = inventory.createInventory()
    local blockedBezoar = inventory.createItemFromTemplate("bezoar")
    stressedPatient.inventory:addItem(blockedBezoar, inventory.LOCATIONS.PACK)
    stressedPatient.afflictions = {
        red_welts = { stage = 1, maxStage = 1 },
    }
    local stressedController = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { stressedPatient },
    })
    stressedController:transitionTo(camp_controller.STATES.RECOVERY)
    ok, result = stressedController:spendHealthfulItemForRecovery(stressedPatient, blockedBezoar.id, {
        affliction = "red_welts",
    })
    assertTrue(not ok, "healthful item recovery should still obey the recovery stress gate")
    assertEqual(result, "Must clear stress first", "blocked healthful item should explain the stress gate")
    assertTrue(stressedPatient.inventory:findItem(blockedBezoar.id), "blocked healthful item recovery should not consume the item")

    stressedPatient.conditions.stressed = false
    ok, result = stressedController:spendHealthfulItemForRecovery(stressedPatient, blockedBezoar.id, {
        affliction = "red_welts",
    })
    assertTrue(not ok, "healthful item recovery should require the Rest and Recover action")
    assertEqual(result, "Requires Rest and Recover action",
        "missing Rest and Recover action should explain blocked healthful recovery")
    assertTrue(stressedPatient.inventory:findItem(blockedBezoar.id),
        "blocked no-rest healthful recovery should not consume the item")

    stressedController.actionsCompleted[stressedPatient.id] = { type = "rest", actor = stressedPatient }
    local torch = inventory.createItemFromTemplate("torch")
    stressedPatient.inventory:addItem(torch, inventory.LOCATIONS.PACK)
    ok, result = stressedController:spendHealthfulItemForRecovery(stressedPatient, torch.id, {
        affliction = "red_welts",
    })
    assertTrue(not ok, "ordinary gear should not count as a healthful affliction item")
    assertEqual(result, "Item is not healthful for afflictions", "ordinary gear should explain failed healthful recovery")
    assertTrue(stressedPatient.inventory:findItem(torch.id), "rejected healthful item should not be consumed")

    local leechDoctor = base_entity.createEntity({
        id = "pc_leech_doctor",
        name = "Leech Doctor",
        isPC = true,
    })
    leechDoctor.inventory = inventory.createInventory()
    local leeches = inventory.createItemFromTemplate("leeches")
    leechDoctor.inventory:addItem(leeches, inventory.LOCATIONS.PACK)
    local leechPatient = base_entity.createEntity({
        id = "pc_leech_patient",
        name = "Leech Patient",
        isPC = true,
    })
    leechPatient.afflictions = {
        red_welts = {
            stage = 2,
            maxStage = 2,
            chargesRequired = {
                [1] = 1,
                [2] = 2,
            },
        },
    }
    local leechController = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { leechDoctor, leechPatient },
    })
    leechController:startCamp({ hasShelter = true })
    ok, result = leechController:submitAction(leechDoctor, {
        type = "use_item",
        target = leechPatient,
        itemId = leeches.id,
        affliction = "red_welts",
        card = { name = "Three of Cups", value = 3, suit = constants.SUITS.CUPS },
    })
    assertTrue(ok, "leeches should be usable as a Camp item")
    assertEqual(result, "affliction_charged", "Cups leech draw should burn 2 affliction charges")
    assertTrue(leechPatient.afflictions.red_welts.curedStages[2],
        "leeches should cure the most severe stage first")
    assertEqual(leechPatient.afflictions.red_welts.stage, 1,
        "curing the current leech-treated stage should regress the affliction")
    assertTrue(not leechDoctor.inventory:findItem(leeches.id), "leeches should be consumed on application")

    local badLeechDoctor = base_entity.createEntity({
        id = "pc_bad_leech_doctor",
        name = "Bad Leech Doctor",
        isPC = true,
    })
    badLeechDoctor.inventory = inventory.createInventory()
    local failedLeeches = inventory.createItemFromTemplate("leeches")
    badLeechDoctor.inventory:addItem(failedLeeches, inventory.LOCATIONS.PACK)
    local badLeechPatient = base_entity.createEntity({
        id = "pc_bad_leech_patient",
        name = "Bad Leech Patient",
        isPC = true,
    })
    badLeechPatient.afflictions = {
        goblin_rot = { stage = 1, maxStage = 2, chargesRequired = 2 },
    }
    local failedLeechController = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { badLeechDoctor, badLeechPatient },
    })
    failedLeechController:startCamp({ hasShelter = true })
    ok, result = failedLeechController:submitAction(badLeechDoctor, {
        type = "use_item",
        target = badLeechPatient,
        itemId = failedLeeches.id,
        affliction = "goblin_rot",
        card = { name = "Four of Swords", value = 4, suit = constants.SUITS.SWORDS },
    })
    assertTrue(ok, "Swords leech draw should still resolve the Camp item action")
    assertEqual(result, "leeches_no_effect", "Swords or Pentacles leech draw should provide no charges")
    assertTrue(not badLeechPatient.afflictions.goblin_rot.curedStages,
        "failed leech suit should not add affliction cure progress")
    assertTrue(not badLeechDoctor.inventory:findItem(failedLeeches.id),
        "leeches should be consumed even when the draw gives no healing")

    local pipeweedSmoker = base_entity.createEntity({
        id = "pc_camp_pipeweed",
        name = "Camp Pipeweed",
        isPC = true,
    })
    pipeweedSmoker.inventory = inventory.createInventory()
    pipeweedSmoker.conditions.stressed = true
    pipeweedSmoker.stressed = true
    local campPipeweed = inventory.createItemFromTemplate("pipeweed")
    pipeweedSmoker.inventory:addItem(campPipeweed, inventory.LOCATIONS.PACK)
    local hasUseItem = false
    for _, action in ipairs(camp_actions.getAvailableActions(pipeweedSmoker, { pipeweedSmoker })) do
        if action.id == "use_item" then
            hasUseItem = true
        end
    end
    assertTrue(hasUseItem, "pipeweed should make Use an Item available during Camp")

    local pipeweedEvent = nil
    local pipeweedBus = events.createEventBus()
    pipeweedBus:on("camp_action_resolved", function(data)
        if data.action == "use_item" and data.itemId == campPipeweed.id then
            pipeweedEvent = data
        end
    end)
    local pipeweedController = camp_controller.createCampController({
        eventBus = pipeweedBus,
        guild = { pipeweedSmoker },
    })
    pipeweedController:startCamp({ hasShelter = true })
    ok, result = pipeweedController:submitAction(pipeweedSmoker, {
        type = "use_item",
        itemId = campPipeweed.id,
    })
    assertTrue(ok, "pipeweed should be usable as a Camp item")
    assertEqual(result, "stress_cleared", "Camp pipeweed should report stress clearing")
    assertTrue(not pipeweedSmoker.conditions.stressed, "Camp pipeweed should clear the Stressed condition")
    assertTrue(not pipeweedSmoker.stressed, "Camp pipeweed should clear the legacy Stressed flag")
    assertTrue(not pipeweedSmoker.inventory:findItem(campPipeweed.id), "Camp pipeweed should be consumed")
    assertTrue(pipeweedEvent and pipeweedEvent.result == "stress_cleared",
        "Camp pipeweed should emit use-item resolution details")
end

local function checkReloadCrossbowAction()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local actor = base_entity.createEntity({
        id = "pc_crossbow",
        name = "Crossbow User",
        isPC = true,
        pentacles = 3,
    })
    actor.ammo = 2
    actor.inventory = inventory.createInventory()
    local crossbow = inventory.createItemFromTemplate("crossbow")
    actor.inventory:addItem(crossbow, inventory.LOCATIONS.HANDS)

    local target = base_entity.createEntity({
        id = "npc_crossbow_target",
        name = "Target",
        isPC = false,
        health = 3,
        defense = 1,
    })

    local firstShot = resolver:resolve({
        actor = actor,
        target = target,
        card = { name = "Pentacles", value = 8, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.MISSILE,
        weapon = crossbow,
        targetInitiative = 5,
    })
    assertTrue(firstShot.success, "loaded crossbow should fire")
    assertTrue(not crossbow.isLoaded, "firing a crossbow should unload it")
    assertEqual(actor.ammo, 1, "firing a crossbow should spend ammo")
    assertTrue(hasValue(firstShot.effects, "crossbow_fired"), "crossbow shot should record fired effect")
    assertTrue(hasValue(firstShot.effects, "ammo_destroyed"),
        "crossbow bolts that hit should be marked destroyed")
    assertTrue(firstShot.ammoOutcome and firstShot.ammoOutcome.type == "bolt" and firstShot.ammoOutcome.destroyed,
        "crossbow hit should expose destroyed bolt details")
    assertTrue(hasValue(firstShot.effects, "piercing"),
        "crossbow shot should always deal Piercing damage")
    assertTrue(hasValue(firstShot.effects, "crossbow_piercing"),
        "crossbow piercing should be reported separately")
    assertEqual(target.npcDefense, 1, "crossbow Piercing damage should bypass target Defense")
    assertEqual(target.npcHealth, 2, "crossbow Piercing damage should reduce target Health")

    local unloadedShot = resolver:resolve({
        actor = actor,
        target = target,
        card = { name = "Pentacles", value = 8, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.MISSILE,
        weapon = crossbow,
        targetInitiative = 5,
    })
    assertTrue(not unloadedShot.success, "unloaded crossbow should not fire")
    assertTrue(hasValue(unloadedShot.effects, "not_loaded"), "unloaded crossbow should report reload requirement")
    assertEqual(actor.ammo, 1, "unloaded crossbow attempt should not spend ammo")

    local reload = resolver:resolve({
        actor = actor,
        card = { name = "Any", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.RELOAD,
    })
    assertTrue(reload.success, "Reload Crossbow should load equipped crossbow")
    assertTrue(crossbow.isLoaded, "Reload Crossbow should mark weapon loaded")
    assertEqual(actor.ammo, 1, "Reload Crossbow should not double-spend the bolt before firing")
    assertTrue(hasValue(reload.effects, "reloaded"), "Reload Crossbow should record reload effect")
    assertEqual(reload.reloadedWeapon, crossbow, "Reload Crossbow should report the reloaded weapon")
    assertEqual(reload.ammoType, "bolt", "Reload Crossbow should report bolt ammunition")
    assertTrue(reload.ammoTracked, "Reload Crossbow should report tracked ammunition when present")
    assertEqual(reload.ammoRemaining, 1, "Reload Crossbow should report remaining bolts without spending one")

    local reloadPopup = getActionSequencerPopup({
        actor = actor,
        card = { name = "Any", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.RELOAD,
        weapon = crossbow,
    }, reload, function(data)
        return data.title == "Reload Crossbow"
    end)
    assertTrue(reloadPopup ~= nil, "Reload Crossbow should queue a visible reload popup")
    assertEqual(reloadPopup.reloadedWeapon, crossbow, "Reload popup should preserve the reloaded weapon")
    assertEqual(reloadPopup.ammoType, "bolt", "Reload popup should preserve the ammunition type")
    assertEqual(reloadPopup.ammoRemaining, 1, "Reload popup should preserve remaining ammunition")
    assertTrue(reloadPopup.loaded, "Reload popup should report the crossbow loaded")

    local alreadyLoaded = resolver:resolve({
        actor = actor,
        card = { name = "Any", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.RELOAD,
    })
    assertTrue(not alreadyLoaded.success, "loaded crossbow should not reload again")
    assertEqual(alreadyLoaded.description, "Crossbow is already loaded!", "reload should explain already-loaded state")

    crossbow.isLoaded = false
    actor.ammo = 0
    local noBoltReload = resolver:resolve({
        actor = actor,
        card = { name = "Any", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.RELOAD,
    })
    assertTrue(not noBoltReload.success, "Reload Crossbow should require a spare bolt when ammo is tracked")
    assertTrue(not crossbow.isLoaded, "failed no-bolt reload should leave the crossbow unloaded")
    assertTrue(hasValue(noBoltReload.effects, "reload_no_bolt"), "no-bolt reload should report the missing bolt")

    local typedActor = base_entity.createEntity({
        id = "pc_typed_crossbow",
        name = "Typed Crossbow User",
        isPC = true,
        pentacles = 3,
    })
    typedActor.inventory = inventory.createInventory()
    local typedCrossbow = inventory.createItemFromTemplate("crossbow")
    typedCrossbow.isLoaded = false
    typedActor.inventory:addItem(typedCrossbow, inventory.LOCATIONS.HANDS)
    typedActor.ammunition = { arrow = 12, bolt = 0 }
    typedActor.ammo = 12

    local typedNoBoltReload = resolver:resolve({
        actor = typedActor,
        card = { name = "Any", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.RELOAD,
    })
    assertTrue(not typedNoBoltReload.success,
        "Reload Crossbow should not treat arrows as bolts when typed ammunition is tracked")
    assertTrue(hasValue(typedNoBoltReload.effects, "reload_no_bolt"),
        "typed no-bolt reload should report the missing bolt")

    typedActor.ammunition.bolt = 1
    typedActor.ammo = 0
    local typedBoltReload = resolver:resolve({
        actor = typedActor,
        card = { name = "Any", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.RELOAD,
    })
    assertTrue(typedBoltReload.success,
        "Reload Crossbow should use the typed bolt pool even when legacy ammo is empty")
    assertTrue(typedCrossbow.isLoaded, "typed bolt reload should load the crossbow")
end

local function checkTestFateActionDrawsSeparateCard()
    local bus = events.createEventBus()
    local request = nil
    bus:on(events.EVENTS.REQUEST_TEST_OF_FATE, function(data)
        request = data
    end)

    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
    })

    local actor = base_entity.createEntity({
        id = "pc_test_fate",
        name = "Risk Taker",
        isPC = true,
        pentacles = 1,
        wands = 3,
    })
    actor.resolve = 2
    local actionCard = { name = "Two of Cups", value = 2, suit = constants.SUITS.CUPS }
    local action = {
        actor = actor,
        card = actionCard,
        type = action_resolver.ACTION_TYPES.TEST_FATE,
        testAttribute = "wands",
        targetSuit = constants.SUITS.WANDS,
        spendResolveForFavor = true,
        challengeController = {
            isActive = function()
                return true
            end,
        },
    }

    local pending = resolver:resolve(action)
    assertTrue(pending.pendingTestOfFate, "Test Fate action should open the async test flow")
    assertTrue(request ~= nil, "Test Fate action should emit a test request")
    assertEqual(request.attribute, "wands", "Test Fate should use explicit GM/action attribute")
    assertEqual(request.targetSuit, constants.SUITS.WANDS, "Test Fate should use explicit GM/action target suit")
    assertEqual(request.favor, true, "Test Fate should pass Resolve-spent favor to the modal")
    assertEqual(actor.resolve, 1, "Test Fate favor should spend one Resolve")
    assertTrue(hasValue(pending.effects, "resolve_spent_for_favor"), "Test Fate should record Resolve favor spend")
    assertTrue(request.actionCard == actionCard, "Test Fate request should retain the spent action card as context")
    assertTrue(pending.testFateRequest == request,
        "Test Fate result should preserve the emitted async request")
    do
        local popup = getActionSequencerPopup(action, pending, function(data)
            return data.title == "Test Fate"
        end)
        assertTrue(popup ~= nil, "Test Fate should queue a visible async-request popup")
        assertEqual(popup.attribute, "wands", "Test Fate popup should preserve the requested attribute")
        assertEqual(popup.targetSuit, constants.SUITS.WANDS, "Test Fate popup should preserve the target suit")
        assertEqual(popup.favor, true, "Test Fate popup should preserve Resolve-spent favor")
        assertTrue(popup.spentResolveForFavor, "Test Fate popup should mark Resolve-spent favor")
        assertTrue(popup.actionCard == actionCard, "Test Fate popup should retain the spent action card")
    end
    local resolveSpentFavor = request.favor

    actor.motifs = { "Wealthy Artificer" }
    local motifRequest = nil
    bus:on(events.EVENTS.REQUEST_TEST_OF_FATE, function(data)
        motifRequest = data
    end)
    local motifPending = resolver:resolve({
        actor = actor,
        card = { name = "Four of Cups", value = 4, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.TEST_FATE,
        testAttribute = "pentacles",
        testMotif = "Wealthy Artificer",
        challengeController = {
            isActive = function()
                return true
            end,
        },
    })
    assertTrue(motifPending.pendingTestOfFate, "motif-backed Test Fate should still open the async flow")
    assertTrue(hasValue(motifPending.effects, "test_fate_motif_favor"),
        "declared matching motifs should report Test Fate favor")
    assertEqual(motifRequest.favor, true, "declared matching motifs should grant Test Fate favor")
    assertEqual(motifRequest.motif, "Wealthy Artificer", "Test Fate request should carry the bid motif")
    do
        local popup = getActionSequencerPopup({
            actor = actor,
            type = action_resolver.ACTION_TYPES.TEST_FATE,
        }, motifPending, function(data)
            return data.title == "Test Fate"
        end)
        assertTrue(popup ~= nil, "motif-backed Test Fate should queue a visible popup")
        assertEqual(popup.motif, "Wealthy Artificer", "Test Fate popup should preserve bid motif")
        assertTrue(popup.motifFavor, "Test Fate popup should preserve motif favor")
    end

    local motifCancelRequest = nil
    bus:on(events.EVENTS.REQUEST_TEST_OF_FATE, function(data)
        motifCancelRequest = data
    end)
    local motifCancel = resolver:resolve({
        actor = actor,
        card = { name = "Five of Cups", value = 5, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.TEST_FATE,
        testAttribute = "pentacles",
        testMotif = "Wealthy Artificer",
        disfavor = true,
        challengeController = {
            isActive = function()
                return true
            end,
        },
    })
    assertTrue(motifCancel.pendingTestOfFate, "motif-backed Test Fate with disfavor should still proceed")
    assertEqual(motifCancelRequest.favor, nil,
        "motif favor and Test Fate disfavor should cancel to a neutral test")

    actor.cups = 5
    actor.afflictions = {
        black_honey = {
            stage = 2,
        },
    }
    request = nil
    pending = resolver:resolve({
        actor = actor,
        card = { name = "Six of Cups", value = 6, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.TEST_FATE,
        testAttribute = "cups",
        fineMotor = true,
        challengeController = {
            isActive = function()
                return true
            end,
        },
    })
    assertTrue(pending.pendingTestOfFate, "black honey stage 2 should still use the async Test Fate flow")
    assertTrue(hasValue(pending.effects, "black_honey_cups_equals_one"),
        "black honey stage 2 should report Cups capped at 1")
    assertTrue(hasValue(pending.effects, "black_honey_fine_motor_disfavor"),
        "black honey stage 2 should report fine-motor disfavor")
    assertEqual(request.attributeBonus, -4,
        "black honey stage 2 should make effective Cups equal 1 without mutating base Cups")
    assertEqual(request.favor, false, "black honey stage 2 should apply disfavor to fine-motor tests")
    assertEqual(actor.cups, 5, "black honey Cups override should not rewrite the base attribute")
    actor.afflictions = nil
    actor.afflictions = {
        ghost_lotus = { stage = 2 },
    }
    assertTrue(resolver:canSeeThroughFaceRatIllusion(actor),
        "ghost lotus stage 2 should make the actor immune to visual illusions")
    actor.afflictions.ghost_lotus.stage = 3
    actor.motifs = { "Romancing Swordsman" }
    actor.ghostLotusRewriteOk, actor.ghostLotusRewrite = resolver:rewriteGhostLotusMotif(actor, {
        newDescriptor = "Drowsy",
    })
    assertTrue(actor.ghostLotusRewriteOk,
        "ghost lotus stage 3 should allow a motif descriptor rewrite")
    assertEqual(actor.motifs[1], "Drowsy Swordsman",
        "ghost lotus motif rewrite should replace one descriptor")
    assertEqual(actor.ghostLotusRewrite.oldMotif, "Romancing Swordsman",
        "ghost lotus motif rewrite should preserve audit metadata")
    actor.afflictions = nil
    actor.conditions = {}
    actor.afflictions = {
        giant_rat_venom = { stage = 3 },
    }
    actor.giantRatOutcome = resolver:resolveTestOfFateOutcome({
        actor = actor,
    }, {
        success = true,
    })
    assertTrue(hasValue(actor.giantRatOutcome.effects, "giant_rat_venom_test_fate_wound"),
        "giant rat venom stage 3 should wound after a Test of Fate resolves")
    assertEqual(actor.giantRatOutcome.giantRatVenomWound.result, "staggered",
        "giant rat venom stage 3 wound should use the Piercing wound track")
    assertTrue(actor.conditions.staggered,
        "giant rat venom stage 3 should persist the post-test Piercing Wound")
    actor.afflictions = nil

    local drawCount = 0
    local fakeDeck = {
        draw = function()
            drawCount = drawCount + 1
            return { name = "King of Swords", value = 14, suit = constants.SUITS.SWORDS }
        end,
        discard = function() end,
    }

    local modal = test_of_fate_modal.createTestOfFateModal({
        eventBus = events.createEventBus(),
        deck = fakeDeck,
    })
    modal:startTest({
        entity = actor,
        attribute = "pentacles",
    })
    assertEqual(drawCount, 1, "Test Fate modal should draw a separate card for the test")
    assertTrue(modal.result.success, "high drawn card should pass the test")
    assertTrue(not modal.result.isGreat, "untyped Test Fate should not make every success great")
    modal:hide()

    modal:startTest({
        entity = actor,
        attribute = "pentacles",
        targetSuit = constants.SUITS.SWORDS,
    })
    assertEqual(drawCount, 2, "Second Test Fate should draw a fresh card")
    assertTrue(modal.result.isGreat, "explicit target suit should allow Great Success on matching draw")
    modal:hide()

    local favorDeck = {
        draw = function()
            return { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS }
        end,
        discard = function() end,
    }
    local favorModal = test_of_fate_modal.createTestOfFateModal({
        eventBus = events.createEventBus(),
        deck = favorDeck,
    })
    favorModal:startTest({
        entity = actor,
        attribute = "pentacles",
        favor = resolveSpentFavor,
    })
    assertEqual(favorModal.result.total, 14, "Resolve-spent favor should add +3 to Test Fate")
    assertTrue(favorModal.result.success, "Resolve-spent favor should be enough to pass this test")
    favorModal:hide()

    local cancelRequest = nil
    bus:on(events.EVENTS.REQUEST_TEST_OF_FATE, function(data)
        cancelRequest = data
    end)
    local cancel = resolver:resolve({
        actor = actor,
        card = { name = "Three of Cups", value = 3, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.TEST_FATE,
        disfavor = true,
        spendResolveForFavor = true,
        challengeController = {
            isActive = function()
                return true
            end,
        },
    })
    assertTrue(cancel.pendingTestOfFate, "Test Fate should still proceed when Resolve favor cancels disfavor")
    assertEqual(actor.resolve, 0, "Canceling disfavor with Resolve should spend one Resolve")
    assertEqual(cancelRequest.favor, nil, "Favor and disfavor should cancel to a neutral Test Fate")

    local autoEvent = nil
    bus:on("test_of_fate_auto_success", function(data)
        autoEvent = data
    end)
    local ironBeard = base_entity.createEntity({
        id = "pc_iron_beards",
        name = "Iron Beards",
        isPC = true,
        talents = {
            iron_beards = { mastered = true },
        },
    })
    ironBeard.resolve = 1
    local ironResult = resolver:resolve({
        actor = ironBeard,
        card = { name = "Two of Swords", value = 2, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.TEST_FATE,
        useAreteAutoSuccess = true,
        areteTalent = "iron_beards",
        testContext = "force a stuck portcullis through stubborn endurance",
        challengeController = {
            isActive = function()
                return true
            end,
        },
    })
    assertTrue(ironResult.success, "Iron Beards should auto-succeed on matching Tests of Fate")
    assertTrue(ironResult.areteAutoSuccess, "Iron Beards should mark arête auto-success")
    assertEqual(ironBeard.resolve, 0, "Iron Beards should spend one Resolve")
    assertTrue(hasValue(ironResult.effects, "arete_iron_beards"),
        "Iron Beards auto-success should report the talent")
    assertTrue(autoEvent and autoEvent.talentId == "iron_beards",
        "arête auto-success should emit talent details")

    local underfoot = base_entity.createEntity({
        id = "pc_underfoot",
        name = "Underfoot",
        isPC = true,
        talents = {
            underfoot = { mastered = true },
        },
    })
    underfoot.resolve = 1
    local underfootResult = resolver:resolve({
        actor = underfoot,
        card = { name = "Two of Pentacles", value = 2, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.TEST_FATE,
        useAreteAutoSuccess = true,
        areteTalent = "underfoot",
        testContext = "move quietly and stay subtle",
        challengeController = {
            isActive = function()
                return true
            end,
        },
    })
    assertTrue(underfootResult.success, "Underfoot should auto-succeed on quiet or subtle Tests of Fate")
    assertEqual(underfoot.resolve, 0, "Underfoot should spend one Resolve")
    assertTrue(hasValue(underfootResult.effects, "arete_underfoot"),
        "Underfoot auto-success should report the talent")

    local colossal = base_entity.createEntity({
        id = "pc_colossal",
        name = "Colossal",
        isPC = true,
        talents = {
            colossal = { mastered = true },
        },
    })
    colossal.resolve = 1
    local colossalResult = resolver:resolve({
        actor = colossal,
        card = { name = "Two of Wands", value = 2, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.TEST_FATE,
        useAreteAutoSuccess = true,
        areteTalent = "colossal",
        testContext = "smash down a door and change the battlefield",
        challengeController = {
            isActive = function()
                return true
            end,
        },
