    assertTrue(not noResolveResult.success, "arête auto-success should require Resolve")
    assertTrue(hasValue(noResolveResult.effects, "resolve_missing"),
        "missing arête Resolve should report missing Resolve")
end

local function checkGuardInitiativeReplacement()
    local guardDiscards = {}
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
        playerDeck = {
            discard = function(_, card)
                guardDiscards[#guardDiscards + 1] = card
            end,
        },
    })

    local actor = base_entity.createEntity({
        id = "pc_guard",
        name = "Shieldbearer",
        isPC = true,
    })
    actor.inventory = inventory.createInventory()
    actor.inventory:addItem(inventory.createItem({
        name = "Shield",
        size = 1,
        properties = { tags = { "shield" } },
    }), inventory.LOCATIONS.HANDS)

    local oldCard = { name = "Five of Swords", value = 5, suit = constants.SUITS.SWORDS }
    local newCard = { name = "Knight of Cups", value = 12, suit = constants.SUITS.CUPS }
    local slot = {
        card = oldCard,
        value = oldCard.value,
        revealed = false,
    }
    local controller = {
        getInitiativeSlot = function(_, entityId)
            if entityId == actor.id then
                return slot
            end
            return nil
        end,
    }

    local guard = resolver:resolve({
        actor = actor,
        card = newCard,
        type = action_resolver.ACTION_TYPES.GUARD,
        challengeController = controller,
    })
    assertTrue(guard.success, "Guard should succeed for a shield-bearing actor")
    assertTrue(hasValue(guard.effects, "guarded"), "Guard should record guarded effect")
    assertTrue(slot.card == newCard, "Guard should replace the initiative card")
    assertEqual(slot.value, 12, "Guard should replace initiative value with the played card")
    assertTrue(slot.revealed, "Guard should reveal the replacement initiative")
    assertTrue(hasValue(guard.effects, "guard_old_initiative_discarded"),
        "Guard should report discarding the old Initiative card")
    assertTrue(guardDiscards[1] == oldCard,
        "Guard should discard the replaced Initiative card to the actor's Challenge deck")
    assertEqual(guard.oldInitiativeValue, 5, "Guard should report the replaced Initiative value")
    assertEqual(guard.newInitiativeValue, 12, "Guard should report the replacement Initiative value")
    assertEqual(guard.oldInitiativeCard, oldCard, "Guard should report the replaced Initiative card")
    assertEqual(guard.newInitiativeCard, newCard, "Guard should report the replacement Initiative card")

    local guardPopup = getActionSequencerPopup({
        actor = actor,
        card = newCard,
        type = action_resolver.ACTION_TYPES.GUARD,
    }, guard, function(data)
        return data.title == "Guard"
    end)
    assertTrue(guardPopup ~= nil, "Guard should queue a visible Initiative replacement popup")
    assertEqual(guardPopup.oldInitiativeValue, 5, "Guard popup should preserve the old Initiative value")
    assertEqual(guardPopup.newInitiativeValue, 12, "Guard popup should preserve the new Initiative value")
    assertEqual(guardPopup.oldInitiativeCardDiscarded, oldCard,
        "Guard popup should preserve the discarded Initiative card")
    assertEqual(guardPopup.newInitiativeCard, newCard, "Guard popup should preserve the replacement card")
    assertTrue(guardPopup.discardedOldInitiative,
        "Guard popup should mark the old Initiative card discarded")

    local unshielded = base_entity.createEntity({
        id = "pc_no_shield",
        name = "No Shield",
        isPC = true,
    })
    local blocked = resolver:resolve({
        actor = unshielded,
        card = newCard,
        type = action_resolver.ACTION_TYPES.GUARD,
        challengeController = controller,
    })
    assertTrue(not blocked.success, "Guard should be blocked without a shield")
    assertEqual(blocked.description, "Requires shield", "Guard should explain shield requirement")
end

local function checkFacedownDefenseReplacement()
    local handDiscards = {}
    local handPC = base_entity.createEntity({
        id = "pc_facedown_hand_lifecycle",
        name = "Facedown Hand Lifecycle",
        isPC = true,
    })
    local heldDodgeCard = { name = "Four of Pentacles", value = 4, suit = constants.SUITS.PENTACLES }
    local heldAttackCard = { name = "Five of Swords", value = 5, suit = constants.SUITS.SWORDS }
    local heldAidCard = { name = "Two of Cups", value = 2, suit = constants.SUITS.CUPS }
    local lifecycleHand = player_hand.createPlayerHand({
        eventBus = events.createEventBus(),
        guild = { handPC },
        playerDeck = {
            discard = function(_, card)
                handDiscards[#handDiscards + 1] = card
            end,
        },
    })
    lifecycleHand.hands[handPC.id] = {
        cards = { heldDodgeCard, heldAttackCard, heldAidCard },
    }
    local keptCard = lifecycleHand:takeCard(handPC, {
        card = heldDodgeCard,
    })
    assertEqual(keptCard, heldDodgeCard,
        "facedown player action cards should be removable from hand without discard")
    assertEqual(#handDiscards, 0,
        "facedown player action cards should stay in play instead of discarding immediately")
    assertEqual(#lifecycleHand.hands[handPC.id].cards, 2,
        "keeping a facedown card in play should still remove it from the player's hand")
    local keptAidCard = lifecycleHand:takeCard(handPC, {
        card = heldAidCard,
    })
    assertEqual(keptAidCard, heldAidCard,
        "Aid Another facedown cards should also be removable from hand without discard")
    assertEqual(#handDiscards, 0,
        "Aid Another facedown cards should not be discarded immediately")
    local discardedCard = lifecycleHand:discardCard(handPC, {
        card = heldAttackCard,
        reason = "action",
    })
    assertEqual(discardedCard, heldAttackCard, "ordinary played cards should still discard from hand")
    assertEqual(#handDiscards, 1, "ordinary played cards should enter the player discard pile immediately")

    handPC.pendingDefense = { type = "dodge", card = heldDodgeCard }
    local drawIndex = 0
    local freshDraws = {
        { name = "Ace of Swords", value = 1, suit = constants.SUITS.SWORDS },
        { name = "Two of Cups", value = 2, suit = constants.SUITS.CUPS },
        { name = "Three of Wands", value = 3, suit = constants.SUITS.WANDS },
        { name = "Four of Pentacles", value = 4, suit = constants.SUITS.PENTACLES },
    }
    lifecycleHand.playerDeck = {
        draw = function()
            drawIndex = drawIndex + 1
            return freshDraws[drawIndex]
        end,
        discard = function(_, card)
            handDiscards[#handDiscards + 1] = card
        end,
    }
    lifecycleHand:drawHand(handPC)
    assertEqual(drawIndex, 4,
        "facedown actions in play should not reduce the next round's Challenge draw")
    assertEqual(#lifecycleHand:getHand(handPC), 4,
        "players should draw four Challenge cards even with a facedown action in play")
    assertTrue(handPC.pendingDefense and handPC.pendingDefense.card == heldDodgeCard,
        "drawing a new hand should leave unresolved facedown action state in play")
    freshDraws[5] = { name = "Five of Cups", value = 5, suit = constants.SUITS.CUPS }
    drawIndex = 0
    handPC.blackHoneyDrawFiveCards = true
    lifecycleHand:drawHand(handPC, { blackHoneyTeethLost = 3 })
    assertEqual(drawIndex, 5,
        "recent black honey should allow the player to draw five Challenge cards")
    assertEqual(#lifecycleHand:getHand(handPC), 5,
        "black honey draw should replace the normal four-card Challenge draw")
    assertTrue(lifecycleHand.hands[handPC.id].blackHoneyDraw,
        "black honey Challenge draws should be recorded for presentation/audit")
    assertEqual(lifecycleHand.hands[handPC.id].blackHoneyDraw.teethLost, 3,
        "black honey Challenge draw should record the 1-4 spat-out teeth consequence")
    assertEqual(handPC.blackHoneyLostTeeth, 3,
        "black honey teeth loss should persist on the character")
    assertEqual(handPC.bodyChanges[#handPC.bodyChanges].id, "black_honey_missing_teeth",
        "black honey teeth loss should be auditable as a physical body change")
    drawIndex = 0
    lifecycleHand:drawHand(handPC, { useBlackHoneyDrawFiveCards = false })
    assertEqual(drawIndex, 4,
        "black honey Challenge draw should remain an elective option")
    handPC.blackHoneyDrawFiveCards = nil

    local cleanupDiscards = {}
    local function cleanupDeck()
        return {
            discard = function(_, card)
                cleanupDiscards[#cleanupDiscards + 1] = card
            end,
        }
    end
    local cleanupPlayerDeck = cleanupDeck()
    local cleanupResolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
        playerDeck = cleanupPlayerDeck,
    })
    local cleanupController = challenge_controller.createChallengeController({
        eventBus = events.createEventBus(),
        playerDeck = cleanupPlayerDeck,
        gmDeck = cleanupDeck(),
        actionResolver = cleanupResolver,
    })
    local cleanupPC = base_entity.createEntity({
        id = "pc_facedown_cleanup",
        name = "Facedown Cleanup",
        isPC = true,
    })
    local defenseCleanupCard = { name = "Nine of Pentacles", value = 9, suit = constants.SUITS.PENTACLES }
    local vigilanceCleanupCard = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS }
    local aidCleanupCard = { name = "Three of Cups", value = 3, suit = constants.SUITS.CUPS }
    cleanupPC.pendingDefense = { type = "dodge", card = defenseCleanupCard }
    cleanupPC.pendingVigilance = { card = vigilanceCleanupCard }
    cleanupResolver.activeAids[cleanupPC.id] = {
        card = aidCleanupCard,
        discardDeck = cleanupPlayerDeck,
    }
    cleanupController.allCombatants = { cleanupPC }
    cleanupController:reset()
    assertTrue(hasValue(cleanupDiscards, defenseCleanupCard),
        "Challenge end should discard unresolved facedown defense cards")
    assertTrue(hasValue(cleanupDiscards, vigilanceCleanupCard),
        "Challenge end should discard unresolved Vigilance cards")
    assertTrue(hasValue(cleanupDiscards, aidCleanupCard),
        "Challenge end should discard unresolved Aid Another cards")
    assertTrue(cleanupPC.pendingDefense == nil and cleanupPC.pendingVigilance == nil,
        "Challenge end should clear pending facedown state")
    assertTrue(next(cleanupResolver.activeAids) == nil,
        "Challenge end should clear unresolved active Aid records")

    local discarded = {}
    local bus = events.createEventBus()
    local replacementEvent = nil
    bus:on("defense_replaced", function(data)
        replacementEvent = data
    end)
    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
        playerDeck = {
            discard = function(_, card)
                discarded[#discarded + 1] = card
            end,
        },
    })

    local actor = base_entity.createEntity({
        id = "pc_defense_replace",
        name = "Defense Replacer",
        isPC = true,
        pentacles = 1,
        swords = 2,
    })
    local dodgeCard = { name = "Five of Pentacles", value = 5, suit = constants.SUITS.PENTACLES }
    local riposteCard = { name = "Knight of Swords", value = 12, suit = constants.SUITS.SWORDS }

    local dodge = resolver:resolve({
        actor = actor,
        card = dodgeCard,
        type = action_resolver.ACTION_TYPES.DODGE,
    })
    assertTrue(dodge.success, "first facedown defense should prepare normally")
    assertEqual(actor:getDefense().type, "dodge", "first defense should be Dodge")

    local riposte = resolver:resolve({
        actor = actor,
        card = riposteCard,
        type = action_resolver.ACTION_TYPES.RIPOSTE,
    })
    assertTrue(riposte.success, "new facedown defense should replace the old one")
    assertTrue(hasValue(riposte.effects, "defense_replaced"),
        "defense replacement should be reported")
    assertEqual(#discarded, 1, "replaced facedown defense card should be discarded")
    assertTrue(discarded[1] == dodgeCard, "discard should receive the old defense card")
    assertEqual(actor:getDefense().type, "riposte", "new defense should become active")
    assertTrue(actor:getDefense().card == riposteCard, "new defense should keep the new card")
    assertTrue(replacementEvent ~= nil, "defense replacement should emit an event")
    assertEqual(replacementEvent.oldType, "dodge", "replacement event should name the old defense")
    assertEqual(replacementEvent.newType, "riposte", "replacement event should name the new defense")

    local sharedDiscards = {}
    local sharedResolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
        playerDeck = {
            discard = function(_, card)
                sharedDiscards[#sharedDiscards + 1] = card
            end,
        },
    })
    local sharedActor = base_entity.createEntity({
        id = "pc_shared_facedown_limit",
        name = "Shared Facedown Limit",
        isPC = true,
        pentacles = 1,
        swords = 1,
        cups = 1,
    })
    local sharedAlly = base_entity.createEntity({
        id = "pc_shared_facedown_ally",
        name = "Shared Facedown Ally",
        isPC = true,
    })
    local sharedDodgeCard = { name = "Five of Pentacles", value = 5, suit = constants.SUITS.PENTACLES }
    local sharedVigilanceCard = { name = "Seven of Swords", value = 7, suit = constants.SUITS.SWORDS }
    local sharedAidCard = { name = "Four of Cups", value = 4, suit = constants.SUITS.CUPS }
    local sharedSecondDodgeCard = { name = "Six of Pentacles", value = 6, suit = constants.SUITS.PENTACLES }

    local sharedDodge = sharedResolver:resolve({
        actor = sharedActor,
        card = sharedDodgeCard,
        type = action_resolver.ACTION_TYPES.DODGE,
    })
    assertTrue(sharedDodge.success, "shared facedown limit setup Dodge should prepare")

    local sharedVigilance = sharedResolver:resolve({
        actor = sharedActor,
        card = sharedVigilanceCard,
        type = action_resolver.ACTION_TYPES.VIGILANCE,
        followUpAction = action_resolver.ACTION_TYPES.MELEE,
    })
    assertTrue(sharedVigilance.success, "Vigilance should replace an existing facedown Dodge")
    assertTrue(hasValue(sharedVigilance.effects, "facedown_replaced"),
        "cross-type facedown replacement should be reported")
    assertTrue(hasValue(sharedDiscards, sharedDodgeCard),
        "Vigilance should discard the replaced facedown Dodge card")
    assertTrue(sharedActor.pendingDefense == nil,
        "Vigilance replacement should clear the old pending defense")
    assertTrue(sharedActor.pendingVigilance and sharedActor.pendingVigilance.card == sharedVigilanceCard,
        "Vigilance should become the actor's active facedown card")

    local sharedAid = sharedResolver:resolve({
        actor = sharedActor,
        target = sharedAlly,
        card = sharedAidCard,
        type = action_resolver.ACTION_TYPES.AID,
    })
    assertTrue(sharedAid.success, "Aid Another should replace an existing facedown Vigilance")
    assertTrue(hasValue(sharedDiscards, sharedVigilanceCard),
        "Aid Another should discard the replaced Vigilance card")
    assertTrue(sharedActor.pendingVigilance == nil,
        "Aid Another replacement should clear pending Vigilance")
    assertTrue(sharedResolver.activeAids[sharedAlly.id] and
        sharedResolver.activeAids[sharedAlly.id].card == sharedAidCard,
        "Aid Another should become the actor's active facedown card")

    local sharedSecondDodge = sharedResolver:resolve({
        actor = sharedActor,
        card = sharedSecondDodgeCard,
        type = action_resolver.ACTION_TYPES.DODGE,
    })
    assertTrue(sharedSecondDodge.success, "Dodge should replace an existing facedown Aid Another")
    assertTrue(hasValue(sharedDiscards, sharedAidCard),
        "Dodge should discard the replaced Aid Another card")
    assertTrue(sharedResolver.activeAids[sharedAlly.id] == nil,
        "Dodge replacement should clear the old active Aid record")
    assertTrue(sharedActor.pendingDefense and sharedActor.pendingDefense.card == sharedSecondDodgeCard,
        "Dodge should become the actor's active facedown card")

    local triggeredDiscards = {}
    local triggeredResolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
        playerDeck = {
            discard = function(_, card)
                triggeredDiscards[#triggeredDiscards + 1] = card
            end,
        },
    })
    local triggerDefender = base_entity.createEntity({
        id = "pc_triggered_defense_discard",
        name = "Triggered Defense Discard",
        isPC = true,
        pentacles = 1,
    })
    local triggerAttacker = base_entity.createEntity({
        id = "npc_triggered_defense_attacker",
        name = "Triggered Defense Attacker",
        isPC = false,
        swords = 3,
    })
    local triggeredDodgeCard = { name = "Three of Pentacles", value = 3, suit = constants.SUITS.PENTACLES }
    local triggeredDodge = triggeredResolver:resolve({
        actor = triggerDefender,
        card = triggeredDodgeCard,
        type = action_resolver.ACTION_TYPES.DODGE,
    })
    assertTrue(triggeredDodge.success, "triggered defense setup should prepare Dodge")
    local triggeredAttack = triggeredResolver:resolve({
        actor = triggerAttacker,
        target = triggerDefender,
        card = { name = "Ten of Swords", value = 10, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        weapon = { name = "Sword", isMelee = true },
    })
    assertTrue(hasValue(triggeredAttack.effects, "defense_card_discarded"),
        "revealed Dodge cards should be discarded after resolving")
    assertTrue(triggeredDiscards[1] == triggeredDodgeCard,
        "resolved Dodge should enter the player discard pile")
    assertTrue(triggerDefender.pendingDefense == nil,
        "resolved Dodge should clear the pending defense")

    local vigilanceDiscards = {}
    local vigilanceController = challenge_controller.createChallengeController({
        eventBus = events.createEventBus(),
        playerDeck = {
            discard = function(_, card)
                vigilanceDiscards[#vigilanceDiscards + 1] = card
            end,
        },
        gmDeck = {
            discard = function() end,
        },
    })
    local sentinel = base_entity.createEntity({
        id = "pc_vigilance_resolved_discard",
        name = "Vigilance Resolved Discard",
        isPC = true,
    })
    local foe = base_entity.createEntity({
        id = "npc_vigilance_trigger",
        name = "Vigilance Trigger",
        isPC = false,
    })
    local resolvedVigilanceCard = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS }
    sentinel.pendingVigilance = {
        card = resolvedVigilanceCard,
        trigger = { mode = "targeted_by_hostile_action", target = "self", hostileOnly = true, excludeSelf = true },
        followUpAction = action_resolver.ACTION_TYPES.MELEE,
        followUpTargetPolicy = "trigger_actor",
        declaredOrder = 1,
    }
    vigilanceController.allCombatants = { sentinel, foe }
    local vigilanceReactions = vigilanceController:collectTriggeredVigilanceReactions({
        actor = foe,
        target = sentinel,
        type = action_resolver.ACTION_TYPES.MELEE,
    })
    assertEqual(#vigilanceReactions, 1, "matching trigger should queue a Vigilance reaction")
    assertTrue(sentinel.pendingVigilance == nil,
        "triggered Vigilance should leave pending state while awaiting reaction resolution")
    assertEqual(#vigilanceDiscards, 0,
        "triggered Vigilance should stay in play until its reaction resolves")
    local vigilanceDiscard = vigilanceController:discardResolvedVigilanceReaction(vigilanceReactions[1], "test_resolved")
    assertTrue(vigilanceDiscard and vigilanceDiscard.discarded,
        "resolved Vigilance reaction should discard its facedown card")
    assertTrue(vigilanceDiscards[1] == resolvedVigilanceCard,
        "resolved Vigilance should enter the player discard pile")

    local cancelDiscards = {}
    local cancelEvents = {}
    local cancelBus = events.createEventBus()
    cancelBus:on("facedown_action_discarded", function(data)
        cancelEvents[#cancelEvents + 1] = data
    end)
    local cancelResolver = action_resolver.createActionResolver({
        eventBus = cancelBus,
        playerDeck = {
            discard = function(_, card)
                cancelDiscards[#cancelDiscards + 1] = card
            end,
        },
    })
    local cancelActor = base_entity.createEntity({
        id = "pc_facedown_cancel",
        name = "Facedown Cancel",
        isPC = true,
        cups = 1,
    })
    local cancelDodgeCard = { name = "Four of Pentacles", value = 4, suit = constants.SUITS.PENTACLES }
    local cancelDodgeSetup = cancelResolver:resolve({
        actor = cancelActor,
        card = cancelDodgeCard,
        type = action_resolver.ACTION_TYPES.DODGE,
    })
    assertTrue(cancelDodgeSetup.success, "voluntary facedown discard setup should prepare Dodge")
    local cancelDodge = cancelResolver:discardCurrentFacedownAction(cancelActor, {
        reason = "player_declined_facedown",
    })
    assertTrue(cancelDodge.success, "voluntary discard should clear a prepared facedown defense")
    assertTrue(hasValue(cancelDodge.effects, "facedown_discarded"),
        "voluntary discard should report facedown discard")
    assertTrue(hasValue(cancelDodge.effects, "dodge_discarded"),
        "voluntary discard should report the discarded facedown type")
    assertTrue(cancelDiscards[#cancelDiscards] == cancelDodgeCard,
        "voluntary discard should put the prepared defense card in discard")
    assertTrue(cancelActor.pendingDefense == nil,
        "voluntary discard should clear pending defense")
    assertTrue(cancelEvents[#cancelEvents] and cancelEvents[#cancelEvents].reason == "player_declined_facedown",
        "voluntary discard should emit the explicit reason")

    local nothingToCancel = cancelResolver:discardCurrentFacedownAction(cancelActor)
    assertTrue(not nothingToCancel.success, "discarding with no facedown action should be a no-op")
    assertTrue(hasValue(nothingToCancel.effects, "no_facedown_action"),
        "empty voluntary discard should report no facedown action")

    local cancelAidTarget = base_entity.createEntity({
        id = "pc_facedown_cancel_aid_target",
        name = "Facedown Cancel Aid Target",
        isPC = true,
    })
    local cancelAidCard = { name = "Three of Cups", value = 3, suit = constants.SUITS.CUPS }
    local cancelAidSetup = cancelResolver:resolve({
        actor = cancelActor,
        target = cancelAidTarget,
        card = cancelAidCard,
        type = action_resolver.ACTION_TYPES.AID,
    })
    assertTrue(cancelAidSetup.success, "voluntary facedown discard setup should bank Aid")
    local cancelAid = cancelResolver:discardCurrentFacedownAction(cancelActor, {
        reason = "player_declined_aid",
    })
    assertTrue(cancelAid.success, "voluntary discard should clear a banked Aid Another")
    assertTrue(hasValue(cancelAid.effects, "aid_discarded"),
        "voluntary discard should report discarded Aid Another")
    assertTrue(cancelDiscards[#cancelDiscards] == cancelAidCard,
        "voluntary discard should put the banked Aid card in discard")
    assertTrue(cancelResolver.activeAids[cancelAidTarget.id] == nil,
        "voluntary discard should clear the active Aid record")

    local cancelVigilanceDeck = {
        discard = function(_, card)
            cancelDiscards[#cancelDiscards + 1] = card
        end,
    }
    local cancelController = challenge_controller.createChallengeController({
        eventBus = cancelBus,
        playerDeck = cancelVigilanceDeck,
        gmDeck = { discard = function() end },
        actionResolver = cancelResolver,
    })
    local cancelVigilanceCard = { name = "Nine of Swords", value = 9, suit = constants.SUITS.SWORDS }
    local cancelVigilanceSetup = cancelResolver:resolve({
        actor = cancelActor,
        card = cancelVigilanceCard,
        type = action_resolver.ACTION_TYPES.VIGILANCE,
        followUpAction = action_resolver.ACTION_TYPES.MELEE,
        challengeController = cancelController,
    })
    assertTrue(cancelVigilanceSetup.success, "voluntary facedown discard setup should prepare Vigilance")
    local cancelVigilance = cancelController:discardFacedownAction(cancelActor, "player_declined_vigilance")
    assertTrue(cancelVigilance.success, "controller helper should discard prepared Vigilance")
    assertTrue(hasValue(cancelVigilance.effects, "vigilance_discarded"),
        "controller helper should report discarded Vigilance")
    assertTrue(cancelDiscards[#cancelDiscards] == cancelVigilanceCard,
        "controller helper should put the Vigilance card in discard")
    assertTrue(cancelActor.pendingVigilance == nil,
        "controller helper should clear pending Vigilance")
end

local function checkFacedownDefenseTimingValues()
    local preparedEvents = {}
    local bus = events.createEventBus()
    bus:on("defense_prepared", function(data)
        preparedEvents[#preparedEvents + 1] = data
    end)
    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
    })

    local mainDodger = base_entity.createEntity({
        id = "pc_main_dodge_value",
        name = "Main Dodge Value",
        isPC = true,
        pentacles = 3,
    })
    local dodge = resolver:resolve({
        actor = mainDodger,
        card = { name = "Five of Pentacles", value = 5, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.DODGE,
    })
    assertTrue(dodge.success, "turn-action Dodge should prepare")
    assertEqual(dodge.modifier, 3, "turn-action Dodge should add Pentacles to the prepared value")
    assertEqual(mainDodger:getDefense().value, 8, "turn-action Dodge should store card plus attribute")
    assertEqual(mainDodger:getDefense().faceValue, 5, "turn-action Dodge should retain face value")
    assertEqual(preparedEvents[#preparedEvents].modifier, 3, "defense event should expose the attribute modifier")
    assertEqual(dodge.preparedDefense.type, "dodge", "Dodge should expose prepared-defense metadata")
    assertEqual(dodge.preparedDefense.value, 8, "Dodge metadata should preserve the prepared value")
    do
        local popup = getActionSequencerPopup({
            actor = mainDodger,
            type = action_resolver.ACTION_TYPES.DODGE,
        }, dodge, function(data)
            return data.title == "Dodge"
        end)
        assertTrue(popup ~= nil, "prepared Dodge should queue an action-sequencer popup")
        assertEqual(popup.value, 8, "Dodge popup should preserve the prepared value")
        assertEqual(popup.modifier, 3, "Dodge popup should preserve the attribute modifier")
        assertTrue(not popup.isMinorAction, "Dodge popup should distinguish turn actions from minor actions")
    end

    local mainRiposter = base_entity.createEntity({
        id = "pc_main_riposte_value",
        name = "Main Riposte Value",
        isPC = true,
        swords = 4,
    })
    local riposte = resolver:resolve({
        actor = mainRiposter,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.RIPOSTE,
    })
    assertTrue(riposte.success, "turn-action Riposte should prepare")
    assertEqual(riposte.modifier, 4, "turn-action Riposte should add Swords to the prepared value")
    assertEqual(mainRiposter:getDefense().value, 12, "turn-action Riposte should store card plus attribute")
    assertEqual(riposte.preparedDefense.type, "riposte", "Riposte should expose prepared-defense metadata")
    assertEqual(riposte.preparedDefense.value, 12, "Riposte metadata should preserve the prepared value")
    do
        local popup = getActionSequencerPopup({
            actor = mainRiposter,
            type = action_resolver.ACTION_TYPES.RIPOSTE,
        }, riposte, function(data)
            return data.title == "Riposte"
        end)
        assertTrue(popup ~= nil, "prepared Riposte should queue an action-sequencer popup")
        assertEqual(popup.value, 12, "Riposte popup should preserve the prepared value")
        assertEqual(popup.modifier, 4, "Riposte popup should preserve the attribute modifier")
    end

    local minorDodger = base_entity.createEntity({
        id = "pc_minor_dodge_value",
        name = "Minor Dodge Value",
        isPC = true,
        pentacles = 3,
    })
    local minor = resolver:resolve({
        actor = minorDodger,
        card = { name = "Five of Pentacles", value = 5, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.DODGE,
        isMinorAction = true,
    })
    assertTrue(minor.success, "minor Dodge should prepare")
    assertEqual(minor.modifier, 0, "minor Dodge should not add the actor's attribute")
    assertEqual(minorDodger:getDefense().value, 5, "minor Dodge should store face value only")
    assertTrue(preparedEvents[#preparedEvents].isMinorAction, "minor defense event should mark minor timing")
    assertTrue(minor.preparedDefense.isMinorAction, "minor Dodge metadata should mark minor timing")
    do
        local popup = getActionSequencerPopup({
            actor = minorDodger,
            type = action_resolver.ACTION_TYPES.DODGE,
            isMinorAction = true,
        }, minor, function(data)
            return data.title == "Dodge"
        end)
        assertTrue(popup ~= nil, "minor Dodge should queue a prepared-defense popup")
        assertTrue(popup.isMinorAction, "minor Dodge popup should mark minor timing")
        assertEqual(popup.value, 5, "minor Dodge popup should preserve face-value-only defense")
    end

    local gmDiscards = {}
    local gmResolver = action_resolver.createActionResolver({
        eventBus = bus,
        gmDeck = {
            discard = function(_, card)
                gmDiscards[#gmDiscards + 1] = card
            end,
        },
    })
    local gmDefender = base_entity.createEntity({
        id = "npc_gm_facedown_value",
        name = "GM Facedown Value",
        isPC = false,
        health = 2,
        defense = 0,
        pentacles = 2,
        swords = 3,
    })
    local gmDodgeCard = major(6)
    local gmRiposteCard = major(4)
    local gmDodge = gmResolver:resolve({
        actor = gmDefender,
        card = gmDodgeCard,
        type = action_resolver.ACTION_TYPES.DODGE,
    })
    assertTrue(gmDodge.success, "GM lesser-doom turn Dodge should prepare")
    assertEqual(gmDodge.modifier, 2, "GM turn Dodge should add the enemy's Pentacles")
    assertEqual(gmDefender:getDefense().value, 8,
        "GM turn Dodge should store lesser doom plus attribute")
    assertEqual(#gmDiscards, 0, "prepared GM facedown actions should remain in play")

    local gmRiposte = gmResolver:resolve({
        actor = gmDefender,
        card = gmRiposteCard,
        type = action_resolver.ACTION_TYPES.RIPOSTE,
    })
    assertTrue(gmRiposte.success, "GM lesser-doom Riposte should replace the old facedown action")
    assertTrue(hasValue(gmRiposte.effects, "defense_replaced"),
        "GM facedown replacement should be reported")
    assertEqual(#gmDiscards, 1, "GM replaced facedown card should discard to the GM deck")
    assertTrue(gmDiscards[1] == gmDodgeCard, "GM discard should receive the replaced facedown card")
    assertEqual(gmDefender:getDefense().type, "riposte", "GM replacement should store Riposte")
    assertEqual(gmDefender:getDefense().value, 7,
        "GM turn Riposte should store lesser doom plus Swords")
    assertTrue(gmRiposte.preparedDefense.replacedDefense ~= nil,
        "replacement Riposte metadata should preserve the discarded facedown action")
    do
        local popup = getActionSequencerPopup({
            actor = gmDefender,
            type = action_resolver.ACTION_TYPES.RIPOSTE,
        }, gmRiposte, function(data)
            return data.title == "Riposte"
        end)
        assertTrue(popup ~= nil, "replacement Riposte should queue a prepared-defense popup")
        assertTrue(popup.replacedDefense ~= nil, "Riposte popup should preserve replaced defense metadata")
        assertTrue(popup.replacedDefenseDiscarded, "Riposte popup should preserve replacement discard state")
    end

    local gmMinorDefender = base_entity.createEntity({
        id = "npc_gm_minor_facedown_value",
        name = "GM Minor Facedown Value",
        isPC = false,
        health = 2,
        defense = 0,
        pentacles = 4,
    })
    local gmMinor = gmResolver:resolve({
        actor = gmMinorDefender,
        card = major(9),
        type = action_resolver.ACTION_TYPES.DODGE,
        isMinorAction = true,
    })
    assertTrue(gmMinor.success, "GM lesser-doom minor Dodge should prepare")
    assertEqual(gmMinor.modifier, 0, "GM minor Dodge should not add the enemy's attribute")
    assertEqual(gmMinorDefender:getDefense().value, 9,
        "GM minor Dodge should store the lesser doom face value only")
end

local function checkAllyPreparedDefenseInSameZone()
    local bus = events.createEventBus()
    local riposteHit = nil
    bus:on("riposte_hit", function(data)
        riposteHit = data
    end)
    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
    })

    local attacker = base_entity.createEntity({
        id = "npc_ally_defense_attacker",
        name = "Ally Defense Attacker",
        isPC = false,
        health = 2,
        defense = 0,
        swords = 0,
        zone = "near",
    })
    local target = base_entity.createEntity({
        id = "pc_ally_defense_target",
        name = "Protected Ally",
        isPC = true,
        zone = "near",
    })
    local defender = base_entity.createEntity({
        id = "pc_ally_defender",
        name = "Same Zone Defender",
        isPC = true,
        zone = "near",
    })

    local preparedOk = defender:prepareDefense("dodge",
        { name = "Eight of Pentacles", value = 8, suit = constants.SUITS.PENTACLES },
        8)
    assertTrue(preparedOk, "same-zone ally should be able to prepare a defense")

    local dodged = resolver:resolve({
        actor = attacker,
        target = target,
        card = { name = "Knight of Swords", value = 12, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        weapon = { name = "Claws", isMelee = true },
        targetInitiative = 5,
        allEntities = { target, defender, attacker },
    })
    assertTrue(not dodged.success, "same-zone ally Dodge should be able to protect the target")
    assertTrue(hasValue(dodged.effects, "ally_defense_used"),
        "same-zone ally defense should be reported")
    assertTrue(hasValue(dodged.effects, "dodged"), "ally Dodge should use the normal Dodge result")
    assertTrue(not defender:hasDefense(), "ally Dodge should be consumed when used")
    assertEqual(target:getWoundsTaken(), 0, "protected target should not take a Wound after ally Dodge")

    local riposteDefender = base_entity.createEntity({
        id = "pc_ally_riposter",
        name = "Same Zone Riposter",
        isPC = true,
        zone = "near",
    })
    riposteDefender.weapon = { name = "Sword", weaponType = "sword" }
    preparedOk = riposteDefender:prepareDefense("riposte",
        { name = "Knight of Swords", value = 12, suit = constants.SUITS.SWORDS },
        12)
    assertTrue(preparedOk, "same-zone ally should be able to prepare Riposte")

    local riposted = resolver:resolve({
        actor = attacker,
        target = target,
        card = { name = "Seven of Swords", value = 7, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        weapon = { name = "Claws", isMelee = true },
        targetInitiative = 5,
        allEntities = { target, riposteDefender, attacker },
    })
    assertTrue(riposted.success, "the original attack can still hit when ally Riposte is used")
    assertTrue(hasValue(riposted.effects, "ally_defense_used"),
        "same-zone ally Riposte should be reported")
    assertTrue(riposted.riposteResult and riposted.riposteResult.success,
        "same-zone ally Riposte should counterattack")
    assertEqual(riposteHit.defender, riposteDefender, "Riposte event should credit the ally defender")
    assertEqual(attacker.npcHealth, 0, "ally sword Riposte should damage the attacker")
    assertTrue(not riposteDefender:hasDefense(), "ally Riposte should be consumed when used")

    local polearmDefender = base_entity.createEntity({
        id = "pc_polearm_riposter",
        name = "Polearm Riposter",
        isPC = true,
        zone = "near",
        swords = 2,
    })
    polearmDefender.inventory = inventory.createInventory()
    local interruptPolearm = inventory.createItem({
        name = "Spear",
        size = 2,
        durability = 2,
        weaponType = "polearm",
        isWeapon = true,
        isMelee = true,
    })
    polearmDefender.inventory:addItem(interruptPolearm, inventory.LOCATIONS.HANDS)
    local polearmPrepare = resolver:resolve({
        actor = polearmDefender,
        card = { name = "Eight of Swords", value = 8, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.RIPOSTE,
        weapon = interruptPolearm,
    })
    assertTrue(polearmPrepare.success, "polearm user should prepare Riposte normally")
    assertEqual(polearmDefender:getDefense().weapon, interruptPolearm,
        "prepared Riposte should remember the wielded polearm")
    local chargingAttacker = base_entity.createEntity({
        id = "npc_polearm_riposte_attacker",
        name = "Polearm Riposte Attacker",
        isPC = false,
        health = 1,
        defense = 0,
        zone = "near",
    })
    local interruptedAttack = resolver:resolve({
        actor = chargingAttacker,
        target = polearmDefender,
        card = { name = "Five of Swords", value = 5, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        weapon = { name = "Claws", isMelee = true },
        targetInitiative = 4,
    })
    assertTrue(interruptedAttack.riposteResult and interruptedAttack.riposteResult.success,
        "polearm Riposte should resolve before the incoming Attack")
    assertTrue(hasValue(interruptedAttack.effects, "polearm_riposte_interrupt"),
        "polearm Riposte should report interrupt timing")
    assertTrue(hasValue(interruptedAttack.effects, "interrupted_by_polearm_riposte"),
        "defeating the attacker with polearm Riposte should cancel the incoming Attack")
    assertTrue(not interruptedAttack.success,
        "the interrupted Attack should not resolve after the attacker is defeated")
    assertEqual(polearmDefender:getWoundsTaken(), 0,
        "polearm Riposte should protect the defender when it drops the attacker")
    assertEqual(chargingAttacker.npcHealth, 0,
        "polearm Riposte should wound the attacker before their Attack resolves")

    local movedDiscarded = {}
    local movedDefenseEvent = nil
    local moveBus = events.createEventBus()
    moveBus:on("defense_discarded", function(data)
        movedDefenseEvent = data
    end)
    local moveResolver = action_resolver.createActionResolver({
        eventBus = moveBus,
        playerDeck = {
            discard = function(_, card)
                movedDiscarded[#movedDiscarded + 1] = card
            end,
        },
    })
    local mobileDefender = base_entity.createEntity({
        id = "pc_mobile_ally_defender",
        name = "Mobile Ally Defender",
        isPC = true,
        zone = "near",
        pentacles = 1,
    })
    local protectedAlly = base_entity.createEntity({
        id = "pc_protected_ally_stays",
        name = "Protected Ally Stays",
        isPC = true,
        zone = "near",
    })
    local allyDodgeCard = { name = "Six of Pentacles", value = 6, suit = constants.SUITS.PENTACLES }
    local allyDodge = moveResolver:resolve({
        actor = mobileDefender,
        card = allyDodgeCard,
        type = action_resolver.ACTION_TYPES.DODGE,
        protectedTarget = protectedAlly,
    })
    assertTrue(allyDodge.success, "explicit ally defense should prepare normally")
    assertEqual(mobileDefender:getDefense().protectedTarget, protectedAlly,
        "prepared ally defense should remember the protected target")

    local movedAway = moveResolver:resolve({
        actor = mobileDefender,
        card = { name = "Three of Cups", value = 3, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.MOVE,
        destinationZone = "far",
        challengeController = {
            zones = {
                { id = "near", name = "Near" },
                { id = "far", name = "Far" },
            },
        },
    })
    assertTrue(movedAway.success, "defender movement should still resolve")
    assertTrue(not mobileDefender:hasDefense(),
        "moving away from a protected ally should discard the facedown defense")
    assertEqual(#movedDiscarded, 1, "moved-away ally defense card should be discarded")
    assertTrue(movedDiscarded[1] == allyDodgeCard,
        "moved-away ally defense should discard the prepared card")
    assertTrue(hasValue(movedAway.effects, "protected_defense_discarded"),
        "moved-away ally defense discard should be reported on movement")
    assertTrue(movedDefenseEvent and movedDefenseEvent.reason == "moved_away_from_protected_ally",
        "moved-away ally defense should emit the rulebook discard reason")
end

local function checkCommandCompanionActions()
    local animalCompanions = require('data.animal_companions')
    assertEqual(animalCompanions.normalizeCommandName("Sic 'Em"), "sic_em",
        "animal companion registry should normalize Sic 'Em")
    assertTrue(animalCompanions.getCommand("Track") ~= nil,
        "animal companion registry should expose canonical Track command")
    local companionRules = animalCompanions.getRules()
    assertEqual(companionRules.commandLimit, "Most normal animals can learn three commands.",
        "animal companion rule metadata should preserve the normal command limit")
    assertTrue(companionRules.hirelings.supported == false,
        "animal companion rule metadata should preserve the no-hirelings rule")
    companionRules.hirelings.supported = true
    assertTrue(animalCompanions.getRules().hirelings.supported == false,
        "animal companion rule metadata should be copy-safe")
    local hirelingOk, hirelingReason, hirelingDetail = animalCompanions.validateHirelingRequest({
        type = "mercenary",
    })
    assertTrue(not hirelingOk, "animal companion authoring should reject hireling-style followers")
    assertEqual(hirelingReason, "Hirelings are not supported by the rulebook",
        "hireling rejection should explain the rulebook constraint")
    assertTrue(hirelingDetail.rule and hirelingDetail.rule.supported == false,
        "hireling rejection should expose rule metadata")
    local mothTemplate = animalCompanions.getTemplate("dire moth")
    assertTrue(mothTemplate ~= nil and mothTemplate.feedType == "dire moth",
        "animal companion registry should expose rulebook example templates")
    local dogTemplate, dogTemplateId = animalCompanions.getTemplate("small but vicious dogs")
    assertTrue(dogTemplate ~= nil and dogTemplateId == "hound",
        "animal companion registry should map rulebook dog wording to hounds")
    local falconTemplate, falconTemplateId = animalCompanions.getTemplate("hunting falcons")
    assertTrue(falconTemplate ~= nil and falconTemplateId == "falcon",
        "animal companion registry should map hunting falcons to falcon templates")
    local boarTemplate, boarTemplateId = animalCompanions.getTemplate("riding boars")
    assertTrue(boarTemplate ~= nil and boarTemplateId == "riding_boar",
        "animal companion registry should map riding boars to boar templates")
    local mothAliasTemplate, mothAliasTemplateId = animalCompanions.getTemplate("trained dire moths")
    assertTrue(mothAliasTemplate ~= nil and mothAliasTemplateId == "dire_moth",
        "animal companion registry should map trained dire moths to dire moth templates")
    local companionRegistryValidation = animalCompanions.validateRegistry()
    assertTrue(companionRegistryValidation.ok,
        "animal companion registry authoring should validate cleanly")
    assertEqual(companionRegistryValidation.commandCount, #animalCompanions.commandOrder,
        "animal companion registry validation should account for every canonical command")
    local overtrainedCommands = animalCompanions.validateCommandList({ "Fetch", "Stay", "Track", "Guard" })
    assertTrue(not overtrainedCommands.ok,
        "animal companion command validation should enforce the normal three-command limit")
    assertEqual(overtrainedCommands.errors[1].code, "command_limit_exceeded",
        "animal companion command validation should report command-limit failures")
    local unknownCommands = animalCompanions.validateCommandList({ "Fetch", "Dance" })
    assertTrue(not unknownCommands.ok and unknownCommands.errors[1].code == "unknown_command",
        "animal companion command validation should reject noncanonical commands")
    local metadataCommand = animalCompanions.validateCommandList({
        { command = "Fetch", commandTestOfFate = true, companionTestTags = { "grab" } },
    })
    assertTrue(metadataCommand.ok and metadataCommand.normalizedCommands[1] == "fetch",
        "animal companion command validation should accept authored command metadata entries")
    local missingCommandName = animalCompanions.validateCommandList({
        { trick = "spin in place" },
    })
    assertTrue(not missingCommandName.ok and missingCommandName.errors[1].code == "command_missing",
        "animal companion command validation should reject metadata entries without a command name")
    local familiarValidation = animalCompanions.validateCompanion(animalCompanions.createCompanion("hound", {
        isFamiliar = true,
        knownCommands = { "Sic 'Em", "Fetch", "Guard", "Track", "Stay" },
    }))
    assertTrue(familiarValidation.ok and familiarValidation.commandLimit == 5,
        "animal companion validation should allow familiar five-command authoring")
    local carryingValidation = animalCompanions.validateCompanion(animalCompanions.createCompanion("horse", {
        carrySlots = 2,
        knownCommands = { "Stay" },
    }), {
        strictCarrySlots = true,
    })
    assertTrue(not carryingValidation.ok and carryingValidation.errors[1].code == "carrying_slots_forbidden",
        "animal companion validation should flag non-rulebook carrying slots in strict mode")
    local houndCompanion = animalCompanions.createCompanion("small but vicious dog", {
        id = "hound_options",
        name = "Options Hound",
        knownCommands = { "Track", "Guard" },
        conditions = {
            staggered = true,
        },
    })
    local companionOptions = animalCompanions.getCompanionOptions({
        owner = {
            animalCompanions = { houndCompanion },
        },
        companionId = "hound_options",
        command = "Track",
        template = "trained dire moths",
    })
    assertEqual(companionOptions.resultPreview, "animal_companion_options_ready",
        "animal companion options should report non-mutating option readiness")
    assertEqual(companionOptions.selectedCompanion.feedType, "hound",
        "animal companion options should preserve selected companion feed type")
    assertTrue(companionOptions.selectedCompanion.conditions.staggered,
        "animal companion options should preview companion wound-state conditions")
    assertEqual(companionOptions.commandLimit, 3,
        "animal companion options should preserve the normal command limit")
    assertEqual(companionOptions.commandSlotsRemaining, 1,
        "animal companion options should preview remaining command slots")
    assertTrue(companionOptions.selectedCommandOption.known,
        "animal companion options should flag trained selected commands")
    local fetchOption = nil
    for _, option in ipairs(companionOptions.commandOptions) do
        if option.key == "fetch" then
            fetchOption = option
            break
        end
    end
    assertTrue(fetchOption ~= nil and fetchOption.disabled,
        "animal companion options should disable untrained commands for a selected companion")
    assertEqual(fetchOption.unavailableReason, "Command not trained",
        "animal companion options should explain untrained command gates")
    assertTrue(companionOptions.selectedTemplate ~= nil and companionOptions.selectedTemplate.id == "dire_moth",
        "animal companion options should map rulebook template aliases")
    companionOptions.rules.hirelings.supported = true
    assertTrue(animalCompanions.getCompanionOptions().rules.hirelings.supported == false,
        "animal companion options should return copy-safe rule metadata")
    local weakCompanionOptions = animalCompanions.getCompanionOptions({
        companion = animalCompanions.createCompanion("hound", {
            id = "weak_hound_options",
            knownCommands = { "Sic 'Em" },
            conditions = {
                weak = true,
            },
        }),
        command = "Sic 'Em",
    })
    assertTrue(weakCompanionOptions.selectedCompanion.disabled,
        "animal companion options should flag weak or starving companion command blocks")
    assertEqual(weakCompanionOptions.selectedCommandOption.unavailableReason, "Animal companion needs feed",
        "animal companion options should explain feed-gated command blocks")

    local commandBus = events.createEventBus()
    local companionTestRequests = {}
    commandBus:on(events.EVENTS.REQUEST_TEST_OF_FATE, function(data)
        companionTestRequests[#companionTestRequests + 1] = data
    end)
    local sharedInitiativeReveal = nil
    commandBus:on(events.EVENTS.INITIATIVE_REVEALED, function(data)
        sharedInitiativeReveal = data
    end)
    local resolver = action_resolver.createActionResolver({
        eventBus = commandBus,
    })

    local actor = base_entity.createEntity({
        id = "pc_commander",
        name = "Beast Master",
        isPC = true,
        cups = 3,
    })
    local hound = {
        id = "hound_1",
        name = "Hound",
        isPC = true,
        zone = "near",
        damage = 1,
        conditions = {},
        knownCommands = { "Sic 'Em", "Fetch", "Guard" },
    }
    actor.companion = hound

    local target = base_entity.createEntity({
        id = "npc_target",
        name = "Goblin",
        isPC = false,
        health = 2,
        defense = 0,
        zone = "near",
    })

    local sicEm = resolver:resolve({
        actor = actor,
        card = { name = "Cups", value = 8, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.COMMAND,
        commandName = "Sic 'Em",
        target = target,
        targetInitiative = 7,
    })
    assertTrue(sicEm.success, "known Sic 'Em command should succeed against beaten Initiative")
    assertEqual(target.npcHealth, 1, "Sic 'Em should apply companion attack damage")
    assertEqual(hound.lastCommand, "sic_em", "companion should record last command")

    local unknown = resolver:resolve({
        actor = actor,
        card = { name = "Cups", value = 8, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.COMMAND,
        commandName = "Dance",
    })
    assertTrue(not unknown.success, "unknown companion command should be rejected")

    local rope = inventory.createItem({ name = "Rope", size = 1 })
    local fetch = resolver:resolve({
        actor = actor,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.COMMAND,
        commandName = "Fetch",
        item = rope,
    })
    assertTrue(fetch.success, "Fetch should be legal with any card value when no combatant is targeted")
    assertTrue(fetch.fetchedItem == rope, "Fetch should expose fetched item on the result")
    local actionSequencer = require('ui.action_sequencer')
    local commandSequencer = actionSequencer.createActionSequencer({ eventBus = events.createEventBus() })
    commandSequencer:queueActionSequence({
        action = {
            actor = actor,
            companion = hound,
            card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
            commandName = "Fetch",
            item = rope,
        },
        result = fetch,
    })
    local hasCommandPopup = false
    for _, step in ipairs(commandSequencer.currentSequence or {}) do
        if step.type == actionSequencer.STEP_TYPES.TEXT_POPUP and
           step.data and step.data.title == "Command" then
            hasCommandPopup = true
            assertEqual(step.data.companion, hound,
                "Command popup should preserve the acting companion")
            assertEqual(step.data.commandName, "fetch",
                "Command popup should preserve the normalized command")
            assertEqual(step.data.item, rope,
                "Command popup should preserve the fetched item")
            break
        end
    end
    assertTrue(hasCommandPopup, "resolved companion commands should queue a visible command popup")

    local objectFetch = resolver:resolve({
        actor = actor,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.COMMAND,
        commandName = "Fetch",
        target = rope,
        item = rope,
        targetInitiative = 99,
    })
    assertTrue(objectFetch.success,
        "Fetch should not compare against Initiative when the supplied target is an object")
    assertTrue(objectFetch.fetchedItem == rope,
        "object-targeted Fetch should still expose the fetched item on the result")

    local commandFieldCompanion = {
        id = "hound_command_field",
        name = "Command Field Hound",
        conditions = {},
        knownCommands = {
            { command = "Fetch", commandTestOfFate = true },
        },
    }
    local commandFieldFetch = resolver:resolve({
        actor = actor,
        companion = commandFieldCompanion,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.COMMAND,
        commandName = "Fetch",
        item = rope,
    })
    assertTrue(commandFieldFetch.success,
        "resolver should recognize command-field companion metadata as a known command")

    hound.conditions.weak = true
    local weak = resolver:resolve({
        actor = actor,
        card = { name = "Cups", value = 8, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.COMMAND,
        commandName = "Guard",
    })
    assertTrue(not weak.success, "weak animal companion should not follow commands")

    local abandonedCompanion = {
        id = "hound_abandoned_command",
        name = "Abandoned Hound",
        conditions = { abandoned = true },
        abandoned = true,
        knownCommands = { "Fetch" },
    }
    local abandonedCommand = resolver:resolve({
        actor = actor,
        companion = abandonedCompanion,
        card = { name = "Cups", value = 8, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.COMMAND,
        commandName = "Fetch",
    })
    assertTrue(not abandonedCommand.success, "abandoned animal companion should not follow commands")
    assertTrue(hasValue(abandonedCommand.effects, "command_blocked"),
        "abandoned animal companion command should report a command block")

    local initiativeOwner = base_entity.createEntity({
        id = "pc_companion_initiative_owner",
        name = "Companion Initiative Owner",
        isPC = true,
    })
    local initiativeCompanion = animalCompanions.createCompanion("hound", {
        id = "hound_shared_initiative",
        name = "Shared Initiative Hound",
        knownCommands = { "Guard" },
    })
    initiativeOwner.animalCompanions = { initiativeCompanion }
    local ownerInitiativeSlot = {
        card = { name = "Six of Cups", value = 6, suit = constants.SUITS.CUPS },
        value = 6,
        revealed = false,
    }
    local sharedInitiative = resolver:getTargetInitiative(initiativeCompanion, {
        target = initiativeCompanion,
        challengeController = {
            guild = { initiativeOwner },
            getInitiativeSlot = function(_, entityId)
                if entityId == initiativeOwner.id then
                    return ownerInitiativeSlot
                end
                return nil
            end,
        },
    })
    assertEqual(sharedInitiative, 6,
        "animal companions should share their master's Initiative when targeted")
    assertTrue(ownerInitiativeSlot.revealed,
        "targeting an animal companion should reveal the master's Initiative")
    assertTrue(sharedInitiativeReveal and sharedInitiativeReveal.entity == initiativeOwner and
        sharedInitiativeReveal.companion == initiativeCompanion,
        "shared companion Initiative should emit the master reveal with companion context")
    assertEqual(initiativeCompanion.sharedInitiativeOwnerId, initiativeOwner.id,
        "shared companion Initiative should record its master")

    local tracker = {
        id = "hound_tracker",
        name = "Tracker Hound",
        zone = "near",
        conditions = {},
        knownCommands = { "Track", "Hunt", "Get Help", "Do a Trick" },
    }
    local track = resolver:resolve({
        actor = actor,
        companion = tracker,
        card = { name = "Cups", value = 3, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.COMMAND,
        commandName = "Track",
        trackSubject = "ogre spoor",
        contestedCommand = false,
    })
    assertTrue(track.success, "Track should resolve as a concrete companion command")
    assertTrue(hasValue(track.effects, "companion_track"), "Track should report its concrete command effect")
    assertEqual(tracker.tracking.subject, "ogre spoor", "Track should record the followed trail")

    local monkey = animalCompanions.createCompanion("monkey", {
        id = "monkey_test",
        name = "Climbing Monkey",
        knownCommands = { "Fetch" },
    })
    local suitedTest = resolver:resolve({
        actor = actor,
        companion = monkey,
        card = { name = "Cups", value = 3, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.COMMAND,
        commandName = "Fetch",
        commandTestOfFate = true,
        companionTestTags = { "climb", "grab" },
        companionTestDescription = "Monkey climbs for the key.",
        contestedCommand = false,
    })
    assertTrue(suitedTest.success and suitedTest.pendingTestOfFate,
        "companion command should request Test of Fate when commanded task calls for it")
    assertTrue(hasValue(suitedTest.effects, "companion_test_favor"),
        "suited companion tests should report favor")
    assertEqual(companionTestRequests[#companionTestRequests].favor, true,
        "suited companion tests should pass favor to Test of Fate")
    assertEqual(monkey.companionFate, 0,
        "companion tests should default to no attribute bonus before favor")

    local suitedDisfavorTest = resolver:resolve({
        actor = actor,
        companion = monkey,
        card = { name = "Cups", value = 3, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.COMMAND,
        commandName = "Fetch",
        commandTestOfFate = true,
        companionTestTags = { "climb" },
        disfavor = true,
        contestedCommand = false,
    })
    assertTrue(suitedDisfavorTest.success and suitedDisfavorTest.pendingTestOfFate,
        "suited companion tests with disfavor should still request Test of Fate")
    assertEqual(companionTestRequests[#companionTestRequests].favor, nil,
        "suited companion favor should cancel companion test disfavor to neutral")

    local unsuitedTest = resolver:resolve({
        actor = actor,
        companion = tracker,
        card = { name = "Cups", value = 3, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.COMMAND,
        commandName = "Track",
        commandTestOfFate = true,
        companionTestTags = { "pick_lock" },
        contestedCommand = false,
    })
    assertTrue(unsuitedTest.success and unsuitedTest.pendingTestOfFate,
        "unsuited companion tests should still request Test of Fate")
    assertTrue(hasValue(unsuitedTest.effects, "companion_test_no_bonus"),
        "unsuited companion tests should report no bonus")
    assertEqual(companionTestRequests[#companionTestRequests].favor, nil,
        "unsuited companion tests should not pass favor")

    local hunt = resolver:resolve({
        actor = actor,
        companion = tracker,
        card = { name = "Cups", value = 3, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.COMMAND,
        commandName = "Hunt",
        commandObjective = "fresh scent",
        contestedCommand = false,
    })
    assertTrue(hunt.success, "Hunt should resolve as a concrete companion command")
    assertTrue(hasValue(hunt.effects, "companion_hunt"), "Hunt should report its concrete command effect")
    assertEqual(hunt.huntTarget, "fresh scent",
        "Hunt should preserve authored command objective text as the hunted subject")
    assertEqual(tracker.currentCommand.objective, "fresh scent",
        "companion current command should retain authored objective text")

    local help = resolver:resolve({
        actor = actor,
        companion = tracker,
        card = { name = "Cups", value = 3, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.COMMAND,
        commandName = "Get Help",
        contestedCommand = false,
    })
    assertTrue(help.success, "Get Help should resolve as a concrete companion command")
    assertTrue(hasValue(help.effects, "companion_get_help"), "Get Help should report its concrete command effect")

    local trick = resolver:resolve({
        actor = actor,
        companion = tracker,
        card = { name = "Cups", value = 3, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.COMMAND,
        commandName = "Do a Trick",
        trick = "distract the guard",
        contestedCommand = false,
    })
    assertTrue(trick.success, "Do a Trick should resolve as a concrete companion command")
    assertTrue(hasValue(trick.effects, "companion_trick"), "Do a Trick should report its concrete command effect")

    actor.zone = "near"
    local positioningCompanion = {
        id = "hound_positioning",
        name = "Positioning Hound",
        zone = "far",
        conditions = {},
        knownCommands = { "Heel", "Stay" },
    }
    local heel = resolver:resolve({
        actor = actor,
        companion = positioningCompanion,
        card = { name = "Cups", value = 3, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.COMMAND,
        commandName = "Heel",
        contestedCommand = false,
    })
    assertTrue(heel.success, "Heel should resolve as a concrete companion command")
    assertEqual(positioningCompanion.zone, "near", "Heel should bring the companion to the owner's zone")
    assertTrue(not positioningCompanion.staying, "Heel should clear any Stay marker")

    positioningCompanion.zone = "far"
    local stay = resolver:resolve({
        actor = actor,
        companion = positioningCompanion,
        card = { name = "Cups", value = 3, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.COMMAND,
        commandName = "Stay",
        contestedCommand = false,
    })
    assertTrue(stay.success, "Stay should resolve as a concrete companion command")
    assertEqual(positioningCompanion.zone, "far", "Stay should leave the companion in its current zone")
    assertTrue(positioningCompanion.staying, "Stay should mark the companion as staying put")
    assertEqual(positioningCompanion.stayZone, "far", "Stay should remember the zone where the companion stayed")

    local independentHound = animalCompanions.createCompanion("hound", {
        id = "hound_independent_action",
        name = "Independent Hound",
        knownCommands = { "Sic 'Em" },
    })
    local independentAction = resolver:resolve({
        actor = independentHound,
        card = { name = "Swords", value = 9, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        target = target,
        targetInitiative = 1,
    })
    assertTrue(not independentAction.success,
        "animal companions should not take ordinary Challenge actions outside Command")
    assertTrue(hasValue(independentAction.effects, "animal_companion_needs_command"),
        "blocked companion actions should report the command requirement")

    local registryActor = {
        animalCompanions = { { id = "mule_1", knownCommands = { "Fetch" }, conditions = {} } },
    }
    local ok, reason = action_registry.checkActionRequirements(action_registry.getAction("command"), registryActor)
    assertTrue(ok and reason == nil, "action registry should accept animalCompanions for Command")
end

local function checkCommandBoardCompanionCommandSelection()
    local previousLove = love
    love = {
        graphics = {
            getDimensions = function()
                return 1280, 720
            end,
        },
    }

    local emitted = nil
    local bus = events.createEventBus()
    bus:on("action_selected", function(data)
        emitted = data
    end)

    local board = command_board.createCommandBoard({ eventBus = bus })
    local actor = {
        id = "pc_command_ui",
        name = "Beast Master",
        isPC = true,
        cups = 3,
        conditions = {},
        companion = {
            id = "hound_ui",
            name = "Hound",
            conditions = {},
            knownCommands = {
                "Sic 'Em",
                { name = "Do a Trick", trick = "distract the guard" },
                {
