local function checkVigilanceTriggerTemplates()
    local controller = challenge_controller.createChallengeController({
        eventBus = events.createEventBus(),
    })

    local sentinel = { id = "pc_1", name = "Sentinel", isPC = true, zone = "near", conditions = {} }
    local ally = { id = "pc_2", name = "Ally", isPC = true, zone = "near", conditions = {} }
    local enemy = { id = "npc_1", name = "Enemy", isPC = false, zone = "far", conditions = {} }
    controller.pcs = { sentinel, ally }
    controller.npcs = { enemy }
    controller.allCombatants = { sentinel, ally, enemy }

    local allyTargeted = controller:doesVigilanceTrigger(sentinel, {
        trigger = { template = "hostile_targets_ally" },
    }, {
        actor = enemy,
        target = ally,
        type = action_resolver.ACTION_TYPES.MELEE,
    })
    assertTrue(allyTargeted, "hostile_targets_ally should trigger when an enemy targets an ally")

    local enemyTargeted = controller:doesVigilanceTrigger(sentinel, {
        trigger = { template = "hostile_targets_ally" },
    }, {
        actor = ally,
        target = enemy,
        type = action_resolver.ACTION_TYPES.MELEE,
    })
    assertTrue(not enemyTargeted, "hostile_targets_ally should ignore ally actions against enemies")

    local selfTargeted = controller:doesVigilanceTrigger(sentinel, {
        trigger = { template = "hostile_targets_ally" },
    }, {
        actor = enemy,
        target = sentinel,
        type = action_resolver.ACTION_TYPES.MELEE,
    })
    assertTrue(not selfTargeted, "hostile_targets_ally should not duplicate the target-self trigger")

    local enemyMoves = controller:doesVigilanceTrigger(sentinel, {
        trigger = "enemy_moves",
    }, {
        actor = enemy,
        type = action_resolver.ACTION_TYPES.DASH,
    })
    assertTrue(enemyMoves, "enemy_moves template should trigger from hostile Move/Dash/Avoid actions")

    local allyMoves = controller:doesVigilanceTrigger(sentinel, {
        trigger = "enemy_moves",
    }, {
        actor = ally,
        type = action_resolver.ACTION_TYPES.DASH,
    })
    assertTrue(not allyMoves, "enemy_moves template should ignore ally movement")

    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local vigilanceCard = { name = "Six of Swords", value = 6, suit = constants.SUITS.SWORDS }
    local trivialVigilance = resolver:resolve({
        actor = sentinel,
        card = vigilanceCard,
        type = action_resolver.ACTION_TYPES.VIGILANCE,
        followUpAction = action_resolver.ACTION_TYPES.TRIVIAL_ACTION,
        trigger = { template = "ally_acts" },
    })
    assertTrue(trivialVigilance.success,
        "Vigilance should allow the rulebook Trivial Action follow-up example")
    assertEqual(sentinel.pendingVigilance.followUpAction, action_resolver.ACTION_TYPES.TRIVIAL_ACTION,
        "Vigilance should store Trivial Action as the pending follow-up")
    assertEqual(trivialVigilance.facedownAction.type, "vigilance",
        "Vigilance should expose facedown preparation metadata")
    assertEqual(trivialVigilance.facedownAction.followUpAction, action_resolver.ACTION_TYPES.TRIVIAL_ACTION,
        "Vigilance metadata should preserve the follow-up action")
    do
        local popup = getActionSequencerPopup({
            actor = sentinel,
            card = vigilanceCard,
            type = action_resolver.ACTION_TYPES.VIGILANCE,
            followUpAction = action_resolver.ACTION_TYPES.TRIVIAL_ACTION,
        }, trivialVigilance, function(data)
            return data.title == "Vigilance"
        end)
        assertTrue(popup ~= nil, "prepared Vigilance should queue an action-sequencer popup")
        assertEqual(popup.followUpAction, action_resolver.ACTION_TYPES.TRIVIAL_ACTION,
            "Vigilance popup should preserve the follow-up action")
        assertEqual(popup.value, 6, "Vigilance popup should preserve the facedown value")
        assertEqual(popup.trigger.template, "ally_acts", "Vigilance popup should preserve the trigger template")
    end

    local reloadVigilance = resolver:resolve({
        actor = ally,
        card = { name = "Seven of Swords", value = 7, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.VIGILANCE,
        followUpAction = action_resolver.ACTION_TYPES.RELOAD,
    })
    assertTrue(not reloadVigilance.success,
        "Vigilance should still reject non-Trivial misc follow-up actions")

    local trivialReactions = controller:collectTriggeredVigilanceReactions({
        actor = ally,
        type = action_resolver.ACTION_TYPES.MOVE,
    })
    assertEqual(#trivialReactions, 1,
        "ally_acts trigger should queue a Trivial Action Vigilance reaction")
    assertEqual(trivialReactions[1].type, action_resolver.ACTION_TYPES.TRIVIAL_ACTION,
        "queued Vigilance reaction should keep the Trivial Action follow-up type")
    local trivialResult = resolver:resolve(trivialReactions[1])
    assertTrue(trivialResult.success,
        "triggered Trivial Action Vigilance reaction should resolve successfully")
end

local function checkRoughhouseCommandBoardEffectSelection()
    local previousLove = love
    love = {
        graphics = {
            getDimensions = function()
                return 1280, 720
            end,
        },
    }

    local pentaclesActions = action_registry.getActionsForSuit(action_registry.SUITS.PENTACLES, {
        challengeOnly = true,
        commandBoardOnly = true,
    })
    local sawRoughhouse = false
    local sawSplitShortcut = false
    for _, action in ipairs(pentaclesActions) do
        if action.id == "roughhouse" then
            sawRoughhouse = true
        elseif action.id == "trip" or action.id == "disarm" or action.id == "displace" or action.id == "grapple" then
            sawSplitShortcut = true
        end
    end
    assertTrue(sawRoughhouse, "Command Board should expose canonical Roughhouse")
    assertTrue(not sawSplitShortcut, "Command Board should hide split Roughhouse shortcuts")

    local emitted = nil
    local bus = events.createEventBus()
    bus:on("action_selected", function(data)
        emitted = data
    end)

    local board = command_board.createCommandBoard({ eventBus = bus })
    local actor = { id = "pc_roughhouse_ui", name = "Roughhouser", isPC = true, pentacles = 3, conditions = {} }

    board:show({ name = "Pentacles", suit = constants.SUITS.PENTACLES, value = 7 }, actor, true)
    local roughhouseButton = nil
    for _, button in ipairs(board.buttons) do
        if button.action and button.action.id == "roughhouse" then
            roughhouseButton = button
            break
        end
    end
    assertTrue(roughhouseButton ~= nil, "Roughhouse button should be present")
    board:mousepressed(roughhouseButton.x + 1, roughhouseButton.y + 1, 1)

    assertEqual(board.mode, "roughhouse_effect", "Roughhouse should open effect picker")
    assertTrue(board.roughhouseBaseAction and board.roughhouseBaseAction.id == "roughhouse", "effect picker should retain base Roughhouse action")

    local rootButton = nil
    for _, button in ipairs(board.buttons) do
        if button.action and button.action.roughhouseEffect == "root" then
            rootButton = button
            break
        end
    end
    assertTrue(rootButton ~= nil, "Roughhouse effect picker should include Root")
    board:mousepressed(rootButton.x + 1, rootButton.y + 1, 1)

    assertTrue(emitted ~= nil, "Roughhouse effect selection should emit action_selected")
    assertEqual(emitted.action.id, "roughhouse", "emitted action should remain canonical Roughhouse")
    assertEqual(emitted.roughhouseEffect, "root", "emitted action should include chosen Roughhouse effect")
    assertEqual(emitted.roughhouseEffectOption.name, "Root", "emitted action should include chosen effect option")

    emitted = nil
    board:show({ name = "Pentacles", suit = constants.SUITS.PENTACLES, value = 7 }, actor, true)
    roughhouseButton = nil
    for _, button in ipairs(board.buttons) do
        if button.action and button.action.id == "roughhouse" then
            roughhouseButton = button
            break
        end
    end
    assertTrue(roughhouseButton ~= nil, "Roughhouse button should be present for Displace")
    board:mousepressed(roughhouseButton.x + 1, roughhouseButton.y + 1, 1)

    local displaceButton = nil
    for _, button in ipairs(board.buttons) do
        if button.action and button.action.roughhouseEffect == "displace" then
            displaceButton = button
            break
        end
    end
    assertTrue(displaceButton ~= nil, "Roughhouse effect picker should include Displace")
    board:mousepressed(displaceButton.x + 1, displaceButton.y + 1, 1)

    assertTrue(emitted ~= nil, "Roughhouse Displace selection should emit action_selected")
    assertEqual(emitted.action.id, "roughhouse", "Displace emission should remain canonical Roughhouse")
    assertEqual(emitted.roughhouseEffect, "displace", "Displace emission should include chosen effect")

    local target = { id = "npc_roughhouse_displace_ui", name = "Displace Target", isPC = false, zone = "A", conditions = {} }
    actor.zone = "A"
    local submitted = nil
    local displaceCard = { name = "Seven of Pentacles", suit = constants.SUITS.PENTACLES, value = 7 }
    local fakeChallenge = {
        pcs = { actor },
        npcs = { target },
        allCombatants = { actor, target },
        zones = {
            { id = "A", name = "Near" },
            { id = "B", name = "Bridge" },
            { id = "C", name = "Far" },
        },
        getState = function()
            return "awaiting_action"
        end,
        submitAction = function(_, action)
            submitted = action
            return true
        end,
    }
    local fakeHand = {
        getHand = function()
            return { displaceCard }
        end,
        discardCard = function()
            return displaceCard, 1, nil
        end,
    }
    local inputController = challenge_input_controller.createChallengeInputController({
        gameState = {
            challengeController = fakeChallenge,
            playerHand = fakeHand,
            actionResolver = {
                getZoneDistance = function(_, _, fromZone, toZone)
                    if fromZone == toZone then
                        return 0, nil
                    end
                    local distances = {
                        A = { B = 1, C = 2 },
                        B = { A = 1, C = 1 },
                        C = { A = 2, B = 1 },
                    }
                    local distance = distances[fromZone] and distances[fromZone][toZone]
                    if distance then
                        return distance, nil
                    end
                    return nil, "not_connected"
                end,
            },
        },
        eventBus = events.createEventBus(),
        inputState = {
            selectedCard = displaceCard,
            selectedCardIndex = 1,
            selectedEntity = actor,
        },
    })
    inputController:handleActionSelected(emitted)
    assertTrue(inputController:getState().awaitingTarget,
        "Roughhouse Displace should ask for a target before the destination zone")
    inputController:handleTargetSelection("1")
    assertTrue(submitted == nil,
        "Roughhouse Displace target selection should wait for destination zone selection")
    assertTrue(inputController:getState().awaitingRoughhouseDisplaceZone,
        "Roughhouse Displace should prompt for the target's destination zone")
    assertEqual(inputController:getState().selectedRoughhouseDisplaceTarget, target,
        "Roughhouse Displace should remember the selected target while picking a zone")
    assertEqual(#inputController:getState().availableZones, 1,
        "Roughhouse Displace should offer adjacent target-zone destinations")
    assertEqual(inputController:getState().availableZones[1].id, "B",
        "Roughhouse Displace should not offer non-adjacent destination zones")

    local overlay = require('ui.challenge_overlay').createChallengeOverlay({
        gameState = {
            challengeController = fakeChallenge,
            playerHand = fakeHand,
        },
        inputState = inputController:getState(),
    })
    assertEqual(overlay:getFooterPrompt("awaiting_action", actor),
        "Select displacement zone (1-1), ESC to cancel",
        "Roughhouse Displace should use a destination-specific HUD prompt")

    inputController:handleRoughhouseDisplaceZoneSelection("1")
    assertTrue(submitted ~= nil, "Roughhouse Displace should submit after zone selection")
    assertEqual(submitted.type, "roughhouse", "Roughhouse Displace should keep canonical action type")
    assertEqual(submitted.target, target, "Roughhouse Displace should keep selected target")
    assertEqual(submitted.roughhouseEffect, "displace", "Roughhouse Displace should keep selected effect")
    assertEqual(submitted.destinationZone, "B", "Roughhouse Displace should keep selected destination zone")

    love = previousLove
end

