    actor.inventory:addItem(chalk, inventory.LOCATIONS.PACK)
    actor.inventory:addItem(potion, inventory.LOCATIONS.PACK)
    actor.inventory:addItem(torch, inventory.LOCATIONS.BELT)

    local board = command_board.createCommandBoard({ eventBus = bus })
    board:show({ name = "Cups", suit = constants.SUITS.CUPS, value = 7 }, actor, true)
    local pullPackButton = nil
    for _, button in ipairs(board.buttons) do
        if button.action and button.action.id == "pull_item" then
            pullPackButton = button
            break
        end
    end
    assertTrue(pullPackButton ~= nil, "Pull Item from Pack button should be present")
    board:mousepressed(pullPackButton.x + 1, pullPackButton.y + 1, 1)

    assertEqual(board.mode, "pull_item", "Pull Item from Pack should open item picker")
    assertTrue(board.pullItemBaseAction and board.pullItemBaseAction.id == "pull_item",
        "Pull item picker should retain base pack action")
    local potionButton = nil
    for _, button in ipairs(board.buttons) do
        if button.action and button.action.pullItemId == potion.id then
            potionButton = button
            break
        end
    end
    assertTrue(potionButton ~= nil, "Pull item picker should include carried pack items")
    board:mousepressed(potionButton.x + 1, potionButton.y + 1, 1)

    assertTrue(emitted ~= nil, "Pull item selection should emit action_selected")
    assertEqual(emitted.action.id, "pull_item", "emitted action should remain Pull Item from Pack")
    assertEqual(emitted.pullItemId, potion.id, "emitted Pull Item should include selected item id")
    assertEqual(emitted.pullItemOption.pullSourceLocation, "pack",
        "emitted Pull Item option should report source location")

    local submitted = nil
    local handCards = { { name = "Seven of Cups", suit = constants.SUITS.CUPS, value = 7 } }
    local fakeChallenge = {
        getState = function()
            return "awaiting_action"
        end,
        submitAction = function(_, action)
            submitted = action
            return true
        end,
    }
    local fakeHand = {
        getHand = function()
            return handCards
        end,
    }
