        gameState = {
            challengeController = fakeChallenge,
            playerHand = fakeHand,
        },
        eventBus = events.createEventBus(),
        inputState = {
            selectedCard = handCards[1],
            selectedCardIndex = 1,
            selectedEntity = actor,
        },
    })
    inputController:handleActionSelected(emitted)
    assertTrue(submitted ~= nil, "Pull Item selection should submit without target selection")
    assertEqual(submitted.type, "pull_item", "submitted Pull Item should keep action type")
    assertEqual(submitted.itemId, potion.id, "submitted Pull Item should keep selected item id")

    emitted = nil
    board:show({ name = "Major", suit = constants.SUITS.MAJOR, value = 9, is_major = true }, actor, true)
    local pullBeltButton = nil
    for _, button in ipairs(board.buttons) do
        if button.action and button.action.id == "pull_item_belt" then
            pullBeltButton = button
            break
        end
    end
    assertTrue(pullBeltButton ~= nil, "Pull Item from Belt button should be present")
    board:mousepressed(pullBeltButton.x + 1, pullBeltButton.y + 1, 1)
    assertEqual(board.mode, "pull_item", "Pull Item from Belt should open item picker")
    local torchButton = nil
    for _, button in ipairs(board.buttons) do
        if button.action and button.action.pullItemId == torch.id then
            torchButton = button
            break
        end
    end
    assertTrue(torchButton ~= nil, "Pull item picker should include carried belt items")
    board:mousepressed(torchButton.x + 1, torchButton.y + 1, 1)
    assertEqual(emitted.pullItemId, torch.id, "emitted belt Pull Item should include selected item id")
    assertEqual(emitted.pullItemOption.pullSourceLocation, "belt",
        "emitted belt Pull Item option should report source location")

    emitted = nil
    local fullHands = base_entity.createEntity({
        id = "pc_pull_item_swap_ui",
        name = "Full Hands Puller",
        isPC = true,
        cups = 2,
        conditions = {},
    })
    fullHands.inventory = inventory.createInventory()
    local heldSword = inventory.createItem({ name = "Held Sword", size = 1, isWeapon = true, isMelee = true })
    local heldShield = inventory.createItem({ name = "Held Shield", size = 1 })
    local packedLantern = inventory.createItem({ name = "Packed Lantern", size = 1 })
    fullHands.inventory:addItem(heldSword, inventory.LOCATIONS.HANDS)
    fullHands.inventory:addItem(heldShield, inventory.LOCATIONS.HANDS)
    fullHands.inventory:addItem(packedLantern, inventory.LOCATIONS.PACK)

    board:show({ name = "Cups", suit = constants.SUITS.CUPS, value = 5 }, fullHands, true)
    pullPackButton = nil
    for _, button in ipairs(board.buttons) do
        if button.action and button.action.id == "pull_item" then
            pullPackButton = button
            break
        end
    end
    board:mousepressed(pullPackButton.x + 1, pullPackButton.y + 1, 1)
    local lanternButton = nil
    for _, button in ipairs(board.buttons) do
        if button.action and button.action.pullItemId == packedLantern.id then
            lanternButton = button
            break
        end
    end
    assertTrue(lanternButton ~= nil, "Pull item picker should include packed item when hands are full")
    board:mousepressed(lanternButton.x + 1, lanternButton.y + 1, 1)
    assertEqual(board.mode, "pull_swap", "full hands should open held-item swap picker")
    local swordSwapButton = nil
    for _, button in ipairs(board.buttons) do
        if button.action and button.action.pullSwapItemId == heldSword.id then
            swordSwapButton = button
            break
        end
    end
    assertTrue(swordSwapButton ~= nil, "Pull swap picker should include held items")
    board:mousepressed(swordSwapButton.x + 1, swordSwapButton.y + 1, 1)
    assertEqual(emitted.pullItemId, packedLantern.id, "emitted Pull Item should keep selected source item")
    assertEqual(emitted.pullSwapItemId, heldSword.id, "emitted Pull Item should include selected held swap")

    submitted = nil
