    local swapHand = {
        getHand = function()
            return { swapCard }
        end,
    }
    local swapController = challenge_input_controller.createChallengeInputController({
        gameState = {
            challengeController = fakeChallenge,
            playerHand = swapHand,
        },
        eventBus = events.createEventBus(),
        inputState = {
            selectedCard = swapCard,
            selectedCardIndex = 1,
            selectedEntity = fullHands,
        },
    })
    swapController:handleActionSelected(emitted)
    assertEqual(submitted.itemId, packedLantern.id, "submitted Pull Item should preserve source item")
    assertEqual(submitted.swapWithItemId, heldSword.id, "submitted Pull Item should preserve selected held swap")

    love = previousLove
end

