    assertTrue(emitted ~= nil, "Up My Sleeve selection should emit action_selected")
    assertEqual(emitted.action.id, "up_my_sleeve", "emitted action should remain Up My Sleeve")
    assertEqual(emitted.action.upMySleeveItemSpec, "length_of_wire",
        "emitted Up My Sleeve action should include selected item")
    assertEqual(emitted.action.itemTemplateId, "length_of_wire",
        "emitted Up My Sleeve action should include selected template id")

