        },
        eventBus = events.createEventBus(),
        inputState = {
            selectedCard = handCards[1],
            selectedCardIndex = 1,
            selectedEntity = actor,
        },
    })
    inputController:handleActionSelected(emitted)
    assertTrue(submitted ~= nil, "Up My Sleeve selection should submit without target selection")
    assertEqual(submitted.type, "up_my_sleeve", "submitted Up My Sleeve should keep action type")
    assertEqual(submitted.upMySleeveItem, "length_of_wire",
        "submitted Up My Sleeve should keep selected item spec")
    assertEqual(submitted.itemSpec, "length_of_wire",
        "submitted Up My Sleeve should pass itemSpec to the resolver")

    actor.resolve = 0
    board:show({ name = "Seven of Cups", suit = constants.SUITS.CUPS, value = 7 }, actor, true)
    local noResolveButton = nil
    for _, button in ipairs(board.buttons) do
        if button.action and button.action.id == "up_my_sleeve" then
            noResolveButton = button
            break
        end
    end
    assertTrue(noResolveButton ~= nil, "Up My Sleeve button should remain visible when Resolve is missing")
    assertTrue(not noResolveButton.enabled, "Up My Sleeve should be disabled without Resolve")
    assertEqual(noResolveButton.disabledReason, "Requires 1 Resolve",
        "Up My Sleeve disabled reason should explain missing Resolve")

    love = previousLove
end

