    assertEqual(submitted.type, "dwimmercraft", "submitted Dwimmercraft should keep action type")
    assertEqual(submitted.dwimmercraftEffect, "second_sight",
        "submitted Dwimmercraft should keep selected effect")

    emitted = nil
    submitted = nil
    local coin = { id = "silver_key", name = "Silver Key", zone = "main", size = 1, weightPounds = 1 }
    board:show(card, actor, true)
    for _, button in ipairs(board.buttons) do
        if button.action and button.action.id == "dwimmercraft" then
            dwimmerButton = button
            break
        end
    end
    board:mousepressed(dwimmerButton.x + 1, dwimmerButton.y + 1, 1)
    for _, button in ipairs(board.buttons) do
        if button.action and button.action.dwimmercraftEffect == "levitate" then
            levitateButton = button
            break
        end
    end
    board:mousepressed(levitateButton.x + 1, levitateButton.y + 1, 1)
    assertTrue(emitted ~= nil, "Dwimmercraft levitation should emit action_selected")
    local levitateCard = { name = "Six of Swords", suit = constants.SUITS.SWORDS, value = 6 }
