    assertTrue(submitted ~= nil, "Dwimmercraft levitation should submit after object selection")
    assertEqual(submitted.dwimmercraftEffect, "levitate", "levitation submission should keep selected effect")
    assertEqual(submitted.target, coin, "levitation submission should use the selected object target")

    actor.resolve = 0
