    secondSightButton = nil
    for _, button in ipairs(board.buttons) do
        if button.action and button.action.dwimmercraftEffect == "second_sight" then
            secondSightButton = button
            break
        end
    end
    assertTrue(secondSightButton ~= nil, "Dwimmercraft picker should keep second sight visible without Resolve")
    assertTrue(not secondSightButton.enabled, "Dwimmercraft second sight should be disabled without Resolve")
    assertEqual(secondSightButton.disabledReason, "Requires 1 Resolve",
        "Dwimmercraft second sight disabled reason should explain missing Resolve")

