    assertTrue(emitted ~= nil, "Counter-spell selection should emit action_selected")
    assertEqual(emitted.action.id, "counter_spell", "emitted action should remain Counter-spell")
    assertEqual(emitted.action.counterSpellMode, "ongoing",
        "emitted Counter-spell should mark ongoing-spell negation")
    assertEqual(emitted.action.activeSpell, activeSpell, "emitted Counter-spell should carry selected spell")
    assertEqual(emitted.action.spellCaster, spellCaster, "emitted Counter-spell should carry spell caster")

    local submitted = nil
    local handCards = { card }
