        getHand = function()
            return handCards
        end,
    }
    local inputController = challenge_input_controller.createChallengeInputController({
        gameState = {
            challengeController = submitChallenge,
            playerHand = fakeHand,
        },
        eventBus = events.createEventBus(),
        inputState = {
            selectedCard = handCards[1],
            selectedCardIndex = 1,
            selectedEntity = counterer,
        },
    })
    inputController:handleActionSelected(emitted)
    assertTrue(submitted ~= nil, "Counter-spell should submit without target selection")
    assertEqual(submitted.type, "counter_spell", "submitted Counter-spell should keep action type")
    assertEqual(submitted.mode, "ongoing", "submitted Counter-spell should keep ongoing mode")
    assertEqual(submitted.counterSpellMode, "ongoing",
        "submitted Counter-spell should carry explicit counter mode")
    assertEqual(submitted.activeSpell, activeSpell, "submitted Counter-spell should carry selected spell")
    assertEqual(submitted.spellCaster, spellCaster, "submitted Counter-spell should carry selected caster")

    counterer.resolve = 0
    board:show(card, counterer, true)
    local noResolveButton = nil
    for _, button in ipairs(board.buttons) do
        if button.action and button.action.id == "counter_spell" then
            noResolveButton = button
            break
        end
    end
    assertTrue(noResolveButton ~= nil, "Counter-spell should remain visible without Resolve")
    assertTrue(not noResolveButton.enabled, "Counter-spell should be disabled without Resolve")
    assertEqual(noResolveButton.disabledReason, "Requires 1 Resolve",
        "Counter-spell disabled reason should explain missing Resolve")

    counterer.resolve = 1
    spellCaster.activeSpells = {}
    board:show(card, counterer, true)
    local noSpellButton = nil
    for _, button in ipairs(board.buttons) do
        if button.action and button.action.id == "counter_spell" then
            noSpellButton = button
            break
        end
    end
    assertTrue(noSpellButton ~= nil, "Counter-spell should remain visible without ongoing spells")
    assertTrue(not noSpellButton.enabled, "Counter-spell should be disabled without ongoing spells")
    assertEqual(noSpellButton.disabledReason, "No ongoing spells",
        "Counter-spell disabled reason should explain missing ongoing spell targets")

    love = previousLove
end

