    local count = 0
    for id, spell in pairs(spell_registry.spells) do
        count = count + 1
        local want = expected[id]
        assertTrue(want ~= nil, "spell registry has non-Appendix A spell: " .. tostring(id))
        assertEqual(spell.id, id, "spell id should match registry key for " .. id)
        assertEqual(spell.name, want.name, "Appendix A spell name mismatch for " .. id)
        assertEqual(spell.branch, want.branch, "Appendix A branch mismatch for " .. id)
        assertEqual(spell.talent, want.talent, "Appendix A talent mismatch for " .. id)
        assertTrue(type(spell.componentId) == "string" and spell.componentId ~= "",
            "Appendix A spell should declare a component: " .. id)
        assertTrue(item_templates.hasTemplate(spell.componentId),
            "Appendix A component template missing for " .. id .. ": " .. tostring(spell.componentId))
    end

    assertEqual(count, 40, "Appendix A spell registry should cover exactly 40 spells")
    for id, _ in pairs(expected) do
        assertTrue(spell_registry.spells[id] ~= nil, "Appendix A spell missing from registry: " .. id)
    end
end

function checkAppendixBAlchemyCatalogCoverage()
    local expected = {
        brain_spider = {
            potion = "brain_spider_potion",
            bomb = "brain_spider_bomb",
            oil = "brain_spider_oil",
        },
        devil = {
            potion = "devil_potion",
            bomb = "devil_bomb",
            oil = "devil_oil",
        },
        cockatrice = {
            bomb = "cockatrice_bomb",
            oil = "cockatrice_oil",
        },
        face_rat = {
            potion = "face_rat_potion",
            bomb = "face_rat_bomb",
        },
        fungoid = {
            potion = "fungoid_potion",
            bomb = "fungoid_bomb",
            oil = "fungoid_oil",
        },
        harpy = {
            potion = "harpy_potion",
            bomb = "harpy_bomb",
        },
        imp = {
            potion = "imp_potion",
            bomb = "imp_bomb",
            oil = "imp_oil",
        },
        griffin = {
            potion = "griffin_potion",
            oil = "griffin_oil",
        },
        jinn = {
            potion = "jinn_potion",
            bomb = "jinn_bomb",
            oil = "jinn_oil",
        },
        mimic = {
            potion = "mimic_potion",
            oil = "mimic_oil",
        },
        kelpie = {
            potion = "kelpie_potion",
            oil = "kelpie_oil",
        },
        nymph = {
            potion = "nymph_potion",
            bomb = "nymph_bomb",
        },
        ogre = {
            potion = "ogre_potion",
            bomb = "ogre_bomb",
            oil = "ogre_oil",
        },
        questing_beast = {
            potion = "questing_beast_potion",
            oil = "questing_beast_oil",
        },
        slime = {
            potion = "slime_potion",
            bomb = "slime_bomb",
            oil = "slime_oil",
        },
        titan = {
            potion = "titan_potion",
            oil = "titan_oil",
        },
        ungoat = {
            potion = "ungoat_potion",
            bomb = "ungoat_bomb",
            oil = "ungoat_oil",
        },
        vampire = {
            potion = "vampire_potion",
            bomb = "vampire_bomb",
        },
        winter_wolf = {
            potion = "winter_wolf_potion",
            oil = "winter_wolf_oil",
        },
    }
    local forms = { "potion", "bomb", "oil" }
    local count = 0

    for source, outputs in pairs(expected) do
        count = count + 1
        local reagentId = source .. "_reagent"
        local reagent = item_templates.getTemplate(reagentId)
        assertTrue(reagent ~= nil, "Appendix B reagent template missing for " .. source)
        local props = reagent.properties or {}
        assertTrue(props.reagent and props.alchemicalReagent and props.hermeticBottle,
            "Appendix B reagent should be bottled alchemical reagent: " .. source)
        assertEqual(props.source, source, "Appendix B reagent source mismatch for " .. source)
        assertTrue(type(props.brewOutputs) == "table", "Appendix B reagent should declare brew outputs: " .. source)

        for _, form in ipairs(forms) do
            local expectedTemplate = outputs[form]
            local actualTemplate = props.brewOutputs[form]
            if expectedTemplate then
                assertEqual(actualTemplate, expectedTemplate,
                    "Appendix B " .. source .. " " .. form .. " output mismatch")
                local output = item_templates.getTemplate(expectedTemplate)
                assertTrue(output ~= nil, "Appendix B output template missing: " .. expectedTemplate)
                local outputProps = output.properties or {}
                assertTrue(outputProps.alchemical and outputProps.consumable,
                    "Appendix B output should be consumable alchemy: " .. expectedTemplate)
                assertTrue(outputProps[form] == true,
                    "Appendix B output should be marked as " .. form .. ": " .. expectedTemplate)
                assertEqual(outputProps.source, source,
                    "Appendix B output source mismatch for " .. expectedTemplate)
                assertTrue(type(outputProps.useEffect) == "table",
                    "Appendix B output should carry a usable effect: " .. expectedTemplate)
            else
                assertTrue(actualTemplate == nil,
                    "Appendix B should not invent a " .. form .. " output for " .. source)
            end
        end
    end

    assertEqual(count, 19, "Appendix B sampled alchemy catalog should cover 19 sources")
end

function checkAppendixBPotionLivingProcesses()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local livingWithMetadata = base_entity.createEntity({
        id = "pc_potion_living_metadata",
        name = "Living Potion Metadata",
        isPC = true,
    })
    livingWithMetadata.properties = {
        ritualScar = true,
    }
    livingWithMetadata.inventory = inventory.createInventory()
    local livingPotion = inventory.createItemFromTemplate("titan_potion")
    livingWithMetadata.inventory:addItem(livingPotion, inventory.LOCATIONS.HANDS)
    local livingUse = resolver:resolve({
        actor = livingWithMetadata,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = livingPotion.id,
    })
    assertTrue(livingUse.success,
        "Appendix B potions should still affect living creatures that carry metadata")
    assertTrue(livingWithMetadata.conditions.titan_growth and livingWithMetadata.sizeMultiplier == 2,
        "living creature metadata should not make potion targets count as objects")
    assertTrue(not hasValue(livingUse.effects, "potion_no_effect"),
        "living creature metadata should not trigger the potion living-process block")

    local flaggedUndead = base_entity.createEntity({
        id = "npc_potion_is_undead",
        name = "Flagged Undead Potion Target",
        isPC = false,
        health = 2,
        defense = 0,
    })
    flaggedUndead.isUndead = true
    flaggedUndead.inventory = inventory.createInventory()
    local undeadPotion = inventory.createItemFromTemplate("slime_potion")
    flaggedUndead.inventory:addItem(undeadPotion, inventory.LOCATIONS.HANDS)
    local undeadUse = resolver:resolve({
        actor = flaggedUndead,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = undeadPotion.id,
    })
    assertTrue(undeadUse.success, "nonliving potion attempts should still spend the potion")
    assertTrue(hasValue(undeadUse.effects, "potion_no_effect") and
        hasValue(undeadUse.effects, "potion_living_processes_required"),
        "undead potion no-effect path should report the living-process rule")
    assertEqual(undeadUse.itemEffect.reason, "no_living_processes",
        "undead potion no-effect path should preserve its rulebook reason")
    assertTrue(not flaggedUndead.conditions.shapeless_body,
        "slime potion should not alter an undead target without living processes")
    assertTrue(not flaggedUndead.inventory:findItem(undeadPotion.id),
        "ineffective undead potion should still be consumed")

    local construct = base_entity.createEntity({
        id = "npc_potion_construct",
        name = "Construct Potion Target",
        isPC = false,
        health = 2,
        defense = 0,
    })
    construct.construct = true
    construct.properties = {
        construct = true,
    }
    construct.inventory = inventory.createInventory()
    local constructPotion = inventory.createItemFromTemplate("titan_potion")
    construct.inventory:addItem(constructPotion, inventory.LOCATIONS.HANDS)
    local constructUse = resolver:resolve({
        actor = construct,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = constructPotion.id,
    })
    assertTrue(constructUse.success, "construct potion attempts should still resolve")
    assertTrue(hasValue(constructUse.effects, "potion_no_effect"),
        "constructs should be covered by the potion living-process rule")
    assertTrue(not construct.conditions.titan_growth,
        "titan potion should not Grow construct targets")

    local automaton = base_entity.createEntity({
        id = "npc_potion_automaton",
        name = "Automaton Potion Target",
        isPC = false,
        health = 2,
        defense = 0,
    })
    automaton.tags = { "automaton" }
    automaton.inventory = inventory.createInventory()
    local automatonPotion = inventory.createItemFromTemplate("slime_potion")
    automaton.inventory:addItem(automatonPotion, inventory.LOCATIONS.HANDS)
    local automatonUse = resolver:resolve({
        actor = automaton,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = automatonPotion.id,
    })
    assertTrue(automatonUse.success, "automaton potion attempts should still resolve")
    assertTrue(hasValue(automatonUse.effects, "potion_no_effect"),
        "automaton tags should be covered by the potion living-process rule")
    assertTrue(not automaton.conditions.shapeless_body,
        "slime potion should not alter automaton targets")
end

local function checkSpeakIncantationRegistry()
    local bus = events.createEventBus()
    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
    })

    local function makeWastesCaster(id, resolve)
        local caster = base_entity.createEntity({
            id = id,
            name = id,
            isPC = true,
            wands = 3,
            talents = {
                magic_of_the_wastes = { mastered = true },
            },
        })
        caster.resolve = resolve or 3
        caster.inventory = inventory.createInventory()
        caster.inventory:addItem(inventory.createItemFromTemplate("component_withering"), inventory.LOCATIONS.HANDS)
        return caster
    end

    local sorcerer = base_entity.createEntity({
        id = "pc_sorcerer",
        name = "Sorcerer",
        isPC = true,
        wands = 3,
        talents = {
            magic_of_the_wastes = { mastered = true },
        },
    })
    sorcerer.resolve = 2
    sorcerer.inventory = inventory.createInventory()
    local witheringComponent = inventory.createItemFromTemplate("component_withering")
    sorcerer.inventory:addItem(witheringComponent, inventory.LOCATIONS.HANDS)

    local target = base_entity.createEntity({
        id = "npc_living",
        name = "Living Target",
        isPC = false,
        health = 2,
        defense = 0,
    })

    local withering = resolver:resolve({
        actor = sorcerer,
        card = { name = "Wands", value = 7, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "withering",
        target = target,
        targetInitiative = 6,
    })
    assertTrue(withering.success, "Withering should cast with training, Resolve, and held component")
    assertEqual(sorcerer.resolve, 1, "Speak Incantation should spend 1 Resolve")
    assertEqual(target.npcHealth, 1, "Withering should deal a wound to a living target")
    assertTrue(target.conditions.witheringAging and target.witheringAging.untilWoundHealed,
        "Withering should mark living targets with aging signs until the Wound is healed")
    assertTrue(sorcerer.inventory:findItem(witheringComponent.id), "spell components should not be consumed")

    local agingCaster = makeWastesCaster("pc_withering_aging", 2)
    local agingTarget = base_entity.createEntity({
        id = "pc_withering_aging_target",
        name = "Aging Target",
        isPC = true,
    })
    local aging = resolver:resolve({
        actor = agingCaster,
        card = { name = "Wands", value = 7, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "withering",
        target = agingTarget,
    })
    assertTrue(aging.success, "Withering should be able to affect a living PC")
    assertTrue(agingTarget.conditions.witheringAging, "living PC should carry Withering aging")
    local healed = agingTarget:healWound()
    assertEqual(healed, "staggered_healed", "healing the Withering Wound should heal the wound track")
    assertTrue(not agingTarget.conditions.witheringAging and agingTarget.witheringAging.healed,
        "Withering aging should clear when that Wound is healed")

    local undeadCaster = makeWastesCaster("pc_withering_undead", 4)
    local zombie = entity_factory.createEntity("zombie", { name = "Withered Zombie" })
    local zombieWithering = resolver:resolve({
        actor = undeadCaster,
        card = { name = "Wands", value = 7, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "withering",
        target = zombie,
        targetInitiative = 1,
    })
    assertTrue(zombieWithering.success, "Withering should affect undead")
    assertEqual(zombie.undeadType, "skeleton", "Withering should transform zombies into skeletons")
    assertTrue(hasValue(zombieWithering.effects, "zombie_transformed_skeleton"),
        "zombie transformation should be reported")

    local skeleton = entity_factory.createEntity("skeleton_brute", { name = "Withered Skeleton" })
    local skeletonWithering = resolver:resolve({
        actor = undeadCaster,
        card = { name = "Wands", value = 7, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "withering",
        target = skeleton,
        targetInitiative = 1,
    })
    assertTrue(skeletonWithering.success, "Withering should affect skeletons")
    assertEqual(skeleton.undeadType, "wraith", "Withering should transform skeletons into wraiths")
    assertTrue(skeleton.wraith and skeleton.spirit and skeleton.incorporeal,
        "Withering-created wraiths should be marked as undead spirits")

    local objectCaster = makeWastesCaster("pc_withering_object", 6)
    local chain = inventory.createItem({
        name = "Iron Chain",
        durability = 2,
        properties = { material = "iron" },
    })
    local chainWithering = resolver:resolve({
        actor = objectCaster,
        card = { name = "Wands", value = 7, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "withering",
        target = chain,
    })
    assertTrue(chainWithering.success, "Withering should decay objects")
    assertEqual(chain.notches, 1, "Withering should Notch objects with 1 Resolve")
    assertTrue(chain.rusted, "Withering should mark iron objects as rusted")
    assertTrue(chain.witheringObjectDecay and chain.witheringObjectDecay.rusted,
        "Withering should persist rusted object-decay metadata")

    chain = inventory.createItem({
        name = "Old Ration",
        type = "ration",
        durability = 1,
        properties = { food = true },
    })
    chainWithering = resolver:resolve({
        actor = objectCaster,
        card = { name = "Wands", value = 7, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "withering",
        target = chain,
    })
    assertTrue(chainWithering.success, "Withering should decay food objects")
    assertTrue(chain.rotted and chain.properties.rotted, "Withering should make food rotten")
    assertTrue(chainWithering.witheringObjectDecay and chainWithering.witheringObjectDecay.rotted,
        "Withering should report rotten food decay metadata")

    local door = inventory.createItem({
        name = "Wooden Door",
        durability = 3,
        properties = { material = "wood" },
    })
    local doorWithering = resolver:resolve({
        actor = objectCaster,
        card = { name = "Wands", value = 7, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "withering",
        target = door,
        resolveSpent = 2,
    })
    assertTrue(doorWithering.success, "Withering should accept 2 Resolve for object destruction")
    assertTrue(door.destroyed and door.moldy, "Withering should Destroy objects when 2 Resolve is spent")
    assertTrue(door.witheringObjectDecay and door.witheringObjectDecay.moldy,
        "Withering should persist moldy wood decay metadata")
    assertTrue(hasValue(doorWithering.effects, "object_destroyed"),
        "Withering object destruction should be reported")

    local stone = inventory.createItem({
        name = "Stone Block",
        durability = 3,
        properties = { material = "stone" },
    })
    local stoneWithering = resolver:resolve({
        actor = objectCaster,
        card = { name = "Wands", value = 7, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "withering",
        target = stone,
        resolveSpent = 2,
    })
    assertTrue(stoneWithering.success, "Withering should resolve against stone")
    assertTrue(not stone.destroyed and stone.notches == 0,
        "stone should be unaffected by Withering object decay")
    assertTrue(stone.witheringObjectDecay and stone.witheringObjectDecay.unaffected,
        "Withering should persist stone-unaffected metadata")
    assertTrue(hasValue(stoneWithering.effects, "withering_stone_unaffected"),
        "stone immunity should be reported")

    local missingComponentCaster = base_entity.createEntity({
        id = "pc_missing_component",
        name = "No Component",
        isPC = true,
        wands = 3,
        talents = {
            magic_of_the_wastes = { mastered = true },
        },
    })
    missingComponentCaster.resolve = 2
    missingComponentCaster.inventory = inventory.createInventory()
    local missingComponent = resolver:resolve({
        actor = missingComponentCaster,
        card = { name = "Wands", value = 7, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "withering",
        target = target,
        targetInitiative = 6,
    })
    assertTrue(not missingComponent.success, "Speak Incantation should require held component")
    assertEqual(missingComponentCaster.resolve, 2, "failed component gate should not spend Resolve")

    local ironCaster = base_entity.createEntity({
        id = "pc_iron",
        name = "Iron-Bound",
        isPC = true,
        wands = 3,
        talents = {
            magic_of_the_wastes = { mastered = true },
        },
    })
    ironCaster.resolve = 2
    ironCaster.inventory = inventory.createInventory()
    ironCaster.inventory:addItem(inventory.createItemFromTemplate("component_withering"), inventory.LOCATIONS.HANDS)
    ironCaster.inventory:addItem(inventory.createItem({
        name = "Iron Pan",
        size = 1,
        properties = { material = "iron" },
    }), inventory.LOCATIONS.PACK)
    local ironBlocked = resolver:resolve({
        actor = ironCaster,
        card = { name = "Wands", value = 7, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "withering",
        target = target,
        targetInitiative = 6,
    })
    assertTrue(not ironBlocked.success, "significant iron should block spellcasting")
    assertEqual(ironCaster.resolve, 2, "iron block should not spend Resolve")

    local silencedCaster = base_entity.createEntity({
        id = "pc_silenced_spell",
        name = "Silenced Mage",
        isPC = true,
        wands = 3,
        talents = {
            magic_of_the_wastes = { mastered = true },
        },
    })
    silencedCaster.resolve = 2
    silencedCaster.conditions.silenced = true
    silencedCaster.inventory = inventory.createInventory()
    silencedCaster.inventory:addItem(inventory.createItemFromTemplate("component_withering"), inventory.LOCATIONS.HANDS)
    local silencedCast = resolver:resolve({
        actor = silencedCaster,
        card = { name = "Wands", value = 7, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "withering",
        target = base_entity.createEntity({ id = "npc_silenced_spell_target", isPC = false, health = 2, defense = 0 }),
        targetInitiative = 6,
    })
    assertTrue(not silencedCast.success, "Silenced creatures should be unable to Speak Incantations")
    assertTrue(hasValue(silencedCast.effects, "spell_speech_blocked"),
        "silenced spellcasting should fail at the speech gate")
    assertEqual(silencedCaster.resolve, 2, "silenced spellcasting should not spend Resolve")

    local trainee = base_entity.createEntity({
        id = "pc_trainee",
        name = "Trainee",
        isPC = true,
        wands = 3,
        talents = {
            magic_of_the_wastes = { mastered = false },
        },
    })
    trainee.resolve = 2
    trainee.xp = 1
    trainee.inventory = inventory.createInventory()
    trainee.inventory:addItem(inventory.createItemFromTemplate("component_withering"), inventory.LOCATIONS.HANDS)
    local trainingCast = resolver:resolve({
        actor = trainee,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "withering",
        target = base_entity.createEntity({ id = "npc_training_target", isPC = false, health = 2, defense = 0 }),
        targetInitiative = 6,
    })
    assertTrue(trainingCast.success, "in-training Magic talent should still cast with XP")
    assertEqual(trainee.xp, 0, "in-training spellcasting should spend 1 XP")
    assertEqual(trainee.resolve, 1, "in-training spellcasting should also spend Resolve")

    local noTarget = resolver:resolve({
        actor = trainee,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "withering",
    })
    assertTrue(not noTarget.success, "targeted spell should reject missing target before spending")
    assertEqual(trainee.resolve, 1, "missing target should not spend Resolve")

    do
    local brainfeverCaster = base_entity.createEntity({
        id = "pc_brainfever",
        name = "Brainfever Mage",
        isPC = true,
        wands = 4,
        talents = {
            magic_of_the_wastes = { mastered = true },
        },
    })
    brainfeverCaster.resolve = 2
    brainfeverCaster.inventory = inventory.createInventory()
    brainfeverCaster.inventory:addItem(inventory.createItemFromTemplate("component_brainfever"),
