    local discardedStunCard = { name = "Discarded Doom", value = 5, is_major = true }
    stunnedTarget.challengeHand = { keptStunCard, discardedStunCard }
    local outsideTarget = base_entity.createEntity({
        id = "npc_thunderclap_outside",
