        spellId = "withering",
        target = ironTarget,
        targetInitiative = 6,
    })
    assertTrue(not ironTargetBlocked.success, "iron armor should block targeted spells against the wearer")
    assertEqual(ironTargetCaster.resolve, 2, "iron target block should not spend Resolve")

    local steelTargetCaster = base_entity.createEntity({
        id = "pc_steel_target_spellcaster",
        name = "Steel Target Spellcaster",
        isPC = true,
        wands = 3,
        talents = {
            magic_of_the_wastes = { mastered = true },
        },
    })
    steelTargetCaster.resolve = 2
    steelTargetCaster.inventory = inventory.createInventory()
    steelTargetCaster.inventory:addItem(inventory.createItemFromTemplate("component_withering"), inventory.LOCATIONS.HANDS)
    local steelTarget = base_entity.createEntity({
        id = "npc_steel_spell_target",
        name = "Steel Spell Target",
        isPC = false,
        health = 2,
        defense = 0,
    })
    steelTarget.inventory = inventory.createInventory()
    steelTarget.inventory:addItem(inventory.createItemFromTemplate("steel_armor"), inventory.LOCATIONS.BELT)
    local steelTargetHit = resolver:resolve({
