    local circle = resolver:resolve({
        actor = circleCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "circle_of_protection",
        circlePrepared = true,
        realms = { "wastes" },
    })
    assertTrue(circle.success, "Circle metadata cast should succeed")
    assertEqual(circle.circleProtection.preparationAction, "watch_sketch_rune_circle_with_ashes",
        "Circle state should preserve watch-long preparation")
    assertTrue(circle.circleProtection.protectsAgainstFarRealmNatives and
        circle.circleProtection.canTrapSpiritIfPreparedUnempowered,
        "Circle state should preserve realm-native protection and trap metadata")

    local featherCaster = base_entity.createEntity({
        id = "pc_feather_metadata",
        name = "Feather Metadata Mage",
        isPC = true,
        wands = 4,
        talents = {
            magic_of_the_welkin = { mastered = true },
        },
    })
    featherCaster.resolve = 2
    featherCaster.inventory = inventory.createInventory()
    featherCaster.inventory:addItem(inventory.createItemFromTemplate("component_feather"), inventory.LOCATIONS.HANDS)
    local featherTarget = base_entity.createEntity({
        id = "pc_feather_metadata_target",
        name = "Feather Metadata Target",
        isPC = true,
    })
    featherTarget.falling = true
    local feather = resolver:resolve({
        actor = featherCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "feather",
        target = featherTarget,
    })
    assertTrue(feather.success, "Feather metadata cast should succeed")
    assertEqual(featherTarget.feather.weightReducedTo, "feather",
        "Feather state should preserve effective weight")
    assertTrue(featherTarget.feather.floatsGentlyToGround and
        featherTarget.feather.quickCastFallingRequiresHeldComponent,
        "Feather state should preserve falling response metadata")

    local guardianCaster = base_entity.createEntity({
        id = "pc_guardian_metadata",
        name = "Guardian Metadata Mage",
        isPC = true,
        wands = 4,
        talents = {
            magic_of_the_welkin = { mastered = true },
        },
    })
    guardianCaster.resolve = 2
    guardianCaster.inventory = inventory.createInventory()
    guardianCaster.inventory:addItem(inventory.createItemFromTemplate("component_guardian_angel"),
        inventory.LOCATIONS.HANDS)
    local guardianTarget = base_entity.createEntity({
        id = "pc_guardian_metadata_target",
        name = "Guardian Metadata Target",
        isPC = true,
    })
    local guardian = resolver:resolve({
        actor = guardianCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "guardian_angel",
        target = guardianTarget,
    })
    assertTrue(guardian.success, "Guardian Angel metadata cast should succeed")
    assertTrue(guardianTarget.guardianAngel.bindsSpiritToTarget and
        guardianTarget.guardianAngel.speakIncantationCardBecomesDefense,
        "Guardian Angel state should preserve spirit-bound defense-card metadata")
    assertTrue(guardianTarget.guardianAngel.stacksWithSameDefenseType and
        guardianTarget.guardianAngel.noMultipleInstances,
        "Guardian Angel state should preserve stacking and duplicate limits")
end

function checkWelkinLifeTruthPactMetadata()
    local spellRegistry = require('data.spell_registry')
    local heavenfireSpell = spellRegistry.spells.heavenfire
    local lifeSpell = spellRegistry.spells.life
    local veritasSpell = spellRegistry.spells.veritas
    local sealPactSpell = spellRegistry.spells.seal_pact
    assertTrue(heavenfireSpell.effect.brightFlameLightNoHeat and
        heavenfireSpell.effect.objectExtinguishesOnTorchesGutter,
        "Heavenfire should record heatless light and torches-gutter behavior")
    assertTrue(lifeSpell.effect.clearsDeathsDoor and lifeSpell.effect.reducesAfflictionStage,
        "Life should record Death's Door and affliction effects")
    assertTrue(veritasSpell.effect.casterKnowsKnowinglySpokenLies,
        "Veritas should record knowingly spoken lie detection")
    assertTrue(sealPactSpell.effect.violatorDoomedForFutureGreatFailure and
        sealPactSpell.effect.violatedConsequencesIrremovable,
        "Seal Pact should record violation consequences")

    local bus = events.createEventBus()
    local veritasLieEvents = 0
    bus:on(events.EVENTS.VERITAS_LIE_DETECTED, function(data)
        veritasLieEvents = veritasLieEvents + 1
        assertTrue(data.speakerId == "pc_veritas_metadata_target",
            "Veritas lie events should identify the speaking target")
    end)
    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
    })

    local heavenfireCaster = base_entity.createEntity({
        id = "pc_heavenfire_metadata",
        name = "Heavenfire Metadata Mage",
        isPC = true,
        wands = 4,
        talents = {
            magic_of_the_welkin = { mastered = true },
        },
    })
    heavenfireCaster.resolve = 3
    heavenfireCaster.inventory = inventory.createInventory()
    heavenfireCaster.inventory:addItem(inventory.createItemFromTemplate("component_heavenfire"), inventory.LOCATIONS.HANDS)
    local holyObject = inventory.createItem({ id = "holy_cap_metadata", name = "Holy Cap", size = 1 })
    local heavenfire = resolver:resolve({
        actor = heavenfireCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "heavenfire",
        target = holyObject,
    })
    assertTrue(heavenfire.success, "Heavenfire metadata cast should succeed")
    assertTrue(holyObject.heavenfire.brightFlameLightNoHeat and
        holyObject.heavenfire.doesNotConsumeBurningObject,
        "Heavenfire object state should preserve heatless non-consuming flame")
    assertTrue(holyObject.heavenfire.actsLikeNormalFlame and
        holyObject.heavenfire.extinguishableByWaterOrSuffocation,
        "Heavenfire object state should preserve normal-flame extinguishing metadata")

    local lifeCaster = base_entity.createEntity({
        id = "pc_life_metadata",
        name = "Life Metadata Mage",
        isPC = true,
        wands = 4,
        talents = {
            magic_of_the_welkin = { mastered = true },
        },
    })
    lifeCaster.resolve = 3
    lifeCaster.inventory = inventory.createInventory()
    lifeCaster.inventory:addItem(inventory.createItemFromTemplate("component_life"), inventory.LOCATIONS.HANDS)
    local lifeTarget = base_entity.createEntity({
        id = "pc_life_metadata_target",
        name = "Life Metadata Target",
        isPC = true,
    })
    lifeTarget.conditions.deaths_door = true
    local life = resolver:resolve({
        actor = lifeCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "life",
        target = lifeTarget,
    })
    assertTrue(life.success, "Life metadata cast should succeed")
    assertTrue(life.life.clearsDeathsDoor and life.life.deathsDoorTargetBecomesStressed,
        "Life result should preserve Death's Door rider metadata")
    assertTrue(life.life.undeadTakesWound and life.life.plantGrowsQuickly,
        "Life result should preserve undead and plant rider metadata")

    local veritasCaster = base_entity.createEntity({
        id = "pc_veritas_metadata",
        name = "Veritas Metadata Mage",
        isPC = true,
        wands = 4,
        talents = {
            magic_of_the_welkin = { mastered = true },
        },
    })
    veritasCaster.resolve = 2
    veritasCaster.inventory = inventory.createInventory()
    veritasCaster.inventory:addItem(inventory.createItemFromTemplate("component_veritas"), inventory.LOCATIONS.HANDS)
    local veritasTarget = base_entity.createEntity({
        id = "pc_veritas_metadata_target",
        name = "Veritas Metadata Target",
        isPC = true,
    })
    local veritas = resolver:resolve({
        actor = veritasCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "veritas",
        target = veritasTarget,
    })
    assertTrue(veritas.success, "Veritas metadata cast should succeed")
    assertEqual(veritasTarget.veritas.componentAction, "administer_sacramental_wine",
        "Veritas state should preserve component use")
    assertTrue(veritasTarget.veritas.personOnly and veritasTarget.veritas.targetUnderstandsMagicalPolygraph,
        "Veritas state should preserve person-only and polygraph metadata")
    local veritasTruth = resolver:evaluateVeritasStatement(veritasTarget, {
        statement = "The reliquary was already open.",
    })
    assertTrue(veritasTruth.success and not veritasTruth.lieDetected,
        "Veritas should evaluate truthful statements without reporting a lie")
    local veritasLie = resolver:evaluateVeritasStatement(veritasTarget, {
        statement = "I never touched the reliquary.",
        knowinglyLies = true,
    })
    assertTrue(veritasLie.success and veritasLie.lieDetected,
        "Veritas should disclose knowingly spoken lies")
    assertEqual(veritasLieEvents, 1, "Veritas should emit one lie detection event")
    assertEqual(veritasCaster.lastVeritasDetectedLie.statement, "I never touched the reliquary.",
        "Veritas should record the detected lie on the caster")
    assertTrue(veritasTarget.lastVeritasLie.caster == veritasCaster,
        "Veritas should retain the caster-visible lie record on the target")
    resolver:endOngoingSpell(veritasCaster, veritasCaster.activeSpells[1], "released")
    assertTrue(veritasTarget.veritas == nil and not veritasTarget.conditions.veritas,
        "ending Veritas concentration should clear the active polygraph state")
    local inactiveVeritas = resolver:evaluateVeritasStatement(veritasTarget, {
        knowinglyLies = true,
    })
    assertTrue(not inactiveVeritas.success and hasValue(inactiveVeritas.effects, "veritas_inactive"),
        "Veritas should stop evaluating lies after concentration ends")

    local sealCaster = base_entity.createEntity({
        id = "pc_seal_metadata",
        name = "Seal Metadata Mage",
        isPC = true,
        wands = 4,
        talents = {
            magic_of_the_welkin = { mastered = true },
        },
    })
    sealCaster.resolve = 3
    sealCaster.inventory = inventory.createInventory()
    sealCaster.inventory:addItem(inventory.createItemFromTemplate("component_seal_pact"), inventory.LOCATIONS.HANDS)
    local partyA = base_entity.createEntity({ id = "pc_seal_metadata_a", name = "Seal Metadata A", isPC = true })
    local partyB = base_entity.createEntity({ id = "pc_seal_metadata_b", name = "Seal Metadata B", isPC = true })
    local seal = resolver:resolve({
        actor = sealCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "seal_pact",
        parties = { partyA, partyB },
        partyConsent = {
            [partyA.id] = true,
            [partyB.id] = true,
        },
        terms = "metadata pact",
    })
    assertTrue(seal.success, "Seal Pact metadata cast should succeed")
    assertEqual(seal.sealedPact.componentAction, "seal_contract_with_goblin_teeth_and_finger_joints",
        "Seal Pact state should preserve component use")
    assertTrue(seal.sealedPact.permanentUnlessDispelled and
        seal.sealedPact.violationAlertsOtherParties,
        "Seal Pact state should preserve permanence and awareness metadata")
    assertTrue(seal.sealedPact.violatorDoomedForFutureGreatFailure and
        seal.sealedPact.dispelTriggersAwarenessButNotDoom,
        "Seal Pact state should preserve doom and dispel metadata")
end

function checkSparseWastesWealdWeirdSpellMetadata()
    local spellRegistry = require('data.spell_registry')
    assertTrue(spellRegistry.spells.brainfever.effect.grantsAttackFavor and
        spellRegistry.spells.brainfever.effect.emotionlessNoEffect,
        "Brainfever registry should preserve rage and emotionless-target metadata")
    assertTrue(spellRegistry.spells.control_undead.effect.suicidalOrdersAllowed and
        spellRegistry.spells.control_undead.effect.wordsPerResolveUsesWands,
        "Control Undead registry should preserve Wands order and suicidal-order metadata")
    assertTrue(spellRegistry.spells.darklight.effect.lightOnlyForHolder and
        spellRegistry.spells.darklight.effect.ignoresTorchesGutter,
        "Darklight registry should preserve private-light and torches-gutter metadata")
    assertTrue(spellRegistry.spells.fear.effect.prioritizeHighInitiative and
        spellRegistry.spells.fear.effect.cloakedTargetAppearance == "terrifying_grotesquery",
        "Fear registry should preserve target-only grotesquery and flight metadata")
    assertTrue(spellRegistry.spells.control_animal.effect.animalsRefuseObviouslySuicidalOrders and
        spellRegistry.spells.control_animal.effect.committedResolveUntilFulfilled,
        "Control Animal registry should preserve animal command limits")
    assertTrue(spellRegistry.spells.flare.effect.torchesCannotBeRelit and
        spellRegistry.spells.flare.effect.campfireBombExplosion,
        "Flare registry should preserve light-source and campfire metadata")
    assertTrue(spellRegistry.spells.defy_depths.effect.smallShipExtraResolve == 1 and
        spellRegistry.spells.defy_depths.effect.largeShipExtraResolve == 3,
        "Defy Depths registry should preserve sunken-ship Resolve surcharges")
    assertTrue(spellRegistry.spells.gust_of_wind.effect.selfTargetAllowed and
        spellRegistry.spells.gust_of_wind.effect.hazardousDestinationStillApplies,
        "Gust of Wind registry should preserve self-target and hazard metadata")
    assertTrue(spellRegistry.spells.thunderclap.effect.shattersFragileObjects and
        hasValue(spellRegistry.spells.thunderclap.effect.alternativeConditions, "deafened"),
        "Thunderclap registry should preserve fragile-object and drop-or-suffer metadata")
    assertTrue(spellRegistry.spells.portable_hole.effect.blindPocketDepthFeet == 1 and
        spellRegistry.spells.portable_hole.effect.livingTissueNoFunction,
        "Portable Hole registry should preserve blind-pocket and living-tissue metadata")
    assertTrue(spellRegistry.spells.illusion.effect.additiveOnly and
        spellRegistry.spells.illusion.effect.detailResolveCost == 1,
        "Illusion registry should preserve additive visual-detail metadata")
    assertTrue(spellRegistry.spells.withering.effect.destroyedAtResolve == 2 and
        spellRegistry.spells.withering.effect.objectDecayByMaterial.stone == "unaffected",
        "Withering registry should preserve object decay and destruction metadata")

    local function makeCaster(id, talent, componentId, resolve)
        local caster = base_entity.createEntity({
            id = id,
            name = id,
            isPC = true,
            wands = 4,
            talents = {
                [talent] = { mastered = true },
            },
        })
        caster.resolve = resolve or 4
        caster.inventory = inventory.createInventory()
        caster.inventory:addItem(inventory.createItemFromTemplate(componentId), inventory.LOCATIONS.HANDS)
        return caster
    end

    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local brainfeverCaster = makeCaster("pc_sparse_brainfever", "magic_of_the_wastes",
        "component_brainfever", 2)
    local brainfeverTarget = base_entity.createEntity({
        id = "npc_sparse_brainfever",
        name = "Sparse Brainfever Target",
        isPC = false,
        health = 2,
        defense = 0,
    })
    local brainfever = resolver:resolve({
        actor = brainfeverCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "brainfever",
        target = brainfeverTarget,
        targetInitiative = 5,
    })
    assertTrue(brainfever.success and brainfeverTarget.brainfever.grantsAttackFavor and
        brainfeverTarget.brainfever.emotionlessNoEffect,
        "Brainfever state should preserve rulebook metadata")

    local controlCaster = makeCaster("pc_sparse_control_animal", "magic_of_the_weald",
        "component_control_animal", 2)
    local animal = base_entity.createEntity({
        id = "npc_sparse_control_animal",
        name = "Sparse Animal",
        isPC = false,
        health = 2,
        defense = 0,
    })
    animal.animal = true
    local control = resolver:resolve({
        actor = controlCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "control_animal",
        target = animal,
        targetInitiative = 5,
        controlOrder = "heel",
    })
    assertTrue(control.success and animal.controlOrder.wordsPerResolveUsesWands and
        animal.controlOrder.animalsRefuseObviouslySuicidalOrders,
        "Control Animal state should preserve command metadata")

    local darklightCaster = makeCaster("pc_sparse_darklight", "magic_of_the_wastes",
        "component_darklight", 2)
    local darklightCandle = inventory.createItemFromTemplate("candles")
    darklightCaster.inventory:addItem(darklightCandle, inventory.LOCATIONS.HANDS)
    local darklight = resolver:resolve({
        actor = darklightCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "darklight",
        target = darklightCandle,
    })
    assertTrue(darklight.success and darklight.darklight.lightOnlyForHolder and
        darklight.darklight.extraViewerResolve == 1,
        "Darklight state should preserve private-light metadata")

    local fearCaster = makeCaster("pc_sparse_fear", "magic_of_the_wastes", "component_fear", 2)
    local fearTarget = base_entity.createEntity({
        id = "npc_sparse_fear",
        name = "Sparse Fear Target",
        isPC = false,
        health = 2,
        defense = 0,
    })
    local fearSource = base_entity.createEntity({ id = "pc_sparse_fear_source", name = "Fear Source", isPC = true })
    local fear = resolver:resolve({
        actor = fearCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "fear",
        target = fearTarget,
        targetInitiative = 5,
        cloakedTarget = fearSource,
    })
    assertTrue(fear.success and fear.emotionalIllusion.fearFleeFocus and
        fear.emotionalIllusion.prioritizeHighInitiative,
        "Fear state should preserve flight and high-Initiative metadata")

    local flareCaster = makeCaster("pc_sparse_flare", "magic_of_the_weald", "component_flare", 2)
    local torch = inventory.createItemFromTemplate("torch")
    flareCaster.inventory:addItem(torch, inventory.LOCATIONS.HANDS)
    local flare = resolver:resolve({
        actor = flareCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "flare",
        target = torch,
    })
    assertTrue(flare.success and flare.flare.torchesCannotBeRelit and flare.flare.torchAndLanternIgniteBearer,
        "Flare result should preserve torch/lantern metadata")

    local depthsCaster = makeCaster("pc_sparse_depths", "magic_of_the_weald",
        "component_defy_depths", 3)
    local rowboat = {
        id = "item_sparse_rowboat",
        name = "Sparse Rowboat",
        isItem = true,
        sunken = true,
        properties = {
            boat = true,
            shipSize = "small",
        },
    }
    local depths = resolver:resolve({
        actor = depthsCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "defy_depths",
        target = rowboat,
        resolveSpent = 2,
    })
    assertTrue(depths.success and depths.defyDepths[1].smallShipExtraResolve == 1 and
        depths.defyDepths[1].floatsEvenIfSubmergedOrSunken,
        "Defy Depths state should preserve ship and submerged-object metadata")

    local gustCaster = makeCaster("pc_sparse_gust", "magic_of_the_weald",
        "component_gust_of_wind", 2)
    gustCaster.zone = "A"
    local gustTarget = base_entity.createEntity({
        id = "npc_sparse_gust",
        name = "Sparse Gust Target",
        isPC = false,
        health = 2,
        defense = 0,
        zone = "A",
    })
    local gust = resolver:resolve({
        actor = gustCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "gust_of_wind",
        target = gustTarget,
        destinationZone = "B",
        challengeController = { zones = { { id = "A", adjacent_to = { "B" } }, { id = "B", adjacent_to = { "A" } } } },
    })
    assertTrue(gust.success and gust.gustOfWind.adjacentZoneOnly and gust.gustOfWind.canCrossGaps,
        "Gust of Wind result should preserve displacement metadata")

    local thunderCaster = makeCaster("pc_sparse_thunder", "magic_of_the_weald",
        "component_thunderclap", 2)
    thunderCaster.zone = "hall"
    local thunder = resolver:resolve({
        actor = thunderCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "thunderclap",
        zoneId = "hall",
        allEntities = { thunderCaster },
        zoneObjects = {},
    })
    assertTrue(thunder.success and thunder.thunderclap.shattersFragileObjects and
        hasValue(thunder.thunderclap.alternativeConditions, "stunned"),
        "Thunderclap result should preserve fragile-object and condition metadata")

    local weirdResolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })
    local holeCaster = makeCaster("pc_sparse_hole", "magic_of_the_weird", "component_portable_hole", 2)
    local surface = {
        id = "surface_sparse_hole",
        name = "Sparse Stone Wall",
        properties = {
            material = "stone",
            wall = true,
        },
    }
    local hole = weirdResolver:resolve({
        actor = holeCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "portable_hole",
        target = surface,
        noOtherSide = true,
    })
    assertTrue(hole.success and hole.portableHole.blindPocketDepthFeet == 1 and
        hole.portableHole.blindPocketSwallowsItemsUndamaged,
        "Portable Hole state should preserve blind-pocket metadata")

    local illusionCaster = makeCaster("pc_sparse_illusion", "magic_of_the_weird", "component_illusion", 2)
    local illusion = weirdResolver:resolve({
        actor = illusionCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "illusion",
        illusionKind = "object",
    })
    assertTrue(illusion.success and illusion.visualIllusion.mentalCommands and
        illusion.visualIllusion.detailResolveCost == 1,
        "Illusion state should preserve mental-command and detail-cost metadata")

    local witheringCaster = makeCaster("pc_sparse_withering", "magic_of_the_wastes",
        "component_withering", 3)
    local chain = {
        id = "item_sparse_chain",
        name = "Sparse Chain",
        isItem = true,
        material = "iron",
        durability = 2,
        properties = {},
    }
    local withering = resolver:resolve({
        actor = witheringCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "withering",
        target = chain,
        resolveSpent = 2,
    })
    assertTrue(withering.success and withering.witheringObjectDecay.objectTakesNotch and
        withering.witheringObjectDecay.destroyedAtResolve == 2,
        "Withering result should preserve object-decay and destruction metadata")
end

local function checkAnimateObjectSpell()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local caster = base_entity.createEntity({
        id = "pc_animate_object",
        name = "Object Mage",
        isPC = true,
        wands = 3,
        talents = {
            magic_of_the_weird = { mastered = true },
        },
    })
    caster.resolve = 4
    caster.inventory = inventory.createInventory()
    caster.inventory:addItem(inventory.createItemFromTemplate("component_animate_object"), inventory.LOCATIONS.HANDS)

    local key = inventory.createItem({
        name = "Bronze Key",
        size = 1,
        durability = 2,
        properties = {
            key = true,
            intendedPurpose = "unlock",
        },
    })
    local animateAction = {
        actor = caster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "animate_object",
        target = key,
        order = "unlock cell door",
    }
    local animate = resolver:resolve(animateAction)
    assertTrue(animate.success, "Animate Object should animate an object with a legal order")
    assertTrue(animate.spellcasting and animate.spellcasting.spellId == "animate_object",
        "Speak Incantation should preserve structured spellcasting metadata")
    assertTrue(animate.activeSpell and animate.spellcasting.activeSpell == animate.activeSpell,
        "ongoing Speak Incantation should expose its active spell entry")
    local spellPopup = getActionSequencerPopup(animateAction, animate, function(data)
        return data.title == "Speak Incantation"
    end)
    assertTrue(spellPopup ~= nil, "successful Speak Incantation should queue a visible spell popup")
    assertEqual(spellPopup.spellId, "animate_object", "spell popup should preserve the spell id")
    assertEqual(spellPopup.resolveSpent, 1, "spell popup should preserve Resolve actually spent")
    assertEqual(spellPopup.spellResolveValue, 1, "spell popup should preserve spell Resolve value")
    assertTrue(spellPopup.component == animate.component, "spell popup should preserve the held component")
    assertTrue(spellPopup.activeSpell == animate.activeSpell, "spell popup should preserve active spell state")
    assertTrue(spellPopup.animatedObject == animate.animatedObject,
        "spell popup should preserve spell-specific effect metadata")
    assertTrue(key.animatedObject and key.animatedObject.invisibleHand,
        "Animate Object should record invisible-hand operation")
    assertTrue(key.animatedObject.intendedPurposeOnly and key.animatedObject.oneTaskPerCasting,
        "Animate Object should preserve intended-purpose and one-task metadata")
    assertTrue(key.animatedObject.wordsPerResolveUsesWands and
        key.animatedObject.actionValueFromSpeakIncantation,
        "Animate Object should preserve Wands-per-Resolve and Challenge-value metadata")
    assertTrue(key.animatedObject.lastsUntilTaskFulfilled and
        key.animatedObject.committedResolveUntilFulfilled,
        "Animate Object should record task-duration Resolve commitment")
    assertEqual(key.animatedObject.maxWords, 3, "Animate Object word limit should be Wands per Resolve")
    assertEqual(key.animatedObject.wordCount, 3, "Animate Object should count command words")
    assertEqual(key.animatedObject.actionValue, animate.testValue,
        "Animate Object Challenge action value should match Speak Incantation value")
    assertEqual(caster.committedResolve, 1, "Animate Object should commit Resolve until the task is fulfilled")
    assertTrue(caster.activeSpells and caster.activeSpells[1] and not caster.activeSpells[1].concentration,
        "Animate Object should not occupy concentration")

    local task = resolver:resolveAnimatedObjectTask(key, {
        task = "unlock cell door",
        inChallenge = true,
    })
    assertTrue(task.success, "Animate Object task helper should fulfill the one task")
    assertEqual(task.actionValue, animate.testValue, "fulfilled animated object task should expose action value")
    assertTrue(key.animatedObject == nil, "fulfilled Animate Object task should clear object animation")
    assertEqual(caster.committedResolve, 0, "fulfilled Animate Object task should release committed Resolve")

    local vaultKey = inventory.createItem({
        name = "Vault Key",
        size = 1,
        durability = 2,
        properties = {
            key = true,
            intendedPurpose = "unlock",
        },
    })
    local extended = resolver:resolve({
        actor = caster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "animate_object",
        target = vaultKey,
        resolveSpent = 2,
        order = "unlock the heavy bronze vault door",
    })
    assertTrue(extended.success, "additional Resolve should extend Animate Object commands")
    assertEqual(vaultKey.animatedObject.maxWords, 6, "extra Resolve should add Wands more words")
    resolver:endOngoingSpell(caster, caster.activeSpells[1], "released")
    assertTrue(vaultKey.animatedObject == nil, "ending Animate Object manually should clear animation")

    local dagger = inventory.createItemFromTemplate("dagger")
    local strike = resolver:resolve({
        actor = caster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "animate_object",
        target = dagger,
        order = "stab guard",
    })
    assertTrue(strike.success, "Animate Object should animate an unattended weapon")
    assertTrue(dagger.animatedObject.unattendedWeaponOneStrike,
        "unattended animated weapons should be limited to one strike")
    local strikeTask = resolver:resolveAnimatedObjectTask(dagger, { task = "stab guard", inChallenge = true })
    assertTrue(hasValue(strikeTask.effects, "animate_object_weapon_strike"),
        "animated weapon fulfillment should report the one strike")
    local secondStrike = resolver:resolveAnimatedObjectTask(dagger, { task = "stab again", inChallenge = true })
    assertTrue(not secondStrike.success, "Animate Object should only fulfill one task per casting")

    local invalidCaster = base_entity.createEntity({
        id = "pc_animate_object_invalid",
        name = "Invalid Object Mage",
        isPC = true,
        wands = 2,
        talents = {
            magic_of_the_weird = { mastered = true },
        },
    })
    invalidCaster.resolve = 1
    invalidCaster.inventory = inventory.createInventory()
    invalidCaster.inventory:addItem(inventory.createItemFromTemplate("component_animate_object"), inventory.LOCATIONS.HANDS)
    local invalidKey = inventory.createItem({
        name = "Wordy Key",
        size = 1,
        durability = 2,
        properties = { key = true },
    })
    local tooLong = resolver:resolve({
        actor = invalidCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "animate_object",
        target = invalidKey,
        order = "unlock the door",
    })
    assertTrue(not tooLong.success, "Animate Object should reject overlong commands before spending Resolve")
    assertTrue(hasValue(tooLong.effects, "animate_object_order_too_long"),
        "Animate Object overlong command should report its gate")
    assertEqual(invalidCaster.resolve, 1, "failed Animate Object validation should not spend Resolve")

    local wrongPurpose = resolver:resolve({
        actor = invalidCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "animate_object",
        target = invalidKey,
        order = "sing softly",
    })
    assertTrue(not wrongPurpose.success, "Animate Object should reject orders outside the object's purpose")
    assertTrue(hasValue(wrongPurpose.effects, "animate_object_wrong_purpose"),
        "Animate Object wrong-purpose orders should report their gate")
    assertEqual(invalidCaster.resolve, 1, "wrong-purpose Animate Object should not spend Resolve")
end

local function checkScrySpell()
    local scrySpell = require('data.spell_registry').spells.scry
    assertEqual(scrySpell.effect.componentAction, "peer_into_crystal_ball",
        "Scry should record crystal-ball component use")
    assertTrue(scrySpell.effect.visitedLocationOnly,
        "Scry should record visited-location restriction")
    assertEqual(scrySpell.effect.outsideAreaExtraResolve, 1,
        "Scry should record outside-area Resolve surcharge")

    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local caster = base_entity.createEntity({
        id = "pc_scry",
        name = "Crystal Seer",
        isPC = true,
        wands = 3,
        talents = {
            magic_of_the_weird = { mastered = true },
        },
    })
    caster.metaphysicalArea = "crypt_level_1"
    caster.visitedLocations = {
        crypt_shrine = true,
        city_gate = true,
    }
    caster.resolve = 4
    caster.inventory = inventory.createInventory()
    caster.inventory:addItem(inventory.createItemFromTemplate("component_scry"), inventory.LOCATIONS.HANDS)

    local shrine = {
        id = "crypt_shrine",
        name = "Guardian Shrine",
        metaphysicalArea = "crypt_level_1",
    }
    local sameArea = resolver:resolve({
        actor = caster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "scry",
        targetLocation = shrine,
    })
    assertTrue(sameArea.success, "Scry should reveal a visited location in the same metaphysical area")
    assertTrue(caster.scrying and caster.scrying.canSeeLocation, "Scry should record active remote sight")
    assertEqual(caster.scrying.locationId, "crypt_shrine", "Scry should store the viewed location")
    assertEqual(caster.scrying.componentAction, "peer_into_crystal_ball",
        "Scry state should preserve component use")
    assertTrue(caster.scrying.visitedLocationOnly and caster.scrying.defaultSameMetaphysicalAreaOnly,
        "Scry state should preserve location restrictions")
    assertTrue(not caster.scrying.outsideCurrentArea, "same-area Scry should not mark cross-area viewing")
    assertEqual(caster.committedResolve, 1, "Scry should commit Resolve while concentrated")

    resolver:endOngoingSpell(caster, caster.activeSpells[1], "released")
    assertTrue(caster.scrying == nil, "ending Scry should clear active remote sight")
    assertEqual(caster.committedResolve, 0, "ending Scry should release committed Resolve")

    local cityGate = {
        id = "city_gate",
        name = "City Gate",
        metaphysicalArea = "surface_city",
    }
    local crossAreaTooCheap = resolver:resolve({
        actor = caster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "scry",
        targetLocation = cityGate,
        resolveSpent = 1,
    })
    assertTrue(not crossAreaTooCheap.success, "Scry should require +1 Resolve outside the current area")
    assertTrue(hasValue(crossAreaTooCheap.effects, "scry_area_resolve_missing"),
        "cross-area Scry should report its Resolve gate")
    assertEqual(caster.resolve, 3, "failed cross-area Scry should not spend Resolve")

    local crossArea = resolver:resolve({
        actor = caster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "scry",
        targetLocation = cityGate,
        resolveSpent = 2,
    })
    assertTrue(crossArea.success, "Scry should allow outside-area viewing with +1 Resolve")
    assertTrue(crossArea.scrying.outsideCurrentArea, "paid cross-area Scry should mark outside-area viewing")
    assertTrue(hasValue(crossArea.effects, "scry_cross_area"), "paid cross-area Scry should report the rider")
    assertEqual(caster.committedResolve, 2, "paid cross-area Scry should commit all spent Resolve")

    resolver:endOngoingSpell(caster, caster.activeSpells[1], "released")

    local unvisited = resolver:resolve({
        actor = caster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "scry",
        targetLocation = {
            id = "unvisited_vault",
            name = "Unvisited Vault",
            metaphysicalArea = "crypt_level_1",
        },
    })
    assertTrue(not unvisited.success, "Scry should reject unvisited locations")
    assertTrue(hasValue(unvisited.effects, "scry_location_unvisited"),
        "unvisited Scry should report its visited-location gate")
    assertEqual(caster.resolve, 1, "failed unvisited Scry should not spend Resolve")
end

local function checkTotemSpell()
    local bus = events.createEventBus()
    local testRequest = nil
    bus:on(events.EVENTS.REQUEST_TEST_OF_FATE, function(data)
        testRequest = data
    end)

    local resolver = action_resolver.createActionResolver({
        eventBus = bus,
    })

    local caster = base_entity.createEntity({
        id = "pc_totem",
        name = "Totem Mage",
        isPC = true,
        swords = 3,
        pentacles = 2,
        cups = 1,
        wands = 4,
        talents = {
            magic_of_the_weald = { mastered = true },
        },
    })
    caster.resolve = 3
    caster.inventory = inventory.createInventory()
    local acorn = inventory.createItemFromTemplate("component_totem")
    local dagger = inventory.createItemFromTemplate("dagger")
    local torch = inventory.createItemFromTemplate("torch")
    local wornArmor = inventory.createItemFromTemplate("light_armor")
    caster.inventory:addItem(acorn, inventory.LOCATIONS.HANDS)
    caster.inventory:addItem(dagger, inventory.LOCATIONS.HANDS)
    caster.inventory:addItem(torch, inventory.LOCATIONS.PACK)
    caster.wornArmor = wornArmor

    local totem = resolver:resolve({
        actor = caster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "totem",
        totemCard = { name = "Knight of Swords", value = 12, suit = constants.SUITS.SWORDS },
        totemKnownFor = { "spot", "fly" },
    })
    assertTrue(totem.success, "Totem should transform the caster without an explicit target")
    assertEqual(totem.totemForm.totemAnimal, "Eagle", "Totem should map random chart cards")
    assertTrue(caster.conditions.totemForm and caster.inTotemForm, "Totem should mark active animal form")
    assertEqual(caster.swords, 0, "Totem form should set Swords to +0")
    assertEqual(caster.pentacles, 0, "Totem form should set Pentacles to +0")
    assertEqual(caster.cups, 0, "Totem form should set Cups to +0")
    assertEqual(caster.wands, 0, "Totem form should set Wands to +0")
    assertTrue(totem.totemForm.uniqueAnimalShape and totem.totemForm.representsSoulTotem,
        "Totem should preserve the unique soul-totem animal shape metadata")
    assertTrue(totem.totemForm.transformationNearInstantaneous,
        "Totem should preserve the near-instantaneous transformation metadata")
    assertTrue(totem.totemForm.wornItemsDoNotTransform and totem.totemForm.carriedObjectsDoNotTransform,
        "Totem should record that worn and carried gear does not transform")
    assertTrue(caster.inventory:findItem(dagger.id) == nil, "Totem should drop carried gear")
    assertTrue(caster.inventory:findItem(torch.id) == nil, "Totem should drop packed gear")
    assertTrue(caster.wornArmor == nil and hasValue(caster.droppedItems, wornArmor),
        "Totem should drop worn gear tracked outside inventory")
    assertTrue(wornArmor.droppedByTotem and wornArmor.properties.transformsWithTotem == false,
        "Totem dropped worn gear should be marked as not transformed")
    assertTrue(caster.inventory:findItem(acorn.id) == nil, "Totem should move the component to the mouth")
    assertTrue(totem.totemForm.componentInMouth and totem.totemForm.componentMouthTarget == caster,
        "Totem should place the acorn in the target's mouth")
    assertEqual(#caster.droppedItems, 3, "Totem should leave worn and carried objects around the target")
    assertEqual(caster.committedResolve, 1, "Totem should commit Resolve while the acorn is held")
    assertTrue(caster.activeSpells and caster.activeSpells[1] and not caster.activeSpells[1].concentration,
        "Totem should be ongoing without occupying concentration")
    assertTrue(hasValue(totem.totemForm.mouthUseEndActions, "eat") and
        hasValue(totem.totemForm.mouthUseEndActions, "drink") and
        hasValue(totem.totemForm.mouthUseEndActions, "pick_up_with_mouth"),
        "Totem should record the mouth uses that end the spell")

    local pending = resolver:resolve({
        actor = caster,
        card = { name = "Cups", value = 2, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.TEST_FATE,
        testAttribute = "wands",
        targetSuit = constants.SUITS.WANDS,
        totemTags = { "spot" },
        challengeController = {
            isActive = function()
                return true
            end,
        },
    })
    assertTrue(pending.pendingTestOfFate, "Totem-form Tests of Fate should still use the async test flow")
    assertEqual(testRequest.attributeBonus, 5, "Totem should add +5 to relevant Tests of Fate")
    assertTrue(hasValue(pending.effects, "totem_test_bonus"), "Totem test bonus should be reported")

    local modal = test_of_fate_modal.createTestOfFateModal({
        eventBus = events.createEventBus(),
        deck = {
            draw = function()
                return { name = "Nine of Cups", value = 9, suit = constants.SUITS.CUPS }
            end,
            discard = function() end,
        },
    })
    modal:startTest({
        entity = caster,
        attribute = "wands",
        attributeBonus = testRequest.attributeBonus,
    })
    assertEqual(modal.result.total, 14, "Totem +5 should apply to Test of Fate totals")
    assertTrue(modal.result.success, "Totem +5 should be enough to pass this test")
    modal:hide()

    caster.totemTalk = resolver:resolve({
        actor = caster,
        type = action_resolver.ACTION_TYPES.FREE_ACTION,
        freeAction = "talk",
        speech = "I speak around the acorn.",
    })
    assertTrue(caster.totemTalk.success and hasValue(caster.totemTalk.effects, "totem_mouth_use"),
        "talking through the normal free-action path should end Totem")
    assertTrue(caster.totemForm == nil and not caster.conditions.totemForm,
        "ending Totem should clear animal form")
    assertEqual(caster.swords, 3, "ending Totem should restore Swords")
    assertEqual(caster.wands, 4, "ending Totem should restore Wands")
    assertEqual(caster.committedResolve, 0, "ending Totem should release committed Resolve")
    assertEqual(#caster.droppedItems, 4, "ending Totem should spit out the acorn")

    local randomCaster = base_entity.createEntity({
        id = "pc_totem_random",
        name = "Random Totem Mage",
        isPC = true,
        wands = 3,
        talents = {
            magic_of_the_weald = { mastered = true },
        },
    })
    randomCaster.resolve = 1
    randomCaster.inventory = inventory.createInventory()
    randomCaster.inventory:addItem(inventory.createItemFromTemplate("component_totem"), inventory.LOCATIONS.HANDS)
    local drawCount = 0
    local discardCount = 0
    local randomDeck = {
        draw = function()
            drawCount = drawCount + 1
            return { name = "Queen of Wands", value = 13, suit = constants.SUITS.WANDS }
        end,
        discard = function()
            discardCount = discardCount + 1
        end,
    }
    local randomTotem = resolver:resolve({
        actor = randomCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "totem",
        deck = randomDeck,
    })
    assertTrue(randomTotem.success, "Totem should randomly determine an unknown soul totem")
    assertEqual(randomCaster.soulTotemAnimal, "Dire Spider", "Totem should store the random soul totem")
    assertEqual(drawCount, 1, "Totem should draw once from the random totem deck")
    assertEqual(discardCount, 1, "Totem should discard the random chart card")
    randomCaster.totemDrink = resolver:resolve({
        actor = randomCaster,
        card = { name = "King of Cups", value = 14, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.TRIVIAL_ACTION,
        trivialAction = "drink",
    })
    assertTrue(randomCaster.totemDrink.success and hasValue(randomCaster.totemDrink.effects, "totem_mouth_use"),
        "drinking through a normal action should end Totem")
    assertTrue(randomCaster.totemForm == nil and not randomCaster.conditions.totemForm,
        "drink-triggered Totem ending should clear animal form")

    local targetCaster = base_entity.createEntity({
        id = "pc_totem_target_caster",
        name = "Targeting Totem Mage",
        isPC = true,
        wands = 3,
        talents = {
            magic_of_the_weald = { mastered = true },
        },
    })
    local targetSubject = base_entity.createEntity({
        id = "pc_totem_target_subject",
        name = "Totem Subject",
        isPC = true,
    })
    targetCaster.resolve = 1
    targetCaster.inventory = inventory.createInventory()
    local targetAcorn = inventory.createItemFromTemplate("component_totem")
    targetCaster.inventory:addItem(targetAcorn, inventory.LOCATIONS.HANDS)
    local targetTotem = resolver:resolve({
        actor = targetCaster,
        target = targetSubject,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "totem",
        totemAnimal = "Fox",
    })
    assertTrue(targetTotem.success, "Totem should transform an explicit willing creature target")
    assertTrue(targetSubject.mouthOccupiedByTotem and targetTotem.totemForm.componentMouthTarget == targetSubject,
        "Totem should place the acorn in an explicit target's mouth")
    assertTrue(targetCaster.inventory:findItem(targetAcorn.id) == nil,
        "targeted Totem should consume the caster's acorn component")
    targetSubject.mouthItem = inventory.createItem({ id = "fallen_apple", name = "Fallen Apple", size = 1 })
    targetSubject.mouthPickup = resolver:resolve({
        actor = targetSubject,
        card = { name = "King of Cups", value = 14, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.TRIVIAL_ACTION,
        trivialAction = "pick_up_with_mouth",
        item = targetSubject.mouthItem,
        withMouth = true,
    })
    assertTrue(targetSubject.mouthPickup.success and hasValue(targetSubject.mouthPickup.effects, "totem_mouth_use"),
        "picking something up with the mouth should end targeted Totem")
    assertTrue(targetSubject.totemForm == nil and not targetSubject.conditions.totemForm,
        "mouth-pickup Totem ending should clear the target's animal form")

    local invalidCaster = base_entity.createEntity({
        id = "pc_totem_invalid",
        name = "Invalid Totem Mage",
        isPC = true,
        wands = 3,
        talents = {
            magic_of_the_weald = { mastered = true },
        },
    })
    invalidCaster.resolve = 1
    invalidCaster.inventory = inventory.createInventory()
    invalidCaster.inventory:addItem(inventory.createItemFromTemplate("component_totem"), inventory.LOCATIONS.HANDS)
    local invalid = resolver:resolve({
        actor = invalidCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "totem",
    })
    assertTrue(not invalid.success, "Totem should require a known totem or random chart draw")
    assertTrue(hasValue(invalid.effects, "totem_missing"), "Totem missing chart should report its gate")
    assertEqual(invalidCaster.resolve, 1, "failed Totem validation should not spend Resolve")
end

local function checkWoodweaveSpell()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local caster = base_entity.createEntity({
        id = "pc_woodweave",
        name = "Woodweaver",
        isPC = true,
        wands = 3,
        zone = "grove",
        talents = {
            magic_of_the_weald = { mastered = true },
        },
    })
    caster.resolve = 6
    caster.inventory = inventory.createInventory()
    caster.inventory:addItem(inventory.createItemFromTemplate("component_woodweave"), inventory.LOCATIONS.HANDS)

    local sapling = {
        id = "plant_grow",
        name = "Sapling",
        plant = true,
        livingPlant = true,
        conditions = {},
    }
    local grow = resolver:resolve({
        actor = caster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "woodweave",
        target = sapling,
        mode = "grow",
    })
    assertTrue(grow.success, "Woodweave should grow living plants")
    assertTrue(sapling.conditions.grown, "Woodweave grow should mark the plant grown")
    assertTrue(grow.woodweave.controlsPlantGrowth and sapling.woodweave.appliesGrowEffect,
        "Woodweave grow should preserve the rapid Grow-effect metadata")

    local vine = {
        id = "plant_shrink",
        name = "Vine",
        plant = true,
        livingPlant = true,
        conditions = {},
    }
    local shrink = resolver:resolve({
        actor = caster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "woodweave",
        target = vine,
        mode = "shrink",
    })
    assertTrue(shrink.success, "Woodweave should shrink living plants")
    assertTrue(vine.conditions.shrunk and vine.conditions.witheredToSeed,
        "Woodweave shrink should wither the plant toward seed")
    assertTrue(shrink.woodweave.withersBackToSeed and vine.woodweave.appliesShrinkingEffect,
        "Woodweave shrink should preserve the Shrinking-effect metadata")

    local woodenDoor = inventory.createItem({
        name = "Wooden Door",
        size = 3,
        durability = 2,
        properties = {
            material = "wood",
        },
    })
    local warp = resolver:resolve({
        actor = caster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "woodweave",
        target = woodenDoor,
        mode = "warp",
    })
    assertTrue(warp.success, "Woodweave should affect wooden objects")
    assertEqual(woodenDoor.notches, 1, "Woodweave should Notch wooden objects")
    assertTrue(woodenDoor.woodweaveWarped, "Woodweave should record warped wooden objects")
    assertTrue(warp.woodweave.notchesObject and woodenDoor.woodweave.warpsAndReshapesWood,
        "Woodweave warp should preserve the Notch and reshape metadata")

    local ally = base_entity.createEntity({
        id = "pc_woodweave_ally",
        name = "Rooted Ally",
        isPC = true,
        zone = "grove",
        conditions = {},
    })
    local foe = base_entity.createEntity({
        id = "npc_woodweave_foe",
        name = "Rooted Foe",
        isPC = false,
        zone = "grove",
        conditions = {},
    })
    local elsewhere = base_entity.createEntity({
        id = "npc_woodweave_elsewhere",
        name = "Elsewhere Foe",
        isPC = false,
        zone = "crypt",
        conditions = {},
    })
    local root = resolver:resolve({
        actor = caster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "woodweave",
        mode = "root",
        zoneId = "grove",
        placeOfVegetation = true,
        allEntities = { caster, ally, foe, elsewhere },
    })
    assertTrue(root.success, "Woodweave should root creatures in a vegetation zone")
    assertTrue(caster.conditions.rooted and ally.conditions.rooted and foe.conditions.rooted,
        "Woodweave roots all creatures in the selected zone")
    assertTrue(not elsewhere.conditions.rooted, "Woodweave should not root creatures outside the selected zone")
    assertTrue(root.woodweave.placeOfVegetation and root.woodweave.conjuresEntanglingVines and
        root.woodweave.rootsAllCreaturesInSingleZone,
        "Woodweave root should preserve vegetation and entangling-vine metadata")

    local rawWood = {
        id = "raw_wood",
        name = "Equivalent Raw Wood",
        properties = {
            material = "wood",
        },
    }
    local shape = resolver:resolve({
        actor = caster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "woodweave",
        target = rawWood,
        mode = "shape",
        shapeInto = "ladder",
    })
    assertTrue(shape.success, "Woodweave should shape equivalent raw materials")
    assertEqual(rawWood.shapedInto, "ladder", "Woodweave should record the shaped wooden object")
    assertTrue(shape.woodweave.instantShape and rawWood.equivalentSizeRequired and rawWood.shapedInstantly,
        "Woodweave shape should preserve equivalent-size and instant-shape metadata")

    local invalidCaster = base_entity.createEntity({
        id = "pc_woodweave_invalid",
        name = "Invalid Woodweaver",
        isPC = true,
        wands = 3,
        talents = {
            magic_of_the_weald = { mastered = true },
        },
    })
    invalidCaster.resolve = 1
    invalidCaster.inventory = inventory.createInventory()
    invalidCaster.inventory:addItem(inventory.createItemFromTemplate("component_woodweave"), inventory.LOCATIONS.HANDS)
    local tooSmallRawWood = {
        id = "small_raw_wood",
        name = "Small Raw Wood",
        size = 1,
        properties = {
            material = "wood",
        },
    }
    local sizeMismatch = resolver:resolve({
        actor = invalidCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "woodweave",
        target = tooSmallRawWood,
        mode = "shape",
        shapeInto = "door",
        shapeSize = 3,
    })
    assertTrue(not sizeMismatch.success, "Woodweave should reject undersized raw materials")
    assertTrue(hasValue(sizeMismatch.effects, "woodweave_material_size_mismatch"),
        "Woodweave undersized raw materials should report the equivalent-size gate")
    assertEqual(invalidCaster.resolve, 1, "undersized Woodweave shape should not spend Resolve")
    assertTrue(not tooSmallRawWood.shapedByWoodweave, "undersized Woodweave shape should not shape the material")

    local barrenRoot = resolver:resolve({
        actor = invalidCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "woodweave",
        mode = "root",
        zoneId = "crypt",
        allEntities = { invalidCaster },
    })
    assertTrue(not barrenRoot.success, "Woodweave roots should require vegetation")
    assertTrue(hasValue(barrenRoot.effects, "woodweave_vegetation_required"),
        "Woodweave root should report the vegetation gate")
    assertEqual(invalidCaster.resolve, 1, "failed Woodweave vegetation gate should not spend Resolve")

    local stone = {
        id = "stone_object",
        name = "Stone Block",
        properties = {
            material = "stone",
        },
    }
    local invalid = resolver:resolve({
        actor = invalidCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "woodweave",
        target = stone,
        mode = "warp",
    })
    assertTrue(not invalid.success, "Woodweave should reject non-wood, non-plant targets")
    assertTrue(hasValue(invalid.effects, "woodweave_invalid_target"),
        "Woodweave invalid target should report its target gate")
    assertEqual(invalidCaster.resolve, 1, "failed Woodweave target gate should not spend Resolve")
end

local function checkWallOfElementsSpell()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local caster = base_entity.createEntity({
        id = "pc_wall_elements",
        name = "Wall Mage",
        isPC = true,
        wands = 3,
        zone = "causeway",
        talents = {
            magic_of_the_weald = { mastered = true },
        },
    })
    caster.resolve = 4
    caster.inventory = inventory.createInventory()
    caster.inventory:addItem(inventory.createItemFromTemplate("component_wall_of_elements"), inventory.LOCATIONS.HANDS)

    local fireWall = resolver:resolve({
        actor = caster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "wall_of_elements",
        resolveSpent = 3,
        element = "fire",
        zoneId = "bridge",
    })
    assertTrue(fireWall.success, "Wall of Elements should create paid wall sections")
    assertTrue(fireWall.elementWall ~= nil, "Wall of Elements should return a wall object")
    assertEqual(fireWall.elementWall.sectionCount, 3, "each Resolve should create one wall section")
    assertTrue(fireWall.elementWall.oneSectionPerResolve and fireWall.elementWall.maintainedByConcentration,
        "Wall of Elements should preserve section-per-Resolve concentration metadata")
    assertEqual(fireWall.elementWall.sections[1].widthFeet, 10, "wall sections should be 10 feet wide")
    assertEqual(fireWall.elementWall.sections[1].heightFeet, 10, "wall sections should be 10 feet tall")
    assertEqual(fireWall.elementWall.sections[1].depthFeet, 2, "wall sections should be 2 feet deep")
    assertEqual(fireWall.elementWall.sections[1].element, "fire", "scalar element should apply to all sections")
    assertTrue(fireWall.elementWall.sections[1].opaque, "fire wall sections should be opaque")
    assertTrue(fireWall.elementWall.sections[1].permeable, "fire wall sections should be permeable")
    assertTrue(fireWall.elementWall.sections[1].woundsOnPassage, "fire wall sections should wound on passage")
    assertTrue(fireWall.elementWall.sections[1].ruleBehavior.woundsOnPassage,
        "fire wall sections should retain registry behavior metadata")
    assertEqual(caster.resolve, 1, "Wall of Elements should spend Resolve")
    assertEqual(caster.committedResolve, 3, "Wall of Elements should commit Resolve while concentrated")
    assertTrue(caster.activeElementWalls and caster.activeElementWalls[1] == fireWall.elementWall,
        "caster should track active element walls")

    local passer = base_entity.createEntity({
        id = "npc_fire_wall_passer",
        name = "Fire Wall Passer",
        isPC = false,
        health = 2,
        defense = 0,
        conditions = {},
    })
    local passage = resolver:resolveElementWallPassage(fireWall.elementWall.sections[1], passer)
    assertTrue(passage.success and passage.wounded, "passing through fire wall should wound the creature")
    assertTrue(hasValue(passage.effects, "wall_fire_wound"), "fire wall passage should report the wound")
    assertEqual(passer.npcHealth, 1, "fire wall passage should apply one Wound")

    resolver:endOngoingSpell(caster, caster.activeSpells[1], "released")
    assertTrue(not fireWall.elementWall.active, "ending Wall of Elements should deactivate the wall")
    assertTrue(not fireWall.elementWall.sections[1].active, "ending Wall of Elements should deactivate sections")
    assertEqual(#caster.activeElementWalls, 0, "ending Wall of Elements should clear caster wall tracking")
    assertEqual(caster.committedResolve, 0, "ending Wall of Elements should release committed Resolve")

    local windCaster = base_entity.createEntity({
        id = "pc_wall_elements_wind",
        name = "Wind Wall Mage",
        isPC = true,
        wands = 3,
        talents = {
            magic_of_the_weald = { mastered = true },
        },
    })
    windCaster.resolve = 1
    windCaster.inventory = inventory.createInventory()
    windCaster.inventory:addItem(inventory.createItemFromTemplate("component_wall_of_elements"), inventory.LOCATIONS.HANDS)
    local windWall = resolver:resolve({
        actor = windCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "wall_of_elements",
        element = "wind",
    })
    assertTrue(windWall.success, "Wall of Elements should create wind sections")
    assertTrue(not windWall.elementWall.sections[1].opaque, "wind wall sections should not be opaque")
    assertTrue(resolver:wallBlocksPassage(windWall.elementWall.sections[1], { missile = true }),
        "wind wall should block missile weapons")
    assertTrue(resolver:wallBlocksPassage(windWall.elementWall.sections[1], { flying = true }),
        "wind wall should block flying creatures")
    assertTrue(not resolver:wallBlocksPassage(windWall.elementWall.sections[1], { walking = true }),
        "wind wall should not block ordinary passage")

    local earthCaster = base_entity.createEntity({
        id = "pc_wall_elements_earth",
        name = "Earth Wall Mage",
        isPC = true,
        wands = 3,
        talents = {
            magic_of_the_weald = { mastered = true },
        },
    })
    earthCaster.resolve = 1
    earthCaster.inventory = inventory.createInventory()
    earthCaster.inventory:addItem(inventory.createItemFromTemplate("component_wall_of_elements"), inventory.LOCATIONS.HANDS)
    local earthWall = resolver:resolve({
        actor = earthCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "wall_of_elements",
        element = "earth",
    })
    assertTrue(earthWall.success, "Wall of Elements should create earth sections")
    assertTrue(earthWall.elementWall.sections[1].opaque and earthWall.elementWall.sections[1].toughAsStone,
        "earth wall sections should be opaque and tough as stone")
    assertTrue(resolver:wallBlocksPassage(earthWall.elementWall.sections[1], { walking = true }),
        "earth wall sections should block ordinary passage")

    local waterCaster = base_entity.createEntity({
        id = "pc_wall_elements_water_invalid",
        name = "Water Wall Mage",
        isPC = true,
        wands = 3,
        talents = {
            magic_of_the_weald = { mastered = true },
        },
    })
    waterCaster.resolve = 1
    waterCaster.inventory = inventory.createInventory()
    waterCaster.inventory:addItem(inventory.createItemFromTemplate("component_wall_of_elements"), inventory.LOCATIONS.HANDS)
    local invalidWater = resolver:resolve({
        actor = waterCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "wall_of_elements",
        element = "water",
    })
    assertTrue(not invalidWater.success, "water walls should require a body of water")
    assertTrue(hasValue(invalidWater.effects, "wall_water_requires_water"),
        "water wall placement should report its water gate")
    assertEqual(waterCaster.resolve, 1, "failed Wall of Elements water gate should not spend Resolve")

    local tooMany = resolver:resolve({
        actor = waterCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "wall_of_elements",
        resolveSpent = 1,
        elements = { "earth", "fire" },
    })
    assertTrue(not tooMany.success, "Wall of Elements should require one Resolve per section")
    assertTrue(hasValue(tooMany.effects, "wall_elements_too_many_sections"),
        "Wall of Elements should report too many sections before spending Resolve")
    assertEqual(waterCaster.resolve, 1, "failed Wall of Elements section gate should not spend Resolve")

    local waterWall = resolver:resolve({
        actor = waterCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "wall_of_elements",
        element = "water",
        bodyOfWater = true,
    })
    assertTrue(waterWall.success, "water walls should be allowed in bodies of water")
    assertTrue(waterWall.elementWall.sections[1].opaque and waterWall.elementWall.sections[1].impermeable,
        "water wall sections should be opaque and impermeable")
    assertTrue(waterWall.elementWall.sections[1].requiresWater and
        waterWall.elementWall.sections[1].blocksShips and waterWall.elementWall.sections[1].blocksWatercraft,
        "water wall sections should require water and block ships or watercraft")
end

local function checkChangeSizeSpell()
    local resolver = action_resolver.createActionResolver({
        eventBus = events.createEventBus(),
    })

    local caster = base_entity.createEntity({
        id = "pc_change_size",
        name = "Size Mage",
        isPC = true,
        wands = 3,
        talents = {
            magic_of_the_weird = { mastered = true },
        },
    })
    caster.resolve = 2
    caster.inventory = inventory.createInventory()
    caster.inventory:addItem(inventory.createItemFromTemplate("component_change_size"), inventory.LOCATIONS.HANDS)

    local target = base_entity.createEntity({
        id = "pc_change_size_target",
        name = "Grown Target",
        isPC = true,
        pentacles = 0,
        swords = 0,
        conditions = {},
    })
    target.heightFeet = 6
    target.inventory = inventory.createInventory()
    target.inventory:addItem(inventory.createItemFromTemplate("dagger"), inventory.LOCATIONS.HANDS)

    local grow = resolver:resolve({
        actor = caster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "change_size",
        target = target,
        mode = "grow",
        unwilling = false,
    })
    assertTrue(grow.success, "Change Size should grow a creature")
    assertTrue(target.conditions.sizeChanged and target.conditions.sizeGrown,
        "Change Size grow should mark size state")
    assertEqual(target.sizeMultiplier, 2, "Change Size grow should double effective size")
    assertEqual(target.changeSize.effectiveHeightFeet, 12, "Change Size grow should double original height")
    assertTrue(target.changeSize.halfOrDoubleOriginalHeight and target.changeSize.attackValuesUnaffected and
        target.changeSize.mayInfluenceRoughhouse,
        "Change Size should preserve height, Attack, and Roughhouse metadata")
    assertEqual(caster.committedResolve, 1, "Change Size should commit Resolve while concentrated")

    local foe = base_entity.createEntity({
        id = "npc_change_size_foe",
        name = "Size Foe",
        isPC = false,
        health = 2,
        defense = 0,
        conditions = {},
    })
    local roughhouse = resolver:resolve({
        actor = target,
        target = foe,
        card = { name = "Pentacles", value = 7, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "trip",
        targetInitiative = 9,
    })
    assertTrue(roughhouse.success, "grown creatures should gain favor where size helps Roughhouse")
    assertEqual(roughhouse.favorModifier, 3, "Change Size grow should grant Roughhouse favor")
    assertTrue(hasValue(roughhouse.effects, "change_size_action_favor"),
        "Change Size Roughhouse favor should be reported")

    foe.conditions.prone = false
    local attack = resolver:resolve({
        actor = target,
        target = foe,
        card = { name = "Swords", value = 7, suit = constants.SUITS.SWORDS },
        type = action_resolver.ACTION_TYPES.MELEE,
        weapon = target.inventory:getWieldedWeapon(),
        targetInitiative = 10,
    })
    assertTrue(not hasValue(attack.effects, "change_size_action_favor"),
        "Change Size should not grant Attack favor")
    assertEqual(attack.favorModifier, 0, "Change Size should not modify Attack values")

    resolver:endOngoingSpell(caster, caster.activeSpells[1], "released")
    assertTrue(target.changeSize == nil, "ending Change Size should clear size state")
    assertTrue(not target.conditions.sizeChanged, "ending Change Size should clear size condition")
    assertEqual(target.sizeMultiplier, 1, "ending Change Size should restore size multiplier")
    assertTrue(target.effectiveHeightFeet == nil, "ending Change Size should clear transient effective height")
    assertEqual(caster.committedResolve, 0, "ending Change Size should release committed Resolve")

    local shrinkCaster = base_entity.createEntity({
        id = "pc_change_size_shrink",
        name = "Shrink Mage",
        isPC = true,
        wands = 3,
        talents = {
            magic_of_the_weird = { mastered = true },
        },
    })
    shrinkCaster.resolve = 1
    shrinkCaster.inventory = inventory.createInventory()
    shrinkCaster.inventory:addItem(inventory.createItemFromTemplate("component_change_size"), inventory.LOCATIONS.HANDS)
    local smallTarget = base_entity.createEntity({
        id = "pc_change_size_small",
        name = "Shrunk Target",
        isPC = true,
        pentacles = 0,
        conditions = {},
    })
    smallTarget.heightFeet = 6
    local shrink = resolver:resolve({
        actor = shrinkCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "change_size",
        target = smallTarget,
        mode = "shrink",
        unwilling = false,
    })
    assertTrue(shrink.success, "Change Size should shrink a creature")
    assertEqual(smallTarget.sizeMultiplier, 0.5, "Change Size shrink should halve effective size")
    assertEqual(smallTarget.changeSize.effectiveHeightFeet, 3, "Change Size shrink should halve original height")

    local shrinkContest = resolver:resolve({
        actor = smallTarget,
        target = foe,
        card = { name = "Pentacles", value = 10, suit = constants.SUITS.PENTACLES },
        type = action_resolver.ACTION_TYPES.ROUGHHOUSE,
        roughhouseEffect = "trip",
        targetInitiative = 10,
    })
    assertTrue(not shrinkContest.success, "shrunk creatures should take disfavor where size hurts Roughhouse")
    assertEqual(shrinkContest.favorModifier, -3, "Change Size shrink should apply Roughhouse disfavor")
    assertTrue(hasValue(shrinkContest.effects, "change_size_action_disfavor"),
        "Change Size Roughhouse disfavor should be reported")

    local invalidCaster = base_entity.createEntity({
        id = "pc_change_size_invalid",
        name = "Invalid Size Mage",
        isPC = true,
        wands = 3,
        talents = {
            magic_of_the_weird = { mastered = true },
        },
    })
    invalidCaster.resolve = 1
    invalidCaster.inventory = inventory.createInventory()
    invalidCaster.inventory:addItem(inventory.createItemFromTemplate("component_change_size"), inventory.LOCATIONS.HANDS)
    local invalid = resolver:resolve({
        actor = invalidCaster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
        spellId = "change_size",
        target = base_entity.createEntity({ id = "pc_change_size_no_mode", isPC = true, conditions = {} }),
    })
    assertTrue(not invalid.success, "Change Size should require grow or shrink")
    assertTrue(hasValue(invalid.effects, "change_size_mode_missing"),
        "Change Size missing mode should report its target gate")
    assertEqual(invalidCaster.resolve, 1, "failed Change Size target gate should not spend Resolve")
end

local function checkNPCGroupedDrawNoFloor()
    local bus = events.createEventBus()
    local ai = npc_ai.createNPCAI({
        eventBus = bus,
        challengeController = {
            npcs = {},
            pcs = {},
        },
    })

    local function makeNPC(id)
        return {
            id = id,
            isPC = false,
            blueprintId = "imp",
            rank = "soldier",
            conditions = {},
        }
    end

    local function makePC(id)
        return {
            id = id,
            isPC = true,
            conditions = {},
        }
    end

    ai.challengeController.npcs = {
        makeNPC("n1"),
        makeNPC("n2"),
        makeNPC("n3"),
        makeNPC("n4"),
        makeNPC("n5"),
    }
    ai.challengeController.pcs = {
        makePC("p1"),
        makePC("p2"),
        makePC("p3"),
        makePC("p4"),
        makePC("p5"),
    }

    local drawCount = ai:calculateRoundDrawCount()
    assertEqual(drawCount, 4, "same enemy group no longer needs one initiative card per NPC")
end

local function checkMaleficenceModalPresentation()
    local bus = events.createEventBus()
    local modal = maleficence_modal.createMaleficenceModal({
        eventBus = bus,
    })
    modal:init()

    bus:emit(events.EVENTS.MALEFICENCE_RESOLVED, {
        branch = "weald",
        rank = "III",
        card = {
            name = "Three of Wands",
            value = 3,
            suit = constants.SUITS.WANDS,
        },
        entry = {
            title = "Thornburst",
            summary = "Roots and thorns erupt in the sorcerer's zone.",
        },
        effects = { "maleficence_zone_rooted" },
        unappliedEffects = {
            { type = "gm_adjudicate", summary = "Describe the vegetation." },
        },
    })

    assertTrue(modal.isVisible, "resolved maleficence should open the presentation modal")
    assertEqual(modal.result.rank, "III", "modal should retain maleficence rank")
    assertEqual(modal.result.entry.title, "Thornburst", "modal should retain table entry title")
    assertTrue(modal:keypressed("return"), "modal should consume confirmation key")
    assertTrue(not modal.isVisible, "confirmation key should close the maleficence modal")
end

